ActorLinesLocalData.tab = {
[400000] = {400000, 10000, 1, 1, "0", "0", "蒼霧殘響。", "蒼霧殘響（ハツリバーブ）。", "0", "0", "蒼霧殘響。", "0", "cv_rurura_33", "0", "0"},
[400001] = {400001, 10000, 2, 2, "0", "0", "一切都交給我吧！", "全部任せて！", "0", "0", "一切都交給我吧！", "0", "cv_rurura_2", "0", "0"},
[400002] = {400002, 10000, 3, 3, "0", "0", "我是魂滅小隊隊長露露啦，只要有我在，無論是生活方面還是戰鬥方面，都不需要領航費心。", "あたしは魂滅小隊の隊長、ルルラ。プライベートも、戦闘も、心配ご無用だよ。", "0", "0", "我是魂滅小隊隊長露露啦，只要有我在，無論是生活方面還是戰鬥方面，都不需要領航費心。", "0", "cv_rurura_1", "0", "0"},
[400003] = {400003, 10000, 4, 4, "0", "idle", "金庫啦和歐朵啦在做什麼呢……呀！我沒在發呆！對了！領航想吃什麼嗎？我可以做很多菜喔，紅燒肉、醋溜魚、辣子雞……", "キンクラとオードラは何をしてるのかな……あっ！いや、ぼうっとしてた訳じゃなくて…...そうだ！ナビゲーターは何が食べたい？あたし、いろんな料理が作れるんだ！豚の角煮、魚の甘酢あんかけ、スパイシーチキン……その他、ご希望のものがあれば。", "0", "0", "金庫啦和歐朵啦在做什麼呢……呀！我沒在發呆！對了！領航想吃什麼嗎？我可以做很多菜哦，紅燒肉、醋溜魚、辣子雞……", "0", "cv_rurura_3", "0", "0"},
[400004] = {400004, 10000, 5, 4, "0", "idle", "領航您累了嗎？把工作交給我吧！有什麼心事也可以和我說，我會一直陪在您身邊。", "お疲れ様、ナビゲーター！仕事ならあたしに任せて！相談にも乗ってあげる。ずっとあなたのそばにいるからね。", "0", "0", "領航您累了嗎？把工作交給我吧！有什麼心事也可以和我說，我會一直陪在您身邊。", "0", "cv_rurura_4", "0", "0"},
[400005] = {400005, 10000, 6, 4, "0", "idle", "領航，工作結束之後，我可以和你一起玩電玩喔！我可是超厲害的，歐朵啦和金庫啦都不是我的對手！", "ナビゲーター。仕事が終わったら一緒にゲームできるよ！あたし、めちゃくちゃ強いんだから。キンクラとオードラに勝ちまくってるし！", "0", "0", "領航，工作結束之後，我可以和你一起玩電玩噢！我可是超厲害的，歐朵啦和金庫啦都不是我的對手！", "0", "cv_rurura_30", "0", "0"},
[400006] = {400006, 10000, 7, 5, "1_》_0_0.8", "level1", "戰爭結束之後想做什麼……？我沒有特別想做的事，不過，如果領航希望的話，我可以像現在一樣一直照顧領航喔。", "戦爭が終わったら何がしたいって……？特にないけど…...そうだなあ、ナビゲーターさえ良ければ、今みたいにずっとナビゲーターのお世話をしてあげてもいいよ。", "0", "0", "戰爭結束之後想做什麼……？我沒有特別想做的事，不過，如果領航希望的話，我可以像現在一樣一直照顧領航哦。", "0", "cv_rurura_31", "0", "0"},
[400007] = {400007, 10000, 8, 5, "1_》_0_0.8", "level1", "嗯……我正在思考今天晚上要做的晚飯喔，還請不要打斷我的思路啦。", "今夜の夕飯を考えているの、邪魔しないで。", "0", "0", "嗯……我正在思考今天晚上要做的晚飯哦，還請不要打斷我的思路啦。", "0", "cv_rurura_5", "0", "0"},
[400008] = {400008, 10000, 9, 5, "1_》_100_1.5", "level2", "欸呀呀，領航是覺得寂寞了嗎？要露露啦來陪你說說話嗎？", "ん？寂しいの？だったらルルラとおしゃべりしない？", "0", "0", "哎呀呀，領航是覺得寂寞了嗎？要露露啦來陪你說說話嗎？", "0", "cv_rurura_6", "0", "0"},
[400009] = {400009, 10000, 10, 5, "1_》_500_2", "level3", "不知不覺中已經在多瑙支部待了這麼久了……一開始的時候確實有點沒法習慣，但是好在這裡大家都非常友善，現在我已經完全適應了喔。", "ダニューブ支局に來てからもうだいぶ経つんだね……最初はなかなか慣れなくて……ああでも、優しいみんなのお陰でもうすっかり慣れてるよ。", "0", "0", "不知不覺中已經在多瑙支部呆了這麼久了……一開始的時候確實有點沒法習慣，但是好在這裡大家都非常友善，現在我已經完全適應了哦。", "0", "cv_rurura_7", "0", "0"},
[400010] = {400010, 10000, 11, 5, "1_》_1000_2.5", "level4", "領航……雖然有些不好意思，但是我覺得還是有必要當面說出來。那……那個，為了感謝這段時間你對我的照顧，我想邀請你來我這邊吃頓晚飯可以嗎？", "ナビゲーター……あのね、ちょっと恥ずかしいけど、面と向かって言うべきだと思うの。え、えっと……最近、色々とお世話になってるじゃない？その感謝の気持ちを伝えたいと思って……良かったらあたしの部屋で一緒に夕飯を食べない？", "0", "0", "領航……雖然有些不好意思，但是我覺得還是有必要當面說出來。那……那個，為了感謝這段時間你對我的照顧，我想邀請你來我這邊吃頓晚飯可以嗎？", "0", "cv_rurura_8", "0", "0"},
[400011] = {400011, 10000, 12, 6, "0", "0", "謝謝！這樣一來就能幫上領航了！", "ありがとう！これならナビゲーターの力になれる！", "0", "0", "謝謝！這樣一來就能幫上領航了！", "0", "cv_rurura_9", "0", "0"},
[400012] = {400012, 10000, 13, 7, "0", "0", "這裡就由我來守護吧！", "ここはあたしに守らせて！", "0", "0", "這裡就由我來守護吧！", "0", "cv_rurura_10", "0", "0"},
[400013] = {400013, 10000, 14, 8, "0", "0", "太好了領航！這樣一來露露啦能做到的事情又變多了呢。", "やったね、ナビゲーター！ルルラのできることがまたまた増えたね。", "0", "0", "太好了領航！這樣一來露露啦能做到的事情又變多了呢。", "0", "cv_rurura_11", "0", "0"},
[400014] = {400014, 10000, 15, 9, "0", "0", "新功能感覺真棒啊，真想馬上就去嘗試一下呢。", "新機能っていいよね！今すぐ試してみたい。", "0", "0", "新功能感覺真棒啊，真想馬上就去嘗試一下呢。", "0", "cv_rurura_12", "0", "0"},
[400015] = {400015, 10000, 16, 10, "0", "0", "這點小事就交給露露啦吧。", "これくらいならルルラに任せて！", "0", "0", "這點小事就交給露露啦吧。", "0", "cv_rurura_13", "0", "0"},
[400016] = {400016, 10000, 17, 11, "0", "0", "呼~終於結束了呢，領航露露啦表現如何呢？", "ふぅ～やっと終わったね。どうだった？ルルラのパフォーマンス。", "0", "0", "呼~終於結束了呢，領航露露啦表現如何呢？", "0", "cv_rurura_14", "0", "0"},
[400017] = {400017, 10000, 18, 12, "0", "0", "下次再繼續加油啦！", "次も引き続き頑張るからね！", "0", "0", "下次再繼續加油啦！", "0", "cv_rurura_15", "0", "0"},
[400018] = {400018, 10000, 19, 13, "0", "0", "看來露露啦做得還不夠好……", "ルルラ、まだまだ精進しなきゃ……", "0", "0", "看來露露啦做得還不夠好……", "0", "cv_rurura_16", "0", "0"},
[400019] = {400019, 10000, 20, 14, "0", "0", "大家……趕快撤離吧，領航也是……", "みんな、早く撤退しよ！ナビゲーターも……！", "0", "0", "大家……趕快撤離吧，領航也是……", "0", "cv_rurura_17", "0", "0"},
[400020] = {400020, 10000, 21, 15, "0", "0", "交給我就對了！", "あたしに任せて！", "0", "0", "交給我就對了！", "0", "cv_rurura_18", "0", "0"},
