[400023] = {400023, 10000, 25, 18, "0", "0", "要來了喔～一切都交給露露啦吧。", "行くよ、全部ルルラに任せて！", "0", "0", "要來了哦～一切都交給露露啦吧。", "0", "cv_rurura_22", "0", "0"},
[400024] = {400024, 10000, 26, 19, "0", "0", "讓您失望了嗎……", "がっかりさせちゃったかな……", "0", "0", "讓您失望了嗎……", "0", "cv_rurura_20", "0", "0"},
[400025] = {400025, 10000, 27, 20, "0", "0", "領航，這次拜託您啦～", "よろしくね、ナビゲーター。", "0", "0", "領航，這次拜託您啦～", "0", "cv_rurura_23", "0", "0"},
[400026] = {400026, 10000, 28, 21, "0", "0", "領航辛苦了，歇一歇吧！", "お疲れ様、ナビゲーター。少し休憩をとったら？", "0", "0", "領航辛苦了，歇一歇吧！", "0", "cv_rurura_24", "0", "0"},
[400027] = {400027, 10000, 29, 21, "0", "0", "如果金庫啦和歐朵啦也在這裡就更好了呢。", "キンクラとオードラも一緒にここにいたら良かったのに。", "0", "0", "如果金庫啦和歐朵啦也在這裡就更好了呢。", "0", "cv_rurura_25", "0", "0"},
[400028] = {400028, 10000, 30, 22, "0", "0", "路上小心～", "気を付けてね。", "0", "0", "路上小心～", "0", "cv_rurura_26", "0", "0"},
[400029] = {400029, 10000, 31, 23, "0", "0", "我可以相信您嗎？", "あなたのこと、信じていいのかな？", "0", "0", "我可以相信您嗎？", "0", "cv_rurura_27", "0", "0"},
[400030] = {400030, 10000, 32, 24, "0", "0", "猜對啦！能遇到領航真是太幸運啦！", "當たったね！ナビゲーターに出會えてよかった！", "0", "0", "猜對啦！能遇到領航真是太幸運啦！", "0", "cv_rurura_28", "0", "0"},
[400031] = {400031, 10000, 33, 25, "0", "0", "沒關係，反正下次還會有機會的吧。", "大丈夫、また次の機會があるから。", "0", "0", "沒關係，反正下次還會有機會的吧。", "0", "cv_rurura_29", "0", "0"},
[400032] = {400032, 10000, 34, 26, "0", "0", "領航，歡迎回來！是要先洗澡嗎？還是說先吃飯呢？", "お帰り、ナビゲーター！お風呂にする？それともご飯？", "0", "0", "領航，歡迎回來！是要先洗澡嗎？還是說先吃飯呢？", "0", "cv_rurura_32", "0", "0"},
[400033] = {400033, 10000, 35, 27, "0", "0", "不管什麼樣的難關都可以依靠我喔。", "どんな困難があったとしても、あたしに頼っていいからね。", "0", "0", "不管什麼樣的難關都可以依靠我哦。", "0", "cv_rurura_34", "0", "0"},
[400034] = {400034, 10000, 36, 28, "0", "0", "請儘管依賴我吧！", "遠慮なくあたしに頼ってね！", "0", "0", "請儘管依賴我吧！", "0", "cv_rurura_35", "0", "0"},
[400035] = {400035, 10000, 37, 29, "0", "0", "有人肚子餓了嗎？", "お腹が空いてる人っているのかな？", "0", "0", "有人肚子餓了嗎？", "0", "cv_rurura_36", "0", "0"},
[400036] = {400036, 10000, 38, 30, "0", "0", "我會負責面試的。", "面接を擔當させてもらうよ。", "0", "0", "我會負責面試的。", "0", "cv_rurura_37", "0", "0"},
[400037] = {400037, 10000, 39, 31, "0", "0", "新裝備？是領航給大家準備的禮物嗎！？", "新しい裝備？ナビゲーターがみんなのために用意してくれたプレゼントなの？！", "0", "0", "新裝備？是領航給大家準備的禮物嗎！？", "0", "cv_rurura_38", "0", "0"},
[400038] = {400038, 10000, 40, 32, "0", "0", "採購的事情也請交給我吧。", "買い物のこともあたしに任せて！", "0", "0", "採購的事情也請交給我吧。", "0", "cv_rurura_39", "0", "0"},
[400039] = {400039, 10000, 41, 33, "0", "0", "資訊確認很重要呢。", "情報の確認って大事だよね。", "0", "0", "資訊確認很重要呢。", "0", "cv_rurura_40", "0", "0"},
[400040] = {400040, 10000, 42, 34, "0", "0", "來設定一下吧。", "設定をしておこう。", "0", "0", "來設置一下吧。", "0", "cv_rurura_41", "0", "0"},
[400041] = {400041, 10000, 43, 35, "0", "0", "嗯……看起來沒有可疑的信件。", "うん…...怪しいメールはないみたい。", "0", "0", "嗯……看起來沒有可疑的信件。", "0", "cv_rurura_42", "0", "0"},
[400042] = {400042, 10000, 44, 36, "0", "0", "領航要多和朋友聊天！", "友達ともっとチャットしないと！ね、ナビゲーター！", "0", "0", "領航要多和朋友聊天！", "0", "cv_rurura_43", "0", "0"},
[400043] = {400043, 10000, 45, 37, "0", "0", "您還有其他事嗎？", "ん、どうしたの？", "0", "0", "您還有其他事嗎？", "0", "cv_rurura_44", "0", "0"},
[400100] = {400100, 10001, 1, 1, "0", "0", "蒼霧殘響。", "蒼霧殘響（ハツリバーブ）。", "0", "0", "蒼霧殘響。", "0", "cv_Julius_33", "0", "0"},
[400101] = {400101, 10001, 2, 2, "0", "0", "我絕對不會辜負您的期待。", "絶対にご期待を裏切りませんわ。", "0", "0", "我絕對不會辜負您的期待。", "0", "cv_Julius_2", "0", "0"},
[400102] = {400102, 10001, 3, 3, "0", "0", "朱利烏斯·馮·尼采，從現在起將作為您最出色的部下，為了我們共同的榮耀而戰鬥。", "ユリウス・フォン・ニーチェです。これからあなた様の一番の部下として、我らの栄光のため、共に戦いましょう。", "0", "0", "朱利烏斯·馮·尼采，從現在起將作為您最出色的部下，為了我們共同的榮耀而戰鬥。", "0", "cv_Julius_1", "0", "0"},
[400103] = {400103, 10001, 4, 4, "0", "idle", "我想要做的，我能做到的，只不過是笨拙地模仿前輩罷了。但是，哪怕是如此愚鈍的我還是有一點可以向您保證……賭上家族的榮耀，我一定會為您帶來光榮的勝利。", "私のやりたいこと、そして私にできることは、ただ不器用に先人の真似をするだけです。でも、そんな不器用な私でも、一つだけ、保証できます……家名をかけて、あなた様に栄光ある勝利をもたらしましょう。", "0", "0", "我想要做的，我能做到的，只不過是笨拙地模仿先人罷了。但是，哪怕是如此愚鈍的我還是有一點可以向您保證……賭上家族的榮耀，我一定會為您帶來光榮的勝利。", "0", "cv_Julius_3", "0", "0"},
[400104] = {400104, 10001, 5, 4, "0", "idle", "在這裡停留了這麼久，難道說領航已經很累了嗎？沒關係的，您去休息好了，這裡交給我就行了。", "ずっとここで作業が止まっているみたいですが、ひょっとしてもうお疲れでしょうか？ナビゲーター。大丈夫です。ここは私に任せて、あなた様は休憩に行ってきてください。", "0", "0", "在這裡停留了這麼久，難道說領航已經很累了嗎？沒關係的，您去休息好了，這裡交給我就行了。", "0", "cv_Julius_4", "0", "0"},
[400105] = {400105, 10001, 6, 4, "0", "idle", "領航，你有看到查麗莎嗎？今天她又沒來訓練……每次也不請一個假，真是讓人擔心的傢夥……", "ナビゲーター、チャリサーを見ませんでしたか？今日もトレーニングを欠席していて……まったく、困ったものです。休暇屆くらい出してほしいのですが……", "0", "0", "領航，你有看到查麗莎嗎？今天她又沒來訓練……每次也不請一個假，真是讓人擔心的傢伙……", "0", "cv_Julius_30", "0", "0"},
[400106] = {400106, 10001, 7, 5, "1_》_0_0.8", "level1", "成為駕駛員的理由？啊，一方面是因為我自己本身就非常憧憬這樣的生活，另一方面則是因為我的父親……", "ドライバーになった理由ですか？それは、私自身がこういう暮らしに憧れていたのと、父が……", "0", "0", "成為駕駛員的理由？啊，一方面是因為我自己本身就非常憧憬這樣的生活，另一方面則是因為我的父親……", "0", "cv_Julius_31", "0", "0"},
[400107] = {400107, 10001, 8, 5, "1_》_0_0.8", "level1", "謝謝關心，但是還請您注意形象。", "お気遣いはありがたいのですが、少しはそうすることで、自分のイメージにどう影響するか…...気にしたほうがいいと思います。", "0", "0", "謝謝關心，但是還請您注意形象。", "0", "cv_Julius_5", "0", "0"},
[400108] = {400108, 10001, 9, 5, "1_》_100_1.5", "level2", "怎麼了？我的裝備穿錯了嗎？抱歉，我馬上檢討。", "どうかしました？私の裝備、著方が間違っている…...？それは失禮しまいした。", "0", "0", "怎麼了？我的裝備穿錯了嗎？抱歉，我馬上檢討。", "0", "cv_Julius_6", "0", "0"},
[400109] = {400109, 10001, 10, 5, "1_》_500_2", "level3", "為什麼……會這麼在意我。如果我有讓您不滿意的地方還請直接指出，老用這種眼神看著我，我也會……", "どうして……そんなに私のことを気にかけてくださるのですか？私に何か至らない點があるのなら、はっきりと言って下されば…...そんな目で見つめられたら、私だって……", "0", "0", "為什麼……會這麼在意我。如果我有讓您不滿意的地方還請直接指出，老用這種眼神看著我，我也會……", "0", "cv_Julius_7", "0", "0"},
[400110] = {400110, 10001, 11, 5, "1_》_1000_2.5", "level4", "原來如此，最近我已經明白您的感受了。沒錯，現在的我和您心中想的事情是一樣的……但是在沒有結束這一切之前，只是這樣看著彼此，就足夠了。", "なるほど。最近、私もようやく、あなた様の気持ちが分かるようになってきました。そう。今、私は…...あなた様と同じことを思っていました……でも、全てが終わるまでは、ただこうしてお互い見つめ合うだけで十分です。", "0", "0", "原來如此，最近我已經明白您的感受了。沒錯，現在的我和您心中想的事情是一樣的……但是在沒有結束這一切之前，只是這樣看著彼此，就足夠了。", "0", "cv_Julius_8", "0", "0"},
[400111] = {400111, 10001, 12, 6, "0", "0", "謝謝關心。", "お気遣い、ありがとうございます。", "0", "0", "謝謝關心。", "0", "cv_Julius_9", "0", "0"},
[400112] = {400112, 10001, 13, 7, "0", "0", "承蒙厚愛。", "そのお気持ち、ありがたく頂戴します。", "0", "0", "承蒙厚愛。", "0", "cv_Julius_10", "0", "0"},
[400113] = {400113, 10001, 14, 8, "0", "0", "終於抵達這個高度了嗎……領航，這份榮耀與您共用！", "やっとここまで辿り著くことができました…...ナビゲーター、この栄光をあなた様と共に！", "0", "0", "終於抵達這個高度了嗎……領航，這份榮耀與您共用！", "0", "cv_Julius_11", "0", "0"},
[400114] = {400114, 10001, 15, 9, "0", "0", "到底還要再揮動多少次劍，才能抵達那個高度呢？", "あとどれほど剣を振り回せば、あそこにたどり著けるのでしょう。", "0", "0", "到底還要再揮動多少次劍，才能抵達那個高度呢？", "0", "cv_Julius_12", "0", "0"},
[400115] = {400115, 10001, 16, 10, "0", "0", "大家，向著勝利前進吧！", "皆、勝利に向かって進みましょう！", "0", "0", "大家，向著勝利前進吧！", "0", "cv_Julius_13", "0", "0"},
[400116] = {400116, 10001, 17, 11, "0", "0", "勝利……很光榮吧？", "勝利とは、輝かしいものです。", "0", "0", "勝利……很光榮吧？", "0", "cv_Julius_14", "0", "0"},
[400117] = {400117, 10001, 18, 12, "0", "0", "任務完成，一起回去吧。", "ミッション完了です。一緒に帰りましょう。", "0", "0", "任務完成，一起回去吧。", "0", "cv_Julius_15", "0", "0"},
[400118] = {400118, 10001, 19, 13, "0", "0", "雖然還有些小遺憾，但是，還是恭喜大家了。", "至らない點も少々ありましたが、おめでとうございます。", "0", "0", "雖然還有些小遺憾，但是，還是恭喜大家了。", "0", "cv_Julius_16", "0", "0"},
[400119] = {400119, 10001, 20, 14, "0", "0", "……沒能完成對您的承諾，非常抱歉。", "……あなた様との約束を果たせなくて、申し訳ありません。", "0", "0", "……沒能完成對您的承諾，非常抱歉。", "0", "cv_Julius_17", "0", "0"},
[400120] = {400120, 10001, 21, 15, "0", "0", "哼，解決了呢。", "ふむ、解決しましたね。", "0", "0", "哼，解決了呢。", "0", "cv_Julius_18", "0", "0"},
[400121] = {400121, 10001, 23, 16, "0", "0", "喝——哈啊!", "やっ――はぁっ！", "0", "0", "喝——哈啊!", "0", "cv_Julius_19", "0", "0"},
[400122] = {400122, 10001, 26, 19, "0", "0", "讓您失望了……", "失望させてしまったでしょう……", "0", "0", "讓您失望了……", "0", "cv_Julius_20", "0", "0"},
[400123] = {400123, 10001, 24, 17, "0", "0", "完全不夠！", "全然足りません！", "0", "0", "完全不夠！", "0", "cv_Julius_21", "0", "0"},
[400124] = {400124, 10001, 25, 18, "0", "0", "這就是賭上了朱利烏斯之名的——全力一擊！！！！！！！！！！！", "ユリウスの名をかけた――會心の一撃！！！！！！！！！！", "0", "0", "這就是賭上了朱利烏斯之名的——全力一擊！！！！！！！！！！！", "0", "cv_Julius_22", "0", "0"},
[400125] = {400125, 10001, 27, 20, "0", "0", "麻煩您了。", "お願いします。", "0", "0", "麻煩您了。", "0", "cv_Julius_23", "0", "0"},
[400126] = {400126, 10001, 28, 21, "0", "0", "怎麼了？您累了嗎？", "どうしましたか？疲れましたか？", "0", "0", "怎麼了？您累了嗎？", "0", "cv_Julius_24", "0", "0"},
[400127] = {400127, 10001, 29, 21, "0", "0", "不用太勉強自己，能享受到領航的服務，我已經很滿足了。", "あまり無理しないでください。ナビゲーターにもてなして頂いて、もう十分幸せです。", "0", "0", "不用太勉強自己，能享受到領航的服務，我已經很滿足了。", "0", "cv_Julius_25", "0", "0"},
[400128] = {400128, 10001, 30, 22, "0", "0", "還請多加小心。", "どうかお気を付けください。", "0", "0", "還請多加小心。", "0", "cv_Julius_26", "0", "0"},
[400129] = {400129, 10001, 31, 23, "0", "0", "還請放輕鬆，無論結果如何我都不會責備您的。", "リラックスしてください。どんな結果になったとしても、責めたりはしませんから。", "0", "0", "還請放輕鬆，無論結果如何我都不會責備您的。", "0", "cv_Julius_27", "0", "0"},
[400130] = {400130, 10001, 32, 24, "0", "0", "謝謝您，每次都讓您費心了。", "いつも、ありがとうございます。", "0", "0", "謝謝您，每次都讓您費心了。", "0", "cv_Julius_28", "0", "0"},
[400131] = {400131, 10001, 33, 25, "0", "0", "我……我沒有責怪您的意思。", "わ、私は……あなた様を責める気はないのですが。", "0", "0", "我……我沒有責怪您的意思。", "0", "cv_Julius_29", "0", "0"},
[400132] = {400132, 10001, 34, 26, "0", "0", "歡迎回來，領航。今天也讓我們一起為了榮耀而戰鬥吧。", "お帰りなさい、ナビゲーター。今日も一緒に、栄光のために戦いましょう。", "0", "0", "歡迎回來，領航。今天也讓我們一起為了榮耀而戰鬥吧。", "0", "cv_Julius_32", "0", "0"},
[400133] = {400133, 10001, 35, 27, "0", "0", "在旅途結束之前，我都將成為您最牢固的盾以及最鋒利的劍。", "この旅が終わるまで、あなた様の一番丈夫な盾、そして一番鋭利な剣であり続けると誓いましょう。", "0", "0", "在旅途結束之前，我都將成為您最牢固的盾以及最鋒利的劍。", "0", "cv_Julius_34", "0", "0"},
[400134] = {400134, 10001, 36, 28, "0", "0", "向著更高點邁進吧。", "もっと高い目標に向かって進んでいきましょう。", "0", "0", "向著更高點邁進吧。", "0", "cv_Julius_35", "0", "0"},
[400135] = {400135, 10001, 37, 29, "0", "0", "大家都在等著您呢。", "皆、あなた様を待っていますよ。", "0", "0", "大家都在等著您呢。", "0", "cv_Julius_36", "0", "0"},
[400136] = {400136, 10001, 38, 30, "0", "0", "有新的夥伴加入是件令人高興的事呢。", "新しい仲間が加わるなんて、嬉しいですね。", "0", "0", "有新的夥伴加入是件令人高興的事呢。", "0", "cv_Julius_37", "0", "0"},
[400137] = {400137, 10001, 39, 31, "0", "0", "新式的裝備真是令人期待啊。", "新しい裝備、楽しみですね。", "0", "0", "新式的裝備真是令人期待啊。", "0", "cv_Julius_38", "0", "0"},
[400138] = {400138, 10001, 40, 32, "0", "0", "補充一下物資吧。", "物資を補充しましょう。", "0", "0", "補充一下物資吧。", "0", "cv_Julius_39", "0", "0"},
[400139] = {400139, 10001, 41, 33, "0", "0", "確認下自己的狀況也很重要呢。", "自分の狀況を確認するというのも大事なことです。", "0", "0", "確認下自己的狀況也很重要呢。", "0", "cv_Julius_40", "0", "0"},
[400140] = {400140, 10001, 42, 34, "0", "0", "變更設定，說不定會對戰鬥有利。", "設定を変更すると、戦いに役立つかもしれません。", "0", "0", "變更設置，說不定會對戰鬥有利。", "0", "cv_Julius_41", "0", "0"},
[400141] = {400141, 10001, 43, 35, "0", "0", "有新的來信嗎？", "新しいメールが屆いていたのでしょうか？", "0", "0", "有新的來信嗎？", "0", "cv_Julius_42", "0", "0"},
[400142] = {400142, 10001, 44, 36, "0", "0", "有必要交流下情報呢。", "情報交換は必要ですよ。", "0", "0", "有必要交流下情報呢。", "0", "cv_Julius_43", "0", "0"},
[400143] = {400143, 10001, 45, 37, "0", "0", "確認一下吧。", "確認しましょう。", "0", "0", "確認一下吧。", "0", "cv_Julius_44", "0", "0"},
[400200] = {400200, 10002, 1, 1, "0", "0", "蒼霧殘響！", "蒼霧殘響（ハツリバーブ）！", "0", "0", "蒼霧殘響！", "0", "cv_hank_31", "0", "0"},
[400201] = {400201, 10002, 2, 2, "0", "0", "欸？這樣真的好嗎，我這種人完全不知道該怎麼處理這種情況欸。", "え？本當にいいのか？こういうとき、どうすればいいのか全然わからないんだが。", "0", "0", "哎？這樣真的好嗎，我這種人完全不知道該怎麼處理這種情況哎。", "0", "cv_hank_2", "0", "0"},
[400202] = {400202, 10002, 3, 3, "0", "0", "唷，你就是領航嗎？話先說好，我只是個傭兵喔。", "よぉ！あんたがナビゲーターか？言っておくが、私はただの傭兵だ。", "0", "0", "喲，你就是領航嗎？話先說好，我只是個傭兵哦。", "0", "cv_hank_1", "0", "0"},
[400203] = {400203, 10002, 4, 4, "0", "idle", "給多少錢辦多少事，不光光是為了我好也是為了雇主好喔。", "私は報酬に応じた仕事をする。自分にとっても雇用主にとっても良いことだと思うんだがな。", "0", "0", "給多少錢辦多少事，不光光是為了我好也是為了雇主好哦。", "0", "cv_hank_3", "0", "0"},
[400204] = {400204, 10002, 5, 4, "0", "idle", "殺戮，殺戮，殺戮，殺戮……這就是我一直以來在做的工作……早在成為駕駛員之前，我就在幹類似的事情了。", "殺戮、殺戮、殺戮、殺戮……これが私の仕事だ……ドライバーになる前もずっと似たような事をやっていた。", "0", "0", "殺戮，殺戮，殺戮，殺戮……這就是我一直以來在做的工作……早在成為駕駛員之前，我就在幹類似的事情了。", "0", "cv_hank_4", "0", "0"},
[400205] = {400205, 10002, 6, 4, "0", "idle", "雖然蒂娜是個蠻難相處的傢夥，不過說實話，比起刀子嘴豆腐心的人，我更喜歡像她一樣言行一致的傢夥。", "確かにティナは扱いにくいやつだけど、でも正直なところ、口が悪いけど心根が優しいっていう女の子より、彼女みたいな言行一致のやつの方がいい。", "0", "0", "雖然蒂娜是個蠻難相處的傢伙，不過說實話，比起刀子嘴豆腐心的人，我更喜歡像她一樣言行一致的傢伙。", "0", "cv_hank_28", "0", "0"},
[400206] = {400206, 10002, 7, 5, "1_》_0_0.8", "level1", "加入艾吉斯的理由…嗯……當然是因為雇主給的錢足夠多啊。還有部分原因是因為我很在意那兩個女孩，在過去，我和姐姐的關係也不太好呢。", "アイギスに入った理由……うーん……それはもちろん、報酬がいいからに決まってるだろ。まぁ、あの二人の女の子のことが気になるからっていうのもなくはないが……昔、私も姉さんとは仲が悪かったからな。", "0", "0", "加入艾吉斯的理由…嗯……當然是因為雇主給的錢足夠多啊。還有部分原因是因為我很在意那兩個女孩，在過去，我和姐姐的關係也不太好呢。", "0", "cv_hank_29", "0", "0"},
[400207] = {400207, 10002, 8, 5, "1_》_0_0.8", "level1", "欸？這是什麼情況啊？", "ん？どういうことだ？", "0", "0", "哎？這是什麼情況啊？", "0", "cv_hank_5", "0", "0"},
[400208] = {400208, 10002, 9, 5, "1_》_100_1.5", "level2", "嗯……雖然還有些奇怪，但是你應該是沒有惡意的吧。", "うーん……なんかよくわからないけど、悪意はないってことだろ？", "0", "0", "嗯……雖然還有些奇怪，但是你應該是沒有惡意的吧。", "0", "cv_hank_6", "0", "0"},
[400209] = {400209, 10002, 10, 5, "1_》_500_2", "level3", "還真是少見，除了敵人外，居然還會有主動靠近我的傢夥啊。難道說，你並沒有討厭我嗎？", "珍しい。敵以外に自分から私に近づいてくるやつがいただなんて。ひょっとして、私のこと、嫌じゃないのか？", "0", "0", "還真是少見，除了敵人外，居然還會有主動靠近我的傢伙啊。難道說，你並沒有討厭我嗎？", "0", "cv_hank_7", "0", "0"},
[400210] = {400210, 10002, 11, 5, "1_》_1000_2.5", "level4", "雖然我只是一個拿錢辦事的傭兵，也不是很懂該怎麼表達自己的想法。但是，該怎麼說呢……哈！就是那個啊——能和你一起工作，真的非常開心！如果有機會的話想要一直和你一起工作！", "私は報酬に応じた仕事をするだけの傭兵、だから、自分の考えをどうやって伝えればいいのかもよくわからない。でも、なんというか……だから、あれだ――あんたと一緒に仕事をすることができて、本當に嬉しいんだ！出來るなら、あんたとはずっと一緒に仕事をしたい！", "0", "0", "雖然我只是一個拿錢辦事的傭兵，也不是很懂該怎麼表達自己的想法。但是，該怎麼說呢……哈！就是那個啊——能和你一起工作，真的非常開心！如果有機會的話想要一直和你一起工作！", "0", "cv_hank_8", "0", "0"},
[400211] = {400211, 10002, 12, 6, "0", "0", "就只有這點嗎？哈，開玩笑的。", "これしかないのか？あはは、冗談だ。", "0", "0", "就只有這點嗎？哈，開玩笑的。", "0", "cv_hank_9", "0", "0"},
[400212] = {400212, 10002, 13, 7, "0", "0", "拿錢辦事～拿錢辦事～今天要去砍誰呢？", "報酬に応じた仕事をするんだ、さて、今日は誰を斬ろうか？", "0", "0", "拿錢辦事～拿錢辦事～今天要去砍誰呢？", "0", "cv_hank_10", "0", "0"},
[400213] = {400213, 10002, 14, 8, "0", "0", "呼啊——真是一筆好買賣呢～你就好好看著吧，我絕對不會讓雇主失望的！", "へぇー、これはうまい話だ。任せとけ！雇用主をがっかりさせるようなことは絶対しない。", "0", "0", "呼啊——真是一筆好買賣呢～你就好好看著吧，我絕對不會讓雇主失望的！", "0", "cv_hank_11", "0", "0"},
[400214] = {400214, 10002, 15, 9, "0", "0", "喔喔喔喔——揮刀的時候感覺更加有幹勁了啊！", "おおお――刀捌きが上手くなった気がするぞ！", "0", "0", "噢噢噢噢——揮刀的時候感覺更加有幹勁了啊！", "0", "cv_hank_12", "0", "0"},
[400215] = {400215, 10002, 16, 10, "0", "0", "OK！工作開始～", "オッケー！仕事を始めようか。", "0", "0", "OK！工作開始～", "0", "cv_hank_13", "0", "0"},
[400216] = {400216, 10002, 17, 11, "0", "0", "perfect！", "パーフェクト！", "0", "0", "perfect！", "0", "cv_hank_14", "0", "0"},
[400217] = {400217, 10002, 18, 12, "0", "0", "怎麼樣我很厲害吧？報酬可不要給少了喔。", "どうだ？私、淒いだろ？報酬の方はケチるなよ。", "0", "0", "怎麼樣我很厲害吧？報酬可不要給少了哦。", "0", "cv_hank_15", "0", "0"},
[400218] = {400218, 10002, 19, 13, "0", "0", "嗯……我懂我懂，你看著扣點錢吧。", "うーん…...ああ、はいはい。報酬の方、適當に減らしておいて良いぞ。", "0", "0", "嗯……我懂我懂，你看著扣點錢吧。", "0", "cv_hank_16", "0", "0"},
[400219] = {400219, 10002, 20, 14, "0", "0", "holyshit！", "ホーリーシット！", "0", "0", "holyshit！", "0", "cv_hank_17", "0", "0"},
[400220] = {400220, 10002, 21, 15, "0", "0", "不堪一擊！", "一溜まりもないな！", "0", "0", "不堪一擊！", "0", "cv_hank_18", "0", "0"},
