[400232] = {400232, 10002, 36, 28, "0", "0", "無論是什麼樣的敵人，最後都會變成酬金。", "どんな敵であっても、最終的には報酬になるからな。", "0", "0", "無論是什麼樣的敵人，最後都會變成酬金。", "0", "cv_hank_33", "0", "0"},
