[400401] = {400401, 10004, 2, 2, "0", "0", "任務確認——任務目的——不明……但是，我會嘗試一下的。", "ミッション確認――ミッション目的――不明……でも、やって、みます。", "0", "0", "0", "0", "cv_dtypeb2_2", "0", "0"},
[400402] = {400402, 10004, 3, 3, "0", "0", "接入確認——認證開始——3——2——1……接入完成——接下來請隨意使用D型b2。", "接続確認――認証開始――3――2――1――……接続完了――では、D型b-2をどうぞ、ご自由にお使いください。", "0", "0", "0", "0", "cv_dtypeb2_1", "0", "0"},
[400403] = {400403, 10004, 4, 4, "0", "idle", "待機中——如需使用請按下啟動鍵——", "待機中――ご利用の場合は、アクティベートキーを押してください――。", "0", "0", "0", "0", "cv_dtypeb2_3", "0", "0"},
[400404] = {400404, 10004, 5, 4, "0", "idle", "正在重啟——還請稍等片刻——……領航，好久不見。在休眠的這段時間裏，我好像學會了做夢……我夢到了，那個孩子。", "再起動しています――しばらくお待ちください――……ナビゲーター、お久しぶりです。スリープ中に、夢を見ることができるようになったみたいです……夢の中で、あの子を見ました。", "0", "0", "0", "0", "cv_dtypeb2_4", "0", "0"},
[400405] = {400405, 10004, 6, 4, "0", "idle", "檢索模式啟動——抱歉，並沒有發現其他同型號的機體。", "検索モード起動――すみません、他の同一型番の機體が見つかりませんでした。", "0", "0", "0", "0", "cv_dtypeb2_30", "0", "0"},
[400406] = {400406, 10004, 7, 5, "1_》_0_0.8", "level1", "無法理解——我們存在的意義只是為了保護人類而已，至少對我而言是這樣的。但是，總覺得又很想再見到那個人……", "理解できません――私たちの存在意義は人間を守ることです。少なくとも、私はそう認識しています。でも、もし可能ならまたあの人に會いたいと思います……", "0", "0", "0", "0", "cv_dtypeb2_31", "0", "0"},
[400407] = {400407, 10004, 8, 5, "1_》_0_0.8", "level1", "啟動確認——認證開始——……啟動完畢。", "アクティベート確認――認証開始――……アクティベート完了。", "0", "0", "0", "0", "cv_dtypeb2_5", "0", "0"},
[400408] = {400408, 10004, 9, 5, "1_》_100_1.5", "level2", "啟動確認——認證開始——……啟動完畢——請問是否要執行接入程式？", "アクティベート確認――認証開始――……アクティベート完了――接続プログラムを実行しますか？", "0", "0", "0", "0", "cv_dtypeb2_6", "0", "0"},
[400409] = {400409, 10004, 10, 5, "1_》_500_2", "level3", "啟動完畢——無論再怎麼樣，我都沒法理解你們人類的情感。所以，還請不要再努力了。", "アクティベート完了――私にとって、あなたたち人間の感情はどうしても理解できないものです。ですから、無駄なことをなさらないでください。", "0", "0", "0", "0", "cv_dtypeb2_7", "0", "0"},
[400410] = {400410, 10004, 11, 5, "1_》_1000_2.5", "level4", "雖然沒法理解你們的情感，但是我會動用記憶模組將你的行為記錄下來。我會將它們留到自己可以解讀出來為止，所以，還請放心吧。", "あなたたちの感情を理解することはできませんが、メモリーモジュールであなたの行為を記録することができます。自分で解読できるようになるまで保存しますので、ご安心ください。", "0", "0", "0", "0", "cv_dtypeb2_8", "0", "0"},
[400411] = {400411, 10004, 12, 6, "0", "0", "升級——完成——", "アップデート――完了――", "0", "0", "0", "0", "cv_dtypeb2_9", "0", "0"},
[400412] = {400412, 10004, 13, 7, "0", "0", "系統更新——完成——", "システム更新――完了――", "0", "0", "0", "0", "cv_dtypeb2_10", "0", "0"},
[400413] = {400413, 10004, 14, 8, "0", "0", "硬體升級——完成——已檢測出情感模組——並沒有。", "ハードウェアアップデート――完了――検知された感情モジュール――ありません", "0", "0", "0", "0", "cv_dtypeb2_11", "0", "0"},
[400414] = {400414, 10004, 15, 9, "0", "0", "部件升級——完成——", "パーツアップデート――完了――", "0", "0", "0", "0", "cv_dtypeb2_12", "0", "0"},
[400415] = {400415, 10004, 16, 10, "0", "0", "敵襲確認——殲滅模式啟動——", "敵襲確認――殲滅モード起動――", "0", "0", "0", "0", "cv_dtypeb2_13", "0", "0"},
[400416] = {400416, 10004, 17, 11, "0", "0", "正在評定戰果——三星——", "戦果評価中――三つ星――", "0", "0", "0", "0", "cv_dtypeb2_14", "0", "0"},
[400417] = {400417, 10004, 18, 12, "0", "0", "正在評定戰果——二星——", "戦果評価中――二つ星――", "0", "0", "0", "0", "cv_dtypeb2_15", "0", "0"},
[400418] = {400418, 10004, 19, 13, "0", "0", "正在評定戰果——一星——", "戦果評価中――一つ星――", "0", "0", "0", "0", "cv_dtypeb2_16", "0", "0"},
[400419] = {400419, 10004, 20, 14, "0", "0", "作戰——失敗——", "作戦――失敗――", "0", "0", "0", "0", "cv_dtypeb2_17", "0", "0"},
[400420] = {400420, 10004, 21, 15, "0", "0", "殲滅成功——", "殲滅成功――", "0", "0", "0", "0", "cv_dtypeb2_18", "0", "0"},
[400421] = {400421, 10004, 23, 16, "0", "0", "目標——鎖定——", "ターゲット――ロックオン――", "0", "0", "0", "0", "cv_dtypeb2_19", "0", "0"},
[400422] = {400422, 10004, 26, 19, "0", "0", "能源耗盡——即將進入休眠模式——", "全エネルギー消費――間もなくスリープモードに入ります――", "0", "0", "0", "0", "cv_dtypeb2_20", "0", "0"},
[400423] = {400423, 10004, 24, 17, "0", "0", "護盾啟動——", "シールド起動――", "0", "0", "0", "0", "cv_dtypeb2_21", "0", "0"},
[400424] = {400424, 10004, 25, 18, "0", "0", "作戰開始——解除全部限制——鎖定目標——將功率調節至最大——從這個世界上消失吧！！！！", "作戦開始――全ての制限を解除――ターゲットをロックオン――出力最大――この世界から消え失せてください！！！！", "0", "0", "0", "0", "cv_dtypeb2_22", "0", "0"},
[400425] = {400425, 10004, 27, 20, "0", "0", "任務確認——任務目的——不明……完全沒有這個必要吧。", "ミッション確認――ミッション目的――不明……まったく必要ありませんが。", "0", "0", "0", "0", "cv_dtypeb2_23", "0", "0"},
[400426] = {400426, 10004, 28, 21, "0", "0", "正在啟動感知模組——好暖和啊——", "感知モジュール起動中――溫かい、です――", "0", "0", "0", "0", "cv_dtypeb2_24", "0", "0"},
[400427] = {400427, 10004, 29, 21, "0", "0", "正在啟動情感模組——好高興啊——", "感情モジュール起動中――嬉しい、です――", "0", "0", "0", "0", "cv_dtypeb2_25", "0", "0"},
[400428] = {400428, 10004, 30, 22, "0", "0", "敵襲確認——殲滅模式啟動——開玩笑的。", "敵襲確認――殲滅モード起動――冗談です。", "0", "0", "0", "0", "cv_dtypeb2_26", "0", "0"},
[400429] = {400429, 10004, 31, 23, "0", "0", "殲滅模式啟動——還請儘快指定目標——", "殲滅モード起動――迅速にターゲットを指定してください――", "0", "0", "0", "0", "cv_dtypeb2_27", "0", "0"},
[400430] = {400430, 10004, 32, 24, "0", "0", "到底……是從哪裡認出來的呢？", "一體……どうやって分かったのですか？", "0", "0", "0", "0", "cv_dtypeb2_28", "0", "0"},
[400431] = {400431, 10004, 33, 25, "0", "0", "休眠模式——啟動——", "スリープモード――起動――", "0", "0", "0", "0", "cv_dtypeb2_29", "0", "0"},
[400432] = {400432, 10004, 34, 26, "0", "0", "休眠結束——歡迎回來，我的領航。", "スリープ終了――お帰りなさい、私のナビゲーター。", "0", "0", "0", "0", "cv_dtypeb2_32", "0", "0"},
[400433] = {400433, 10004, 35, 27, "0", "0", "記錄模式啟動——", "記録モード起動――", "0", "0", "0", "0", "cv_dtypeb2_34", "0", "0"},
[400434] = {400434, 10004, 36, 28, "0", "0", "殲滅模式啟動——請問要調節成手動模式嗎？", "殲滅モード起動――手動モードに変更しますか？", "0", "0", "0", "0", "cv_dtypeb2_35", "0", "0"},
[400435] = {400435, 10004, 37, 29, "0", "0", "友軍確認——", "友軍確認――", "0", "0", "0", "0", "cv_dtypeb2_36", "0", "0"},
[400436] = {400436, 10004, 38, 30, "0", "0", "隊伍擴充確認——", "チーム拡張確認――", "0", "0", "0", "0", "cv_dtypeb2_37", "0", "0"},
[400437] = {400437, 10004, 39, 31, "0", "0", "生產裝備確認——", "生産裝備確認――", "0", "0", "0", "0", "cv_dtypeb2_38", "0", "0"},
[400438] = {400438, 10004, 40, 32, "0", "0", "跳轉至採購介面——", "ショッピング畫面へ移行――", "0", "0", "0", "0", "cv_dtypeb2_39", "0", "0"},
[400439] = {400439, 10004, 41, 33, "0", "0", "個人資訊確認——", "個人情報確認――", "0", "0", "0", "0", "cv_dtypeb2_40", "0", "0"},
[400440] = {400440, 10004, 42, 34, "0", "0", "設置確認——", "設定確認――", "0", "0", "0", "0", "cv_dtypeb2_41", "0", "0"},
[400441] = {400441, 10004, 43, 35, "0", "0", "郵件確認——", "メール確認――", "0", "0", "0", "0", "cv_dtypeb2_42", "0", "0"},
[400442] = {400442, 10004, 44, 36, "0", "0", "世界聊天確認——", "ワールドチャット確認――", "0", "0", "0", "0", "cv_dtypeb2_43", "0", "0"},
[400443] = {400443, 10004, 45, 37, "0", "0", "連接確認——", "接続確認――", "0", "0", "0", "0", "cv_dtypeb2_44", "0", "0"},
[400500] = {400500, 10005, 1, 1, "0", "0", "蒼霧殘響！", "蒼霧殘響（ハツリバーブ）！", "0", "0", "蒼霧殘響！", "0", "cv_karenn_33", "0", "0"},
[400501] = {400501, 10005, 2, 2, "0", "0", "這麼在意小生，難道說……", "ボクのことがそんなに気になるの？もしかして……", "0", "0", "這麼在意小生，難道說……", "0", "cv_karenn_2", "0", "0"},
[400502] = {400502, 10005, 3, 3, "0", "0", "小生名為華戀，如果能接下小生這一腳的話小生就跟定你了喔。", "ボクの名は華戀。もしボクの蹴りを受け流すことができたなら、結婚してあげるよ！", "0", "0", "小生名為華戀，如果能接下小生這一腳的話小生就跟定你了哦。", "0", "cv_karenn_1", "0", "0"},
[400503] = {400503, 10005, 4, 4, "0", "idle", "我說……你是不是已經有點累了啊？如果累了的話就趕快去休息吧，這裡有小生在就好。", "あのね……もしかして、疲れてきた？だったら早く休んで！ここはボクに任せて。", "0", "0", "我說……你是不是已經有點累了啊？如果累了的話就趕快去休息吧，這裡有小生在就好。", "0", "cv_karenn_3", "0", "0"},
[400504] = {400504, 10005, 5, 4, "0", "idle", "輸贏並不是關鍵，重要的是在交手時的心理交流。正所謂不打不相識，只有好好打上一架才能真正瞭解一個人啊。", "手合わせする時は、勝敗なんかより、心の交流の方が大事だよ。「けんかをしなければ友達になれない」って言うでしょ？人を理解するにはちゃんとした手合わせが必要だってこと。", "0", "0", "輸贏並不是關鍵，重要的是在交手時的心理交流。正所謂不打不相識，只有好好打上一架才能真正瞭解一個人啊。", "0", "cv_karenn_4", "0", "0"},
[400505] = {400505, 10005, 6, 4, "0", "idle", "華夢？啊，她是小生的姐姐，也是小生的對手。從很小的時候我們就在一起修行了。", "華夢？ああ、あれはボクの姉で、好敵手だよ。小さい頃からずっと一緒に修行してるし。", "0", "0", "華夢？啊，她是小生的姐姐，也是小生的對手。從很小的時候我們就在一起修行了。", "0", "cv_karenn_30", "0", "0"},
[400506] = {400506, 10005, 7, 5, "1_》_0_0.8", "level1", "小生自己倒是沒什麼志向，加入艾吉斯也只是單純覺得這裡一定會有小生中意的強者罷了。", "ボクには個人的な志なんかない。アイギスに入ったのも、ボクの気に入る強者がいそうだと思ったから。ただそれだけ。", "0", "0", "小生自己倒是沒什麼志向，加入艾吉斯也只是單純覺得這裡一定會有小生中意的強者罷了。", "0", "cv_karenn_31", "0", "0"},
[400507] = {400507, 10005, 8, 5, "1_》_0_0.8", "level1", "要來打上一架嗎？小生已經準備好了喔。", "手合わせをやる？ボクはもう、準備出來てるよ。", "0", "0", "要來打上一架嗎？小生已經準備好了哦。", "0", "cv_karenn_5", "0", "0"},
[400508] = {400508, 10005, 9, 5, "1_》_100_1.5", "level2", "喔喔，不錯的一擊嘛，看來你的體內也流淌著多瑙的血啊。", "おお、なかなか良い攻撃だったね。あんたの體にも九州の血が流れてるようだ。", "0", "0", "噢噢，不錯的一擊嘛，看來你的體內也流淌著九州的血啊。", "0", "cv_karenn_6", "0", "0"},
[400509] = {400509, 10005, 10, 5, "1_》_500_2", "level3", "不是這樣的啦，像你這樣的踢腿是沒法將情感傳遞給小生的啦。看好了喔，小生再給你演示一遍。", "そうじゃなくて……！そんな足蹴りじゃ気持ちをボクに伝えることはできないよ。いい？ボクがもう一回手本をやって見せてあげる。", "0", "0", "不是這樣的啦，像你這樣的踢腿是沒法將情感傳遞給小生的啦。看好了哦，小生再給你演示一遍。", "0", "cv_karenn_7", "0", "0"},
[400510] = {400510, 10005, 11, 5, "1_》_1000_2.5", "level4", "為什麼……為什麼無法使出全力呢？只要與你對視的話，小生全身的力氣都會溜走……這樣的話可沒法將現在的心情好好傳遞給你啊。", "なんで……なんで全力を出せないんだろ？あんたと目が合うと、全身の力が抜けちゃうっていうか……こんなんじゃ今の気持ちをちゃんとあんたに伝えられないじゃないか！", "0", "0", "為什麼……為什麼無法使出全力呢？只要與你對視的話，小生全身的力氣都會溜走……這樣的話可沒法將現在的心情好好傳遞給你啊。", "0", "cv_karenn_8", "0", "0"},
[400511] = {400511, 10005, 12, 6, "0", "0", "呼呼呼，小腿上的肌肉增加了喔~", "ふふ、ふくらはぎの筋肉が増えた！", "0", "0", "呼呼呼，小腿上的肌肉增加了哦~", "0", "cv_karenn_9", "0", "0"},
[400512] = {400512, 10005, 13, 7, "0", "0", "喔，小生在收下你的禮物後好像又變強了欸！", "おっ！あんたからのプレゼントをもらったお陰でまた強くなったみたい！", "0", "0", "哦，小生在收下你的禮物後好像又變強了哎！", "0", "cv_karenn_10", "0", "0"},
[400513] = {400513, 10005, 14, 8, "0", "0", "完全形態！領航，還請務必要收下這注入了小生所有情感的一擊！", "完全形態！ナビゲーター、このボクの気持ちが込められた一撃を是非受け取めて！", "0", "0", "完全形態！領航，還請務必要收下這注入了小生所有情感的一擊！", "0", "cv_karenn_11", "0", "0"},
[400514] = {400514, 10005, 15, 9, "0", "0", "戰鬥變得得心應手了！", "戦闘が上達したね！", "0", "0", "戰鬥變得得心應手了！", "0", "cv_karenn_12", "0", "0"},
[400515] = {400515, 10005, 16, 10, "0", "0", "我可沒打算和原罪交朋友啊。", "原罪なんかと友達になるつもりはないから。", "0", "0", "我可沒打算和原罪交朋友啊。", "0", "cv_karenn_13", "0", "0"},
[400516] = {400516, 10005, 17, 11, "0", "0", "這個世界上沒有什麼傢夥是用武術打不倒的！", "武術で倒せない奴なんてこの世界には存在しない！", "0", "0", "這個世界上沒有什麼傢伙是用武術打不倒的！", "0", "cv_karenn_14", "0", "0"},
[400517] = {400517, 10005, 18, 12, "0", "0", "稍微有點吃力啊，回去之後再鍛煉下好了。", "ギリだったね。帰ってもっと鍛錬した方がいい。", "0", "0", "稍微有點吃力啊，回去之後再鍛煉下好了。", "0", "cv_karenn_15", "0", "0"},
[400518] = {400518, 10005, 19, 13, "0", "0", "果然……他們只是沒有心的怪物。", "やっぱり……あいつらは心のないモンスターに過ぎない。", "0", "0", "果然……他們只是沒有心的怪物。", "0", "cv_karenn_16", "0", "0"},
[400519] = {400519, 10005, 20, 14, "0", "0", "原來還有武術達不到的境界……", "武術で到達できない領域もあったんだ……", "0", "0", "原來還有武術達不到的境界……", "0", "cv_karenn_17", "0", "0"},
[400520] = {400520, 10005, 21, 15, "0", "0", "還差點意思啊。", "ちょっと足りないかも。", "0", "0", "還差點意思啊。", "0", "cv_karenn_18", "0", "0"},
[400521] = {400521, 10005, 23, 16, "0", "0", "小生來了喔！", "華戀、參る！", "0", "0", "小生來了哦！", "0", "cv_karenn_19", "0", "0"},
[400522] = {400522, 10005, 24, 17, "0", "0", "來吧，朝小生攻擊吧。", "さぁ、かかってこい！", "0", "0", "來吧，朝小生攻擊吧。", "0", "cv_karenn_21", "0", "0"},
[400523] = {400523, 10005, 26, 19, "0", "0", "小生的定力……還遠遠不夠……", "ボクの定力……まだまだだったね……", "0", "0", "小生的定力……還遠遠不夠……", "0", "cv_karenn_20", "0", "0"},
[400524] = {400524, 10005, 27, 20, "0", "0", "洗澡，也就是與水的戰鬥嗎？小生瞭解了。", "お風呂？つまり水との戦い？分かった。", "0", "0", "洗澡，也就是與水的戰鬥嗎？小生清楚了。", "0", "cv_karenn_23", "0", "0"},
[400525] = {400525, 10005, 28, 21, "0", "0", "如果是水的話應該能接住小生的一腳吧。", "水ならボクの足蹴りを受け流せるよね？", "0", "0", "如果是水的話應該能接住小生的一腳吧。", "0", "cv_karenn_24", "0", "0"},
[400526] = {400526, 10005, 29, 21, "0", "0", "聽說過嗎？在小生的故鄉，有人會使用瀑布進行修行呢。", "ボクの故郷には滝を使って鍛錬する人がいるんだ。こんな話、聞いたことある？", "0", "0", "聽說過嗎？在小生的故鄉，有人會使用瀑布進行修行呢。", "0", "cv_karenn_25", "0", "0"},
[400527] = {400527, 10005, 30, 22, "0", "0", "像小生一樣使出全心全意的一擊吧！", "ボクのみたいに、會心の一撃を出そう！", "0", "0", "像小生一樣使出全心全意的一擊吧！", "0", "cv_karenn_26", "0", "0"},
[400528] = {400528, 10005, 31, 23, "0", "0", "猜錯了的話就準備接下小生這腳吧。", "外れたらボクの足蹴りを食らうことになるからね。", "0", "0", "猜錯了的話就準備接下小生這腳吧。", "0", "cv_karenn_27", "0", "0"},
[400529] = {400529, 10005, 32, 24, "0", "0", "看來我們之間的默契已經足夠了呢。", "ボクたちはもう、心が通じ合ってるみたいだね。", "0", "0", "看來我們之間的默契已經足夠了呢。", "0", "cv_karenn_28", "0", "0"},
[400530] = {400530, 10005, 33, 25, "0", "0", "嘿呀！我踹！", "はっ！足蹴りを食らえ！", "0", "0", "嘿呀！我踹！", "0", "cv_karenn_29", "0", "0"},
[400531] = {400531, 10005, 34, 26, "0", "0", "歡迎回來，多瑙的領航，小生正愁沒有對手呢。", "お帰り、ダニューブのナビゲーター。ボクはちょうど、手合わせの相手がいなくて悩んでたところだ。", "0", "0", "歡迎回來，多瑙的領航，小生正愁沒有對手呢。", "0", "cv_karenn_32", "0", "0"},
[400532] = {400532, 10005, 35, 27, "0", "0", "就讓小生用拳腳為你開路吧。", "ボクが武術で道を切り開いてやる！", "0", "0", "就讓小生用拳腳為你開路吧。", "0", "cv_karenn_34", "0", "0"},
[400533] = {400533, 10005, 36, 28, "0", "0", "修行又要開始了啊。", "修行がまた始まるってことだね。", "0", "0", "修行又要開始了啊。", "0", "cv_karenn_35", "0", "0"},
[400534] = {400534, 10005, 37, 29, "0", "0", "部隊已經集合完畢了喔。", "部隊はもう、集合済みだ。", "0", "0", "部隊已經集合完畢了哦。", "0", "cv_karenn_36", "0", "0"},
[400535] = {400535, 10005, 38, 30, "0", "0", "希望能招到個好對手啊。", "好敵手が來ると良いな。", "0", "0", "希望能招到個好對手啊。", "0", "cv_karenn_37", "0", "0"},
[400536] = {400536, 10005, 39, 31, "0", "0", "我還是更習慣九州的裝備啊。", "個人的には九州の裝備の方がいい。", "0", "0", "我還是更習慣九州的裝備啊。", "0", "cv_karenn_38", "0", "0"},
[400537] = {400537, 10005, 40, 32, "0", "0", "採購的事情就交給小生吧！", "買いものならボクに任せて！", "0", "0", "採購的事情就交給小生吧！", "0", "cv_karenn_39", "0", "0"},
[400538] = {400538, 10005, 41, 33, "0", "0", "身份確認。", "身分確認だ。", "0", "0", "身份確認。", "0", "cv_karenn_40", "0", "0"},
[400539] = {400539, 10005, 42, 34, "0", "0", "按照自己的喜好來變更設定吧。", "自分の好みに合わせて設定を変更しよう。", "0", "0", "按照自己的喜好來變更設置吧。", "0", "cv_karenn_41", "0", "0"},
[400540] = {400540, 10005, 43, 35, "0", "0", "檢查一下有沒有新的來信吧。", "新しいメールが來てるかチェックしよう。", "0", "0", "檢查一下有沒有新的來信吧。", "0", "cv_karenn_42", "0", "0"},
[400541] = {400541, 10005, 44, 36, "0", "0", "這是領航專用的聊天室吧。", "これはナビゲーター専用のチャットルームかな？", "0", "0", "這是領航專用的聊天室吧。", "0", "cv_karenn_43", "0", "0"},
[400542] = {400542, 10005, 45, 37, "0", "0", "由小生來確認一下吧。", "ボクが確認してあげる。", "0", "0", "由小生來確認一下吧。", "0", "cv_karenn_44", "0", "0"},
[400600] = {400600, 10006, 1, 1, "0", "0", "蒼霧殘響~", "蒼霧殘響（ハツリバーブ）。", "0", "0", "蒼霧殘響~", "0", "cv_shirinn_32", "0", "0"},
[400601] = {400601, 10006, 2, 2, "0", "0", "工作不好會有什麼懲罰嗎？我很好奇喔~", "仕事で失敗したら、何か罰があるの？あたし、淒く知りたいなぁ。", "0", "0", "工作不好會有什麼懲罰嗎？我很好奇哦~", "0", "cv_shirinn_2", "0", "0"},
[400602] = {400602, 10006, 3, 3, "0", "0", "我是棲林·瓦爾特，您想叫我什麼都可以喔。", "あたし、シリン・ウォルターっていうの。好きに呼んでねぇ。", "0", "0", "我是棲林·瓦爾特，您想叫我什麼都可以哦。", "0", "cv_shirinn_1", "0", "0"},
[400603] = {400603, 10006, 4, 4, "0", "idle", "欸~如果我讓您感到壓力的話，就請懲罰我吧~", "ねぇねぇ、もしあたしのことでなにかストレスを感じたら、お仕置きでもなんでも、好きにしていいからねぇ。", "0", "0", "哎~如果我讓您感到壓力的話，就請懲罰我吧~", "0", "cv_shirinn_3", "0", "0"},
[400604] = {400604, 10006, 5, 4, "0", "idle", "領航，不要不理人家啦，總是這麼盯著我卻什麼都不做嗎？", "ナビゲーター、もうっ！もうちょっと構ってほしいの！なんであたしを見つめるだけで、何もしないの？", "0", "0", "領航，不要不理人家啦，總是這麼盯著我卻什麼都不做嗎？", "0", "cv_shirinn_4", "0", "0"},
[400605] = {400605, 10006, 6, 4, "0", "idle", "領航，你見到茱莉亞了嗎？嗯？找她有什麼事……嘿嘿，是秘密喔~", "ナビゲーター、ジュリアを見なかった？え？何の用かって？……うふふ、秘密よぉ。", "0", "0", "領航，你見到茱莉亞了嗎？嗯？找她有什麼事……嘿嘿，是秘密哦~", "0", "cv_shirinn_29", "0", "0"},
[400606] = {400606, 10006, 7, 5, "1_》_0_0.8", "level1", "領航，請責罵我，懲罰我吧。", "ナビゲーター、あたしを叱って。お仕置きしてぇ。", "0", "0", "領航，請責駡我，懲罰我吧。", "0", "cv_shirinn_30", "0", "0"},
[400607] = {400607, 10006, 8, 5, "1_》_0_0.8", "level1", "領航，你想要知道我的秘密嗎？", "ナビゲーター、あたしの秘密、知りたくない？", "0", "0", "領航，你想要知道我的秘密嗎？", "0", "cv_shirinn_5", "0", "0"},
[400608] = {400608, 10006, 9, 5, "1_》_100_1.5", "level2", "你們眼中的痛苦對我而言就是快樂，所以，領航，請責罵我吧~", "あなたにとっての苦しみは、あたしにとっては喜びなの。だからナビゲーター、あたしを責めてぇ～！", "0", "0", "你們眼中的痛苦對我而言就是快樂，所以，領航，請責駡我吧~", "0", "cv_shirinn_6", "0", "0"},
[400609] = {400609, 10006, 10, 5, "1_》_500_2", "level3", "果然…只有傷痛才能帶給我真正的愉悅呢，這樣的我才是真正的我。", "やっぱり……本當の喜びをもたらしてくれるのは、痛みだけ。今のあたしこそ、本當のあたしなの。", "0", "0", "果然…只有傷痛才能帶給我真正的愉悅呢，這樣的我才是真正的我。", "0", "cv_shirinn_7", "0", "0"},
[400610] = {400610, 10006, 11, 5, "1_》_1000_2.5", "level4", "和你在一起的時候總是感到非常安心呢，和肉體受到刺激後所產生的愉悅感不同……是那種，想讓人閉上眼好好休息一下的感覺呢。", "あなたと一緒にいると、いつもホッとするの。體に刺激を受けて得られる喜びとは違って、なんか……まどろむような感じ。", "0", "0", "和你在一起的時候總是感到非常安心呢，和肉體受到刺激後所產生的愉悅感不同……是那種，想讓人閉上眼好好休息一下的感覺呢。", "0", "cv_shirinn_8", "0", "0"},
[400611] = {400611, 10006, 12, 6, "0", "0", "完全不夠呢~", "全然足りないよぉ。", "0", "0", "完全不夠呢~", "0", "cv_shirinn_9", "0", "0"},
[400612] = {400612, 10006, 13, 7, "0", "0", "普通的疼痛已經不能滿足我了~", "普通の痛みじゃ、もう満足できないの。", "0", "0", "普通的疼痛已經不能滿足我了~", "0", "cv_shirinn_10", "0", "0"},
[400613] = {400613, 10006, 14, 8, "0", "0", "還有未知的刺激在等待著我嗎~", "あたしの知らない刺激がまだまだあるの？", "0", "0", "還有未知的刺激在等待著我嗎~", "0", "cv_shirinn_11", "0", "0"},
[400614] = {400614, 10006, 15, 9, "0", "0", "閾值提高了呢~", "痛みの閾値が上がったわぁ！", "0", "0", "閾值提高了呢~", "0", "cv_shirinn_12", "0", "0"},
[400615] = {400615, 10006, 16, 10, "0", "0", "攻擊都衝我來吧！", "攻撃なら全部、あたしに！", "0", "0", "攻擊都沖我來吧！", "0", "cv_shirinn_13", "0", "0"},
[400616] = {400616, 10006, 17, 11, "0", "0", "敵人太弱有些不夠盡興呢～", "敵が弱すぎて物足りなーい。", "0", "0", "敵人太弱有些不夠盡興呢～", "0", "cv_shirinn_14", "0", "0"},
[400617] = {400617, 10006, 18, 12, "0", "0", "這份刺激剛剛好~", "この刺激、ちょうどいい。", "0", "0", "這份刺激剛剛好~", "0", "cv_shirinn_15", "0", "0"},
[400618] = {400618, 10006, 19, 13, "0", "0", "有些過於刺激了~", "刺激がちょっと強すぎたかも……", "0", "0", "有些過於刺激了~", "0", "cv_shirinn_16", "0", "0"},
[400619] = {400619, 10006, 20, 14, "0", "0", "滿足感並不能抵消失敗的挫折感啊……", "あたしだけ満足しても、ダメね……。", "0", "0", "滿足感並不能抵消失敗的挫折感啊……", "0", "cv_shirinn_17", "0", "0"},
[400620] = {400620, 10006, 21, 15, "0", "0", "你滿足不了我呢！", "あんたじゃ満足できないわ！", "0", "0", "你滿足不了我呢！", "0", "cv_shirinn_18", "0", "0"},
[400621] = {400621, 10006, 23, 16, "0", "0", "欸嘿！", "やぁ！", "0", "0", "誒嘿！", "0", "cv_shirinn_19", "0", "0"},
[400622] = {400622, 10006, 24, 17, "0", "0", "啊～很痛吧~", "ああ、痛いよねぇー！", "0", "0", "啊～很痛吧~", "0", "cv_shirinn_21", "0", "0"},
[400623] = {400623, 10006, 26, 19, "0", "0", "要被擄走了嗎~", "攫われちゃう……", "0", "0", "要被擄走了嗎~", "0", "cv_shirinn_20", "0", "0"},
[400624] = {400624, 10006, 27, 20, "0", "0", "領航要做壞壞的事情了嗎？", "ナビゲーター、何か企んでない？", "0", "0", "領航要做壞壞的事情了嗎？", "0", "cv_shirinn_22", "0", "0"},
[400625] = {400625, 10006, 28, 21, "0", "0", "不要轉到前面偷看啦~", "正面から覗くなんて、ダメよ。", "0", "0", "不要轉到前面偷看啦~", "0", "cv_shirinn_23", "0", "0"},
[400626] = {400626, 10006, 29, 21, "0", "0", "這是放置玩法嗎~", "これって放置プレイなの？", "0", "0", "這是放置玩法嗎~", "0", "cv_shirinn_24", "0", "0"},
[400627] = {400627, 10006, 30, 22, "0", "0", "想要獎勵嗎~", "ご褒美が欲しい？", "0", "0", "想要獎勵嗎~", "0", "cv_shirinn_25", "0", "0"},
[400628] = {400628, 10006, 31, 23, "0", "0", "猜錯的話也可以換您來懲罰我喔~", "あなたが外したら、あたしにお仕置きしてぇ。", "0", "0", "猜錯的話也可以換您來懲罰我哦~", "0", "cv_shirinn_26", "0", "0"},
[400629] = {400629, 10006, 32, 24, "0", "0", "你還記得挺清楚嘛~", "よく覚えてたわぁ。", "0", "0", "你還記得挺清楚嘛~", "0", "cv_shirinn_27", "0", "0"},
[400630] = {400630, 10006, 33, 25, "0", "0", "這摻雜著失望與喜悅的感情是什麼呢……", "失望と喜びが混在するこの気持ち、複雑だわぁ……", "0", "0", "這摻雜著失望與喜悅的感情是什麼呢……", "0", "cv_shirinn_28", "0", "0"},
[400631] = {400631, 10006, 34, 26, "0", "0", "終於回來了嗎，我等了你好久了呢，領航~~", "やっと帰ってきたの？ずっと待ってたわぁ、ナビゲーター！", "0", "0", "終於回來了嗎，我等了你好久了呢，領航~~", "0", "cv_shirinn_31", "0", "0"},
[400632] = {400632, 10006, 35, 27, "0", "0", "故事總會迎來結局吧~", "物語には必ず終わりがあるものなのよぉ。", "0", "0", "故事總會迎來結局吧~", "0", "cv_shirinn_33", "0", "0"},
[400633] = {400633, 10006, 36, 28, "0", "0", "會有很多敵人吧~", "敵がいっぱいいるのかなぁ。", "0", "0", "會有很多敵人吧~", "0", "cv_shirinn_34", "0", "0"},
[400634] = {400634, 10006, 37, 29, "0", "0", "都是些可愛的夥伴呢~", "仲間のみんな、とっても可愛いわぁ。", "0", "0", "都是些可愛的夥伴呢~", "0", "cv_shirinn_35", "0", "0"},
[400635] = {400635, 10006, 38, 30, "0", "0", "新同伴要來了嗎？", "新しい仲間が來るの？", "0", "0", "新同伴要來了嗎？", "0", "cv_shirinn_36", "0", "0"},
[400636] = {400636, 10006, 39, 31, "0", "0", "想要新裝備了~~", "新しい裝備が欲しいわぁ。", "0", "0", "想要新裝備了~~", "0", "cv_shirinn_37", "0", "0"},
[400637] = {400637, 10006, 40, 32, "0", "0", "我可以推薦有趣的商品喔~", "面白い商品をおすすめしちゃうわ。", "0", "0", "我可以推薦有趣的商品哦~", "0", "cv_shirinn_38", "0", "0"},
[400638] = {400638, 10006, 41, 33, "0", "0", "領航是十分重要的~", "ナビゲーターはとっても大切な存在なの。", "0", "0", "領航是十分重要的~", "0", "cv_shirinn_39", "0", "0"},
[400639] = {400639, 10006, 42, 34, "0", "0", "更改設定~", "設定を変更できるわぁ。", "0", "0", "更改設置~", "0", "cv_shirinn_40", "0", "0"},
