[400641] = {400641, 10006, 44, 36, "0", "0", "和大家一起交流心得吧~", "みんないろんな體験談を話しましょうよぉ。", "0", "0", "和大家一起交流心得吧~", "0", "cv_shirinn_42", "0", "0"},
[400642] = {400642, 10006, 45, 37, "0", "0", "欸嘿~", "ねーえ。", "0", "0", "哎嘿~", "0", "cv_shirinn_43", "0", "0"},
[400700] = {400700, 10007, 1, 1, "0", "0", "蒼霧殘響。", "蒼霧殘響（ハツリバーブ）。", "0", "0", "蒼霧殘響。", "0", "cv_uki_31", "0", "0"},
[400701] = {400701, 10007, 2, 2, "0", "0", "請放心，我會一直待在這，照顧好您的。", "ご安心ください。私はずっとあなたの傍でお世話をしますから。", "0", "0", "請放心，我會一直待在這，照顧好您的。", "0", "cv_uki_2", "0", "0"},
[400702] = {400702, 10007, 3, 3, "0", "0", "初次見面，我的名字叫做海姬，是海神的新娘……開玩笑的，您的表情真是可愛啊。", "初めまして。私の名は海姫。海神の花嫁です――冗談ですわ。その表情、可愛かったですよ。", "0", "0", "初次見面，我的名字叫做海姬，是海神的新娘……開玩笑的，您的表情真是可愛啊。", "0", "cv_uki_1", "0", "0"},
[400703] = {400703, 10007, 4, 4, "0", "idle", "領航，把衣服脫下來吧……為什麼？欸呀，因為脫下來才能縫好它呀。", "服を脫いでくださいね、ナビゲーター……どうしたのですか？脫がないと繕えないですよ？", "0", "0", "領航，把衣服脫下來吧……為什麼？誒呀，因為脫下來才能縫好它呀。", "0", "cv_uki_3", "0", "0"},
[400704] = {400704, 10007, 5, 4, "0", "idle", "差不多該到休息的時間了……領航，午飯想吃什麼？", "そろそろ休憩時間ですね……ナビゲーター、お晝は何がいいですか？", "0", "0", "差不多該到休息的時間了……領航，午飯想吃什麼？", "0", "cv_uki_4", "0", "0"},
[400705] = {400705, 10007, 6, 4, "0", "idle", "默默……總是讓人不明白她在想什麼。但是那孩子似乎總是表現出一副很孤單的樣子，領航要多關心下她喔。", "モモ……あのコが何を考えているのか全然分かりません。でも、何だか寂しそうに見えます……優しくしてあげてくださいね、ナビゲーター。", "0", "0", "默默……總是讓人不明白她在想什麼。但是那孩子似乎總是表現出一副很孤單的樣子，領航要多關心下她噢。", "0", "cv_uki_28", "0", "0"},
[400706] = {400706, 10007, 7, 5, "1_》_0_0.8", "level1", "戰爭結束之後，海姬想回到故鄉，開一間旅館。每天看著來來往往的旅人，傾聽旅人的故事，治癒旅人的疲憊。", "戦爭が終わったら、私は故郷に帰って旅館をやりたいと思っています。毎日行き來する旅人たちを眺めて、彼らの物語を聞いたりして、疲れを癒してあげたいのです。", "0", "0", "戰爭結束之後，海姬想回到故鄉，開一間旅館。每天看著來來往往的旅人，傾聽旅人的故事，治癒旅人的疲憊。", "0", "cv_uki_29", "0", "0"},
[400707] = {400707, 10007, 8, 5, "1_》_0_0.8", "level1", "嗯？領航，我的臉上有什麼嗎？", "え？私の顔に何かついていますか？ナビゲーター。", "0", "0", "嗯？領航，我的臉上有什麼嗎？", "0", "cv_uki_5", "0", "0"},
[400708] = {400708, 10007, 9, 5, "1_》_100_1.5", "level2", "領航，總是吃一些不健康的食品對身體不好，讓我給您做些料理吧。", "ナビゲーター、不健康な食品ばかり食べていると、體に悪いですよ？私の自慢の手料理を作ってあげましょう。", "0", "0", "領航，總是吃一些不健康的食品對身體不好，讓我給您做些料理吧。", "0", "cv_uki_6", "0", "0"},
[400709] = {400709, 10007, 10, 5, "1_》_500_2", "level3", "領航，等閒暇的時候，我們一起去旅行吧，只有你和我喔~", "ナビゲーター、いつか一緒に旅行に行きましょう！私とあなた、二人きりで。", "0", "0", "領航，等閒暇的時候，我們一起去旅行吧，只有你和我噢~", "0", "cv_uki_7", "0", "0"},
[400710] = {400710, 10007, 11, 5, "1_》_1000_2.5", "level4", "真希望這樣的時光能一直持續下去啊……領航，您以後想和什麼樣的人結婚呢？", "こんな日が続くといいのにって思います……ナビゲーターは將來、どんな方と結婚したいのですか？", "0", "0", "真希望這樣的時光能一直持續下去啊……領航，您以後想和什麼樣的人結婚呢？", "0", "cv_uki_8", "0", "0"},
[400711] = {400711, 10007, 12, 6, "0", "0", "料理的水準也提高了呢。", "料理の腕が上がったみたいですね。", "0", "0", "料理的水準也提高了呢。", "0", "cv_uki_9", "0", "0"},
[400712] = {400712, 10007, 13, 7, "0", "0", "果然，我對領航來說是特別的嗎……", "やはり、ナビゲーターにとって、私は特別な存在なのですね……", "0", "0", "果然，我對領航來說是特別的嗎……", "0", "cv_uki_10", "0", "0"},
[400713] = {400713, 10007, 14, 8, "0", "0", "我感受到了，領航您那顆炙熱的心。為了回應那份熱情，海姬會傾盡所有的。", "感じていますよ、ナビゲーターのその熱い心。私は全てをかけてその情熱に応えます。", "0", "0", "我感受到了，領航您那顆炙熱的心。為了回應那份熱情，海姬會傾盡所有的。", "0", "cv_uki_11", "0", "0"},
[400714] = {400714, 10007, 15, 9, "0", "0", "連戰鬥技能也上升了喔~", "戦闘スキルが上達しました。", "0", "0", "連戰鬥技能也上升了噢~", "0", "cv_uki_12", "0", "0"},
[400715] = {400715, 10007, 16, 10, "0", "0", "戰場……可不能掉以輕心呢。", "戦場……絶対に気を緩めてはいけません。", "0", "0", "戰場……可不能掉以輕心呢。", "0", "cv_uki_13", "0", "0"},
[400716] = {400716, 10007, 17, 11, "0", "0", "戰鬥勝利，太好了~領航，一起回家吧。", "戦闘勝利！よかったですね！一緒に帰りましょう、ナビゲーター。", "0", "0", "戰鬥勝利，太好了~領航，一起回家吧。", "0", "cv_uki_14", "0", "0"},
[400717] = {400717, 10007, 18, 12, "0", "0", "有一些遺憾，下次一起努力吧，領航。", "惜しかったですね。また今度一緒に頑張りましょう、ナビゲーター。", "0", "0", "有一些遺憾，下次一起努力吧，領航。", "0", "cv_uki_15", "0", "0"},
[400718] = {400718, 10007, 19, 13, "0", "0", "真危險，領航，您沒事吧？", "危ないところでした！ナビゲーター、大丈夫ですか？", "0", "0", "真危險，領航，您沒事吧？", "0", "cv_uki_16", "0", "0"},
[400719] = {400719, 10007, 20, 14, "0", "0", "領航，請跟緊我，要撤退了。", "ナビゲーター、撤退しますから、私について來てください。", "0", "0", "領航，請跟緊我，要撤退了。", "0", "cv_uki_17", "0", "0"},
[400720] = {400720, 10007, 21, 15, "0", "0", "嘿咻！消滅一隻了！", "やっ！一體、片付けましたね！", "0", "0", "嘿咻！幹掉一隻了！", "0", "cv_uki_18", "0", "0"},
[400721] = {400721, 10007, 23, 16, "0", "0", "這是……大海的力量。", "これが……海の力です。", "0", "0", "這是……大海的力量。", "0", "cv_uki_19", "0", "0"},
[400722] = {400722, 10007, 26, 19, "0", "0", "抱歉，領航……給您添麻煩了……", "申し訳ありません、ナビゲーター……ご迷惑をお掛けしてしまって……", "0", "0", "抱歉，領航……給您添麻煩了……", "0", "cv_uki_20", "0", "0"},
[400723] = {400723, 10007, 27, 20, "0", "0", "領航，您不進來嗎？", "ナビゲーター、入らないのですか？", "0", "0", "領航，您不進來嗎？", "0", "cv_uki_21", "0", "0"},
[400724] = {400724, 10007, 28, 21, "0", "0", "海姬從小時候開始，就很喜歡泡在水裡的感覺，您呢？", "私は小さい頃から水の中が好きなんです。あなたは？", "0", "0", "海姬從小時候開始，就很喜歡泡在水裡的感覺，您呢？", "0", "cv_uki_22", "0", "0"},
[400725] = {400725, 10007, 29, 21, "0", "0", "一起洗吧，領航您也累了一天了，不是嗎？", "一緒に入りましょう。今日も一日頑張っていましたから、ナビゲーターもお疲れでしょう。", "0", "0", "一起洗吧，領航您也累了一天了，不是嗎？", "0", "cv_uki_23", "0", "0"},
[400726] = {400726, 10007, 30, 22, "0", "0", "您要當心腳下的路面呀。", "足元に、お気をつけて。", "0", "0", "您要當心腳下的路面呀。", "0", "cv_uki_24", "0", "0"},
[400727] = {400727, 10007, 31, 23, "0", "0", "如果領航能猜中是我的話，我會很高興的。", "當たったら嬉しいです。", "0", "0", "如果領航能猜中是我的話，我會很高興的。", "0", "cv_uki_25", "0", "0"},
[400728] = {400728, 10007, 32, 24, "0", "0", "我從一開始，就相信您一定能答對的。", "正解すると信じていましたよ、最初から。", "0", "0", "我從一開始，就相信您一定能答對的。", "0", "cv_uki_26", "0", "0"},
[400729] = {400729, 10007, 33, 25, "0", "0", "嗯……沒關係，領航已經盡力了，對吧？", "うーん……大丈夫です。ナビゲーターは全力を盡くしましたから、ね？", "0", "0", "嗯……沒關係，領航已經盡力了，對吧？", "0", "cv_uki_27", "0", "0"},
[400730] = {400730, 10007, 34, 26, "0", "0", "領航，今天您也要工作嗎？那麼，我也會一直在這陪您的。", "今日もお仕事ですか、ナビゲーター？では、ここから、ずっとご一緒しますよ。", "0", "0", "領航，今天您也要工作嗎？那麼，我也會一直在這陪您的。", "0", "cv_uki_30", "0", "0"},
[400731] = {400731, 10007, 35, 27, "0", "0", "領航，請您帶領著我們前進吧。", "ナビゲーター、私たちを率いて前に進んでください。", "0", "0", "領航，請您帶領著我們前進吧。", "0", "cv_uki_32", "0", "0"},
[400732] = {400732, 10007, 36, 28, "0", "0", "您要多注意身體喔。", "お體に気をつけてくださいね。", "0", "0", "您要多注意身體哦。", "0", "cv_uki_33", "0", "0"},
[400733] = {400733, 10007, 37, 29, "0", "0", "有不聽話的孩子嗎？", "言う事を聞かないコがいたりしますか？", "0", "0", "有不聽話的孩子嗎？", "0", "cv_uki_34", "0", "0"},
[400734] = {400734, 10007, 38, 30, "0", "0", "要給新的同伴做豐盛的宴席才行。", "新しい仲間のために豪華な宴を用意してあげないと。", "0", "0", "要給新的同伴做豐盛的宴席才行。", "0", "cv_uki_35", "0", "0"},
[400735] = {400735, 10007, 39, 31, "0", "0", "舊的東西要記得回收利用喔。", "古いものは回収して再利用するようにしましょう。", "0", "0", "舊的東西要記得回收利用噢。", "0", "cv_uki_36", "0", "0"},
[400736] = {400736, 10007, 40, 32, "0", "0", "購物要適度喔。", "お買い物は適度に、お願いしますね。", "0", "0", "購物要適度哦。", "0", "cv_uki_37", "0", "0"},
[400737] = {400737, 10007, 41, 33, "0", "0", "您要記得經常檢查身體。", "健診をこまめにやりましょうね。", "0", "0", "您要記得經常檢查身體。", "0", "cv_uki_38", "0", "0"},
[400738] = {400738, 10007, 42, 34, "0", "0", "變更設定，您在這方面上很認真呢。", "設定の変更、真面目にやっていますね。", "0", "0", "變更設置，您在這方面上很認真呢。", "0", "cv_uki_39", "0", "0"},
[400739] = {400739, 10007, 43, 35, "0", "0", "我已經將信件整理好了~", "もうメールの整理は終わりましたよ。", "0", "0", "我已經將郵件整理好了~", "0", "cv_uki_40", "0", "0"},
[400740] = {400740, 10007, 44, 36, "0", "0", "社交能充實人的心靈呢。", "交流は人の心を豊かにしてくれます。", "0", "0", "社交能充實人的心靈呢。", "0", "cv_uki_41", "0", "0"},
[400741] = {400741, 10007, 45, 37, "0", "0", "您還有其他事嗎？", "他に何かありますか？", "0", "0", "您還有其他事嗎？", "0", "cv_uki_42", "0", "0"},
[400800] = {400800, 10008, 1, 1, "0", "0", "蒼霧殘響。", "蒼霧殘響（ハツリバーブ）。", "0", "0", "蒼霧殘響。", "0", "cv_dororisu_31", "0", "0"},
[400801] = {400801, 10008, 2, 2, "0", "0", "交給我吧，我一定會守住這裡的。", "私に任せてください。この場所は、絶対に守ってみせます。", "0", "0", "交給我吧，我一定會守住這裡的。", "0", "cv_dororisu_2", "0", "0"},
[400802] = {400802, 10008, 3, 3, "0", "0", "我的名字叫做多洛莉絲，第三研究室防衛班的多洛莉絲……從今天起就要給您添麻煩了。", "私の名はドロリィス、第三研究室防衛班のドロリィスです……今日からお世話になります、よろしくお願いします。", "0", "0", "我的名字叫做多洛莉絲，第三研究室防衛班的多洛莉絲……從今天起就要給您添麻煩了。", "0", "cv_dororisu_1", "0", "0"},
[400803] = {400803, 10008, 4, 4, "0", "idle", "我已經很久沒回方舟了呢，這裡的變化可真不小啊。", "方舟に帰るのは久しぶりです。ここも、大きく変わりましたね。", "0", "0", "我已經很久沒回方舟了呢，這裡的變化可真不小啊。", "0", "cv_dororisu_3", "0", "0"},
[400804] = {400804, 10008, 5, 4, "0", "idle", "領航，要喝茶嗎？這是我家裡人從老家寄過來的，因為稍微有些多了，所以就想分給大家。", "ナビゲーターさん、お茶はいかがですか？これ、実家から送ってきて…...たくさんあるので、皆さんにお分けしようかなと思いまして。", "0", "0", "領航，要喝茶嗎？這是我家裡人從老家寄過來的，因為稍微有些多了，所以就想分給大家。", "0", "cv_dororisu_4", "0", "0"},
[400805] = {400805, 10008, 6, 4, "0", "idle", "第三研究室防衛班哪怕只剩下一個人，我們都不會忘記自己的使命。", "第三研究室防衛班の私たちは、たとえ一人になったとしても、自分の使命を全うします。", "0", "0", "第三研究室防衛班哪怕只剩下一個人，我們都不會忘記自己的使命。", "0", "cv_dororisu_28", "0", "0"},
[400806] = {400806, 10008, 7, 5, "1_》_0_0.8", "level1", "真希望有朝一日，防衛班還能恢復往昔的熱鬧啊。", "いつか、昔のように賑やかな防衛班に戻れたらなぁって思います。", "0", "0", "真希望有朝一日，防衛班還能恢復往昔的熱鬧啊。", "0", "cv_dororisu_29", "0", "0"},
[400807] = {400807, 10008, 8, 5, "1_》_0_0.8", "level1", "嗯？領航找我有什麼事嗎？還是說要一起行動？", "え？私に何かご用ですか、それとも、一緒に行動したい、…...ということでしょうか？", "0", "0", "嗯？領航找我有什麼事嗎？還是說要一起行動？", "0", "cv_dororisu_5", "0", "0"},
[400808] = {400808, 10008, 9, 5, "1_》_100_1.5", "level2", "海鷗，我最喜歡的動物就是它們。看著它們集群劃過碧空的身影，我就會不由自主地想起她們來……", "カモメは、私の一番好きな動物です。群れで青空を飛んでいく姿を見るたびに、彼女たちのことを思い出すんです……", "0", "0", "海鷗，我最喜歡的動物就是它們。看著它們集群劃過碧空的身影，我就會不由自主地想起她們來……", "0", "cv_dororisu_6", "0", "0"},
[400809] = {400809, 10008, 10, 5, "1_》_500_2", "level3", "領航，你聽說過北極燕鷗嗎？它們是世界上遷徙路線最長的候鳥。每年都要經歷4萬公里的旅途，往返於兩極的夏日。我總是在隱約中覺得，您也是一隻為了追尋某物而跋山涉水的燕鷗呢。", "キョクアジサシって聞いたことありますか？最も長距離の渡りをする鳥ですよ。この鳥は年間約4萬キロを飛んで、夏を追い求め、両極を往復するんです。ナビゲーターさんも、何かを追い求めるために旅をするキョクアジサシのような方なのかなって、何となくそう思ったんです。", "0", "0", "領航，你聽說過北極燕鷗嗎？它們是世界上遷徙路線最長的候鳥。每年都要經歷4萬公里的旅途，往返於兩極的夏日。我總是在隱約中覺得，您也是一隻為了追尋某物而跋山涉水的燕鷗呢。", "0", "cv_dororisu_7", "0", "0"},
[400810] = {400810, 10008, 11, 5, "1_》_1000_2.5", "level4", "大海還真是厲害啊，即便是經歷那樣的戰鬥也能將一切在一夜之間恢復成原樣。這裡已經沒有什麼讓我留戀的了……領航，不久之後也許我也會像候鳥一樣，為了尋回自己那短暫的夏日而啟航吧。", "海って淒いですね。あんな戦いがあったっていうのに、一晩で元通りに戻りました。ここにはもう、未練はありません……ナビゲーターさん、私ももうすぐ渡り鳥のように、自分の短い夏を取り戻すために旅に出ようかと思うんです。", "0", "0", "大海還真是厲害啊，即便是經歷那樣的戰鬥也能將一切在一夜之間恢復成原樣。這裡已經沒有什麼讓我留戀的了……領航，不久之後也許我也會像候鳥一樣，為了尋回自己那短暫的夏日而啟航吧。", "0", "cv_dororisu_8", "0", "0"},
[400811] = {400811, 10008, 12, 6, "0", "0", "謝謝您！", "ありがとうございます！", "0", "0", "謝謝您！", "0", "cv_dororisu_9", "0", "0"},
[400812] = {400812, 10008, 13, 7, "0", "0", "又讓您費心了。", "お手數をおかけしました。", "0", "0", "又讓您費心了。", "0", "cv_dororisu_10", "0", "0"},
[400813] = {400813, 10008, 14, 8, "0", "0", "您對我的提攜以及幫助，多洛莉絲永遠不會忘記，當您遇到困境之時，這份力量一定會為您所用。", "ご支援とご協力、ドロリィスは決して忘れません。何か困ったことがありましたら、必ずあなたの力になります。", "0", "0", "您對我的提攜以及幫助，多洛莉絲永遠不會忘記，當您遇到困境之時，這份力量一定會為您所用。", "0", "cv_dororisu_11", "0", "0"},
[400814] = {400814, 10008, 15, 9, "0", "0", "新功能還需要適應一段時間呢。", "新機能に慣れるまで、もうちょっと時間がかかりそうですね。", "0", "0", "新功能還需要適應一段時間呢。", "0", "cv_dororisu_12", "0", "0"},
[400815] = {400815, 10008, 16, 10, "0", "0", "登陸完畢，準備開始迎敵。", "ログイン完了です。迎撃の準備に入ります。", "0", "0", "登陸完畢，準備開始迎敵。", "0", "cv_dororisu_13", "0", "0"},
[400816] = {400816, 10008, 17, 11, "0", "0", "太好了……大家都沒有受傷吧。", "良かったです……皆さん、無事でしたか？", "0", "0", "太好了……大家都沒有受傷吧。", "0", "cv_dororisu_14", "0", "0"},
[400817] = {400817, 10008, 18, 12, "0", "0", "好險……差點就沒擋下來。", "危なかったですね……危うくやられてしまうところでした。", "0", "0", "好險……差點就沒擋下來。", "0", "cv_dororisu_15", "0", "0"},
[400818] = {400818, 10008, 19, 13, "0", "0", "嗚……都是我的錯……", "うっ……全部、私のせいです……", "0", "0", "嗚……都是我的錯……", "0", "cv_dororisu_16", "0", "0"},
[400819] = {400819, 10008, 20, 14, "0", "0", "任務失敗……拜託了，這次你們先撤離吧。", "ミッション失敗……お願いですから、先に撤退してください。", "0", "0", "任務失敗……拜託了，這次你們先撤離吧。", "0", "cv_dororisu_17", "0", "0"},
[400820] = {400820, 10008, 21, 15, "0", "0", "呼啊——終於解決了……", "ふぅ――やっと解決できました……", "0", "0", "呼啊——終於解決了……", "0", "cv_dororisu_18", "0", "0"},
[400821] = {400821, 10008, 23, 16, "0", "0", "嘿啊！", "やっ！", "0", "0", "嘿啊！", "0", "cv_dororisu_19", "0", "0"},
[400822] = {400822, 10008, 26, 19, "0", "0", "好冷……和那個時候一樣……", "寒いです……あの時と、同じ……", "0", "0", "好冷……和那個時候一樣……", "0", "cv_dororisu_20", "0", "0"},
[400823] = {400823, 10008, 27, 20, "0", "0", "在海上的時候我們都沒有像這樣洗澡的機會呢。", "海にいた時はこうしてお風呂に入る機會がなかったので……", "0", "0", "在海上的時候我們都沒有像這樣洗澡的機會呢。", "0", "cv_dororisu_21", "0", "0"},
[400824] = {400824, 10008, 28, 21, "0", "0", "水溫正好呢，嗯~啊——", "水溫がちょうどいいです。ふぅ～ああ――", "0", "0", "水溫正好呢，嗯~啊——", "0", "cv_dororisu_22", "0", "0"},
[400825] = {400825, 10008, 29, 21, "0", "0", "領航，要小心些喔。", "ナビゲーターさん、お気を付けください。", "0", "0", "領航，要小心些哦。", "0", "cv_dororisu_23", "0", "0"},
[400826] = {400826, 10008, 30, 22, "0", "0", "果然……又發生意外了嗎？", "やっぱり……何か起きてしまったのでしょうか？", "0", "0", "果然……又發生意外了嗎？", "0", "cv_dororisu_24", "0", "0"},
[400827] = {400827, 10008, 31, 23, "0", "0", "領航，來猜猜我是誰吧？", "ナビゲーターさん、私が誰なのか、當ててみてください！", "0", "0", "領航，來猜猜我是誰吧？", "0", "cv_dororisu_25", "0", "0"},
[400828] = {400828, 10008, 32, 24, "0", "0", "回答正確！", "正解です！", "0", "0", "回答正確！", "0", "cv_dororisu_26", "0", "0"},
[400829] = {400829, 10008, 33, 25, "0", "0", "放心好了，沒有懲罰環節喔。", "安心してくださいね、罰ゲームはありませんから。", "0", "0", "放心好了，沒有懲罰環節哦。", "0", "cv_dororisu_27", "0", "0"},
[400830] = {400830, 10008, 34, 26, "0", "0", "歡迎回來，多瑙特別聯合部隊的領航。", "お帰りなさい、ダニューブ特別連合部隊のナビゲーターさん。", "0", "0", "歡迎回來，多瑙特別聯合部隊的領航。", "0", "cv_dororisu_30", "0", "0"},
[400831] = {400831, 10008, 35, 27, "0", "0", "繼續書寫屬於您的故事吧。", "あなたの物語の続きを書きましょう。", "0", "0", "繼續書寫屬於您的故事吧。", "0", "cv_dororisu_32", "0", "0"},
[400832] = {400832, 10008, 36, 28, "0", "0", "第三研究室防衛班，準備完畢。", "第三研究室防衛班、準備完了です。", "0", "0", "第三研究室防衛班，準備完畢。", "0", "cv_dororisu_33", "0", "0"},
[400833] = {400833, 10008, 37, 29, "0", "0", "大家已經集合完畢了呢。", "皆さん、集合完了しましたね。", "0", "0", "大家已經集合完畢了呢。", "0", "cv_dororisu_34", "0", "0"},
[400834] = {400834, 10008, 38, 30, "0", "0", "歡迎會已經準備好了喔。", "歓迎會の用意ができましたよ。", "0", "0", "歡迎會已經準備好了哦。", "0", "cv_dororisu_35", "0", "0"},
[400835] = {400835, 10008, 39, 31, "0", "0", "是時候去訂購一些新裝備了呢。", "そろそろ新しい裝備を購入しないといけませんね。", "0", "0", "是時候去訂購一些新裝備了呢。", "0", "cv_dororisu_36", "0", "0"},
[400836] = {400836, 10008, 40, 32, "0", "0", "連接採購中心。", "ショッピングセンターに接続します。", "0", "0", "連接採購中心。", "0", "cv_dororisu_37", "0", "0"},
[400837] = {400837, 10008, 41, 33, "0", "0", "確認一下自己的資料吧。", "自分の資料を確認しましょう。", "0", "0", "確認一下自己的資料吧。", "0", "cv_dororisu_38", "0", "0"},
[400838] = {400838, 10008, 42, 34, "0", "0", "設定沒有問題吧。", "設定は大丈夫でしょうか。", "0", "0", "設置沒有問題吧。", "0", "cv_dororisu_39", "0", "0"},
[400839] = {400839, 10008, 43, 35, "0", "0", "郵箱的狀態也ok吧？", "受信箱も大丈夫でしょうか。", "0", "0", "郵箱的狀態也ok吧？", "0", "cv_dororisu_40", "0", "0"},
[400840] = {400840, 10008, 44, 36, "0", "0", "和其他領航一起聊天吧。", "他のナビゲーターさんとチャットしましょう。", "0", "0", "和其他領航一起聊天吧。", "0", "cv_dororisu_41", "0", "0"},
[400841] = {400841, 10008, 45, 37, "0", "0", "得好好確認一下呢。", "ちゃんと確認しないといけませんね。", "0", "0", "得好好確認一下呢。", "0", "cv_dororisu_42", "0", "0"},
[400900] = {400900, 10009, 1, 1, "0", "0", "蒼霧殘響", "0", "0", "0", "0", "0", "cv_morgan_33", "0", "0"},
[400901] = {400901, 10009, 2, 2, "0", "0", "我嗎…我明白了，我會好好協助領航您完成工作的。", "0", "0", "0", "0", "0", "cv_morgan_2", "0", "0"},
[400902] = {400902, 10009, 3, 3, "0", "0", "您好，領航。我是月冕的隊長，摩根勒菲，莉莉絲和斯卡蒂有給您添麻煩嗎？", "0", "0", "0", "0", "0", "cv_morgan_1", "0", "0"},
[400903] = {400903, 10009, 4, 4, "0", "idle", "我不像莉莉絲那孩子那麼敏感…不過，我也能感受到周圍人的感情。好的，壞的，我全部都能感受到。領航，您也是這樣嗎…？", "0", "0", "0", "0", "0", "cv_morgan_3", "0", "0"},
[400904] = {400904, 10009, 5, 4, "0", "idle", "領航，您好像很累的樣子…還是休息一下比較好吧？", "0", "0", "0", "0", "0", "cv_morgan_4", "0", "0"},
[400905] = {400905, 10009, 6, 4, "0", "idle", "斯卡蒂…我和她是七年前認識的，那時發生的事情…不，沒什麼，請不要在意。", "0", "0", "0", "0", "0", "cv_morgan_30", "0", "0"},
[400906] = {400906, 10009, 7, 5, "1_》_0_0.8", "level1", "我想守護所有人的幸福…想要所有不幸的人都能過上正常的，幸福的生活。這就是我戰鬥的理由…那個…很…奇怪嗎？", "0", "0", "0", "0", "0", "cv_morgan_31", "0", "0"},
[400907] = {400907, 10009, 8, 5, "1_》_0_0.8", "level1", "領航的身邊總是聚集著很多可愛的孩子呢，大家都很信賴您，領航。", "0", "0", "0", "0", "0", "cv_morgan_5", "0", "0"},
[400908] = {400908, 10009, 9, 5, "1_》_100_1.5", "level2", "領航，您想看魔術嗎？“紙牌魔術”啊，“禮帽魔術”之類的，嘿嘿嘿……", "0", "0", "0", "0", "0", "cv_morgan_6", "0", "0"},
[400909] = {400909, 10009, 10, 5, "1_》_500_2", "level3", "我的魔術，是從父母那裏學來的。以前，只要他們表演魔術，大家就會露出幸福的笑容。我也想…讓大家都能綻放笑容。", "0", "0", "0", "0", "0", "cv_morgan_7", "0", "0"},
[400910] = {400910, 10009, 11, 5, "1_》_1000_2.5", "level4", "大家如此信賴領航的理由…現在的我已經完全明白了。想要更加依賴領航，想要陪伴在領航身邊，這份心情，我和大家是一樣的。", "0", "0", "0", "0", "0", "cv_morgan_8", "0", "0"},
[400911] = {400911, 10009, 12, 6, "0", "0", "謝謝，這下變得更強了呢。", "0", "0", "0", "0", "0", "cv_morgan_9", "0", "0"},
[400912] = {400912, 10009, 13, 7, "0", "0", "謝謝…我一定不會辜負領航您的期望的。", "0", "0", "0", "0", "0", "cv_morgan_10", "0", "0"},
[400913] = {400913, 10009, 14, 8, "0", "0", "不知不覺我也成長了許多…如果沒有領航的話，我一個人是不可能做到的。謝謝您，領航，今後也和我一起守護大家吧。", "0", "0", "0", "0", "0", "cv_morgan_11", "0", "0"},
[400914] = {400914, 10009, 15, 9, "0", "0", "這份力量，我會好好使用的。", "0", "0", "0", "0", "0", "cv_morgan_12", "0", "0"},
[400915] = {400915, 10009, 16, 10, "0", "0", "傷害同伴的人…在哪？", "0", "0", "0", "0", "0", "cv_morgan_13", "0", "0"},
[400916] = {400916, 10009, 17, 11, "0", "0", "敵人全滅，我們勝利了，領航。", "0", "0", "0", "0", "0", "cv_morgan_14", "0", "0"},
[400917] = {400917, 10009, 18, 12, "0", "0", "我需要得做更好才行…不然……", "0", "0", "0", "0", "0", "cv_morgan_15", "0", "0"},
[400918] = {400918, 10009, 19, 13, "0", "0", "大家…還好嗎？", "0", "0", "0", "0", "0", "cv_morgan_16", "0", "0"},
[400919] = {400919, 10009, 20, 14, "0", "0", "…振作起來，領航，還沒有結束。", "0", "0", "0", "0", "0", "cv_morgan_17", "0", "0"},
[400920] = {400920, 10009, 21, 15, "0", "0", "不能放鬆警惕。", "0", "0", "0", "0", "0", "cv_morgan_18", "0", "0"},
[400921] = {400921, 10009, 23, 16, "0", "0", "給我、安靜、呀！", "0", "0", "0", "0", "0", "cv_morgan_19", "0", "0"},
[400922] = {400922, 10009, 26, 19, "0", "0", "大家…加油。", "0", "0", "0", "0", "0", "cv_morgan_20", "0", "0"},
[400923] = {400923, 10009, 24, 17, "0", "0", "不會讓你們逃走的！", "0", "0", "0", "0", "0", "cv_morgan_21", "0", "0"},
[400924] = {400924, 10009, 25, 18, "0", "0", "請看著吧，這是我為您準備的華麗演出。", "0", "0", "0", "0", "0", "cv_morgan_22", "0", "0"},
[400925] = {400925, 10009, 27, 20, "0", "0", "領航，麻煩您了。", "0", "0", "0", "0", "0", "cv_morgan_23", "0", "0"},
[400926] = {400926, 10009, 28, 21, "0", "0", "以前，和父母流亡的時候，都沒辦法像這樣靜下心來放鬆呢……", "0", "0", "0", "0", "0", "cv_morgan_24", "0", "0"},
[400927] = {400927, 10009, 29, 21, "0", "0", "莉莉絲來過了嗎…您被她嚇到了？真是的…之後我會好好跟她溝通的，讓她不要再這麼做了。", "0", "0", "0", "0", "0", "cv_morgan_25", "0", "0"},
[400928] = {400928, 10009, 30, 22, "0", "0", "領航，請小心。", "0", "0", "0", "0", "0", "cv_morgan_26", "0", "0"},
[400929] = {400929, 10009, 31, 23, "0", "0", "猜對了的話…我給您表演一個魔術吧？", "0", "0", "0", "0", "0", "cv_morgan_27", "0", "0"},
[400930] = {400930, 10009, 32, 24, "0", "0", "——嘿！玫瑰花出現了，如何，厲害吧？", "0", "0", "0", "0", "0", "cv_morgan_28", "0", "0"},
[400931] = {400931, 10009, 33, 25, "0", "0", "沒關係，我相信領航您下次一定會成功的……", "0", "0", "0", "0", "0", "cv_morgan_29", "0", "0"},
[400932] = {400932, 10009, 34, 26, "0", "0", "領航，歡迎回來，今天我們也一起加油吧。", "0", "0", "0", "0", "0", "cv_morgan_32", "0", "0"},
[400933] = {400933, 10009, 35, 27, "0", "0", "不戰鬥的話…就無法保護大家，不是嗎？", "0", "0", "0", "0", "0", "cv_morgan_34", "0", "0"},
[400934] = {400934, 10009, 36, 28, "0", "0", "不要太勉強哦。", "0", "0", "0", "0", "0", "cv_morgan_35", "0", "0"},
[400935] = {400935, 10009, 37, 29, "0", "0", "大家，都要乖乖的噢？", "0", "0", "0", "0", "0", "cv_morgan_36", "0", "0"},
[400936] = {400936, 10009, 38, 30, "0", "0", "要為新來的同伴準備禮物才行。", "0", "0", "0", "0", "0", "cv_morgan_37", "0", "0"},
[400937] = {400937, 10009, 39, 31, "0", "0", "要購入新裝備嗎？", "0", "0", "0", "0", "0", "cv_morgan_38", "0", "0"},
[400938] = {400938, 10009, 40, 32, "0", "0", "有好好做購物規劃嗎？", "0", "0", "0", "0", "0", "cv_morgan_39", "0", "0"},
[400939] = {400939, 10009, 41, 33, "0", "0", "請看個人信息。", "0", "0", "0", "0", "0", "cv_morgan_40", "0", "0"},
[400940] = {400940, 10009, 42, 34, "0", "0", "要看仔細哦。", "0", "0", "0", "0", "0", "cv_morgan_41", "0", "0"},
[400941] = {400941, 10009, 43, 35, "0", "0", "情書…不可能有吧？", "0", "0", "0", "0", "0", "cv_morgan_42", "0", "0"},
[400942] = {400942, 10009, 44, 36, "0", "0", "有需要幫助的人嗎？", "0", "0", "0", "0", "0", "cv_morgan_43", "0", "0"},
[400943] = {400943, 10009, 45, 37, "0", "0", "真有趣呢。", "0", "0", "0", "0", "0", "cv_morgan_44", "0", "0"},
[401000] = {401000, 10010, 1, 1, "0", "0", "蒼霧殘響。", "蒼霧殘響（ハツリバーブ）。", "0", "0", "蒼霧殘響。", "0", "cv_alaita_32", "0", "0"},
[401001] = {401001, 10010, 2, 2, "0", "0", "可不要看我看入迷了喔，那樣會耽誤工作的。", "あまり見惚れないで。仕事に支障を來すわよ。", "0", "0", "可不要看我看入迷了哦，那樣會耽誤工作的。", "0", "cv_alaita_2", "0", "0"},
[401002] = {401002, 10010, 3, 3, "0", "0", "第三研究室防衛班，阿萊塔。我家的多洛莉絲隊長受你照顧了，謝謝~", "第三研究室防衛班、アライタ。うちのドロリィス隊長が世話になったようね。禮を言うわ。", "0", "0", "第三研究室防衛班，阿萊塔。我家的多洛莉絲隊長受你照顧了，謝謝~", "0", "cv_alaita_1", "0", "0"},
[401003] = {401003, 10010, 4, 4, "0", "idle", "“海妖”？的確有人這麼叫我啦…不過，我唱歌並沒有那麼好聽喔？", "セイレーン？私をそう呼ぶ者もいるけど……私の歌はそんなに上手くないわよ？", "0", "0", "“海妖”？的確有人這麼叫我啦…不過，我唱歌並沒有那麼好聽噢？", "0", "cv_alaita_3", "0", "0"},
[401004] = {401004, 10010, 5, 4, "0", "idle", "你不覺得那些轉瞬即逝的美麗總是讓人著迷嗎？當然，這其中也包括我自己。", "一瞬の美しさには、目を奪われてしまうものよ。勿論、私のことも、ね。", "0", "0", "你不覺得那些轉瞬即逝的美麗總是讓人著迷嗎？當然，這其中也包括我自己。", "0", "cv_alaita_4", "0", "0"},
[401005] = {401005, 10010, 6, 4, "0", "idle", "多洛莉絲隊長~多洛莉絲隊長~啊…不在啊，那下次再把這些文檔交給她吧。偷懶？不不不，這是沒辦法的事吧。", "ドロリィス隊長？……ドロリィス隊長？……あら、いないの。じゃあこのファイルを渡すのは今度ね。……サボり？いいえ、これは仕方のないことよ。", "0", "0", "多洛莉絲隊長~多洛莉絲隊長~啊…不在啊，那下次再把這些檔交給她吧。偷懶？不不不，這是沒辦法的事吧。", "0", "cv_alaita_29", "0", "0"},
[401006] = {401006, 10010, 7, 5, "1_》_0_0.8", "level1", "欸呀，我正好也在找您呢。明天早上有我的演出，要來看看嗎？等演出結束之後，我們正好可以一起去喝杯茶。", "あら、ちょうど探していたのよ。明日、私の舞臺があるの。見に來ない？それで終わったら、一緒にお茶でもどうかしら。", "0", "0", "哎呀，我正好也在找您呢。明天早上有我的演出，要來看看嗎？等演出結束之後，我們正好可以一起去喝杯茶。", "0", "cv_alaita_30", "0", "0"},
[401007] = {401007, 10010, 8, 5, "1_》_0_0.8", "level1", "對認識不久的異性出手，可不太好喔。", "知り合ったばかりの女性に手を出すのは感心しないわ。", "0", "0", "對認識不久的異性出手，可不太好噢。", "0", "cv_alaita_5", "0", "0"},
[401008] = {401008, 10010, 9, 5, "1_》_100_1.5", "level2", "據說，“海妖”在大海上可是會招來不幸的。那你最好不要和我太親近了……你不在乎嗎？是這樣啊…呵呵。", "伝説のセイレーンは海で不幸をもたらすもの。あまり私に近づかない方がいいわよ。……そんなの気にしないって？そう……フフ。", "0", "0", "據說，“海妖”在大海上可是會招來不幸的。那你最好不要和我太親近了……你不在乎嗎？是這樣啊…呵呵。", "0", "cv_alaita_6", "0", "0"},
[401009] = {401009, 10010, 10, 5, "1_》_500_2", "level3", "呵，連領航你也被我的美色迷惑了嗎？那麼，就請好好守護我吧，領航~我也會保護你的~", "あら。ナビゲーターも私の美しさの虜になったのかしら。それじゃあ、ちゃんと私を守ってちょうだい。私もあなたを守るから。", "0", "0", "呵，連領航你也被我的美色迷惑了嗎？那麼，就請好好守護我吧，領航~我也會保護你的~", "0", "cv_alaita_7", "0", "0"},
[401010] = {401010, 10010, 11, 5, "1_》_1000_2.5", "level4", "我的人生只需如曇花與朝露那樣便好，畢竟，永恆只會讓美麗褪色。領航，現在，就與我一起享受這份短暫的美好吧。", "私の人生は、花や朝露のように一瞬でいいの。美しさなんて色褪せるだけだもの。さぁナビゲーター。この束の間の美しさを、私と一緒に楽しんでちょうだい。", "0", "0", "我的人生只需如曇花與朝露那樣便好，畢竟，永恆只會讓美麗褪色。領航，現在，就與我一起享受這份短暫的美好吧。", "0", "cv_alaita_8", "0", "0"},
[401011] = {401011, 10010, 12, 6, "0", "0", "不錯的感覺。", "いい感じね。", "0", "0", "不錯的感覺。", "0", "cv_alaita_9", "0", "0"},
[401012] = {401012, 10010, 13, 7, "0", "0", "想看更華麗的演出嗎？", "もっと煌びやかにしてもいいんじゃない？", "0", "0", "想看更華麗的演出嗎？", "0", "cv_alaita_10", "0", "0"},
[401013] = {401013, 10010, 14, 8, "0", "0", "呵呵……你能感受到嗎，這把劍正在發出喜悅的鳴聲呢。不，並不是在稱讚我的美麗。它一定是因為能夠再一次保護多瑙，保護薩爾而高興吧。", "ふふ……この剣の喜びが聞こえるかしら？私の美しさはもとより、再びダニューブやサールを守ることができる喜びに違いないわ。", "0", "0", "呵呵……你能感受到嗎，這把劍正在發出喜悅的鳴聲呢。不，並不是在稱讚我的美麗。它一定是因為能夠再一次保護多瑙，保護薩爾而高興吧。", "0", "cv_alaita_11", "0", "0"},
[401014] = {401014, 10010, 15, 9, "0", "0", "讓我變得更加美麗吧。", "もっと美しくしてちょうだい。", "0", "0", "讓我變得更加美麗吧。", "0", "cv_alaita_12", "0", "0"},
[401015] = {401015, 10010, 16, 10, "0", "0", "我負責表演，你負責喝彩！", "私は舞臺に。あなたは喝采を！", "0", "0", "我負責表演，你負責喝彩！", "0", "cv_alaita_13", "0", "0"},
[401016] = {401016, 10010, 17, 11, "0", "0", "誇讚我吧，稱讚我吧，然後迷戀上我吧。", "讃えよ、讃えよ。そして私の虜になるのよ。", "0", "0", "誇讚我吧，稱讚我吧，然後迷戀上我吧。", "0", "cv_alaita_14", "0", "0"},
[401017] = {401017, 10010, 18, 12, "0", "0", "馬馬虎虎…領航，別發呆了，回去了。", "まあまあね。……ナビゲーター、ボーッとしてないで帰るわよ。", "0", "0", "馬馬虎虎…領航，別發呆了，回去了。", "0", "cv_alaita_15", "0", "0"},
[401018] = {401018, 10010, 19, 13, "0", "0", "…嗯，這也算是完成工作了吧？", "……まあ、とりあえず良しとするわ。", "0", "0", "…嗯，這也算是完成工作了吧？", "0", "cv_alaita_16", "0", "0"},
[401019] = {401019, 10010, 20, 14, "0", "0", "嗯…真是一場失敗的演出，你不這樣認為嗎？", "うーん……出來の悪い舞臺ね。そう思わない？", "0", "0", "嗯…真是一場失敗的演出，你不這樣認為嗎？", "0", "cv_alaita_17", "0", "0"},
[401020] = {401020, 10010, 21, 15, "0", "0", "你該退場了。", "退場して。", "0", "0", "你該退場了。", "0", "cv_alaita_18", "0", "0"},
[401021] = {401021, 10010, 23, 16, "0", "0", "到我了！", "私の番よ！", "0", "0", "到我了！", "0", "cv_alaita_19", "0", "0"},
[401022] = {401022, 10010, 24, 17, "0", "0", "陶醉吧！", "酔いしれるがいいわ！", "0", "0", "陶醉吧！", "0", "cv_alaita_21", "0", "0"},
[401023] = {401023, 10010, 26, 19, "0", "0", "這是…謝幕嗎……", "これで…終幕……", "0", "0", "這是…謝幕嗎……", "0", "cv_alaita_20", "0", "0"},
[401024] = {401024, 10010, 27, 20, "0", "0", "喔？你來了啊。", "あら、來たの？", "0", "0", "噢？你來了啊。", "0", "cv_alaita_22", "0", "0"},
[401025] = {401025, 10010, 28, 21, "0", "0", "看入迷了嗎？不用害羞，稱讚我的美麗吧。", "見とれてるの？遠慮しないで、私の美しさを存分に讃えてちょうだい。", "0", "0", "看入迷了嗎？不用害羞，稱讚我的美麗吧。", "0", "cv_alaita_23", "0", "0"},
[401026] = {401026, 10010, 29, 21, "0", "0", "情不自禁想哼歌呢…你準備了蠟來封耳朵嗎？", "なんだか歌いたくなる気分よ。……あなた、耳栓は持ってるかしら？", "0", "0", "情不自禁想哼歌呢…你準備了蠟來封耳朵嗎？", "0", "cv_alaita_24", "0", "0"},
[401027] = {401027, 10010, 30, 22, "0", "0", "呵…提高警惕，對嗎？", "ふぅん……警戒すればいいのね？", "0", "0", "呵…提高警惕，對嗎？", "0", "cv_alaita_25", "0", "0"},
[401028] = {401028, 10010, 31, 23, "0", "0", "這點幕布是遮擋不了我的星光的，對吧？", "こんなもので私の美しさは隠せないわ。でしょ？", "0", "0", "這點幕布是遮擋不了我的星光的，對吧？", "0", "cv_alaita_26", "0", "0"},
[401029] = {401029, 10010, 32, 24, "0", "0", "不愧是領航~遺憾的是，沒有獎勵喔。", "悪くないわ。でもご褒美はないの。殘念ね。", "0", "0", "不愧是領航~遺憾的是，沒有獎勵噢。", "0", "cv_alaita_27", "0", "0"},
[401030] = {401030, 10010, 33, 25, "0", "0", "下次再努力吧。", "次は頑張って…", "0", "0", "下次再努力吧。", "0", "cv_alaita_28", "0", "0"},
[401031] = {401031, 10010, 34, 26, "0", "0", "早上好，領航，這是為您準備的玫瑰茶，還請慢用。", "おはよう、ナビゲーター。あなたのためにローズティーを淹れてあげたわ。どうぞ。", "0", "0", "早上好，領航，這是為您準備的玫瑰茶，還請慢用。", "0", "cv_alaita_31", "0", "0"},
[401032] = {401032, 10010, 35, 27, "0", "0", "要執行任務了？我明白了，出發吧。", "ミッション？いいわよ。出発するわ。", "0", "0", "要執行任務了？我明白了，出發吧。", "0", "cv_alaita_33", "0", "0"},
[401033] = {401033, 10010, 36, 28, "0", "0", "早點完成，早點休息~", "さっさと終わらせて、お茶にしましょ。", "0", "0", "早點完成，早點休息~", "0", "cv_alaita_34", "0", "0"},
[401034] = {401034, 10010, 37, 29, "0", "0", "嗨，大家好~！", "皆さん、どうぞよろしく。", "0", "0", "嗨，大家好~！", "0", "cv_alaita_35", "0", "0"},
[401035] = {401035, 10010, 38, 30, "0", "0", "要增加新的同伴嗎？", "新しい仲間を増やすのかしら？", "0", "0", "要增加新的同伴嗎？", "0", "cv_alaita_36", "0", "0"},
[401036] = {401036, 10010, 39, 31, "0", "0", "要採購新裝備了嗎？", "新しい裝備を増やすのかしら？", "0", "0", "要採購新裝備了嗎？", "0", "cv_alaita_37", "0", "0"},
[401037] = {401037, 10010, 40, 32, "0", "0", "需要零花錢嗎？", "お小遣いが欲しいの？", "0", "0", "需要零花錢嗎？", "0", "cv_alaita_38", "0", "0"},
[401038] = {401038, 10010, 41, 33, "0", "0", "笑一下？", "笑顔になって。", "0", "0", "笑一下？", "0", "cv_alaita_39", "0", "0"},
[401039] = {401039, 10010, 42, 34, "0", "0", "隨便吧。", "好きにして。", "0", "0", "隨便吧。", "0", "cv_alaita_40", "0", "0"},
[401040] = {401040, 10010, 43, 35, "0", "0", "有邀請函嗎？", "招待狀はあるかしら？", "0", "0", "有邀請函嗎？", "0", "cv_alaita_41", "0", "0"},
[401041] = {401041, 10010, 44, 36, "0", "0", "遇到喜歡的人記得要聯繫方式喔。", "気に入った人とは連絡先の交換を忘れずにね。", "0", "0", "遇到喜歡的人記得要聯繫方式哦。", "0", "cv_alaita_42", "0", "0"},
[401042] = {401042, 10010, 45, 37, "0", "0", "吼~", "ふーん。", "0", "0", "謔~", "0", "cv_alaita_43", "0", "0"},
[401100] = {401100, 10011, 1, 1, "0", "0", "蒼霧殘響。", "蒼霧殘響（ハツリバーブ）。", "0", "0", "蒼霧殘響。", "0", "cv_ruoshui_32", "0", "0"},
[401101] = {401101, 10011, 2, 2, "0", "0", "是，我會一直站在這等待您下一個命令的，領航哥哥。", "はい、次の命令までここで待ってますね。ナビゲーターのお兄さん。", "0", "0", "是，我會一直站在這等待您下一個命令的，領航哥哥。", "0", "cv_ruoshui_2", "0", "0"},
[401102] = {401102, 10011, 3, 3, "0", "0", "我的名字是弱水…眼睛？沒關係，我能看見您的，領航哥哥。", "私の名前は弱水です。……私の目ですか？大丈夫です。ちゃんと見えてますよ、ナビゲーターのお兄さん。", "0", "0", "我的名字是弱水…眼睛？沒關係，我能看見您的，領航哥哥。", "0", "cv_ruoshui_1", "0", "0"},
[401103] = {401103, 10011, 4, 4, "0", "idle", "我的眼睛…雖然看得見，但是好像和大家看到的“世界”不一樣…不過這也是沒辦法的事吧？", "見えてはいるのですが、皆さんが見ている世界とは違うのだそうです。……まあ、それも仕方ないですね。", "0", "0", "我的眼睛…雖然看得見，但是好像和大家看到的“世界”不一樣…不過這也是沒辦法的事吧？", "0", "cv_ruoshui_3", "0", "0"},
[401104] = {401104, 10011, 5, 4, "0", "idle", "領航哥哥，昨天的電視劇你看了嗎？那部電視劇雖然各種地方都很爛，但他們想要拍好一部作品的決心卻讓我超感動的！欸？沒看嗎？", "ナビゲーターのお兄さん、昨日のテレビドラマは見ましたか？色々な意味で最悪なドラマでしたが、良い作品を作ろうという姿勢にすごく感動したんです！えぇ？見てないんですか！？", "0", "0", "領航哥哥，昨天的電視劇你看了嗎？那部電視劇雖然各種地方都很爛，但他們想要拍好一部作品的決心卻讓我超感動的！誒？沒看嗎？", "0", "cv_ruoshui_4", "0", "0"},
[401105] = {401105, 10011, 6, 4, "0", "idle", "冥火！冥火！嗯？她不在這裡嗎…欸，她只要沒有任務的時候，感覺就跟消失了一樣，真神秘呢…我還想找她玩呢！", "冥火ー？冥火ー？あれ？いない……任務がないとすぐいなくなっちゃうんだから。……一緒に遊ぼうって思ってたのに！", "0", "0", "冥火！冥火！嗯？她不在這裡嗎…誒，她只要沒有任務的時候，感覺就跟消失了一樣，真神秘呢…我還想找她玩呢！", "0", "cv_ruoshui_29", "0", "0"},
[401106] = {401106, 10011, 7, 5, "1_》_0_0.8", "level1", "以前…因為一些原因，我失去了視力，也因此失去了自己的朋友和家人…不過，一切都過去了，現在的我，只想盡自己所能地幫助大家！", "ここに來る前に……視力も、友達も、家族も失いました。……でも、それはもう過ぎたことです。今はただ、出來る限りみんなの助けになりたいんです！", "0", "0", "以前…因為一些原因，我失去了視力，也因此失去了自己的朋友和家人…不過，一切都過去了，現在的我，只想盡自己所能地幫助大家！", "0", "cv_ruoshui_30", "0", "0"},
[401107] = {401107, 10011, 8, 5, "1_》_0_0.8", "level1", "領航哥哥，眼罩…您別亂碰它呀！", "ちょっと、眼帯に…勝手に觸らないでください！", "0", "0", "領航哥哥，眼罩…您別亂碰它呀！", "0", "cv_ruoshui_5", "0", "0"},
[401108] = {401108, 10011, 9, 5, "1_》_100_1.5", "level2", "哥哥，哥哥，我們一起出去玩吧，我想去遊樂場玩！", "お兄さんお兄さん、一緒に出かけましょう。遊園地がいいです！", "0", "0", "哥哥，哥哥，我們一起出去玩吧，我想去遊樂場玩！", "0", "cv_ruoshui_6", "0", "0"},
[401109] = {401109, 10011, 10, 5, "1_》_500_2", "level3", "哥哥，我們一起去看電影吧，首先要做的是去買飲料、爆米花…欸，像約會一樣？……約、約會的話，也不是不行啦。", "お兄さん、一緒に映畫を見に行きましょう。まず飲み物とポップコーンを買って……え、デートみたい？……デ、デートはダメ……じゃないですけど……", "0", "0", "哥哥，我們一起去看電影吧，首先要做的是去買飲料、爆米花…誒，像約會一樣？……約、約會的話，也不是不行啦。", "0", "cv_ruoshui_7", "0", "0"},
[401110] = {401110, 10011, 11, 5, "1_》_1000_2.5", "level4", "是領航您的話，我不用擔心被背叛，也不用擔心你會突然消失吧…這樣就足夠了。領航，之後也請您一直陪著我吧，我…不想和您分開。", "お兄さんがナビゲーターなら、私を裏切ったり、ある日突然消えちゃうこともないですよね。……それで十分です。これからもずっと私のそばに居てください。私……お兄さんと離れるのは嫌なんです。", "0", "0", "是領航您的話，我不用擔心被背叛，也不用擔心你會突然消失吧…這樣就足夠了。領航，之後也請您一直陪著我吧，我…不想和您分開。", "0", "cv_ruoshui_8", "0", "0"},
[401111] = {401111, 10011, 12, 6, "0", "0", "我升級了欸！", "レベルアップしましたよ！", "0", "0", "我升級了誒！", "0", "cv_ruoshui_9", "0", "0"},
[401112] = {401112, 10011, 13, 7, "0", "0", "武器變鋒利了！", "武器が鋭くなりました！", "0", "0", "武器變鋒利了！", "0", "cv_ruoshui_10", "0", "0"},
[401113] = {401113, 10011, 14, 8, "0", "0", "真是不可思議呢…力量在源源不斷地湧出。嗯，決定了，這份力量，這份強大，只為領航您而存在。今後，不管是什麼樣的敵人，“弱水”都會為了您，將他擊潰！", "不思議……力がどんどん湧いてきます。うん、決めました。この力、この強さはお兄さんだけのものです。これからどんな敵が現れようとも、お兄さんのために弱水が倒して見せます！", "0", "0", "真是不可思議呢…力量在源源不斷地湧出。嗯，決定了，這份力量，這份強大，只為領航您而存在。今後，不管是什麼樣的敵人，“弱水”都會為了您，將他擊潰！", "0", "cv_ruoshui_11", "0", "0"},
[401114] = {401114, 10011, 15, 9, "0", "0", "速度變快了！", "もっと速くなりました！", "0", "0", "速度變快了！", "0", "cv_ruoshui_12", "0", "0"},
[401115] = {401115, 10011, 16, 10, "0", "0", "瞭解，作戰開始。", "瞭解、作戦開始。", "0", "0", "瞭解，作戰開始。", "0", "cv_ruoshui_13", "0", "0"},
[401116] = {401116, 10011, 17, 11, "0", "0", "任務完成——領航，我們回去吧。", "任務完了。……帰りましょう、お兄さん。", "0", "0", "任務完成——領航，我們回去吧。", "0", "cv_ruoshui_14", "0", "0"},
[401117] = {401117, 10011, 18, 12, "0", "0", "我沒事…但是有傷員需要治療，領航。", "大丈夫です……私より、負傷者の方を……お兄さん……", "0", "0", "我沒事…但是有傷患需要治療，領航。", "0", "cv_ruoshui_15", "0", "0"},
[401118] = {401118, 10011, 19, 13, "0", "0", "大家…還好嗎？", "みなさん…無事ですか？", "0", "0", "大家…還好嗎？", "0", "cv_ruoshui_16", "0", "0"},
[401119] = {401119, 10011, 20, 14, "0", "0", "不能就這樣放棄，領航……", "お兄さん、諦めてはいけません……", "0", "0", "不能就這樣放棄，領航……", "0", "cv_ruoshui_17", "0", "0"},
[401120] = {401120, 10011, 21, 15, "0", "0", "已擊殺。", "撃破。", "0", "0", "已擊殺。", "0", "cv_ruoshui_18", "0", "0"},
