[401125] = {401125, 10011, 28, 21, "0", "0", "哥哥！水裡面有一條白色的大鯊魚——開玩笑的~", "お兄さん、お風呂の中に人食いザメが！……冗談ですよー。", "0", "0", "哥哥！水裡面有一條白色的大鯊魚——開玩笑的~", "0", "cv_ruoshui_23", "0", "0"},
[401126] = {401126, 10011, 29, 21, "0", "0", "哥哥，能幫我拿一聽碳酸飲料過來嗎~謝謝~", "お兄さん、サイダーを取ってきてくれませんか？……ありがとうございます！", "0", "0", "哥哥，能幫我拿一聽碳酸飲料過來嗎~謝謝~", "0", "cv_ruoshui_24", "0", "0"},
[401127] = {401127, 10011, 30, 22, "0", "0", "是敵人嗎！？", "敵ですか！？", "0", "0", "是敵人嗎！？", "0", "cv_ruoshui_25", "0", "0"},
