[401129] = {401129, 10011, 32, 24, "0", "0", "好耶！哥哥是最棒的！", "やったあ！お兄さん最高です！", "0", "0", "好耶！哥哥是最棒的！", "0", "cv_ruoshui_27", "0", "0"},
