[401131] = {401131, 10011, 34, 26, "0", "0", "領航，歡迎回來，在你不在的時候，我也有好好努力喔！", "ナビゲーターのお兄さん、おかえりなさい。お兄さんがいない間もちゃんと頑張りましたよ！", "0", "0", "領航，歡迎回來，在你不在的時候，我也有好好努力哦！", "0", "cv_ruoshui_31", "0", "0"},
[401132] = {401132, 10011, 35, 27, "0", "0", "要開始任務了嗎——瞭解。", "任務ですか？……瞭解。", "0", "0", "要開始任務了嗎——瞭解。", "0", "cv_ruoshui_33", "0", "0"},
