[401141] = {401141, 10011, 44, 36, "0", "0", "好多人啊……", "人が…いっぱい……", "0", "0", "好多人啊……", "0", "cv_ruoshui_42", "0", "0"},
[401142] = {401142, 10011, 45, 37, "0", "0", "噗噠！", "ポチ！", "0", "0", "噗噠！", "0", "cv_ruoshui_43", "0", "0"},
[401200] = {401200, 10012, 1, 1, "0", "0", "蒼霧殘響。", "蒼霧殘響（ハツリバーブ）。", "0", "0", "蒼霧殘響。", "0", "cv_guroria_32", "0", "0"},
[401201] = {401201, 10012, 2, 2, "0", "0", "我會站在這，注視著您工作的……無聊？不，您無須在意我的感受。", "ここで貴方を見守りますね。……退屈じゃないか？いえ、私のことはお気になさらず。", "0", "0", "我會站在這，注視著您工作的……無聊？不，您無須在意我的感受。", "0", "cv_guroria_2", "0", "0"},
[401202] = {401202, 10012, 3, 3, "0", "0", "您好，我是第三研究室防衛班的新成員，格洛麗亞。從今天開始，您便是我的領航了。", "はじめまして。第三研究室防衛班の新メンバーで、グロリアと申します。本日から、貴方が私のナビゲーターです。", "0", "0", "您好，我是第三研究室防衛班的新成員，格洛麗亞。從今天開始，您便是我的領航了。", "0", "cv_guroria_1", "0", "0"},
[401203] = {401203, 10012, 4, 4, "0", "idle", "領航先生，我有一個疑惑…艾吉斯的規章制度，只有那一點嗎？是嗎…這樣啊。嗯，真好啊。", "ナビゲーターさん、少しお聞きしたいのですが……アイギスの規則はこれだけでしょうか？そう…ですか。なるほど。いいですね。", "0", "0", "領航先生，我有一個疑惑…艾吉斯的規章制度，只有那一點嗎？是嗎…這樣啊。嗯，真好啊。", "0", "cv_guroria_3", "0", "0"},
[401204] = {401204, 10012, 5, 4, "0", "idle", "領航先生，您今天的工作還沒有結束嗎？是嗎，請加油。", "ナビゲーターさん、まだ今日の仕事が終わっていないのですか？……そうですか。頑張ってください。", "0", "0", "領航先生，您今天的工作還沒有結束嗎？是嗎，請加油。", "0", "cv_guroria_4", "0", "0"},
[401205] = {401205, 10012, 6, 4, "0", "idle", "多洛莉絲學姐？啊…她是一個好人，和她相處久了能學到不少東西。您也是這麼認為的吧，領航先生。", "ドロリィス先輩ですか？ええ、素晴らしいお方です。一緒にいれば、きっと沢山の學びが得られることでしょう。ナビゲーターさんもそう思ってらっしゃるのでは？", "0", "0", "多洛莉絲學姐？啊…她是一個好人，和她相處久了能學到不少東西。您也是這麼認為的吧，領航先生。", "0", "cv_guroria_29", "0", "0"},
[401206] = {401206, 10012, 7, 5, "1_》_0_0.8", "level1", "艾吉斯…對我而言，是一次新的開始。我想試著…開始新的生活。…領航先生，請不要在意，我只是在自言自語。", "アイギス……私の新たなスタート……新しい生活を、始められる……あ。ナビゲーターさん、お気になさらないでください。ただの獨り言ですから。", "0", "0", "艾吉斯…對我而言，是一次新的開始。我想試著…開始新的生活。…領航先生，請不要在意，我只是在自言自語。", "0", "cv_guroria_30", "0", "0"},
[401207] = {401207, 10012, 8, 5, "1_》_0_0.8", "level1", "嗯？請問，有什麼事嗎？", "はい？あの……どうしたのですか？", "0", "0", "嗯？請問，有什麼事嗎？", "0", "cv_guroria_5", "0", "0"},
[401208] = {401208, 10012, 9, 5, "1_》_100_1.5", "level2", "領航先生…您如果有空的話，工作結束後能和我聊聊嗎？我有很多想對您說的話，不過，如果給您添麻煩了，就算了。", "ナビゲーターさん……お仕事の後に少しお時間よろしいですか？もしご迷惑でないなら、お話ししたいことが沢山あるのです。", "0", "0", "領航先生…您如果有空的話，工作結束後能和我聊聊嗎？我有很多想對您說的話，不過，如果給您添麻煩了，就算了。", "0", "cv_guroria_6", "0", "0"},
[401209] = {401209, 10012, 10, 5, "1_》_500_2", "level3", "領航先生，待在您身邊…有一種輕鬆感，就像是，把什麼沉重的東西卸下來了一樣。您或許能成為我…唯一的“理解者”。", "ナビゲーターさん、貴方のそばにいると……心の中にある大きな重いものがすっと消えるような、軽やかな気持ちになるのです。もしかすると、貴方は私の……唯一の理解者になってくださるのでしょうか……？", "0", "0", "領航先生，待在您身邊…有一種輕鬆感，就像是，把什麼沉重的東西卸下來了一樣。您或許能成為我…唯一的“理解者”。", "0", "cv_guroria_7", "0", "0"},
[401210] = {401210, 10012, 11, 5, "1_》_1000_2.5", "level4", "領航先生…不，我的“理解者”，你就是我一直在尋找著的，唯一一個想要瞭解我，能夠理解我的，只屬於我的“理解者”。", "ナビゲーターさん……いえ、私の理解者である貴方こそ、私が探し続けたただ一人の人。私を理解しようと思ってくださる、そして理解してくださる人。私だけの……理解者。", "0", "0", "領航先生…不，我的“理解者”，你就是我一直在尋找著的，唯一一個想要瞭解我，能夠理解我的，只屬於我的“理解者”。", "0", "cv_guroria_8", "0", "0"},
[401211] = {401211, 10012, 12, 6, "0", "0", "升級？喔，謝謝。", "レベルアップですか？ありがとうございます。", "0", "0", "升級？哦，謝謝。", "0", "cv_guroria_9", "0", "0"},
[401212] = {401212, 10012, 13, 7, "0", "0", "階級提升，謝謝。", "ランクアップ、ありがとうございます。", "0", "0", "階級提升，謝謝。", "0", "cv_guroria_10", "0", "0"},
[401213] = {401213, 10012, 14, 8, "0", "0", "領航先生…一直以來，我十分感謝您對我的幫助…可，這些並不是我所希望的。領航先生…能，離我更近一些嗎？", "ナビゲーターさん…いつも私に良くしてくださって、ありがとうございます。……ですが、私の本當の望みは、違うのです。ナビゲーターさん……もっと近くに來ていただけますか？", "0", "0", "領航先生…一直以來，我十分感謝您對我的幫助…可，這些並不是我所希望的。領航先生…能，離我更近一些嗎？", "0", "cv_guroria_11", "0", "0"},
[401214] = {401214, 10012, 15, 9, "0", "0", "謝謝您，領航先生。", "ありがとうございます、ナビゲーターさん。", "0", "0", "謝謝您，領航先生。", "0", "cv_guroria_12", "0", "0"},
[401215] = {401215, 10012, 16, 10, "0", "0", "到此為止吧。", "終わらせます。", "0", "0", "到此為止吧。", "0", "cv_guroria_13", "0", "0"},
[401216] = {401216, 10012, 17, 11, "0", "0", "勝利了嗎，嗯，那就好，多虧大家了。", "勝利ですか。良かった。皆さんのお陰です。", "0", "0", "勝利了嗎，嗯，那就好，多虧大家了。", "0", "cv_guroria_14", "0", "0"},
[401217] = {401217, 10012, 18, 12, "0", "0", "給您添麻煩了。", "ご迷惑をおかけしました。", "0", "0", "給您添麻煩了。", "0", "cv_guroria_15", "0", "0"},
[401218] = {401218, 10012, 19, 13, "0", "0", "抱歉，我應該做得更好的。", "すみません、もう少しうまくできれば……", "0", "0", "抱歉，我應該做得更好的。", "0", "cv_guroria_16", "0", "0"},
[401219] = {401219, 10012, 20, 14, "0", "0", "先撤退吧。", "ここは撤退しましょう…！", "0", "0", "先撤退吧。", "0", "cv_guroria_17", "0", "0"},
[401220] = {401220, 10012, 21, 15, "0", "0", "不堪一擊呢。", "私の敵ではありません。", "0", "0", "不堪一擊呢。", "0", "cv_guroria_18", "0", "0"},
[401221] = {401221, 10012, 23, 16, "0", "0", "劈開你！", "切り裂く！", "0", "0", "劈開你！", "0", "cv_guroria_19", "0", "0"},
[401222] = {401222, 10012, 24, 17, "0", "0", "嘿呀！", "せやぁっ！", "0", "0", "嘿呀！", "0", "cv_guroria_21", "0", "0"},
[401223] = {401223, 10012, 26, 19, "0", "0", "看來只能到此為止……", "ここまでのようですね……", "0", "0", "看來只能到此為止……", "0", "cv_guroria_20", "0", "0"},
[401224] = {401224, 10012, 27, 20, "0", "0", "您也要一起過來嗎？是嗎…那按您喜歡的來吧。", "貴方もご一緒にいかがですか？ええ…どうぞお好きなように。", "0", "0", "您也要一起過來嗎？是嗎…那按您喜歡的來吧。", "0", "cv_guroria_22", "0", "0"},
[401225] = {401225, 10012, 28, 21, "0", "0", "領航先生，您累了的話，就別勉強了。", "ナビゲーターさん、お疲れでしょうか？どうかご無理をなさらないでください。", "0", "0", "領航先生，您累了的話，就別勉強了。", "0", "cv_guroria_23", "0", "0"},
[401226] = {401226, 10012, 29, 21, "0", "0", "領航先生，辛苦您了。剩下的讓我自己來…不行嗎？…我明白了。", "ナビゲーターさん、お疲れさまでした。あとは私が……ダメですか？…承知しました。", "0", "0", "領航先生，辛苦您了。剩下的讓我自己來…不行嗎？…我明白了。", "0", "cv_guroria_24", "0", "0"},
[401227] = {401227, 10012, 30, 22, "0", "0", "喔…是事件。", "おや…事件ですね。", "0", "0", "哦…是事件。", "0", "cv_guroria_25", "0", "0"},
[401228] = {401228, 10012, 31, 23, "0", "0", "請您隨意。", "お気に召すまま、どうぞ。", "0", "0", "請您隨意。", "0", "cv_guroria_26", "0", "0"},
[401229] = {401229, 10012, 32, 24, "0", "0", "恭喜您。", "おめでとうございます。", "0", "0", "恭喜您。", "0", "cv_guroria_27", "0", "0"},
[401230] = {401230, 10012, 33, 25, "0", "0", "辛苦了。", "お疲れさまでした。", "0", "0", "辛苦了。", "0", "cv_guroria_28", "0", "0"},
[401231] = {401231, 10012, 34, 26, "0", "0", "您好，領航先生。今天也要工作嗎？真是辛苦呢。", "おはようございます、ナビゲーターさん。今日もお仕事ですか？お疲れ様です。", "0", "0", "您好，領航先生。今天也要工作嗎？真是辛苦呢。", "0", "cv_guroria_31", "0", "0"},
[401232] = {401232, 10012, 35, 27, "0", "0", "領航先生，出發吧，我沒有需要準備的東西。", "ナビゲーターさん、行きましょう。私に準備は不要です。", "0", "0", "領航先生，出發吧，我沒有需要準備的東西。", "0", "cv_guroria_33", "0", "0"},
[401233] = {401233, 10012, 36, 28, "0", "0", "我們走吧，領航先生。", "參りましょう、ナビゲーターさん。", "0", "0", "我們走吧，領航先生。", "0", "cv_guroria_34", "0", "0"},
[401234] = {401234, 10012, 37, 29, "0", "0", "午安，各位。", "こんにちは、皆さん。", "0", "0", "午安，各位。", "0", "cv_guroria_35", "0", "0"},
[401235] = {401235, 10012, 38, 30, "0", "0", "領航先生，您是要面試嗎？", "ナビゲーターさん、面接をしますか？", "0", "0", "領航先生，您是要面試嗎？", "0", "cv_guroria_36", "0", "0"},
[401236] = {401236, 10012, 39, 31, "0", "0", "裝備…要換新的嗎？", "新しい裝備が必要ですか？", "0", "0", "裝備…要換新的嗎？", "0", "cv_guroria_37", "0", "0"},
[401237] = {401237, 10012, 40, 32, "0", "0", "想買什麼？", "何を購入しましょうか。", "0", "0", "想買什麼？", "0", "cv_guroria_38", "0", "0"},
[401238] = {401238, 10012, 41, 33, "0", "0", "請記得洗漱。", "身だしなみを整えるのをお忘れなく。", "0", "0", "請記得洗漱。", "0", "cv_guroria_39", "0", "0"},
[401239] = {401239, 10012, 42, 34, "0", "0", "請小心設定。", "慎重に設定してください。", "0", "0", "請小心設置。", "0", "cv_guroria_40", "0", "0"},
