[401241] = {401241, 10012, 44, 36, "0", "0", "很熱鬧呢。", "賑やかですね。", "0", "0", "很熱鬧呢。", "0", "cv_guroria_42", "0", "0"},
[401242] = {401242, 10012, 45, 37, "0", "0", "嗯？", "はい？", "0", "0", "嗯？", "0", "cv_guroria_43", "0", "0"},
[401300] = {401300, 10013, 1, 1, "0", "0", "蒼霧殘響。", "蒼霧殘響（ハツリバーブ）。", "0", "0", "蒼霧殘響。", "0", "cv_lilith_31", "0", "0"},
[401301] = {401301, 10013, 2, 2, "0", "0", "為什麼要這麼在意我？", "何故そんなに私のことが気になるの？", "0", "0", "為什麼要這麼在意我？", "0", "cv_lilith_2", "0", "0"},
[401302] = {401302, 10013, 3, 3, "0", "0", "啊，熟悉的味道啊。你就是那個真正的通感者吧。話先說在前面，我討厭所有的通感者，當然也包括我自己。", "ああ、懐かしい匂い…...あなたが真の通感覚者なのね。先に言っておくけど、私、通感覚者のことが嫌いなの。もちろん、私自身も含めて。", "0", "0", "啊，熟悉的味道啊。你就是那個真正的通感者吧。話先說在前面，我討厭所有的通感者，當然也包括我自己。", "0", "cv_lilith_1", "0", "0"},
[401303] = {401303, 10013, 4, 4, "0", "idle", "身為真正的通感者，你應該也能聽得到吧？大家的恐懼，憎恨以及……絕望。", "真の通感覚者のあなたなら、聞こえるんじゃない？みんなの恐怖、憎悪、そして……絶望。", "0", "0", "身為真正的通感者，你應該也能聽得到吧？大家的恐懼，憎恨以及……絕望。", "0", "cv_lilith_3", "0", "0"},
[401304] = {401304, 10013, 5, 4, "0", "idle", "在這裡浪費時間毫無意義，既然我是你的屬下，就趕快給我佈置任務吧。", "ここで時間を費やしても意味がない。ここでは私はあなたの部下なのだから、早く指示を出してちょうだい。", "0", "0", "在這裡浪費時間毫無意義，既然我是你的屬下，就趕快給我佈置任務吧。", "0", "cv_lilith_4", "0", "0"},
[401305] = {401305, 10013, 6, 4, "0", "idle", "藍莓蛋糕……斯卡蒂，你又偷偷吃了我的藍莓蛋糕了吧？不要再裝了，你心裡想的我全都知道了。", "スカディ、また私のブルーベリーケーキをこっそりつまみ食いしたでしょ？知らないふりをしたって無駄よ。何を考えてるのか、私には分かる。", "0", "0", "藍莓蛋糕……斯卡蒂，你又偷偷吃了我的藍莓蛋糕了吧？不要再裝了，你心裡想的我全都知道了。", "0", "cv_lilith_28", "0", "0"},
[401306] = {401306, 10013, 7, 5, "1_》_0_0.8", "level1", "怎麼了？我喜歡吃甜食很奇怪嗎？", "どうしたの？私がスイーツ好きなのが、そんなに驚くこと？", "0", "0", "怎麼了？我喜歡吃甜食很奇怪嗎？", "0", "cv_lilith_29", "0", "0"},
[401307] = {401307, 10013, 8, 5, "1_》_0_0.8", "level1", "如果可以的話，將我當作是工具就好了。", "私を道具として使っていいよ。", "0", "0", "如果可以的話，將我當作是工具就好了。", "0", "cv_lilith_5", "0", "0"},
[401308] = {401308, 10013, 9, 5, "1_》_100_1.5", "level2", "既然你也能接受到他人的負面情感的話，那麼我們姑且也能算作是通感者中的同類了吧。", "もし、あなたも他人の負の感情を感じられると言うのなら、私たちは、通感覚者の中でも同類であると言えるね。", "0", "0", "既然你也能接受到他人的負面情感的話，那麼我們姑且也能算作是通感者中的同類了吧。", "0", "cv_lilith_6", "0", "0"},
[401309] = {401309, 10013, 10, 5, "1_》_500_2", "level3", "一直以來都很辛苦吧，雖然不清楚為什麼你對此還是一副無所謂的態度。但是我很清楚，你的痛楚，你的自責……", "辛いでしょ？あなたが何故そのようにどうでもいいみたいな態度をとってるのかは知らないけど。でも、私は知ってる。あなたの苦しみと自責の念……", "0", "0", "一直以來都很辛苦吧，雖然不清楚為什麼你對此還是一副無所謂的態度。但是我很清楚，你的痛楚，你的自責……", "0", "cv_lilith_7", "0", "0"},
[401310] = {401310, 10013, 11, 5, "1_》_1000_2.5", "level4", "是同伴而不是同類嗎……隨便你怎麼說吧，我只是你的工具而已。不過在戰鬥的時候還請不要再對我使用通感了，我可不希望你的痛苦翻倍。", "同類じゃなくて仲間、か……勝手にすれば。私はただの道具だわ。あなたの道具。でも、戦ってる時は私に対して通感覚をしないで。あなたの苦しみを増やしたくないから。", "0", "0", "是同伴而不是同類嗎……隨便你怎麼說吧，我只是你的工具而已。不過在戰鬥的時候還請不要再對我使用通感了，我可不希望你的痛苦翻倍。", "0", "cv_lilith_8", "0", "0"},
[401311] = {401311, 10013, 12, 6, "0", "0", "沒錯，就這樣繼續下去吧。", "そう、こうやって続けて。", "0", "0", "沒錯，就這樣繼續下去吧。", "0", "cv_lilith_9", "0", "0"},
[401312] = {401312, 10013, 13, 7, "0", "0", "很好……這麼一來我的病就能痊癒了吧……", "良いわね…...これなら私の病もきっと治るわ……", "0", "0", "很好……這麼一來我的病就能痊癒了吧……", "0", "cv_lilith_10", "0", "0"},
[401313] = {401313, 10013, 14, 8, "0", "0", "果然，無論怎麼樣都無法擺脫通感者的身份嗎……只是，那些讓人討厭的聲音好像變得柔和了……我好像能聽到其他的聲音了。孩子們的祝福，感謝以及……祈禱的歌聲。", "やっぱり、何をやっても通感覚者という身分から逃れられないのね……でも、最近あの嫌な聲が柔らかくなった気がする……私、他の聲が聞こえるようになったみたいだわ。子供たちの祝福、感謝、そして……祈りの歌聲。", "0", "0", "果然，無論怎麼樣都無法擺脫通感者的身份嗎……只是，那些讓人討厭的聲音好像變得柔和了……我好像能聽到其他的聲音了。孩子們的祝福，感謝以及……祈禱的歌聲。", "0", "cv_lilith_11", "0", "0"},
[401314] = {401314, 10013, 15, 9, "0", "0", "電流量提升了呢。", "電流の量が上がったわ。", "0", "0", "電流量提升了呢。", "0", "cv_lilith_12", "0", "0"},
[401315] = {401315, 10013, 16, 10, "0", "0", "真討厭啊。", "嫌だわ。", "0", "0", "真討厭啊。", "0", "cv_lilith_13", "0", "0"},
[401316] = {401316, 10013, 17, 11, "0", "0", "不用急著感謝我。", "感謝など、要らないわ。", "0", "0", "不用急著感謝我。", "0", "cv_lilith_14", "0", "0"},
[401317] = {401317, 10013, 18, 12, "0", "0", "都和你說過了，沒問題的。", "だから言ったでしょ？大丈夫だって。", "0", "0", "都和你說過了，沒問題的。", "0", "cv_lilith_15", "0", "0"},
[401318] = {401318, 10013, 19, 13, "0", "0", "嗯，怎麼說呢，有驚無險吧。", "…うん、なんていうか、ギリギリだったのね。", "0", "0", "嗯，怎麼說呢，有驚無險吧。", "0", "cv_lilith_16", "0", "0"},
[401319] = {401319, 10013, 20, 14, "0", "0", "啊……那些討厭的聲音…又出現了嗎。", "ああ……例の嫌な聲がまた……", "0", "0", "啊……那些討厭的聲音…又出現了嗎。", "0", "cv_lilith_17", "0", "0"},
[401320] = {401320, 10013, 21, 15, "0", "0", "怨恨我吧。", "私を恨みなさい。", "0", "0", "怨恨我吧。", "0", "cv_lilith_18", "0", "0"},
[401321] = {401321, 10013, 23, 16, "0", "0", "殺了你。", "あなたを、殺す。", "0", "0", "殺了你。", "0", "cv_lilith_19", "0", "0"},
[401322] = {401322, 10013, 26, 19, "0", "0", "能量儲備即將歸零……終於可以結束了嗎……誰來救救我……你在哪裡啊……", "エネルギーがもうすぐ切れてしまう……やっと終わるのね……誰か、私を助けて……あなたはどこ……", "0", "0", "能量儲備即將歸零……終於可以結束了嗎……誰來救救我……你在哪裡啊……", "0", "cv_lilith_20", "0", "0"},
[401323] = {401323, 10013, 27, 20, "0", "0", "啊，又是那股熟悉的味道呢，是你吧。", "あっ、またあの懐かしい匂いが……あなたよね？", "0", "0", "啊，又是那股熟悉的味道呢，是你吧。", "0", "cv_lilith_21", "0", "0"},
[401324] = {401324, 10013, 28, 21, "0", "0", "和你貼得這麼近，真討厭啊……", "あなたがこんな近い所にいるなんて、嫌だわ……", "0", "0", "和你貼得這麼近，真討厭啊……", "0", "cv_lilith_22", "0", "0"},
[401325] = {401325, 10013, 29, 21, "0", "0", "要小心點喔，我可不想聽到你摔下去時發出的哀嚎。", "あなた、気を付けてね。落ちる時の叫び聲は聞きたくないわ。", "0", "0", "要小心點哦，我可不想聽到你摔下去時發出的哀嚎。", "0", "cv_lilith_23", "0", "0"},
[401326] = {401326, 10013, 30, 22, "0", "0", "放心地上吧。", "安心して行きなさい。", "0", "0", "放心地上吧。", "0", "cv_lilith_24", "0", "0"},
[401327] = {401327, 10013, 31, 23, "0", "0", "如果敢使用通感作弊就殺了你喔。", "通感覚でカンニングしたら殺すわよ。", "0", "0", "如果敢使用通感作弊就殺了你哦。", "0", "cv_lilith_25", "0", "0"},
[401328] = {401328, 10013, 32, 24, "0", "0", "好棒，我好開心。", "やった！…...嬉しいわ。", "0", "0", "好棒，我好開心。", "0", "cv_lilith_26", "0", "0"},
[401329] = {401329, 10013, 33, 25, "0", "0", "啊，和我想得一樣，下次再努力吧。", "ああ、こうなると思ったわ。また次の機會に頑張って。", "0", "0", "啊，和我想得一樣，下次再努力吧。", "0", "cv_lilith_27", "0", "0"},
[401330] = {401330, 10013, 34, 26, "0", "0", "老遠就聞到你的味道了呢。當然，我指的不是體味。", "遠くからあなたの匂いがしたわ。もちろん、體臭の話じゃないわよ。", "0", "0", "老遠就聞到你的味道了呢。當然，我指的不是體味。", "0", "cv_lilith_30", "0", "0"},
[401331] = {401331, 10013, 35, 27, "0", "0", "終點到底有什麼在等著我們呢？", "終點で私たちを待っているものは何だろう。", "0", "0", "終點到底有什麼在等著我們呢？", "0", "cv_lilith_32", "0", "0"},
[401332] = {401332, 10013, 36, 28, "0", "0", "這次又要持續多久呢？", "今回はどのくらい続くの？", "0", "0", "這次又要持續多久呢？", "0", "cv_lilith_33", "0", "0"},
[401333] = {401333, 10013, 37, 29, "0", "0", "這些是同伴吧。", "この者たちは仲間よね。", "0", "0", "這些是同伴吧。", "0", "cv_lilith_34", "0", "0"},
[401334] = {401334, 10013, 38, 30, "0", "0", "招些厲害的傢夥吧。", "優秀な人材を集めて", "0", "0", "招些厲害的傢伙吧。", "0", "cv_lilith_35", "0", "0"},
[401335] = {401335, 10013, 39, 31, "0", "0", "嗯？缺裝備了嗎？", "ん？裝備が足りないの？", "0", "0", "嗯？缺裝備了嗎？", "0", "cv_lilith_36", "0", "0"},
[401336] = {401336, 10013, 40, 32, "0", "0", "去採購點東西吧。", "買い物をすれば？", "0", "0", "去採購點東西吧。", "0", "cv_lilith_37", "0", "0"},
[401337] = {401337, 10013, 41, 33, "0", "0", "確認一下個人資訊吧。", "個人情報を確認しよう。", "0", "0", "確認一下個人資訊吧。", "0", "cv_lilith_38", "0", "0"},
[401338] = {401338, 10013, 42, 34, "0", "0", "在這裡變更設定。", "ここでは設定を変更できるわ。", "0", "0", "在這裡變更設置。", "0", "cv_lilith_39", "0", "0"},
[401339] = {401339, 10013, 43, 35, "0", "0", "有給你寫的情書，開玩笑的。", "あなた宛のラブレターがあるわよ。…...冗談よ。", "0", "0", "有給你寫的情書，開玩笑的。", "0", "cv_lilith_40", "0", "0"},
[401340] = {401340, 10013, 44, 36, "0", "0", "滿是通感者的味道呢，真討厭。", "通感覚者の匂いがする。本當に嫌だわ。", "0", "0", "滿是通感者的味道呢，真討厭。", "0", "cv_lilith_41", "0", "0"},
[401341] = {401341, 10013, 45, 37, "0", "0", "確認一下。", "確認して。", "0", "0", "確認一下。", "0", "cv_lilith_42", "0", "0"},
[401400] = {401400, 10014, 1, 1, "0", "0", "蒼霧殘響。", "0", "0", "0", "蒼霧殘響。", "0", "cv_korovin_32", "0", "0"},
[401401] = {401401, 10014, 2, 2, "0", "0", "真沒辦法，就幫你看管一會兒吧。", "0", "0", "0", "真沒辦法，就幫你看管一會兒吧。", "0", "cv_korovin_2", "0", "0"},
[401402] = {401402, 10014, 3, 3, "0", "0", "科羅溫·卡·薇拉，向領航報導，請問這裡附近有買零食的地方嗎？", "0", "0", "0", "柯洛溫·卡·薇拉，向領航報導，請問這裡附近有買零食的地方嗎？", "0", "cv_korovin_1", "0", "0"},
[401403] = {401403, 10014, 4, 4, "0", "idle", "零食要吃完了，得想辦法去買一些…領航，能借我一萬盾幣嗎？", "0", "0", "0", "零食要吃完了，得想辦法去買一些…領航，能借我一萬盾幣嗎？", "0", "cv_korovin_3", "0", "0"},
[401404] = {401404, 10014, 5, 4, "0", "idle", "不知道小伊莉雅跑哪去了，領航，你知道嗎？", "0", "0", "0", "不知道小伊莉雅跑哪去了，領航，你知道嗎？", "0", "cv_korovin_4", "0", "0"},
[401405] = {401405, 10014, 6, 4, "0", "idle", "雖然大家都覺得我們灰燼小隊的人都是怪胎，但是在我眼裏伊莉雅她們都是善良的孩子，只是對別人缺乏信任。不過據我所知，她們對於領航你可是非常信任的。", "0", "0", "0", "雖然大家都覺得我們灰燼小隊的人都是怪胎，但是在我眼裡伊莉雅她們都是善良的孩子，只是對別人缺乏信任。不過據我所知，她們對於領航你可是非常信任的。", "0", "cv_korovin_29", "0", "0"},
[401406] = {401406, 10014, 7, 5, "1_》_0_0.8", "level1", "和灰燼的大家在一起的日子，我感到非常開心，真希望這樣的生活能一直持續下去。", "0", "0", "0", "和灰燼的大家在一起的日子，我感到非常開心，真希望這樣的生活能一直持續下去。", "0", "cv_korovin_30", "0", "0"},
