[401502] = {401502, 10015, 3, 3, "0", "0", "我是索菲亞，索菲亞·伊·波戈洛夫斯基。嗯，你就是領航嗎？呵呵，真小啊~", "0", "0", "0", "我是索菲亞，索菲亞·伊·波戈洛夫斯基。嗯，你就是領航嗎？呵呵，真小啊~", "0", "cv_sofia_1", "0", "0"},
[401503] = {401503, 10015, 4, 4, "0", "idle", "打雪仗是我在卡佳最喜歡的娛樂活動了。不管多麼用力地扔出去，都不會傷到人，這不是很好的娛樂活動嗎？", "0", "0", "0", "打雪仗是我在卡佳最喜歡的娛樂活動了。不管多麼用力地扔出去，都不會傷到人，這不是很好的娛樂活動嗎？", "0", "cv_sofia_3", "0", "0"},
[401504] = {401504, 10015, 5, 4, "0", "idle", "不管殺死多少隻原罪，它們都會不停地湧來……怎麼會有如此美麗的生物呢？", "0", "0", "0", "不管殺死多少只原罪，它們都會不停地湧來……怎麼會有如此美麗的生物呢？", "0", "cv_sofia_4", "0", "0"},
[401505] = {401505, 10015, 6, 4, "0", "idle", "“鋼輪戈爾”的隊長，也就是葉夫根尼婭……將她的身體和精神一併摧毀……我想，能做到這件事的人，應該還不存在吧？畢竟，她可是我的隊長呢。", "0", "0", "0", "“鋼輪戈爾”的隊長，也就是葉夫根尼婭……將她的身體和精神一併摧毀……我想，能做到這件事的人，應該還不存在吧？畢竟，她可是我的隊長呢。", "0", "cv_sofia_29", "0", "0"},
[401506] = {401506, 10015, 7, 5, "1_》_0_0.8", "level1", "“毀壞”、“死亡”、“滅絕”、“消亡”……光是念誦它們，想像畫面，我就會興奮起來。果然，我不正常呢。", "0", "0", "0", "“毀壞”、“死亡”、“滅絕”、“消亡”……光是念誦它們，想像畫面，我就會興奮起來。果然，我不正常呢。", "0", "cv_sofia_30", "0", "0"},
