[401509] = {401509, 10015, 10, 5, "1_》_500_2", "level3", "現在看到領航的時候，我的心裡就會萌生出一種奇怪的衝動……想要將你變成隻屬於我一個人的東西呢，呵呵。", "0", "0", "0", "現在看到領航的時候，我的心裡就會萌生出一種奇怪的衝動……想要將你變成只屬於我一個人的東西呢，呵呵。", "0", "cv_sofia_7", "0", "0"},
[401510] = {401510, 10015, 11, 5, "1_》_1000_2.5", "level4", "人是不可以忤逆她的天性的。而我的天性就是“破壞”。我有一種預感，有一天，我會對原罪以外的生命下手……所以，那一天來臨的時候，我希望會是領航你來阻止我……殺死我……", "0", "0", "0", "人是不可以忤逆她的天性的。而我的天性就是“破壞”。我有一種預感，有一天，我會對原罪以外的生命下手……所以，那一天來臨的時候，我希望會是領航你來阻止我……殺死我……", "0", "cv_sofia_8", "0", "0"},
[401511] = {401511, 10015, 12, 6, "0", "0", "謝謝~ 雖想這麼說，你難道想自殺嗎？", "0", "0", "0", "謝謝~ 雖想這麼說，你難道想自殺嗎？", "0", "cv_sofia_9", "0", "0"},
[401512] = {401512, 10015, 13, 7, "0", "0", "故意給炸彈加分量麼？這話由我來說雖然有點奇怪，領航你真是瘋了。", "0", "0", "0", "故意給炸彈加分量麼？這話由我來說雖然有點奇怪，領航你真是瘋了。", "0", "cv_sofia_10", "0", "0"},
[401513] = {401513, 10015, 14, 8, "0", "0", "呵呵，我能感受到，潛藏在我心裡的那副欲望要湧出來了……接下來會發生什麼，連我也不知道呢，要做好心理準備，領航。", "0", "0", "0", "呵呵，我能感受到，潛藏在我心裡的那副欲望要湧出來了……接下來會發生什麼，連我也不知道呢，要做好心理準備，領航。", "0", "cv_sofia_11", "0", "0"},
[401514] = {401514, 10015, 15, 9, "0", "0", "能更輕鬆地摧毀敵人了。", "0", "0", "0", "能更輕鬆地摧毀敵人了。", "0", "cv_sofia_12", "0", "0"},
