[401724] = {401724, 10017, 27, 20, "0", "0", "哇啊啊，這…這這，這就是貴族的奢靡生活嗎！……啊，就和我家一樣！", "0", "0", "0", "哇啊啊，這…這這，這就是貴族的奢靡生活嗎！……啊，就和我家一樣！", "0", "cv_rosalind_22", "0", "0"},
[401725] = {401725, 10017, 28, 21, "0", "0", "這樣盯著一位女士可不是紳士所為。", "0", "0", "0", "這樣盯著一位女士可不是紳士所為。", "0", "cv_rosalind_23", "0", "0"},
[401726] = {401726, 10017, 29, 21, "0", "0", "就一次喔，本小姐允許你為我搓背。", "0", "0", "0", "就一次哦，本小姐允許你為我搓背。", "0", "cv_rosalind_24", "0", "0"},
[401727] = {401727, 10017, 30, 22, "0", "0", "抓住這次機會，領航。", "0", "0", "0", "抓住這次機會，領航。", "0", "cv_rosalind_25", "0", "0"},
[401728] = {401728, 10017, 31, 23, "0", "0", "相信你不會認錯本小姐的。", "0", "0", "0", "相信你不會認錯本小姐的。", "0", "cv_rosalind_26", "0", "0"},
