[401733] = {401733, 10017, 36, 28, "0", "0", "該讓你們看一下本小姐的實力了。", "0", "0", "0", "該讓你們看一下本小姐的實力了。", "0", "cv_rosalind_34", "0", "0"},
[401734] = {401734, 10017, 37, 29, "0", "0", "原來你有這麼多朋友呢。", "0", "0", "0", "原來你有這麼多朋友呢。", "0", "cv_rosalind_35", "0", "0"},
[401735] = {401735, 10017, 38, 30, "0", "0", "花錢就能買到朋友？！這個得記下來。", "0", "0", "0", "花錢就能買到朋友？！這個得記下來。", "0", "cv_rosalind_36", "0", "0"},
[401736] = {401736, 10017, 39, 31, "0", "0", "不錯的裝備，不過比起本小姐的還差遠了。", "0", "0", "0", "不錯的裝備，不過比起本小姐的還差遠了。", "0", "cv_rosalind_37", "0", "0"},
[401737] = {401737, 10017, 40, 32, "0", "0", "今天的特惠是……咳，隨便挑吧。", "0", "0", "0", "今天的特惠是……咳，隨便挑吧。", "0", "cv_rosalind_38", "0", "0"},
[401738] = {401738, 10017, 41, 33, "0", "0", "領航來自多瑙……啊！你不會是真正的貴族吧？", "0", "0", "0", "領航來自多瑙……啊！你不會是真正的貴族吧？", "0", "cv_rosalind_39", "0", "0"},
[401739] = {401739, 10017, 42, 34, "0", "0", "真複雜啊……", "0", "0", "0", "真複雜啊……", "0", "cv_rosalind_40", "0", "0"},
