[401741] = {401741, 10017, 44, 36, "0", "0", "名流聚會？不行，還沒做好心理準備……", "0", "0", "0", "名流聚會？不行，還沒做好心理準備……", "0", "cv_rosalind_42", "0", "0"},
[401742] = {401742, 10017, 45, 37, "0", "0", "還行吧。", "0", "0", "0", "還行吧。", "0", "cv_rosalind_43", "0", "0"},
[401800] = {401800, 10018, 1, 1, "0", "0", "蒼霧殘響", "0", "0", "0", "0", "0", "cv_lyfa_32", "0", "0"},
[401801] = {401801, 10018, 2, 2, "0", "0", "交給我吧。", "0", "0", "0", "0", "0", "cv_lyfa_2", "0", "0"},
[401802] = {401802, 10018, 3, 3, "0", "0", "瓦爾基里小隊的莉法，向您報導。領航……我能稱呼您為主人嗎？", "0", "0", "0", "0", "0", "cv_lyfa_1", "0", "0"},
[401803] = {401803, 10018, 4, 4, "0", "idle", "資料和筆記…還有這麼多戰鬥報告！主人的工作真是幸苦啊。", "0", "0", "0", "0", "0", "cv_lyfa_3", "0", "0"},
[401804] = {401804, 10018, 5, 4, "0", "idle", "雖然我穿著女僕裝，但是在戰場上也請相信我的實力。", "0", "0", "0", "0", "0", "cv_lyfa_4", "0", "0"},
[401805] = {401805, 10018, 6, 4, "0", "idle", "隊長是個通情達理的人，同意了我穿女僕裝的任性要求…我當然不能讓她失望，所以必須在戰場上好好表現。", "0", "0", "0", "0", "0", "cv_lyfa_29", "0", "0"},
[401806] = {401806, 10018, 7, 5, "1_》_0_0.8", "level1", "女僕每天要做的工作是很多的，比如打掃衛生啦，清洗衣物啦，準備下午茶啦……其實我也是樂在其中的，所以下一個命令是什麼呢，主人！", "0", "0", "0", "0", "0", "cv_lyfa_30", "0", "0"},
[401807] = {401807, 10018, 8, 5, "1_》_0_0.8", "level1", "主人，您也覺得這身裝束很適合我嗎？嘿嘿，謝謝~", "0", "0", "0", "0", "0", "cv_lyfa_5", "0", "0"},
[401808] = {401808, 10018, 9, 5, "1_》_100_1.5", "level2", "主人，請問需要喝茶還是咖啡？和平時一樣的紅茶，明白了~", "0", "0", "0", "0", "0", "cv_lyfa_6", "0", "0"},
[401809] = {401809, 10018, 10, 5, "1_》_500_2", "level3", "主人，到開會的時間了，祝您一路順風……誒？我也要一起去嗎……是，遵命~", "0", "0", "0", "0", "0", "cv_lyfa_7", "0", "0"},
[401810] = {401810, 10018, 11, 5, "1_》_1000_2.5", "level4", "陰霾的天空會讓人們的臉蒙上陰翳，心情也會因此而低落沮喪。但是沒關係，總有一天，天空會放晴的。到時候，主人會和我一起出去野餐嗎，嘿嘿~", "0", "0", "0", "0", "0", "cv_lyfa_8", "0", "0"},
[401811] = {401811, 10018, 12, 6, "0", "0", "感覺到能力有提升了。", "0", "0", "0", "0", "0", "cv_lyfa_9", "0", "0"},
[401812] = {401812, 10018, 13, 7, "0", "0", "離成為專業女僕又進了一步。", "0", "0", "0", "0", "0", "cv_lyfa_10", "0", "0"},
[401813] = {401813, 10018, 14, 8, "0", "0", "主人的心意，我感受到了。從主人那得到的全部，我都會用來更好地服侍您的。", "0", "0", "0", "0", "0", "cv_lyfa_11", "0", "0"},
