[401816] = {401816, 10018, 17, 11, "0", "0", "可不要小瞧女僕的厲害之處哦。", "0", "0", "0", "0", "0", "cv_lyfa_14", "0", "0"},
[401817] = {401817, 10018, 18, 12, "0", "0", "十分抱歉，撒掉的咖啡，馬上就幫你換一杯。", "0", "0", "0", "0", "0", "cv_lyfa_15", "0", "0"},
[401818] = {401818, 10018, 19, 13, "0", "0", "嗚——這種情況第一次遇到，該怎麼辦呢……", "0", "0", "0", "0", "0", "cv_lyfa_16", "0", "0"},
