[401836] = {401836, 10018, 39, 31, "0", "0", "和風女僕裝也好好看……啊，沒 沒什麼。", "0", "0", "0", "0", "0", "cv_lyfa_37", "0", "0"},
[401837] = {401837, 10018, 40, 32, "0", "0", "咖啡豆有點不夠用了。", "0", "0", "0", "0", "0", "cv_lyfa_38", "0", "0"},
