[401839] = {401839, 10018, 42, 34, "0", "0", "這就要麻煩主人自行整理了。", "0", "0", "0", "0", "0", "cv_lyfa_40", "0", "0"},
[401840] = {401840, 10018, 43, 35, "0", "0", "這是今日的郵件。", "0", "0", "0", "0", "0", "cv_lyfa_41", "0", "0"},
[401841] = {401841, 10018, 44, 36, "0", "0", "請稍等，馬上就為大家泡茶。", "0", "0", "0", "0", "0", "cv_lyfa_42", "0", "0"},
[401842] = {401842, 10018, 45, 37, "0", "0", "安心使用吧。", "0", "0", "0", "0", "0", "cv_lyfa_43", "0", "0"},
[401900] = {401900, 10019, 1, 1, "0", "0", "蒼霧殘響", "蒼霧殘響（ハツリバーブ）。", "0", "0", "0", "0", "cv_nozomi_sw_1", "0", "0"},
[401901] = {401901, 10019, 2, 2, "0", "0", "你找到我啦，領航，我等你好久了。", "あたしを見つけてくれたんですね。ナビゲーターさん。", "0", "0", "0", "0", "cv_nozomi_sw_2", "0", "0"},
[401902] = {401902, 10019, 3, 3, "0", "0", "嗯？我的名字怎麼了嗎？和那位傳說中的偶像名字一模一樣？……是嘛，原來“她”已經死了啊。", "あたしの名前が何か……？え、伝説のアイドルと同じ？……そうですか。彼女はもう、いないんですね。", "0", "0", "0", "0", "cv_nozomi_sw_3", "0", "0"},
[401903] = {401903, 10019, 4, 4, "0", "idle", "偶像！演奏家！駕駛員！嘿嘿，接下來的目標就是要為大家帶來真正的愛與和平！", "アイドル、ヴァイオリニスト、そしてドライバー！えへへ。次の目標は、みんなに愛と平和を屆けることです！", "0", "0", "0", "0", "cv_nozomi_sw_5", "0", "0"},
[401904] = {401904, 10019, 5, 4, "0", "idle", "把大家拉進偶像的領域又擅自走掉……她們一定對我很失望吧……", "勝手にアイドルの世界に引き込んで、自分だけ勝手にいなくなって……みんなきっと、あたしのこと怒ってるよね……", "0", "0", "0", "0", "cv_nozomi_sw_6", "0", "0"},
[401905] = {401905, 10019, 6, 4, "0", "idle", "好——久——沒有唱歌了！生疏了不少呢，不過這也沒辦法……我想快點重新回到舞臺上！得加把勁了！", "すっごく久しぶりに歌いました！だいぶ下手になっちゃったけど……これが今のあたし。またステージに戻るために、もっと頑張らなきゃ！", "0", "0", "0", "0", "cv_nozomi_sw_7", "0", "0"},
[401906] = {401906, 10019, 7, 5, "1_》_0_0.8", "level1", "當我站在舞臺上，還能拉動琴弦，還能繼續歌唱……活著真是太好了。", "ステージに立って、ヴァイオリンを弾いて、歌うことができる……生きるって素晴らしい……", "0", "0", "0", "0", "cv_nozomi_sw_8", "0", "0"},
[401907] = {401907, 10019, 8, 5, "1_》_0_0.8", "level1", "呀！不要在我練習的時候忽然靠過來嘛。", "きゃっ！練習してる時に急に近寄らないでください！", "0", "0", "0", "0", "cv_nozomi_sw_9", "0", "0"},
[401908] = {401908, 10019, 9, 5, "1_》_100_1.5", "level2", "你……想聽聽嗎？我已經好久沒有面對觀眾了……有點害羞。", "演奏を聞かせてほしい、ですか？お客さんの前でするのは久しぶりです……ちょっと照れちゃいますね。", "0", "0", "0", "0", "cv_nozomi_sw_10", "0", "0"},
[401909] = {401909, 10019, 10, 5, "1_》_500_2", "level3", "好緊張……現在的我還能調動起觀眾的情緒嗎。……我的首場演出，領航你會來的吧？", "緊張する……今のあたしで、お客さんを満足させられるのかな……ナビゲーターさん。あたしのファーストライブ、來てくれるよね？", "0", "0", "0", "0", "cv_nozomi_sw_11", "0", "0"},
[401910] = {401910, 10019, 11, 5, "1_》_1000_2.5", "level4", "你知道嗎，領航。音樂演出能傳達出演出者的感情，所以，我想向你傳達結束希的聲音。這是我為你譜寫的曲子。", "ナビゲーターさん。演奏者は音楽にのせて気持ちを伝えることができるんです。だから結束希の音を聞いてください。これは、あなたのために作った曲なんですよ。", "0", "0", "0", "0", "cv_nozomi_sw_12", "0", "0"},
[401911] = {401911, 10019, 12, 6, "0", "0", "哼♫~~", "フンフフーン♪", "0", "0", "0", "0", "cv_nozomi_sw_13", "0", "0"},
[401912] = {401912, 10019, 13, 7, "0", "0", "接近頂點了。", "トップを目指します！", "0", "0", "0", "0", "cv_nozomi_sw_14", "0", "0"},
[401913] = {401913, 10019, 14, 8, "0", "0", "嗯……嗯？剛剛好像有了一點靈感，剛剛那個是什麼？！覺醒？好厲害！可以再來一次嗎！……不可以了？遺憾……", "んん……あれ？このインスピレーション……これ、なんですか！？覚醒？すごーい！もう一回お願いできますか？……ダメ？殘念です……", "0", "0", "0", "0", "cv_nozomi_sw_15", "0", "0"},
[401914] = {401914, 10019, 15, 9, "0", "0", "找回曾經的手感了。", "昔の感覚が戻ってきました！", "0", "0", "0", "0", "cv_nozomi_sw_16", "0", "0"},
[401915] = {401915, 10019, 16, 10, "0", "0", "輪到我表演了嗎？", "私の出番ですか？", "0", "0", "0", "0", "cv_nozomi_sw_17", "0", "0"},
[401916] = {401916, 10019, 17, 11, "0", "0", "完美謝幕！", "カーテンコール！", "0", "0", "0", "0", "cv_nozomi_sw_18", "0", "0"},
[401917] = {401917, 10019, 18, 12, "0", "0", "略微的失誤，嗯……音樂有點雜音呢。", "ちょっと失敗ですね。うーん……ノイズが入っちゃいました。", "0", "0", "0", "0", "cv_nozomi_sw_19", "0", "0"},
[401918] = {401918, 10019, 19, 13, "0", "0", "還沒完全掌握這一段，再鍛煉一下自己吧。", "あのパートが上手くいきません……もっと練習しなきゃ。", "0", "0", "0", "0", "cv_nozomi_sw_20", "0", "0"},
[401919] = {401919, 10019, 20, 14, "0", "0", "大事件！演奏大失敗！要引起公憤了！", "やばい、大失敗！炎上しちゃいます！", "0", "0", "0", "0", "cv_nozomi_sw_21", "0", "0"},
[401920] = {401920, 10019, 21, 15, "0", "0", "大幕落下。", "これでラスト！", "0", "0", "0", "0", "cv_nozomi_sw_23", "0", "0"},
[401921] = {401921, 10019, 23, 16, "0", "0", "請聆聽！", "聞いてください！", "0", "0", "0", "0", "cv_nozomi_sw_22", "0", "0"},
[401922] = {401922, 10019, 26, 19, "0", "0", "噪音……", "不協和音が……", "0", "0", "0", "0", "cv_nozomi_sw_24", "0", "0"},
[401923] = {401923, 10019, 24, 17, "0", "0", "間奏律——", "インテルメッツォ！", "0", "0", "0", "0", "cv_nozomi_sw_26", "0", "0"},
[401924] = {401924, 10019, 25, 18, "0", "0", "大家久等了！結束希重回舞臺的演出，此刻，開演！", "お待たせしました！希ちゃんの復帰ライブ、開演です！", "0", "0", "0", "0", "cv_nozomi_sw_25", "0", "0"},
[401925] = {401925, 10019, 27, 20, "0", "0", "——呀！！領航？！你怎麼在這裏？！", "え、えええ！？ナビゲーターさん！？なんでここに？", "0", "0", "0", "0", "cv_nozomi_sw_27", "0", "0"},
[401926] = {401926, 10019, 28, 21, "0", "0", "…嗯嗯，原來如此，現在的樂壇真是大不一樣啊。", "……なるほど。今の音楽業界はこうなんですね。", "0", "0", "0", "0", "cv_nozomi_sw_28", "0", "0"},
[401927] = {401927, 10019, 29, 21, "0", "0", "音樂真是讓人痛苦又快樂……別人的表演會打動我的心，但卻又讓我嫉妒，不甘心。……等出去了，就繼續練習吧！", "音楽って本當に楽しいけど、辛い時もあるんですよ。他の人のパフォーマンスで感動して泣くこともあれば、嫉妬で悔しくなることも……うん！帰ったらすぐ練習します！", "0", "0", "0", "0", "cv_nozomi_sw_29", "0", "0"},
[401928] = {401928, 10019, 30, 22, "0", "0", "秘密演唱會開始了哦~", "シークレットライブ、開演です！", "0", "0", "0", "0", "cv_nozomi_sw_30", "0", "0"},
[401929] = {401929, 10019, 31, 23, "0", "0", "我的“聲音”對你而言是特殊的嗎？", "ナビゲーターさんにとって私の聲って、特別ですかねー？", "0", "0", "0", "0", "cv_nozomi_sw_31", "0", "0"},
[401930] = {401930, 10019, 32, 24, "0", "0", "你記住了呢！那我單方面宣佈你是我的死忠粉了！", "覚えててくれたんですね！あたしのファンとして合格です！", "0", "0", "0", "0", "cv_nozomi_sw_32", "0", "0"},
[401931] = {401931, 10019, 33, 25, "0", "0", "嗚……看來我還不夠成熟……", "ううう……私もまだまだですね……", "0", "0", "0", "0", "cv_nozomi_sw_33", "0", "0"},
[401932] = {401932, 10019, 34, 26, "0", "0", "歡迎回來，我正要準備練習了，領航你可以在旁邊聽哦~", "おかえりなさーい。ちょうど練習をはじめるところだったんですよ。よかったらそこで聞いててくださいね。", "0", "0", "0", "0", "cv_nozomi_sw_34", "0", "0"},
[401933] = {401933, 10019, 35, 27, "0", "0", "戰鬥的練習也沒有落下！", "戦闘訓練もちゃんとしてますよ！", "0", "0", "0", "0", "cv_nozomi_sw_35", "0", "0"},
[401934] = {401934, 10019, 36, 28, "0", "0", "駕駛員的道路也和偶像一樣殘酷呢。", "ドライバーの世界もアイドルと同じくらい過酷なんですね。", "0", "0", "0", "0", "cv_nozomi_sw_36", "0", "0"},
[401935] = {401935, 10019, 37, 29, "0", "0", "下次邀請大家一起來聽吧！", "みなさんもライブに來てくださいねー！", "0", "0", "0", "0", "cv_nozomi_sw_37", "0", "0"},
[401936] = {401936, 10019, 38, 30, "0", "0", "哦！新的成員要來了嗎。", "新しいメンバーですか？", "0", "0", "0", "0", "cv_nozomi_sw_38", "0", "0"},
[401937] = {401937, 10019, 39, 31, "0", "0", "其實鋼琴我也會彈哦。", "実はピアノも弾けちゃいますよ！", "0", "0", "0", "0", "cv_nozomi_sw_39", "0", "0"},
[401938] = {401938, 10019, 40, 32, "0", "0", "想試試新的樂器。", "新しい楽器も試してみたいです。", "0", "0", "0", "0", "cv_nozomi_sw_40", "0", "0"},
[401939] = {401939, 10019, 41, 33, "0", "0", "檔案對吧，請看。", "プロフィールですね、どうぞ。", "0", "0", "0", "0", "cv_nozomi_sw_41", "0", "0"},
[401940] = {401940, 10019, 42, 34, "0", "0", "把音量調到最大吧！", "音量を最大にしましょう！", "0", "0", "0", "0", "cv_nozomi_sw_42", "0", "0"},
[401941] = {401941, 10019, 43, 35, "0", "0", "有粉絲的感謝信嗎？", "ファンレターは…ありますか？", "0", "0", "0", "0", "cv_nozomi_sw_43", "0", "0"},
[401942] = {401942, 10019, 44, 36, "0", "0", "看看大家的想法吧。", "みんなの感想を見てみましょう。", "0", "0", "0", "0", "cv_nozomi_sw_44", "0", "0"},
[401943] = {401943, 10019, 45, 37, "0", "0", "哼~", "へえー。", "0", "0", "0", "0", "cv_nozomi_sw_45", "0", "0"},
[402000] = {402000, 10020, 1, 1, "0", "0", "蒼霧殘響", "ハツリバーブ", "0", "0", "0", "0", "cv_weilai_sw_1", "0", "0"},
[402001] = {402001, 10020, 2, 2, "0", "0", "變態先生就這麼想看到我嗎，好噁心。不過我可是成熟大方的淑女，自然是不會拒絕這種要求的。", "変態さん、そんなに私に会いたかったんですか？気持ち悪いです。だけど私も大人のレディですから、お誘いを断ったりはしませんよ。", "0", "0", "0", "0", "cv_weilai_sw_2", "0", "0"},
[402002] = {402002, 10020, 3, 3, "0", "0", "我的名字是未來，是早前預約過要來的駕駛員。咦……你說在夢裡見過我？變態先生你真的是……要是我什麼都不記得了的話，你這句話就是性騷擾哦？", "私の名前はミライです。約束通り会いに来ました。えっ？夢の中で私に会ったことがある？変態さん、あなた……それ私が何も覚えてなかったら、ただのセクハラですからね？", "0", "0", "0", "0", "cv_weilai_sw_3", "0", "0"},
[402003] = {402003, 10020, 4, 4, "0", "idle", "我、我對所有的事情基本上都是三分鐘熱度……就連來服役當駕駛員都是腦子一熱的結果……不過還好遇見了變態先生。", "わ、私、何事にも三日坊主なところがありまして……ドライバーになったのも、その場の勢いだったんです…。…でも、変態さんと出会えたのは幸運でした。", "0", "0", "0", "0", "cv_weilai_sw_4", "0", "0"},
[402004] = {402004, 10020, 5, 4, "0", "idle", "沒想到變態先生竟然和我是在同一個世界……更沒想到我竟然還活著……這下真是太不妙了……變態先生你會對我負責的吧？", "まさか変態さんと同じ世界にいられるなんて…。…しかも生きたまま…。…これは大変なことですよ。変態さん、責任取ってくれますよね？", "0", "0", "0", "0", "cv_weilai_sw_5", "0", "0"},
[402005] = {402005, 10020, 6, 4, "0", "idle", "所謂的大人，只不過是大一點的人罷了。那巨大化之後我應該就是大人中的大人了吧。", "いわゆる大人なんてものは、子供より大きいってだけです。ということは、巨大化した私は大人の中の大人ということですね。", "0", "0", "0", "0", "cv_weilai_sw_6", "0", "0"},
[402006] = {402006, 10020, 7, 5, "1_》_0_0.8", "level1", "啊~差不多已經當膩駕駛員了，什麼時候讓我試試其他崗位？", "あ～、そろそろドライバーにも飽きてきました。なんか他の仕事はないんですか？", "0", "0", "0", "0", "cv_weilai_sw_7", "0", "0"},
[402007] = {402007, 10020, 8, 5, "1_》_0_0.8", "level1", "就算是我也是有能堅持下去的事情的……我堅持著對每一件未知的事情抱持著好奇心，也堅持著自己三分鐘的熱度，怎麼樣，了不起吧？", "私にだって継続している事くらいありますよ。未知への好奇心を持ち続けることと三日坊主を繰り返すことです。どうですか、凄いでしょう？", "0", "0", "0", "0", "cv_weilai_sw_8", "0", "0"},
[402008] = {402008, 10020, 9, 5, "1_》_100_1.5", "level2", "我都穿了泳衣過來的，變態先生你難道一點想法和行動都沒有嗎，真是一點都不懂女孩子……不要再辦公了！陪我出去玩啦！", "水着を着て来たのに、まさか少しもリアクションがないなんて…。本当に女の子の気持ちが分かっていませんね。……仕事の手を止めてください！遊びに行きますよ！", "0", "0", "0", "0", "cv_weilai_sw_9", "0", "0"},
[402009] = {402009, 10020, 10, 5, "1_》_500_2", "level3", "曼妙的身段，性感的嗓音，偉大的性格，對所有的事情懷抱著熱忱，淑女中的淑女……我在說誰？這還用問當然是我啦！難道不像嗎？", "ナイスなボディ、セクシーな声、大物の気質、あらゆるものに情熱を持つ淑女の中の淑女。……誰のこと言ってるのかって？私に決まってるじゃないですか！違うって言うんですか？", "0", "0", "0", "0", "cv_weilai_sw_10", "0", "0"},
[402010] = {402010, 10020, 11, 5, "1_》_1000_2.5", "level4", "變態先生，我媽媽說想見見我的男朋友……是誰？當然是你啦！事到如今你要是還說出“我們什麼時候是這種關係了？”之類裝傻的話我就咬死你。", "変態さん、お母さんが彼氏を紹介しろって言ってるんですけど…。…誰のことかって？あなたに決まってるでしょう！この期に及んで「いつからそんな関係になったんだ？」なんて言う気なら噛み殺しますからね。", "0", "0", "0", "0", "cv_weilai_sw_11", "0", "0"},
[402011] = {402011, 10020, 12, 6, "0", "0", "這樣就變強了……好沒有實感……等一下還要特訓？誒——", "これで強くなったんですね……実感はありませんが。後で特訓がある？え～…。", "0", "0", "0", "0", "cv_weilai_sw_12", "0", "0"},
[402012] = {402012, 10020, 13, 7, "0", "0", "呀啊啊啊啊——！有什麼東西進到我身體內的感覺！麻麻的！好噁心！變態先生就是這樣用【通感】性騷擾其他女主角的嗎！", "ぎゃああああ！何かが体の中に入って来きます！ムズムズします！気持ち悪い！変態さん、通感覚でヒロイン達にこんなセクハラじみたことしてたんですか！？", "0", "0", "0", "0", "cv_weilai_sw_13", "0", "0"},
[402013] = {402013, 10020, 14, 8, "0", "0", "好累啊——我受不了了，特訓要不還是算了吧！", "疲れました…もう限界です…！やっぱり特訓はやめておきましょう！", "0", "0", "0", "0", "cv_weilai_sw_14", "0", "0"},
[402014] = {402014, 10020, 15, 9, "0", "0", "誒……你說希望和我保護大家……真是的太狡猾了竟然說這種話……我、我儘量回應你的期待吧。", "えっ？……私と一緒にみんなを守りたいって……ほんと言い回しが卑怯ですねあなたって。……わ、私もできるだけ頑張ってみますよ。", "0", "0", "0", "0", "cv_weilai_sw_15", "0", "0"},
[402015] = {402015, 10020, 16, 10, "0", "0", "啊？我也要上戰場嗎？", "は？私も戦場に出るんですか？", "0", "0", "0", "0", "cv_weilai_sw_16", "0", "0"},
[402016] = {402016, 10020, 17, 11, "0", "0", "輕、輕鬆拿下了，呼，我已經對當駕駛員這件事沒興趣了。", "ら、楽勝でしたね。ふぅ…私、もうドライバーという仕事に飽きちゃったかもです。", "0", "0", "0", "0", "cv_weilai_sw_17", "0", "0"},
[402017] = {402017, 10020, 18, 12, "0", "0", "快點回家吧！", "早く家に帰りましょう！", "0", "0", "0", "0", "cv_weilai_sw_18", "0", "0"},
[402018] = {402018, 10020, 19, 13, "0", "0", "啊！剛剛——鐳射擦著我的額頭飛過去啦！", "わっ！いま、光線が私のおでこを掠めていきましたよ！", "0", "0", "0", "0", "cv_weilai_sw_19", "0", "0"},
[402019] = {402019, 10020, 20, 14, "0", "0", "誒……這種情況該怎麼辦……要、要不領航和我一起當逃兵吧！", "あ、ああ……この状況、一体どうすれば…。な、ナビゲーターさん、一緒に逃げましょう！", "0", "0", "0", "0", "cv_weilai_sw_20", "0", "0"},
[402020] = {402020, 10020, 21, 15, "0", "0", "死掉的原罪才是我喜歡的原罪！", "私の好きな原罪は死んだ原罪だけです！", "0", "0", "0", "0", "cv_weilai_sw_21", "0", "0"},
[402021] = {402021, 10020, 23, 16, "0", "0", "趕緊消失！", "消えてください！", "0", "0", "0", "0", "cv_weilai_sw_23", "0", "0"},
[402022] = {402022, 10020, 26, 19, "0", "0", "我就說了做不到的……", "何もできないって言ったじゃないですか……", "0", "0", "0", "0", "cv_weilai_sw_26", "0", "0"},
[402023] = {402023, 10020, 24, 17, "0", "0", "呃啊——", "やぁあ！", "0", "0", "0", "0", "cv_weilai_sw_24", "0", "0"},
[402024] = {402024, 10020, 25, 18, "0", "0", "既然對我有所期待的話，那就好好地把目光放到我身上啊！！！！", "私に期待してるんだったら、絶対に目を離さないでくださいよ！！！！", "0", "0", "0", "0", "cv_weilai_sw_25", "0", "0"},
[402025] = {402025, 10020, 27, 20, "0", "0", "嗯……你要和我一起洗？好、好啊，來吧。我已經做好準備了。", "へぇ……私と一緒にお風呂に入りたいんですか？い、いいでしょう。準備はできてますので。", "0", "0", "0", "0", "cv_weilai_sw_27", "0", "0"},
[402026] = {402026, 10020, 28, 21, "0", "0", "原、原來說是洗澡就真的只是洗澡嗎！？太奇怪了吧！", "お、お風呂に入るってほんとにお風呂に入るだけって意味だったんですか！？おかしくないですか！？", "0", "0", "0", "0", "cv_weilai_sw_28", "0", "0"},
[402027] = {402027, 10020, 29, 21, "0", "0", "巨大化之後和你一起洗澡！？能想到這種玩法……果然不愧是變態先生！你的性癖也太奇怪了吧……！", "巨大化した私と一緒にお風呂に入りたい！？そんなやり方が……さすがは変態さんですね！あなたの性癖には驚かされてばかりですよ……！", "0", "0", "0", "0", "cv_weilai_sw_29", "0", "0"},
[402028] = {402028, 10020, 30, 22, "0", "0", "這是……懲罰遊戲？", "これって罰ゲームですか…？", "0", "0", "0", "0", "cv_weilai_sw_30", "0", "0"},
[402029] = {402029, 10020, 31, 23, "0", "0", "我可不保證你答錯了之後會發生什麼事情……", "答えを間違えたらどうなるか分かってますよね……", "0", "0", "0", "0", "cv_weilai_sw_31", "0", "0"},
[402030] = {402030, 10020, 32, 24, "0", "0", "我就知道你能認出來，因為我可是你的女主角呀！", "間違うはずがないって思ってましたよ。だって私はあなたのヒロインですもんね！", "0", "0", "0", "0", "cv_weilai_sw_32", "0", "0"},
[402031] = {402031, 10020, 33, 25, "0", "0", "明、明明說好要把我放在心上的……", "わ、私のことを気にかけてるって言ってたくせに……", "0", "0", "0", "0", "cv_weilai_sw_33", "0", "0"},
[402032] = {402032, 10020, 34, 26, "0", "0", "啊……你終於回來了！我還以為你丟下我跑掉了！不、不要擅自消失啊……", "あ、やっと戻って来たんですね！置いてきぼりにされたかと思いました！か、勝手にいなくならないでくださいよ……。", "0", "0", "0", "0", "cv_weilai_sw_34", "0", "0"},
[402033] = {402033, 10020, 35, 27, "0", "0", "不要——我不想戰鬥——好危險——！", "いやです！戦いたくありませんっ！危な過ぎます！", "0", "0", "0", "0", "cv_weilai_sw_35", "0", "0"},
[402034] = {402034, 10020, 36, 28, "0", "0", "演、演習……可以試試……", "え、演習ですか？……やってみてもいいですけど……。", "0", "0", "0", "0", "cv_weilai_sw_36", "0", "0"},
[402035] = {402035, 10020, 37, 29, "0", "0", "大家好可靠……", "みんな頼もしいです……", "0", "0", "0", "0", "cv_weilai_sw_37", "0", "0"},
[402036] = {402036, 10020, 38, 30, "0", "0", "說起來……泳裝也算裝備嗎……", "そう言えば……水着も装備品なんですよね……", "0", "0", "0", "0", "cv_weilai_sw_38", "0", "0"},
[402037] = {402037, 10020, 39, 31, "0", "0", "……明明是為了保護世界而研發的裝甲竟然不是免費配給駕駛員……好奇怪啊。", "……世界を救うために開発された装甲が、ドライバーにタダで提供されないなんて……なんかおかしいですよね。", "0", "0", "0", "0", "cv_weilai_sw_39", "0", "0"},
[402038] = {402038, 10020, 40, 32, "0", "0", "變態先生……我、我還沒工作，真的能進這種店嗎……", "変態さん……わ、私、仕事もしてないのに、こんなお店入っていいんですか……？", "0", "0", "0", "0", "cv_weilai_sw_40", "0", "0"},
[402039] = {402039, 10020, 41, 33, "0", "0", "把我的照片也放在變態先生這裡吧！", "私の写真も変態さんのところに置いておいてください！", "0", "0", "0", "0", "cv_weilai_sw_41", "0", "0"},
[402040] = {402040, 10020, 42, 34, "0", "0", "把所有人都禁言看看。", "全員ミュートしてみたらどうですかね。", "0", "0", "0", "0", "cv_weilai_sw_42", "0", "0"},
[402041] = {402041, 10020, 43, 35, "0", "0", "變態先生的家門口竟然有郵箱，好復古啊~", "変態さんの家ってポストが置いてあるんですか。レトロですね。", "0", "0", "0", "0", "cv_weilai_sw_43", "0", "0"},
[402042] = {402042, 10020, 44, 36, "0", "0", "喂——變態先生有聽到回音嗎？", "ちょっと、変態さん、返信来てませんか？", "0", "0", "0", "0", "cv_weilai_sw_44", "0", "0"},
[402043] = {402043, 10020, 45, 37, "0", "0", "這是什麼？", "これなんですか？", "0", "0", "0", "0", "cv_weilai_sw_45", "0", "0"},
[402100] = {402100, 10021, 1, 1, "0", "0", "蒼霧殘響。", "蒼霧殘響（ハツリバーブ）。", "0", "0", "0", "0", "cv_xinxiya_33", "0", "0"},
[402101] = {402101, 10021, 2, 2, "0", "0", "交給我們吧。", "私たちに任せてください。", "0", "0", "0", "0", "cv_xinxiya_2", "0", "0"},
[402102] = {402102, 10021, 3, 3, "0", "0", "初次見面，多瑙的領航，我們是兩人一體的駕駛員，辛西婭，辛米亞。", "はじめまして、ダニューブのナビゲーター。私たちは二つで一つのドライバー、シンシアとシンミアです。", "0", "0", "0", "0", "cv_xinxiya_1", "0", "0"},
[402103] = {402103, 10021, 4, 4, "0", "idle", "光是站在這裏稍微有些無聊……\n不如一起出去轉轉吧，領航。", "立っているだけでは少し退屈ですから……。みんなでお散歩に行こうよ！ナビゲーター。", "0", "0", "0", "0", "cv_xinxiya_3", "0", "0"},
[402104] = {402104, 10021, 5, 4, "0", "idle", "方舟周邊沒有任何敵人，還請不用太過操心。\n即便是出現敵人了，我們也能在瞬間搞定吧。", "方舟周辺に敵影、ありません。大丈夫です。もし敵がきても、私たちなら一瞬でやっつけちゃうしね。", "0", "0", "0", "0", "cv_xinxiya_4", "0", "0"},
[402105] = {402105, 10021, 6, 4, "0", "idle", "真羡慕你可以全世界到處跑啊，我們基本上就只能在方舟上行動。", "世界中を旅できるナビゲーターが羨ましいなあ。私たちは基本方舟に乗ってるだけだからねー。", "0", "0", "0", "0", "cv_xinxiya_30", "0", "0"},
[402106] = {402106, 10021, 7, 5, "1_》_0_0.8", "level1", "機會難得，週末一起和芙羅拉到城裏逛逛吧，領航也要一起來嗎？", "せっかくの機會ですから、週末はフローラと一緒に街に行く予定です。……ナビゲーターもご一緒にいかがですか？", "0", "0", "0", "0", "cv_xinxiya_31", "0", "0"},
[402107] = {402107, 10021, 8, 5, "1_》_0_0.8", "level1", "哎？是在叫我嗎？還是說，辛米亞？", "あ……私に何か、ご用でしょうか？それとも、シンミアにですか？", "0", "0", "0", "0", "cv_xinxiya_5", "0", "0"},
[402108] = {402108, 10021, 9, 5, "1_》_100_1.5", "level2", "想要和辛西婭處好關係嗎？我能告訴你方法哦。\n辛米亞……", "シンシアと仲良くなりたいの？じゃあいい方法を教えるね。シンミア……", "0", "0", "0", "0", "cv_xinxiya_6", "0", "0"},
[402109] = {402109, 10021, 10, 5, "1_》_500_2", "level3", "嗯……抱歉，我對你沒有任何印象。不過話說回來我對除了辛西婭外的所有人都沒有什麼印象。但是潛意識裏，我還是覺得你是個對我還有她而言非常重要的人。", "えーっと……ごめんね。あなたのこと、覚えてないんだ。っていうより、私はシンシア以外の人のことはあんまり覚えてないの。でもなぜか、私にも、シンシアにも、あなたがとても大切な人だって気がするんだ。", "0", "0", "0", "0", "cv_xinxiya_7", "0", "0"},
[402110] = {402110, 10021, 11, 5, "1_》_1000_2.5", "level4", "正如你所見，她就像是我的影子一樣。如果你不介意的話，我們三個人就像現在這樣相處就好……", "ご覧の通り、私とシンミアは表裏一體の存在。もしあなたが宜しければ、私達三人、このままで……いたいです……", "0", "0", "0", "0", "cv_xinxiya_8", "0", "0"},
[402111] = {402111, 10021, 12, 6, "0", "0", "一起變強吧，辛米亞。", "一緒に強くなろう。シンミア。", "0", "0", "0", "0", "cv_xinxiya_9", "0", "0"},
[402112] = {402112, 10021, 13, 7, "0", "0", "太好了，辛西婭，這樣一來我們就變得更強了！。", "やったね、シンシア！これで私たち、もっと強くなれたよ！", "0", "0", "0", "0", "cv_xinxiya_10", "0", "0"},
[402113] = {402113, 10021, 14, 8, "0", "0", "和你們一起抵達這裏的此刻，是我人生中最寶貴的時刻。", "あなたと一緒にここまで來ることができました。いま私は、人生で一番大切な瞬間を迎えています……", "0", "0", "0", "0", "cv_xinxiya_11", "0", "0"},
[402114] = {402114, 10021, 15, 9, "0", "0", "辛米亞，一起試試新的技能吧。", "シンミア、一緒に新しいスキルを試してみよう！", "0", "0", "0", "0", "cv_xinxiya_12", "0", "0"},
[402115] = {402115, 10021, 16, 10, "0", "0", "一起上吧，辛米亞。", "シンミア、一緒に行こう。", "0", "0", "0", "0", "cv_xinxiya_13", "0", "0"},
[402116] = {402116, 10021, 17, 11, "0", "0", "戰鬥結束，下次再一起並肩作戰吧。", "戦闘終了。次も一緒に戦いましょう。", "0", "0", "0", "0", "cv_xinxiya_14", "0", "0"},
[402117] = {402117, 10021, 18, 12, "0", "0", "哎嘿嘿，稍微有點點小失誤就別在意啦。", "えへへ。ちょっとぐらいのミスは気にしない、気にしない！", "0", "0", "0", "0", "cv_xinxiya_15", "0", "0"},
[402118] = {402118, 10021, 19, 13, "0", "0", "對不起…我明明可以做得更好的……", "すみません…もっと上手くできたはず……", "0", "0", "0", "0", "cv_xinxiya_16", "0", "0"},
[402119] = {402119, 10021, 20, 14, "0", "0", "絕對…不能讓你們傷害辛西婭……", "絶対に…シンシアを傷つけさせない…！", "0", "0", "0", "0", "cv_xinxiya_17", "0", "0"},
[402120] = {402120, 10021, 21, 15, "0", "0", "到此為止了……", "ここまでです…！", "0", "0", "0", "0", "cv_xinxiya_19", "0", "0"},
[402121] = {402121, 10021, 23, 16, "0", "0", "辛西婭，交給你了！", "シンシア、任せたよ！", "0", "0", "0", "0", "cv_xinxiya_18", "0", "0"},
[402122] = {402122, 10021, 26, 19, "0", "0", "辛西婭…", "シンシア……", "0", "0", "0", "0", "cv_xinxiya_20", "0", "0"},
[402123] = {402123, 10021, 24, 17, "0", "0", "剩下的交給我吧！", "後はお任せてください！", "0", "0", "0", "0", "cv_xinxiya_21", "0", "0"},
[402124] = {402124, 10021, 25, 18, "0", "0", "辛米亞！\n在~\n一起來完成最後一擊吧。\n收到！", "シンミア！はーい！とどめを一緒にっ！ラジャー！", "0", "0", "0", "0", "cv_xinxiya_22", "0", "0"},
[402125] = {402125, 10021, 27, 20, "0", "0", "被水沒過身體的感覺真糟糕……", "水沒したみたいで、気持ち悪いです……", "0", "0", "0", "0", "cv_xinxiya_23", "0", "0"},
[402126] = {402126, 10021, 28, 21, "0", "0", "要是能換成淋浴式的就好了。", "シャワーでもいいですか……", "0", "0", "0", "0", "cv_xinxiya_24", "0", "0"},
[402127] = {402127, 10021, 29, 21, "0", "0", "不用擔心我，過段時間我就會自己消失啦，所以不洗也無所謂。", "私のことなら気にしないで。そのうち消えるんだから、洗わなくてもいいよね。", "0", "0", "0", "0", "cv_xinxiya_25", "0", "0"},
[402128] = {402128, 10021, 30, 22, "0", "0", "小心！", "気をつけて！", "0", "0", "0", "0", "cv_xinxiya_26", "0", "0"},
[402129] = {402129, 10021, 31, 23, "0", "0", "我們應該很好就猜對了吧。", "私たちを當てるのは簡単だよね。", "0", "0", "0", "0", "cv_xinxiya_27", "0", "0"},
[402130] = {402130, 10021, 32, 24, "0", "0", "回答正確。", "正解です。", "0", "0", "0", "0", "cv_xinxiya_28", "0", "0"},
[402131] = {402131, 10021, 33, 25, "0", "0", "回答錯誤！", "はっずれー！", "0", "0", "0", "0", "cv_xinxiya_29", "0", "0"},
[402132] = {402132, 10021, 34, 26, "0", "0", "歡迎回來。", "お帰りなさい。", "0", "0", "0", "0", "cv_xinxiya_32", "0", "0"},
[402133] = {402133, 10021, 35, 27, "0", "0", "一起行動吧，辛米亞。", "シンミア、一緒に行くよ。", "0", "0", "0", "0", "cv_xinxiya_34", "0", "0"},
[402134] = {402134, 10021, 36, 28, "0", "0", "發揮出全部的實力吧，辛西婭。", "シンシア、実力を全部出そう。", "0", "0", "0", "0", "cv_xinxiya_35", "0", "0"},
[402135] = {402135, 10021, 37, 29, "0", "0", "同隊的夥伴都在這裏了。", "同じ部隊の仲間はみんなここに。", "0", "0", "0", "0", "cv_xinxiya_36", "0", "0"},
[402136] = {402136, 10021, 38, 30, "0", "0", "朋友多多益善~", "友達は多いに越したことないねー。", "0", "0", "0", "0", "cv_xinxiya_37", "0", "0"},
[402137] = {402137, 10021, 39, 31, "0", "0", "裝備多多益善。", "裝備は多いに越したことはありません。", "0", "0", "0", "0", "cv_xinxiya_38", "0", "0"},
[402138] = {402138, 10021, 40, 32, "0", "0", "一起去購物吧。", "一緒に買い物に。", "0", "0", "0", "0", "cv_xinxiya_39", "0", "0"},
[402139] = {402139, 10021, 41, 33, "0", "0", "需要更新個人資料嗎？", "個人プロフィールの更新ですか？", "0", "0", "0", "0", "cv_xinxiya_40", "0", "0"},
[402140] = {402140, 10021, 42, 34, "0", "0", "變更設置。", "設定を変更します。", "0", "0", "0", "0", "cv_xinxiya_41", "0", "0"},
[402141] = {402141, 10021, 43, 35, "0", "0", "收到的信件都在這裏了。", "メールはこちらです。", "0", "0", "0", "0", "cv_xinxiya_42", "0", "0"},
[402142] = {402142, 10021, 44, 36, "0", "0", "大家已經到齊了吧。", "全員到著したようです。", "0", "0", "0", "0", "cv_xinxiya_43", "0", "0"},
[402143] = {402143, 10021, 45, 37, "0", "0", "交給我們吧。", "私たちに任せて。", "0", "0", "0", "0", "cv_xinxiya_44", "0", "0"},
[402200] = {402200, 10022, 1, 1, "0", "0", "蒼霧殘響", "0", "0", "0", "0", "0", "cv_fafnir_32", "0", "0"},
[402201] = {402201, 10022, 2, 2, "0", "0", "無聊的工作。", "0", "0", "0", "0", "0", "cv_fafnir_2", "0", "0"},
[402202] = {402202, 10022, 3, 3, "0", "0", "我的名字是法芙娜，沒錯，和傳說中的惡龍同名。", "0", "0", "0", "0", "0", "cv_fafnir_1", "0", "0"},
[402203] = {402203, 10022, 4, 4, "0", "idle", "嗯，你的事蹟我多少也聽說過一些，只要跟著你就能遇到更強的對手吧？", "0", "0", "0", "0", "0", "cv_fafnir_3", "0", "0"},
[402204] = {402204, 10022, 5, 4, "0", "idle", "怎麼了？被我的機甲嚇到了嗎？放心好了，只要不是在戰鬥中我還是可以控制住它的。", "0", "0", "0", "0", "0", "cv_fafnir_4", "0", "0"},
[402205] = {402205, 10022, 6, 4, "0", "idle", "伊莎貝拉，她的戰鬥方式還是太保守了……", "0", "0", "0", "0", "0", "cv_fafnir_29", "0", "0"},
[402206] = {402206, 10022, 7, 5, "1_》_0_0.8", "level1", "戰鬥時我隨時都有可能陷入狂暴狀態，給你個建議，離我遠一點。", "0", "0", "0", "0", "0", "cv_fafnir_30", "0", "0"},
[402207] = {402207, 10022, 8, 5, "1_》_0_0.8", "level1", "我臉上的印記很難看嗎？如果看不慣的話還是離我遠些吧。", "0", "0", "0", "0", "0", "cv_fafnir_5", "0", "0"},
[402208] = {402208, 10022, 9, 5, "1_》_100_1.5", "level2", "早晚有一天我的理智也會被心中的惡龍完全吞噬掉吧。", "0", "0", "0", "0", "0", "cv_fafnir_6", "0", "0"},
[402209] = {402209, 10022, 10, 5, "1_》_500_2", "level3", "無論如何都不會讓我走到那一步？這種像是要保護我的承諾還真是好笑，明明我該保護你才對吧。但是，並不討厭……", "0", "0", "0", "0", "0", "cv_fafnir_7", "0", "0"},
[402210] = {402210, 10022, 11, 5, "1_》_1000_2.5", "level4", "是嗎，我迄今為止所背負的命運，惡意，以及名為法芙娜的人生已經結束了啊。但讓我現在就拋下它們還為時過早，它們是我戰鬥與抗爭下去的武器……至少在結束這場戰爭前，還是像往常那樣和我相處吧。", "0", "0", "0", "0", "0", "cv_fafnir_8", "0", "0"},
[402211] = {402211, 10022, 12, 6, "0", "0", "哦？這是給我的嗎？", "0", "0", "0", "0", "0", "cv_fafnir_9", "0", "0"},
[402212] = {402212, 10022, 13, 7, "0", "0", "突破瓶頸了啊。", "0", "0", "0", "0", "0", "cv_fafnir_10", "0", "0"},
[402213] = {402213, 10022, 14, 8, "0", "0", "讓那些原罪見識下抵達了巔峰的我吧，沒錯，現在就出擊吧！", "0", "0", "0", "0", "0", "cv_fafnir_11", "0", "0"},
[402214] = {402214, 10022, 15, 9, "0", "0", "真想趕快試試手啊。", "0", "0", "0", "0", "0", "cv_fafnir_12", "0", "0"},
[402215] = {402215, 10022, 16, 10, "0", "0", "那個傢伙是我的獵物。", "0", "0", "0", "0", "0", "cv_fafnir_13", "0", "0"},
[402216] = {402216, 10022, 17, 11, "0", "0", "還沒有結束，更強的傢伙一定還藏在某處。", "0", "0", "0", "0", "0", "cv_fafnir_14", "0", "0"},
[402217] = {402217, 10022, 18, 12, "0", "0", "真是無趣的敵人。", "0", "0", "0", "0", "0", "cv_fafnir_15", "0", "0"},
[402218] = {402218, 10022, 19, 13, "0", "0", "真是有趣的戰鬥啊，但還遠遠沒法讓我滿足。", "0", "0", "0", "0", "0", "cv_fafnir_16", "0", "0"},
[402219] = {402219, 10022, 20, 14, "0", "0", "就此毀滅也好。", "0", "0", "0", "0", "0", "cv_fafnir_17", "0", "0"},
[402220] = {402220, 10022, 21, 15, "0", "0", "還不夠！", "0", "0", "0", "0", "0", "cv_fafnir_19", "0", "0"},
[402221] = {402221, 10022, 23, 16, "0", "0", "嗬啊！", "0", "0", "0", "0", "0", "cv_fafnir_18", "0", "0"},
[402222] = {402222, 10022, 26, 19, "0", "0", "不可能…我還沒有…還沒有盡興啊……", "0", "0", "0", "0", "0", "cv_fafnir_20", "0", "0"},
[402223] = {402223, 10022, 24, 17, "0", "0", "真不錯。", "0", "0", "0", "0", "0", "cv_fafnir_21", "0", "0"},
[402224] = {402224, 10022, 25, 18, "0", "0", "就讓你們見識一下吧——惡龍的力量！", "0", "0", "0", "0", "0", "cv_fafnir_45", "0", "0"},
[402225] = {402225, 10022, 27, 20, "0", "0", "剛好，我需要冷靜一下。", "0", "0", "0", "0", "0", "cv_fafnir_22", "0", "0"},
[402226] = {402226, 10022, 28, 21, "0", "0", "心中的憤怒，都化作水蒸氣了啊。", "0", "0", "0", "0", "0", "cv_fafnir_23", "0", "0"},
[402227] = {402227, 10022, 29, 21, "0", "0", "請不要一直盯著我臉上的印記……", "0", "0", "0", "0", "0", "cv_fafnir_24", "0", "0"},
[402228] = {402228, 10022, 30, 22, "0", "0", "哦？", "0", "0", "0", "0", "0", "cv_fafnir_25", "0", "0"},
[402229] = {402229, 10022, 31, 23, "0", "0", "可以跳過這個環節嗎？", "0", "0", "0", "0", "0", "cv_fafnir_26", "0", "0"},
[402230] = {402230, 10022, 32, 24, "0", "0", "嗯，還算可以吧。", "0", "0", "0", "0", "0", "cv_fafnir_27", "0", "0"},
[402231] = {402231, 10022, 33, 25, "0", "0", "毫無意義。", "0", "0", "0", "0", "0", "cv_fafnir_28", "0", "0"},
[402232] = {402232, 10022, 34, 26, "0", "0", "啊，你回來得還真是早啊。", "0", "0", "0", "0", "0", "cv_fafnir_31", "0", "0"},
[402233] = {402233, 10022, 35, 27, "0", "0", "你能聽到嗎？遠處傳來的咆哮聲。", "0", "0", "0", "0", "0", "cv_fafnir_33", "0", "0"},
[402234] = {402234, 10022, 36, 28, "0", "0", "無論對手是誰都不要留情。", "0", "0", "0", "0", "0", "cv_fafnir_34", "0", "0"},
[402235] = {402235, 10022, 37, 29, "0", "0", "並肩作戰的大家嗎？", "0", "0", "0", "0", "0", "cv_fafnir_35", "0", "0"},
[402236] = {402236, 10022, 38, 30, "0", "0", "招募同伴嗎？", "0", "0", "0", "0", "0", "cv_fafnir_36", "0", "0"},
