[402242] = {402242, 10022, 44, 36, "0", "0", "你還挺受歡迎的嘛。", "0", "0", "0", "0", "0", "cv_fafnir_42", "0", "0"},
[402243] = {402243, 10022, 45, 37, "0", "0", "瞭解。", "0", "0", "0", "0", "0", "cv_fafnir_43", "0", "0"},
[402300] = {402300, 10023, 1, 1, "0", "0", "蒼霧殘響嗼。", "0", "0", "0", "0", "0", "cv_mo_1", "0", "0"},
[402301] = {402301, 10023, 2, 2, "0", "0", "這副繁榮的景象，曾幾何時在埃塔星上也看見過。", "0", "0", "0", "0", "0", "cv_mo_2", "0", "0"},
[402302] = {402302, 10023, 3, 3, "0", "0", "您就是領航？比我想像要年輕好多嗼。我是摩，是位“牧者”，簡單來說就是照顧小孩子的職業嗼。", "0", "0", "0", "0", "0", "cv_mo_3", "0", "0"},
[402303] = {402303, 10023, 4, 4, "0", "idle", "這樣看領航真的好小，小得像個孩子……不，應該說更像是胚胎嗼。", "0", "0", "0", "0", "0", "cv_mo_4", "0", "0"},
[402304] = {402304, 10023, 5, 4, "0", "idle", "我這個樣子不會嚇到別人嗎？我還是一動不動裝成雕像好了嗼。", "0", "0", "0", "0", "0", "cv_mo_5", "0", "0"},
[402305] = {402305, 10023, 6, 4, "0", "idle", "銀和渠每天都在為族人的事情忙東忙西，相比之下我這個年長者是不是悠閒過頭了嗼？這也是沒辦法的事，誰讓現在沒有孩子讓我照顧呢。", "0", "0", "0", "0", "0", "cv_mo_6", "0", "0"},
[402306] = {402306, 10023, 7, 5, "1_》_0_0.8", "level1", "年輕的時候也想過換個工作，比如“歌手”、“偶像”。但還是放不下那些小崽子們，一轉眼也已經這個年紀了，換算成地球人年齡的話差不多有……24歲？", "0", "0", "0", "0", "0", "cv_mo_7", "0", "0"},
[402307] = {402307, 10023, 8, 5, "1_》_0_0.8", "level1", "唔……你就別像孩子一樣調皮了嗼。", "0", "0", "0", "0", "0", "cv_mo_8", "0", "0"},
[402308] = {402308, 10023, 9, 5, "1_》_100_1.5", "level2", "為什嗼要做駕駛員？因為找不到其他工作了嗼。“牧者”是負責照顧孩子的職業，可是你看埃塔人居住地哪裡還有埃塔人的孩子嗼。", "0", "0", "0", "0", "0", "cv_mo_9", "0", "0"},
[402309] = {402309, 10023, 10, 5, "1_》_500_2", "level3", "領航應該有很多事要忙吧，不用特地把時間浪費在我一個閒人身上嗼。我不是在趕你走啦……唔……其實你能花時間陪我我也是很開心的嗼。", "0", "0", "0", "0", "0", "cv_mo_10", "0", "0"},
[402310] = {402310, 10023, 11, 5, "1_》_1000_2.5", "level4", "地球人繁衍的方法和埃塔人完全不一樣嗼。這或許能解決埃塔人目前遇到的難題。領航能不能教教我嗼？就當是為埃塔人種族的延續做貢獻了嗼。", "0", "0", "0", "0", "0", "cv_mo_11", "0", "0"},
[402311] = {402311, 10023, 12, 6, "0", "0", "又變老了嗼。", "0", "0", "0", "0", "0", "cv_mo_12", "0", "0"},
[402312] = {402312, 10023, 13, 7, "0", "0", "要變成金光閃閃的偶像了嗼。", "0", "0", "0", "0", "0", "cv_mo_13", "0", "0"},
[402313] = {402313, 10023, 14, 8, "0", "0", "我終於知道我真心想要的了嗼。", "0", "0", "0", "0", "0", "cv_mo_14", "0", "0"},
[402314] = {402314, 10023, 15, 9, "0", "0", "派得上用處了嗼。", "0", "0", "0", "0", "0", "cv_mo_15", "0", "0"},
[402315] = {402315, 10023, 16, 10, "0", "0", "小孩子都退後，摩來了嗼。", "0", "0", "0", "0", "0", "cv_mo_16", "0", "0"},
[402316] = {402316, 10023, 17, 11, "0", "0", "大家都活著就好嗼。", "0", "0", "0", "0", "0", "cv_mo_17", "0", "0"},
[402317] = {402317, 10023, 18, 12, "0", "0", "我應該再加把勁的嗼。", "0", "0", "0", "0", "0", "cv_mo_18", "0", "0"},
[402318] = {402318, 10023, 19, 13, "0", "0", "真是沒用呢嗼。", "0", "0", "0", "0", "0", "cv_mo_19", "0", "0"},
[402319] = {402319, 10023, 20, 14, "0", "0", "我不是個稱職的“牧者”嗼。", "0", "0", "0", "0", "0", "cv_mo_20", "0", "0"},
[402320] = {402320, 10023, 21, 15, "0", "0", "就這樣安睡吧。", "0", "0", "0", "0", "0", "cv_mo_21", "0", "0"},
[402321] = {402321, 10023, 23, 16, "0", "0", "要保護她們嗼。", "0", "0", "0", "0", "0", "cv_mo_23", "0", "0"},
[402322] = {402322, 10023, 26, 19, "0", "0", "盡力了嗼。", "0", "0", "0", "0", "0", "cv_mo_26", "0", "0"},
[402323] = {402323, 10023, 24, 17, "0", "0", "還不夠。", "0", "0", "0", "0", "0", "cv_mo_24", "0", "0"},
[402324] = {402324, 10023, 25, 18, "0", "0", "迷路的羔羊們，小心藏在黑暗中的狼。", "0", "0", "0", "0", "0", "cv_mo_25", "0", "0"},
[402325] = {402325, 10023, 27, 20, "0", "0", "還有這種好地方嗼。", "0", "0", "0", "0", "0", "cv_mo_27", "0", "0"},
[402326] = {402326, 10023, 28, 21, "0", "0", "真是舒服嗼，乾脆以後都住這裡好了嗼。", "0", "0", "0", "0", "0", "cv_mo_28", "0", "0"},
[402327] = {402327, 10023, 29, 21, "0", "0", "最近的毛髮有些乾燥分叉嗼，不知道是不是因為太久沒像這樣清理了嗼。", "0", "0", "0", "0", "0", "cv_mo_29", "0", "0"},
[402328] = {402328, 10023, 30, 22, "0", "0", "這是什麼嗼？", "0", "0", "0", "0", "0", "cv_mo_30", "0", "0"},
[402329] = {402329, 10023, 31, 23, "0", "0", "好像哄小孩的遊戲嗼。", "0", "0", "0", "0", "0", "cv_mo_31", "0", "0"},
[402330] = {402330, 10023, 32, 24, "0", "0", "獎勵你一個擁抱嗼。", "0", "0", "0", "0", "0", "cv_mo_32", "0", "0"},
[402331] = {402331, 10023, 33, 25, "0", "0", "沒關係，下次再努力嗼。", "0", "0", "0", "0", "0", "cv_mo_33", "0", "0"},
[402332] = {402332, 10023, 34, 26, "0", "0", "今天的工作終於做完了嗎？要好好休息嗼。", "0", "0", "0", "0", "0", "cv_mo_34", "0", "0"},
[402333] = {402333, 10023, 35, 27, "0", "0", "又要出戰了嗼？", "0", "0", "0", "0", "0", "cv_mo_35", "0", "0"},
[402334] = {402334, 10023, 36, 28, "0", "0", "大家都很有活力嗼。", "0", "0", "0", "0", "0", "cv_mo_36", "0", "0"},
[402335] = {402335, 10023, 37, 29, "0", "0", "領航身邊的異性還真不少嗼。", "0", "0", "0", "0", "0", "cv_mo_37", "0", "0"},
[402336] = {402336, 10023, 38, 30, "0", "0", "人類還真是興旺呢。", "0", "0", "0", "0", "0", "cv_mo_38", "0", "0"},
[402337] = {402337, 10023, 39, 31, "0", "0", "我這身衣服就不用換了嗼。", "0", "0", "0", "0", "0", "cv_mo_39", "0", "0"},
[402338] = {402338, 10023, 40, 32, "0", "0", "有喜歡的東西嗎？嗼。", "0", "0", "0", "0", "0", "cv_mo_40", "0", "0"},
