[402500] = {402500, 10025, 1, 1, "0", "0", "蒼霧殘響！", "0", "0", "0", "0", "0", "cv_melu_32", "0", "0"},
[402501] = {402501, 10025, 2, 2, "0", "0", "我還是想要更自由一點啊......", "0", "0", "0", "0", "0", "cv_melu_2", "0", "0"},
[402502] = {402502, 10025, 3, 3, "0", "0", "我是梅爾。你就是那個多瑙特別聯合部隊的領航？比我想像中的要瘦弱一點啊。", "0", "0", "0", "0", "0", "cv_melu_1", "0", "0"},
[402503] = {402503, 10025, 4, 4, "0", "idle", "喂，我們什麼時候才能出擊啊，稍微有些無聊了。", "0", "0", "0", "0", "0", "cv_melu_3", "0", "0"},
[402504] = {402504, 10025, 5, 4, "0", "idle", "哎？我的聲音太大了？沒辦法，身體變得這麼大之後我也沒辦法啊。", "0", "0", "0", "0", "0", "cv_melu_4", "0", "0"},
[402505] = {402505, 10025, 6, 4, "0", "idle", "喂，可以聽我稍微抱怨下嗎？雖說我並沒有指望能和大家相處得多好，但是法芙娜那個傢夥也太過分了吧。戰鬥的時候完全沒法和她好好配合......", "0", "0", "0", "0", "0", "cv_melu_29", "0", "0"},
[402506] = {402506, 10025, 7, 5, "1_》_0_0.8", "level1", "如果有可能的話，我希望能夠回到過去...哪怕只是再見他們一面也好......", "0", "0", "0", "0", "0", "cv_melu_30", "0", "0"},
[402507] = {402507, 10025, 8, 5, "1_》_0_0.8", "level1", "哈？找我有什麼事嗎？如果要出擊的話我隨時都能奉陪。", "0", "0", "0", "0", "0", "cv_melu_5", "0", "0"},
[402508] = {402508, 10025, 9, 5, "1_》_100_1.5", "level2", "哎...你已經知道那些事了吧。不過不用同情我，在這個時代像我一樣的人還有很多很多，這並不是什麼大不了的事...並不是...", "0", "0", "0", "0", "0", "cv_melu_6", "0", "0"},
[402509] = {402509, 10025, 10, 5, "1_》_500_2", "level3", "我很後悔，如果當年沒有離開家的話，說不定就能多陪家人一段時間了。但即便當時的我在現場，應該也改變不了什麼......這一切都因為我非常弱小吧，哪怕是現在的我，也非常的弱小......", "0", "0", "0", "0", "0", "cv_melu_7", "0", "0"},
[402510] = {402510, 10025, 11, 5, "1_》_1000_2.5", "level4", "所謂的自由也許只是一個偽命題，哪怕是解決了所有的原罪我們依舊也無法擺脫死亡的詛咒。但如果真的有永遠不會消逝的生命，那大概也非常痛苦吧。......請不要在意，還請繼續前進吧，我會一直陪在你身邊的。", "0", "0", "0", "0", "0", "cv_melu_8", "0", "0"},
[402511] = {402511, 10025, 12, 6, "0", "0", "噢！", "0", "0", "0", "0", "0", "cv_melu_9", "0", "0"},
[402512] = {402512, 10025, 13, 7, "0", "0", "噢噢噢噢，這種感覺真暢快啊~", "0", "0", "0", "0", "0", "cv_melu_10", "0", "0"},
[402513] = {402513, 10025, 14, 8, "0", "0", "這樣一來應該就沒有什麼原罪可以阻擋我了吧，喂，一起去把它們都給砍碎吧！", "0", "0", "0", "0", "0", "cv_melu_11", "0", "0"},
[402514] = {402514, 10025, 15, 9, "0", "0", "嘿咻~感覺武器變重了呢。好啊，就得這樣~", "0", "0", "0", "0", "0", "cv_melu_12", "0", "0"},
[402515] = {402515, 10025, 16, 10, "0", "0", "接下來就讓你們見識一下這套機甲的威力吧。", "0", "0", "0", "0", "0", "cv_melu_13", "0", "0"},
[402516] = {402516, 10025, 17, 11, "0", "0", "真是暢快啊~", "0", "0", "0", "0", "0", "cv_melu_14", "0", "0"},
[402517] = {402517, 10025, 18, 12, "0", "0", "雖然還有些小問題啊，但贏了就是贏了。", "0", "0", "0", "0", "0", "cv_melu_15", "0", "0"},
[402518] = {402518, 10025, 19, 13, "0", "0", "完全沒法放開手腳，真是討厭啊......", "0", "0", "0", "0", "0", "cv_melu_16", "0", "0"},
[402519] = {402519, 10025, 20, 14, "0", "0", "可惡......又被這套機甲奪取理智了嗎.......", "0", "0", "0", "0", "0", "cv_melu_17", "0", "0"},
