[402543] = {402543, 10025, 45, 37, "0", "0", "交給我吧！", "0", "0", "0", "0", "0", "cv_melu_43", "0", "0"},
[402600] = {402600, 10026, 1, 1, "0", "0", "蒼~霧~殘~響", "0", "0", "0", "0", "0", "cv_nasijia_1", "0", "0"},
[402601] = {402601, 10026, 2, 2, "0", "0", "我可不保證會發生什麼事哦~", "0", "0", "0", "0", "0", "cv_nasijia_2", "0", "0"},
[402602] = {402602, 10026, 3, 3, "0", "0", "吼呀，好年輕的領航呀，還以為會是個滿身汗味的臭大叔呢。", "0", "0", "0", "0", "0", "cv_nasijia_3", "0", "0"},
[402603] = {402603, 10026, 4, 4, "0", "idle", "你要不也來這坐著吧，反正看你也很閑呢。", "0", "0", "0", "0", "0", "cv_nasijia_4", "0", "0"},
[402604] = {402604, 10026, 5, 4, "0", "idle", "突然想到件有趣的事，想知道的話就跪下來求我吧。", "0", "0", "0", "0", "0", "cv_nasijia_5", "0", "0"},
[402605] = {402605, 10026, 6, 4, "0", "idle", "我和隊伍的其他駕駛員當然不一樣了，只是掛名在這而已，你不會這都弄不清楚吧，笨蛋領航。", "0", "0", "0", "0", "0", "cv_nasijia_6", "0", "0"},
[402606] = {402606, 10026, 7, 5, "1_》_0_0.8", "level1", "我可要呼叫警備了哦。", "0", "0", "0", "0", "0", "cv_nasijia_7", "0", "0"},
[402607] = {402607, 10026, 8, 5, "1_》_0_0.8", "level1", "在這大庭廣眾之下，領航不會想對我做那種事情吧。", "0", "0", "0", "0", "0", "cv_nasijia_8", "0", "0"},
[402608] = {402608, 10026, 9, 5, "1_》_100_1.5", "level2", "誒~原來領航比我大這麼多嗎？外表上完全看不出呢。一下子變成大叔了呢，領航大叔。", "0", "0", "0", "0", "0", "cv_nasijia_9", "0", "0"},
[402609] = {402609, 10026, 10, 5, "1_》_500_2", "level3", "聽說領航被人惡作劇了呀，嘻嘻。加了辣椒醬的果汁一飲而盡的樣子真是太好笑了……當然不是我做的啦，我可是一直在這站崗呢，笨蛋大叔。", "0", "0", "0", "0", "0", "cv_nasijia_10", "0", "0"},
[402610] = {402610, 10026, 11, 5, "1_》_1000_2.5", "level4", "明天晚上有空嗎?我有些話想對領航說……或者現在……領航，我喜……喜……啊哈哈哈，上當了吧，你的心剛才跳得好快哦。不會真以為我會向你表白吧，笨蛋大叔。", "0", "0", "0", "0", "0", "cv_nasijia_11", "0", "0"},
[402611] = {402611, 10026, 12, 6, "0", "0", "才這點就想打發我嗎？", "0", "0", "0", "0", "0", "cv_nasijia_12", "0", "0"},
[402612] = {402612, 10026, 13, 7, "0", "0", "這還差不多。", "0", "0", "0", "0", "0", "cv_nasijia_13", "0", "0"},
[402613] = {402613, 10026, 14, 8, "0", "0", "怎麼樣，被我的強大給嚇到了吧。", "0", "0", "0", "0", "0", "cv_nasijia_14", "0", "0"},
[402614] = {402614, 10026, 15, 9, "0", "0", "感覺肩膀輕鬆了不少。", "0", "0", "0", "0", "0", "cv_nasijia_15", "0", "0"},
[402615] = {402615, 10026, 16, 10, "0", "0", "好多敵人哦，我好害怕哦。", "0", "0", "0", "0", "0", "cv_nasijia_16", "0", "0"},
[402616] = {402616, 10026, 17, 11, "0", "0", "還沒怎麼用力就倒下了，真弱。", "0", "0", "0", "0", "0", "cv_nasijia_17", "0", "0"},
[402617] = {402617, 10026, 18, 12, "0", "0", "我只是稍微放放水而已。", "0", "0", "0", "0", "0", "cv_nasijia_18", "0", "0"},
[402618] = {402618, 10026, 19, 13, "0", "0", "這樣都贏不了我。", "0", "0", "0", "0", "0", "cv_nasijia_19", "0", "0"},
[402619] = {402619, 10026, 20, 14, "0", "0", "這可不是我的問題。", "0", "0", "0", "0", "0", "cv_nasijia_20", "0", "0"},
[402620] = {402620, 10026, 21, 15, "0", "0", "果然雜魚就是雜魚。", "0", "0", "0", "0", "0", "cv_nasijia_21", "0", "0"},
[402621] = {402621, 10026, 23, 16, "0", "0", "去死吧，雜魚。", "0", "0", "0", "0", "0", "cv_nasijia_23", "0", "0"},
[402622] = {402622, 10026, 26, 19, "0", "0", "哦？沒想到還挺堅強的嘛，雜魚。", "0", "0", "0", "0", "0", "cv_nasijia_24", "0", "0"},
[402623] = {402623, 10026, 24, 17, "0", "0", "老實一點，雜魚就要有雜魚的覺悟。", "0", "0", "0", "0", "0", "cv_nasijia_25", "0", "0"},
[402624] = {402624, 10026, 25, 18, "0", "0", "肚子有些不舒服，先撤退了。", "0", "0", "0", "0", "0", "cv_nasijia_26", "0", "0"},
[402625] = {402625, 10026, 27, 20, "0", "0", "還有這種地方？", "0", "0", "0", "0", "0", "cv_nasijia_27", "0", "0"},
[402626] = {402626, 10026, 28, 21, "0", "0", "你就只會看著嗎？", "0", "0", "0", "0", "0", "cv_nasijia_28", "0", "0"},
[402627] = {402627, 10026, 29, 21, "0", "0", "很想觸碰吧，我的身體。", "0", "0", "0", "0", "0", "cv_nasijia_29", "0", "0"},
[402628] = {402628, 10026, 30, 22, "0", "0", "誰允許你亂碰了。", "0", "0", "0", "0", "0", "cv_nasijia_30", "0", "0"},
[402629] = {402629, 10026, 31, 23, "0", "0", "以大叔的智力來說是不是有點困難呢？", "0", "0", "0", "0", "0", "cv_nasijia_31", "0", "0"},
[402630] = {402630, 10026, 32, 24, "0", "0", "哈，勉強算及格吧。", "0", "0", "0", "0", "0", "cv_nasijia_32", "0", "0"},
[402631] = {402631, 10026, 33, 25, "0", "0", "笨蛋！白癡！", "0", "0", "0", "0", "0", "cv_nasijia_33", "0", "0"},
[402632] = {402632, 10026, 34, 26, "0", "0", "又孤零零一個人來向我尋求安慰了嗎？", "0", "0", "0", "0", "0", "cv_nasijia_34", "0", "0"},
[402633] = {402633, 10026, 35, 27, "0", "0", "這種雜魚還需要我出手嗎？", "0", "0", "0", "0", "0", "cv_nasijia_35", "0", "0"},
[402634] = {402634, 10026, 36, 28, "0", "0", "憑什麼要跟她們打？", "0", "0", "0", "0", "0", "cv_nasijia_36", "0", "0"},
[402635] = {402635, 10026, 37, 29, "0", "0", "她們是誰！", "0", "0", "0", "0", "0", "cv_nasijia_37", "0", "0"},
[402636] = {402636, 10026, 38, 30, "0", "0", "真是精力旺盛呢。", "0", "0", "0", "0", "0", "cv_nasijia_38", "0", "0"},
[402637] = {402637, 10026, 39, 31, "0", "0", "都是些便宜貨。", "0", "0", "0", "0", "0", "cv_nasijia_39", "0", "0"},
[402638] = {402638, 10026, 40, 32, "0", "0", "給我買根棒棒糖吧。", "0", "0", "0", "0", "0", "cv_nasijia_40", "0", "0"},
[402639] = {402639, 10026, 41, 33, "0", "0", "哎呀，發現有趣的東西了。", "0", "0", "0", "0", "0", "cv_nasijia_41", "0", "0"},
[402640] = {402640, 10026, 42, 34, "0", "0", "我當然知道這是什麼。", "0", "0", "0", "0", "0", "cv_nasijia_42", "0", "0"},
[402641] = {402641, 10026, 43, 35, "0", "0", "真可憐啊，一封情書都沒有呢。", "0", "0", "0", "0", "0", "cv_nasijia_43", "0", "0"},
[402642] = {402642, 10026, 44, 36, "0", "0", "有我陪你說話還不夠嗎？真實貪婪呢。", "0", "0", "0", "0", "0", "cv_nasijia_44", "0", "0"},
[402643] = {402643, 10026, 45, 37, "0", "0", "這個。", "0", "0", "0", "0", "0", "cv_nasijia_45", "0", "0"},
[402700] = {402700, 10027, 1, 1, "0", "0", "蒼霧殘響", "0", "0", "0", "0", "0", "cv_alvitr_1", "0", "0"},
[402701] = {402701, 10027, 2, 2, "0", "0", "作為我的領航，如果盡做些無趣的事，那會是對我的侮辱。", "0", "0", "0", "0", "0", "cv_alvitr_2", "0", "0"},
[402702] = {402702, 10027, 3, 3, "0", "0", "這次與我合作的對像是你嗎？呵，多瑙的領航，竭盡全力跟上我的步伐吧。", "0", "0", "0", "0", "0", "cv_alvitr_3", "0", "0"},
[402703] = {402703, 10027, 4, 4, "0", "idle", "真是遺憾，艾吉斯之中能與我並肩而戰的人，一個也沒有呢。", "0", "0", "0", "0", "0", "cv_alvitr_4", "0", "0"},
[402704] = {402704, 10027, 5, 4, "0", "idle", "貧瘠而無力的人類，只需要臥在地上瞻望我偉大的背影即可。我會帶來勝利，帶來不止一次的勝利，最終將原罪盡數屠戮。", "0", "0", "0", "0", "0", "cv_alvitr_5", "0", "0"},
[402705] = {402705, 10027, 6, 4, "0", "idle", "天真的潔蘿，將希望寄託在他人身上，甘心成為凡人的基石...不，應該說是墊腳石。我可不會像她那麼幼稚...我將成為人類的領袖。到時候，你就好好輔佐我吧，領航。", "0", "0", "0", "0", "0", "cv_alvitr_6", "0", "0"},
[402706] = {402706, 10027, 7, 5, "1_》_0_0.8", "level1", "人類是沒有肚量的生物，對超出常識的事物只會心懷恐懼。無妨，引導無能的人類前進，本就是我的使命。", "0", "0", "0", "0", "0", "cv_alvitr_7", "0", "0"},
[402707] = {402707, 10027, 8, 5, "1_》_0_0.8", "level1", "怎麼，你很驚訝我是一名科學官嗎？掌握區區人類的淺薄學識，對我來說不是什麼難事。", "0", "0", "0", "0", "0", "cv_alvitr_8", "0", "0"},
[402708] = {402708, 10027, 9, 5, "1_》_100_1.5", "level2", "史蒂芬妮為什麼會如此信任你？我是為了弄清楚這件事才沒從你身邊離開的。盡可能滿足我對你的期待吧，人類。", "0", "0", "0", "0", "0", "cv_alvitr_9", "0", "0"},
[402709] = {402709, 10027, 10, 5, "1_》_500_2", "level3", "史蒂芬妮和我聊過這條世界線上人類的結局。我不會同情人類...不過，人類之中也不盡是些無藥可救的人，比如說...咳，總之，只是讓我擔負起拯救世界的責任，那還是值得一試的。", "0", "0", "0", "0", "0", "cv_alvitr_10", "0", "0"},
[402710] = {402710, 10027, 11, 5, "1_》_1000_2.5", "level4", "我會陪你走到這個世界的結局，無論它最終會是怎樣一副模樣。你問為什麼？呵呵，這當然是我對你這名人類的最大認可，是對你兢兢業業為我服務的獎賞。好了，接下來或短暫或漫長的時光，就讓我們好好相處吧，領航。", "0", "0", "0", "0", "0", "cv_alvitr_11", "0", "0"},
[402711] = {402711, 10027, 12, 6, "0", "0", "很好，繼續取悅我吧。", "0", "0", "0", "0", "0", "cv_alvitr_12", "0", "0"},
[402712] = {402712, 10027, 13, 7, "0", "0", "還差得遠呢。", "0", "0", "0", "0", "0", "cv_alvitr_13", "0", "0"},
[402713] = {402713, 10027, 14, 8, "0", "0", "呵呵呵....多瑙的領航，我認可了為我做到這一步的你。放聲大笑吧，理智淹沒在狂熱中吧，這是凡人能夠得到的最大的殊榮。", "0", "0", "0", "0", "0", "cv_alvitr_14", "0", "0"},
[402714] = {402714, 10027, 15, 9, "0", "0", "繼續努力吧。", "0", "0", "0", "0", "0", "cv_alvitr_15", "0", "0"},
[402715] = {402715, 10027, 16, 10, "0", "0", "螻蟻，準備接受審判吧。", "0", "0", "0", "0", "0", "cv_alvitr_16", "0", "0"},
[402716] = {402716, 10027, 17, 11, "0", "0", "為此歡呼吧，這是你我攜手帶來的勝利。", "0", "0", "0", "0", "0", "cv_alvitr_17", "0", "0"},
[402717] = {402717, 10027, 18, 12, "0", "0", "無聊的對手。", "0", "0", "0", "0", "0", "cv_alvitr_18", "0", "0"},
[402718] = {402718, 10027, 19, 13, "0", "0", "姑且承認...這次的敵人給我帶來了點困擾。", "0", "0", "0", "0", "0", "cv_alvitr_19", "0", "0"},
[402719] = {402719, 10027, 20, 14, "0", "0", "居然被這種對手打敗了...真是丟人。", "0", "0", "0", "0", "0", "cv_alvitr_20", "0", "0"},
[402720] = {402720, 10027, 21, 15, "0", "0", "消失吧，真礙眼。", "0", "0", "0", "0", "0", "cv_alvitr_22", "0", "0"},
[402721] = {402721, 10027, 23, 16, "0", "0", "無聊。", "0", "0", "0", "0", "0", "cv_alvitr_21", "0", "0"},
[402722] = {402722, 10027, 26, 19, "0", "0", "稍微動點真格吧。", "0", "0", "0", "0", "0", "cv_alvitr_24", "0", "0"},
[402723] = {402723, 10027, 24, 17, "0", "0", "感到榮幸吧，因為我將賜予你們永恆的死亡！", "0", "0", "0", "0", "0", "cv_alvitr_25", "0", "0"},
[402724] = {402724, 10027, 25, 18, "0", "0", "呵呵，這次就到此為止吧。", "0", "0", "0", "0", "0", "cv_alvitr_23", "0", "0"},
[402725] = {402725, 10027, 27, 20, "0", "0", "想服侍我嗎？呵，我准許了。", "0", "0", "0", "0", "0", "cv_alvitr_26", "0", "0"},
[402726] = {402726, 10027, 28, 21, "0", "0", "誰允許你休息了？", "0", "0", "0", "0", "0", "cv_alvitr_27", "0", "0"},
[402727] = {402727, 10027, 29, 21, "0", "0", "允許你侍奉我，是對你一直以來辛苦工作的獎勵。", "0", "0", "0", "0", "0", "cv_alvitr_28", "0", "0"},
[402728] = {402728, 10027, 30, 22, "0", "0", "在大驚小怪什麼？", "0", "0", "0", "0", "0", "cv_alvitr_29", "0", "0"},
[402729] = {402729, 10027, 31, 23, "0", "0", "我的聲音，還有氣味，難道沒有深刻進你的靈魂嗎？", "0", "0", "0", "0", "0", "cv_alvitr_30", "0", "0"},
[402730] = {402730, 10027, 32, 24, "0", "0", "儘管是幼稚的把戲，但你表現得不錯。", "0", "0", "0", "0", "0", "cv_alvitr_31", "0", "0"},
[402731] = {402731, 10027, 33, 25, "0", "0", "連這種小事都做不好嗎？", "0", "0", "0", "0", "0", "cv_alvitr_32", "0", "0"},
[402732] = {402732, 10027, 34, 26, "0", "0", "真慢啊。既然沒出什麼事就趕緊回到自己的位置上吧，領航。", "0", "0", "0", "0", "0", "cv_alvitr_33", "0", "0"},
[402733] = {402733, 10027, 35, 27, "0", "0", "別命令我...走吧，去拯救這個殘破的世界。", "0", "0", "0", "0", "0", "cv_alvitr_34", "0", "0"},
[402734] = {402734, 10027, 36, 28, "0", "0", "我可沒有蹂躪弱者的惡趣味。", "0", "0", "0", "0", "0", "cv_alvitr_35", "0", "0"},
[402735] = {402735, 10027, 37, 29, "0", "0", "我的隊伍裡可不需要庸才。", "0", "0", "0", "0", "0", "cv_alvitr_36", "0", "0"},
[402736] = {402736, 10027, 38, 30, "0", "0", "無聊的流程。", "0", "0", "0", "0", "0", "cv_alvitr_37", "0", "0"},
[402737] = {402737, 10027, 39, 31, "0", "0", "拙劣的技術。", "0", "0", "0", "0", "0", "cv_alvitr_38", "0", "0"},
[402738] = {402738, 10027, 40, 32, "0", "0", "沒有能入眼的寶物呢。", "0", "0", "0", "0", "0", "cv_alvitr_39", "0", "0"},
[402739] = {402739, 10027, 41, 33, "0", "0", "謔，你還蠻有趣的。", "0", "0", "0", "0", "0", "cv_alvitr_40", "0", "0"},
[402740] = {402740, 10027, 42, 34, "0", "0", "真原始的方式。", "0", "0", "0", "0", "0", "cv_alvitr_41", "0", "0"},
[402741] = {402741, 10027, 43, 35, "0", "0", "盡是些無聊的內容。", "0", "0", "0", "0", "0", "cv_alvitr_42", "0", "0"},
[402742] = {402742, 10027, 44, 36, "0", "0", "盡情暢談吧。", "0", "0", "0", "0", "0", "cv_alvitr_43", "0", "0"},
[402743] = {402743, 10027, 45, 37, "0", "0", "嗯？", "0", "0", "0", "0", "0", "cv_alvitr_44", "0", "0"},
[402800] = {402800, 10028, 1, 1, "0", "0", "蒼霧殘響", "0", "0", "0", "0", "0", "cv_mojun_1", "0", "0"},
[402801] = {402801, 10028, 2, 2, "0", "0", "明君亦不可無賢，領航願意委任於我，我定不負所望。", "0", "0", "0", "0", "0", "cv_mojun_2", "0", "0"},
[402802] = {402802, 10028, 3, 3, "0", "0", "我名墨君，墨家學派當代掌門、機關工程學創立者兼教師。都說學海無涯，願我們能讓彼此受益良多，往後的相處中還請不吝賜教。", "0", "0", "0", "0", "0", "cv_mojun_3", "0", "0"},
[402803] = {402803, 10028, 4, 4, "0", "idle", "如此聳立，方覺自己原本何其渺小，而文明的造物何其宏大。", "0", "0", "0", "0", "0", "cv_mojun_4", "0", "0"},
[402804] = {402804, 10028, 5, 4, "0", "idle", "這裡的氣候與故鄉差別不大，人們待我也頗為熱情，唯一的遺憾是……吃不到桂花蛋了。", "0", "0", "0", "0", "0", "cv_mojun_5", "0", "0"},
[402805] = {402805, 10028, 6, 4, "0", "idle", "九州有句古語，“三人行，必有我師焉”。在制蜜人中，同伴們有許多值得我學習之處。", "0", "0", "0", "0", "0", "cv_mojun_6", "0", "0"},
[402806] = {402806, 10028, 7, 5, "1_》_0_0.8", "level1", "機巧多變，猶不及世相萬千……這是父親常掛嘴邊的一句格言。我出身九州，後又遠蹈薩哈拉與多瑙，也正是為求開拓視野，尋覓新機。", "0", "0", "0", "0", "0", "cv_mojun_7", "0", "0"},
[402807] = {402807, 10028, 8, 5, "1_》_0_0.8", "level1", "我的愛好？如機關裝置般玲瓏精巧的器物都不錯，玻璃藝品、機械鐘錶，還有塑膠模玩之類。唔……很意外嗎？我又不是古人。", "0", "0", "0", "0", "0", "cv_mojun_8", "0", "0"},
[402808] = {402808, 10028, 9, 5, "1_》_100_1.5", "level2", "雖然我在教務方面一向嚴苛，不過領航若有任何問題或想法，不用心存顧忌，只管向我傾說無妨。", "0", "0", "0", "0", "0", "cv_mojun_9", "0", "0"},
[402809] = {402809, 10028, 10, 5, "1_》_500_2", "level3", "將前沿科學應用於機關術，這項古老技藝才得以不被淘汰——我從其中領悟的道理是，自己須力爭進步，切不可墨守成規。所以領航……就再向我傳授些經驗吧？", "0", "0", "0", "0", "0", "cv_mojun_10", "0", "0"},
[402810] = {402810, 10028, 11, 5, "1_》_1000_2.5", "level4", "與你相處越久，我便越忍不住去想“嚴師出高徒”之外的教育方式……畢竟在你這裡，我切身體會到了溫柔也能很好地引領眾人。", "0", "0", "0", "0", "0", "cv_mojun_11", "0", "0"},
[402811] = {402811, 10028, 12, 6, "0", "0", "提升的感覺真不錯。", "0", "0", "0", "0", "0", "cv_mojun_12", "0", "0"},
[402812] = {402812, 10028, 13, 7, "0", "0", "精妙的裝置絕不只靠零件堆疊，我會比以往更加用心。", "0", "0", "0", "0", "0", "cv_mojun_13", "0", "0"},
[402813] = {402813, 10028, 14, 8, "0", "0", "領航的栽培也許能使朽木成材，這可不是恭維話。我會銘記此刻所感，並作為一名教師，將你的經驗、耐心與溫柔傳承下去。", "0", "0", "0", "0", "0", "cv_mojun_14", "0", "0"},
[402814] = {402814, 10028, 15, 9, "0", "0", "雕琢，方可成器。", "0", "0", "0", "0", "0", "cv_mojun_15", "0", "0"},
[402815] = {402815, 10028, 16, 10, "0", "0", "非攻非非戰。", "0", "0", "0", "0", "0", "cv_mojun_16", "0", "0"},
[402816] = {402816, 10028, 17, 11, "0", "0", "日有其躔，然命非天定。這場勝利由我們親手締造，值得為之雀躍。", "0", "0", "0", "0", "0", "cv_mojun_17", "0", "0"},
[402817] = {402817, 10028, 18, 12, "0", "0", "距磨合完美只差一步，還待共勉。", "0", "0", "0", "0", "0", "cv_mojun_18", "0", "0"},
[402818] = {402818, 10028, 19, 13, "0", "0", "斫木為鷂，須三年才成，我們不必氣餒。", "0", "0", "0", "0", "0", "cv_mojun_19", "0", "0"},
[402819] = {402819, 10028, 20, 14, "0", "0", "機關停轉，該仔細檢查一番了。", "0", "0", "0", "0", "0", "cv_mojun_20", "0", "0"},
[402820] = {402820, 10028, 21, 15, "0", "0", "崩解吧。", "0", "0", "0", "0", "0", "cv_mojun_21", "0", "0"},
[402821] = {402821, 10028, 23, 16, "0", "0", "以守為攻。", "0", "0", "0", "0", "0", "cv_mojun_22", "0", "0"},
[402822] = {402822, 10028, 24, 17, "0", "0", "天工開物。", "0", "0", "0", "0", "0", "cv_mojun_23", "0", "0"},
[402823] = {402823, 10028, 26, 19, "0", "0", "一次教訓……", "0", "0", "0", "0", "0", "cv_mojun_24", "0", "0"},
[402824] = {402824, 10028, 27, 20, "0", "0", "勞逸結合，至關重要。", "0", "0", "0", "0", "0", "cv_mojun_25", "0", "0"},
[402825] = {402825, 10028, 28, 21, "0", "0", "我心非木石，該享受的時候，自會好好享受的~", "0", "0", "0", "0", "0", "cv_mojun_26", "0", "0"},
[402826] = {402826, 10028, 29, 21, "0", "0", "領航如此沉默……莫非是在觀察我？咳咳，真希望你能將這份銳利的目光用在學習上。", "0", "0", "0", "0", "0", "cv_mojun_27", "0", "0"},
[402827] = {402827, 10028, 30, 22, "0", "0", "讓我見證一下吧。", "0", "0", "0", "0", "0", "cv_mojun_28", "0", "0"},
[402828] = {402828, 10028, 31, 23, "0", "0", "好的老師當熟知每一名學生。", "0", "0", "0", "0", "0", "cv_mojun_29", "0", "0"},
[402829] = {402829, 10028, 32, 24, "0", "0", "果然，我的期待沒錯。", "0", "0", "0", "0", "0", "cv_mojun_30", "0", "0"},
[402830] = {402830, 10028, 33, 25, "0", "0", "這樣……下次再加油吧。", "0", "0", "0", "0", "0", "cv_mojun_31", "0", "0"},
[402831] = {402831, 10028, 34, 26, "0", "0", "四季遞嬗，彷如機關運轉。", "0", "0", "0", "0", "0", "cv_mojun_32", "0", "0"},
[402832] = {402832, 10028, 35, 27, "0", "0", "開啟新的篇章吧。", "0", "0", "0", "0", "0", "cv_mojun_33", "0", "0"},
[402833] = {402833, 10028, 36, 28, "0", "0", "即便是演習，也不可懈怠。", "0", "0", "0", "0", "0", "cv_mojun_34", "0", "0"},
[402834] = {402834, 10028, 37, 29, "0", "0", "大家休息得怎麼樣了？", "0", "0", "0", "0", "0", "cv_mojun_35", "0", "0"},
[402835] = {402835, 10028, 38, 30, "0", "0", "新的學生嗎。", "0", "0", "0", "0", "0", "cv_mojun_36", "0", "0"},
[402836] = {402836, 10028, 39, 31, "0", "0", "從新裝備中汲取知識。", "0", "0", "0", "0", "0", "cv_mojun_37", "0", "0"},
[402837] = {402837, 10028, 40, 32, "0", "0", "交易也是一種流轉。", "0", "0", "0", "0", "0", "cv_mojun_38", "0", "0"},
[402838] = {402838, 10028, 41, 33, "0", "0", "有些好奇呢……", "0", "0", "0", "0", "0", "cv_mojun_39", "0", "0"},
[402839] = {402839, 10028, 42, 34, "0", "0", "細節，決定成敗。", "0", "0", "0", "0", "0", "cv_mojun_40", "0", "0"},
[402840] = {402840, 10028, 43, 35, "0", "0", "相信會是好消息。", "0", "0", "0", "0", "0", "cv_mojun_41", "0", "0"},
[402841] = {402841, 10028, 44, 36, "0", "0", "我也喜歡通過聊天來放鬆。", "0", "0", "0", "0", "0", "cv_mojun_42", "0", "0"},
[402842] = {402842, 10028, 45, 37, "0", "0", "呼……", "0", "0", "0", "0", "0", "cv_mojun_43", "0", "0"},
[402900] = {402900, 10029, 1, 1, "0", "0", "蒼霧殘響", "0", "0", "0", "0", "0", "cv_lili_001", "0", "0"},
[402901] = {402901, 10029, 2, 2, "0", "0", "會不會被人誤會啊……我現在的樣子看起來不是很糟糕嗎？", "0", "0", "0", "0", "0", "cv_lili_002", "0", "0"},
[402902] = {402902, 10029, 3, 3, "0", "0", "黎貝……不對，現在是莉莉，“九頭蛇”的莉莉。領航！我們又見面了！", "0", "0", "0", "0", "0", "cv_lili_003", "0", "0"},
[402903] = {402903, 10029, 4, 4, "0", "idle", "這顆蛋……博士說，我能變成原罪，就是因為這顆蛋裏的能量，而維持我巨大化身體的平衡也需要它……所以要保持這個姿態的話，就必須要和這顆蛋在一起。", "0", "0", "0", "0", "0", "cv_lili_004", "0", "0"},
[402904] = {402904, 10029, 5, 4, "0", "idle", "我們這一次相信艾吉斯，不是因為我們原諒了它……而是因為這個地方有你在，領航。我和萊薇相信的人是你。", "0", "0", "0", "0", "0", "cv_lili_005", "0", "0"},
[402905] = {402905, 10029, 6, 4, "0", "idle", "萊薇只想著保護好我……其實我也想保護她，比起我，她才是那個看起來更容易受傷的人。", "0", "0", "0", "0", "0", "cv_lili_006", "0", "0"},
[402906] = {402906, 10029, 7, 5, "1_》_0_0.8", "level1", "等我的身體恢復正常後，我要和領航、萊薇一起去最美麗的島嶼上旅遊，吃最美味的美食，這是我能想到的最美好的事情了。", "0", "0", "0", "0", "0", "cv_lili_007", "0", "0"},
[402907] = {402907, 10029, 8, 5, "1_》_0_0.8", "level1", "我——莉莉在~！", "0", "0", "0", "0", "0", "cv_lili_008", "0", "0"},
[402908] = {402908, 10029, 9, 5, "1_》_100_1.5", "level2", "我時不時還能夢到那天晚上的事情，在那個噩夢裏，我變成了怪物，向著自己保護的人揮下爪子……一次又一次地夢到它，怎麼也無法釋懷。", "0", "0", "0", "0", "0", "cv_lili_009", "0", "0"},
[402909] = {402909, 10029, 10, 5, "1_》_500_2", "level3", "史蒂芬妮博士每次都跟我說，我的身體正在好轉……真的是這樣嗎？我會不會已經……再也回不去了……呼，領航，你會陪著我的吧？", "0", "0", "0", "0", "0", "cv_lili_010", "0", "0"},
[402910] = {402910, 10029, 11, 5, "1_》_1000_2.5", "level4", "領航，還記得我們那時候定下的約定嗎？嗯，就是你想的那件事。如果那一天真的到來了，請你不要猶豫，做你應該做的事情，這也是我所希望的——我希望能死在你的手下。", "0", "0", "0", "0", "0", "cv_lili_011", "0", "0"},
[402911] = {402911, 10029, 12, 6, "0", "0", "我變得更強了嗎？", "0", "0", "0", "0", "0", "cv_lili_012", "0", "0"},
[402912] = {402912, 10029, 13, 7, "0", "0", "好美麗的星星。", "0", "0", "0", "0", "0", "cv_lili_013", "0", "0"},
[402913] = {402913, 10029, 14, 8, "0", "0", "如果身體不能恢復的話……我也要用這份力量去保護領航和萊薇，因為你們是我僅有的“家人”了。", "0", "0", "0", "0", "0", "cv_lili_014", "0", "0"},
[402914] = {402914, 10029, 15, 9, "0", "0", "身體更敏銳了……", "0", "0", "0", "0", "0", "cv_lili_015", "0", "0"},
[402915] = {402915, 10029, 16, 10, "0", "0", "嗚喵？", "0", "0", "0", "0", "0", "cv_lili_016", "0", "0"},
[402916] = {402916, 10029, 17, 11, "0", "0", "嘿嘿嘿，我很棒吧？", "0", "0", "0", "0", "0", "cv_lili_017", "0", "0"},
[402917] = {402917, 10029, 18, 12, "0", "0", "贏了？我們贏了？", "0", "0", "0", "0", "0", "cv_lili_018", "0", "0"},
[402918] = {402918, 10029, 19, 13, "0", "0", "沒有出現意外真是太好了。", "0", "0", "0", "0", "0", "cv_lili_019", "0", "0"},
[402919] = {402919, 10029, 20, 14, "0", "0", "只要還活著，就沒問題。", "0", "0", "0", "0", "0", "cv_lili_020", "0", "0"},
[402920] = {402920, 10029, 21, 15, "0", "0", "喵！", "0", "0", "0", "0", "0", "cv_lili_021", "0", "0"},
[402921] = {402921, 10029, 23, 16, "0", "0", "喵喵喵！", "0", "0", "0", "0", "0", "cv_lili_023", "0", "0"},
[402922] = {402922, 10029, 26, 19, "0", "0", "救救我……萊薇，領航……", "0", "0", "0", "0", "0", "cv_lili_026", "0", "0"},
[402923] = {402923, 10029, 24, 17, "0", "0", "喵喵！", "0", "0", "0", "0", "0", "cv_lili_024", "0", "0"},
[402924] = {402924, 10029, 25, 18, "0", "0", "能量……快要暴走了。", "0", "0", "0", "0", "0", "cv_lili_025", "0", "0"},
[402925] = {402925, 10029, 27, 20, "0", "0", "嗚哇——是領航？嚇死我了……", "0", "0", "0", "0", "0", "cv_lili_027", "0", "0"},
[402926] = {402926, 10029, 28, 21, "0", "0", "體內的能量好像平靜下來了，原來如此，這就是領航在這裏的原因嗎？", "0", "0", "0", "0", "0", "cv_lili_028", "0", "0"},
[402927] = {402927, 10029, 29, 21, "0", "0", "領航小小的……在背上走來走去的，有點癢……", "0", "0", "0", "0", "0", "cv_lili_029", "0", "0"},
[402928] = {402928, 10029, 30, 22, "0", "0", "誒誒誒？", "0", "0", "0", "0", "0", "cv_lili_030", "0", "0"},
[402929] = {402929, 10029, 31, 23, "0", "0", "應該很好猜……吧？", "0", "0", "0", "0", "0", "cv_lili_031", "0", "0"},
[402930] = {402930, 10029, 32, 24, "0", "0", "呼……還好猜對了。", "0", "0", "0", "0", "0", "cv_lili_032", "0", "0"},
[402931] = {402931, 10029, 33, 25, "0", "0", "嗚嗚嗚，領航欺負人。", "0", "0", "0", "0", "0", "cv_lili_033", "0", "0"},
[402932] = {402932, 10029, 34, 26, "0", "0", "領航，今天的身體檢查也拜託你了！", "0", "0", "0", "0", "0", "cv_lili_034", "0", "0"},
[402933] = {402933, 10029, 35, 27, "0", "0", "為了領航，為了萊薇，我會戰鬥的！", "0", "0", "0", "0", "0", "cv_lili_035", "0", "0"},
[402934] = {402934, 10029, 36, 28, "0", "0", "會被當做原罪的吧……", "0", "0", "0", "0", "0", "cv_lili_036", "0", "0"},
[402935] = {402935, 10029, 37, 29, "0", "0", "嗚嗚嗚，大、大家好！", "0", "0", "0", "0", "0", "cv_lili_037", "0", "0"},
[402936] = {402936, 10029, 38, 30, "0", "0", "要見其他人了？", "0", "0", "0", "0", "0", "cv_lili_038", "0", "0"},
[402937] = {402937, 10029, 39, 31, "0", "0", "誒——會有我的裝備嗎？", "0", "0", "0", "0", "0", "cv_lili_039", "0", "0"},
[402938] = {402938, 10029, 40, 32, "0", "0", "要購物嗎？", "0", "0", "0", "0", "0", "cv_lili_040", "0", "0"},
[402939] = {402939, 10029, 41, 33, "0", "0", "領航變得更加帥氣了呢。", "0", "0", "0", "0", "0", "cv_lili_041", "0", "0"},
[402940] = {402940, 10029, 42, 34, "0", "0", "設置~", "0", "0", "0", "0", "0", "cv_lili_042", "0", "0"},
[402941] = {402941, 10029, 43, 35, "0", "0", "需要我幫忙打開嗎？", "0", "0", "0", "0", "0", "cv_lili_043", "0", "0"},
[402942] = {402942, 10029, 44, 36, "0", "0", "我不打擾你了~", "0", "0", "0", "0", "0", "cv_lili_044", "0", "0"},
[402943] = {402943, 10029, 45, 37, "0", "0", "誒？", "0", "0", "0", "0", "0", "cv_lili_045", "0", "0"},
[403000] = {403000, 10030, 1, 1, "0", "0", "蒼霧殘響", "0", "0", "0", "0", "0", "cv_faernaisi_1", "0", "0"},
[403001] = {403001, 10030, 2, 2, "0", "0", "父親曾計劃將我培養為參謀，您也有此打算嗎？", "0", "0", "0", "0", "0", "cv_faernaisi_2", "0", "0"},
[403002] = {403002, 10030, 3, 3, "0", "0", "我已聽聞您是位通情達理的領航，在此請允許我更多按照家族的規則，而非艾吉斯的規則行事。那麼，“歧花”隊長，法爾奈斯·蘭特向您報道。", "0", "0", "0", "0", "0", "cv_faernaisi_3", "0", "0"},
[403003] = {403003, 10030, 4, 4, "0", "idle", "從首次巨大化起，這種高度的視野就未曾讓我不適過。無非是滿園林立的絲柏變成大廈，低矮密集的花草變成人群。", "0", "0", "0", "0", "0", "cv_faernaisi_4", "0", "0"},
[403004] = {403004, 10030, 5, 4, "0", "idle", "領航在休息嗎，抑或是在思考？微風徐起時，我也喜歡在庭院裡靜默不語地待著。不過，這高空的風對您難道不會過於強烈了？", "0", "0", "0", "0", "0", "cv_faernaisi_5", "0", "0"},
[403005] = {403005, 10030, 6, 4, "0", "idle", "“蕩漾兔”，那傢夥總是喜歡挑戰我的忍耐力，由於真身不明，拿她也沒什麼辦法……還好倒是值得信賴，讓人願意在戰鬥中託付後背。", "0", "0", "0", "0", "0", "cv_faernaisi_6", "0", "0"},
[403006] = {403006, 10030, 7, 5, "1_》_0_0.8", "level1", "蘭特家族掌管了薩哈拉北部的建築與園林產業，人們對那些典雅的宅邸與花園引以為豪，以至於忘了石料也是種武器，花草也能助燃烈焰。", "0", "0", "0", "0", "0", "cv_faernaisi_7", "0", "0"},
[403007] = {403007, 10030, 8, 5, "1_》_0_0.8", "level1", "要是在我的家鄉，您這樣冒然肢體接觸，可能會讓腦袋裡被人播種一顆子彈。不過請別誤會，這不是威脅，只是在感慨環境的差異。", "0", "0", "0", "0", "0", "cv_faernaisi_8", "0", "0"},
[403008] = {403008, 10030, 9, 5, "1_》_100_1.5", "level2", "倘若有此必要，領航您願捨棄良善而去槍殺一朵花嗎？嗯……溫柔之人的答案果然早已註定。但，我會。", "0", "0", "0", "0", "0", "cv_faernaisi_9", "0", "0"},
[403009] = {403009, 10030, 10, 5, "1_》_500_2", "level3", "我身上的香味？柑橘與香檸檬的前調方才消散，現在正是苦橙葉、小豆蔻和茉莉的中調。而至於後調……就待數小時後今夜裡的芬芳來揭曉吧。", "0", "0", "0", "0", "0", "cv_faernaisi_10", "0", "0"},
[403010] = {403010, 10030, 11, 5, "1_》_1000_2.5", "level4", "關於讓您加入家族一事，我已向父親申請了。唔，您問以何種方式加入？這般明知故問，是想讓我親口說出來吧？您的壞心眼果真適合加入我們呢。", "0", "0", "0", "0", "0", "cv_faernaisi_11", "0", "0"},
[403011] = {403011, 10030, 12, 6, "0", "0", "何處都得學習啊。", "0", "0", "0", "0", "0", "cv_faernaisi_12", "0", "0"},
[403012] = {403012, 10030, 13, 7, "0", "0", "花開之時，也即瀕臨凋謝之際。", "0", "0", "0", "0", "0", "cv_faernaisi_13", "0", "0"},
[403013] = {403013, 10030, 14, 8, "0", "0", "父親畏懼我的才能，一度放棄過對我的栽培，看來領航您不會這樣。那麼，今後就請享受我所結出的碩果吧。", "0", "0", "0", "0", "0", "cv_faernaisi_14", "0", "0"},
[403014] = {403014, 10030, 15, 9, "0", "0", "這門“手藝”可不能生疏。", "0", "0", "0", "0", "0", "cv_faernaisi_15", "0", "0"},
[403015] = {403015, 10030, 16, 10, "0", "0", "這種場地的話……", "0", "0", "0", "0", "0", "cv_faernaisi_16", "0", "0"},
[403016] = {403016, 10030, 17, 11, "0", "0", "我們所期望的結果。", "0", "0", "0", "0", "0", "cv_faernaisi_17", "0", "0"},
[403017] = {403017, 10030, 18, 12, "0", "0", "可以接受的損失。", "0", "0", "0", "0", "0", "cv_faernaisi_18", "0", "0"},
[403018] = {403018, 10030, 19, 13, "0", "0", "得好好反省了。", "0", "0", "0", "0", "0", "cv_faernaisi_19", "0", "0"},
[403019] = {403019, 10030, 20, 14, "0", "0", "這種失敗不會有下次。", "0", "0", "0", "0", "0", "cv_faernaisi_20", "0", "0"},
[403020] = {403020, 10030, 21, 15, "0", "0", "再見。", "0", "0", "0", "0", "0", "cv_faernaisi_21", "0", "0"},
[403021] = {403021, 10030, 23, 16, "0", "0", "種下子彈。", "0", "0", "0", "0", "0", "cv_faernaisi_22", "0", "0"},
[403022] = {403022, 10030, 26, 19, "0", "0", "現在是我的主場了。", "0", "0", "0", "0", "0", "cv_faernaisi_23", "0", "0"},
[403023] = {403023, 10030, 24, 17, "0", "0", "你所對抗的，是整個家族。", "0", "0", "0", "0", "0", "cv_faernaisi_24", "0", "0"},
[403024] = {403024, 10030, 25, 18, "0", "0", "這次大意了……", "0", "0", "0", "0", "0", "cv_faernaisi_26", "0", "0"},
[403025] = {403025, 10030, 27, 20, "0", "0", "您不敲門就……好吧，我忘了這種體型是很難聽見敲門聲的。", "0", "0", "0", "0", "0", "cv_faernaisi_27", "0", "0"},
[403026] = {403026, 10030, 28, 21, "0", "0", "如此坦誠相待的場合，才最適合用來放鬆，畢竟沒人能在這裡偷偷攜帶武器。", "0", "0", "0", "0", "0", "cv_faernaisi_28", "0", "0"},
[403027] = {403027, 10030, 29, 21, "0", "0", "還不快點嗎？還是說……您不願讓這種曖昧的氛圍太快結束呢？", "0", "0", "0", "0", "0", "cv_faernaisi_29", "0", "0"},
[403028] = {403028, 10030, 30, 22, "0", "0", "這個動靜……", "0", "0", "0", "0", "0", "cv_faernaisi_30", "0", "0"},
[403029] = {403029, 10030, 31, 23, "0", "0", "關於信賴的遊戲嗎。", "0", "0", "0", "0", "0", "cv_faernaisi_31", "0", "0"},
[403030] = {403030, 10030, 32, 24, "0", "0", "我也會回應您的重視。", "0", "0", "0", "0", "0", "cv_faernaisi_32", "0", "0"},
[403031] = {403031, 10030, 33, 25, "0", "0", "不得不說，我有些失望。", "0", "0", "0", "0", "0", "cv_faernaisi_33", "0", "0"},
[403032] = {403032, 10030, 34, 26, "0", "0", "今天是個好天氣，晴朗、明媚、溫暖，適合蒔花弄草，洽談生意，訓練射擊，以及清理那些庭院陰影裡的東西。", "0", "0", "0", "0", "0", "cv_faernaisi_34", "0", "0"},
[403033] = {403033, 10030, 35, 27, "0", "0", "出發吧。", "0", "0", "0", "0", "0", "cv_faernaisi_35", "0", "0"},
[403034] = {403034, 10030, 36, 28, "0", "0", "一種遊戲。", "0", "0", "0", "0", "0", "cv_faernaisi_36", "0", "0"},
[403035] = {403035, 10030, 37, 29, "0", "0", "親信之人嗎。", "0", "0", "0", "0", "0", "cv_faernaisi_37", "0", "0"},
[403036] = {403036, 10030, 38, 30, "0", "0", "新的成員啊。", "0", "0", "0", "0", "0", "cv_faernaisi_38", "0", "0"},
[403037] = {403037, 10030, 39, 31, "0", "0", "得清點仔細。", "0", "0", "0", "0", "0", "cv_faernaisi_39", "0", "0"},
[403038] = {403038, 10030, 40, 32, "0", "0", "我喜歡消費。", "0", "0", "0", "0", "0", "cv_faernaisi_40", "0", "0"},
[403039] = {403039, 10030, 41, 33, "0", "0", "小心洩露。", "0", "0", "0", "0", "0", "cv_faernaisi_41", "0", "0"},
[403040] = {403040, 10030, 42, 34, "0", "0", "請。", "0", "0", "0", "0", "0", "cv_faernaisi_42", "0", "0"},
[403041] = {403041, 10030, 43, 35, "0", "0", "確保無人看見。", "0", "0", "0", "0", "0", "cv_faernaisi_43", "0", "0"},
[403042] = {403042, 10030, 44, 36, "0", "0", "言語的戰場。", "0", "0", "0", "0", "0", "cv_faernaisi_44", "0", "0"},
[403043] = {403043, 10030, 45, 37, "0", "0", "注意安全。", "0", "0", "0", "0", "0", "cv_faernaisi_45", "0", "0"},
[403100] = {403100, 10031, 1, 1, "0", "0", "蒼霧殘響", "0", "0", "0", "0", "0", "cv_aofeiliya_1", "0", "0"},
[403101] = {403101, 10031, 2, 2, "0", "0", "我、我會努力的！", "0", "0", "0", "0", "0", "cv_aofeiliya_2", "0", "0"},
[403102] = {403102, 10031, 3, 3, "0", "0", "那個……您就是那位大名鼎鼎的領航嗎？我是啟泉會的奧菲莉亞，來自水車村，愛好是和小動物一起玩，然後還有……初次見面，請多多指教！", "0", "0", "0", "0", "0", "cv_aofeiliya_3", "0", "0"},
[403103] = {403103, 10031, 4, 4, "0", "idle", "小時候在村子裡的水車旁玩耍時，我從沒想過自己以後會變得比它們更大，甚至還用它作為武器。", "0", "0", "0", "0", "0", "cv_aofeiliya_4", "0", "0"},
[403104] = {403104, 10031, 5, 4, "0", "idle", "領航……是不是有些困了？想休息的話不用強撐哦，我會在旁邊幫忙遮一遮風。", "0", "0", "0", "0", "0", "cv_aofeiliya_5", "0", "0"},
[403105] = {403105, 10031, 6, 4, "0", "idle", "感覺這件裙子涼颼颼的……但既然是米菈隊長要求的著裝，再難為情也還是得努力克服呢。", "0", "0", "0", "0", "0", "cv_aofeiliya_6", "0", "0"},
[403106] = {403106, 10031, 7, 5, "1_》_0_0.8", "level1", "我的家鄉，是座以水車聞名的美麗村莊，流經土地的每條大河都建有一座水車，從山坡上望去就像許多齒輪在轉動，日復一日拉起晝夜的帷幕。", "0", "0", "0", "0", "0", "cv_aofeiliya_7", "0", "0"},
[403107] = {403107, 10031, 8, 5, "1_》_0_0.8", "level1", "嗚欸！唔……對、對不起我有些反應過度，我是從鄉下來的，還不習慣領航可以隨意摸駕駛員的規定……嗯？沒有這種規定嗎？", "0", "0", "0", "0", "0", "cv_aofeiliya_8", "0", "0"},
[403108] = {403108, 10031, 9, 5, "1_》_100_1.5", "level2", "您是說，打算抽空帶我去商業街逛逛？我、我想想……嗯，的確是個熟悉城市的辦法，那好吧。（話說這該不會就是約會吧！城裡人還真是開放……）", "0", "0", "0", "0", "0", "cv_aofeiliya_9", "0", "0"},
[403109] = {403109, 10031, 10, 5, "1_》_500_2", "level3", "下次回鄉，我想買點禮物帶來，領航有什麼想要的嗎？小點心、手工藝品、帶有風景的明信片。欸，您要直接陪我一起回去？也、也不是不行啦……", "0", "0", "0", "0", "0", "cv_aofeiliya_10", "0", "0"},
[403110] = {403110, 10031, 11, 5, "1_》_1000_2.5", "level4", "領領領領航……您覺得，“你像永不停轉的水車，日夜灌溉著我的心田”這句話怎麼樣？欸，很土嗎？！我媽說這是她那一代人最新潮的情話了……", "0", "0", "0", "0", "0", "cv_aofeiliya_11", "0", "0"},
[403111] = {403111, 10031, 12, 6, "0", "0", "加、加油哦！", "0", "0", "0", "0", "0", "cv_aofeiliya_12", "0", "0"},
[403112] = {403112, 10031, 13, 7, "0", "0", "居然還能變強，這是怎麼辦到的……", "0", "0", "0", "0", "0", "cv_aofeiliya_13", "0", "0"},
[403113] = {403113, 10031, 14, 8, "0", "0", "即使河流乾涸，我也想讓水車不斷轉動下去……雖然這麼說有點難為情，但領航，一起加油吧！", "0", "0", "0", "0", "0", "cv_aofeiliya_14", "0", "0"},
[403114] = {403114, 10031, 15, 9, "0", "0", "身體更靈活了。", "0", "0", "0", "0", "0", "cv_aofeiliya_15", "0", "0"},
[403115] = {403115, 10031, 16, 10, "0", "0", "帶著全村人的期望——", "0", "0", "0", "0", "0", "cv_aofeiliya_16", "0", "0"},
[403116] = {403116, 10031, 17, 11, "0", "0", "戰鬥好難，還好完美結束了。", "0", "0", "0", "0", "0", "cv_aofeiliya_17", "0", "0"},
[403117] = {403117, 10031, 18, 12, "0", "0", "下次得更加努力些。", "0", "0", "0", "0", "0", "cv_aofeiliya_18", "0", "0"},
[403118] = {403118, 10031, 19, 13, "0", "0", "得打起精神來呢……", "0", "0", "0", "0", "0", "cv_aofeiliya_19", "0", "0"},
[403119] = {403119, 10031, 20, 14, "0", "0", "我辜負了大家的期望……", "0", "0", "0", "0", "0", "cv_aofeiliya_20", "0", "0"},
[403120] = {403120, 10031, 21, 15, "0", "0", "呼……真嚇人。", "0", "0", "0", "0", "0", "cv_aofeiliya_21", "0", "0"},
[403121] = {403121, 10031, 23, 16, "0", "0", "請離開！", "0", "0", "0", "0", "0", "cv_aofeiliya_23", "0", "0"},
[403122] = {403122, 10031, 26, 19, "0", "0", "咿呀——！", "0", "0", "0", "0", "0", "cv_aofeiliya_25", "0", "0"},
[403123] = {403123, 10031, 24, 17, "0", "0", "去死！", "0", "0", "0", "0", "0", "cv_aofeiliya_24", "0", "0"},
