[403125] = {403125, 10031, 27, 20, "0", "0", "身體必須好好清洗乾淨才行呢。", "0", "0", "0", "0", "0", "cv_aofeiliya_26", "0", "0"},
[403126] = {403126, 10031, 28, 21, "0", "0", "小時候在山上玩得一身土，我就會去一條只有自己知道的小溪清洗呢。", "0", "0", "0", "0", "0", "cv_aofeiliya_27", "0", "0"},
[403127] = {403127, 10031, 29, 21, "0", "0", "領、領航是不是盯著我看得有點久了？我這種鄉下的貧瘠身體有那麼好看嗎……", "0", "0", "0", "0", "0", "cv_aofeiliya_28", "0", "0"},
[403128] = {403128, 10031, 30, 22, "0", "0", "是什麼呢？", "0", "0", "0", "0", "0", "cv_aofeiliya_29", "0", "0"},
[403129] = {403129, 10031, 31, 23, "0", "0", "猜猜我是誰~", "0", "0", "0", "0", "0", "cv_aofeiliya_30", "0", "0"},
[403130] = {403130, 10031, 32, 24, "0", "0", "欸，居然猜中了嗎？好厲害！", "0", "0", "0", "0", "0", "cv_aofeiliya_31", "0", "0"},
[403131] = {403131, 10031, 33, 25, "0", "0", "嘿嘿，沒猜到吧~", "0", "0", "0", "0", "0", "cv_aofeiliya_32", "0", "0"},
[403132] = {403132, 10031, 34, 26, "0", "0", "領航，今天的天氣也很不錯呢。剛剛我看到了一群燕子，即使是在城市裡，它們也能無憂無慮地生活下去，真好啊~", "0", "0", "0", "0", "0", "cv_aofeiliya_33", "0", "0"},
[403133] = {403133, 10031, 35, 27, "0", "0", "打倒那些壞傢夥吧。", "0", "0", "0", "0", "0", "cv_aofeiliya_34", "0", "0"},
[403134] = {403134, 10031, 36, 28, "0", "0", "要和和氣氣的哦。", "0", "0", "0", "0", "0", "cv_aofeiliya_35", "0", "0"},
[403135] = {403135, 10031, 37, 29, "0", "0", "大家都在這裏。", "0", "0", "0", "0", "0", "cv_aofeiliya_36", "0", "0"},
[403136] = {403136, 10031, 38, 30, "0", "0", "新的夥伴呢。", "0", "0", "0", "0", "0", "cv_aofeiliya_37", "0", "0"},
[403137] = {403137, 10031, 39, 31, "0", "0", "會有什麼呢？", "0", "0", "0", "0", "0", "cv_aofeiliya_38", "0", "0"},
[403138] = {403138, 10031, 40, 32, "0", "0", "好期待~", "0", "0", "0", "0", "0", "cv_aofeiliya_39", "0", "0"},
