[403140] = {403140, 10031, 42, 34, "0", "0", "需要幫忙嗎？", "0", "0", "0", "0", "0", "cv_aofeiliya_41", "0", "0"},
[403141] = {403141, 10031, 43, 35, "0", "0", "有給我的信嗎？", "0", "0", "0", "0", "0", "cv_aofeiliya_42", "0", "0"},
[403142] = {403142, 10031, 44, 36, "0", "0", "好、好多人……", "0", "0", "0", "0", "0", "cv_aofeiliya_43", "0", "0"},
