[403200] = {403200, 10032, 1, 1, "0", "0", "蒼霧殘響", "0", "0", "0", "0", "0", "cv_kelisidina_1", "0", "0"},
[403201] = {403201, 10032, 2, 2, "0", "0", "啊……輪到我來擔任這個職務了嗎……讓科研人員來當領航的保護者真的合適嗎？如果您想我一直在身邊的話，可以在附近建一所實驗室，我會在裡面隨時待命的。", "0", "0", "0", "0", "0", "cv_kelisidina_2", "0", "0"},
[403202] = {403202, 10032, 3, 3, "0", "0", "……領航？你終於想好了要作為我的實驗對象了嗎？快來這裡吧，我為你準備了很多方案，保證接下來會讓你一生難忘。", "0", "0", "0", "0", "0", "cv_kelisidina_3", "0", "0"},
[403203] = {403203, 10032, 4, 4, "0", "idle", "科研啊……很多時候對於我來說，研究的過程都是些不好的體驗，是惡報，也是噩耗，只有在真正完成的那一刻才能感到開心到爆炸。", "0", "0", "0", "0", "0", "cv_kelisidina_4", "0", "0"},
[403204] = {403204, 10032, 5, 4, "0", "idle", "要是我生來就是那種“能在科研的寂寞過程中感受到快樂的人”就好了，那樣的話不就能無時無刻地享福了嘛……哈哈，和抖M一樣。", "0", "0", "0", "0", "0", "cv_kelisidina_5", "0", "0"},
[403205] = {403205, 10032, 6, 4, "0", "idle", "想要找個時間好好休息一下啊……這一周要是能有進展的話，就獎勵自己好好睡一會吧……忍幾天看看。", "0", "0", "0", "0", "0", "cv_kelisidina_6", "0", "0"},
[403206] = {403206, 10032, 7, 5, "1_》_0_0.8", "level1", "大事不妙啊，最近發現頭髮一直在掉……怎麼辦呢……領航有什麼推薦的東西嗎。", "0", "0", "0", "0", "0", "cv_kelisidina_7", "0", "0"},
[403207] = {403207, 10032, 8, 5, "1_》_0_0.8", "level1", "呼，今天半夜還要趕著去提取尼姆比斯液，所以我只能這裡待一會。", "0", "0", "0", "0", "0", "cv_kelisidina_8", "0", "0"},
[403208] = {403208, 10032, 9, 5, "1_》_100_1.5", "level2", "以前最忙的那段時間，我會睡在實驗室，越到深夜腦子越清醒，晚上也沒有人會打擾我，效率比白天高不少，回去的話路上還要花時間……總之，好處多多。", "0", "0", "0", "0", "0", "cv_kelisidina_9", "0", "0"},
[403209] = {403209, 10032, 10, 5, "1_》_500_2", "level3", "想看我工作時候的樣子？你的要求真奇怪，如果你想要試試在實驗室過夜的感覺，我可以悄悄帶你進去。", "0", "0", "0", "0", "0", "cv_kelisidina_10", "0", "0"},
[403210] = {403210, 10032, 11, 5, "1_》_1000_2.5", "level4", "本來這個時間我該待在實驗室的……所以希望你也能打起精神來，我難得的時間要留下寶貴的回憶才行。", "0", "0", "0", "0", "0", "cv_kelisidina_11", "0", "0"},
[403211] = {403211, 10032, 12, 6, "0", "0", "研究進度提升了。", "0", "0", "0", "0", "0", "cv_kelisidina_12", "0", "0"},
[403212] = {403212, 10032, 13, 7, "0", "0", "階段性的突破。", "0", "0", "0", "0", "0", "cv_kelisidina_13", "0", "0"},
[403213] = {403213, 10032, 14, 8, "0", "0", "這一次的目標完成了麼，哈啊啊，讓我睡一覺吧。", "0", "0", "0", "0", "0", "cv_kelisidina_14", "0", "0"},
[403214] = {403214, 10032, 15, 9, "0", "0", "朝著下一個目標前進吧。", "0", "0", "0", "0", "0", "cv_kelisidina_15", "0", "0"},
[403215] = {403215, 10032, 16, 10, "0", "0", "啊~快點結束吧。", "0", "0", "0", "0", "0", "cv_kelisidina_16", "0", "0"},
[403216] = {403216, 10032, 17, 11, "0", "0", "理想中的結果。", "0", "0", "0", "0", "0", "cv_kelisidina_17", "0", "0"},
[403217] = {403217, 10032, 18, 12, "0", "0", "雖說有些偏差，但是也還算可以接受，再調整吧。", "0", "0", "0", "0", "0", "cv_kelisidina_18", "0", "0"},
[403218] = {403218, 10032, 19, 13, "0", "0", "是不是選錯了戰略目標？", "0", "0", "0", "0", "0", "cv_kelisidina_19", "0", "0"},
[403219] = {403219, 10032, 20, 14, "0", "0", "重新開始吧，沒關係的，我陪著你。", "0", "0", "0", "0", "0", "cv_kelisidina_20", "0", "0"},
[403220] = {403220, 10032, 21, 15, "0", "0", "實驗結束。", "0", "0", "0", "0", "0", "cv_kelisidina_21", "0", "0"},
[403221] = {403221, 10032, 23, 16, "0", "0", "開始實驗吧。", "0", "0", "0", "0", "0", "cv_kelisidina_22", "0", "0"},
