[403223] = {403223, 10032, 26, 19, "0", "0", "是過勞了嗎……", "0", "0", "0", "0", "0", "cv_kelisidina_24", "0", "0"},
[403224] = {403224, 10032, 27, 20, "0", "0", "我早就想體驗一下這個了，我可以在一旁記錄這些資料嗎？", "0", "0", "0", "0", "0", "cv_kelisidina_25", "0", "0"},
[403225] = {403225, 10032, 28, 21, "0", "0", "呼哈……這次的報告不過關……呼哈……需要重新寫……", "0", "0", "0", "0", "0", "cv_kelisidina_26", "0", "0"},
[403226] = {403226, 10032, 29, 21, "0", "0", "呼哈……呼哈……嗯……我竟然睡著了……？", "0", "0", "0", "0", "0", "cv_kelisidina_27", "0", "0"},
[403227] = {403227, 10032, 30, 22, "0", "0", "“通感者催化實驗”，開始。", "0", "0", "0", "0", "0", "cv_kelisidina_28", "0", "0"},
[403228] = {403228, 10032, 31, 23, "0", "0", "快點結束吧，還有下一場實驗在等著我。", "0", "0", "0", "0", "0", "cv_kelisidina_29", "0", "0"},
[403229] = {403229, 10032, 32, 24, "0", "0", "嗯……你的記性不錯嘛。", "0", "0", "0", "0", "0", "cv_kelisidina_30", "0", "0"},
[403230] = {403230, 10032, 33, 25, "0", "0", "嗯……也情有可原，畢竟我和你接觸的時間很少。", "0", "0", "0", "0", "0", "cv_kelisidina_31", "0", "0"},
[403231] = {403231, 10032, 34, 26, "0", "0", "回來了？我剛好要找你。", "0", "0", "0", "0", "0", "cv_kelisidina_32", "0", "0"},
[403232] = {403232, 10032, 35, 27, "0", "0", "帶一些材料回來吧。", "0", "0", "0", "0", "0", "cv_kelisidina_33", "0", "0"},
[403233] = {403233, 10032, 36, 28, "0", "0", "駕駛員的戰鬥資料是必要的。", "0", "0", "0", "0", "0", "cv_kelisidina_34", "0", "0"},
[403234] = {403234, 10032, 37, 29, "0", "0", "收集大家的資料吧。", "0", "0", "0", "0", "0", "cv_kelisidina_35", "0", "0"},
[403235] = {403235, 10032, 38, 30, "0", "0", "調查出你想要的搭檔了嗎？", "0", "0", "0", "0", "0", "cv_kelisidina_36", "0", "0"},
[403236] = {403236, 10032, 39, 31, "0", "0", "讓我看看這些裝備……不錯。", "0", "0", "0", "0", "0", "cv_kelisidina_37", "0", "0"},
[403237] = {403237, 10032, 40, 32, "0", "0", "買點咖啡。", "0", "0", "0", "0", "0", "cv_kelisidina_38", "0", "0"},
