[403301] = {403301, 10033, 2, 2, "0", "0", "晨曦，S52，名字是柯朗。介紹完畢。", "0", "0", "0", "0", "0", "cv_kelang_2", "0", "0"},
[403302] = {403302, 10033, 3, 3, "0", "0", "由唯一的通感者來監控？這可真是太看得起我了。", "0", "0", "0", "0", "0", "cv_kelang_3", "0", "0"},
[403303] = {403303, 10033, 4, 4, "0", "idle", "……不對勁。", "0", "0", "0", "0", "0", "cv_kelang_4", "0", "0"},
