[403305] = {403305, 10033, 6, 4, "0", "idle", "為什麼在你眼裏看不到任何黑暗？", "0", "0", "0", "0", "0", "cv_kelang_6", "0", "0"},
[403306] = {403306, 10033, 7, 5, "1_》_0_0.8", "level1", "你知道嗎？晨曦這個詞，通常用來指代“希望之光”。", "0", "0", "0", "0", "0", "cv_kelang_7", "0", "0"},
[403307] = {403307, 10033, 8, 5, "1_》_0_0.8", "level1", "奇怪的人。", "0", "0", "0", "0", "0", "cv_kelang_8", "0", "0"},
[403308] = {403308, 10033, 9, 5, "1_》_100_1.5", "level2", "你對於任何人、任何事，都沒有絲毫不滿嗎？", "0", "0", "0", "0", "0", "cv_kelang_9", "0", "0"},
[403309] = {403309, 10033, 10, 5, "1_》_500_2", "level3", "或許你就是我一直找尋的那個人……？", "0", "0", "0", "0", "0", "cv_kelang_10", "0", "0"},
[403310] = {403310, 10033, 11, 5, "1_》_1000_2.5", "level4", "絕對的正確，絕對的正義……太好了，我終於找到您了。", "0", "0", "0", "0", "0", "cv_kelang_11", "0", "0"},
[403311] = {403311, 10033, 12, 6, "0", "0", "我？", "0", "0", "0", "0", "0", "cv_kelang_12", "0", "0"},
[403312] = {403312, 10033, 13, 7, "0", "0", "好吧，瞭解了。", "0", "0", "0", "0", "0", "cv_kelang_13", "0", "0"},
[403313] = {403313, 10033, 14, 8, "0", "0", "……我還挺喜歡的。你將資源給我時，其他駕駛員的表情。", "0", "0", "0", "0", "0", "cv_kelang_14", "0", "0"},
[403314] = {403314, 10033, 15, 9, "0", "0", "要不你手把手教教我，這些該怎麼用？", "0", "0", "0", "0", "0", "cv_kelang_15", "0", "0"},
[403315] = {403315, 10033, 16, 10, "0", "0", "……搭建通感吧。", "0", "0", "0", "0", "0", "cv_kelang_16", "0", "0"},
[403316] = {403316, 10033, 17, 11, "0", "0", "恭喜啊。", "0", "0", "0", "0", "0", "cv_kelang_17", "0", "0"},
[403317] = {403317, 10033, 18, 12, "0", "0", "真可惜。", "0", "0", "0", "0", "0", "cv_kelang_18", "0", "0"},
[403318] = {403318, 10033, 19, 13, "0", "0", "我看到了，有駕駛員對自己產生了疑惑。", "0", "0", "0", "0", "0", "cv_kelang_19", "0", "0"},
[403319] = {403319, 10033, 20, 14, "0", "0", "面對這麼糟糕的結果，你竟然都沒有一丁半點的動搖？？", "0", "0", "0", "0", "0", "cv_kelang_20", "0", "0"},
[403320] = {403320, 10033, 21, 15, "0", "0", "……好髒。", "0", "0", "0", "0", "0", "cv_kelang_21", "0", "0"},
[403321] = {403321, 10033, 23, 16, "0", "0", "這指令有夠粗暴的。", "0", "0", "0", "0", "0", "cv_kelang_23", "0", "0"},
[403322] = {403322, 10033, 24, 17, "0", "0", "我能看見，你所背負的諸多罪孽。", "0", "0", "0", "0", "0", "cv_kelang_24", "0", "0"},
[403323] = {403323, 10033, 25, 18, "0", "0", "不許碰我的信眾！", "0", "0", "0", "0", "0", "cv_kelang_25", "0", "0"},
[403324] = {403324, 10033, 26, 19, "0", "0", "至少我保護住了……", "0", "0", "0", "0", "0", "cv_kelang_26", "0", "0"},
[403325] = {403325, 10033, 27, 20, "0", "0", "在這裏也要被監視？", "0", "0", "0", "0", "0", "cv_kelang_27", "0", "0"},
[403326] = {403326, 10033, 28, 21, "0", "0", "……喂，說點什麼吧。", "0", "0", "0", "0", "0", "cv_kelang_28", "0", "0"},
[403327] = {403327, 10033, 29, 21, "0", "0", "你不覺得尷尬嗎？", "0", "0", "0", "0", "0", "cv_kelang_29", "0", "0"},
[403328] = {403328, 10033, 30, 22, "0", "0", "呼，終於來了。", "0", "0", "0", "0", "0", "cv_kelang_30", "0", "0"},
[403329] = {403329, 10033, 31, 23, "0", "0", "……你的小遊戲有點別致啊。", "0", "0", "0", "0", "0", "cv_kelang_31", "0", "0"},
[403330] = {403330, 10033, 32, 24, "0", "0", "嗯？一直都是我啊？不然你以為是誰？", "0", "0", "0", "0", "0", "cv_kelang_32", "0", "0"},
[403331] = {403331, 10033, 33, 25, "0", "0", "……原來如此。你認錯人了。", "0", "0", "0", "0", "0", "cv_kelang_33", "0", "0"},
[403332] = {403332, 10033, 34, 26, "0", "0", "你又來了啊。放心，我知道那些話術對你不起效果，所以不會用在你身上的。除非……", "0", "0", "0", "0", "0", "cv_kelang_34", "0", "0"},
[403333] = {403333, 10033, 35, 27, "0", "0", "戰爭總會與絕望相伴。", "0", "0", "0", "0", "0", "cv_kelang_35", "0", "0"},
[403334] = {403334, 10033, 36, 28, "0", "0", "點到為止的演習。", "0", "0", "0", "0", "0", "cv_kelang_36", "0", "0"},
[403335] = {403335, 10033, 37, 29, "0", "0", "我可以幫你與她們談談心。", "0", "0", "0", "0", "0", "cv_kelang_37", "0", "0"},
[403336] = {403336, 10033, 38, 30, "0", "0", "會是下一位信眾嗎？", "0", "0", "0", "0", "0", "cv_kelang_38", "0", "0"},
[403337] = {403337, 10033, 39, 31, "0", "0", "如果共鳴裝備沒有集齊，我是不是就可以不用上戰場了？", "0", "0", "0", "0", "0", "cv_kelang_39", "0", "0"},
[403338] = {403338, 10033, 40, 32, "0", "0", "人的物欲啊……", "0", "0", "0", "0", "0", "cv_kelang_40", "0", "0"},
[403339] = {403339, 10033, 41, 33, "0", "0", "不要讓我失望。", "0", "0", "0", "0", "0", "cv_kelang_41", "0", "0"},
[403340] = {403340, 10033, 42, 34, "0", "0", "什麼？", "0", "0", "0", "0", "0", "cv_kelang_42", "0", "0"},
[403341] = {403341, 10033, 43, 35, "0", "0", "我也可以看？", "0", "0", "0", "0", "0", "cv_kelang_43", "0", "0"},
[403342] = {403342, 10033, 44, 36, "0", "0", "真是個奇妙的平臺。", "0", "0", "0", "0", "0", "cv_kelang_44", "0", "0"},
[403343] = {403343, 10033, 45, 37, "0", "0", "嗯？", "0", "0", "0", "0", "0", "cv_kelang_45", "0", "0"},
[403400] = {403400, 10034, 1, 1, "0", "0", "蒼霧殘響", "0", "0", "0", "0", "0", "cv_roki_1", "0", "0"},
[403401] = {403401, 10034, 2, 2, "0", "0", "讓我待在明處……不知道該說你是膽大心細，還是初出茅廬氣焰正盛……不過，畢竟你的命令是大於守則的，我很樂意聽從。", "0", "0", "0", "0", "0", "cv_roki_2", "0", "0"},
[403402] = {403402, 10034, 3, 3, "0", "0", "“受刑人”洛基……可以的話，最好別用這個名字叫我……用“喂”或者是“那個誰”，都可以，我能明白的。", "0", "0", "0", "0", "0", "cv_roki_3", "0", "0"},
[403403] = {403403, 10034, 4, 4, "0", "idle1", "你真的是那位史蒂芬妮的養子？真是……嚇了我一跳，她居然還保留了這種程度人性，令人刮目相看，我得重新審視一下她在我心中的形象了。", "0", "0", "0", "0", "0", "cv_roki_4", "0", "0"},
[403404] = {403404, 10034, 5, 4, "0", "idle2", "頭疼……我還是第一次和人待在一個地方相處這麼久，這種時候該說什麼比較好，你有什麼主意嗎？", "0", "0", "0", "0", "0", "cv_roki_5", "0", "0"},
[403405] = {403405, 10034, 6, 4, "0", "idle3", "你見過其他的“受刑人”？那不得不誇獎你了，因為我可沒見過其他服役的“受刑人”。怎麼，你不會以為“受刑人”是一個氛圍良好的大家庭吧？", "0", "0", "0", "0", "0", "cv_roki_6", "0", "0"},
[403406] = {403406, 10034, 7, 5, "1_》_0_0.8", "level1", "離開“受刑人”之後要做什麼？是呢，我得好好想想……總之，先去九州找史蒂芬妮，給她的腦袋來上一槍吧……開個玩笑，畢竟我還沒查到她躲在哪呢。", "0", "0", "0", "0", "0", "cv_roki_7", "0", "0"},
[403407] = {403407, 10034, 8, 5, "1_》_0_0.8", "level1", "最近的生活真是一團糟……睡也睡不安穩，真羨慕你還能保持樂觀，好想知道你的頭蓋骨下面裝著什麼。", "0", "0", "0", "0", "0", "cv_roki_8", "0", "0"},
[403408] = {403408, 10034, 9, 5, "1_》_100_1.5", "level2", "多瑙的事情……瑪雅的事情，你好像總是在為這些事奔波，你不會覺得累嗎？不會厭倦嗎？", "0", "0", "0", "0", "0", "cv_roki_9", "0", "0"},
[403409] = {403409, 10034, 10, 5, "1_》_500_2", "level3", "我受不了像你這麼耀眼的人……光憑藉內心湧現的情感就能不顧一切地前進，這也太奢侈了。", "0", "0", "0", "0", "0", "cv_roki_10", "0", "0"},
[403410] = {403410, 10034, 11, 5, "1_》_1000_2.5", "level4", "你是在進行一場看不到盡頭的長跑，體力枯竭時就是你的終點。我真想讓你停下，但你肯定不願意……艾莉娜·霍普，這是我的名字，普普通通的名字，同時也是即將陪伴你進行這場長跑的同伴的名字。", "0", "0", "0", "0", "0", "cv_roki_11", "0", "0"},
[403411] = {403411, 10034, 12, 6, "0", "0", "享受到了正規軍的待遇。", "0", "0", "0", "0", "0", "cv_roki_12", "0", "0"},
[403412] = {403412, 10034, 13, 7, "0", "0", "感謝提拔。", "0", "0", "0", "0", "0", "cv_roki_13", "0", "0"},
[403413] = {403413, 10034, 14, 8, "0", "0", "突然覺得……當駕駛員說不定也挺好的。", "0", "0", "0", "0", "0", "cv_roki_14", "0", "0"},
[403414] = {403414, 10034, 15, 9, "0", "0", "多學點戰鬥技能也不是壞事。", "0", "0", "0", "0", "0", "cv_roki_15", "0", "0"},
[403415] = {403415, 10034, 16, 10, "0", "0", "我也沒想過自己會出現在正面戰場。", "0", "0", "0", "0", "0", "cv_roki_16", "0", "0"},
[403416] = {403416, 10034, 17, 11, "0", "0", "完美勝利？難以置信。", "0", "0", "0", "0", "0", "cv_roki_17", "0", "0"},
[403417] = {403417, 10034, 18, 12, "0", "0", "居然贏了嗎？不可思議。", "0", "0", "0", "0", "0", "cv_roki_18", "0", "0"},
[403418] = {403418, 10034, 19, 13, "0", "0", "這也能贏？值得佩服。", "0", "0", "0", "0", "0", "cv_roki_19", "0", "0"},
[403419] = {403419, 10034, 20, 14, "0", "0", "輸了？應該不是我的責任吧。", "0", "0", "0", "0", "0", "cv_roki_20", "0", "0"},
[403420] = {403420, 10034, 21, 15, "0", "0", "手感不錯。", "0", "0", "0", "0", "0", "cv_roki_21", "0", "0"},
[403421] = {403421, 10034, 23, 16, "0", "0", "就選你了。", "0", "0", "0", "0", "0", "cv_roki_23", "0", "0"},
[403422] = {403422, 10034, 26, 19, "0", "0", "那麼，我就先撤退了。", "0", "0", "0", "0", "0", "cv_roki_26", "0", "0"},
[403423] = {403423, 10034, 24, 17, "0", "0", "快嚥氣吧。", "0", "0", "0", "0", "0", "cv_roki_24", "0", "0"},
[403424] = {403424, 10034, 25, 18, "0", "0", "我來斬去你的多餘之物吧。", "0", "0", "0", "0", "0", "cv_roki_25", "0", "0"},
[403425] = {403425, 10034, 27, 20, "0", "0", "如果你因此產生了什麼邪念，我就會殺了你，立即，立刻。", "0", "0", "0", "0", "0", "cv_roki_27", "0", "0"},
[403426] = {403426, 10034, 28, 21, "0", "0", "以前只在動畫和漫畫裡遇過這種事……怎麼，你覺得我對那種東西不感興趣？", "0", "0", "0", "0", "0", "cv_roki_28", "0", "0"},
[403427] = {403427, 10034, 29, 21, "0", "0", "看著你在旁邊晃悠，就會想到不小心踩到你的畫面……放心，只是想想而已。", "0", "0", "0", "0", "0", "cv_roki_29", "0", "0"},
[403428] = {403428, 10034, 30, 22, "0", "0", "嗯？", "0", "0", "0", "0", "0", "cv_roki_30", "0", "0"},
[403429] = {403429, 10034, 31, 23, "0", "0", "你要叫那個名字了嗎……", "0", "0", "0", "0", "0", "cv_roki_31", "0", "0"},
[403430] = {403430, 10034, 32, 24, "0", "0", "別叫我洛基——就當是我在求你吧。", "0", "0", "0", "0", "0", "cv_roki_32", "0", "0"},
[403431] = {403431, 10034, 33, 25, "0", "0", "總好過你用那個代號叫我。", "0", "0", "0", "0", "0", "cv_roki_33", "0", "0"},
[403432] = {403432, 10034, 34, 26, "0", "0", "嗯……我剛剛正在和人打賭你不會回來了。", "0", "0", "0", "0", "0", "cv_roki_34", "0", "0"},
[403433] = {403433, 10034, 35, 27, "0", "0", "我還不是很喜歡這種類型的出勤任務……算了，總會習慣的。", "0", "0", "0", "0", "0", "cv_roki_35", "0", "0"},
[403434] = {403434, 10034, 36, 28, "0", "0", "也算是我擅長的事情吧。", "0", "0", "0", "0", "0", "cv_roki_36", "0", "0"},
[403435] = {403435, 10034, 37, 29, "0", "0", "這下我們才是真正的總部了。", "0", "0", "0", "0", "0", "cv_roki_37", "0", "0"},
[403436] = {403436, 10034, 38, 30, "0", "0", "很好，召集人反攻總部吧。", "0", "0", "0", "0", "0", "cv_roki_38", "0", "0"},
[403437] = {403437, 10034, 39, 31, "0", "0", "我也挺想要那種看著很厲害的裝備。", "0", "0", "0", "0", "0", "cv_roki_39", "0", "0"},
[403438] = {403438, 10034, 40, 32, "0", "0", "一起逛逛吧。", "0", "0", "0", "0", "0", "cv_roki_40", "0", "0"},
[403439] = {403439, 10034, 41, 33, "0", "0", "看來你也沒少被使喚。", "0", "0", "0", "0", "0", "cv_roki_41", "0", "0"},
[403440] = {403440, 10034, 42, 34, "0", "0", "忘帶東西了嗎？", "0", "0", "0", "0", "0", "cv_roki_42", "0", "0"},
[403441] = {403441, 10034, 43, 35, "0", "0", "想起來了？我正打算刪了呢。", "0", "0", "0", "0", "0", "cv_roki_43", "0", "0"},
[403442] = {403442, 10034, 44, 36, "0", "0", "留下文字記錄可不是什麼好事。", "0", "0", "0", "0", "0", "cv_roki_44", "0", "0"},
[403443] = {403443, 10034, 45, 37, "0", "0", "怎麼了？", "0", "0", "0", "0", "0", "cv_roki_45", "0", "0"},
[403500] = {403500, 10035, 1, 1, "0", "0", "蒼霧殘響", "0", "0", "0", "0", "0", "cv_heli_1", "0", "0"},
[403501] = {403501, 10035, 2, 2, "0", "0", "OK，這種事我還是挺擅長的，畢竟當了六年打雜的……呵呵……", "0", "0", "0", "0", "0", "cv_heli_2", "0", "0"},
[403502] = {403502, 10035, 3, 3, "0", "0", "你是領航……是吧？那我就是駕駛員了？對吧？沒錯吧？咳咳，我是赫莉·加西亞，是一名正式駕駛員！", "0", "0", "0", "0", "0", "cv_heli_3", "0", "0"},
[403503] = {403503, 10035, 4, 4, "0", "idle", "我以前對艾吉斯還挺憧憬的，結果來了之後才發現到處都是些怪人，這就是適者生存吧，普通人早就待不下去了，切斯頓也是這樣，可能哪裡都一樣吧。", "0", "0", "0", "0", "0", "cv_heli_4", "0", "0"},
[403504] = {403504, 10035, 5, 4, "0", "idle", "駕駛員的假期比想像中要多不少，這樣一來我就可以經常回去嘲笑以前的店老闆了，讓她瞧不起我。", "0", "0", "0", "0", "0", "cv_heli_5", "0", "0"},
[403505] = {403505, 10035, 6, 4, "0", "idle", "……說起來，因為各種各樣的原因，我幾乎沒有和其他隊友好好聊過，她們的臉和名字我都不一定對得上，真是一點也不成熟啊。", "0", "0", "0", "0", "0", "cv_heli_6", "0", "0"},
[403506] = {403506, 10035, 7, 5, "1_》_0_0.8", "level1", "不同人追求的幸福是有不同重量的。有的人想要的是“10”，有的人則是“100”。我的話……總之，先以變成正數為目標吧。", "0", "0", "0", "0", "0", "cv_heli_7", "0", "0"},
[403507] = {403507, 10035, 8, 5, "1_》_0_0.8", "level1", "只要不戰鬥的話，駕駛員的工作還蠻輕鬆的。", "0", "0", "0", "0", "0", "cv_heli_8", "0", "0"},
[403508] = {403508, 10035, 9, 5, "1_》_100_1.5", "level2", "想吃牛肋骨……想吃牛排……廣告上把它們拍得太美味了啦……你能請我吃嗎？", "0", "0", "0", "0", "0", "cv_heli_9", "0", "0"},
[403509] = {403509, 10035, 10, 5, "1_》_500_2", "level3", "你的時間真的是被工作擠得滿滿……喂，找個時間，我們偷偷溜出去玩吧？我知道一個很適合發洩壓力，淨化心靈的地方。", "0", "0", "0", "0", "0", "cv_heli_10", "0", "0"},
[403510] = {403510, 10035, 11, 5, "1_》_1000_2.5", "level4", "嗚啊啊……真是心煩，這種心情還是第一次，太奇怪了，我居然也會有這種不切實際的想法嗎？喂，領航，答應我，絕對不要騙我，也絕對不要突然消失，可以吧？沒問題的吧？", "0", "0", "0", "0", "0", "cv_heli_11", "0", "0"},
[403511] = {403511, 10035, 12, 6, "0", "0", "該怎麼說……感謝培養？", "0", "0", "0", "0", "0", "cv_heli_12", "0", "0"},
[403512] = {403512, 10035, 13, 7, "0", "0", "怪怪的感覺……", "0", "0", "0", "0", "0", "cv_heli_13", "0", "0"},
[403513] = {403513, 10035, 14, 8, "0", "0", "我不太習慣你這類好人……一開始還以為會被冷落呢……謝謝啦。", "0", "0", "0", "0", "0", "cv_heli_14", "0", "0"},
[403514] = {403514, 10035, 15, 9, "0", "0", "謝、謝謝。", "0", "0", "0", "0", "0", "cv_heli_15", "0", "0"},
[403515] = {403515, 10035, 16, 10, "0", "0", "早點結束，早點回家！", "0", "0", "0", "0", "0", "cv_heli_16", "0", "0"},
[403516] = {403516, 10035, 17, 11, "0", "0", "嚇了我一跳，我原來這麼厲害嗎？", "0", "0", "0", "0", "0", "cv_heli_17", "0", "0"},
[403517] = {403517, 10035, 18, 12, "0", "0", "要知足，做到這個程度已經可以了啦。", "0", "0", "0", "0", "0", "cv_heli_18", "0", "0"},
[403518] = {403518, 10035, 19, 13, "0", "0", "總比輸掉要好吧？", "0", "0", "0", "0", "0", "cv_heli_19", "0", "0"},
[403519] = {403519, 10035, 20, 14, "0", "0", "我還真沒想過會輸……", "0", "0", "0", "0", "0", "cv_heli_20", "0", "0"},
[403520] = {403520, 10035, 21, 15, "0", "0", "Next。", "0", "0", "0", "0", "0", "cv_heli_21", "0", "0"},
[403521] = {403521, 10035, 23, 16, "0", "0", "要上了。", "0", "0", "0", "0", "0", "cv_heli_23", "0", "0"},
[403522] = {403522, 10035, 24, 17, "0", "0", "切。", "0", "0", "0", "0", "0", "cv_heli_24", "0", "0"},
[403523] = {403523, 10035, 26, 19, "0", "0", "不是吧……", "0", "0", "0", "0", "0", "cv_heli_25", "0", "0"},
[403524] = {403524, 10035, 27, 20, "0", "0", "我的常識正在告訴我這不合理。", "0", "0", "0", "0", "0", "cv_heli_26", "0", "0"},
[403525] = {403525, 10035, 28, 21, "0", "0", "我正試著通過無視你來保證我的神經不崩壞。", "0", "0", "0", "0", "0", "cv_heli_27", "0", "0"},
[403526] = {403526, 10035, 29, 21, "0", "0", "要是你想看到我害羞丟臉的樣子，那就死心吧，我是絕對不會出醜的！", "0", "0", "0", "0", "0", "cv_heli_28", "0", "0"},
[403527] = {403527, 10035, 30, 22, "0", "0", "怎、怎麼了？！", "0", "0", "0", "0", "0", "cv_heli_29", "0", "0"},
[403528] = {403528, 10035, 31, 23, "0", "0", "有點意思……猜猜我是誰？", "0", "0", "0", "0", "0", "cv_heli_30", "0", "0"},
[403529] = {403529, 10035, 32, 24, "0", "0", "答對啦！姑且是件好事吧？", "0", "0", "0", "0", "0", "cv_heli_31", "0", "0"},
[403530] = {403530, 10035, 33, 25, "0", "0", "答錯了，看來你真的和我不熟呢。", "0", "0", "0", "0", "0", "cv_heli_32", "0", "0"},
[403531] = {403531, 10035, 34, 26, "0", "0", "歡迎回來……對了，有女孩子找你……你還真是有夠受歡迎的。", "0", "0", "0", "0", "0", "cv_heli_33", "0", "0"},
[403532] = {403532, 10035, 35, 27, "0", "0", "那麼，今天又要去哪裡鬧騰呢？", "0", "0", "0", "0", "0", "cv_heli_34", "0", "0"},
[403533] = {403533, 10035, 36, 28, "0", "0", "不想進行無意義的戰鬥呀。", "0", "0", "0", "0", "0", "cv_heli_35", "0", "0"},
[403534] = {403534, 10035, 37, 29, "0", "0", "要是當時大家都在，可能結果就不一樣了吧。", "0", "0", "0", "0", "0", "cv_heli_36", "0", "0"},
[403535] = {403535, 10035, 38, 30, "0", "0", "又要有人被騙來當炮灰咯。", "0", "0", "0", "0", "0", "cv_heli_37", "0", "0"},
[403536] = {403536, 10035, 39, 31, "0", "0", "真希望你能把這些錢交給我。", "0", "0", "0", "0", "0", "cv_heli_38", "0", "0"},
[403537] = {403537, 10035, 40, 32, "0", "0", "想買什麼就買什麼吧，反正花的不是我存的錢。", "0", "0", "0", "0", "0", "cv_heli_39", "0", "0"},
[403538] = {403538, 10035, 41, 33, "0", "0", "我還以為你和我一樣是新人……", "0", "0", "0", "0", "0", "cv_heli_40", "0", "0"},
[403539] = {403539, 10035, 42, 34, "0", "0", "要再確認一次嗎？", "0", "0", "0", "0", "0", "cv_heli_41", "0", "0"},
[403540] = {403540, 10035, 43, 35, "0", "0", "你不會指望我幫你整理吧？", "0", "0", "0", "0", "0", "cv_heli_42", "0", "0"},
[403541] = {403541, 10035, 44, 36, "0", "0", "沒有興趣。", "0", "0", "0", "0", "0", "cv_heli_43", "0", "0"},
[403542] = {403542, 10035, 45, 37, "0", "0", "嗯？", "0", "0", "0", "0", "0", "cv_heli_44", "0", "0"},
[403600] = {403600, 10036, 1, 1, "0", "0", "蒼霧殘響", "0", "0", "0", "0", "0", "cv_chalisha_vd_1", "0", "0"},
[403601] = {403601, 10036, 2, 2, "0", "0", "竟，竟然讓本小姐穿著這樣的衣服陪你……", "0", "0", "0", "0", "0", "cv_chalisha_vd_2", "0", "0"},
[403602] = {403602, 10036, 3, 3, "0", "0", "這是巧克力……我只是順手拿來的，別把它當成什麼特別的東西。", "0", "0", "0", "0", "0", "cv_chalisha_vd_3", "0", "0"},
[403603] = {403603, 10036, 4, 4, "0", "idle", "情人節？真是無聊，不過既然是你邀請了，那，那本小姐也不是不能和你一起過……", "0", "0", "0", "0", "0", "cv_chalisha_vd_4", "0", "0"},
[403604] = {403604, 10036, 5, 4, "0", "idle", "巧克力很好吃？那當然啦！本小姐可是努力了好久好久……啊……沒什麼……我什麼都沒說……你聽到了？", "0", "0", "0", "0", "0", "cv_chalisha_vd_5", "0", "0"},
[403605] = {403605, 10036, 6, 4, "0", "idle", "這不過是一點點小禮物，不必太在意……好吃？太好了！太好了！——本小姐的手藝果然是是天下第一……", "0", "0", "0", "0", "0", "cv_chalisha_vd_6", "0", "0"},
[403606] = {403606, 10036, 7, 5, "1_》_0_0.8", "level1", "這個日子的意義，我一定會牢牢地抓住的，給我等著吧！", "0", "0", "0", "0", "0", "cv_chalisha_vd_7", "0", "0"},
[403607] = {403607, 10036, 8, 5, "1_》_0_0.8", "level1", "這件衣服本小姐只會穿這一次哦，你可要好好珍惜……如果這次不能成功的話……我就……我就……嗚嗚嗚……", "0", "0", "0", "0", "0", "cv_chalisha_vd_8", "0", "0"},
[403608] = {403608, 10036, 9, 5, "1_》_100_1.5", "level2", "嗯，其實這點小禮物是我用心挑選的，希望你會喜歡……畢竟領航……領航是本小姐生命中……生命中……第一個遇到的朋友。", "0", "0", "0", "0", "0", "cv_chalisha_vd_9", "0", "0"},
[403609] = {403609, 10036, 10, 5, "1_》_500_2", "level3", "第一次被人這麼對待，第一次和你一起挑選衣服，第一次和你吵架……現在回想起來……這些第一次竟然這麼讓人安心……領航……", "0", "0", "0", "0", "0", "cv_chalisha_vd_10", "0", "0"},
[403610] = {403610, 10036, 11, 5, "1_》_1000_2.5", "level4", "本小姐不會覺得後悔的，所以——要把對我的感情一直記在心裡啊，呆子……", "0", "0", "0", "0", "0", "cv_chalisha_vd_11", "0", "0"},
[403611] = {403611, 10036, 12, 6, "0", "0", "就陪你再來一次吧。", "0", "0", "0", "0", "0", "cv_chalisha_vd_12", "0", "0"},
[403612] = {403612, 10036, 13, 7, "0", "0", "在這身衣服穿在身上的時候，我便知曉了我的心意。", "0", "0", "0", "0", "0", "cv_chalisha_vd_29", "0", "0"},
[403613] = {403613, 10036, 14, 8, "0", "0", "啊……啊……我明白了。", "0", "0", "0", "0", "0", "cv_chalisha_vd_14", "0", "0"},
[403614] = {403614, 10036, 15, 9, "0", "0", "多麼燦爛啊……我的感情。", "0", "0", "0", "0", "0", "cv_chalisha_vd_15", "0", "0"},
[403615] = {403615, 10036, 16, 10, "0", "0", "快點結束回去吧，我有話要對領航講呢。", "0", "0", "0", "0", "0", "cv_chalisha_vd_16", "0", "0"},
[403616] = {403616, 10036, 17, 11, "0", "0", "呼呼，還是打原罪讓人安心。", "0", "0", "0", "0", "0", "cv_chalisha_vd_17", "0", "0"},
[403617] = {403617, 10036, 18, 12, "0", "0", "……為什麼我會失誤。", "0", "0", "0", "0", "0", "cv_chalisha_vd_18", "0", "0"},
[403618] = {403618, 10036, 19, 13, "0", "0", "我我我……才沒有一邊戰鬥一邊在想領航的事情呢！", "0", "0", "0", "0", "0", "cv_chalisha_vd_19", "0", "0"},
[403619] = {403619, 10036, 20, 14, "0", "0", "搞砸了……怎麼會這樣……", "0", "0", "0", "0", "0", "cv_chalisha_vd_20", "0", "0"},
[403620] = {403620, 10036, 21, 15, "0", "0", "搞定了！", "0", "0", "0", "0", "0", "cv_chalisha_vd_21", "0", "0"},
[403621] = {403621, 10036, 23, 16, "0", "0", "別擋我！", "0", "0", "0", "0", "0", "cv_chalisha_vd_23", "0", "0"},
[403622] = {403622, 10036, 24, 17, "0", "0", "滾開！", "0", "0", "0", "0", "0", "cv_chalisha_vd_24", "0", "0"},
[403623] = {403623, 10036, 25, 18, "0", "0", "不要妨礙我！全部消失吧！", "0", "0", "0", "0", "0", "cv_chalisha_vd_25", "0", "0"},
[403624] = {403624, 10036, 26, 19, "0", "0", "還沒有傳達出的感情……", "0", "0", "0", "0", "0", "cv_chalisha_vd_26", "0", "0"},
[403625] = {403625, 10036, 27, 20, "0", "0", "怎，怎麼了，一直在那裡盯著看個不停……本小姐吸引了你的目光？哼，算你有眼光！", "0", "0", "0", "0", "0", "cv_chalisha_vd_27", "0", "0"},
[403626] = {403626, 10036, 28, 21, "0", "0", "因為你，本小姐才會變成這樣，本小姐是想說，還好能遇見你。", "0", "0", "0", "0", "0", "cv_chalisha_vd_28", "0", "0"},
[403627] = {403627, 10036, 29, 21, "0", "0", "心裡熱熱的……以前也是這個樣子嗎……", "0", "0", "0", "0", "0", "cv_chalisha_vd_13", "0", "0"},
[403628] = {403628, 10036, 30, 22, "0", "0", "本小姐就破例和你一起看看，我可沒在擔心什麼……", "0", "0", "0", "0", "0", "cv_chalisha_vd_30", "0", "0"},
[403629] = {403629, 10036, 31, 23, "0", "0", "你不會認不出本小姐吧——", "0", "0", "0", "0", "0", "cv_chalisha_vd_31", "0", "0"},
[403630] = {403630, 10036, 32, 24, "0", "0", "哼哼，不錯嘛，能感受到我的心意，算是你的福氣。", "0", "0", "0", "0", "0", "cv_chalisha_vd_32", "0", "0"},
[403631] = {403631, 10036, 33, 25, "0", "0", "假的吧——————！", "0", "0", "0", "0", "0", "cv_chalisha_vd_33", "0", "0"},
[403632] = {403632, 10036, 34, 26, "0", "0", "糟糕了！？我還沒準備好！", "0", "0", "0", "0", "0", "cv_chalisha_vd_34", "0", "0"},
[403633] = {403633, 10036, 35, 27, "0", "0", "一起走吧！", "0", "0", "0", "0", "0", "cv_chalisha_vd_35", "0", "0"},
[403634] = {403634, 10036, 36, 28, "0", "0", "這裡還是和以前一樣呢。", "0", "0", "0", "0", "0", "cv_chalisha_vd_36", "0", "0"},
[403635] = {403635, 10036, 37, 29, "0", "0", "都是珍貴的邂逅嗎……", "0", "0", "0", "0", "0", "cv_chalisha_vd_37", "0", "0"},
[403636] = {403636, 10036, 38, 30, "0", "0", "習以為常了。", "0", "0", "0", "0", "0", "cv_chalisha_vd_38", "0", "0"},
[403637] = {403637, 10036, 39, 31, "0", "0", "發著光呢，這些裝備。", "0", "0", "0", "0", "0", "cv_chalisha_vd_39", "0", "0"},
[403638] = {403638, 10036, 40, 32, "0", "0", "今天晚上想吃什麼？", "0", "0", "0", "0", "0", "cv_chalisha_vd_40", "0", "0"},
[403639] = {403639, 10036, 41, 33, "0", "0", "從今往後會有我的故事被記錄在這裡嗎？", "0", "0", "0", "0", "0", "cv_chalisha_vd_41", "0", "0"},
[403640] = {403640, 10036, 42, 34, "0", "0", "請再對我說些什麼吧。", "0", "0", "0", "0", "0", "cv_chalisha_vd_42", "0", "0"},
[403641] = {403641, 10036, 43, 35, "0", "0", "想向你傳達……", "0", "0", "0", "0", "0", "cv_chalisha_vd_43", "0", "0"},
[403642] = {403642, 10036, 44, 36, "0", "0", "不可思議的地方呢。", "0", "0", "0", "0", "0", "cv_chalisha_vd_44", "0", "0"},
[403643] = {403643, 10036, 45, 37, "0", "0", "好極了。", "0", "0", "0", "0", "0", "cv_chalisha_vd_45", "0", "0"},
[403700] = {403700, 10037, 1, 1, "0", "0", "蒼霧殘響。", "ハツリバーブ", "0", "0", "0", "0", "cv_zhensusi_01", "0", "0"},
[403701] = {403701, 10037, 2, 2, "0", "0", "眞把我當警備員了啊。", "警備員扱いですか。", "0", "0", "0", "0", "cv_zhensusi_02", "0", "0"},
[403702] = {403702, 10037, 3, 3, "0", "0", "你就是領航？那个上輩子毁滅了宇宙的人……就叫我軫宿四吧，免得和某个紅頭發的家夥搞混了。", "あなたがナビゲーターですか？あの前世に宇宙を破壊した人……クラズと呼んでください、赤い髪の誰かさんと間違わないようにね。", "0", "0", "0", "0", "cv_zhensusi_03", "0", "0"},
[403703] = {403703, 10037, 4, 4, "0", "idle", "她們從沒有想到我能活下，更沒想到我會站在這裏……其實我也沒想過能有一天會變成這樣。", "僕が生き延びたことも、ここに立ってることも、彼女たちは想像もしていなかったでしょう……僕もです。", "0", "0", "0", "0", "cv_zhensusi_04", "0", "0"},
[403704] = {403704, 10037, 5, 4, "0", "idle", "支撐著不讓這片盾牌倒下來可是很累的……要不你來試試？", "盾を支えるのも結構疲れますよ……なんなら試してみますか？", "0", "0", "0", "0", "cv_zhensusi_05", "0", "0"},
[403705] = {403705, 10037, 6, 4, "0", "idle", "唔……你知道哪裏有小醜嗎？像是銀白色頭發，頂著个紅鼻子，臉上畫著夸張笑臉的人。沒有紅鼻子和笑臉？那可能是我記錯了。", "うーん……ピエロを見かけませんでしたか？白い髪に、赤い鼻、そして大きな笑顔が描かれている人。赤い鼻と笑顔はない？僕が間違えたかもしれません。", "0", "0", "0", "0", "cv_zhensusi_06", "0", "0"},
[403706] = {403706, 10037, 7, 5, "1_》_0_0.8", "level1", "我沒想過復仇，不管是在四年前還是更早的時候。能够過上安穩的生活我已經謝天謝地。就是有時候心裏會憋著一股氣，想找个樹洞發泄一下。", "復讐なんて考えたことはありません、四年前も、その前も。穏やかな日々を過ごせたら万々歳です。ただ時には、穴の空いた切り株に胸のモヤモヤを喚き散らしたいです。", "0", "0", "0", "0", "cv_zhensusi_07", "0", "0"},
[403707] = {403707, 10037, 8, 5, "1_》_0_0.8", "level1", "我不喜歡這頂帽子，又小又緊，連我的臉都遮不住。", "この帽子は好きではありません。小さいしきついし、顔も隠せません。", "0", "0", "0", "0", "cv_zhensusi_08", "0", "0"},
[403708] = {403708, 10037, 9, 5, "1_》_100_1.5", "level2", "從硏究所中脫身之後，我本想離開印加這个是非之地，如今我站在這裏，依仗的卻是印加隸屬的駕駛員身份。", "研究所から脱出した後、インカという危険な場所から離れたかったのですが、今ここにいられるのはインカに所属するドライバーという肩書きのおかげです。", "0", "0", "0", "0", "cv_zhensusi_09", "0", "0"},
[403709] = {403709, 10037, 10, 5, "1_》_500_2", "level3", "有空一起去遊泳吧，我對自己的遊泳技術可是很有自信的。畢竟是我用命換來的本領。", "時間があるときに一緒に泳ぎに行きませんか？自分の泳ぎには自信があります。命をかけて得た技術ですので。", "0", "0", "0", "0", "cv_zhensusi_10", "0", "0"},
[403710] = {403710, 10037, 11, 5, "1_》_1000_2.5", "level4", "“維嘉”、“警備員”、“軫宿四”，我好像一直在扮演這些不討人喜歡的角色。要是讓我按照自己想法選的話……有了！我要當你的“戀人”，或者“女兒”也可以。", "「ベガ」、「警備員」、「クラズ」、僕はずっと嫌われ役を演じているように感じます。もし僕の好きなように選べるなら……そうですね、あなたの「恋人」になりたいです、もしくは「娘」でも構いません。", "0", "0", "0", "0", "cv_zhensusi_11", "0", "0"},
[403711] = {403711, 10037, 12, 6, "0", "0", "會長高嗎？", "背が伸びるでしょうか？", "0", "0", "0", "0", "cv_zhensusi_12", "0", "0"},
[403712] = {403712, 10037, 13, 7, "0", "0", "放在肩章上更合適。", "肩章に置く方がもっと似合うかもしれません。", "0", "0", "0", "0", "cv_zhensusi_13", "0", "0"},
[403713] = {403713, 10037, 14, 8, "0", "0", "如果在四年前掌握這力量就好了……", "4年前にこの力を持っていたらよかったのですが……", "0", "0", "0", "0", "cv_zhensusi_14", "0", "0"},
[403714] = {403714, 10037, 15, 9, "0", "0", "眞不考慮換掉這塊盾牌嗎？這對我來説完全是阻礙。", "本当にこの盾を変えようとは思わないのですか？僕にとっては完全に邪魔なのですが。", "0", "0", "0", "0", "cv_zhensusi_15", "0", "0"},
[403715] = {403715, 10037, 16, 10, "0", "0", "我……我不要站最前排。", "僕は……最前列には立ちたくありません。", "0", "0", "0", "0", "cv_zhensusi_16", "0", "0"},
[403716] = {403716, 10037, 17, 11, "0", "0", "贏了？總算是熬過去了。", "勝ったのですか？やっと耐え抜きました。", "0", "0", "0", "0", "cv_zhensusi_17", "0", "0"},
[403717] = {403717, 10037, 18, 12, "0", "0", "好險，多虧了這塊盾牌。", "危なかった、盾のおかげです。", "0", "0", "0", "0", "cv_zhensusi_18", "0", "0"},
[403718] = {403718, 10037, 19, 13, "0", "0", "又活過了一天。", "また一日生き延びました。", "0", "0", "0", "0", "cv_zhensusi_19", "0", "0"},
[403719] = {403719, 10037, 20, 14, "0", "0", "還活著就好……", "生きていてよかった……", "0", "0", "0", "0", "cv_zhensusi_20", "0", "0"},
[403720] = {403720, 10037, 21, 15, "0", "0", "意外收獲。", "意外な収穫です。", "0", "0", "0", "0", "cv_zhensusi_21", "0", "0"},
[403721] = {403721, 10037, 23, 16, "0", "0", "我只管開槍。", "僕はただ撃つだけ。", "0", "0", "0", "0", "cv_zhensusi_23", "0", "0"},
[403722] = {403722, 10037, 24, 17, "0", "0", "餧，你想去哪兒？", "ねぇ、どこに行くんですか？", "0", "0", "0", "0", "cv_zhensusi_24", "0", "0"},
[403723] = {403723, 10037, 25, 18, "0", "0", "赶緊死吧，掙紥是很痛苦的。", "はやくくたばってください、もがく姿を見るのは辛いのですから。", "0", "0", "0", "0", "cv_zhensusi_25", "0", "0"},
[403724] = {403724, 10037, 26, 19, "0", "0", "趁著還沒倒下……", "倒れる前に……", "0", "0", "0", "0", "cv_zhensusi_26", "0", "0"},
[403725] = {403725, 10037, 27, 20, "0", "0", "只要不是水池就好。", "水の中でなければいいのです。", "0", "0", "0", "0", "cv_zhensusi_27", "0", "0"},
[403726] = {403726, 10037, 28, 21, "0", "0", "小有小的好處，例如趴著的時候不會感到胸悶。", "小さいにも小さいなりの利点があります、例えばうつ伏せの時は苦しくない、とか。", "0", "0", "0", "0", "cv_zhensusi_28", "0", "0"},
[403727] = {403727, 10037, 29, 21, "0", "0", "有日光浴嗎？我想把皮膚顔色曬深一點。", "日焼けはできますか？肌の色を少し黒くしたいのですが。", "0", "0", "0", "0", "cv_zhensusi_29", "0", "0"},
[403728] = {403728, 10037, 30, 22, "0", "0", "這又是什麽玩法？", "これは何の遊びですか？", "0", "0", "0", "0", "cv_zhensusi_30", "0", "0"},
[403729] = {403729, 10037, 31, 23, "0", "0", "猜人遊戲……讓我想起了在收容所的日子。", "人を当てるゲーム……収容所の日々を思い出させますね。", "0", "0", "0", "0", "cv_zhensusi_31", "0", "0"},
[403730] = {403730, 10037, 32, 24, "0", "0", "“軫宿四”是我，“維嘉”也是我。", "「クラズ」は僕で、「ベガ」も僕です。", "0", "0", "0", "0", "cv_zhensusi_32", "0", "0"},
[403731] = {403731, 10037, 33, 25, "0", "0", "“S70”下次還是記這个代號吧。", "「S70」、このコードネームのほうが覚えやすいですかね。", "0", "0", "0", "0", "cv_zhensusi_33", "0", "0"},
[403732] = {403732, 10037, 34, 26, "0", "0", "報告領航，您離開的時間裏沒有發現可疑人員。", "報告します、ナビゲーター、あなたがいなかった間に怪しい人物はいませんでした。", "0", "0", "0", "0", "cv_zhensusi_34", "0", "0"},
[403733] = {403733, 10037, 35, 27, "0", "0", "想送死的請走這邊。", "死にたい方はこちらへ。", "0", "0", "0", "0", "cv_zhensusi_35", "0", "0"},
[403734] = {403734, 10037, 36, 28, "0", "0", "想報復的請走這邊。", "復讐したい方はこちらへ。", "0", "0", "0", "0", "cv_zhensusi_36", "0", "0"},
[403735] = {403735, 10037, 37, 29, "0", "0", "原來你並不缺少保鏢。", "あなたのボディーガードがいないわけではないですよね。", "0", "0", "0", "0", "cv_zhensusi_37", "0", "0"},
[403736] = {403736, 10037, 38, 30, "0", "0", "好像看到了幾个熟人。", "知っている人を何人か見かけました。", "0", "0", "0", "0", "cv_zhensusi_38", "0", "0"},
[403737] = {403737, 10037, 39, 31, "0", "0", "終於能換頂帽子了。", "やっと帽子を替えられるのですね。", "0", "0", "0", "0", "cv_zhensusi_39", "0", "0"},
[403738] = {403738, 10037, 40, 32, "0", "0", "好貴……", "高いですね……", "0", "0", "0", "0", "cv_zhensusi_40", "0", "0"},
[403739] = {403739, 10037, 41, 33, "0", "0", "沒想到領航是這樣的大人物。", "ナビゲーターがこんなに大物だとは思いませんでした。", "0", "0", "0", "0", "cv_zhensusi_41", "0", "0"},
[403740] = {403740, 10037, 42, 34, "0", "0", "你來。", "どうぞ。", "0", "0", "0", "0", "cv_zhensusi_42", "0", "0"},
[403741] = {403741, 10037, 43, 35, "0", "0", "給我个查看權限吧。", "僕に権限を与えてください。", "0", "0", "0", "0", "cv_zhensusi_43", "0", "0"},
[403742] = {403742, 10037, 44, 36, "0", "0", "匿名？我喜歡。", "匿名？いいですね。", "0", "0", "0", "0", "cv_zhensusi_44", "0", "0"},
[403743] = {403743, 10037, 45, 37, "0", "0", "嘿嘿。", "へへ。", "0", "0", "0", "0", "cv_zhensusi_45", "0", "0"},
[403800] = {403800, 10038, 1, 1, "0", "0", "蒼霧殘響~", "0", "0", "0", "0", "0", "cv_heluoka_1", "0", "0"},
[403801] = {403801, 10038, 2, 2, "0", "0", "如果是在河邊就更好了。", "0", "0", "0", "0", "0", "cv_heluoka_2", "0", "0"},
[403802] = {403802, 10038, 3, 3, "0", "0", "又見面了領航，這次換我來你這裏做客了……領航看上去好像不是很歡迎我？", "0", "0", "0", "0", "0", "cv_heluoka_3", "0", "0"},
[403803] = {403803, 10038, 4, 4, "0", "idle", "我先睡一會兒，等有魚咬鉤了叫醒我。", "0", "0", "0", "0", "0", "cv_heluoka_4", "0", "0"},
[403804] = {403804, 10038, 5, 4, "0", "idle", "“無事發生”也算是“意料之外”吧。", "0", "0", "0", "0", "0", "cv_heluoka_5", "0", "0"},
[403805] = {403805, 10038, 6, 4, "0", "idle", "聖誕節之後我算是徹底失業了，被第一研究室停職，也禁止我去其他研究室……或許我該去投奔其他“守夜人”試試，不過她們人在天南地北的實在不好找。", "0", "0", "0", "0", "0", "cv_heluoka_6", "0", "0"},
[403806] = {403806, 10038, 7, 5, "1_》_0_0.8", "level1", "釣魚最有趣的點在於無論是老手還是菜鳥，無論漁具和魚餌准備得多充分，上不上鉤都得看魚的心情。做實驗也一樣。", "0", "0", "0", "0", "0", "cv_heluoka_7", "0", "0"},
[403807] = {403807, 10038, 8, 5, "1_》_0_0.8", "level1", "噓，別把魚兒嚇跑了，我在等它們自己跳上來。", "0", "0", "0", "0", "0", "cv_heluoka_8", "0", "0"},
[403808] = {403808, 10038, 9, 5, "1_》_100_1.5", "level2", "餌料的配比會直接影響魚咬鉤的頻率。不過隨便亂弄的話，也有可能吸引到一些稀有的品種。", "0", "0", "0", "0", "0", "cv_heluoka_9", "0", "0"},
[403809] = {403809, 10038, 10, 5, "1_》_500_2", "level3", "聖誕節的事我不後悔，所以我要道歉，為我的不悔道歉。但即使重來一次我還是會做出同樣的選擇，因為我想看看那突破生命桎梏的可能性。", "0", "0", "0", "0", "0", "cv_heluoka_10", "0", "0"},
[403810] = {403810, 10038, 11, 5, "1_》_1000_2.5", "level4", "領航在感情上就像個老練的釣手，隨手撒出一把餌料便能引來眾多的魚兒，而我也在其中成了最想接近你的那幾條魚的其中之一。現在，我要准備咬鉤了。", "0", "0", "0", "0", "0", "cv_heluoka_11", "0", "0"},
[403811] = {403811, 10038, 12, 6, "0", "0", "平平無奇。", "0", "0", "0", "0", "0", "cv_heluoka_12", "0", "0"},
[403812] = {403812, 10038, 13, 7, "0", "0", "有趣的提升方式。", "0", "0", "0", "0", "0", "cv_heluoka_13", "0", "0"},
[403813] = {403813, 10038, 14, 8, "0", "0", "這倒是出乎我的意料了。", "0", "0", "0", "0", "0", "cv_heluoka_14", "0", "0"},
[403814] = {403814, 10038, 15, 9, "0", "0", "我覺得也不是很有必要。", "0", "0", "0", "0", "0", "cv_heluoka_15", "0", "0"},
[403815] = {403815, 10038, 16, 10, "0", "0", "吸引了很多“魚”嘛。", "0", "0", "0", "0", "0", "cv_heluoka_16", "0", "0"},
[403816] = {403816, 10038, 17, 11, "0", "0", "你怎麼知道我釣上了大魚？", "0", "0", "0", "0", "0", "cv_heluoka_17", "0", "0"},
[403817] = {403817, 10038, 18, 12, "0", "0", "正常情況，下次早點拉杆。", "0", "0", "0", "0", "0", "cv_heluoka_18", "0", "0"},
[403818] = {403818, 10038, 19, 13, "0", "0", "至少不是一無所獲。", "0", "0", "0", "0", "0", "cv_heluoka_19", "0", "0"},
[403819] = {403819, 10038, 20, 14, "0", "0", "空軍了……", "0", "0", "0", "0", "0", "cv_heluoka_20", "0", "0"},
[403820] = {403820, 10038, 21, 15, "0", "0", "上鉤。", "0", "0", "0", "0", "0", "cv_heluoka_21", "0", "0"},
[403821] = {403821, 10038, 23, 16, "0", "0", "被魚竿砸到可是很痛的。", "0", "0", "0", "0", "0", "cv_heluoka_22", "0", "0"},
[403822] = {403822, 10038, 24, 17, "0", "0", "可別期待我先松手。", "0", "0", "0", "0", "0", "cv_heluoka_23", "0", "0"},
[403823] = {403823, 10038, 25, 18, "0", "0", "拿你作為今天的收杆魚。", "0", "0", "0", "0", "0", "cv_heluoka_25", "0", "0"},
[403824] = {403824, 10038, 26, 19, "0", "0", "我回去拿備用竿。", "0", "0", "0", "0", "0", "cv_heluoka_26", "0", "0"},
[403825] = {403825, 10038, 27, 20, "0", "0", "有水的地方就有魚。", "0", "0", "0", "0", "0", "cv_heluoka_27", "0", "0"},
[403826] = {403826, 10038, 28, 21, "0", "0", "身上有汗味？是穿的裝甲太厚的緣故吧，巨大化後的身體也還是會流汗的。", "0", "0", "0", "0", "0", "cv_heluoka_28", "0", "0"},
[403827] = {403827, 10038, 29, 21, "0", "0", "溝溝縫縫裏都要清洗幹淨哦，拜托了。", "0", "0", "0", "0", "0", "cv_heluoka_29", "0", "0"},
[403828] = {403828, 10038, 30, 22, "0", "0", "到底會發生什麼呢？", "0", "0", "0", "0", "0", "cv_heluoka_30", "0", "0"},
[403829] = {403829, 10038, 31, 23, "0", "0", "我期待領航的答案。", "0", "0", "0", "0", "0", "cv_heluoka_31", "0", "0"},
[403830] = {403830, 10038, 32, 24, "0", "0", "領航記得還真清楚……", "0", "0", "0", "0", "0", "cv_heluoka_32", "0", "0"},
[403831] = {403831, 10038, 33, 25, "0", "0", "果然我這種人不值得被領航記住。", "0", "0", "0", "0", "0", "cv_heluoka_33", "0", "0"},
[403832] = {403832, 10038, 34, 26, "0", "0", "歡迎回來，猜猜看在你離開的這段時間裏，我釣上了幾條大魚。", "0", "0", "0", "0", "0", "cv_heluoka_34", "0", "0"},
[403833] = {403833, 10038, 35, 27, "0", "0", "來點出人意料的展開。", "0", "0", "0", "0", "0", "cv_heluoka_35", "0", "0"},
[403834] = {403834, 10038, 36, 28, "0", "0", "戰前就確定的結局，無聊。", "0", "0", "0", "0", "0", "cv_heluoka_36", "0", "0"},
[403835] = {403835, 10038, 37, 29, "0", "0", "你們之間一定發生過很多有趣的事。", "0", "0", "0", "0", "0", "cv_heluoka_37", "0", "0"},
[403836] = {403836, 10038, 38, 30, "0", "0", "下一個上鉤的會是哪位？", "0", "0", "0", "0", "0", "cv_heluoka_38", "0", "0"},
[403837] = {403837, 10038, 39, 31, "0", "0", "給我換一身清涼些的裝甲。", "0", "0", "0", "0", "0", "cv_heluoka_39", "0", "0"},
[403838] = {403838, 10038, 40, 32, "0", "0", "不需要新魚竿了。", "0", "0", "0", "0", "0", "cv_heluoka_40", "0", "0"},
[403839] = {403839, 10038, 41, 33, "0", "0", "告訴我一些檔案上沒有的事吧。", "0", "0", "0", "0", "0", "cv_heluoka_41", "0", "0"},
[403840] = {403840, 10038, 42, 34, "0", "0", "這個按鈕按下去會發什麼？我按。", "0", "0", "0", "0", "0", "cv_heluoka_42", "0", "0"},
[403841] = {403841, 10038, 43, 35, "0", "0", "釣魚郵件？", "0", "0", "0", "0", "0", "cv_heluoka_43", "0", "0"},
[403842] = {403842, 10038, 44, 36, "0", "0", "驚喜往往就藏在其中。", "0", "0", "0", "0", "0", "cv_heluoka_44", "0", "0"},
[403843] = {403843, 10038, 45, 37, "0", "0", "嗯。", "0", "0", "0", "0", "0", "cv_heluoka_45", "0", "0"},
[403900] = {403900, 10039, 1, 1, "0", "0", "蒼霧殘響！", "0", "0", "0", "0", "0", "cv_harriet_1", "0", "0"},
[403901] = {403901, 10039, 2, 2, "0", "0", "对手在哪里？……什么！你说这里不是擂台？", "0", "0", "0", "0", "0", "cv_harriet_2", "0", "0"},
[403902] = {403902, 10039, 3, 3, "0", "0", "嗬嗬……你就是领航？看着挺结实的，敢不敢接我一拳。", "0", "0", "0", "0", "0", "cv_harriet_3", "0", "0"},
[403903] = {403903, 10039, 4, 4, "0", "idle", "我可以在这里练拳击吗？", "0", "0", "0", "0", "0", "cv_harriet_4", "0", "0"},
[403904] = {403904, 10039, 5, 4, "0", "idle", "原罪！……原来只是个飞艇啊，唉……", "0", "0", "0", "0", "0", "cv_harriet_5", "0", "0"},
[403905] = {403905, 10039, 6, 4, "0", "idle", "这里的驾驶员不是玩枪就是玩鞭子的，想找个懂拳的对手真难啊。", "0", "0", "0", "0", "0", "cv_harriet_6", "0", "0"},
[403906] = {403906, 10039, 7, 5, "1_》_0_0.8", "leve", "冲动是拳击手唯一的敌人，越是头脑发昏的时候就越是要让自己冷静下来。冷静、观察、计算，最后打出制胜的那一拳。不过对于领航来说应该不用再强调这些了。", "0", "0", "0", "0", "0", "cv_harriet_7", "0", "0"},
[403907] = {403907, 10039, 8, 5, "1_》_0_0.8", "leve1", "给你一拳。", "0", "0", "0", "0", "0", "cv_harriet_8", "0", "0"},
[403908] = {403908, 10039, 9, 5, "1_》_100_1.5", "leve2", "别光痴迷别人的身体，领航你自己也要勤加锻炼。", "0", "0", "0", "0", "0", "cv_harriet_9", "0", "0"},
[403909] = {403909, 10039, 10, 5, "1_》_500_2", "leve3", "肩膀有些酸痛，难道是胸前的两团又重了吗……看来下次练拳的时候得要请领航帮忙托着了。", "0", "0", "0", "0", "0", "cv_harriet_10", "0", "0"},
[403910] = {403910, 10039, 11, 5, "1_》_1000_2.5", "leve4", "以前练拳的时候脑子里想的都是些拳赛的对手做假想敌。然而最近我满脑子出现的都是领航，这还让我怎么练习……我，没法对领航出拳啊！——", "0", "0", "0", "0", "0", "cv_harriet_11", "0", "0"},
[403911] = {403911, 10039, 12, 6, "0", "0", "拳头硬了。", "0", "0", "0", "0", "0", "cv_harriet_12", "0", "0"},
[403912] = {403912, 10039, 13, 7, "0", "0", "让敌人眼冒金星。", "0", "0", "0", "0", "0", "cv_harriet_13", "0", "0"},
[403913] = {403913, 10039, 14, 8, "0", "0", "今后破敌只需一拳。", "0", "0", "0", "0", "0", "cv_harriet_14", "0", "0"},
[403914] = {403914, 10039, 15, 9, "0", "0", "技巧的提升也很重要。", "0", "0", "0", "0", "0", "cv_harriet_15", "0", "0"},
[403915] = {403915, 10039, 16, 10, "0", "0", "对面竖着的那些，是沙袋吗？", "0", "0", "0", "0", "0", "cv_harriet_16", "0", "0"},
[403916] = {403916, 10039, 17, 11, "0", "0", "仅仅只是蛮力就搞定了。", "0", "0", "0", "0", "0", "cv_harriet_17", "0", "0"},
[403917] = {403917, 10039, 18, 12, "0", "0", "受伤是我的家常菜，不必在意。", "0", "0", "0", "0", "0", "cv_harriet_18", "0", "0"},
[403918] = {403918, 10039, 19, 13, "0", "0", "赢了就是赢了。", "0", "0", "0", "0", "0", "cv_harriet_19", "0", "0"},
[403919] = {403919, 10039, 20, 14, "0", "0", "失败的味道……好久没有尝过了。", "0", "0", "0", "0", "0", "cv_harriet_20", "0", "0"},
[403920] = {403920, 10039, 21, 15, "0", "0", "K.O，下一个是谁？", "0", "0", "0", "0", "0", "cv_harriet_21", "0", "0"},
[403921] = {403921, 10039, 23, 16, "0", "0", "直拳！勾拳！你在看哪呢？", "0", "0", "0", "0", "0", "cv_harriet_23", "0", "0"},
[403922] = {403922, 10039, 24, 17, "0", "0", "这拳接得住吗？", "0", "0", "0", "0", "0", "cv_harriet_24", "0", "0"},
[403923] = {403923, 10039, 25, 18, "0", "0", "速战速决，这一拳就决定胜负！", "0", "0", "0", "0", "0", "cv_harriet_25", "0", "0"},
[403924] = {403924, 10039, 26, 19, "0", "0", "再来啊！我还没有倒下！", "0", "0", "0", "0", "0", "cv_harriet_26", "0", "0"},
[403925] = {403925, 10039, 27, 20, "0", "0", "不错的地方嘛，有按摩服务吗？", "0", "0", "0", "0", "0", "cv_harriet_27", "0", "0"},
[403926] = {403926, 10039, 28, 21, "0", "0", "水温有点冷了，可我的肌肉还没冷却下来。", "0", "0", "0", "0", "0", "cv_harriet_28", "0", "0"},
[403927] = {403927, 10039, 29, 21, "0", "0", "训练的疲惫涌上来了……", "0", "0", "0", "0", "0", "cv_harriet_29", "0", "0"},
[403928] = {403928, 10039, 30, 22, "0", "0", "吓我一跳……差点就出拳了。", "0", "0", "0", "0", "0", "cv_harriet_30", "0", "0"},
[403929] = {403929, 10039, 31, 23, "0", "0", "呃……有比这更无聊的游戏吗？", "0", "0", "0", "0", "0", "cv_harriet_31", "0", "0"},
[403930] = {403930, 10039, 32, 24, "0", "0", "领航记性还蛮好的嘛。", "0", "0", "0", "0", "0", "cv_harriet_32", "0", "0"},
[403931] = {403931, 10039, 33, 25, "0", "0", "吃我一拳！", "0", "0", "0", "0", "0", "cv_harriet_33", "0", "0"},
[403932] = {403932, 10039, 34, 26, "0", "0", "嗬——嗬——领航，今天你又迟到了哦。", "0", "0", "0", "0", "0", "cv_harriet_34", "0", "0"},
[403933] = {403933, 10039, 35, 27, "0", "0", "任务下来了吗？这次要去哪里揍原罪？", "0", "0", "0", "0", "0", "cv_harriet_35", "0", "0"},
[403934] = {403934, 10039, 36, 28, "0", "0", "这里就是我想要的训练场。", "0", "0", "0", "0", "0", "cv_harriet_36", "0", "0"},
[403935] = {403935, 10039, 37, 29, "0", "0", "人不少嘛。", "0", "0", "0", "0", "0", "cv_harriet_37", "0", "0"},
[403936] = {403936, 10039, 38, 30, "0", "0", "有安排体能测试吗？", "0", "0", "0", "0", "0", "cv_harriet_38", "0", "0"},
[403937] = {403937, 10039, 39, 31, "0", "0", "迟早有一天，我会摆脱这些装备。", "0", "0", "0", "0", "0", "cv_harriet_39", "0", "0"},
[403938] = {403938, 10039, 40, 32, "0", "0", "需要冷静。", "0", "0", "0", "0", "0", "cv_harriet_40", "0", "0"},
[403939] = {403939, 10039, 41, 33, "0", "0", "长相没什么变化。", "0", "0", "0", "0", "0", "cv_harriet_41", "0", "0"},
[403940] = {403940, 10039, 42, 34, "0", "0", "坏了的时候敲一拳就好了。", "0", "0", "0", "0", "0", "cv_harriet_42", "0", "0"},
[403941] = {403941, 10039, 43, 35, "0", "0", "有什么话不能当面说吗？", "0", "0", "0", "0", "0", "cv_harriet_43", "0", "0"},
[403942] = {403942, 10039, 44, 36, "0", "0", "有些发言真的让人恼火，想给他一拳。", "0", "0", "0", "0", "0", "cv_harriet_44", "0", "0"},
[403943] = {403943, 10039, 45, 37, "0", "0", "嗬啊——", "0", "0", "0", "0", "0", "cv_harriet_45", "0", "0"},
[404000] = {404000, 10040, 1, 1, "0", "0", "蒼霧殘響（红博士）\n蒼霧殘響（red）", "0", "0", "0", "0", "0", "cv_megazlws_001", "0", "0"},
[404001] = {404001, 10040, 2, 2, "0", "0", "我是朱利乌斯，朱利乌斯·冯·尼采。我绝对不会辜负您的期待的。", "0", "0", "0", "0", "0", "cv_megazlws_002", "0", "0"},
[404002] = {404002, 10040, 3, 3, "0", "0", "這是red醬的朱利烏斯形態……會有版權問題嗎？", "0", "0", "0", "0", "0", "cv_megazlws_003", "0", "0"},
[404003] = {404003, 10040, 4, 4, "0", "idle", "朱利烏斯在朱利烏斯模仿大會獲得了第二名的好成績。可喜可賀，可喜可賀。", "0", "0", "0", "0", "0", "cv_megazlws_004", "0", "0"},
[404004] = {404004, 10040, 5, 4, "0", "idle", "矽基之箭是超聲波，矽基之耳是探測器，矽基之翼在天空飛翔，機械射線是熱光線。初次瞭解人類之愛，這覺醒了溫柔的人造原罪正是我，正義的英雄，red醬，red醬！", "0", "0", "0", "0", "0", "cv_megazlws_005", "0", "0"},
[404005] = {404005, 10040, 6, 4, "0", "idle", "你說紅博士？她是個成事不足敗事有餘的傢伙，和她合作真是我人生的敗筆之一。\n（red）我好歹也是你的造物主！\n（紅博士）那是我人生的另一個重大敗筆。（red）", "0", "0", "0", "0", "0", "cv_megazlws_006", "0", "0"},
[404006] = {404006, 10040, 7, 5, "1_》_0_0.8", "level1", "聽好了。red，今天即將展開的是獻媚大作戰，我們的目標是獲得更多的那位領航的基因。（紅博士）\n博士，你現在正在公共頻道發言，我們的密謀被大家都聽到了。（red）", "0", "0", "0", "0", "0", "cv_megazlws_007", "0", "0"},
[404007] = {404007, 10040, 8, 5, "1_》_0_0.8", "level2", "紅博士，你以後還是不要靠近我了，我怕領航誤會我們之間的關係。（red）\n啊？嗯？這是什麼意思……？難道說……你愛上他了？不會吧，有夠好笑的。（紅博士）", "0", "0", "0", "0", "0", "cv_megazlws_008", "0", "0"},
[404008] = {404008, 10040, 9, 5, "1_》_100_1.5", "level3", "想要摸摸我的胸部嗎？矽基的胸部也是胸部，你不要看起不矽基生命體。", "0", "0", "0", "0", "0", "cv_megazlws_009", "0", "0"},
[404009] = {404009, 10040, 10, 5, "1_》_500_2", "level4", "我永遠忘不了那天你和我擁抱完之後，我身體上你的體溫都還沒消散，你轉頭就打開了《機械核心16》，那一刻的屈辱我這輩子都不想再體驗一次。", "0", "0", "0", "0", "0", "cv_megazlws_010", "0", "0"},
[404010] = {404010, 10040, 11, 5, "1_》_1000_2.5", "level5", "好感度什麼的都無所謂了吧，反正作為機器人內核的red我對你是滿好感度。但是請你不要說“請用朱利烏斯的聲音對我說點色情的話吧”之類的話，有時候被當作替代品我也是會生氣的。", "0", "0", "0", "0", "0", "cv_megazlws_011", "0", "0"},
[404011] = {404011, 10040, 12, 6, "0", "0", "通俗易懂地說，我變強了。", "0", "0", "0", "0", "0", "cv_megazlws_012", "0", "0"},
[404012] = {404012, 10040, 13, 7, "0", "0", "以普世的價值觀來說，我的傷害更高了。", "0", "0", "0", "0", "0", "cv_megazlws_013", "0", "0"},
[404013] = {404013, 10040, 14, 8, "0", "0", "我擁有著快速學習世間一切知識的能力……你說很多駕駛員都能做到？等等，這可是我的角色特色耶，這也能重複的嗎？", "0", "0", "0", "0", "0", "cv_megazlws_014", "0", "0"},
[404014] = {404014, 10040, 15, 9, "0", "0", "這就是我和領航的羈絆（棒讀）……啊因為不是第一次了，所以沒有初次的那種熱情了。", "0", "0", "0", "0", "0", "cv_megazlws_015", "0", "0"},
[404015] = {404015, 10040, 16, 10, "0", "0", "我的同胞們，戰鬥吧。", "0", "0", "0", "0", "0", "cv_megazlws_016", "0", "0"},
[404016] = {404016, 10040, 17, 11, "0", "0", "果然只有我才是最完美的。", "0", "0", "0", "0", "0", "cv_megazlws_017", "0", "0"},
[404017] = {404017, 10040, 18, 12, "0", "0", "想死都難啊真是。", "0", "0", "0", "0", "0", "cv_megazlws_018", "0", "0"},
[404018] = {404018, 10040, 19, 13, "0", "0", "只要不死掉，這次的經驗會讓我更加完美。", "0", "0", "0", "0", "0", "cv_megazlws_019", "0", "0"},
[404019] = {404019, 10040, 20, 14, "0", "0", "怎麼會！？高性能的我竟然會……！？", "0", "0", "0", "0", "0", "cv_megazlws_020", "0", "0"},
[404020] = {404020, 10040, 21, 15, "0", "0", "變成養分吧。", "0", "0", "0", "0", "0", "cv_megazlws_021", "0", "0"},
[404021] = {404021, 10040, 23, 16, "0", "0", "開始。", "0", "0", "0", "0", "0", "cv_megazlws_022", "0", "0"},
[404022] = {404022, 10040, 24, 17, "0", "0", "終了。", "0", "0", "0", "0", "0", "cv_megazlws_023", "0", "0"},
[404023] = {404023, 10040, 25, 18, "0", "0", "同步率400%，開始作戰。", "0", "0", "0", "0", "0", "cv_megazlws_024", "0", "0"},
[404024] = {404024, 10040, 26, 19, "0", "0", "？？？？？", "0", "0", "0", "0", "0", "cv_megazlws_026", "0", "0"},
[404025] = {404025, 10040, 27, 20, "0", "0", "為什麼要我以朱利烏斯的樣子進維護池。", "0", "0", "0", "0", "0", "cv_megazlws_027", "0", "0"},
[404026] = {404026, 10040, 28, 21, "0", "0", "你會對著朱利烏斯樣子的我發情嗎？", "0", "0", "0", "0", "0", "cv_megazlws_028", "0", "0"},
[404027] = {404027, 10040, 29, 21, "0", "0", "快點完事，我等得不耐煩了。", "0", "0", "0", "0", "0", "cv_megazlws_029", "0", "0"},
[404028] = {404028, 10040, 30, 22, "0", "0", "地獄的試煉。", "0", "0", "0", "0", "0", "cv_megazlws_030", "0", "0"},
[404029] = {404029, 10040, 31, 23, "0", "0", "外表是朱利烏斯，內心卻是只有1歲的小寶寶red。", "0", "0", "0", "0", "0", "cv_megazlws_031", "0", "0"},
[404030] = {404030, 10040, 32, 24, "0", "0", "red醬大勝利！", "0", "0", "0", "0", "0", "cv_megazlws_032", "0", "0"},
[404031] = {404031, 10040, 33, 25, "0", "0", "你傷害我的心，你這個殺人犯。", "0", "0", "0", "0", "0", "cv_megazlws_033", "0", "0"},
[404032] = {404032, 10040, 34, 26, "0", "0", "朱利烏斯哦，是朱利烏斯。", "0", "0", "0", "0", "0", "cv_megazlws_034", "0", "0"},
[404033] = {404033, 10040, 35, 27, "0", "0", "開始種族的戰爭吧。", "0", "0", "0", "0", "0", "cv_megazlws_035", "0", "0"},
[404034] = {404034, 10040, 36, 28, "0", "0", "朱利烏斯打的人，關我什麼事？", "0", "0", "0", "0", "0", "cv_megazlws_036", "0", "0"},
[404035] = {404035, 10040, 37, 29, "0", "0", "學習大家的長處。", "0", "0", "0", "0", "0", "cv_megazlws_037", "0", "0"},
[404036] = {404036, 10040, 38, 30, "0", "0", "來為我添加更多參考素材吧。", "0", "0", "0", "0", "0", "cv_megazlws_038", "0", "0"},
[404037] = {404037, 10040, 40, 31, "0", "0", "沒有比我性能更高的裝備了。", "0", "0", "0", "0", "0", "cv_megazlws_039", "0", "0"},
[404038] = {404038, 10040, 40, 32, "0", "0", "看不懂的東西好多，人類也就這樣了。", "0", "0", "0", "0", "0", "cv_megazlws_040", "0", "0"},
[404039] = {404039, 10040, 41, 33, "0", "0", "我不希望在這裡看到其他人。", "0", "0", "0", "0", "0", "cv_megazlws_041", "0", "0"},
[404040] = {404040, 10040, 42, 34, "0", "0", "設定好了就快走吧。", "0", "0", "0", "0", "0", "cv_megazlws_042", "0", "0"},
[404041] = {404041, 10040, 43, 35, "0", "0", "安全密碼好弱，我一秒就破解了。", "0", "0", "0", "0", "0", "cv_megazlws_043", "0", "0"},
[404042] = {404042, 10040, 44, 36, "0", "0", "需要我在網上攻擊誰嗎？", "0", "0", "0", "0", "0", "cv_megazlws_044", "0", "0"},
[404043] = {404043, 10040, 45, 37, "0", "0", "盯——", "0", "0", "0", "0", "0", "cv_megazlws_045", "0", "0"},
[404100] = {404100, 10041, 1, 1, "0", "0", "蒼霧殘響", "0", "0", "0", "0", "0", "cv_alaita2nd_001", "0", "0"},
[404101] = {404101, 10041, 2, 2, "0", "0", "我知道了，就像從前那樣，對嗎？", "0", "0", "0", "0", "0", "cv_alaita2nd_002", "0", "0"},
[404102] = {404102, 10041, 3, 3, "0", "0", "讓我們為您的眼眸乾杯，領航。", "0", "0", "0", "0", "0", "cv_alaita2nd_003", "0", "0"},
[404103] = {404103, 10041, 4, 4, "0", "idle", "現在，我還不清楚，您的回來，是希望來臨時的第一絲曙光，還是將我們引入瘋狂的誘惑……無論如何，我們都將追隨您，領航。", "0", "0", "0", "0", "0", "cv_alaita2nd_004", "0", "0"},
[404104] = {404104, 10041, 5, 4, "0", "idle", "您在身邊的時候，就像一切都回到了從前一樣，令人陶醉。", "0", "0", "0", "0", "0", "cv_alaita2nd_005", "0", "0"},
[404105] = {404105, 10041, 6, 4, "0", "idle", "領航……您之後能不能和查麗莎說一下，讓她把上次收繳的酒還給我？那可是我僅有的人生樂趣了。", "0", "0", "0", "0", "0", "cv_alaita2nd_006", "0", "0"},
[404106] = {404106, 10041, 7, 5, "1_》_0_0.8", "level1", "行蹤不明的王子在公主遇上危機時出現，將世界重新引向和平，這就是我想要的童話故事。", "0", "0", "0", "0", "0", "cv_alaita2nd_007", "0", "0"},
[404107] = {404107, 10041, 8, 5, "1_》_0_0.8", "level2", "我們都知道……領航您一定是會回去的。您要回去的地方，沒有路，也不需要路。", "0", "0", "0", "0", "0", "cv_alaita2nd_008", "0", "0"},
[404108] = {404108, 10041, 9, 5, "1_》_100_1.5", "level3", "過去的悲劇已經發生，未來的道路撲朔迷離。領航，唯有您，能把握現在，讓悲劇不復存在，讓未來迎來光明。", "0", "0", "0", "0", "0", "cv_alaita2nd_009", "0", "0"},
[404109] = {404109, 10041, 10, 5, "1_》_500_2", "level4", "從時間的角度來看，未來無垠沒有盡頭，您可以出現在未來的每一個節點，可以與每個節點的人相遇，但這一刻，您偏偏與我們重逢了，我認為，這就是命運。", "0", "0", "0", "0", "0", "cv_alaita2nd_010", "0", "0"},
[404110] = {404110, 10041, 11, 5, "1_》_1000_2.5", "level5", "我會將自己的餘生，自己的未來，自己的一切交給您，只要您想要——這是我最後的瘋狂，最後的賭博，領航，您會贏的，對嗎？", "0", "0", "0", "0", "0", "cv_alaita2nd_011", "0", "0"},
[404111] = {404111, 10041, 12, 6, "0", "0", "謝謝。", "0", "0", "0", "0", "0", "cv_alaita2nd_012", "0", "0"},
[404112] = {404112, 10041, 13, 7, "0", "0", "能得到您的信任，是我的榮幸。", "0", "0", "0", "0", "0", "cv_alaita2nd_013", "0", "0"},
[404113] = {404113, 10041, 14, 8, "0", "0", "時間無法讓我的利刃生鏽，只會讓我更加清楚，自己為何而戰。", "0", "0", "0", "0", "0", "cv_alaita2nd_014", "0", "0"},
[404114] = {404114, 10041, 15, 9, "0", "0", "真是美妙。", "0", "0", "0", "0", "0", "cv_alaita2nd_015", "0", "0"},
[404115] = {404115, 10041, 16, 10, "0", "0", "歡呼吧，這是名作的重映。", "0", "0", "0", "0", "0", "cv_alaita2nd_016", "0", "0"},
[404116] = {404116, 10041, 17, 11, "0", "0", "時光荏苒，但依然無法遮掩我的無瑕光輝。", "0", "0", "0", "0", "0", "cv_alaita2nd_017", "0", "0"},
[404117] = {404117, 10041, 18, 12, "0", "0", "時間只會讓我更有魅力。", "0", "0", "0", "0", "0", "cv_alaita2nd_018", "0", "0"},
[404118] = {404118, 10041, 19, 13, "0", "0", "不完美也是一種美。", "0", "0", "0", "0", "0", "cv_alaita2nd_019", "0", "0"},
[404119] = {404119, 10041, 20, 14, "0", "0", "還是生疏了嗎……", "0", "0", "0", "0", "0", "cv_alaita2nd_020", "0", "0"},
[404120] = {404120, 10041, 21, 15, "0", "0", "這就結束了嗎？", "0", "0", "0", "0", "0", "cv_alaita2nd_021", "0", "0"},
[404121] = {404121, 10041, 23, 16, "0", "0", "死吧。", "0", "0", "0", "0", "0", "cv_alaita2nd_022", "0", "0"},
[404122] = {404122, 10041, 24, 17, "0", "0", "染上血色吧。", "0", "0", "0", "0", "0", "cv_alaita2nd_023", "0", "0"},
[404123] = {404123, 10041, 26, 19, "0", "0", "遲來的謝幕……", "0", "0", "0", "0", "0", "cv_alaita2nd_026", "0", "0"},
[404124] = {404124, 10041, 27, 20, "0", "0", "嗯？是領航啊……也就只有您會在這種場合出現了。", "0", "0", "0", "0", "0", "cv_alaita2nd_027", "0", "0"},
[404125] = {404125, 10041, 28, 21, "0", "0", "能吸引您的視線，說明我的魅力依然不減當年。", "0", "0", "0", "0", "0", "cv_alaita2nd_028", "0", "0"},
[404126] = {404126, 10041, 29, 21, "0", "0", "能聽見這具巨大軀體下的心跳嗎？它讓我知道這一刻的我身處現實，而非妄想的幻覺。", "0", "0", "0", "0", "0", "cv_alaita2nd_029", "0", "0"},
[404127] = {404127, 10041, 30, 22, "0", "0", "令人懷念……", "0", "0", "0", "0", "0", "cv_alaita2nd_030", "0", "0"},
[404128] = {404128, 10041, 31, 23, "0", "0", "那麼，請說出我的名字吧，領航。", "0", "0", "0", "0", "0", "cv_alaita2nd_031", "0", "0"},
[404129] = {404129, 10041, 32, 24, "0", "0", "您想要什麼獎勵呢，領航？", "0", "0", "0", "0", "0", "cv_alaita2nd_032", "0", "0"},
[404130] = {404130, 10041, 33, 25, "0", "0", "您真喜歡讓人空歡喜，領航。", "0", "0", "0", "0", "0", "cv_alaita2nd_033", "0", "0"},
[404131] = {404131, 10041, 34, 26, "0", "0", "領航，我為您準備了提神的咖啡，您有空和我討論一下之後的戰術佈置嗎？", "0", "0", "0", "0", "0", "cv_alaita2nd_034", "0", "0"},
[404132] = {404132, 10041, 35, 27, "0", "0", "準備和海妖最後瘋狂一次嗎？", "0", "0", "0", "0", "0", "cv_alaita2nd_035", "0", "0"},
[404133] = {404133, 10041, 36, 28, "0", "0", "就當遠征前的熱身吧。", "0", "0", "0", "0", "0", "cv_alaita2nd_036", "0", "0"},
[404134] = {404134, 10041, 37, 29, "0", "0", "大家還真是有精神呢。", "0", "0", "0", "0", "0", "cv_alaita2nd_037", "0", "0"},
[404135] = {404135, 10041, 38, 30, "0", "0", "希望能來位能幹的新人。", "0", "0", "0", "0", "0", "cv_alaita2nd_038", "0", "0"},
[404136] = {404136, 10041, 40, 31, "0", "0", "得定期研發裝備呢。", "0", "0", "0", "0", "0", "cv_alaita2nd_039", "0", "0"},
[404137] = {404137, 10041, 40, 32, "0", "0", "要購物了嗎？", "0", "0", "0", "0", "0", "cv_alaita2nd_040", "0", "0"},
[404138] = {404138, 10041, 41, 33, "0", "0", "讓人懷念的名字。", "0", "0", "0", "0", "0", "cv_alaita2nd_041", "0", "0"},
[404139] = {404139, 10041, 42, 34, "0", "0", "耐心設置吧。", "0", "0", "0", "0", "0", "cv_alaita2nd_042", "0", "0"},
[404140] = {404140, 10041, 43, 35, "0", "0", "別誤刪郵件噢。", "0", "0", "0", "0", "0", "cv_alaita2nd_043", "0", "0"},
[404141] = {404141, 10041, 44, 36, "0", "0", "喧鬧也是一種幸福。", "0", "0", "0", "0", "0", "cv_alaita2nd_044", "0", "0"},
[404142] = {404142, 10041, 45, 37, "0", "0", "呵呵~", "0", "0", "0", "0", "0", "cv_alaita2nd_045", "0", "0"},
[410000] = {410000, 11000, 1, 1, "0", "0", "蒼霧殘響——切，這麼做的意義到底是什麼啊？！", "蒼霧殘響（ハツリバーブ）――ふーん、これって意味あるの？", "0", "0", "蒼霧殘響——切，這麼做的意義到底是什麼啊？！", "0", "cv_chilyarisa_32", "0", "0"},
[410001] = {410001, 11000, 2, 2, "0", "0", "喔～眼光還不錯嘛～", "へぇ、見る目があるじゃん～", "0", "0", "噢～眼光還不錯嘛～", "0", "cv_chilyarisa_2", "0", "0"},
[410002] = {410002, 11000, 3, 3, "0", "0", "嘖，真是的。人家為什麼會被編進這種邊緣部隊啊。", "もうっ！何でこんなノンコア部隊に配屬されてるのよ。", "0", "0", "嘖，真是的。人家為什麼會被編進這種邊緣部隊啊。", "0", "cv_chilyarisa_1", "0", "0"},
[410003] = {410003, 11000, 4, 4, "0", "idle", "喂，那邊的傢夥。如果有什麼要幫忙的就隨時聯繫人家吧，今天也絕對不會讓你失望的。", "ねえ、ちょっと。何かあったらいつでも言いなさい？今日も絶対、あんたの期待を裏切らないから。", "0", "0", "喂，那邊的傢伙。如果有什麼要幫忙的就隨時連絡人家吧，今天也絕對不會讓你失望的。", "0", "cv_chilyarisa_3", "0", "0"},
[410004] = {410004, 11000, 5, 4, "0", "idle", "離家出走的千金大小姐？你到底是從哪聽到的謠言啊，下次如果再敢提起這事，人家絕對不會放過你。", "家出したお嬢様？そんな根も葉もないこと、誰から聞いたの？てか、二度と口にしないでよね！今度は絶対許さないから。", "0", "0", "離家出走的千金大小姐？你到底是從哪聽到的謠言啊，下次如果再敢提起這事，人家絕對不會放過你。", "0", "cv_chilyarisa_4", "0", "0"},
[410005] = {410005, 11000, 6, 4, "0", "idle", "嗚嗚嗚，弗蘭卡真的超級可愛啊～說實話，沒人能拒絕年幼又懂事的後輩叫自己學姐吧。", "もう……！フランカーって本當に可愛い～てか、大人しい後輩に先輩って呼ばれるのは、普通に嬉しいんだけど。", "0", "0", "嗚嗚嗚，弗蘭卡真的超級可愛啊～說實話，沒人能拒絕年幼又懂事的後輩叫自己學姐吧。", "0", "cv_chilyarisa_29", "0", "0"},
[410006] = {410006, 11000, 7, 5, "1_》_0_0.8", "level1", "我就直說了吧，我想要出名，想讓全世界的目光都聚焦到我的身上。想要……證明自己才不是什麼一無是處任人擺佈的千金大小姐。", "はっきり言わせてもらうけどね。あたし、有名人になりたいの。世界中の注目を集めたいの。自分は何の取り柄もない、人の言いなりになるお嬢様じゃないってことを、証明したいの。", "0", "0", "我就直說了吧，我想要出名，想讓全世界的目光都聚焦到我的身上。想要……證明自己才不是什麼一無是處任人擺佈的千金大小姐。", "0", "cv_chilyarisa_30", "0", "0"},
[410007] = {410007, 11000, 8, 5, "1_》_0_0.8", "level1", "滾。", "どいて。", "0", "0", "滾。", "0", "cv_chilyarisa_5", "0", "0"},
[410008] = {410008, 11000, 9, 5, "1_》_100_1.5", "level2", "哈？被人家迷住了嗎～真是單純的傢夥啊。", "へ？あたしに魅了されたってこと？ふ、ふーん、ちょろいヤツね。", "0", "0", "哈？被人家迷住了嗎～真是單純的傢伙啊。", "0", "cv_chilyarisa_6", "0", "0"},
[410009] = {410009, 11000, 10, 5, "1_》_500_2", "level3", "喂，都說了，不要再這麼盯著人家了……煩……煩死人了哇啊啊啊啊！！！！！", "だから、そんなに見つめないでってば……う、鬱陶しいの！！！！！", "0", "0", "喂，都說了，不要再這麼盯著人家了……煩……煩死人了哇啊啊啊啊！！！！！", "0", "cv_chilyarisa_7", "0", "0"},
[410010] = {410010, 11000, 11, 5, "1_》_1000_2.5", "level4", "哼，那個什麼。就破例讓你看一會吧，聽好了就一會喔……真……真是的，沒……沒想到人家的魅力這麼大啊，哈，哈哈，哈哈哈哈。", "ふん。じゃあさ、ちょっとだけなら、見てもいいけど……今回だけだから、ちょっとだけだからね！もうっ……！あんたがあたしにそんなに夢中になるなんてね。あはは、あははは。", "0", "0", "哼，那個什麼。就破例讓你看一會吧，聽好了就一會哦……真……真是的，沒……沒想到人家的魅力這麼大啊，哈，哈哈，哈哈哈哈。", "0", "cv_chilyarisa_8", "0", "0"},
[410011] = {410011, 11000, 12, 6, "0", "0", "吼～", "ふーん", "0", "0", "吼～", "0", "cv_chilyarisa_9", "0", "0"},
[410012] = {410012, 11000, 13, 7, "0", "0", "感覺真是不錯呢～", "いい感じ。", "0", "0", "感覺真是不錯呢～", "0", "cv_chilyarisa_10", "0", "0"},
[410013] = {410013, 11000, 14, 8, "0", "0", "怎麼說呢，那個……雖然這都是人家自己努力得到的結果，但是還是多謝你一直陪著人家了。", "なんていうか、その……あたし自身が頑張ったからね！まぁ、そばにいてくれたのは…...その、あ、ありがとう……", "0", "0", "怎麼說呢，那個……雖然這都是人家自己努力得到的結果，但是還是多謝你一直陪著人家了。", "0", "cv_chilyarisa_11", "0", "0"},
