[410031] = {410031, 11000, 34, 26, "0", "0", "歡迎回來～放心好了，在你不在的這段時間裏我可沒到處惹事喔。", "お帰り、安心して。あんたがいない間、特に何の問題も起こしてないかよ。", "0", "0", "歡迎回來～放心好了，在你不在的這段時間裡我可沒到處惹事哦。", "0", "cv_chilyarisa_31", "0", "0"},
[410032] = {410032, 11000, 35, 27, "0", "0", "你的故事中應該也有我的戲份吧……", "あんたの物語、あたしも出てるよね……？", "0", "0", "你的故事中應該也有我的戲份吧……", "0", "cv_chilyarisa_33", "0", "0"},
