[410902] = {410902, 11009, 3, 3, "0", "0", "我是波琳娜……呃……波琳娜•伊•羅夫斯基。", "私はボーリンナ……えっと……ボーリンナ・イ・ロフスキー。", "0", "0", "我是波琳娜……呃……波琳娜•伊•羅夫斯基。", "0", "cv_borinna_1", "0", "0"},
[410903] = {410903, 11009, 4, 4, "0", "idle", "……領航！……沒什麼？只是想叫叫您了……", "……ナビゲーター！……ううん。ただ呼びたくって……", "0", "0", "……領航！……沒什麼？只是想叫叫您了……", "0", "cv_borinna_3", "0", "0"},
[410904] = {410904, 11009, 5, 4, "0", "idle", "在戰場，伊莉雅經常讓我不要緊張……但是……真的好可怕……", "戦場では、よくイリアから緊張しないでって言われてるけど……でも……本當に淒く、怖い……", "0", "0", "在戰場，伊莉雅經常讓我不要緊張……但是……真的好可怕……", "0", "cv_borinna_4", "0", "0"},
[410905] = {410905, 11009, 6, 4, "0", "idle", "在和領航相遇前，一直都是伊莉雅隊長在照顧我喔~在這個世界上，對波琳娜最好的人就是伊莉雅隊長了！", "ナビゲーターに出會うまではずっとイリア隊長が世話をしてくれてたの。この世界で一番よくしてくれる人はイリア隊長なの。", "0", "0", "在和領航相遇前，一直都是伊莉雅隊長在照顧我哦~在這個世界上，對波琳娜最好的人就是伊莉雅隊長了！", "0", "cv_borinna_29", "0", "0"},
[410906] = {410906, 11009, 7, 5, "1_》_0_0.8", "level1", "波琳娜想要好多好多的糖~溫暖的房子，能讓大家都睡在一起的大床~", "ボーリンナ、沢山のキャンディーが欲しいの。暖かい家と、みんなが一緒に寢れる、大きなベッドも。", "0", "0", "波琳娜想要好多好多的糖~溫暖的房子，能讓大家都睡在一起的大床~", "0", "cv_borinna_30", "0", "0"},
[410907] = {410907, 11009, 8, 5, "1_》_0_0.8", "level1", "領航以後就是我們的老闆了嗎？會像那些討厭的大人一樣不給我們東西吃嗎？", "これから、ナビゲーターがボーリングたちのボスになるの？…...あの嫌な大人たちみたいに、ご飯を食べさせてくれないの？", "0", "0", "領航以後就是我們的老闆了嗎？會像那些討厭的大人一樣不給我們東西吃嗎？", "0", "cv_borinna_5", "0", "0"},
[410908] = {410908, 11009, 9, 5, "1_》_100_1.5", "level2", "父母？波琳娜沒有見過自己的父母喔。不過，伊莉雅對我可好了，就像母親一樣呢！", "両親？ボーリンナ、自分の両親には會ったことないの。でも、イリアには淒く親切にしてもらってる。まるでお母さんみたい。", "0", "0", "父母？波琳娜沒有見過自己的父母喔。不過，伊莉雅對我可好了，就像母親一樣呢！", "0", "cv_borinna_6", "0", "0"},
[410909] = {410909, 11009, 10, 5, "1_》_500_2", "level3", "我明明一直都在努力戰鬥，為什麼那些人總是責怪我們呢……嗚，要是大家都像領航一樣是個大好人就好了！", "ずっと頑張って戦ってるのに、なんでいつもあの人たちに責められなきゃいけないの……うっ……みんな、ナビゲーターみたいにいい人だったらいいのに。", "0", "0", "我明明一直都在努力戰鬥，為什麼那些人總是責怪我們呢……嗚，要是大家都像領航一樣是個大好人就好了！", "0", "cv_borinna_7", "0", "0"},
[410910] = {410910, 11009, 11, 5, "1_》_1000_2.5", "level4", "波琳娜最近看到領航，都有一種怪怪的感覺……想要一直陪伴在領航身邊，是這樣的感覺……是不是很奇怪？", "ボーリンナは最近、ナビゲーターを見るとなんか変な気持ちになるの……ずっとナビゲーターのそばにいたい…...って気持ち、……変かな？", "0", "0", "波琳娜最近看到領航，都有一種怪怪的感覺……想要一直陪伴在領航身邊，是這樣的感覺……是不是很奇怪？", "0", "cv_borinna_8", "0", "0"},
[410911] = {410911, 11009, 12, 6, "0", "0", "波琳娜要控制好自己的力量~", "ボーリンナ、自分の力をちゃんとコントロールしなきゃ。", "0", "0", "波琳娜要控制好自己的力量~", "0", "cv_borinna_9", "0", "0"},
[410912] = {410912, 11009, 13, 7, "0", "0", "力量……增加了。", "力が……増したの。", "0", "0", "力量……增加了。", "0", "cv_borinna_10", "0", "0"},
[410913] = {410913, 11009, 14, 8, "0", "0", "只有領航才會像這樣不介意波琳娜的力量……為了領航，我會好好控制自己的力量，不給大家添麻煩的！", "ボーリンナの力のことを気にしないのは、ナビゲーターくらいだよ……ナビゲーターのために、自分の力をちゃんとコントロールできるよう、みんなに迷惑をかけないように、努力する。", "0", "0", "只有領航才會像這樣不介意波琳娜的力量……為了領航，我會好好控制自己的力量，不給大家添麻煩的！", "0", "cv_borinna_11", "0", "0"},
