[411001] = {411001, 11010, 2, 2, "0", "0", "我……我嗎？瓏真的能行嗎……瓏、瓏會試著努力的。", "わ……私？瓏、大丈夫かな？……ろ、瓏、頑張ってみる。", "0", "0", "我……我嗎？瓏真的能行嗎……瓏、瓏會試著努力的。", "0", "cv_long_2", "0", "0"},
[411002] = {411002, 11010, 3, 3, "0", "0", "初……初次見面，領航。瓏會努力工作的，請不要罵瓏……", "は……初めまして、ナビゲーター。瓏、頑張るから、叱らないで……", "0", "0", "初……初次見面，領航。瓏會努力工作的，請不要罵瓏……", "0", "cv_long_1", "0", "0"},
[411003] = {411003, 11010, 4, 4, "0", "idle", "瓏……常常因為害怕而從戰場上逃走。多虧了隊伍裡的大家，瓏才能免受責罰。這樣是不對的，可是瓏真的很怕，該怎麼辦才好呢？", "瓏は……怖いから戦場から逃げてばかりなの。だけど、チームのみんなのお陰で、ペナルティを免れたの。こんなの、良くない。でも、本當に淒く怖いの。どうすればいいのかな？", "0", "0", "瓏……常常因為害怕而從戰場上逃走。多虧了隊伍裡的大家，瓏才能免受責罰。這樣是不對的，可是瓏真的很怕，該怎麼辦才好呢？", "0", "cv_long_3", "0", "0"},
[411004] = {411004, 11010, 5, 4, "0", "idle", "瓏很弱……還很膽小，這樣的我，真的能夠得到領航的信任嗎？……但，但是！瓏會加油的，請不要丟下瓏一個人……", "瓏は弱くて……臆病なの。こんな瓏でも、本當にナビゲーターに信頼してもらえるの？……で、でも！瓏、頑張るから！だから、一人にしないで……", "0", "0", "瓏很弱……還很膽小，這樣的我，真的能夠得到領航的信任嗎？……但，但是！瓏會加油的，請不要丟下瓏一個人……", "0", "cv_long_4", "0", "0"},
[411005] = {411005, 11010, 6, 4, "0", "idle", "一直以來，都是渠小姐在保護著瓏……瓏不能再逃了，要為了渠小姐變強才行。", "瓏、今まではずっと渠さんに守られてて……これ以上は逃げちゃだめ。瓏、渠さんのために強くならなきゃ。", "0", "0", "一直以來，都是渠小姐在保護著瓏……瓏不能再逃了，要為了渠小姐變強才行。", "0", "cv_long_28", "0", "0"},
[411006] = {411006, 11010, 7, 5, "1_》_0_0.8", "level1", "瓏……其實一點也不想戰鬥。但是瓏的家鄉已經沒了，所以，這裡是瓏唯一的歸宿。瓏不想再失去它了！", "瓏、本當は戦いたくないの。でも、瓏の故郷はもう、ない。だから、ここが瓏の唯一の居場所なの。瓏、この場所を失いたくない！", "0", "0", "瓏……其實一點也不想戰鬥。但是瓏的家鄉已經沒了，所以，這裡是瓏唯一的歸宿。瓏不想再失去它了！", "0", "cv_long_29", "0", "0"},
[411007] = {411007, 11010, 8, 5, "1_》_0_0.8", "level1", "嗚哇！領航，請不要嚇我呀……", "うわぁ！ナビゲーター！驚かさないでよ……", "0", "0", "嗚哇！領航，請不要嚇我呀……", "0", "cv_long_5", "0", "0"},
[411008] = {411008, 11010, 9, 5, "1_》_100_1.5", "level2", "領航……很喜歡瓏的耳朵嗎？太好了，嘻嘻。", "ナビゲーター……瓏の耳が好きなの？よかった、えへへ。", "0", "0", "領航……很喜歡瓏的耳朵嗎？太好了，嘻嘻。", "0", "cv_long_6", "0", "0"},
[411009] = {411009, 11010, 10, 5, "1_》_500_2", "level3", "為什麼？為什麼？領航每次都只會跟渠小姐進行通感，是因為瓏太弱了嗎？", "なんで？なんで？ナビゲーターさんは渠さんばかりと通感覚して……瓏が弱すぎるから……？", "0", "0", "為什麼？為什麼？領航每次都只會跟渠小姐進行通感，是因為瓏太弱了嗎？", "0", "cv_long_7", "0", "0"},
[411010] = {411010, 11010, 11, 5, "1_》_1000_2.5", "level4", "領航的手，很溫暖……就像爸爸和媽媽一樣。領航，請不要丟下瓏一個人，好嗎？瓏也會一直陪在領航身邊的。無論何時，無論何地。", "ナビゲーターの手、とても溫かい……何だかお父さんとお母さんみたい……ナビゲーター、瓏を一人にしないで、ね？瓏も、ずっとナビゲーターのそばにいる。いつまでもどこまでも。", "0", "0", "領航的手，很溫暖……就像爸爸和媽媽一樣。領航，請不要丟下瓏一個人，好嗎？瓏也會一直陪在領航身邊的。無論何時，無論何地。", "0", "cv_long_8", "0", "0"},
[411011] = {411011, 11010, 12, 6, "0", "0", "瓏真的變強了嗎……太好了……", "瓏、本當に強くなったの……？よかった……", "0", "0", "瓏真的變強了嗎……太好了……", "0", "cv_long_9", "0", "0"},
[411012] = {411012, 11010, 13, 7, "0", "0", "瓏會努力不逃跑的！", "瓏、逃げないように頑張るから！", "0", "0", "瓏會努力不逃跑的！", "0", "cv_long_10", "0", "0"},
[411013] = {411013, 11010, 14, 8, "0", "0", "領……領航！最近瓏學習了一套“埃塔星琉璃刀法”，我想示範一下給你看看？喝！……欸？領航呢？咦？你怎麼到天花板上了？", "ナ……ナビゲーター！最近ね、瓏、「アイター星瑠璃刀法」を習ったの！ちょっとやってみせるね！はっ！……え？ナビゲーター？あっ！なんで天井に……？", "0", "0", "領……領航！最近瓏學習了一套“埃塔星琉璃刀法”，我想示範一下給你看看？喝！……唉？領航呢？咦？你怎麼到天花板上了？", "0", "cv_long_11", "0", "0"},
[411014] = {411014, 11010, 15, 9, "0", "0", "雖然變強了，但瓏果然還是不行的吧……", "強くなったけど……やっぱダメだよね……", "0", "0", "雖然變強了，但瓏果然還是不行的吧……", "0", "cv_long_12", "0", "0"},
[411015] = {411015, 11010, 16, 10, "0", "0", "請不要讓我一個人出戰，嗚！", "出陣、一人にしないで！う……！", "0", "0", "請不要讓我一個人出戰，嗚！", "0", "cv_long_13", "0", "0"},
[411016] = {411016, 11010, 17, 11, "0", "0", "這次只是巧合而已……但是，瓏會更加努力的！", "偶々だよ……でも、瓏、もっと頑張るから！", "0", "0", "這次只是巧合而已……但是，瓏會更加努力的！", "0", "cv_long_14", "0", "0"},
[411017] = {411017, 11010, 18, 12, "0", "0", "大家都沒事吧？", "みんな無事？", "0", "0", "大家都沒事吧？", "0", "cv_long_15", "0", "0"},
[411018] = {411018, 11010, 19, 13, "0", "0", "贏……贏了嗎？", "か……勝ったの？", "0", "0", "贏……贏了嗎？", "0", "cv_long_16", "0", "0"},
[411019] = {411019, 11010, 20, 14, "0", "0", "敵人太強了，根本贏不了……領……領航！快和瓏一起撤離！", "敵が強すぎて、勝てるわけがないよ……ナ……ナビゲーター！瓏と一緒に、早く撤退しよう！", "0", "0", "敵人太強了，根本贏不了……領……領航！快和瓏一起撤離！", "0", "cv_long_17", "0", "0"},
[411020] = {411020, 11010, 21, 15, "0", "0", "瓏做到了！", "瓏、やり遂げた！", "0", "0", "瓏做到了！", "0", "cv_long_18", "0", "0"},
[411021] = {411021, 11010, 23, 16, "0", "0", "嘿呀！", "はぁい！", "0", "0", "嘿呀！", "0", "cv_long_19", "0", "0"},
[411022] = {411022, 11010, 26, 19, "0", "0", "嗚……嗚，不要丟下我……", "ううう……う！一人にしないで……", "0", "0", "嗚……嗚，不要丟下我……", "0", "cv_long_20", "0", "0"},
[411023] = {411023, 11010, 27, 20, "0", "0", "領航，稍等一下，我想帶點玩具……欸，不行嗎？", "ナビゲーター、ちょっと待って！おもちゃも一緒に……え？ダメなの？", "0", "0", "領航，稍等一下，我想帶點玩具……誒，不行嗎？", "0", "cv_long_21", "0", "0"},
[411024] = {411024, 11010, 28, 21, "0", "0", "咕咕咕——啊，領航！我沒有在玩，一定是領航看錯了。", "ぶくぶく――あっ、ナビゲーター！遊んでない！ナビゲーターの見間違いだよ。", "0", "0", "咕咕咕——啊，領航！我沒有在玩，一定是領航看錯了。", "0", "cv_long_22", "0", "0"},
[411025] = {411025, 11010, 29, 21, "0", "0", "熱水……好舒服，快睡著了，呼……呼……", "お湯……気持ちいい～眠くなってきた。グー……グー……", "0", "0", "熱水……好舒服，快睡著了，呼……呼……", "0", "cv_long_23", "0", "0"},
[411026] = {411026, 11010, 30, 22, "0", "0", "嗚哇？！發生什麼了？", "うわぁ？！何があったの？", "0", "0", "嗚哇？！發生什麼了？", "0", "cv_long_24", "0", "0"},
[411027] = {411027, 11010, 31, 23, "0", "0", "即使猜錯也沒有關係，因為是瓏呀……", "外れたとしても大丈夫だよ！瓏だし……", "0", "0", "即使猜錯也沒有關係，因為是瓏呀……", "0", "cv_long_25", "0", "0"},
[411028] = {411028, 11010, 32, 24, "0", "0", "領航……太厲害了！居然能猜出來是瓏！", "ナビゲーター……淒い！瓏のことが分かったなんて！", "0", "0", "領航……太厲害了！居然能猜出來是瓏！", "0", "cv_long_26", "0", "0"},
[411029] = {411029, 11010, 33, 25, "0", "0", "沒……沒關係，瓏是不會怪領航的……嗚……", "だ……大丈夫だよ。ナビゲーターのせいじゃない……う……", "0", "0", "沒……沒關係，瓏是不會怪領航的……嗚……", "0", "cv_long_27", "0", "0"},
[411030] = {411030, 11010, 34, 26, "0", "0", "領、領航！歡迎回來！瓏沒有在偷懶喔！", "ナ、ナビゲーター！お帰り！瓏、サボってないよ！", "0", "0", "領、領航！歡迎回來！瓏沒有在偷懶哦！", "0", "cv_long_30", "0", "0"},
[411031] = {411031, 11010, 35, 27, "0", "0", "戰鬥，又要開始了嗎……瓏會努力完成任務的！", "戦い、また始まるの？……瓏、頑張ってミッションをやり遂げるから！", "0", "0", "戰鬥，又要開始了嗎……瓏會努力完成任務的！", "0", "cv_long_32", "0", "0"},
[411032] = {411032, 11010, 36, 28, "0", "0", "好可怕……但是為了變強，瓏會努力的。", "怖い……でも、瓏、強くなるために頑張る！", "0", "0", "好可怕……但是為了變強，瓏會努力的。", "0", "cv_long_33", "0", "0"},
[411033] = {411033, 11010, 37, 29, "0", "0", "大家都很優秀呢……", "みんな、とても優秀だよね……", "0", "0", "大家都很優秀呢……", "0", "cv_long_34", "0", "0"},
[411034] = {411034, 11010, 38, 30, "0", "0", "嗚嗚……渠小姐在哪？", "うう……渠さんはどこ？", "0", "0", "嗚嗚……渠小姐在哪？", "0", "cv_long_35", "0", "0"},
[411035] = {411035, 11010, 39, 31, "0", "0", "瓏不要裝備也可以喔……", "瓏、裝備がなくてもいいよ……", "0", "0", "瓏不要裝備也可以哦……", "0", "cv_long_36", "0", "0"},
[411036] = {411036, 11010, 40, 32, "0", "0", "喔喔，這就是你們的採購方式啊~", "うわぁ、これがナビゲーターたちの買い物の仕方なんだ。", "0", "0", "哦哦，這就是你們的採購方式啊~", "0", "cv_long_37", "0", "0"},
[411037] = {411037, 11010, 41, 33, "0", "0", "領航果然和瓏的身體不一樣呢~", "ナビゲーターってやっぱり瓏とは違う體をしてるね。", "0", "0", "領航果然和瓏的身體不一樣呢~", "0", "cv_long_38", "0", "0"},
[411038] = {411038, 11010, 42, 34, "0", "0", "設定？嗚……是瓏不明白的東西。", "設定？う……瓏、よく分からない。", "0", "0", "設置？嗚……是瓏不明白的東西。", "0", "cv_long_39", "0", "0"},
[411039] = {411039, 11010, 43, 35, "0", "0", "有發給瓏的信嗎？欸，沒有嗎……", "瓏宛のメールはある？そっか、ないか……", "0", "0", "有發給瓏的信嗎？誒，沒有嗎……", "0", "cv_long_40", "0", "0"},
[411040] = {411040, 11010, 44, 36, "0", "0", "好多人……我也想像領航一樣勇敢呢。", "沢山の人がいる……瓏も勇気を出して、ナビゲーターみたいになりたい。", "0", "0", "好多人……我也想像領航一樣勇敢呢。", "0", "cv_long_41", "0", "0"},
[411041] = {411041, 11010, 45, 37, "0", "0", "嗚哇！", "うわぁ！", "0", "0", "嗚哇！", "0", "cv_long_42", "0", "0"},
[411100] = {411100, 11011, 1, 1, "0", "0", "蒼霧殘響。", "蒼霧殘響（ハツリバーブ）。", "0", "0", "蒼霧殘響。", "0", "cv_honglei_32", "0", "0"},
[411101] = {411101, 11011, 2, 2, "0", "0", "這是您下達的任務嗎？瞭解，我會一直站在這裡的。", "これは貴殿の命令か？承知した。ここから離れぬ。", "0", "0", "這是您下達的任務嗎？瞭解，我會一直站在這裡的。", "0", "cv_honglei_2", "0", "0"},
[411102] = {411102, 11011, 3, 3, "0", "0", "忍心社，轟雷。您就是這支隊伍的領航嗎？我明白了，我會聽從您的所有命令。", "忍心社、轟雷。貴殿がこの隊のナビゲーターか？分かった。命令に従う。", "0", "0", "忍心社，轟雷。您就是這支隊伍的領航嗎？我明白了，我會聽從您的所有命令。", "0", "cv_honglei_1", "0", "0"},
[411103] = {411103, 11011, 4, 4, "0", "idle", "鈴木清風…她不在這裡吧？那就好……領航，給您一個提議，最好不要把她和我安排在一起。", "鈴木清風は……ここにはおらぬようだな。よかった。……貴殿に一つ忠告しておく。彼女と我を同じ所に配置せぬことだ。", "0", "0", "鈴木清風…她不在這裡吧？那就好……領航，給您一個提議，最好不要把她和我安排在一起。", "0", "cv_honglei_3", "0", "0"},
[411104] = {411104, 11011, 5, 4, "0", "idle", "打起精神，領航，您也有自己的任務吧？", "ナビゲーター、しっかりしろ。貴殿にも己の任務があるはずだ。", "0", "0", "打起精神，領航，您也有自己的任務吧？", "0", "cv_honglei_4", "0", "0"},
[411105] = {411105, 11011, 6, 4, "0", "idle", "儘管艾吉斯並不是一個表面上那樣完美的的組織…但它救了我，讓我重獲新生也是不爭的事實。所以，我決定將作為“轟雷”的人生…全部奉獻給艾吉斯。", "アイギスは……特に素晴らしい組織とも言えぬ。だが我を救い、新たな人生を與えてくれたことも紛れのない事実だ。だから我は轟雷としての人生を、全てアイギスに捧げると決意したのだ。", "0", "0", "儘管艾吉斯並不是一個表面上那樣完美的的組織…但它救了我，讓我重獲新生也是不爭的事實。所以，我決定將作為“轟雷”的人生…全部奉獻給艾吉斯。", "0", "cv_honglei_29", "0", "0"},
[411106] = {411106, 11011, 7, 5, "1_》_0_0.8", "level1", "忍心社的成員，平常會偽裝成不起眼的人，來隱藏自己的身份。我們作為艾吉斯的無形之刃，在黑暗中為它服務，直到死亡才會停下，這就是我們的宿命。", "忍心社の者たちは、目立たぬ一般人として生活することで、己の正體を隠している。アイギスの刃として闇の中で己を研ぎすまし、人知れず錆びていく。これが我らの宿命だ。", "0", "0", "忍心社的成員，平常會偽裝成不起眼的人，來隱藏自己的身份。我們作為艾吉斯的無形之刃，在黑暗中為它服務，直到死亡才會停下，這就是我們的宿命。", "0", "cv_honglei_30", "0", "0"},
[411107] = {411107, 11011, 8, 5, "1_》_0_0.8", "level1", "有任務嗎？", "任務か？", "0", "0", "有任務嗎？", "0", "cv_honglei_5", "0", "0"},
[411108] = {411108, 11011, 9, 5, "1_》_100_1.5", "level2", "領航，無論多麼骯髒的任務我都會完成的，這就是我的使命。", "どんな汚い任務でも成し遂げてみせる。これが我が使命だ。", "0", "0", "領航，無論多麼骯髒的任務我都會完成的，這就是我的使命。", "0", "cv_honglei_6", "0", "0"},
[411109] = {411109, 11011, 10, 5, "1_》_500_2", "level3", "成立“忍心社”的目的，是為了防止像“她”那樣的悲劇再次出現。領航，我不會讓任何人傷害您的…您理應有一個美滿的人生。", "忍心社を創設した目的は……彼女のような悲劇を二度と生じさせぬこと。……ナビゲーター、誰にも貴殿を傷付けさせぬ。貴殿には幸せな人生を送って欲しいのだ。", "0", "0", "成立“忍心社”的目的，是為了防止像“她”那樣的悲劇再次出現。領航，我不會讓任何人傷害您的…您理應有一個美滿的人生。", "0", "cv_honglei_7", "0", "0"},
[411110] = {411110, 11011, 11, 5, "1_》_1000_2.5", "level4", "…領航，我一直認為，只要能夠完成任務，無論是別人的性命，亦或是自己的生命，都不過是消耗品。但，唯有您…只有您，是不同的。", "……ナビゲーター。我は任務が達成できるのであれば、人の命や自分の命など、ただの消耗品に過ぎないと思っていた。しかしナビゲーター。貴殿だけは……特別なのだ。", "0", "0", "…領航，我一直認為，只要能夠完成任務，無論是別人的性命，亦或是自己的生命，都不過是消耗品。但，唯有您…只有您，是不同的。", "0", "cv_honglei_8", "0", "0"},
[411111] = {411111, 11011, 12, 6, "0", "0", "嗯，我變得更強了。", "うむ。強くなった。", "0", "0", "嗯，我變得更強了。", "0", "cv_honglei_9", "0", "0"},
[411112] = {411112, 11011, 13, 7, "0", "0", "您相信我嗎？", "貴殿は……我を信じるか？", "0", "0", "您…相信我嗎？", "0", "cv_honglei_10", "0", "0"},
[411113] = {411113, 11011, 14, 8, "0", "0", "您的這份信任，我會用實績來回報的。請原諒我現在只能用一句簡單的“謝謝”來回應您……", "貴殿の信頼に、必ずや実績を持って応えよう。今は、感謝の言葉しかない。許してくれ……", "0", "0", "您的這份信任，我會用實績來回報的。請原諒我現在只能用一句簡單的“謝謝”來回應您……", "0", "cv_honglei_11", "0", "0"},
[411114] = {411114, 11011, 15, 9, "0", "0", "謝謝。", "感謝する。", "0", "0", "謝謝。", "0", "cv_honglei_12", "0", "0"},
[411115] = {411115, 11011, 16, 10, "0", "0", "作戰開始。", "作戦開始。", "0", "0", "作戰開始。", "0", "cv_honglei_13", "0", "0"},
[411116] = {411116, 11011, 17, 11, "0", "0", "這是當然的結果，忍心社從未失敗過。", "當然の結果だ。忍心社に失敗はない。", "0", "0", "這是當然的結果，忍心社從未失敗過。", "0", "cv_honglei_14", "0", "0"},
