[411129] = {411129, 11011, 32, 24, "0", "0", "您已經能夠認出我了…這樣一來，就不太妙了啊。", "我が気配を見抜かれてしまうとは……修行不足か。", "0", "0", "您已經能夠認出我了…這樣一來，就不太妙了啊。", "0", "cv_honglei_27", "0", "0"},
[411130] = {411130, 11011, 33, 25, "0", "0", "偽裝是我們擅長的事，您認不出來，很正常……", "隠れ身は我の得意とするところ。貴殿が分からぬのも當然だ。", "0", "0", "偽裝是我們擅長的事，您認不出來，很正常……", "0", "cv_honglei_28", "0", "0"},
[411131] = {411131, 11011, 34, 26, "0", "0", "領航，開始工作吧，我正看著你。", "ナビゲーター。勤めを果たそう。我もついていく。", "0", "0", "領航，開始工作吧，我正看著你。", "0", "cv_honglei_31", "0", "0"},
[411132] = {411132, 11011, 35, 27, "0", "0", "您下達的任務，我一定會完成的。", "貴殿に與えられた任務、必ずや成し遂げてみせる。", "0", "0", "您下達的任務，我一定會完成的。", "0", "cv_honglei_33", "0", "0"},
