[411205] = {411205, 11012, 6, 4, "0", "idle", "…D型b2……阿爾法的資料庫裏，有關於她的記錄。這樣啊，是她阻止了阿爾法……", "…Ｄ型ｂ－２……アルファのデータベースに、彼女に関する記録があります。なるほど、アルファを止めたのは、彼女……", "0", "0", "0", "0", "cv_arufa_29", "0", "0"},
[411206] = {411206, 11012, 7, 5, "1_》_0_0.8", "level1", "初號機阿爾法，搭載具備自我意識與學習能力的次人格晶片。現在，啟用阿爾法的目的是為了保護人類——阿爾法的資料庫裏，記載著這樣的事。", "初號機アルファ、自我意識と學習能力を備えた次人格チップを搭載。アルファの存在理由は、人間を守る。……アルファのデータベースにこう記載しています。", "0", "0", "0", "0", "cv_arufa_30", "0", "0"},
[411207] = {411207, 11012, 8, 5, "1_》_0_0.8", "level1", "阿爾法的臉…很怪嗎？", "アルファの顔…変ですか？", "0", "0", "0", "0", "cv_arufa_5", "0", "0"},
[411208] = {411208, 11012, 9, 5, "1_》_100_1.5", "level2", "阿爾法…常常會想起以前的事…是阿爾法還沒有成為阿爾法之前的事……是的，我曾經……", "アルファは…時々昔のことを思い出します…アルファがまだアルファではない時のこと……そう、昔の自分……", "0", "0", "0", "0", "cv_arufa_6", "0", "0"},
[411209] = {411209, 11012, 10, 5, "1_》_500_2", "level3", "您如果討厭阿爾法的模樣，就銷毀阿爾法吧……雖然很可怕，但為了領航，阿爾法會忍耐的。", "もしアルファの姿が嫌いでしたら、どうかアルファを処分してください……怖いですが、ナビゲーターのためなら、アルファは我慢します。", "0", "0", "0", "0", "cv_arufa_7", "0", "0"},
[411210] = {411210, 11012, 11, 5, "1_》_1000_2.5", "level4", "阿爾法…是個機器人，不理解人類的情感，也無法與人類共鳴…本來，是這樣的。但是，阿爾法現在卻漸漸知道“感情”是什麼了，阿爾法想…保護領航，守護…人類。", "アルファは…ロボットで、人間の感情を理解できず、共鳴もできない…はずでした。でも今は段々、感情を理解できるようになりました。アルファは、ナビゲーターを…人間を守りたい。", "0", "0", "0", "0", "cv_arufa_8", "0", "0"},
[411211] = {411211, 11012, 12, 6, "0", "0", "阿爾法，變強了。", "アルファ、強くなりました。", "0", "0", "0", "0", "cv_arufa_9", "0", "0"},
[411212] = {411212, 11012, 13, 7, "0", "0", "阿爾法，更新了！", "アルファ、アップデートしました！", "0", "0", "0", "0", "cv_arufa_10", "0", "0"},
