[411401] = {411401, 11014, 2, 2, "0", "0", "哼，你會選擇吾是理所當然的，畢竟吾與汝之間可是存在著不可視的命運紅線在連接著…喂，別走啊，我還沒說完呢！", "フン、汝が妾を選ぶのは當然だ。汝と妾は、運命の赤い糸で結ばれておるのだからなぁ……ってこら！行くな、まだ話の途中だぁ！", "0", "0", "哼，你會選擇吾是理所當然的，畢竟吾與汝之間可是存在著不可視的命運紅線在連接著…喂，別走啊，我還沒說完呢！", "0", "cv_sikadi_2", "0", "0"},
[411402] = {411402, 11014, 3, 3, "0", "0", "終於，找到你了，這就是我與你的宿命嗎？我…吾的名字是斯卡蒂，統治著暗之國的女王…“應該是影之國吧？”…不要在意那麼多啦！", "ようやく見つけたぞ。まさにこれが運命。あた…妾の名はスカディ、影の國を統べる女王なり！……え？冬の女神のほうが正しい？……細かいことを気にするなぁ！", "0", "0", "終於，找到你了，這就是我與你的宿命嗎？我…吾的名字是斯卡蒂，統治著暗之國的女王…“應該是影之國吧？”…不要在意那麼多啦！", "0", "cv_sikadi_1", "0", "0"},
[411403] = {411403, 11014, 4, 4, "0", "idle", "哈——哈——哈，領航，吾能感覺到汝在想什麼…“通感”？不是啦，這是魔法，魔法！", "はっはっはー！ナビゲーター、汝の思惑、妾には隠せぬぞ。……通感覚？違う！これは魔法だ、魔法ぉ！", "0", "0", "哈——哈——哈，領航，吾能感覺到汝在想什麼…“通感”？不是啦，這是魔法，魔法！", "0", "cv_sikadi_3", "0", "0"},
[411404] = {411404, 11014, 5, 4, "0", "idle", "看到了嗎，領航，吾的眼睛正在閃閃發光，這是與汝產生共鳴的徵兆！", "見たか、ナビゲーター。妾の目が光っておるぞ。これは汝との共鳴の兆しじゃ！", "0", "0", "看到了嗎，領航，吾的眼睛正在閃閃發光，這是與汝產生共鳴的徵兆！", "0", "cv_sikadi_4", "0", "0"},
[411405] = {411405, 11014, 6, 4, "0", "idle", "噓——領航，不要告訴莉莉絲我在這裡…真是的，只是一個蛋糕而已，有什麼關係嘛……", "しーっ……ナビゲーター、妾がここに居ること、リリスに言うでないぞ。……まったく、ケーキのひとつぐらい、別にいいじゃないか……", "0", "0", "噓——領航，不要告訴莉莉絲我在這裡…真是的，只是一個蛋糕而已，有什麼關係嘛……", "0", "cv_sikadi_28", "0", "0"},
[411406] = {411406, 11014, 7, 5, "1_》_0_0.8", "level1", "中二病？不是！吾才不是中二病！聽好了，吾是因為被世界選擇，被人們需要，所以才會成為影之國的女王，出現在這裡的！才不是普通的“中二病”！", "中二病？違う！妾は中二病などではないっ！よいかっ。妾は世界に選ばれ、民に必要とされたが故、影の國の女王となってここに顕現したのじゃ！決して中二病ではないぞ！", "0", "0", "中二病？不是！吾才不是中二病！聽好了，吾是因為被世界選擇，被人們需要，所以才會成為影之國的女王，出現在這裡的！才不是普通的“中二病”！", "0", "cv_sikadi_29", "0", "0"},
[411407] = {411407, 11014, 8, 5, "1_》_0_0.8", "level1", "想靠近吾的話，倒也無妨，不過要小心被陰影吞噬喔，領航。", "ナビゲーターよ。妾に近づくのは構わぬが、影に飲み込まれるでないぞ。", "0", "0", "想靠近吾的話，倒也無妨，不過要小心被陰影吞噬噢，領航。", "0", "cv_sikadi_5", "0", "0"},
[411408] = {411408, 11014, 9, 5, "1_》_100_1.5", "level2", "啊，是領航啊。正好，幫吾去買一份補充黑暗力量的魔力劑吧…就是那個…碳酸飲料啦。", "あっ、ナビゲーターだ。……丁度よい。妾の代理としてダークエネルギーを補充する魔剤を入手するのだ。……えーっと、あれだよ……サイダーのことだよ。", "0", "0", "啊，是領航啊。正好，幫吾去買一份補充黑暗力量的魔力劑吧…就是那個…碳酸飲料啦。", "0", "cv_sikadi_6", "0", "0"},
[411409] = {411409, 11014, 10, 5, "1_》_500_2", "level3", "不，不要老是摸吾啦，別把吾當成那些愛撒嬌的孩子！吾可是最強的影之國女王！咳咳…不過，你真這麼喜歡吾的話，吾也不會在意的。", "な、なぜいつも頭をなでるのだ。妾を甘えん坊な子供と一緒にするなぁ！妾は最強なる影の國の女王じゃぞ！オホン……でもまあ、そんなに妾のことが好きなら……仕方ないのう。", "0", "0", "不，不要老是摸吾啦，別把吾當成那些愛撒嬌的孩子！吾可是最強的影之國女王！咳咳…不過，你真這麼喜歡吾的話，吾也不會在意的。", "0", "cv_sikadi_7", "0", "0"},
[411410] = {411410, 11014, 11, 5, "1_》_1000_2.5", "level4", "被陰影與死亡吸引而墮落的人啊，和影之國的女王結下戀…領航！？汝什麼時候在這的？", "影と死に魅了された者よ。影の國の女王と……戀の契りを。……ん？ナ、ナビゲーター！？いつからそこにいたのだぁ？", "0", "0", "被陰影與死亡吸引而墮落的人啊，和影之國的女王結下戀…領航！？汝什麼時候在這的？", "0", "cv_sikadi_8", "0", "0"},
[411411] = {411411, 11014, 12, 6, "0", "0", "喔喔喔，吾感受到了，力量正在提升！", "おおお、感じるぞ！妾の力が漲っておる！", "0", "0", "噢噢噢，吾感受到了，力量正在提升！", "0", "cv_sikadi_9", "0", "0"},
[411412] = {411412, 11014, 13, 7, "0", "0", "喔？想要見識下嗎，吾巔峰時期的實力。", "なんだ？全盛期の妾の力を、その目に焼き付けたいのだな？", "0", "0", "噢？想要見識下嗎，吾巔峰時期的實力。", "0", "cv_sikadi_10", "0", "0"},
[411413] = {411413, 11014, 14, 8, "0", "0", "嗯嗯，現在的吾，已經是完全體了！就算是傳說中的神靈、魔物，怪獸出現在吾的面前，也不會是吾的對手。畢竟，影之國的女王是最強的！", "うむ、今の妾はもはや完全體！例え伝説の神霊、魔物、怪獣が現れようとも相手ではない。なにせ影の國の女王は、最強じゃからなぁ！", "0", "0", "嗯嗯，現在的吾，已經是完全體了！就算是傳說中的神靈、魔物，怪獸出現在吾的面前，也不會是吾的對手。畢竟，影之國的女王是最強的！", "0", "cv_sikadi_11", "0", "0"},
[411414] = {411414, 11014, 15, 9, "0", "0", "吾已經迫不及待想展示這份力量了！", "早くこの力を試させよ！妾はもう待てぬぞ！", "0", "0", "吾已經迫不及待想展示這份力量了！", "0", "cv_sikadi_12", "0", "0"},
[411415] = {411415, 11014, 16, 10, "0", "0", "陰影降臨，亡者的力量！", "影の降臨、亡者の力！", "0", "0", "陰影降臨，亡者的力量！", "0", "cv_sikadi_13", "0", "0"},
[411416] = {411416, 11014, 17, 11, "0", "0", "完美的勝利，哈——哈——哈，見識到了嗎，神靈的力量！", "完全勝利！はっはっはー！見たか、これぞ神霊の力よ！", "0", "0", "完美的勝利，哈——哈——哈，見識到了嗎，神靈的力量！", "0", "cv_sikadi_14", "0", "0"},
[411417] = {411417, 11014, 18, 12, "0", "0", "呼…看來，吾對自己力量的控制還有些不足啊。", "うぅむ……どうやらまだ、力の制禦が足りぬようじゃな。", "0", "0", "呼…看來，吾對自己力量的控制還有些不足啊。", "0", "cv_sikadi_15", "0", "0"},
[411418] = {411418, 11014, 19, 13, "0", "0", "嗚…失誤了，這次不算，這次不算！", "う…ミスった。今回はなし、なしー！", "0", "0", "嗚…失誤了，這次不算，這次不算！", "0", "cv_sikadi_16", "0", "0"},
[411419] = {411419, 11014, 20, 14, "0", "0", "失、失敗了嗎…撤退，我來掩護。", "し、失敗か……撤退だ。あたしが援護する。", "0", "0", "失、失敗了嗎…撤退，我來掩護。", "0", "cv_sikadi_17", "0", "0"},
[411420] = {411420, 11014, 21, 15, "0", "0", "被陰影吞噬吧！", "影に飲まれよ！", "0", "0", "被陰影吞噬吧！", "0", "cv_sikadi_18", "0", "0"},
[411421] = {411421, 11014, 23, 16, "0", "0", "斯卡蒂式迅猛劍X！", "スカディ式、ハヤテブレイドエックス！", "0", "0", "斯卡蒂式迅猛劍X！", "0", "cv_sikadi_19", "0", "0"},
[411422] = {411422, 11014, 26, 19, "0", "0", "吾的時間…到了……", "妾の番が……來た……", "0", "0", "吾的時間…到了……", "0", "cv_sikadi_20", "0", "0"},
[411423] = {411423, 11014, 27, 20, "0", "0", "如何，被吾美麗的身體吸引了嗎？", "なんじゃ。妾の美しい體の虜になったのか？", "0", "0", "如何，被吾美麗的身體吸引了嗎？", "0", "cv_sikadi_21", "0", "0"},
[411424] = {411424, 11014, 28, 21, "0", "0", "吾雖然不介意，可汝真打算這樣一直盯著嗎……", "べ、別に構わぬのじゃが……そのままずっと見ているつもり……なのか？", "0", "0", "吾雖然不介意，可汝真打算這樣一直盯著嗎……", "0", "cv_sikadi_22", "0", "0"},
[411425] = {411425, 11014, 29, 21, "0", "0", "泡澡真舒服啊…讓我…吾想起小時候的事了。", "風呂は気持ちがいいのう……あた…妾の幼き頃を思い出すぞ。", "0", "0", "泡澡真舒服啊…讓我…吾想起小時候的事了。", "0", "cv_sikadi_23", "0", "0"},
[411426] = {411426, 11014, 30, 22, "0", "0", "難道說，是冥界的那些傢夥追來了嗎……", "まさか、冥界の奴らが……", "0", "0", "難道說，是冥界的那些傢伙追來了嗎……", "0", "cv_sikadi_24", "0", "0"},
[411427] = {411427, 11014, 31, 23, "0", "0", "領航，陰影將我們連接在一起…不會猜錯…吧？", "ナビゲーター。影が我らを結んでおるのじゃ。……間違いはせぬ…よな？", "0", "0", "領航，陰影將我們連接在一起…不會猜錯…吧？", "0", "cv_sikadi_25", "0", "0"},
[411428] = {411428, 11014, 32, 24, "0", "0", "很好，吾都想將汝收為影之國的國民了！", "でかした！褒美に影の國の住民として迎え入れてやろうぞ！", "0", "0", "很好，吾都想將汝收為影之國的國民了！", "0", "cv_sikadi_26", "0", "0"},
[411429] = {411429, 11014, 33, 25, "0", "0", "隱藏在影子中的漆黑力量啊，將吾眼前的人燒成灰燼吧！", "影に隠れし漆黒の力よ……目の前のこやつを灰にせよぉ！", "0", "0", "隱藏在影子中的漆黑力量啊，將吾眼前的人燒成灰燼吧！", "0", "cv_sikadi_27", "0", "0"},
[411430] = {411430, 11014, 34, 26, "0", "0", "領航，汝來了啊。就像汝看見的那樣，吾正在練習新的必殺技——“漆黑的迅疾影刃”……喂，不許笑啦！", "おおナビゲーターよ、しかと見たか？これが妾の新たなる必殺技、名付けて……ダークソニックシャドーブレイク……ってこらぁ、笑うなぁ！", "0", "0", "領航，汝來了啊。就像汝看見的那樣，吾正在練習新的必殺技——“漆黑的迅疾影刃”……喂，不許笑啦！", "0", "cv_sikadi_30", "0", "0"},
[411431] = {411431, 11014, 35, 27, "0", "0", "吾的魔眼正在發熱，要來了嗎，“命運”……", "我が魔眼が熱く疼いておる。……來るか。……運命が。", "0", "0", "吾的魔眼正在發熱，要來了嗎，“命運”……", "0", "cv_sikadi_32", "0", "0"},
[411432] = {411432, 11014, 36, 28, "0", "0", "正好，讓汝見識一下女王的力量。", "丁度よい。女王たる力、汝に見せようぞ。", "0", "0", "正好，讓汝見識一下女王的力量。", "0", "cv_sikadi_33", "0", "0"},
[411433] = {411433, 11014, 37, 29, "0", "0", "跟吾比起來，其他人還是差了一截呀。", "妾に比べれば、とるに足らぬものばかりよの。", "0", "0", "跟吾比起來，其他人還是差了一截呀。", "0", "cv_sikadi_34", "0", "0"},
[411434] = {411434, 11014, 38, 30, "0", "0", "吾感受到了…有人在呼喚吾。", "感じるぞ…誰かが妾を呼んでいるっ。", "0", "0", "吾感受到了…有人在呼喚吾。", "0", "cv_sikadi_35", "0", "0"},
[411435] = {411435, 11014, 39, 31, "0", "0", "將現世與影之國的聯繫斬斷的劍，這裡有嗎？", "現世と影の國を斷ち切った剣は、ここにあるのか？", "0", "0", "將現世與影之國的聯繫斬斷的劍，這裡有嗎？", "0", "cv_sikadi_36", "0", "0"},
[411436] = {411436, 11014, 40, 32, "0", "0", "那個，亮亮的東西，吾很中意！", "あのキラキラ光るやつ、妾は気に入ったぞ！", "0", "0", "那個，亮亮的東西，吾很中意！", "0", "cv_sikadi_37", "0", "0"},
[411437] = {411437, 11014, 41, 33, "0", "0", "影之國裡可沒有汝這樣的人呢。", "影の國には、汝のような者はおらぬぞ。", "0", "0", "影之國裡可沒有汝這樣的人呢。", "0", "cv_sikadi_38", "0", "0"},
[411438] = {411438, 11014, 42, 34, "0", "0", "吾…看不懂……", "うむ…分からん……", "0", "0", "吾…看不懂……", "0", "cv_sikadi_39", "0", "0"},
[411439] = {411439, 11014, 43, 35, "0", "0", "小心，也許有來自“官方”的陷阱——", "気をつけよ。「公式」からの罠があるやもしれぬ。", "0", "0", "小心，也許有來自“官方”的陷阱——", "0", "cv_sikadi_40", "0", "0"},
[411440] = {411440, 11014, 44, 36, "0", "0", "直接去他們家吧！", "そやつらの家に向かうのじゃ！", "0", "0", "直接去他們家吧！", "0", "cv_sikadi_41", "0", "0"},
[411441] = {411441, 11014, 45, 37, "0", "0", "嗚哇，按鈕真多。", "うーむ……なんじゃこのボタンの數は。", "0", "0", "嗚哇，按鈕真多。", "0", "cv_sikadi_42", "0", "0"},
[411500] = {411500, 11015, 1, 1, "0", "0", "蒼霧殘響。", "蒼霧殘響ーー（ハツリバーブ）。", "0", "0", "蒼霧殘響。", "0", "cv_lin_32", "0", "0"},
[411501] = {411501, 11015, 2, 2, "0", "0", "呵，領航果然離不開我呢，誰讓我是天才呢~欸？只是站在這裡嗎，這是大材小用啦！", "やれやれ。ナビゲーターはやっぱりあたしがいないとダメだねー。まあ天才だしー。……え？ここに立ってるだけ？そんなの誰だってできるじゃーん！", "0", "0", "呵，領航果然離不開我呢，誰讓我是天才呢~誒？只是站在這裡嗎，這是大材小用啦！", "0", "cv_lin_2", "0", "0"},
[411502] = {411502, 11015, 3, 3, "0", "0", "我的名字叫做鈴，天華閣的王牌，九州的超新星！呼呼，領航，從今天開始，我的時代開始了——喂，聽我說完啦！", "あたしは鈴！天華閣のエース、九州の超新星であーる！フッフーン。ナビゲーター、今日からあたしの時代が開幕……って最後まで聞けー！", "0", "0", "我的名字叫做鈴，天華閣的王牌，九州的超新星！呼呼，領航，從今天開始，我的時代開始了——喂，聽我說完啦！", "0", "cv_lin_1", "0", "0"},
[411503] = {411503, 11015, 4, 4, "0", "idle", "“永不放棄”，這就是我的座右銘！怎麼樣，很帥氣吧？嘻嘻。", "あたしのモットー、それは……ネバーギブアップ！どう？カッコいいでしょ？ニシシ。", "0", "0", "“永不放棄”，這就是我的座右銘！怎麼樣，很帥氣吧？嘻嘻。", "0", "cv_lin_3", "0", "0"},
[411504] = {411504, 11015, 5, 4, "0", "idle", "所謂“天才”，就是要在其他人都放棄、氣餒的時候，一如既往地露出自己帥氣的背影，奮力向前！", "天才はね、他の人が諦めてくじけそうになっていても、いつものように突き進んで、カッコいい背中を見せつけるの！", "0", "0", "所謂“天才”，就是要在其他人都放棄、氣餒的時候，一如既往地露出自己帥氣的背影，奮力向前！", "0", "cv_lin_4", "0", "0"},
[411505] = {411505, 11015, 6, 4, "0", "idle", "上次，我不小心把彩華隊長喜歡的葫蘆弄壞了，我還以為自己要被殺掉了呢。結果隊長卻對我說沒關係，真是溫柔呢~", "こないだね、彩華隊長が大事にしてるひょうたんを壊しちゃったの。「あ、ダメだ。死ぬ……」って思ってたらなんと！大丈夫って言ってくれたのー！隊長やさしー！", "0", "0", "上次，我不小心把彩華隊長喜歡的葫蘆弄壞了，我還以為自己要被殺掉了呢。結果隊長卻對我說沒關係，真是溫柔呢~", "0", "cv_lin_29", "0", "0"},
[411506] = {411506, 11015, 7, 5, "1_》_0_0.8", "level1", "我的夢想是，成為一個受人景仰，被人依賴，並且，勇往直前的英雄！因為我是天才，所以一定能實現的！", "あたしの夢は、みんなが憧れてくれる、頼りにしてくれる、道を切り開くヒーローになること！天才だから、きっと葉えてみせるもんね！", "0", "0", "我的夢想是，成為一個受人景仰，被人依賴，並且，勇往直前的英雄！因為我是天才，所以一定能實現的！", "0", "cv_lin_30", "0", "0"},
[411507] = {411507, 11015, 8, 5, "1_》_0_0.8", "level1", "遇上什麼麻煩事就跟本天才說吧，不用客氣的啦~", "何か面倒なことがあったらこの天才に任せなー。遠慮はいらないよー。", "0", "0", "遇上什麼麻煩事就跟本天才說吧，不用客氣的啦~", "0", "cv_lin_5", "0", "0"},
[411508] = {411508, 11015, 9, 5, "1_》_100_1.5", "level2", "考試總是考零分…？啊，這個……學校教的東西太基礎了，根本沒有學的必要啦！", "テストはいつも０點…？あっ、それは……學校の授業なんか初歩的すぎて、この天才にふさわしくないから！", "0", "0", "考試總是考零分…？啊，這個……學校教的東西太基礎了，根本沒有學的必要啦！", "0", "cv_lin_6", "0", "0"},
[411509] = {411509, 11015, 10, 5, "1_》_500_2", "level3", "領航，你知道嗎，我有兩位母親喔！不管是哪一個，都是十分偉大的母親，所以才會有我這樣的天才誕生！", "ねえねえ知ってる？あたしにはお母さんが二人いるんだよ！二人ともすっごいの！あたしみたいな天才が生まれるのも當然よね！", "0", "0", "領航，你知道嗎，我有兩位母親噢！不管是哪一個，都是十分偉大的母親，所以才會有我這樣的天才誕生！", "0", "cv_lin_7", "0", "0"},
[411510] = {411510, 11015, 11, 5, "1_》_1000_2.5", "level4", "任何時候都要表現出自己最強的一面，這就是天才的天職喔~畢竟，只有這樣，才能成為大家的依靠，才不會讓身邊的人擔心。領航，你可以盡情地依靠我喔~嘿嘿~", "天才の資格とは……どんな時でも最強であること！周りに心配をかけず、むしろ誰からも頼りにされる。それが天才よ！ナビゲーター。好きなだけあたしを頼っていいからねー。えっへーん！", "0", "0", "任何時候都要表現出自己最強的一面，這就是天才的天職噢~畢竟，只有這樣，才能成為大家的依靠，才不會讓身邊的人擔心。領航，你可以盡情地依靠我噢~嘿嘿~", "0", "cv_lin_8", "0", "0"},
[411511] = {411511, 11015, 12, 6, "0", "0", "訓練真開心啊！", "訓練おもしろーい！", "0", "0", "訓練真開心啊！", "0", "cv_lin_9", "0", "0"},
[411512] = {411512, 11015, 13, 7, "0", "0", "我的才能，正在蘇醒~", "あたしの才能が開花しちゃう！", "0", "0", "我的才能，正在蘇醒~", "0", "cv_lin_10", "0", "0"},
[411513] = {411513, 11015, 14, 8, "0", "0", "嚇了一跳吧？哼哼，這就是我火力全開後的模樣！我已經，戰無不勝啦！", "びっくりしたー？ふっふーん。これがパワー全開のあたしだよ！もはや完全無敵だあ！", "0", "0", "嚇了一跳吧？哼哼，這就是我火力全開後的模樣！我已經，戰無不勝啦！", "0", "cv_lin_11", "0", "0"},
[411514] = {411514, 11015, 15, 9, "0", "0", "欸？！怎麼做到的？", "え？どうやったの！？", "0", "0", "誒？！怎麼做到的？", "0", "cv_lin_12", "0", "0"},
[411515] = {411515, 11015, 16, 10, "0", "0", "無敵的天才來啦！", "無敵の天才さまの登場だ！", "0", "0", "無敵的天才來啦！", "0", "cv_lin_13", "0", "0"},
[411516] = {411516, 11015, 17, 11, "0", "0", "完美勝利…？我做到的…？——咳咳！這是當然的，我可是天才嘛！", "完全勝利…？あたしが…？オホン！當然だよね、天才なんだもん！", "0", "0", "完美勝利…？我做到的…？——咳咳！這是當然的，我可是天才嘛！", "0", "cv_lin_14", "0", "0"},
