[411518] = {411518, 11015, 19, 13, "0", "0", "嗚…失誤了…這，這是我故意的！", "うぅ…やっちゃった……こ、これはわざとだもん！", "0", "0", "嗚…失誤了…這，這是我故意的！", "0", "cv_lin_16", "0", "0"},
[411519] = {411519, 11015, 20, 14, "0", "0", "不甘心……下次，下次我會贏回來的，一定！", "悔しい……次、次は勝ってみせるから、絶対っ！", "0", "0", "不甘心……下次，下次我會贏回來的，一定！", "0", "cv_lin_17", "0", "0"},
