[411529] = {411529, 11015, 32, 24, "0", "0", "厲害…咳，這是當然的結果啦！", "え、すごい……オ、オホン！當然の結果よ！", "0", "0", "厲害…咳，這是當然的結果啦！", "0", "cv_lin_27", "0", "0"},
