[411701] = {411701, 11017, 2, 2, "0", "0", "收到，芙蘿拉保證不會讓您失望的。", "承知いたしました。あなた様のご期待に応えてみせます。", "0", "0", "收到，芙蘿拉保證不會讓您失望的。", "0", "cv_fuluola_2", "0", "0"},
[411702] = {411702, 11017, 3, 3, "0", "0", "多瑙第一親衛班隊長，芙蘿拉。欸？您問為什麼親衛隊要穿女僕裝？", "ダニューブ第一親衛班班長、フローラと申します。え？どうして親衛班がメイド服なのか、ですか？", "0", "0", "多瑙第一親衛班隊長，芙蘿拉。哎？您問為什麼親衛隊要穿女僕裝？", "0", "cv_fuluola_1", "0", "0"},
[411703] = {411703, 11017, 4, 4, "0", "idle", "方舟正在平穩地行駛，看來暫時沒有什麼要忙的，要為您泡杯茶嗎？", "方舟の運航は順調です。暫くゆっくりなさってください。そうだ、お茶を淹れましょうか？", "0", "0", "方舟正在平穩地行駛，看來暫時沒有什麼要忙的，要為您泡杯茶嗎？", "0", "cv_fuluola_3", "0", "0"},
[411704] = {411704, 11017, 5, 4, "0", "idle", "我的武器嚇到您了嗎？很抱歉，現在就收起來。", "わたくしの武器で驚かせてしまったでしょうか？申し訳ありません。今すぐ収めます。", "0", "0", "我的武器嚇到您了嗎？很抱歉，現在就收起來。", "0", "cv_fuluola_4", "0", "0"},
[411705] = {411705, 11017, 6, 4, "0", "idle", "身為親衛班的隊長，我更應該要起到表率作用。有機會的話，我想要向朱利烏斯小姐請教一下。", "わたくしは親衛班の班長として、常に模範とならなければいけません。今度、ユリウスさんにご指導いただこうと思います。", "0", "0", "身為親衛班的隊長，我更應該要起到表率作用。有機會的話，我想要向朱利烏斯小姐請教一下。", "0", "cv_fuluola_29", "0", "0"},
[411706] = {411706, 11017, 7, 5, "1_》_0_0.8", "level1", "第一親衛班的首要任務是確保多瑙的象徵——方舟能夠安全地行駛。當然，我們本身也常常被當做是多瑙駕駛員的代表，所以維持自身形象是非常有必要的。", "第一親衛班の最も重要な任務はダニューブの象徴、方舟を守ることです。また、わたくしたちはダニューブのドライバーの代表として見られることが多いですから、自身のイメージを維持することも非常に重要です。", "0", "0", "第一親衛班的首要任務是確保多瑙的象徵——方舟能夠安全地行駛。當然，我們本身也常常被當做是多瑙駕駛員的代表，所以維持自身形象是非常有必要的。", "0", "cv_fuluola_5", "0", "0"},
[411707] = {411707, 11017, 8, 5, "1_》_0_0.8", "level1", "嗯，今天的巡視任務已經結束了，隨時聽從您的調遣。", "はい。本日の巡迴は終了しました。何なりとお申しつけください。", "0", "0", "嗯，今天的巡視任務已經結束了，隨時聽從您的調遣。", "0", "cv_fuluola_30", "0", "0"},
[411708] = {411708, 11017, 9, 5, "1_》_100_1.5", "level2", "我的父母？嗯，她們不光光是養育我的人，同時還是我努力想要成為的人。作為親衛的後代，我必須要做得比其他隊員更好。只有這樣，才不會辜負大家的期待。", "わたくしの両親ですか？はい。わたくしを育ててくれただけでなく、わたくしの目標でもあります。親衛班の家系で生まれたわたくしは、他の隊員以上に責務を全うしなければなりません。でなければ、皆様の期待を裏切ることになってしまいます。", "0", "0", "我的父母？嗯，她們不光光是養育我的人，同時還是我努力想要成為的人。作為親衛的後代，我必須要做得比其他隊員更好。只有這樣，才不會辜負大家的期待。", "0", "cv_fuluola_6", "0", "0"},
[411709] = {411709, 11017, 10, 5, "1_》_500_2", "level3", "真是羡慕朱利烏斯和查麗莎小姐啊……如果我不是親衛的話，也想像她們一樣和您並肩作戰。但是，我現在有更重要的東西要去做，守住多瑙的方舟是我的使命……", "ユリウスさんとチャリサーさんが羨ましいです。もしわたくしも親衛隊でなければ、彼女たちのようにあなた様と共に戦いたい……。ですがわたくしには為すべきことが、ダニューブの方舟を守るという使命があるのです。", "0", "0", "真是羡慕朱利烏斯和查麗莎小姐啊……如果我不是親衛的話，也想像她們一樣和您並肩作戰。但是，我現在有更重要的東西要去做，守住多瑙的方舟是我的使命……", "0", "cv_fuluola_7", "0", "0"},
[411710] = {411710, 11017, 11, 5, "1_》_1000_2.5", "level4", "雖然無法和您一同遠征，但也有身為親衛的我能做的事。無論您身處何方都還請放心，我一定會守住您和您同伴們的歸所。如果有一天您感到疲憊了也隨時都能回來休息一段時間，我會在這裡等著您的。", "あなたと共に遠征はできませんが、親衛班であるわたくしだからこそ、できることがあります。ご安心ください。あなた様と仲間の皆様の帰る場所は、わたくしが必ずお守りします。もし疲れたら、いつでも帰ってきてください。いつでもここでお待ちしております。", "0", "0", "雖然無法和您一同遠征，但也有身為親衛的我能做的事。無論您身處何方都還請放心，我一定會守住您和您同伴們的歸所。如果有一天您感到疲憊了也隨時都能回來休息一段時間，我會在這裡等著您的。", "0", "cv_fuluola_8", "0", "0"},
[411711] = {411711, 11017, 12, 6, "0", "0", "呼~力氣變大了呢。", "ふぅ……力が増したようです。", "0", "0", "呼~力氣變大了呢。", "0", "cv_fuluola_9", "0", "0"},
[411712] = {411712, 11017, 13, 7, "0", "0", "一切都是為了多瑙。", "すべてはダニューブのために。", "0", "0", "一切都是為了多瑙。", "0", "cv_fuluola_10", "0", "0"},
[411713] = {411713, 11017, 14, 8, "0", "0", "呼啊~神清氣爽……簡直就像是漫步在春天的花園中一樣。", "ああ、なんと清らかな……春の庭園にいるかのようです。", "0", "0", "呼啊~神清氣爽……簡直就像是漫步在春天的花園中一樣。", "0", "cv_fuluola_11", "0", "0"},
[411714] = {411714, 11017, 15, 9, "0", "0", "很好，就這樣繼續下去吧。", "いいですね。このまま続けましょう。", "0", "0", "很好，就這樣繼續下去吧。", "0", "cv_fuluola_12", "0", "0"},
[411715] = {411715, 11017, 16, 10, "0", "0", "嗯，一口氣解決它們吧。", "はい。一気に倒しましょう。", "0", "0", "嗯，一口氣解決它們吧。", "0", "cv_fuluola_13", "0", "0"},
