[411718] = {411718, 11017, 19, 13, "0", "0", "放棄追擊吧，比起殲滅敵人，保全戰力才是重要的。", "追撃はやめましょう、敵の殲滅より、戦力の溫存が大事です。", "0", "0", "放棄追擊吧，比起殲滅敵人，保全戰力才是重要的。", "0", "cv_fuluola_16", "0", "0"},
