[411902] = {411902, 11019, 3, 3, "0", "0", "鏘鏘！雛鷹小隊成員天天報導！你就是領航嗎？來吃一個我親手做的蛋糕吧！", "0", "0", "0", "鏘鏘！雛鷹小隊成員天天報導！你就是領航嗎？來吃一個我親手做的蛋糕吧！", "0", "cv_tenten_1", "0", "0"},
[411903] = {411903, 11019, 4, 4, "0", "idle", "領航！到飯點了，天天給你做漢堡肉吃吧！", "0", "0", "0", "領航！到飯點了，天天給你做漢堡肉吃吧！", "0", "cv_tenten_3", "0", "0"},
[411904] = {411904, 11019, 5, 4, "0", "idle", "不喜歡吃蔬菜嗎？挑食的孩子可不是好孩子，領航可要好好吃完這些青菜喔！", "0", "0", "0", "不喜歡吃蔬菜嗎？挑食的孩子可不是好孩子，領航可要好好吃完這些青菜哦！", "0", "cv_tenten_4", "0", "0"},
[411905] = {411905, 11019, 6, 4, "0", "idle", "領航，請更放心地指揮我們吧，不用顧慮雛鷹小隊實習生的身份。既然成了駕駛員，總有一天要和原罪戰鬥的。", "0", "0", "0", "領航，請更放心地指揮我們吧，不用顧慮雛鷹小隊實習生的身份。既然成了駕駛員，總有一天要和原罪戰鬥的。", "0", "cv_tenten_28", "0", "0"},
[411906] = {411906, 11019, 7, 5, "1_》_0_0.8", "level1", "要是有更多的食材就好了，天天就可以給領航每天都做不同好吃的了！", "0", "0", "0", "要是有更多的食材就好了，天天就可以給領航每天都做不同好吃的了！", "0", "cv_tenten_29", "0", "0"},
