[411908] = {411908, 11019, 9, 5, "1_》_100_1.5", "level2", "嘿嘿，天天今天也完美完成任務了呢，領航！晚上來做一頓大餐吧！", "0", "0", "0", "嘿嘿，天天今天也完美完成任務了呢，領航！晚上來做一頓大餐吧！", "0", "cv_tenten_6", "0", "0"},
[411909] = {411909, 11019, 10, 5, "1_》_500_2", "level3", "我的料理都是我爸爸教我的，他曾經告訴我“只要食客吃得開心，就是廚師最大的幸福”，和領航在一起天天也感覺很幸福喔。", "0", "0", "0", "我的料理都是我爸爸教我的，他曾經告訴我“只要食客吃得開心，就是廚師最大的幸福”，和領航在一起天天也感覺很幸福哦。", "0", "cv_tenten_7", "0", "0"},
[411910] = {411910, 11019, 11, 5, "1_》_1000_2.5", "level4", "爸爸教過我一道特殊的料理，當年我的媽媽就是嘗了這道料理才和我爸爸結婚的。欸，領航你想嘗嘗這道料理？不行!不行!爸爸說過這料理只能做給……倒也不是不行啦，不過吃完領航可要負責喔！", "0", "0", "0", "爸爸教過我一道特殊的料理，當年我的媽媽就是嘗了這道料理才和我爸爸結婚的。誒，領航你想嘗嘗這道料理？不行!不行!爸爸說過這料理只能做給……倒也不是不行啦，不過吃完領航可要負責哦！", "0", "cv_tenten_8", "0", "0"},
