[412000] = {412000, 11020, 1, 1, "0", "0", "蒼霧殘響", "0", "0", "0", "0", "0", "cv_caroline_32", "0", "0"},
[412001] = {412001, 11020, 2, 2, "0", "0", "誒？啊！嗯！當然沒問題，我完全可以勝任這個位置，我是這麼想的！", "0", "0", "0", "0", "0", "cv_caroline_2", "0", "0"},
[412002] = {412002, 11020, 3, 3, "0", "0", "領航，您好！我是來自鐵鴉小隊的卡洛琳！還有，這是我的個人資料，一定不要弄丟了！", "0", "0", "0", "0", "0", "cv_caroline_1", "0", "0"},
[412003] = {412003, 11020, 4, 4, "0", "idle", "呃……巨大化之後卻只是在這裏站著，不會很奇怪嗎？“大家都是這麼做的”……真的？您不會是在騙我吧？", "0", "0", "0", "0", "0", "cv_caroline_3", "0", "0"},
[412004] = {412004, 11020, 5, 4, "0", "idle", "是錯覺嗎……感覺站久了之後，身體在慢慢變透明……一定是錯覺吧，對吧？", "0", "0", "0", "0", "0", "cv_caroline_4", "0", "0"},
[412005] = {412005, 11020, 6, 4, "0", "idle", "唉，隊長到底什麼時候才能想起以前的事啊……真是的……", "0", "0", "0", "0", "0", "cv_caroline_29", "0", "0"},
[412006] = {412006, 11020, 7, 5, "1_》_0_0.8", "level1", "領航，有時候我會這麼想，誕生於世的人，應該都有他們存在的使命。不管是多麼不起眼的人，也一定能有她能勝任的位置……我是這麼想的…………誒？您沒在聽嗎？難道您從一開始就沒在聽我說話嗎！？", "0", "0", "0", "0", "0", "cv_caroline_30", "0", "0"},
[412007] = {412007, 11020, 8, 5, "1_》_0_0.8", "level1", "有什麼事嗎？", "0", "0", "0", "0", "0", "cv_caroline_5", "0", "0"},
[412008] = {412008, 11020, 9, 5, "1_》_100_1.5", "level2", "多瑙支部……應該說艾吉斯的駕駛員，和我不一樣，都有著自己的特色呢……啊，我可不會因此自卑噢！對我而言，普通是最好的了，我是這麼想的！", "0", "0", "0", "0", "0", "cv_caroline_6", "0", "0"},
[412009] = {412009, 11020, 10, 5, "1_》_500_2", "level3", "隊長說，偵查的時候需要像我這樣巨大化後也沒什麼存在感的駕駛員。雖然是事實……但真希望她說的時候能夠注意下我的個人感受啦。", "0", "0", "0", "0", "0", "cv_caroline_7", "0", "0"},
[412010] = {412010, 11020, 11, 5, "1_》_1000_2.5", "level4", "如果沒有戰爭，許多人都不會走上“英雄”的道路。但我相信，即使是那些英雄，也一定盼望著“普通”的人生。所以，我的責任一定就是讓那些遠離日常的英雄們，回到她們本該的位置上……我是這麼想的。", "0", "0", "0", "0", "0", "cv_caroline_8", "0", "0"},
[412011] = {412011, 11020, 12, 6, "0", "0", "揮劍的速度更快了呢。", "0", "0", "0", "0", "0", "cv_caroline_9", "0", "0"},
[412012] = {412012, 11020, 13, 7, "0", "0", "多、多了一顆星星？", "0", "0", "0", "0", "0", "cv_caroline_10", "0", "0"},
[412013] = {412013, 11020, 14, 8, "0", "0", "謝謝您，領航…嗯？我可不會做出什麼特殊反應噢，領航。即使擁有這樣的力量，我也不會有什麼改變啦，因為我就是我嘛，我是這麼想的。", "0", "0", "0", "0", "0", "cv_caroline_11", "0", "0"},
[412014] = {412014, 11020, 15, 9, "0", "0", "普通萬歲！", "0", "0", "0", "0", "0", "cv_caroline_12", "0", "0"},
[412015] = {412015, 11020, 16, 10, "0", "0", "呼，我沒有來遲吧？", "0", "0", "0", "0", "0", "cv_caroline_13", "0", "0"},
[412016] = {412016, 11020, 17, 11, "0", "0", "是我們的完全勝利，領航！", "0", "0", "0", "0", "0", "cv_caroline_14", "0", "0"},
[412017] = {412017, 11020, 18, 12, "0", "0", "普普通通的勝利不也挺好的嗎？", "0", "0", "0", "0", "0", "cv_caroline_15", "0", "0"},
[412018] = {412018, 11020, 19, 13, "0", "0", "多少……有點狼狽呢。", "0", "0", "0", "0", "0", "cv_caroline_16", "0", "0"},
