[412025] = {412025, 11020, 28, 21, "0", "0", "您差不多……該出去了吧，領航？", "0", "0", "0", "0", "0", "cv_caroline_23", "0", "0"},
[412026] = {412026, 11020, 29, 21, "0", "0", "難道說，其他人泡澡的時候，領航您也是像這樣……？", "0", "0", "0", "0", "0", "cv_caroline_24", "0", "0"},
