[412031] = {412031, 11020, 34, 26, "0", "0", "領航，在您不在的時候我已經把文檔整理好了！今天也一起努力吧！", "0", "0", "0", "0", "0", "cv_caroline_31", "0", "0"},
[412032] = {412032, 11020, 35, 27, "0", "0", "偶爾也會覺得，您的故事就像現代的史詩呢。", "0", "0", "0", "0", "0", "cv_caroline_33", "0", "0"},
[412033] = {412033, 11020, 36, 28, "0", "0", "我會全力以赴的。", "0", "0", "0", "0", "0", "cv_caroline_34", "0", "0"},
