[412040] = {412040, 11020, 43, 35, "0", "0", "看郵件~看郵件~", "0", "0", "0", "0", "0", "cv_caroline_41", "0", "0"},
[412041] = {412041, 11020, 44, 36, "0", "0", "大家好？", "0", "0", "0", "0", "0", "cv_caroline_42", "0", "0"},
[412042] = {412042, 11020, 45, 37, "0", "0", "嗯？", "0", "0", "0", "0", "0", "cv_caroline_43", "0", "0"},
[412100] = {412100, 11021, 1, 1, "0", "0", "蒼霧殘響！", "蒼霧殘響（ハツリバーブ）！", "0", "0", "0", "0", "cv_sikadi_sw_1", "0", "0"},
[412101] = {412101, 11021, 2, 2, "0", "0", "哈——哈——哈，領航，吾都等你好久了。選吾不是毋庸置疑的嘛！", "はーっはっはー！ナビゲーター、待っておったぞ。妾を選ぶのに何を迷う！", "0", "0", "0", "0", "cv_sikadi_sw_2", "0", "0"},
[412102] = {412102, 11021, 3, 3, "0", "0", "吾乃影之國的夏之女王，這是吾百般王之形態的其中一種，只有借助陽炎的力量才能顯現的特殊形態！", "妾は影の國……夏の女王！王が持つ百の姿の一。太陽の力によってのみ発現する特別な姿なのじゃ！", "0", "0", "0", "0", "cv_sikadi_sw_3", "0", "0"},
[412103] = {412103, 11021, 4, 4, "0", "idle", "……你說吾背後有兩個模糊的人影？……嗯！？沒、沒有呀。吾、我完全沒看到哦。你在騙我對吧？", "妾の背後に……人影が二つ？……ええっ！？ど、どこにもおらんぞ。噓じゃよな……ナビゲーター？", "0", "0", "0", "0", "cv_sikadi_sw_4", "0", "0"},
[412104] = {412104, 11021, 5, 4, "0", "idle", "說起來，最近睡覺的時候經常做夢。醒來後又好像學會了新的招式…………難道吾被封印的記憶覺醒了嗎？", "そう言えば妾はよく夢を見るんじゃが、起きたら新しい技を覚えてることがあって…………もしかして、妾の封印されし記憶が蘇ったのか！？", "0", "0", "0", "0", "cv_sikadi_sw_5", "0", "0"},
[412105] = {412105, 11021, 6, 4, "0", "idle", "睡了一覺起來渾身酸痛，像是打了很多場架。嘛，不過，現在已經完全恢復了。所以陪吾一起去看海吧！領航！", "目が覚めたら全身筋肉痛で、なんかいっぱい戦った感じがするんじゃが……でももう全回復したぞ！一緒に海を見に行くぞ、ナビゲーター！", "0", "0", "0", "0", "cv_sikadi_sw_6", "0", "0"},
[412106] = {412106, 11021, 7, 5, "1_》_0_0.8", "level1", "陽炎想要覆滅大地上的一切生機，即使是吾也受到了它的影響，但是極淵之地的冰寒中篆刻著破解這高懸陽炎的辦法。領航……要去吃霜淇淋嗎。", "太陽がこの大地に生きる者すべてを圧倒し、妾ですらその影響を受けておる。だが極寒の地の氷に、この炎熱に対抗する方法が封じられていたのじゃ。つまり、ナビゲーターよ……アイスクリームを食べに行かぬか？", "0", "0", "0", "0", "cv_sikadi_sw_7", "0", "0"},
[412107] = {412107, 11021, 8, 5, "1_》_0_0.8", "level1", "吾說的話能讓大家鼓起勇氣？嗯！因為吾是要保護影之國居民的女王嘛！", "妾の言葉はみんなを勇気づける？うむ！妾は影の國の民を守る女王じゃからな！", "0", "0", "0", "0", "cv_sikadi_sw_8", "0", "0"},
[412108] = {412108, 11021, 9, 5, "1_》_100_1.5", "level2", "上次回孤兒院，甚至還碰到了以前的朋友，大家都長得好高，只有吾沒什麼變化，唔……", "この前孤児院に行って昔の友達と會ったのじゃが、みんな背がすっごく伸びていて……妾だけ昔のままで、ううぅ……", "0", "0", "0", "0", "cv_sikadi_sw_9", "0", "0"},
[412109] = {412109, 11021, 10, 5, "1_》_500_2", "level3", "領航，不管發生什麼事情吾都會來到你身邊保護你的哦！不論是過去，現在，還是未來，只要你高呼著“斯卡蒂”的名字，那麼影之國女王便會來到你身邊。", "ナビゲーター。例え何があろうと、妾が守ってやるぞ！過去、現在、そしてこれからも……スカディと呼べば、影の女王がすぐに降臨するのじゃ！", "0", "0", "0", "0", "cv_sikadi_sw_10", "0", "0"},
[412110] = {412110, 11021, 11, 5, "1_》_1000_2.5", "level4", "昨天夢見吾落在了海裏，是領航救了吾。吾和領航流落到了一座荒島上，然後我們就在島上一起生活……之後？……之，之後吾，吾吾吾已經全部忘掉了！！", "ゆうべ海に落ちる夢を見て……ナビゲーターが妾を救ってくれたのじゃ。そして妾たちは孤島に流れ著いて、二人で暮らし始めて…………それから？そっ、そそそれからは何も覚えとらーん！", "0", "0", "0", "0", "cv_sikadi_sw_11", "0", "0"},
[412111] = {412111, 11021, 12, 6, "0", "0", "又要測試啊？稍微等我一下，馬上就來嘛！", "またテストか？ちょっと待て。すぐに行くぞ！", "0", "0", "0", "0", "cv_sikadi_sw_12", "0", "0"},
[412112] = {412112, 11021, 13, 7, "0", "0", "閃光的一角。", "シャイニングエッジ！", "0", "0", "0", "0", "cv_sikadi_sw_13", "0", "0"},
[412113] = {412113, 11021, 14, 8, "0", "0", "現在的吾還不是完全體。雖然現在已經足夠了，但果然還是很期待啊，吾的究極形態！！", "妾はまだ完全體ではない。これで十分とも言えるが、究極形態が本當に楽しみじゃ！", "0", "0", "0", "0", "cv_sikadi_sw_14", "0", "0"},
[412114] = {412114, 11021, 15, 9, "0", "0", "POWER！", "パワー！！", "0", "0", "0", "0", "cv_sikadi_sw_15", "0", "0"},
[412115] = {412115, 11021, 16, 10, "0", "0", "明明特地穿了泳裝…竟然要戰鬥？！", "せっかく水著を著たのに…戦うのか？", "0", "0", "0", "0", "cv_sikadi_sw_16", "0", "0"},
[412116] = {412116, 11021, 17, 11, "0", "0", "接下來？該去游泳咯~", "これからどうするか、じゃと？泳ぎに行くに決まっておろー！", "0", "0", "0", "0", "cv_sikadi_sw_17", "0", "0"},
[412117] = {412117, 11021, 18, 12, "0", "0", "還差一點就成功了……領航~我已經累了。", "あとちょっとでパーフェクトだったのに……もう疲れたのじゃー！", "0", "0", "0", "0", "cv_sikadi_sw_18", "0", "0"},
[412118] = {412118, 11021, 19, 13, "0", "0", "誒！雖然勝利了，嗯——嗯——但是有種微妙的感覺呢。", "勝ちはしたが、うむ……うーん…微妙な感じじゃな。", "0", "0", "0", "0", "cv_sikadi_sw_19", "0", "0"},
[412119] = {412119, 11021, 20, 14, "0", "0", "呀——這、這一下不算！", "やあぁっ！……い、今のなし！", "0", "0", "0", "0", "cv_sikadi_sw_20", "0", "0"},
[412120] = {412120, 11021, 21, 15, "0", "0", "到此為止吧，你們不可再越過此處。", "ここで終わりじゃ！", "0", "0", "0", "0", "cv_sikadi_sw_22", "0", "0"},
[412121] = {412121, 11021, 23, 16, "0", "0", "嘿呀！", "せいや！", "0", "0", "0", "0", "cv_sikadi_sw_21", "0", "0"},
[412122] = {412122, 11021, 24, 17, "0", "0", "斯卡蒂式帝王劍α！", "スカディ式キングスラッシュ・アルファ！！", "0", "0", "0", "0", "cv_sikadi_sw_24", "0", "0"},
[412123] = {412123, 11021, 26, 19, "0", "0", "唔嗯、這一次就饒過你們！", "うぐぐ……今回だけは見逃してやる！", "0", "0", "0", "0", "cv_sikadi_sw_23", "0", "0"},
[412124] = {412124, 11021, 27, 20, "0", "0", "領航！？……吾就特許你和吾一、一起共浴吧！", "ナ、ナビゲーター！？……し、仕方がない。特別に許してやるぞ。", "0", "0", "0", "0", "cv_sikadi_sw_25", "0", "0"},
[412125] = {412125, 11021, 28, 21, "0", "0", "嗯！吾每次來到這裏，就像回到了影之國一樣安心。", "うむ……いつもここに來ると、影の國にいるみたいに安心するのじゃ。", "0", "0", "0", "0", "cv_sikadi_sw_26", "0", "0"},
[412126] = {412126, 11021, 29, 21, "0", "0", "領航……？如果累了的話，可以坐在吾的身上休息一下哦。", "ナビゲーター？疲れたならここに座って休むがよい。", "0", "0", "0", "0", "cv_sikadi_sw_27", "0", "0"},
[412127] = {412127, 11021, 30, 22, "0", "0", "要、要開始了嗎？", "な、なんか始まるのか？", "0", "0", "0", "0", "cv_sikadi_sw_28", "0", "0"},
[412128] = {412128, 11021, 31, 23, "0", "0", "領航，領航，你看你看，吾背上的紋章！", "ナビゲーター、見よ！この背に刻まれた紋章を。", "0", "0", "0", "0", "cv_sikadi_sw_29", "0", "0"},
[412129] = {412129, 11021, 32, 24, "0", "0", "就該這樣嘛！吾從來都沒想過領航會猜錯哦！", "そうこなくっちゃ！汝が外すはずないのじゃ！", "0", "0", "0", "0", "cv_sikadi_sw_30", "0", "0"},
[412130] = {412130, 11021, 33, 25, "0", "0", "你一定是故意選錯的吧？對不對？是不是？", "わざと外したんじゃろ……？そうじゃな？な？", "0", "0", "0", "0", "cv_sikadi_sw_31", "0", "0"},
[412131] = {412131, 11021, 34, 26, "0", "0", "領航，吾等你很久了哦。", "ナビゲーター、待ちくたびれたぞ！！", "0", "0", "0", "0", "cv_sikadi_sw_32", "0", "0"},
[412132] = {412132, 11021, 35, 27, "0", "0", "領航，給你看看吾在夢中學到的，超級厲害的技藝哦。", "ナビゲーターに見せてやろう。妾が夢で修得した、超淒い技をな！", "0", "0", "0", "0", "cv_sikadi_sw_33", "0", "0"},
[412133] = {412133, 11021, 36, 28, "0", "0", "哼哼，無論挑戰吾多少次結果也不會改變哦？你們一起上吧！", "フフン、妾に何度挑んでも結果は変わらんぞ？まとめてかかってくるがいい！", "0", "0", "0", "0", "cv_sikadi_sw_34", "0", "0"},
[412134] = {412134, 11021, 37, 29, "0", "0", "……領航真是受歡迎啊。", "……ナビゲーターは本當にモテモテだな。", "0", "0", "0", "0", "cv_sikadi_sw_35", "0", "0"},
[412135] = {412135, 11021, 38, 30, "0", "0", "收到新的調度書了？", "新しい配置書か？", "0", "0", "0", "0", "cv_sikadi_sw_36", "0", "0"},
[412136] = {412136, 11021, 39, 31, "0", "0", "讓吾看看，科研部又研發了什麼新武器。", "どれどれー。開発部門の新兵器はあるかなー？", "0", "0", "0", "0", "cv_sikadi_sw_37", "0", "0"},
[412137] = {412137, 11021, 40, 32, "0", "0", "我什麼都不要，嗯……", "妾は何もいらぬぞ。……うん。", "0", "0", "0", "0", "cv_sikadi_sw_38", "0", "0"},
[412138] = {412138, 11021, 41, 33, "0", "0", "看看有沒有吾的畫像。", "妾の寫真はあるか？", "0", "0", "0", "0", "cv_sikadi_sw_39", "0", "0"},
[412139] = {412139, 11021, 42, 34, "0", "0", "可不許關掉吾的聲音哦！", "妾の聲を消すとか許さんぞ！", "0", "0", "0", "0", "cv_sikadi_sw_40", "0", "0"},
[412140] = {412140, 11021, 43, 35, "0", "0", "讓可靠的我來看看吧！", "頼りになる妾が見てやろう！", "0", "0", "0", "0", "cv_sikadi_sw_41", "0", "0"},
[412141] = {412141, 11021, 44, 36, "0", "0", "吾好像聽到了……世界之外的語音！", "世界の外から何か聞こえた気がするぞ！", "0", "0", "0", "0", "cv_sikadi_sw_42", "0", "0"},
[412142] = {412142, 11021, 45, 37, "0", "0", "嗯！", "うむ！", "0", "0", "0", "0", "cv_sikadi_sw_43", "0", "0"},
[412200] = {412200, 11022, 1, 1, "0", "0", "誒？蒼霧……殘響？", "え？　はつ……りばーぶ？", "0", "0", "0", "0", "cv_wangnv_1", "0", "0"},
[412201] = {412201, 11022, 2, 2, "0", "0", "好好笑哦，這個角度的領航像小蟲子一樣，真可愛。", "おっかし～。こっから見るとナビくん、蟲みたいで可愛いじゃん。", "0", "0", "0", "0", "cv_wangnv_2", "0", "0"},
[412202] = {412202, 11022, 3, 3, "0", "0", "哦，好久不見打擾了，我是王女。嗯……？你問我為什麼能出現在這裡？不要在意這種小事嘛！", "おっひさー、王女だよー。え……？　なんでここにいるのかって？　細かいことはどうでもいいじゃん！", "0", "0", "0", "0", "cv_wangnv_3", "0", "0"},
[412203] = {412203, 11022, 4, 4, "0", "idle", "嗯……我就像一個趕不走的租客一樣寄宿在領航的身邊，這話聽起來是不是有點色情？", "ふむふむ……追い出せない同居人みたいにナビくんから離れない……って聞くとちょっとエッチじゃない？", "0", "0", "0", "0", "cv_wangnv_4", "0", "0"},
[412204] = {412204, 11022, 5, 4, "0", "idle", "可以看到很多熟悉的面孔呢……欸……剛剛走過來的那個人是不是小斯卡蒂！好可惜！我好想過去和她打招呼哦！", "ちらほらと見覚えのある顔が……あっ今通り過ぎたのってすかきちじゃん！　やばー！　挨拶しとけば良かったぁ！", "0", "0", "0", "0", "cv_wangnv_5", "0", "0"},
[412205] = {412205, 11022, 6, 4, "0", "idle", "誒……你平時有這麼多文件要處理啊，好麻煩哦，真是難為你了。我看到這麼多檔就會犯困，因為一點都沒有意思嘛——！", "えぇ……普段からこんなに書類仕事があるのー？　大変だねー。同情しちゃうよ。あーしなら白目剝いちゃうね。だってマジ面白くなさそうだしー！", "0", "0", "0", "0", "cv_wangnv_6", "0", "0"},
[412206] = {412206, 11022, 7, 5, "1_》_0_0.8", "level1", "這裡就是艾吉斯啊……好！決定了！我的下一個目標就是成為艾吉斯的TOP1。", "ここがアイギスかぁ……よし決めた！　あーしの次の目標はアイギスのトップになること！", "0", "0", "0", "0", "cv_wangnv_7", "0", "0"},
[412207] = {412207, 11022, 8, 5, "1_》_0_0.8", "level1", "差不多也該帶我去和巨大怪獸一起作戰了吧……我已經按耐不住自己心中這股想保護大家的心情了……你說我只是想玩鬧？結果沒差別就好啦~", "そろそろあーしも巨大怪獣と戦うのに連れてってよー。みんなを守りたいっていう気持ちが抑えられなくてさぁ……暴れたいだけだろって？結果オーライならいいっしょ～", "0", "0", "0", "0", "cv_wangnv_8", "0", "0"},
[412208] = {412208, 11022, 9, 5, "1_》_100_1.5", "level2", "……在沒有人的地方，你可以偷偷叫我斯卡蒂哦？是不是有種背德的感覺……嘿嘿，感覺會上癮呢。", "……誰もいないとこでなら、あーしのことこっそりスカディって呼んでいいよ？　へへ……なんかイケないことしてるみたいでクセになるかもね。", "0", "0", "0", "0", "cv_wangnv_9", "0", "0"},
[412209] = {412209, 11022, 10, 5, "1_》_500_2", "level3", "領航……你更喜歡哪個斯卡蒂呢？是還在成長的她，還是充滿威嚴的她，還是我？", "ナビくんは……どのスカディの方が好き？　成長途中のか、威厳に満ちてるのか、それとも……あーしが好き？", "0", "0", "0", "0", "cv_wangnv_10", "0", "0"},
[412210] = {412210, 11022, 11, 5, "1_》_1000_2.5", "level4", "我說……我覺得你還是喜歡我比較好。", "知ってるよ……ナビくんはあーしのことが好きなんだってこと！", "0", "0", "0", "0", "cv_wangnv_11", "0", "0"},
[412211] = {412211, 11022, 12, 6, "0", "0", "這就是LVEVL—UP的感覺嗎。", "レベルアーップ、って感じだね。", "0", "0", "0", "0", "cv_wangnv_12", "0", "0"},
[412212] = {412212, 11022, 13, 7, "0", "0", "感覺還不賴嘛。", "まあイケてんじゃない？", "0", "0", "0", "0", "cv_wangnv_13", "0", "0"},
[412213] = {412213, 11022, 14, 8, "0", "0", "我懂了……因為有了你的幫助所以才能提升力量，從而讓我對你產生依賴和好感——所謂的特訓就是這樣的一種東西對吧？", "なるほど……ナビくんのおかげでレベルアップできる代わりに、あーしはナビくんのことが好きになっちゃう……特訓ってそういうアレなんだね？", "0", "0", "0", "0", "cv_wangnv_14", "0", "0"},
[412214] = {412214, 11022, 15, 9, "0", "0", "這就是慢慢變強的踏實感覺呢。", "コツコツ強くなってるって感じだね！", "0", "0", "0", "0", "cv_wangnv_15", "0", "0"},
[412215] = {412215, 11022, 16, 10, "0", "0", "心之鼓動，開始了。", "心臓ドキドキ、やばー♪", "0", "0", "0", "0", "cv_wangnv_16", "0", "0"},
[412216] = {412216, 11022, 17, 11, "0", "0", "小意思！就這點水準嗎！", "楽勝楽勝！　こんなん餘裕っしょ！", "0", "0", "0", "0", "cv_wangnv_17", "0", "0"},
[412217] = {412217, 11022, 18, 12, "0", "0", "哼，戰鬥的勝負就在一瞬間呢。", "ふっふーん。勝負が決まるのは一瞬なんだよ。", "0", "0", "0", "0", "cv_wangnv_18", "0", "0"},
[412218] = {412218, 11022, 19, 13, "0", "0", "我還活著啊！好危險！好危險！", "死ぬかと思った！あっぶな！マジ危なかった！", "0", "0", "0", "0", "cv_wangnv_19", "0", "0"},
[412219] = {412219, 11022, 20, 14, "0", "0", "快——跑——啊，敵人要追上來了，好可怕！", "にーげーろー！　追いかけて來てるよ、ヤバいヤバい！", "0", "0", "0", "0", "cv_wangnv_20", "0", "0"},
[412220] = {412220, 11022, 21, 15, "0", "0", "啊哈~", "へっへーん！", "0", "0", "0", "0", "cv_wangnv_21", "0", "0"},
[412221] = {412221, 11022, 23, 16, "0", "0", "必殺！", "必殺！", "0", "0", "0", "0", "cv_wangnv_23", "0", "0"},
[412222] = {412222, 11022, 24, 17, "0", "0", "超必殺！", "超必殺！", "0", "0", "0", "0", "cv_wangnv_24", "0", "0"},
[412223] = {412223, 11022, 26, 19, "0", "0", "我可還沒結束！", "あーしはまだ終わってないよ！", "0", "0", "0", "0", "cv_wangnv_26", "0", "0"},
[412224] = {412224, 11022, 27, 20, "0", "0", "這……這是……！澡堂！", "こ……これは……！お風呂！", "0", "0", "0", "0", "cv_wangnv_27", "0", "0"},
[412225] = {412225, 11022, 28, 21, "0", "0", "沒想到我的預感成為了現實，你真的跟進來要和我一起洗澡啊……", "まさかあーしの予感が的中するなんて。ほんとにあーしと一緒にお風呂入るんだ……", "0", "0", "0", "0", "cv_wangnv_28", "0", "0"},
[412226] = {412226, 11022, 29, 21, "0", "0", "你這傢伙……算了，就當是給你的福利環節了……畢竟一直借住在你的身邊。", "ナビくんってば……ま、お禮だと思えばいっか……いつもお世話になってるしねー。", "0", "0", "0", "0", "cv_wangnv_29", "0", "0"},
[412227] = {412227, 11022, 30, 22, "0", "0", "然後呢？", "それから？", "0", "0", "0", "0", "cv_wangnv_30", "0", "0"},
[412228] = {412228, 11022, 31, 23, "0", "0", "猜猜我是誰~猜錯了可是有懲罰的哦！", "あーしは誰かな～？　間違ったら罰ゲームだからね！", "0", "0", "0", "0", "cv_wangnv_31", "0", "0"},
[412229] = {412229, 11022, 32, 24, "0", "0", "好！答對了，獎勵你和我的二人世界時間，陪我再一次前往戰場吧！", "はい、良くできましたー！　ご褒美に二人きりの時間をあげるね……さ、二人で戦場に行くよー！", "0", "0", "0", "0", "cv_wangnv_32", "0", "0"},
[412230] = {412230, 11022, 33, 25, "0", "0", "好！懲罰就是等一下陪我一起再一次上戰場，接下來我和領航的二人世界時間。", "オッケー、罰としてもう一回戦場に付き合って貰うよー。ここからはあーしとナビくん、二人の時間だからね。", "0", "0", "0", "0", "cv_wangnv_33", "0", "0"},
[412231] = {412231, 11022, 34, 26, "0", "0", "你終於來了，我等得好無聊啊~等會一起去找點樂子吧？", "やっと來たー。退屈だったんだよー？　んじゃ早速、どっか遊びに行かない？", "0", "0", "0", "0", "cv_wangnv_34", "0", "0"},
[412232] = {412232, 11022, 35, 27, "0", "0", "我們兩個人偷偷加班吧？", "あーし達ふたりでこっそり殘業しない？", "0", "0", "0", "0", "cv_wangnv_35", "0", "0"},
[412233] = {412233, 11022, 36, 28, "0", "0", "不錯不錯！", "いいねいいねぇ！", "0", "0", "0", "0", "cv_wangnv_36", "0", "0"},
[412234] = {412234, 11022, 37, 29, "0", "0", "打算帶我去見見其他人？好啊，現在就走嗎？", "あーしを連れて他の人に會いに行くの？いいよ、今から行く？", "0", "0", "0", "0", "cv_wangnv_37", "0", "0"},
[412235] = {412235, 11022, 38, 30, "0", "0", "原來你的權力這麼大，竟然能隨便調度其他駕駛員過來耶。", "ナビくんって結構偉いんだねー。他のドライバーを自由に募集できるなんて。", "0", "0", "0", "0", "cv_wangnv_38", "0", "0"},
[412236] = {412236, 11022, 39, 31, "0", "0", "噗，好奇怪的裝備。", "ぷっ、変な裝備。", "0", "0", "0", "0", "cv_wangnv_39", "0", "0"},
[412237] = {412237, 11022, 40, 32, "0", "0", "我請客好了。", "あーしが奢ったげるよ。", "0", "0", "0", "0", "cv_wangnv_40", "0", "0"},
[412238] = {412238, 11022, 41, 33, "0", "0", "這我認得，這照片是你對吧？", "あ、見覚えあるー。この寫真ってナビくんでしょ？", "0", "0", "0", "0", "cv_wangnv_41", "0", "0"},
[412239] = {412239, 11022, 42, 34, "0", "0", "改變世界的機關就在這裡。", "世界を変える仕組みはここにあるよ。", "0", "0", "0", "0", "cv_wangnv_42", "0", "0"},
[412240] = {412240, 11022, 43, 35, "0", "0", "我知道！這個是領獎勵的地方對吧？誒……錯了嗎？", "分かった！ここってボーナスが入ってる場所でしょ？え……違った？", "0", "0", "0", "0", "cv_wangnv_43", "0", "0"},
[412241] = {412241, 11022, 44, 36, "0", "0", "聊天欄啊……可要小心那些居心不軌的人哦。", "チャットかぁ……荒らしには気を付けてよね。", "0", "0", "0", "0", "cv_wangnv_44", "0", "0"},
[412242] = {412242, 11022, 45, 37, "0", "0", "盯——", "じぃ～", "0", "0", "0", "0", "cv_wangnv_45", "0", "0"},
[412300] = {412300, 11023, 1, 1, "0", "0", "蒼霧殘響", "ハツリバーブ。", "0", "0", "0", "0", "cv_xiaomeng_1", "0", "0"},
[412301] = {412301, 11023, 2, 2, "0", "0", "這就是閣下經常呆的地方嗎。嗯……嗯！那現在這裏就是曉夢要守護的地方了。", "ここが殿がよくいる場所か……うん……うん！では、今からここが暁夢（ぎょうむ）の守備範囲だな！", "0", "0", "0", "0", "cv_xiaomeng_2", "0", "0"},
[412302] = {412302, 11023, 3, 3, "0", "0", "閣下，聽到你的呼喚，曉夢馬上就來幫忙了。這次又要給予曉夢什麼樣的試煉呢？", "殿の呼びかけに応じ、暁夢、ここに參上！さあ、今回はどのような試練が待っているんだ？", "0", "0", "0", "0", "cv_xiaomeng_3", "0", "0"},
[412303] = {412303, 11023, 4, 4, "0", "idle", "出拳的意義？不知道，也沒想過，先生教曉夢拳法，曉夢便習武，練了便是練了。曉夢為何出拳，怎麼出拳，這些都是閣下需要思考的問題吧？拳出拳止，這才是曉夢的意義。", "この拳の意味？分からん、考えたこともない。師匠が拳法を教え、暁夢はそれを修める。それだけのことだ。暁夢が何のためにどうやって拳を出すのか。それは殿に任せる。殿が思うところに我が拳あり！それが暁夢の生き様だ！", "0", "0", "0", "0", "cv_xiaomeng_4", "0", "0"},
[412304] = {412304, 11023, 5, 4, "0", "idle", "澄練說閣下可以教導曉夢修行，要聽閣下的話。那麼從現在開始，曉夢便聽閣下的話。", "殿が修行をつけてくれると澄練（ちょうれん）から聞いたんだ。今からどんな命令にも従うぞ！", "0", "0", "0", "0", "cv_xiaomeng_5", "0", "0"},
[412305] = {412305, 11023, 6, 4, "0", "idle", "大而無當——母親在說完這句後，曉夢就被趕了出來。閣下知道母親說的話……是什麼意思嗎？", "その拳に乗せるものを探しなさい……母上はそう言って、暁夢を追い出したんだ。殿。この意味が分かるか？", "0", "0", "0", "0", "cv_xiaomeng_6", "0", "0"},
[412306] = {412306, 11023, 7, 5, "1_》_0_0.8", "level1", "閣……閣下！這是在做什麼？", "と、殿？何をしているんだ？", "0", "0", "0", "0", "cv_xiaomeng_7", "0", "0"},
[412307] = {412307, 11023, 8, 5, "1_》_0_0.8", "level1", "最開始練拳的時候當然很痛啊，但是痛過之後，現在曉夢的拳頭已經不會痛了。閣下想要看看曉夢的手嗎？", "拳法を始めた時は痛かった拳が、今はもう痛むことはない。暁夢の手を見てみるか？", "0", "0", "0", "0", "cv_xiaomeng_8", "0", "0"},
[412308] = {412308, 11023, 9, 5, "1_》_100_1.5", "level2", "領航對曉夢下命令吧，曉夢想要聽閣下的話！曉夢想……待在閣下身邊……", "殿。暁夢に命令をくれ。暁夢は殿の言うことを聞きたい。暁夢は……殿の傍にいたい……", "0", "0", "0", "0", "cv_xiaomeng_9", "0", "0"},
[412309] = {412309, 11023, 10, 5, "1_》_500_2", "level3", "閣下，曉夢好像明白一點了……想靜下心來思考再給閣下答案……原來是這樣啊……", "殿。暁夢は少し分かってきた気がする……でも、もっと落ち著いて考えてから、話そうと思う。だから今はここまでだ。", "0", "0", "0", "0", "cv_xiaomeng_10", "0", "0"},
[412310] = {412310, 11023, 11, 5, "1_》_1000_2.5", "level4", "……思考是很重要的……對錯也是很重要的！平心社的大家是很重要的……閣下也是很重要的……！對不起……閣下……曉夢現在只能想到這些…………今後再和領航一起想吧。", "考えることは大切だけど……決めることも大切だな！で、暁夢は平心社のみんなが大切で……でも！殿も大切な存在で……うーん……申し訳ない。いまの暁夢は、これぐらいしか分からない。……だからこれから一緒に考えてくれ！", "0", "0", "0", "0", "cv_xiaomeng_11", "0", "0"},
[412311] = {412311, 11023, 12, 6, "0", "0", "原來如此，還有這種練習方式。", "このような修行があるとは！", "0", "0", "0", "0", "cv_xiaomeng_12", "0", "0"},
[412312] = {412312, 11023, 13, 7, "0", "0", "這樣做的目的是什麼。", "もっと體を鍛えるぞ！", "0", "0", "0", "0", "cv_xiaomeng_13", "0", "0"},
[412313] = {412313, 11023, 14, 8, "0", "0", "該練練脊骨了……", "うおぉー！こんなにスッキリしたのは久しぶりだ！どうだ！暁夢は殿の望む姿になれたか？", "0", "0", "0", "0", "cv_xiaomeng_14", "0", "0"},
[412314] = {412314, 11023, 15, 9, "0", "0", "無過不及，隨曲就伸！", "過ぎること及ばざることなく、曲に隨（したが）い伸（しん）に就（つ）く！", "0", "0", "0", "0", "cv_xiaomeng_15", "0", "0"},
[412315] = {412315, 11023, 16, 10, "0", "0", "九州平心社，“武夫”曉夢，請指教。", "九州平心社（きゅうしゅうへいしんしゃ）の武者、暁夢。參る！", "0", "0", "0", "0", "cv_xiaomeng_16", "0", "0"},
[412316] = {412316, 11023, 17, 11, "0", "0", "簡單，順利完成了！", "押忍、一件落著！", "0", "0", "0", "0", "cv_xiaomeng_17", "0", "0"},
[412317] = {412317, 11023, 18, 12, "0", "0", "積累了經驗，再來一次吧！", "経験は積んだ、もう一度！", "0", "0", "0", "0", "cv_xiaomeng_18", "0", "0"},
[412318] = {412318, 11023, 19, 13, "0", "0", "棋差半步啊。", "一手足りないか……！", "0", "0", "0", "0", "cv_xiaomeng_19", "0", "0"},
[412319] = {412319, 11023, 20, 14, "0", "0", "勝敗乃常事，曉夢陪閣下重新來過吧。", "勝敗は兵家の常だ。殿が命じてくれるのなら暁夢が再び挑んでやる！", "0", "0", "0", "0", "cv_xiaomeng_20", "0", "0"},
[412320] = {412320, 11023, 21, 15, "0", "0", "殺了便是殺了。", "倒す。それだけだ。", "0", "0", "0", "0", "cv_xiaomeng_21", "0", "0"},
[412321] = {412321, 11023, 23, 16, "0", "0", "中！", "いちっ！", "0", "0", "0", "0", "cv_xiaomeng_22", "0", "0"},
[412322] = {412322, 11023, 24, 17, "0", "0", "再中！", "にっ！", "0", "0", "0", "0", "cv_xiaomeng_23", "0", "0"},
[412323] = {412323, 11023, 25, 18, "0", "0", "虛領頂勁。哈——！", "虛領頂勁。はぁーー！", "0", "0", "0", "0", "cv_xiaomeng_24", "0", "0"},
[412324] = {412324, 11023, 26, 19, "0", "0", "曉夢……腐朽了啊。", "暁夢は……錆びてしまったのか……", "0", "0", "0", "0", "cv_xiaomeng_25", "0", "0"},
[412325] = {412325, 11023, 27, 20, "0", "0", "久候多時了，今天是要……那個吧……以前媽媽經常做的……藥浴……", "待っていたぞ。今日は…あの…昔、母上がよくやっていた薬湯をするんだな？", "0", "0", "0", "0", "cv_xiaomeng_26", "0", "0"},
[412326] = {412326, 11023, 28, 21, "0", "0", "閣下……不向曉夢下要求嗎……曉夢會聽閣下的話哦。", "殿……暁夢に命令はないか？……ちゃんと従うぞ。", "0", "0", "0", "0", "cv_xiaomeng_27", "0", "0"},
[412327] = {412327, 11023, 29, 21, "0", "0", "乖乖這樣就可以了嗎，只是一個姿勢的話，有些地方會洗不乾淨哦……", "これでいいのか？同じ體勢だけだと、すみずみまできれいに洗えないだろ……？", "0", "0", "0", "0", "cv_xiaomeng_28", "0", "0"},
[412328] = {412328, 11023, 30, 22, "0", "0", "要開始了嗎……", "やってみるか？", "0", "0", "0", "0", "cv_xiaomeng_29", "0", "0"},
[412329] = {412329, 11023, 31, 23, "0", "0", "曉夢相信閣下。", "暁夢は殿を信じるぞ。", "0", "0", "0", "0", "cv_xiaomeng_30", "0", "0"},
[412330] = {412330, 11023, 32, 24, "0", "0", "分清楚是和非、正確和錯誤。閣下就是教會曉夢這個道理的人。", "善と悪、正解と不正解を見極める。殿がこの道理を教えてくれたんだ！", "0", "0", "0", "0", "cv_xiaomeng_31", "0", "0"},
[412331] = {412331, 11023, 33, 25, "0", "0", "閣下！", "殿！", "0", "0", "0", "0", "cv_xiaomeng_32", "0", "0"},
[412332] = {412332, 11023, 34, 26, "0", "0", "歡迎回來，曉夢有聽閣下的話好好看家哦！", "おかえり、殿！暁夢はちゃんと言いつけ通り留守番をしてたぞ！", "0", "0", "0", "0", "cv_xiaomeng_33", "0", "0"},
[412333] = {412333, 11023, 35, 27, "0", "0", "下達命令吧，閣下。", "命令をくれ！殿！", "0", "0", "0", "0", "cv_xiaomeng_34", "0", "0"},
[412334] = {412334, 11023, 36, 28, "0", "0", "準備踏青了嗎。", "ピクニックにでも行くのか？", "0", "0", "0", "0", "cv_xiaomeng_35", "0", "0"},
[412335] = {412335, 11023, 37, 29, "0", "0", "好強的氣息……", "強者の気配がするぞ……", "0", "0", "0", "0", "cv_xiaomeng_36", "0", "0"},
[412336] = {412336, 11023, 38, 30, "0", "0", "……", "……色々な気配があるな。", "0", "0", "0", "0", "cv_xiaomeng_37", "0", "0"},
[412337] = {412337, 11023, 39, 31, "0", "0", "身外之物罷了。", "大事なのは己の肉體だ！", "0", "0", "0", "0", "cv_xiaomeng_38", "0", "0"},
[412338] = {412338, 11023, 40, 32, "0", "0", "銀貨兩訖。", "貸し借りなし。だろ？", "0", "0", "0", "0", "cv_xiaomeng_39", "0", "0"},
[412339] = {412339, 11023, 41, 33, "0", "0", "哦哦，曉夢也有類似的檔案！", "おぉ。暁夢にもこんなプロフィールがあるぞ。", "0", "0", "0", "0", "cv_xiaomeng_40", "0", "0"},
[412340] = {412340, 11023, 42, 34, "0", "0", "設定好了嗎。", "設定できたか？", "0", "0", "0", "0", "cv_xiaomeng_41", "0", "0"},
[412341] = {412341, 11023, 43, 35, "0", "0", "書信來去。", "手紙は行ったり來たりするものだよな。", "0", "0", "0", "0", "cv_xiaomeng_42", "0", "0"},
[412342] = {412342, 11023, 44, 36, "0", "0", "聒噪，曉夢只想聽閣下的聲音。", "うるさいな。暁夢は殿の聲だけが聞きたいのだ。", "0", "0", "0", "0", "cv_xiaomeng_43", "0", "0"},
[412343] = {412343, 11023, 45, 37, "0", "0", "哦哦！", "おおぉ！", "0", "0", "0", "0", "cv_xiaomeng_44", "0", "0"},
[412400] = {412400, 11024, 1, 1, "0", "0", "蒼霧殘響", "0", "0", "0", "0", "0", "cv_yanyanluo_1", "0", "0"},
[412401] = {412401, 11024, 2, 2, "0", "0", "做這種乏味的工作……我也許會精神渙散而不小心踩到建築哦。", "0", "0", "0", "0", "0", "cv_yanyanluo_2", "0", "0"},
[412402] = {412402, 11024, 3, 3, "0", "0", "“鯨落”的秘密武器——妍妍蘿參上。在領航身上能尋找到什麼樂趣，就讓我期待一番吧。", "0", "0", "0", "0", "0", "cv_yanyanluo_3", "0", "0"},
[412403] = {412403, 11024, 4, 4, "0", "idle", "今天的風吹個不停，頭髮好像變得有些乾燥，要不要呼叫一場人工降雨呢？", "0", "0", "0", "0", "0", "cv_yanyanluo_4", "0", "0"},
[412404] = {412404, 11024, 5, 4, "0", "idle", "這副身姿能讓我在海底潛得更深，或是在地上望得更遠。像這樣矗立著，同時觀察好幾片街區的景象倒也挺有意思。", "0", "0", "0", "0", "0", "cv_yanyanluo_5", "0", "0"},
[412405] = {412405, 11024, 6, 4, "0", "idle", "伽藍見又打算在圖書館裏泡一整天吧，該為今晚如何捉弄她想個新點子了。", "0", "0", "0", "0", "0", "cv_yanyanluo_6", "0", "0"},
[412406] = {412406, 11024, 7, 5, "1_》_0_0.8", "level1", "謔~這麼做，是在期待著什麼反應呢？", "0", "0", "0", "0", "0", "cv_yanyanluo_7", "0", "0"},
[412407] = {412407, 11024, 8, 5, "1_》_0_0.8", "level1", "這種地方可沒有按鈕，再怎麼按也不會發射魚雷的。", "0", "0", "0", "0", "0", "cv_yanyanluo_8", "0", "0"},
[412408] = {412408, 11024, 9, 5, "1_》_100_1.5", "level2", "姑且提醒一句，潛水時就不要像這樣亂摸亂碰了，海底的有毒物種很多呢。", "0", "0", "0", "0", "0", "cv_yanyanluo_9", "0", "0"},
[412409] = {412409, 11024, 10, 5, "1_》_500_2", "level3", "據說，在南太平洋的某片海域下有座沉沒之城，等哪天有空，陪我去進行一場驚心動魄的冒險吧？", "0", "0", "0", "0", "0", "cv_yanyanluo_10", "0", "0"},
[412410] = {412410, 11024, 11, 5, "1_》_1000_2.5", "level4", "在這種時候，領航的內心到底會思考些什麼呢？唔……要不你也試試讓身體巨大化？我有些想潛入你的心裏一探究竟了。", "0", "0", "0", "0", "0", "cv_yanyanluo_11", "0", "0"},
[412411] = {412411, 11024, 12, 6, "0", "0", "好耶——", "0", "0", "0", "0", "0", "cv_yanyanluo_12", "0", "0"},
[412412] = {412412, 11024, 13, 7, "0", "0", "又變強了，可我的潛力究竟還剩多少呢？", "0", "0", "0", "0", "0", "cv_yanyanluo_13", "0", "0"},
[412413] = {412413, 11024, 14, 8, "0", "0", "深潛時，無垠的黑暗並不令我害怕，不期而遇的“邊界”才會，因為它將宣告著這趟旅途到此為止。然而每當抵達海底，我仍會被終點的景色觸動。領航，謝謝你引領我看見這種景色。", "0", "0", "0", "0", "0", "cv_yanyanluo_14", "0", "0"},
[412414] = {412414, 11024, 15, 9, "0", "0", "我迫不及待展現新的力量了。", "0", "0", "0", "0", "0", "cv_yanyanluo_15", "0", "0"},
[412415] = {412415, 11024, 16, 10, "0", "0", "由我擔任前鋒吧。", "0", "0", "0", "0", "0", "cv_yanyanluo_16", "0", "0"},
[412416] = {412416, 11024, 17, 11, "0", "0", "這就是完美的勝利嗎？", "0", "0", "0", "0", "0", "cv_yanyanluo_17", "0", "0"},
[412417] = {412417, 11024, 18, 12, "0", "0", "你會追求更加完美的結果嗎？反正我不會滿足於此哦。", "0", "0", "0", "0", "0", "cv_yanyanluo_18", "0", "0"},
[412418] = {412418, 11024, 19, 13, "0", "0", "下次再加把勁吧。", "0", "0", "0", "0", "0", "cv_yanyanluo_19", "0", "0"},
[412419] = {412419, 11024, 20, 14, "0", "0", "不甘心，我要跟敵人同歸於盡……開玩笑的。", "0", "0", "0", "0", "0", "cv_yanyanluo_20", "0", "0"},
[412420] = {412420, 11024, 21, 15, "0", "0", "沉沒吧。", "0", "0", "0", "0", "0", "cv_yanyanluo_22", "0", "0"},
[412421] = {412421, 11024, 23, 16, "0", "0", "餘裕餘裕。", "0", "0", "0", "0", "0", "cv_yanyanluo_21", "0", "0"},
[412422] = {412422, 11024, 24, 17, "0", "0", "我先回家了。", "0", "0", "0", "0", "0", "cv_yanyanluo_24", "0", "0"},
[412423] = {412423, 11024, 26, 19, "0", "0", "永別了。", "0", "0", "0", "0", "0", "cv_yanyanluo_23", "0", "0"},
[412424] = {412424, 11024, 27, 20, "0", "0", "這裏的池子好淺，只能陸遊了。", "0", "0", "0", "0", "0", "cv_yanyanluo_25", "0", "0"},
[412425] = {412425, 11024, 28, 21, "0", "0", "雲蒸霧繞的程度都能讓人體驗桑拿了，我們來比比誰能撐更久吧。", "0", "0", "0", "0", "0", "cv_yanyanluo_26", "0", "0"},
[412426] = {412426, 11024, 29, 21, "0", "0", "這種時候要是蒼霧侵入浴室就有意思了。", "0", "0", "0", "0", "0", "cv_yanyanluo_27", "0", "0"},
[412427] = {412427, 11024, 30, 22, "0", "0", "快點快點。", "0", "0", "0", "0", "0", "cv_yanyanluo_28", "0", "0"},
[412428] = {412428, 11024, 31, 23, "0", "0", "聰明如你不會猜錯的吧？", "0", "0", "0", "0", "0", "cv_yanyanluo_29", "0", "0"},
[412429] = {412429, 11024, 32, 24, "0", "0", "這就是你心中的答案啊，我瞭解了。", "0", "0", "0", "0", "0", "cv_yanyanluo_30", "0", "0"},
[412430] = {412430, 11024, 33, 25, "0", "0", "比起唯一的答案，更多可能性倒也不錯。", "0", "0", "0", "0", "0", "cv_yanyanluo_31", "0", "0"},
[412431] = {412431, 11024, 34, 26, "0", "0", "回來了啊，快開始工作吧，我想早點下班。", "0", "0", "0", "0", "0", "cv_yanyanluo_32", "0", "0"},
[412432] = {412432, 11024, 35, 27, "0", "0", "鳴響命運的汽笛吧。", "0", "0", "0", "0", "0", "cv_yanyanluo_33", "0", "0"},
[412433] = {412433, 11024, 36, 28, "0", "0", "我已經做好連戰連勝的準備了哦。", "0", "0", "0", "0", "0", "cv_yanyanluo_34", "0", "0"},
[412434] = {412434, 11024, 37, 29, "0", "0", "看看大家都在做什麼。", "0", "0", "0", "0", "0", "cv_yanyanluo_35", "0", "0"},
[412435] = {412435, 11024, 38, 30, "0", "0", "又會尋得什麼新樂子呢？", "0", "0", "0", "0", "0", "cv_yanyanluo_36", "0", "0"},
[412436] = {412436, 11024, 39, 31, "0", "0", "還是在海底神殿找到的寶藏更適合我。", "0", "0", "0", "0", "0", "cv_yanyanluo_37", "0", "0"},
[412437] = {412437, 11024, 40, 32, "0", "0", "人的欲望比海還深呢。", "0", "0", "0", "0", "0", "cv_yanyanluo_38", "0", "0"},
[412438] = {412438, 11024, 41, 33, "0", "0", "看看你的。", "0", "0", "0", "0", "0", "cv_yanyanluo_39", "0", "0"},
[412439] = {412439, 11024, 42, 34, "0", "0", "萬物中樞系統——啟動。", "0", "0", "0", "0", "0", "cv_yanyanluo_40", "0", "0"},
[412440] = {412440, 11024, 43, 35, "0", "0", "會收到網路漂流瓶嗎？", "0", "0", "0", "0", "0", "cv_yanyanluo_41", "0", "0"},
[412441] = {412441, 11024, 44, 36, "0", "0", "弱者才社交。", "0", "0", "0", "0", "0", "cv_yanyanluo_42", "0", "0"},
[412442] = {412442, 11024, 45, 37, "0", "0", "怎麼還有事啊……", "0", "0", "0", "0", "0", "cv_yanyanluo_43", "0", "0"},
[412700] = {412700, 11027, 1, 1, "0", "0", "蒼霧殘響", "ハツリバーブ", "0", "0", "0", "0", "cv_qishi_1", "0", "0"},
[412701] = {412701, 11027, 2, 2, "0", "0", "既然是你選的，那可不要嫌棄我的話太多了。", "あなたが選んだのだから、私がおしゃべりだとは思わないでね。", "0", "0", "0", "0", "cv_qishi_2", "0", "0"},
[412702] = {412702, 11027, 3, 3, "0", "0", "我還以為你不想再見到我了，果然是我的魅力太大了嗎？也好，我會在接下來的相處中，讓你充分感受到我那致命的誘惑力的，領航小弟。", "もう会いたくないのかと思ったわ。やっぱり私の魅力が強すぎるのかしら？まあいいわ、これからの付き合いで、私の魅力的な誘惑を存分に味わせてあげるわね、ナビゲーターくん。", "0", "0", "0", "0", "cv_qishi_3", "0", "0"},
[412703] = {412703, 11027, 4, 4, "0", "idle", "喜歡甜食的人和喜歡鹹食的人在本質上沒有區別。這句話放在我身上也是一樣的，崇尚希望與美好的人，跟我這類拿別人的不幸當下酒菜的人是同類。", "甘いものが好きな人と塩辛いものが好きな人は本質的に変わらないわ。それは私にも言えることよ。希望や美しさを尊ぶ人も、他人の不幸を酒の肴にする私みたいな人も、結局同じなの。", "0", "0", "0", "0", "cv_qishi_4", "0", "0"},
[412704] = {412704, 11027, 5, 4, "0", "idle", "不要對自己的能力有不切實際的期待，不要擅自幻想自己的人生會有夢幻般的展開，凡事往最糟糕的情況去設想，這就是我們這種人唯一能抓住幸福人生的方法。", "自分の能力に過度な期待をしないで。人生が夢のように展開するなんて幻想を抱かないで。全てを最悪の状況で考えること、それが私たちのような人間が幸せをつかむ唯一の方法よ。", "0", "0", "0", "0", "cv_qishi_5", "0", "0"},
[412705] = {412705, 11027, 6, 4, "0", "idle", "言語的力量是有限的，就算我再怎麼花言巧語，也不可能敵得過極致的暴力。那個凡事只想著用剪刀來解決問題的暴力小鬼，可謂是我的“天敵”啊。", "言葉の力は限られているの。どんなに私が巧みに話しても、極度の暴力には勝てないわ。何でもハサミで解決しようとするあの暴力おちびちゃん、彼女はまさに私の「天敵」ね。", "0", "0", "0", "0", "cv_qishi_6", "0", "0"},
[412706] = {412706, 11027, 7, 5, "1_》_0_0.8", "level1", "就當做是我的詭辯吧——領航小弟，這世界上有助人為樂的人，那理所當然也該有我這種盼著別人墜下深淵的人，人們應該尊重我這一惡劣的興趣。", "これを私の詭弁だと思ってもいいわ——ナビゲーターくん。この世には助けを求める人がいる一方で、当然のことながら、他人が奈落の底に落ちるのを楽しみにしている私のような人間もいるの。私の悪趣味は尊重されるべきよ。", "0", "0", "0", "0", "cv_qishi_7", "0", "0"},
[412707] = {412707, 11027, 8, 5, "1_》_0_0.8", "level1", "我從來不會害人，我的所作所為只不過是推動人做出選擇而已——即便選擇了錯誤的那一邊，也是他們憑著自己的意志做出的選擇。", "私は決して人を害することはないわ。私のすることはただ、人を選択へと促すだけ——たとえそれが間違った選択であっても、それは彼らが自分の意志で決めたことよ。", "0", "0", "0", "0", "cv_qishi_8", "0", "0"},
[412708] = {412708, 11027, 9, 5, "1_》_100_1.5", "level2", "當人站在迷茫的十字路口時，即使是細如微風一般的言語，也會讓他停滯的身體向某處傾斜。領航小弟，你可要提防那些教導你什麼是“正確”的人呀。", "人が迷いの十字路に立たされるとき、そよ風のような言葉でもその体をどこかに傾かせる力になるの。ナビゲーターくん、「正しい」ことを教えようとする人には注意しなさいね。", "0", "0", "0", "0", "cv_qishi_9", "0", "0"},
[412709] = {412709, 11027, 10, 5, "1_》_500_2", "level3", "領航小弟，我是教唆犯，不是詐騙師，謊言是我瞧不上的卑劣手段，我的言語都是真心實意，比方說這一句——領航小弟，你的氣味在教唆我對你犯罪哦~", "ナビゲーターくん、私は教唆犯であって、詐欺師ではないわ。嘘なんて卑劣な手段は使わない。私の言葉はすべて本心よ。例えば——あなたの香りが私を犯罪に駆り立てるのよ、ナビゲーターくん。", "0", "0", "0", "0", "cv_qishi_10", "0", "0"},
[412710] = {412710, 11027, 11, 5, "1_》_1000_2.5", "level4", "我不會，也不值得被救贖，我的一生都是在犯罪，也是在贖罪，不管過去多久，我都不會改變。現在，領航小弟已經瞭解我是個怎樣的人了……你願意當我一輩子的共犯嗎？", "私は救われることも、救われる価値もないわ。私の一生は犯罪と贖罪の連続よ。どんなに時間が経っても、私は変わらない。さあ、ナビゲーターくんは私がどんな人間か分かったでしょう……あなた、一生私の共犯者になってくれる？", "0", "0", "0", "0", "cv_qishi_11", "0", "0"},
[412711] = {412711, 11027, 12, 6, "0", "0", "即使投資我，也未必能得到什麼好處呀。", "私に投資しても、何の利益も得られないかもしれないわよ。", "0", "0", "0", "0", "cv_qishi_12", "0", "0"},
[412712] = {412712, 11027, 13, 7, "0", "0", "這算是獲得褒獎了嗎？", "これが褒められたってことかしら？", "0", "0", "0", "0", "cv_qishi_13", "0", "0"},
[412713] = {412713, 11027, 14, 8, "0", "0", "要是能像領航小弟一樣知道別人腦子裡在想些什麼就好了~", "ナビゲーターくんのように他人の考えが分かるようになれたらいいのにね。", "0", "0", "0", "0", "cv_qishi_14", "0", "0"},
[412714] = {412714, 11027, 15, 9, "0", "0", "感覺沒什麼提升呢。", "特に進歩は感じられないわ。", "0", "0", "0", "0", "cv_qishi_15", "0", "0"},
[412715] = {412715, 11027, 16, 10, "0", "0", "人家比較想待在領航小弟身邊呀~", "私はナビゲーターくんのそばにいたいだけよ。", "0", "0", "0", "0", "cv_qishi_16", "0", "0"},
[412716] = {412716, 11027, 17, 11, "0", "0", "我是在該認真的時候會認真的人~", "私も真剣になる時は真剣になるの。", "0", "0", "0", "0", "cv_qishi_17", "0", "0"},
[412717] = {412717, 11027, 18, 12, "0", "0", "能做到這份上已經值得領航小弟誇獎了。", "ここまでやれたんだから、ナビゲーターくんに褒めてもらってもいいわよね。", "0", "0", "0", "0", "cv_qishi_18", "0", "0"},
[412718] = {412718, 11027, 19, 13, "0", "0", "再慘烈的勝利也強過一無所獲的失敗。", "どんなに惨めな勝利でも、何も得られない敗北よりはましよ。", "0", "0", "0", "0", "cv_qishi_19", "0", "0"},
[412719] = {412719, 11027, 20, 14, "0", "0", "人家盡力了啦。", "私は全力を尽くしたわ。", "0", "0", "0", "0", "cv_qishi_20", "0", "0"},
[412720] = {412720, 11027, 21, 15, "0", "0", "漂亮的全壘打。", "素晴らしいホームランね。", "0", "0", "0", "0", "cv_qishi_21", "0", "0"},
[412721] = {412721, 11027, 23, 16, "0", "0", "哢嚓！", "カチン！", "0", "0", "0", "0", "cv_qishi_22", "0", "0"},
[412722] = {412722, 11027, 24, 17, "0", "0", "會很痛噢？", "痛いかもよ？", "0", "0", "0", "0", "cv_qishi_23", "0", "0"},
[412723] = {412723, 11027, 25, 18, "0", "0", "快點放棄吧，快點絕望吧，讓我好好欣賞你們破滅時的表情吧。", "早く諦めて、絶望して、あなたたちの破滅する表情をじっくり楽しませてね。", "0", "0", "0", "0", "cv_qishi_25", "0", "0"},
[412724] = {412724, 11027, 26, 19, "0", "0", "遭報應了啊……", "報いが来たわね……", "0", "0", "0", "0", "cv_qishi_26", "0", "0"},
[412725] = {412725, 11027, 27, 20, "0", "0", "嗯哼？原來領航小弟也是有自己欲望的人啊，我說的對嗎？", "んふ？ナビゲーターくんにも欲望があるのね、私の言った通りでしょう？", "0", "0", "0", "0", "cv_qishi_27", "0", "0"},
[412726] = {412726, 11027, 28, 21, "0", "0", "既然都做到這一步了，就不要移開視線，欺騙自己的內心了，領航小弟。", "ここまで来たのだから、視線をそらさないで、自分の心に嘘つかないでね、ナビゲーターくん。", "0", "0", "0", "0", "cv_qishi_28", "0", "0"},
[412727] = {412727, 11027, 29, 21, "0", "0", "就當是被我欺騙慫恿吧，做你想做的事情吧，領航小弟。", "私に騙されて、そそのかされたと思って、やりたいことをやりなさい、ナビゲーターくん。", "0", "0", "0", "0", "cv_qishi_29", "0", "0"},
[412728] = {412728, 11027, 30, 22, "0", "0", "有什麼好事嗎？", "何かいいことでもあった？", "0", "0", "0", "0", "cv_qishi_30", "0", "0"},
[412729] = {412729, 11027, 31, 23, "0", "0", "檢驗一下我是不是個令你印象深刻的女人吧。", "私が印象に残る女かどうか、確かめてみて。", "0", "0", "0", "0", "cv_qishi_31", "0", "0"},
[412730] = {412730, 11027, 32, 24, "0", "0", "原來如此，領航小弟已經迷上我了吧？", "なるほど、ナビゲーターくんはもう私に夢中なのね？", "0", "0", "0", "0", "cv_qishi_32", "0", "0"},
[412731] = {412731, 11027, 33, 25, "0", "0", "看來我對領航小弟只是個“不過如此”的女人呀。", "どうやら私はナビゲーターくんにとって「それほどでもない」女みたいね。", "0", "0", "0", "0", "cv_qishi_33", "0", "0"},
[412732] = {412732, 11027, 34, 26, "0", "0", "讓我們找找今天的受害者吧~", "さあ、今日の犠牲者を見つけましょうか～", "0", "0", "0", "0", "cv_qishi_34", "0", "0"},
[412733] = {412733, 11027, 35, 27, "0", "0", "讓我去做這種事……你和我是同類啊。", "こんなことを私にやらせるなんて……あなたも私と同類ね。", "0", "0", "0", "0", "cv_qishi_35", "0", "0"},
[412734] = {412734, 11027, 36, 28, "0", "0", "大家一起愉快地自相殘殺吧~", "みんなで楽しく殺し合いましょう～", "0", "0", "0", "0", "cv_qishi_36", "0", "0"},
[412735] = {412735, 11027, 37, 29, "0", "0", "一盤散沙和精兵強將，你們是哪類呢？", "結束するか、それともしないかしら？", "0", "0", "0", "0", "cv_qishi_37", "0", "0"},
[412736] = {412736, 11027, 38, 30, "0", "0", "祈禱不要再遇上我這樣的人吧。", "私のような人間に二度と会わないように祈りなさい。", "0", "0", "0", "0", "cv_qishi_38", "0", "0"},
[412737] = {412737, 11027, 39, 31, "0", "0", "凡事都有要支付代價，連拯救世界的裝備也不例外。", "すべてには代償が必要よ、世界を救う装備だって例外じゃないわ。", "0", "0", "0", "0", "cv_qishi_39", "0", "0"},
[412738] = {412738, 11027, 40, 32, "0", "0", "有錢的話，什麼都可以買到嗎？", "お金さえあれば、何でも買えると思うの？", "0", "0", "0", "0", "cv_qishi_40", "0", "0"},
[412739] = {412739, 11027, 41, 33, "0", "0", "看起來是很好騙的那類人呢。", "騙しやすそうな人に見えるわね。", "0", "0", "0", "0", "cv_qishi_41", "0", "0"},
[412740] = {412740, 11027, 42, 34, "0", "0", "記得開聲音~", "音をオンにするのを忘れないでね。", "0", "0", "0", "0", "cv_qishi_42", "0", "0"},
[412741] = {412741, 11027, 43, 35, "0", "0", "會不會有詐騙郵件呢？", "詐欺メールが届いてないかしら？", "0", "0", "0", "0", "cv_qishi_43", "0", "0"},
[412742] = {412742, 11027, 44, 36, "0", "0", "別被花言巧語騙了。", "甘い言葉に騙されないでね。", "0", "0", "0", "0", "cv_qishi_44", "0", "0"},
[412743] = {412743, 11027, 45, 37, "0", "0", "嗯哼？", "んふ？", "0", "0", "0", "0", "cv_qishi_45", "0", "0"},
[412800] = {412800, 11028, 1, 1, "0", "0", "蒼霧殘響", "蒼霧殘響（ハツリバーブ）。", "0", "0", "0", "0", "cv_geiro_1", "0", "0"},
[412801] = {412801, 11028, 2, 2, "0", "0", "瞭解。", "瞭解。", "0", "0", "0", "0", "cv_geiro_2", "0", "0"},
[412802] = {412802, 11028, 3, 3, "0", "0", "初次見面…嗯？你…啊…失禮了，我是潔蘿，是瓦爾基里的一員…同時也是卡佳最強的駕駛員。嗯，我有說出這句話的自信。", "はじめまして…うん？あなたは…あっ、失禮。私はワルキューレが一人、ジェロよ。そしてカティア最強のドライバー。えぇ、その自信があるわ。", "0", "0", "0", "0", "cv_geiro_3", "0", "0"},
[412803] = {412803, 11028, 4, 4, "0", "idle", "領航…你並不是人類吧？至少，你血管裏流淌著的血液中，有一部分不屬於人類。為什麼會知道你的秘密？…我也不知道，或許只是直覺而已吧。", "ナビゲーター、あなた人間じゃ…ないわよね。少なくとも、人間じゃない血が混ざってる。どうして知ってるのかって？…私も分からないわ、ただそう感じただけよ。", "0", "0", "0", "0", "cv_geiro_4", "0", "0"},
[412804] = {412804, 11028, 5, 4, "0", "idle", "誒——你…比我想像中還要悠閒呢。看到你這份遊刃有餘的態度，真不舒服。", "ん～、あなた…想像してたよりものんびりしてるのね。その餘裕のある態度、なんかムカつくわ。", "0", "0", "0", "0", "cv_geiro_5", "0", "0"},
[412805] = {412805, 11028, 6, 4, "0", "idle", "“生命只有一次，每個人都有義務在死亡到來前想好怎麼揮霍它。想要成為怎樣的人，由你自己決定。”這是那位醫生對我說過的話，我希望領航你也能好好思考它的含義。", "「人生は一回限り、死が訪れる前に自分の人生をどうやって費やすのを考えなければならない。どんな人になるのか、決めるのは己自身だ。」これはあの醫師に言われたこと。ナビゲーターにもその意味をちゃんと考えて欲しいの。", "0", "0", "0", "0", "cv_geiro_6", "0", "0"},
[412806] = {412806, 11028, 7, 5, "1_》_0_0.8", "level1", "動亂的世界想要恢復和平，就必須剷除所有的原罪。為了讓那一天儘早到來，我會一直戰鬥下去，為了我自己，為了人類。", "平和を取り戻すには、全ての原罪を駆除しなくちゃならない。そんな日が一日も早く來るよう、私は戦い続ける。私自身のためにも、人類のためにも。", "0", "0", "0", "0", "cv_geiro_7", "0", "0"},
[412807] = {412807, 11028, 8, 5, "1_》_0_0.8", "level1", "請不要隨便觸碰我…這是為了你的安全著想才說的忠告。", "気安く觸らないで…これはあなたための忠告よ。", "0", "0", "0", "0", "cv_geiro_8", "0", "0"},
[412808] = {412808, 11028, 9, 5, "1_》_100_1.5", "level2", "真是的，我不是說了不要碰我嗎…我沒有在嚇你啦。我還不能很好地控制自己的力量，要是傷到你了該怎麼辦啊？", "まったく、觸らないでって言ったはずよ…脅しじゃないわ。私はまだ自分の力を完璧にコントロール出來ないの。怪我したらどうすれば？", "0", "0", "0", "0", "cv_geiro_9", "0", "0"},
[412809] = {412809, 11028, 10, 5, "1_》_500_2", "level3", "我在卡佳遊歷過一段時間，所以心裏很清楚。如果沒有艾吉斯，那些平民只會過得比現在更糟。也是這段經歷，讓我審視起自己擁有的東西，去思考自己該成為什麼樣的人。…為什麼我會和你說這些啊…真奇怪。", "カティアを旅してた私には分かるの。アイギスがなかったら、みんなは今よりも酷い生活を送っていただろうって。だから私は自分を見つめ直して、どんな人間になりたいかを考えたの。……どうしてあなたにこんなことを…変ね。", "0", "0", "0", "0", "cv_geiro_10", "0", "0"},
[412810] = {412810, 11028, 11, 5, "1_》_1000_2.5", "level4", "艾吉斯能帶領人類前往美好的未來，但我確信那個地方不會有我的位置。領航，我會守護艾吉斯的，人類的現在，而他們的未來則拜託你了。雖然你有時候挺不正經的…但我相信你，你一定能做到的。", "アイギスは人類を素晴らしい未來へ導いてくれるけど、その未來に私の居場所はないでしょうね。ナビゲーター、私はアイギスの、人類の今を守る。だけど未來はあなたに任せるわ。時々不真面目な所もあるけど…あなたなら出來ると信じてるわ。", "0", "0", "0", "0", "cv_geiro_11", "0", "0"},
[412811] = {412811, 11028, 12, 6, "0", "0", "謝謝。", "ありがとう。", "0", "0", "0", "0", "cv_geiro_12", "0", "0"},
[412812] = {412812, 11028, 13, 7, "0", "0", "我會消滅所有原罪，一隻也不會剩。", "私は必ず全ての原罪を退治する。一匹も殘らさないわ。", "0", "0", "0", "0", "cv_geiro_13", "0", "0"},
[412813] = {412813, 11028, 14, 8, "0", "0", "力量會讓人迷失自我，尤其是當這份力量強大到超越常識的時候。所以，我一直在審問著自己的心，詢問自己該如何使用這份力量。領航，請和我一起將這份力量用在正確的地方上吧，謝謝。", "力を持つと人は自分自身を見失いやすくなる、その力が強ければ強いほどね。だから、私はいつも自分の心に問うの、この力の使い方を。ナビゲーター、どうか私と共に、この力を正しく使ってね。", "0", "0", "0", "0", "cv_geiro_14", "0", "0"},
[412814] = {412814, 11028, 15, 9, "0", "0", "我需要向前輩們學習更多技能。", "先輩からもっとスキルを學ばないと。", "0", "0", "0", "0", "cv_geiro_15", "0", "0"},
[412815] = {412815, 11028, 16, 10, "0", "0", "我會將自己的力量…用在正確的地方。", "この力…正しく使うわ。", "0", "0", "0", "0", "cv_geiro_16", "0", "0"},
[412816] = {412816, 11028, 17, 11, "0", "0", "領航，我們還需要更多勝利。", "ナビゲーター、私たちにはもっと勝利が必要よ。", "0", "0", "0", "0", "cv_geiro_17", "0", "0"},
[412817] = {412817, 11028, 18, 12, "0", "0", "先確認城市的受損情況吧。", "まずは街の被害狀況を確認しましょう。", "0", "0", "0", "0", "cv_geiro_18", "0", "0"},
[412818] = {412818, 11028, 19, 13, "0", "0", "…你沒事吧？沒有受傷吧？", "…あなたは大丈夫？怪我してない？", "0", "0", "0", "0", "cv_geiro_19", "0", "0"},
[412819] = {412819, 11028, 20, 14, "0", "0", "重整旗鼓…我還能繼續戰鬥。", "陣形を立て直して…私はまだ戦える。", "0", "0", "0", "0", "cv_geiro_20", "0", "0"},
[412820] = {412820, 11028, 21, 15, "0", "0", "繼續。", "次！", "0", "0", "0", "0", "cv_geiro_22", "0", "0"},
[412821] = {412821, 11028, 23, 16, "0", "0", "去死吧。", "はあーー！", "0", "0", "0", "0", "cv_geiro_21", "0", "0"},
[412822] = {412822, 11028, 24, 17, "0", "0", "能量收集率…提高。", "エネルギー収集率…限界突破！", "0", "0", "0", "0", "cv_geiro_24", "0", "0"},
[412823] = {412823, 11028, 26, 19, "0", "0", "還不行…我不能在這裏倒下。", "まだよ…ここで倒れる訳には…", "0", "0", "0", "0", "cv_geiro_23", "0", "0"},
[412824] = {412824, 11028, 27, 20, "0", "0", "…誒？為…為、為什麼你能進來這裏啊！快出去啊！", "…え？ど…どうしてあなたがここに！早く出ていって！", "0", "0", "0", "0", "cv_geiro_25", "0", "0"},
[412825] = {412825, 11028, 28, 21, "0", "0", "我還以為你是一個正經人…你這變態！色狼！真是的，你到底要待到什麼時候啊！", "まともな奴かと思ってたのに…この変態！スケベ！いつまでここに居るのよ！", "0", "0", "0", "0", "cv_geiro_26", "0", "0"},
[412826] = {412826, 11028, 29, 21, "0", "0", "如果看到了不該看的東西，你會後悔的！", "もし見ちゃいけないものを見てたら、後悔するわよ！", "0", "0", "0", "0", "cv_geiro_27", "0", "0"},
[412827] = {412827, 11028, 30, 22, "0", "0", "…怎麼了？", "…どうしたの？", "0", "0", "0", "0", "cv_geiro_28", "0", "0"},
[412828] = {412828, 11028, 31, 23, "0", "0", "哼，原來是這種無聊的遊戲。", "ふーん、つまらない遊びね。", "0", "0", "0", "0", "cv_geiro_29", "0", "0"},
[412829] = {412829, 11028, 32, 24, "0", "0", "有時間等我誇獎的話，不如去做更加有意義的事情，你這變態。", "褒め言葉を待ってる時間があるなら、もっと有意義なことに使えば？この変態。", "0", "0", "0", "0", "cv_geiro_30", "0", "0"},
[412830] = {412830, 11028, 33, 25, "0", "0", "我一開始就沒有過期待。", "最初から期待してなかったわ。", "0", "0", "0", "0", "cv_geiro_31", "0", "0"},
[412831] = {412831, 11028, 34, 26, "0", "0", "終於來了嗎…我可沒有寂寞，只是希望你不要離開崗位太久而已。", "やっと來たわね…寂しかったわけじゃないわ、ただ持ち場から長時間離れないで欲しいだけ。", "0", "0", "0", "0", "cv_geiro_32", "0", "0"},
[412832] = {412832, 11028, 35, 27, "0", "0", "出發吧，將籠罩在世界上方的烏雲一掃而盡吧。", "出発しましょう、世界を覆う暗雲を一掃するわよ。", "0", "0", "0", "0", "cv_geiro_33", "0", "0"},
[412833] = {412833, 11028, 36, 28, "0", "0", "多餘的演習…隨你喜歡吧。", "餘計な演習だけど…好きにして。", "0", "0", "0", "0", "cv_geiro_34", "0", "0"},
[412834] = {412834, 11028, 37, 29, "0", "0", "姑且說一下，我一定是最強的那一個。", "先に言っておくけど、この中で一番強いのはおそらく私よ。", "0", "0", "0", "0", "cv_geiro_35", "0", "0"},
[412835] = {412835, 11028, 38, 30, "0", "0", "要補強隊伍嗎？", "チームを補強するの？", "0", "0", "0", "0", "cv_geiro_36", "0", "0"},
[412836] = {412836, 11028, 39, 31, "0", "0", "盡可能的武裝自己吧。", "出來る限り裝備を整えなさい。", "0", "0", "0", "0", "cv_geiro_37", "0", "0"},
[412837] = {412837, 11028, 40, 32, "0", "0", "都是些奢侈品呢。", "贅沢品ばかりね。", "0", "0", "0", "0", "cv_geiro_38", "0", "0"},
[412838] = {412838, 11028, 41, 33, "0", "0", "在炫耀勳章嗎？", "勲章を見せびらかしているの？", "0", "0", "0", "0", "cv_geiro_39", "0", "0"},
[412839] = {412839, 11028, 42, 34, "0", "0", "設置…真無聊。", "セッティングね…任せるわ。", "0", "0", "0", "0", "cv_geiro_40", "0", "0"},
[412840] = {412840, 11028, 43, 35, "0", "0", "我是不會偷看的。", "覗いたりしないわよ。", "0", "0", "0", "0", "cv_geiro_41", "0", "0"},
[412841] = {412841, 11028, 44, 36, "0", "0", "真是悠閒呢。", "本當に暇ね。", "0", "0", "0", "0", "cv_geiro_42", "0", "0"},
[412842] = {412842, 11028, 45, 37, "0", "0", "怎麼了？", "どうしたの？", "0", "0", "0", "0", "cv_geiro_43", "0", "0"},
[412900] = {412900, 11029, 1, 1, "0", "0", "蒼霧殘響", "ハツリバーブ", "0", "0", "0", "0", "cv_qianmo_1", "0", "0"},
[412901] = {412901, 11029, 2, 2, "0", "0", "就算是學生會長也不能逃避值日。", "生徒會長も例外なく、日直を擔當します。", "0", "0", "0", "0", "cv_qianmo_2", "0", "0"},
[412902] = {412902, 11029, 3, 3, "0", "0", "早安，領航先生，雛鷹小隊千陌報導，今後就麻煩您了。", "おはようございます、先生。雛鷹（ひなたか）所屬の、千陌（せんはく）です。これからよろしくお願いします。", "0", "0", "0", "0", "cv_qianmo_3", "0", "0"},
[412903] = {412903, 11029, 4, 4, "0", "idle", "給實習生裝備這麼精良的裝備合乎規定嗎？", "インターン生にこのような高性能の裝備を與えて、問題はないのでしょうか？", "0", "0", "0", "0", "cv_qianmo_4", "0", "0"},
[412904] = {412904, 11029, 5, 4, "0", "idle", "按照休息表上的時間，馬上就是休息時間了。", "スケジュールによると、もうすぐ休憩時間です。", "0", "0", "0", "0", "cv_qianmo_5", "0", "0"},
[412905] = {412905, 11029, 6, 4, "0", "idle", "其實我一直反對“雛鷹計畫”，讓沒有經驗的學生上戰場就是在揠苗助長。目前來看，學院裏有能力執行實戰任務的只有我和卡蓮。", "私は「雛鷹プロジェクト」には反対です。戦闘経験のない學生を戦場に送るなど、助長抜苗（じょちょうばつびょう）でしかありません。現時點で実戦任務を遂行できるのは、私とカリンだけです。", "0", "0", "0", "0", "cv_qianmo_6", "0", "0"},
[412906] = {412906, 11029, 7, 5, "1_》_0_0.8", "level1", "弱肉強食雖合乎自然生存之法，但並不合乎人類發展之法。所以縱使原罪比我們強上千倍百倍，我也不會低頭。", "自然界においては弱肉強食が正しいのかもしれませんが、人類が発展したのは、それだけが理由ではないはずです。だからこそ、原罪が私たちの百倍、いえ、千倍強くとも屈することはありません。", "0", "0", "0", "0", "cv_qianmo_7", "0", "0"},
[412907] = {412907, 11029, 8, 5, "1_》_0_0.8", "level1", "騷擾學生可是重大犯罪，請先生三思。", "學生への迷惑行為は重大な犯罪です。慎重に考えてください。", "0", "0", "0", "0", "cv_qianmo_8", "0", "0"},
[412908] = {412908, 11029, 9, 5, "1_》_100_1.5", "level2", "現在是工作時間……想發牢騷的話可以在工作結束後說，先生。", "仕事中です。愚癡を言いたければ、仕事が終わってからお聞きしましょう。", "0", "0", "0", "0", "cv_qianmo_9", "0", "0"},
[412909] = {412909, 11029, 10, 5, "1_》_500_2", "level3", "先生上次說到的原罪行動方式，和學校裏老師所教學的有些出入。如果在實戰中按照教材來應對，想必會敗得很慘吧。", "先生から教わった原罪の行動パターンは、學校で聞いたものとずいぶん違いますね……もし実戦で教科書通りに動いたら、あっさりと敗北してしまうかもしれません……", "0", "0", "0", "0", "cv_qianmo_10", "0", "0"},
[412910] = {412910, 11029, 11, 5, "1_》_1000_2.5", "level4", "先生的學識和見聞超過我太多。遺憾的是作為實習生，不能長久地在先生身邊學習。希望在成為真正的駕駛員之後可以繼續和先生共事。", "先生の知識と経験は想像以上でした。もっと先生の元で學びたいのですが……インターン生ですから、殘された時間は多くありません。將來、一人前のドライバーになって、先生と一緒に仕事をすることが私の目標です。", "0", "0", "0", "0", "cv_qianmo_11", "0", "0"},
[412911] = {412911, 11029, 12, 6, "0", "0", "感謝教誨。", "教えに感謝します。", "0", "0", "0", "0", "cv_qianmo_12", "0", "0"},
[412912] = {412912, 11029, 13, 7, "0", "0", "與先生閒聊真的感悟頗豐。", "先生との會話は、本當に得ることが多いです。", "0", "0", "0", "0", "cv_qianmo_13", "0", "0"},
[412913] = {412913, 11029, 14, 8, "0", "0", "按規矩這不該是實習駕駛員應該獲得的力量，難道在先生心中，我已經是正式的駕駛員了嗎？", "規定では、これはインターン生が持つべき力ではありません。先生の心の中では、私を一人前のドライバーと認めてくださったのですか？", "0", "0", "0", "0", "cv_qianmo_14", "0", "0"},
[412914] = {412914, 11029, 15, 9, "0", "0", "如此貴重的禮物，不該讓先生如此破費。", "このように貴重なもの、いただけません。", "0", "0", "0", "0", "cv_qianmo_15", "0", "0"},
[412915] = {412915, 11029, 16, 10, "0", "0", "毀壞城市者必須嚴懲。", "都市を破壊する者は、厳しく罰せられるべきです。", "0", "0", "0", "0", "cv_qianmo_16", "0", "0"},
[412916] = {412916, 11029, 17, 11, "0", "0", "只要按照指揮行動，勝利如探囊取物。", "優れた指揮で、こうも簡単に勝利できるとは。", "0", "0", "0", "0", "cv_qianmo_17", "0", "0"},
[412917] = {412917, 11029, 18, 12, "0", "0", "勉強守住了底線。", "ひとまず守り切ることができました。", "0", "0", "0", "0", "cv_qianmo_18", "0", "0"},
[412918] = {412918, 11029, 19, 13, "0", "0", "勝利……如此艱難……", "なんとか勝ちましたが……手こずりました。", "0", "0", "0", "0", "cv_qianmo_19", "0", "0"},
[412919] = {412919, 11029, 20, 14, "0", "0", "萬策盡矣……", "萬策盡きました……", "0", "0", "0", "0", "cv_qianmo_20", "0", "0"},
[412920] = {412920, 11029, 21, 15, "0", "0", "這就是破壞規矩者的下場。", "ルール違反者の末路です。", "0", "0", "0", "0", "cv_qianmo_21", "0", "0"},
[412921] = {412921, 11029, 23, 16, "0", "0", "輪到我的回合了。", "私のターンです。", "0", "0", "0", "0", "cv_qianmo_22", "0", "0"},
[412922] = {412922, 11029, 24, 17, "0", "0", "毫無章法，全是破綻。", "條理なく隙だらけです。", "0", "0", "0", "0", "cv_qianmo_23", "0", "0"},
[412923] = {412923, 11029, 26, 19, "0", "0", "還是比不上……正式的駕駛員……", "やはり……正式のドライバーには葉わないのでしょうか……", "0", "0", "0", "0", "cv_qianmo_24", "0", "0"},
[412924] = {412924, 11029, 27, 20, "0", "0", "規章上可沒提過這個地方。", "レギュレーションにこの場所はなかったようですが。", "0", "0", "0", "0", "cv_qianmo_25", "0", "0"},
[412925] = {412925, 11029, 28, 21, "0", "0", "難得可以放下學生會的事……", "生徒會長の立場を忘れることができたのは久しぶりです……", "0", "0", "0", "0", "cv_qianmo_26", "0", "0"},
[412926] = {412926, 11029, 29, 21, "0", "0", "這裏不是女生浴室嗎？先生你……", "ここは女湯ですよ、先生……", "0", "0", "0", "0", "cv_qianmo_27", "0", "0"},
[412927] = {412927, 11029, 30, 22, "0", "0", "嗯？", "おや？", "0", "0", "0", "0", "cv_qianmo_28", "0", "0"},
[412928] = {412928, 11029, 31, 23, "0", "0", "規則可沒說有這個。", "レギュレーションには書かれていませんね。", "0", "0", "0", "0", "cv_qianmo_29", "0", "0"},
[412929] = {412929, 11029, 32, 24, "0", "0", "先生果然不會讓人失望。", "先生はやはり、期待を裏切らないですね。", "0", "0", "0", "0", "cv_qianmo_30", "0", "0"},
[412930] = {412930, 11029, 33, 25, "0", "0", "沒關係，按照規定我們保持距離吧。", "大丈夫です。レギュレーション通り、互いの距離を保ちましょう。", "0", "0", "0", "0", "cv_qianmo_31", "0", "0"},
[412931] = {412931, 11029, 34, 26, "0", "0", "今天又遲到了，需要我向您彙報遲到了多久嗎，先生。", "今日も遅刻ですね。", "0", "0", "0", "0", "cv_qianmo_32", "0", "0"},
[412932] = {412932, 11029, 35, 27, "0", "0", "請按照指令部署戰場。", "指示に従い、戦場に展開します。", "0", "0", "0", "0", "cv_qianmo_33", "0", "0"},
[412933] = {412933, 11029, 36, 28, "0", "0", "我會全力以赴的。", "全力を盡くします。", "0", "0", "0", "0", "cv_qianmo_34", "0", "0"},
[412934] = {412934, 11029, 37, 29, "0", "0", "大家都很整齊地站著。", "皆さん一列で並んでいます。", "0", "0", "0", "0", "cv_qianmo_35", "0", "0"},
[412935] = {412935, 11029, 38, 30, "0", "0", "戰況吃緊了嗎？", "戦況が厳しいのでしょうか。", "0", "0", "0", "0", "cv_qianmo_36", "0", "0"},
[412936] = {412936, 11029, 39, 31, "0", "0", "新的裝備。", "新しい裝備の確保です。", "0", "0", "0", "0", "cv_qianmo_37", "0", "0"},
[412937] = {412937, 11029, 40, 32, "0", "0", "這裏的價格……太貴了。", "ここは……値が張りますね。", "0", "0", "0", "0", "cv_qianmo_38", "0", "0"},
[412938] = {412938, 11029, 41, 33, "0", "0", "這不是實習生應該看的。", "これはインターン生が見るべきものではありません。", "0", "0", "0", "0", "cv_qianmo_39", "0", "0"},
[412939] = {412939, 11029, 42, 34, "0", "0", "這超出了我的許可權。", "これは私の権限を超えています。", "0", "0", "0", "0", "cv_qianmo_40", "0", "0"},
[412940] = {412940, 11029, 43, 35, "0", "0", "這份郵件不符合格式……", "このメールはフォーマットに合致していません。", "0", "0", "0", "0", "cv_qianmo_41", "0", "0"},
[412941] = {412941, 11029, 44, 36, "0", "0", "發文的格式是……", "このメッセージの書式は……", "0", "0", "0", "0", "cv_qianmo_42", "0", "0"},
[412942] = {412942, 11029, 45, 37, "0", "0", "點。", "タップしましょう。", "0", "0", "0", "0", "cv_qianmo_43", "0", "0"},
[413000] = {413000, 11030, 1, 1, "0", "0", "蒼霧殘響", "ハツリバーブ", "0", "0", "0", "0", "cv_chenglian_1", "0", "0"},
[413001] = {413001, 11030, 2, 2, "0", "0", "由我來擔任參謀嗎……正好，我也有很多話想與領航講。", "私が參謀、ですか……わかりました。ちょうどナビゲーターさんにお聞きしたいことがたくさんあったんです。", "0", "0", "0", "0", "cv_chenglian_2", "0", "0"},
[413002] = {413002, 11030, 3, 3, "0", "0", "閣下就是那位來自多瑙的領航吧？九州平心社，澄練，在此久候多時了。可以預見，接下來我們將會共事很長一段時間，請多多指教。", "あなたがダニューブのナビゲーターさんですね？九州平心社（きゅうしゅうへいしんしゃ）の澄練（ちょうれん）といいます。お會いできるのを楽しみにしていました。長いお付き合いになると思いますが、どうぞよろしくお願いします。", "0", "0", "0", "0", "cv_chenglian_3", "0", "0"},
[413003] = {413003, 11030, 4, 4, "0", "idle", "領航需要幫忙嗎，作為照顧我們的回禮，我會在能力範圍內協助您的工作，即使是不瞭解的事情，我也會跟著領航學習的。", "平心社がお世話になったお禮として、できる限りの協力をさせてください。分からない事があっても、勉強してできるようになりますから。", "0", "0", "0", "0", "cv_chenglian_4", "0", "0"},
[413004] = {413004, 11030, 5, 4, "0", "idle", "我們需要通過領航來瞭解塵世，所以我希望領航也能稍微依靠我們一點。在戰場上也好，在生活中……也一樣……我會負責記錄領航的點點滴滴。", "平心社は塵世（じんせい）を知るために、ナビゲーターさんのお力を必要としています。ですから、ナビゲーターさんももう少し私たちを頼ってください。戦場でも、日常生活でも、些細なことまできちんと記録しますから。", "0", "0", "0", "0", "cv_chenglian_5", "0", "0"},
[413005] = {413005, 11030, 6, 4, "0", "idle", "在史書上的人類，從來沒有像現在這樣團結過，雖然難免有摩擦，但是所有人都為了更好的明天全心全意，能記錄下這段歷史，我已經死而無憾了。", "歴史上、人類がこれほど団結したことはないでしょう。多少の摩擦が生じることがあっても、みんながより良い未來を目指して全力を盡くしています。この歴史を書き記すことができれば、私はもう悔いはありません。", "0", "0", "0", "0", "cv_chenglian_6", "0", "0"},
[413006] = {413006, 11030, 7, 5, "1_》_0_0.8", "level1", "我們幻化之後的腿是不是看起來很奇怪？", "ダニューブの博物館に行って、昔の人々が作り出した遺物を見てみたいんです。……その持ち主と私の祖先が知り合いかもしれないとか、想像したら楽しくないですか？", "0", "0", "0", "0", "cv_chenglian_7", "0", "0"},
[413007] = {413007, 11030, 8, 5, "1_》_0_0.8", "level1", "嗚……領航，我們與您只是相熟共事的關係，請不要靠得太近。", "ひゃ！……ナ、ナビゲーターさんと平心社はお仕事でのお付き合いなんですから、近づきすぎちゃダメです！", "0", "0", "0", "0", "cv_chenglian_8", "0", "0"},
[413008] = {413008, 11030, 9, 5, "1_》_100_1.5", "level2", "我們正處於人類歷史中最特殊的節點，而領航您無疑是這個時代最奇怪的人之一，無論如何請活下去，讓我們見證結局您的吧。", "私たちは現在、人類史上最も重要な時代にいます。そしてナビゲーターさんは間違いなく、この時代でもっとも特別な一人です。どうかこれからも歩みを止めず、その結末を私たちに見屆けさせてください。", "0", "0", "0", "0", "cv_chenglian_9", "0", "0"},
[413009] = {413009, 11030, 10, 5, "1_》_500_2", "level3", "我總是用“我們”來替代“我”，仿佛失去了“她們”，我便失去了與人交流、面對難題、處理事情的底氣……我……很膽小吧。", "私、いつも自分のことを「平心社」って言ってしまうんです。仲間がいないと、人と話すことも問題に対処することも自信が持てなくなってしまうみたいで……弱蟲ですよね……", "0", "0", "0", "0", "cv_chenglian_10", "0", "0"},
[413010] = {413010, 11030, 11, 5, "1_》_1000_2.5", "level4", "您的心願……我已經知道了……但是……但是……我是“史官”啊……", "あなたの願い……ちゃんと受け取りました……ですが……ですが私は史官なんですよ……まだ、お返事はできません……", "0", "0", "0", "0", "cv_chenglian_11", "0", "0"},
[413011] = {413011, 11030, 12, 6, "0", "0", "來自領航的支援。我收到了。", "ナビゲーターさんのご支援、受け取りました。", "0", "0", "0", "0", "cv_chenglian_12", "0", "0"},
[413012] = {413012, 11030, 13, 7, "0", "0", "原來是這種感覺。我記錄了。", "こんな感じだったんですね。記録しないと。", "0", "0", "0", "0", "cv_chenglian_13", "0", "0"},
[413013] = {413013, 11030, 14, 8, "0", "0", "新的知識。我明白了。", "時間の積み重ねは、物事に歳月の風味を與えます。私にも、ナビゲーターさんにも。……私、それが好きなんです。", "0", "0", "0", "0", "cv_chenglian_14", "0", "0"},
[413014] = {413014, 11030, 15, 9, "0", "0", "這……這是……！", "こ…これは……！", "0", "0", "0", "0", "cv_chenglian_15", "0", "0"},
[413015] = {413015, 11030, 16, 10, "0", "0", "任務目標好好傳達到了嗎？", "任務目標は屆きましたか？", "0", "0", "0", "0", "cv_chenglian_16", "0", "0"},
[413016] = {413016, 11030, 17, 11, "0", "0", "馬馬虎虎吧，戰鬥結束了。", "戦闘終了。まあまあでしたね。", "0", "0", "0", "0", "cv_chenglian_17", "0", "0"},
[413017] = {413017, 11030, 18, 12, "0", "0", "出現了紕漏啊。", "問題點が出ましたね。", "0", "0", "0", "0", "cv_chenglian_18", "0", "0"},
[413018] = {413018, 11030, 19, 13, "0", "0", "記錄然後修正，也只能這樣了吧。", "記録し、修正する。これしかありません。", "0", "0", "0", "0", "cv_chenglian_19", "0", "0"},
[413019] = {413019, 11030, 20, 14, "0", "0", "打起精神來，我們來想辦法。", "気を取り直してください。何か対策を考えましょう。", "0", "0", "0", "0", "cv_chenglian_20", "0", "0"},
[413020] = {413020, 11030, 21, 15, "0", "0", "墨已成章。", "墨が乾き、ことを成す。", "0", "0", "0", "0", "cv_chenglian_21", "0", "0"},
[413021] = {413021, 11030, 23, 16, "0", "0", "提筆。", "筆をとる。", "0", "0", "0", "0", "cv_chenglian_22", "0", "0"},
[413022] = {413022, 11030, 24, 17, "0", "0", "著墨。", "墨をつける。", "0", "0", "0", "0", "cv_chenglian_23", "0", "0"},
[413023] = {413023, 11030, 26, 19, "0", "0", "歷史的記錄，並不會中斷……", "歴史の記録は、途絶えません……", "0", "0", "0", "0", "cv_chenglian_24", "0", "0"},
[413024] = {413024, 11030, 27, 20, "0", "0", "感覺有點熱熱的……", "なんか熱くありませんか……？", "0", "0", "0", "0", "cv_chenglian_25", "0", "0"},
[413025] = {413025, 11030, 28, 21, "0", "0", "領航……答應我不要往下看哦……", "ナビゲーターさん……下を見ないでください……約束ですよ？", "0", "0", "0", "0", "cv_chenglian_26", "0", "0"},
[413026] = {413026, 11030, 29, 21, "0", "0", "焚香沐浴……是有什麼大事要發生了？", "お香とお風呂……何かが起きる予感がします……", "0", "0", "0", "0", "cv_chenglian_27", "0", "0"},
[413027] = {413027, 11030, 30, 22, "0", "0", "嗯……我的背上有什麼東西嗎？", "ん……？私の背中に何かついてますか？", "0", "0", "0", "0", "cv_chenglian_28", "0", "0"},
[413028] = {413028, 11030, 31, 23, "0", "0", "這算是一件值得記下來的大事嗎？", "これは記録すべきことでしょうか？", "0", "0", "0", "0", "cv_chenglian_29", "0", "0"},
[413029] = {413029, 11030, 32, 24, "0", "0", "呼……權且記下吧。", "ふぅ…一応記録しておきますね……", "0", "0", "0", "0", "cv_chenglian_30", "0", "0"},
[413030] = {413030, 11030, 33, 25, "0", "0", "領航認錯了人這件事，我就記下了。", "ナビゲーターさんが人を間違えました、と……", "0", "0", "0", "0", "cv_chenglian_31", "0", "0"},
[413031] = {413031, 11030, 34, 26, "0", "0", "今日的記錄，領航回到了方舟。", "今日の記録……ナビゲーターさんが方舟に戻りました、と……", "0", "0", "0", "0", "cv_chenglian_32", "0", "0"},
[413032] = {413032, 11030, 35, 27, "0", "0", "準備出征了嗎。", "出発の準備はできましたか？", "0", "0", "0", "0", "cv_chenglian_33", "0", "0"},
[413033] = {413033, 11030, 36, 28, "0", "0", "未雨綢繆。", "転ばぬ先の杖ですね。", "0", "0", "0", "0", "cv_chenglian_34", "0", "0"},
[413034] = {413034, 11030, 37, 29, "0", "0", "今日，造訪友人。", "今日は友人を訪ねるのですね。", "0", "0", "0", "0", "cv_chenglian_35", "0", "0"},
[413035] = {413035, 11030, 38, 30, "0", "0", "你究竟還會遇見多少人呢。", "これから先、いくつの出會いがあるのでしょうか。", "0", "0", "0", "0", "cv_chenglian_36", "0", "0"},
[413036] = {413036, 11030, 39, 31, "0", "0", "這都是為了我們啊。", "平心社のためでしょうか？", "0", "0", "0", "0", "cv_chenglian_37", "0", "0"},
[413037] = {413037, 11030, 40, 32, "0", "0", "購易之時。", "買い物の時です。", "0", "0", "0", "0", "cv_chenglian_38", "0", "0"},
[413038] = {413038, 11030, 41, 33, "0", "0", "檔案就由我幫你保存吧，領航。", "プロフィールは私が預かりましょうか？", "0", "0", "0", "0", "cv_chenglian_39", "0", "0"},
[413039] = {413039, 11030, 42, 34, "0", "0", "條理清晰呢。", "良く整理されてますね。", "0", "0", "0", "0", "cv_chenglian_40", "0", "0"},
[413040] = {413040, 11030, 43, 35, "0", "0", "書信也是歲月的載體。", "手紙もまた、時の経過を記す媒體です。", "0", "0", "0", "0", "cv_chenglian_41", "0", "0"},
[413041] = {413041, 11030, 44, 36, "0", "0", "這我可不能錯過。", "これは見逃せません。", "0", "0", "0", "0", "cv_chenglian_42", "0", "0"},
[413042] = {413042, 11030, 45, 37, "0", "0", "條條框框。", "枠組みが細かいですね。", "0", "0", "0", "0", "cv_chenglian_43", "0", "0"},
[413100] = {413100, 11031, 1, 1, "0", "0", "蒼霧殘響", "0", "0", "0", "0", "0", "cv_lailapusi_001", "0", "0"},
[413101] = {413101, 11031, 2, 2, "0", "0", "難道沒有其他更合適的人了嗎？這太引人矚目了，要是出了什麼意外，不要怪我沒提醒你。", "0", "0", "0", "0", "0", "cv_lailapusi_002", "0", "0"},
[413102] = {413102, 11031, 3, 3, "0", "0", "萊……萊拉普斯……“九頭蛇”的萊拉普斯……怎麼了，又不是我想取這個名字，我的品味才沒這麼低級。", "0", "0", "0", "0", "0", "cv_lailapusi_003", "0", "0"},
[413103] = {413103, 11031, 4, 4, "0", "idle", "自由……許多人都在追尋它，我們也不例外。我們現在只能寄望於那位博士能遵守承諾，在事情結束之後讓我們得到應有的自由。", "0", "0", "0", "0", "0", "cv_lailapusi_004", "0", "0"},
[413104] = {413104, 11031, 5, 4, "0", "idle", "我不喜歡這個地方，無論是這個組織還是這個方舟，但有你們在的話，我多少還能忍受這種異樣的環境和目光。", "0", "0", "0", "0", "0", "cv_lailapusi_005", "0", "0"},
[413105] = {413105, 11031, 6, 4, "0", "idle", "上次的事情，我還沒有機會好好答謝你呢。只是請客的話不足以奉還恩情……你還有其他想做的事情嗎？", "0", "0", "0", "0", "0", "cv_lailapusi_006", "0", "0"},
[413106] = {413106, 11031, 7, 5, "1_》_0_0.8", "level1", "只要能讓黎貝卡她能過上幸福、和平的生活，無論讓我做什麼，我都願意。", "0", "0", "0", "0", "0", "cv_lailapusi_007", "0", "0"},
[413107] = {413107, 11031, 8, 5, "1_》_0_0.8", "level1", "這具身體比我想像中還難控制，仿佛它有自己的情緒。這種想要將一切燒卻的憤怒，不是來自於我的想法，而是這具身體……是原罪的想法。", "0", "0", "0", "0", "0", "cv_lailapusi_008", "0", "0"},
[413108] = {413108, 11031, 9, 5, "1_》_100_1.5", "level2", "我有想過，如果黎貝卡再也無法恢復成正常人的身體，那我就和她一起成為別人眼中的怪物……你會介意嗎？", "0", "0", "0", "0", "0", "cv_lailapusi_009", "0", "0"},
[413109] = {413109, 11031, 10, 5, "1_》_500_2", "level3", "困……我要睡覺了……別在我睡覺的時候對我做壞事……我會生……生氣的……", "0", "0", "0", "0", "0", "cv_lailapusi_010", "0", "0"},
[413110] = {413110, 11031, 11, 5, "1_》_1000_2.5", "level4", "我追求的生活是平凡人的幸福，真遺憾，我們註定沒辦法在這條路上同行，但我會在自己將來的住所，為你準備好你想要的一切，等待你的凱旋。", "0", "0", "0", "0", "0", "cv_lailapusi_011", "0", "0"},
[413111] = {413111, 11031, 12, 6, "0", "0", "謝謝。", "0", "0", "0", "0", "0", "cv_lailapusi_012", "0", "0"},
[413112] = {413112, 11031, 13, 7, "0", "0", "噢……是星星啊，真好看。", "0", "0", "0", "0", "0", "cv_lailapusi_013", "0", "0"},
[413113] = {413113, 11031, 14, 8, "0", "0", "在艾吉斯，你是我唯一一個可以相信的人，你可能不清楚你對我來說有什麼樣的意義……總之，我想成為能讓你信任的人。", "0", "0", "0", "0", "0", "cv_lailapusi_014", "0", "0"},
[413114] = {413114, 11031, 15, 9, "0", "0", "謝了，感覺不壞。", "0", "0", "0", "0", "0", "cv_lailapusi_015", "0", "0"},
[413115] = {413115, 11031, 16, 10, "0", "0", "要戰鬥了嗎？嗯，我準備好了。", "0", "0", "0", "0", "0", "cv_lailapusi_016", "0", "0"},
[413116] = {413116, 11031, 17, 11, "0", "0", "很好，這樣一來我們就安全了吧？", "0", "0", "0", "0", "0", "cv_lailapusi_017", "0", "0"},
[413117] = {413117, 11031, 18, 12, "0", "0", "做的還不夠乾脆嗎？", "0", "0", "0", "0", "0", "cv_lailapusi_018", "0", "0"},
[413118] = {413118, 11031, 19, 13, "0", "0", "勉勉強強，真是危險啊。", "0", "0", "0", "0", "0", "cv_lailapusi_019", "0", "0"},
[413119] = {413119, 11031, 20, 14, "0", "0", "我來掩護你們。", "0", "0", "0", "0", "0", "cv_lailapusi_020", "0", "0"},
[413120] = {413120, 11031, 21, 15, "0", "0", "接著是哪一個？", "0", "0", "0", "0", "0", "cv_lailapusi_021", "0", "0"},
[413121] = {413121, 11031, 23, 16, "0", "0", "哈啊——！", "0", "0", "0", "0", "0", "cv_lailapusi_023", "0", "0"},
[413122] = {413122, 11031, 24, 17, "0", "0", "倒下吧！", "0", "0", "0", "0", "0", "cv_lailapusi_024", "0", "0"},
[413123] = {413123, 11031, 26, 19, "0", "0", "我會死嗎……真是討厭的感覺。", "0", "0", "0", "0", "0", "cv_lailapusi_025", "0", "0"},
[413124] = {413124, 11031, 27, 20, "0", "0", "……如果這個狀態下有槍，我已經開槍了。", "0", "0", "0", "0", "0", "cv_lailapusi_026", "0", "0"},
[413125] = {413125, 11031, 28, 21, "0", "0", "你在旁邊……有點怪，但好像還好，至少是你在。", "0", "0", "0", "0", "0", "cv_lailapusi_027", "0", "0"},
[413126] = {413126, 11031, 29, 21, "0", "0", "可能是你的能力在起作用，你在身邊的時候，這具原罪的軀體就會變得平靜。", "0", "0", "0", "0", "0", "cv_lailapusi_028", "0", "0"},
[413127] = {413127, 11031, 30, 22, "0", "0", "嗯？", "0", "0", "0", "0", "0", "cv_lailapusi_029", "0", "0"},
[413128] = {413128, 11031, 31, 23, "0", "0", "呃…也就是說你可能沒有認出我是誰？", "0", "0", "0", "0", "0", "cv_lailapusi_030", "0", "0"},
[413129] = {413129, 11031, 32, 24, "0", "0", "我還擔心……沒事，恭喜你答對了。", "0", "0", "0", "0", "0", "cv_lailapusi_031", "0", "0"},
[413130] = {413130, 11031, 33, 25, "0", "0", "你覺得這很幽默嗎？", "0", "0", "0", "0", "0", "cv_lailapusi_032", "0", "0"},
[413131] = {413131, 11031, 34, 26, "0", "0", "你來了？我還在想今天能不能見到你。", "0", "0", "0", "0", "0", "cv_lailapusi_033", "0", "0"},
[413132] = {413132, 11031, 35, 27, "0", "0", "為了我們各自的目標……前進。", "0", "0", "0", "0", "0", "cv_lailapusi_034", "0", "0"},
[413133] = {413133, 11031, 36, 28, "0", "0", "我不太擅長戰鬥，但和你的話可以試一試。", "0", "0", "0", "0", "0", "cv_lailapusi_035", "0", "0"},
[413134] = {413134, 11031, 37, 29, "0", "0", "你挺受歡迎的。", "0", "0", "0", "0", "0", "cv_lailapusi_036", "0", "0"},
[413135] = {413135, 11031, 38, 30, "0", "0", "你要組建一個超級戰隊嗎？", "0", "0", "0", "0", "0", "cv_lailapusi_037", "0", "0"},
[413136] = {413136, 11031, 39, 31, "0", "0", "別衝動就好。", "0", "0", "0", "0", "0", "cv_lailapusi_038", "0", "0"},
[413137] = {413137, 11031, 40, 32, "0", "0", "節約點吧。", "0", "0", "0", "0", "0", "cv_lailapusi_039", "0", "0"},
[413138] = {413138, 11031, 41, 33, "0", "0", "……還好吧。", "0", "0", "0", "0", "0", "cv_lailapusi_040", "0", "0"},
[413139] = {413139, 11031, 42, 34, "0", "0", "設置，記得保存。", "0", "0", "0", "0", "0", "cv_lailapusi_041", "0", "0"},
[413140] = {413140, 11031, 43, 35, "0", "0", "情書……咳，應該不可能有……吧？", "0", "0", "0", "0", "0", "cv_lailapusi_042", "0", "0"},
[413141] = {413141, 11031, 44, 36, "0", "0", "別打擾到我就好。", "0", "0", "0", "0", "0", "cv_lailapusi_043", "0", "0"},
[413142] = {413142, 11031, 45, 37, "0", "0", "嗯。", "0", "0", "0", "0", "0", "cv_lailapusi_044", "0", "0"},
[413200] = {413200, 11032, 1, 1, "0", "0", "蒼霧殘響", "0", "0", "0", "0", "0", "cv_qianqiu_1", "0", "0"},
[413201] = {413201, 11032, 2, 2, "0", "0", "就不能讓別人來做這件事……好啦好啦，我做就是了。", "0", "0", "0", "0", "0", "cv_qianqiu_2", "0", "0"},
[413202] = {413202, 11032, 3, 3, "0", "0", "唉……史蒂芬妮那傢夥真是有夠目中無人的……總之——好久不見，看來你已經成為相當出色的領航了……你不會已經忘了我吧？千——秋，好好記住這個名字。", "0", "0", "0", "0", "0", "cv_qianqiu_3", "0", "0"},
[413203] = {413203, 11032, 4, 4, "0", "idle", "“殺人鬼”千秋——我一直想被人這樣稱呼。不過艾吉斯裏好像已經有人被這麼叫了……可惡，也不知道是被哪個不知好歹的傢夥搶先了。", "0", "0", "0", "0", "0", "cv_qianqiu_4", "0", "0"},
[413204] = {413204, 11032, 5, 4, "0", "idle", "謔——沒想到，一年多不見，你的身邊又多出了這麼多漂亮的女孩，真不愧是你。怎麼，不打算給我介紹下她們嗎，尤其是那個一臉狂妄，總纏著你的金髮妹。", "0", "0", "0", "0", "0", "cv_qianqiu_5", "0", "0"},
[413205] = {413205, 11032, 6, 4, "0", "idle", "下次有機會的話，我要嘗試一下霜淇淋蛋糕搭配拉麵的吃法。嗯，這會是一次前所未有的挑戰，但不管怎麼說，咽下它們應該比殺人要簡單吧？", "0", "0", "0", "0", "0", "cv_qianqiu_6", "0", "0"},
[413206] = {413206, 11032, 7, 5, "1_》_0_0.8", "level1", "你知道嗎？“將某人殺死”，這種事做起來其實沒有多難。可若是一個人能沒有心理負擔地輕易越過殺人之門，那便是殺人鬼。", "0", "0", "0", "0", "0", "cv_qianqiu_7", "0", "0"},
[413207] = {413207, 11032, 8, 5, "1_》_0_0.8", "level1", "如果不是史蒂芬妮，我是絕對不會當駕駛員的……唉，那傢夥不會是施虐狂吧，一定要強迫別人做不願意做的事情。", "0", "0", "0", "0", "0", "cv_qianqiu_8", "0", "0"},
[413208] = {413208, 11032, 9, 5, "1_》_100_1.5", "level2", "怎麼？沒事情做嗎？既然如此，要不要看看我的胸部？“玩笑”？為什麼會這麼想，我是認真的。畢竟現在真的很無聊。放心，我不會殺你的。", "0", "0", "0", "0", "0", "cv_qianqiu_9", "0", "0"},
[413209] = {413209, 11032, 10, 5, "1_》_500_2", "level3", "話說，史蒂芬妮說你的使命很重要——你知道自己的使命是什麼嗎……算了，怎麼樣都好，跟我沒關係，我只要在自己死之前，保證你不會死，這樣就行了。", "0", "0", "0", "0", "0", "cv_qianqiu_10", "0", "0"},
[413210] = {413210, 11032, 11, 5, "1_》_1000_2.5", "level4", "我呢，是殺人鬼，如果不是還有利用價值的話，我大概已經被處死了……只要活著總會有好事發生，能在自己像下水溝裏的屎一般又臭又爛的人生裏能遇到你，也不壞。", "0", "0", "0", "0", "0", "cv_qianqiu_11", "0", "0"},
[413211] = {413211, 11032, 12, 6, "0", "0", "級別越高，責任越大，我說的對嗎？", "0", "0", "0", "0", "0", "cv_qianqiu_12", "0", "0"},
[413212] = {413212, 11032, 13, 7, "0", "0", "想獎勵我的話，不如下次請我吃拉麵。", "0", "0", "0", "0", "0", "cv_qianqiu_13", "0", "0"},
[413213] = {413213, 11032, 14, 8, "0", "0", "還記得我們第一次見面時說的嗎？對，我一點也不想當駕駛員……唉，我可能怎麼也想不到居然會成這樣，真有你的——領航。", "0", "0", "0", "0", "0", "cv_qianqiu_14", "0", "0"},
[413214] = {413214, 11032, 15, 9, "0", "0", "讓我的剪刀更加鋒銳吧！", "0", "0", "0", "0", "0", "cv_qianqiu_15", "0", "0"},
[413215] = {413215, 11032, 16, 10, "0", "0", "讓我們大鬧一場吧！", "0", "0", "0", "0", "0", "cv_qianqiu_16", "0", "0"},
[413216] = {413216, 11032, 17, 11, "0", "0", "這樣就結束了？我才剛熱完身呢。", "0", "0", "0", "0", "0", "cv_qianqiu_17", "0", "0"},
[413217] = {413217, 11032, 18, 12, "0", "0", "稍微有點棘手呀。", "0", "0", "0", "0", "0", "cv_qianqiu_18", "0", "0"},
[413218] = {413218, 11032, 19, 13, "0", "0", "我還以為要輸了……居然贏了啊。", "0", "0", "0", "0", "0", "cv_qianqiu_19", "0", "0"},
[413219] = {413219, 11032, 20, 14, "0", "0", "我們一起好好反省吧，這次太遜了。", "0", "0", "0", "0", "0", "cv_qianqiu_20", "0", "0"},
[413220] = {413220, 11032, 21, 15, "0", "0", "大卸八塊！", "0", "0", "0", "0", "0", "cv_qianqiu_21", "0", "0"},
[413221] = {413221, 11032, 23, 16, "0", "0", "死吧！", "0", "0", "0", "0", "0", "cv_qianqiu_23", "0", "0"},
[413222] = {413222, 11032, 24, 17, "0", "0", "還沒死嗎？", "0", "0", "0", "0", "0", "cv_qianqiu_24", "0", "0"},
[413223] = {413223, 11032, 25, 18, "0", "0", "此刻開始，無人生還。", "0", "0", "0", "0", "0", "cv_qianqiu_25", "0", "0"},
[413224] = {413224, 11032, 26, 19, "0", "0", "我還沒盡興呢——", "0", "0", "0", "0", "0", "cv_qianqiu_26", "0", "0"},
[413225] = {413225, 11032, 27, 20, "0", "0", "我打賭，想出讓你進來搓澡這種餿主意的人一定是史蒂芬妮，只有她才會這麼惡趣味。", "0", "0", "0", "0", "0", "cv_qianqiu_27", "0", "0"},
[413226] = {413226, 11032, 28, 21, "0", "0", "說起來，我還沒有去泡過溫泉呢……要一起去嗎？", "0", "0", "0", "0", "0", "cv_qianqiu_28", "0", "0"},
[413227] = {413227, 11032, 29, 21, "0", "0", "還沒結束嗎？", "0", "0", "0", "0", "0", "cv_qianqiu_29", "0", "0"},
[413228] = {413228, 11032, 30, 22, "0", "0", "怎麼了？", "0", "0", "0", "0", "0", "cv_qianqiu_30", "0", "0"},
[413229] = {413229, 11032, 31, 23, "0", "0", "“你身後的是誰~”", "0", "0", "0", "0", "0", "cv_qianqiu_31", "0", "0"},
[413230] = {413230, 11032, 32, 24, "0", "0", "回答正確，下一個到我了，我也要玩。", "0", "0", "0", "0", "0", "cv_qianqiu_32", "0", "0"},
[413231] = {413231, 11032, 33, 25, "0", "0", "喂，殺了你哦。", "0", "0", "0", "0", "0", "cv_qianqiu_33", "0", "0"},
[413232] = {413232, 11032, 34, 26, "0", "0", "回來了？知道你很忙，既然回來了就先休息一會吧。", "0", "0", "0", "0", "0", "cv_qianqiu_34", "0", "0"},
[413233] = {413233, 11032, 35, 27, "0", "0", "嗯——呼——好，出發，讓我們把它們殺個乾淨吧。", "0", "0", "0", "0", "0", "cv_qianqiu_35", "0", "0"},
[413234] = {413234, 11032, 36, 28, "0", "0", "要是不小心殺人了可別怪我噢？", "0", "0", "0", "0", "0", "cv_qianqiu_36", "0", "0"},
[413235] = {413235, 11032, 37, 29, "0", "0", "比我想像中還“華麗”啊……", "0", "0", "0", "0", "0", "cv_qianqiu_37", "0", "0"},
[413236] = {413236, 11032, 38, 30, "0", "0", "你要找多少女孩子才滿意呢？", "0", "0", "0", "0", "0", "cv_qianqiu_38", "0", "0"},
[413237] = {413237, 11032, 39, 31, "0", "0", "不能直接買嗎？", "0", "0", "0", "0", "0", "cv_qianqiu_39", "0", "0"},
[413238] = {413238, 11032, 40, 32, "0", "0", "拉麵！霜淇淋漢堡！", "0", "0", "0", "0", "0", "cv_qianqiu_40", "0", "0"},
[413239] = {413239, 11032, 41, 33, "0", "0", "你真的成長了不少啊。", "0", "0", "0", "0", "0", "cv_qianqiu_41", "0", "0"},
[413240] = {413240, 11032, 42, 34, "0", "0", "設置~", "0", "0", "0", "0", "0", "cv_qianqiu_42", "0", "0"},
[413241] = {413241, 11032, 43, 35, "0", "0", "有犯罪預告或者怪盜的挑戰書嗎？", "0", "0", "0", "0", "0", "cv_qianqiu_43", "0", "0"},
[413242] = {413242, 11032, 44, 36, "0", "0", "真閑啊。", "0", "0", "0", "0", "0", "cv_qianqiu_44", "0", "0"},
[413243] = {413243, 11032, 45, 37, "0", "0", "嘿咻！", "0", "0", "0", "0", "0", "cv_qianqiu_45", "0", "0"},
[413300] = {413300, 11033, 1, 1, "0", "0", "蒼霧殘響", "0", "0", "0", "0", "0", "cv_starry_1", "0", "0"},
[413301] = {413301, 11033, 2, 2, "0", "0", "讓我待在這的話，說不定會被墜落的隕石命中——哈哈，只是開個“電影玩笑”而已。", "0", "0", "0", "0", "0", "cv_starry_2", "0", "0"},
[413302] = {413302, 11033, 3, 3, "0", "0", "嗨~色狼先生，好久不見~你已經是正式的領航了？嗯，我也是正式的駕駛員，前線小隊的“星爍”咯……雖然發生了各種各樣的事，但我們總算又見面了。", "0", "0", "0", "0", "0", "cv_starry_3", "0", "0"},
[413303] = {413303, 11033, 4, 4, "0", "idle", "請別嫉妒我的強運哦，畢竟這是我僅有的優點了，除了它之外，我一無所有。", "0", "0", "0", "0", "0", "cv_starry_4", "0", "0"},
[413304] = {413304, 11033, 5, 4, "0", "idle", "我很喜歡一個人行動哦，一個人不是挺好的嗎？人與人之間的對比只會產生讓人自我懷疑的落差感。大家都孤身一人的話，誰都不會受傷了。", "0", "0", "0", "0", "0", "cv_starry_5", "0", "0"},
[413305] = {413305, 11033, 6, 4, "0", "idle", "如果我想去旅遊的話，說不定就會抽中免費機票或者豪華遊輪船票什麼的……不過說不定旅遊的景點會發生什麼糟糕的事情。這樣一想，就沒什麼心情去旅遊了呀。", "0", "0", "0", "0", "0", "cv_starry_6", "0", "0"},
[413306] = {413306, 11033, 7, 5, "1_》_0_0.8", "level1", "不論我採取多麼離譜的舉動，世界都會以好的結果來回應我的期待。如何？很不公平吧？", "0", "0", "0", "0", "0", "cv_starry_7", "0", "0"},
[413307] = {413307, 11033, 8, 5, "1_》_0_0.8", "level1", "色狼先生又要開始啦？", "0", "0", "0", "0", "0", "cv_starry_8", "0", "0"},
[413308] = {413308, 11033, 9, 5, "1_》_100_1.5", "level2", "裝甲？那種東西太重了，穿在身上一點也不舒服。如果有攻擊能打中我，那就說明我的好運到頭了，也算是種好事吧。", "0", "0", "0", "0", "0", "cv_starry_9", "0", "0"},
[413309] = {413309, 11033, 10, 5, "1_》_500_2", "level3", "你還記得那時候的事啊……唉，比起那種無聊的事，你要是能記得更久以前的事就好了……算啦，你當做沒聽見，我什麼也沒說吧。", "0", "0", "0", "0", "0", "cv_starry_10", "0", "0"},
[413310] = {413310, 11033, 11, 5, "1_》_1000_2.5", "level4", "對了，我是不是沒有說過？我很喜歡雖然色狼先生那副什麼都不知道， 但還是憑著感覺沖出來的模樣，真是酷斃了。要是有一天我遇到了危險，你也一定要來救我哦。", "0", "0", "0", "0", "0", "cv_starry_11", "0", "0"},
[413311] = {413311, 11033, 12, 6, "0", "0", "不錯不錯。", "0", "0", "0", "0", "0", "cv_starry_12", "0", "0"},
[413312] = {413312, 11033, 13, 7, "0", "0", "和我的代號很搭配呢。", "0", "0", "0", "0", "0", "cv_starry_13", "0", "0"},
[413313] = {413313, 11033, 14, 8, "0", "0", "我們貪婪的本性會讓我們去不斷索取更好的東西，連運氣也不會放過。色狼先生，也許以後會發生不好的事情，但這一次，我會和你共同面對的。", "0", "0", "0", "0", "0", "cv_starry_14", "0", "0"},
[413314] = {413314, 11033, 15, 9, "0", "0", "我更加幸運了？", "0", "0", "0", "0", "0", "cv_starry_15", "0", "0"},
[413315] = {413315, 11033, 16, 10, "0", "0", "接下來會發生什麼好事呢？", "0", "0", "0", "0", "0", "cv_starry_16", "0", "0"},
[413316] = {413316, 11033, 17, 11, "0", "0", "真好啊，我們又贏了。", "0", "0", "0", "0", "0", "cv_starry_17", "0", "0"},
[413317] = {413317, 11033, 18, 12, "0", "0", "確認一下傷患狀況吧。", "0", "0", "0", "0", "0", "cv_starry_18", "0", "0"},
[413318] = {413318, 11033, 19, 13, "0", "0", "這樣可算不上勝利呀。", "0", "0", "0", "0", "0", "cv_starry_19", "0", "0"},
[413319] = {413319, 11033, 20, 14, "0", "0", "吸取失敗的教訓，這也是成功的必經之路。", "0", "0", "0", "0", "0", "cv_starry_20", "0", "0"},
[413320] = {413320, 11033, 21, 15, "0", "0", "看著真可憐。", "0", "0", "0", "0", "0", "cv_starry_21", "0", "0"},
[413321] = {413321, 11033, 23, 16, "0", "0", "上咯！", "0", "0", "0", "0", "0", "cv_starry_23", "0", "0"},
[413322] = {413322, 11033, 24, 17, "0", "0", "會很痛的。", "0", "0", "0", "0", "0", "cv_starry_24", "0", "0"},
[413323] = {413323, 11033, 26, 19, "0", "0", "沒事的，因為我很走運嘛。", "0", "0", "0", "0", "0", "cv_starry_25", "0", "0"},
[413324] = {413324, 11033, 27, 20, "0", "0", "噢，色狼先生，又來偷窺了嗎？", "0", "0", "0", "0", "0", "cv_starry_26", "0", "0"},
[413325] = {413325, 11033, 28, 21, "0", "0", "怎麼樣，好看嗎？那就趁還能看的時候多看一下吧。", "0", "0", "0", "0", "0", "cv_starry_27", "0", "0"},
[413326] = {413326, 11033, 29, 21, "0", "0", "色狼先生要是也巨大化的話，我就可以替你搓背了吧？", "0", "0", "0", "0", "0", "cv_starry_28", "0", "0"},
[413327] = {413327, 11033, 30, 22, "0", "0", "撿到錢了嗎？", "0", "0", "0", "0", "0", "cv_starry_29", "0", "0"},
[413328] = {413328, 11033, 31, 23, "0", "0", "猜猜我是誰？", "0", "0", "0", "0", "0", "cv_starry_30", "0", "0"},
[413329] = {413329, 11033, 32, 24, "0", "0", "恭喜，看來你這次記得我啦。", "0", "0", "0", "0", "0", "cv_starry_31", "0", "0"},
[413330] = {413330, 11033, 33, 25, "0", "0", "真遺憾，猜錯了，別在意~", "0", "0", "0", "0", "0", "cv_starry_32", "0", "0"},
[413331] = {413331, 11033, 34, 26, "0", "0", "對我來說，和你的每次見面都像是一種重逢——這樣想的話就會很浪漫吧。", "0", "0", "0", "0", "0", "cv_starry_33", "0", "0"},
[413332] = {413332, 11033, 35, 27, "0", "0", "遇到危險我會向你求救的~", "0", "0", "0", "0", "0", "cv_starry_34", "0", "0"},
[413333] = {413333, 11033, 36, 28, "0", "0", "我不會對她們手下留情的。", "0", "0", "0", "0", "0", "cv_starry_35", "0", "0"},
[413334] = {413334, 11033, 37, 29, "0", "0", "嗨——大家好~", "0", "0", "0", "0", "0", "cv_starry_36", "0", "0"},
[413335] = {413335, 11033, 38, 30, "0", "0", "招聘新人啦！", "0", "0", "0", "0", "0", "cv_starry_37", "0", "0"},
[413336] = {413336, 11033, 39, 31, "0", "0", "抽獎嗎？那我還是離遠點比較好~", "0", "0", "0", "0", "0", "cv_starry_38", "0", "0"},
[413337] = {413337, 11033, 40, 32, "0", "0", "購物啊，我不討厭。", "0", "0", "0", "0", "0", "cv_starry_39", "0", "0"},
[413338] = {413338, 11033, 41, 33, "0", "0", "你真努力呀。", "0", "0", "0", "0", "0", "cv_starry_40", "0", "0"},
[413339] = {413339, 11033, 42, 34, "0", "0", "應付一下就行啦。", "0", "0", "0", "0", "0", "cv_starry_41", "0", "0"},
[413340] = {413340, 11033, 43, 35, "0", "0", "有寄錯的禮品就安心收下吧！", "0", "0", "0", "0", "0", "cv_starry_42", "0", "0"},
[413341] = {413341, 11033, 44, 36, "0", "0", "要和人聊聊天嗎？", "0", "0", "0", "0", "0", "cv_starry_43", "0", "0"},
[413342] = {413342, 11033, 45, 37, "0", "0", "點一下！", "0", "0", "0", "0", "0", "cv_starry_44", "0", "0"},
[413400] = {413400, 11034, 1, 1, "0", "0", "蒼霧殘響噢！", "0", "0", "0", "0", "0", "cv_lodonia_34", "0", "0"},
[413401] = {413401, 11034, 2, 2, "0", "0", "瞭解！我會把所有想傷害領航的傢夥全部打飛的！", "0", "0", "0", "0", "0", "cv_lodonia_2", "0", "0"},
[413402] = {413402, 11034, 3, 3, "0", "0", "噢噢噢！我聽說過你！你就是那位很厲害的領航吧！我是第三研究室防衛班的羅德尼亞，請多關照！", "0", "0", "0", "0", "0", "cv_lodonia_1", "0", "0"},
[413403] = {413403, 11034, 4, 4, "0", "idle", "領航，我可是被人評價為“天生的領袖”噢，超——厲害吧！誰說的？哼哼，當然是我自己說的啦。", "0", "0", "0", "0", "0", "cv_lodonia_3", "0", "0"},
[413404] = {413404, 11034, 5, 4, "0", "idle", "領航要是無聊的話，我可以為你用風笛演奏樂曲噢！……什麼，“不像是我會做的事”？真是失禮啊，我可是溫柔的女孩子噢！", "0", "0", "0", "0", "0", "cv_lodonia_4", "0", "0"},
[413405] = {413405, 11034, 6, 4, "0", "idle", "說起來……我一開始以為多洛莉絲隊長很弱呢。接觸之後才發現，她這不是超強的嗎！真不愧是“隊長”啊。", "0", "0", "0", "0", "0", "cv_lodonia_31", "0", "0"},
[413406] = {413406, 11034, 7, 5, "1_》_0_0.8", "level1", "好癢啦哈哈哈！", "0", "0", "0", "0", "0", "cv_lodonia_5", "0", "0"},
[413407] = {413407, 11034, 8, 5, "1_》_0_0.8", "level1", "我的夢想？說出來不許笑話我噢！我想成為像我的姐姐，還有多洛莉絲隊長那樣，既強大，又溫柔的人……", "0", "0", "0", "0", "0", "cv_lodonia_32", "0", "0"},
[413408] = {413408, 11034, 9, 5, "1_》_100_1.5", "level2", "領航，我基本上是從來不開玩笑的噢。有想要做的事情就現在去做！這是我的人生信條！", "0", "0", "0", "0", "0", "cv_lodonia_6", "0", "0"},
[413409] = {413409, 11034, 10, 5, "1_》_500_2", "level3", "領航，工作辛苦了，也要稍微注重一下身體噢——啊，不行不行，這樣說話超累啊！姐姐和多洛莉絲隊長是怎麼做到的呀？我偶爾也想試著這樣，溫柔的和領航說話啦~", "0", "0", "0", "0", "0", "cv_lodonia_7", "0", "0"},
[413410] = {413410, 11034, 11, 5, "1_》_1000_2.5", "level4", "領航，你工作上如果遇到什麼不順心的事，生活上有什麼煩惱，可以跟我說噢。我超願意當你的傾聽者，聽你講述自己的煩心事的！畢竟，這也是我的目標之一啦~", "0", "0", "0", "0", "0", "cv_lodonia_8", "0", "0"},
[413411] = {413411, 11034, 12, 6, "0", "0", "前輩們的戰鬥方式超帥啊！", "0", "0", "0", "0", "0", "cv_lodonia_9", "0", "0"},
[413412] = {413412, 11034, 13, 7, "0", "0", "噢噢噢，心情高漲起來了！", "0", "0", "0", "0", "0", "cv_lodonia_10", "0", "0"},
[413413] = {413413, 11034, 14, 8, "0", "0", "哼哼，這樣一來，我就超過那些“天才”了吧！謝啦！之後就讓我為領航你獻上一曲“友誼地久天長”吧……誒？居然說不合適嗎！？", "0", "0", "0", "0", "0", "cv_lodonia_11", "0", "0"},
[413414] = {413414, 11034, 15, 9, "0", "0", "我變得更厲害了!", "0", "0", "0", "0", "0", "cv_lodonia_12", "0", "0"},
[413415] = {413415, 11034, 16, 10, "0", "0", "讓它們見識一下新第三研究室防衛班的實力！", "0", "0", "0", "0", "0", "cv_lodonia_13", "0", "0"},
[413416] = {413416, 11034, 17, 11, "0", "0", "領航，看到我們在戰場活躍的身姿了嗎？超厲害吧！", "0", "0", "0", "0", "0", "cv_lodonia_14", "0", "0"},
[413417] = {413417, 11034, 18, 12, "0", "0", "哼哼，對戰局的把握漸入佳境了呢！", "0", "0", "0", "0", "0", "cv_lodonia_15", "0", "0"},
[413418] = {413418, 11034, 19, 13, "0", "0", "我們下一次一定能做得更好的！", "0", "0", "0", "0", "0", "cv_lodonia_16", "0", "0"},
[413419] = {413419, 11034, 20, 14, "0", "0", "先暫時撤退吧，我來掩護大家！", "0", "0", "0", "0", "0", "cv_lodonia_17", "0", "0"},
[413420] = {413420, 11034, 21, 15, "0", "0", "下一個！", "0", "0", "0", "0", "0", "cv_lodonia_18", "0", "0"},
[413421] = {413421, 11034, 23, 16, "0", "0", "開火~！", "0", "0", "0", "0", "0", "cv_lodonia_20", "0", "0"},
[413422] = {413422, 11034, 24, 17, "0", "0", "我可不會手下留情噢！", "0", "0", "0", "0", "0", "cv_lodonia_22", "0", "0"},
[413423] = {413423, 11034, 25, 18, "0", "0", "接下來是我的超必殺技！接招吧，原罪！", "0", "0", "0", "0", "0", "cv_lodonia_23", "0", "0"},
[413424] = {413424, 11034, 26, 19, "0", "0", "還有好多想和領航一起做的事……真遺憾啊……", "0", "0", "0", "0", "0", "cv_lodonia_21", "0", "0"},
[413425] = {413425, 11034, 27, 20, "0", "0", "哈哈，這不是領航嗎，你也來泡澡嗎？", "0", "0", "0", "0", "0", "cv_lodonia_24", "0", "0"},
[413426] = {413426, 11034, 28, 21, "0", "0", "我也是最近才明白了泡澡的魅力。我決定了，以後要一天泡兩次澡！", "0", "0", "0", "0", "0", "cv_lodonia_25", "0", "0"},
[413427] = {413427, 11034, 29, 21, "0", "0", "像這樣慢慢地在水裏躺下，然後放鬆身體——超舒服的！領航，你要一起來試試嗎！", "0", "0", "0", "0", "0", "cv_lodonia_26", "0", "0"},
[413428] = {413428, 11034, 30, 22, "0", "0", "有趣的事件要來了嗎！", "0", "0", "0", "0", "0", "cv_lodonia_27", "0", "0"},
[413429] = {413429, 11034, 31, 23, "0", "0", "以我們的默契而看，這不是超簡單的嘛，領航！", "0", "0", "0", "0", "0", "cv_lodonia_28", "0", "0"},
[413430] = {413430, 11034, 32, 24, "0", "0", "看來領航你超懂我嘛，哈哈！", "0", "0", "0", "0", "0", "cv_lodonia_29", "0", "0"},
[413431] = {413431, 11034, 33, 25, "0", "0", "誒~超失望。", "0", "0", "0", "0", "0", "cv_lodonia_30", "0", "0"},
[413432] = {413432, 11034, 34, 26, "0", "0", "呼！嘿咻！嘿嘿，安全上壘！嗯？什麼都沒發生啦！我有老老實實地在這裏等你回來噢~", "0", "0", "0", "0", "0", "cv_lodonia_33", "0", "0"},
[413433] = {413433, 11034, 35, 27, "0", "0", "差不多該帶我去加入超大型戰役了吧~領航！", "0", "0", "0", "0", "0", "cv_lodonia_35", "0", "0"},
[413434] = {413434, 11034, 36, 28, "0", "0", "一口氣清理乾淨，然後變得超級厲害吧！", "0", "0", "0", "0", "0", "cv_lodonia_36", "0", "0"},
[413435] = {413435, 11034, 37, 29, "0", "0", "感覺大家都很厲害呢。", "0", "0", "0", "0", "0", "cv_lodonia_37", "0", "0"},
[413436] = {413436, 11034, 38, 30, "0", "0", "我超擅長選人的！讓我來吧！", "0", "0", "0", "0", "0", "cv_lodonia_38", "0", "0"},
[413437] = {413437, 11034, 39, 31, "0", "0", "讓我來抽吧，我運氣超好的！", "0", "0", "0", "0", "0", "cv_lodonia_39", "0", "0"},
[413438] = {413438, 11034, 40, 32, "0", "0", "我要買那個看著最厲害的那個！", "0", "0", "0", "0", "0", "cv_lodonia_40", "0", "0"},
[413439] = {413439, 11034, 41, 33, "0", "0", "很有精神嘛！", "0", "0", "0", "0", "0", "cv_lodonia_41", "0", "0"},
[413440] = {413440, 11034, 42, 34, "0", "0", "隨便應付一下吧！", "0", "0", "0", "0", "0", "cv_lodonia_42", "0", "0"},
[413441] = {413441, 11034, 43, 35, "0", "0", "不帶贈品的郵件沒有意義！", "0", "0", "0", "0", "0", "cv_lodonia_43", "0", "0"},
[413442] = {413442, 11034, 44, 36, "0", "0", "我來啦我來啦！", "0", "0", "0", "0", "0", "cv_lodonia_44", "0", "0"},
[413443] = {413443, 11034, 45, 37, "0", "0", "超可疑的按鈕！", "0", "0", "0", "0", "0", "cv_lodonia_45", "0", "0"},
[413500] = {413500, 11035, 1, 1, "0", "0", "蒼霧殘響。", "0", "0", "0", "0", "0", "cv_zepar_32", "0", "0"},
[413501] = {413501, 11035, 2, 2, "0", "0", "真沒想到，如今已經餘裕到可以讓駕駛員做這樣的事了~不過人家並不討厭，倒不如說很中意這份餘裕呢！", "0", "0", "0", "0", "0", "cv_zepar_2", "0", "0"},
[413502] = {413502, 11035, 3, 3, "0", "0", "你就是史蒂芬妮提過的那位領航嗎？嘻嘻，我是桀派。現在姑且是“鐵鴉”小隊的隊員。之後你可得好好照顧可愛的人家哦。", "0", "0", "0", "0", "0", "cv_zepar_1", "0", "0"},
[413503] = {413503, 11035, 4, 4, "0", "idle", "“所羅門的魔神”？討厭啦，人家這麼可愛的女孩子，怎麼會有那種奇怪的稱號呢？一定是領航你把人家和不知道的哪個誰弄混了。", "0", "0", "0", "0", "0", "cv_zepar_3", "0", "0"},
[413504] = {413504, 11035, 5, 4, "0", "idle", "艾吉斯的變化真大呢…這就是“時間”嗎？人家是不是也得努力一下，不能讓那些後生小瞧了~", "0", "0", "0", "0", "0", "cv_zepar_4", "0", "0"},
[413505] = {413505, 11035, 6, 4, "0", "idle", "“您要是害羞的話，我就用鎖鏈領走您了哦？”被萊帕尼隊長這麼說了之後，就算是人家也不好意思拒絕了。不過，像現在這樣為隊友提供支援，意外得很適合人家呢！", "0", "0", "0", "0", "0", "cv_zepar_29", "0", "0"},
[413506] = {413506, 11035, 7, 5, "1_》_0_0.8", "level1", "困的時候可以想睡多久就睡多久；喜歡的食物想吃多少就可以吃多少；如果有了想要談戀愛的對象，就大膽地去追。這就是人家現在最想做的事情。對方是誰？嘿嘿，這麼想知道麼？", "0", "0", "0", "0", "0", "cv_zepar_30", "0", "0"},
[413507] = {413507, 11035, 8, 5, "1_》_0_0.8", "level1", "呵呵~人家是不是很可愛呀？", "0", "0", "0", "0", "0", "cv_zepar_5", "0", "0"},
[413508] = {413508, 11035, 9, 5, "1_》_100_1.5", "level2", "哈啊~這種感覺，真好啊。悠悠閑閑的，更別說是和領航一起享受二人世界~", "0", "0", "0", "0", "0", "cv_zepar_6", "0", "0"},
[413509] = {413509, 11035, 10, 5, "1_》_500_2", "level3", "人家很關心領航你的身體健康哦~跟身體健康比起來，榮譽和金錢都不算什麼了。所以想要休息的時候要好好休息哦。", "0", "0", "0", "0", "0", "cv_zepar_7", "0", "0"},
[413510] = {413510, 11035, 11, 5, "1_》_1000_2.5", "level4", "“桀派”……它是我的榮譽，也是我的桎梏。就算我躲到地獄，它也把我拉了回來，趕回戰場上。但是，我並不後悔…至少，正是因為大家需要“桀派”，人家才會和領航相遇呀。", "0", "0", "0", "0", "0", "cv_zepar_8", "0", "0"},
[413511] = {413511, 11035, 12, 6, "0", "0", "嘻嘻~謝謝~", "0", "0", "0", "0", "0", "cv_zepar_9", "0", "0"},
[413512] = {413512, 11035, 13, 7, "0", "0", "變強了嗎…接下來不會要加班吧……", "0", "0", "0", "0", "0", "cv_zepar_10", "0", "0"},
[413513] = {413513, 11035, 14, 8, "0", "0", "人家現在的心情真的有些複雜，被如此重視的話，不在戰場上好好表現是不行的吧？嗯…好！決定了，人家得拿出幹勁，讓領航你見識一下“所羅門的魔神”有多麼厲害了！……不過領航還真是喜歡人家呢，嘻嘻~♪", "0", "0", "0", "0", "0", "cv_zepar_11", "0", "0"},
[413514] = {413514, 11035, 15, 9, "0", "0", "我已經有不好的預感啦……", "0", "0", "0", "0", "0", "cv_zepar_12", "0", "0"},
[413515] = {413515, 11035, 16, 10, "0", "0", "久違的戰場呢……總之加油吧！", "0", "0", "0", "0", "0", "cv_zepar_13", "0", "0"},
[413516] = {413516, 11035, 17, 11, "0", "0", "真是漂亮的勝利！那麼可以休息了嗎？", "0", "0", "0", "0", "0", "cv_zepar_14", "0", "0"},
[413517] = {413517, 11035, 18, 12, "0", "0", "這種程度的勝利不是剛剛好嘛。", "0", "0", "0", "0", "0", "cv_zepar_15", "0", "0"},
[413518] = {413518, 11035, 19, 13, "0", "0", "唉…人家是不是該多點幹勁？", "0", "0", "0", "0", "0", "cv_zepar_16", "0", "0"},
[413519] = {413519, 11035, 20, 14, "0", "0", "別在意別在意~活著最重要。", "0", "0", "0", "0", "0", "cv_zepar_17", "0", "0"},
[413520] = {413520, 11035, 21, 15, "0", "0", "呵呵~", "0", "0", "0", "0", "0", "cv_zepar_44", "0", "0"},
[413521] = {413521, 11035, 23, 16, "0", "0", "要好好表現啊~", "0", "0", "0", "0", "0", "cv_zepar_18", "0", "0"},
[413522] = {413522, 11035, 24, 17, "0", "0", "再來一發~", "0", "0", "0", "0", "0", "cv_zepar_20", "0", "0"},
[413523] = {413523, 11035, 25, 18, "0", "0", "人家的厲害之處，好好盯著不要眨眼哦~", "0", "0", "0", "0", "0", "cv_zepar_21", "0", "0"},
[413524] = {413524, 11035, 26, 19, "0", "0", "哈哈…搞砸了啊。", "0", "0", "0", "0", "0", "cv_zepar_19", "0", "0"},
[413525] = {413525, 11035, 27, 20, "0", "0", "領航嗎？真是大膽，但人家不討厭哦。", "0", "0", "0", "0", "0", "cv_zepar_22", "0", "0"},
[413526] = {413526, 11035, 28, 21, "0", "0", "要是當時也有這個設施的話…唉……", "0", "0", "0", "0", "0", "cv_zepar_23", "0", "0"},
[413527] = {413527, 11035, 29, 21, "0", "0", "泡完澡後，人家一定會變得更可愛喲！嘻嘻~想看麼？", "0", "0", "0", "0", "0", "cv_zepar_24", "0", "0"},
[413528] = {413528, 11035, 30, 22, "0", "0", "怎麼啦？", "0", "0", "0", "0", "0", "cv_zepar_25", "0", "0"},
[413529] = {413529, 11035, 31, 23, "0", "0", "猜猜人家是誰！", "0", "0", "0", "0", "0", "cv_zepar_26", "0", "0"},
[413530] = {413530, 11035, 32, 24, "0", "0", "人家可愛的樣子，果然怎麼也忘不掉吧？嘻嘻~", "0", "0", "0", "0", "0", "cv_zepar_27", "0", "0"},
[413531] = {413531, 11035, 33, 25, "0", "0", "哈哈……也是啊…畢竟過去這麼久了嘛……", "0", "0", "0", "0", "0", "cv_zepar_28", "0", "0"},
[413532] = {413532, 11035, 34, 26, "0", "0", "領航可以晚一會再開始工作麼？人家剛打算出去玩來著……不行麼？", "0", "0", "0", "0", "0", "cv_zepar_31", "0", "0"},
[413533] = {413533, 11035, 35, 27, "0", "0", "偶爾也該上一回戰場了。", "0", "0", "0", "0", "0", "cv_zepar_33", "0", "0"},
[413534] = {413534, 11035, 36, 28, "0", "0", "人家不行不行，對手太強了~", "0", "0", "0", "0", "0", "cv_zepar_34", "0", "0"},
[413535] = {413535, 11035, 37, 29, "0", "0", "哇哦，好多人啊…", "0", "0", "0", "0", "0", "cv_zepar_35", "0", "0"},
[413536] = {413536, 11035, 38, 30, "0", "0", "要招到厲害的駕駛員噢！", "0", "0", "0", "0", "0", "cv_zepar_36", "0", "0"},
[413537] = {413537, 11035, 39, 31, "0", "0", "比起裝備更想要休假~", "0", "0", "0", "0", "0", "cv_zepar_37", "0", "0"},
[413538] = {413538, 11035, 40, 32, "0", "0", "要給人家買禮物嗎？", "0", "0", "0", "0", "0", "cv_zepar_38", "0", "0"},
[413539] = {413539, 11035, 41, 33, "0", "0", "領航的資料已經全被人家看光光啦~", "0", "0", "0", "0", "0", "cv_zepar_39", "0", "0"},
[413540] = {413540, 11035, 42, 34, "0", "0", "人家來設置！", "0", "0", "0", "0", "0", "cv_zepar_40", "0", "0"},
[413541] = {413541, 11035, 43, 35, "0", "0", "就讓身為秘書的人家來檢查吧！", "0", "0", "0", "0", "0", "cv_zepar_41", "0", "0"},
[413542] = {413542, 11035, 44, 36, "0", "0", "人家也想一起聊天~", "0", "0", "0", "0", "0", "cv_zepar_42", "0", "0"},
[413543] = {413543, 11035, 45, 37, "0", "0", "真有趣~", "0", "0", "0", "0", "0", "cv_zepar_43", "0", "0"},
[413600] = {413600, 11036, 1, 1, "0", "0", "蒼霧殘響", "0", "0", "0", "0", "0", "cv_puruixiou_1", "0", "0"},
[413601] = {413601, 11036, 2, 2, "0", "0", "真的？終於能更加近距離地觀察你了呢。", "0", "0", "0", "0", "0", "cv_puruixiou_2", "0", "0"},
[413602] = {413602, 11036, 3, 3, "0", "0", "經過計算，你和我相遇的概率是……100%！嘿嘿，開個玩笑。這裡是普瑞席歐，薩哈拉的原罪學者哦~", "0", "0", "0", "0", "0", "cv_puruixiou_3", "0", "0"},
[413603] = {413603, 11036, 4, 4, "0", "idle", "雖說能在這裡觀察你已經很不錯了，但科研的推進過程果然無比漫長，我真想快進到下一個階段，比如說……直接上手開始研究！", "0", "0", "0", "0", "0", "cv_puruixiou_4", "0", "0"},
[413604] = {413604, 11036, 5, 4, "0", "idle", "當你凝視著我，我也正凝視著你哦。對於研究目標，不僅是接觸交流，單純地觀察也很必要。", "0", "0", "0", "0", "0", "cv_puruixiou_5", "0", "0"},
[413605] = {413605, 11036, 6, 4, "0", "idle", "梅貝爾的席位，斯緹菈的精準，墨君的學識，都對製蜜人不可或缺。不過維繫這支小隊的，也絕不僅僅是工作上的便利呢。", "0", "0", "0", "0", "0", "cv_puruixiou_6", "0", "0"},
[413606] = {413606, 11036, 7, 5, "1_》_0_0.8", "level1", "是否萬物皆可測量與計算，連思維也能用數理邏輯加以分析？“七賢”各有答案，而領航你又如何認為呢？對此，我相當感興趣。", "0", "0", "0", "0", "0", "cv_puruixiou_7", "0", "0"},
[413607] = {413607, 11036, 8, 5, "1_》_0_0.8", "level1", "這些“蜂群”？請放心，它們會乖乖遵守我的指令，就像物理學家的儀器、數學家的公式，以及女王的僕從一樣聽話。", "0", "0", "0", "0", "0", "cv_puruixiou_8", "0", "0"},
[413608] = {413608, 11036, 9, 5, "1_》_100_1.5", "level2", "要不要來我的實驗室幫忙做點研究？那些數據與儀器是很貴重沒錯，但是你的話，我可以放心。", "0", "0", "0", "0", "0", "cv_puruixiou_9", "0", "0"},
[413609] = {413609, 11036, 10, 5, "1_》_500_2", "level3", "對哪位駕駛員的身體數據感興趣嗎？我可以將採集方法告訴你哦。欸？想知道我的？唔……那就要看你有沒有本事拿到了呢~", "0", "0", "0", "0", "0", "cv_puruixiou_10", "0", "0"},
[413610] = {413610, 11036, 11, 5, "1_》_1000_2.5", "level4", "最初只是對你的身體感興趣，漸漸的，你人格的構成、情感的運作、思維的奧秘，也開始讓我興致盎然了——這麼難的課題，我已久未遇見過。", "0", "0", "0", "0", "0", "cv_puruixiou_11", "0", "0"},
[413611] = {413611, 11036, 12, 6, "0", "0", "成長，就是逐漸減少可能性的過程。", "0", "0", "0", "0", "0", "cv_puruixiou_12", "0", "0"},
[413612] = {413612, 11036, 13, 7, "0", "0", "量變引起質變呢。", "0", "0", "0", "0", "0", "cv_puruixiou_13", "0", "0"},
[413613] = {413613, 11036, 14, 8, "0", "0", "我會將自己這一成果，署上你的名字，而除此以外的致謝，領航也敬請期待哦。", "0", "0", "0", "0", "0", "cv_puruixiou_14", "0", "0"},
[413614] = {413614, 11036, 15, 9, "0", "0", "“蜂群”在嗡鳴。", "0", "0", "0", "0", "0", "cv_puruixiou_15", "0", "0"},
[413615] = {413615, 11036, 16, 10, "0", "0", "數據猶如花粉，正待我們採集。", "0", "0", "0", "0", "0", "cv_puruixiou_16", "0", "0"},
[413616] = {413616, 11036, 17, 11, "0", "0", "完美結束，新一批經費又有著落了。", "0", "0", "0", "0", "0", "cv_puruixiou_17", "0", "0"},
[413617] = {413617, 11036, 18, 12, "0", "0", "不好也不壞，就像多數時候的實驗一樣。", "0", "0", "0", "0", "0", "cv_puruixiou_18", "0", "0"},
[413618] = {413618, 11036, 19, 13, "0", "0", "與其在這裡氣餒，不如趕緊回去調整一番。", "0", "0", "0", "0", "0", "cv_puruixiou_19", "0", "0"},
[413619] = {413619, 11036, 20, 14, "0", "0", "失敗的數據，與成功同樣珍貴。", "0", "0", "0", "0", "0", "cv_puruixiou_20", "0", "0"},
[413620] = {413620, 11036, 21, 15, "0", "0", "你們的貢獻，我會記得鳴謝。", "0", "0", "0", "0", "0", "cv_puruixiou_21", "0", "0"},
[413621] = {413621, 11036, 23, 16, "0", "0", "採集知識的蜜。", "0", "0", "0", "0", "0", "cv_puruixiou_22", "0", "0"},
[413622] = {413622, 11036, 24, 17, "0", "0", "還沒結束哦。", "0", "0", "0", "0", "0", "cv_puruixiou_23", "0", "0"},
[413623] = {413623, 11036, 25, 18, "0", "0", "“蜂群”集結，急襲目標！", "0", "0", "0", "0", "0", "cv_puruixiou_24", "0", "0"},
[413624] = {413624, 11036, 26, 19, "0", "0", "哎呀，這次失算了。", "0", "0", "0", "0", "0", "cv_puruixiou_26", "0", "0"},
[413625] = {413625, 11036, 27, 20, "0", "0", "我們在此相遇的概率是100%，這是根據直覺，而非計算得出的。", "0", "0", "0", "0", "0", "cv_puruixiou_27", "0", "0"},
[413626] = {413626, 11036, 28, 21, "0", "0", "你是以科研人員的冷峻目光在審視著我，還是帶著其他某種意圖呢？", "0", "0", "0", "0", "0", "cv_puruixiou_28", "0", "0"},
[413627] = {413627, 11036, 29, 21, "0", "0", "這麼毫無意義的時光，就讓它快點結束吧。", "0", "0", "0", "0", "0", "cv_puruixiou_29", "0", "0"},
[413628] = {413628, 11036, 30, 22, "0", "0", "要發生什麼了？", "0", "0", "0", "0", "0", "cv_puruixiou_30", "0", "0"},
[413629] = {413629, 11036, 31, 23, "0", "0", "有趣的環節呢。", "0", "0", "0", "0", "0", "cv_puruixiou_31", "0", "0"},
[413630] = {413630, 11036, 32, 24, "0", "0", "蜜蜂憑嗅覺辨人，領航你又是憑藉什麼呢？", "0", "0", "0", "0", "0", "cv_puruixiou_32", "0", "0"},
[413631] = {413631, 11036, 33, 25, "0", "0", "針對你的錯誤，我真想寫篇論文。", "0", "0", "0", "0", "0", "cv_puruixiou_33", "0", "0"},
[413632] = {413632, 11036, 34, 26, "0", "0", "你好呀，今天狀態如何？身體是否疲憊，注意力夠不夠集中，早上醒來時的生理反應還正常嗎？", "0", "0", "0", "0", "0", "cv_puruixiou_34", "0", "0"},
[413633] = {413633, 11036, 35, 27, "0", "0", "快快出發吧。", "0", "0", "0", "0", "0", "cv_puruixiou_35", "0", "0"},
[413634] = {413634, 11036, 36, 28, "0", "0", "這裡能更安全地採集數據。", "0", "0", "0", "0", "0", "cv_puruixiou_36", "0", "0"},
[413635] = {413635, 11036, 37, 29, "0", "0", "我能研究研究她們嗎？", "0", "0", "0", "0", "0", "cv_puruixiou_37", "0", "0"},
[413636] = {413636, 11036, 38, 30, "0", "0", "新的研究者，抑或小白鼠？", "0", "0", "0", "0", "0", "cv_puruixiou_38", "0", "0"},
[413637] = {413637, 11036, 39, 31, "0", "0", "裝備永遠不嫌多。", "0", "0", "0", "0", "0", "cv_puruixiou_39", "0", "0"},
[413638] = {413638, 11036, 40, 32, "0", "0", "採購時間到。", "0", "0", "0", "0", "0", "cv_puruixiou_40", "0", "0"},
[413639] = {413639, 11036, 41, 33, "0", "0", "都是些流於表面的資訊啊。", "0", "0", "0", "0", "0", "cv_puruixiou_41", "0", "0"},
[413640] = {413640, 11036, 42, 34, "0", "0", "設置就交給你了。", "0", "0", "0", "0", "0", "cv_puruixiou_42", "0", "0"},
[413641] = {413641, 11036, 43, 35, "0", "0", "你的郵箱裡怎麼全是女孩子寫的信？", "0", "0", "0", "0", "0", "cv_puruixiou_43", "0", "0"},
[413642] = {413642, 11036, 44, 36, "0", "0", "少說，多做。", "0", "0", "0", "0", "0", "cv_puruixiou_44", "0", "0"},
[413643] = {413643, 11036, 45, 37, "0", "0", "你去哪？", "0", "0", "0", "0", "0", "cv_puruixiou_45", "0", "0"},
[413700] = {413700, 11037, 1, 1, "0", "0", "蒼霧殘響", "0", "0", "0", "0", "0", "cv_saileixiya_1", "0", "0"},
[413701] = {413701, 11037, 2, 2, "0", "0", "如果您需要的話。", "0", "0", "0", "0", "0", "cv_saileixiya_2", "0", "0"},
[413702] = {413702, 11037, 3, 3, "0", "0", "我的名字是塞蕾希婭，聖濯教會的神職，就任於鐵鴉小隊。願源遠流長之水洗去彼此的不潔。", "0", "0", "0", "0", "0", "cv_saileixiya_3", "0", "0"},
[413703] = {413703, 11037, 4, 4, "0", "idle", "多瑙的天空依然這麼渾濁，霧霾中的每一口呼吸，都像是在浮藻滿佈的湖中溺了水。", "0", "0", "0", "0", "0", "cv_saileixiya_4", "0", "0"},
[413704] = {413704, 11037, 5, 4, "0", "idle", "體型變得巨大，就更容易忽視細微而又無孔不入的汙物，仿佛它們從不存在一樣……", "0", "0", "0", "0", "0", "cv_saileixiya_5", "0", "0"},
[413705] = {413705, 11037, 6, 4, "0", "idle", "萊帕尼隊長染上了迷茫的毒，而我則罹患了偏執的病，偶爾，我們各自的問題在對方身上或許卻成了一種良方。", "0", "0", "0", "0", "0", "cv_saileixiya_6", "0", "0"},
[413706] = {413706, 11037, 7, 5, "1_》_0_0.8", "level1", "領航，您的嘴角有一粒飯，衣服上刮了層灰，還有……褲子拉鏈居然忘了拉上？嘖，實在是有失檢點，我真想親手為您進行一場洗禮。", "0", "0", "0", "0", "0", "cv_saileixiya_7", "0", "0"},
[413707] = {413707, 11037, 8, 5, "1_》_0_0.8", "level1", "在觸碰我之前，您是否好好進行過清潔？啊，我指的不僅是身體上的，也包括心靈。", "0", "0", "0", "0", "0", "cv_saileixiya_8", "0", "0"},
[413708] = {413708, 11037, 9, 5, "1_》_100_1.5", "level2", "我喜歡的事物？纖塵不染的羽毛、鹽晶般澄澈透明的水流、無暇的天空……然而我不確定，這份“喜歡”的情感本身，會不會成為玷污它們的泥。", "0", "0", "0", "0", "0", "cv_saileixiya_9", "0", "0"},
[413709] = {413709, 11037, 10, 5, "1_》_500_2", "level3", "您是說，汙穢也是人類必須背負的罪罰，與其逃避，不如直面並接受？在教會中，我曾聽過類似的教誨，那麼您想讓我承受的汙穢，究竟是什麼呢？", "0", "0", "0", "0", "0", "cv_saileixiya_10", "0", "0"},
[413710] = {413710, 11037, 11, 5, "1_》_1000_2.5", "level4", "最近我愈發感到，自己已無法處理內心氾濫成災的那份骯髒汙濁的思緒……領航，您能夠以您的力量、您的方式，為我淨化深植於心的不潔嗎？", "0", "0", "0", "0", "0", "cv_saileixiya_11", "0", "0"},
[413711] = {413711, 11037, 12, 6, "0", "0", "不錯的感覺。", "0", "0", "0", "0", "0", "cv_saileixiya_12", "0", "0"},
[413712] = {413712, 11037, 13, 7, "0", "0", "我不討厭這種事。", "0", "0", "0", "0", "0", "cv_saileixiya_13", "0", "0"},
[413713] = {413713, 11037, 14, 8, "0", "0", "我希望自己不僅是力量變得強大，心靈也依舊堅如鑽石，不被外物侵蝕，依舊保持自身的光輝。", "0", "0", "0", "0", "0", "cv_saileixiya_14", "0", "0"},
[413714] = {413714, 11037, 15, 9, "0", "0", "更加運用自如。", "0", "0", "0", "0", "0", "cv_saileixiya_15", "0", "0"},
[413715] = {413715, 11037, 16, 10, "0", "0", "消殺這些毒物。", "0", "0", "0", "0", "0", "cv_saileixiya_16", "0", "0"},
[413716] = {413716, 11037, 17, 11, "0", "0", "每次戰鬥都該像這樣結束。", "0", "0", "0", "0", "0", "cv_saileixiya_17", "0", "0"},
[413717] = {413717, 11037, 18, 12, "0", "0", "還差一點，再接再厲。", "0", "0", "0", "0", "0", "cv_saileixiya_18", "0", "0"},
[413718] = {413718, 11037, 19, 13, "0", "0", "也許完全潰敗都比這樣要好。", "0", "0", "0", "0", "0", "cv_saileixiya_19", "0", "0"},
[413719] = {413719, 11037, 20, 14, "0", "0", "我無法忍受這種結果……", "0", "0", "0", "0", "0", "cv_saileixiya_20", "0", "0"},
[413720] = {413720, 11037, 21, 15, "0", "0", "枯涸。", "0", "0", "0", "0", "0", "cv_saileixiya_21", "0", "0"},
[413721] = {413721, 11037, 23, 16, "0", "0", "滌除。", "0", "0", "0", "0", "0", "cv_saileixiya_22", "0", "0"},
[413722] = {413722, 11037, 24, 17, "0", "0", "洞見。", "0", "0", "0", "0", "0", "cv_saileixiya_23", "0", "0"},
[413723] = {413723, 11037, 26, 19, "0", "0", "不甘心……", "0", "0", "0", "0", "0", "cv_saileixiya_25", "0", "0"},
[413724] = {413724, 11037, 27, 20, "0", "0", "終於到了最讓人安心的地方。", "0", "0", "0", "0", "0", "cv_saileixiya_26", "0", "0"},
[413725] = {413725, 11037, 28, 21, "0", "0", "怎麼了？沒事的話，還請不要停下動作，許多地方都還沒被您顧及。", "0", "0", "0", "0", "0", "cv_saileixiya_27", "0", "0"},
[413726] = {413726, 11037, 29, 21, "0", "0", "在這洗滌身心的場合……領航您不會在思考某些不潔之事吧？", "0", "0", "0", "0", "0", "cv_saileixiya_28", "0", "0"},
[413727] = {413727, 11037, 30, 22, "0", "0", "還待更多。", "0", "0", "0", "0", "0", "cv_saileixiya_29", "0", "0"},
[413728] = {413728, 11037, 31, 23, "0", "0", "這種遊戲……有什麼意義嗎？", "0", "0", "0", "0", "0", "cv_saileixiya_30", "0", "0"},
[413729] = {413729, 11037, 32, 24, "0", "0", "您真的想要的話，我就誇獎你一句吧。", "0", "0", "0", "0", "0", "cv_saileixiya_31", "0", "0"},
[413730] = {413730, 11037, 33, 25, "0", "0", "看來您的判斷被某些汙物幹擾了。", "0", "0", "0", "0", "0", "cv_saileixiya_32", "0", "0"},
[413731] = {413731, 11037, 34, 26, "0", "0", "您回來了，在不潔的此世牢籠中，讓我們今天也保持身心的純粹吧。", "0", "0", "0", "0", "0", "cv_saileixiya_33", "0", "0"},
[413732] = {413732, 11037, 35, 27, "0", "0", "淨化必不可懈怠。", "0", "0", "0", "0", "0", "cv_saileixiya_34", "0", "0"},
[413733] = {413733, 11037, 36, 28, "0", "0", "不會沾血的活動。", "0", "0", "0", "0", "0", "cv_saileixiya_35", "0", "0"},
[413734] = {413734, 11037, 37, 29, "0", "0", "有不愛乾淨的人呢……", "0", "0", "0", "0", "0", "cv_saileixiya_36", "0", "0"},
[413735] = {413735, 11037, 38, 30, "0", "0", "我會隨您一同迎接。", "0", "0", "0", "0", "0", "cv_saileixiya_37", "0", "0"},
[413736] = {413736, 11037, 39, 31, "0", "0", "不腐之物。", "0", "0", "0", "0", "0", "cv_saileixiya_38", "0", "0"},
[413737] = {413737, 11037, 40, 32, "0", "0", "貪慾也是種毒素。", "0", "0", "0", "0", "0", "cv_saileixiya_39", "0", "0"},
[413738] = {413738, 11037, 41, 33, "0", "0", "還算整潔。", "0", "0", "0", "0", "0", "cv_saileixiya_40", "0", "0"},
[413739] = {413739, 11037, 42, 34, "0", "0", "請您慢慢調整。", "0", "0", "0", "0", "0", "cv_saileixiya_41", "0", "0"},
[413740] = {413740, 11037, 43, 35, "0", "0", "我會閉上眼。", "0", "0", "0", "0", "0", "cv_saileixiya_42", "0", "0"},
[413741] = {413741, 11037, 44, 36, "0", "0", "言語也有乾淨汙俗之分。", "0", "0", "0", "0", "0", "cv_saileixiya_43", "0", "0"},
[413742] = {413742, 11037, 45, 37, "0", "0", "最好不要亂碰。", "0", "0", "0", "0", "0", "cv_saileixiya_44", "0", "0"},
[413800] = {413800, 11038, 1, 1, "0", "0", "蒼霧殘響", "0", "0", "0", "0", "0", "cv_kafuka_1", "0", "0"},
[413801] = {413801, 11038, 2, 2, "0", "0", "哈？你覺得我適合做這個？", "0", "0", "0", "0", "0", "cv_kafuka_2", "0", "0"},
[413802] = {413802, 11038, 3, 3, "0", "0", "我是“歧花”小隊的卡芙卡，如你所見是個所謂的不良，想讓我乖乖聽話可不簡單，你應該做好心理準備了吧？", "0", "0", "0", "0", "0", "cv_kafuka_3", "0", "0"},
[413803] = {413803, 11038, 4, 4, "0", "idle", "感覺地上的人群就像垃圾一樣……這句台詞老早就想說了。", "0", "0", "0", "0", "0", "cv_kafuka_4", "0", "0"},
[413804] = {413804, 11038, 5, 4, "0", "idle", "難得你這麼安靜，明明平時那麼喜歡羅裡吧嗦個不停，該不會是終於對我死心了？", "0", "0", "0", "0", "0", "cv_kafuka_5", "0", "0"},
[413805] = {413805, 11038, 6, 4, "0", "idle", "老實說，我感覺自己已經算小隊裡最安分守己的了，其他人要麼帶手槍上學、要麼用虛擬身份，還有一個笨蛋戀愛腦……真是一個比一個有意思。", "0", "0", "0", "0", "0", "cv_kafuka_6", "0", "0"},
[413806] = {413806, 11038, 7, 5, "1_》_0_0.8", "level1", "駕駛員這種被一堆條條框框束縛的存在，要不是情非得已，我才不想當呢。", "0", "0", "0", "0", "0", "cv_kafuka_7", "0", "0"},
[413807] = {413807, 11038, 8, 5, "1_》_0_0.8", "level1", "都是這種身高差了，就不用執著於摸我頭了吧……竟然還特意搬個雲梯過來，該誇你執行力驚人嗎？", "0", "0", "0", "0", "0", "cv_kafuka_8", "0", "0"},
[413808] = {413808, 11038, 9, 5, "1_》_100_1.5", "level2", "看你也總是對其他駕駛員摸來摸去的，這算是一種示好嗎？如果是在欺負人我可不會坐視不管。", "0", "0", "0", "0", "0", "cv_kafuka_9", "0", "0"},
[413809] = {413809, 11038, 10, 5, "1_》_500_2", "level3", "即使到現在，比起當駕駛員我也還是更想開一家街機廳。不過……有你在的話倒也不是那麼無聊了。", "0", "0", "0", "0", "0", "cv_kafuka_10", "0", "0"},
[413810] = {413810, 11038, 11, 5, "1_》_1000_2.5", "level4", "剛剛臭老爹又打電話來問我狀況了，問東問西的真煩人啊，甚至還擔心我在外談戀愛，乾脆……讓領航你來假扮一下戀人，幫忙氣一氣他好了。", "0", "0", "0", "0", "0", "cv_kafuka_11", "0", "0"},
[413811] = {413811, 11038, 12, 6, "0", "0", "有勞你了。", "0", "0", "0", "0", "0", "cv_kafuka_12", "0", "0"},
[413812] = {413812, 11038, 13, 7, "0", "0", "用街機的說法，就是刷新記錄了。", "0", "0", "0", "0", "0", "cv_kafuka_13", "0", "0"},
[413813] = {413813, 11038, 14, 8, "0", "0", "畢竟我是不愛廢話的性格，除了一聲“謝謝”外，就讓我用更實在的方式回報你吧。", "0", "0", "0", "0", "0", "cv_kafuka_14", "0", "0"},
[413814] = {413814, 11038, 15, 9, "0", "0", "很好，拳頭更硬了。", "0", "0", "0", "0", "0", "cv_kafuka_15", "0", "0"},
[413815] = {413815, 11038, 16, 10, "0", "0", "就拿它們來發洩不滿吧。", "0", "0", "0", "0", "0", "cv_kafuka_16", "0", "0"},
[413816] = {413816, 11038, 17, 11, "0", "0", "哼，小菜一碟。", "0", "0", "0", "0", "0", "cv_kafuka_17", "0", "0"},
[413817] = {413817, 11038, 18, 12, "0", "0", "勉勉強強吧。", "0", "0", "0", "0", "0", "cv_kafuka_18", "0", "0"},
[413818] = {413818, 11038, 19, 13, "0", "0", "下次得以牙還牙。", "0", "0", "0", "0", "0", "cv_kafuka_19", "0", "0"},
[413819] = {413819, 11038, 20, 14, "0", "0", "可不能連怪物都踩在我頭上。", "0", "0", "0", "0", "0", "cv_kafuka_20", "0", "0"},
[413820] = {413820, 11038, 21, 15, "0", "0", "不自量力。", "0", "0", "0", "0", "0", "cv_kafuka_21", "0", "0"},
[413821] = {413821, 11038, 23, 16, "0", "0", "看招！", "0", "0", "0", "0", "0", "cv_kafuka_23", "0", "0"},
[413822] = {413822, 11038, 24, 17, "0", "0", "閉嘴吧！", "0", "0", "0", "0", "0", "cv_kafuka_24", "0", "0"},
[413823] = {413823, 11038, 26, 19, "0", "0", "真想“續關”啊……", "0", "0", "0", "0", "0", "cv_kafuka_25", "0", "0"},
[413824] = {413824, 11038, 27, 20, "0", "0", "你來了？剛才本來還有個駕駛員，一看我進來就被嚇跑了。", "0", "0", "0", "0", "0", "cv_kafuka_26", "0", "0"},
[413825] = {413825, 11038, 28, 21, "0", "0", "你會在浴室裡唱歌嗎？我雖然會，但旁邊有人的話還是算了。", "0", "0", "0", "0", "0", "cv_kafuka_27", "0", "0"},
[413826] = {413826, 11038, 29, 21, "0", "0", "有次我在學校浴室裡和其他學生打架，但地太滑，誰也沒打贏誰。", "0", "0", "0", "0", "0", "cv_kafuka_28", "0", "0"},
[413827] = {413827, 11038, 30, 22, "0", "0", "這是啥。", "0", "0", "0", "0", "0", "cv_kafuka_29", "0", "0"},
[413828] = {413828, 11038, 31, 23, "0", "0", "這遊戲還真是幼稚……", "0", "0", "0", "0", "0", "cv_kafuka_30", "0", "0"},
[413829] = {413829, 11038, 32, 24, "0", "0", "好好好，給你誇誇。", "0", "0", "0", "0", "0", "cv_kafuka_31", "0", "0"},
[413830] = {413830, 11038, 33, 25, "0", "0", "你是故意猜錯想看我反應吧。", "0", "0", "0", "0", "0", "cv_kafuka_32", "0", "0"},
[413831] = {413831, 11038, 34, 26, "0", "0", "早啊，睡醒了嗎？沒睡醒的話我用拳頭幫你一下？", "0", "0", "0", "0", "0", "cv_kafuka_33", "0", "0"},
[413832] = {413832, 11038, 35, 27, "0", "0", "去找沙包們玩吧。", "0", "0", "0", "0", "0", "cv_kafuka_34", "0", "0"},
[413833] = {413833, 11038, 36, 28, "0", "0", "可別說我欺負弱小。", "0", "0", "0", "0", "0", "cv_kafuka_35", "0", "0"},
[413834] = {413834, 11038, 37, 29, "0", "0", "她們好像很開心。", "0", "0", "0", "0", "0", "cv_kafuka_36", "0", "0"},
[413835] = {413835, 11038, 38, 30, "0", "0", "又要有新人啊。", "0", "0", "0", "0", "0", "cv_kafuka_37", "0", "0"},
[413836] = {413836, 11038, 39, 31, "0", "0", "能自己改造裝備嗎？", "0", "0", "0", "0", "0", "cv_kafuka_38", "0", "0"},
[413837] = {413837, 11038, 40, 32, "0", "0", "貨差的話我不付錢哦。", "0", "0", "0", "0", "0", "cv_kafuka_39", "0", "0"},
[413838] = {413838, 11038, 41, 33, "0", "0", "普普通通嘛。", "0", "0", "0", "0", "0", "cv_kafuka_40", "0", "0"},
[413839] = {413839, 11038, 42, 34, "0", "0", "你在鼓搗什麼？", "0", "0", "0", "0", "0", "cv_kafuka_41", "0", "0"},
[413840] = {413840, 11038, 43, 35, "0", "0", "好多字，真麻煩。", "0", "0", "0", "0", "0", "cv_kafuka_42", "0", "0"},
[413841] = {413841, 11038, 44, 36, "0", "0", "我更喜歡發語音。", "0", "0", "0", "0", "0", "cv_kafuka_43", "0", "0"},
[413842] = {413842, 11038, 45, 37, "0", "0", "啊？", "0", "0", "0", "0", "0", "cv_kafuka_44", "0", "0"},
[413900] = {413900, 11039, 1, 1, "0", "0", "蒼霧殘響", "0", "0", "0", "0", "0", "cv_sikadi_vd_01", "0", "0"},
[413901] = {413901, 11039, 2, 2, "0", "0", "你選擇了吾，吾也會回應你的呼喚。", "0", "0", "0", "0", "0", "cv_sikadi_vd_02", "0", "0"},
[413902] = {413902, 11039, 3, 3, "0", "0", "吾感受到了，已經抑制不住的黑暗力量，隨著奇跡之月升起而復蘇。別擔心，吾會以全新的姿態保護你的，領航。", "0", "0", "0", "0", "0", "cv_sikadi_vd_03", "0", "0"},
[413903] = {413903, 11039, 4, 4, "0", "idle", "這就是影之國女王的新形態，吾決定就叫它王之形態其三。因為受到大家鼓動的情緒而誕生……這樣子說是不是很酷！", "0", "0", "0", "0", "0", "cv_sikadi_vd_04", "0", "0"},
[413904] = {413904, 11039, 5, 4, "0", "idle", "哈——哈——哈——吾在黑暗的禁區中聽見了，我聽見了——領航你現在在心中想著吾的事情吧！……誒？沒，沒有嗎？……那就是以前想了，吾現在才收到！", "0", "0", "0", "0", "0", "cv_sikadi_vd_05", "0", "0"},
[413905] = {413905, 11039, 6, 4, "0", "idle", "“巧克力……都是醜陋的怪物。”你覺得這句臺詞怎麼樣？我打算把它用在《影之國編年史3》裡，當女騎士被千夫所指時說了這句話。", "0", "0", "0", "0", "0", "cv_sikadi_vd_06", "0", "0"},
[413906] = {413906, 11039, 7, 5, "1_》_0_0.8", "level1", "吾乃吸食血液而活的吸血鬼魅魔王女，但是現在只要巧克力就足夠了，快點把巧克力交給吾！", "0", "0", "0", "0", "0", "cv_sikadi_vd_07", "0", "0"},
[413907] = {413907, 11039, 8, 5, "1_》_0_0.8", "level1", "領航，你看你看，和泳裝一樣可以看到肚臍眼哦……咦，但是又和穿泳裝的時候不一樣……現在被領航一直盯著看的話，吾有點……不要……領航還是別看了！", "0", "0", "0", "0", "0", "cv_sikadi_vd_08", "0", "0"},
[413908] = {413908, 11039, 9, 5, "1_》_100_1.5", "level2", "即使被再殘酷的命運所愚弄，吾也會找到你的。吾會找到你向你訴說，在沒有你的日子裡吾是多麼無趣。", "0", "0", "0", "0", "0", "cv_sikadi_vd_09", "0", "0"},
[413909] = {413909, 11039, 10, 5, "1_》_500_2", "level3", "嗯，吾剛剛想到……無論是歡笑著暢聊未來的日子，還是忐忑著躲避莉莉絲的日子，都與領航息息相關呢，你永遠在這裡真是太好了。", "0", "0", "0", "0", "0", "cv_sikadi_vd_10", "0", "0"},
