[414100] = {414100, 11041, 1, 1, "0", "0", "蒼霧殘響。", "0", "0", "0", "0", "0", "cv_zhinvxing_1", "0", "0"},
[414101] = {414101, 11041, 2, 2, "0", "0", "正好我現在等調查結果，也沒什麼事可做，就應你邀請，來體驗一下多瑙駕駛員的日常工作吧。", "0", "0", "0", "0", "0", "cv_zhinvxing_2", "0", "0"},
[414102] = {414102, 11041, 3, 3, "0", "0", "哦？你就是柯朗吹捧的那位領航？那麼重新自我介紹一下。代號織女星，隸屬於伊斯坎瓦亞，來自印加地區。", "0", "0", "0", "0", "0", "cv_zhinvxing_3", "0", "0"},
[414103] = {414103, 11041, 4, 4, "0", "idle", "多瑙真是個好地方啊。最難能可貴的是，這裏非常有人情味。", "0", "0", "0", "0", "0", "cv_zhinvxing_4", "0", "0"},
[414104] = {414104, 11041, 5, 4, "0", "idle", "休息也是備戰的一環。你很懂嘛。", "0", "0", "0", "0", "0", "cv_zhinvxing_5", "0", "0"},
[414105] = {414105, 11041, 6, 4, "0", "idle", "嘿。如果覺得困了，就回房間睡覺，別在這裏硬撐。", "0", "0", "0", "0", "0", "cv_zhinvxing_6", "0", "0"},
[414106] = {414106, 11041, 7, 5, "1_》_0_0.8", "level1", "答應我，如果看到了可疑的、能裝下一個人的貨物箱，一定要在第一時間聯繫我。為了你的人身安全，絕對不要擅自打開。", "0", "0", "0", "0", "0", "cv_zhinvxing_7", "0", "0"},
[414107] = {414107, 11041, 8, 5, "1_》_0_0.8", "level1", "蘇亞娜？你想叫我本名是無妨，但不要在戰場上這樣稱呼。畢竟我們在這方面是有規章制度需要遵守的。", "0", "0", "0", "0", "0", "cv_zhinvxing_8", "0", "0"},
[414108] = {414108, 11041, 9, 5, "1_》_100_1.5", "level2", "當初會起“織女星”這個代號，只是為了借此警示自己，不要再輕信他人。至於現在嘛……如果可以，我想要將它還回去。可惜代號一經確定，就不允許修改了。", "0", "0", "0", "0", "0", "cv_zhinvxing_9", "0", "0"},
[414109] = {414109, 11041, 10, 5, "1_》_500_2", "level3", "我聽說你的那位情報官，其實是你妹妹。能得到家人的支持……真令人羡慕啊。", "0", "0", "0", "0", "0", "cv_zhinvxing_10", "0", "0"},
[414110] = {414110, 11041, 11, 5, "1_》_1000_2.5", "level4", "現如今想想，如果那對夫婦能有你的一半好，我也不至於……欸，突然想到了個好主意。反正你與你的家人們都沒有血緣關係，那麼再加我一個也沒問題？別急著拒絕，你再考慮考慮？", "0", "0", "0", "0", "0", "cv_zhinvxing_11", "0", "0"},
[414111] = {414111, 11041, 12, 6, "0", "0", "我這邊也會奉上誠意回報的。", "0", "0", "0", "0", "0", "cv_zhinvxing_12", "0", "0"},
[414112] = {414112, 11041, 13, 7, "0", "0", "居然會把難得的資源用在非嫡系的駕駛員身上……你還真是個怪人。", "0", "0", "0", "0", "0", "cv_zhinvxing_13", "0", "0"},
[414113] = {414113, 11041, 14, 8, "0", "0", "到這份上，如果再不意思一下，就顯得我這人有些小氣了。所以來約定吧。等以後你來印加了，雖然沒法保證讓你橫著走，但只要是能幫上忙的，我都不會拒絕。", "0", "0", "0", "0", "0", "cv_zhinvxing_14", "0", "0"},
[414114] = {414114, 11041, 15, 9, "0", "0", "設備升級？費用還是你來出？多瑙這邊的駕駛員待遇也太好了吧？！", "0", "0", "0", "0", "0", "cv_zhinvxing_15", "0", "0"},
[414115] = {414115, 11041, 16, 10, "0", "0", "說吧，需要我幫忙爭取多少撤退時間？", "0", "0", "0", "0", "0", "cv_zhinvxing_16", "0", "0"},
[414116] = {414116, 11041, 17, 11, "0", "0", "喲吼，大獲全勝？你這傢夥很行嘛。", "0", "0", "0", "0", "0", "cv_zhinvxing_17", "0", "0"},
[414117] = {414117, 11041, 18, 12, "0", "0", "這點小傷不礙事。下一個戰場在哪裡？", "0", "0", "0", "0", "0", "cv_zhinvxing_18", "0", "0"},
[414118] = {414118, 11041, 19, 13, "0", "0", "幸好你有先見之明，在開戰之前先通知其他隊伍疏散了群眾。", "0", "0", "0", "0", "0", "cv_zhinvxing_19", "0", "0"},
[414119] = {414119, 11041, 20, 14, "0", "0", "你難道是想安慰我？哈哈，不需要，這種失敗我早就習慣了。", "0", "0", "0", "0", "0", "cv_zhinvxing_20", "0", "0"},
[414120] = {414120, 11041, 21, 15, "0", "0", "呵，連我都打不過。", "0", "0", "0", "0", "0", "cv_zhinvxing_21", "0", "0"},
[414121] = {414121, 11041, 23, 16, "0", "0", "由我來牽制他們。", "0", "0", "0", "0", "0", "cv_zhinvxing_23", "0", "0"},
[414122] = {414122, 11041, 24, 17, "0", "0", "這就是你的決斷嗎？", "0", "0", "0", "0", "0", "cv_zhinvxing_24", "0", "0"},
[414123] = {414123, 11041, 26, 19, "0", "0", "應該爭取到足夠的時間了……", "0", "0", "0", "0", "0", "cv_zhinvxing_26", "0", "0"},
[414124] = {414124, 11041, 27, 20, "0", "0", "不管第幾次來，都接受不了啊……為什麼“維修池”會就在你的辦公室下麵？", "0", "0", "0", "0", "0", "cv_zhinvxing_27", "0", "0"},
[414125] = {414125, 11041, 28, 21, "0", "0", "沒想到……巨大化之後還能像這樣躺在池子裡泡澡，真不可思議。", "0", "0", "0", "0", "0", "cv_zhinvxing_28", "0", "0"},
[414126] = {414126, 11041, 29, 21, "0", "0", "……任何駕駛員都可以在這裡使用你的維修池嗎？為什麼說是你的維修池？因為這裡除了你和我外沒有別人了呀。", "0", "0", "0", "0", "0", "cv_zhinvxing_29", "0", "0"},
[414127] = {414127, 11041, 30, 22, "0", "0", "動手吧。我已經準備好了。", "0", "0", "0", "0", "0", "cv_zhinvxing_30", "0", "0"},
[414128] = {414128, 11041, 31, 23, "0", "0", "我聽說過這個環節。", "0", "0", "0", "0", "0", "cv_zhinvxing_31", "0", "0"},
[414129] = {414129, 11041, 32, 24, "0", "0", "果然難不倒你。", "0", "0", "0", "0", "0", "cv_zhinvxing_32", "0", "0"},
[414130] = {414130, 11041, 33, 25, "0", "0", "別介意，猜不出來也正常。誰讓我是外地人呢。", "0", "0", "0", "0", "0", "cv_zhinvxing_33", "0", "0"},
[414131] = {414131, 11041, 34, 26, "0", "0", "喲，又見面了。今天你的眼神也很不錯，能看到一名戰士該有的堅韌。", "0", "0", "0", "0", "0", "cv_zhinvxing_34", "0", "0"},
[414132] = {414132, 11041, 35, 27, "0", "0", "終於有機會見識一下你的特殊能力了。", "0", "0", "0", "0", "0", "cv_zhinvxing_35", "0", "0"},
[414133] = {414133, 11041, 36, 28, "0", "0", "演習？也就是自己人跟自己人打？有點意思。", "0", "0", "0", "0", "0", "cv_zhinvxing_36", "0", "0"},
[414134] = {414134, 11041, 37, 29, "0", "0", "能看出來，那些駕駛員都很仰慕你。", "0", "0", "0", "0", "0", "cv_zhinvxing_37", "0", "0"},
[414135] = {414135, 11041, 38, 30, "0", "0", "在你眼中，駕駛員究竟是什麼？", "0", "0", "0", "0", "0", "cv_zhinvxing_38", "0", "0"},
[414136] = {414136, 11041, 39, 31, "0", "0", "這些裝備都可以試用？", "0", "0", "0", "0", "0", "cv_zhinvxing_39", "0", "0"},
[414137] = {414137, 11041, 40, 32, "0", "0", "不愧是艾吉斯，員工價的折扣就是大。", "0", "0", "0", "0", "0", "cv_zhinvxing_40", "0", "0"},
[414138] = {414138, 11041, 41, 33, "0", "0", "獎章不少嘛你。", "0", "0", "0", "0", "0", "cv_zhinvxing_41", "0", "0"},
[414139] = {414139, 11041, 42, 34, "0", "0", "這外掛程式的靜音效果不錯啊。", "0", "0", "0", "0", "0", "cv_zhinvxing_42", "0", "0"},
[414140] = {414140, 11041, 43, 35, "0", "0", "又是公事？你可真是有夠忙的。", "0", "0", "0", "0", "0", "cv_zhinvxing_43", "0", "0"},
[414141] = {414141, 11041, 44, 36, "0", "0", "匿名聊天啊……你最好小心一點，別透露自己的個人隱私。", "0", "0", "0", "0", "0", "cv_zhinvxing_44", "0", "0"},
[414142] = {414142, 11041, 45, 37, "0", "0", "這是什麼高科技？", "0", "0", "0", "0", "0", "cv_zhinvxing_45", "0", "0"},
[414200] = {414200, 11042, 1, 1, "0", "0", "蒼霧殘響！", "0", "0", "0", "0", "0", "cv_hailuo_1", "0", "0"},
[414201] = {414201, 11042, 2, 2, "0", "0", "我來啦！把事情都交給我吧，絕對不會出錯的，嘿嘿。", "0", "0", "0", "0", "0", "cv_hailuo_2", "0", "0"},
[414202] = {414202, 11042, 3, 3, "0", "0", "我是前線的海蘿！海蘿·特裡亞@#￥%……記不得啦，總之叫我海蘿就好！", "0", "0", "0", "0", "0", "cv_hailuo_3", "0", "0"},
[414203] = {414203, 11042, 4, 4, "0", "idle", "不開心的時候只要去跑步就好了！陽光照在身上，風打在臉上，什麼煩惱都會忘了！", "0", "0", "0", "0", "0", "cv_hailuo_4", "0", "0"},
[414204] = {414204, 11042, 5, 4, "0", "idle", "這是今天要做的事情……這是明天要做的事情……OK，已經全部記下來了……嗯，話說今天是幾號……啊！這不是全部錯過了嗎！", "0", "0", "0", "0", "0", "cv_hailuo_5", "0", "0"},
[414205] = {414205, 11042, 6, 4, "0", "idle", "星爍……她那樣子真讓人擔心……啊，我不是說她的外表，是說她的精神狀態，總感覺她好像隨時都會爆炸一樣……彭！啪嗒！我很擔心她。", "0", "0", "0", "0", "0", "cv_hailuo_6", "0", "0"},
[414206] = {414206, 11042, 7, 5, "1_》_0_0.8", "level1", "我沒有想要實現的事情，就算有也肯定很快就忘記吧，但是我會努力幫其他人實現夢想的，為此就算一直戰鬥下去也沒關係！", "0", "0", "0", "0", "0", "cv_hailuo_7", "0", "0"},
[414207] = {414207, 11042, 8, 5, "1_》_0_0.8", "level1", "領航，重要的約定一定要寫在紙上，因為人的記憶是不可靠的！", "0", "0", "0", "0", "0", "cv_hailuo_8", "0", "0"},
[414208] = {414208, 11042, 9, 5, "1_》_100_1.5", "level2", "即使記不住重要的人的名字也沒關係，因為那份感情和回憶一直會存在我和領航的心裡的！", "0", "0", "0", "0", "0", "cv_hailuo_9", "0", "0"},
[414209] = {414209, 11042, 10, 5, "1_》_500_2", "level3", "領航也失憶過嗎？我懂的我懂的，那種想不起來重要事情的感覺特別難受吧。不過只要我們還活著，還能向著未來前進，我們總能找回當初忘掉的事情的！", "0", "0", "0", "0", "0", "cv_hailuo_10", "0", "0"},
[414210] = {414210, 11042, 11, 5, "1_》_1000_2.5", "level4", "哼哼，作為記性不好的病友，領航要是遇到了什麼困擾就儘管和我傾訴吧，我不管什麼時候都會陪伴你在身邊的，就算是睡覺時候也會的！洗澡的時候……我不介意！", "0", "0", "0", "0", "0", "cv_hailuo_11", "0", "0"},
[414211] = {414211, 11042, 12, 6, "0", "0", "花了好多錢！", "0", "0", "0", "0", "0", "cv_hailuo_12", "0", "0"},
[414212] = {414212, 11042, 13, 7, "0", "0", "我會更努力的~", "0", "0", "0", "0", "0", "cv_hailuo_13", "0", "0"},
[414213] = {414213, 11042, 14, 8, "0", "0", "感覺不會再輸給任何人了。", "0", "0", "0", "0", "0", "cv_hailuo_14", "0", "0"},
[414214] = {414214, 11042, 15, 9, "0", "0", "不用考試就好。", "0", "0", "0", "0", "0", "cv_hailuo_15", "0", "0"},
[414215] = {414215, 11042, 16, 10, "0", "0", "無畏前線，無畏前行！", "0", "0", "0", "0", "0", "cv_hailuo_16", "0", "0"},
[414216] = {414216, 11042, 17, 11, "0", "0", "贏啦！請為我們的精彩發揮鼓掌吧！", "0", "0", "0", "0", "0", "cv_hailuo_17", "0", "0"},
[414217] = {414217, 11042, 18, 12, "0", "0", "就算是新人，也不容小覷！", "0", "0", "0", "0", "0", "cv_hailuo_18", "0", "0"},
[414218] = {414218, 11042, 19, 13, "0", "0", "呼，出了好多汗！", "0", "0", "0", "0", "0", "cv_hailuo_19", "0", "0"},
[414219] = {414219, 11042, 20, 14, "0", "0", "搞砸了……", "0", "0", "0", "0", "0", "cv_hailuo_20", "0", "0"},
[414220] = {414220, 11042, 21, 15, "0", "0", "啪嗒！", "0", "0", "0", "0", "0", "cv_hailuo_21", "0", "0"},
[414221] = {414221, 11042, 23, 16, "0", "0", "看招！", "0", "0", "0", "0", "0", "cv_hailuo_23", "0", "0"},
[414222] = {414222, 11042, 24, 17, "0", "0", "還有一招！", "0", "0", "0", "0", "0", "cv_hailuo_24", "0", "0"},
[414223] = {414223, 11042, 25, 18, "0", "0", "讓你飛起來吧！", "0", "0", "0", "0", "0", "cv_hailuo_25", "0", "0"},
[414224] = {414224, 11042, 26, 19, "0", "0", "不太妙……大家要平安呀……", "0", "0", "0", "0", "0", "cv_hailuo_26", "0", "0"},
[414225] = {414225, 11042, 27, 20, "0", "0", "領航，一起來洗澡吧！", "0", "0", "0", "0", "0", "cv_hailuo_27", "0", "0"},
[414226] = {414226, 11042, 28, 21, "0", "0", "嗯……領航？你什麼時候在的？一開始就在嗎？誒嘿，我忘記了~！", "0", "0", "0", "0", "0", "cv_hailuo_28", "0", "0"},
[414227] = {414227, 11042, 29, 21, "0", "0", "身體好暖和……就像在曬太陽一樣，真舒服，嘿嘿。", "0", "0", "0", "0", "0", "cv_hailuo_29", "0", "0"},
[414228] = {414228, 11042, 30, 22, "0", "0", "沒、沒事吧？！", "0", "0", "0", "0", "0", "cv_hailuo_30", "0", "0"},
[414229] = {414229, 11042, 31, 23, "0", "0", "我是……誰？", "0", "0", "0", "0", "0", "cv_hailuo_31", "0", "0"},
[414230] = {414230, 11042, 32, 24, "0", "0", "我都差點想不起來我是誰啦！", "0", "0", "0", "0", "0", "cv_hailuo_32", "0", "0"},
[414231] = {414231, 11042, 33, 25, "0", "0", "我也沒想起來，哈哈~", "0", "0", "0", "0", "0", "cv_hailuo_33", "0", "0"},
[414232] = {414232, 11042, 34, 26, "0", "0", "噢，領航，你來啦，要一起曬太陽嗎？今天的太陽光可是完美陽光哦。", "0", "0", "0", "0", "0", "cv_hailuo_34", "0", "0"},
[414233] = {414233, 11042, 35, 27, "0", "0", "今天要去的地方是……哪裡來著？對了，我們要做什麼？", "0", "0", "0", "0", "0", "cv_hailuo_35", "0", "0"},
[414234] = {414234, 11042, 36, 28, "0", "0", "只要不用記東西的話，我誰都不會輸的！", "0", "0", "0", "0", "0", "cv_hailuo_36", "0", "0"},
[414235] = {414235, 11042, 37, 29, "0", "0", "哇哇哇，好多人，我記不住名字的啦……", "0", "0", "0", "0", "0", "cv_hailuo_37", "0", "0"},
[414236] = {414236, 11042, 38, 30, "0", "0", "新人？我要當前輩了？", "0", "0", "0", "0", "0", "cv_hailuo_38", "0", "0"},
[414237] = {414237, 11042, 39, 31, "0", "0", "我更加信賴自己的拳頭！", "0", "0", "0", "0", "0", "cv_hailuo_39", "0", "0"},
[414238] = {414238, 11042, 40, 32, "0", "0", "眼睛看不過來了！", "0", "0", "0", "0", "0", "cv_hailuo_40", "0", "0"},
[414239] = {414239, 11042, 41, 33, "0", "0", "領航的名字是……我記住啦！", "0", "0", "0", "0", "0", "cv_hailuo_41", "0", "0"},
[414240] = {414240, 11042, 42, 34, "0", "0", "設置~", "0", "0", "0", "0", "0", "cv_hailuo_42", "0", "0"},
[414241] = {414241, 11042, 43, 35, "0", "0", "好記性不如爛筆頭~", "0", "0", "0", "0", "0", "cv_hailuo_43", "0", "0"},
[414242] = {414242, 11042, 44, 36, "0", "0", "我是來自切斯頓的海蘿！", "0", "0", "0", "0", "0", "cv_hailuo_44", "0", "0"},
[414243] = {414243, 11042, 45, 37, "0", "0", "咋啦？", "0", "0", "0", "0", "0", "cv_hailuo_45", "0", "0"},
[414300] = {414300, 11043, 1, 1, "0", "0", "蒼霧殘響", "0", "0", "0", "0", "0", "cv_mila_1", "0", "0"},
[414301] = {414301, 11043, 2, 2, "0", "0", "能有更多傳教機會了？", "0", "0", "0", "0", "0", "cv_mila_2", "0", "0"},
[414302] = {414302, 11043, 3, 3, "0", "0", "你好啊領航，我是多瑙教區的主教米菈~呵呵，感覺我的語調不太像一名神職？看來你的瞭解有些滯後了，聖濯教會可是如奔流般與時俱進的哦。", "0", "0", "0", "0", "0", "cv_mila_3", "0", "0"},
[414303] = {414303, 11043, 4, 4, "0", "idle", "古人們曾想像神的模樣，有人認為神就如同我現在這般巨大，然而矗立在此俯瞰著大地，我不由得感到人類的想像力是那麼貧弱。", "0", "0", "0", "0", "0", "cv_mila_4", "0", "0"},
[414304] = {414304, 11043, 5, 4, "0", "idle", "在這種地方以巨大化的軀體宣說教義，想必能起到非常不錯的傳教效果，領航覺得呢？唔，不允許嗎？真的不行嗎？", "0", "0", "0", "0", "0", "cv_mila_5", "0", "0"},
[414305] = {414305, 11043, 6, 4, "0", "idle", "奧菲利亞和塞蕾希婭都是相當努力又單純的孩子，領航跟她們相處時，可要記得不能欺負得太過哦。", "0", "0", "0", "0", "0", "cv_mila_6", "0", "0"},
[414306] = {414306, 11043, 7, 5, "1_》_0_0.8", "level1", "只是內斂自省、埋頭祈禱的話，奇跡可是不會自己降臨的，為了我們各自的信念，一起更加大膽地昂首向前吧。", "0", "0", "0", "0", "0", "cv_mila_7", "0", "0"},
[414307] = {414307, 11043, 8, 5, "1_》_0_0.8", "level1", "管風琴音域寬廣，規模宏大，氣流振鳴所發出的樂聲猶如信眾們的整齊合唱。領航你的通感，是不是也能和信仰一樣，讓人們發自真心地意念合一呢？", "0", "0", "0", "0", "0", "cv_mila_8", "0", "0"},
[414308] = {414308, 11043, 9, 5, "1_》_100_1.5", "level2", "聖濯教會並不是那種頑固的守舊派，我們教義的細節其實一直隨著時代演變、革新，領航若有興趣，禮拜之日不妨來教堂好好傾聽一下。", "0", "0", "0", "0", "0", "cv_mila_9", "0", "0"},
[414309] = {414309, 11043, 10, 5, "1_》_500_2", "level3", "如同預言往往會自我實現，信仰也擁有神奇的力量，只要你相信，它就將成真。而我的行動正是這種篤信的產物，它能讓我心無旁騖地幫助人們。", "0", "0", "0", "0", "0", "cv_mila_10", "0", "0"},
[414310] = {414310, 11043, 11, 5, "1_》_1000_2.5", "level4", "哎呀，領航喜歡經由肌膚與人交流？那麼可以將腦袋再貼近些……現在，能仔細聽見嗎？脈搏是生命的激流，心跳則是為你而鳴響的戰鼓。", "0", "0", "0", "0", "0", "cv_mila_11", "0", "0"},
[414311] = {414311, 11043, 12, 6, "0", "0", "感謝恩賜。", "0", "0", "0", "0", "0", "cv_mila_12", "0", "0"},
[414312] = {414312, 11043, 13, 7, "0", "0", "宛若開啟一眼清泉。", "0", "0", "0", "0", "0", "cv_mila_13", "0", "0"},
[414313] = {414313, 11043, 14, 8, "0", "0", "細微的泉流積累匯聚，終將形成一股碎岩之勢。以我的琴聲作為伴奏，讓大家的努力一起沖洗世間的的塵霾吧。", "0", "0", "0", "0", "0", "cv_mila_14", "0", "0"},
[414314] = {414314, 11043, 15, 9, "0", "0", "音色更加明亮了。", "0", "0", "0", "0", "0", "cv_mila_15", "0", "0"},
[414315] = {414315, 11043, 16, 10, "0", "0", "我將奏響聖樂。", "0", "0", "0", "0", "0", "cv_mila_16", "0", "0"},
[414316] = {414316, 11043, 17, 11, "0", "0", "不完美的，也就無法稱之為奇跡。", "0", "0", "0", "0", "0", "cv_mila_17", "0", "0"},
[414317] = {414317, 11043, 18, 12, "0", "0", "只要人在，就還能重來。", "0", "0", "0", "0", "0", "cv_mila_18", "0", "0"},
[414318] = {414318, 11043, 19, 13, "0", "0", "這樣的結果，人們可不太能接受。", "0", "0", "0", "0", "0", "cv_mila_19", "0", "0"},
[414319] = {414319, 11043, 20, 14, "0", "0", "就連我也很難接受這種結果。", "0", "0", "0", "0", "0", "cv_mila_20", "0", "0"},
[414320] = {414320, 11043, 21, 15, "0", "0", "很好，很乖。", "0", "0", "0", "0", "0", "cv_mila_21", "0", "0"},
[414321] = {414321, 11043, 23, 16, "0", "0", "不要躲開哦。", "0", "0", "0", "0", "0", "cv_mila_22", "0", "0"},
[414322] = {414322, 11043, 24, 17, "0", "0", "請安息吧。", "0", "0", "0", "0", "0", "cv_mila_23", "0", "0"},
[414323] = {414323, 11043, 25, 18, "0", "0", "讓天空也為之共鳴的聲音，還請洗耳恭聽。", "0", "0", "0", "0", "0", "cv_mila_24", "0", "0"},
[414324] = {414324, 11043, 26, 19, "0", "0", "只好先撤退了。", "0", "0", "0", "0", "0", "cv_mila_26", "0", "0"},
[414325] = {414325, 11043, 27, 20, "0", "0", "真想和艾吉斯合作，推出教會主題的維護池啊。", "0", "0", "0", "0", "0", "cv_mila_27", "0", "0"},
[414326] = {414326, 11043, 28, 21, "0", "0", "洗禮時保持靜默，是在內心進行祈禱嗎？", "0", "0", "0", "0", "0", "cv_mila_28", "0", "0"},
[414327] = {414327, 11043, 29, 21, "0", "0", "領航累了嗎？這種程度就不行的話，可沒法跨越萬千苦難哦。", "0", "0", "0", "0", "0", "cv_mila_29", "0", "0"},
[414328] = {414328, 11043, 30, 22, "0", "0", "真期待呢。", "0", "0", "0", "0", "0", "cv_mila_30", "0", "0"},
[414329] = {414329, 11043, 31, 23, "0", "0", "需要我給出更多提示嗎？", "0", "0", "0", "0", "0", "cv_mila_31", "0", "0"},
[414330] = {414330, 11043, 32, 24, "0", "0", "我就相信你能猜中。", "0", "0", "0", "0", "0", "cv_mila_32", "0", "0"},
[414331] = {414331, 11043, 33, 25, "0", "0", "也是沒辦法的事呢。", "0", "0", "0", "0", "0", "cv_mila_33", "0", "0"},
[414332] = {414332, 11043, 34, 26, "0", "0", "“人不會兩次踏入同一條河流”，而我現在所見到的領航是否與昨天一樣？嗯……狀態似乎更好了些，看來的確不同呢。", "0", "0", "0", "0", "0", "cv_mila_34", "0", "0"},
[414333] = {414333, 11043, 35, 27, "0", "0", "一起帶去福音。", "0", "0", "0", "0", "0", "cv_mila_35", "0", "0"},
[414334] = {414334, 11043, 36, 28, "0", "0", "也是不錯的選擇。", "0", "0", "0", "0", "0", "cv_mila_36", "0", "0"},
[414335] = {414335, 11043, 37, 29, "0", "0", "還有迷茫的人。", "0", "0", "0", "0", "0", "cv_mila_37", "0", "0"},
[414336] = {414336, 11043, 38, 30, "0", "0", "做好迎接的準備吧。", "0", "0", "0", "0", "0", "cv_mila_38", "0", "0"},
[414337] = {414337, 11043, 39, 31, "0", "0", "我會為其賜予祝福。", "0", "0", "0", "0", "0", "cv_mila_39", "0", "0"},
[414338] = {414338, 11043, 40, 32, "0", "0", "大大方方地採購。", "0", "0", "0", "0", "0", "cv_mila_40", "0", "0"},
[414339] = {414339, 11043, 41, 33, "0", "0", "怎樣都好啦。", "0", "0", "0", "0", "0", "cv_mila_41", "0", "0"},
[414340] = {414340, 11043, 42, 34, "0", "0", "請慢慢來。", "0", "0", "0", "0", "0", "cv_mila_42", "0", "0"},
[414341] = {414341, 11043, 43, 35, "0", "0", "有給我的嗎？", "0", "0", "0", "0", "0", "cv_mila_43", "0", "0"},
[414342] = {414342, 11043, 44, 36, "0", "0", "能不能發送音頻？", "0", "0", "0", "0", "0", "cv_mila_44", "0", "0"},
[414343] = {414343, 11043, 45, 37, "0", "0", "請。", "0", "0", "0", "0", "0", "cv_mila_45", "0", "0"},
[414400] = {414400, 11044, 1, 1, "0", "0", "蒼霧殘響", "0", "0", "0", "0", "0", "cv_hein_1", "0", "0"},
[414401] = {414401, 11044, 2, 2, "0", "0", "呃，今天輪到我了嗎？請多指教……", "0", "0", "0", "0", "0", "cv_hein_2", "0", "0"},
[414402] = {414402, 11044, 3, 3, "0", "0", "我是海因，一名新人駕駛員……那麼，自我介紹就到此為止吧，領航早已瞭解我了不是嗎？我更愛用行動與繪畫代替言語。", "0", "0", "0", "0", "0", "cv_hein_3", "0", "0"},
[414403] = {414403, 11044, 4, 4, "0", "idle", "以這種高度，可以看到與平常不一樣的風景。反正站著也是站著，真想順便寫寫生啊。", "0", "0", "0", "0", "0", "cv_hein_4", "0", "0"},
[414404] = {414404, 11044, 5, 4, "0", "idle2", "在研究所裡，我通常獨自一人靜靜待著。不過像現在這樣兩個人一起相視無言，倒也不錯呢。", "0", "0", "0", "0", "0", "cv_hein_5", "0", "0"},
[414405] = {414405, 11044, 6, 4, "0", "idle3", "希夏說什麼也要拉我去健身，甚至還表示這有助於發育，完全演變成職場騷擾了吧……領航不管管她嗎？欸？你也讚同她的想法？", "0", "0", "0", "0", "0", "cv_hein_6", "0", "0"},
[414406] = {414406, 11044, 7, 5, "1_》_0_0.8", "level1", "掌握的學識越豐富，我就越是能感到自己的無力。信仰無法換取的、思想無法撼動的、藝術無法觸及的，只有行動。", "0", "0", "0", "0", "0", "cv_hein_7", "0", "0"},
[414407] = {414407, 11044, 8, 5, "1_》_0_0.8", "level1", "這根法杖？是我自己設計的AVG武裝哦。杖頭部分概念為調色盤，可以通過“調色”來改變尼姆比斯能的性質，杖柄則是一根科技筆。", "0", "0", "0", "0", "0", "cv_hein_8", "0", "0"},
[414408] = {414408, 11044, 9, 5, "1_》_100_1.5", "level2", "下班後一起出去玩？可以啊。不過我毫無運動細胞，就別考慮什麼過於刺激的活動了，水族館或天文館之類的怎麼樣？", "0", "0", "0", "0", "0", "cv_hein_9", "0", "0"},
[414409] = {414409, 11044, 10, 5, "1_》_500_2", "level3", "明知道你不是壞人，但這種肌膚接觸還是讓我有些……唔，已經分不清是喜歡還是討厭了……雖然可能這是我的問題啦，我腦子裡到底裝著些什麼？", "0", "0", "0", "0", "0", "cv_hein_10", "0", "0"},
[414410] = {414410, 11044, 11, 5, "1_》_1000_2.5", "level4", "此前我獨愛於畫景，最近卻感到只是這樣總有些寂寞……如果我想抵達新的領域，想見識新的景色，領航，能否請你成為我的模特呢？", "0", "0", "0", "0", "0", "cv_hein_11", "0", "0"},
[414411] = {414411, 11044, 12, 6, "0", "0", "感謝……", "0", "0", "0", "0", "0", "cv_hein_12", "0", "0"},
[414412] = {414412, 11044, 13, 7, "0", "0", "我會繼續成長的。", "0", "0", "0", "0", "0", "cv_hein_13", "0", "0"},
[414413] = {414413, 11044, 14, 8, "0", "0", "我居然也成為資深駕駛員了啊，已經快忘記不久前那個只是一名普通人的自己了。領航，或許與你的相遇就是我真正的奇跡吧。", "0", "0", "0", "0", "0", "cv_hein_14", "0", "0"},
[414414] = {414414, 11044, 15, 9, "0", "0", "筆觸改變了。", "0", "0", "0", "0", "0", "cv_hein_15", "0", "0"},
[414415] = {414415, 11044, 16, 10, "0", "0", "僅憑想像畫不出好作品，戰鬥也是。", "0", "0", "0", "0", "0", "cv_hein_16", "0", "0"},
[414416] = {414416, 11044, 17, 11, "0", "0", "對研究，對繪畫，都是不錯的素材。", "0", "0", "0", "0", "0", "cv_hein_17", "0", "0"},
[414417] = {414417, 11044, 18, 12, "0", "0", "不完美的作品也有價值。", "0", "0", "0", "0", "0", "cv_hein_18", "0", "0"},
[414418] = {414418, 11044, 19, 13, "0", "0", "必須努力汲取教訓。", "0", "0", "0", "0", "0", "cv_hein_19", "0", "0"},
[414419] = {414419, 11044, 20, 14, "0", "0", "都是疏於訓練的結果……", "0", "0", "0", "0", "0", "cv_hein_20", "0", "0"},
[414420] = {414420, 11044, 21, 15, "0", "0", "錯誤的痕跡就該塗抹掉。", "0", "0", "0", "0", "0", "cv_hein_21", "0", "0"},
[414421] = {414421, 11044, 23, 16, "0", "0", "運筆不疑。", "0", "0", "0", "0", "0", "cv_hein_22", "0", "0"},
[414422] = {414422, 11044, 24, 17, "0", "0", "再來一筆。", "0", "0", "0", "0", "0", "cv_hein_23", "0", "0"},
[414423] = {414423, 11044, 26, 19, "0", "0", "真不想半途而廢……", "0", "0", "0", "0", "0", "cv_hein_24", "0", "0"},
[414424] = {414424, 11044, 27, 20, "0", "0", "唔欸！為什麼要突然進來？", "0", "0", "0", "0", "0", "cv_hein_25", "0", "0"},
[414425] = {414425, 11044, 28, 21, "0", "0", "雖然我平時喜歡安靜，但、但這種時候還是請你多說兩句話吧？", "0", "0", "0", "0", "0", "cv_hein_26", "0", "0"},
[414426] = {414426, 11044, 29, 21, "0", "0", "這麼貧瘠的身體有什麼好看的……你有一雙發現美的眼睛？還真敢說啊。", "0", "0", "0", "0", "0", "cv_hein_27", "0", "0"},
[414427] = {414427, 11044, 30, 22, "0", "0", "什、什麼？", "0", "0", "0", "0", "0", "cv_hein_28", "0", "0"},
[414428] = {414428, 11044, 31, 23, "0", "0", "為什麼會有這種遊戲。", "0", "0", "0", "0", "0", "cv_hein_29", "0", "0"},
[414429] = {414429, 11044, 32, 24, "0", "0", "猜對了也沒什麼可高興的。", "0", "0", "0", "0", "0", "cv_hein_30", "0", "0"},
[414430] = {414430, 11044, 33, 25, "0", "0", "居然會猜錯……", "0", "0", "0", "0", "0", "cv_hein_31", "0", "0"},
[414431] = {414431, 11044, 34, 26, "0", "0", "回來了啊，放心，街道、人們都一切正常，連天氣也沒有改變，畫成畫一定是幅沒有新意的風景。", "0", "0", "0", "0", "0", "cv_hein_32", "0", "0"},
[414432] = {414432, 11044, 35, 27, "0", "0", "去完成今天的“寫生”吧。", "0", "0", "0", "0", "0", "cv_hein_33", "0", "0"},
[414433] = {414433, 11044, 36, 28, "0", "0", "練習勝於一切。", "0", "0", "0", "0", "0", "cv_hein_34", "0", "0"},
[414434] = {414434, 11044, 37, 29, "0", "0", "完全記不清這麼多人……", "0", "0", "0", "0", "0", "cv_hein_35", "0", "0"},
[414435] = {414435, 11044, 38, 30, "0", "0", "我也要當前輩了？", "0", "0", "0", "0", "0", "cv_hein_36", "0", "0"},
[414436] = {414436, 11044, 39, 31, "0", "0", "比我研發的更好嗎？", "0", "0", "0", "0", "0", "cv_hein_37", "0", "0"},
