[414438] = {414438, 11044, 41, 33, "0", "0", "我不會偷看的。", "0", "0", "0", "0", "0", "cv_hein_39", "0", "0"},
[414439] = {414439, 11044, 42, 34, "0", "0", "我來幫忙。", "0", "0", "0", "0", "0", "cv_hein_40", "0", "0"},
[414440] = {414440, 11044, 43, 35, "0", "0", "你的郵箱居然不分公私？", "0", "0", "0", "0", "0", "cv_hein_41", "0", "0"},
[414441] = {414441, 11044, 44, 36, "0", "0", "我就不說話了。", "0", "0", "0", "0", "0", "cv_hein_42", "0", "0"},
