[414500] = {414500, 11045, 1, 1, "0", "0", "蒼霧殘響", "0", "0", "0", "0", "0", "cv_feilier_33", "0", "0"},
[414501] = {414501, 11045, 2, 2, "0", "0", "只要呆在這裡，就能和你保持通感？", "0", "0", "0", "0", "0", "cv_feilier_2", "0", "0"},
[414502] = {414502, 11045, 3, 3, "0", "0", "你就是多瑙的領航？好小一隻啊……先自我介紹一下。晨曦，吠黎爾，B17，是B組唯一倖存下來的失敗品。通感治療，就拜託你了。", "0", "0", "0", "0", "0", "cv_feilier_1", "0", "0"},
[414503] = {414503, 11045, 4, 4, "0", "idle", "每次連上通感，感覺整個人都飄飄然的，好舒服……", "0", "0", "0", "0", "0", "cv_feilier_3", "0", "0"},
[414504] = {414504, 11045, 5, 4, "0", "idle", "……糟糕，有點上癮欸。", "0", "0", "0", "0", "0", "cv_feilier_4", "0", "0"},
[414505] = {414505, 11045, 6, 4, "0", "idle", "咦？通感怎麼斷了？", "0", "0", "0", "0", "0", "cv_feilier_5", "0", "0"},
[414506] = {414506, 11045, 7, 5, "1_》_0_0.8", "level1", "等解除巨大化了，可不要再這麼觸碰我。我不確定，那時候的自己……會不會傷到你。", "0", "0", "0", "0", "0", "cv_feilier_6", "0", "0"},
[414507] = {414507, 11045, 8, 5, "1_》_0_0.8", "level1", "請放心，現在我能控制住自己的。", "0", "0", "0", "0", "0", "cv_feilier_7", "0", "0"},
[414508] = {414508, 11045, 9, 5, "1_》_100_1.5", "level2", "衣服？無所謂，就讓它破著吧。反正也不過是層布而已。", "0", "0", "0", "0", "0", "cv_feilier_8", "0", "0"},
[414509] = {414509, 11045, 10, 5, "1_》_500_2", "level3", "回印加？為什麼？我可是知道的，我是多瑙人，要回也是回多瑙才對。", "0", "0", "0", "0", "0", "cv_feilier_9", "0", "0"},
[414510] = {414510, 11045, 11, 5, "1_》_1000_2.5", "level4", "只要一直在一起，就能一直保持通感……永遠不斷開……", "0", "0", "0", "0", "0", "cv_feilier_10", "0", "0"},
[414511] = {414511, 11045, 12, 6, "0", "0", "聽你的。", "0", "0", "0", "0", "0", "cv_feilier_11", "0", "0"},
[414512] = {414512, 11045, 13, 7, "0", "0", "都聽你的。", "0", "0", "0", "0", "0", "cv_feilier_12", "0", "0"},
[414513] = {414513, 11045, 14, 8, "0", "0", "照這個趨勢，或許不久後，即便沒有連接幻化核心，我也能保持意志，與你正常交流？真期待那一天的到來呀。", "0", "0", "0", "0", "0", "cv_feilier_13", "0", "0"},
[414514] = {414514, 11045, 15, 9, "0", "0", "小心，這爪子還挺利的。", "0", "0", "0", "0", "0", "cv_feilier_14", "0", "0"},
[414515] = {414515, 11045, 16, 10, "0", "0", "別忘了搭建通感。", "0", "0", "0", "0", "0", "cv_feilier_15", "0", "0"},
[414516] = {414516, 11045, 17, 11, "0", "0", "你很高興。我能感受到。", "0", "0", "0", "0", "0", "cv_feilier_16", "0", "0"},
[414517] = {414517, 11045, 18, 12, "0", "0", "小傷，沒事。有尼姆比斯，能修復。", "0", "0", "0", "0", "0", "cv_feilier_17", "0", "0"},
[414518] = {414518, 11045, 19, 13, "0", "0", "手上的繃帶，不髒，分你一些？", "0", "0", "0", "0", "0", "cv_feilier_18", "0", "0"},
[414519] = {414519, 11045, 20, 14, "0", "0", "不要生氣，不要沮喪……我再去和它們打一架，你會不會開心些？", "0", "0", "0", "0", "0", "cv_feilier_19", "0", "0"},
[414520] = {414520, 11045, 21, 15, "0", "0", "撕裂你！", "0", "0", "0", "0", "0", "cv_feilier_20", "0", "0"},
[414521] = {414521, 11045, 23, 16, "0", "0", "是你剛才打我的？", "0", "0", "0", "0", "0", "cv_feilier_21", "0", "0"},
[414522] = {414522, 11045, 24, 17, "0", "0", "好痛呀……", "0", "0", "0", "0", "0", "cv_feilier_23", "0", "0"},
[414523] = {414523, 11045, 25, 18, "0", "0", "現在的我可是無敵的！", "0", "0", "0", "0", "0", "cv_feilier_24", "0", "0"},
[414524] = {414524, 11045, 26, 19, "0", "0", "眼睛……不可以閉上……", "0", "0", "0", "0", "0", "cv_feilier_22", "0", "0"},
[414525] = {414525, 11045, 27, 20, "0", "0", "這也是治療的一環？", "0", "0", "0", "0", "0", "cv_feilier_25", "0", "0"},
[414526] = {414526, 11045, 28, 21, "0", "0", "我都快忘了，原來人類的肌膚是如此溫暖……", "0", "0", "0", "0", "0", "cv_feilier_26", "0", "0"},
[414527] = {414527, 11045, 29, 21, "0", "0", "……不痛，癢癢的。好奇怪呀。", "0", "0", "0", "0", "0", "cv_feilier_27", "0", "0"},
[414528] = {414528, 11045, 30, 22, "0", "0", "要結束了？", "0", "0", "0", "0", "0", "cv_feilier_28", "0", "0"},
[414529] = {414529, 11045, 31, 23, "0", "0", "不要明知故問呐。", "0", "0", "0", "0", "0", "cv_feilier_29", "0", "0"},
[414530] = {414530, 11045, 32, 24, "0", "0", "自問自答很有意思麼……那我也要來。猜猜我是誰？", "0", "0", "0", "0", "0", "cv_feilier_30", "0", "0"},
[414531] = {414531, 11045, 33, 25, "0", "0", "……那個人是誰？", "0", "0", "0", "0", "0", "cv_feilier_31", "0", "0"},
[414532] = {414532, 11045, 34, 26, "0", "0", "終於回來了……其他的不急，先重新連上通感吧。快點，我已經準備好了。", "0", "0", "0", "0", "0", "cv_feilier_32", "0", "0"},
[414533] = {414533, 11045, 35, 27, "0", "0", "好吧。治療期間，我確實得保護你的人身安全呢。", "0", "0", "0", "0", "0", "cv_feilier_34", "0", "0"},
[414534] = {414534, 11045, 36, 28, "0", "0", "這裡也是靠拳頭說話麼。", "0", "0", "0", "0", "0", "cv_feilier_35", "0", "0"},
[414535] = {414535, 11045, 37, 29, "0", "0", "好多的人……", "0", "0", "0", "0", "0", "cv_feilier_36", "0", "0"},
[414536] = {414536, 11045, 38, 30, "0", "0", "這裡有我就夠了。", "0", "0", "0", "0", "0", "cv_feilier_37", "0", "0"},
[414537] = {414537, 11045, 39, 31, "0", "0", "這些裝備……如果被它們打，一定很痛……", "0", "0", "0", "0", "0", "cv_feilier_38", "0", "0"},
[414538] = {414538, 11045, 40, 32, "0", "0", "我可以幫忙搬東西。我力氣很大的。", "0", "0", "0", "0", "0", "cv_feilier_39", "0", "0"},
[414539] = {414539, 11045, 41, 33, "0", "0", "就算療程結束，我也是可以繼續呆在這裡的吧？", "0", "0", "0", "0", "0", "cv_feilier_40", "0", "0"},
[414540] = {414540, 11045, 42, 34, "0", "0", "需要我更大聲說話？還是再小聲一點？", "0", "0", "0", "0", "0", "cv_feilier_41", "0", "0"},
[414541] = {414541, 11045, 43, 35, "0", "0", "我來幫忙整理。", "0", "0", "0", "0", "0", "cv_feilier_42", "0", "0"},
[414542] = {414542, 11045, 44, 36, "0", "0", "你在看什麼？", "0", "0", "0", "0", "0", "cv_feilier_43", "0", "0"},
[414543] = {414543, 11045, 45, 37, "0", "0", "不要不理我啊。", "0", "0", "0", "0", "0", "cv_feilier_44", "0", "0"},
[414600] = {414600, 11046, 1, 1, "0", "0", "蒼霧殘響", "0", "0", "0", "0", "0", "cv_peipeita_1", "0", "0"},
[414601] = {414601, 11046, 2, 2, "0", "0", "能待在老師身邊就好~", "0", "0", "0", "0", "0", "cv_peipeita_2", "0", "0"},
[414602] = {414602, 11046, 3, 3, "0", "0", "歧花小隊所屬，佩佩塔前來報到！終於又見到老師您了，雖然是以問題學生的身份……但我會加倍努力的！", "0", "0", "0", "0", "0", "cv_peipeita_3", "0", "0"},
[414603] = {414603, 11046, 4, 4, "0", "idle", "這就是正式駕駛員每天都會看見的風景啊，比學校裡見到的更加廣闊，也更讓人期待不已。", "0", "0", "0", "0", "0", "cv_peipeita_4", "0", "0"},
[414604] = {414604, 11046, 5, 4, "0", "idle", "老師？工作辛苦所以困了的話，可以在我身上休息哦，躺在胸口上會更柔軟、暖和，就是……如果心跳聲太吵的話，還請包涵。", "0", "0", "0", "0", "0", "cv_peipeita_5", "0", "0"},
[414605] = {414605, 11046, 6, 4, "0", "idle", "明明想作為優等生來見老師，卻事與願違加入了問題學生小隊呢。而且，這支隊伍中對老師虎視眈眈的人也不少，請當心點哦。", "0", "0", "0", "0", "0", "cv_peipeita_6", "0", "0"},
[414606] = {414606, 11046, 7, 5, "1_》_0_0.8", "level1", "用、用摸頭來鼓勵學生嗎？那我就把腦袋再低一點好了，這樣老師摸起來也會更方便~", "0", "0", "0", "0", "0", "cv_peipeita_7", "0", "0"},
[414607] = {414607, 11046, 8, 5, "1_》_0_0.8", "level1", "因為很在意，就收集了不少關於老師的資料，那個……老師真的和很多駕駛員都有超常的關係嗎？還是說只是謠言呢？", "0", "0", "0", "0", "0", "cv_peipeita_8", "0", "0"},
[414608] = {414608, 11046, 9, 5, "1_》_100_1.5", "level2", "這個武器因為很重所以用起來很吃力，不過我是特意選擇它的，因為如果連這點困難都克服不了，怎麼能成為老師的駕駛員呢~", "0", "0", "0", "0", "0", "cv_peipeita_9", "0", "0"},
[414609] = {414609, 11046, 10, 5, "1_》_500_2", "level3", "已經和老師相處一段時間了，我想聽聽您對我的評價……在您看來，我是一名好學生嗎？沒有輸給雛鷹小隊那些傢伙嗎？嗯……嗯……感謝老師！", "0", "0", "0", "0", "0", "cv_peipeita_10", "0", "0"},
[414610] = {414610, 11046, 11, 5, "1_》_1000_2.5", "level4", "我曾被批評，身為學生不要老想著大人世界的感情……但現在我已經是名出色的駕駛員了吧？如果得到您的認可，我對您的憧憬更激進大膽些也可以了吧？", "0", "0", "0", "0", "0", "cv_peipeita_11", "0", "0"},
[414611] = {414611, 11046, 12, 6, "0", "0", "我要變得更強。", "0", "0", "0", "0", "0", "cv_peipeita_12", "0", "0"},
[414612] = {414612, 11046, 13, 7, "0", "0", "是不是多少與老師更相稱了呢？", "0", "0", "0", "0", "0", "cv_peipeita_13", "0", "0"},
[414613] = {414613, 11046, 14, 8, "0", "0", "嗚哇，我做到了？我也變強到這種程度了？不……這都多虧了老師無微不至的關心與栽培，而且我依然有許多做不好的事，還請老師繼續指點我吧！", "0", "0", "0", "0", "0", "cv_peipeita_14", "0", "0"},
[414614] = {414614, 11046, 15, 9, "0", "0", "學習、不斷學習。", "0", "0", "0", "0", "0", "cv_peipeita_15", "0", "0"},
[414615] = {414615, 11046, 16, 10, "0", "0", "立下更多實績吧！", "0", "0", "0", "0", "0", "cv_peipeita_16", "0", "0"},
[414616] = {414616, 11046, 17, 11, "0", "0", "嘿嘿~老師可以誇誇我嗎？", "0", "0", "0", "0", "0", "cv_peipeita_17", "0", "0"},
[414617] = {414617, 11046, 18, 12, "0", "0", "唔，看來還得再努力些呢。", "0", "0", "0", "0", "0", "cv_peipeita_18", "0", "0"},
[414618] = {414618, 11046, 19, 13, "0", "0", "回去後請對我進行魔鬼訓練吧！", "0", "0", "0", "0", "0", "cv_peipeita_19", "0", "0"},
[414619] = {414619, 11046, 20, 14, "0", "0", "不是老師的責任，是我還不夠強……", "0", "0", "0", "0", "0", "cv_peipeita_20", "0", "0"},
[414620] = {414620, 11046, 21, 15, "0", "0", "哼，小菜一碟~", "0", "0", "0", "0", "0", "cv_peipeita_21", "0", "0"},
[414621] = {414621, 11046, 23, 16, "0", "0", "吃我一招！", "0", "0", "0", "0", "0", "cv_peipeita_23", "0", "0"},
[414622] = {414622, 11046, 24, 17, "0", "0", "還沒完呢！", "0", "0", "0", "0", "0", "cv_peipeita_24", "0", "0"},
[414623] = {414623, 11046, 25, 18, "0", "0", "礙事的傢伙，要是能全部消失就好了！", "0", "0", "0", "0", "0", "cv_peipeita_25", "0", "0"},
[414624] = {414624, 11046, 26, 19, "0", "0", "怎麼能就這麼……", "0", "0", "0", "0", "0", "cv_peipeita_26", "0", "0"},
[414625] = {414625, 11046, 27, 20, "0", "0", "原來正式駕駛員還能享受這個……可惡，要是早出生就能更早體驗了。", "0", "0", "0", "0", "0", "cv_peipeita_27", "0", "0"},
[414626] = {414626, 11046, 28, 21, "0", "0", "雖然還是學生，但我的身體已經很成熟了對吧~", "0", "0", "0", "0", "0", "cv_peipeita_28", "0", "0"},
[414627] = {414627, 11046, 29, 21, "0", "0", "駕駛員身體健康程度也有成績的話，老師能給我打多少分呢？", "0", "0", "0", "0", "0", "cv_peipeita_29", "0", "0"},
[414628] = {414628, 11046, 30, 22, "0", "0", "什麼？", "0", "0", "0", "0", "0", "cv_peipeita_30", "0", "0"},
[414629] = {414629, 11046, 31, 23, "0", "0", "像是點名環節呢。", "0", "0", "0", "0", "0", "cv_peipeita_31", "0", "0"},
[414630] = {414630, 11046, 32, 24, "0", "0", "嘿嘿，是我喲~", "0", "0", "0", "0", "0", "cv_peipeita_32", "0", "0"},
[414631] = {414631, 11046, 33, 25, "0", "0", "老師，請好好記住學生的名字！", "0", "0", "0", "0", "0", "cv_peipeita_33", "0", "0"},
[414632] = {414632, 11046, 34, 26, "0", "0", "雖然知道老師很忙，但請再多分點時間給我嘛……啊！不是在抱怨，只是、只是想更加刻苦地接受您的教導啦！", "0", "0", "0", "0", "0", "cv_peipeita_34", "0", "0"},
[414633] = {414633, 11046, 35, 27, "0", "0", "已經迫不及待了！", "0", "0", "0", "0", "0", "cv_peipeita_35", "0", "0"},
[414634] = {414634, 11046, 36, 28, "0", "0", "得戰勝勁敵們才行。", "0", "0", "0", "0", "0", "cv_peipeita_36", "0", "0"},
[414635] = {414635, 11046, 37, 29, "0", "0", "全是我的敵人呢……", "0", "0", "0", "0", "0", "cv_peipeita_37", "0", "0"},
[414636] = {414636, 11046, 38, 30, "0", "0", "又有新的挑戰了嗎……", "0", "0", "0", "0", "0", "cv_peipeita_38", "0", "0"},
[414637] = {414637, 11046, 39, 31, "0", "0", "老師，哪件更適合我呢？", "0", "0", "0", "0", "0", "cv_peipeita_39", "0", "0"},
[414638] = {414638, 11046, 40, 32, "0", "0", "和老師一起購物……", "0", "0", "0", "0", "0", "cv_peipeita_40", "0", "0"},
[414639] = {414639, 11046, 41, 33, "0", "0", "我、我可以看嗎？", "0", "0", "0", "0", "0", "cv_peipeita_41", "0", "0"},
[414640] = {414640, 11046, 42, 34, "0", "0", "老師的細心值得學習。", "0", "0", "0", "0", "0", "cv_peipeita_42", "0", "0"},
[414641] = {414641, 11046, 43, 35, "0", "0", "唔……好想偷看。", "0", "0", "0", "0", "0", "cv_peipeita_43", "0", "0"},
[414642] = {414642, 11046, 44, 36, "0", "0", "就在這宣誓主權吧~", "0", "0", "0", "0", "0", "cv_peipeita_44", "0", "0"},
[414643] = {414643, 11046, 45, 37, "0", "0", "嗯？", "0", "0", "0", "0", "0", "cv_peipeita_45", "0", "0"},
[414700] = {414700, 11047, 1, 1, "0", "0", "蒼霧殘響", "0", "0", "0", "0", "0", "cv_dangyangtu_1", "0", "0"},
[414701] = {414701, 11047, 2, 2, "0", "0", "欸？真的不是什麼整人綜藝節目？", "0", "0", "0", "0", "0", "cv_dangyangtu_2", "0", "0"},
[414702] = {414702, 11047, 3, 3, "0", "0", "這裡是蕩漾兔，一名活躍在網絡世界的偶像~你就是我的製作人嗎？雖然並非初次見面，以後請多指教咯！", "0", "0", "0", "0", "0", "cv_dangyangtu_3", "0", "0"},
[414703] = {414703, 11047, 4, 4, "0", "idle", "如果將城市視為一座巨大的演唱會場館，那麼多瑙可謂是座無虛席，不放聲唱首歌真有些浪費呢。", "0", "0", "0", "0", "0", "cv_dangyangtu_4", "0", "0"},
[414704] = {414704, 11047, 5, 4, "0", "idle", "怎麼啦怎麼啦？突然間這麼死氣沉沉的，作為我的製作人兼粉絲，不時刻保持活力的話可是會讓我很傷心的！", "0", "0", "0", "0", "0", "cv_dangyangtu_5", "0", "0"},
[414705] = {414705, 11047, 6, 4, "0", "idle", "小隊裡老有人想揪出我的真實身份，實在是傷腦筋啊，戳破了真實與虛假之間的這層面紗，許多事可就會沒有意思了。", "0", "0", "0", "0", "0", "cv_dangyangtu_6", "0", "0"},
[414706] = {414706, 11047, 7, 5, "1_》_0_0.8", "level1", "用尼姆比斯能幻化出的這具身體，操控起來的確更輕鬆了，但相比投影也少了些樂趣啊，比如說，不能裝作電子幽靈嚇唬人了~", "0", "0", "0", "0", "0", "cv_dangyangtu_7", "0", "0"},
[414707] = {414707, 11047, 8, 5, "1_》_0_0.8", "level1", "喂喂現在可不是握手會的時候啊！而且作為我的製作人，你不是每天都有機會和我互動嗎？", "0", "0", "0", "0", "0", "cv_dangyangtu_8", "0", "0"},
[414708] = {414708, 11047, 9, 5, "1_》_100_1.5", "level2", "想知道我的真實身份嗎？我已經將解開秘密的鑰匙藏在網絡海洋的某一處了，請製作人自行尋找吧~當然，可別忘了有句話叫“狡兔三窟”。", "0", "0", "0", "0", "0", "cv_dangyangtu_9", "0", "0"},
[414709] = {414709, 11047, 10, 5, "1_》_500_2", "level3", "運營偶像身份的同時，學業也不能就這麼落下，再加上還有駕駛員的工作要做，我已經分身乏術了，看來，得更加依靠製作人才行啊~", "0", "0", "0", "0", "0", "cv_dangyangtu_10", "0", "0"},
[414710] = {414710, 11047, 11, 5, "1_》_1000_2.5", "level4", "雖然起初不太滿意這種安排，但能由你成為我的製作人果然最棒了~充分給予每個人自由與尊重，我想成為的正是這樣的“偶像”。", "0", "0", "0", "0", "0", "cv_dangyangtu_11", "0", "0"},
[414711] = {414711, 11047, 12, 6, "0", "0", "感謝應援！", "0", "0", "0", "0", "0", "cv_dangyangtu_12", "0", "0"},
[414712] = {414712, 11047, 13, 7, "0", "0", "得好好回饋你的愛才行了~", "0", "0", "0", "0", "0", "cv_dangyangtu_13", "0", "0"},
[414713] = {414713, 11047, 14, 8, "0", "0", "偶像與駭客都能創造奇跡，儘管只憑歌聲或代碼無法辦到的事同樣還有許多，但……如果和你一起，我相信現在還遠遠沒到極限。", "0", "0", "0", "0", "0", "cv_dangyangtu_14", "0", "0"},
[414714] = {414714, 11047, 15, 9, "0", "0", "身為偶像可不能懈怠。", "0", "0", "0", "0", "0", "cv_dangyangtu_15", "0", "0"},
[414715] = {414715, 11047, 16, 10, "0", "0", "讓我聽聽，哪邊的粉絲呼聲最熱情~", "0", "0", "0", "0", "0", "cv_dangyangtu_16", "0", "0"},
[414716] = {414716, 11047, 17, 11, "0", "0", "我不會忘記這場演出的哦。", "0", "0", "0", "0", "0", "cv_dangyangtu_17", "0", "0"},
[414717] = {414717, 11047, 18, 12, "0", "0", "既然還不完美，未來就讓我們共同進步吧！", "0", "0", "0", "0", "0", "cv_dangyangtu_18", "0", "0"},
[414718] = {414718, 11047, 19, 13, "0", "0", "玩鬧過頭了嗎？得認真起來了啊。", "0", "0", "0", "0", "0", "cv_dangyangtu_19", "0", "0"},
[414719] = {414719, 11047, 20, 14, "0", "0", "事前准備還得更加充足。", "0", "0", "0", "0", "0", "cv_dangyangtu_20", "0", "0"},
[414720] = {414720, 11047, 21, 15, "0", "0", "請這位粉絲安靜點~", "0", "0", "0", "0", "0", "cv_dangyangtu_21", "0", "0"},
[414721] = {414721, 11047, 23, 16, "0", "0", "這次是新的曲子！", "0", "0", "0", "0", "0", "cv_dangyangtu_23", "0", "0"},
[414722] = {414722, 11047, 24, 17, "0", "0", "陶醉其中吧~", "0", "0", "0", "0", "0", "cv_dangyangtu_24", "0", "0"},
[414723] = {414723, 11047, 25, 18, "0", "0", "慾望與源碼，都將由我改寫。", "0", "0", "0", "0", "0", "cv_dangyangtu_25", "0", "0"},
[414724] = {414724, 11047, 26, 19, "0", "0", "唔……我還會再出現的！", "0", "0", "0", "0", "0", "cv_dangyangtu_26", "0", "0"},
[414725] = {414725, 11047, 27, 20, "0", "0", "咿呀！——以為我會這麼尖叫嗎？", "0", "0", "0", "0", "0", "cv_dangyangtu_27", "0", "0"},
[414726] = {414726, 11047, 28, 21, "0", "0", "喜歡這副身體？我也很喜歡~", "0", "0", "0", "0", "0", "cv_dangyangtu_28", "0", "0"},
[414727] = {414727, 11047, 29, 21, "0", "0", "我懂我懂，檢視偶像的身體健康狀況也是製作人的職責對吧？", "0", "0", "0", "0", "0", "cv_dangyangtu_29", "0", "0"},
[414728] = {414728, 11047, 30, 22, "0", "0", "請~", "0", "0", "0", "0", "0", "cv_dangyangtu_30", "0", "0"},
[414729] = {414729, 11047, 31, 23, "0", "0", "餘興節目嗎？", "0", "0", "0", "0", "0", "cv_dangyangtu_31", "0", "0"},
[414730] = {414730, 11047, 32, 24, "0", "0", "理所當然嘛。", "0", "0", "0", "0", "0", "cv_dangyangtu_32", "0", "0"},
[414731] = {414731, 11047, 33, 25, "0", "0", "製作人的失格啊！", "0", "0", "0", "0", "0", "cv_dangyangtu_33", "0", "0"},
[414732] = {414732, 11047, 34, 26, "0", "0", "製作人回來了啊，我又有了些新的靈感，要一起來商量下嗎？——關於如何在艾吉斯總部的會議室上舉辦一場演唱會~", "0", "0", "0", "0", "0", "cv_dangyangtu_34", "0", "0"},
[414733] = {414733, 11047, 35, 27, "0", "0", "快前往live現場吧。", "0", "0", "0", "0", "0", "cv_dangyangtu_35", "0", "0"},
[414734] = {414734, 11047, 36, 28, "0", "0", "排練時也得努力。", "0", "0", "0", "0", "0", "cv_dangyangtu_36", "0", "0"},
[414735] = {414735, 11047, 37, 29, "0", "0", "都是具有偶像潛質的孩子呢。", "0", "0", "0", "0", "0", "cv_dangyangtu_37", "0", "0"},
[414736] = {414736, 11047, 38, 30, "0", "0", "新的夥伴？", "0", "0", "0", "0", "0", "cv_dangyangtu_38", "0", "0"},
[414737] = {414737, 11047, 39, 31, "0", "0", "有新衣服嗎？", "0", "0", "0", "0", "0", "cv_dangyangtu_39", "0", "0"},
[414738] = {414738, 11047, 40, 32, "0", "0", "這個商場系統，好多漏洞。", "0", "0", "0", "0", "0", "cv_dangyangtu_40", "0", "0"},
[414739] = {414739, 11047, 41, 33, "0", "0", "而我的檔案全是虛假信息呢。", "0", "0", "0", "0", "0", "cv_dangyangtu_41", "0", "0"},
[414740] = {414740, 11047, 42, 34, "0", "0", "真用心啊。", "0", "0", "0", "0", "0", "cv_dangyangtu_42", "0", "0"},
[414741] = {414741, 11047, 43, 35, "0", "0", "小心釣魚郵件。", "0", "0", "0", "0", "0", "cv_dangyangtu_43", "0", "0"},
[414742] = {414742, 11047, 44, 36, "0", "0", "我聽到了粉絲們的呼聲。", "0", "0", "0", "0", "0", "cv_dangyangtu_44", "0", "0"},
[414743] = {414743, 11047, 45, 37, "0", "0", "加油~", "0", "0", "0", "0", "0", "cv_dangyangtu_45", "0", "0"},
[414800] = {414800, 11048, 1, 1, "0", "0", "蒼霧殘響", "ハツリバーブ", "0", "0", "0", "0", "cv_lilith_sw_1", "0", "0"},
[414801] = {414801, 11048, 2, 2, "0", "0", "好笑嗎？那就趁你的那張嘴被我撕爛前多笑一下吧。", "そんなにおかしい？　好きなだけ笑っていいのよ。その口を引き裂く前に、ね。", "0", "0", "0", "0", "cv_lilith_sw_2", "0", "0"},
[414802] = {414802, 11048, 3, 3, "0", "0", "你的臉上真是寫滿了意外，我換上泳裝在你看來是很不可思議的事情嗎？通感者。", "びっくりしたって顔ね。私の水著がそんなに意外だった？通感覚者さん。", "0", "0", "0", "0", "cv_lilith_sw_3", "0", "0"},
[414803] = {414803, 11048, 4, 4, "0", "idle", "現實真是難以預料……那個時候的我，肯定不會想到自己會有和你心平氣和共處在一起的時候。", "事実は小説より奇なりってやつね……以前の私なら、あなたと穏やかに過ごす日が來るなんて思いもよらなかったでしょうね。", "0", "0", "0", "0", "cv_lilith_sw_4", "0", "0"},
[414804] = {414804, 11048, 5, 4, "0", "idle", "你有想過嗎？那些環繞在你身邊的女孩子，或許都曾經與你有過一段孽緣，只是你和她們都忘了……算了，當我沒說。", "考えたことある？　あなたの周りにいるあの子たちが、あなたと男女の仲だったことを忘れてしまっているかも知れないなんて……いいわ、聞かなかったことにして。", "0", "0", "0", "0", "cv_lilith_sw_5", "0", "0"},
[414805] = {414805, 11048, 6, 4, "0", "idle", "不管離你多遠，都能聽見你的聲音。真是的，都快聽膩了……通感，真是麻煩的能力，以後想忘也忘不掉了。", "どれだけ離れてもあなたの聲が聞こえてくるなんて。まったく、うんざりするわ……通感覚って本當に厄介な能力ね。忘れようにも忘れられないじゃない。", "0", "0", "0", "0", "cv_lilith_sw_6", "0", "0"},
[414806] = {414806, 11048, 7, 5, "1_》_0_0.8", "level1", "你的手還真是冷啊……明明天氣這麼熱，要我幫你捂熱嗎？", "あなたの手、冷たいのね……こんなに暑い日なのに。溫めてあげましょうか？", "0", "0", "0", "0", "cv_lilith_sw_7", "0", "0"},
[414807] = {414807, 11048, 8, 5, "1_》_0_0.8", "level1", "每一次觸摸，彼此的心情就會流傳過去，被我們所感受——這種相處方式，恐怕也只有我們了。", "觸れる度に、互いの感情が流れ込んで來る……そんな付き合い方ができるのは、私達だけなのかもね。", "0", "0", "0", "0", "cv_lilith_sw_8", "0", "0"},
[414808] = {414808, 11048, 9, 5, "1_》_100_1.5", "level2", "主人今天要吃什麼~要充滿莉莉絲“愛”的蛋包飯嗎——怎、怎麼回事，剛剛……剛剛是我？是我？嘴巴擅自就……", "ご主人様、今日は何をご注文ですか～？　リリスの愛情がたっぷり詰まったオムライ……な、なに今の……私？　私が喋ってたの？　口が勝手に……", "0", "0", "0", "0", "cv_lilith_sw_9", "0", "0"},
[414809] = {414809, 11048, 10, 5, "1_》_500_2", "level3", "之前到底是怎麼回事……是夏天的詛咒嗎？不管是身體還是嘴，都在擅自做些奇怪的事……還有，那份感情到底是……", "さっきから何なのよ……夏の呪いだとでもいうの？　體も口も、私の意志とは関係なく勝手に……それに、この気持ちは一體……", "0", "0", "0", "0", "cv_lilith_sw_10", "0", "0"},
[414810] = {414810, 11048, 11, 5, "1_》_1000_2.5", "level4", "通感者，也許你以為自己可以仗著自己的能力肆無忌憚地深入瞭解每個人的內心，但是你要清楚，招惹我的代價是很重的——主人，你能陪我整個夏天嗎——咳，怎，怎麼回事啊？", "通感覚者さん。その力で好き勝手に他人の心に入り込めると思っているようだけど、力の代償についてはよく考えた方がいいわよ……ご主人様、この夏を一緒に過ごしてくださいませ……げほっげほっ……な、なに今の？", "0", "0", "0", "0", "cv_lilith_sw_11", "0", "0"},
[414811] = {414811, 11048, 12, 6, "0", "0", "變強總歸是好事。", "強くなるのは良いことよ。", "0", "0", "0", "0", "cv_lilith_sw_12", "0", "0"},
[414812] = {414812, 11048, 13, 7, "0", "0", "會在你眼中變得更加耀眼嗎？", "より輝いて見えるかしら？", "0", "0", "0", "0", "cv_lilith_sw_13", "0", "0"},
[414813] = {414813, 11048, 14, 8, "0", "0", "錯覺嗎……為什麼會出現不存在的記憶？", "錯覚かしら……どうして存在しないはずの記憶が浮かんで來るの？", "0", "0", "0", "0", "cv_lilith_sw_14", "0", "0"},
[414814] = {414814, 11048, 15, 9, "0", "0", "感官更敏銳了，真是複雜的心情。", "感覚がより鋭敏になったみたい。複雑な気持ちよ。", "0", "0", "0", "0", "cv_lilith_sw_15", "0", "0"},
[414815] = {414815, 11048, 16, 10, "0", "0", "難得的夏日……", "貴重な夏が……", "0", "0", "0", "0", "cv_lilith_sw_16", "0", "0"},
[414816] = {414816, 11048, 17, 11, "0", "0", "趁夏天還沒結束，回去吧。", "夏が終わらない內に、戻りましょう。", "0", "0", "0", "0", "cv_lilith_sw_17", "0", "0"},
[414817] = {414817, 11048, 18, 12, "0", "0", "狀態還沒從假期中調整回來。", "休暇明けからまだ調子が戻ってないわ。", "0", "0", "0", "0", "cv_lilith_sw_18", "0", "0"},
[414818] = {414818, 11048, 19, 13, "0", "0", "我們應該做得更好。", "私達ならもっとうまくやれるわ。", "0", "0", "0", "0", "cv_lilith_sw_19", "0", "0"},
[414819] = {414819, 11048, 20, 14, "0", "0", "這份感情不管多少次都讓人不愉快。", "この感覚、何度経験しても慣れないわね。", "0", "0", "0", "0", "cv_lilith_sw_20", "0", "0"},
[414820] = {414820, 11048, 21, 15, "0", "0", "融化在酷暑中吧。", "夏の暑さに溶けてしまいなさい。", "0", "0", "0", "0", "cv_lilith_sw_21", "0", "0"},
[414821] = {414821, 11048, 23, 16, "0", "0", "別來礙事。", "邪魔をしないで。", "0", "0", "0", "0", "cv_lilith_sw_23", "0", "0"},
[414822] = {414822, 11048, 24, 17, "0", "0", "真煩人。", "うっとうしいわ。", "0", "0", "0", "0", "cv_lilith_sw_24", "0", "0"},
[414823] = {414823, 11048, 25, 18, "0", "0", "現在可是【星之女僕】的度假時間！", "【星のメイド】は休暇中よ！", "0", "0", "0", "0", "cv_lilith_sw_25", "0", "0"},
[414824] = {414824, 11048, 26, 19, "0", "0", "苦夏……來了嗎……", "夏バテ……したみたい……", "0", "0", "0", "0", "cv_lilith_sw_26", "0", "0"},
[414825] = {414825, 11048, 27, 20, "0", "0", "不知不覺就習慣了……真可怕。", "いつの間にか慣れちゃったわ……いやね。", "0", "0", "0", "0", "cv_lilith_sw_27", "0", "0"},
[414826] = {414826, 11048, 28, 21, "0", "0", "真是讓人心跳的距離啊……呵呵。", "ドキドキするでしょ、この距離……ふふ。", "0", "0", "0", "0", "cv_lilith_sw_28", "0", "0"},
[414827] = {414827, 11048, 29, 21, "0", "0", "你還真是擅長這件事呢……到底幫多少女孩子做了？", "こういうの本當に上手よね……一體どれだけの女の子にして來たの？", "0", "0", "0", "0", "cv_lilith_sw_29", "0", "0"},
[414828] = {414828, 11048, 30, 22, "0", "0", "又來了。", "また來たわね。", "0", "0", "0", "0", "cv_lilith_sw_30", "0", "0"},
[414829] = {414829, 11048, 31, 23, "0", "0", "“泳衣”，這算提示嗎？", "水著って、これヒントなの？", "0", "0", "0", "0", "cv_lilith_sw_31", "0", "0"},
[414830] = {414830, 11048, 32, 24, "0", "0", "理所當然。", "當然よね。", "0", "0", "0", "0", "cv_lilith_sw_32", "0", "0"},
[414831] = {414831, 11048, 33, 25, "0", "0", "真無趣。", "つまらないわ。", "0", "0", "0", "0", "cv_lilith_sw_33", "0", "0"},
[414832] = {414832, 11048, 34, 26, "0", "0", "天氣真會看人臉色，你一來它就由陰轉晴了。", "お天道様はよく人を見てるの。あなたが來た途端に晴れて來たわ。", "0", "0", "0", "0", "cv_lilith_sw_34", "0", "0"},
[414833] = {414833, 11048, 35, 27, "0", "0", "我們的假期真的很少。", "本當に休む暇もないわ。", "0", "0", "0", "0", "cv_lilith_sw_35", "0", "0"},
[414834] = {414834, 11048, 36, 28, "0", "0", "最後留在場上的人一定是我。", "最後に殘るのはきっとこの私よ。", "0", "0", "0", "0", "cv_lilith_sw_36", "0", "0"},
[414835] = {414835, 11048, 37, 29, "0", "0", "你是要和其他人打招呼嗎？", "他の人にも聲をかけるつもり？", "0", "0", "0", "0", "cv_lilith_sw_37", "0", "0"},
[414836] = {414836, 11048, 38, 30, "0", "0", "又要有新的孽緣了呀……", "また新しい子に手を出すつもり？", "0", "0", "0", "0", "cv_lilith_sw_38", "0", "0"},
[414837] = {414837, 11048, 39, 31, "0", "0", "買什麼", "なにを買うのかしら。", "0", "0", "0", "0", "cv_lilith_sw_39", "0", "0"},
[414838] = {414838, 11048, 40, 32, "0", "0", "一起去吧。", "行きましょうか。", "0", "0", "0", "0", "cv_lilith_sw_40", "0", "0"},
[414839] = {414839, 11048, 41, 33, "0", "0", "真是讓人懷念的呆臉。", "相変わらずの間抜け面ね。", "0", "0", "0", "0", "cv_lilith_sw_41", "0", "0"},
[414840] = {414840, 11048, 42, 34, "0", "0", "還要調整設定嗎？", "設定を調整するの？", "0", "0", "0", "0", "cv_lilith_sw_42", "0", "0"},
[414841] = {414841, 11048, 43, 35, "0", "0", "海灘的邀請券說不定落在裡面了。", "ビーチへの招待狀が來てるかもしれないわね。", "0", "0", "0", "0", "cv_lilith_sw_43", "0", "0"},
[414842] = {414842, 11048, 44, 36, "0", "0", "保持安靜。", "靜かに。", "0", "0", "0", "0", "cv_lilith_sw_44", "0", "0"},
[414843] = {414843, 11048, 45, 37, "0", "0", "嗯。", "あら。", "0", "0", "0", "0", "cv_lilith_sw_45", "0", "0"},
[414900] = {414900, 11049, 1, 1, "0", "0", "蒼霧殘響", "ハツリバーブ", "0", "0", "0", "0", "cv_aertaiya_1", "0", "0"},
[414901] = {414901, 11049, 2, 2, "0", "0", "真不想值班啊……好想睡覺，好想看動畫……", "当直したくない……寝たい、アニメ観たい……", "0", "0", "0", "0", "cv_aertaiya_2", "0", "0"},
[414902] = {414902, 11049, 3, 3, "0", "0", "沒想到我會出現在這裡吧，蜥蜴先生！哼哼，不是有人說過嗎，世間所有的重逢，都是蓄謀已久的相遇——我沒記錯吧？", "驚いたでしょ、トカゲさん！ふふ、誰かが言ってたよね、世の中の再会はすべて仕組まれた出会いだって——間違ってないよね？", "0", "0", "0", "0", "cv_aertaiya_3", "0", "0"},
[414903] = {414903, 11049, 4, 4, "0", "idle", "人們沉浸在幻想裡，並不是因為幻想有多美好，而是現實太過殘酷。過去我想逃避，現在我想明白了，我要面對它，戰勝它，這樣才能讓我的幻想成為現實。", "人々が幻想に浸るのは、幻想がどれほど美しいかではなく、現実があまりにも残酷だからなんだ。昔は逃げたかったけど、今はわかったよ、向き合って、乗り越えなきゃ。そうすれば、私の幻想を現実にできる。", "0", "0", "0", "0", "cv_aertaiya_4", "0", "0"},
[414904] = {414904, 11049, 5, 4, "0", "idle2", "用自由當代價才能留在你身邊，你可真是了不起啊，領——航。", "自由を代償にしてまであなたのそばに居たいなんて、あなたって本当にすごいよ、ナビゲーター。", "0", "0", "0", "0", "cv_aertaiya_5", "0", "0"},
[414905] = {414905, 11049, 6, 4, "0", "idle3", "被我趕跑的那只原罪叫海德拉，我現在待的的隊伍也叫海德拉，我的隊友好像還是原罪……嗚哇，這真的是巧合嗎……等等，難道我也是原罪？", "私が追い払った原罪の名前はハイドラ、今のチームの名前もハイドラ、そして仲間も原罪みたい……うわ、これって本当に偶然？……待って、もしかして私も原罪？", "0", "0", "0", "0", "cv_aertaiya_6", "0", "0"},
[414906] = {414906, 11049, 7, 5, "1_》_0_0.8", "level1", "如果說生活真的如別人所說是一盒巧克力的話，我的那盒裡面一定裝滿了黑巧克力——苦澀？不，我的意思是成熟！性感！", "もし他の人が言うように人生が一箱のチョコレートだとしたら、私の箱はきっとダークチョコでいっぱい——苦い？いや、私が言いたいのは成熟だ！セクシーさだ！", "0", "0", "0", "0", "cv_aertaiya_7", "0", "0"},
[414907] = {414907, 11049, 8, 5, "1_》_0_0.8", "level1", "像是在撓癢癢一樣，還挺舒服的。", "なんだかくすぐったいけど、結構気持ちいい。", "0", "0", "0", "0", "cv_aertaiya_8", "0", "0"},
[414908] = {414908, 11049, 9, 5, "1_》_100_1.5", "level2", "我正處於謳歌青春的年齡，但是怎樣才算謳歌青春嗎？要去談一場轟轟烈烈的戀愛嗎？……現實的戀愛是什麼樣的啊？", "私は今、青春を謳歌する年齢だけど、どうすれば青春を謳歌してるって言えるんだろう？破天荒な恋愛をすればいいのかな？……現実の恋愛ってどんな感じなんだろう？", "0", "0", "0", "0", "cv_aertaiya_9", "0", "0"},
[414909] = {414909, 11049, 10, 5, "1_》_500_2", "level3", "說起來……我沒談過戀愛，不太清楚喜歡是種什麼樣的感情。不過我可以肯定的是，待在你身邊的時候，我很開心，也很安心。", "そういえば……恋愛したことないから、好きってどんな感情かわからない。でも、あなたのそばにいるとき、私はとても幸せで安心してるよ。", "0", "0", "0", "0", "cv_aertaiya_10", "0", "0"},
[414910] = {414910, 11049, 11, 5, "1_》_1000_2.5", "level4", "不知不覺我已經習慣待在你身邊了……你知道嗎，我無法想像有一天哪天醒來，你不在我身邊，或者我不在你身邊。", "いつの間にか、あなたのそばにいるのが当たり前になってた……わかる？朝目覚めて、あなたがそばにいないとか、そんなこと想像できないんだ。", "0", "0", "0", "0", "cv_aertaiya_11", "0", "0"},
[414911] = {414911, 11049, 12, 6, "0", "0", "等級提升！", "レベルアップ！ ", "0", "0", "0", "0", "cv_aertaiya_12", "0", "0"},
[414912] = {414912, 11049, 13, 7, "0", "0", "覺醒吧，我沉睡的潛力！", "目覚めよ、私の眠れる力！", "0", "0", "0", "0", "cv_aertaiya_13", "0", "0"},
[414913] = {414913, 11049, 14, 8, "0", "0", "現在，我登上食物鏈的頂端了吧……開玩笑的，只是個“遊戲玩笑”而已。", "今、私は食物連鎖の頂点に立ったよ……冗談、ただの「ゲームジョーク」さ。", "0", "0", "0", "0", "cv_aertaiya_14", "0", "0"},
[414914] = {414914, 11049, 15, 9, "0", "0", "只要吃掉124個自己，我就會無敵了！", "124人の自分を食べれば、私は無敵になる！", "0", "0", "0", "0", "cv_aertaiya_15", "0", "0"},
[414915] = {414915, 11049, 16, 10, "0", "0", "你們的救世主來了！", "あなたたちの救世主が来た！ ", "0", "0", "0", "0", "cv_aertaiya_16", "0", "0"},
[414916] = {414916, 11049, 17, 11, "0", "0", "這就是由我喚來的奇跡！", "これが私が呼び起こした奇跡！", "0", "0", "0", "0", "cv_aertaiya_17", "0", "0"},
[414917] = {414917, 11049, 18, 12, "0", "0", "作為新手駕駛員，我已經表現得很好了！", "新米ドライバーとして、私、かなりよくやってるよね！", "0", "0", "0", "0", "cv_aertaiya_18", "0", "0"},
[414918] = {414918, 11049, 19, 13, "0", "0", "遍體鱗傷的我們看起來就像真正的英雄一樣！", "傷だらけの私たち、まるで本当の英雄みたい！", "0", "0", "0", "0", "cv_aertaiya_19", "0", "0"},
[414919] = {414919, 11049, 20, 14, "0", "0", "輸得太醜陋了，這可不像我們的作風！", "こんなみにくい負け方、私たちらしくないよ！", "0", "0", "0", "0", "cv_aertaiya_20", "0", "0"},
[414920] = {414920, 11049, 21, 15, "0", "0", "輕鬆！", "楽勝！", "0", "0", "0", "0", "cv_aertaiya_21", "0", "0"},
[414921] = {414921, 11049, 23, 16, "0", "0", "面對我！", "かかってこい！ ", "0", "0", "0", "0", "cv_aertaiya_22", "0", "0"},
[414922] = {414922, 11049, 24, 17, "0", "0", "你們逃不掉的！", "逃げられないよ！", "0", "0", "0", "0", "cv_aertaiya_23", "0", "0"},
[414923] = {414923, 11049, 26, 19, "0", "0", "我有點……害怕。", "ちょっと……怖いな。", "0", "0", "0", "0", "cv_aertaiya_26", "0", "0"},
[414924] = {414924, 11049, 27, 20, "0", "0", "我可不會像動畫裡的女生那樣尖叫——反正你肯定有什麼理由吧……不可能真是走錯地方了吧？", "アニメの女の子みたいに叫んだりしないからね——どうせ理由があるんでしょ……まさか本当に間違って来たわけじゃないよね？", "0", "0", "0", "0", "cv_aertaiya_27", "0", "0"},
[414925] = {414925, 11049, 28, 21, "0", "0", "不該看的地方都被你看光了吧，“給我負起責任呀”……要是說這句話會不會太老土了？", "見ちゃいけないとこ全部見ちゃったでしょ、「責任取ってよ」……ちょっと古くさいかな？", "0", "0", "0", "0", "cv_aertaiya_28", "0", "0"},
[414926] = {414926, 11049, 29, 21, "0", "0", "對了，下次要不要一起去真正的溫泉？我對動畫裡的溫泉旅店一直都很感興趣！", "そうだ、今度本物の温泉に一緒に行かない？アニメの温泉旅館にずっと興味があったんだ！", "0", "0", "0", "0", "cv_aertaiya_29", "0", "0"},
[414927] = {414927, 11049, 30, 22, "0", "0", "嗯？", "え？ ", "0", "0", "0", "0", "cv_aertaiya_30", "0", "0"},
[414928] = {414928, 11049, 31, 23, "0", "0", "猜不出來的話就去查聲優名字吧！", "声優さんの名前を調べればわかるよ！", "0", "0", "0", "0", "cv_aertaiya_31", "0", "0"},
[414929] = {414929, 11049, 32, 24, "0", "0", "我的聲音難道不好記嗎？", "私の声、覚えにくい？", "0", "0", "0", "0", "cv_aertaiya_32", "0", "0"},
[414930] = {414930, 11049, 33, 25, "0", "0", "哼哼，在聽聲識人上，蜥蜴先生不如我呢。", "ふふ、声で人を見分けるのは、私のほうが上手いわね。", "0", "0", "0", "0", "cv_aertaiya_33", "0", "0"},
[414931] = {414931, 11049, 34, 26, "0", "0", "噓——我正在琢磨怎麼悄悄離開方舟呢。", "しー——方舟をこっそり離れる方法を考えてるの。", "0", "0", "0", "0", "cv_aertaiya_34", "0", "0"},
[414932] = {414932, 11049, 35, 27, "0", "0", "聽我說聽我說，我有一個計畫，一個最好的計畫！", "聞いて聞いて、作戦があるんだ、最高の作戦が！", "0", "0", "0", "0", "cv_aertaiya_35", "0", "0"},
[414933] = {414933, 11049, 36, 28, "0", "0", "屁股被踢痛了可不要告狀噢。", "お尻を蹴られて痛くても、文句言わないでね。", "0", "0", "0", "0", "cv_aertaiya_36", "0", "0"},
[414934] = {414934, 11049, 37, 29, "0", "0", "這麼多人……有社團嗎？有傳說中的動漫社嗎？", "こんなに人がいる……部活とかあるの？伝説のアニメ部とか？", "0", "0", "0", "0", "cv_aertaiya_37", "0", "0"},
[414935] = {414935, 11049, 38, 30, "0", "0", "女孩子一個接一個的靠過來，你真是搶手呀。", "女の子が次々に寄ってくるなんて、ほんとにモテるね。", "0", "0", "0", "0", "cv_aertaiya_38", "0", "0"},
[414936] = {414936, 11049, 39, 31, "0", "0", "我要最高配置的裝備！", "最高の装備が欲しい！ ", "0", "0", "0", "0", "cv_aertaiya_39", "0", "0"},
[414937] = {414937, 11049, 40, 32, "0", "0", "全部買下來吧！", "全部買っちゃおう！ ", "0", "0", "0", "0", "cv_aertaiya_40", "0", "0"},
[414938] = {414938, 11049, 41, 33, "0", "0", "我就知道你不一般！", "あなたはやっぱり特別だね！ ", "0", "0", "0", "0", "cv_aertaiya_41", "0", "0"},
[414939] = {414939, 11049, 42, 34, "0", "0", "全部拉滿！", "全部マックス！ ", "0", "0", "0", "0", "cv_aertaiya_42", "0", "0"},
[414940] = {414940, 11049, 43, 35, "0", "0", "一鍵領取！一鍵刪除！", "一括受け取り！一括削除！", "0", "0", "0", "0", "cv_aertaiya_43", "0", "0"},
[414941] = {414941, 11049, 44, 36, "0", "0", "Good Game.", "Good Game.", "0", "0", "0", "0", "cv_aertaiya_44", "0", "0"},
