[415000] = {415000, 11050, 1, 1, "0", "0", "蒼霧殘響~", "0", "0", "0", "0", "0", "cv_borinna2_1", "0", "0"},
[415001] = {415001, 11050, 2, 2, "0", "0", "好的，波琳娜一定會保護好這裏。", "0", "0", "0", "0", "0", "cv_borinna2_2", "0", "0"},
[415002] = {415002, 11050, 3, 3, "0", "0", "領航——！這麼快就又見面了，好開心。", "0", "0", "0", "0", "0", "cv_borinna2_3", "0", "0"},
[415003] = {415003, 11050, 4, 4, "0", "idle", "唔……嗯？波琳娜的身體是不是變小了？", "0", "0", "0", "0", "0", "cv_borinna2_4", "0", "0"},
[415004] = {415004, 11050, 5, 4, "0", "idle", "波琳娜已經不會害怕戰鬥……嗯，不會害怕……", "0", "0", "0", "0", "0", "cv_borinna2_5", "0", "0"},
[415005] = {415005, 11050, 6, 4, "0", "idle", "伊莉雅的左手變得和以前不一樣了，摸上去不是冷冰冰的了。雖然波琳娜不明白伊莉雅身上發生了什麼，不過應該是好事。對吧，領航。", "0", "0", "0", "0", "0", "cv_borinna2_6", "0", "0"},
[415006] = {415006, 11050, 7, 5, "1_》_0_0.8", "level1", "領航，我們再過一次聖誕節吧，波琳娜還想和大家一起堆雪人，打雪仗，還想要吃吉雅姐姐做好吃的飯，還想要和領航一起去大鯨魚背上玩捉迷藏。", "0", "0", "0", "0", "0", "cv_borinna2_7", "0", "0"},
[415007] = {415007, 11050, 8, 5, "1_》_0_0.8", "level1", "背後的翅膀，波琳娜也不知道是幹嘛用的。", "0", "0", "0", "0", "0", "cv_borinna2_8", "0", "0"},
[415008] = {415008, 11050, 9, 5, "1_》_100_1.5", "level2", "波琳娜還想要變大，變得和聖誕節時一樣大，那樣波琳娜以後就可以保護大家了。", "0", "0", "0", "0", "0", "cv_borinna2_9", "0", "0"},
[415009] = {415009, 11050, 10, 5, "1_》_500_2", "level3", "這兩把新武器，波琳娜已經用得越來越熟練了。即使再遇到大怪獸，波琳娜也不會害怕。", "0", "0", "0", "0", "0", "cv_borinna2_10", "0", "0"},
[415010] = {415010, 11050, 11, 5, "1_》_1000_2.5", "level4", "波琳娜還想試試那個，想要和領航連接在一起。“通感”……是這樣讀的嗎？能夠感受到領航的想法，波琳娜很喜歡那種感覺。", "0", "0", "0", "0", "0", "cv_borinna2_11", "0", "0"},
[415011] = {415011, 11050, 12, 6, "0", "0", "翅膀發光了。", "0", "0", "0", "0", "0", "cv_borinna2_12", "0", "0"},
[415012] = {415012, 11050, 13, 7, "0", "0", "流星……波琳娜抓住啦。", "0", "0", "0", "0", "0", "cv_borinna2_13", "0", "0"},
[415013] = {415013, 11050, 14, 8, "0", "0", "變成天使了！", "0", "0", "0", "0", "0", "cv_borinna2_14", "0", "0"},
