[415015] = {415015, 11050, 16, 10, "0", "0", "波琳娜來了哦。", "0", "0", "0", "0", "0", "cv_borinna2_16", "0", "0"},
[415016] = {415016, 11050, 17, 11, "0", "0", "全部殲滅，波琳娜很厲害的。", "0", "0", "0", "0", "0", "cv_borinna2_17", "0", "0"},
[415017] = {415017, 11050, 18, 12, "0", "0", "那幢房子……波琳娜不是故意的。", "0", "0", "0", "0", "0", "cv_borinna2_18", "0", "0"},
[415018] = {415018, 11050, 19, 13, "0", "0", "別……別告訴伊莉雅。", "0", "0", "0", "0", "0", "cv_borinna2_19", "0", "0"},
