[415020] = {415020, 11050, 21, 15, "0", "0", "一個敵人換兩顆糖！", "0", "0", "0", "0", "0", "cv_borinna2_21", "0", "0"},
[415021] = {415021, 11050, 23, 16, "0", "0", "該用刀還是槍……", "0", "0", "0", "0", "0", "cv_borinna2_22", "0", "0"},
