[415025] = {415025, 11050, 27, 20, "0", "0", "又能洗澡澡了耶。", "0", "0", "0", "0", "0", "cv_borinna2_27", "0", "0"},
[415026] = {415026, 11050, 28, 21, "0", "0", "哼哼，癢癢的，哼哼……", "0", "0", "0", "0", "0", "cv_borinna2_28", "0", "0"},
[415027] = {415027, 11050, 29, 21, "0", "0", "香香的味道，是什麼呢？", "0", "0", "0", "0", "0", "cv_borinna2_29", "0", "0"},
[415028] = {415028, 11050, 30, 22, "0", "0", "又要玩遊戲了嗎？讓我來！", "0", "0", "0", "0", "0", "cv_borinna2_30", "0", "0"},
