[415035] = {415035, 11050, 37, 29, "0", "0", "領航認識這麼多姐姐嗎？", "0", "0", "0", "0", "0", "cv_borinna2_37", "0", "0"},
[415036] = {415036, 11050, 38, 30, "0", "0", "朋友許願機？", "0", "0", "0", "0", "0", "cv_borinna2_38", "0", "0"},
[415037] = {415037, 11050, 39, 31, "0", "0", "哈~我的舊武器原來在這裏！", "0", "0", "0", "0", "0", "cv_borinna2_39", "0", "0"},
[415038] = {415038, 11050, 40, 32, "0", "0", "領航，波琳娜想吃糖。", "0", "0", "0", "0", "0", "cv_borinna2_40", "0", "0"},
[415039] = {415039, 11050, 41, 33, "0", "0", "嘿嘿，給領航畫成大臉貓。", "0", "0", "0", "0", "0", "cv_borinna2_41", "0", "0"},
[415040] = {415040, 11050, 42, 34, "0", "0", "不好玩。", "0", "0", "0", "0", "0", "cv_borinna2_42", "0", "0"},
[415041] = {415041, 11050, 43, 35, "0", "0", "“油箱”，波琳娜認得這個詞。", "0", "0", "0", "0", "0", "cv_borinna2_43", "0", "0"},
[415042] = {415042, 11050, 44, 36, "0", "0", "大家在說什麼？", "0", "0", "0", "0", "0", "cv_borinna2_44", "0", "0"},
[415043] = {415043, 11050, 45, 37, "0", "0", "嘿呀——", "0", "0", "0", "0", "0", "cv_borinna2_45", "0", "0"},
[415100] = {415100, 11051, 1, 1, "0", "0", "蒼霧殘響", "0", "0", "0", "0", "0", "cv_Julius_vd_1", "0", "0"},
[415101] = {415101, 11051, 2, 2, "0", "0", "讓我以現、現在這個狀態待在、在這麼顯眼的地方真的好嗎……", "0", "0", "0", "0", "0", "cv_Julius_vd_2", "0", "0"},
[415102] = {415102, 11051, 3, 3, "0", "0", "我的名字是朱……咳咳，阿瑟·潘德拉貢，初次見面，請多指教。……非得再說一遍嗎？", "0", "0", "0", "0", "0", "cv_Julius_vd_3", "0", "0"},
[415103] = {415103, 11051, 4, 4, "0", "idle", "哼哼哼~啊……您聽到了？呵呵，真是不好意思……那是我家鄉的鋼琴曲，哪天由我親自演奏給您聽吧。", "0", "0", "0", "0", "0", "cv_Julius_vd_4", "0", "0"},
[415104] = {415104, 11051, 5, 4, "0", "idle", "嗚……咖啡好苦啊……沒想到身體變小了之後味覺也變得敏感了……還是多加點牛奶和糖吧……", "0", "0", "0", "0", "0", "cv_Julius_vd_5", "0", "0"},
[415105] = {415105, 11051, 6, 4, "0", "idle", "聽說人類精神的老化是由於肉體的老化失去各種激素引起的……所以您所見的我的不成熟之處，肯定也是因為我變得“年輕”了。", "0", "0", "0", "0", "0", "cv_Julius_vd_6", "0", "0"},
[415106] = {415106, 11051, 7, 5, "1_》_0_0.8", "level1", "領航的手指……好燙啊。怎麼了？是身體不舒服了嗎？", "0", "0", "0", "0", "0", "cv_Julius_vd_7", "0", "0"},
[415107] = {415107, 11051, 8, 5, "1_》_0_0.8", "level1", "抱歉……我變成這樣之後給您添了不少麻煩吧……既要幫我瞞住查麗莎她們，還要幫我做康復的訓練。", "0", "0", "0", "0", "0", "cv_Julius_vd_8", "0", "0"},
[415108] = {415108, 11051, 9, 5, "1_》_100_1.5", "level2", "咳……所以領航……我、我的、假、假情書你看了之後……有……有什麼感、感悟之類的嗎……", "0", "0", "0", "0", "0", "cv_Julius_vd_9", "0", "0"},
[415109] = {415109, 11051, 10, 5, "1_》_500_2", "level3", "……如果是以前的我的話，一定會說“在沒有結束這一切之前，只是這樣看著彼此，就足夠了。”，但是我現在竟然為這份覺悟感到不甘。", "0", "0", "0", "0", "0", "cv_Julius_vd_10", "0", "0"},
[415110] = {415110, 11051, 11, 5, "1_》_1000_2.5", "level4", "我、我不能對自己再撒謊了，不能再騙自己說“我不能再靠近您了”……我已經做不到強迫自己不去看您了……我……我……", "0", "0", "0", "0", "0", "cv_Julius_vd_11", "0", "0"},
[415111] = {415111, 11051, 12, 6, "0", "0", "麻煩您了。", "0", "0", "0", "0", "0", "cv_Julius_vd_12", "0", "0"},
[415112] = {415112, 11051, 13, 7, "0", "0", "感覺又離變回來近了一步。", "0", "0", "0", "0", "0", "cv_Julius_vd_13", "0", "0"},
[415113] = {415113, 11051, 14, 8, "0", "0", "重新體驗一遍這種感覺……我本以為會是一段百無聊賴的路途，沒想到由您陪在身邊……也不賴呢。", "0", "0", "0", "0", "0", "cv_Julius_vd_14", "0", "0"},
[415114] = {415114, 11051, 15, 9, "0", "0", "任重而道遠。", "0", "0", "0", "0", "0", "cv_Julius_vd_15", "0", "0"},
[415115] = {415115, 11051, 16, 10, "0", "0", "我會繼續履行我的職責的。", "0", "0", "0", "0", "0", "cv_Julius_vd_16", "0", "0"},
[415116] = {415116, 11051, 17, 11, "0", "0", "好久沒有上戰場了……看來我並未忘記心中的這份榮耀。", "0", "0", "0", "0", "0", "cv_Julius_vd_17", "0", "0"},
[415117] = {415117, 11051, 18, 12, "0", "0", "……能凱旋而歸了呢。", "0", "0", "0", "0", "0", "cv_Julius_vd_18", "0", "0"},
[415118] = {415118, 11051, 19, 13, "0", "0", "如果是“長大的我”的話，會做的更好吧。", "0", "0", "0", "0", "0", "cv_Julius_vd_19", "0", "0"},
[415119] = {415119, 11051, 20, 14, "0", "0", "請您先撤離吧，領航。", "0", "0", "0", "0", "0", "cv_Julius_vd_20", "0", "0"},
[415120] = {415120, 11051, 21, 15, "0", "0", "嗯……嗯？", "0", "0", "0", "0", "0", "cv_Julius_vd_21", "0", "0"},
[415121] = {415121, 11051, 23, 16, "0", "0", "喝呀！", "0", "0", "0", "0", "0", "cv_Julius_vd_22", "0", "0"},
[415122] = {415122, 11051, 24, 17, "0", "0", "還沒結束！", "0", "0", "0", "0", "0", "cv_Julius_vd_23", "0", "0"},
[415123] = {415123, 11051, 25, 18, "0", "0", "即使是這副模樣，朱利烏斯的劍依舊將為您開闢未來！！！", "0", "0", "0", "0", "0", "cv_Julius_vd_24", "0", "0"},
[415124] = {415124, 11051, 26, 19, "0", "0", "我只能……陪您走到這裏了。", "0", "0", "0", "0", "0", "cv_Julius_vd_26", "0", "0"},
[415125] = {415125, 11051, 27, 20, "0", "0", "以這幅樣子見面還是第一次呢。", "0", "0", "0", "0", "0", "cv_Julius_vd_27", "0", "0"},
[415126] = {415126, 11051, 28, 21, "0", "0", "怎麼了？您……還不行動嗎？", "0", "0", "0", "0", "0", "cv_Julius_vd_28", "0", "0"},
[415127] = {415127, 11051, 29, 21, "0", "0", "請慢慢來吧，我會等待您的。", "0", "0", "0", "0", "0", "cv_Julius_vd_29", "0", "0"},
[415128] = {415128, 11051, 30, 22, "0", "0", "事件……?", "0", "0", "0", "0", "0", "cv_Julius_vd_30", "0", "0"},
[415129] = {415129, 11051, 31, 23, "0", "0", "變成這幅您不熟悉的模樣後……也要玩這個遊戲嗎？", "0", "0", "0", "0", "0", "cv_Julius_vd_31", "0", "0"},
[415130] = {415130, 11051, 32, 24, "0", "0", "說實話……很開心。至少變成這樣您還認得出我……這就足夠了。", "0", "0", "0", "0", "0", "cv_Julius_vd_32", "0", "0"},
[415131] = {415131, 11051, 33, 25, "0", "0", "也……也是沒辦法的事情呢，呵呵，只能從新的我開始認識了。", "0", "0", "0", "0", "0", "cv_Julius_vd_33", "0", "0"},
[415132] = {415132, 11051, 34, 26, "0", "0", "歡迎回家。", "0", "0", "0", "0", "0", "cv_Julius_vd_34", "0", "0"},
[415133] = {415133, 11051, 35, 27, "0", "0", "戰鬥……要開始了！", "0", "0", "0", "0", "0", "cv_Julius_vd_35", "0", "0"},
[415134] = {415134, 11051, 36, 28, "0", "0", "熟悉一下這幅年輕的身體吧。", "0", "0", "0", "0", "0", "cv_Julius_vd_36", "0", "0"},
[415135] = {415135, 11051, 37, 29, "0", "0", "咳咳……我是阿瑟·潘德拉貢。", "0", "0", "0", "0", "0", "cv_Julius_vd_37", "0", "0"},
[415136] = {415136, 11051, 38, 30, "0", "0", "現在還不是結交新朋友的時候……以這副面貌。", "0", "0", "0", "0", "0", "cv_Julius_vd_38", "0", "0"},
[415137] = {415137, 11051, 39, 31, "0", "0", "裝備也要換一身吧。", "0", "0", "0", "0", "0", "cv_Julius_vd_39", "0", "0"},
[415138] = {415138, 11051, 40, 32, "0", "0", "補給品？", "0", "0", "0", "0", "0", "cv_Julius_vd_40", "0", "0"},
[415139] = {415139, 11051, 41, 33, "0", "0", "在戰鬥前最後再檢查一下自己的狀態吧。", "0", "0", "0", "0", "0", "cv_Julius_vd_41", "0", "0"},
[415140] = {415140, 11051, 42, 34, "0", "0", "調整下設置吧。", "0", "0", "0", "0", "0", "cv_Julius_vd_42", "0", "0"},
[415141] = {415141, 11051, 43, 35, "0", "0", "有來信。", "0", "0", "0", "0", "0", "cv_Julius_vd_43", "0", "0"},
[415142] = {415142, 11051, 44, 36, "0", "0", "整理一下現在獲得的情報吧。", "0", "0", "0", "0", "0", "cv_Julius_vd_44", "0", "0"},
[415143] = {415143, 11051, 45, 37, "0", "0", "嗯……", "0", "0", "0", "0", "0", "cv_Julius_vd_45", "0", "0"},
[415200] = {415200, 11052, 1, 1, "0", "0", "蒼霧殘響", "0", "0", "0", "0", "0", "cv_sps_001", "0", "0"},
[415201] = {415201, 11052, 2, 2, "0", "0", "畢竟我是勇者，被人依靠是當然的，護衛工作就交給我吧。", "0", "0", "0", "0", "0", "cv_sps_002", "0", "0"},
[415202] = {415202, 11052, 3, 3, "0", "0", "我是斯珀絲，未來的救世主，人類最後的希望，註定要拯救世界的勇者，記清楚了嗎？", "0", "0", "0", "0", "0", "cv_sps_003", "0", "0"},
[415203] = {415203, 11052, 4, 4, "0", "idle", "等我拯救世界之後，“斯珀絲”這個名字一定會傳遍全世界，到時候人人都會讚頌我，崇拜我，永遠記得我，嘿嘿。", "0", "0", "0", "0", "0", "cv_sps_004", "0", "0"},
[415204] = {415204, 11052, 5, 4, "0", "idle", "生命的長度在出生之時就已經被定好，所以，我會在用自己的方式去延伸自己的寬度與高度。", "0", "0", "0", "0", "0", "cv_sps_005", "0", "0"},
[415205] = {415205, 11052, 6, 4, "0", "idle", "沒人規定過勇者小隊的成員數量，所以僅有你和我的勇者小隊也是成立的——畢竟，光靠我和你，拯救世界也綽綽有餘了。", "0", "0", "0", "0", "0", "cv_sps_006", "0", "0"},
[415206] = {415206, 11052, 7, 5, "1_》_0_0.8", "level1", "在我的印象裡，這個世界一直都是這樣，破破爛爛的，什麼時候毀滅也不奇怪。我知道，它一定是在等待一個勇者出現，將它恢復成以前的模樣——毫無疑問，那個人就是我。", "0", "0", "0", "0", "0", "cv_sps_007", "0", "0"},
[415207] = {415207, 11052, 8, 5, "1_》_0_0.8", "level1", "這顆星球以前有多少人啊？幾十億？真的假的，你不會在哄我吧？這個數字……光是聽著就要窒息了。", "0", "0", "0", "0", "0", "cv_sps_008", "0", "0"},
[415208] = {415208, 11052, 9, 5, "1_》_100_1.5", "level2", "你以前一定是個拈花惹草的壞男人，不然怎麼會有那麼多人盯著你……不管你以前和她們什麼關係，現在都是我的一號同伴，你是我的人，清楚了嗎？", "0", "0", "0", "0", "0", "cv_sps_009", "0", "0"},
[415209] = {415209, 11052, 10, 5, "1_》_500_2", "level3", "人最大的恐懼是死亡，但比死亡更讓人恐懼的是被遺忘……我會讓旅途中遇到的每個人都記住我，這也是旅行的意義。", "0", "0", "0", "0", "0", "cv_sps_010", "0", "0"},
[415210] = {415210, 11052, 11, 5, "1_》_1000_2.5", "level4", "我不能決定自己為什麼而生，也無法決定自己為什麼而死——所以，就當是我對命運的報復吧，我會讓你一輩子都記住我，想忘也忘不掉我的。這是我對你下的詛咒，領航。", "0", "0", "0", "0", "0", "cv_sps_011", "0", "0"},
[415211] = {415211, 11052, 12, 6, "0", "0", "要是能用指令升級就好了。", "0", "0", "0", "0", "0", "cv_sps_012", "0", "0"},
[415212] = {415212, 11052, 13, 7, "0", "0", "已經到上限了嗎？", "0", "0", "0", "0", "0", "cv_sps_013", "0", "0"},
[415213] = {415213, 11052, 14, 8, "0", "0", "成長係的勇者是沒有極限的。", "0", "0", "0", "0", "0", "cv_sps_014", "0", "0"},
[415214] = {415214, 11052, 15, 9, "0", "0", "升到滿級吧。", "0", "0", "0", "0", "0", "cv_sps_015", "0", "0"},
[415215] = {415215, 11052, 16, 10, "0", "0", "別擔心，有我在呢。", "0", "0", "0", "0", "0", "cv_sps_016", "0", "0"},
[415216] = {415216, 11052, 17, 11, "0", "0", "不做到這種程度，怎麼拯救世界？", "0", "0", "0", "0", "0", "cv_sps_017", "0", "0"},
[415217] = {415217, 11052, 18, 12, "0", "0", "我只是沒有拿出全部實力。", "0", "0", "0", "0", "0", "cv_sps_018", "0", "0"},
[415218] = {415218, 11052, 19, 13, "0", "0", "只是在熱身。", "0", "0", "0", "0", "0", "cv_sps_019", "0", "0"},
[415219] = {415219, 11052, 20, 14, "0", "0", "太丟人了，好想去死。", "0", "0", "0", "0", "0", "cv_sps_020", "0", "0"},
[415220] = {415220, 11052, 21, 15, "0", "0", "成為經驗值吧。", "0", "0", "0", "0", "0", "cv_sps_021", "0", "0"},
[415221] = {415221, 11052, 23, 16, "0", "0", "一刀兩斷，勇者劍！", "0", "0", "0", "0", "0", "cv_sps_022", "0", "0"},
[415222] = {415222, 11052, 24, 17, "0", "0", "還沒有死嗎？", "0", "0", "0", "0", "0", "cv_sps_023", "0", "0"},
[415223] = {415223, 11052, 25, 18, "0", "0", "就讓你們見識一下，全盛期的勇者有多強吧。", "0", "0", "0", "0", "0", "cv_sps_025", "0", "0"},
[415224] = {415224, 11052, 26, 19, "0", "0", "我……是不會死的。", "0", "0", "0", "0", "0", "cv_sps_026", "0", "0"},
[415225] = {415225, 11052, 27, 20, "0", "0", "你也要一起來嗎？", "0", "0", "0", "0", "0", "cv_sps_027", "0", "0"},
[415226] = {415226, 11052, 28, 21, "0", "0", "小的時候，媽媽還會幫我洗澡……後來她嫌麻煩，就再也沒幫過了。", "0", "0", "0", "0", "0", "cv_sps_028", "0", "0"},
[415227] = {415227, 11052, 29, 21, "0", "0", "不能再這麼放鬆了……懈怠是勇者的頭號大敵。", "0", "0", "0", "0", "0", "cv_sps_029", "0", "0"},
[415228] = {415228, 11052, 30, 22, "0", "0", "觸發特殊事件了？", "0", "0", "0", "0", "0", "cv_sps_030", "0", "0"},
[415229] = {415229, 11052, 31, 23, "0", "0", "這件事有什麼難度嗎？", "0", "0", "0", "0", "0", "cv_sps_031", "0", "0"},
[415230] = {415230, 11052, 32, 24, "0", "0", "身為我唯一的同伴，這是理所當然該做到的事。", "0", "0", "0", "0", "0", "cv_sps_032", "0", "0"},
[415231] = {415231, 11052, 33, 25, "0", "0", "這次就算了，之後你要把我的聲音記在靈魂深處，明白嗎？", "0", "0", "0", "0", "0", "cv_sps_033", "0", "0"},
[415232] = {415232, 11052, 34, 26, "0", "0", "醒了？那就跟我一起去拯救這個一塌糊塗的世界吧。", "0", "0", "0", "0", "0", "cv_sps_034", "0", "0"},
[415233] = {415233, 11052, 35, 27, "0", "0", "準備好繼續我們的旅行了嗎？", "0", "0", "0", "0", "0", "cv_sps_035", "0", "0"},
[415234] = {415234, 11052, 36, 28, "0", "0", "被打哭了別找媽媽告狀啊。", "0", "0", "0", "0", "0", "cv_sps_036", "0", "0"},
[415235] = {415235, 11052, 37, 29, "0", "0", "舊時代的駕駛員也沒什麼特別之處。", "0", "0", "0", "0", "0", "cv_sps_037", "0", "0"},
[415236] = {415236, 11052, 38, 30, "0", "0", "事先說好，我不會付僱傭費的。", "0", "0", "0", "0", "0", "cv_sps_038", "0", "0"},
[415237] = {415237, 11052, 39, 31, "0", "0", "每個人的專屬套裝都要集齊啊。", "0", "0", "0", "0", "0", "cv_sps_039", "0", "0"},
[415238] = {415238, 11052, 40, 32, "0", "0", "可以賒賬嗎，我以後再還。", "0", "0", "0", "0", "0", "cv_sps_040", "0", "0"},
[415239] = {415239, 11052, 41, 33, "0", "0", "還不錯，和我比起來就一般了。", "0", "0", "0", "0", "0", "cv_sps_041", "0", "0"},
[415240] = {415240, 11052, 42, 34, "0", "0", "用默認就行了。", "0", "0", "0", "0", "0", "cv_sps_042", "0", "0"},
[415241] = {415241, 11052, 43, 35, "0", "0", "會有新郵件嗎？", "0", "0", "0", "0", "0", "cv_sps_043", "0", "0"},
