[420000] = {420000, 12000, 1, 1, "0", "0", "蒼霧殘響！", "蒼霧殘響（ハツリバーブ）！", "0", "0", "蒼霧殘響！", "0", "cv_kinkura_32", "0", "0"},
[420001] = {420001, 12000, 2, 2, "0", "0", "喔吼~還真是有眼光啊~", "おほほ、見る目があるのね。", "0", "0", "哦吼~還真是有眼光啊~", "0", "cv_kinkura_2", "0", "0"},
[420002] = {420002, 12000, 3, 3, "0", "0", "喔吼吼~你就是那個多瑙的領航嗎？聽好了，本小姐的名字是金庫啦，好好記住吧。", "おーっほっほ、あんたがあのダニューブのナビゲーター？よく聞いて！あたしはキンクラ。ちゃんと覚えなさい？", "0", "0", "哦吼吼~你就是那個多瑙的領航嗎？聽好了，本小姐的名字是金庫啦，好好記住吧。", "0", "cv_kinkura_1", "0", "0"},
[420003] = {420003, 12000, 4, 4, "0", "idle", "富有的人貢獻金錢，強壯的人貢獻力量。當然~對於我來說，金錢就是力量！", "お金持ちがお金を出す。體の強い人が力を出す。まぁ、あたしにとっては、お金イコール力だからね！", "0", "0", "富有的人貢獻金錢，強壯的人貢獻力量。當然~對於我來說，金錢就是力量！", "0", "cv_kinkura_3", "0", "0"},
[420004] = {420004, 12000, 5, 4, "0", "idle", "真是可惜啊，像你這樣的人才如果能來九州的話，一定會為我們帶來新的變革吧。", "殘念ね。あんたみたいな人が九州に來たら、きっと新しい変化をもたらしてくれるのに。", "0", "0", "真是可惜啊，像你這樣的人才如果能來九州的話，一定會為我們帶來新的變革吧。", "0", "cv_kinkura_4", "0", "0"},
[420005] = {420005, 12000, 6, 4, "0", "idle", "多瑙的領航，你不覺得露露啦太天真了嗎？她那種溫柔的性格，太容易被人利用了。嗯？你也這麼覺得……喂，她可是本小姐先看上的！", "ルルラってホント単純すぎる。そう思わない？あんな優しい性格じゃ利用されちゃうよね。そっか、あんたもそう思って……？待って、彼女はあたしが先に目を付けたんだからね！", "0", "0", "多瑙的領航，你不覺得露露啦太天真了嗎？她那種溫柔的性格，太容易被人利用了。嗯？你也這麼覺得……喂，她可是本小姐先看上的！", "0", "cv_kinkura_29", "0", "0"},
[420006] = {420006, 12000, 7, 5, "1_》_0_0.8", "level1", "加入這場戰爭，不過是本小姐計劃的第一步。與原罪的戰爭結束後，本小姐的商業帝國也就成型了，哼哼哼！", "この戦爭に參加するのはあたしの計畫の第一歩に過ぎない。原罪との戦爭が終わったら、あたしの商業帝國も形になってるはず。ふっふっふー", "0", "0", "加入這場戰爭，不過是本小姐計畫的第一步。與原罪的戰爭結束後，本小姐的商業帝國也就成型了，哼哼哼！", "0", "cv_kinkura_30", "0", "0"},
[420007] = {420007, 12000, 8, 5, "1_》_0_0.8", "level1", "喔吼~難道說你終於打算轉部了嗎？放心好了，只要有本小姐的指示，你的待遇一切從優。", "おほほほ、ようやく転部を決心したの？安心して。あたしからの指示さえあれば、あんたの待遇は保証されるよ。", "0", "0", "哦吼~難道說你終於打算轉部了嗎？放心好了，只要有本小姐的指示，你的待遇一切從優。", "0", "cv_kinkura_5", "0", "0"},
[420008] = {420008, 12000, 9, 5, "1_》_100_1.5", "level2", "沒錯，沒錯。本小姐確實是結果主義者，只要能夠幫助到那些有困難的人。我既可以是商人，也可以是戰士。", "そう、そうなのよ。困ってる人を助けられるかどうか、あたしは成果主義者なの。あたしは商人でもあり、戦士でもあるのよ。", "0", "0", "沒錯，沒錯。本小姐確實是結果主義者，只要能夠幫助到那些有困難的人。我既可以是商人，也可以是戰士。", "0", "cv_kinkura_6", "0", "0"},
[420009] = {420009, 12000, 10, 5, "1_》_500_2", "level3", "雖然家裡的長輩曾經教導過我們，不要妄圖使用金錢解決一切問題。但是，我明白，有些事情必須要用金錢來解決……比如說，想要為那些流離失所的孩子們建起一座大廈，光靠力氣是絕對辦不到的。", "全てのことをお金で解決しようとしてはいけないって、家族に教わってるけど。でも、時にはそうしなければならないこともあると、あたしは思ってる……たとえば、居場所を失ってしまった子供たちのためにビルを建てることは、力だけじゃできないでしょ。", "0", "0", "雖然家裡的長輩曾經教導過我們，不要妄圖使用金錢解決一切問題。但是，我明白，有些事情必須要用金錢來解決……比如說，想要為那些流離失所的孩子們建起一座大廈，光靠力氣是絕對辦不到的。", "0", "cv_kinkura_7", "0", "0"},
[420010] = {420010, 12000, 11, 5, "1_》_1000_2.5", "level4", "無價之寶嗎……確實啊，我承認，這個世界上確實存在著無法用金錢衡量的事物。比如爺爺曾經說過的，人和人之間的聯繫，信任，與愛意……究竟從何時起，我好像也能漸漸體會到這其中的含義了。", "価値なき寶か……確かに、この世にはお金で価値を判斷できないものはある。たとえば、人と人の間にある繋がり、信頼、愛がそうだって……おじいちゃんが言ってた。いつの間にかあたしもその意味が分かるようになった気がする。", "0", "0", "無價之寶嗎……確實啊，我承認，這個世界上確實存在著無法用金錢衡量的事物。比如爺爺曾經說過的，人和人之間的聯繫，信任，與愛意……究竟從何時起，我好像也能漸漸體會到這其中的含義了。", "0", "cv_kinkura_8", "0", "0"},
[420011] = {420011, 12000, 12, 6, "0", "0", "看來我的股勢要大漲啦。", "どうやらあたしの株が大きく上がったみたいね。", "0", "0", "看來我的股勢要大漲啦。", "0", "cv_kinkura_9", "0", "0"},
[420012] = {420012, 12000, 13, 7, "0", "0", "喔吼吼~沒錯，就是這樣，你投入得越多我的力量也會變得越大。這便是，等價交換！", "おーっほっほ、そうなの。あんたからの投資が多いほど、あたしの力は大きくなるの。これはいわば等価交換ってやつなのよ！", "0", "0", "哦吼吼~沒錯，就是這樣，你投入得越多我的力量也會變得越大。這便是，等價交換！", "0", "cv_kinkura_10", "0", "0"},
[420013] = {420013, 12000, 14, 8, "0", "0", "將攢到現在的積蓄全部都投在我身上了嗎？這樣真的好嗎？事到如今本小姐可不允許你反悔喔~", "今まで貯めてきたものを全部あたしに？本當にいいの？後悔しても遅いわよっ。", "0", "0", "將攢到現在的積蓄全部都投在我身上了嗎？這樣真的好嗎？事到如今本小姐可不允許你反悔哦~", "0", "cv_kinkura_11", "0", "0"},
[420014] = {420014, 12000, 15, 9, "0", "0", "看來新訂的貨到了啊，正好想去活動一下呢。", "新しく発注したものが屆いたみたいね。ちょうど、體を動かそうと思ってたところなの。", "0", "0", "看來新訂的貨到了啊，正好想去活動一下呢。", "0", "cv_kinkura_12", "0", "0"},
[420015] = {420015, 12000, 16, 10, "0", "0", "來試試新買的玩具吧。", "新しく買ったおもちゃを試してみようっと。", "0", "0", "來試試新買的玩具吧。", "0", "cv_kinkura_13", "0", "0"},
[420016] = {420016, 12000, 17, 11, "0", "0", "金錢就是力量！", "お金こそ力よ！", "0", "0", "金錢就是力量！", "0", "cv_kinkura_14", "0", "0"},
[420017] = {420017, 12000, 18, 12, "0", "0", "喔吼~看來你們這邊給的獎金也不算少嘛。", "おほほほ、どうやらあんたたちからの報酬も少なくないみたいね。", "0", "0", "哦吼~看來你們這邊給的獎金也不算少嘛。", "0", "cv_kinkura_15", "0", "0"},
[420018] = {420018, 12000, 19, 13, "0", "0", "哼，本小姐只不過是稍微有些累了而已。", "ふん。ちょっと疲れただけよ。", "0", "0", "哼，本小姐只不過是稍微有些累了而已。", "0", "cv_kinkura_16", "0", "0"},
[420019] = {420019, 12000, 20, 14, "0", "0", "果然……除了金錢外還需要投入更多的精力啊。", "やっぱり……お金以外にももっと力を入れるべきだったわ。", "0", "0", "果然……除了金錢外還需要投入更多的精力啊。", "0", "cv_kinkura_17", "0", "0"},
[420020] = {420020, 12000, 21, 15, "0", "0", "你的賞金本小姐可不稀罕喔。", "あんたからの賞金、別に要らないわ。", "0", "0", "你的賞金本小姐可不稀罕哦。", "0", "cv_kinkura_18", "0", "0"},
[420021] = {420021, 12000, 23, 16, "0", "0", "你們的好日子要到頭了喔~", "どうやらここまでのようね。", "0", "0", "你們的好日子要到頭了哦~", "0", "cv_kinkura_20", "0", "0"},
[420022] = {420022, 12000, 22, 38, "0", "0", "喂~", "ちょっと待って。", "0", "0", "喂~", "0", "cv_kinkura_19", "0", "0"},
[420023] = {420023, 12000, 26, 19, "0", "0", "怎麼會……歐朵啦……領航……救救我……", "そんな……オードラ……ナビゲーター……助けて……", "0", "0", "怎麼會……歐朵啦……領航……救救我……", "0", "cv_kinkura_21", "0", "0"},
[420024] = {420024, 12000, 27, 20, "0", "0", "你來了啊，多瑙的領航，要和本小姐一起泡澡嗎？", "來たんだ？ナビゲーター。あたしと一緒にお風呂に入る？", "0", "0", "你來了啊，多瑙的領航，要和本小姐一起泡澡嗎？", "0", "cv_kinkura_22", "0", "0"},
[420025] = {420025, 12000, 28, 21, "0", "0", "喔吼吼~沒想到你們多瑙也有泡澡的習慣啊。", "おほほ、あんたたちダニューブにもお風呂に入る習慣があったのね。", "0", "0", "哦吼吼~沒想到你們多瑙也有泡澡的習慣啊。", "0", "cv_kinkura_23", "0", "0"},
[420026] = {420026, 12000, 29, 21, "0", "0", "說起來，領航下次要不要來體驗下多瑙那邊的澡堂文化呢？放心好了，我請客就是了。", "そういえば、今度は九州のお風呂文化を體験してみない？安心して、あたしのおごりだから。", "0", "0", "說起來，領航下次要不要來體驗下九州那邊的澡堂文化呢？放心好了，我請客就是了。", "0", "cv_kinkura_24", "0", "0"},
[420027] = {420027, 12000, 30, 22, "0", "0", "看來這裡也有窺探著我的財寶的小偷呢。", "どうやらここにもあたしの財寶を狙ってる泥棒がいるみたい。", "0", "0", "看來這裡也有窺探著我的財寶的小偷呢。", "0", "cv_kinkura_25", "0", "0"},
[420028] = {420028, 12000, 31, 23, "0", "0", "不要有壓力，放鬆挑戰吧。", "自分にプレッシャーをかけないで。リラックスして挑戦しなさい。", "0", "0", "不要有壓力，放鬆挑戰吧。", "0", "cv_kinkura_26", "0", "0"},
[420029] = {420029, 12000, 32, 24, "0", "0", "喔吼吼~看來你和本小姐還真是有緣啊。", "おほほ、どうやらあたしとは隨分縁があるようね。", "0", "0", "哦吼吼~看來你和本小姐還真是有緣啊。", "0", "cv_kinkura_27", "0", "0"},
[420030] = {420030, 12000, 33, 25, "0", "0", "你總會做出讓本小姐出乎意料的事呢~當然，這次可不算驚喜~", "あんたっていつも予想のつかないことをやってくれるのね。もちろん、今回のはサプライズでも何でもないけど。", "0", "0", "你總會做出讓本小姐出乎意料的事呢~當然，這次可不算驚喜~", "0", "cv_kinkura_28", "0", "0"},
[420031] = {420031, 12000, 34, 26, "0", "0", "太慢了，你以為本小姐等你多久了啊？", "遅すぎ。あたしがどれだけ待ってたと思うの？", "0", "0", "太慢了，你以為本小姐等你多久了啊？", "0", "cv_kinkura_31", "0", "0"},
[420032] = {420032, 12000, 35, 27, "0", "0", "危機四伏之地，處處都是商機。我們出發吧，多瑙的領航！", "危険が多い場所には商機も沢山あるからね。出発しよう。", "0", "0", "危機四伏之地，處處都是商機。我們出發吧，多瑙的領航！", "0", "cv_kinkura_33", "0", "0"},
[420033] = {420033, 12000, 36, 28, "0", "0", "優秀的商人能從日常中發現寶藏。", "優秀な商人は日常生活の中でも寶を見つけられるの。", "0", "0", "優秀的商人能從日常中發現寶藏。", "0", "cv_kinkura_34", "0", "0"},
[420034] = {420034, 12000, 37, 29, "0", "0", "雇傭這麼多人要花多少錢啊？", "これくらい人を雇うのって、どのくらいお金がかかるの？", "0", "0", "雇傭這麼多人要花多少錢啊？", "0", "cv_kinkura_35", "0", "0"},
[420035] = {420035, 12000, 38, 30, "0", "0", "又要招新人了嗎？", "また新人を募集するの？", "0", "0", "又要招新人了嗎？", "0", "cv_kinkura_36", "0", "0"},
