[420038] = {420038, 12000, 41, 33, "0", "0", "多瑙的領航，身體是你的本錢，不可忽視呀。", "身體が一番大事よ。気を付けてね。", "0", "0", "多瑙的領航，身體是你的本錢，不可忽視呀。", "0", "cv_kinkura_39", "0", "0"},
[420039] = {420039, 12000, 42, 34, "0", "0", "將環境調整成最舒適的狀況吧。", "一番心地いい環境に整えて。", "0", "0", "將環境調整成最舒適的狀況吧。", "0", "cv_kinkura_40", "0", "0"},
[420040] = {420040, 12000, 43, 35, "0", "0", "先確認有沒有商業合作吧！", "先に商業関係のものが入ってるか確認して！", "0", "0", "先確認有沒有商業合作吧！", "0", "cv_kinkura_41", "0", "0"},
