[420108] = {420108, 12001, 9, 5, "1_》_100_1.5", "level2", "哎？你又來了啊……什麼嗎，居然只帶了這點吃的……", "0", "0", "0", "0", "0", "cv_jing_6", "0", "0"},
[420109] = {420109, 12001, 10, 5, "1_》_500_2", "level3", "喂喂喂～你這麼頻繁地找我到底是看上我哪一點了啊？在我身上投入再多也不會有回報的哦～比起我，你還是去多關照下姐姐吧。", "0", "0", "0", "0", "0", "cv_jing_7", "0", "0"},
[420110] = {420110, 12001, 11, 5, "1_》_1000_2.5", "level4", "還真是執著啊，弄得我都有些感動了。我還是第一次被人這麼期待著。嗯……要不要也嘗試努力下呢，比如給你泡包速食麵什麼的。", "0", "0", "0", "0", "0", "cv_jing_8", "0", "0"},
[420111] = {420111, 12001, 12, 6, "0", "0", "level up！哎？不是電子遊戲嗎？", "0", "0", "0", "0", "0", "cv_jing_9", "0", "0"},
