[420201] = {420201, 12002, 2, 2, "0", "0", "我可不是什麼好榜樣喔～", "私は別に、手本になるような存在じゃないわよ。", "0", "0", "我可不是什麼好榜樣哦～", "0", "cv_shiranui_2", "0", "0"},
[420202] = {420202, 12002, 3, 3, "0", "0", "你好，我是風林火山的不知火，聽說這裡有很多可愛的女孩子，就讓我來確認下吧。", "こんにちは。私は風林火山の不知火よ。ここには沢山の可愛い女の子がいるって聞いたの。さて、さっそく確認させていただきましょ。", "0", "0", "你好，我是風林火山的不知火，聽說這裡有很多可愛的女孩子，就讓我來確認下吧。", "0", "cv_shiranui_1", "0", "0"},
[420203] = {420203, 12002, 4, 4, "0", "idle", "弱小之人，可愛之人，令人心生憐憫之人啊。正是因為有她們的存在，強者才能被稱作強者。無論是保護她們，還是摧毀她們，強者始終都離不開弱者。", "弱き者、可愛い者。不憫でならないわ。彼女たちが存在するからこそ、強者は強者と呼ばれるの。守るにせよ、滅ぼすにせよ……強者は弱者から離れられないのよ。", "0", "0", "弱小之人，可愛之人，令人心生憐憫之人啊。正是因為有她們的存在，強者才能被稱作強者。無論是保護她們，還是摧毀她們，強者始終都離不開弱者。", "0", "cv_shiranui_3", "0", "0"},
[420204] = {420204, 12002, 5, 4, "0", "idle", "喜歡可愛而又脆弱的東西又有什麼錯呢？", "可愛くて弱いものが好きで、何が悪いの？", "0", "0", "喜歡可愛而又脆弱的東西又有什麼錯呢？", "0", "cv_shiranui_4", "0", "0"},
[420205] = {420205, 12002, 6, 4, "0", "idle", "領航，你不覺得清風那孩子可愛得有些過分了嗎？明明還是個孩子，卻要裝成大人的模樣。那雙柔弱的肩膀上，背負著太多沉重的東西了。", "清風って本當に可愛いわあ。ナビゲーターもそう思わない？子供なのに大人ぶってて。あの柔らかい肩に重荷を背負いすぎてるのね。", "0", "0", "領航，你不覺得清風那孩子可愛得有些過分了嗎？明明還是個孩子，卻要裝成大人的模樣。那雙柔弱的肩膀上，背負著太多沉重的東西了。", "0", "cv_shiranui_30", "0", "0"},
[420206] = {420206, 12002, 7, 5, "1_》_0_0.8", "level1", "為什麼要當駕駛員，當然是因為有很多可愛的孩子在啦……而且，如果戰爭不結束的話，那些孩子就沒辦法過上幸福的生活，不是嗎？", "ドライバーになった理由？沢山の可愛いコがいるからに決まってるわ……それに、戦爭が終わらないと、あのコたちは幸せに暮らせない。そうでしょ？", "0", "0", "為什麼要當駕駛員，當然是因為有很多可愛的孩子在啦……而且，如果戰爭不結束的話，那些孩子就沒辦法過上幸福的生活，不是嗎？", "0", "cv_shiranui_31", "0", "0"},
[420207] = {420207, 12002, 8, 5, "1_》_0_0.8", "level1", "欸呀，難道說你和我一樣也是會主動進攻的那類嗎？", "あら、もしかして、あなたも私みたいに自分から攻めるタイプなの？", "0", "0", "哎呀，難道說你和我一樣也是會主動進攻的那類嗎？", "0", "cv_shiranui_5", "0", "0"},
[420208] = {420208, 12002, 9, 5, "1_》_100_1.5", "level2", "呵呵呵，明明長得那麼可愛，但是卻意外得成熟嘛。這樣一來姐姐就沒法對你下手了吧。", "うふふ。見た目は可愛いけど、案外大人しいのね。これじゃ手が出せないじゃない。", "0", "0", "呵呵呵，明明長得那麼可愛，但是卻意外得成熟嘛。這樣一來姐姐就沒法對你下手了吧。", "0", "cv_shiranui_6", "0", "0"},
[420209] = {420209, 12002, 10, 5, "1_》_500_2", "level3", "即便是再強大的人都會擁有弱點，強者只不過是善於掩蓋自己弱點的人罷了。領航，我能感覺到，支撐著你內心的那根支柱實際上非常脆弱吧。", "どれだけ強い人であっても弱點は必ずあるわ。ただ、強者は自分の弱點を隠すのが上手い。それだけよ。ナビゲーター、私、感じてるわ。あなたの心を支えてる支柱、本當は淒く脆いんでしょ？", "0", "0", "即便是再強大的人都會擁有弱點，強者只不過是善於掩蓋自己弱點的人罷了。領航，我能感覺到，支撐著你內心的那根支柱實際上非常脆弱吧。", "0", "cv_shiranui_7", "0", "0"},
[420210] = {420210, 12002, 11, 5, "1_》_1000_2.5", "level4", "等一切都結束過後，你我就都能卸下偽裝了。是啊，我想要創造的，只是一個不需要強者的世界罷了。", "全てが終わったら、あなたも私も、偽りの仮面を外すことができるわ。そう。私が創りたいのは、強者を必要としない世界なの。", "0", "0", "等一切都結束過後，你我就都能卸下偽裝了。是啊，我想要創造的，只是一個不需要強者的世界罷了。", "0", "cv_shiranui_8", "0", "0"},
[420211] = {420211, 12002, 12, 6, "0", "0", "變強的感覺……真不錯啊。", "強くなる感じって、いいわね。", "0", "0", "變強的感覺……真不錯啊。", "0", "cv_shiranui_9", "0", "0"},
[420212] = {420212, 12002, 13, 7, "0", "0", "這樣一來就更加容易吸引到可愛的孩子了吧？", "これでもっと沢山の可愛いコたちを惹きつけられるのかしら？", "0", "0", "這樣一來就更加容易吸引到可愛的孩子了吧？", "0", "cv_shiranui_10", "0", "0"},
[420213] = {420213, 12002, 14, 8, "0", "0", "呵呵呵，沒想到你這麼在意姐姐啊。那麼接下來該如何疼愛你呢？", "うふふ。お姉さんのことがそんなに気になるんだ。さて、どう可愛がってあげようかしら？", "0", "0", "呵呵呵，沒想到你這麼在意姐姐啊。那麼接下來該如何疼愛你呢？", "0", "cv_shiranui_11", "0", "0"},
[420214] = {420214, 12002, 15, 9, "0", "0", "喝啊！哼，真是一把好弓啊。", "はっ！ふーん、なかなか良い弓だわ。", "0", "0", "喝啊！哼，真是一把好弓啊。", "0", "cv_shiranui_12", "0", "0"},
[420215] = {420215, 12002, 16, 10, "0", "0", "燒盡他們吧。", "彼らを焼き盡くしなさい。", "0", "0", "燒盡他們吧。", "0", "cv_shiranui_13", "0", "0"},
[420216] = {420216, 12002, 17, 11, "0", "0", "怎麼樣，我很強吧？", "どう？私、強いでしょ？", "0", "0", "怎麼樣，我很強吧？", "0", "cv_shiranui_14", "0", "0"},
[420217] = {420217, 12002, 18, 12, "0", "0", "稍微掙紮了一下嗎？不過也就這樣了。", "それで抵抗したつもり？まぁ、所詮その程度ね。", "0", "0", "稍微掙扎了一下嗎？不過也就這樣了。", "0", "cv_shiranui_15", "0", "0"},
[420218] = {420218, 12002, 19, 13, "0", "0", "呵呵呵，敵人也不弱啊。", "うふふ。敵もなかなか手強かったわね。", "0", "0", "呵呵呵，敵人也不弱啊。", "0", "cv_shiranui_16", "0", "0"},
[420219] = {420219, 12002, 20, 14, "0", "0", "無論是我還是你，都還需要再努力一些啊。", "私もあなたも、もっと頑張らないと。", "0", "0", "無論是我還是你，都還需要再努力一些啊。", "0", "cv_shiranui_17", "0", "0"},
[420220] = {420220, 12002, 21, 15, "0", "0", "很痛吧？", "痛いんでしょ？", "0", "0", "很痛吧？", "0", "cv_shiranui_18", "0", "0"},
[420221] = {420221, 12002, 23, 16, "0", "0", "喝啊——！", "はぁぁっ――！", "0", "0", "喝啊——！", "0", "cv_shiranui_20", "0", "0"},
[420222] = {420222, 12002, 24, 17, "0", "0", "還沒有結束！", "まだ終わってないわ！", "0", "0", "還沒有結束！", "0", "cv_shiranui_22", "0", "0"},
[420223] = {420223, 12002, 22, 38, "0", "0", "火啊……蔓延吧。", "火よ……延び広がりなさい。", "0", "0", "火啊……蔓延吧。", "0", "cv_shiranui_19", "0", "0"},
[420224] = {420224, 12002, 26, 19, "0", "0", "火……要熄滅了啊。", "火が……消えてしまうわ。", "0", "0", "火……要熄滅了啊。", "0", "cv_shiranui_21", "0", "0"},
[420225] = {420225, 12002, 27, 20, "0", "0", "小小的，還真是可愛呢。", "小さくて可愛いわね。", "0", "0", "小小的，還真是可愛呢。", "0", "cv_shiranui_23", "0", "0"},
[420226] = {420226, 12002, 28, 21, "0", "0", "不要偷懶喔～", "怠けてはダメ。", "0", "0", "不要偷懶哦～", "0", "cv_shiranui_24", "0", "0"},
[420227] = {420227, 12002, 29, 21, "0", "0", "如果領航是女孩子的話，我會更加開心喔～", "もしナビゲーターが女の子だったら、もっと嬉しいのに。", "0", "0", "如果領航是女孩子的話，我會更加開心哦～", "0", "cv_shiranui_25", "0", "0"},
[420228] = {420228, 12002, 30, 22, "0", "0", "看來有人想要打擾我們呢。", "私たちの邪魔をしてくる者がいるようね。", "0", "0", "看來有人想要打擾我們呢。", "0", "cv_shiranui_26", "0", "0"},
[420229] = {420229, 12002, 31, 23, "0", "0", "使出渾身解數來猜猜姐姐是誰吧～", "誰がお姉さんか、頑張って當ててみて。", "0", "0", "使出渾身解數來猜猜姐姐是誰吧～", "0", "cv_shiranui_27", "0", "0"},
[420230] = {420230, 12002, 32, 24, "0", "0", "啊～真是一個可愛的孩子啊。", "ああ、なんて可愛らしいコ。", "0", "0", "啊～真是一個可愛的孩子啊。", "0", "cv_shiranui_28", "0", "0"},
[420231] = {420231, 12002, 33, 25, "0", "0", "猜錯的領航也好可愛啊～", "外したナビゲーターも可愛いわ。", "0", "0", "猜錯的領航也好可愛啊～", "0", "cv_shiranui_29", "0", "0"},
[420232] = {420232, 12002, 34, 26, "0", "0", "回來了呀，領航。如何，今天也要和我一起去找那些可愛的小傢夥們玩嗎？", "お帰りなさい、ナビゲーター。どう？今日も私と一緒に可愛いコたちの所に行く？", "0", "0", "回來了呀，領航。如何，今天也要和我一起去找那些可愛的小傢伙們玩嗎？", "0", "cv_shiranui_32", "0", "0"},
[420233] = {420233, 12002, 35, 27, "0", "0", "讓我們一起終結這無盡頭的故事吧。", "一緒にこの果てのない物語を終わらせましょ。", "0", "0", "讓我們一起終結這無盡頭的故事吧。", "0", "cv_shiranui_34", "0", "0"},
[420234] = {420234, 12002, 36, 28, "0", "0", "為了變強，日常的鍛煉也是必須的。", "強くなるためには日常の鍛錬も必要だわ。", "0", "0", "為了變強，日常的鍛煉也是必須的。", "0", "cv_shiranui_35", "0", "0"},
[420235] = {420235, 12002, 37, 29, "0", "0", "需要我推薦幾位元嗎？", "何人か推薦してあげようかしら？", "0", "0", "需要我推薦幾位元嗎？", "0", "cv_shiranui_36", "0", "0"},
[420236] = {420236, 12002, 38, 30, "0", "0", "多找些可愛的孩子吧！", "可愛いコたちをもっと募集して！", "0", "0", "多找些可愛的孩子吧！", "0", "cv_shiranui_37", "0", "0"},
[420237] = {420237, 12002, 39, 31, "0", "0", "拿來給她們做禮物~", "彼女たちにプレゼントしようかしら。", "0", "0", "拿來給她們做禮物~", "0", "cv_shiranui_38", "0", "0"},
[420238] = {420238, 12002, 40, 32, "0", "0", "隨便買點什麼吧，不是什麼重要的東西。", "適當に買えばいいわ。重要な物じゃないし。", "0", "0", "隨便買點什麼吧，不是什麼重要的東西。", "0", "cv_shiranui_39", "0", "0"},
[420239] = {420239, 12002, 41, 33, "0", "0", "仔細看的話，果然領航也很可愛，姐姐會心動的。", "よく見たら、ナビゲーターも可愛い～お姉さんの心が、揺さぶられてしまうわ。", "0", "0", "仔細看的話，果然領航也很可愛，姐姐會心動的。", "0", "cv_shiranui_40", "0", "0"},
[420240] = {420240, 12002, 42, 34, "0", "0", "領航，你還真是喜歡這些瑣碎的事情呢。", "ナビゲーターって本當に細かい作業が好きね。", "0", "0", "領航，你還真是喜歡這些瑣碎的事情呢。", "0", "cv_shiranui_41", "0", "0"},
[420241] = {420241, 12002, 43, 35, "0", "0", "也許會有害羞可愛的孩子悄悄給你寫信喔？", "可愛い子が照れながらこっそりメールを送ってくれたかもしれないわよ？", "0", "0", "也許會有害羞可愛的孩子悄悄給你寫信哦？", "0", "cv_shiranui_42", "0", "0"},
[420242] = {420242, 12002, 44, 36, "0", "0", "和大家一起交流心得吧~", "みんなと一緒に心得について交流しましょ。", "0", "0", "和大家一起交流心得吧~", "0", "cv_shiranui_43", "0", "0"},
[420243] = {420243, 12002, 45, 37, "0", "0", "進行最後的確認吧。", "最後の確認を行いましょ。", "0", "0", "進行最後的確認吧。", "0", "cv_shiranui_44", "0", "0"},
[420300] = {420300, 12003, 1, 1, "0", "0", "蒼霧殘響！", "蒼霧殘響（ハツリバーブ）！", "0", "0", "蒼霧殘響！", "0", "cv_efugenia_34", "0", "0"},
[420301] = {420301, 12003, 2, 2, "0", "0", "哈哈，你的眼光不錯！", "あはは、見る目があるね、あんた！", "0", "0", "哈哈，你的眼光不錯！", "0", "cv_efugenia_2", "0", "0"},
[420302] = {420302, 12003, 3, 3, "0", "0", "你這個傢夥就是領航？看起來有些弱不禁風啊。哈哈，沒事，你的敵人就交給我葉芙根尼婭解決吧！", "あんたがナビゲーターなの？何だか弱そうな奴だね。あはははっ、でも大丈夫。あんたの敵はこのあたし、エフゲニアに任せて！", "0", "0", "你這個傢伙就是領航？看起來有些弱不禁風啊。哈哈，沒事，你的敵人就交給我葉芙根尼婭解決吧！", "0", "cv_efugenia_1", "0", "0"},
[420303] = {420303, 12003, 4, 4, "0", "idle", "四十八——四十九——五十——好了，今天的第十二組力量訓練完成，還剩下八組！領航，要試試鍛煉肌肉嗎？", "四十八――四十九――五十――よし、今日の筋トレはもう12セットすんだから…...あと8セット！ナビゲーターもやってみない？筋トレ。", "0", "0", "四十八——四十九——五十——好了，今天的第十二組力量訓練完成，還剩下八組！領航，要試試鍛煉肌肉嗎？", "0", "cv_efugenia_3", "0", "0"},
[420304] = {420304, 12003, 5, 4, "0", "idle", "肉體遠比精神重要，只有健碩的軀體才能容下堅毅的靈魂。所以領航，你真的不考慮再鍛煉一下嗎？哈哈，放心好了，我會耐下性子來好好指導你的。", "肉體は精神より遙かに重要だ。丈夫な體にこそ強い魂を宿せるんだから。ってワケで、本當にトレーニングしなくていいの？あはは、安心して。根気よく指導してあげるからさ。", "0", "0", "肉體遠比精神重要，只有健碩的軀體才能容下堅毅的靈魂。所以領航，你真的不考慮再鍛煉一下嗎？哈哈，放心好了，我會耐下性子來好好指導你的。", "0", "cv_efugenia_4", "0", "0"},
[420305] = {420305, 12003, 6, 4, "0", "idle", "作為鋼輪戈爾的隊長，我必須要對自己的隊員負責！因此，只要有空閑的時間，我都會給她們進行緊急強化訓練。", "コウリンゲールの隊長として、チーム內の皆の世話をする義務があるんだ。だから、時間がある時はいつも皆を対象に緊急強化トレーニングを実施してるのさ。", "0", "0", "作為鋼輪戈爾的隊長，我必須要對自己的隊員負責！因此，只要有空閒的時間，我都會給她們進行緊急強化訓練。", "0", "cv_efugenia_31", "0", "0"},
[420306] = {420306, 12003, 7, 5, "1_》_0_0.8", "level1", "如果不能保護同伴，我一直鍛煉的肌肉就沒有了意義。只有變得足夠強大，我才能守護人類的世界。", "仲間を守れないなら、ずっと鍛えた筋肉も意味がない。十分強くなってこそ、人間の世界を守ることができるんだ。", "0", "0", "如果不能保護同伴，我一直鍛煉的肌肉就沒有了意義。只有變得足夠強大，我才能守護人類的世界。", "0", "cv_efugenia_32", "0", "0"},
[420307] = {420307, 12003, 8, 5, "1_》_0_0.8", "level1", "我已經很久沒有收到過其他人的挑戰了，領航你還真是勇敢！哈！欸？我還沒用力……", "人から挑戦を受けるなんて久しぶりだ。やるね、ナビゲーター！はっ！…...え？そんなあ、これからが本番だっていうのに……", "0", "0", "我已經很久沒有收到過其他人的挑戰了，領航你還真是勇敢！哈！誒？我還沒用力……", "0", "cv_efugenia_5", "0", "0"},
[420308] = {420308, 12003, 9, 5, "1_》_100_1.5", "level2", "你想要鍛煉肌肉了嗎？哈哈，那我來給你安排一套訓練方案吧！擁有強健身材的人才更帥氣啊！", "筋トレ、やりたくなった？あはは、じゃあ、トレーニングプランを練ってやるよ！丈夫な體を持った方がかっこいいしね！", "0", "0", "你想要鍛煉肌肉了嗎？哈哈，那我來給你安排一套訓練方案吧！擁有強健身材的人才更帥氣啊！", "0", "cv_efugenia_6", "0", "0"},
[420309] = {420309, 12003, 10, 5, "1_》_500_2", "level3", "你還真是個有毅力的傢夥！居然還要加練！那我陪你一起鍛煉吧，你可不能中途放棄喔！", "あんた、本當に根気強いね！まだあたしが作ったトレーニングプランを続けてるだなんて！ここまできたら、付き合ってあげるよ。途中で諦めたりしちゃダメだからね！", "0", "0", "你還真是個有毅力的傢伙！居然還要加練！那我陪你一起鍛煉吧，你可不能中途放棄哦！", "0", "cv_efugenia_7", "0", "0"},
[420310] = {420310, 12003, 11, 5, "1_》_1000_2.5", "level4", "不要逞強啊，我的訓練強度可不是其他人能承受的。你的意志我已經感受到了，雖然你現在還沒那麼強壯，但確實是個優秀的戰士。", "無理しないでね。あたしのトレーニングは超ハードだから、普通の人じゃ耐えられないんだ。でも、あんたの意志、確かに感じたよ。體はまだまだだけど、心はもう優秀な戦士に違いないよ。", "0", "0", "不要逞強啊，我的訓練強度可不是其他人能承受的。你的意志我已經感受到了，雖然你現在還沒那麼強壯，但確實是個優秀的戰士。", "0", "cv_efugenia_8", "0", "0"},
[420311] = {420311, 12003, 12, 6, "0", "0", "肌肉增加了！", "筋肉が増えた！", "0", "0", "肌肉增加了！", "0", "cv_efugenia_9", "0", "0"},
[420312] = {420312, 12003, 13, 7, "0", "0", "人類記錄又被我打破了？我覺得還沒到極限！", "あたし、また世界新記録を更新した？まだまだ全力を出し切ってないんだけど！", "0", "0", "人類記錄又被我打破了？我覺得還沒到極限！", "0", "cv_efugenia_10", "0", "0"},
[420313] = {420313, 12003, 14, 8, "0", "0", "不要把我從人類中排除出去啊！", "あたしを人間って括りから外さないでってば！", "0", "0", "不要把我從人類中排除出去啊！", "0", "cv_efugenia_11", "0", "0"},
