[420333] = {420333, 12003, 34, 26, "0", "0", "回來了嗎，領航。事不宜遲，讓我們開始肌肉鍛煉吧！", "帰ってきた？ナビゲーター。じゃあ早速、筋トレを始めよう！", "0", "0", "回來了嗎，領航。事不宜遲，讓我們開始肌肉鍛煉吧！", "0", "cv_efugenia_33", "0", "0"},
[420334] = {420334, 12003, 35, 27, "0", "0", "該去驗證一下鍛煉的成果了，領航！", "トレーニングの成果を見せる時間だ、ナビゲーター！", "0", "0", "該去驗證一下鍛煉的成果了，領航！", "0", "cv_efugenia_35", "0", "0"},
[420335] = {420335, 12003, 36, 28, "0", "0", "只有不斷地錘煉自己的身與心，才能成為強大的戰士！", "自分の身體と心を鍛え続けてこそ、強い戦士になれる！", "0", "0", "只有不斷地錘煉自己的身與心，才能成為強大的戰士！", "0", "cv_efugenia_36", "0", "0"},
