[420726] = {420726, 12007, 29, 21, "0", "0", "洗澡的時候總會忍不住放鬆下來啊~", "お風呂に入ると何だかんだ気が緩むな。", "0", "0", "洗澡的時候總會忍不住放鬆下來啊~", "0", "cv_kamu_24", "0", "0"},
