[420729] = {420729, 12007, 32, 24, "0", "0", "是通過氣來分辨出來的嗎？還是說……", "気で分かったのか？それとも……", "0", "0", "是通過氣來分辨出來的嗎？還是說……", "0", "cv_kamu_27", "0", "0"},
[420730] = {420730, 12007, 33, 25, "0", "0", "無論是你我，修行還都不夠啊。", "お前もオレも、まだまだ修行が足りないな。", "0", "0", "無論是你我，修行還都不夠啊。", "0", "cv_kamu_28", "0", "0"},
[420731] = {420731, 12007, 34, 26, "0", "0", "啊，領航你回來了嗎？小生這就中斷修行。", "ああ、お帰り、ナビゲーター！待ってくれ、すぐに修行を終えるから。", "0", "0", "啊，領航你回來了嗎？小生這就中斷修行。", "0", "cv_kamu_31", "0", "0"},
[420732] = {420732, 12007, 35, 27, "0", "0", "前往新的戰場吧。", "新しい戦場に向かおう。", "0", "0", "前往新的戰場吧。", "0", "cv_kamu_33", "0", "0"},
[420733] = {420733, 12007, 36, 28, "0", "0", "人只有在苦修中才能磨練自己。", "人は苦行の中でのみ、自分を磨けるからな。", "0", "0", "人只有在苦修中才能磨練自己。", "0", "cv_kamu_34", "0", "0"},
[420734] = {420734, 12007, 37, 29, "0", "0", "各位，在苦修中磨練自己吧！", "皆、苦行で自分を磨こう！", "0", "0", "各位，在苦修中磨練自己吧！", "0", "cv_kamu_35", "0", "0"},
[420735] = {420735, 12007, 38, 30, "0", "0", "要增加夥伴了嗎？", "仲間が増えるのか？", "0", "0", "要增加夥伴了嗎？", "0", "cv_kamu_36", "0", "0"},
[420736] = {420736, 12007, 39, 31, "0", "0", "多瑙的裝備還真是有趣啊。", "ダニューブの裝備って面白いな。", "0", "0", "多瑙的裝備還真是有趣啊。", "0", "cv_kamu_37", "0", "0"},
