[421022] = {421022, 12010, 22, 38, "0", "0", "煙火要綻放了！", "花火を打ち上げっぞ！", "0", "0", "煙火要綻放了！", "0", "cv_meika_19", "0", "0"},
[421023] = {421023, 12010, 26, 19, "0", "0", "消失什麼的，老娘才不想啊……", "消えるなんて、嫌だ……", "0", "0", "消失什麼的，老娘才不想啊……", "0", "cv_meika_21", "0", "0"},
