[421025] = {421025, 12010, 28, 21, "0", "0", "喂，就沒有準備些什麼泡澡時的零食嗎？", "おい、なんか風呂で食うもんはねぇのかよ？", "0", "0", "喂，就沒有準備些什麼泡澡時的零食嗎？", "0", "cv_meika_23", "0", "0"},
[421026] = {421026, 12010, 29, 21, "0", "0", "差不多該起來了，牛奶給我準備好了嗎？咖啡牛奶！", "そろそろ出るか。牛乳は用意してんだろうな？コーヒー牛乳だぞ！", "0", "0", "差不多該起來了，牛奶給我準備好了嗎？咖啡牛奶！", "0", "cv_meika_24", "0", "0"},
[421027] = {421027, 12010, 30, 22, "0", "0", "事件！要來了要來了！", "事件か？キタキター！", "0", "0", "事件！要來了要來了！", "0", "cv_meika_25", "0", "0"},
[421028] = {421028, 12010, 31, 23, "0", "0", "你眼中的我…是哪一個呢？", "あなたの目に映るのは、どちらのあたしなのでしょうか……？", "0", "0", "你眼中的我…是哪一個呢？", "0", "cv_meika_26", "0", "0"},
[421029] = {421029, 12010, 32, 24, "0", "0", "果然，我和你很合得來嘛！", "やっぱりてめーとは気が合うな！", "0", "0", "果然，我和你很合得來嘛！", "0", "cv_meika_27", "0", "0"},
[421030] = {421030, 12010, 33, 25, "0", "0", "嘁，沒勁。", "チェッ、つまんねぇ。", "0", "0", "嘁，沒勁。", "0", "cv_meika_28", "0", "0"},
[421031] = {421031, 12010, 34, 26, "0", "0", "喔，領航，今天我們要轟誰？", "おう、ナビゲーター。今日は誰をぶっとばす？", "0", "0", "噢，領航，今天我們要轟誰？", "0", "cv_meika_31", "0", "0"},
[421032] = {421032, 12010, 35, 27, "0", "0", "我們去把那些礙事的傢夥轟飛吧！", "邪魔な奴らをぶっ飛ばしに行こうぜ！", "0", "0", "我們去把那些礙事的傢伙轟飛吧！", "0", "cv_meika_33", "0", "0"},
