[421036] = {421036, 12010, 39, 31, "0", "0", "有更大口徑的炮嗎？", "もっと口徑のデカい銃はねぇのか？", "0", "0", "有更大口徑的炮嗎？", "0", "cv_meika_37", "0", "0"},
