[421103] = {421103, 12011, 4, 4, "0", "idle", "“巴厘斯先生在死前十五分鐘還活著。”呵，真有意思。", "0", "0", "0", "0", "0", "cv_garannken_3", "0", "0"},
[421104] = {421104, 12011, 5, 4, "0", "idle", "呼…已經這個時間了嗎？差不多該休息了呢…不行嗎？", "0", "0", "0", "0", "0", "cv_garannken_4", "0", "0"},
[421105] = {421105, 12011, 6, 4, "0", "idle", "我並不討厭海姬她們…我從她們身上，感受到一種從未有過的親切感。", "0", "0", "0", "0", "0", "cv_garannken_31", "0", "0"},
[421106] = {421106, 12011, 7, 5, "1_》_0_0.8", "level1", "曾經，有一位鋼琴師與這個世界擦肩而過…我不想，所以我才下了船。", "0", "0", "0", "0", "0", "cv_garannken_32", "0", "0"},
[421107] = {421107, 12011, 8, 5, "1_》_0_0.8", "level1", "嗯？", "0", "0", "0", "0", "0", "cv_garannken_5", "0", "0"},
