[421109] = {421109, 12011, 10, 5, "1_》_500_2", "level3", "早安，領航…現在已經不算是早上了嗎……沒關係，那只不過是問候的形式而已，對你我而言，能明白對方的心意就已經足夠了。", "0", "0", "0", "0", "0", "cv_garannken_7", "0", "0"},
[421110] = {421110, 12011, 11, 5, "1_》_1000_2.5", "level4", "我們行走在行徑分叉的花園裏，偶然的機會使我們於此相遇。領航，我能與您像現在這樣對話，已經足夠幸福了。", "0", "0", "0", "0", "0", "cv_garannken_8", "0", "0"},
[421111] = {421111, 12011, 12, 6, "0", "0", "啊…謝謝。", "0", "0", "0", "0", "0", "cv_garannken_9", "0", "0"},
[421112] = {421112, 12011, 13, 7, "0", "0", "嗯…和之前比起來，稍微有些改變了吧。", "0", "0", "0", "0", "0", "cv_garannken_10", "0", "0"},
[421113] = {421113, 12011, 14, 8, "0", "0", "這就是…“覺醒”…和我在資料庫裏看到的一樣。嗯，這樣一來，我就多多少少接近領航您了吧。成為一個像您一樣，能幫助別人，引領大家前進的人。", "0", "0", "0", "0", "0", "cv_garannken_11", "0", "0"},
[421114] = {421114, 12011, 15, 9, "0", "0", "小白，我們變強了呢。", "0", "0", "0", "0", "0", "cv_garannken_12", "0", "0"},
[421115] = {421115, 12011, 16, 10, "0", "0", "小白，我們上吧。", "0", "0", "0", "0", "0", "cv_garannken_13", "0", "0"},
[421116] = {421116, 12011, 17, 11, "0", "0", "已經沒事了。", "0", "0", "0", "0", "0", "cv_garannken_14", "0", "0"},
[421117] = {421117, 12011, 18, 12, "0", "0", "結束了。", "0", "0", "0", "0", "0", "cv_garannken_15", "0", "0"},
[421118] = {421118, 12011, 19, 13, "0", "0", "好危險…", "0", "0", "0", "0", "0", "cv_garannken_16", "0", "0"},
[421119] = {421119, 12011, 20, 14, "0", "0", "撤退，別離開我。", "0", "0", "0", "0", "0", "cv_garannken_17", "0", "0"},
[421120] = {421120, 12011, 21, 15, "0", "0", "消失吧。", "0", "0", "0", "0", "0", "cv_garannken_18", "0", "0"},
[421121] = {421121, 12011, 23, 16, "0", "0", "上吧，小白。", "0", "0", "0", "0", "0", "cv_garannken_20", "0", "0"},
[421122] = {421122, 12011, 24, 17, "0", "0", "再來一次，小白。", "0", "0", "0", "0", "0", "cv_garannken_22", "0", "0"},
[421123] = {421123, 12011, 22, 38, "0", "0", "要上了…", "0", "0", "0", "0", "0", "cv_garannken_19", "0", "0"},
[421124] = {421124, 12011, 26, 19, "0", "0", "沒關係…沒關係…嗚……", "0", "0", "0", "0", "0", "cv_garannken_21", "0", "0"},
[421125] = {421125, 12011, 27, 20, "0", "0", "澡堂…讓我想起了以前的事…不，沒什麼。", "0", "0", "0", "0", "0", "cv_garannken_24", "0", "0"},
[421126] = {421126, 12011, 28, 21, "0", "0", "這時候有一本書的話就好了…嗯，推理小說之類的……", "0", "0", "0", "0", "0", "cv_garannken_25", "0", "0"},
[421127] = {421127, 12011, 29, 21, "0", "0", "還要多久？我快睡著了……不行，會感冒的。", "0", "0", "0", "0", "0", "cv_garannken_26", "0", "0"},
[421128] = {421128, 12011, 30, 22, "0", "0", "放心，我會保護你的。", "0", "0", "0", "0", "0", "cv_garannken_27", "0", "0"},
[421129] = {421129, 12011, 31, 23, "0", "0", "提示是…書。", "0", "0", "0", "0", "0", "cv_garannken_28", "0", "0"},
[421130] = {421130, 12011, 32, 24, "0", "0", "…領航，這是我喜歡的書，借給你。", "0", "0", "0", "0", "0", "cv_garannken_29", "0", "0"},
[421131] = {421131, 12011, 33, 25, "0", "0", "哦…猜錯了啊。不，我沒有不高興。", "0", "0", "0", "0", "0", "cv_garannken_30", "0", "0"},
[421132] = {421132, 12011, 34, 26, "0", "0", "領航，歡迎回來…我手上的書？噢，這是《飛鳥集》，我的寶物。", "0", "0", "0", "0", "0", "cv_garannken_33", "0", "0"},
[421133] = {421133, 12011, 35, 27, "0", "0", "我能帶上喜歡的書出去嗎？", "0", "0", "0", "0", "0", "cv_garannken_35", "0", "0"},
[421134] = {421134, 12011, 36, 28, "0", "0", "“生於憂患，死於安樂”……", "0", "0", "0", "0", "0", "cv_garannken_36", "0", "0"},
[421135] = {421135, 12011, 37, 29, "0", "0", "真熱鬧……", "0", "0", "0", "0", "0", "cv_garannken_37", "0", "0"},
[421136] = {421136, 12011, 38, 30, "0", "0", "遵從我的召喚…開玩笑的。", "0", "0", "0", "0", "0", "cv_garannken_38", "0", "0"},
[421137] = {421137, 12011, 39, 31, "0", "0", "我有小白就足夠了。", "0", "0", "0", "0", "0", "cv_garannken_39", "0", "0"},
[421138] = {421138, 12011, 40, 32, "0", "0", "…書，有嗎？", "0", "0", "0", "0", "0", "cv_garannken_40", "0", "0"},
[421139] = {421139, 12011, 41, 33, "0", "0", "要好好打理自己。", "0", "0", "0", "0", "0", "cv_garannken_41", "0", "0"},
[421140] = {421140, 12011, 42, 34, "0", "0", "按喜歡的來吧。", "0", "0", "0", "0", "0", "cv_garannken_42", "0", "0"},
[421141] = {421141, 12011, 43, 35, "0", "0", "有新的郵件嗎？", "0", "0", "0", "0", "0", "cv_garannken_43", "0", "0"},
[421142] = {421142, 12011, 44, 36, "0", "0", "……好吵。", "0", "0", "0", "0", "0", "cv_garannken_44", "0", "0"},
[421143] = {421143, 12011, 45, 37, "0", "0", "嗯。", "0", "0", "0", "0", "0", "cv_garannken_45", "0", "0"},
[421200] = {421200, 12012, 1, 1, "0", "0", "蒼霧殘響。", "蒼霧殘響（ハツリバーブ）。", "0", "0", "蒼霧殘響。", "0", "cv_jyuria_32", "0", "0"},
[421201] = {421201, 12012, 2, 2, "0", "0", "真是有勇氣呢，想必你也做好了相應的心理準備了吧？", "アタシにこんなことをさせるなんて、良い度胸ね。覚悟はできてるのかしら？", "0", "0", "真是有勇氣呢，想必你也做好了相應的心理準備了吧？", "0", "cv_jyuria_2", "0", "0"},
[421202] = {421202, 12012, 3, 3, "0", "0", "呵，你就是領航嗎，看起來很普通呢。我是茱莉亞，茱莉亞·福克斯，颶風突擊隊的隊長，讓我們“友好相處”吧~", "ふん、アンタがナビゲーター？……なんか普通ね。アタシはジュリア。ジュリア・フォックス。颶風突撃隊の隊長よ。仲良くしましょうね。", "0", "0", "呵，你就是領航嗎，看起來很普通呢。我是茱莉亞，茱莉亞·福克斯，颶風突擊隊的隊長，讓我們“友好相處”吧~", "0", "cv_jyuria_1", "0", "0"},
[421203] = {421203, 12012, 4, 4, "0", "idle", "口渴了呢…笨豬，對，就是在說你，快去幫我買喝的過來。", "喉が乾いたわ。……ねえ、そこのブタ野郎。そう、アンタのことよ。さっさと飲み物を買ってきて。", "0", "0", "口渴了呢…笨豬，對，就是在說你，快去幫我買喝的過來。", "0", "cv_jyuria_3", "0", "0"},
[421204] = {421204, 12012, 5, 4, "0", "idle", "不要發出豬一樣的叫聲！就不能矜持一點嗎？", "ブタみたいな聲を出さないでくれる？プライドってものがないのかしら？", "0", "0", "不要發出豬一樣的叫聲！就不能矜持一點嗎？", "0", "cv_jyuria_4", "0", "0"},
[421205] = {421205, 12012, 6, 4, "0", "idle", "笨豬，你今天看見棲琳了嗎？沒有嗎？嗯…這樣的話，就拿你來替代吧…喂，別跑啊，真是的，真膽小豬呢。", "ブタ。シリンを見かけなかった？見てないの？……ふーん。しょうがないわね。代わりにアンタを……あ、ちょっと！何逃げてんのよ！……なんて憶病なブタかしら。", "0", "0", "笨豬，你今天看見棲琳了嗎？沒有嗎？嗯…這樣的話，就拿你來替代吧…喂，別跑啊，真是的，真膽小豬呢。", "0", "cv_jyuria_29", "0", "0"},
[421206] = {421206, 12012, 7, 5, "1_》_0_0.8", "level1", "有錢人家的大小姐？燕妮是這麼跟你說的嗎？真是無趣的笑話。金錢與權力，這種渣滓一樣東西對我來說一點意義也沒有。", "お金持ちのお嬢様？ジェニィからそう聞いたの？ふん、くだらない冗談ね。お金と権力なんてカスみたいなもの、私にとってはなんの意味もないわ。", "0", "0", "有錢人家的大小姐？燕妮是這麼跟你說的嗎？真是無趣的笑話。金錢與權力，這種渣滓一樣東西對我來說一點意義也沒有。", "0", "cv_jyuria_30", "0", "0"},
[421207] = {421207, 12012, 8, 5, "1_》_0_0.8", "level1", "不要隨便碰我，笨豬。", "なに勝手に觸ってるの。ブタ野郎。", "0", "0", "不要隨便碰我，笨豬。", "0", "cv_jyuria_5", "0", "0"},
[421208] = {421208, 12012, 9, 5, "1_》_100_1.5", "level2", "笨豬，你剛剛碰我了吧。是這只手嗎？好的，乖乖把手伸出來。別害怕，剛開始會很痛，但之後你一定會喜歡上這種感覺的——嘿呀！", "このブタ、今アタシに觸ったわね。觸ったのはこの手かしら？いいわ。大人しくその手を出して。大丈夫、最初は痛いけど、だんだんその痛みも愛しくなるわ。……ヘイヤー！", "0", "0", "笨豬，你剛剛碰我了吧。是這只手嗎？好的，乖乖把手伸出來。別害怕，剛開始會很痛，但之後你一定會喜歡上這種感覺的——嘿呀！", "0", "cv_jyuria_6", "0", "0"},
[421209] = {421209, 12012, 10, 5, "1_》_500_2", "level3", "不管被鞭打多少次都要接近我嗎？呵呵，笨豬，你讓我感興趣了呢。", "何度もムチに叩かれて、まだアタシに近づくつもり？フフフ……ブタ野郎。だんだんお前に興味が出てきたわ。", "0", "0", "不管被鞭打多少次都要接近我嗎？呵呵，笨豬，你讓我感興趣了呢。", "0", "cv_jyuria_7", "0", "0"},
[421210] = {421210, 12012, 11, 5, "1_》_1000_2.5", "level4", "…喂，笨豬，你又碰我了是吧……我已經忍無可忍了。今天工作結束之後，到我的房間裡來！呵呵呵呵呵…我要讓你明白，什麼是真正的地獄。", "……信じられない。このアホブタ、またアタシを觸るなんて。……もう我慢できないわ。今日の仕事が終わったらアタシの部屋に來るのよ！フフフ…アンタに本物の地獄を見せてあげるわ。", "0", "0", "…喂，笨豬，你又碰我了是吧……我已經忍無可忍了。今天工作結束之後，到我的房間裡來！呵呵呵呵呵…我要讓你明白，什麼是真正的地獄。", "0", "cv_jyuria_8", "0", "0"},
[421211] = {421211, 12012, 12, 6, "0", "0", "嗯，馬馬虎虎吧。", "ふーん。まあまあね。", "0", "0", "嗯，馬馬虎虎吧。", "0", "cv_jyuria_9", "0", "0"},
[421212] = {421212, 12012, 13, 7, "0", "0", "供奉我是理所當然的。", "アタシに仕えるのは當然のことよ。", "0", "0", "供奉我是理所當然的。", "0", "cv_jyuria_10", "0", "0"},
[421213] = {421213, 12012, 14, 8, "0", "0", "居然做到這一步…連我也忍不住想要誇獎你呢……不過，不要太得意忘形了！為我付出這麼多是你應該做的……咳咳，喂，豬…領航，你就沒有什麼其他想對我說的嗎？", "まさかここまでするなんて……こんなの、さすがのアタシも褒めるしか……なによ！あまり調子に乗らないでちょうだい！こんなの、當たり前のことよ……。おい、ブタ。……ナビゲーター！アタシに何か、言いたいことはないの？", "0", "0", "居然做到這一步…連我也忍不住想要誇獎你呢……不過，不要太得意忘形了！為我付出這麼多是你應該做的……咳咳，喂，豬…領航，你就沒有什麼其他想對我說的嗎？", "0", "cv_jyuria_11", "0", "0"},
[421214] = {421214, 12012, 15, 9, "0", "0", "這是你的榮幸。", "光栄に思うことね。", "0", "0", "這是你的榮幸。", "0", "cv_jyuria_12", "0", "0"},
[421215] = {421215, 12012, 16, 10, "0", "0", "僕從們，為我服務吧。", "下僕ども。アタシに従うのよ。", "0", "0", "僕從們，為我服務吧。", "0", "cv_jyuria_13", "0", "0"},
[421216] = {421216, 12012, 17, 11, "0", "0", "這才是與我相配的作戰方式。", "アタシに相応しい戦闘だったわ。", "0", "0", "這才是與我相配的作戰方式。", "0", "cv_jyuria_14", "0", "0"},
[421217] = {421217, 12012, 18, 12, "0", "0", "連這點小事都做不好嗎？", "こんなことも上手くできないの？", "0", "0", "連這點小事都做不好嗎？", "0", "cv_jyuria_15", "0", "0"},
[421218] = {421218, 12012, 19, 13, "0", "0", "看來，笨豬和僕從們很需要我的鞭打啊。", "アホブタと下僕どもには、鞭が必要なようね。", "0", "0", "看來，笨豬和僕從們很需要我的鞭打啊。", "0", "cv_jyuria_16", "0", "0"},
[421219] = {421219, 12012, 20, 14, "0", "0", "沒骨氣的豬！這點挫折你就放棄了嗎，給我振作起來！", "この能無しブタ野郎！こんなことで諦めるなんて許さないわよ！", "0", "0", "沒骨氣的豬！這點挫折你就放棄了嗎，給我振作起來！", "0", "cv_jyuria_17", "0", "0"},
[421220] = {421220, 12012, 21, 15, "0", "0", "真是動聽的慘叫。", "心地いい悲鳴ね。", "0", "0", "真是動聽的慘叫。", "0", "cv_jyuria_18", "0", "0"},
[421221] = {421221, 12012, 23, 16, "0", "0", "悲鳴吧，讓我聽聽你們的悲鳴吧。", "悲鳴よ。お前たちの悲鳴が聞きたいの。", "0", "0", "悲鳴吧，讓我聽聽你們的悲鳴吧。", "0", "cv_jyuria_20", "0", "0"},
[421222] = {421222, 12012, 22, 38, "0", "0", "呵！做好準備吧。", "ふん！覚悟するのね。", "0", "0", "呵！做好準備吧。", "0", "cv_jyuria_19", "0", "0"},
[421223] = {421223, 12012, 26, 19, "0", "0", "笨豬…繼續加油啊……", "ブタ野郎…しっかりしないと……", "0", "0", "笨豬…繼續加油啊……", "0", "cv_jyuria_21", "0", "0"},
[421224] = {421224, 12012, 27, 20, "0", "0", "欸，你們真了不起呢，居然能在這種公共廁所一樣的地方洗澡。", "へぇ、こんな汚いところでお風呂に入れるなんて。褒めてあげるわ。", "0", "0", "誒，你們真了不起呢，居然能在這種公共廁所一樣的地方洗澡。", "0", "cv_jyuria_22", "0", "0"},
[421225] = {421225, 12012, 28, 21, "0", "0", "笨豬，不要在那裡傻站著，快點過來啦。", "ブタ野郎。そんなところで突っ立ってないで、アタシの世話をするのよ。", "0", "0", "笨豬，不要在那裡傻站著，快點過來啦。", "0", "cv_jyuria_23", "0", "0"},
[421226] = {421226, 12012, 29, 21, "0", "0", "只要笨豬你跪下來舔我的腳趾，我倒不介意讓你看看我高貴的身體。", "跪いて足を舐めるなら、アタシの高貴な體を見せてあげようかしら。", "0", "0", "只要笨豬你跪下來舔我的腳趾，我倒不介意讓你看看我高貴的身體。", "0", "cv_jyuria_24", "0", "0"},
[421227] = {421227, 12012, 30, 22, "0", "0", "探路豬，看看發生什麼了。", "ブタ。先に行って。アンタが偵察してくるのよ。", "0", "0", "探路豬，看看發生什麼了。", "0", "cv_jyuria_25", "0", "0"},
[421228] = {421228, 12012, 31, 23, "0", "0", "笨豬，你不會猜不出我是誰吧！？", "まさかこのアタシが分からないはず、ないわよね？", "0", "0", "笨豬，你不會猜不出我是誰吧！？", "0", "cv_jyuria_26", "0", "0"},
[421229] = {421229, 12012, 32, 24, "0", "0", "嗯，看來你比我想像中要聰明一些。", "ふうん。どうやら思ったよりはマシな頭みたいね。", "0", "0", "嗯，看來你比我想像中要聰明一些。", "0", "cv_jyuria_27", "0", "0"},
[421230] = {421230, 12012, 33, 25, "0", "0", "皮鞭、火烤、高壓電、窒息……選一個你喜歡的吧。", "鞭。火あぶり。感電。窒息。……好きなのを選んでちょうだい。", "0", "0", "皮鞭、火烤、高壓電、窒息……選一個你喜歡的吧。", "0", "cv_jyuria_28", "0", "0"},
[421231] = {421231, 12012, 34, 26, "0", "0", "笨豬，我還以為你不來了呢…“寂寞”？別惹我發笑了，認清自己位置，笨蛋！", "このアホブタ。もう來ないのかと思ったわ……寂しかったか……って笑わせないで！身の程も知らないで……バカ！", "0", "0", "笨豬，我還以為你不來了呢…“寂寞”？別惹我發笑了，認清自己位置，笨蛋！", "0", "cv_jyuria_31", "0", "0"},
[421232] = {421232, 12012, 35, 27, "0", "0", "笨豬，讓我見識下你的覺悟吧，不要讓我無聊喔。", "ブタ野郎の覚悟を見せてちょうだい。退屈させないでよ。", "0", "0", "笨豬，讓我見識下你的覺悟吧，不要讓我無聊喔。", "0", "cv_jyuria_33", "0", "0"},
[421233] = {421233, 12012, 36, 28, "0", "0", "如果你只滿足現狀，我會失望的。", "これで満足しているようじゃ、がっかりね。", "0", "0", "如果你只滿足現狀，我會失望的。", "0", "cv_jyuria_34", "0", "0"},
[421234] = {421234, 12012, 37, 29, "0", "0", "呵呵呵…棲琳在這裡嗎？", "フフフ……シリンはいるかしら？", "0", "0", "呵呵呵…棲琳在這裡嗎？", "0", "cv_jyuria_35", "0", "0"},
