[421300] = {421300, 12013, 1, 1, "0", "0", "蒼霧殘響。", "蒼霧殘響（ハツリバーブ）。", "0", "0", "蒼霧殘響。", "0", "cv_kalian_33", "0", "0"},
[421301] = {421301, 12013, 2, 2, "0", "0", "交給我這種候補生真的好嗎？", "候補生の私が擔當しても宜しいのですか？", "0", "0", "交給我這種候補生真的好嗎？", "0", "cv_kalian_2", "0", "0"},
[421302] = {421302, 12013, 3, 3, "0", "0", "終於見面了，領航。我是薩哈拉支部的候補生，卡蓮。如果不介意的話，可以讓我與您一同前往戰場嗎？", "ナビゲーター、やっとお會いできました。サハラ支部の候補生、カレンと申します。ご迷惑でなければ、戦場に同行させていただいても宜しいでしょうか？", "0", "0", "終於見面了，領航。我是薩哈拉支部的候補生，卡蓮。如果不介意的話，可以讓我與您一同前往戰場嗎？", "0", "cv_kalian_1", "0", "0"},
[421303] = {421303, 12013, 4, 4, "0", "idle", "這就是駕駛員們平時的工作嗎……好的，我會努力的。", "ドライバーの通常業務ですか……わかりました。頑張ります。", "0", "0", "這就是駕駛員們平時的工作嗎……好的，我會努力的。", "0", "cv_kalian_3", "0", "0"},
[421304] = {421304, 12013, 5, 4, "0", "idle", "怎麼說呢？將幻化出的裝備穿在身上的感覺真是太奇妙了……欸？還可以去戰場測試一下嗎？！", "なんと言うか、幻化した裝備を身に付けるのは本當に不思議な感覚ですね。", "0", "0", "怎麼說呢？將幻化出的裝備穿在身上的感覺真是太奇妙了……哎？還可以去戰場測試一下嗎？！", "0", "cv_kalian_4", "0", "0"},
[421305] = {421305, 12013, 6, 4, "0", "idle", "除了我之外應該還有其他候補生吧，如果見到她們的話還請多多關照一下。", "私の他にも候補生がいるのですよね。彼女たちの事も、どうぞよろしくお願いします。", "0", "0", "除了我之外應該還有其他候補生吧，如果見到她們的話還請多多關照一下。", "0", "cv_kalian_30", "0", "0"},
[421306] = {421306, 12013, 7, 5, "1_》_0_0.8", "level1", "這件制服很陌生？啊，這是薩哈拉為候補生們準備的學院服。", "見たことないユニフォーム、ですか？ああ、これはサハラが候補生に用意した制服ですよ。", "0", "0", "這件制服很陌生？啊，這是薩哈拉為候補生們準備的學院服。", "0", "cv_kalian_31", "0", "0"},
[421307] = {421307, 12013, 8, 5, "1_》_0_0.8", "level1", "嗯？正好我有事想要請教您，可以佔有您一些時間嗎？領航。", "あ、ちょうどナビゲーターにお聞きしたい事があったのです。少しお時間を頂いても宜しいですか？", "0", "0", "嗯？正好我有事想要請教您，可以佔有您一些時間嗎？領航。", "0", "cv_kalian_5", "0", "0"},
[421308] = {421308, 12013, 9, 5, "1_》_100_1.5", "level2", "領航，我回去思考了一段時間，但還是有很多事情都弄不明白……非常抱歉，可能今後也還要拜託你了，老師。嗯，還請允許我像這樣稱呼您吧。", "ナビゲーター。しばらく考えたのですが、私には、まだまだ分からないことが沢山あるようです。お手數をおかけいたしますが、今後とも宜しくお願いします、先生。……ええ、先生とお呼びすることをお許しください。", "0", "0", "領航，我回去思考了一段時間，但還是有很多事情都弄不明白……非常抱歉，可能今後也還要拜託你了，老師。嗯，還請允許我像這樣稱呼您吧。", "0", "cv_kalian_6", "0", "0"},
[421309] = {421309, 12013, 10, 5, "1_》_500_2", "level3", "老師，您今天有空嗎？我整理出了一些自己這段時間收集到的記錄，想讓您幫忙看一下可以嗎？當然，如果您正在忙的話，我們改天也可以。", "先生、今日、少しお時間宜しいでしょうか？今までの記録を整理したのですが、ご覧いただけますか？もちろんお忙しいようでしたら、後日でも結構ですので。", "0", "0", "老師，您今天有空嗎？我整理出了一些自己這段時間收集到的記錄，想讓您幫忙看一下可以嗎？當然，如果您正在忙的話，我們改天也可以。", "0", "cv_kalian_7", "0", "0"},
[421310] = {421310, 12013, 11, 5, "1_》_1000_2.5", "level4", "不知不覺已經和你相處了這麼久了啊，老師。在當駕駛員的時間裏，多虧了你的照顧我才沒有受傷。真希望分別的日子可以再晚些……我還有很多想向老師請教的東西……", "先生とはじめてお會いしてから、もうこんなに経ったんですね。先生のおかげで、私は生き延びることができたんですよ。……私、先生とお別れしたくありません。まだまだ教えていただきたいことが、沢山あるんです。", "0", "0", "不知不覺已經和你相處了這麼久了啊，老師。在當駕駛員的時間裡，多虧了你的照顧我才沒有受傷。真希望分別的日子可以再晚些……我還有很多想向老師請教的東西……", "0", "cv_kalian_8", "0", "0"},
[421311] = {421311, 12013, 12, 6, "0", "0", "這真是……非常感謝！", "これは……本當にありがとうございます！", "0", "0", "這真是……非常感謝！", "0", "cv_kalian_9", "0", "0"},
[421312] = {421312, 12013, 13, 7, "0", "0", "馳騁在戰場的感覺……真好。", "戦場を駆け抜ける感じ……素晴らしいです。", "0", "0", "馳騁在戰場的感覺……真好。", "0", "cv_kalian_10", "0", "0"},
[421313] = {421313, 12013, 14, 8, "0", "0", "雖然這麼說有些自大，不過我感覺在你的幫助下，自己已經是個合格的駕駛員了呢。", "自惚れに聞こえるかもしれませんが、私が一人前のドライバーになれたのは、先生のお陰です。", "0", "0", "雖然這麼說有些自大，不過我感覺在你的幫助下，自己已經是個合格的駕駛員了呢。", "0", "cv_kalian_11", "0", "0"},
[421314] = {421314, 12013, 15, 9, "0", "0", "果然，實戰中獲取的經驗才是最寶貴的。", "やはり、実戦での経験ほど貴重なものはありません。", "0", "0", "果然，實戰中獲取的經驗才是最寶貴的。", "0", "cv_kalian_12", "0", "0"},
[421315] = {421315, 12013, 16, 10, "0", "0", "調試完畢，準備戰鬥。", "デバッグ完了。戦闘態勢に入ります。", "0", "0", "調試完畢，準備戰鬥。", "0", "cv_kalian_13", "0", "0"},
[421316] = {421316, 12013, 17, 11, "0", "0", "完勝，沒有人受傷就是最好的結果。", "完勝です！誰も怪我をせずに勝利できたことは、最高の戦果です。", "0", "0", "完勝，沒有人受傷就是最好的結果。", "0", "cv_kalian_14", "0", "0"},
[421317] = {421317, 12013, 18, 12, "0", "0", "任務完成，現在就返回吧，領航。", "任務完了。直ちに帰還しましょう、ナビゲーター。", "0", "0", "任務完成，現在就返回吧，領航。", "0", "cv_kalian_15", "0", "0"},
[421318] = {421318, 12013, 19, 13, "0", "0", "略微有些遺憾嗎？不過算了，這也是寶貴的經驗。", "少し殘念、ですか？でも、これも貴重な経験ですから。", "0", "0", "略微有些遺憾嗎？不過算了，這也是寶貴的經驗。", "0", "cv_kalian_16", "0", "0"},
[421319] = {421319, 12013, 20, 14, "0", "0", "撤退…至少要活下來……", "撤退…せめて生き延びてください……", "0", "0", "撤退…至少要活下來……", "0", "cv_kalian_17", "0", "0"},
