[421324] = {421324, 12013, 26, 19, "0", "0", "撤退…已經來不及了嗎？", "撤退は…もう間に合わないのか……", "0", "0", "撤退…已經來不及了嗎？", "0", "cv_kalian_21", "0", "0"},
[421325] = {421325, 12013, 27, 20, "0", "0", "呼~水溫正好呢，老師。", "ふぅ。いい湯加減ですよ、先生。", "0", "0", "呼~水溫正好呢，老師。", "0", "cv_kalian_23", "0", "0"},
[421326] = {421326, 12013, 28, 21, "0", "0", "多瑙的浴場和薩哈拉的浴場還蠻像的嘛，讓我有種還在學校裏的感覺。", "ダニューブの浴場は、サハラのと隨分似ています。なんだか未だに學校にいるような感じですね。", "0", "0", "多瑙的浴場和薩哈拉的浴場還蠻像的嘛，讓我有種還在學校裡的感覺。", "0", "cv_kalian_24", "0", "0"},
[421327] = {421327, 12013, 29, 21, "0", "0", "好像小時候和姐姐一起洗澡時的感覺一樣呢。", "子供の頃、お姉ちゃんと一緒にお風呂に入ったのを思い出します……", "0", "0", "好像小時候和姐姐一起洗澡時的感覺一樣呢。", "0", "cv_kalian_25", "0", "0"},
[421328] = {421328, 12013, 30, 22, "0", "0", "老師，還請小心一些。", "先生、どうかお気をつけて。", "0", "0", "老師，還請小心一些。", "0", "cv_kalian_26", "0", "0"},
[421329] = {421329, 12013, 31, 23, "0", "0", "稍微玩個小遊戲吧。", "ちょっとしたゲームですね。", "0", "0", "稍微玩個小遊戲吧。", "0", "cv_kalian_27", "0", "0"},
[421330] = {421330, 12013, 32, 24, "0", "0", "果然，不愧是我的老師。", "さすが、私の先生です。", "0", "0", "果然，不愧是我的老師。", "0", "cv_kalian_28", "0", "0"},
[421331] = {421331, 12013, 33, 25, "0", "0", "原來老師也會有出錯的時候啊。", "先生もミスをする時があるのですね。", "0", "0", "原來老師也會有出錯的時候啊。", "0", "cv_kalian_29", "0", "0"},
[421332] = {421332, 12013, 34, 26, "0", "0", "終於等到您了，今天也有一大堆問題想要請教您呢。", "やっとお會いできました。今日も教えて頂きたいことが沢山あるのです。", "0", "0", "終於等到您了，今天也有一大堆問題想要請教您呢。", "0", "cv_kalian_32", "0", "0"},
[421333] = {421333, 12013, 35, 27, "0", "0", "戰場才是最好的教室。", "戦場こそ最高の教室です。", "0", "0", "戰場才是最好的教室。", "0", "cv_kalian_34", "0", "0"},
[421334] = {421334, 12013, 36, 28, "0", "0", "沒有什麼可以難倒我。", "私にとって難しいことではありません。", "0", "0", "沒有什麼可以難倒我。", "0", "cv_kalian_35", "0", "0"},
