[421506] = {421506, 12015, 7, 5, "1_》_0_0.8", "level1", "嘿嘿嘿，您很喜歡我的頭髮嗎？", "0", "0", "0", "嘿嘿嘿，您很喜歡我的頭髮嗎？", "0", "cv_vicepearl_31", "0", "0"},
[421507] = {421507, 12015, 8, 5, "1_》_0_0.8", "level1", "怎麼了？您也有緊張的時候嗎？別擔心，我不會為難您的。", "0", "0", "0", "怎麼了？您也有緊張的時候嗎？別擔心，我不會為難您的。", "0", "cv_vicepearl_5", "0", "0"},
[421508] = {421508, 12015, 9, 5, "1_》_100_1.5", "level2", "多瑙的勢力錯綜複雜，現在大家只不過是因為原罪而聯合在了一起。不過我還是相信父親能處理好這一切，所以您大可不必擔心，這裡永遠歡迎您。", "0", "0", "0", "多瑙的勢力錯綜複雜，現在大家只不過是因為原罪而聯合在了一起。不過我還是相信父親能處理好這一切，所以您大可不必擔心，這裡永遠歡迎您。", "0", "cv_vicepearl_6", "0", "0"},
[421509] = {421509, 12015, 10, 5, "1_》_500_2", "level3", "我必須要為未來做好準備，當父親老去，當原罪從世界上消失，多瑙又會走向何方？必須得有一個多瑙人得在這場戰爭中成為新的傳奇，這是我們無法規避的命運。領航……我希望您能支持我。", "0", "0", "0", "我必須要為未來做好準備，當父親老去，當原罪從世界上消失，多瑙又會走向何方？必須得有一個多瑙人得在這場戰爭中成為新的傳奇，這是我們無法規避的命運。領航……我希望您能支持我。", "0", "cv_vicepearl_7", "0", "0"},
[421510] = {421510, 12015, 11, 5, "1_》_1000_2.5", "level4", "長夜終會迎來黎明，而為這片土地帶來黎明的也許不會是任何一個個人。但是這片土地的人需要一個偶像，需要一篇傳奇。領航，我能看出您並不屬於多瑙，也許多年之後我們也會站在彼此的對立面吧。但無論結局如何，我的傳奇故事中一定會為您留下筆墨的。", "0", "0", "0", "長夜終會迎來黎明，而為這片土地帶來黎明的也許不會是任何一個個人。但是這片土地的人需要一個偶像，需要一篇傳奇。領航，我能看出您並不屬於多瑙，也許多年之後我們也會站在彼此的對立面吧。但無論結局如何，我的傳奇故事中一定會為您留下筆墨的。", "0", "cv_vicepearl_8", "0", "0"},
[421511] = {421511, 12015, 12, 6, "0", "0", "由衷地感謝您。", "0", "0", "0", "由衷地感謝您。", "0", "cv_vicepearl_9", "0", "0"},
