[421603] = {421603, 12016, 4, 4, "0", "idle", "今天的樂隊練習怎麼辦呢？…啊，把大家都叫來就好了呀！", "0", "0", "0", "今天的樂隊練習怎麼辦呢？…啊，把大家都叫來就好了呀！", "0", "cv_saraid_3", "0", "0"},
[421604] = {421604, 12016, 5, 4, "0", "idle", "之前發售的專輯比想像中賣得還要快，我特意幫領航留了一套，一定要記得聽喔~", "0", "0", "0", "之前發售的專輯比想像中賣得還要快，我特意幫領航留了一套，一定要記得聽哦~", "0", "cv_saraid_4", "0", "0"},
[421605] = {421605, 12016, 6, 4, "0", "idle", "多虧了艾希麗卡給了我希望，我才能重新拾起音樂。雖然很多人都不能接受我們的音樂，但是只要有一個人喜歡……那它就有存在的意義！", "0", "0", "0", "多虧了艾希麗卡給了我希望，我才能重新拾起音樂。雖然很多人都不能接受我們的音樂，但是只要有一個人喜歡……那它就有存在的意義！", "0", "cv_saraid_30", "0", "0"},
[421606] = {421606, 12016, 7, 5, "1_》_0_0.8", "level1", "真希望有一天，我們樂隊能開巡迴演唱會，讓全世界的人聽到我們的音樂……領航？你為什麼是一副看到世界末日的表情！", "0", "0", "0", "真希望有一天，我們樂隊能開巡迴演唱會，讓全世界的人聽到我們的音樂……領航？你為什麼是一副看到世界末日的表情！", "0", "cv_saraid_31", "0", "0"},
[421607] = {421607, 12016, 8, 5, "1_》_0_0.8", "level1", "就算是fan領航，對於skinship也要注意喔。", "0", "0", "0", "就算是fan領航，對於skinship也要注意哦。", "0", "cv_saraid_5", "0", "0"},
[421608] = {421608, 12016, 9, 5, "1_》_100_1.5", "level2", "領航，要是有空的話要不要一起去商店轉轉？喜歡的樂隊出新曲了！到底是怎樣的曲子呢……好在意啊！", "0", "0", "0", "領航，要是有空的話要不要一起去商店轉轉？喜歡的樂隊出新曲了！到底是怎樣的曲子呢……好在意啊！", "0", "cv_saraid_6", "0", "0"},
[421609] = {421609, 12016, 10, 5, "1_》_500_2", "level3", "啊~啊~啊~啊~啊！——領航？你什麼時候來的！？糟糕…能不能當做什麼都沒聽見呢？拜託了！", "0", "0", "0", "啊~啊~啊~啊~啊！——領航？你什麼時候來的！？糟糕…能不能當做什麼都沒聽見呢？拜託了！", "0", "cv_saraid_7", "0", "0"},
[421610] = {421610, 12016, 11, 5, "1_》_1000_2.5", "level4", "領航，這是下週樂隊演唱會的門票。請一定要來參加！我為領航準備了特別的樂曲……領航，為什麼要跑啊！", "0", "0", "0", "領航，這是下周樂隊演唱會的門票。請一定要來參加！我為領航準備了特別的樂曲……領航，為什麼要跑啊！", "0", "cv_saraid_8", "0", "0"},
[421611] = {421611, 12016, 12, 6, "0", "0", "我將獻上更動聽的旋律。", "0", "0", "0", "我將獻上更動聽的旋律。", "0", "cv_saraid_9", "0", "0"},
[421612] = {421612, 12016, 13, 7, "0", "0", "我想要給大家帶來希望，而舞臺一直會承載著我的願望！", "0", "0", "0", "我想要給大家帶來希望，而舞臺一直會承載著我的願望！", "0", "cv_saraid_10", "0", "0"},
[421613] = {421613, 12016, 14, 8, "0", "0", "音樂裏飽含著無限的可能性。我感覺到現在我可以真正地抓住這可能性了。謝謝你，領航。你給我和我的音樂能夠飛向更遠處。", "0", "0", "0", "音樂裡飽含著無限的可能性。我感覺到現在我可以真正地抓住這可能性了。謝謝你，領航。你給我和我的音樂能夠飛向更遠處。", "0", "cv_saraid_11", "0", "0"},
[421614] = {421614, 12016, 15, 9, "0", "0", "掌握了新的編曲法，這就加入新的單曲裏試試吧！", "0", "0", "0", "掌握了新的編曲法，這就加入新的單曲裡試試吧！", "0", "cv_saraid_12", "0", "0"},
