[421700] = {421700, 12017, 1, 1, "0", "0", "蒼霧殘響~", "蒼霧殘響（ハツリバーブ）！", "0", "0", "0", "0", "cv_lin_sw_33", "0", "0"},
[421701] = {421701, 12017, 2, 2, "0", "0", "久等了！——鈴的超天才模式已經準備就緒了！實驗開始……誒？你問平時是什麼狀態？——那當然是天才模式啦？！", "お待たせー！鈴、超天才モードの準備オッケー！実験を開始するよー！……え、普段はどんなモード？當然、天才モードだけど？", "0", "0", "0", "0", "cv_lin_sw_1", "0", "0"},
[421702] = {421702, 12017, 3, 3, "0", "0", "哇，我把太陽傘一起帶到這裏可以嗎？水之狐丸也過來這邊吧~", "うわぁ！ここにパラソル差しちゃっていい？きつね丸たちもこっちにおいでー！", "0", "0", "0", "0", "cv_lin_sw_2", "0", "0"},
[421703] = {421703, 12017, 4, 4, "0", "idle", "領航，我在這裏等了你好久呢！快走吧！呼呼，這個夏天，本天才一定要讓你留下拍案叫絕的回憶的！——你說我成語用錯了？才沒有！", "ナビゲーター、待ってたよー！早く行こー！ふっふーん。この夏は、ゆりかごから墓場までの思い出を天才のあたしが作ってあげるんだから！……言葉の使い方を間違ってる？そ、そんなことないもん！", "0", "0", "0", "0", "cv_lin_sw_3", "0", "0"},
[421704] = {421704, 12017, 5, 4, "0", "idle", "超天才也會遇到困擾的事情哦！如果全都一下子就看懂的話，豈不是太無聊了！", "超天才にだって悩みくらいあるよ。何もかもぜーんぶ分かっちゃったら、つまんないでしょ？", "0", "0", "0", "0", "cv_lin_sw_4", "0", "0"},
[421705] = {421705, 12017, 6, 4, "0", "idle", "真想要讓這夏日的場景再停留一會啊~但是這樣是不行的，領航和我都要向前跑才對。", "この夏がもっと続いてくれたらなぁ……。でも、ダメだよね。ナビゲーターもあたしも、前に進まなきゃ。", "0", "0", "0", "0", "cv_lin_sw_30", "0", "0"},
[421706] = {421706, 12017, 7, 5, "1_》_0_0.8", "level1", "“我成為了一個英雄了嗎”“我成為保護大家的力量了嗎？”我有的時候會這麼想。也許正是因為這樣的想法，我才沒有走太多歪路吧。", "ヒーローになれたか……みんなを守れるのか……時々、そんなことを考えちゃうんだ。だからこそ、いまのあたしがあるんだけどね。", "0", "0", "0", "0", "cv_lin_sw_31", "0", "0"},
[421707] = {421707, 12017, 8, 5, "1_》_0_0.8", "level1", "領航！領航！你看，我這次考試全部都是滿分哦？誇我誇我！", "ナビゲーター見て見てー！今回のテスト全部満點だったよ！褒めて褒めてー！", "0", "0", "0", "0", "cv_lin_sw_5", "0", "0"},
[421708] = {421708, 12017, 9, 5, "1_》_100_1.5", "level2", "你問我頭上的耳朵是不是真的？當然是真的啦！你要摸摸看嗎？——呀！不許摸，太敏感了！", "この耳が本物かって？もちろん本物だよー。觸ってみたい？……ひゃっ！急に觸んないでよ、敏感なんだから！", "0", "0", "0", "0", "cv_lin_sw_6", "0", "0"},
[421709] = {421709, 12017, 10, 5, "1_》_500_2", "level3", "這裏是虛幻的世界呢？是這樣嗎？一切都結束之後，大家都會淡忘這段記憶嗎？那麼本天才就想一想，有沒有辦法保留下我與你的這段回憶了。", "ここってまぼろしの世界だよね？ぜんぶ終わったらみんなここの事、忘れちゃうのかな？じゃあこの天才が、思い出を殘す方法を見つけてみせるよ！", "0", "0", "0", "0", "cv_lin_sw_7", "0", "0"},
[421710] = {421710, 12017, 11, 5, "1_》_1000_2.5", "level4", "這真是一段讓人能沉溺在其中的美夢……如果，我是說如果，我不再是超天才。領航……你還會記得這樣的我嗎……我絕對，絕對不會忘記的！", "この夢、ずーっと見ていたいなぁ。……もし、もしもなんだけどさ……あたしが超天才じゃなくなっても、ナビゲーターは覚えていてくれるかな？あたしは絶対、絶っ対忘れないよ！", "0", "0", "0", "0", "cv_lin_sw_8", "0", "0"},
[421711] = {421711, 12017, 12, 6, "0", "0", "夏日力提升了。", "サマーパワーレベルアァァップッ！", "0", "0", "0", "0", "cv_lin_sw_9", "0", "0"},
[421712] = {421712, 12017, 13, 7, "0", "0", "哦！鼓動的泳裝力量充斥著我的全身。", "おおぉ！水著パワーがみなぎってきたぁ！", "0", "0", "0", "0", "cv_lin_sw_10", "0", "0"},
[421713] = {421713, 12017, 14, 8, "0", "0", "這就是我的極限了？哼哼，天才是不會停下自己的腳步的，極限就是用來超越的！", "これがあたしの限界？……ふふん、天才に不可能はないんだよ。限界は超えるものだもんね！", "0", "0", "0", "0", "cv_lin_sw_11", "0", "0"},
[421714] = {421714, 12017, 15, 9, "0", "0", "知識的積累也很重要呢……但是呢，我討厭看書！！！", "勉強しなくちゃいけないことはいっぱいあるけど……本は嫌いなの！", "0", "0", "0", "0", "cv_lin_sw_12", "0", "0"},
[421715] = {421715, 12017, 16, 10, "0", "0", "天才登場，大家就退到我身後吧，我會保護你們的！", "天才様のお出ましだよー！あたしが守るから、みんな後ろに下がって！", "0", "0", "0", "0", "cv_lin_sw_13", "0", "0"},
[421716] = {421716, 12017, 17, 11, "0", "0", "實驗成功。作戰完美執行。不愧是超天才的我！", "実験成功！完璧な作戦だったね。さすがあたし、超天才！", "0", "0", "0", "0", "cv_lin_sw_14", "0", "0"},
[421717] = {421717, 12017, 18, 12, "0", "0", "預料之中的損失，我已經幫你把下一次的行動路線規劃好了，重整旗鼓吧！", "これくらい想定內だよ。次の作戦も準備できてるから、切り替えていこー！", "0", "0", "0", "0", "cv_lin_sw_15", "0", "0"},
[421718] = {421718, 12017, 19, 13, "0", "0", "呃嗯嗯……事態還沒脫離我們的掌控，領航不要放棄啊！", "ぐぬぬ……もっとうまくできるはずだよ。ナビゲーター、がんばろー！", "0", "0", "0", "0", "cv_lin_sw_16", "0", "0"},
[421719] = {421719, 12017, 20, 14, "0", "0", "嗚……看來我所預設的未來還不夠充分。", "うぅ……あたしの読みが甘かったかぁ……", "0", "0", "0", "0", "cv_lin_sw_17", "0", "0"},
[421720] = {421720, 12017, 21, 15, "0", "0", "哎嘿，一擊必殺！", "えっへん、一撃必殺！", "0", "0", "0", "0", "cv_lin_sw_18", "0", "0"},
[421721] = {421721, 12017, 23, 16, "0", "0", "嘿！", "ほいっ！", "0", "0", "0", "0", "cv_lin_sw_19", "0", "0"},
[421722] = {421722, 12017, 24, 17, "0", "0", "這就是展現天才實力的最佳時機！", "天才の実力をみせる時だぁー！", "0", "0", "0", "0", "cv_lin_sw_21", "0", "0"},
[421723] = {421723, 12017, 25, 18, "0", "0", "夏日！泳裝！超天才的概念能量在此時溢滿而出。盛夏的實驗場沒有退路，這是只有親身體驗才能明白的水之研究派對！", "夏！そして水著！超天才のエネルギーが溢れ出ているっ！真夏の実験場に出口なし！これは體験してみないとわからない水の実験パーティーだー！", "0", "0", "0", "0", "cv_lin_sw_22", "0", "0"},
[421724] = {421724, 12017, 22, 38, "0", "0", "找到了！", "発見っ！", "0", "0", "0", "0", "cv_lin_sw_45", "0", "0"},
[421725] = {421725, 12017, 26, 19, "0", "0", "狐丸，啟動緊急撤退裝置……", "きつね丸、緊急脫出裝置を……", "0", "0", "0", "0", "cv_lin_sw_20", "0", "0"},
[421726] = {421726, 12017, 27, 20, "0", "0", "為什麼游泳之後還要洗澡？？", "泳いだあとにお風呂入るのおかしくなーい？", "0", "0", "0", "0", "cv_lin_sw_23", "0", "0"},
[421727] = {421727, 12017, 28, 21, "0", "0", "誒？澡堂裏竟然有橡膠鴨子！", "あ、お風呂にアヒルさんがいるー！", "0", "0", "0", "0", "cv_lin_sw_24", "0", "0"},
[421728] = {421728, 12017, 29, 21, "0", "0", "呼~哦——我打算開發一個能一直冒泡的裝置！", "ふぅうぅ……ジャグジーもほしいなぁ……", "0", "0", "0", "0", "cv_lin_sw_25", "0", "0"},
[421729] = {421729, 12017, 30, 22, "0", "0", "領航？！你、你也一起來嗎。", "ナビゲーター！い、一緒に行くか？", "0", "0", "0", "0", "cv_lin_sw_26", "0", "0"},
[421730] = {421730, 12017, 31, 23, "0", "0", "哇嗚嗚，被太陽曬的地方有點痛，應該抹防曬霜的……", "あああ……日焼けしすぎてちょっと痛いぃー。オイル塗るの忘れてたぁ……", "0", "0", "0", "0", "cv_lin_sw_27", "0", "0"},
[421731] = {421731, 12017, 32, 24, "0", "0", "聽到聲音就知道了吧？就是本天才哦！", "天才の聲を間違えるはずないよねー！", "0", "0", "0", "0", "cv_lin_sw_28", "0", "0"},
[421732] = {421732, 12017, 33, 25, "0", "0", "欸……？你把我弄疼啦！領航是笨蛋！", "ちょ、ちょっと、痛いんだけどー！ナビゲーターのバカッ！", "0", "0", "0", "0", "cv_lin_sw_29", "0", "0"},
[421733] = {421733, 12017, 34, 26, "0", "0", "歡迎回來，我們馬上就要開party了！燒烤party！", "おかえりー！もうすぐパーティーがはじまるよー！焼肉パーティー！", "0", "0", "0", "0", "cv_lin_sw_32", "0", "0"},
[421734] = {421734, 12017, 35, 27, "0", "0", "趕緊解決戰鬥之後來游泳吧！", "さっさと片付けて泳ぎにいこ！", "0", "0", "0", "0", "cv_lin_sw_34", "0", "0"},
[421735] = {421735, 12017, 36, 28, "0", "0", "比游泳的話我可不會輸哦！", "泳ぎなら負けないもんね！", "0", "0", "0", "0", "cv_lin_sw_35", "0", "0"},
[421736] = {421736, 12017, 37, 29, "0", "0", "我給你們帶了伴手禮哦~", "お土産持ってきたよー！", "0", "0", "0", "0", "cv_lin_sw_36", "0", "0"},
[421737] = {421737, 12017, 38, 30, "0", "0", "大家為什麼都不出來玩？", "みんな遊ばないの？", "0", "0", "0", "0", "cv_lin_sw_37", "0", "0"},
[421738] = {421738, 12017, 39, 31, "0", "0", "給狐丸也配個救生圈……啊，好像能飛欸？", "きつね丸にも浮き輪を……あ、飛べるからいらないか。", "0", "0", "0", "0", "cv_lin_sw_38", "0", "0"},
[421739] = {421739, 12017, 40, 32, "0", "0", "我要防曬霜！領航幫我抹背上！", "日焼け止め買ったんだー！ナビゲーター、背中に塗って塗ってー！", "0", "0", "0", "0", "cv_lin_sw_39", "0", "0"},
[421740] = {421740, 12017, 41, 33, "0", "0", "領航你看，我發現你的照片了！", "ナビゲーターの寫真、発見！", "0", "0", "0", "0", "cv_lin_sw_40", "0", "0"},
[421741] = {421741, 12017, 42, 34, "0", "0", "需要本天才幫你嗎？", "天才が助けてあげよっか？", "0", "0", "0", "0", "cv_lin_sw_41", "0", "0"},
[421742] = {421742, 12017, 43, 35, "0", "0", "有信件了嗎？", "メールが來たのー？", "0", "0", "0", "0", "cv_lin_sw_42", "0", "0"},
[421743] = {421743, 12017, 44, 36, "0", "0", "喂~有人線上嗎？", "もしもーし、誰かいるー？", "0", "0", "0", "0", "cv_lin_sw_43", "0", "0"},
[421744] = {421744, 12017, 45, 37, "0", "0", "這是什麼？", "なにこれ？", "0", "0", "0", "0", "cv_lin_sw_44", "0", "0"},
[421800] = {421800, 12018, 1, 1, "0", "0", "蒼霧殘響", "0", "0", "0", "0", "0", "cv_xhixha_1", "0", "0"},
[421801] = {421801, 12018, 2, 2, "0", "0", "全部交給我就好~", "0", "0", "0", "0", "0", "cv_xhixha_2", "0", "0"},
[421802] = {421802, 12018, 3, 3, "0", "0", "珀因雷德首席橋梁設計師——希夏報道！不介意的話，就讓我用這副巨大身軀承載你的意志，成為架向未來之橋吧~", "0", "0", "0", "0", "0", "cv_xhixha_3", "0", "0"},
[421803] = {421803, 12018, 4, 4, "0", "idle", "以前也偶爾因工作來到多瑙，不過以駕駛員的身份俯瞰城市還是會不免感歎，不同地方的風景果然大相徑庭呢。", "0", "0", "0", "0", "0", "cv_xhixha_4", "0", "0"},
[421804] = {421804, 12018, 5, 4, "0", "idle2", "領航一動不動的，是在沉思什麼嗎？我在設計工作中也常常陷入苦惱，不過小酌一杯的話，偶爾可能會靈感乍現，領航也試試看吧？", "0", "0", "0", "0", "0", "cv_xhixha_5", "0", "0"},
[421805] = {421805, 12018, 6, 4, "0", "idle3", "之前也就算了，成為駕駛員後海因卻還是窩在房裡不肯鍛煉，要不我們下次健身時也叫上她一起？領航你去邀請的話，她肯定不會拒絕的。", "0", "0", "0", "0", "0", "cv_xhixha_6", "0", "0"},
[421806] = {421806, 12018, 7, 5, "1_》_0_0.8", "level1", "我頭上的花？是喲，這是鳶尾花髮飾，在珀因雷德中央峽谷間也盛放著這道色彩，它被譽為彩虹女神的象徵，也是連接神界與人間的使者哦。", "0", "0", "0", "0", "0", "cv_xhixha_7", "0", "0"},
[421807] = {421807, 12018, 8, 5, "1_》_0_0.8", "level1", "下班後要一起去逛逛嗎？多瑙這麼大，肯定還有很多有趣的地方我沒去過，領航最喜歡哪家餐廳，哪片公園？歡迎向我推薦！", "0", "0", "0", "0", "0", "cv_xhixha_8", "0", "0"},
[421808] = {421808, 12018, 9, 5, "1_》_100_1.5", "level2", "最近又買了好多東西，拼裝積木，鐵道模型，還有貓爬架，我想在多瑙這邊的家裡也建一個微縮版遊樂園，這就是工程設計的樂趣~", "0", "0", "0", "0", "0", "cv_xhixha_9", "0", "0"},
[421809] = {421809, 12018, 10, 5, "1_》_500_2", "level3", "比起單純觸碰，我想要更加親密的接觸，比如……我還記得我們初次進行通感時的那份感受，城市、山巒，以及心靈都變得像天空一樣澄澈透明。", "0", "0", "0", "0", "0", "cv_xhixha_10", "0", "0"},
[421810] = {421810, 12018, 11, 5, "1_》_1000_2.5", "level4", "所謂橋樑，是既不在此岸也不在彼端之物，它只是一種“過程”，就像連通著過去與未來的“此時此刻”。當我們漫步在時間之橋上，只要著眼於當下的每個瞬間，就絕不會迷失方向。", "0", "0", "0", "0", "0", "cv_xhixha_11", "0", "0"},
[421811] = {421811, 12018, 12, 6, "0", "0", "感謝~", "0", "0", "0", "0", "0", "cv_xhixha_12", "0", "0"},
[421812] = {421812, 12018, 13, 7, "0", "0", "提升的感覺真不錯。", "0", "0", "0", "0", "0", "cv_xhixha_13", "0", "0"},
[421813] = {421813, 12018, 14, 8, "0", "0", "我自認為是個樂觀主義者，所以隨能力增長帶來的更多責任、更大的危險之類都沒什麼好擔憂的，比起那些，更重要的是我今後能與你一起做到更多。", "0", "0", "0", "0", "0", "cv_xhixha_14", "0", "0"},
[421814] = {421814, 12018, 15, 9, "0", "0", "修築，然後鞏固。", "0", "0", "0", "0", "0", "cv_xhixha_15", "0", "0"},
[421815] = {421815, 12018, 16, 10, "0", "0", "戰鬥，會是一座通往何方的橋樑？", "0", "0", "0", "0", "0", "cv_xhixha_16", "0", "0"},
[421816] = {421816, 12018, 17, 11, "0", "0", "看來這次，我們通向了勝利~", "0", "0", "0", "0", "0", "cv_xhixha_17", "0", "0"},
[421817] = {421817, 12018, 18, 12, "0", "0", "雖然不完美，但也不錯。", "0", "0", "0", "0", "0", "cv_xhixha_18", "0", "0"},
[421818] = {421818, 12018, 19, 13, "0", "0", "好險，差點失敗！", "0", "0", "0", "0", "0", "cv_xhixha_19", "0", "0"},
[421819] = {421819, 12018, 20, 14, "0", "0", "唔……到底是哪出了問題？", "0", "0", "0", "0", "0", "cv_xhixha_20", "0", "0"},
[421820] = {421820, 12018, 21, 15, "0", "0", "又完成一項工作。", "0", "0", "0", "0", "0", "cv_xhixha_21", "0", "0"},
[421821] = {421821, 12018, 23, 16, "0", "0", "“光橋”展開！", "0", "0", "0", "0", "0", "cv_xhixha_22", "0", "0"},
[421822] = {421822, 12018, 24, 17, "0", "0", "大家加油哦！", "0", "0", "0", "0", "0", "cv_xhixha_23", "0", "0"},
[421823] = {421823, 12018, 25, 18, "0", "0", "這座橋樑，直抵未來！", "0", "0", "0", "0", "0", "cv_xhixha_24", "0", "0"},
[421824] = {421824, 12018, 22, 38, "0", "0", "必要的準備。", "0", "0", "0", "0", "0", "cv_xhixha_25", "0", "0"},
[421825] = {421825, 12018, 26, 19, "0", "0", "不得不撤退了啊……", "0", "0", "0", "0", "0", "cv_xhixha_26", "0", "0"},
[421826] = {421826, 12018, 27, 20, "0", "0", "和領航一起嗎？真讓人期待~", "0", "0", "0", "0", "0", "cv_xhixha_27", "0", "0"},
[421827] = {421827, 12018, 28, 21, "0", "0", "困了嗎？在這種氛圍中果然不知不覺就想睡覺啊。", "0", "0", "0", "0", "0", "cv_xhixha_28", "0", "0"},
[421828] = {421828, 12018, 29, 21, "0", "0", "領航的眼神好專注，難道我身上哪裡有痣？", "0", "0", "0", "0", "0", "cv_xhixha_29", "0", "0"},
[421829] = {421829, 12018, 30, 22, "0", "0", "嗯嗯？", "0", "0", "0", "0", "0", "cv_xhixha_30", "0", "0"},
[421830] = {421830, 12018, 31, 23, "0", "0", "不可以用通感作弊哦。", "0", "0", "0", "0", "0", "cv_xhixha_31", "0", "0"},
[421831] = {421831, 12018, 32, 24, "0", "0", "bingo~不愧是領航！", "0", "0", "0", "0", "0", "cv_xhixha_32", "0", "0"},
[421832] = {421832, 12018, 33, 25, "0", "0", "好失落……得努力給你留下更深的印象了！", "0", "0", "0", "0", "0", "cv_xhixha_33", "0", "0"},
[421833] = {421833, 12018, 34, 26, "0", "0", "嗨~！今天又是生機勃勃的一天，城市裡不知會多出多少商鋪，上演多少戲劇，我也會幹勁十足地輔佐你，並時刻期待著下班後與你一起的遊玩時間~", "0", "0", "0", "0", "0", "cv_xhixha_34", "0", "0"},
[421834] = {421834, 12018, 35, 27, "0", "0", "准備萬全就出發吧！", "0", "0", "0", "0", "0", "cv_xhixha_35", "0", "0"},
