[421901] = {421901, 12019, 2, 2, "0", "0", "接下來的任務是駐守這裡？", "0", "0", "0", "0", "0", "cv_kaitelin_2", "0", "0"},
[421902] = {421902, 12019, 3, 3, "0", "0", "黑荊棘編號ODY763001，你也可以叫我的名字——凱特琳。", "0", "0", "0", "0", "0", "cv_kaitelin_3", "0", "0"},
[421903] = {421903, 12019, 4, 4, "0", "idle", "恕我直言，這裡的安防措施在我看來漏洞百出。", "0", "0", "0", "0", "0", "cv_kaitelin_4", "0", "0"},
[421904] = {421904, 12019, 5, 4, "0", "idle2", "我不太理解領航你的想法，佔用我一個駕駛員的戰鬥力僅僅是在這裡站崗？", "0", "0", "0", "0", "0", "cv_kaitelin_5", "0", "0"},
[421905] = {421905, 12019, 6, 4, "0", "idle3", "管理一個小隊並不輕鬆，特別是當你的隊員都是擁有強烈個人色彩的傢夥的時候。不過所幸我在當員警時管理過不少這樣的人。", "0", "0", "0", "0", "0", "cv_kaitelin_6", "0", "0"},
[421906] = {421906, 12019, 7, 5, "1_》_0_0.8", "level1", "我只是想守護我想守護的東西，作為特警的我失敗了，但是作為駕駛員的我一定會成功。你會幫我？那一言為定……怎麼，你以為我是那種自負的笨蛋嗎？", "0", "0", "0", "0", "0", "cv_kaitelin_7", "0", "0"},
[421907] = {421907, 12019, 8, 5, "1_》_0_0.8", "level1", "哼，這次只是警告。", "0", "0", "0", "0", "0", "cv_kaitelin_8", "0", "0"},
[421908] = {421908, 12019, 9, 5, "1_》_100_1.5", "level2", "碰我可以但不能碰我的槍。", "0", "0", "0", "0", "0", "cv_kaitelin_9", "0", "0"},
[421909] = {421909, 12019, 10, 5, "1_》_500_2", "level3", "聽說領航你也懂一點射擊？只用過手槍嗎……那你想要試試狙擊槍嗎？我們可以先從後坐力最小的練起。", "0", "0", "0", "0", "0", "cv_kaitelin_10", "0", "0"},
[421910] = {421910, 12019, 11, 5, "1_》_1000_2.5", "level4", "領航上次戰鬥你使用的那套戰術效果非凡，我有幾個戰鬥上的想法想與你探討探討。要不我們去你的住處吧，免得閒人打擾，或者到我的住處也行。", "0", "0", "0", "0", "0", "cv_kaitelin_11", "0", "0"},
[421911] = {421911, 12019, 12, 6, "0", "0", "很特殊的練習方法。", "0", "0", "0", "0", "0", "cv_kaitelin_12", "0", "0"},
[421912] = {421912, 12019, 13, 7, "0", "0", "軍銜提升了嗎？", "0", "0", "0", "0", "0", "cv_kaitelin_13", "0", "0"},
[421913] = {421913, 12019, 14, 8, "0", "0", "奇怪的感覺，好像槍更趁手了。", "0", "0", "0", "0", "0", "cv_kaitelin_14", "0", "0"},
[421914] = {421914, 12019, 15, 9, "0", "0", "不練習就會生疏。", "0", "0", "0", "0", "0", "cv_kaitelin_15", "0", "0"},
[421915] = {421915, 12019, 16, 10, "0", "0", "黑荊棘小隊，到達目標地點。", "0", "0", "0", "0", "0", "cv_kaitelin_16", "0", "0"},
[421916] = {421916, 12019, 17, 11, "0", "0", "任務完成，等待進一步指示——", "0", "0", "0", "0", "0", "cv_kaitelin_17", "0", "0"},
