[421926] = {421926, 12019, 27, 20, "0", "0", "人和槍一樣需要保養。", "0", "0", "0", "0", "0", "cv_kaitelin_27", "0", "0"},
[421927] = {421927, 12019, 28, 21, "0", "0", "這裡的水溫是不是太燙了？", "0", "0", "0", "0", "0", "cv_kaitelin_28", "0", "0"},
[421928] = {421928, 12019, 29, 21, "0", "0", "巨大化下……感覺很奇妙……", "0", "0", "0", "0", "0", "cv_kaitelin_29", "0", "0"},
