[421933] = {421933, 12019, 34, 26, "0", "0", "發現可疑人員……哦，原來是領航啊。", "0", "0", "0", "0", "0", "cv_kaitelin_34", "0", "0"},
[421934] = {421934, 12019, 35, 27, "0", "0", "請下達命令吧。", "0", "0", "0", "0", "0", "cv_kaitelin_35", "0", "0"},
