[421944] = {421944, 12019, 45, 37, "0", "0", "這裡。", "0", "0", "0", "0", "0", "cv_kaitelin_45", "0", "0"},
[422000] = {422000, 12020, 1, 1, "0", "0", "蒼霧殘響", "0", "0", "0", "0", "0", "cv_flovilla_34", "0", "0"},
[422001] = {422001, 12020, 2, 2, "0", "0", "嘿咻！…誒？只是待在這裏嗎…我明白了……", "0", "0", "0", "0", "0", "cv_flovilla_2", "0", "0"},
[422002] = {422002, 12020, 3, 3, "0", "0", "嗚哇哇，你原來是領航嗎？我是弗洛維拉，之後就麻煩你帶路咯~", "0", "0", "0", "0", "0", "cv_flovilla_1", "0", "0"},
[422003] = {422003, 12020, 4, 4, "0", "idle", "這裏…還有這裏…嗯，決定好了！領航，我已經規劃好節假日要去的地方了，你要來嗎？", "0", "0", "0", "0", "0", "cv_flovilla_3", "0", "0"},
[422004] = {422004, 12020, 5, 4, "0", "idle", "宇宙航行時總會遇到各種難題,燃料不足、導航系統失靈之類的；不過我總會有辦法解決它們，我很了不起吧！", "0", "0", "0", "0", "0", "cv_flovilla_4", "0", "0"},
[422005] = {422005, 12020, 6, 4, "0", "idle", "唉…現在想起來還是很可怕啊，密托希瓦她們一瞬間就被拍飛了。那個大家夥，真是個不折不扣的怪物呀。", "0", "0", "0", "0", "0", "cv_flovilla_31", "0", "0"},
[422006] = {422006, 12020, 7, 5, "1_》_0_0.8", "level1", "為什麼要旅行？因為宇宙就在那裏！咳咳，當然是因為我喜歡旅行啦，想要一直旅行，死在旅行的路上；死了以後也要繼續我的旅行，我的這份心情，你能明白嗎？", "0", "0", "0", "0", "0", "cv_flovilla_32", "0", "0"},
[422007] = {422007, 12020, 8, 5, "1_》_0_0.8", "level1", "領航，就算你不停地摸我，我也不會給你零食的。", "0", "0", "0", "0", "0", "cv_flovilla_5", "0", "0"},
[422008] = {422008, 12020, 9, 5, "1_》_100_1.5", "level2", "宇宙裏存在著各種各樣的外星人呢，真的很有趣。誒，我也是外星人？這個…的確呢……", "0", "0", "0", "0", "0", "cv_flovilla_6", "0", "0"},
[422009] = {422009, 12020, 10, 5, "1_》_500_2", "level3", "領航，我們去旅行吧！丟下所有煩心的、讓人不快樂的事情，來一場只有你和我的旅行，怎麼樣？", "0", "0", "0", "0", "0", "cv_flovilla_7", "0", "0"},
[422010] = {422010, 12020, 11, 5, "1_》_1000_2.5", "level4", "如你所瞭解的那樣…真正的我已經死了；現在的我，說不定只是一道思念的幻影。即便如此，你也願意與我踏上旅途嗎？這樣的話…或許你就是我的“終點”呢。", "0", "0", "0", "0", "0", "cv_flovilla_8", "0", "0"},
[422011] = {422011, 12020, 12, 6, "0", "0", "變強後肚子餓了呢~", "0", "0", "0", "0", "0", "cv_flovilla_9", "0", "0"},
[422012] = {422012, 12020, 13, 7, "0", "0", "設備升級！這下就無敵了吧？", "0", "0", "0", "0", "0", "cv_flovilla_10", "0", "0"},
[422013] = {422013, 12020, 14, 8, "0", "0", "地球上的力量，真是不可思議啊。嗯，這樣一來，大概連黑洞的視界也抓不住我了吧！下次…遇到那個大家夥的時候，不會再輸了！", "0", "0", "0", "0", "0", "cv_flovilla_11", "0", "0"},
[422014] = {422014, 12020, 15, 9, "0", "0", "謝謝~", "0", "0", "0", "0", "0", "cv_flovilla_12", "0", "0"},
[422015] = {422015, 12020, 16, 10, "0", "0", "著陸成功，開始探測生命體信號！", "0", "0", "0", "0", "0", "cv_flovilla_13", "0", "0"},
[422016] = {422016, 12020, 17, 11, "0", "0", "嘿嘿，這就是旅行的成果。", "0", "0", "0", "0", "0", "cv_flovilla_14", "0", "0"},
[422017] = {422017, 12020, 18, 12, "0", "0", "一定是沒吃飽的原因！", "0", "0", "0", "0", "0", "cv_flovilla_15", "0", "0"},
