[422106] = {422106, 12021, 7, 5, "1_》_0_0.8", "level1", "此番造訪，是為何事？", "0", "0", "0", "0", "0", "cv_shaoyin_7", "0", "0"},
[422107] = {422107, 12021, 8, 5, "1_》_0_0.8", "level1", "既得領航委命，小女子自會事無巨細，事必躬親。", "0", "0", "0", "0", "0", "cv_shaoyin_8", "0", "0"},
[422108] = {422108, 12021, 9, 5, "1_》_100_1.5", "level2", "無需拘謹。既然好奇，多摸一會兒又何妨？小女子——不，是我。我很開心哦。倒不如說，僅靠一對鹿角就能與領航這般親昵，未免也太走運了吧我？！", "0", "0", "0", "0", "0", "cv_shaoyin_9", "0", "0"},
[422109] = {422109, 12021, 10, 5, "1_》_500_2", "level3", "要來聊天嗎？好呀。我等這一刻已經很久了，有很多很多話想跟領航您說呢。", "0", "0", "0", "0", "0", "cv_shaoyin_10", "0", "0"},
[422110] = {422110, 12021, 11, 5, "1_》_1000_2.5", "level4", "所以說，再多陪陪我有什麼不好的？最近領航您不是和其他駕駛員去出任務，就是在指揮室裡待著，一天下來都見不了幾面……我、我也是會寂寞的，不要留我一個人在這裡呐……", "0", "0", "0", "0", "0", "cv_shaoyin_11", "0", "0"},
[422111] = {422111, 12021, 12, 6, "0", "0", "善矣。", "0", "0", "0", "0", "0", "cv_shaoyin_12", "0", "0"},
[422112] = {422112, 12021, 13, 7, "0", "0", "此般垂青，定不辜負。", "0", "0", "0", "0", "0", "cv_shaoyin_13", "0", "0"},
[422113] = {422113, 12021, 14, 8, "0", "0", "……領航，誇誇我好嗎？", "0", "0", "0", "0", "0", "cv_shaoyin_14", "0", "0"},
[422114] = {422114, 12021, 15, 9, "0", "0", "利器，然工事。", "0", "0", "0", "0", "0", "cv_shaoyin_15", "0", "0"},
[422115] = {422115, 12021, 16, 10, "0", "0", "明瞭。", "0", "0", "0", "0", "0", "cv_shaoyin_16", "0", "0"},
[422116] = {422116, 12021, 17, 11, "0", "0", "敬賀領航大獲全勝。", "0", "0", "0", "0", "0", "cv_shaoyin_17", "0", "0"},
[422117] = {422117, 12021, 18, 12, "0", "0", "無需失落，略有瑕疵而已。", "0", "0", "0", "0", "0", "cv_shaoyin_18", "0", "0"},
[422118] = {422118, 12021, 19, 13, "0", "0", "……是以領航更勝一籌，應當高興。", "0", "0", "0", "0", "0", "cv_shaoyin_19", "0", "0"},
[422119] = {422119, 12021, 20, 14, "0", "0", "怎麼會這樣？等等，先讓我複盤一下，看問題究竟出在那裡……", "0", "0", "0", "0", "0", "cv_shaoyin_20", "0", "0"},
[422120] = {422120, 12021, 21, 15, "0", "0", "後會無期。", "0", "0", "0", "0", "0", "cv_shaoyin_21", "0", "0"},
[422121] = {422121, 12021, 23, 16, "0", "0", "落。", "0", "0", "0", "0", "0", "cv_shaoyin_23", "0", "0"},
[422122] = {422122, 12021, 24, 17, "0", "0", "斬草需除根。", "0", "0", "0", "0", "0", "cv_shaoyin_24", "0", "0"},
[422123] = {422123, 12021, 25, 18, "0", "0", "謀事在人，成事在天。", "0", "0", "0", "0", "0", "cv_shaoyin_25", "0", "0"},
[422124] = {422124, 12021, 22, 38, "0", "0", "正如小女子所料。", "0", "0", "0", "0", "0", "cv_shaoyin_22", "0", "0"},
[422125] = {422125, 12021, 26, 19, "0", "0", "失罪于此，乞蒙見恕。", "0", "0", "0", "0", "0", "cv_shaoyin_26", "0", "0"},
[422126] = {422126, 12021, 27, 20, "0", "0", "連這裡也有您相伴呀。", "0", "0", "0", "0", "0", "cv_shaoyin_27", "0", "0"},
[422127] = {422127, 12021, 28, 21, "0", "0", "欲速則不達。", "0", "0", "0", "0", "0", "cv_shaoyin_28", "0", "0"},
[422128] = {422128, 12021, 29, 21, "0", "0", "……所以說慢慢來嘛。和我在這裡多呆一會兒不好嗎？", "0", "0", "0", "0", "0", "cv_shaoyin_29", "0", "0"},
[422129] = {422129, 12021, 30, 22, "0", "0", "原來這裡還設有小遊戲呀。", "0", "0", "0", "0", "0", "cv_shaoyin_30", "0", "0"},
[422130] = {422130, 12021, 31, 23, "0", "0", "是小女子哦。可千萬要猜對哦。", "0", "0", "0", "0", "0", "cv_shaoyin_31", "0", "0"},
[422131] = {422131, 12021, 32, 24, "0", "0", "太好啦！", "0", "0", "0", "0", "0", "cv_shaoyin_32", "0", "0"},
[422132] = {422132, 12021, 33, 25, "0", "0", "……我沒有生氣。", "0", "0", "0", "0", "0", "cv_shaoyin_33", "0", "0"},
[422133] = {422133, 12021, 34, 26, "0", "0", "什麼嘛，又只剩我一個人——咿呀？！領、領航，您回來呐……咳，小女子方才什麼都沒說，您也什麼都沒聽見。", "0", "0", "0", "0", "0", "cv_shaoyin_34", "0", "0"},
[422134] = {422134, 12021, 35, 27, "0", "0", "望諸事順遂。", "0", "0", "0", "0", "0", "cv_shaoyin_35", "0", "0"},
[422135] = {422135, 12021, 36, 28, "0", "0", "願旗開得勝。", "0", "0", "0", "0", "0", "cv_shaoyin_36", "0", "0"},
[422136] = {422136, 12021, 37, 29, "0", "0", "領航認識的駕駛員可真多啊……", "0", "0", "0", "0", "0", "cv_shaoyin_37", "0", "0"},
[422137] = {422137, 12021, 38, 30, "0", "0", "此般仁人志士……等等，該不會是準備把我換掉了吧？", "0", "0", "0", "0", "0", "cv_shaoyin_38", "0", "0"},
[422138] = {422138, 12021, 39, 31, "0", "0", "人形錦鯉的傳言，您已知曉了呀……", "0", "0", "0", "0", "0", "cv_shaoyin_39", "0", "0"},
[422139] = {422139, 12021, 40, 32, "0", "0", "欲易何物？", "0", "0", "0", "0", "0", "cv_shaoyin_40", "0", "0"},
[422140] = {422140, 12021, 41, 33, "0", "0", "哼哼，領航的助理是我呢~", "0", "0", "0", "0", "0", "cv_shaoyin_41", "0", "0"},
[422141] = {422141, 12021, 42, 34, "0", "0", "難道是我話太多了，領航決定要靜我的音？", "0", "0", "0", "0", "0", "cv_shaoyin_42", "0", "0"},
[422142] = {422142, 12021, 43, 35, "0", "0", "要不然我也寫封信寄給領航吧？", "0", "0", "0", "0", "0", "cv_shaoyin_43", "0", "0"},
[422143] = {422143, 12021, 44, 36, "0", "0", "……不要總是和別人聊啦。", "0", "0", "0", "0", "0", "cv_shaoyin_44", "0", "0"},
[422144] = {422144, 12021, 45, 37, "0", "0", "凡事皆應謹言慎——您已經按下去了？！", "0", "0", "0", "0", "0", "cv_shaoyin_45", "0", "0"},
[422200] = {422200, 12022, 1, 1, "0", "0", "蒼霧殘響~", "0", "0", "0", "0", "0", "cv_laipani_34", "0", "0"},
[422201] = {422201, 12022, 2, 2, "0", "0", "領航，現在可是工作的時間，就在這哪裡都不要去哦。", "0", "0", "0", "0", "0", "cv_laipani_2", "0", "0"},
[422202] = {422202, 12022, 3, 3, "0", "0", "初次見面，我是萊帕尼，偵查小隊“鐵鴉”的隊長。之後很長一段時間都要請您指教了，領航。", "0", "0", "0", "0", "0", "cv_laipani_1", "0", "0"},
[422203] = {422203, 12022, 4, 4, "0", "idle", "領航，您看上去睡眠不足的樣子，要休息一下嗎？曠工的懲罰可以先記在本子上。", "0", "0", "0", "0", "0", "cv_laipani_3", "0", "0"},
[422204] = {422204, 12022, 5, 4, "0", "idle", "“鐵鴉”是一隻讓我引以為豪的隊伍。所以，我也希望領航您能夠信任我們，把重要的任務託付給我們。", "0", "0", "0", "0", "0", "cv_laipani_4", "0", "0"},
[422205] = {422205, 12022, 6, 4, "0", "idle", "執行任務的時候，如果洛洛不在身邊的話，我可能哪裡都去不了。真的多虧有她在了。", "0", "0", "0", "0", "0", "cv_laipani_31", "0", "0"},
[422206] = {422206, 12022, 7, 5, "1_》_0_0.8", "level1", "戰爭中，一定有很多像我一樣和父母走散了的孩子……那樣的事實在是太不合理了……您不這麼認為嗎？", "0", "0", "0", "0", "0", "cv_laipani_32", "0", "0"},
[422207] = {422207, 12022, 8, 5, "1_》_0_0.8", "level1", "領航，您是想讓我握住您的手嗎？嗯……是不是太小了點？", "0", "0", "0", "0", "0", "cv_laipani_5", "0", "0"},
[422208] = {422208, 12022, 9, 5, "1_》_100_1.5", "level2", "領航，您最近如果失眠的話，我可以幫你噢。我這邊有許多類型的安眠藥，一定能讓您睡個好覺的。", "0", "0", "0", "0", "0", "cv_laipani_6", "0", "0"},
[422209] = {422209, 12022, 10, 5, "1_》_500_2", "level3", "領航，雖然我是路癡，但我可是“鐵鴉”的隊長噢！不管您身處何地，只要您呼喚了我，我一定能找到您的！", "0", "0", "0", "0", "0", "cv_laipani_7", "0", "0"},
[422210] = {422210, 12022, 11, 5, "1_》_1000_2.5", "level4", "領航，能請您帶上這根鏈子嗎……“捆綁”？啊，不是的。我只是希望我們從此之後都不會分開，不會走散而已……不行……嗎？", "0", "0", "0", "0", "0", "cv_laipani_8", "0", "0"},
[422211] = {422211, 12022, 12, 6, "0", "0", "謝謝。", "0", "0", "0", "0", "0", "cv_laipani_9", "0", "0"},
[422212] = {422212, 12022, 13, 7, "0", "0", "要想想該怎麼回報您才行~", "0", "0", "0", "0", "0", "cv_laipani_10", "0", "0"},
[422213] = {422213, 12022, 14, 8, "0", "0", "能被您如此重視，我真的感到很幸福，領航。在這之後，我們也要一直在一起，不要，也不能分開噢。", "0", "0", "0", "0", "0", "cv_laipani_11", "0", "0"},
[422214] = {422214, 12022, 15, 9, "0", "0", "更想要識路的技能呀……", "0", "0", "0", "0", "0", "cv_laipani_12", "0", "0"},
[422215] = {422215, 12022, 16, 10, "0", "0", "討人厭的原罪在哪呢？", "0", "0", "0", "0", "0", "cv_laipani_13", "0", "0"},
[422216] = {422216, 12022, 17, 11, "0", "0", "這都是大家的功勞。", "0", "0", "0", "0", "0", "cv_laipani_14", "0", "0"},
[422217] = {422217, 12022, 18, 12, "0", "0", "我們一起反省吧，領航。", "0", "0", "0", "0", "0", "cv_laipani_15", "0", "0"},
[422218] = {422218, 12022, 19, 13, "0", "0", "千鈞一髮，真危險啊……", "0", "0", "0", "0", "0", "cv_laipani_16", "0", "0"},
[422219] = {422219, 12022, 20, 14, "0", "0", "撤退……大家，別走散了！", "0", "0", "0", "0", "0", "cv_laipani_17", "0", "0"},
[422220] = {422220, 12022, 21, 15, "0", "0", "下一位是誰呢？", "0", "0", "0", "0", "0", "cv_laipani_18", "0", "0"},
[422221] = {422221, 12022, 23, 16, "0", "0", "發射！", "0", "0", "0", "0", "0", "cv_laipani_20", "0", "0"},
[422222] = {422222, 12022, 24, 17, "0", "0", "永不復還！", "0", "0", "0", "0", "0", "cv_laipani_22", "0", "0"},
[422223] = {422223, 12022, 25, 18, "0", "0", "我宣佈，捉迷藏遊戲結束了。", "0", "0", "0", "0", "0", "cv_laipani_23", "0", "0"},
[422224] = {422224, 12022, 22, 38, "0", "0", "要來了噢。", "0", "0", "0", "0", "0", "cv_laipani_19", "0", "0"},
[422225] = {422225, 12022, 26, 19, "0", "0", "要找到我噢，領航……", "0", "0", "0", "0", "0", "cv_laipani_21", "0", "0"},
[422226] = {422226, 12022, 27, 20, "0", "0", "領航，果然是您來了。您的腳步聲，我已經完全記住了呢。", "0", "0", "0", "0", "0", "cv_laipani_24", "0", "0"},
[422227] = {422227, 12022, 28, 21, "0", "0", "呼……好危險。剛剛差點把領航當做蚊子拍下去了~", "0", "0", "0", "0", "0", "cv_laipani_25", "0", "0"},
[422228] = {422228, 12022, 29, 21, "0", "0", "領航的視線……感覺癢癢的。", "0", "0", "0", "0", "0", "cv_laipani_26", "0", "0"},
[422229] = {422229, 12022, 30, 22, "0", "0", "嗯？", "0", "0", "0", "0", "0", "cv_laipani_27", "0", "0"},
[422230] = {422230, 12022, 31, 23, "0", "0", "請放心，即使錯了也沒有關係的。", "0", "0", "0", "0", "0", "cv_laipani_28", "0", "0"},
[422231] = {422231, 12022, 32, 24, "0", "0", "謝謝您找到了我，領航。", "0", "0", "0", "0", "0", "cv_laipani_29", "0", "0"},
[422232] = {422232, 12022, 33, 25, "0", "0", "為了不重蹈覆轍，請您聽我的錄音一萬遍，好嗎？", "0", "0", "0", "0", "0", "cv_laipani_30", "0", "0"},
[422233] = {422233, 12022, 34, 26, "0", "0", "領航，歡迎回來，您安排好今天的行程了嗎？", "0", "0", "0", "0", "0", "cv_laipani_33", "0", "0"},
[422234] = {422234, 12022, 35, 27, "0", "0", "放著我不管的話，我會迷路的。", "0", "0", "0", "0", "0", "cv_laipani_35", "0", "0"},
[422235] = {422235, 12022, 36, 28, "0", "0", "我們攜手前進吧，領航。", "0", "0", "0", "0", "0", "cv_laipani_36", "0", "0"},
[422236] = {422236, 12022, 37, 29, "0", "0", "大家看起來都很健康呢。", "0", "0", "0", "0", "0", "cv_laipani_37", "0", "0"},
[422237] = {422237, 12022, 38, 30, "0", "0", "我來為新人引路吧。", "0", "0", "0", "0", "0", "cv_laipani_38", "0", "0"},
[422238] = {422238, 12022, 39, 31, "0", "0", "不能太沉迷噢。", "0", "0", "0", "0", "0", "cv_laipani_39", "0", "0"},
[422239] = {422239, 12022, 40, 32, "0", "0", "嗯……全買了吧？", "0", "0", "0", "0", "0", "cv_laipani_40", "0", "0"},
[422240] = {422240, 12022, 41, 33, "0", "0", "要記得管理好自己的檔案噢。", "0", "0", "0", "0", "0", "cv_laipani_41", "0", "0"},
[422241] = {422241, 12022, 42, 34, "0", "0", "要細心設置呢。", "0", "0", "0", "0", "0", "cv_laipani_42", "0", "0"},
[422242] = {422242, 12022, 43, 35, "0", "0", "不許和可疑的人來往。", "0", "0", "0", "0", "0", "cv_laipani_43", "0", "0"},
[422243] = {422243, 12022, 44, 36, "0", "0", "有可疑的人要告訴我~", "0", "0", "0", "0", "0", "cv_laipani_44", "0", "0"},
[422244] = {422244, 12022, 45, 37, "0", "0", "小心觸電。", "0", "0", "0", "0", "0", "cv_laipani_45", "0", "0"},
[422300] = {422300, 12023, 1, 1, "0", "0", "蒼霧殘響", "0", "0", "0", "0", "0", "cv_stella_1", "0", "0"},
[422301] = {422301, 12023, 2, 2, "0", "0", "薩哈拉蒼穹學院的……軍事戰略學與狙擊老師，斯緹菈報到。我會守護好學生們的背影，以及……領航您的期望。", "0", "0", "0", "0", "0", "cv_stella_3", "0", "0"},
[422302] = {422302, 12023, 3, 3, "0", "0", "誒？安排我在此就位？嗯……我相信領航的判斷。", "0", "0", "0", "0", "0", "cv_stella_2", "0", "0"},
[422303] = {422303, 12023, 4, 4, "0", "idle", "也許難以通過肉眼望見，但就在此時，星星們也一刻不停地轉動著。", "0", "0", "0", "0", "0", "cv_stella_4", "0", "0"},
[422304] = {422304, 12023, 5, 4, "0", "idle", "對狙擊手而言，最重要的不是視力或技巧，而是耐心……耐心，多麼冷酷的一種能力。", "0", "0", "0", "0", "0", "cv_stella_5", "0", "0"},
[422305] = {422305, 12023, 6, 4, "0", "idle", "梅貝爾老師曾對我說，像這種單調的工作可以不用那麼認真，但……我還是想彌補過去的失職。", "0", "0", "0", "0", "0", "cv_stella_6", "0", "0"},
[422306] = {422306, 12023, 7, 5, "1_》_0_0.8", "level1", "雖是為戰爭而生的器材，這副狙擊鏡同樣能用於遙望星星……關於這點，我一度險些遺忘了。", "0", "0", "0", "0", "0", "cv_stella_7", "0", "0"},
[422307] = {422307, 12023, 8, 5, "1_》_0_0.8", "level1", "突、突然間有什麼事嗎？如果我有哪裡做得不好，還請領航指導……", "0", "0", "0", "0", "0", "cv_stella_8", "0", "0"},
[422308] = {422308, 12023, 9, 5, "1_》_100_1.5", "level2", "您說這身裝束看著有些厚實？唔……在高處待命時，它能為我遮風禦寒，所以我已經習慣了這份重量。", "0", "0", "0", "0", "0", "cv_stella_9", "0", "0"},
[422309] = {422309, 12023, 10, 5, "1_》_500_2", "level3", "雲與月輕聲告訴我：今晚的夜空會格外晴朗。等工作結束後，領、領航要一起去看星星嗎？", "0", "0", "0", "0", "0", "cv_stella_10", "0", "0"},
[422310] = {422310, 12023, 11, 5, "1_》_1000_2.5", "level4", "戰場上隊友的身影，夜空中浩繁的遠星，再怎樣調整倍率也都可望而不可即……只有這份熟悉的觸感讓人慶幸……我的身旁還有您。", "0", "0", "0", "0", "0", "cv_stella_11", "0", "0"},
[422311] = {422311, 12023, 12, 6, "0", "0", "離目標更近了嗎……？", "0", "0", "0", "0", "0", "cv_stella_12", "0", "0"},
[422312] = {422312, 12023, 13, 7, "0", "0", "又是一顆閃閃發亮的星。", "0", "0", "0", "0", "0", "cv_stella_13", "0", "0"},
[422313] = {422313, 12023, 14, 8, "0", "0", "星光瞬息萬裏，能輕易飛往子彈也無力觸及之地……希望我也可以這樣，無論身在何方，都能指引學生，成為她們的榜樣。", "0", "0", "0", "0", "0", "cv_stella_14", "0", "0"},
[422314] = {422314, 12023, 15, 9, "0", "0", "為了學生們……我也要不斷學習。", "0", "0", "0", "0", "0", "cv_stella_15", "0", "0"},
[422315] = {422315, 12023, 16, 10, "0", "0", "可以……與大家並肩作戰嗎？", "0", "0", "0", "0", "0", "cv_stella_16", "0", "0"},
[422316] = {422316, 12023, 17, 11, "0", "0", "任務圓滿完成的當晚，星空總是會比以往更美。", "0", "0", "0", "0", "0", "cv_stella_17", "0", "0"},
[422317] = {422317, 12023, 18, 12, "0", "0", "還好這次沒出現太大損傷……", "0", "0", "0", "0", "0", "cv_stella_18", "0", "0"},
[422318] = {422318, 12023, 19, 13, "0", "0", "都是我的錯，沒能把握好大家創造的機會……", "0", "0", "0", "0", "0", "cv_stella_19", "0", "0"},
[422319] = {422319, 12023, 20, 14, "0", "0", "我……真的能勝任要職嗎？", "0", "0", "0", "0", "0", "cv_stella_20", "0", "0"},
[422320] = {422320, 12023, 21, 15, "0", "0", "如流星般隕落。", "0", "0", "0", "0", "0", "cv_stella_21", "0", "0"},
[422321] = {422321, 12023, 23, 16, "0", "0", "請一定……", "0", "0", "0", "0", "0", "cv_stella_22", "0", "0"},
[422322] = {422322, 12023, 24, 17, "0", "0", "閃爍吧。", "0", "0", "0", "0", "0", "cv_stella_23", "0", "0"},
[422323] = {422323, 12023, 22, 38, "0", "0", "調整呼吸。", "0", "0", "0", "0", "0", "cv_stella_24", "0", "0"},
[422324] = {422324, 12023, 26, 19, "0", "0", "如果能為大家分擔火力……", "0", "0", "0", "0", "0", "cv_stella_25", "0", "0"},
[422325] = {422325, 12023, 27, 20, "0", "0", "那個……拜託您了？", "0", "0", "0", "0", "0", "cv_stella_26", "0", "0"},
[422326] = {422326, 12023, 28, 21, "0", "0", "等待……等待，似乎一直都是這樣，嗯，我會等下去的。", "0", "0", "0", "0", "0", "cv_stella_27", "0", "0"},
[422327] = {422327, 12023, 29, 21, "0", "0", "以前想逃避什麼的時候，我就會像這樣，在浴室裡靜靜發呆。", "0", "0", "0", "0", "0", "cv_stella_28", "0", "0"},
[422328] = {422328, 12023, 30, 22, "0", "0", "這、這是……？", "0", "0", "0", "0", "0", "cv_stella_29", "0", "0"},
[422329] = {422329, 12023, 31, 23, "0", "0", "小時候，我也會對著天空猜星星的名字。", "0", "0", "0", "0", "0", "cv_stella_30", "0", "0"},
[422330] = {422330, 12023, 32, 24, "0", "0", "您對我如此熟悉，我、我很開心。", "0", "0", "0", "0", "0", "cv_stella_31", "0", "0"},
[422331] = {422331, 12023, 33, 25, "0", "0", "嗯……狙擊手不太起眼，或許也是件好事呢……", "0", "0", "0", "0", "0", "cv_stella_32", "0", "0"},
[422332] = {422332, 12023, 34, 26, "0", "0", "您回來了……今天有什麼安排嗎？", "0", "0", "0", "0", "0", "cv_stella_33", "0", "0"},
[422333] = {422333, 12023, 35, 27, "0", "0", "這次，我不會再猶豫了。", "0", "0", "0", "0", "0", "cv_stella_34", "0", "0"},
[422334] = {422334, 12023, 36, 28, "0", "0", "只是演習的話，沒問題。", "0", "0", "0", "0", "0", "cv_stella_35", "0", "0"},
[422335] = {422335, 12023, 37, 29, "0", "0", "唔……夥伴很多呢。", "0", "0", "0", "0", "0", "cv_stella_36", "0", "0"},
[422336] = {422336, 12023, 38, 30, "0", "0", "回想起我剛來這裡的時候了。", "0", "0", "0", "0", "0", "cv_stella_37", "0", "0"},
[422337] = {422337, 12023, 39, 31, "0", "0", "希望能幫到大家。", "0", "0", "0", "0", "0", "cv_stella_38", "0", "0"},
[422338] = {422338, 12023, 40, 32, "0", "0", "既然是購物，就開心些吧……", "0", "0", "0", "0", "0", "cv_stella_39", "0", "0"},
[422339] = {422339, 12023, 41, 33, "0", "0", "領、領航的資料嗎……", "0", "0", "0", "0", "0", "cv_stella_40", "0", "0"},
[422340] = {422340, 12023, 42, 34, "0", "0", "作戰前要好好校準呢。", "0", "0", "0", "0", "0", "cv_stella_41", "0", "0"},
[422341] = {422341, 12023, 43, 35, "0", "0", "來自遠方的思念。", "0", "0", "0", "0", "0", "cv_stella_42", "0", "0"},
[422342] = {422342, 12023, 44, 36, "0", "0", "簡直就像漫天星光，彼此輝映。", "0", "0", "0", "0", "0", "cv_stella_43", "0", "0"},
[422343] = {422343, 12023, 45, 37, "0", "0", "不太明白呢……", "0", "0", "0", "0", "0", "cv_stella_44", "0", "0"},
[422400] = {422400, 12024, 1, 1, "0", "0", "蒼霧殘響！", "ハツリバーブ！", "0", "0", "0", "0", "cv_fulanka_sw_1", "0", "0"},
[422401] = {422401, 12024, 2, 2, "0", "0", "嗯……我想坐領航身邊的位置可以嗎？", "あの……ナビゲーターさんのとなりに座ってもいいですか？", "0", "0", "0", "0", "cv_fulanka_sw_2", "0", "0"},
[422402] = {422402, 12024, 3, 3, "0", "0", "我等了您很久了……嘿嘿，我一直想像著再一次和領航遇見會是怎樣的場景……沒想到是這樣子在夢中見面呢。", "ずっと待ってたんですよ……えへへ、ナビゲーターさんとまた會える日をいつも想像してたんですが……こんな風に夢で會うとは思いませんでした。", "0", "0", "0", "0", "cv_fulanka_sw_3", "0", "0"},
[422403] = {422403, 12024, 4, 4, "0", "idle", "我一直都相信著會有再見到領航的這一天……現在我的願望實現了，嘿嘿，真是太好了。", "ナビゲーターさんとまた會える日が必ず來るって信じてました……願いが葉っちゃいましたね。えへへ。とっても嬉しいです。", "0", "0", "0", "0", "cv_fulanka_sw_4", "0", "0"},
[422404] = {422404, 12024, 5, 4, "0", "idle", "如果領航你還有以前的記憶就好了……不過沒有關係，即使您已經忘掉了我……", "ナビゲーターさんに以前の記憶があれば良かったんですが……でも構いません。私のことを忘れてしまっていたとしても……", "0", "0", "0", "0", "cv_fulanka_sw_5", "0", "0"},
[422405] = {422405, 12024, 6, 4, "0", "idle", "對於“我”而言，現在與您渡過的每一天都是與幸福的相遇之日，這一定是對我堅持與等待的獎勵。", "私、ナビゲーターさんと過ごすこの毎日がとても幸せです。きっと、辛抱強く待ち続けたご褒美ですよね。", "0", "0", "0", "0", "cv_fulanka_sw_6", "0", "0"},
[422406] = {422406, 12024, 7, 5, "1_》_0_0.8", "level1", "為了慶祝風平浪靜的這一天，今天晚上我們要不要稍微放縱一下？", "平穏な一日を祝って、今晩はちょっとだけ贅沢しちゃいませんか？", "0", "0", "0", "0", "cv_fulanka_sw_7", "0", "0"},
[422407] = {422407, 12024, 8, 5, "1_》_0_0.8", "level1", "我變得特別愛黏在領航的身邊了？嘿嘿……", "私、ナビゲーターさんにべったりしすぎでしょうか？えへへ……", "0", "0", "0", "0", "cv_fulanka_sw_8", "0", "0"},
[422408] = {422408, 12024, 9, 5, "1_》_100_1.5", "level2", "我想主世界的“我”一定和我是心意相通……所以我想把一些話留給她講。", "メイン世界の私とは、きっと心が通じ合っていますから……思い出を殘してあげたいんです。", "0", "0", "0", "0", "cv_fulanka_sw_9", "0", "0"},
[422409] = {422409, 12024, 10, 5, "1_》_500_2", "level3", "早晚有一天我會去找您的，您為“我”保留下的這份記憶與我對您的愛意，終將有歸巢的一日。", "いつの日かナビゲーターさんに會いに行きます。私のために殘してくれたこの記憶と、ナビゲーターさんへの愛情が、元の場所へと戻るように……", "0", "0", "0", "0", "cv_fulanka_sw_10", "0", "0"},
[422410] = {422410, 12024, 11, 5, "1_》_1000_2.5", "level4", "您只要記住“我愛慕著您”，這就足夠了，這就是我的心意，現在的我能傳達到這一點就已經滿足了。", "私がナビゲーターさんを想っていたこと……それさえ覚えていてもらえれば、十分です。私の気持ちを伝えられただけで、今は満足ですから。", "0", "0", "0", "0", "cv_fulanka_sw_11", "0", "0"},
[422411] = {422411, 12024, 12, 6, "0", "0", "嗯。我們一起再加把勁吧。", "はい。一緒にもっとがんばりましょう。", "0", "0", "0", "0", "cv_fulanka_sw_12", "0", "0"},
[422412] = {422412, 12024, 13, 7, "0", "0", "這就是我和領航一起努力的成果。", "私とナビゲーターさんの努力の賜物ですね。", "0", "0", "0", "0", "cv_fulanka_sw_13", "0", "0"},
[422413] = {422413, 12024, 14, 8, "0", "0", "在我的身體內……能感受到領航的力量呢，無論多少次都覺得不可思議呢……", "體の中に……ナビゲーターさんの力を感じます。何度経験しても不思議な感覚ですね……", "0", "0", "0", "0", "cv_fulanka_sw_14", "0", "0"},
[422414] = {422414, 12024, 15, 9, "0", "0", "握住我的手吧。", "私の手を握っていてくださいね。", "0", "0", "0", "0", "cv_fulanka_sw_15", "0", "0"},
[422415] = {422415, 12024, 16, 10, "0", "0", "再一次……我會保護好領航的！", "今度も……ナビゲーターさんを守ります！", "0", "0", "0", "0", "cv_fulanka_sw_16", "0", "0"},
[422416] = {422416, 12024, 17, 11, "0", "0", "這樣的感受，真是懷念。", "この感覚、本當に懐かしいです。", "0", "0", "0", "0", "cv_fulanka_sw_17", "0", "0"},
[422417] = {422417, 12024, 18, 12, "0", "0", "嘿嘿，慢慢來吧。", "えへへ、まぁまぁですね。", "0", "0", "0", "0", "cv_fulanka_sw_18", "0", "0"},
[422418] = {422418, 12024, 19, 13, "0", "0", "再加把勁的話……", "もう少しがんばれば……", "0", "0", "0", "0", "cv_fulanka_sw_19", "0", "0"},
[422419] = {422419, 12024, 20, 14, "0", "0", "準備撤退了，跟我來吧。", "撤退の準備ができました、こちらへ！", "0", "0", "0", "0", "cv_fulanka_sw_20", "0", "0"},
[422420] = {422420, 12024, 21, 15, "0", "0", "消失吧。", "消えてください。", "0", "0", "0", "0", "cv_fulanka_sw_21", "0", "0"},
[422421] = {422421, 12024, 23, 16, "0", "0", "哈！", "はぁっ！", "0", "0", "0", "0", "cv_fulanka_sw_23", "0", "0"},
[422422] = {422422, 12024, 24, 17, "0", "0", "呀！", "やぁっ！", "0", "0", "0", "0", "cv_fulanka_sw_24", "0", "0"},
[422423] = {422423, 12024, 22, 38, "0", "0", "嗯——", "うぅぅぅん……", "0", "0", "0", "0", "cv_fulanka_sw_22", "0", "0"},
[422424] = {422424, 12024, 26, 19, "0", "0", "我……還會再回來的。", "また……戻って來ます。", "0", "0", "0", "0", "cv_fulanka_sw_26", "0", "0"},
[422425] = {422425, 12024, 27, 20, "0", "0", "到洗澡的時間了呢，領航要和我一起嗎？", "お風呂の時間ですね。ナビゲーターさん、一緒に入りますか？", "0", "0", "0", "0", "cv_fulanka_sw_27", "0", "0"},
[422426] = {422426, 12024, 28, 21, "0", "0", "洗完澡之後就是晚安的時間了呢。不過我想……在夢中說晚安未免也太奇怪了。", "お風呂が済んだらおやすみの時間ですね。でも……夢の中でおやすみっていうのもなんか変ですが。", "0", "0", "0", "0", "cv_fulanka_sw_28", "0", "0"},
[422427] = {422427, 12024, 29, 21, "0", "0", "我們之所以出現在女主角宇宙裡就是為了我們的未來，同理，我出現在這裡肯定是為了我的未來……對嗎？", "私達がヒロインバースに現れたのは、私達の未來のためです。同じように、私がここに現れたのは私の未來のため……ではないでしょうか？", "0", "0", "0", "0", "cv_fulanka_sw_29", "0", "0"},
[422428] = {422428, 12024, 30, 22, "0", "0", "呵呵，果然大家還是這樣的氛圍，都喜歡在洗澡的時候戲弄領航呢。", "ふふ、やっぱりこうなりますよね。みんなお風呂の時にナビゲーターさんをからかうのが好きですから。", "0", "0", "0", "0", "cv_fulanka_sw_30", "0", "0"},
[422429] = {422429, 12024, 31, 23, "0", "0", "要到結束的時間了嗎，好快！我還沒和領航待夠。", "もう終わりですか、あっという間ですね！もっとナビゲーターさんと一緒にいたいのに。", "0", "0", "0", "0", "cv_fulanka_sw_31", "0", "0"},
[422430] = {422430, 12024, 32, 24, "0", "0", "接受我的一切吧。", "私の全てを受け取ってくださいね。", "0", "0", "0", "0", "cv_fulanka_sw_32", "0", "0"},
[422431] = {422431, 12024, 33, 25, "0", "0", "選錯了！？怎麼會——！", "間違えたんですか！？そんなぁ！", "0", "0", "0", "0", "cv_fulanka_sw_33", "0", "0"},
[422432] = {422432, 12024, 34, 26, "0", "0", "領航……今天的您也可以在我的夢中想待多久就待多久哦。", "ナビゲーターさん……今日も好きなだけ、私の夢の中にいてくださいね。", "0", "0", "0", "0", "cv_fulanka_sw_34", "0", "0"},
[422433] = {422433, 12024, 35, 27, "0", "0", "誒……在夢中也要戰鬥嗎？", "えっ……夢の中でも戦うんですか？", "0", "0", "0", "0", "cv_fulanka_sw_35", "0", "0"},
[422434] = {422434, 12024, 36, 28, "0", "0", "是不是有點太努力了？不要緊嗎？", "がんばり過ぎじゃないですか？大丈夫ですか？", "0", "0", "0", "0", "cv_fulanka_sw_36", "0", "0"},
[422435] = {422435, 12024, 37, 29, "0", "0", "要和大家一起在夢中做些什麼呢……", "みんなと夢の中で何をしましょうか……", "0", "0", "0", "0", "cv_fulanka_sw_37", "0", "0"},
[422436] = {422436, 12024, 38, 30, "0", "0", "想邀請誰一起來夢中相見嗎……但是我還是想和領航兩個人在一起。", "誰を夢の中に招待したいか、ですか……私はやっぱり、ナビゲーターさんと一緒がいいです。", "0", "0", "0", "0", "cv_fulanka_sw_38", "0", "0"},
[422437] = {422437, 12024, 39, 31, "0", "0", "未來科技！夢中的裝備！", "ハイテクですね！夢のような裝備です！", "0", "0", "0", "0", "cv_fulanka_sw_39", "0", "0"},
[422438] = {422438, 12024, 40, 32, "0", "0", "來……這裡是商店。", "さあ、ここがお店ですよ。", "0", "0", "0", "0", "cv_fulanka_sw_40", "0", "0"},
[422439] = {422439, 12024, 41, 33, "0", "0", "啊，是好早之前的檔案。", "隨分前のデータですね。", "0", "0", "0", "0", "cv_fulanka_sw_41", "0", "0"},
[422440] = {422440, 12024, 42, 34, "0", "0", "要改變點什麼嗎？", "何か変更しますか？", "0", "0", "0", "0", "cv_fulanka_sw_42", "0", "0"},
[422441] = {422441, 12024, 43, 35, "0", "0", "嗯……也許在夢裡放著郵件不動的話，郵件會自己增殖也說不定。", "う～ん……夢の中にメールを置いたままにすると、勝手に増えちゃうかも知れませんよ。", "0", "0", "0", "0", "cv_fulanka_sw_43", "0", "0"},
[422442] = {422442, 12024, 44, 36, "0", "0", "大家會說什麼樣的夢話呢……", "みんな一體どんな寢言を話してるんでしょうか……", "0", "0", "0", "0", "cv_fulanka_sw_44", "0", "0"},
[422443] = {422443, 12024, 45, 37, "0", "0", "這是？", "これは？", "0", "0", "0", "0", "cv_fulanka_sw_45", "0", "0"},
[422500] = {422500, 12025, 1, 1, "0", "0", "蒼霧殘響", "ハツリバーブ", "0", "0", "0", "0", "cv_feilin_1", "0", "0"},
[422501] = {422501, 12025, 2, 2, "0", "0", "要當領航的貼身護衛嗎？我嗎？深呼吸，要深呼吸才行——嘶——呼——好危險，差點缺氧窒息了……我會加油的！", "ナビゲーターさんのボディガードを務めるのは私ですか？深呼吸、深呼吸しなければ——すぅ——はぁ——危なかった、息が切れそうになった……頑張ります！", "0", "0", "0", "0", "cv_feilin_2", "0", "0"},
[422502] = {422502, 12025, 3, 3, "0", "0", "在想自己還適不適合當駕駛員的時候，就不自覺走到這了。請允許我再一次自我介紹，領航，我叫菲琳·布蘭妮，是一名駕駛員。", "自分がまだドライバーに向いているかどうか考えていたら、いつの間にかここに来てしまいました。もう一度自己紹介させてください、ナビゲーターさん。私はフェリン・ブリトニー、ドライバーです。", "0", "0", "0", "0", "cv_feilin_3", "0", "0"},
[422503] = {422503, 12025, 4, 4, "0", "idle", "無論是負責後勤的支援人員，還是前線戰鬥的駕駛員，對於艾吉斯來說都是不可或缺的。這應該是我半年來學到的最寶貴的東西。", "後方支援のスタッフも、前線で戦うドライバーも、アイギスには欠かせない存在です。これがこの半年で学んだ最も貴重なことです。", "0", "0", "0", "0", "cv_feilin_4", "0", "0"},
[422504] = {422504, 12025, 5, 4, "0", "idle", "最近又夢到隊長她們了，還被她們誇獎成長了，說我真的很努力了，辛苦我了……其實這是我的內心想法吧？我還真是——自戀。", "最近、また隊長たちの夢を見ました。彼女たちに成長したと褒められて、本当に努力してるねと言われました……実はこれ、私の独りよがりですよね？私って本当に……ナルシズムですね。", "0", "0", "0", "0", "cv_feilin_5", "0", "0"},
[422505] = {422505, 12025, 6, 4, "0", "idle", "在方舟上遇到過去共事過的社會復興部的同事時，我都會祈禱自己不要被看到……為什麼？因為不知道該說什麼呀……", "方舟で一緒に働いていた社会復興部の同僚に出会いそうなときは、いつも見つからないように祈っています……なぜって？何を話せばいいかわからないからです……", "0", "0", "0", "0", "cv_feilin_6", "0", "0"},
[422506] = {422506, 12025, 7, 5, "1_》_0_0.8", "level1", "這是我最近才知道的事……似乎有很多人把“駕駛員”當成了夢想，就像以前的科學家一樣。這算好事嗎？有點微妙呢……", "最近知ったことですが……多くの人が「ドライバー」を夢見ているようです。かつての科学者のように。これは良いことなのでしょうか……？", "0", "0", "0", "0", "cv_feilin_7", "0", "0"},
[422507] = {422507, 12025, 8, 5, "1_》_0_0.8", "level1", "領航的臉色有點差，是工作太累了嗎？我知道一家不錯的店，那裡的酒和烤肉很棒，下班後要一起去嗎？", "ナビゲーターさん、顔色が悪いですね。仕事が大変なのでしょうか？いいお店を知っていますよ。そこのお酒と焼肉は最高です。仕事が終わったら一緒に行きませんか？", "0", "0", "0", "0", "cv_feilin_8", "0", "0"},
[422508] = {422508, 12025, 9, 5, "1_》_100_1.5", "level2", "我這樣的人真的能當稱職的隊長嗎？領航，您認識多洛莉絲小姐嗎？我有些事情想諮詢她——關於如何當好一名隊長的事情。", "私のような人間が本当に有能な隊長になれるのでしょうか？ナビゲーターさん、ドロリィスさんをご存知ですか？彼女に相談したいことがあります——どうやったら良い隊長になれるかについてです。", "0", "0", "0", "0", "cv_feilin_9", "0", "0"},
[422509] = {422509, 12025, 10, 5, "1_》_500_2", "level3", "領航，您最近有空嗎？不，不是什麼特別重要的事。駕駛員的心理輔導……您很擅長吧？", "ナビゲーターさん、近々お時間ありますか？いえ、特に重要なことではありません。ドライバーの心理カウンセリング……ナビゲーターさんはお得意ですよね？", "0", "0", "0", "0", "cv_feilin_10", "0", "0"},
[422510] = {422510, 12025, 11, 5, "1_》_1000_2.5", "level4", "領航，您能取消今晚的行程嗎？是的，我知道您原本和其他駕駛員有約，但我有很重要的事情要跟你說——是關於戀愛的，關於駕駛員和領航的……關於普通人與通感者的……戀愛諮詢。", "ナビゲーターさん、今晩の予定をキャンセルできますか？はい、他のドライバーとの約束があるのは知っていますが、重要なお話があります——恋愛についてです。ドライバーとナビゲーターのこと……一般人と通感覚者のことについての……恋愛相談です。", "0", "0", "0", "0", "cv_feilin_11", "0", "0"},
[422511] = {422511, 12025, 12, 6, "0", "0", "我變強了。", "私、強くなりました。", "0", "0", "0", "0", "cv_feilin_12", "0", "0"},
[422512] = {422512, 12025, 13, 7, "0", "0", "我也要變得閃閃發光才行。", "私も輝かないといけませんね。", "0", "0", "0", "0", "cv_feilin_13", "0", "0"},
[422513] = {422513, 12025, 14, 8, "0", "0", "這樣一來，就能加入您的隊伍了吧……誒，還是不行嗎？嗚，好難啊……", "こうすれば、あなたのチームに参加できますよね……え、まだダメですか？うぅ、難しいですね……", "0", "0", "0", "0", "cv_feilin_14", "0", "0"},
[422514] = {422514, 12025, 15, 9, "0", "0", "以成為專業的駕駛員為目標！", "ベテランドライバーを目指します！", "0", "0", "0", "0", "cv_feilin_15", "0", "0"},
[422515] = {422515, 12025, 16, 10, "0", "0", "我會保護好大家的！", "私がみんなを守ります！", "0", "0", "0", "0", "cv_feilin_16", "0", "0"},
[422516] = {422516, 12025, 17, 11, "0", "0", "太好了，領航，我做到了！接下來的每次戰鬥，都要像這次一樣！", "良かった、ナビゲーターさん、私やりました！次の戦闘も今回のように頑張ります！", "0", "0", "0", "0", "cv_feilin_17", "0", "0"},
[422517] = {422517, 12025, 18, 12, "0", "0", "還能做得更好，我們還能做得更好，領航。", "もっと上手くできるはずです、私たちならはもっと上手くやれます、ナビゲーターさん。", "0", "0", "0", "0", "cv_feilin_18", "0", "0"},
[422518] = {422518, 12025, 19, 13, "0", "0", "是我攻擊的時機不對嗎……動作要更快點嗎？我應該能做得更好啊。", "私の攻撃のタイミングが間違っていましたか……動作をもっと速くするべきでしょうか？もっと上手くできるはずです。", "0", "0", "0", "0", "cv_feilin_19", "0", "0"},
[422519] = {422519, 12025, 20, 14, "0", "0", "又失敗了……這樣一來不是一點長進都沒有嗎……", "また失敗しました……これじゃ成長していないみたいです……", "0", "0", "0", "0", "cv_feilin_20", "0", "0"},
[422520] = {422520, 12025, 21, 15, "0", "0", "轉火下一個！", "次のターゲットに移ります！", "0", "0", "0", "0", "cv_feilin_21", "0", "0"},
[422521] = {422521, 12025, 23, 16, "0", "0", "命中它！", "あたって！", "0", "0", "0", "0", "cv_feilin_22", "0", "0"},
[422522] = {422522, 12025, 24, 17, "0", "0", "我還能繼續！", "まだ続けられます！", "0", "0", "0", "0", "cv_feilin_23", "0", "0"},
[422523] = {422523, 12025, 22, 38, "0", "0", "馬上就好了！", "もうすぐ終わります！", "0", "0", "0", "0", "cv_feilin_25", "0", "0"},
[422524] = {422524, 12025, 26, 19, "0", "0", "這次……我沒有逃走……", "今回は……逃げませんでした……", "0", "0", "0", "0", "cv_feilin_26", "0", "0"},
[422525] = {422525, 12025, 27, 20, "0", "0", "嗯？是領航啊……嗯？…………領航！？誒！？", "ん？ナビゲーターさんですか……え？…………ナビゲーターさん！？ええ！？", "0", "0", "0", "0", "cv_feilin_27", "0", "0"},
[422526] = {422526, 12025, 28, 21, "0", "0", "“因為要用通感緩解駕駛員的疲憊所以才會在這裡”——這個解釋也太可疑了，不會有人信的啦。", "「通感覚を使ってドライバーの疲れを癒すためにここにいる」という説明は、怪しすぎます。誰も信じませんよ。", "0", "0", "0", "0", "cv_feilin_28", "0", "0"},
[422527] = {422527, 12025, 29, 21, "0", "0", "我沒有害羞啦，反正現在這具身體是幻化出來的，就算被領航碰到也不會怎麼樣……嗚，您不要真的到處亂摸呀，這是欺負人！", "恥ずかしくないですよ。今は幻化の体ですから、ナビゲーターさんが触っても大丈夫です……うぅ、本当にあちこち触らないでください、それは意地悪です！", "0", "0", "0", "0", "cv_feilin_29", "0", "0"},
[422528] = {422528, 12025, 30, 22, "0", "0", "發生什麼了！？", "何が起きましたか！？", "0", "0", "0", "0", "cv_feilin_30", "0", "0"},
[422529] = {422529, 12025, 31, 23, "0", "0", "要猜嗎？能給提示嗎？嗯……“眼鏡”，這個提示怎麼樣？能猜出來嗎？", "当ててみますか？ヒントをあげましょうか？うーん……「眼鏡」、このヒントでどうですか？当てられますか？", "0", "0", "0", "0", "cv_feilin_31", "0", "0"},
[422530] = {422530, 12025, 32, 24, "0", "0", "呼……松了口氣，我還以為領航會忘了我呢。", "ふぅ……ほっとしました。ナビゲーターさんが私を忘れたのかと思いました。", "0", "0", "0", "0", "cv_feilin_32", "0", "0"},
[422531] = {422531, 12025, 33, 25, "0", "0", "請下一次猜對，一定要猜對，拜託您了！", "次は当ててください、必ず当ててください、お願いします！", "0", "0", "0", "0", "cv_feilin_33", "0", "0"},
[422532] = {422532, 12025, 34, 26, "0", "0", "歡迎回來！要稍微休息一下再開始工作嗎？", "お帰りなさい！少し休憩してから仕事を始めますか？", "0", "0", "0", "0", "cv_feilin_34", "0", "0"},
[422533] = {422533, 12025, 35, 27, "0", "0", "我會去戰鬥的，這次不會再逃跑了！", "私は戦いに行きます、今回はもう逃げません！", "0", "0", "0", "0", "cv_feilin_35", "0", "0"},
[422534] = {422534, 12025, 36, 28, "0", "0", "我會好好表現的！", "私、ちゃんとやります！", "0", "0", "0", "0", "cv_feilin_36", "0", "0"},
[422535] = {422535, 12025, 37, 29, "0", "0", "優秀的人會互相吸引，她們都是因為您而聚在一起的，領航。", "優秀な人は互いに引き寄せ合います。彼女たちはみんな、ナビゲーターさんのために集まっているのです。", "0", "0", "0", "0", "cv_feilin_37", "0", "0"},
[422536] = {422536, 12025, 38, 30, "0", "0", "這次也會產生新的邂逅吧。", "今回も新しい出会いがあるでしょう。", "0", "0", "0", "0", "cv_feilin_38", "0", "0"},
[422537] = {422537, 12025, 39, 31, "0", "0", "我的裝備是不是也該更新了呢……", "私の装備も更新するべきでしょうか……", "0", "0", "0", "0", "cv_feilin_39", "0", "0"},
[422538] = {422538, 12025, 40, 32, "0", "0", "要酌情購物，理智消費噢。", "賢い買い物、理性的な消費を。", "0", "0", "0", "0", "cv_feilin_40", "0", "0"},
[422539] = {422539, 12025, 41, 33, "0", "0", "這就是精英的履歷嗎，好厲害。", "これがエリートのプロフィールですか、すごいです。", "0", "0", "0", "0", "cv_feilin_41", "0", "0"},
[422540] = {422540, 12025, 42, 34, "0", "0", "請認真設定。", "設定してください。", "0", "0", "0", "0", "cv_feilin_42", "0", "0"},
[422541] = {422541, 12025, 43, 35, "0", "0", "需要我幫忙整理嗎？", "整理を手伝いましょうか？", "0", "0", "0", "0", "cv_feilin_43", "0", "0"},
[422542] = {422542, 12025, 44, 36, "0", "0", "請謹慎交友噢。", "交友は慎重にしてくださいね。", "0", "0", "0", "0", "cv_feilin_44", "0", "0"},
[422543] = {422543, 12025, 45, 37, "0", "0", "嗯？", "うん？", "0", "0", "0", "0", "cv_feilin_45", "0", "0"},
[422600] = {422600, 12026, 1, 1, "0", "0", "蒼霧殘響", "ハツリバーブ", "0", "0", "0", "0", "cv_lyfa2_1", "0", "0"},
[422601] = {422601, 12026, 2, 2, "0", "0", "請放心交給我吧，保護老大的安全是身為手下的我該盡的義務！", "安心して私にお任せください、親分の身の安全を確保することこそ、私の義務ですから。", "0", "0", "0", "0", "cv_lyfa2_2", "0", "0"},
[422602] = {422602, 12026, 3, 3, "0", "0", "瓦爾基裡的莉法小姐——也就是我——又來打擾您啦！這次的目標是打倒艾吉斯嗎？", "ワルキューレのリーファさん――つまり私――この度もお邪魔することになりました！今回の目標は打倒アイギスでしょうか？", "0", "0", "0", "0", "cv_lyfa2_3", "0", "0"},
[422603] = {422603, 12026, 4, 4, "0", "idle", "領航！您知道想要瞭解摩托文化的話閱讀什麼作品比較好嗎？雖然只是臨時的，但我覺得還是有必要瞭解一下摩托文化。", "ナビゲーターさん、バイクの文化について知りたいなら、どんな作品を読めばいいですか？一時的な興味でも、ちゃんと理解しておくのは大事ですからね。", "0", "0", "0", "0", "cv_lyfa2_4", "0", "0"},
[422604] = {422604, 12026, 5, 4, "0", "idle", "領航週末有想去的地方嗎？我可以搭車送您一程噢！放心，我不會超速行駛的！", "ナビゲーターさん、週末に行きたい場所はありますか？私がお連れしますよ！安心してください、スピードは出しすぎませんから。", "0", "0", "0", "0", "cv_lyfa2_5", "0", "0"},
[422605] = {422605, 12026, 6, 4, "0", "idle", "這身裝備是我自己設計的，亞爾薇特隊長知道後狠狠地教訓了我一頓，說拙劣的裝備只會丟瓦爾基裡的臉……真是的，就不能鼓勵下我嗎？", "この装備、実は私がデザインしたんです。アルヴィト隊長に見せたら、そんな無様な装備じゃ、ワルキューレの名に泥を塗るだけだって、すごく叱られちゃいました……。もう、少しは励ましてくれてもいいのに。", "0", "0", "0", "0", "cv_lyfa2_6", "0", "0"},
[422606] = {422606, 12026, 7, 5, "1_》_0_0.8", "level1", "當一名合格的女僕是我的夢想……一直都是，現在也是。不過，在實現夢想的途中，偶爾看一下別處的風景也不是壞事。", "プロのメイドになるのが私の夢なんです……ずっと前から、今でも。それでも、夢を追う途中で違う景色を眺めるのも悪くないですね。", "0", "0", "0", "0", "cv_lyfa2_7", "0", "0"},
[422607] = {422607, 12026, 8, 5, "1_》_0_0.8", "level1", "是不是摸起來很舒服？這身衣服是我用特別的材料打造的，觸感一流噢！", "この服、触ってみてください。特別な素材で作ったから、触り心地は最高ですよ！", "0", "0", "0", "0", "cv_lyfa2_8", "0", "0"},
[422608] = {422608, 12026, 9, 5, "1_》_100_1.5", "level2", "瓦爾基裡的任務是什麼？領航怎麼突然這件事好奇了？到不是什麼秘密，但是說出來會很害羞啦。簡單來說就是——將所有可能威脅到人類社會的危機扼殺在搖籃中……就像超級英雄一樣。", "ワルキューレの任務、ですか？いきなりですね。秘密ってほどでもないんですけど……簡単に言うと、人類社会に脅威を与える可能性のある危機を未然に防ぐことです……まるでスーパーヒーローみたいでしょ。", "0", "0", "0", "0", "cv_lyfa2_9", "0", "0"},
[422609] = {422609, 12026, 10, 5, "1_》_500_2", "level3", "普萊特市的事情……說出來對阿爾泰婭小姐不太好，但在我心裡面覺得很有趣哦。希望下次，還有下下次，都能和領航遇上這麼有趣的故事……要是有人能寫成書就好了呢！", "プレート市の件……アルテアさんには悪いけど、私は楽しかったですよ。次も、その次も、ナビゲーターさんと一緒にそんな楽しい物語に出会えたら……誰かが本にしてくれたらいいのにね。", "0", "0", "0", "0", "cv_lyfa2_10", "0", "0"},
[422610] = {422610, 12026, 11, 5, "1_》_1000_2.5", "level4", "領航，您肯定不知道自己有多優秀，沒有人清楚您的功績與付出……所以，我只有成為能與您匹配的人時，才會將我心中所想的……全部傾訴給您。", "ナビゲーターさん、ご自分がどれだけ素晴らしいか、きっとご存じないでしょう。あなたの功績と努力を誰も知らない……だから、私もあなたにふさわしい存在になったら、心の中の想いを全部伝えたいと思います。", "0", "0", "0", "0", "cv_lyfa2_11", "0", "0"},
[422611] = {422611, 12026, 12, 6, "0", "0", "謝謝~", "ありがとうございます～", "0", "0", "0", "0", "cv_lyfa2_12", "0", "0"},
[422612] = {422612, 12026, 13, 7, "0", "0", "聽到引擎的嗡嗡聲了！", "エンジン音が聞こえる！", "0", "0", "0", "0", "cv_lyfa2_13", "0", "0"},
[422613] = {422613, 12026, 14, 8, "0", "0", "能聽到咆哮聲嗎？嗯，那正是我與摩托的默契達到極致時發出的共鳴！", "この轟音こそが、私とバイクの共鳴です！", "0", "0", "0", "0", "cv_lyfa2_14", "0", "0"},
[422614] = {422614, 12026, 15, 9, "0", "0", "車技變得更嫺熟了。", "運転技術がさらに上達しました。", "0", "0", "0", "0", "cv_lyfa2_15", "0", "0"},
[422615] = {422615, 12026, 16, 10, "0", "0", "讓我們在戰場上刮起龍捲風吧！", "戦場に竜巻を巻き起こしましょう！", "0", "0", "0", "0", "cv_lyfa2_16", "0", "0"},
[422616] = {422616, 12026, 17, 11, "0", "0", "這是一次完美的表演。", "完璧なパフォーマンスですね。", "0", "0", "0", "0", "cv_lyfa2_17", "0", "0"},
[422617] = {422617, 12026, 18, 12, "0", "0", "是不是違章了？", "もしかして、交通違反しちゃった？", "0", "0", "0", "0", "cv_lyfa2_18", "0", "0"},
[422618] = {422618, 12026, 19, 13, "0", "0", "嗚哇，摩托車出現裂痕了……", "ああ、バイクに傷が……", "0", "0", "0", "0", "cv_lyfa2_19", "0", "0"},
[422619] = {422619, 12026, 20, 14, "0", "0", "擰滿油門，撤退！", "アクセル全開、撤退します！", "0", "0", "0", "0", "cv_lyfa2_20", "0", "0"},
[422620] = {422620, 12026, 21, 15, "0", "0", "漂亮~", "かっこいい～", "0", "0", "0", "0", "cv_lyfa2_21", "0", "0"},
[422621] = {422621, 12026, 23, 16, "0", "0", "撞飛你們！", "ぶっ飛ばしますよ！", "0", "0", "0", "0", "cv_lyfa2_22", "0", "0"},
[422622] = {422622, 12026, 24, 17, "0", "0", "我可不會停下噢。", "私は止まりませんよ。", "0", "0", "0", "0", "cv_lyfa2_23", "0", "0"},
[422623] = {422623, 12026, 25, 18, "0", "0", "將風和煩惱都拋在身後，奔著深淵疾馳吧！", "風も悩みも置き去りにして、深淵へと疾走しましょう！", "0", "0", "0", "0", "cv_lyfa2_24", "0", "0"},
[422624] = {422624, 12026, 22, 38, "0", "0", "準備就緒！", "準備万端！", "0", "0", "0", "0", "cv_lyfa2_25", "0", "0"},
[422625] = {422625, 12026, 26, 19, "0", "0", "哎呀……超速被逮到了……", "ああ……スピード違反で捕まっちゃった……", "0", "0", "0", "0", "cv_lyfa2_26", "0", "0"},
[422626] = {422626, 12026, 27, 20, "0", "0", "居然又麻煩領航來招待我了……之後只好下跪謝罪了！", "またナビゲーターさんに迷惑をかけちゃって……これはもう土下座してお詫びするしか！", "0", "0", "0", "0", "cv_lyfa2_27", "0", "0"},
[422627] = {422627, 12026, 28, 21, "0", "0", "我會懷著感恩的心情享受領航的服務，謝謝！", "ナビゲーターさんのサービスに感謝しながら、楽しませていただきますね、ありがとうございます！", "0", "0", "0", "0", "cv_lyfa2_28", "0", "0"},
[422628] = {422628, 12026, 29, 21, "0", "0", "下次換我來給領航搓背吧~", "次は私がナビゲーターさんの背中を洗いますね～", "0", "0", "0", "0", "cv_lyfa2_29", "0", "0"},
[422629] = {422629, 12026, 30, 22, "0", "0", "發生什麼了？", "何があったんですか？", "0", "0", "0", "0", "cv_lyfa2_30", "0", "0"},
[422630] = {422630, 12026, 31, 23, "0", "0", "鏘鏘鏘！老大，猜猜我是誰！", "じゃじゃーん！親分、私が誰だか分かりますか？", "0", "0", "0", "0", "cv_lyfa2_31", "0", "0"},
[422631] = {422631, 12026, 32, 24, "0", "0", "答對啦，我們之間的默契無懈可擊。", "大正解、私たちの相性はバッチリですね！", "0", "0", "0", "0", "cv_lyfa2_32", "0", "0"},
[422632] = {422632, 12026, 33, 25, "0", "0", "奇怪，到底是哪裡搞錯了呢……", "あれ、どこで間違えたんだろう……", "0", "0", "0", "0", "cv_lyfa2_33", "0", "0"},
[422633] = {422633, 12026, 34, 26, "0", "0", "歡迎回來，接下來讓我們一起在世界大舞臺上馳騁吧~", "お帰りなさい。これからも一緒に世界の舞台を駆け抜けましょうね～", "0", "0", "0", "0", "cv_lyfa2_34", "0", "0"},
[422634] = {422634, 12026, 35, 27, "0", "0", "把攔在路上的敵人全部撞飛吧。", "道を阻む敵は全部ぶっ飛ばしましょう！", "0", "0", "0", "0", "cv_lyfa2_35", "0", "0"},
[422635] = {422635, 12026, 36, 28, "0", "0", "點到即止噢。", "加減はちゃんとしますよ。", "0", "0", "0", "0", "cv_lyfa2_36", "0", "0"},
[422636] = {422636, 12026, 37, 29, "0", "0", "大家既是夥伴……也是競爭者。", "みんな仲間でもあり……競争相手でもあります。", "0", "0", "0", "0", "cv_lyfa2_37", "0", "0"},
[422637] = {422637, 12026, 38, 30, "0", "0", "不知道這次來的會是怎樣有趣的人。", "今回はどんな面白い人が来るかな。", "0", "0", "0", "0", "cv_lyfa2_38", "0", "0"},
[422638] = {422638, 12026, 39, 31, "0", "0", "我也想換上更高檔的車。", "私ももっと高級なバイクに乗りたいな。", "0", "0", "0", "0", "cv_lyfa2_39", "0", "0"},
[422639] = {422639, 12026, 40, 32, "0", "0", "我來負責搬東西~", "荷物運びは私に任せてください～", "0", "0", "0", "0", "cv_lyfa2_40", "0", "0"},
[422640] = {422640, 12026, 41, 33, "0", "0", "領航變得更成熟了~", "ナビゲーターさん、また一段と立派になりましたね。", "0", "0", "0", "0", "cv_lyfa2_41", "0", "0"},
[422641] = {422641, 12026, 42, 34, "0", "0", "修改後記得確認哦。", "修正したら確認してくださいね。", "0", "0", "0", "0", "cv_lyfa2_42", "0", "0"},
[422642] = {422642, 12026, 43, 35, "0", "0", "沒有定時炸彈，沒有刀片，安全。", "爆弾も刃物もありません、安全です。", "0", "0", "0", "0", "cv_lyfa2_43", "0", "0"},
[422643] = {422643, 12026, 44, 36, "0", "0", "不可以說髒話。", "汚い言葉はダメですよ。", "0", "0", "0", "0", "cv_lyfa2_44", "0", "0"},
[422644] = {422644, 12026, 45, 37, "0", "0", "呼呼~", "ふふ～", "0", "0", "0", "0", "cv_lyfa2_45", "0", "0"},
[422700] = {422700, 12027, 1, 1, "0", "0", "蒼霧殘響", "0", "0", "0", "0", "0", "cv_kurimu2_1", "0", "0"},
[422701] = {422701, 12027, 2, 2, "0", "0", "可不能讓孩子們看到聖誕老人喝醉的樣子。", "0", "0", "0", "0", "0", "cv_kurimu2_2", "0", "0"},
[422702] = {422702, 12027, 3, 3, "0", "0", "聖誕老人來咯，我帶了很多……禮物！只有好孩子才能領取哦。", "0", "0", "0", "0", "0", "cv_kurimu2_3", "0", "0"},
[422703] = {422703, 12027, 4, 4, "0", "idle", "一年才有一次的聖誕節，領航不喝一點慶祝嗎？", "0", "0", "0", "0", "0", "cv_kurimu2_4", "0", "0"},
[422704] = {422704, 12027, 5, 4, "0", "idle", "我的袋子裏可不只有酒，還有花生、熏肉、肉腸……", "0", "0", "0", "0", "0", "cv_kurimu2_5", "0", "0"},
[422705] = {422705, 12027, 6, 4, "0", "idle", "雖然不能像真的聖誕老人一樣給大家分發禮物，但能讓大家在看到我的時候開心地笑起來，那也就足夠了。", "0", "0", "0", "0", "0", "cv_kurimu2_6", "0", "0"},
[422706] = {422706, 12027, 7, 5, "1_》_0_0.8", "level1", "你說聖誕老人在平時是在做什麼工作呢？無論他做什麼工作，一定是很努力的吧，不然怎麼能有那麼多錢給孩子們買禮物。", "0", "0", "0", "0", "0", "cv_kurimu2_7", "0", "0"},
[422707] = {422707, 12027, 8, 5, "1_》_0_0.8", "level1", "Merry Christmas！", "0", "0", "0", "0", "0", "cv_kurimu2_8", "0", "0"},
[422708] = {422708, 12027, 9, 5, "1_》_100_1.5", "level2", "吼吼吼，想要聖誕老人禮物可以，但是你得自己來拿。", "0", "0", "0", "0", "0", "cv_kurimu2_9", "0", "0"},
[422709] = {422709, 12027, 10, 5, "1_》_500_2", "level3", "為什麼聖誕老人能知道每個孩子心裏想要的禮物？難道他也和領航一樣有通感……等等，難道領航你就是聖誕老人！", "0", "0", "0", "0", "0", "cv_kurimu2_10", "0", "0"},
[422710] = {422710, 12027, 11, 5, "1_》_1000_2.5", "level4", "這就喝光了嗎？可我還沒有喝夠……清醒可比醉的時候更難熬。沒有酒精的幫助，我實在沒法抑制自己的胡思亂想……領航，你會喜歡像我這種酒鬼嗎？", "0", "0", "0", "0", "0", "cv_kurimu2_11", "0", "0"},
[422711] = {422711, 12027, 12, 6, "0", "0", "再來一杯！", "0", "0", "0", "0", "0", "cv_kurimu2_12", "0", "0"},
[422712] = {422712, 12027, 13, 7, "0", "0", "聖誕之星？", "0", "0", "0", "0", "0", "cv_kurimu2_13", "0", "0"},
[422713] = {422713, 12027, 14, 8, "0", "0", "馴鹿和雪橇在哪裏？", "0", "0", "0", "0", "0", "cv_kurimu2_14", "0", "0"},
[422714] = {422714, 12027, 15, 9, "0", "0", "聖誕特飲！", "0", "0", "0", "0", "0", "cv_kurimu2_15", "0", "0"},
[422715] = {422715, 12027, 16, 10, "0", "0", "聖誕老人來了。", "0", "0", "0", "0", "0", "cv_kurimu2_16", "0", "0"},
[422716] = {422716, 12027, 17, 11, "0", "0", "吼吼吼，真是個完美的節日。", "0", "0", "0", "0", "0", "cv_kurimu2_17", "0", "0"},
[422717] = {422717, 12027, 18, 12, "0", "0", "聖誕節的遺憾。", "0", "0", "0", "0", "0", "cv_kurimu2_18", "0", "0"},
[422718] = {422718, 12027, 19, 13, "0", "0", "好想喝一杯……", "0", "0", "0", "0", "0", "cv_kurimu2_19", "0", "0"},
[422719] = {422719, 12027, 20, 14, "0", "0", "要是真正的聖誕老人的話……", "0", "0", "0", "0", "0", "cv_kurimu2_20", "0", "0"},
[422720] = {422720, 12027, 21, 15, "0", "0", "才喝這點就倒下了？", "0", "0", "0", "0", "0", "cv_kurimu2_21", "0", "0"},
[422721] = {422721, 12027, 23, 16, "0", "0", "禮物放哪去了……", "0", "0", "0", "0", "0", "cv_kurimu2_25", "0", "0"},
[422722] = {422722, 12027, 24, 17, "0", "0", "不醉不歸！", "0", "0", "0", "0", "0", "cv_kurimu2_22", "0", "0"},
[422723] = {422723, 12027, 25, 18, "0", "0", "不行不行，必須喝完。", "0", "0", "0", "0", "0", "cv_kurimu2_23", "0", "0"},
[422724] = {422724, 12027, 22, 38, "0", "0", "吼吼吼，分發禮物咯！", "0", "0", "0", "0", "0", "cv_kurimu2_24", "0", "0"},
[422725] = {422725, 12027, 26, 19, "0", "0", "聖誕節已經結束了……", "0", "0", "0", "0", "0", "cv_kurimu2_26", "0", "0"},
[422726] = {422726, 12027, 27, 20, "0", "0", "聖誕老人也需要假期。", "0", "0", "0", "0", "0", "cv_kurimu2_27", "0", "0"},
[422727] = {422727, 12027, 28, 21, "0", "0", "至少給我留個聖誕帽吧，不然大家怎麼知道我是聖誕老人？", "0", "0", "0", "0", "0", "cv_kurimu2_28", "0", "0"},
[422728] = {422728, 12027, 29, 21, "0", "0", "還沒有把水換成威士忌嗎？", "0", "0", "0", "0", "0", "cv_kurimu2_29", "0", "0"},
[422729] = {422729, 12027, 30, 22, "0", "0", "完成這些能拿禮物嗎？", "0", "0", "0", "0", "0", "cv_kurimu2_30", "0", "0"},
[422730] = {422730, 12027, 31, 23, "0", "0", "吼吼吼，猜中了給你禮物哦。", "0", "0", "0", "0", "0", "cv_kurimu2_31", "0", "0"},
[422731] = {422731, 12027, 32, 24, "0", "0", "走，我們去喝一頓慶祝！", "0", "0", "0", "0", "0", "cv_kurimu2_32", "0", "0"},
[422732] = {422732, 12027, 33, 25, "0", "0", "這裏不止我一個聖誕老人嗎？", "0", "0", "0", "0", "0", "cv_kurimu2_33", "0", "0"},
[422733] = {422733, 12027, 34, 26, "0", "0", "吼吼吼，歡迎，想要什麼禮物盡管告訴我吧。", "0", "0", "0", "0", "0", "cv_kurimu2_34", "0", "0"},
[422734] = {422734, 12027, 35, 27, "0", "0", "聖誕節的故事要開始了嗎？", "0", "0", "0", "0", "0", "cv_kurimu2_35", "0", "0"},
[422735] = {422735, 12027, 36, 28, "0", "0", "一起打雪仗吧。", "0", "0", "0", "0", "0", "cv_kurimu2_36", "0", "0"},
[422736] = {422736, 12027, 37, 29, "0", "0", "舉辦聖誕派對吧。", "0", "0", "0", "0", "0", "cv_kurimu2_37", "0", "0"},
[422737] = {422737, 12027, 38, 30, "0", "0", "聖誕節就是團聚的節日。", "0", "0", "0", "0", "0", "cv_kurimu2_38", "0", "0"},
[422738] = {422738, 12027, 39, 31, "0", "0", "有沒有大點的聖誕帽？", "0", "0", "0", "0", "0", "cv_kurimu2_39", "0", "0"},
[422739] = {422739, 12027, 40, 32, "0", "0", "有聖誕節折扣嗎。", "0", "0", "0", "0", "0", "cv_kurimu2_40", "0", "0"},
[422740] = {422740, 12027, 41, 33, "0", "0", "我已經記在好孩子名單上了。", "0", "0", "0", "0", "0", "cv_kurimu2_41", "0", "0"},
[422741] = {422741, 12027, 42, 34, "0", "0", "把聖誕節設定到100天吧。", "0", "0", "0", "0", "0", "cv_kurimu2_42", "0", "0"},
[422742] = {422742, 12027, 43, 35, "0", "0", "有給聖誕老人的信嗎？", "0", "0", "0", "0", "0", "cv_kurimu2_43", "0", "0"},
[422743] = {422743, 12027, 44, 36, "0", "0", "把大家的心願收集起來。", "0", "0", "0", "0", "0", "cv_kurimu2_44", "0", "0"},
[422744] = {422744, 12027, 45, 37, "0", "0", "幹杯！", "0", "0", "0", "0", "0", "cv_kurimu2_45", "0", "0"},
[422800] = {422800, 12028, 1, 1, "0", "0", "又要我念一遍？……蒼霧殘響。", "0", "0", "0", "0", "0", "cv_weilai_vd_1", "0", "0"},
[422801] = {422801, 12028, 2, 2, "0", "0", "果然超級戀愛偵探就是要和助手在一次才行。……不過我是不是應該扮成醫生？", "0", "0", "0", "0", "0", "cv_weilai_vd_2", "0", "0"},
[422802] = {422802, 12028, 3, 3, "0", "0", "超級戀愛偵探助手，參上！助手and變態先生，best組合！", "0", "0", "0", "0", "0", "cv_weilai_vd_3", "0", "0"},
[422803] = {422803, 12028, 4, 4, "0", "idle", "這是常識，我的朋友。嘿嘿，雖然這句話不該由我這個助手來說……但是我還是想耍一耍帥。", "0", "0", "0", "0", "0", "cv_weilai_vd_4", "0", "0"},
[422804] = {422804, 12028, 5, 4, "0", "idle", "嗚啊啊啊啊……為什麼今天的菜裏有苦瓜，嘔……這、這簡直就是殺手1號……我、我被暗殺了……！", "0", "0", "0", "0", "0", "cv_weilai_vd_5", "0", "0"},
[422805] = {422805, 12028, 6, 4, "0", "idle", "已經累了，給我抱抱。", "0", "0", "0", "0", "0", "cv_weilai_vd_6", "0", "0"},
[422806] = {422806, 12028, 7, 5, "1_》_0_0.8", "level1", "只要我的帽子還停留在頭上一天，我就一輩子都是偵探助手……這句話的意思是當我膩了的時候就會摘下帽子。", "0", "0", "0", "0", "0", "cv_weilai_vd_7", "0", "0"},
[422807] = {422807, 12028, 8, 5, "1_》_0_0.8", "level1", "這次正義的偵探與他的助手也戰勝了邪惡，地球的明天也依舊在旋轉。", "0", "0", "0", "0", "0", "cv_weilai_vd_8", "0", "0"},
[422808] = {422808, 12028, 9, 5, "1_》_100_1.5", "level2", "喜歡的東西是變態先生，討厭的東西是解謎……遇到困難的時候就找能預知未來的超能力者看看吧，為什麼要我動腦子。", "0", "0", "0", "0", "0", "cv_weilai_vd_9", "0", "0"},
[422809] = {422809, 12028, 10, 5, "1_》_500_2", "level3", "發、發生了盜竊案！？快、快點打報警電話啊……看、看我幹什麼，我只是個偵探啊？", "0", "0", "0", "0", "0", "cv_weilai_vd_10", "0", "0"},
[422810] = {422810, 12028, 11, 5, "1_》_1000_2.5", "level4", "我要偷走你的心！變態先生接招吧！", "0", "0", "0", "0", "0", "cv_weilai_vd_11", "0", "0"},
[422811] = {422811, 12028, 12, 6, "0", "0", "洞察力提升了。", "0", "0", "0", "0", "0", "cv_weilai_vd_12", "0", "0"},
[422812] = {422812, 12028, 13, 7, "0", "0", "綜合性思維能力提升了，大概？", "0", "0", "0", "0", "0", "cv_weilai_vd_13", "0", "0"},
[422813] = {422813, 12028, 14, 8, "0", "0", "宏觀把握能力……什麼是宏觀……？姆……不管了……總之這個東西也提升了。", "0", "0", "0", "0", "0", "cv_weilai_vd_14", "0", "0"},
[422814] = {422814, 12028, 15, 9, "0", "0", "從零開始慢慢成為世界第一的名偵探助手！變態先生作為偵探會和我一起努力的吧？", "0", "0", "0", "0", "0", "cv_weilai_vd_15", "0", "0"},
[422815] = {422815, 12028, 16, 10, "0", "0", "超級戀愛偵探，出擊！", "0", "0", "0", "0", "0", "cv_weilai_vd_16", "0", "0"},
[422816] = {422816, 12028, 17, 11, "0", "0", "200%超偵探模式勝利，呼呼，多虧了我能堅持下來。", "0", "0", "0", "0", "0", "cv_weilai_vd_17", "0", "0"},
[422817] = {422817, 12028, 18, 12, "0", "0", "輕輕鬆松拿下勝利——！即使是2星也算是勝利吧？", "0", "0", "0", "0", "0", "cv_weilai_vd_18", "0", "0"},
[422818] = {422818, 12028, 19, 13, "0", "0", "身上髒兮兮的了……不管多少次我都討厭這樣！我要回去洗澡了！", "0", "0", "0", "0", "0", "cv_weilai_vd_19", "0", "0"},
[422819] = {422819, 12028, 20, 14, "0", "0", "我說……變態先生，我們還是先跑吧？反正都不是一次兩次了。", "0", "0", "0", "0", "0", "cv_weilai_vd_20", "0", "0"},
[422820] = {422820, 12028, 21, 15, "0", "0", "真相只有一個！", "0", "0", "0", "0", "0", "cv_weilai_vd_21", "0", "0"},
[422821] = {422821, 12028, 23, 16, "0", "0", "biu——biu——biu——我正在假裝自己正在蓄力，怎麼樣，識破偵探的偽裝了嗎？", "0", "0", "0", "0", "0", "cv_weilai_vd_25", "0", "0"},
[422822] = {422822, 12028, 24, 17, "0", "0", "哼哼！", "0", "0", "0", "0", "0", "cv_weilai_vd_22", "0", "0"},
[422823] = {422823, 12028, 25, 18, "0", "0", "我全都明白了！", "0", "0", "0", "0", "0", "cv_weilai_vd_23", "0", "0"},
[422824] = {422824, 12028, 22, 38, "0", "0", "盛放的愛之偵探，princess pink！", "0", "0", "0", "0", "0", "cv_weilai_vd_24", "0", "0"},
[422825] = {422825, 12028, 26, 19, "0", "0", "撤退！！！！", "0", "0", "0", "0", "0", "cv_weilai_vd_26", "0", "0"},
[422826] = {422826, 12028, 27, 20, "0", "0", "終於——洗澡了！！背上好癢哦~變態先生快幫我看看~！", "0", "0", "0", "0", "0", "cv_weilai_vd_27", "0", "0"},
[422827] = {422827, 12028, 28, 21, "0", "0", "變態先生~耳朵後面也要仔細擦乾淨~", "0", "0", "0", "0", "0", "cv_weilai_vd_28", "0", "0"},
[422828] = {422828, 12028, 29, 21, "0", "0", "出、出了好多汗，變態先生要小心不要再在我身上滑倒哦！上次就不小心掉到肚臍眼裏去了……", "0", "0", "0", "0", "0", "cv_weilai_vd_29", "0", "0"},
[422829] = {422829, 12028, 30, 22, "0", "0", "有事件的氣息！", "0", "0", "0", "0", "0", "cv_weilai_vd_30", "0", "0"},
[422830] = {422830, 12028, 31, 23, "0", "0", "我是超級戀愛偵探助手！！！千萬別猜錯！別猜錯！", "0", "0", "0", "0", "0", "cv_weilai_vd_31", "0", "0"},
[422831] = {422831, 12028, 32, 24, "0", "0", "好耶！！！你猜對啦！！！好棒好棒！！！", "0", "0", "0", "0", "0", "cv_weilai_vd_32", "0", "0"},
[422832] = {422832, 12028, 33, 25, "0", "0", "……變態先生，我都給了這麼明顯的提示了還是猜不出來，我可不保證我接下來會對變態先生做出什麼過分的事情哦！！！", "0", "0", "0", "0", "0", "cv_weilai_vd_33", "0", "0"},
[422833] = {422833, 12028, 34, 26, "0", "0", "超級戀愛偵探，集合了。", "0", "0", "0", "0", "0", "cv_weilai_vd_34", "0", "0"},
[422834] = {422834, 12028, 35, 27, "0", "0", "開始我們的推理吧！來吧，變態先生，輪到你動腦筋了。", "0", "0", "0", "0", "0", "cv_weilai_vd_35", "0", "0"},
[422835] = {422835, 12028, 36, 28, "0", "0", "……我也要一起想答案嗎？", "0", "0", "0", "0", "0", "cv_weilai_vd_36", "0", "0"},
[422836] = {422836, 12028, 37, 29, "0", "0", "我、我需要到場嘉賓的援助！", "0", "0", "0", "0", "0", "cv_weilai_vd_37", "0", "0"},
[422837] = {422837, 12028, 38, 30, "0", "0", "緊、緊急場外電話援助！", "0", "0", "0", "0", "0", "cv_weilai_vd_38", "0", "0"},
[422838] = {422838, 12028, 39, 31, "0", "0", "變態先生，你說這裏有沒有超級AI幫我思考！", "0", "0", "0", "0", "0", "cv_weilai_vd_39", "0", "0"},
[422839] = {422839, 12028, 40, 32, "0", "0", "那裏有情侶特惠咖啡店……我早就想喝一次大人的咖啡了，我們去那裏吧。", "0", "0", "0", "0", "0", "cv_weilai_vd_40", "0", "0"},
[422840] = {422840, 12028, 41, 33, "0", "0", "儘管把我的照片當去頭像吧！我可是很大度的哦。", "0", "0", "0", "0", "0", "cv_weilai_vd_41", "0", "0"},
[422841] = {422841, 12028, 42, 34, "0", "0", "要……要幹什麼？", "0", "0", "0", "0", "0", "cv_weilai_vd_42", "0", "0"},
[422842] = {422842, 12028, 43, 35, "0", "0", "郵箱裏有好多信啊~那我作為女主人就幫你代收了。", "0", "0", "0", "0", "0", "cv_weilai_vd_43", "0", "0"},
[422843] = {422843, 12028, 44, 36, "0", "0", "出去聊天的話，不可以很晚才回來哦……我會寂寞的！", "0", "0", "0", "0", "0", "cv_weilai_vd_44", "0", "0"},
[422844] = {422844, 12028, 45, 37, "0", "0", "嘿！", "0", "0", "0", "0", "0", "cv_weilai_vd_45", "0", "0"},
[422900] = {422900, 12029, 1, 1, "0", "0", "蒼霧殘響", "0", "0", "0", "0", "0", "cv_fululu_2nd_01", "0", "0"},
[422901] = {422901, 12029, 2, 2, "0", "0", "領航請安心地依賴我吧。", "0", "0", "0", "0", "0", "cv_fululu_2nd_02", "0", "0"},
[422902] = {422902, 12029, 3, 3, "0", "0", "領航，好久不見，芙露露已經是大人了喵。", "0", "0", "0", "0", "0", "cv_fululu_2nd_03", "0", "0"},
[422903] = {422903, 12029, 4, 4, "0", "idle", "雨天過後是晴天，黑夜過後是白日，終焉之後是一次新的開始，破破爛爛的世界總會恢復原樣，我就是這樣想的哦，之後也會一直這樣想下去的。", "0", "0", "0", "0", "0", "cv_fululu_2nd_04", "0", "0"},
[422904] = {422904, 12029, 5, 4, "0", "idle", "那些前仆後繼的犧牲，那些看似渺茫的努力，都是為了這一刻——領航，我們堅持到了現在，之後的事情，就拜託你了。", "0", "0", "0", "0", "0", "cv_fululu_2nd_05", "0", "0"},
[422905] = {422905, 12029, 6, 4, "0", "idle", "希望是什麼？阿萊塔覺得那是危險的誘惑，查麗莎姐姐總是對它緘默不言，我的話，認為希望是必需品，是活在這個世界，對抗絕望的必需品——這也是我們需要你的原因。", "0", "0", "0", "0", "0", "cv_fululu_2nd_06", "0", "0"},
[422906] = {422906, 12029, 7, 5, "1_》_0_0.8", "level1", "我可是一直相信著——領航沒有死，也一定有辦法再一次拯救這個世界的。", "0", "0", "0", "0", "0", "cv_fululu_2nd_07", "0", "0"},
[422907] = {422907, 12029, 8, 5, "1_》_0_0.8", "level1", "領航是想確認下我是不是大人嗎？", "0", "0", "0", "0", "0", "cv_fululu_2nd_08", "0", "0"},
[422908] = {422908, 12029, 9, 5, "1_》_100_1.5", "level2", "要說事到如今還有什麼遺憾的話，就是身體上沒有完全成為一個成熟的大姐姐吧~", "0", "0", "0", "0", "0", "cv_fululu_2nd_09", "0", "0"},
[422909] = {422909, 12029, 10, 5, "1_》_500_2", "level3", "只要是領航的話，想做什麼都可以~這是我給領航的特權~", "0", "0", "0", "0", "0", "cv_fululu_2nd_10", "0", "0"},
[422910] = {422910, 12029, 11, 5, "1_》_1000_2.5", "level4", "領航，新切斯頓的東邊就是你消失的地方，也是太陽升起的地方，每一個日出，我都會望著那個方向，等待你像太陽一樣出現——終於，我等到了。", "0", "0", "0", "0", "0", "cv_fululu_2nd_11", "0", "0"},
[422911] = {422911, 12029, 12, 6, "0", "0", "等級提高了~", "0", "0", "0", "0", "0", "cv_fululu_2nd_12", "0", "0"},
[422912] = {422912, 12029, 13, 7, "0", "0", "真遺憾，芙露露不能再長大了。", "0", "0", "0", "0", "0", "cv_fululu_2nd_13", "0", "0"},
[422913] = {422913, 12029, 14, 8, "0", "0", "現在的我成長到了什麼程度，領航來親自感受吧。", "0", "0", "0", "0", "0", "cv_fululu_2nd_14", "0", "0"},
[422914] = {422914, 12029, 15, 9, "0", "0", "想要一擊必殺的技能~", "0", "0", "0", "0", "0", "cv_fululu_2nd_15", "0", "0"},
[422915] = {422915, 12029, 16, 10, "0", "0", "從現在開始逆轉局勢吧，領航。", "0", "0", "0", "0", "0", "cv_fululu_2nd_16", "0", "0"},
[422916] = {422916, 12029, 17, 11, "0", "0", "從現在開始，一直贏到最後吧。", "0", "0", "0", "0", "0", "cv_fululu_2nd_17", "0", "0"},
