[430000] = {430000, 13000, 1, 1, "0", "0", "蒼霧…zzz……", "蒼霧（ハツ）……zzz……", "0", "0", "蒼霧…zzz……", "0", "cv_odora_30", "0", "0"},
[430001] = {430001, 13000, 2, 2, "0", "0", "交給我就放心……呼——", "あたしに任せ……て……ふぁ――", "0", "0", "交給我就放心……呼——", "0", "cv_odora_2", "0", "0"},
[430002] = {430002, 13000, 3, 3, "0", "0", "哇呼——你是誰？原來是領航，你好，我是歐朵啦。呼——", "ふぁ――あなた、誰？ナビゲーターだったのね。初めまして。あたしはオードラ。ふぁ――", "0", "0", "哇呼——你是誰？原來是領航，你好，我是歐朵啦。呼——", "0", "cv_odora_1", "0", "0"},
[430003] = {430003, 13000, 4, 4, "0", "idle", "明明睡眠很充足，為什麼長不高呢……領航有什麼長高的秘訣嗎？牛奶……露露啦也是這麼說的……好吧，相信你們……", "たっぷり寢てるのに、背が伸びないんだよね。何でだろう……ナビゲーターって、背を伸ばす秘訣とか何か知らない？ミルクか……ルルラもそう言ってたなあ……よし、あなたたちの言うことを信じようっと……", "0", "0", "明明睡眠很充足，為什麼長不高呢……領航有什麼長高的秘訣嗎？牛奶……露露啦也是這麼說的……好吧，相信你們……", "0", "cv_odora_3", "0", "0"},
[430004] = {430004, 13000, 5, 4, "0", "idle", "哼哼——哼哼——太陽出來啦～領航和我出去玩吧～露露啦說多曬太陽才能長高哇～", "ふふふん～ふんふん～♪お日様が出てきたよ、あたしと出かけて遊ぼ、ね、ナビゲーター。背を伸ばすにはひなたぼっこを沢山しないといけないってルルラも言ってたの。", "0", "0", "哼哼——哼哼——太陽出來啦～領航和我出去玩吧～露露啦說多曬太陽才能長高哇～", "0", "cv_odora_4", "0", "0"},
[430005] = {430005, 13000, 6, 4, "0", "idle", "肚子餓了……露露啦，你在哪~我肚子餓了~~~", "お腹空いた……ルルラ！どこにいるの、お腹空いたよ～……", "0", "0", "肚子餓了……露露啦，你在哪~我肚子餓了~~~", "0", "cv_odora_27", "0", "0"},
[430006] = {430006, 13000, 7, 5, "1_》_0_0.8", "level1", "歐朵啦……想一直和大家在一起。", "オードラは……みんなとずっと一緒にいたいもん。", "0", "0", "歐朵啦……想一直和大家在一起。", "0", "cv_odora_28", "0", "0"},
