[430101] = {430101, 13001, 2, 2, "0", "0", "這樣真的好嗎？不……我並不是在質疑您的判斷，非常抱歉！", "本當に、いいのですか？いいえ……あなた様の判斷を疑っているわけではありません。失禮しました！", "0", "0", "這樣真的好嗎？不……我並不是在質疑您的判斷，非常抱歉！", "0", "cv_furanka_2", "0", "0"},
[430102] = {430102, 13001, 3, 3, "0", "0", "您好，我的名字是弗蘭卡·芬奇，是今年新上任的駕駛員，很高興能夠見到您。", "こんにちは。私はフランカー・ヴィンチ、今年新任のドライバーです。會えて嬉しいです。", "0", "0", "您好，我的名字是弗蘭卡·芬奇，是今年新上任的駕駛員，很高興能夠見到您。", "0", "cv_furanka_1", "0", "0"},
[430103] = {430103, 13001, 4, 4, "0", "idle", "嗚……好緊張啊，還是第一次站在這裡……但是放心好了，我會努力做好的！", "う……緊張します。ここに立つのは初めてなので……で、でも、安心してください。私、頑張ります！", "0", "0", "嗚……好緊張啊，還是第一次站在這裡……但是放心好了，我會努力做好的！", "0", "cv_furanka_3", "0", "0"},
[430104] = {430104, 13001, 5, 4, "0", "idle", "多瑙支部的方舟離我家很近呢，有空的話要和大家一起來做客嗎？我會招待好大家的。", "ダニューブ支部の方舟は私の家に近いんですよ。時間があったら、みんな一緒にうちに來ませんか？ちゃんとおもてなししますから。", "0", "0", "多瑙支部的方舟離我家很近呢，有空的話要和大家一起來做客嗎？我會招待好大家的。", "0", "cv_furanka_4", "0", "0"},
[430105] = {430105, 13001, 6, 4, "0", "idle", "朱利烏斯學姐，領航還有查麗莎學姐……她們都是優秀的人。如果我能再接近你們一些的話，那就好了。", "ユリウス先輩、ナビゲーターさん、そしてチャリサー先輩……みなさん、優秀な方です。もっとみなさんに近づいていけたらいいなぁって思います。", "0", "0", "朱利烏斯學姐，領航還有查麗莎學姐……她們都是優秀的人。如果我能再接近你們一些的話，那就好了。", "0", "cv_furanka_27", "0", "0"},
[430106] = {430106, 13001, 7, 5, "1_》_0_0.8", "level1", "柔和的海風，美味的食物，還有……一群善良溫柔的人。這就是我成長的地方，也是我想要守護的東西。", "しなやかな潮風、美味しい食べ物、そして……優しい方々。ここは私の育った場所であり、私の守りたいものでもあるんです。", "0", "0", "柔和的海風，美味的食物，還有……一群善良溫柔的人。這就是我成長的地方，也是我想要守護的東西。", "0", "cv_furanka_28", "0", "0"},
[430107] = {430107, 13001, 8, 5, "1_》_0_0.8", "level1", "請…請不要開這種玩笑……", "こ、こんな冗談はやめてください……", "0", "0", "請…請不要開這種玩笑……", "0", "cv_furanka_5", "0", "0"},
[430108] = {430108, 13001, 9, 5, "1_》_100_1.5", "level2", "呼啊！——原……原來是領航啊。", "きゃっ！――ああ……ナビゲーターさんですか。", "0", "0", "呼啊！——原……原來是領航啊。", "0", "cv_furanka_6", "0", "0"},
[430109] = {430109, 13001, 10, 5, "1_》_500_2", "level3", "嘿嘿，已經不會被您嚇到了喔。", "うふふ、もう驚かされませんよ。", "0", "0", "嘿嘿，已經不會被您嚇到了哦。", "0", "cv_furanka_7", "0", "0"},
[430110] = {430110, 13001, 11, 5, "1_》_1000_2.5", "level4", "不知不覺中我們已經認識那麼久了嗎？如果領航您不介意的話，我可以請您喝杯茶嗎？有些話想要私下對您說…", "私たち、知り合ってからもうそんなに経つんですね。ナビゲーターさんさえよければ、一緒にお茶を飲みませんか？二人きりで話したいことがあって……", "0", "0", "不知不覺中我們已經認識那麼久了嗎？如果領航您不介意的話，我可以請您喝杯茶嗎？有些話想要私下對您說……", "0", "cv_furanka_8", "0", "0"},
[430111] = {430111, 13001, 12, 6, "0", "0", "欸？這些真的要給我嗎？", "えっ？本當に私にこれを？", "0", "0", "哎？這些真的要給我嗎？", "0", "cv_furanka_9", "0", "0"},
[430112] = {430112, 13001, 13, 7, "0", "0", "讓領航您費心了，謝謝！", "お気遣いありがとうございます、ナビゲーターさん！", "0", "0", "讓領航您費心了，謝謝！", "0", "cv_furanka_10", "0", "0"},
[430113] = {430113, 13001, 14, 8, "0", "0", "哇啊——快看啊領航，我也能夠做到了！", "わぁ――見てください、ナビゲーターさん！私もできるようになりました！", "0", "0", "哇啊——快看啊領航，我也能夠做到了！", "0", "cv_furanka_11", "0", "0"},
[430114] = {430114, 13001, 15, 9, "0", "0", "還要再努力些……", "もっと頑張らないと……", "0", "0", "還要再努力些……", "0", "cv_furanka_12", "0", "0"},
[430115] = {430115, 13001, 16, 10, "0", "0", "不會讓你們受傷的！", "怪我なんてさせません！", "0", "0", "不會讓你們受傷的！", "0", "cv_furanka_13", "0", "0"},
[430116] = {430116, 13001, 17, 11, "0", "0", "終於結束了，領航，我們平安回來了！", "やっと終わりましたね、ナビゲーターさん。無事に帰ってこれました！", "0", "0", "終於結束了，領航，我們平安回來了！", "0", "cv_furanka_14", "0", "0"},
[430117] = {430117, 13001, 18, 12, "0", "0", "啊哈哈，稍微有些失誤呢。", "あははは、えっと……ミスがちょっとありましたが、良いでしょう。", "0", "0", "啊哈哈，稍微有些失誤呢。", "0", "cv_furanka_15", "0", "0"},
[430118] = {430118, 13001, 19, 13, "0", "0", "終於……結束了，領航，我們回來了……", "やっと……終わりましたね、ナビゲーターさん。なんとか帰ってこれました……", "0", "0", "終於……結束了，領航，我們回來了……", "0", "cv_furanka_16", "0", "0"},
[430119] = {430119, 13001, 20, 14, "0", "0", "戰鬥……失敗……非常抱歉領航。欸？您說只要我們平安回來就好，但是……", "戦闘……失敗……すみません、ナビゲーターさん。え？無事に帰ってきたことが何より、ですか？でも……", "0", "0", "戰鬥……失敗……非常抱歉領航。哎？您說只要我們平安回來就好，但是……", "0", "cv_furanka_17", "0", "0"},
[430120] = {430120, 13001, 23, 16, "0", "0", "馬上就來！", "直ちに伺います！", "0", "0", "馬上就來！", "0", "cv_furanka_18", "0", "0"},
[430121] = {430121, 13001, 26, 19, "0", "0", "抱歉……大家……一定要堅持住啊。", "ごめんなさい……みんな……最後まで頑張って……", "0", "0", "抱歉……大家……一定要堅持住啊。", "0", "cv_furanka_19", "0", "0"},
[430122] = {430122, 13001, 27, 20, "0", "0", "好…好難為情啊……我的身材完全比不上兩位學姐……", "は、恥ずかしいですが……私のスタイル、先輩たちにはかないません……", "0", "0", "好…好難為情啊……我的身材完全比不上兩位學姐……", "0", "cv_furanka_20", "0", "0"},
[430123] = {430123, 13001, 28, 21, "0", "0", "嗯嗯，好舒服啊～", "ふぅ、気持ちいいです……", "0", "0", "嗯嗯，好舒服啊～", "0", "cv_furanka_21", "0", "0"},
[430124] = {430124, 13001, 29, 21, "0", "0", "領航，還沒有好嗎？", "まだですか？ナビゲーターさん。", "0", "0", "領航，還沒有好嗎？", "0", "cv_furanka_22", "0", "0"},
[430125] = {430125, 13001, 30, 22, "0", "0", "要開始了喔，加油！", "行きますよ？頑張ってくださいね！", "0", "0", "要開始了哦，加油！", "0", "cv_furanka_23", "0", "0"},
[430126] = {430126, 13001, 31, 23, "0", "0", "要來猜猜看嗎，領航？", "ナビゲーターさんも當ててみます？", "0", "0", "要來猜猜看嗎，領航？", "0", "cv_furanka_24", "0", "0"},
[430127] = {430127, 13001, 32, 24, "0", "0", "欸？領航居然能認出我嗎？", "えっ？私のこと、分かったのですか？", "0", "0", "哎？領航居然能認出我嗎？", "0", "cv_furanka_25", "0", "0"},
[430128] = {430128, 13001, 33, 25, "0", "0", "果然……不過這也是預料當中的結果吧。", "でも……想定內のことです。", "0", "0", "果然……不過這也是預料當中的結果吧。", "0", "cv_furanka_26", "0", "0"},
[430129] = {430129, 13001, 34, 26, "0", "0", "歡迎回來，我煮了些墨魚面，領航要來嘗嘗嗎？", "お帰りなさい。イカのパスタを作ったんです。ナビゲーターさんも食べてみます？", "0", "0", "歡迎回來，我煮了些墨魚面，領航要來嘗嘗嗎？", "0", "cv_furanka_29", "0", "0"},
[430130] = {430130, 13001, 35, 27, "0", "0", "無論過程是有多艱辛，我相信故事的最後一定會迎來一個讓大家都滿意的結局吧。", "どんなに大変なことがあったとしても、きっと、みんなが満足できるような結末を迎えられます。", "0", "0", "無論過程是有多艱辛，我相信故事的最後一定會迎來一個讓大家都滿意的結局吧。", "0", "cv_furanka_31", "0", "0"},
[430131] = {430131, 13001, 36, 28, "0", "0", "每天都要給自己定個目標才行呢。", "毎日の目標を作った方がいいですね。", "0", "0", "每天都要給自己定個目標才行呢。", "0", "cv_furanka_32", "0", "0"},
[430132] = {430132, 13001, 37, 29, "0", "0", "我也要努力追上大家才行呢。", "私も頑張ってみんなに追いつかないと。", "0", "0", "我也要努力追上大家才行呢。", "0", "cv_furanka_33", "0", "0"},
