[430234] = {430234, 13002, 39, 31, "0", "0", "裝備對戰鬥力的提升是不可忽視的。", "裝備は戦闘力を上げるのに必要なものですわ。", "0", "0", "裝備對戰鬥力的提升是不可忽視的。", "0", "cv_tina_34", "0", "0"},
[430235] = {430235, 13002, 40, 32, "0", "0", "採購的話，就交給我吧。", "買い付けなら、私にお任せください。", "0", "0", "採購的話，就交給我吧。", "0", "cv_tina_35", "0", "0"},
