[430301] = {430301, 13003, 2, 2, "0", "0", "喔！這就是所謂的上得廳堂下得廚房吧。", "おお、これがいわゆる、外でも働いて、家事も完璧ってやつね。", "0", "0", "哦！這就是所謂的上得廳堂下得廚房吧。", "0", "cv_kurimu_2", "0", "0"},
[430302] = {430302, 13003, 3, 3, "0", "0", "欸嘿嘿~李猴牙~我名字是克裏姆木木木木點科點塔諾夫~", "えへへ～こんにちは。あたしはクリム、ム…...ムムム、デ、ク……デ、タノーフ…...でぇ～す……～", "0", "0", "哎嘿嘿~李猴牙~我名字是克裡姆木木木木點科點塔諾夫~", "0", "cv_kurimu_1", "0", "0"},
[430303] = {430303, 13003, 4, 4, "0", "idle", "身為後勤卻總是偷吃？誰說的，那都是試毒，是試毒啦。當然我肯定不可能往菜裡下毒的。", "後方勤務のくせにいつもつまみ食いしてるって？ないない、あれは毒見だよ、毒見！まぁ、あたしは絶対、ご飯に毒なんか入れないからね。", "0", "0", "身為後勤卻總是偷吃？誰說的，那都是試毒，是試毒啦。當然我肯定不可能往菜裡下毒的。", "0", "cv_kurimu_3", "0", "0"},
[430304] = {430304, 13003, 5, 4, "0", "idle", "領航，聽說最近有個護送臘腸和熏肉的任務，不如我們一起去吧？！你看，我連喝的都準備好了。", "ナビゲーター、最近ソーセージとベーコンを護送するミッションがあるみたいだけど、一緒に行かない？ほら、あたし、飲み物も用意しといたよ。", "0", "0", "領航，聽說最近有個護送臘腸和熏肉的任務，不如我們一起去吧？！你看，我連喝的都準備好了。", "0", "cv_kurimu_4", "0", "0"},
[430305] = {430305, 13003, 6, 4, "0", "idle", "我說，你也是這麼覺得的吧，那個伊莉雅其實超級能喝但只是不想表現出來吧？！有機會的話一定要試一下她的……欸？我是被誰從後面提起來了嗎？", "ほらね！あんたもそう思うでしょ？――イリアって実はめっちゃ飲めるけど、下戸を裝ってるだけだって！いつか絶対彼女の……あれ？あたし、誰かに後ろから引っ張られてない？", "0", "0", "我說，你也是這麼覺得的吧，那個伊莉雅其實超級能喝但只是不想表現出來吧？！有機會的話一定要試一下她的……哎？我是被誰從後面提起來了嗎？", "0", "cv_kurimu_27", "0", "0"},
[430306] = {430306, 13003, 7, 5, "1_》_0_0.8", "level1", "卡佳人都能打過熊？開什麼玩笑啦，你都是從哪聽來的謠言啊？！", "カティア人が熊に勝てるって？何バカなこと言ってるの？それ、何処から聞いたデマなの？！", "0", "0", "卡佳人都能打過熊？開什麼玩笑啦，你都是從哪聽來的謠言啊？！", "0", "cv_kurimu_28", "0", "0"},
[430307] = {430307, 13003, 8, 5, "1_》_0_0.8", "level1", "我，我才沒有偷吃！請不要告訴伊莉雅姐姐啊！", "つ、つまみ食いしてないって！お願いだから、イリア姉さんに言わないで！", "0", "0", "我，我才沒有偷吃！請不要告訴伊莉雅姐姐啊！", "0", "cv_kurimu_5", "0", "0"},
[430308] = {430308, 13003, 9, 5, "1_》_100_1.5", "level2", "看來你已經上道了啊，以後不如這麼稱呼你吧，我的摯友~來為我們的友誼乾杯！", "段々分かってくれるようになったじゃん、これからは親友って呼んであげるよ。それじゃ、この友情のに、乾杯！", "0", "0", "看來你已經上道了啊，以後不如這麼稱呼你吧，我的摯友~來為我們的友誼乾杯！", "0", "cv_kurimu_6", "0", "0"},
[430309] = {430309, 13003, 10, 5, "1_》_500_2", "level3", "欸？領航……為什麼會有2個，3個，4個領航……欸呀呀，我是到天堂了嗎？", "え？ナビゲーター……なんで、ナビゲーターが二人も、三人も、四人もいるの……あれ？あたしって、天國にいるのかなー…...…？", "0", "0", "哎？領航……為什麼會有2個，3個，4個領航……哎呀呀，我是到天堂了嗎？", "0", "cv_kurimu_7", "0", "0"},
[430310] = {430310, 13003, 11, 5, "1_》_1000_2.5", "level4", "世界上還有很多沒法頓頓都吃飽的人，在我沒有加入艾吉斯前也是他們中的一員。但是我相信，如果只要你能堅持走下去的話，一定可以改變這一切吧。既然如此，我會一直陪在你的身邊，成為你最堅固的後盾。", "この世界にはね、飢えに苦しむ人々が沢山いるの。アイギスに加入するまでのあたしもそうだった。でも、前に進み続けるあんたなら、きっと全てのことを変えられる。あたしはそう信じてる。だから、あたしはずっと、あんたのそばにいて、あんたの一番の支持者で、理解者になるって決めたの。", "0", "0", "世界上還有很多沒法頓頓都吃飽的人，在我沒有加入艾吉斯前也是他們中的一員。但是我相信，如果只要你能堅持走下去的話，一定可以改變這一切吧。既然如此，我會一直陪在你的身邊，成為你最堅固的後盾。", "0", "cv_kurimu_8", "0", "0"},
[430311] = {430311, 13003, 12, 6, "0", "0", "Колбаса！", "カルバサー！", "0", "0", "Колбаса！", "0", "cv_kurimu_9", "0", "0"},
[430312] = {430312, 13003, 13, 7, "0", "0", "ура乾杯！", "ウラー！乾杯！", "0", "0", "ура乾杯！", "0", "cv_kurimu_10", "0", "0"},
[430313] = {430313, 13003, 14, 8, "0", "0", "終於到了最後的階段了啊，ура萬歲！真是件值得慶祝的事情，不如今晚我們一起去喝一杯吧？", "やっと最終段階に入ったのね。ウラー！萬歳！これはお祝いしなきゃ。今夜飲みに行かない？", "0", "0", "終於到了最後的階段了啊，ура萬歲！真是件值得慶祝的事情，不如今晚我們一起去喝一杯吧？", "0", "cv_kurimu_11", "0", "0"},
[430314] = {430314, 13003, 15, 9, "0", "0", "Борщ甜菜湯！", "ボルシチ！", "0", "0", "Борщ甜菜湯！", "0", "cv_kurimu_12", "0", "0"},
[430315] = {430315, 13003, 16, 10, "0", "0", "放心好了，我絕對不會偷吃的~", "安心して、絶対につまみ食いしないからさ。", "0", "0", "放心好了，我絕對不會偷吃的~", "0", "cv_kurimu_13", "0", "0"},
[430316] = {430316, 13003, 17, 11, "0", "0", "怎麼樣？我的後勤工作做得不錯吧。", "どう？あたしが擔當してる後方勤務。よくできたっしょ。", "0", "0", "怎麼樣？我的後勤工作做得不錯吧。", "0", "cv_kurimu_14", "0", "0"},
[430317] = {430317, 13003, 18, 12, "0", "0", "任務完成！該回去吃飯啦~", "ミッション完了！帰ってご飯、食べよ。", "0", "0", "任務完成！該回去吃飯啦~", "0", "cv_kurimu_15", "0", "0"},
[430318] = {430318, 13003, 19, 13, "0", "0", "下次再努力吧，只是一次小失誤而已啦，來吃點東西打起精神吧！", "また次頑張ればいいよ、ちょっとしたミスだけだし。何か美味しいものでも食べて、元気出してこ～！", "0", "0", "下次再努力吧，只是一次小失誤而已啦，來吃點東西打起精神吧！", "0", "cv_kurimu_16", "0", "0"},
[430319] = {430319, 13003, 20, 14, "0", "0", "唔啊啊，感覺頭暈暈的呢。", "あれ？なんか頭がクラクラするんだけど……", "0", "0", "唔啊啊，感覺頭暈暈的呢。", "0", "cv_kurimu_17", "0", "0"},
[430320] = {430320, 13003, 23, 16, "0", "0", "嘗嘗這個吧。", "これ、食べてみて。", "0", "0", "嘗嘗這個吧。", "0", "cv_kurimu_18", "0", "0"},
[430321] = {430321, 13003, 26, 19, "0", "0", "抱歉……後勤…要斷掉了啊。", "ごめんね……後方支援……できなくなっちゃう……", "0", "0", "抱歉……後勤…要斷掉了啊。", "0", "cv_kurimu_19", "0", "0"},
[430322] = {430322, 13003, 27, 20, "0", "0", "欸嘿嘿~要被你看光啦~", "ああっ！これじゃ全部見えちゃうじゃん！", "0", "0", "哎嘿嘿~要被你看光啦~", "0", "cv_kurimu_20", "0", "0"},
[430323] = {430323, 13003, 28, 21, "0", "0", "欸？原來艾吉斯的澡堂裡不能邊吃邊洗嗎？", "え？アイギスの浴場って食べながら入っちゃダメなの？", "0", "0", "哎？原來艾吉斯的澡堂裡不能邊吃邊洗嗎？", "0", "cv_kurimu_21", "0", "0"},
[430324] = {430324, 13003, 29, 21, "0", "0", "下次要不要往水箱裏參點威士卡呢？", "今度はバスタブの中にウイスキーを入れてみようかな～", "0", "0", "下次要不要往水箱裡參點威士卡呢？", "0", "cv_kurimu_22", "0", "0"},
[430325] = {430325, 13003, 30, 22, "0", "0", "這些算是……食物殘渣？！", "ここにあるのって……食べ殘し？！", "0", "0", "這些算是……食物殘渣？！", "0", "cv_kurimu_23", "0", "0"},
[430326] = {430326, 13003, 31, 23, "0", "0", "來吧，來吧~身為我的摯友你應該不會認錯人吧。", "さぁ、やろう。あたしの親友のあんたなら、間違えるはずないよね？", "0", "0", "來吧，來吧~身為我的摯友你應該不會認錯人吧。", "0", "cv_kurimu_24", "0", "0"},
[430327] = {430327, 13003, 32, 24, "0", "0", "ура萬歲！", "ウラー！萬歳！", "0", "0", "ура萬歲！", "0", "cv_kurimu_25", "0", "0"},
[430328] = {430328, 13003, 33, 25, "0", "0", "果然，喝酒誤事啊。", "あーあ、飲み過ぎってやっぱよくないよね。", "0", "0", "果然，喝酒誤事啊。", "0", "cv_kurimu_26", "0", "0"},
[430329] = {430329, 13003, 34, 26, "0", "0", "啊嗚啊嗚啊——", "もぐもぐ――", "0", "0", "啊嗚啊嗚啊——", "0", "cv_kurimu_29", "0", "0"},
[430330] = {430330, 13003, 35, 27, "0", "0", "真好啊，我也想成為故事的主角呢。", "いいなぁ、あたしも物語の主人公になってみたい。", "0", "0", "真好啊，我也想成為故事的主角呢。", "0", "cv_kurimu_31", "0", "0"},
[430331] = {430331, 13003, 36, 28, "0", "0", "ура！向著高處邁步吧！", "ウラー！高い所に向かって進もう！", "0", "0", "ура！向著高處邁步吧！", "0", "cv_kurimu_32", "0", "0"},
[430332] = {430332, 13003, 37, 29, "0", "0", "喔喔喔，這就是當老大的感覺吧。", "おお、これがリーダーになった気分なのかね。", "0", "0", "噢噢噢，這就是當老大的感覺吧。", "0", "cv_kurimu_33", "0", "0"},
[430333] = {430333, 13003, 38, 30, "0", "0", "欸呀呀，沒想到這麼快又要來新人了啊。", "へぇー、新人が入ってくるんだ。もうそんな時期なの？", "0", "0", "哎呀呀，沒想到這麼快又要來新人了啊。", "0", "cv_kurimu_34", "0", "0"},
[430334] = {430334, 13003, 39, 31, "0", "0", "隨便什麼裝備都行喔~", "どんな裝備でもいいよ。", "0", "0", "隨便什麼裝備都行哦~", "0", "cv_kurimu_35", "0", "0"},
[430335] = {430335, 13003, 40, 32, "0", "0", "順便買點香腸吧~", "ついでにソーセージも買っておこう。", "0", "0", "順便買點香腸吧~", "0", "cv_kurimu_36", "0", "0"},
[430336] = {430336, 13003, 41, 33, "0", "0", "欸呀呀，這是你的狗牌嗎？", "へぇ、これがあんたのドッグタグなの？", "0", "0", "哎呀呀，這是你的狗牌嗎？", "0", "cv_kurimu_37", "0", "0"},
[430337] = {430337, 13003, 42, 34, "0", "0", "隨便設定一下就好了吧。", "適當に設定すればいいんじゃない？", "0", "0", "隨便設置一下就好了吧。", "0", "cv_kurimu_38", "0", "0"},
[430338] = {430338, 13003, 43, 35, "0", "0", "會有人給我們寄香腸嗎？", "ソーセージを送ってくれる人はいるのかな？", "0", "0", "會有人給我們寄香腸嗎？", "0", "cv_kurimu_39", "0", "0"},
[430339] = {430339, 13003, 44, 36, "0", "0", "應該能遇到不少夥伴吧。", "きっと、沢山の仲間に出會えるよ。", "0", "0", "應該能遇到不少夥伴吧。", "0", "cv_kurimu_40", "0", "0"},
[430340] = {430340, 13003, 45, 37, "0", "0", "讓我按一下這個按鈕吧~", "このボタン、押させてー！", "0", "0", "讓我按一下這個按鈕吧~", "0", "cv_kurimu_41", "0", "0"},
[430400] = {430400, 13004, 1, 1, "0", "0", "蒼霧殘響。", "蒼霧殘響（ハツリバーブ）。", "0", "0", "蒼霧殘響。", "0", "cv_ayaka_30", "0", "0"},
[430401] = {430401, 13004, 2, 2, "0", "0", "瞭解！在下會一直站在這裡履行職責的！領航也千萬不要偷懶！", "瞭解！拙者、ここに立って使命を果たす！ナビゲーターも気を引き締めてくれ！", "0", "0", "瞭解！在下會一直站在這裡履行職責的！領航也千萬不要偷懶！", "0", "cv_ayaka_2", "0", "0"},
[430402] = {430402, 13004, 3, 3, "0", "0", "在下是新晉的醫療官-彩華！請下達任務吧，領航！", "拙者は新しく就任した醫療官、彩華！ミッションの指示を出してくれ、ナビゲーター！", "0", "0", "在下是新晉的醫療官-彩華！請下達任務吧，領航！", "0", "cv_ayaka_1", "0", "0"},
[430403] = {430403, 13004, 4, 4, "0", "idle", "領航！你的脖子酸痛嗎？在下精通針灸點穴，可以免費幫您物理矯正一下！", "首が痛いのか？拙者、鍼灸や點穴に精通している、無料で矯正してやろう。", "0", "0", "領航！你的脖子酸痛嗎？在下精通針灸點穴，可以免費幫您物理矯正一下！", "0", "cv_ayaka_3", "0", "0"},
[430404] = {430404, 13004, 5, 4, "0", "idle", "這幫可惡的傷患，就因為治療手段稍微特殊了點，居然私底下投訴在下。雖然很痛，但是效果絕對很好啊！", "もう……あいつら！治療方法がちょっと獨特だからって拙者にクレームをつけるなんて！確かに痛いけど、その分治療効果が高いのだぞ！", "0", "0", "這幫可惡的傷患，就因為治療手段稍微特殊了點，居然私底下投訴在下。雖然很痛，但是效果絕對很好啊！", "0", "cv_ayaka_4", "0", "0"},
[430405] = {430405, 13004, 6, 4, "0", "idle", "華戀那傢夥……腦子裏整天在想些奇怪的事情。有機會的話，在下一定要用針灸治好她的腦袋！", "華戀のやつ……可笑しなことばっかり考えて！いつか、鍼灸であの頭をどうにかしてやる！", "0", "0", "華戀那傢伙……腦子裡整天在想些奇怪的事情。有機會的話，在下一定要用針灸治好她的腦袋！", "0", "cv_ayaka_27", "0", "0"},
[430406] = {430406, 13004, 7, 5, "1_》_0_0.8", "level1", "在下的醫術，是家族歷代傳承的技藝。雖然現在已經落寞了，但是在下一定會重振家族榮光的！", "拙者の醫術は先祖に代々伝わる技術だ。今はもう、沒落してしまったが……いつかは必ず、先祖の栄光を取り戻す！", "0", "0", "在下的醫術，是家族歷代傳承的技藝。雖然現在已經落寞了，但是在下一定會重振家族榮光的！", "0", "cv_ayaka_28", "0", "0"},
[430407] = {430407, 13004, 8, 5, "1_》_0_0.8", "level1", "現在是工作時間，請不要胡鬧，領航。", "仕事中に感心せんな、ナビゲーター。", "0", "0", "現在是工作時間，請不要胡鬧，領航。", "0", "cv_ayaka_5", "0", "0"},
[430408] = {430408, 13004, 9, 5, "1_》_100_1.5", "level2", "領航……你難道對點穴有興趣嗎？", "ひょっとして、點穴に興味あるのか？", "0", "0", "領航……你難道對點穴有興趣嗎？", "0", "cv_ayaka_6", "0", "0"},
[430409] = {430409, 13004, 10, 5, "1_》_500_2", "level3", "領航，請允許在下為你示範正確的點穴方式吧——疼痛只是一瞬間的，馬上就結束了。", "拙者が正しい點穴のやり方の手本をお見せしよう――一瞬だけ痛みが走るが、すぐに終わる。", "0", "0", "領航，請允許在下為你示範正確的點穴方式吧——疼痛只是一瞬間的，馬上就結束了。", "0", "cv_ayaka_7", "0", "0"},
[430410] = {430410, 13004, 11, 5, "1_》_1000_2.5", "level4", "領航……如果你不介意的話，在下想請你作為在下的練習對象。欸？可以嗎？明明是工作時間……那麼，在下不客氣了！喝！", "もしよければ、拙者の練習相手になってくれるか？うえ？いいのか？仕事中なのに……では、失禮する！はっ！", "0", "0", "領航……如果你不介意的話，在下想請你作為在下的練習對象。誒？可以嗎？明明是工作時間……那麼，在下不客氣了！喝！", "0", "cv_ayaka_8", "0", "0"},
[430411] = {430411, 13004, 12, 6, "0", "0", "嗯，對於穴道的把握也更加精准了！", "ふむ、経穴をもっと正確に把握できるようになった！", "0", "0", "嗯，對於穴道的把握也更加精准了！", "0", "cv_ayaka_9", "0", "0"},
[430412] = {430412, 13004, 13, 7, "0", "0", "作為醫師的水準上升了。", "醫師としてのレベルが上がったぞ！", "0", "0", "作為醫師的水準上升了。", "0", "cv_ayaka_10", "0", "0"},
[430413] = {430413, 13004, 14, 8, "0", "0", "力量從身體裡不斷湧出……領航，從今往後請放心地將治療任務交予在下吧。", "體の中から力がどんどん湧いてくる……ナビゲーター、これからも安心して治療のことは拙者に任せてくれ。", "0", "0", "力量從身體裡不斷湧出……領航，從今往後請放心地將治療任務交予在下吧。", "0", "cv_ayaka_11", "0", "0"},
[430414] = {430414, 13004, 15, 9, "0", "0", "領航，治療的效果提升了呢。", "治療効果が上がったぞ。", "0", "0", "領航，治療的效果提升了呢。", "0", "cv_ayaka_12", "0", "0"},
[430415] = {430415, 13004, 16, 10, "0", "0", "作戰開始，請受傷的人來在下身邊。", "作戦開始。負傷した者は拙者の所へ。", "0", "0", "作戰開始，請受傷的人來在下身邊。", "0", "cv_ayaka_13", "0", "0"},
[430416] = {430416, 13004, 17, 11, "0", "0", "就像在下預計的那樣，無人傷亡，全殲敵人！", "拙者の予想通り、死傷者ゼロで敵を全滅！", "0", "0", "就像在下預計的那樣，無人傷亡，全殲敵人！", "0", "cv_ayaka_14", "0", "0"},
[430417] = {430417, 13004, 18, 12, "0", "0", "確認傷亡情況，受傷人員立即接受治療。", "死傷者の狀況を確認する。負傷した者はすぐ治療を受けるように！", "0", "0", "確認傷亡情況，受傷人員立即接受治療。", "0", "cv_ayaka_15", "0", "0"},
[430418] = {430418, 13004, 19, 13, "0", "0", "慘烈的勝利……下次在下會做得更好的。", "勝利したが大変だった……次はきっとうまくいく。", "0", "0", "慘烈的勝利……下次在下會做得更好的。", "0", "cv_ayaka_16", "0", "0"},
[430419] = {430419, 13004, 20, 14, "0", "0", "領航，請重整旗鼓，我們還有機會。", "気を取り直せ。チャンスはまだある。", "0", "0", "領航，請重整旗鼓，我們還有機會。", "0", "cv_ayaka_17", "0", "0"},
[430420] = {430420, 13004, 23, 16, "0", "0", "忍一下就好了！", "少しの辛抱だ！", "0", "0", "忍一下就好了！", "0", "cv_ayaka_18", "0", "0"},
[430421] = {430421, 13004, 26, 19, "0", "0", "果然……醫者不能自醫嗎……", "やっぱり……醫者は自分の病を治せない、か……", "0", "0", "果然……醫者不能自醫嗎……", "0", "cv_ayaka_19", "0", "0"},
[430422] = {430422, 13004, 27, 20, "0", "0", "呼……工作後立馬就去泡澡果然是最棒的，對吧，領航？", "ふぅ……仕事上がりの風呂はやっぱり最高だな！ナビゲーター。", "0", "0", "呼……工作後立馬就去泡澡果然是最棒的，對吧，領航？", "0", "cv_ayaka_20", "0", "0"},
[430423] = {430423, 13004, 28, 21, "0", "0", "熱浴的前後一段時間內都不能夠針灸，這是泡澡的唯一壞處呢。", "熱い風呂の前後は鍼灸を施せない。これが風呂の唯一の欠點だ。", "0", "0", "熱浴的前後一段時間內都不能夠針灸，這是泡澡的唯一壞處呢。", "0", "cv_ayaka_21", "0", "0"},
[430424] = {430424, 13004, 29, 21, "0", "0", "領航也很累了吧，在下可以給你按摩喔……欸？沒有那麼痛的，不要害怕啦。", "ナビゲーターも疲れただろう？拙者がマッサージしてやる……？え？そんなに痛くないぞ！怖がらなくていい。", "0", "0", "領航也很累了吧，在下可以給你按摩哦……誒？沒有那麼痛的，不要害怕啦。", "0", "cv_ayaka_22", "0", "0"},
[430425] = {430425, 13004, 30, 22, "0", "0", "領航，請提高警惕！", "十分気を付けるのだ！", "0", "0", "領航，請提高警惕！", "0", "cv_ayaka_23", "0", "0"},
[430426] = {430426, 13004, 31, 23, "0", "0", "決定了，猜錯的話，就用針讓領航的腦袋清醒過來！", "よし、外れたら鍼でナビゲーターの頭をはっきりさせよう。", "0", "0", "決定了，猜錯的話，就用針讓領航的腦袋清醒過來！", "0", "cv_ayaka_24", "0", "0"},
[430427] = {430427, 13004, 32, 24, "0", "0", "這是理所當然的結果，猜錯了的話就糟糕了。", "當たり前の結果だ。外れたら大変なことになっていたぞ。", "0", "0", "這是理所當然的結果，猜錯了的話就糟糕了。", "0", "cv_ayaka_25", "0", "0"},
[430428] = {430428, 13004, 33, 25, "0", "0", "領航，乖，不要怕，沒有你想像中那麼痛的。", "ナビゲーターはいいコだからな、怖がらなくていい。思っているほど痛くないぞ。", "0", "0", "領航，乖，不要怕，沒有你想像中那麼痛的。", "0", "cv_ayaka_26", "0", "0"},
[430429] = {430429, 13004, 34, 26, "0", "0", "領航，歡迎回來，要試一下在下的針灸嗎？", "ナビゲーター、お帰り。拙者の鍼灸を體験してみないか？", "0", "0", "領航，歡迎回來，要試一下在下的針灸嗎？", "0", "cv_ayaka_29", "0", "0"},
[430430] = {430430, 13004, 35, 27, "0", "0", "戰場上，一定有很多人在等待著治療……請下達指示吧！", "戦場には治療が必要な負傷者が沢山いるはず……指示を頼む！", "0", "0", "戰場上，一定有很多人在等待著治療……請下達指示吧！", "0", "cv_ayaka_31", "0", "0"},
[430431] = {430431, 13004, 36, 28, "0", "0", "只有通過實戰，技藝才能得到鍛煉！", "技術は実踐で鍛えられるものだ！", "0", "0", "只有通過實戰，技藝才能得到鍛煉！", "0", "cv_ayaka_32", "0", "0"},
[430432] = {430432, 13004, 37, 29, "0", "0", "讓在下看看，有誰需要治療~", "治療が必要なものがいないか、拙者に確認させてくれ。", "0", "0", "讓在下看看，有誰需要治療~", "0", "cv_ayaka_33", "0", "0"},
[430433] = {430433, 13004, 38, 30, "0", "0", "又有新的陪練人選了！", "新しい練習相手が來るということか！", "0", "0", "又有新的陪練人選了！", "0", "cv_ayaka_34", "0", "0"},
[430434] = {430434, 13004, 39, 31, "0", "0", "有在下想要的醫書嗎？", "拙者が探してる醫書はあるか？", "0", "0", "有在下想要的醫書嗎？", "0", "cv_ayaka_35", "0", "0"},
[430435] = {430435, 13004, 40, 32, "0", "0", "在下也想買點東西……", "拙者も買い物をしたいが……", "0", "0", "在下也想買點東西……", "0", "cv_ayaka_36", "0", "0"},
[430436] = {430436, 13004, 41, 33, "0", "0", "領航，讓在下檢查下你的脖子吧！", "ナビゲーター、拙者にその首をチェックさせよ！", "0", "0", "領航，讓在下檢查下你的脖子吧！", "0", "cv_ayaka_37", "0", "0"},
[430437] = {430437, 13004, 42, 34, "0", "0", "設定和點穴，感覺很像呢。", "設定と點穴ってなんか似てるよな。", "0", "0", "設置和點穴，感覺很像呢。", "0", "cv_ayaka_38", "0", "0"},
[430438] = {430438, 13004, 43, 35, "0", "0", "不要忘了看別人的信喔。", "屆いたメールをチェックするのを忘れるないよ。", "0", "0", "不要忘了看別人的信哦。", "0", "cv_ayaka_39", "0", "0"},
[430439] = {430439, 13004, 44, 36, "0", "0", "在下也想和這麼多人聊天呢！", "拙者もこのように沢山の人とチャットしてみたい！", "0", "0", "在下也想和這麼多人聊天呢！", "0", "cv_ayaka_40", "0", "0"},
[430440] = {430440, 13004, 45, 37, "0", "0", "還有要確認的事呢。", "確認が必要なことは他にもある。", "0", "0", "還有要確認的事呢。", "0", "cv_ayaka_41", "0", "0"},
[430500] = {430500, 13005, 1, 1, "0", "0", "蒼霧殘響", "0", "0", "0", "0", "0", "cv_genia_32", "0", "0"},
[430501] = {430501, 13005, 2, 2, "0", "0", "明白了，我會站在這裏監督您的工作的。", "0", "0", "0", "0", "0", "cv_genia_2", "0", "0"},
[430502] = {430502, 13005, 3, 3, "0", "0", "熱尼亞·李·紮伊采夫，擔任的職位是醫療官，治療的工作就交給我吧。", "0", "0", "0", "0", "0", "cv_genia_1", "0", "0"},
[430503] = {430503, 13005, 4, 4, "0", "idle", "莉迪亞…是的，我的確救過她的性命，但那次“奇跡”並不是因為我一個人而發生的。她那強烈到令人目眩，感到不可思議的求生意志才是關鍵。", "0", "0", "0", "0", "0", "cv_genia_29", "0", "0"},
[430504] = {430504, 13005, 5, 4, "0", "idle", "您問我累不累…和以前的工作比起來，站在這裏已經是一種休息了。", "0", "0", "0", "0", "0", "cv_genia_3", "0", "0"},
[430505] = {430505, 13005, 6, 4, "0", "idle", "呼…呼…啊，抱歉，因為太放鬆了，不小心睡著了，失禮了。", "0", "0", "0", "0", "0", "cv_genia_4", "0", "0"},
[430506] = {430506, 13005, 7, 5, "1_》_0_0.8", "level1", "如果不是奶奶的事…我大概不會想要去成為一名醫生吧。而之所以能夠一直堅持下來，大概是因為我不希望有人在自己眼前死去吧……", "0", "0", "0", "0", "0", "cv_genia_30", "0", "0"},
[430507] = {430507, 13005, 8, 5, "1_》_0_0.8", "level1", "怎麼了？需要我給您的腕管做切開手術嗎？", "0", "0", "0", "0", "0", "cv_genia_5", "0", "0"},
[430508] = {430508, 13005, 9, 5, "1_》_100_1.5", "level2", "不僅是確保您的生命安全，任何人的生命，我都有責任去守護。這就是醫生的職責。", "0", "0", "0", "0", "0", "cv_genia_6", "0", "0"},
[430509] = {430509, 13005, 10, 5, "1_》_500_2", "level3", "沒有人能逃過死亡的命運。但——我希望，像您這樣的人，能迎來安詳的，幸福的死。", "0", "0", "0", "0", "0", "cv_genia_7", "0", "0"},
[430510] = {430510, 13005, 11, 5, "1_》_1000_2.5", "level4", "生命的奇跡與凋零，我見證得足夠多了。今後，我也會一直以醫生的身份去戰鬥。領航，能與我同行嗎？", "0", "0", "0", "0", "0", "cv_genia_8", "0", "0"},
[430511] = {430511, 13005, 12, 6, "0", "0", "嗯，治療的效率提高了。", "0", "0", "0", "0", "0", "cv_genia_9", "0", "0"},
[430512] = {430512, 13005, 13, 7, "0", "0", "嗯？還有這種提升手段嗎？", "0", "0", "0", "0", "0", "cv_genia_10", "0", "0"},
[430513] = {430513, 13005, 14, 8, "0", "0", "那些為了結束戰爭而在拼命的戰士，需要人去保護他們。謝謝您，領航，給了我這份力量，我會把它用在正確的地方的。", "0", "0", "0", "0", "0", "cv_genia_11", "0", "0"},
[430514] = {430514, 13005, 15, 9, "0", "0", "醫療技術還在進步啊。", "0", "0", "0", "0", "0", "cv_genia_12", "0", "0"},
[430515] = {430515, 13005, 16, 10, "0", "0", "我來了，請各位放心戰鬥吧。", "0", "0", "0", "0", "0", "cv_genia_13", "0", "0"},
[430516] = {430516, 13005, 17, 11, "0", "0", "完美勝利？這不意味著沒有傷患，讓傷患過來接受治療。", "0", "0", "0", "0", "0", "cv_genia_14", "0", "0"},
[430517] = {430517, 13005, 18, 12, "0", "0", "負傷者，過來。", "0", "0", "0", "0", "0", "cv_genia_15", "0", "0"},
[430518] = {430518, 13005, 19, 13, "0", "0", "別沮喪了，先轉移傷患。", "0", "0", "0", "0", "0", "cv_genia_16", "0", "0"},
[430519] = {430519, 13005, 20, 14, "0", "0", "撤退！不要落下任何一個傷患！", "0", "0", "0", "0", "0", "cv_genia_17", "0", "0"},
[430520] = {430520, 13005, 23, 16, "0", "0", "可能會有點痛。", "0", "0", "0", "0", "0", "cv_genia_18", "0", "0"},
[430521] = {430521, 13005, 26, 19, "0", "0", "嘁，到此為止了啊……", "0", "0", "0", "0", "0", "cv_genia_19", "0", "0"},
[430522] = {430522, 13005, 24, 17, "0", "0", "上吧…別再受傷了。", "0", "0", "0", "0", "0", "cv_genia_20", "0", "0"},
[430523] = {430523, 13005, 25, 18, "0", "0", "我會拯救你的……即使代價是我的生命。", "0", "0", "0", "0", "0", "cv_genia_21", "0", "0"},
[430524] = {430524, 13005, 27, 20, "0", "0", "時刻保持身體的清潔，能有效預防疾病。", "0", "0", "0", "0", "0", "cv_genia_22", "0", "0"},
[430525] = {430525, 13005, 28, 21, "0", "0", "這個位置？從這裏切開兩英寸的小口，就能看見心臟瓣膜了噢。", "0", "0", "0", "0", "0", "cv_genia_23", "0", "0"},
[430526] = {430526, 13005, 29, 21, "0", "0", "我身上也有以前戰場上自己留下的手術痕跡呢…要摸摸看嗎？", "0", "0", "0", "0", "0", "cv_genia_24", "0", "0"},
[430527] = {430527, 13005, 30, 22, "0", "0", "提高警惕，不要受傷。", "0", "0", "0", "0", "0", "cv_genia_25", "0", "0"},
[430528] = {430528, 13005, 31, 23, "0", "0", "快點結束吧，我還有病歷要寫。", "0", "0", "0", "0", "0", "cv_genia_26", "0", "0"},
[430529] = {430529, 13005, 32, 24, "0", "0", "需要我給你一個獎勵的吻嗎…呵，當然是開玩笑的。", "0", "0", "0", "0", "0", "cv_genia_27", "0", "0"},
[430530] = {430530, 13005, 33, 25, "0", "0", "…沒有其他事的話，我先回去了。", "0", "0", "0", "0", "0", "cv_genia_28", "0", "0"},
[430531] = {430531, 13005, 34, 26, "0", "0", "您終於來了，領航，這是之前的工作總結，您過目一下吧。", "0", "0", "0", "0", "0", "cv_genia_31", "0", "0"},
[430532] = {430532, 13005, 35, 27, "0", "0", "前往戰場吧，那裏有人需要我們。", "0", "0", "0", "0", "0", "cv_genia_33", "0", "0"},
[430533] = {430533, 13005, 36, 28, "0", "0", "那麼，以全員無傷為挑戰目標吧。", "0", "0", "0", "0", "0", "cv_genia_34", "0", "0"},
[430534] = {430534, 13005, 37, 29, "0", "0", "沒有人生病吧？", "0", "0", "0", "0", "0", "cv_genia_35", "0", "0"},
[430535] = {430535, 13005, 38, 30, "0", "0", "我去給新人安排體檢。", "0", "0", "0", "0", "0", "cv_genia_36", "0", "0"},
[430536] = {430536, 13005, 39, 31, "0", "0", "我們需要最先進的醫療器械。", "0", "0", "0", "0", "0", "cv_genia_37", "0", "0"},
[430537] = {430537, 13005, 40, 32, "0", "0", "剛買的東西要記得消毒。", "0", "0", "0", "0", "0", "cv_genia_38", "0", "0"},
[430538] = {430538, 13005, 41, 33, "0", "0", "要時刻注意個人衛生。", "0", "0", "0", "0", "0", "cv_genia_39", "0", "0"},
[430539] = {430539, 13005, 42, 34, "0", "0", "準備是工作的一環。", "0", "0", "0", "0", "0", "cv_genia_40", "0", "0"},
[430540] = {430540, 13005, 43, 35, "0", "0", "別忘了整理郵件。", "0", "0", "0", "0", "0", "cv_genia_41", "0", "0"},
[430541] = {430541, 13005, 44, 36, "0", "0", "這裏是等候室嗎？", "0", "0", "0", "0", "0", "cv_genia_42", "0", "0"},
[430542] = {430542, 13005, 45, 37, "0", "0", "點點看吧。", "0", "0", "0", "0", "0", "cv_genia_43", "0", "0"},
[430600] = {430600, 13006, 1, 1, "0", "0", "蒼霧殘響。", "蒼霧殘響（ハツリバーブ）。", "0", "0", "蒼霧殘響。", "0", "cv_yincao_31", "0", "0"},
[430601] = {430601, 13006, 2, 2, "0", "0", "是！那麼，時薪是…什麼，沒有嗎？嘁——", "はぁい！じゃあ時給は……えぇ、でないの？ちぇ。", "0", "0", "是！那麼，時薪是…什麼，沒有嗎？嘁——", "0", "cv_yincao_2", "0", "0"},
[430602] = {430602, 13006, 3, 3, "0", "0", "我來了喔~心經屋的經紀人…不，心經屋的巫女，小瑩草，向你報導，領航。", "ナビゲーターちゃん、お待たせぇ。心経屋のマネージャー…じゃなかった、心経屋の巫女、蛍草ちゃんよぉ。", "0", "0", "我來了噢~心經屋的經紀人…不，心經屋的巫女，小瑩草，向你報導，領航。", "0", "cv_yincao_1", "0", "0"},
[430603] = {430603, 13006, 4, 4, "0", "idle", "瑩草姐？討厭啦，是小瑩草才對。下次再叫錯的話…你會死喔？", "蛍草姉さん？やあねえ。蛍草ちゃん、だよ。次に呼び間違えたら…死んじゃうかもよぉ？", "0", "0", "瑩草姐？討厭啦，是小瑩草才對。下次再叫錯的話…你會死噢？", "0", "cv_yincao_3", "0", "0"},
[430604] = {430604, 13006, 5, 4, "0", "idle", "在現代社會，只要經受過培訓，任何人都能成為巫女——領航想試試看嗎，我給你備好巫女服了。", "今はちょっと研修を受ければ、誰でも巫女になれるの。ナビゲーターちゃんはどう？あなたの分の巫女裝束も用意してあるのよぉ。", "0", "0", "在現代社會，只要經受過培訓，任何人都能成為巫女——領航想試試看嗎，我給你備好巫女服了。", "0", "cv_yincao_4", "0", "0"},
[430605] = {430605, 13006, 6, 4, "0", "idle", "領航，你的臉色很難看喔——花語剛剛看到我們了？唔嗯…被她看見了的話，就麻煩了，是不是先預定一下床位比較好？", "ナビゲーターちゃん、顔色が悪いわよ？……私たちが一緒にいるところを花語（はなことば）に見られたの？うーん……今のうちに病院のベッドの予約、しておいたらぁ？", "0", "0", "領航，你的臉色很難看噢——花語剛剛看到我們了？唔嗯…被她看見了的話，就麻煩了，是不是先預定一下床位比較好？", "0", "cv_yincao_28", "0", "0"},
[430606] = {430606, 13006, 7, 5, "1_》_0_0.8", "level1", "溫柔地引領迷茫之人，點亮前進道路的燈……大概，我沒辦法成為這樣的巫女。不過，我所守護那名少女一定…領航，你能幫我嗎？", "迷える人をそっと導いて、道を照らす燈りになる。……多分私はそんな巫女にはなれないと思うの。でも、私が守ったあの少女ならきっと……。ナビゲーターちゃん、お願い。力を貸してね。", "0", "0", "溫柔地引領迷茫之人，點亮前進道路的燈……大概，我沒辦法成為這樣的巫女。不過，我所守護那名少女一定…領航，你能幫我嗎？", "0", "cv_yincao_29", "0", "0"},
[430607] = {430607, 13006, 8, 5, "1_》_0_0.8", "level1", "嗯？喔，我正在算這個月的收支。", "なに？ああ、今月の収支を計算していたところよぉ。", "0", "0", "嗯？噢，我正在算這個月的收支。", "0", "cv_yincao_5", "0", "0"},
[430608] = {430608, 13006, 9, 5, "1_》_100_1.5", "level2", "居然有人說巫女只要微笑迎客就行了…別小看巫女這個職業啊！打掃衛生、朝拜神社、主持典禮，還要練習舞蹈…可沒想像中那麼輕鬆。", "巫女なんてニコニコしてれば何とかなるって言う人がいるけど……舐めないでほしいわ！神社の掃除に參拝者への対応、祭祀の補助に舞の練習……みんなが思っているほど楽じゃないのよぉ。", "0", "0", "居然有人說巫女只要微笑迎客就行了…別小看巫女這個職業啊！打掃衛生、朝拜神社、主持典禮，還要練習舞蹈…可沒想像中那麼輕鬆。", "0", "cv_yincao_6", "0", "0"},
[430609] = {430609, 13006, 10, 5, "1_》_500_2", "level3", "我和想像中的巫女不一樣？領航，平安年代之後，巫女被賦予沉重意義的時代也就結束了…“可靠”，呵呵，我就當做誇獎收下了。", "想像してた巫女とは違う？ナビゲーターちゃん、平安時代と今では、巫女が與えられた役割が違うのよ。……頼もしい？フフ、もったいない言葉だわぁ。", "0", "0", "我和想像中的巫女不一樣？領航，平安年代之後，巫女被賦予沉重意義的時代也就結束了…“可靠”，呵呵，我就當做誇獎收下了。", "0", "cv_yincao_7", "0", "0"},
[430610] = {430610, 13006, 11, 5, "1_》_1000_2.5", "level4", "“夢想”、“理想”、“願望”之類的，我已經很久沒有說過這種話了。不過…心紙，還有領航，你們卻應該去追逐它們。請放心地翱翔吧，其他的交給我來處理吧。", "夢とか理想とか願いなんて、私には遠い思い出よ。でも…心紙ちゃんやナビゲーターちゃんには、まだそういったものを追いかけてほしいの。他のことは私に任せて、安心して前に進んでちょうだい。", "0", "0", "“夢想”、“理想”、“願望”之類的，我已經很久沒有說過這種話了。不過…心紙，還有領航，你們卻應該去追逐它們。請放心地翱翔吧，其他的交給我來處理吧。", "0", "cv_yincao_8", "0", "0"},
[430611] = {430611, 13006, 12, 6, "0", "0", "謝謝惠顧~", "毎度ありがとうございまぁす。", "0", "0", "謝謝惠顧~", "0", "cv_yincao_9", "0", "0"},
[430612] = {430612, 13006, 13, 7, "0", "0", "要好好算下收益呢。", "収益はしっかり計算しないとね。", "0", "0", "要好好算下收益呢。", "0", "cv_yincao_10", "0", "0"},
[430613] = {430613, 13006, 14, 8, "0", "0", "現在的我，似乎能聽見神明的聲音…那是不可能的啦。畢竟，我並不是“真正的巫女”吧。不過，雖然聽不見神靈的聲音，但我能聽見你的聲音，領航。", "今、神様の聲が聞こえた気が……なんて、そんな訳ないよね。私は本物の巫女じゃないんだから。でもね、ナビゲーターちゃん。神様の聲は聞こえなくても、君の聲は聞こえるわよ。", "0", "0", "現在的我，似乎能聽見神明的聲音…那是不可能的啦。畢竟，我並不是“真正的巫女”吧。不過，雖然聽不見神靈的聲音，但我能聽見你的聲音，領航。", "0", "cv_yincao_11", "0", "0"},
[430614] = {430614, 13006, 15, 9, "0", "0", "我會加油的~", "私、頑張るわぁ。", "0", "0", "我會加油的~", "0", "cv_yincao_12", "0", "0"},
[430615] = {430615, 13006, 16, 10, "0", "0", "不乖的傢夥在哪裡呢~", "悪い子はどこかなぁ？", "0", "0", "不乖的傢伙在哪裡呢~", "0", "cv_yincao_13", "0", "0"},
[430616] = {430616, 13006, 17, 11, "0", "0", "打掃戰場，記得回收貴重物品。", "戦場をきれいにして、貴重品の回収も忘れずにねぇ。", "0", "0", "打掃戰場，記得回收貴重物品。", "0", "cv_yincao_14", "0", "0"},
[430617] = {430617, 13006, 18, 12, "0", "0", "遺憾也是一種美，別在意別在意。", "後悔することも大事な経験よぉ。気にしない気にしない。", "0", "0", "遺憾也是一種美，別在意別在意。", "0", "cv_yincao_15", "0", "0"},
[430618] = {430618, 13006, 19, 13, "0", "0", "傷患就交給我來照顧吧。", "ケガした人のお世話は私に任せて。", "0", "0", "傷患就交給我來照顧吧。", "0", "cv_yincao_16", "0", "0"},
[430619] = {430619, 13006, 20, 14, "0", "0", "搞砸了…得想辦法彌補…總之，先暫時撤退吧。", "やっちゃった……なんとかしないと…とりあえず、一旦撤退ね。", "0", "0", "搞砸了…得想辦法彌補…總之，先暫時撤退吧。", "0", "cv_yincao_17", "0", "0"},
[430620] = {430620, 13006, 23, 16, "0", "0", "嗯…嗯…我揮！", "よっ…こい…しょっ！", "0", "0", "嗯…嗯…我揮！", "0", "cv_yincao_18", "0", "0"},
[430621] = {430621, 13006, 26, 19, "0", "0", "稍微…休息一下……", "少し…休むわね……", "0", "0", "稍微…休息一下……", "0", "cv_yincao_19", "0", "0"},
[430622] = {430622, 13006, 24, 17, "0", "0", "我可是專業的。", "こう見えてプロなのよぉ！", "0", "0", "我可是專業的。", "0", "cv_yincao_20", "0", "0"},
[430623] = {430623, 13006, 27, 20, "0", "0", "這件巫女服，脫下來可能比你想像中要麻煩喔。", "この巫女裝束、君が思ってるより脫ぎにくいのよ。", "0", "0", "這件巫女服，脫下來可能比你想像中要麻煩噢。", "0", "cv_yincao_21", "0", "0"},
[430624] = {430624, 13006, 28, 21, "0", "0", "嗚哈——酸痛感全部消失了，領航，你不來試試嗎？", "うはぁ……肩や腰がラクになったわぁ。ナビゲーターちゃんも試してみない？", "0", "0", "嗚哈——酸痛感全部消失了，領航，你不來試試嗎？", "0", "cv_yincao_22", "0", "0"},
[430625] = {430625, 13006, 29, 21, "0", "0", "差不多該準備工作了，也不能一直在這裡偷懶吧。", "そろそろ仕事に戻らなきゃね。ずっとここでサボってるのもマズいしぃ。", "0", "0", "差不多該準備工作了，也不能一直在這裡偷懶吧。", "0", "cv_yincao_23", "0", "0"},
[430626] = {430626, 13006, 30, 22, "0", "0", "是“吉簽”呢？還是“凶簽”呢？", "吉かな？それとも凶かなぁ？", "0", "0", "是“吉簽”呢？還是“凶簽”呢？", "0", "cv_yincao_24", "0", "0"},
[430627] = {430627, 13006, 31, 23, "0", "0", "猜錯的話，就把你釘在神木上喔~", "間違えたら、ご神木に磔の刑よぉ。", "0", "0", "猜錯的話，就把你釘在神木上哦~", "0", "cv_yincao_25", "0", "0"},
[430628] = {430628, 13006, 32, 24, "0", "0", "恭喜，這是我親手做的禦守，收下吧~", "おめでとう！手作りのお守りよ。受け取ってねぇ。", "0", "0", "恭喜，這是我親手做的禦守，收下吧~", "0", "cv_yincao_26", "0", "0"},
[430629] = {430629, 13006, 33, 25, "0", "0", "傷腦筋，沒有神木的話，就釘在床上吧~", "困ったわねぇ。ご神木がダメなら、ベットに磔の刑かなぁ。", "0", "0", "傷腦筋，沒有神木的話，就釘在床上吧~", "0", "cv_yincao_27", "0", "0"},
[430630] = {430630, 13006, 34, 26, "0", "0", "領航，你來了呀。我正在打掃衛生，稍等一下喔。", "ナビゲーターちゃん、いらっしゃい。いま掃除しているから、ちょっと待ってねぇ。", "0", "0", "領航，你來了呀。我正在打掃衛生，稍等一下噢。", "0", "cv_yincao_30", "0", "0"},
[430631] = {430631, 13006, 35, 27, "0", "0", "我聽見了樂器奏出的樂曲…領航，你的故事要開始了呢。", "楽器の音色が聞こえる……ナビゲーターちゃんの物語が始まるのね。", "0", "0", "我聽見了樂器奏出的樂曲…領航，你的故事要開始了呢。", "0", "cv_yincao_32", "0", "0"},
[430632] = {430632, 13006, 36, 28, "0", "0", "額外任務，要多付工資呢。", "殘業手當が付くのよね？", "0", "0", "額外任務，要多付工資呢。", "0", "cv_yincao_33", "0", "0"},
[430633] = {430633, 13006, 37, 29, "0", "0", "大家要好好相處，不要吵架喔。", "みんなは仲良く、喧嘩しないでねぇ。", "0", "0", "大家要好好相處，不要吵架哦。", "0", "cv_yincao_34", "0", "0"},
[430634] = {430634, 13006, 38, 30, "0", "0", "我會為你向神明祈禱好運的~", "君の幸運を神様にお祈りするわねぇ。", "0", "0", "我會為你向神明祈禱好運的~", "0", "cv_yincao_35", "0", "0"},
[430635] = {430635, 13006, 39, 31, "0", "0", "願你抽中想要的簽~", "良い物が當たりますように。", "0", "0", "願你抽中想要的簽~", "0", "cv_yincao_36", "0", "0"},
[430636] = {430636, 13006, 40, 32, "0", "0", "嗯…價格可以作為參考……", "へえぇ。この値段は參考になるわぁ。", "0", "0", "嗯…價格可以作為參考……", "0", "cv_yincao_37", "0", "0"},
[430637] = {430637, 13006, 41, 33, "0", "0", "有考慮過當巫女嗎？", "巫女になってみない？", "0", "0", "有考慮過當巫女嗎？", "0", "cv_yincao_38", "0", "0"},
[430638] = {430638, 13006, 42, 34, "0", "0", "繁瑣的準備工作……", "こういうの、結構大変ねぇ。", "0", "0", "繁瑣的準備工作……", "0", "cv_yincao_39", "0", "0"},
[430639] = {430639, 13006, 43, 35, "0", "0", "有客人要預約嗎？", "ご予約のお客様はいらっしゃいますかぁ？", "0", "0", "有客人要預約嗎？", "0", "cv_yincao_40", "0", "0"},
[430640] = {430640, 13006, 44, 36, "0", "0", "大家排隊發言~", "みんな、順番に発言してねぇ。", "0", "0", "大家排隊發言~", "0", "cv_yincao_41", "0", "0"},
[430641] = {430641, 13006, 45, 37, "0", "0", "嗯？", "あらぁ？", "0", "0", "嗯？", "0", "cv_yincao_42", "0", "0"},
[430700] = {430700, 13007, 1, 1, "0", "0", "蒼霧殘響", "蒼霧殘響（ハツリバーブ）。", "0", "0", "0", "0", "cv_Ttype_31", "0", "0"},
[430701] = {430701, 13007, 2, 2, "0", "0", "收到，現在開始執行您的命令語句。", "コマンド、承りました。直ちに執行します。", "0", "0", "0", "0", "cv_Ttype_2", "0", "0"},
[430702] = {430702, 13007, 3, 3, "0", "0", "——人臉圖像識別完畢，初次見面，您就是“領航”吧。試作機T型，向您報導。", "はじめまして、ナビゲーター。試作機Ｔ型、ただいま著任いたしました。", "0", "0", "0", "0", "cv_Ttype_1", "0", "0"},
[430703] = {430703, 13007, 4, 4, "0", "idle", "領航，如您所知，我的一切行動都是基於對人類行為地模仿與學習。", "ご承知の通り、私の行動はすべて人間の行為への模倣や學習に基づくものです。", "0", "0", "0", "0", "cv_Ttype_3", "0", "0"},
[430704] = {430704, 13007, 5, 4, "0", "idle", "我很好奇，我想學習“人類”的知識，想知道人類為什麼創造了“我”。", "好奇心が私を駆り立てています。人間の知識と、なぜ、私を作ったかを知りたいのです。", "0", "0", "0", "0", "cv_Ttype_4", "0", "0"},
[430705] = {430705, 13007, 6, 4, "0", "idle", "領航，我想要從這裏出去…想要…去見那個人。達…芙…達芙妮？是這個名字嗎？記憶…錯誤……", "ナビゲーター、私はここから出たい…あの人に…會いたいんです。ダ…プ…ネー？この名前であっていますか？メ…メモリー…エラー……", "0", "0", "0", "0", "cv_Ttype_28", "0", "0"},
[430706] = {430706, 13007, 7, 5, "1_》_0_0.8", "level1", "您知道嗎？我的晶片複寫了某位英雄的記憶……在那段記憶中，似乎有您的身影。沒錯，在很深很很深的記憶深處，有您的…身影。", "ご存知でしょうか？私のチップにはある英雄の記憶の複寫があるのです……そしてその記憶の中には、あなたの姿があるようなのです。そう、深い深い記憶の底に……あなたの姿が。", "0", "0", "0", "0", "cv_Ttype_29", "0", "0"},
[430707] = {430707, 13007, 8, 5, "1_》_0_0.8", "level1", "識別指紋——領航，怎麼了？", "指紋認証。……どうかなさいましたか、ナビゲーター？", "0", "0", "0", "0", "cv_Ttype_5", "0", "0"},
[430708] = {430708, 13007, 9, 5, "1_》_100_1.5", "level2", "肢體觸摸是人類釋放友好信號的方式…學習完畢", "スキンシップは人間がお互いに友好のサインを送る方法…ラーニング完了。", "0", "0", "0", "0", "cv_Ttype_6", "0", "0"},
[430709] = {430709, 13007, 10, 5, "1_》_500_2", "level3", "我的人格數據並不是來自人類——不過，想要學習人類的想法，並不是虛假的。我想成為，像領航一樣的“人類”。", "私の人格データは人間からのものではないのですが……人間を學びたいのは偽りではありません。私は、ナビゲーターのような、人間になりたいのです。", "0", "0", "0", "0", "cv_Ttype_7", "0", "0"},
[430710] = {430710, 13007, 11, 5, "1_》_1000_2.5", "level4", "我是沒有“心”的機器。即便是情感，也不過是通過演算法與邏輯程式展現出的“臨摹”……本來應該是這樣的，但，領航，您讓我擁有了“心”。", "私は、心のない機械です。感情でさえも、アルゴリズムや論理プログラミングによるタダの模倣。……ですが、ナビゲーターが私に、心を持たせてくれました。", "0", "0", "0", "0", "cv_Ttype_8", "0", "0"},
[430711] = {430711, 13007, 12, 6, "0", "0", "性能提升。", "フォーマンスアップグレード。", "0", "0", "0", "0", "cv_Ttype_9", "0", "0"},
[430712] = {430712, 13007, 13, 7, "0", "0", "系統模組更新。", "システムモジュールアップデート。", "0", "0", "0", "0", "cv_Ttype_10", "0", "0"},
[430713] = {430713, 13007, 14, 8, "0", "0", "被造物無論如何努力，也無法突破自身的限制。可是…我想突破這個限制，我想…成為人類，領航。", "作られたものはいくら努力しても自身のリミットを突破することができません。なのに私は…この限界を超えたい。……ナビゲーター、私は人間になりたい。", "0", "0", "0", "0", "cv_Ttype_11", "0", "0"},
[430714] = {430714, 13007, 15, 9, "0", "0", "學習完畢。", "ラーニング完了。", "0", "0", "0", "0", "cv_Ttype_12", "0", "0"},
[430715] = {430715, 13007, 16, 10, "0", "0", "已啟動支援模式。", "サポートモードに移ります。", "0", "0", "0", "0", "cv_Ttype_13", "0", "0"},
[430716] = {430716, 13007, 17, 11, "0", "0", "任務成功，請為這次行動打分，領航。", "ミッションコンプリート。今回の行動に採點を、ナビゲーター。", "0", "0", "0", "0", "cv_Ttype_14", "0", "0"},
[430717] = {430717, 13007, 18, 12, "0", "0", "任務成功，我會繼續學習人類駕駛員的思維方式的。", "ミッションコンプリート。引き続き、人間パイロットの思考パターンを學びます。", "0", "0", "0", "0", "cv_Ttype_15", "0", "0"},
[430718] = {430718, 13007, 19, 13, "0", "0", "領航，我需要學習的東西還有很多。", "ナビゲーター、私はまだまだ勉強不足のようです。", "0", "0", "0", "0", "cv_Ttype_16", "0", "0"},
[430719] = {430719, 13007, 20, 14, "0", "0", "作戰——失敗，現在開始撤退。", "作戦、失敗……撤退します。", "0", "0", "0", "0", "cv_Ttype_17", "0", "0"},
[430720] = {430720, 13007, 23, 16, "0", "0", "強化支援，啟動。", "強化サポート、開始。", "0", "0", "0", "0", "cv_Ttype_18", "0", "0"},
[430721] = {430721, 13007, 26, 19, "0", "0", "運作…終止。", "オペレーション…停止。", "0", "0", "0", "0", "cv_Ttype_19", "0", "0"},
[430722] = {430722, 13007, 24, 17, "0", "0", "敵人數據，已解析。", "敵データ、解析完了。", "0", "0", "0", "0", "cv_Ttype_20", "0", "0"},
[430723] = {430723, 13007, 25, 18, "0", "0", "我還想知道更多。", "これがお前の宿命だ。", "0", "0", "0", "0", "cv_Ttype_43", "0", "0"},
[430724] = {430724, 13007, 27, 20, "0", "0", "這算是“修理”的一種嗎？", "これは、修理の一種でしょうか？", "0", "0", "0", "0", "cv_Ttype_21", "0", "0"},
[430725] = {430725, 13007, 28, 21, "0", "0", "人類似乎很享受這樣的行為，我不能理解。", "この行為、人間にとっては悅楽のようですが、私には理解できません。", "0", "0", "0", "0", "cv_Ttype_22", "0", "0"},
[430726] = {430726, 13007, 29, 21, "0", "0", "電路接觸不良，正在重啟…重啟失敗，自毀程式啟動…呵呵，嚇到您了嗎？", "回路接觸不良、再起動します…再起動失敗、自滅プログラム起動…フフ、ビックリしましたか？", "0", "0", "0", "0", "cv_Ttype_23", "0", "0"},
[430727] = {430727, 13007, 30, 22, "0", "0", "我已為您備好應對方案。", "対策の準備は完了しました。", "0", "0", "0", "0", "cv_Ttype_24", "0", "0"},
[430728] = {430728, 13007, 31, 23, "0", "0", "問答環節。", "質問コーナーです。", "0", "0", "0", "0", "cv_Ttype_25", "0", "0"},
[430729] = {430729, 13007, 32, 24, "0", "0", "真不愧是您，出色的判斷力。", "流石です、素晴らしい判斷力です。", "0", "0", "0", "0", "cv_Ttype_26", "0", "0"},
[430730] = {430730, 13007, 33, 25, "0", "0", "…程式出錯…關機中。", "…システムエラー…シャットダウン中。", "0", "0", "0", "0", "cv_Ttype_27", "0", "0"},
[430731] = {430731, 13007, 34, 26, "0", "0", "探測到生物體登入，開始進行聲音、指紋、人臉識別——啊，是領航您啊，歡迎回來。", "生命體のログインを探知。音聲、指紋及び顔を認証。……あっ、おかえりなさいませ、ナビゲーター。", "0", "0", "0", "0", "cv_Ttype_30", "0", "0"},
[430732] = {430732, 13007, 35, 27, "0", "0", "已切換至記錄模式。", "記録モードに切り替わりました。", "0", "0", "0", "0", "cv_Ttype_32", "0", "0"},
[430733] = {430733, 13007, 36, 28, "0", "0", "已切換至戰鬥模式，隨時可以出發。", "戦闘モードに切り替わりました、発進準備完了。", "0", "0", "0", "0", "cv_Ttype_33", "0", "0"},
[430734] = {430734, 13007, 37, 29, "0", "0", "未感知到可疑生命體。", "未登録生命體感知なし。", "0", "0", "0", "0", "cv_Ttype_34", "0", "0"},
[430735] = {430735, 13007, 38, 30, "0", "0", "正在登記新的友軍單位。", "新規友軍単位登録中。", "0", "0", "0", "0", "cv_Ttype_35", "0", "0"},
[430736] = {430736, 13007, 39, 31, "0", "0", "開始生產裝備——", "裝備製造中。", "0", "0", "0", "0", "cv_Ttype_36", "0", "0"},
[430737] = {430737, 13007, 40, 32, "0", "0", "採購中。", "買い出し中。", "0", "0", "0", "0", "cv_Ttype_37", "0", "0"},
[430738] = {430738, 13007, 41, 33, "0", "0", "已更新圖像數據。", "畫像データを更新しました。", "0", "0", "0", "0", "cv_Ttype_38", "0", "0"},
[430739] = {430739, 13007, 42, 34, "0", "0", "設置參數中——", "パラメーター設置中。", "0", "0", "0", "0", "cv_Ttype_39", "0", "0"},
[430740] = {430740, 13007, 43, 35, "0", "0", "掃描完畢，無危險物。", "スキャン完了、危険物なし。", "0", "0", "0", "0", "cv_Ttype_40", "0", "0"},
[430741] = {430741, 13007, 44, 36, "0", "0", "已備份至資料庫。", "データベースにバックアップしました。", "0", "0", "0", "0", "cv_Ttype_41", "0", "0"},
[430742] = {430742, 13007, 45, 37, "0", "0", "連接中——", "接続中。", "0", "0", "0", "0", "cv_Ttype_42", "0", "0"},
[430800] = {430800, 13008, 1, 1, "0", "0", "蒼霧殘響", "蒼霧殘響（ハツリバーブ）。", "0", "0", "0", "0", "cv_izabera_32", "0", "0"},
[430801] = {430801, 13008, 2, 2, "0", "0", "嗯，我知道了。", "うむ。承知した。", "0", "0", "0", "0", "cv_izabera_2", "0", "0"},
[430802] = {430802, 13008, 3, 3, "0", "0", "伊莎貝拉，我的名字是伊莎貝拉。我是被上天選中的，註定要踏入戰場的人。", "イザベラ。我が名はイザベラ。天に選ばれ、戦場に立つ運命を背負う者だ。", "0", "0", "0", "0", "cv_izabera_1", "0", "0"},
[430803] = {430803, 13008, 4, 4, "0", "idle", "光是站在這裏真的好嗎？不，還請不要在意，我確實是有些急躁了，還請按照你的節奏來吧。", "ここに立っているだけでいいのか？……いや、何でもない。いささか急ぎ過ぎかもしれんな。貴公のペースで行こう。", "0", "0", "0", "0", "cv_izabera_3", "0", "0"},
[430804] = {430804, 13008, 5, 4, "0", "idle", "領航，聽說你有半夜去甲板上的習慣？正好，下次還請叫上我一起吧。哎？不是去看星星嗎？", "ナビゲーター、夜、甲板へ行く習慣があると聞いたが、本當か？では、次は私も誘ってくれないだろうか。……え？星を見るためではないのか？", "0", "0", "0", "0", "cv_izabera_4", "0", "0"},
[430805] = {430805, 13008, 6, 4, "0", "idle", "查麗莎·德·羅蘭小姐，我們又見面了啊，沒想到自從那次分別過後已經過了這麼久了。", "チャリサー・ド・ロラン。また會ったな。長い時を経てこうして再會することになるとは、思いもしなかった。", "0", "0", "0", "0", "cv_izabera_29", "0", "0"},
[430806] = {430806, 13008, 7, 5, "1_》_0_0.8", "level1", "每個人的命運都是寫死的，如果與之背道而行那必然會迎來最差的結果……身為人的我們，只要順從自己的命運就好。", "全ての運命は定められ、逆らえば最悪の結末にたどり著く。人の身である我々は、運命に従うしかないのだ。", "0", "0", "0", "0", "cv_izabera_5", "0", "0"},
[430807] = {430807, 13008, 8, 5, "1_》_0_0.8", "level1", "嗯，我就在這裏領航，如果在戰場您找不到我的話就請仰頭看看天空吧。", "おーい、ナビゲーター。私はここだ。戦場でも私を見失ったら、空を見上げるといい。", "0", "0", "0", "0", "cv_izabera_30", "0", "0"},
[430808] = {430808, 13008, 9, 5, "1_》_100_1.5", "level2", "雖然聽著有些像是在自誇，不過領航，我一直堅信著，自己是被上天賦予特殊使命的人。在我出生的那天，天空中便出現了代表命運的星宿。之後，在我迷茫之時，在我瀕死之時，我又再次被那顆命運之星拯救了……", "自畫自賛になるかもしれぬが、私自身、天命を與えられた人間だと信じている。私が生まれた日に、運命を示す星が現れたと聞いている。そして私が迷った時に、私が死にかけた時に、再び運命の星が現れ、私を救ったのだ……。", "0", "0", "0", "0", "cv_izabera_6", "0", "0"},
[430809] = {430809, 13008, 10, 5, "1_》_500_2", "level3", "看來我們的目的一致呢，姑且將你視作一同履行使命的摯友也不錯。不過可不要誤會，我並不是指你被賦予的使命和我一樣。只是現階段，我們都有共同的目標，而且和你合作，確實讓我感到非常愉快。", "どうやら我々の目的は同じようだな、大切な友よ。だが誤解しないでくれ。貴公と私は、同じ使命を負っていないのだ。ただ、現時點で我らは共通の目標を持ち、協力している。これは実に大きな喜びだ。", "0", "0", "0", "0", "cv_izabera_7", "0", "0"},
[430810] = {430810, 13008, 11, 5, "1_》_1000_2.5", "level4", "領航，我會一直等待著，等待著你開闢出沒有戰爭的未來。那時，也許就是我作為駕駛員的宿命終結之時。", "ナビゲーター。私は貴公が、戦爭のない未來を切り開くのを、待ち続ける。そしてその時は、私のドライバーとしての宿命が終わる時でもあるのだろう。", "0", "0", "0", "0", "cv_izabera_8", "0", "0"},
[430811] = {430811, 13008, 12, 6, "0", "0", "真好，就這樣一起提升下去吧。", "素晴らしい。このまま共に精進していこう。", "0", "0", "0", "0", "cv_izabera_9", "0", "0"},
[430812] = {430812, 13008, 13, 7, "0", "0", "咦？是我眼花了嗎？剛剛好像多出了一個亮閃閃的東西……", "あれ、目の錯覚か？なんだかキラキラしているものが……", "0", "0", "0", "0", "cv_izabera_10", "0", "0"},
[430813] = {430813, 13008, 14, 8, "0", "0", "嗯，這是我的天命，同時也是你努力的成果，總之，謝謝你領航。", "うむ。これは私の天命だが、貴公が努力した成果でもある。感謝するぞ、ナビゲーター。", "0", "0", "0", "0", "cv_izabera_11", "0", "0"},
[430814] = {430814, 13008, 15, 9, "0", "0", "變得更加耀眼吧。", "さらなる輝きを。", "0", "0", "0", "0", "cv_izabera_12", "0", "0"},
[430815] = {430815, 13008, 16, 10, "0", "0", "一同閃耀吧！", "共に輝こう！", "0", "0", "0", "0", "cv_izabera_13", "0", "0"},
[430816] = {430816, 13008, 17, 11, "0", "0", "不久的將來，那顆明星將會再次出現。", "近い將來、再びあの明星が現れるだろう。", "0", "0", "0", "0", "cv_izabera_14", "0", "0"},
[430817] = {430817, 13008, 18, 12, "0", "0", "哼，一切早在開始前便有了結果。", "フン。始まる前に全ては決まっていたのだ。", "0", "0", "0", "0", "cv_izabera_15", "0", "0"},
[430818] = {430818, 13008, 19, 13, "0", "0", "如果這也是命運的安排，那就這樣吧。", "これも定めであるのなら、受け入れるしかない。", "0", "0", "0", "0", "cv_izabera_16", "0", "0"},
[430819] = {430819, 13008, 20, 14, "0", "0", "還沒有……這裏還不是宿命的終點……", "まだだ……私の宿命は、まだ終わっていない……", "0", "0", "0", "0", "cv_izabera_17", "0", "0"},
[430820] = {430820, 13008, 23, 16, "0", "0", "打起精神來吧。", "元気を出せ。", "0", "0", "0", "0", "cv_izabera_19", "0", "0"},
[430821] = {430821, 13008, 26, 19, "0", "0", "那顆星星…現在究竟在哪裡……", "あの星は…今、どこに……", "0", "0", "0", "0", "cv_izabera_20", "0", "0"},
[430822] = {430822, 13008, 24, 17, "0", "0", "閃爍吧……", "煌めけーー！", "0", "0", "0", "0", "cv_izabera_21", "0", "0"},
[430823] = {430823, 13008, 25, 18, "0", "0", "這是你的宿命。", "これがお前の宿命だ。", "0", "0", "0", "0", "cv_izabera_18", "0", "0"},
[430824] = {430824, 13008, 27, 20, "0", "0", "比起熱水澡，我還是更喜歡冷水澡呢。", "私は熱いシャワーより、冷たい方が好きだ。", "0", "0", "0", "0", "cv_izabera_22", "0", "0"},
[430825] = {430825, 13008, 28, 21, "0", "0", "稍微有些暈了嗎？要不就先到這裏吧，你要多注意下自己的身體啊。", "少しのぼせたか？ここまでにしよう。無理は禁物だ。", "0", "0", "0", "0", "cv_izabera_23", "0", "0"},
[430826] = {430826, 13008, 29, 21, "0", "0", "嗯…把身體泡在水裏，真是讓人感覺不自在……", "ん…お湯に浸かるのは、なんか落ち著かないな……", "0", "0", "0", "0", "cv_izabera_24", "0", "0"},
[430827] = {430827, 13008, 30, 22, "0", "0", "天命！", "天命！", "0", "0", "0", "0", "cv_izabera_25", "0", "0"},
[430828] = {430828, 13008, 31, 23, "0", "0", "遵從命運，做出選擇吧。", "運命に従い、選択をするがいい。", "0", "0", "0", "0", "cv_izabera_26", "0", "0"},
[430829] = {430829, 13008, 32, 24, "0", "0", "和我預感的一樣，你做出了正確的判斷，非常感謝。", "私の予想通り、正しい判斷をしたな。感謝する。", "0", "0", "0", "0", "cv_izabera_27", "0", "0"},
[430830] = {430830, 13008, 33, 25, "0", "0", "不用太過沮喪，通往成功的路上遇到些小挫折也是必然的。", "あまり落ち込むな。成功への道のりに多少の挫折はつきものだ。", "0", "0", "0", "0", "cv_izabera_28", "0", "0"},
[430831] = {430831, 13008, 34, 26, "0", "0", "歡迎回來，領航。今天也一起並肩作戰吧。", "待っていたぞ、ナビゲーター。今日も共に戦おう。", "0", "0", "0", "0", "cv_izabera_31", "0", "0"},
[430832] = {430832, 13008, 35, 27, "0", "0", "能和你一同前行，是我的榮幸。", "貴公と共に進めるのは、私の譽れだ。", "0", "0", "0", "0", "cv_izabera_33", "0", "0"},
[430833] = {430833, 13008, 36, 28, "0", "0", "向著更高處邁進吧。", "さらなる高みへ、いざ征かん！", "0", "0", "0", "0", "cv_izabera_34", "0", "0"},
[430834] = {430834, 13008, 37, 29, "0", "0", "要去拜訪一下大家嗎？", "みなを訪ねるのか？", "0", "0", "0", "0", "cv_izabera_35", "0", "0"},
[430835] = {430835, 13008, 38, 30, "0", "0", "稍微招點人吧。", "少し新人を募集しよう。", "0", "0", "0", "0", "cv_izabera_36", "0", "0"},
[430836] = {430836, 13008, 39, 31, "0", "0", "稍微補充些裝備吧。", "少し裝備の補充をしよう。", "0", "0", "0", "0", "cv_izabera_37", "0", "0"},
[430837] = {430837, 13008, 40, 32, "0", "0", "購物……我不擅長這個。", "買物は……苦手だ。", "0", "0", "0", "0", "cv_izabera_38", "0", "0"},
[430838] = {430838, 13008, 41, 33, "0", "0", "更新下個人檔案吧。", "個人プロフィールを更新しよう。", "0", "0", "0", "0", "cv_izabera_39", "0", "0"},
[430839] = {430839, 13008, 42, 34, "0", "0", "更新下設置吧。", "設定を更新しよう。", "0", "0", "0", "0", "cv_izabera_40", "0", "0"},
[430840] = {430840, 13008, 43, 35, "0", "0", "檢查下郵箱吧。", "メールをチェックしよう。", "0", "0", "0", "0", "cv_izabera_41", "0", "0"},
[430841] = {430841, 13008, 44, 36, "0", "0", "要交流下情報嗎？", "情報交換をするのか？", "0", "0", "0", "0", "cv_izabera_42", "0", "0"},
[430842] = {430842, 13008, 45, 37, "0", "0", "我明白了。", "分かった。", "0", "0", "0", "0", "cv_izabera_43", "0", "0"},
[430900] = {430900, 13009, 1, 1, "0", "0", "蒼霧殘響。", "0", "0", "0", "蒼霧殘響。", "0", "cv_evatee_33", "0", "0"},
[430901] = {430901, 13009, 2, 2, "0", "0", "我還是第一次擔任這麼重要的職務。", "0", "0", "0", "我還是第一次擔任這麼重要的職務。", "0", "cv_evatee_2", "0", "0"},
[430902] = {430902, 13009, 3, 3, "0", "0", "艾伊瓦蒂，跨越時空的米狄爾星際旅行者，能與您相見甚是榮幸。", "0", "0", "0", "艾伊瓦蒂，跨越時空的米狄爾星際旅行者，能與您相見甚是榮幸。", "0", "cv_evatee_1", "0", "0"},
[430903] = {430903, 13009, 4, 4, "0", "idle", "這顆星球的文明……和米狄爾的文明完全不一樣呢。親眼見識過後，我更是這麼覺得。", "0", "0", "0", "這顆星球的文明……和米狄爾的文明完全不一樣呢。親眼見識過後，我更是這麼覺得。", "0", "cv_evatee_3", "0", "0"},
[430904] = {430904, 13009, 5, 4, "0", "idle", "白天和晚上給人的感覺很不一樣呢。以前的我總是身處一片漆黑的宇宙…完全沒法察覺。", "0", "0", "0", "白天和晚上給人的感覺很不一樣呢。以前的我總是身處一片漆黑的宇宙…完全沒法察覺。", "0", "cv_evatee_4", "0", "0"},
[430905] = {430905, 13009, 6, 4, "0", "idle", "如果有機會的話，真想把修米婭號也給復原出來。", "0", "0", "0", "如果有機會的話，真想把修米婭號也給復原出來。", "0", "cv_evatee_30", "0", "0"},
[430906] = {430906, 13009, 7, 5, "1_》_0_0.8", "level1", "弗洛維拉是我最要好的朋友，看著她一臉幸福地吃著我做出來的食物，真是開心啊。", "0", "0", "0", "弗洛維拉是我最要好的朋友，看著她一臉幸福地吃著我做出來的食物，真是開心啊。", "0", "cv_evatee_31", "0", "0"},
[430907] = {430907, 13009, 8, 5, "1_》_0_0.8", "level1", "嗯，我就在這裡，地球的領航。", "0", "0", "0", "嗯，我就在這裡，地球的領航。", "0", "cv_evatee_5", "0", "0"},
[430908] = {430908, 13009, 9, 5, "1_》_100_1.5", "level2", "想要瞭解修米婭號上的伙食？還真是少見啊，一般大家都對我們的旅行見聞更感興趣。還是第一次有人來打聽我最拿手的事情呢。", "0", "0", "0", "想要瞭解修米婭號上的伙食？還真是少見啊，一般大家都對我們的旅行見聞更感興趣。還是第一次有人來打聽我最拿手的事情呢。", "0", "cv_evatee_6", "0", "0"},
[430909] = {430909, 13009, 10, 5, "1_》_500_2", "level3", "只有親身經歷一次才會明白，這個世界上並不存在天堂。被黑暗吞沒也只是一瞬間的事……但是這些已經過去了，我能從那漫無邊際的噩夢中醒來已經足夠了。", "0", "0", "0", "只有親身經歷一次才會明白，這個世界上並不存在天堂。被黑暗吞沒也只是一瞬間的事……但是這些已經過去了，我能從那漫無邊際的噩夢中醒來已經足夠了。", "0", "cv_evatee_7", "0", "0"},
[430910] = {430910, 13009, 11, 5, "1_》_1000_2.5", "level4", "在宇宙中不斷旅行是我們米狄爾人的生存方式，但是這並不意味著我們不會停靠在某處。領航，在我們的文化中，當旅行者落地之時，便是與其生命中最重要的人邂逅之時……", "0", "0", "0", "在宇宙中不斷旅行是我們米狄爾人的生存方式，但是這並不意味著我們不會停靠在某處。領航，在我們的文化中，當旅行者落地之時，便是與其生命中最重要的人邂逅之時……", "0", "cv_evatee_8", "0", "0"},
[430911] = {430911, 13009, 12, 6, "0", "0", "非常感謝。", "0", "0", "0", "非常感謝。", "0", "cv_evatee_9", "0", "0"},
[430912] = {430912, 13009, 13, 7, "0", "0", "欸？剛剛的那個是什麼？", "0", "0", "0", "哎？剛剛的那個是什麼？", "0", "cv_evatee_10", "0", "0"},
[430913] = {430913, 13009, 14, 8, "0", "0", "原來如此，這顆星球上有著我們尚未理解的力量……", "0", "0", "0", "原來如此，這顆星球上有著我們尚未理解的力量……", "0", "cv_evatee_11", "0", "0"},
[430914] = {430914, 13009, 15, 9, "0", "0", "麻煩您了。", "0", "0", "0", "麻煩您了。", "0", "cv_evatee_12", "0", "0"},
[430915] = {430915, 13009, 16, 10, "0", "0", "請允許我助戰吧。", "0", "0", "0", "請允許我助戰吧。", "0", "cv_evatee_13", "0", "0"},
[430916] = {430916, 13009, 17, 11, "0", "0", "成功了！我沒有做錯什麼吧，領航。", "0", "0", "0", "成功了！我沒有做錯什麼吧，領航。", "0", "cv_evatee_14", "0", "0"},
[430917] = {430917, 13009, 18, 12, "0", "0", "戰鬥已經結束了，就讓我來為大家療傷吧。", "0", "0", "0", "戰鬥已經結束了，就讓我來為大家療傷吧。", "0", "cv_evatee_15", "0", "0"},
[430918] = {430918, 13009, 19, 13, "0", "0", "稍微還有些不太習慣用這幅身軀戰鬥……", "0", "0", "0", "稍微還有些不太習慣用這幅身軀戰鬥……", "0", "cv_evatee_16", "0", "0"},
