[430925] = {430925, 13009, 27, 20, "0", "0", "這裡就是清洗身體的地方嗎？沒想到連這裡都這麼寬敞。", "0", "0", "0", "這裡就是清洗身體的地方嗎？沒想到連這裡都這麼寬敞。", "0", "cv_evatee_23", "0", "0"},
[430926] = {430926, 13009, 28, 21, "0", "0", "修米婭號上也有淋浴間，不過遠比不上這裡。", "0", "0", "0", "修米婭號上也有淋浴間，不過遠比不上這裡。", "0", "cv_evatee_24", "0", "0"},
[430927] = {430927, 13009, 29, 21, "0", "0", "好久都沒有洗過熱水澡了……真的是已經過了好久…好久……", "0", "0", "0", "好久都沒有洗過熱水澡了……真的是已經過了好久…好久……", "0", "cv_evatee_25", "0", "0"},
