[430931] = {430931, 13009, 33, 25, "0", "0", "嘿嘿嘿，下次可不要再猜錯了。", "0", "0", "0", "嘿嘿嘿，下次可不要再猜錯了。", "0", "cv_evatee_29", "0", "0"},
