[430943] = {430943, 13009, 45, 37, "0", "0", "我明白了。", "0", "0", "0", "我明白了。", "0", "cv_evatee_44", "0", "0"},
[431000] = {431000, 13010, 1, 1, "0", "0", "蒼霧殘響", "蒼霧殘響（ハツリバーブ）。", "0", "0", "0", "0", "cv_qu_1", "0", "0"},
[431001] = {431001, 13010, 2, 2, "0", "0", "真是奇怪啊，這可不在我的任務範圍，不過…這樣也好。", "……変ね。私の任務範囲じゃなさそうだけど。まあ、いいわ。", "0", "0", "0", "0", "cv_qu_2", "0", "0"},
[431002] = {431002, 13010, 3, 3, "0", "0", "新來的領航？今後就請多多關照了，無論是戰鬥還是生活的事都可以找我幫忙。話說，你看到我們時會嚇一跳嗎？", "新しいナビゲーター？これからよろしくね。戦闘でもそれ以外でも、困ったことがあれば力になるわ。……ねえ。私たちを初めて見て、驚いたかしら？", "0", "0", "0", "0", "cv_qu_3", "0", "0"},
[431003] = {431003, 13010, 4, 4, "0", "idle", "這裏的視野很寬廣，那些藏在陰影中的事物都無處遁形。", "ここはよく見えるわね。影に潛もうと、隠れることはできないわ。", "0", "0", "0", "0", "cv_qu_4", "0", "0"},
[431004] = {431004, 13010, 5, 4, "0", "idle", "每次看到領航，總感覺心裏特別平靜……", "ナビゲーターを見ると、なんだか心がとても落ち著く……", "0", "0", "0", "0", "cv_qu_5", "0", "0"},
[431005] = {431005, 13010, 6, 4, "0", "idle", "銀有時會太過衝動，而瓏不過還是個孩子，不能很好地適應戰場……在她們成長起來之前，我得肩負起保護同胞的責任。", "銀は衝動的になりすぎるところがあるし、瓏は戦場に出るべきではない子供よ……あの子たちが成長するまでは、私が仲間を守る責任を負うわ。", "0", "0", "0", "0", "cv_qu_6", "0", "0"},
[431006] = {431006, 13010, 7, 5, "1_》_0_0.8", "level1", "埃塔人對你們人類來說是外來者，只是因為原罪才能保持我們之間的和平。如果有一天原罪被消滅了，我們該以什麼方式相處呢？", "あなた達人間にとってエッタ人はよそ者よ。私たちの間に平和が保たれているのは、原罪に対抗するためだけど……いつか全ての原罪を滅ぼしたら、私たちはどう付き合えばいいの？", "0", "0", "0", "0", "cv_qu_7", "0", "0"},
[431007] = {431007, 13010, 8, 5, "1_》_0_0.8", "level1", "請保持克制，我可不會像小狗一樣……", "やめて。私は犬じゃないのよ。", "0", "0", "0", "0", "cv_qu_8", "0", "0"},
[431008] = {431008, 13010, 9, 5, "1_》_100_1.5", "level2", "我只希望我的同胞們能安穩地活下去，不再被原罪或者其他什麼東西傷害。", "私はただ、同胞がこれ以上原罪などに傷つけられることなく、平和に生きてほしいと願っているだけよ。", "0", "0", "0", "0", "cv_qu_9", "0", "0"},
[431009] = {431009, 13010, 10, 5, "1_》_500_2", "level3", "這麼在意我的尾巴嗎？請隨意地撫摸吧，這是僅領航擁有的特權。", "そんなに私のしっぽが気になるの？ふふっ。じゃあご自由にどうぞ。ナビゲーターだけの特権よ。", "0", "0", "0", "0", "cv_qu_10", "0", "0"},
[431010] = {431010, 13010, 11, 5, "1_》_1000_2.5", "level4", "在之前的通感中，我明白了領航的心意，領航也瞭解了我黑暗的過去。所以在艾吉斯中我能相信的只有你一個。只有和領航在一起，我才能真正感到安心。", "この前の通感覚で、私はナビゲーターの心を理解することができた。……そしてナビゲーターも、私の暗い過去を知ったのね。だから、アイギスで信頼できるのはナビゲーターだけ。あなたと一緒にいる時だけ、私は本當に安らげるの。", "0", "0", "0", "0", "cv_qu_11", "0", "0"},
[431011] = {431011, 13010, 12, 6, "0", "0", "謝謝。", "ありがとう。", "0", "0", "0", "0", "cv_qu_12", "0", "0"},
[431012] = {431012, 13010, 13, 7, "0", "0", "如果是為了同胞們，我願意變強。", "同胞のために、もっと強くなりたい。", "0", "0", "0", "0", "cv_qu_13", "0", "0"},
[431013] = {431013, 13010, 14, 8, "0", "0", "“覺醒”嗎…這讓我想起了以前的事……領航，我和你約定好了，我不會再重蹈覆轍了。失敗的苦楚，對我來說品嘗一次就足夠了。", "覚醒、ね……昔を思い出すわ……ナビゲーター、約束するわ。私はもう同じ失敗を繰り返さない。苦汁をなめるのは一度で十分よ。", "0", "0", "0", "0", "cv_qu_14", "0", "0"},
[431014] = {431014, 13010, 15, 9, "0", "0", "全新的技藝，值得學習。", "新技ね。使いこなしてみせるわ。", "0", "0", "0", "0", "cv_qu_15", "0", "0"},
[431015] = {431015, 13010, 16, 10, "0", "0", "我會保證你們的安全。", "私があなた達を守ってみせる。", "0", "0", "0", "0", "cv_qu_16", "0", "0"},
[431016] = {431016, 13010, 17, 11, "0", "0", "只要相信她們就好了。", "信じて……いいのね。", "0", "0", "0", "0", "cv_qu_17", "0", "0"},
[431017] = {431017, 13010, 18, 12, "0", "0", "由我來治療傷患吧。", "負傷者はこっちに！", "0", "0", "0", "0", "cv_qu_18", "0", "0"},
[431018] = {431018, 13010, 19, 13, "0", "0", "下一次再努力吧，先讓我看看哪裡受傷了。", "反省は後よ。早く傷を見せて。", "0", "0", "0", "0", "cv_qu_19", "0", "0"},
[431019] = {431019, 13010, 20, 14, "0", "0", "先保住性命，等待下一次機會。", "生き延びることが最優先よ。チャンスはまた來るわ。", "0", "0", "0", "0", "cv_qu_20", "0", "0"},
[431020] = {431020, 13010, 23, 16, "0", "0", "治療的事就交給我吧。", "治療なら任せてちょうだい。", "0", "0", "0", "0", "cv_qu_21", "0", "0"},
[431021] = {431021, 13010, 26, 19, "0", "0", "嗚…我到此為止了嗎……", "うう……ここまでなの……", "0", "0", "0", "0", "cv_qu_22", "0", "0"},
[431022] = {431022, 13010, 24, 17, "0", "0", "我來掩護你們。", "援護する。", "0", "0", "0", "0", "cv_qu_23", "0", "0"},
[431023] = {431023, 13010, 27, 20, "0", "0", "好久沒有安心地泡澡了。", "落ち著いてお風呂に入るのは久しぶりね。", "0", "0", "0", "0", "cv_qu_24", "0", "0"},
[431024] = {431024, 13010, 28, 21, "0", "0", "不知道這個沐浴露會不會損傷毛髮。", "このボディーソープ、毛が痛まないかしら……", "0", "0", "0", "0", "cv_qu_25", "0", "0"},
[431025] = {431025, 13010, 29, 21, "0", "0", "水池有點擠呢。", "少し狹いわね。", "0", "0", "0", "0", "cv_qu_26", "0", "0"},
[431026] = {431026, 13010, 30, 22, "0", "0", "領航……準備好了麼？", "ナビゲーター、準備はできた？", "0", "0", "0", "0", "cv_qu_27", "0", "0"},
[431027] = {431027, 13010, 31, 23, "0", "0", "我的毛色……應該很好猜吧。", "私の毛色なら……わかるわよね。", "0", "0", "0", "0", "cv_qu_28", "0", "0"},
[431028] = {431028, 13010, 32, 24, "0", "0", "不會是蒙對的吧。", "當てずっぽうだったりして。", "0", "0", "0", "0", "cv_qu_29", "0", "0"},
[431029] = {431029, 13010, 33, 25, "0", "0", "不會是故意的吧。", "……わざと？", "0", "0", "0", "0", "cv_qu_30", "0", "0"},
[431030] = {431030, 13010, 34, 26, "0", "0", "歡迎回來，要先做個身體檢查嗎？", "おかえりなさい。先に身體検査をする？", "0", "0", "0", "0", "cv_qu_31", "0", "0"},
[431031] = {431031, 13010, 35, 27, "0", "0", "在一旁監督她們戰鬥吧。", "彼女たちの戦いを見屆けるわ。", "0", "0", "0", "0", "cv_qu_32", "0", "0"},
[431032] = {431032, 13010, 36, 28, "0", "0", "得拿出真本事了。", "本気を出さないと。", "0", "0", "0", "0", "cv_qu_33", "0", "0"},
[431033] = {431033, 13010, 37, 29, "0", "0", "有傷員需要治療嗎？", "ナビゲーターも大変ね。", "0", "0", "0", "0", "cv_qu_34", "0", "0"},
[431034] = {431034, 13010, 38, 30, "0", "0", "又需要新人手了嗎？", "人手不足なの？", "0", "0", "0", "0", "cv_qu_35", "0", "0"},
[431035] = {431035, 13010, 39, 31, "0", "0", "希望這些能增加存活率。", "これで生存率が上がったら嬉しいわ。", "0", "0", "0", "0", "cv_qu_36", "0", "0"},
[431036] = {431036, 13010, 40, 32, "0", "0", "下個月的物資現在就採購吧。", "來月分も仕入れておこうかしら。", "0", "0", "0", "0", "cv_qu_37", "0", "0"},
[431037] = {431037, 13010, 41, 33, "0", "0", "人類沒有皮毛不會冷嗎？", "人間には毛皮がないけど、寒くないの？", "0", "0", "0", "0", "cv_qu_38", "0", "0"},
[431038] = {431038, 13010, 42, 34, "0", "0", "非常新奇的方式。", "面白いやり方ね。", "0", "0", "0", "0", "cv_qu_39", "0", "0"},
[431039] = {431039, 13010, 43, 35, "0", "0", "查看一下吧。", "メールをチェックして。", "0", "0", "0", "0", "cv_qu_40", "0", "0"},
[431040] = {431040, 13010, 44, 36, "0", "0", "全世界都能聽到。", "世界中に聞こえるわよ。", "0", "0", "0", "0", "cv_qu_41", "0", "0"},
[431041] = {431041, 13010, 45, 37, "0", "0", "嗯哼。", "ふふ。", "0", "0", "0", "0", "cv_qu_42", "0", "0"},
[431100] = {431100, 13011, 1, 1, "0", "0", "蒼霧殘響", "ハツリバーブ", "0", "0", "0", "0", "cv_meiliya_1", "0", "0"},
[431101] = {431101, 13011, 2, 2, "0", "0", "不就是裝模作樣，這種事我再擅長不過。", "貓を被るのは、得意ですよ。", "0", "0", "0", "0", "cv_meiliya_2", "0", "0"},
[431102] = {431102, 13011, 3, 3, "0", "0", "您好，我是梅莉雅，聖濯教會的一名虔誠的聖女，願源遠流長之水為我們帶來祝福……呵呵，領航想聽到的就是這種台詞？真是變態呢。", "初めまして、聖濯教會の敬虔な聖女、メリアです。永遠の水が、私たちに祝福をもたらしますように……ふふっ、ナビゲーターさんは、こういうセリフが聞きたかったのですか？ほんとう、変態ですね。", "0", "0", "0", "0", "cv_meiliya_3", "0", "0"},
[431103] = {431103, 13011, 4, 4, "0", "idle", "以此身軀吹口氣就成一陣風，灑杯水就是一場雨，如果神明如此簡單就能操控萬物，我也想當神。", "息を吹けば風となり、水を撒けば雨となる。……そんな簡単に萬物を扱うことができるのなら、私も神になりたいです。", "0", "0", "0", "0", "cv_meiliya_4", "0", "0"},
[431104] = {431104, 13011, 5, 4, "0", "idle", "領航……這就睡著了？真是個沒用的大人啊，雖然我對工作也漫不經心，但至少還是會裝一下的。", "ナビゲーターさん……眠ってしまいましたか？まったく、ダメな大人ですね。私も仕事はしたくないですが、してるフリくらいはするというのに。", "0", "0", "0", "0", "cv_meiliya_5", "0", "0"},
[431105] = {431105, 13011, 6, 4, "0", "idle", "我的偽裝效果因人而異，就拿隊友來說，奧菲莉亞最易欺騙，珂斯嘉德則嗅覺靈敏，而最可怕的還是米菈，她能輕易看透我卻依舊佯裝無事。", "私の変裝の効果は、人によって異なります。同じ部隊のメンバーなら、オフィーリアさんが一番騙しやすいですね。コースガードさんは鋭くて、一番怖いのはミーラさんでしょうか。見破っているのに、気付いていないようなフリをするんですよ。", "0", "0", "0", "0", "cv_meiliya_6", "0", "0"},
[431106] = {431106, 13011, 7, 5, "1_》_0_0.8", "level1", "小手這麼亂動，是有煩惱要向本聖女傾訴？那麼就讓我告訴你快樂的秘訣吧，首先的一步，當然是學會隱瞞本心啦。", "そのおかしな手つき…さてはこの聖女に悩みを打ち明けたいのですね？では、幸せになる秘訣をお教えしましょう。まずは、自分の本心を隠すことです。", "0", "0", "0", "0", "cv_meiliya_7", "0", "0"},
[431107] = {431107, 13011, 8, 5, "1_》_0_0.8", "level1", "幹什麼？你的手機？問我幹嘛，我可沒看見。不過嘛……之後要是碰巧找到了，今晚就去趟你的房間送還失物吧。", "何でしょうか？ナビゲーターさんの攜帯電話ですか？なぜ私に聞くのですか？見ていませんよ？まぁ……もし偶然見つけたら、今夜部屋に屆けますね。", "0", "0", "0", "0", "cv_meiliya_8", "0", "0"},
[431108] = {431108, 13011, 9, 5, "1_》_100_1.5", "level2", "我只為自己而活，領航則有著更宏大的目標吧？雖然想說你太理想主義，但如果我也在那宏大目標中佔一部分，就還是為你鼓鼓勁好了~", "私は自分のためだけに生きているのです。ナビゲーターさんは、何か大きな目標とかあるのですか？理想主義もほどほどにと言いたいところですが、私もその大きな目標に含まれているのなら、応援してあげてもいいですよ。", "0", "0", "0", "0", "cv_meiliya_9", "0", "0"},
[431109] = {431109, 13011, 10, 5, "1_》_500_2", "level3", "領航也想嘗嘗聖杯中的水嗎？但這裡面只是液態尼姆比斯能，沒什麼特殊的。哦對了，難道你的真正目的是間接接吻？", "聖杯の水を飲んでみたいのですか？まあ、何の変哲もない、ただの液體ニムビウスですよ。あ、もしかして本當の狙いは……間接キッス？", "0", "0", "0", "0", "cv_meiliya_10", "0", "0"},
[431110] = {431110, 13011, 11, 5, "1_》_1000_2.5", "level4", "在你身上還有什麼寶物值得讓我竊取呢？理念？那種東西太過耀眼。勇氣？那又炙熱到難以忍受。想來想去，還是只有你的人生讓我不禁垂涎呢。", "あなたは盜む価値のあるような物を持っていますか？…信念？それは眩しすぎますね。勇気？それは熱すぎます。…考えてみれば、私が欲しいものは、あなたの人生だけかもしれませんね。", "0", "0", "0", "0", "cv_meiliya_11", "0", "0"},
[431111] = {431111, 13011, 12, 6, "0", "0", "就不能當沒我這號人？", "私をいないものとして扱ってもらえませんか？", "0", "0", "0", "0", "cv_meiliya_12", "0", "0"},
[431112] = {431112, 13011, 13, 7, "0", "0", "要是薪水也能增加就好了。", "お給料も上がると良いですね。", "0", "0", "0", "0", "cv_meiliya_13", "0", "0"},
[431113] = {431113, 13011, 14, 8, "0", "0", "總說能力增長伴隨責任增加，為什麼一定要我承擔更大的責任才滿意？要是我繼續擺爛下去，不就顯得像辜負了你的期待嗎，真是的。", "能力が上がると、責任も重くなるとよく言われますが、なぜ私に大きな責任を背負わせようとするのですか？このまま逃げ続けてしまったら、あなたの期待を裏切ったように見えるではないですか…まったく。", "0", "0", "0", "0", "cv_meiliya_14", "0", "0"},
[431114] = {431114, 13011, 15, 9, "0", "0", "學習好痛苦。", "勉強はいやです。", "0", "0", "0", "0", "cv_meiliya_15", "0", "0"},
[431115] = {431115, 13011, 16, 10, "0", "0", "連我也得上戰場，真殘酷呢。", "私も戦場に行くのですか？なんて殘酷なのでしょう。", "0", "0", "0", "0", "cv_meiliya_16", "0", "0"},
[431116] = {431116, 13011, 17, 11, "0", "0", "總得有我一份功勞吧？", "私の手柄でもありますよね？", "0", "0", "0", "0", "cv_meiliya_17", "0", "0"},
[431117] = {431117, 13011, 18, 12, "0", "0", "勉勉強強吧。", "まあまあといった感じですね。", "0", "0", "0", "0", "cv_meiliya_18", "0", "0"},
[431118] = {431118, 13011, 19, 13, "0", "0", "該想想檢討的說辭了。", "言い訳を考えなくては。", "0", "0", "0", "0", "cv_meiliya_19", "0", "0"},
[431119] = {431119, 13011, 20, 14, "0", "0", "這次是不是你指揮得有問題？", "ナビゲーターさんの指揮の問題ではないでしょうか？", "0", "0", "0", "0", "cv_meiliya_20", "0", "0"},
[431120] = {431120, 13011, 23, 16, "0", "0", "象徵性動一動好了。", "適當にやっておきますよ。", "0", "0", "0", "0", "cv_meiliya_23", "0", "0"},
[431121] = {431121, 13011, 26, 19, "0", "0", "我盡力了，接下來交給你們吧。", "力は盡くしました、あとは任せましたよ。", "0", "0", "0", "0", "cv_meiliya_24", "0", "0"},
[431122] = {431122, 13011, 24, 17, "0", "0", "接受賞賜吧~", "贈り物を受け取りなさい。", "0", "0", "0", "0", "cv_meiliya_25", "0", "0"},
[431123] = {431123, 13011, 25, 18, "0", "0", "為了我好好加油吧。", "私のために頑張ってくださいね。", "0", "0", "0", "0", "cv_meiliya_26", "0", "0"},
[431124] = {431124, 13011, 27, 20, "0", "0", "洗澡洗澡~", "お風呂。お風呂。", "0", "0", "0", "0", "cv_meiliya_27", "0", "0"},
[431125] = {431125, 13011, 28, 21, "0", "0", "純潔的聖女在你面前入浴，你是否反而激起了不潔的想法？", "純潔の聖女が目の前でお風呂に入っている時に、不純な気持ちが湧いているのですか？", "0", "0", "0", "0", "cv_meiliya_28", "0", "0"},
[431126] = {431126, 13011, 29, 21, "0", "0", "內心的汙穢再怎麼也不可能洗淨，所以至少要好好清洗身體。", "心の汚れを浄化できないのなら、せめて體くらいは清らかにしましょう。", "0", "0", "0", "0", "cv_meiliya_29", "0", "0"},
[431127] = {431127, 13011, 30, 22, "0", "0", "怎麼啦？", "どうしました？", "0", "0", "0", "0", "cv_meiliya_30", "0", "0"},
[431128] = {431128, 13011, 31, 23, "0", "0", "猜對有獎勵哦。", "當てたらご褒美がありますよ。", "0", "0", "0", "0", "cv_meiliya_31", "0", "0"},
[431129] = {431129, 13011, 32, 24, "0", "0", "猜對的喜悅本身就是一種獎勵~", "當てられた喜びがご褒美ですよ。", "0", "0", "0", "0", "cv_meiliya_32", "0", "0"},
[431130] = {431130, 13011, 33, 25, "0", "0", "我的偽裝果然出色。", "私の変裝、うまくいったようですね。", "0", "0", "0", "0", "cv_meiliya_33", "0", "0"},
[431131] = {431131, 13011, 34, 26, "0", "0", "不會想讓我優雅地拎起裙角，臉上掛好甜美微笑，用矯揉造作的聲音迎接你吧？歡迎回來——就像這樣？", "スカートを優雅にたくし上げ、優しい笑顔を浮かべ、気取った聲で出迎えてほしいのですか？…おかえりなさいませ♪…こんな感じですか？", "0", "0", "0", "0", "cv_meiliya_34", "0", "0"},
[431132] = {431132, 13011, 35, 27, "0", "0", "突然不舒服，要不我今天請假吧？", "気分が悪くなったので、休暇をとってもいいですか？", "0", "0", "0", "0", "cv_meiliya_35", "0", "0"},
[431133] = {431133, 13011, 36, 28, "0", "0", "希望大家能手下留情。", "皆さん、お手柔らかにお願いします。", "0", "0", "0", "0", "cv_meiliya_36", "0", "0"},
[431134] = {431134, 13011, 37, 29, "0", "0", "你認識好多美女。", "可愛い女の子の知り合い、多いですね。", "0", "0", "0", "0", "cv_meiliya_37", "0", "0"},
[431135] = {431135, 13011, 38, 30, "0", "0", "會有更好騙的人嗎？", "もっと騙されやすそうな方とかいないのですか？", "0", "0", "0", "0", "cv_meiliya_38", "0", "0"},
[431136] = {431136, 13011, 39, 31, "0", "0", "讓我試試。", "試してみましょう。", "0", "0", "0", "0", "cv_meiliya_39", "0", "0"},
[431137] = {431137, 13011, 40, 32, "0", "0", "買東西還要花錢？", "物を買うために、お金が必要なのですか？", "0", "0", "0", "0", "cv_meiliya_40", "0", "0"},
[431138] = {431138, 13011, 41, 33, "0", "0", "好無聊的履歷。", "退屈な経歴ですね。", "0", "0", "0", "0", "cv_meiliya_41", "0", "0"},
[431139] = {431139, 13011, 42, 34, "0", "0", "你真仔細。", "慎重ですね。", "0", "0", "0", "0", "cv_meiliya_42", "0", "0"},
[431140] = {431140, 13011, 43, 35, "0", "0", "當沒看到好了。", "見なかったことにしましょう。", "0", "0", "0", "0", "cv_meiliya_43", "0", "0"},
[431141] = {431141, 13011, 44, 36, "0", "0", "人人戴著面具的世界啊。", "誰もが仮面を被っている世界ですか。", "0", "0", "0", "0", "cv_meiliya_44", "0", "0"},
[431142] = {431142, 13011, 45, 37, "0", "0", "多動症？", "落ち著けないのですか？", "0", "0", "0", "0", "cv_meiliya_45", "0", "0"},
[431200] = {431200, 13012, 1, 1, "0", "0", "蒼霧殘響", "蒼霧殘響（ハツリバーブ）。", "0", "0", "0", "0", "cv_dorothy_1", "0", "0"},
[431201] = {431201, 13012, 2, 2, "0", "0", "領航，找魔女小姐有什麼事嗎？", "ナビゲーターさん。何か魔女にご用ですか？", "0", "0", "0", "0", "cv_dorothy_2", "0", "0"},
[431202] = {431202, 13012, 3, 3, "0", "0", "我聽到了你的呼喚，跨越了世界的障壁來到了你的面前……怎麼樣？夢中的人出現在你身邊有沒有很驚喜？嗯……驚嚇？", "ナビゲーターさんの呼ぶ聲が聞こえたので、世界の壁を越えてやってきました。どうですか。夢から出てきたみたいで、嬉しかったですか？え。びっくりした…だけ？", "0", "0", "0", "0", "cv_dorothy_4", "0", "0"},
[431203] = {431203, 13012, 4, 4, "0", "idle", "魔女的占卜時間，無論是財運、事業運，還是其他需求，我都可以為你占卜。……戀愛運？看不出來，你還真是單純啊……", "魔女の占いタイムです！金運や仕事運、どんなことでも占っちゃいますよ！……戀愛運ですか？ナビゲーターさん、意外とピュアなんですね。", "0", "0", "0", "0", "cv_dorothy_5", "0", "0"},
[431204] = {431204, 13012, 5, 4, "0", "idle", "我要去參加魔女們的聚會了，要一起去玩嗎……有事情要忙？真可惜呢……那下次可輪到領航來邀請我了哦。", "魔女たちのパーティーに行くんですが、ナビゲーターさんも一緒にいかがですか？……用事がある？うーん、殘念ですね……じゃあ今度はナビゲーターさんから誘ってくださいね！", "0", "0", "0", "0", "cv_dorothy_6", "0", "0"},
[431205] = {431205, 13012, 6, 4, "0", "idle", "要把我調回多瑙支部？……我現在可是正處於離家出走的狀態呢。但是……假如領航一定要我陪在你身邊，也不是不可以哦？", "私をダニューブ支部に？いまは家出中の身なんですが……でももし、ナビゲーターさんがどうしてもって言うのなら……行っちゃおうかなぁ……", "0", "0", "0", "0", "cv_dorothy_7", "0", "0"},
[431206] = {431206, 13012, 7, 5, "1_》_0_0.8", "level1", "其實今年是我渡過的的第497個年頭……欸？身份證明上寫著我的出生年月？姆——真是的，領航，在我維護“職業”神秘感的時候，不要幹這樣掃興的事情哦。", "今年で４９７回目の夏ですね……って何で噓って知ってるんですか！？ＩＤに生年月日が書いてあった？もう！この仕事は神秘的なのも大事なんですから、ばらさないでくださいよー！", "0", "0", "0", "0", "cv_dorothy_8", "0", "0"},
[431207] = {431207, 13012, 8, 5, "1_》_0_0.8", "level1", "擅自靠近魔女可是會招致災厄的哦。", "不用意に魔女に近づくと、災いを招きますよ。", "0", "0", "0", "0", "cv_dorothy_9", "0", "0"},
[431208] = {431208, 13012, 9, 5, "1_》_100_1.5", "level2", "在故事中，接觸魔女的人都會帶上不幸……但是領航你還是這樣靠過來了。要不稍微陪我一會吧，我來給你解除這段不幸的詛咒。", "魔女に近づくと不幸になる……って言い伝えがあるのに、ナビゲーターさんは気にせず接してくださいましたね。良かったら、もうちょっと付き合ってくださいませんか？「不幸の呪い」を解いてさしあげますから。", "0", "0", "0", "0", "cv_dorothy_10", "0", "0"},
[431209] = {431209, 13012, 10, 5, "1_》_500_2", "level3", "這是勇者的塔羅牌，在這個故事裏，拯救世界的使命交給你了。……塔羅牌沒有勇者牌？我的塔羅有哦~你就是我挑選的勇者。", "これは……勇者のタロットカードです！この物語で世界を救うのは、ナビゲーターさんですよ！……え？タロットカードに勇者なんてあったかって？私のタロットにはあるんです！ナビゲーターさんは私が選んだ勇者なんですから！", "0", "0", "0", "0", "cv_dorothy_11", "0", "0"},
[431210] = {431210, 13012, 11, 5, "1_》_1000_2.5", "level4", "我真的是魔女嗎？……來，看著這個，3，2，1。好了，我已經對你施加了會不知不覺愛上我的魔法，而且已經生效了哦~", "私が本當に魔女なのか、信じてないんですか？……じゃあ、これを見てください。３…２…１…はい！ナビゲーターさんが私のことを好きになる魔法をかけちゃいました。ほーら、もう効いてるでしょう？", "0", "0", "0", "0", "cv_dorothy_12", "0", "0"},
[431211] = {431211, 13012, 12, 6, "0", "0", "更多地、許諾我更多的力量吧……", "もっと、私にもっと力をお與えください……", "0", "0", "0", "0", "cv_dorothy_13", "0", "0"},
[431212] = {431212, 13012, 13, 7, "0", "0", "這份饋贈，我就用辰星來回贈你吧。", "この恩は、星と共にお返しします。", "0", "0", "0", "0", "cv_dorothy_14", "0", "0"},
[431213] = {431213, 13012, 14, 8, "0", "0", "這樣就算與我立下約定了。……與魔女的約定，你可以猜猜是什麼~", "これで私達の間には、契約が結ばれました。……魔女との契約……その意味、わかりますか？", "0", "0", "0", "0", "cv_dorothy_15", "0", "0"},
[431214] = {431214, 13012, 15, 9, "0", "0", "接下來就隨我一起見證吧。", "私と共に見屆けましょう。", "0", "0", "0", "0", "cv_dorothy_16", "0", "0"},
[431215] = {431215, 13012, 16, 10, "0", "0", "多蘿西法術序列，展開。", "ドロシー・スペルシークエンス、展開。", "0", "0", "0", "0", "cv_dorothy_17", "0", "0"},
[431216] = {431216, 13012, 17, 11, "0", "0", "沒有什麼是魔女不能解決的。", "魔女に解決できないことはありません！", "0", "0", "0", "0", "cv_dorothy_18", "0", "0"},
[431217] = {431217, 13012, 18, 12, "0", "0", "……差一點啊，看來我還需要精進呢。", "……惜しかったですね。私にはまだ修行が必要なようです。", "0", "0", "0", "0", "cv_dorothy_19", "0", "0"},
[431218] = {431218, 13012, 19, 13, "0", "0", "慘勝嗎……領航，請相信魔女的力量，再次挑戰吧。", "危ないところでした……魔女の力を信じて、もう一度挑戦しますか？", "0", "0", "0", "0", "cv_dorothy_20", "0", "0"},
[431219] = {431219, 13012, 20, 14, "0", "0", "領航，快過來，要逃跑了！", "ナビゲーターさん、こっちへ！撤退しましょう！", "0", "0", "0", "0", "cv_dorothy_21", "0", "0"},
[431220] = {431220, 13012, 23, 16, "0", "0", "只要在這片星空下，繁星都會是你我的夥伴。", "この空の下にいる限り、星は私たちの味方です！", "0", "0", "0", "0", "cv_dorothy_22", "0", "0"},
[431221] = {431221, 13012, 26, 19, "0", "0", "沒關係，我還有很多代替死亡的手段……", "大丈夫です。死を回避する道具はたくさんありますから……", "0", "0", "0", "0", "cv_dorothy_23", "0", "0"},
[431222] = {431222, 13012, 24, 17, "0", "0", "法術輪重置，現在還是我的回合。", "マジックループ、リセット！まだ私のターンです！", "0", "0", "0", "0", "cv_dorothy_24", "0", "0"},
[431223] = {431223, 13012, 27, 20, "0", "0", "啊呀，領航，過來坐在這裏吧。我已經預見到你會來到這裏了。", "ナビゲーターさん。どうぞ、こちらにおかけください。來ることは予見していましたから。", "0", "0", "0", "0", "cv_dorothy_25", "0", "0"},
[431224] = {431224, 13012, 28, 21, "0", "0", "我的身體已經停止了生長，停止了衰老，這是不老不死的泉水帶來的效果哦。領航也想要喝嗎？嗯……我一直喝的飲料是這個牌子哦。", "不老不死の泉の効果で、ずいぶん前に私の體の成長は止まったんです。ナビゲーターさんも飲んでみたいですか？えーと、私が飲んだのはこのブランドのものですよー。", "0", "0", "0", "0", "cv_dorothy_26", "0", "0"},
[431225] = {431225, 13012, 29, 21, "0", "0", "你有想要實現的願望嗎？現在的我……可以滿足你的任何要求哦。", "ナビゲーターさんは、葉えたい夢がありますか？私なら……何でも葉えてあげられますよ。", "0", "0", "0", "0", "cv_dorothy_27", "0", "0"},
[431226] = {431226, 13012, 30, 22, "0", "0", "接下來是占卜的時間。", "さあ、占いの時間ですよ。", "0", "0", "0", "0", "cv_dorothy_28", "0", "0"},
[431227] = {431227, 13012, 31, 23, "0", "0", "和塔羅牌抽籤很像呢，猜中的話，會有獎勵哦。", "タロットに似ていますね。もし當たったら、ご褒美がありますよ。", "0", "0", "0", "0", "cv_dorothy_29", "0", "0"},
[431228] = {431228, 13012, 32, 24, "0", "0", "獎勵就是——多蘿西的好感度提升了。呀……你是不是在期待著一些朦朧而又美妙的事情呀？", "ご褒美は……ドロシーの好感度が上がりましたー！あれ？なんか期待しちゃってましたか？", "0", "0", "0", "0", "cv_dorothy_30", "0", "0"},
[431229] = {431229, 13012, 33, 25, "0", "0", "猜錯了？呵呵，那麼我就把大獎為你保留到下次吧。", "ハズれたんですか？ふふ。じゃあご褒美はお預けですね。", "0", "0", "0", "0", "cv_dorothy_31", "0", "0"},
[431230] = {431230, 13012, 34, 26, "0", "0", "呵呵，我就知道領航會在這個時間回來。", "ふっふーん。ナビゲーターさんがこの時間に帰ってくるの、知ってましたよ。", "0", "0", "0", "0", "cv_dorothy_32", "0", "0"},
[431231] = {431231, 13012, 35, 27, "0", "0", "想去哪裡看看嗎？一起走吧。", "行きたいところはありますか？私がご一緒しますよ。", "0", "0", "0", "0", "cv_dorothy_33", "0", "0"},
[431232] = {431232, 13012, 36, 28, "0", "0", "不用擔心，交給魔女姐姐吧。", "大丈夫です。魔女にお任せてください。", "0", "0", "0", "0", "cv_dorothy_34", "0", "0"},
[431233] = {431233, 13012, 37, 29, "0", "0", "有很多緣分在這裏聚集啊，你真是了不起的人。", "ここにはいろんな縁がありますね。さすがナビゲーターさんです。", "0", "0", "0", "0", "cv_dorothy_35", "0", "0"},
[431234] = {431234, 13012, 38, 30, "0", "0", "在這裏一切的相遇都是必然的。", "ここでは、全ての出會いが必然です。", "0", "0", "0", "0", "cv_dorothy_36", "0", "0"},
[431235] = {431235, 13012, 39, 31, "0", "0", "我的法術筆記在哪裡？", "私の魔法ノートを見ませんでしたか？", "0", "0", "0", "0", "cv_dorothy_37", "0", "0"},
[431236] = {431236, 13012, 40, 32, "0", "0", "法術炮臺的造價可是很貴的。", "魔法キャノンの製作費は高いですよ。", "0", "0", "0", "0", "cv_dorothy_38", "0", "0"},
[431237] = {431237, 13012, 41, 33, "0", "0", "真想回到過去見證領航的歷史啊。", "過去に戻って、ナビゲーターさんの歴史をこの目で見たいものです。", "0", "0", "0", "0", "cv_dorothy_39", "0", "0"},
[431238] = {431238, 13012, 42, 34, "0", "0", "改變，我們需要改變。", "変化しましょう。私たちは変化し続けるべきです。", "0", "0", "0", "0", "cv_dorothy_40", "0", "0"},
[431239] = {431239, 13012, 43, 35, "0", "0", "不用藏著掖著啦，魔女有全知之眼哦。", "隠さなくてもいいですよ。魔女は全てを見通すことができるんですから。", "0", "0", "0", "0", "cv_dorothy_41", "0", "0"},
[431240] = {431240, 13012, 44, 36, "0", "0", "異世界的聲音……", "異世界の聲……", "0", "0", "0", "0", "cv_dorothy_42", "0", "0"},
[431241] = {431241, 13012, 45, 37, "0", "0", "一起走吧。", "一緒に行きましょう。", "0", "0", "0", "0", "cv_dorothy_43", "0", "0"},
[431300] = {431300, 13013, 1, 1, "0", "0", "蒼霧殘響喵", "0", "0", "0", "0", "0", "cv_fururu_30", "0", "0"},
[431301] = {431301, 13013, 2, 2, "0", "0", "交給芙露露喵。", "0", "0", "0", "0", "0", "cv_fururu_2", "0", "0"},
[431302] = {431302, 13013, 3, 3, "0", "0", "嗯…嗯，所以是到芙露露登場了喵？", "0", "0", "0", "0", "0", "cv_fururu_1", "0", "0"},
[431303] = {431303, 13013, 4, 4, "0", "idle", "今天早上打早飯的時候被人多送了一個雞蛋，說是讓芙露露長高些什麼的。不過，芙露露當時已經吃飽了，所以就偷偷留給你了喵，喏。", "0", "0", "0", "0", "0", "cv_fururu_3", "0", "0"},
[431304] = {431304, 13013, 5, 4, "0", "idle", "方舟上有很多貓咪，不過因為大家都有自己的爸爸媽媽，所以只有中午才能出來陪芙露露玩。", "0", "0", "0", "0", "0", "cv_fururu_4", "0", "0"},
[431305] = {431305, 13013, 6, 4, "0", "idle", "那個叫多洛莉絲的姐姐…和芙露露之前認識的一個人很像喵。", "0", "0", "0", "0", "0", "cv_fururu_27", "0", "0"},
[431306] = {431306, 13013, 7, 5, "1_》_0_0.8", "level1", "喵喵喵？", "0", "0", "0", "0", "0", "cv_fururu_28", "0", "0"},
[431307] = {431307, 13013, 8, 5, "1_》_0_0.8", "level1", "幹嘛喵，領航你找芙露露有事喵？芙露露現在不忙，可以陪你聊很久很久。", "0", "0", "0", "0", "0", "cv_fururu_5", "0", "0"},
[431308] = {431308, 13013, 9, 5, "1_》_100_1.5", "level2", "領航，你也喜歡半夜去甲板喵？之前好像有幾次看到過你，不過你都沒有注意到芙露露喵。下次要去的話，可以叫上我喵？", "0", "0", "0", "0", "0", "cv_fururu_6", "0", "0"},
[431309] = {431309, 13013, 10, 5, "1_》_500_2", "level3", "明明是已經過去很久了的事情……為什麼看到你，芙露露就會忍不住又回憶起來呢喵？領航…芙露露的胸口…還有頭……都好痛…好痛……像是要溺亡了一樣。", "0", "0", "0", "0", "0", "cv_fururu_7", "0", "0"},
[431310] = {431310, 13013, 11, 5, "1_》_1000_2.5", "level4", "芙露露明明…明明已經沒有活下去的理由了。但是在那個時候卻一直有個溫柔的聲音在呼喚著芙露露，在拯救著芙露露。芙露露第一次知道…原來芙露露只是像是往常那樣活著，醒過來也能給於他人幸福。", "0", "0", "0", "0", "0", "cv_fururu_8", "0", "0"},
[431311] = {431311, 13013, 12, 6, "0", "0", "變強了喵。", "0", "0", "0", "0", "0", "cv_fururu_9", "0", "0"},
[431312] = {431312, 13013, 13, 7, "0", "0", "嗯嗯，稍微長高一些了喵。", "0", "0", "0", "0", "0", "cv_fururu_10", "0", "0"},
[431313] = {431313, 13013, 14, 8, "0", "0", "哎？已經到這一步了喵？沒辦法了，稍微慶賀一下吧。哇哦——", "0", "0", "0", "0", "0", "cv_fururu_11", "0", "0"},
[431314] = {431314, 13013, 15, 9, "0", "0", "嗯嗯，芙露露知道了喵。", "0", "0", "0", "0", "0", "cv_fururu_12", "0", "0"},
[431315] = {431315, 13013, 16, 10, "0", "0", "輪到芙露露上場了喵~", "0", "0", "0", "0", "0", "cv_fururu_13", "0", "0"},
[431316] = {431316, 13013, 17, 11, "0", "0", "哦——快看快看，我們贏了喵。", "0", "0", "0", "0", "0", "cv_fururu_14", "0", "0"},
[431317] = {431317, 13013, 18, 12, "0", "0", "唉，戰鬥已經結束了嗎喵？我們贏了喵？", "0", "0", "0", "0", "0", "cv_fururu_15", "0", "0"},
[431318] = {431318, 13013, 19, 13, "0", "0", "嗚…稍微有些倒楣，不過總算還是贏了喵。", "0", "0", "0", "0", "0", "cv_fururu_16", "0", "0"},
[431319] = {431319, 13013, 20, 14, "0", "0", "實在是忙不過來了喵……下次再來喵。", "0", "0", "0", "0", "0", "cv_fururu_17", "0", "0"},
[431320] = {431320, 13013, 23, 16, "0", "0", "抱歉，馬上就來喵！", "0", "0", "0", "0", "0", "cv_fururu_18", "0", "0"},
[431321] = {431321, 13013, 26, 19, "0", "0", "嗚喵喵……", "0", "0", "0", "0", "0", "cv_fururu_19", "0", "0"},
[431322] = {431322, 13013, 27, 20, "0", "0", "不要洗澡…不要洗澡…不要洗澡喵……", "0", "0", "0", "0", "0", "cv_fururu_20", "0", "0"},
[431323] = {431323, 13013, 28, 21, "0", "0", "咦？身體暖烘烘的，真舒服喵~", "0", "0", "0", "0", "0", "cv_fururu_21", "0", "0"},
[431324] = {431324, 13013, 29, 21, "0", "0", "芙露露不要出去…芙露露不要出去…芙露露不要出去喵……", "0", "0", "0", "0", "0", "cv_fururu_22", "0", "0"},
[431325] = {431325, 13013, 30, 22, "0", "0", "好像有什麼東西冒出來了喵。", "0", "0", "0", "0", "0", "cv_fururu_23", "0", "0"},
[431326] = {431326, 13013, 31, 23, "0", "0", "嗯…這是什麼新遊戲喵？", "0", "0", "0", "0", "0", "cv_fururu_24", "0", "0"},
[431327] = {431327, 13013, 32, 24, "0", "0", "嘿嘿嘿，真厲害喵。", "0", "0", "0", "0", "0", "cv_fururu_25", "0", "0"},
[431328] = {431328, 13013, 33, 25, "0", "0", "唉，原來你不認識芙露露喵？", "0", "0", "0", "0", "0", "cv_fururu_26", "0", "0"},
[431329] = {431329, 13013, 34, 26, "0", "0", "又見面了喵，領航今天要從哪裡開始忙起喵？", "0", "0", "0", "0", "0", "cv_fururu_29", "0", "0"},
[431330] = {431330, 13013, 35, 27, "0", "0", "出擊喵。", "0", "0", "0", "0", "0", "cv_fururu_31", "0", "0"},
[431331] = {431331, 13013, 36, 28, "0", "0", "芙露露不會認輸的。", "0", "0", "0", "0", "0", "cv_fururu_32", "0", "0"},
[431332] = {431332, 13013, 37, 29, "0", "0", "要拜訪哪位喵？", "0", "0", "0", "0", "0", "cv_fururu_33", "0", "0"},
[431333] = {431333, 13013, 38, 30, "0", "0", "招募駕駛員喵。", "0", "0", "0", "0", "0", "cv_fururu_34", "0", "0"},
[431334] = {431334, 13013, 39, 31, "0", "0", "購置新裝備喵。", "0", "0", "0", "0", "0", "cv_fururu_35", "0", "0"},
[431335] = {431335, 13013, 40, 32, "0", "0", "去購物喵？", "0", "0", "0", "0", "0", "cv_fururu_36", "0", "0"},
[431336] = {431336, 13013, 41, 33, "0", "0", "好好檢查下名片喵。", "0", "0", "0", "0", "0", "cv_fururu_37", "0", "0"},
[431337] = {431337, 13013, 42, 34, "0", "0", "變更設置", "0", "0", "0", "0", "0", "cv_fururu_38", "0", "0"},
[431338] = {431338, 13013, 43, 35, "0", "0", "有新的快遞箱喵？", "0", "0", "0", "0", "0", "cv_fururu_39", "0", "0"},
[431339] = {431339, 13013, 44, 36, "0", "0", "世界聊天喵", "0", "0", "0", "0", "0", "cv_fururu_40", "0", "0"},
[431340] = {431340, 13013, 45, 37, "0", "0", "芙露露喵", "0", "0", "0", "0", "0", "cv_fururu_41", "0", "0"},
[431400] = {431400, 13014, 1, 1, "0", "0", "蒼霧殘響", "0", "0", "0", "0", "0", "cv_momoca_31", "0", "0"},
[431401] = {431401, 13014, 2, 2, "0", "0", "……這樣看上去，領航小小的真可愛。", "0", "0", "0", "0", "0", "cv_momoca_2", "0", "0"},
[431402] = {431402, 13014, 3, 3, "0", "0", "我叫莫莫卡…來自雪鴞小隊…", "0", "0", "0", "0", "0", "cv_momoca_1", "0", "0"},
[431403] = {431403, 13014, 4, 4, "0", "idle", "領航睡著了嗎？如果睡著的話要記得蓋被子哦…不過現在也聽不到了吧。", "0", "0", "0", "0", "0", "cv_momoca_3", "0", "0"},
[431404] = {431404, 13014, 5, 4, "0", "idle", "這裏沒有雪嗎？真可惜，我還挺喜歡雪的。", "0", "0", "0", "0", "0", "cv_momoca_4", "0", "0"},
[431405] = {431405, 13014, 6, 4, "0", "idle", "雪鴞的成員都是很溫柔的人，特別是隊長莉迪婭，讓我想到了我的母親。", "0", "0", "0", "0", "0", "cv_momoca_28", "0", "0"},
[431406] = {431406, 13014, 7, 5, "1_》_0_0.8", "level1", "我想找到我真正的故鄉，但是我完全不知道她在何處，也可能就埋葬在我走過的某片雪地之下。", "0", "0", "0", "0", "0", "cv_momoca_29", "0", "0"},
[431407] = {431407, 13014, 8, 5, "1_》_0_0.8", "level1", "嗯？", "0", "0", "0", "0", "0", "cv_momoca_5", "0", "0"},
[431408] = {431408, 13014, 9, 5, "1_》_100_1.5", "level2", "呼~呼~領航，請喝冰咖啡。", "0", "0", "0", "0", "0", "cv_momoca_6", "0", "0"},
[431409] = {431409, 13014, 10, 5, "1_》_500_2", "level3", "領航你喜歡雪花嗎？從天上誕生，卻在地上死亡，總感覺和我一樣。", "0", "0", "0", "0", "0", "cv_momoca_7", "0", "0"},
[431410] = {431410, 13014, 11, 5, "1_》_1000_2.5", "level4", "我的身體很冷，就算這樣你還願意擁抱我嗎？是嗎，你不介意這一點嗎……感受到了…領航的氣息和體溫，仿佛像家的感覺一樣，讓我安心……", "0", "0", "0", "0", "0", "cv_momoca_8", "0", "0"},
