[431500] = {431500, 13015, 1, 1, "0", "0", "蒼霧殘響", "0", "0", "0", "0", "0", "cv_lina_1", "0", "0"},
[431501] = {431501, 13015, 2, 2, "0", "0", "明白了，到時候爭取時間的事情就交給我吧，我會掩護著你撤退的。", "0", "0", "0", "0", "0", "cv_lina_2", "0", "0"},
[431502] = {431502, 13015, 3, 3, "0", "0", "超級假面人1號，莉娜·布恩登場！又見面了，boy~", "0", "0", "0", "0", "0", "cv_lina_3", "0", "0"},
[431503] = {431503, 13015, 4, 4, "0", "idle", "和你玩個小遊戲好了，來猜猜我身上有多少“武器”吧，猜對了就獎勵你一槍~錯了的話，我保證會讓你舒服得死去活來，你覺得如何？", "0", "0", "0", "0", "0", "cv_lina_4", "0", "0"},
[431504] = {431504, 13015, 5, 4, "0", "idle", "想掃掃我肚子上的碼？哈，也許你可以趁我睡著的時候來掃，至於現在……滾蛋吧~", "0", "0", "0", "0", "0", "cv_lina_5", "0", "0"},
[431505] = {431505, 13015, 6, 4, "0", "idle", "放心放心，我的寶貝可不是危險的傢夥。既不會走火，也不會傷到人……如果被她射中會怎麼樣？你要試試嗎？", "0", "0", "0", "0", "0", "cv_lina_6", "0", "0"},
[431506] = {431506, 13015, 7, 5, "1_》_0_0.8", "level1", "大熱天也會戴著圍巾嗎？就是要紅圍巾才有超級英雄的氛圍，boy你懂不懂啊？我的圍巾之下可是隱藏著必殺——自爆裝置的。", "0", "0", "0", "0", "0", "cv_lina_7", "0", "0"},
[431507] = {431507, 13015, 8, 5, "1_》_0_0.8", "level1", "只要吹起哨子，被我認可的人，志同道合的人便會彙聚過來保護人類、世界、地球的安危，這便是我理想中的超級英雄聯盟，而你便是第二位持哨人。", "0", "0", "0", "0", "0", "cv_lina_8", "0", "0"},
[431508] = {431508, 13015, 9, 5, "1_》_100_1.5", "level2", "無聊啊，太無聊了~！喂boy，你要不要和我出去轉換一下心情，上個廁所，吃個飯，順便打擊一下罪犯。", "0", "0", "0", "0", "0", "cv_lina_9", "0", "0"},
[431509] = {431509, 13015, 10, 5, "1_》_500_2", "level3", "我的父母死在了一場犯罪中，所以我要用畢生來打擊邪惡……哈，很老土的故事吧？像那些故事中的超級英雄一樣，一樣愚蠢，一樣自大，但~這就是我~", "0", "0", "0", "0", "0", "cv_lina_10", "0", "0"},
[431510] = {431510, 13015, 11, 5, "1_》_1000_2.5", "level4", "哦~超級假面人2號，今天的多瑙也是和平的一天嗎？那要和我去卡佳找點樂子嗎？", "0", "0", "0", "0", "0", "cv_lina_11", "0", "0"},
[431511] = {431511, 13015, 12, 6, "0", "0", "能感覺到心中的烈火。", "0", "0", "0", "0", "0", "cv_lina_12", "0", "0"},
[431512] = {431512, 13015, 13, 7, "0", "0", "嗯，讓我們加把勁吧。", "0", "0", "0", "0", "0", "cv_lina_13", "0", "0"},
[431513] = {431513, 13015, 14, 8, "0", "0", "秉持著你自己正義就好，我會和你一起的。", "0", "0", "0", "0", "0", "cv_lina_14", "0", "0"},
