[431600] = {431600, 13016, 1, 1, "0", "0", "蒼霧殘響", "0", "0", "0", "0", "0", "cv_dororisu_ss_001", "0", "0"},
[431601] = {431601, 13016, 2, 2, "0", "0", "要我穿著這身衣服站在這裏嗎？有點害羞呢……感覺……比偶像服還要過分！", "0", "0", "0", "0", "0", "cv_dororisu_ss_002", "0", "0"},
[431602] = {431602, 13016, 3, 3, "0", "0", "領航……到約定的時間了哦。我已經準備好了。", "0", "0", "0", "0", "0", "cv_dororisu_ss_003", "0", "0"},
[431603] = {431603, 13016, 4, 4, "0", "idle", "領航，你看……你給我的戒指，我一直都戴在手上哦。", "0", "0", "0", "0", "0", "cv_dororisu_ss_004", "0", "0"},
[431604] = {431604, 13016, 5, 4, "0", "idle", "如果……我能讓每個人都能擁有各自的幸福就好了，如果我再努力一點就好了。", "0", "0", "0", "0", "0", "cv_dororisu_ss_005", "0", "0"},
