[431606] = {431606, 13016, 7, 5, "1_》_0_0.8", "level1", "失落的時候是怎麼度過的？我想想，“加油！打起精神來！我一定可以的！”大概會這麼安慰自己吧！", "0", "0", "0", "0", "0", "cv_dororisu_ss_007", "0", "0"},
[431607] = {431607, 13016, 8, 5, "1_》_0_0.8", "level1", "如果累了的時候可以再來找您嗎……想要您像那天一樣對我!", "0", "0", "0", "0", "0", "cv_dororisu_ss_008", "0", "0"},
[431608] = {431608, 13016, 9, 5, "1_》_100_1.5", "level2", "我就像一顆一顆漂浮在無垠中的石頭……被您的重力所捕獲……嘿嘿……希望我能在粉身碎骨的那一刻迸發出耀眼的光芒……!", "0", "0", "0", "0", "0", "cv_dororisu_ss_009", "0", "0"},
[431609] = {431609, 13016, 10, 5, "1_》_500_2", "level3", "總覺得在不為人知的地方……您一次又一次地保護了我……不……請您忘掉我剛剛的話……應、應該是我意識過剩了！", "0", "0", "0", "0", "0", "cv_dororisu_ss_010", "0", "0"},
[431610] = {431610, 13016, 11, 5, "1_》_1000_2.5", "level4", "我、我喜、喜歡歡……領、領……和領航在一起時候的感覺！", "0", "0", "0", "0", "0", "cv_dororisu_ss_011", "0", "0"},
[431611] = {431611, 13016, 12, 6, "0", "0", "這樣……就能讓我再陪伴您一會了吧！", "0", "0", "0", "0", "0", "cv_dororisu_ss_012", "0", "0"},
[431612] = {431612, 13016, 13, 7, "0", "0", "……即然我已經被點燃……那接下來……我想要和太陽靠得更近一點也沒問題吧……！", "0", "0", "0", "0", "0", "cv_dororisu_ss_013", "0", "0"},
[431613] = {431613, 13016, 14, 8, "0", "0", "很少見我穿這種風格的衣服……？嗯……那您覺得怎麼樣呢……嘿嘿……", "0", "0", "0", "0", "0", "cv_dororisu_ss_014", "0", "0"},
[431614] = {431614, 13016, 15, 9, "0", "0", "咦！？奇、奇怪的石頭增加了！？為什麼？", "0", "0", "0", "0", "0", "cv_dororisu_ss_015", "0", "0"},
[431615] = {431615, 13016, 16, 10, "0", "0", "嘿！我會加油的！", "0", "0", "0", "0", "0", "cv_dororisu_ss_016", "0", "0"},
[431616] = {431616, 13016, 17, 11, "0", "0", "我也變得有點可靠了呢……！", "0", "0", "0", "0", "0", "cv_dororisu_ss_017", "0", "0"},
[431617] = {431617, 13016, 18, 12, "0", "0", "大家都有點累了呢……回去好好休息吧！", "0", "0", "0", "0", "0", "cv_dororisu_ss_018", "0", "0"},
[431618] = {431618, 13016, 19, 13, "0", "0", "嗚啊……大家都沒事吧？", "0", "0", "0", "0", "0", "cv_dororisu_ss_019", "0", "0"},
