[431701] = {431701, 13017, 2, 2, "0", "0", "領航真的是……兩個人待在一起的話，直接叫我小環好不好？", "0", "0", "0", "0", "0", "cv_jiushijiuhuan_2", "0", "0"},
[431702] = {431702, 13017, 3, 3, "0", "0", "數字的九十九，九十九環的環，從今天開始我們就是新婚夫妻了……現在還不行嗎？", "0", "0", "0", "0", "0", "cv_jiushijiuhuan_3", "0", "0"},
[431703] = {431703, 13017, 4, 4, "0", "idle", "哈哈，很少看到親愛的會發呆呢，真的忍不住想要捉弄一下，不過嘛我還是忍住了，怎麼樣，很了不起吧？", "0", "0", "0", "0", "0", "cv_jiushijiuhuan_4", "0", "0"},
[431704] = {431704, 13017, 5, 4, "0", "idle", "會很細心地，很積極地面對每一個駕駛員，親愛的是個很願意誇獎別人的人……嗯？我是不會嫉妒這樣的正常交流的啦。", "0", "0", "0", "0", "0", "cv_jiushijiuhuan_5", "0", "0"},
[431705] = {431705, 13017, 6, 4, "0", "idle", "親愛的在想什麼事情呢？我還蠻擅長傾聽的，不介意的話和我說說吧，我也正因為親愛的好久沒有陪我說話感到有一點一點一點寂寞。", "0", "0", "0", "0", "0", "cv_jiushijiuhuan_6", "0", "0"},
[431706] = {431706, 13017, 7, 5, "1_》_0_0.8", "level1", "我在想該怎麼稱呼領航比較好，先生？當家的？親愛的？Honey？……你覺得哪個好？", "0", "0", "0", "0", "0", "cv_jiushijiuhuan_7", "0", "0"},
[431707] = {431707, 13017, 8, 5, "1_》_0_0.8", "level1", "忙這麼久真是辛苦了，要不要和我一起去吃點甜品，我知道有一家店最近在開著活動呢，會幫到店的情侶拍攝有魔法的照片哦。", "0", "0", "0", "0", "0", "cv_jiushijiuhuan_8", "0", "0"},
[431708] = {431708, 13017, 9, 5, "1_》_100_1.5", "level2", "那……那個，聽我說啊，今天啊我的父母都不在家，晚上只有一個人感覺很孤單……要一起出來玩，就我們兩個，一起去熱鬧一點的地方逛逛。", "0", "0", "0", "0", "0", "cv_jiushijiuhuan_9", "0", "0"},
[431709] = {431709, 13017, 10, 5, "1_》_500_2", "level3", "我們都已經是這樣的關係了，親愛的有沒有什麼事情想要我做的，可以提一些大膽點的要求，真的不行的話我會說出來的……今天去參加99場模擬戰？不行不行不行！", "0", "0", "0", "0", "0", "cv_jiushijiuhuan_10", "0", "0"},
[431710] = {431710, 13017, 11, 5, "1_》_1000_2.5", "level4", "給你帶了桃子，真的好甜，回家的時候記得嘗嘗看，如果今天沒有其他事情的話，晚上我想陪吉雅妹妹玩……接下來我的人生規劃就是——要一直待在親愛的身邊！", "0", "0", "0", "0", "0", "cv_jiushijiuhuan_11", "0", "0"},
[431711] = {431711, 13017, 12, 6, "0", "0", "嗯嗯……收穫了很多的領航能量。", "0", "0", "0", "0", "0", "cv_jiushijiuhuan_12", "0", "0"},
[431712] = {431712, 13017, 13, 7, "0", "0", "哇啊啊！親愛的能量多到溢出了！", "0", "0", "0", "0", "0", "cv_jiushijiuhuan_13", "0", "0"},
[431713] = {431713, 13017, 14, 8, "0", "0", "哦——這像是要靈魂出竅般的誇張感覺！不愧是親愛的！", "0", "0", "0", "0", "0", "cv_jiushijiuhuan_14", "0", "0"},
[431714] = {431714, 13017, 15, 9, "0", "0", "心在噗通噗通地跳。", "0", "0", "0", "0", "0", "cv_jiushijiuhuan_15", "0", "0"},
[431715] = {431715, 13017, 16, 10, "0", "0", "九十九環，作為駕駛員開始戰鬥。", "0", "0", "0", "0", "0", "cv_jiushijiuhuan_16", "0", "0"},
