[431723] = {431723, 13017, 27, 20, "0", "0", "洗澡洗澡~戰鬥過後就要痛痛快快地洗澡洗澡~", "0", "0", "0", "0", "0", "cv_jiushijiuhuan_24", "0", "0"},
[431724] = {431724, 13017, 28, 21, "0", "0", "我等你很久了哦，怎麼了剛剛在忙嗎，那就等會讓我來幫你也做個按摩舒服舒服吧。", "0", "0", "0", "0", "0", "cv_jiushijiuhuan_25", "0", "0"},
