[431801] = {431801, 13018, 2, 2, "0", "0", "只要不用說話就好。", "0", "0", "0", "0", "0", "cv_mittshiva_2", "0", "0"},
[431802] = {431802, 13018, 3, 3, "0", "0", "修米婭號空間飛船通訊員——密托希瓦，前來報到……我自己的聲音？不行，那樣會發生可怕的事情。", "0", "0", "0", "0", "0", "cv_mittshiva_3", "0", "0"},
[431803] = {431803, 13018, 4, 4, "0", "idle", "“滴——滴——滴——您所通訊的物件不在服務區——”", "0", "0", "0", "0", "0", "cv_mittshiva_4", "0", "0"},
[431804] = {431804, 13018, 5, 4, "0", "idle", "這裡是修米婭號空間飛船，我們帶著善意而來，請接收到該資訊的文明回應我們的善意……沒有回應，太好了……", "0", "0", "0", "0", "0", "cv_mittshiva_5", "0", "0"},
[431805] = {431805, 13018, 6, 4, "0", "idle", "弗洛維拉，艾伊瓦蒂，西法裡斯……果然只剩下我們四個人了……反正旅行也不能繼續了，這樣也不錯。", "0", "0", "0", "0", "0", "cv_mittshiva_6", "0", "0"},
[431806] = {431806, 13018, 7, 5, "1_》_0_0.8", "level1", "誒？！不……不行！", "0", "0", "0", "0", "0", "cv_mittshiva_7", "0", "0"},
[431807] = {431807, 13018, 8, 5, "1_》_0_0.8", "level1", "這樣頻繁地觸摸是地球人問好的方式嗎？果然還是很難接受——文明交流……", "0", "0", "0", "0", "0", "cv_mittshiva_8", "0", "0"},
[431808] = {431808, 13018, 9, 5, "1_》_100_1.5", "level2", "為什麼領航你在這裡從不說話呢？……難道這裡也有不能說話的詛咒嗎？……嗚——還好我沒有用自己的嘴發聲。", "0", "0", "0", "0", "0", "cv_mittshiva_9", "0", "0"},
[431809] = {431809, 13018, 10, 5, "1_》_500_2", "level3", "當得知要擔任通訊員的時候，我恨不得下一刻整個宇宙都陷入冷寂。不過還好，實際的工作內容只是廣播預先寫好的短訊而已。", "0", "0", "0", "0", "0", "cv_mittshiva_10", "0", "0"},
[431810] = {431810, 13018, 11, 5, "1_》_1000_2.5", "level4", "每到一個新的星球就要先進行為期一個米狄爾月時間的全球旅行，這是修米婭上的傳統……怎麼說我也是米狄爾人，也是會嚮往旅行的。只是比起什麼文明交流，我更喜歡欣賞不同的風景而已。", "0", "0", "0", "0", "0", "cv_mittshiva_11", "0", "0"},
[431811] = {431811, 13018, 12, 6, "0", "0", "已經到極限了……", "0", "0", "0", "0", "0", "cv_mittshiva_12", "0", "0"},
[431812] = {431812, 13018, 13, 7, "0", "0", "極限被突破了？！", "0", "0", "0", "0", "0", "cv_mittshiva_13", "0", "0"},
