[431826] = {431826, 13018, 30, 22, "0", "0", "唔？唔！唔！", "0", "0", "0", "0", "0", "cv_mittshiva_27", "0", "0"},
[431827] = {431827, 13018, 31, 23, "0", "0", "唔……", "0", "0", "0", "0", "0", "cv_mittshiva_28", "0", "0"},
[431828] = {431828, 13018, 32, 24, "0", "0", "哼♪哼♪", "0", "0", "0", "0", "0", "cv_mittshiva_29", "0", "0"},
[431829] = {431829, 13018, 33, 25, "0", "0", "哼！", "0", "0", "0", "0", "0", "cv_mittshiva_30", "0", "0"},
[431830] = {431830, 13018, 34, 26, "0", "0", "……通訊員密托希瓦正在認真監聽宇宙電波……絕對沒有偷懶睡覺。", "0", "0", "0", "0", "0", "cv_mittshiva_31", "0", "0"},
[431831] = {431831, 13018, 35, 27, "0", "0", "監測到原罪信號。", "0", "0", "0", "0", "0", "cv_mittshiva_32", "0", "0"},
[431832] = {431832, 13018, 36, 28, "0", "0", "這次的敵人是……駕駛員？", "0", "0", "0", "0", "0", "cv_mittshiva_33", "0", "0"},
[431833] = {431833, 13018, 37, 29, "0", "0", "好多人……", "0", "0", "0", "0", "0", "cv_mittshiva_34", "0", "0"},
[431834] = {431834, 13018, 38, 30, "0", "0", "能招募別人來頂替我的位子嗎？", "0", "0", "0", "0", "0", "cv_mittshiva_35", "0", "0"},
[431835] = {431835, 13018, 39, 31, "0", "0", "讓別人先選吧……", "0", "0", "0", "0", "0", "cv_mittshiva_36", "0", "0"},
[431836] = {431836, 13018, 40, 32, "0", "0", "網路購物？真方便啊……", "0", "0", "0", "0", "0", "cv_mittshiva_37", "0", "0"},
[431837] = {431837, 13018, 41, 33, "0", "0", "領航的資料！還是不要多看比較好……", "0", "0", "0", "0", "0", "cv_mittshiva_38", "0", "0"},
[431838] = {431838, 13018, 42, 34, "0", "0", "不會點壞吧……", "0", "0", "0", "0", "0", "cv_mittshiva_39", "0", "0"},
[431839] = {431839, 13018, 43, 35, "0", "0", "好老土的通訊方式……對不起，我不是那個意思。", "0", "0", "0", "0", "0", "cv_mittshiva_40", "0", "0"},
[431840] = {431840, 13018, 44, 36, "0", "0", "我……我……你……你……", "0", "0", "0", "0", "0", "cv_mittshiva_41", "0", "0"},
[431841] = {431841, 13018, 45, 37, "0", "0", "碰一下不要緊吧？", "0", "0", "0", "0", "0", "cv_mittshiva_42", "0", "0"},
[431900] = {431900, 13019, 1, 1, "0", "0", "蒼霧殘響", "ハツリバーブ。", "0", "0", "0", "0", "cv_zhaowu_1", "0", "0"},
[431901] = {431901, 13019, 2, 2, "0", "0", "這樣真的好嗎……讓我這樣的罪人站在這裏……", "本當に良いのでしょうか……わたくしのような罪深い者がここにいて……", "0", "0", "0", "0", "cv_zhaowu_2", "0", "0"},
[431902] = {431902, 13019, 3, 3, "0", "0", "初次見面，我是來自“學宮”的……啊，不，現在應該叫平心社了……我是平心社的朝霧，小……小女子不才，我……我會全心全意支援領航的。", "初めてお目にかかります。學宮（がっきゅう）……あ、いえ。今は平心社（へいしんしゃ）の朝霧（ちょうむ）と申します。ふ、不束者ですが、全身全霊でナビゲーターをお支えします。", "0", "0", "0", "0", "cv_zhaowu_3", "0", "0"},
[431903] = {431903, 13019, 4, 4, "0", "idle", "“學宮”……是我出身、長大的地方，一個能讓人能靜下心來讀書的地方……但是我現在已經不用回去了。沒事的……是我自己決定出來的，我是為了領航，也是為了我自己而來的。", "學宮……わたくしが生まれ育ち、心靜かに學ぶことができた場所。……でももう帰ることはありません。……わたくし自身のために、そしてナビゲーターのために……自分で決斷したのです。", "0", "0", "0", "0", "cv_zhaowu_4", "0", "0"},
[431904] = {431904, 13019, 5, 4, "0", "idle", "我覺得……領航就是我們一直在等待的人。我們“平心社”的責任，我的目標在遇見領航的時候就已經完成了，接下來只需要陪伴著您就好了。", "わたくし達が待ち望んでいたのはきっと……ナビゲーターです。平心社の目的と使命は、あなたと出會った瞬間に達成されました。これからは、あなたの傍にいるだけで良いのです。", "0", "0", "0", "0", "cv_zhaowu_5", "0", "0"},
[431905] = {431905, 13019, 6, 4, "0", "idle", "我認為領航的存在比任何人都重要——所以在危險的時候，請毫不留情地使用我吧，能和您經歷過這麼多事情，我已經很滿足了。", "ナビゲーターは誰よりも重要な存在です。危険な時は迷わずわたくしを盾にしてください。あなたと多くの時間を共有することができて、わたくしはもう十分満足です。", "0", "0", "0", "0", "cv_zhaowu_6", "0", "0"},
[431906] = {431906, 13019, 7, 5, "1_》_0_0.8", "level1", "領航，請不要……碰觸我這個戴罪之人。", "ナビゲーター……どうかこの咎人に觸れないでください。", "0", "0", "0", "0", "cv_zhaowu_7", "0", "0"},
[431907] = {431907, 13019, 8, 5, "1_》_0_0.8", "level1", "有更值得您去陪伴的駕駛員，領航，為什麼要呆在我身邊呢。", "わたくしよりも、傍にいるべきドライバーがいるはずです。なのにどうして……？", "0", "0", "0", "0", "cv_zhaowu_8", "0", "0"},
[431908] = {431908, 13019, 9, 5, "1_》_100_1.5", "level2", "我是作為罪人降生在這個世界上的，但是謝謝您能相信我。您允許我站在您的身邊，不知道為什麼……讓我感到放鬆。", "咎人としてこの世に生を受けたわたくしを信じてくださって、ありがとうございます。あなたの隣はなぜか……心が安らぐのです。", "0", "0", "0", "0", "cv_zhaowu_9", "0", "0"},
[431909] = {431909, 13019, 10, 5, "1_》_500_2", "level3", "我犯下了什麼過錯……您無需擔心，相伴在您身邊的每一天，便是在贖罪的每一天，但是——我希望您知道，我並不是為了贖罪待在您身邊的，而是我希望，我想要……我憧憬著您。", "わたくしが犯した罪、ですか……どうか、お気になさらないでください。あなたのそばにいる毎日が償いの日々ですが……罪滅ぼしのためにあなたの傍にいるのではありません。わたくしが……わたくしがあなたに憧れているからです。", "0", "0", "0", "0", "cv_zhaowu_10", "0", "0"},
[431910] = {431910, 13019, 11, 5, "1_》_1000_2.5", "level4", "領航……領航……", "ナビゲーター……ナビゲーター……", "0", "0", "0", "0", "cv_zhaowu_11", "0", "0"},
[431911] = {431911, 13019, 12, 6, "0", "0", "呼，這……這是給我的嗎？", "こ…これをわたくしに……？", "0", "0", "0", "0", "cv_zhaowu_12", "0", "0"},
[431912] = {431912, 13019, 13, 7, "0", "0", "就算您習以為常，我依然能感受到其中真實的心意。", "あなたにとっては當たり前のことかもしれませんが、わたくしは真心を感じています。", "0", "0", "0", "0", "cv_zhaowu_13", "0", "0"},
[431913] = {431913, 13019, 14, 8, "0", "0", "呼……呼……呼……我做到了，我……現在感覺很好，很安心。", "はぁ、はぁ……成し遂げました。いま……とっても、ホッとしています。", "0", "0", "0", "0", "cv_zhaowu_14", "0", "0"},
[431914] = {431914, 13019, 15, 9, "0", "0", "我的力量，全部都……為您所用。", "わたくしの力すべてを……あなたに捧げます。", "0", "0", "0", "0", "cv_zhaowu_15", "0", "0"},
[431915] = {431915, 13019, 16, 10, "0", "0", "平心社，“天醫”朝霧，抵達戰場。", "平心社の天醫（てんい）、朝霧。ここにあり。", "0", "0", "0", "0", "cv_zhaowu_16", "0", "0"},
[431916] = {431916, 13019, 17, 11, "0", "0", "成功了……你看到了嗎，領航！", "やりました……見ていただけましたか、ナビゲーター！", "0", "0", "0", "0", "cv_zhaowu_17", "0", "0"},
[431917] = {431917, 13019, 18, 12, "0", "0", "如果有受傷一定要馬上和我講哦。", "もし怪我をしたらすぐわたくしにおっしゃってください。", "0", "0", "0", "0", "cv_zhaowu_18", "0", "0"},
[431918] = {431918, 13019, 19, 13, "0", "0", "如果沒有我參戰……領航一定會獲得更完美的勝利吧。", "わたくしさえいなければ……きっとナビゲーターは完璧な勝利を手にされていたはず……", "0", "0", "0", "0", "cv_zhaowu_19", "0", "0"},
[431919] = {431919, 13019, 20, 14, "0", "0", "嗚……領航……您先走，我……隨後就到。", "うぅ……ナビゲーター、早くお逃げください……わたくしが背中をお守りします。", "0", "0", "0", "0", "cv_zhaowu_20", "0", "0"},
[431920] = {431920, 13019, 23, 16, "0", "0", "哪裡受傷了嗎？", "どこを怪我されたんですか？", "0", "0", "0", "0", "cv_zhaowu_21", "0", "0"},
[431921] = {431921, 13019, 26, 19, "0", "0", "讓我……看看傷口。", "傷口をお見せください。", "0", "0", "0", "0", "cv_zhaowu_22", "0", "0"},
[431922] = {431922, 13019, 25, 18, "0", "0", "我要在這裏償還我身為“天醫”的人之罪，我不會再讓你們傷害到大家的。", "「天醫」即ち「人の罪」。これがその償い。二度と仲間を傷つけさせません。", "0", "0", "0", "0", "cv_zhaowu_23", "0", "0"},
[431923] = {431923, 13019, 24, 17, "0", "0", "這份罪責，我還清了嗎……？", "罪を償えたでしょうか……", "0", "0", "0", "0", "cv_zhaowu_24", "0", "0"},
[431924] = {431924, 13019, 27, 20, "0", "0", "啊……如果您不嫌棄的話……", "あ……もし……あなたさえ良ければ……", "0", "0", "0", "0", "cv_zhaowu_25", "0", "0"},
[431925] = {431925, 13019, 28, 21, "0", "0", "在開始之前，請戴好護具，保護好自己……", "最初に防具を著用し、ご自分の體をお守りください……", "0", "0", "0", "0", "cv_zhaowu_26", "0", "0"},
[431926] = {431926, 13019, 29, 21, "0", "0", "還沒有開始嗎……沒關係，在您做好準備之前，我會一直忍耐的。", "まだ始まらないんですね……大丈夫です。準備が整うまでお待ちします。", "0", "0", "0", "0", "cv_zhaowu_27", "0", "0"},
[431927] = {431927, 13019, 30, 22, "0", "0", "需要我來幫您一起嗎……雖然我可能……起不到什麼作用。", "お手伝いいたしましょうか……何の役にも立たないかもしれませんが……", "0", "0", "0", "0", "cv_zhaowu_28", "0", "0"},
[431928] = {431928, 13019, 31, 23, "0", "0", "領航……您……還記得我？", "ナビゲーター……わたくしのこと、覚えていらっしゃいますよね？", "0", "0", "0", "0", "cv_zhaowu_29", "0", "0"},
[431929] = {431929, 13019, 32, 24, "0", "0", "呼……謝謝您。", "ふぅ……ありがとうございます。", "0", "0", "0", "0", "cv_zhaowu_30", "0", "0"},
[431930] = {431930, 13019, 33, 25, "0", "0", "這也是沒辦法的事情……畢竟是我啊……", "當然でしょうね……わたくしですから……", "0", "0", "0", "0", "cv_zhaowu_31", "0", "0"},
[431931] = {431931, 13019, 34, 26, "0", "0", "安心……像是回到了學宮一樣。", "なんだか安心します……まるで學宮に帰ったみたいに……", "0", "0", "0", "0", "cv_zhaowu_32", "0", "0"},
[431932] = {431932, 13019, 35, 27, "0", "0", "要上戰場了……", "戦場ですね……お任せください。", "0", "0", "0", "0", "cv_zhaowu_33", "0", "0"},
[431933] = {431933, 13019, 36, 28, "0", "0", "演習也會出現傷患……", "演習でも負傷者が出るかもしれませんね……", "0", "0", "0", "0", "cv_zhaowu_34", "0", "0"},
[431934] = {431934, 13019, 37, 29, "0", "0", "大家都好好的，真好呀。", "皆さんお元気で、何よりです。", "0", "0", "0", "0", "cv_zhaowu_35", "0", "0"},
[431935] = {431935, 13019, 38, 30, "0", "0", "您要去找新的陪伴者了嗎……", "新しいパートナーを探しに行くんですか？", "0", "0", "0", "0", "cv_zhaowu_36", "0", "0"},
[431936] = {431936, 13019, 39, 31, "0", "0", "出門要穿戴整齊哦。", "外出する際は、身なりを整えないと。", "0", "0", "0", "0", "cv_zhaowu_37", "0", "0"},
[431937] = {431937, 13019, 40, 32, "0", "0", "……我……我想要買本書可以嗎？", "本を……本を買いたいです……", "0", "0", "0", "0", "cv_zhaowu_38", "0", "0"},
[431938] = {431938, 13019, 41, 33, "0", "0", "檔案上有您的照片。", "あなたの寫真がありますね。", "0", "0", "0", "0", "cv_zhaowu_39", "0", "0"},
[431939] = {431939, 13019, 42, 34, "0", "0", "這裏是調整設置的地方。", "セッティングを調整できます。", "0", "0", "0", "0", "cv_zhaowu_40", "0", "0"},
[431940] = {431940, 13019, 43, 35, "0", "0", "會有新的來信嗎？", "新しいメールは來ているでしょうか？", "0", "0", "0", "0", "cv_zhaowu_41", "0", "0"},
[431941] = {431941, 13019, 44, 36, "0", "0", "領航的聊天……我……我也被允許一起看嗎？", "ナビゲーターのチャット……わ、わたくしも拝見していいでしょうか？", "0", "0", "0", "0", "cv_zhaowu_42", "0", "0"},
[431942] = {431942, 13019, 45, 37, "0", "0", "呼——", "ふぅ……", "0", "0", "0", "0", "cv_zhaowu_43", "0", "0"},
[432000] = {432000, 13020, 1, 1, "0", "0", "蒼霧殘響", "ハツ…ふぁ～（あくび）…リバーブ", "0", "0", "0", "0", "cv_mayball_1", "0", "0"},
[432001] = {432001, 13020, 2, 2, "0", "0", "確定交由我嗎？事先說好，不保證能勝任哦。", "私に任せるの？あんまり、期待しないでね。", "0", "0", "0", "0", "cv_mayball_2", "0", "0"},
[432002] = {432002, 13020, 3, 3, "0", "0", "這裏是梅貝爾·伊司，薩哈拉蒼穹學院的一名哲學教師，隸屬於制蜜人小隊。唔，介紹應該就這些了……", "私はメイベル・イース。サハラの「ファーマメントアカデミー」で哲學の授業擔當。ハニーメイカーに所屬。これぐらいかな……。", "0", "0", "0", "0", "cv_mayball_3", "0", "0"},
[432003] = {432003, 13020, 4, 4, "0", "idle", "等工作完就放鬆下吧，去咖啡館會會朋友，享受靜謐、芬芳，以及……哈嗚~思想的碰撞。", "仕事が終わったら、友達とカフェで會って、リラックスして、靜かな時間と良い香り、そして…ふぁ～、思想のぶつかり合いを楽しむの。", "0", "0", "0", "0", "cv_mayball_4", "0", "0"},
[432004] = {432004, 13020, 5, 4, "0", "idle", "我這悠閒散漫的樣子不太受一些學生歡迎，雖說作為教師有些失敗，但反面教材也算教嘛~", "のんびりしてる私は、一部の生徒からあまり良く思われてないみたい。でも教師としては成功かな…反面教師としてだけど。", "0", "0", "0", "0", "cv_mayball_5", "0", "0"},
[432005] = {432005, 13020, 6, 4, "0", "idle", "普瑞席歐和墨君都是工作狂，小隊有她們真讓人輕鬆不少。至於斯緹菈，軟乎乎的非常治癒呢，領航同學也要試試嗎？", "プレシオと墨君（ぼくくん）は仕事狂いだから、彼女たちがいるとチームはかなり楽になる。ステラは……柔らかくて癒されるの、ナビゲーターくんも試してみない？", "0", "0", "0", "0", "cv_mayball_6", "0", "0"},
[432006] = {432006, 13020, 7, 5, "1_》_0_0.8", "level1", "存在即虛無，因此，存在才會不斷探尋意義……但虛無真的能被填滿嗎？", "存在は虛無であるが故に、意味を探し続ける。虛無を埋めることは出來るのかな？", "0", "0", "0", "0", "cv_mayball_7", "0", "0"},
[432007] = {432007, 13020, 8, 5, "1_》_0_0.8", "level1", "我看起來有些困？請不用擔心，就算不小心睡著，手上的書正好能作為一個小枕頭。", "少し疲れているように見える？心配しないで。うっかり寢てしまっても、この本がちょうど枕代わりになるから。", "0", "0", "0", "0", "cv_mayball_8", "0", "0"},
[432008] = {432008, 13020, 9, 5, "1_》_100_1.5", "level2", "哲學書艱深晦澀，有些能打消困倦，有些能使人安眠。領航同學喜歡哪種呢？", "哲學の本は難解で深遠。眠気が飛ぶものもあれば、眠りへ誘うものもある。ナビゲーターくんはどちらがお好み？", "0", "0", "0", "0", "cv_mayball_9", "0", "0"},
[432009] = {432009, 13020, 10, 5, "1_》_500_2", "level3", "偶爾會感到迷茫嗎？沒關係，能夠迷茫正是“存在先於本質”的證明，這不是壞事。", "たまに迷いを感じることはある？心配しないで。迷いを感じることこそ「実存は本質に先立つ」ということの証明。悪いことではないよ。", "0", "0", "0", "0", "cv_mayball_10", "0", "0"},
[432010] = {432010, 13020, 11, 5, "1_》_1000_2.5", "level4", "領航同學，我可以更加依靠你一些嗎？比如……要是嗜睡症不小心發作，希望正好有你在我身邊……這種感覺？", "ナビゲーターくん、もっと君に頼ってもいいかな？…もし過眠症の発作が起きたとき、君が側にいてくれたらいいなって思って。", "0", "0", "0", "0", "cv_mayball_11", "0", "0"},
[432011] = {432011, 13020, 12, 6, "0", "0", "哈嗚~謝謝。", "ふぅ～、ありがとう。", "0", "0", "0", "0", "cv_mayball_12", "0", "0"},
[432012] = {432012, 13020, 13, 7, "0", "0", "思維更清晰了，像在品一杯冰咖啡。", "頭の中がすっきりしてる。まるでアイスコーヒーを飲んだ後みたい。", "0", "0", "0", "0", "cv_mayball_13", "0", "0"},
[432013] = {432013, 13020, 14, 8, "0", "0", "“覺醒”嗎？這詞真不適合我呢，說不定我下一秒就會睡著。但領航同學一直對我有所期待，果然我還是拿出十足的幹勁吧~", "「覚醒」？私にはあまり似合わないね。もしかしたら、次の瞬間には寢てしまうかもしれないのに。でも、ナビゲーターくんが期待してくれてるなら、頑張ってみようかな。", "0", "0", "0", "0", "cv_mayball_14", "0", "0"},
[432014] = {432014, 13020, 15, 9, "0", "0", "用思想武裝自己呢。", "思考で武裝するよ。", "0", "0", "0", "0", "cv_mayball_15", "0", "0"},
[432015] = {432015, 13020, 16, 10, "0", "0", "闊別已久的戰場啊。", "久しぶりの戦場だ。", "0", "0", "0", "0", "cv_mayball_16", "0", "0"},
[432016] = {432016, 13020, 17, 11, "0", "0", "哎呀，不小心發揮超常了。", "おっと、やりすぎちゃったかな。", "0", "0", "0", "0", "cv_mayball_17", "0", "0"},
[432017] = {432017, 13020, 18, 12, "0", "0", "不完美才是人生的常態，不用在意哦。", "不完全こそ人らしさだよ。心配しないで。", "0", "0", "0", "0", "cv_mayball_18", "0", "0"},
[432018] = {432018, 13020, 19, 13, "0", "0", "這樣下去沒法給學生們當榜樣了呢。", "これじゃあお手本を見せられないね。", "0", "0", "0", "0", "cv_mayball_19", "0", "0"},
[432019] = {432019, 13020, 20, 14, "0", "0", "果然下次作戰把我換掉更好吧~？", "やっぱり、次の作戦では私を交代させた方が良さそうだね～。", "0", "0", "0", "0", "cv_mayball_20", "0", "0"},
[432020] = {432020, 13020, 23, 16, "0", "0", "加油吧。", "頑張って。", "0", "0", "0", "0", "cv_mayball_21", "0", "0"},
[432021] = {432021, 13020, 26, 19, "0", "0", "我還沒睡著呢。", "まだ寢てないよ。", "0", "0", "0", "0", "cv_mayball_22", "0", "0"},
[432022] = {432022, 13020, 24, 17, "0", "0", "希望醒來後還能再見到大家。", "起きたらまた會えますように……", "0", "0", "0", "0", "cv_mayball_23", "0", "0"},
[432023] = {432023, 13020, 27, 20, "0", "0", "為了更好地思考，讓我們洗卻身體的疲憊吧~", "體の疲れを癒して、思考をスムーズにしよ～。", "0", "0", "0", "0", "cv_mayball_24", "0", "0"},
[432024] = {432024, 13020, 28, 21, "0", "0", "哈嗚~這裏比外面更容易讓人發困，領航同學可不能比我先睡著哦。", "ふぁ～、ここは外よりも寢やすいね。ナビゲーターくんは先に寢ちゃだめだよ。", "0", "0", "0", "0", "cv_mayball_25", "0", "0"},
[432025] = {432025, 13020, 29, 21, "0", "0", "古時起，薩哈拉的哲學家們就喜歡在浴場討論問題，領航同學此刻也有想要知曉的問題嗎？", "昔からサハラの哲學者たちはお風呂で議論するのが大好きだったの。ナビゲーターくんは何か話したいことはある？", "0", "0", "0", "0", "cv_mayball_26", "0", "0"},
[432026] = {432026, 13020, 30, 22, "0", "0", "遊戲時間開始~", "遊びの時間だ～。", "0", "0", "0", "0", "cv_mayball_27", "0", "0"},
[432027] = {432027, 13020, 31, 23, "0", "0", "那麼答案是什麼呢？", "それでは答えは？", "0", "0", "0", "0", "cv_mayball_28", "0", "0"},
[432028] = {432028, 13020, 32, 24, "0", "0", "答對了，一百分！", "正解、ひゃくてん！", "0", "0", "0", "0", "cv_mayball_29", "0", "0"},
[432029] = {432029, 13020, 33, 25, "0", "0", "很遺憾，不及格呢~", "殘念ながら、不正解～。", "0", "0", "0", "0", "cv_mayball_30", "0", "0"},
[432030] = {432030, 13020, 34, 26, "0", "0", "時間過得真快，又要開始工作了。", "時間が経つのは速いね。もう仕事の時だ。", "0", "0", "0", "0", "cv_mayball_31", "0", "0"},
[432031] = {432031, 13020, 35, 27, "0", "0", "該認真起來了嗎？", "本気を出しちゃう？", "0", "0", "0", "0", "cv_mayball_32", "0", "0"},
[432032] = {432032, 13020, 36, 28, "0", "0", "模擬戰就隨意點吧。", "模擬戦はほどほどにね。", "0", "0", "0", "0", "cv_mayball_33", "0", "0"},
[432033] = {432033, 13020, 37, 29, "0", "0", "突擊檢查~有開小差的同學嗎？", "抜き打ち検査～。サボってる人いない？", "0", "0", "0", "0", "cv_mayball_34", "0", "0"},
[432034] = {432034, 13020, 38, 30, "0", "0", "謔~要出現神秘轉校生了。", "へぇ～、転校生が來るみたいだよ。", "0", "0", "0", "0", "cv_mayball_35", "0", "0"},
[432035] = {432035, 13020, 39, 31, "0", "0", "會得到什麼呢？稍微期待下吧。", "何が出るのか、期待してね。", "0", "0", "0", "0", "cv_mayball_36", "0", "0"},
[432036] = {432036, 13020, 40, 32, "0", "0", "幫忙留意下新款睡衣哦。", "新デザインのパジャマ探し、手伝って？", "0", "0", "0", "0", "cv_mayball_37", "0", "0"},
[432037] = {432037, 13020, 41, 33, "0", "0", "看看領航同學的志向填了什麼。", "どれどれ、ナビゲーターくんの進路希望は……", "0", "0", "0", "0", "cv_mayball_38", "0", "0"},
[432038] = {432038, 13020, 42, 34, "0", "0", "領航同學真講究呢~", "ナビゲーターくん、こだわってるね。", "0", "0", "0", "0", "cv_mayball_39", "0", "0"},
[432039] = {432039, 13020, 43, 35, "0", "0", "比起口頭交流，果然文字更方便呢。", "會話より、文字のほうが便利かも。", "0", "0", "0", "0", "cv_mayball_40", "0", "0"},
[432040] = {432040, 13020, 44, 36, "0", "0", "有什麼想對大家說的呢？", "みんなに何か言いたいの？", "0", "0", "0", "0", "cv_mayball_41", "0", "0"},
[432041] = {432041, 13020, 45, 37, "0", "0", "好、好。", "はい、はい。", "0", "0", "0", "0", "cv_mayball_42", "0", "0"},
[432100] = {432100, 13021, 1, 1, "0", "0", "蒼~霧~殘~響~", "0", "0", "0", "0", "0", "cv_hoshii_1", "0", "0"},
[432101] = {432101, 13021, 2, 2, "0", "0", "用九州的神秘學理論來說就是——這裏的風水不錯。", "0", "0", "0", "0", "0", "cv_hoshii_2", "0", "0"},
[432102] = {432102, 13021, 3, 3, "0", "0", "我是星井伯納蒂，您的人生指引者。我可以稱呼你為“領航哥哥”嗎？", "0", "0", "0", "0", "0", "cv_hoshii_3", "0", "0"},
[432103] = {432103, 13021, 4, 4, "0", "idle", "來自無邊思緒之上的無上之光，請照亮迷惑靈魂飄蕩的方向。", "0", "0", "0", "0", "0", "cv_hoshii_4", "0", "0"},
[432104] = {432104, 13021, 5, 4, "0", "idle", "占卜的結果是……晚飯吃拉麵。", "0", "0", "0", "0", "0", "cv_hoshii_5", "0", "0"},
[432105] = {432105, 13021, 6, 4, "0", "idle", "我呀，昨天偷偷給其他人占卜了一下未來。小螢草和花語的命運清晰而寧靜，但心紙姐姐她……嗯……領航哥哥還是不要知道比較好。", "0", "0", "0", "0", "0", "cv_hoshii_6", "0", "0"},
[432106] = {432106, 13021, 7, 5, "1_》_0_0.8", "level1", "巫女和占卜師的在我看來並沒有區別，都是幫助迷茫的人尋找人生的希望。不過巫女可以穿可愛的巫女服。", "0", "0", "0", "0", "0", "cv_hoshii_7", "0", "0"},
[432107] = {432107, 13021, 8, 5, "1_》_0_0.8", "level1", "別……別打擾我的冥想……我正在……接受……思維世界先賢的……智慧……呼——（呼嚕聲）", "0", "0", "0", "0", "0", "cv_hoshii_8", "0", "0"},
[432108] = {432108, 13021, 9, 5, "1_》_100_1.5", "level2", "誒？領航哥哥還要再占卜一次嗎？可以是可以啦，不過就算再占卜一千次，結果也不會變的——黑色的光自月亮開始吞沒了太陽與大地……", "0", "0", "0", "0", "0", "cv_hoshii_9", "0", "0"},
[432109] = {432109, 13021, 10, 5, "1_》_500_2", "level3", "不必過於擔心“黑光”，占卜的結果僅僅是未來的推演而已，真正的未來並不一定會發生那樣的事。更何況，還有我在領航哥哥身邊。", "0", "0", "0", "0", "0", "cv_hoshii_10", "0", "0"},
[432110] = {432110, 13021, 11, 5, "1_》_1000_2.5", "level4", "母親的占卜結果說，我將會與一位千轉輪回之人產生超越群體潛意識控制的深度交融。現在我越來越確定，那個千轉輪回之人就是你——領航哥哥。", "0", "0", "0", "0", "0", "cv_hoshii_11", "0", "0"},
[432111] = {432111, 13021, 12, 6, "0", "0", "靈感提升。", "0", "0", "0", "0", "0", "cv_hoshii_12", "0", "0"},
[432112] = {432112, 13021, 13, 7, "0", "0", "與思維世界的感應更緊密了。", "0", "0", "0", "0", "0", "cv_hoshii_13", "0", "0"},
[432113] = {432113, 13021, 14, 8, "0", "0", "世界的枝條在我眼前舒展，未來的定格照正在一張一張覆蓋。唯一的光將消融黑色，那便是領航哥哥你。", "0", "0", "0", "0", "0", "cv_hoshii_14", "0", "0"},
[432114] = {432114, 13021, 15, 9, "0", "0", "要保持水晶球的清潔。", "0", "0", "0", "0", "0", "cv_hoshii_15", "0", "0"},
[432115] = {432115, 13021, 16, 10, "0", "0", "我來占卜一下戰鬥的結果。", "0", "0", "0", "0", "0", "cv_hoshii_16", "0", "0"},
[432116] = {432116, 13021, 17, 11, "0", "0", "占卜的結果是——完全勝利！", "0", "0", "0", "0", "0", "cv_hoshii_17", "0", "0"},
[432117] = {432117, 13021, 18, 12, "0", "0", "和占卜結果基本符合。", "0", "0", "0", "0", "0", "cv_hoshii_18", "0", "0"},
[432118] = {432118, 13021, 19, 13, "0", "0", "勉強成功——改寫必輸的命運。", "0", "0", "0", "0", "0", "cv_hoshii_19", "0", "0"},
[432119] = {432119, 13021, 20, 14, "0", "0", "未來無法改變嗎？", "0", "0", "0", "0", "0", "cv_hoshii_20", "0", "0"},
[432120] = {432120, 13021, 23, 16, "0", "0", "機會只有一次。", "0", "0", "0", "0", "0", "cv_hoshii_21", "0", "0"},
[432121] = {432121, 13021, 26, 19, "0", "0", "水晶球碎了……", "0", "0", "0", "0", "0", "cv_hoshii_23", "0", "0"},
[432122] = {432122, 13021, 24, 17, "0", "0", "你的生命之河不會在此斷流。", "0", "0", "0", "0", "0", "cv_hoshii_22", "0", "0"},
[432123] = {432123, 13021, 27, 20, "0", "0", "哇哦！好大的澡堂。", "0", "0", "0", "0", "0", "cv_hoshii_24", "0", "0"},
[432124] = {432124, 13021, 28, 21, "0", "0", "領航哥哥能幫我搓下背嗎？", "0", "0", "0", "0", "0", "cv_hoshii_25", "0", "0"},
[432125] = {432125, 13021, 29, 21, "0", "0", "在這裏冥想效率會變高吧。", "0", "0", "0", "0", "0", "cv_hoshii_26", "0", "0"},
[432126] = {432126, 13021, 30, 22, "0", "0", "需要占卜的幫助嗎？", "0", "0", "0", "0", "0", "cv_hoshii_27", "0", "0"},
[432127] = {432127, 13021, 31, 23, "0", "0", "應該不需要我的引導吧。", "0", "0", "0", "0", "0", "cv_hoshii_28", "0", "0"},
[432128] = {432128, 13021, 32, 24, "0", "0", "果然領航哥哥的命運與我是相連的。", "0", "0", "0", "0", "0", "cv_hoshii_29", "0", "0"},
[432129] = {432129, 13021, 33, 25, "0", "0", "難道我又占卜錯了？", "0", "0", "0", "0", "0", "cv_hoshii_30", "0", "0"},
[432130] = {432130, 13021, 34, 26, "0", "0", "三，二，一，嘻嘻，我早就通過占卜算到領航哥哥回來的時間了。", "0", "0", "0", "0", "0", "cv_hoshii_31", "0", "0"},
[432131] = {432131, 13021, 35, 27, "0", "0", "戰前的占卜儀式很重要。", "0", "0", "0", "0", "0", "cv_hoshii_32", "0", "0"},
[432132] = {432132, 13021, 36, 28, "0", "0", "如果提前知道結果就不好玩了哦。", "0", "0", "0", "0", "0", "cv_hoshii_33", "0", "0"},
[432133] = {432133, 13021, 37, 29, "0", "0", "哥哥的桃花運真旺啊。", "0", "0", "0", "0", "0", "cv_hoshii_34", "0", "0"},
[432134] = {432134, 13021, 38, 30, "0", "0", "想知道下一個出現的是誰嗎？領航哥哥。", "0", "0", "0", "0", "0", "cv_hoshii_35", "0", "0"},
[432135] = {432135, 13021, 39, 31, "0", "0", "水晶球顯現出金色的光芒。", "0", "0", "0", "0", "0", "cv_hoshii_36", "0", "0"},
[432136] = {432136, 13021, 40, 32, "0", "0", "那件道具……充滿了能量。", "0", "0", "0", "0", "0", "cv_hoshii_37", "0", "0"},
[432137] = {432137, 13021, 41, 33, "0", "0", "領航哥哥的名字擁有強大的能量。", "0", "0", "0", "0", "0", "cv_hoshii_38", "0", "0"},
[432138] = {432138, 13021, 42, 34, "0", "0", "能改變什麼呢？", "0", "0", "0", "0", "0", "cv_hoshii_39", "0", "0"},
[432139] = {432139, 13021, 43, 35, "0", "0", "我有一封來自未來的信。", "0", "0", "0", "0", "0", "cv_hoshii_40", "0", "0"},
[432140] = {432140, 13021, 44, 36, "0", "0", "這麼多人我可占卜不過來。", "0", "0", "0", "0", "0", "cv_hoshii_41", "0", "0"},
[432141] = {432141, 13021, 45, 37, "0", "0", "哦吼？", "0", "0", "0", "0", "0", "cv_hoshii_42", "0", "0"},
[432200] = {432200, 13022, 1, 1, "0", "0", "蒼霧殘響！", "0", "0", "0", "0", "0", "cv_monika_1", "0", "0"},
[432201] = {432201, 13022, 2, 2, "0", "0", "很好，終於遇到個有眼光的上司了。", "0", "0", "0", "0", "0", "cv_monika_2", "0", "0"},
[432202] = {432202, 13022, 3, 3, "0", "0", "自我介紹？檔案上不都寫著了嗎……“莫妮卡”，給我記住了。", "0", "0", "0", "0", "0", "cv_monika_3", "0", "0"},
[432203] = {432203, 13022, 4, 4, "0", "idle", "無聊，什麼時候能來新的任務？", "0", "0", "0", "0", "0", "cv_monika_4", "0", "0"},
[432204] = {432204, 13022, 5, 4, "0", "idle2", "死死盯著對方的眼睛來施加壓力，這是審訊時才會用到的技巧。", "0", "0", "0", "0", "0", "cv_monika_5", "0", "0"},
[432205] = {432205, 13022, 6, 4, "0", "idle3", "凱特琳的槍法很准但是不擅長近身格鬥，哈莉特的近身格鬥很強可面對遠程敵人束手無策。而我可以從容面對這兩種情況，所以為什麼不讓我來當黑荊棘的隊長？", "0", "0", "0", "0", "0", "cv_monika_6", "0", "0"},
[432206] = {432206, 13022, 7, 5, "1_》_0_0.8", "level1", "“對壞人的仁慈就是對好人的殘忍。”這就是我信奉的正義。可是其他人只會說什麼“人道主義”……狗屁！", "0", "0", "0", "0", "0", "cv_monika_7", "0", "0"},
[432207] = {432207, 13022, 8, 5, "1_》_0_0.8", "level2", "討厭，你是對金髮有什麼特殊癖好嗎？", "0", "0", "0", "0", "0", "cv_monika_8", "0", "0"},
[432208] = {432208, 13022, 9, 5, "1_》_100_1.5", "level3", "成為駕駛員的好處之一是不會有人對原罪產生同情……應該不會有吧。", "0", "0", "0", "0", "0", "cv_monika_9", "0", "0"},
[432209] = {432209, 13022, 10, 5, "1_》_500_2", "level4", "有的審訊官會用言語威脅犯人，突破他們的心理防線來讓他們說出隱藏的情報。而我更喜歡用鞭子，快捷，高效。我和那些危險分子可沒什麼好說的。", "0", "0", "0", "0", "0", "cv_monika_10", "0", "0"},
[432210] = {432210, 13022, 11, 5, "1_》_1000_2.5", "level5", "我最近經常做相同的夢，我夢見我成了犯人，而負責審訊的人是領航你。夢裏的你溫柔而耐心，只是不停地用耳語勸導我主動坦白自己。於是我決定在今天向你說出我心裏的秘密——我喜歡……", "0", "0", "0", "0", "0", "cv_monika_11", "0", "0"},
[432211] = {432211, 13022, 12, 6, "0", "0", "變強了嗎？沒什麼感覺。", "0", "0", "0", "0", "0", "cv_monika_12", "0", "0"},
[432212] = {432212, 13022, 13, 7, "0", "0", "也算是有了些長進。", "0", "0", "0", "0", "0", "cv_monika_13", "0", "0"},
[432213] = {432213, 13022, 14, 8, "0", "0", "這下該讓我做隊長了。", "0", "0", "0", "0", "0", "cv_monika_14", "0", "0"},
[432214] = {432214, 13022, 15, 9, "0", "0", "新的技巧，在實戰中熟悉吧。", "0", "0", "0", "0", "0", "cv_monika_15", "0", "0"},
[432215] = {432215, 13022, 16, 10, "0", "0", "審訊開始。", "0", "0", "0", "0", "0", "cv_monika_16", "0", "0"},
[432216] = {432216, 13022, 17, 11, "0", "0", "就這樣結束了嗎？", "0", "0", "0", "0", "0", "cv_monika_17", "0", "0"},
[432217] = {432217, 13022, 18, 12, "0", "0", "早知道就使出全力了。", "0", "0", "0", "0", "0", "cv_monika_18", "0", "0"},
[432218] = {432218, 13022, 19, 13, "0", "0", "真是難纏的敵人。", "0", "0", "0", "0", "0", "cv_monika_19", "0", "0"},
[432219] = {432219, 13022, 20, 14, "0", "0", "我還不夠資格……", "0", "0", "0", "0", "0", "cv_monika_20", "0", "0"},
[432220] = {432220, 13022, 23, 16, "0", "0", "給我清醒一下！", "0", "0", "0", "0", "0", "cv_monika_23", "0", "0"},
[432221] = {432221, 13022, 24, 17, "0", "0", "還沒到結束的時候。", "0", "0", "0", "0", "0", "cv_monika_24", "0", "0"},
[432222] = {432222, 13022, 26, 19, "0", "0", "中斷審訊。", "0", "0", "0", "0", "0", "cv_monika_26", "0", "0"},
[432223] = {432223, 13022, 27, 20, "0", "0", "這是什麼特別的審訊方式嗎？", "0", "0", "0", "0", "0", "cv_monika_27", "0", "0"},
[432224] = {432224, 13022, 28, 21, "0", "0", "手裏沒有鞭子，心裏就沒有安全感。", "0", "0", "0", "0", "0", "cv_monika_28", "0", "0"},
[432225] = {432225, 13022, 29, 21, "0", "0", "趁著我無法反抗的時候，將我每一部分都牢記在心吧。", "0", "0", "0", "0", "0", "cv_monika_29", "0", "0"},
[432226] = {432226, 13022, 30, 22, "0", "0", "果然，這是一場特殊的審訊。", "0", "0", "0", "0", "0", "cv_monika_30", "0", "0"},
[432227] = {432227, 13022, 31, 23, "0", "0", "這還需要提示？答錯的話我就用鞭子抽你。", "0", "0", "0", "0", "0", "cv_monika_31", "0", "0"},
[432228] = {432228, 13022, 32, 24, "0", "0", "完美通過了審訊。", "0", "0", "0", "0", "0", "cv_monika_32", "0", "0"},
[432229] = {432229, 13022, 33, 25, "0", "0", "準備好接受我的鞭撻吧。", "0", "0", "0", "0", "0", "cv_monika_33", "0", "0"},
[432230] = {432230, 13022, 34, 26, "0", "0", "把我晾在這這麼久，是想讓我更在意你嗎？", "0", "0", "0", "0", "0", "cv_monika_34", "0", "0"},
[432231] = {432231, 13022, 35, 27, "0", "0", "這才是我該做的事。", "0", "0", "0", "0", "0", "cv_monika_35", "0", "0"},
[432232] = {432232, 13022, 36, 28, "0", "0", "話說前頭，我可不會點到為止。", "0", "0", "0", "0", "0", "cv_monika_36", "0", "0"},
[432233] = {432233, 13022, 37, 29, "0", "0", "真是什麼人都能成為駕駛員。", "0", "0", "0", "0", "0", "cv_monika_37", "0", "0"},
[432234] = {432234, 13022, 38, 30, "0", "0", "需要我來審訊她們嗎？", "0", "0", "0", "0", "0", "cv_monika_38", "0", "0"},
[432235] = {432235, 13022, 39, 31, "0", "0", "我要多備幾根鞭子，壞得太快了。", "0", "0", "0", "0", "0", "cv_monika_39", "0", "0"},
[432236] = {432236, 13022, 40, 32, "0", "0", "這裏充滿了陷阱。", "0", "0", "0", "0", "0", "cv_monika_40", "0", "0"},
[432237] = {432237, 13022, 41, 33, "0", "0", "不用審訊就能知道的秘密。", "0", "0", "0", "0", "0", "cv_monika_41", "0", "0"},
[432238] = {432238, 13022, 42, 34, "0", "0", "更改設置嗎？", "0", "0", "0", "0", "0", "cv_monika_42", "0", "0"},
[432239] = {432239, 13022, 43, 35, "0", "0", "垃圾郵件。", "0", "0", "0", "0", "0", "cv_monika_43", "0", "0"},
[432240] = {432240, 13022, 44, 36, "0", "0", "禍從口出。", "0", "0", "0", "0", "0", "cv_monika_44", "0", "0"},
[432241] = {432241, 13022, 45, 37, "0", "0", "哼。", "0", "0", "0", "0", "0", "cv_monika_45", "0", "0"},
[432300] = {432300, 13023, 1, 1, "0", "0", "蒼霧殘響", "0", "0", "0", "0", "0", "cv_lilith_vd_01", "0", "0"},
[432301] = {432301, 13023, 2, 2, "0", "0", "……這種折磨的日子，對我來說也不是完全沒有意義啊。", "0", "0", "0", "0", "0", "cv_lilith_vd_02", "0", "0"},
[432302] = {432302, 13023, 3, 3, "0", "0", "情人節？真是災難，你也像她們一樣那麼無聊嗎？不過……既然是你，我就不追究了。", "0", "0", "0", "0", "0", "cv_lilith_vd_03", "0", "0"},
[432303] = {432303, 13023, 4, 4, "0", "idle", "你有好好地回應斯卡蒂的感情嗎？她可是很努力地，很認真地為了你製作巧克力。", "0", "0", "0", "0", "0", "cv_lilith_vd_04", "0", "0"},
[432304] = {432304, 13023, 5, 4, "0", "idle2", "巧克力不過是一點點小心意，不必太在意……如果你還想要的話，下次來的時候我給你帶一點吧。", "0", "0", "0", "0", "0", "cv_lilith_vd_05", "0", "0"},
[432305] = {432305, 13023, 6, 4, "0", "idle3", "我們只是很普通的朋友關係。你幫助我，我幫助你，一起並肩作戰，一起從戰場生還的朋友關係。僅此而已。", "0", "0", "0", "0", "0", "cv_lilith_vd_06", "0", "0"},
[432306] = {432306, 13023, 7, 5, "1_》_0_0.8", "level1", "朋友……我們現在是這樣的關係……但是究竟該以什麼樣的態度面對你，容我再想想吧……與你相處的方式……以及我應該處在什麼位置呢？", "0", "0", "0", "0", "0", "cv_lilith_vd_07", "0", "0"},
[432307] = {432307, 13023, 8, 5, "1_》_0_0.8", "level2", "只是朋友而已……為什麼這麼感動，之前的我有這麼可怕嗎？", "0", "0", "0", "0", "0", "cv_lilith_vd_08", "0", "0"},
[432308] = {432308, 13023, 9, 5, "1_》_100_1.5", "level3", "……你是唯一一個能夠讓我表現出這麼多感情的人……很多……和你呆在一起……源源不斷的感情就從我心中湧現……", "0", "0", "0", "0", "0", "cv_lilith_vd_09", "0", "0"},
[432309] = {432309, 13023, 10, 5, "1_》_500_2", "level4", "我送你的巧克力好吃嗎？……還沒吃嗎？……要當紀念品？巧克力是為了吃而被製作出來的……當然也是為了感謝你。", "0", "0", "0", "0", "0", "cv_lilith_vd_10", "0", "0"},
[432310] = {432310, 13023, 11, 5, "1_》_1000_2.5", "level5", "叭叭——！……啊？我剛剛說了什麼？", "0", "0", "0", "0", "0", "cv_lilith_vd_11", "0", "0"},
[432311] = {432311, 13023, 12, 6, "0", "0", "這感覺並不陌生。", "0", "0", "0", "0", "0", "cv_lilith_vd_12", "0", "0"},
[432312] = {432312, 13023, 13, 7, "0", "0", "等到莉莉絲不再是莉莉絲。", "0", "0", "0", "0", "0", "cv_lilith_vd_13", "0", "0"},
[432313] = {432313, 13023, 14, 8, "0", "0", "我得承認……我對你有一點點好感。是碰巧？還是誤會……我沒辦法繼續分析下去了。所以讓我再在你身邊想一會吧。", "0", "0", "0", "0", "0", "cv_lilith_vd_14", "0", "0"},
[432314] = {432314, 13023, 15, 9, "0", "0", "我感覺到了你的付出……", "0", "0", "0", "0", "0", "cv_lilith_vd_15", "0", "0"},
[432315] = {432315, 13023, 16, 10, "0", "0", "不止歇的戰鬥……", "0", "0", "0", "0", "0", "cv_lilith_vd_16", "0", "0"},
[432316] = {432316, 13023, 17, 11, "0", "0", "耀眼的勝利啊。", "0", "0", "0", "0", "0", "cv_lilith_vd_17", "0", "0"},
[432317] = {432317, 13023, 18, 12, "0", "0", "勝利了，理所因當。", "0", "0", "0", "0", "0", "cv_lilith_vd_18", "0", "0"},
[432318] = {432318, 13023, 19, 13, "0", "0", "也不算是失敗呢。", "0", "0", "0", "0", "0", "cv_lilith_vd_19", "0", "0"},
[432319] = {432319, 13023, 20, 14, "0", "0", "嗯，別沮喪了。", "0", "0", "0", "0", "0", "cv_lilith_vd_20", "0", "0"},
[432320] = {432320, 13023, 23, 16, "0", "0", "吃吧。", "0", "0", "0", "0", "0", "cv_lilith_vd_23", "0", "0"},
[432321] = {432321, 13023, 24, 17, "0", "0", "然後死吧。", "0", "0", "0", "0", "0", "cv_lilith_vd_24", "0", "0"},
[432322] = {432322, 13023, 25, 18, "0", "0", "毀棄一切高潔——", "0", "0", "0", "0", "0", "cv_lilith_vd_25", "0", "0"},
[432323] = {432323, 13023, 26, 19, "0", "0", "為何……心不斷刺痛著。", "0", "0", "0", "0", "0", "cv_lilith_vd_26", "0", "0"},
[432324] = {432324, 13023, 27, 20, "0", "0", "……沒想我會有聞到你的味道而心安的一天。", "0", "0", "0", "0", "0", "cv_lilith_vd_27", "0", "0"},
[432325] = {432325, 13023, 28, 21, "0", "0", "意料之外，我竟然不討厭和你接觸了……", "0", "0", "0", "0", "0", "cv_lilith_vd_28", "0", "0"},
[432326] = {432326, 13023, 29, 21, "0", "0", "領航，你覺得是我自己改變了嗎……還是說是通感改變了我？", "0", "0", "0", "0", "0", "cv_lilith_vd_29", "0", "0"},
[432327] = {432327, 13023, 30, 22, "0", "0", "只是為了消耗一下多餘的時間？", "0", "0", "0", "0", "0", "cv_lilith_vd_30", "0", "0"},
[432328] = {432328, 13023, 31, 23, "0", "0", "你會猜對嗎？我的朋友。", "0", "0", "0", "0", "0", "cv_lilith_vd_31", "0", "0"},
[432329] = {432329, 13023, 32, 24, "0", "0", "認出來了……作為朋友……這是當然的嗎？", "0", "0", "0", "0", "0", "cv_lilith_vd_32", "0", "0"},
[432330] = {432330, 13023, 33, 25, "0", "0", "這也是理所當然的吧……", "0", "0", "0", "0", "0", "cv_lilith_vd_33", "0", "0"},
[432331] = {432331, 13023, 34, 26, "0", "0", "回來了？等你很久了。", "0", "0", "0", "0", "0", "cv_lilith_vd_34", "0", "0"},
[432332] = {432332, 13023, 35, 27, "0", "0", "我……竟然不再不安了。", "0", "0", "0", "0", "0", "cv_lilith_vd_35", "0", "0"},
[432333] = {432333, 13023, 36, 28, "0", "0", "三十分鐘……開始吧。", "0", "0", "0", "0", "0", "cv_lilith_vd_36", "0", "0"},
[432334] = {432334, 13023, 37, 29, "0", "0", "你與她們又是什麼關係呢。", "0", "0", "0", "0", "0", "cv_lilith_vd_37", "0", "0"},
[432335] = {432335, 13023, 38, 30, "0", "0", "夥伴……朋友……有什麼區別嗎？", "0", "0", "0", "0", "0", "cv_lilith_vd_38", "0", "0"},
[432336] = {432336, 13023, 39, 31, "0", "0", "讓人安心。", "0", "0", "0", "0", "0", "cv_lilith_vd_39", "0", "0"},
[432337] = {432337, 13023, 40, 32, "0", "0", "……要給我買零食？我又不是小孩子", "0", "0", "0", "0", "0", "cv_lilith_vd_40", "0", "0"},
[432338] = {432338, 13023, 41, 33, "0", "0", "叭。", "0", "0", "0", "0", "0", "cv_lilith_vd_41", "0", "0"},
[432339] = {432339, 13023, 42, 34, "0", "0", "叭叭。", "0", "0", "0", "0", "0", "cv_lilith_vd_42", "0", "0"},
[432340] = {432340, 13023, 43, 35, "0", "0", "叭叭！", "0", "0", "0", "0", "0", "cv_lilith_vd_43", "0", "0"},
[432341] = {432341, 13023, 44, 36, "0", "0", "叭叭？", "0", "0", "0", "0", "0", "cv_lilith_vd_44", "0", "0"},
[432342] = {432342, 13023, 45, 37, "0", "0", "叭叭——", "0", "0", "0", "0", "0", "cv_lilith_vd_45", "0", "0"},
[432500] = {432500, 13025, 1, 1, "0", "0", "蒼霧殘響~", "0", "0", "0", "0", "0", "cv_fulanka_her_01", "0", "0"},
[432501] = {432501, 13025, 2, 2, "0", "0", "糟了……要遲到了……得趕緊起床才行！", "0", "0", "0", "0", "0", "cv_fulanka_her_02", "0", "0"},
[432502] = {432502, 13025, 3, 3, "0", "0", "領航你看~我已經把婚紗穿好了哦~奇怪——為什麼我背後長了翅膀？", "0", "0", "0", "0", "0", "cv_fulanka_her_03", "0", "0"},
[432503] = {432503, 13025, 4, 4, "0", "idle", "沒想到還會第二次來到這裡……嗯……既然是“夢”的話，稍微做些美夢也沒關係吧？（小聲）", "0", "0", "0", "0", "0", "cv_fulanka_her_04", "0", "0"},
[432504] = {432504, 13025, 5, 4, "0", "idle2", "小惡魔和婚紗的樣子都是我潛藏感情的具現化……？呼呼……我完全聽不懂您在說什麼……", "0", "0", "0", "0", "0", "cv_fulanka_her_05", "0", "0"},
[432505] = {432505, 13025, 6, 4, "0", "idle3", "領航，既然我們難得同時都穿了婚慶的衣服……要不要試試結婚看看……嘿嘿……開個玩笑……誒？好……？我當然也沒問題！", "0", "0", "0", "0", "0", "cv_fulanka_her_06", "0", "0"},
[432506] = {432506, 13025, 7, 5, "1_》_0_0.8", "level1", "以結婚為前提進行的交往……我沒理解錯的話是這個意思吧？", "0", "0", "0", "0", "0", "cv_fulanka_her_07", "0", "0"},
[432507] = {432507, 13025, 8, 5, "1_》_0_0.8", "level2", "啊，我想到了……以結婚為前提的話……是不是很多事情都能以結婚為前提去做……來試試看吧？", "0", "0", "0", "0", "0", "cv_fulanka_her_08", "0", "0"},
[432508] = {432508, 13025, 9, 5, "1_》_100_1.5", "level3", "我能搬來和領航一起住嗎？嗯……反正早晚都會住到一起的啊？沒問題吧？", "0", "0", "0", "0", "0", "cv_fulanka_her_09", "0", "0"},
[432509] = {432509, 13025, 10, 5, "1_》_500_2", "level4", "糟了……光是稍微想像過去的經歷和未來的光景，就有想要大哭一場的衝動……能遇見您真是太好了。", "0", "0", "0", "0", "0", "cv_fulanka_her_10", "0", "0"},
[432510] = {432510, 13025, 11, 5, "1_》_1000_2.5", "level5", "未來會怎麼樣……誰都不知道……我也不知道能不能成為您理想的伴侶，不過我是不會就此說放棄的，做不到的話就直到做到為止……！", "0", "0", "0", "0", "0", "cv_fulanka_her_11", "0", "0"},
[432511] = {432511, 13025, 12, 6, "0", "0", "情緒高漲呢。", "0", "0", "0", "0", "0", "cv_fulanka_her_12", "0", "0"},
[432512] = {432512, 13025, 13, 7, "0", "0", "我會時刻記得這份心意的。", "0", "0", "0", "0", "0", "cv_fulanka_her_13", "0", "0"},
[432513] = {432513, 13025, 14, 8, "0", "0", "嗯……總覺我們的關係已經……是不是到該訂婚的程度了……所以要訂婚嗎？我想把這個消息告訴大家……", "0", "0", "0", "0", "0", "cv_fulanka_her_14", "0", "0"},
[432514] = {432514, 13025, 15, 9, "0", "0", "不知不覺就成長到這種程度了嗎……和領航在一起的時間過得真快……", "0", "0", "0", "0", "0", "cv_fulanka_her_15", "0", "0"},
[432515] = {432515, 13025, 16, 10, "0", "0", "戰鬥準備！", "0", "0", "0", "0", "0", "cv_fulanka_her_16", "0", "0"},
[432516] = {432516, 13025, 17, 11, "0", "0", "怎麼樣？新娘的修行完成了嗎？", "0", "0", "0", "0", "0", "cv_fulanka_her_17", "0", "0"},
[432517] = {432517, 13025, 18, 12, "0", "0", "我還能做的更好。", "0", "0", "0", "0", "0", "cv_fulanka_her_18", "0", "0"},
[432518] = {432518, 13025, 19, 13, "0", "0", "僅僅只是合格而已，我還會進步的。", "0", "0", "0", "0", "0", "cv_fulanka_her_19", "0", "0"},
[432519] = {432519, 13025, 20, 14, "0", "0", "修行還不足夠呢。", "0", "0", "0", "0", "0", "cv_fulanka_her_20", "0", "0"},
[432520] = {432520, 13025, 23, 16, "0", "0", "哼~哼~哼~哼~哼~哼~哼~哼~哼~", "0", "0", "0", "0", "0", "cv_fulanka_her_22", "0", "0"},
[432521] = {432521, 13025, 24, 17, "0", "0", "嘿嘿~", "0", "0", "0", "0", "0", "cv_fulanka_her_23", "0", "0"},
[432522] = {432522, 13025, 25, 18, "0", "0", "大家一定會收穫幸福的！", "0", "0", "0", "0", "0", "cv_fulanka_her_24", "0", "0"},
[432523] = {432523, 13025, 26, 19, "0", "0", "嗚……我會查漏補缺的，請等著我。", "0", "0", "0", "0", "0", "cv_fulanka_her_26", "0", "0"},
[432524] = {432524, 13025, 27, 20, "0", "0", "哦~您終於來了，快走吧。", "0", "0", "0", "0", "0", "cv_fulanka_her_27", "0", "0"},
[432525] = {432525, 13025, 28, 21, "0", "0", "接下來是要去維護池幫助駕駛員們呢……我相信領航是不會偷偷和其他駕駛員偷情的吧？", "0", "0", "0", "0", "0", "cv_fulanka_her_28", "0", "0"},
[432526] = {432526, 13025, 29, 21, "0", "0", "不知道為什麼，脫下婚紗之後小惡魔的翅膀和尾巴都消失了……難道說這兩者有什麼關聯嗎……", "0", "0", "0", "0", "0", "cv_fulanka_her_29", "0", "0"},
[432527] = {432527, 13025, 30, 22, "0", "0", "要開始了……緊張……要加油哦！", "0", "0", "0", "0", "0", "cv_fulanka_her_30", "0", "0"},
[432528] = {432528, 13025, 31, 23, "0", "0", "我相信領航！總不能忘記即將要結婚的物件的聲音和背影吧！？", "0", "0", "0", "0", "0", "cv_fulanka_her_31", "0", "0"},
[432529] = {432529, 13025, 32, 24, "0", "0", "能好好地認出我了，嘿嘿，好棒好棒！給努力領航的肯定！", "0", "0", "0", "0", "0", "cv_fulanka_her_32", "0", "0"},
[432530] = {432530, 13025, 33, 25, "0", "0", "都快結婚了竟然認不出來我！？", "0", "0", "0", "0", "0", "cv_fulanka_her_33", "0", "0"},
[432531] = {432531, 13025, 34, 26, "0", "0", "歡迎回來，今天也辛苦了。", "0", "0", "0", "0", "0", "cv_fulanka_her_34", "0", "0"},
[432532] = {432532, 13025, 35, 27, "0", "0", "不論過程有多艱辛，我們終於迎來了最好的結局。", "0", "0", "0", "0", "0", "cv_fulanka_her_35", "0", "0"},
[432533] = {432533, 13025, 36, 28, "0", "0", "不要懈怠。", "0", "0", "0", "0", "0", "cv_fulanka_her_36", "0", "0"},
[432534] = {432534, 13025, 37, 29, "0", "0", "我努力追上大家了嗎？……嘿嘿，在某些方面確實領先大家很多了。", "0", "0", "0", "0", "0", "cv_fulanka_her_37", "0", "0"},
[432535] = {432535, 13025, 38, 30, "0", "0", "邀請大家參加我們的婚禮吧？", "0", "0", "0", "0", "0", "cv_fulanka_her_38", "0", "0"},
[432536] = {432536, 13025, 39, 31, "0", "0", "不如把婚紗也設計成AVG藍圖吧？", "0", "0", "0", "0", "0", "cv_fulanka_her_39", "0", "0"},
[432537] = {432537, 13025, 40, 32, "0", "0", "我想買點東西佈置一下婚房……", "0", "0", "0", "0", "0", "cv_fulanka_her_40", "0", "0"},
[432538] = {432538, 13025, 41, 33, "0", "0", "可以把婚紗照擺在這裡嗎？", "0", "0", "0", "0", "0", "cv_fulanka_her_41", "0", "0"},
[432539] = {432539, 13025, 42, 34, "0", "0", "要好好規劃好結婚當天的行程呢……", "0", "0", "0", "0", "0", "cv_fulanka_her_42", "0", "0"},
[432540] = {432540, 13025, 43, 35, "0", "0", "寫信告訴大家我們要結婚了這個好消息吧？", "0", "0", "0", "0", "0", "cv_fulanka_her_43", "0", "0"},
[432541] = {432541, 13025, 44, 36, "0", "0", "早點回來哦？我在家裡等著你。", "0", "0", "0", "0", "0", "cv_fulanka_her_44", "0", "0"},
[432542] = {432542, 13025, 45, 37, "0", "0", "嘿嘿……", "0", "0", "0", "0", "0", "cv_fulanka_her_45", "0", "0"},
[440000] = {440000, 14000, 1, 1, "0", "0", "蒼霧殘響", "0", "0", "0", "0", "0", "cv_starry2_1", "0", "0"},
[440001] = {440001, 14000, 2, 2, "0", "0", "有沒有想我？我倒是每天都在想你，色狼先生。", "0", "0", "0", "0", "0", "cv_starry2_2", "0", "0"},
[440002] = {440002, 14000, 3, 3, "0", "0", "色狼先生，這段時間有好好吃飯，好好休息嗎，感覺你消瘦了不少——我？沒事的，只是點小事故，跟喝水被嗆到沒區別。", "0", "0", "0", "0", "0", "cv_starry2_3", "0", "0"},
[440003] = {440003, 14000, 4, 4, "0", "idle", "色狼先生，感覺我們那之後就一直沒有機會好好聊聊。這次要好好地——把這段時間欠下的都說出來。", "0", "0", "0", "0", "0", "cv_starry2_4", "0", "0"},
[440004] = {440004, 14000, 5, 4, "0", "idle", "才能是上天賜予的禮物，也是被選中的人不得不背負的詛咒……每個人都有自己的詛咒，我想……我的詛咒就是“幸運”吧。", "0", "0", "0", "0", "0", "cv_starry2_5", "0", "0"},
[440005] = {440005, 14000, 6, 4, "0", "idle", "有人並肩作戰的感覺也許沒我預想的那麼糟糕……不過，我果然還是一個人最合適。“孤獨是女孩子最好的化妝品！”有句話是這麼說的，你聽過嗎？", "0", "0", "0", "0", "0", "cv_starry2_6", "0", "0"},
[440006] = {440006, 14000, 7, 5, "1_》_0_0.8", "level1", "我好想一直待在這裏……哪都不想去……但是果然不行吧，不管是你，還是我，都有要奔赴的戰場。一旦停下來，說不定就會有更多無辜的人死去，你不會允許這種事發生的。", "0", "0", "0", "0", "0", "cv_starry2_7", "0", "0"},
[440007] = {440007, 14000, 8, 5, "1_》_0_0.8", "level1", "嗯，我知道，多瑙的事，第三研究室防衛班的事，還有瑪雅的事……我都知道，你做的很棒，色狼先生。", "0", "0", "0", "0", "0", "cv_starry2_8", "0", "0"},
[440008] = {440008, 14000, 9, 5, "1_》_100_1.5", "level2", "色狼先生，你覺得這一切什麼時候才會結束呢……還是說，永遠無法結束呢？不……沒什麼，我只是有點累了。", "0", "0", "0", "0", "0", "cv_starry2_9", "0", "0"},
[440009] = {440009, 14000, 10, 5, "1_》_500_2", "level3", "墮落的源頭是想要追求幸福的心。人越是想用自己的手抓住幸福的繩子，就越容易從空中墜下。從一開始就認定自己無法獲得幸福的話，我大概就不會動搖了吧。", "0", "0", "0", "0", "0", "cv_starry2_10", "0", "0"},
[440010] = {440010, 14000, 11, 5, "1_》_1000_2.5", "level4", "再過不久……我們又要分別了吧。沒關係的，你身邊有許多優秀的人……查麗莎，還有那個能看到未來的孩子，有她們在，你是不會出事的。我會心揣著希望，期待我們下一次重逢的。", "0", "0", "0", "0", "0", "cv_starry2_11", "0", "0"},
[440011] = {440011, 14000, 12, 6, "0", "0", "哈哈……手有點疼……", "0", "0", "0", "0", "0", "cv_starry2_12", "0", "0"},
[440012] = {440012, 14000, 13, 7, "0", "0", "還算在控制範圍吧。", "0", "0", "0", "0", "0", "cv_starry2_13", "0", "0"},
[440013] = {440013, 14000, 14, 8, "0", "0", "在燃盡之前綻放出最耀眼的光，這就是我要做的事。", "0", "0", "0", "0", "0", "cv_starry2_14", "0", "0"},
[440014] = {440014, 14000, 15, 9, "0", "0", "偶爾也想變得更耀眼一點。", "0", "0", "0", "0", "0", "cv_starry2_15", "0", "0"},
[440015] = {440015, 14000, 16, 10, "0", "0", "又能並肩作戰了呢。", "0", "0", "0", "0", "0", "cv_starry2_16", "0", "0"},
[440016] = {440016, 14000, 17, 11, "0", "0", "這次做到了，誰都沒有受傷。", "0", "0", "0", "0", "0", "cv_starry2_17", "0", "0"},
[440017] = {440017, 14000, 18, 12, "0", "0", "果然還是不夠走運啊。", "0", "0", "0", "0", "0", "cv_starry2_18", "0", "0"},
[440018] = {440018, 14000, 19, 13, "0", "0", "還要繼續嗎……", "0", "0", "0", "0", "0", "cv_starry2_19", "0", "0"},
[440019] = {440019, 14000, 20, 14, "0", "0", "我們……走吧。", "0", "0", "0", "0", "0", "cv_starry2_20", "0", "0"},
[440020] = {440020, 14000, 21, 15, "0", "0", "真髒啊。", "0", "0", "0", "0", "0", "cv_starry2_21", "0", "0"},
[440021] = {440021, 14000, 23, 16, "0", "0", "上咯。", "0", "0", "0", "0", "0", "cv_starry2_23", "0", "0"},
[440022] = {440022, 14000, 24, 17, "0", "0", "很走運呢。", "0", "0", "0", "0", "0", "cv_starry2_24", "0", "0"},
[440023] = {440023, 14000, 25, 18, "0", "0", "不會有事的，我保證。", "0", "0", "0", "0", "0", "cv_starry2_25", "0", "0"},
[440024] = {440024, 14000, 26, 19, "0", "0", "沒事的，因為我很幸運嘛。", "0", "0", "0", "0", "0", "cv_starry2_26", "0", "0"},
[440025] = {440025, 14000, 27, 20, "0", "0", "哈哈哈——讓我想起我們第一次見面的時候……“第一次”……", "0", "0", "0", "0", "0", "cv_starry2_27", "0", "0"},
[440026] = {440026, 14000, 28, 21, "0", "0", "那些東西……果然還是有點嚇人吧？不知道除黑頭的面膜能不能除去它們呢？", "0", "0", "0", "0", "0", "cv_starry2_28", "0", "0"},
[440027] = {440027, 14000, 29, 21, "0", "0", "疼疼疼……不知道那些有腎結石的人是不是也是這種感覺？", "0", "0", "0", "0", "0", "cv_starry2_29", "0", "0"},
[440028] = {440028, 14000, 30, 22, "0", "0", "發生好事了嗎？", "0", "0", "0", "0", "0", "cv_starry2_30", "0", "0"},
[440029] = {440029, 14000, 31, 23, "0", "0", "又要來嗎？", "0", "0", "0", "0", "0", "cv_starry2_31", "0", "0"},
[440030] = {440030, 14000, 32, 24, "0", "0", "這次我想直率的表達——我很高興，色狼先生。", "0", "0", "0", "0", "0", "cv_starry2_32", "0", "0"},
[440031] = {440031, 14000, 33, 25, "0", "0", "別在意~總會有錯的時候。", "0", "0", "0", "0", "0", "cv_starry2_33", "0", "0"},
[440032] = {440032, 14000, 34, 26, "0", "0", "分別，然後重逢，接著是分別……我們一定能脫離這個迴圈的。", "0", "0", "0", "0", "0", "cv_starry2_34", "0", "0"},
[440033] = {440033, 14000, 35, 27, "0", "0", "好啦，戰場還在等著我們呢，出發吧。", "0", "0", "0", "0", "0", "cv_starry2_35", "0", "0"},
[440034] = {440034, 14000, 36, 28, "0", "0", "我不會讓給別人的。", "0", "0", "0", "0", "0", "cv_starry2_36", "0", "0"},
[440035] = {440035, 14000, 37, 29, "0", "0", "又多了些不認識的人呢。", "0", "0", "0", "0", "0", "cv_starry2_37", "0", "0"},
[440036] = {440036, 14000, 38, 30, "0", "0", "你還真是永不滿足呢。", "0", "0", "0", "0", "0", "cv_starry2_38", "0", "0"},
[440037] = {440037, 14000, 39, 31, "0", "0", "全力武裝自己，盡可能變強吧。", "0", "0", "0", "0", "0", "cv_starry2_39", "0", "0"},
[440038] = {440038, 14000, 40, 32, "0", "0", "有什麼想買的嗎？", "0", "0", "0", "0", "0", "cv_starry2_40", "0", "0"},
[440039] = {440039, 14000, 41, 33, "0", "0", "士別三日，刮目相看~", "0", "0", "0", "0", "0", "cv_starry2_41", "0", "0"},
[440040] = {440040, 14000, 42, 34, "0", "0", "怎麼了？", "0", "0", "0", "0", "0", "cv_starry2_42", "0", "0"},
[440041] = {440041, 14000, 43, 35, "0", "0", "又是女孩子的信嗎？", "0", "0", "0", "0", "0", "cv_starry2_43", "0", "0"},
[440042] = {440042, 14000, 44, 36, "0", "0", "真有精神啊。", "0", "0", "0", "0", "0", "cv_starry2_44", "0", "0"},
[440043] = {440043, 14000, 45, 37, "0", "0", "哈啊……", "0", "0", "0", "0", "0", "cv_starry2_45", "0", "0"},
[440100] = {440100, 14001, 1, 1, "0", "0", "蒼霧殘響", "0", "0", "0", "0", "0", "cv_korsgaard_1", "0", "0"},
[440101] = {440101, 14001, 2, 2, "0", "0", "雖然不擅長，但我相信你的選擇。", "0", "0", "0", "0", "0", "cv_korsgaard_2", "0", "0"},
[440102] = {440102, 14001, 3, 3, "0", "0", "沒想到重逢來得這麼快，領航。多餘的寒暄就留在日後吧，我——珀因雷德教會騎士團長珂斯嘉德，期待與你的再次合作。", "0", "0", "0", "0", "0", "cv_korsgaard_3", "0", "0"},
[440103] = {440103, 14001, 4, 4, "0", "idle", "宛如一尊巨大的神像，只是佇立於此就能讓人心安的話，這份工作倒也不算沒有意義。", "0", "0", "0", "0", "0", "cv_korsgaard_4", "0", "0"},
[440104] = {440104, 14001, 5, 4, "0", "idle2", "領航是在冥想？我煩惱時也常常如此。分明看似什麼也沒思考，卻反倒有利於之後的行動，人類的精神還真是奇妙啊。", "0", "0", "0", "0", "0", "cv_korsgaard_5", "0", "0"},
[440105] = {440105, 14001, 6, 4, "0", "idle3", "我曾認為不該過分探究別人的本質，因此對於米菈隊長和梅莉雅的一些違和之處並未過問，但現在看來，這只不過是在逃避吧。", "0", "0", "0", "0", "0", "cv_korsgaard_6", "0", "0"},
[440106] = {440106, 14001, 7, 5, "1_》_0_0.8", "level1", "如之前所說，這支左臂失去了運動機能，但在巨大化狀態卻可以正常使用。而我現在之所以不用……大概是覺得，劍在鞘中時才最具價值。", "0", "0", "0", "0", "0", "cv_korsgaard_7", "0", "0"},
[440107] = {440107, 14001, 8, 5, "1_》_0_0.8", "level1", "要說我遠在外鄉，對珀因雷德的狀況是否擔心，答案是毋庸置疑的。但那座城市已有了靠自己飛離舊巢的力量，接下來的，就交給時間吧。", "0", "0", "0", "0", "0", "cv_korsgaard_8", "0", "0"},
[440108] = {440108, 14001, 9, 5, "1_》_100_1.5", "level2", "怎麼了？想再進行一場痛痛快快的決鬥的話，我很樂意奉陪。只是現在這副狀態不太合適，或者……我們可以先通感，在內心來一場模擬戰？", "0", "0", "0", "0", "0", "cv_korsgaard_9", "0", "0"},
[440109] = {440109, 14001, 10, 5, "1_》_500_2", "level3", "除了劍術，我當然也有其他更為尋常的興趣，例如登山、看書、喝茶之類……唔，還是太古板了嗎？那麼，我就向領航討教些更現代的娛樂方式吧？", "0", "0", "0", "0", "0", "cv_korsgaard_10", "0", "0"},
[440110] = {440110, 14001, 11, 5, "1_》_1000_2.5", "level4", "所謂純粹，就是保持本真，因此我向來以此要求自己。但與世界相處的模式只是這樣就可以了嗎？我不知道……我唯一能確認的，只有在你身邊會更加安心。", "0", "0", "0", "0", "0", "cv_korsgaard_11", "0", "0"},
[440111] = {440111, 14001, 12, 6, "0", "0", "有勞你了。", "0", "0", "0", "0", "0", "cv_korsgaard_12", "0", "0"},
[440112] = {440112, 14001, 13, 7, "0", "0", "強大的力量，需要更強的心靈來控制。", "0", "0", "0", "0", "0", "cv_korsgaard_13", "0", "0"},
[440113] = {440113, 14001, 14, 8, "0", "0", "那次事件之後，我原以為我會不再堅持玻璃製品般易碎的“純粹”，但與你相處的這段時間，讓我重新開始思考何為純粹，何為永恆。", "0", "0", "0", "0", "0", "cv_korsgaard_14", "0", "0"},
[440114] = {440114, 14001, 15, 9, "0", "0", "不斷磨礪劍藝。", "0", "0", "0", "0", "0", "cv_korsgaard_15", "0", "0"},
[440115] = {440115, 14001, 16, 10, "0", "0", "我即是防線。", "0", "0", "0", "0", "0", "cv_korsgaard_16", "0", "0"},
[440116] = {440116, 14001, 17, 11, "0", "0", "勝利的滋味，和大家一起分享吧。", "0", "0", "0", "0", "0", "cv_korsgaard_17", "0", "0"},
[440117] = {440117, 14001, 18, 12, "0", "0", "還有提升空間呢。", "0", "0", "0", "0", "0", "cv_korsgaard_18", "0", "0"},
[440118] = {440118, 14001, 19, 13, "0", "0", "真危險啊……應當吸取教訓。", "0", "0", "0", "0", "0", "cv_korsgaard_19", "0", "0"},
[440119] = {440119, 14001, 20, 14, "0", "0", "我會反省，領航也請不用吝惜懲罰。", "0", "0", "0", "0", "0", "cv_korsgaard_20", "0", "0"},
[440120] = {440120, 14001, 21, 15, "0", "0", "仍不可大意。", "0", "0", "0", "0", "0", "cv_korsgaard_21", "0", "0"},
[440121] = {440121, 14001, 23, 16, "0", "0", "時刻專注。", "0", "0", "0", "0", "0", "cv_korsgaard_22", "0", "0"},
[440122] = {440122, 14001, 24, 17, "0", "0", "聖光所賜！", "0", "0", "0", "0", "0", "cv_korsgaard_23", "0", "0"},
[440123] = {440123, 14001, 25, 18, "0", "0", "神聖之劍啊，請用這份光芒指引我吧。", "0", "0", "0", "0", "0", "cv_korsgaard_24", "0", "0"},
[440124] = {440124, 14001, 26, 19, "0", "0", "必須得戰鬥到最後一刻……", "0", "0", "0", "0", "0", "cv_korsgaard_25", "0", "0"},
[440125] = {440125, 14001, 27, 20, "0", "0", "來了啊，今天就拜託你了。", "0", "0", "0", "0", "0", "cv_korsgaard_26", "0", "0"},
[440126] = {440126, 14001, 28, 21, "0", "0", "可能因為我自己就是個直率的人，像這樣坦誠相待的感覺很不錯。", "0", "0", "0", "0", "0", "cv_korsgaard_27", "0", "0"},
[440127] = {440127, 14001, 29, 21, "0", "0", "領航？注意力請稍微集中些，畢竟我也不是一點都不害羞的。", "0", "0", "0", "0", "0", "cv_korsgaard_28", "0", "0"},
[440128] = {440128, 14001, 30, 22, "0", "0", "加油。", "0", "0", "0", "0", "0", "cv_korsgaard_29", "0", "0"},
[440129] = {440129, 14001, 31, 23, "0", "0", "這個遊戲是……？", "0", "0", "0", "0", "0", "cv_korsgaard_30", "0", "0"},
[440130] = {440130, 14001, 32, 24, "0", "0", "看來是個會增加信賴感的遊戲呢。", "0", "0", "0", "0", "0", "cv_korsgaard_31", "0", "0"},
[440131] = {440131, 14001, 33, 25, "0", "0", "好吧，我們還需更加熟悉彼此才行。", "0", "0", "0", "0", "0", "cv_korsgaard_32", "0", "0"},
[440132] = {440132, 14001, 34, 26, "0", "0", "人既要恪守本心，又始終力求進步，在你身上能看到調和兩者的方法嗎？請讓我見識一下吧，你會做出何種選擇，領航。", "0", "0", "0", "0", "0", "cv_korsgaard_33", "0", "0"},
[440133] = {440133, 14001, 35, 27, "0", "0", "該出擊了嗎。", "0", "0", "0", "0", "0", "cv_korsgaard_34", "0", "0"},
[440134] = {440134, 14001, 36, 28, "0", "0", "以劍會友吧。", "0", "0", "0", "0", "0", "cv_korsgaard_35", "0", "0"},
[440135] = {440135, 14001, 37, 29, "0", "0", "大家都有各自的目標啊。", "0", "0", "0", "0", "0", "cv_korsgaard_36", "0", "0"},
[440136] = {440136, 14001, 38, 30, "0", "0", "領航所賞識的新人嗎？", "0", "0", "0", "0", "0", "cv_korsgaard_37", "0", "0"},
[440137] = {440137, 14001, 39, 31, "0", "0", "不要過於依賴裝備就好。", "0", "0", "0", "0", "0", "cv_korsgaard_38", "0", "0"},
[440138] = {440138, 14001, 40, 32, "0", "0", "請注意開銷。", "0", "0", "0", "0", "0", "cv_korsgaard_39", "0", "0"},
[440139] = {440139, 14001, 41, 33, "0", "0", "非常漂亮的履歷。", "0", "0", "0", "0", "0", "cv_korsgaard_40", "0", "0"},
[440140] = {440140, 14001, 42, 34, "0", "0", "仔細檢查下吧。", "0", "0", "0", "0", "0", "cv_korsgaard_41", "0", "0"},
[440141] = {440141, 14001, 43, 35, "0", "0", "有信到了嗎？", "0", "0", "0", "0", "0", "cv_korsgaard_42", "0", "0"},
[440142] = {440142, 14001, 44, 36, "0", "0", "以言語交戰的地方呢。", "0", "0", "0", "0", "0", "cv_korsgaard_43", "0", "0"},
[440143] = {440143, 14001, 45, 37, "0", "0", "請。", "0", "0", "0", "0", "0", "cv_korsgaard_44", "0", "0"},
[440200] = {440200, 14002, 1, 1, "0", "0", "蒼霧殘響", "ハツリバーブ", "0", "0", "0", "0", "cv_aofeiliya2_1", "0", "0"},
[440201] = {440201, 14002, 2, 2, "0", "0", "就、就交給我吧！", "う、うちに任せてください！", "0", "0", "0", "0", "cv_aofeiliya2_2", "0", "0"},
[440202] = {440202, 14002, 3, 3, "0", "0", "遵，遵從古老的誓約而來，我、我是您的騎士奧菲莉亞，因為深知自己的不足正在【星之騎士】修行中……再一次，請多多指教！", "い、古の誓いに従い參上しました。う、うちがあなたの騎士・オフィーリアです。まだ力不足ゆえ、【星の騎士】として修行中の身です……あらためて、よろしくお願いいたします！", "0", "0", "0", "0", "cv_aofeiliya2_3", "0", "0"},
[440203] = {440203, 14002, 4, 4, "0", "idle", "領、領航要去我的星球看看嗎？我的“奧菲莉亞星”，我、我在上面建造了一個全新的水車村……是我在這裡的家。", "な、なびげーたーさん、うちの星を見ますか？　オフィーリア星にはですね、新しい水車村を……うちの家を作ってあるんです。", "0", "0", "0", "0", "cv_aofeiliya2_4", "0", "0"},
[440204] = {440204, 14002, 5, 4, "0", "idle", "我、我作為女主角最後的結局是什麼？領航竟然會好奇這件事……不過，我是不會告訴您的，容我暫且保留這個秘密吧？", "ひ、ひろいんとしてのうちの最期、ですか？なびげーたーさんがそんな事を気にするなんて……でも、教えることはできません。しばらく秘密にさせてくれませんか？", "0", "0", "0", "0", "cv_aofeiliya2_5", "0", "0"},
[440205] = {440205, 14002, 6, 4, "0", "idle", "沒、沒想到宇宙和平星竟然會選擇我這樣的人……聽說星之君主是宇宙的代言人……我、我真的能做好嗎……", "ま、まさかこすみっく・ぴーすすたーがうちを選ぶだなんて……星の君主は宇宙の代弁者だって話ですけど……う、うち、ちゃんとやれるんでしょうか……", "0", "0", "0", "0", "cv_aofeiliya2_6", "0", "0"},
[440206] = {440206, 14002, 7, 5, "15_1_0_0.8", "level2", "哇啊啊……好、好險……差一點就暈過去了。", "あわわ……あ、あぶなかった……もう少しで気絶するところでした。", "0", "0", "0", "0", "cv_aofeiliya2_7", "0", "0"},
[440207] = {440207, 14002, 8, 5, "15_1_0_0.8", "level2", "總感覺……暈乎乎的……好難受。", "なんだか……頭がぼんやりして……苦しいです。", "0", "0", "0", "0", "cv_aofeiliya2_8", "0", "0"},
[440208] = {440208, 14002, 9, 5, "15_2_0_0.8", "level1", "頭、頭套——呼，這樣就不用擔心被熟悉的駕駛員認出來了……多虧了米菈隊長給我的幫助……", "か、被り物を……ふぅ、これで他のどらいばーにバレずにすみますね……ミーラ隊長のおかげです……", "0", "0", "0", "0", "cv_aofeiliya2_9", "0", "0"},
[440209] = {440209, 14002, 10, 5, "15_2_0_0.8", "level1", "既然這麼害羞為什麼還要穿這身泳衣？這是梅莉雅為我準備的……我、我覺得還是不能辜負她的好意……我、我沒關係的！", "そんなに恥ずかしいのになんで水著を著るのか、ですか？これはメリアがうちに用意してくれたものだから……彼女の好意をムダにしたくなくて……だ、だから平気です！", "0", "0", "0", "0", "cv_aofeiliya2_10", "0", "0"},
[440210] = {440210, 14002, 11, 5, "15_2_0_0.8", "level1", "領、領航，你有看最近很火熱的《騎士的禁忌愛戀》嗎？我、我覺得故事的主人公，實、實在是不檢點！但、但是我、我們啟泉會是允許結結結結婚的，也就是說我、我與領航是可以的結婚的！", "な、なびげーたーさん、最近流行ってた『騎士の許されざる恋愛』って見ましたか？あ、あの主人公ったら、なってませんよね！で、でも、れべれーしょん・すぷりんぐはけ、けけけ結婚を認めているので、つまりう、うちとなびげーたーさんも結婚できるってことですよ！", "0", "0", "0", "0", "cv_aofeiliya2_11", "0", "0"},
[440211] = {440211, 14002, 12, 6, "0", "0", "能、能感受到宇宙的力量，已、已經開始傳遞了。", "う、宇宙の力が伝わって來るのを、か、感じます。", "0", "0", "0", "0", "cv_aofeiliya2_12", "0", "0"},
[440212] = {440212, 14002, 13, 7, "0", "0", "這還不是我的極限……請繼續吧，我、我會忍耐的！", "うちはまだ限界じゃありません……続けましょう、う、うち頑張ります！", "0", "0", "0", "0", "cv_aofeiliya2_13", "0", "0"},
[440213] = {440213, 14002, 14, 8, "0", "0", "啊……就在剛剛的一瞬間，我好像能感受到命運的水車開始轉動了……奇怪……", "あ……いま、運命の水車が回り始めたのを感じました……なんか不思議ですね……", "0", "0", "0", "0", "cv_aofeiliya2_14", "0", "0"},
[440214] = {440214, 14002, 15, 9, "0", "0", "啊——嚇、嚇死我了，我、我還沒做好心理準備呢。", "うわ…！　び、びっくりしました。まだ心の準備ができてなくて……", "0", "0", "0", "0", "cv_aofeiliya2_15", "0", "0"},
[440215] = {440215, 14002, 16, 10, "0", "0", "【星之騎士】，准、準備開始前進了。", "【星の騎士】い、いつでも行けます。", "0", "0", "0", "0", "cv_aofeiliya2_16", "0", "0"},
[440216] = {440216, 14002, 17, 11, "0", "0", "呼……戰、戰鬥總算結束了，趕緊回去洗澡吧。", "ふぅ……や、やっと終わりましたぁ……早く戻ってお風呂にしましょう……", "0", "0", "0", "0", "cv_aofeiliya2_17", "0", "0"},
[440217] = {440217, 14002, 18, 12, "0", "0", "距、距離成為真正的騎士還有一點距離。", "ほ、本當の騎士になるまでには、もう少しかかりそうです。", "0", "0", "0", "0", "cv_aofeiliya2_18", "0", "0"},
[440218] = {440218, 14002, 19, 13, "0", "0", "請領航不要遠離我，接下來要小心了。", "なびげーたーさん、気をつけて……うちから離れないでくださいね。", "0", "0", "0", "0", "cv_aofeiliya2_19", "0", "0"},
[440219] = {440219, 14002, 20, 14, "0", "0", "沒有時間再猶豫了，請您下達撤退的指令吧。", "これ以上迷っていては……撤退命令をお願いします！", "0", "0", "0", "0", "cv_aofeiliya2_20", "0", "0"},
[440220] = {440220, 14002, 21, 15, "0", "0", "去、去死！", "し、死んでください！", "0", "0", "0", "0", "cv_aofeiliya2_21", "0", "0"},
[440221] = {440221, 14002, 23, 16, "0", "0", "咿——！", "ハァー！", "0", "0", "0", "0", "cv_aofeiliya2_23", "0", "0"},
[440222] = {440222, 14002, 24, 17, "0", "0", "呀——！", "やぁー！", "0", "0", "0", "0", "cv_aofeiliya2_24", "0", "0"},
[440223] = {440223, 14002, 25, 18, "0", "0", "和平星啊，為大家照亮前路吧！", "ピーススターよ、みんなの道を照らしてください！", "0", "0", "0", "0", "cv_aofeiliya2_25", "0", "0"},
[440224] = {440224, 14002, 26, 19, "0", "0", "等我回來。", "必ず戻って來ます。", "0", "0", "0", "0", "cv_aofeiliya2_26", "0", "0"},
[440225] = {440225, 14002, 27, 20, "0", "0", "不管是戰鬥後還是游泳之後都要好好地清洗自己的身體。", "戦闘の後も水泳の後も、しっかり體を洗わなきゃですね。", "0", "0", "0", "0", "cv_aofeiliya2_27", "0", "0"},
[440226] = {440226, 14002, 28, 21, "0", "0", "領、領航更喜歡那種肌膚呢？是、是稍微被曬黑一點的健康膚色……還、還是現在這樣就好……我、我可以做好準備……", "な、なびげーたーさんって、ああいう感じの子がお好きなんですか？ちょっと日に焼けた、健康的な感じの……やっぱり今はこういうのが……わ、分かりました……", "0", "0", "0", "0", "cv_aofeiliya2_28", "0", "0"},
[440227] = {440227, 14002, 29, 21, "0", "0", "肩、肩膀好僵硬……是因為一直在戰鬥的原因吧……不過還好有領航幫我調理。", "か、肩がガチガチですね……ずっと戦っていたからでしょうか……でも、なびげーたーさんがほぐしてくれるので助かります。", "0", "0", "0", "0", "cv_aofeiliya2_29", "0", "0"},
[440228] = {440228, 14002, 30, 22, "0", "0", "又、又開始了嗎！", "ま、また始まったんですね！", "0", "0", "0", "0", "cv_aofeiliya2_30", "0", "0"},
[440229] = {440229, 14002, 31, 23, "0", "0", "領、領航可千萬不要猜錯啊，加油！", "な、なびげーたーさん、間違えちゃダメですよ。がんばって！", "0", "0", "0", "0", "cv_aofeiliya2_31", "0", "0"},
[440230] = {440230, 14002, 32, 24, "0", "0", "嘿嘿嘿，不愧是我的主君。", "えへへ、さすがはうちの主さまです。", "0", "0", "0", "0", "cv_aofeiliya2_32", "0", "0"},
[440231] = {440231, 14002, 33, 25, "0", "0", "我、我還是希望領航能認出我的！", "な、なびげーたーさんなら當ててくれると思ってたのに……", "0", "0", "0", "0", "cv_aofeiliya2_33", "0", "0"},
[440232] = {440232, 14002, 34, 26, "0", "0", "如果時間能不再流動，每一天每一天都能見到您就好了。", "いま時間が止まったら、なびげーたーさんをずっと見ていられますね。", "0", "0", "0", "0", "cv_aofeiliya2_34", "0", "0"},
[440233] = {440233, 14002, 35, 27, "0", "0", "我會盡到騎士的職責的，請待在我身後吧。", "うちが騎士としての務めを果たします。うちの後ろに下がっていてください。", "0", "0", "0", "0", "cv_aofeiliya2_35", "0", "0"},
[440234] = {440234, 14002, 36, 28, "0", "0", "我會跟上大家的行動的。", "みんなに著いて行きます。", "0", "0", "0", "0", "cv_aofeiliya2_36", "0", "0"},
[440235] = {440235, 14002, 37, 29, "0", "0", "大家……", "みんな……", "0", "0", "0", "0", "cv_aofeiliya2_37", "0", "0"},
[440236] = {440236, 14002, 38, 30, "0", "0", "想好要遇見哪位駕駛員了嗎？", "どのどらいばーさんに会うか決まりましたか？", "0", "0", "0", "0", "cv_aofeiliya2_38", "0", "0"},
[440237] = {440237, 14002, 39, 31, "0", "0", "找一些正常的衣服換掉泳裝吧……沒、沒有？也是呢……", "み、水著に著替えるんですか？　……ち、違う？　そうですか……", "0", "0", "0", "0", "cv_aofeiliya2_39", "0", "0"},
[440238] = {440238, 14002, 40, 32, "0", "0", "好貴……", "高いですね……", "0", "0", "0", "0", "cv_aofeiliya2_40", "0", "0"},
[440239] = {440239, 14002, 41, 33, "0", "0", "領航的照片……要裝裱起來……", "なびげーたーさんの寫真……ちゃんと額に入れなきゃ……", "0", "0", "0", "0", "cv_aofeiliya2_41", "0", "0"},
[440240] = {440240, 14002, 42, 34, "0", "0", "嗯……", "えーっと……", "0", "0", "0", "0", "cv_aofeiliya2_42", "0", "0"},
[440241] = {440241, 14002, 43, 35, "0", "0", "我會記得給您寫信的。", "ちゃんと手紙を出しますね。", "0", "0", "0", "0", "cv_aofeiliya2_43", "0", "0"},
[440242] = {440242, 14002, 44, 36, "0", "0", "好、好吵……", "に、賑やかですね……", "0", "0", "0", "0", "cv_aofeiliya2_44", "0", "0"},
[440243] = {440243, 14002, 45, 37, "0", "0", "哇哦。", "わわっ。", "0", "0", "0", "0", "cv_aofeiliya2_45", "0", "0"},
[440300] = {440300, 14003, 1, 1, "0", "0", "蒼霧殘響。", "0", "0", "0", "0", "0", "cv_iria2_1", "0", "0"},
[440301] = {440301, 14003, 2, 2, "0", "0", "可以算在加班時長上嗎？", "0", "0", "0", "0", "0", "cv_iria2_2", "0", "0"},
[440302] = {440302, 14003, 3, 3, "0", "0", "這次的重逢是難得的機會，我要向領航您展現我的蛻變。", "0", "0", "0", "0", "0", "cv_iria2_3", "0", "0"},
[440303] = {440303, 14003, 4, 4, "0", "idle", "聖誕節過後，灰燼好像受到了卡佳支部上層的關注，給了我們更多的物資配給。我想這都是托了領航的福。", "0", "0", "0", "0", "0", "cv_iria2_4", "0", "0"},
[440304] = {440304, 14003, 5, 4, "0", "idle2", "對原罪的仇恨我不會忘，但我不會再讓仇恨支配我的心。從今往後，我的怒火將在平靜中燃燒。", "0", "0", "0", "0", "0", "cv_iria2_5", "0", "0"},
[440305] = {440305, 14003, 6, 4, "0", "idle3", "原本我最擔心的人是波琳娜，害怕她在離開我之後一個人沒有辦法好好生活。不過從聖誕節的表現來看，好像是克裡姆更不讓人省心。", "0", "0", "0", "0", "0", "cv_iria2_6", "0", "0"},
[440306] = {440306, 14003, 7, 5, "1_》_0_0.8", "level", "我和灰燼，都已經走上了一條和之前完全不同的道路。但無論在哪，領航您都是唯一指引著我們的北極星。", "0", "0", "0", "0", "0", "cv_iria2_7", "0", "0"},
[440307] = {440307, 14003, 8, 5, "1_》_0_0.8", "level2", "我還不是不敢相信，我的左手竟然能恢複如初。", "0", "0", "0", "0", "0", "cv_iria2_8", "0", "0"},
[440308] = {440308, 14003, 9, 5, "1_》_100_1.5", "level3", "是領航將我從複仇的深淵中拉了回來，所以領航想做什麼都沒關系。", "0", "0", "0", "0", "0", "cv_iria2_9", "0", "0"},
[440309] = {440309, 14003, 10, 5, "1_》_500_2", "level4", "“更加愛惜自己的身體。”我現在一定會做到的。因為我不想辜負領航的努力，更不想因為我的原因讓領航再次挺身犯險。", "0", "0", "0", "0", "0", "cv_iria2_10", "0", "0"},
[440310] = {440310, 14003, 11, 5, "1_》_1000_2.5", "level5", "除了左手之外，我的身體其他地方也恢複原樣。請把您的手給我……感受到了嗎？真正的心髒跳動的聲音，這就是我一直希望領航聽到的心聲。", "0", "0", "0", "0", "0", "cv_iria2_11", "0", "0"},
[440311] = {440311, 14003, 12, 6, "0", "0", "力量從身體裏湧現。", "0", "0", "0", "0", "0", "cv_iria2_12", "0", "0"},
[440312] = {440312, 14003, 13, 7, "0", "0", "燃燒一切的小火星。", "0", "0", "0", "0", "0", "cv_iria2_13", "0", "0"},
[440313] = {440313, 14003, 14, 8, "0", "0", "灰燼即將重燃，我知道取回失去的東西有多麼困難，所以才更珍惜這來之不易的奇跡。", "0", "0", "0", "0", "0", "cv_iria2_14", "0", "0"},
[440314] = {440314, 14003, 15, 9, "0", "0", "不再需要外物，我已經獲得了複仇的力量。", "0", "0", "0", "0", "0", "cv_iria2_15", "0", "0"},
[440315] = {440315, 14003, 16, 10, "0", "0", "原罪，該贖罪了。", "0", "0", "0", "0", "0", "cv_iria2_16", "0", "0"},
[440316] = {440316, 14003, 17, 11, "0", "0", "前所未有的平靜。", "0", "0", "0", "0", "0", "cv_iria2_17", "0", "0"},
[440317] = {440317, 14003, 18, 12, "0", "0", "複仇之路，還是沒那麼輕松。", "0", "0", "0", "0", "0", "cv_iria2_18", "0", "0"},
[440318] = {440318, 14003, 19, 13, "0", "0", "為了複仇，我之前到底忽視了多少代價。", "0", "0", "0", "0", "0", "cv_iria2_19", "0", "0"},
[440319] = {440319, 14003, 20, 14, "0", "0", "複仇不急於一時，重要的是大家都還活著……", "0", "0", "0", "0", "0", "cv_iria2_20", "0", "0"},
[440320] = {440320, 14003, 21, 15, "0", "0", "下一個。", "0", "0", "0", "0", "0", "cv_iria2_21", "0", "0"},
[440321] = {440321, 14003, 23, 16, "0", "0", "終將化為灰燼。", "0", "0", "0", "0", "0", "cv_iria2_22", "0", "0"},
[440322] = {440322, 14003, 24, 17, "0", "0", "慢慢來，一個都逃不掉。", "0", "0", "0", "0", "0", "cv_iria2_24", "0", "0"},
[440323] = {440323, 14003, 25, 18, "0", "0", "我從沒有忘記複仇，平靜的憤怒就是為了在這一刻燃燒殆盡。", "0", "0", "0", "0", "0", "cv_iria2_25", "0", "0"},
[440324] = {440324, 14003, 26, 19, "0", "0", "我以為……我已經……", "0", "0", "0", "0", "0", "cv_iria2_26", "0", "0"},
[440325] = {440325, 14003, 27, 20, "0", "0", "雖然不是第一次，但還是想說“拜托領航了”。", "0", "0", "0", "0", "0", "cv_iria2_27", "0", "0"},
[440326] = {440326, 14003, 28, 21, "0", "0", "能夠更加清晰地感受到領航的動作，請再溫柔一些……", "0", "0", "0", "0", "0", "cv_iria2_28", "0", "0"},
[440327] = {440327, 14003, 29, 21, "0", "0", "只有領航在時才能享受到的特殊待遇，我快沉迷其中了。", "0", "0", "0", "0", "0", "cv_iria2_29", "0", "0"},
[440328] = {440328, 14003, 30, 22, "0", "0", "等的就是這個。", "0", "0", "0", "0", "0", "cv_iria2_30", "0", "0"},
[440329] = {440329, 14003, 31, 23, "0", "0", "我還是我，這是不會改變的。", "0", "0", "0", "0", "0", "cv_iria2_31", "0", "0"},
[440330] = {440330, 14003, 32, 24, "0", "0", "果然領航還掛念著我。", "0", "0", "0", "0", "0", "cv_iria2_32", "0", "0"},
[440331] = {440331, 14003, 33, 25, "0", "0", "心痛的感覺也回來了。", "0", "0", "0", "0", "0", "cv_iria2_33", "0", "0"},
[440332] = {440332, 14003, 34, 26, "0", "0", "有原罪的消息嗎？沒有也好，我已經明白複仇不是目的，不讓原罪摧毀這裏才更有意義。", "0", "0", "0", "0", "0", "cv_iria2_34", "0", "0"},
[440333] = {440333, 14003, 35, 27, "0", "0", "請下令出戰吧，領航。", "0", "0", "0", "0", "0", "cv_iria2_35", "0", "0"},
[440334] = {440334, 14003, 36, 28, "0", "0", "按時訓練才能更好應對突發情況。", "0", "0", "0", "0", "0", "cv_iria2_36", "0", "0"},
[440335] = {440335, 14003, 37, 29, "0", "0", "大家都是因為領航才聚在這裏。", "0", "0", "0", "0", "0", "cv_iria2_37", "0", "0"},
[440336] = {440336, 14003, 38, 30, "0", "0", "繼續擴充兵力吧。", "0", "0", "0", "0", "0", "cv_iria2_38", "0", "0"},
[440337] = {440337, 14003, 39, 31, "0", "0", "艾吉斯的裝備真是日新月異。", "0", "0", "0", "0", "0", "cv_iria2_39", "0", "0"},
[440338] = {440338, 14003, 40, 32, "0", "0", "真讓我來負責采購嗎？", "0", "0", "0", "0", "0", "cv_iria2_40", "0", "0"},
[440339] = {440339, 14003, 41, 33, "0", "0", "我永遠不會忘記的面孔。", "0", "0", "0", "0", "0", "cv_iria2_41", "0", "0"},
[440340] = {440340, 14003, 42, 34, "0", "0", "還是原來的設置。", "0", "0", "0", "0", "0", "cv_iria2_42", "0", "0"},
[440341] = {440341, 14003, 43, 35, "0", "0", "不在多瑙的這段時間裏，收到了不少郵件吧。", "0", "0", "0", "0", "0", "cv_iria2_43", "0", "0"},
[440342] = {440342, 14003, 44, 36, "0", "0", "看看有沒有可靠的情報。", "0", "0", "0", "0", "0", "cv_iria2_44", "0", "0"},
[440343] = {440343, 14003, 45, 37, "0", "0", "這是？", "0", "0", "0", "0", "0", "cv_iria2_45", "0", "0"},
[440400] = {440400, 14004, 1, 1, "0", "0", "蒼霧殘響。", "0", "0", "0", "0", "0", "cv_chilyarisa_sp_01", "0", "0"},
[440401] = {440401, 14004, 2, 2, "0", "0", "嗯，我會賭上性命保護你的，領航。", "0", "0", "0", "0", "0", "cv_chilyarisa_sp_02", "0", "0"},
[440402] = {440402, 14004, 3, 3, "0", "0", "終於又見面了，領航，我為了這一天的重逢，已經等了二十年了。", "0", "0", "0", "0", "0", "cv_chilyarisa_sp_03", "0", "0"},
[440403] = {440403, 14004, 4, 4, "0", "idle", "時間真是不公平，對你來說只是短短的幾天，但對我來說已經過去了二十年……這就是關於時間的那個……那個什麼理論？", "0", "0", "0", "0", "0", "cv_chilyarisa_sp_04", "0", "0"},
[440404] = {440404, 14004, 5, 4, "0", "idle2", "我們還有希望讓一切回到正軌上嗎……也許這麼多年的堅持只是在癡人做夢……在你回來之前，我一直都如此懷疑著。現在你回來了，這一切就還有希望，我們還有未來。", "0", "0", "0", "0", "0", "cv_chilyarisa_sp_05", "0", "0"},
[440405] = {440405, 14004, 6, 4, "0", "idle3", "朱利烏斯……她真的很了不起，我用了二十年的時光，才明白怎麼當一名合格的領隊……要是她在的話，一定會比我做得更好吧。", "0", "0", "0", "0", "0", "cv_chilyarisa_sp_06", "0", "0"},
[440406] = {440406, 14004, 7, 5, "1_》_0_0.8", "level", "請繼續閃耀下去，成為指引大家的明星吧——這句話，既像是祝福，也像是詛咒……還是說，祝福本就是一種詛咒呢？", "0", "0", "0", "0", "0", "cv_chilyarisa_sp_07", "0", "0"},
[440407] = {440407, 14004, 8, 5, "1_》_0_0.8", "level2", "不要摸我的頭啦……我已經不是當初那個小姑娘了……真是的……", "0", "0", "0", "0", "0", "cv_chilyarisa_sp_08", "0", "0"},
[440408] = {440408, 14004, 9, 5, "1_》_100_1.5", "level3", "奇跡發生的時候，是要感謝神明呢？還是說感謝史蒂芬妮博士呢……不管是誰都好，我都要感謝那個人，讓我有了再一次與你相遇的機會。", "0", "0", "0", "0", "0", "cv_chilyarisa_sp_09", "0", "0"},
[440409] = {440409, 14004, 10, 5, "1_》_500_2", "level4", "嗯，我知道你會回去的……放心地回去吧。如果你成功了，我們會在新的時間裡重逢。如果你失敗了……這裡就交給我吧，我會拯救世界的……一定會的！", "0", "0", "0", "0", "0", "cv_chilyarisa_sp_10", "0", "0"},
[440410] = {440410, 14004, 11, 5, "1_》_1000_2.5", "level5", "現在的我，已經能夠坦率地面對自己的心情了。領航，我喜歡你，這份心情不會輸給世界上的任何一個人……不管是過去，現在，還是未來，我都會喜歡你。", "0", "0", "0", "0", "0", "cv_chilyarisa_sp_11", "0", "0"},
[440411] = {440411, 14004, 12, 6, "0", "0", "謝謝。", "0", "0", "0", "0", "0", "cv_chilyarisa_sp_12", "0", "0"},
[440412] = {440412, 14004, 13, 7, "0", "0", "我會一直閃耀下去的。", "0", "0", "0", "0", "0", "cv_chilyarisa_sp_13", "0", "0"},
[440413] = {440413, 14004, 14, 8, "0", "0", "我要做出能與這份榮耀匹配的實績。", "0", "0", "0", "0", "0", "cv_chilyarisa_sp_14", "0", "0"},
[440414] = {440414, 14004, 15, 9, "0", "0", "這種感覺真不錯。", "0", "0", "0", "0", "0", "cv_chilyarisa_sp_15", "0", "0"},
[440415] = {440415, 14004, 16, 10, "0", "0", "接下來，由我接管這個戰場。", "0", "0", "0", "0", "0", "cv_chilyarisa_sp_16", "0", "0"},
[440416] = {440416, 14004, 17, 11, "0", "0", "我會一直贏，一直贏，贏到最後。", "0", "0", "0", "0", "0", "cv_chilyarisa_sp_17", "0", "0"},
[440417] = {440417, 14004, 18, 12, "0", "0", "贏了就好。", "0", "0", "0", "0", "0", "cv_chilyarisa_sp_18", "0", "0"},
[440418] = {440418, 14004, 19, 13, "0", "0", "還不能鬆懈。", "0", "0", "0", "0", "0", "cv_chilyarisa_sp_19", "0", "0"},
[440419] = {440419, 14004, 20, 14, "0", "0", "不要慌亂，有序撤退。", "0", "0", "0", "0", "0", "cv_chilyarisa_sp_20", "0", "0"},
[440420] = {440420, 14004, 21, 15, "0", "0", "下一個是誰？", "0", "0", "0", "0", "0", "cv_chilyarisa_sp_21", "0", "0"},
[440421] = {440421, 14004, 23, 16, "0", "0", "滾開！", "0", "0", "0", "0", "0", "cv_chilyarisa_sp_22", "0", "0"},
[440422] = {440422, 14004, 24, 17, "0", "0", "全力以赴。", "0", "0", "0", "0", "0", "cv_chilyarisa_sp_23", "0", "0"},
[440423] = {440423, 14004, 25, 18, "0", "0", "尼德霍格——咬碎它們吧！", "0", "0", "0", "0", "0", "cv_chilyarisa_sp_25", "0", "0"},
[440424] = {440424, 14004, 26, 19, "0", "0", "至少這一次……我沒有錯過。", "0", "0", "0", "0", "0", "cv_chilyarisa_sp_26", "0", "0"},
[440425] = {440425, 14004, 27, 20, "0", "0", "是呢，該放鬆的時候就得好好放鬆。", "0", "0", "0", "0", "0", "cv_chilyarisa_sp_27", "0", "0"},
[440426] = {440426, 14004, 28, 21, "0", "0", "在想些什麼呢，領航？", "0", "0", "0", "0", "0", "cv_chilyarisa_sp_28", "0", "0"},
[440427] = {440427, 14004, 29, 21, "0", "0", "你應該沒有在幻想一些很糟糕的事情吧？", "0", "0", "0", "0", "0", "cv_chilyarisa_sp_29", "0", "0"},
[440428] = {440428, 14004, 30, 22, "0", "0", "怎麼了？", "0", "0", "0", "0", "0", "cv_chilyarisa_sp_30", "0", "0"},
[440429] = {440429, 14004, 31, 23, "0", "0", "又來這套……千萬別猜錯了啊。", "0", "0", "0", "0", "0", "cv_chilyarisa_sp_31", "0", "0"},
[440430] = {440430, 14004, 32, 24, "0", "0", "我就知道——領航是不會忘記我的。", "0", "0", "0", "0", "0", "cv_chilyarisa_sp_32", "0", "0"},
[440431] = {440431, 14004, 33, 25, "0", "0", "笨蛋……", "0", "0", "0", "0", "0", "cv_chilyarisa_sp_33", "0", "0"},
[440432] = {440432, 14004, 34, 26, "0", "0", "歡迎回來……你不在的這段時間，我可是一直有在努力呢。", "0", "0", "0", "0", "0", "cv_chilyarisa_sp_34", "0", "0"},
[440433] = {440433, 14004, 35, 27, "0", "0", "讓我們將故事書寫到尾聲吧。", "0", "0", "0", "0", "0", "cv_chilyarisa_sp_35", "0", "0"},
[440434] = {440434, 14004, 36, 28, "0", "0", "陪練嗎？我會手下留情的。", "0", "0", "0", "0", "0", "cv_chilyarisa_sp_36", "0", "0"},
[440435] = {440435, 14004, 37, 29, "0", "0", "每一位駕駛員，都是希望的火種。", "0", "0", "0", "0", "0", "cv_chilyarisa_sp_37", "0", "0"},
[440436] = {440436, 14004, 38, 30, "0", "0", "是要補充作戰人員嗎？", "0", "0", "0", "0", "0", "cv_chilyarisa_sp_38", "0", "0"},
[440437] = {440437, 14004, 39, 31, "0", "0", "從實戰角度挑選裝備吧。", "0", "0", "0", "0", "0", "cv_chilyarisa_sp_39", "0", "0"},
[440438] = {440438, 14004, 40, 32, "0", "0", "有什麼需要的嗎？", "0", "0", "0", "0", "0", "cv_chilyarisa_sp_40", "0", "0"},
[440439] = {440439, 14004, 41, 33, "0", "0", "你真是一點也沒變啊。", "0", "0", "0", "0", "0", "cv_chilyarisa_sp_41", "0", "0"},
[440440] = {440440, 14004, 42, 34, "0", "0", "要變更設置嗎？", "0", "0", "0", "0", "0", "cv_chilyarisa_sp_42", "0", "0"},
[440441] = {440441, 14004, 43, 35, "0", "0", "多留意重要信息。", "0", "0", "0", "0", "0", "cv_chilyarisa_sp_43", "0", "0"},
[440442] = {440442, 14004, 44, 36, "0", "0", "要珍惜與人交流的機會啊。", "0", "0", "0", "0", "0", "cv_chilyarisa_sp_44", "0", "0"},
[440443] = {440443, 14004, 45, 37, "0", "0", "嗯？", "0", "0", "0", "0", "0", "cv_chilyarisa_sp_45", "0", "0"},
[900000] = {900000, 90000, 1, 1, "0", "0", "蒼霧殘響~", "蒼霧殘響（ハツリバーブ）~", "0", "0", "蒼霧殘響~", "0", "cv_jiya_1", "0", "0"},
[900001] = {900001, 90000, 2, 2, "0", "3", "啊哇哇，不知道能不能做好啊……", "わっ……ちゃんとやれるかな……", "0", "0", "啊哇哇，不知道能不能做好啊……", "0", "cv_jiya_4", "0", "0"},
[900002] = {900002, 90000, 4, 4, "0_0_0_0.1", "6", "比起給予萬物生命但卻令人無法直視的太陽，我更加喜歡維繫著規則但卻更加柔和的月亮。", "お日さまは皆は萬物に命を與えてくれるけど、直視できない。私は柔らかい光のお月さまの方が好き。", "0", "0", "比起給予萬物生命但卻令人無法直視的太陽，我更加喜歡維繫著規則但卻更加柔和的月亮。", "0", "cv_jiya_7", "0", "0"},
[900003] = {900003, 90000, 5, 4, "0_0_0_0.1", "7", "等戰爭結束，我想親自去海邊看一看。然後…如果我的病能痊癒的話，吉雅想自己在海邊開一間花店。", "戦爭が終わったら、海に行ってみたい。あと……もし病気が治ったら、海沿いでお花屋さんをやりたい。", "0", "0", "等戰爭結束，我想親自去海邊看一看。然後…如果我的病能痊癒的話，吉雅想自己在海邊開一間花店。", "0", "cv_jiya_8", "0", "0"},
[900004] = {900004, 90000, 6, 4, "0_0_0_0.1", "8", "如果我也能夠幫上哥哥的忙就好了……", "私がお兄ちゃんの力になれればいいのに……", "0", "0", "如果我也能夠幫上哥哥的忙就好了……", "0", "cv_jiya_9", "0", "0"},
[900005] = {900005, 90000, 46, 4, "0_0_0_0.1", "9", "如果能快點當上情報官的話，就能幫上哥哥了吧。好！趁著還有力氣，今天也要打起精神努力學習喔！", "早く情報官になれば、お兄ちゃんの力になれるよね。よし。まだまだいける気がするし…、今日も頑張って勉強する！", "0", "0", "如果能快點當上情報官的話，就能幫上哥哥了吧。好！趁著還有力氣，今天也要打起精神努力學習哦！", "0", "cv_jiya_10", "0", "0"},
[900006] = {900006, 90000, 47, 4, "0_0_0_0.1", "10", "寂寞？沒關係，因為每天都能和哥哥視頻所以也不算太寂寞。當然，如果哥哥能早點回來那就更好了。多洛莉絲小姐教會了我很多新的料理，就等您回來檢驗成果了。", "寂しいかって……？私は大丈夫だよ。だって、毎日お兄ちゃんとテレビ電話できるし、寂しくないよ。…でもお兄ちゃんがもうちょっと早く帰ってきてくれればうれしいなぁって。ドロリィスさんに沢山の新しい料理を教えてもらったから、その成果を見せてあげたいの。", "0", "0", "寂寞？沒關係，因為每天都能和哥哥視頻所以也不算太寂寞。當然，如果哥哥能早點回來那就更好了。多洛莉絲小姐教會了我很多新的料理，就等您回來檢驗成果了。", "0", "cv_jiya_11", "0", "0"},
[900007] = {900007, 90000, 48, 4, "0_0_0_0.1", "11", "沒想到會被破格提升成情報官啊……雖然能幫上哥哥的忙很開心，但是如果我有做得不好的地方還請哥哥一定要指出……畢竟我不能再在工作上給您添麻煩了。", "まさか情報官に抜擢されるなんて、思ってもみなかった……やっとお兄ちゃんの力になれるし、嬉しいけど……何か駄目なところがあったら言ってね、お兄ちゃん……これ以上お仕事で…お兄ちゃんに、迷惑かけるわけにはいかないから。", "0", "0", "沒想到會被破格提升成情報官啊……雖然能幫上哥哥的忙很開心，但是如果我有做得不好的地方還請哥哥一定要指出……畢竟我不能再在工作上給您添麻煩了。", "0", "cv_jiya_12", "0", "0"},
[900008] = {900008, 90000, 49, 5, "1_》_0_0.3", "12", "呼呼呼，哥哥你總是這麼溫柔啊……哪怕哥哥不摸我的頭，只是陪在我身邊我就很幸福了。", "うふふ。お兄ちゃんっていつも優しいね……頭をぽんぽんしてくれるのも嬉しいけど、本當はそばにいてくれるだけで幸せなんだよ。", "0", "0", "呼呼呼，哥哥你總是這麼溫柔啊……哪怕哥哥不摸我的頭，只是陪在我身邊我就很幸福了。", "0", "cv_jiya_13", "0", "0"},
[900009] = {900009, 90000, 50, 5, "1_》_0_0.3", "13", "哇呼——哥哥……不對…領…領航，這麼多都在看著我們……我還是用輪椅吧……但是…像這樣被您抱著的感覺並不討厭……", "えっ――お兄ちゃん……あっ、えっと、ナ……ナビゲーター、みんな見ているから……私、やっぱり車椅子で……うう。……でも、こうやって抱き上げられるのは、本當は嫌じゃないかも……", "0", "0", "哇呼——哥哥……不對…領…領航，這麼多都在看著我們……我還是用輪椅吧……但是…像這樣被您抱著的感覺並不討厭……", "0", "cv_jiya_14", "0", "0"},
[900010] = {900010, 90000, 51, 5, "1_》_0_0.2", "14", "在，吉雅可沒有偷懶喔，哼哼~", "ちゃんといるよ、サボったりしてないよ。ふふ。", "0", "0", "在，吉雅可沒有偷懶哦，哼哼~", "0", "cv_jiya_15", "0", "0"},
[900011] = {900011, 90000, 52, 5, "1_》_0_0.2", "15", "“想要被認同…想要和其他人一樣……被媽媽認同……”哥哥，我最近總是聽到這樣的聲音在耳邊迴響，到底是誰呢？", "「認めてもらいたい……他の人みたいに……母さんに認めてもらいたい……」お兄ちゃん、最近ね、いつもこんな聲が聞こえてくるんだけど……。一體誰だろう……？", "0", "0", "“想要被認同…想要和其他人一樣……被媽媽認同……”哥哥，我最近總是聽到這樣的聲音在耳邊迴響，到底是誰呢？", "0", "cv_jiya_16", "0", "0"},
[900012] = {900012, 90000, 53, 5, "1_》_0_0.2", "16", "“將一切都捨棄掉之後……就能心無旁騖地進食了，只要進食得足夠多，馬上就能回到母親身邊了……。”哥哥，好像又有新的聲音出現了！這是……", "「全部捨てたら……遠慮なく食べられるようになる。沢山食べれば、すぐに母さんの所に帰れる……。」お兄ちゃん、また新しい聲が……！これって……", "0", "0", "“將一切都捨棄掉之後……就能心無旁騖地進食了，只要進食得足夠多，馬上就能回到母親身邊了……。”哥哥，好像又有新的聲音出現了！這是……", "0", "cv_jiya_17", "0", "0"},
[900013] = {900013, 90000, 34, 26, "0", "1", "哥哥，歡迎回來~", "お兄ちゃん、お帰り…。", "0", "0", "哥哥，歡迎回來~", "0", "cv_jiya_2", "0", "0"},
[900014] = {900014, 90000, 54, 26, "0", "2", "歡迎回來，領航，今天也一起努力吧。", "お帰り、ナビゲーター。今日も一緒に頑張ろうね。", "0", "0", "歡迎回來，領航，今天也一起努力吧。", "0", "cv_jiya_3", "0", "0"},
[900015] = {900015, 90000, 35, 27, "0", "17", "繼續我們的故事吧。", "私たちの物語を続けよう。", "0", "0", "繼續我們的故事吧。", "0", "cv_jiya_18", "0", "0"},
