[9000702] = {9000702, 90007, 98, 0, "0", "tiaopi", "呼呼呼，如果被姐姐看到我在這裏偷懶估計又會惹她生氣了吧。", "0", "0", "0", "0", "0", "shop_jing_3", "0", "0"},
[9000703] = {9000703, 90007, 97, 0, "0", "idle", "一直保持這個姿勢好累啊……麻煩可以把我給換下去嗎？", "0", "0", "0", "0", "0", "shop_jing_4", "0", "0"},
[9000704] = {9000704, 90007, 98, 0, "0", "tushe", "夢想是創造出讓懶人和廢材能夠快樂生活的世界！當然，這只是夢想而已，真正落實起來還是交給姐姐吧~", "0", "0", "0", "0", "0", "shop_jing_5", "0", "0"},
[9000800] = {9000800, 90008, 2, 0, "0", "idle", "已經到了這個時間了？那就敬請七天後的“show time”吧。", "0", "0", "0", "0", "0", "side1_starry_001", "0", "0"},
[9000801] = {9000801, 90008, 2, 0, "0", "kaixin", "哼哼哼~現在是第二天~之後會發生什麼呢？真期待啊。", "0", "0", "0", "0", "0", "side1_starry_002", "0", "0"},
[9000802] = {9000802, 90008, 2, 0, "0", "kaixin", "七天……比想像中要長呢，現在才第三天呀。", "0", "0", "0", "0", "0", "side1_starry_003", "0", "0"},
[9000803] = {9000803, 90008, 2, 0, "0", "idle2", "才過去四天嗎？我還以為四年了呢。", "0", "0", "0", "0", "0", "side1_starry_004", "0", "0"},
[9000804] = {9000804, 90008, 2, 0, "0", "kaixin", "還沒好嗎？誒——我的耐心都快被消磨殆盡啦。", "0", "0", "0", "0", "0", "side1_starry_005", "0", "0"},
[9000805] = {9000805, 90008, 2, 0, "0", "idle2", "忍耐，我要忍耐，可不能失態了，後天可是很重要的日子。", "0", "0", "0", "0", "0", "side1_starry_006", "0", "0"},
[9000806] = {9000806, 90008, 2, 0, "0", "kaixin", "明天就要出發啦，得早點睡才行……不然就要興奮得睡不著了！", "0", "0", "0", "0", "0", "side1_starry_007", "0", "0"},
[9000807] = {9000807, 90008, 97, 0, "0", "idle", "以前訓練的時候，有過好幾次中途就解除巨大化的經歷，現在想起來可真是尷尬啊……", "0", "0", "0", "0", "0", "side1_starry_008", "0", "0"},
[9000808] = {9000808, 90008, 97, 0, "0", "kaixin", "感覺之後盡是些麻煩事……算啦，船到橋頭自然，總會有辦法的。", "0", "0", "0", "0", "0", "side1_starry_009", "0", "0"},
[9000809] = {9000809, 90008, 97, 0, "0", "kaixin", "洛根市有我重要的回憶，現在只有我還記得它，所以只能讓我去保護它啦。", "0", "0", "0", "0", "0", "side1_starry_010", "0", "0"},
[9000810] = {9000810, 90008, 97, 0, "0", "idle2", "對了，我最近在想巨大化時要說的台詞……你有什麼好點子嗎？", "0", "0", "0", "0", "0", "side1_starry_011", "0", "0"},
[9000811] = {9000811, 90008, 98, 0, "0", "kaixin", "這東西是我老師的得意作品，雖然還有缺陷，但對駕駛員來說是劃時代的傑作哦。", "0", "0", "0", "0", "0", "side1_starry_012", "0", "0"},
[9000812] = {9000812, 90008, 98, 0, "0", "idle2", "“星變”真是個不錯的名字，雖然是隨便取的，但是我很中意。", "0", "0", "0", "0", "0", "side1_starry_013", "0", "0"},
[9000900] = {9000900, 90009, 97, 0, "0", "jixiao", "誒——這裡還有這種玩意啊。真不錯啊，快點上癮變成廢人吧。", "0", "0", "0", "0", "0", "side1_qianqiu_1", "0", "0"},
[9000901] = {9000901, 90009, 97, 0, "0", "laugh", "放縱地玩吧，要是你成了扭蛋廢人，我會負責把你解決掉的，哈哈哈~", "0", "0", "0", "0", "0", "side1_qianqiu_2", "0", "0"},
[9000902] = {9000902, 90009, 98, 0, "0", "lenku", "喔，這機器還真是什麼都有啊。", "0", "0", "0", "0", "0", "side1_qianqiu_3", "0", "0"},
[9000903] = {9000903, 90009, 97, 0, "0", "weixiao", "……讓我吃驚了，這台扭蛋機難道是某種方便的二十二世紀料理道具嗎？", "0", "0", "0", "0", "0", "side1_qianqiu_4", "0", "0"},
[9000904] = {9000904, 90009, 98, 0, "0", "haixiu", "呃……啊……這……快把它交出來，看不出來我很想要嗎，笨蛋！", "0", "0", "0", "0", "0", "side1_qianqiu_5", "0", "0"},
[9001000] = {9001000, 90010, 97, 0, "0", "haixiu2", "領航……太沉迷是不好的，姐姐說過，這台機器會讓人玩物喪志的。", "0", "0", "0", "0", "0", "side1_libeika_1", "0", "0"},
[9001001] = {9001001, 90010, 97, 0, "0", "kaixin", "領航真辛苦……我幫不上什麼忙，只能在這裡為你工作順利做祈禱了。", "0", "0", "0", "0", "0", "side1_libeika_2", "0", "0"},
[9001002] = {9001002, 90010, 98, 0, "0", "qianxiao", "聽說每一個玩扭蛋機的人都有個一發中大獎的夢想……領航也是嗎？", "0", "0", "0", "0", "0", "side1_libeika_3", "0", "0"},
[9001003] = {9001003, 90010, 97, 0, "0", "haixiu", "那個……領航有想好要把抽到的獎品給誰嗎？如果沒想好的話，可以……可以找我諮詢哦。", "0", "0", "0", "0", "0", "side1_libeika_4", "0", "0"},
[9001004] = {9001004, 90010, 98, 0, "0", "kaixin", "雖然不知道未來會發生什麼……但只要姐姐和領航在身邊，我就什麼都不怕了！", "0", "0", "0", "0", "0", "side1_libeika_5", "0", "0"},
[9001005] = {9001005, 90010, 97, 0, "0", "kaixin", "呼啦啦~轉轉轉!", "0", "0", "0", "0", "0", "side1_libeika_6", "0", "0"},
[9001006] = {9001006, 90010, 98, 0, "0", "qidao", "呼……我沒有偷懶，只是……有點困……呼……", "0", "0", "0", "0", "0", "side1_libeika_7", "0", "0"},
[9001007] = {9001007, 90010, 98, 0, "0", "kaixin", "獎品快點來~", "0", "0", "0", "0", "0", "side1_libeika_8", "0", "0"},
[9001100] = {9001100, 90011, 97, 0, "0", "shiluo", "嗯？你來了？清單上是要做的事情……給你添麻煩了，抱歉。", "0", "0", "0", "0", "0", "side1_laiwei_1", "0", "0"},
[9001101] = {9001101, 90011, 97, 0, "0", "qianxiao", "你願意幫忙我是很感謝……不過別把自己累到了，你的身體很寶貴的吧？", "0", "0", "0", "0", "0", "side1_laiwei_2", "0", "0"},
[9001102] = {9001102, 90011, 98, 0, "0", "shiluo", "我們給這座城市添了太多不必要的麻煩……能有機會彌補的話，那就再好不過了。", "0", "0", "0", "0", "0", "side1_laiwei_3", "0", "0"},
[9001103] = {9001103, 90011, 97, 0, "0", "qianxiao", "不知道我能不能適應方舟上的生活……算了，用星爍的話，“總會有辦法的。”", "0", "0", "0", "0", "0", "side1_laiwei_4", "0", "0"},
[9001104] = {9001104, 90011, 98, 0, "0", "kaixin", "人與人之間該如何建立信賴的關係……我不明白，我很難再相信其他人了……不過，我想相信你，我願意相信你，領航。", "0", "0", "0", "0", "0", "side1_laiwei_5", "0", "0"},
[9001105] = {9001105, 90011, 98, 0, "0", "kaixin", "噢，幹得漂亮。", "0", "0", "0", "0", "0", "side1_laiwei_6", "0", "0"},
[9001106] = {9001106, 90011, 97, 0, "0", "qianxiao", "你做得比我預計的更出色。", "0", "0", "0", "0", "0", "side1_laiwei_7", "0", "0"},
[9001107] = {9001107, 90011, 98, 0, "0", "kaixin", "對你來說，這些事算不上什麼難題吧？我和黎貝卡可能更棘手一些。", "0", "0", "0", "0", "0", "side1_laiwei_8", "0", "0"},
[9001200] = {9001200, 90012, 97, 0, "0", "smile", "領航，我要出門去採購些物資,要一起來嗎？今晚我打算給大家做燉牛肉喔。", "0", "0", "0", "0", "0", "shop_lidiya_1", "0", "0"},
[9001201] = {9001201, 90012, 97, 0, "0", "rage", "我也有生氣的時候喔。", "0", "0", "0", "0", "0", "shop_lidiya_2", "0", "0"},
[9001202] = {9001202, 90012, 97, 0, "0", "smile", "無論是什麼事情，大姐姐都會幫你解決的。", "0", "0", "0", "0", "0", "shop_lidiya_3", "0", "0"},
[9001203] = {9001203, 90012, 98, 0, "0", "idle", "下次送你一批卡佳的裝備吧。", "0", "0", "0", "0", "0", "shop_lidiya_4", "0", "0"},
[9001204] = {9001204, 90012, 98, 0, "0", "sad", "真是麻煩你了，你應該不會嫌棄姐姐吧？", "0", "0", "0", "0", "0", "shop_lidiya_5", "0", "0"},
[9001300] = {9001300, 90013, 97, 0, "0", "nanshou", "做這種乏味的工作……我也許會精神渙散而不小心踩到建築哦。", "0", "0", "0", "0", "0", "shop_yanyanluo_1", "0", "0"},
[9001301] = {9001301, 90013, 97, 0, "0", "happy", "伽藍見又打算在圖書館裏泡一整天吧，該為今晚如何捉弄她想個新點子了。", "0", "0", "0", "0", "0", "shop_yanyanluo_2", "0", "0"},
[9001302] = {9001302, 90013, 97, 0, "0", "yihuo", "這種地方可沒有按鈕，再怎麼按也不會發射魚雷的。", "0", "0", "0", "0", "0", "shop_yanyanluo_3", "0", "0"},
[9001303] = {9001303, 90013, 98, 0, "0", "smile", "還是在海底神殿找到的寶藏更適合我。", "0", "0", "0", "0", "0", "shop_yanyanluo_4", "0", "0"},
[9001304] = {9001304, 90013, 98, 0, "0", "dong", "人的欲望比海還深呢。", "0", "0", "0", "0", "0", "shop_yanyanluo_5", "0", "0"},
[9001400] = {9001400, 90014, 97, 0, "0", "smile", "咦，這裡怎麼會有禮物盒，最近是有什麼節日嗎？", "0", "0", "0", "0", "0", "bzn_yr_dlls_1", "0", "0"},
[9001401] = {9001401, 90014, 97, 0, "0", "smile", "是哪幾位博士準備的禮物？", "0", "0", "0", "0", "0", "bzn_yr_dlls_2", "0", "0"},
[9001402] = {9001402, 90014, 97, 0, "0", "sad", "竟然是那三位博士……我們還是不要打開比較好……", "0", "0", "0", "0", "0", "bzn_yr_dlls_3", "0", "0"},
[9001403] = {9001403, 90014, 97, 0, "0", "rage", "誒？這是什麼？“特別紀念禮物箱，請自取。”哦，竟然是巧克力布丁——我剛好想要吃甜品。", "0", "0", "0", "0", "0", "bzn_yr_jsjh_1", "0", "0"},
[9001404] = {9001404, 90014, 97, 0, "0", "idle", "安排妥當了，目前已經有九十個樣本。", "0", "0", "0", "0", "0", "bzn_yr_klsdn_1", "0", "0"},
[9001500] = {9001500, 90015, 97, 0, "0", "idle", "歡迎光顧，這裡是只為你開張的秘密小店。", "0", "0", "0", "0", "0", "bzn_shop_jsjh_3", "0", "0"},
[9001501] = {9001501, 90015, 97, 0, "0", "shy", "希望我和領航的感情，在日積月累的相處之後也能產生好聞的味道。", "0", "0", "0", "0", "0", "bzn_shop_jsjh_4", "0", "0"},
[9001502] = {9001502, 90015, 97, 0, "0", "smile", "在外面的時候要注意安全。", "0", "0", "0", "0", "0", "bzn_shop_jsjh_5", "0", "0"},
[9001503] = {9001503, 90015, 97, 0, "0", "smile2", "“未來”會變成什麼樣呢，現在就連我也不知道了，不過對我來說這也算是一種好事吧。", "0", "0", "0", "0", "0", "bzn_shop_jsjh_6", "0", "0"},
[9001504] = {9001504, 90015, 97, 0, "0", "wink", "好期待只有我們兩人的時間，在事情結束之後你會留時間給我的吧？", "0", "0", "0", "0", "0", "bzn_shop_jsjh_7", "0", "0"},
[9001505] = {9001505, 90015, 98, 0, "0", "yabee", "恭喜這位中獎的親愛的，請留下你的房間號，今天晚上會有神秘禮物寄給你。", "0", "0", "0", "0", "0", "bzn_shop_jsjh_8", "0", "0"},
[9001506] = {9001506, 90015, 98, 0, "0", "smile", "交易達成，錢貨兩清，但是人與人的感情可不是這樣的。", "0", "0", "0", "0", "0", "bzn_shop_jsjh_9", "0", "0"},
[9001507] = {9001507, 90015, 98, 0, "0", "smile2", "好~~這是你要的東西，要送到哪裡~？", "0", "0", "0", "0", "0", "bzn_shop_jsjh_10", "0", "0"},
[9001600] = {9001600, 90016, 97, 0, "0", "biyan", "我接下來還有實驗，讓我們快點解決吧？", "0", "0", "0", "0", "0", "bzn_mission_klsdn_2", "0", "0"},
[9001601] = {9001601, 90016, 97, 0, "0", "idle", "仔細觀察這些資料吧，對於你接下來的行動會有幫助的，相信我的判斷吧。", "0", "0", "0", "0", "0", "bzn_mission_klsdn_3", "0", "0"},
[9001602] = {9001602, 90016, 97, 0, "0", "laugh", "通過歲月的努力達成目標，任何事情都是這樣。", "0", "0", "0", "0", "0", "bzn_mission_klsdn_4", "0", "0"},
[9001603] = {9001603, 90016, 97, 0, "0", "smile", "勞累的時候我會去睡兩個小時，說不定就能有不可思議的靈感產生。", "0", "0", "0", "0", "0", "bzn_mission_klsdn_5", "0", "0"},
[9001604] = {9001604, 90016, 98, 0, "0", "smile", "實驗報告完成了嗎？嗯做得很好，這是給你的獎勵。", "0", "0", "0", "0", "0", "bzn_mission_klsdn_6", "0", "0"},
[9001605] = {9001605, 90016, 98, 0, "0", "biyan", "下一階段的計畫準備好了嗎？", "0", "0", "0", "0", "0", "bzn_mission_klsdn_7", "0", "0"},
[9001700] = {9001700, 90017, 97, 0, "0", "haixiu2", "“去擊碎天上墜落的星辰。”，約定好的這件事我一定會做到的。", "0", "0", "0", "0", "0", "bzn_neizhi_dlls_4", "0", "0"},
[9001701] = {9001701, 90017, 97, 0, "0", "kaixin", "我一刻也不曾忘記那份心情。", "0", "0", "0", "0", "0", "bzn_neizhi_dlls_5", "0", "0"},
[9001702] = {9001702, 90017, 97, 0, "0", "qianxiao", "帶著大家的希望前進這件事情，對我而言並不是一種負擔。", "0", "0", "0", "0", "0", "bzn_neizhi_dlls_6", "0", "0"},
[9001703] = {9001703, 90017, 97, 0, "0", "haixiu", "我已經做好了覺悟，我——不接受我的宿命！", "0", "0", "0", "0", "0", "bzn_neizhi_dlls_7", "0", "0"},
[9001704] = {9001704, 90017, 97, 0, "0", "kaixin", "讓我們開始吧，加油！", "0", "0", "0", "0", "0", "bzn_neizhi_dlls_8", "0", "0"},
[9001705] = {9001705, 90017, 97, 0, "0", "kaixin", "第743次訓練——開始。", "0", "0", "0", "0", "0", "bzn_neizhi_dlls_9", "0", "0"},
[9001706] = {9001706, 90017, 98, 0, "0", "qidao", "大成功了，完美擊碎了，領航，你看到了？", "0", "0", "0", "0", "0", "bzn_neizhi_dlls_10", "0", "0"},
[9001707] = {9001707, 90017, 98, 0, "0", "kaixin", "目標達成了，擊墜成功！但是，我覺得還可以做得更好，請領航繼續訓練我。", "0", "0", "0", "0", "0", "bzn_neizhi_dlls_11", "0", "0"},
[9001708] = {9001708, 90017, 98, 0, "0", "kaixin", "再來吧，只是一次失敗而已。", "0", "0", "0", "0", "0", "bzn_neizhi_dlls_12", "0", "0"},
[9001800] = {9001800, 90018, 97, 0, "0", "say", "休息也是備戰的一環。你很懂嘛。", "0", "0", "0", "0", "0", "shop_zhinvxing_1", "0", "0"},
[9001801] = {9001801, 90018, 97, 0, "0", "shame", "喲，又見面了。今天你的眼神也很不錯，能看到一名戰士該有的堅韌。", "0", "0", "0", "0", "0", "shop_zhinvxing_2", "0", "0"},
[9001802] = {9001802, 90018, 97, 0, "0", "idle", "又是公事？你可真是有夠忙的。", "0", "0", "0", "0", "0", "shop_zhinvxing_3", "0", "0"},
[9001803] = {9001803, 90018, 98, 0, "0", "shame", "設備升級？費用還是你來出？多瑙這邊的駕駛員待遇也太好了吧？！", "0", "0", "0", "0", "0", "shop_zhinvxing_4", "0", "0"},
[9001804] = {9001804, 90018, 98, 0, "0", "say", "不愧是艾吉斯，員工價的折扣就是大。", "0", "0", "0", "0", "0", "shop_zhinvxing_5", "0", "0"},
[9001900] = {9001900, 90019, 97, 0, "0", "smile", "歡迎光臨，要是看上什麼就直接拿走吧……當然，不是免費的。", "0", "0", "0", "0", "0", "side2_heli_1", "0", "0"},
[9001901] = {9001901, 90019, 97, 0, "0", "deyi", "工作的時候就會想著休息，休息久了就會想著適當工作也不錯，大家都是這樣吧？", "0", "0", "0", "0", "0", "side2_heli_2", "0", "0"},
[9001902] = {9001902, 90019, 97, 0, "0", "shame", "如果不知道買什麼的話，就把錢直接給我吧，我很需要它。", "0", "0", "0", "0", "0", "side2_heli_3", "0", "0"},
[9001903] = {9001903, 90019, 97, 0, "0", "yansu", "消費欲就像是卡在咽喉的菜絲，只有扯出來的時候才發現它的長度比想像中要多得多。", "0", "0", "0", "0", "0", "side2_heli_4", "0", "0"},
[9001904] = {9001904, 90019, 97, 0, "0", "sad", "工作是為了掙錢，掙錢是為了更好的活著，但是人一旦開始工作就成了美好生活的絕緣體……真是矛盾啊。", "0", "0", "0", "0", "0", "side2_heli_5", "0", "0"},
[9001905] = {9001905, 90019, 98, 0, "0", "smile", "謝謝惠顧，歡迎下次再來！", "0", "0", "0", "0", "0", "side2_heli_6", "0", "0"},
[9001906] = {9001906, 90019, 98, 0, "0", "deyi", "物質需求和精神需求，只要商品滿足了其中一點，就請毫不猶豫地消費吧。", "0", "0", "0", "0", "0", "side2_heli_7", "0", "0"},
[9001907] = {9001907, 90019, 98, 0, "0", "yansu", "錢如果不在需要的時候花掉，那它就沒有意義了。", "0", "0", "0", "0", "0", "side2_heli_8", "0", "0"},
[9002000] = {9002000, 90020, 97, 0, "0", "tanqi", "史蒂芬妮博士……有人知道她是哪個領域的博士嗎？也許是在使喚人方面有特殊才能的博士。", "0", "0", "0", "0", "0", "side2_luoji_1", "0", "0"},
[9002001] = {9002001, 90020, 97, 0, "0", "sad", "我聽說了，給一條巨蛇取名為“耶夢加得”，給一條鱷魚取名為“索貝克”，是她的話，也不是什麼會讓人驚訝的事情。", "0", "0", "0", "0", "0", "side2_luoji_2", "0", "0"},
[9002002] = {9002002, 90020, 97, 0, "0", "smile", "虛偽的人在說話時往往會標榜自己的正義，每句話都在讚揚自己優秀品格的人更是不值得信任，這一點你感同身受嗎？", "0", "0", "0", "0", "0", "side2_luoji_3", "0", "0"},
[9002003] = {9002003, 90020, 97, 0, "0", "smile", "用希望和夢想蠱惑人跌入深淵的人，在我看來是和原罪有著等同之罪的“惡”。", "0", "0", "0", "0", "0", "side2_luoji_4", "0", "0"},
[9002004] = {9002004, 90020, 98, 0, "0", "tanqi", "幹得不錯，要是每個人都有像你這樣的效率，可能世界也不會變成這副破爛的模樣了。", "0", "0", "0", "0", "0", "side2_luoji_5", "0", "0"},
[9002005] = {9002005, 90020, 98, 0, "0", "smile", "你是奔著獎勵而來的？很好，這才是正確的工作態度。", "0", "0", "0", "0", "0", "side2_luoji_6", "0", "0"},
[9002006] = {9002006, 90020, 98, 0, "0", "sad", "責任感和使命感是連一元早餐都不如的廉價物，真金白銀的獎勵才是我們該追求的東西。", "0", "0", "0", "0", "0", "side2_luoji_7", "0", "0"},
[9002100] = {9002100, 90021, 97, 0, "0", "idle", "在這裡的吾……掌握了全世界的金錢流動，是當之無愧的金錢女王呢。", "0", "0", "0", "0", "0", "vd_shop_sikadi_2", "0", "0"},
[9002101] = {9002101, 90021, 97, 0, "0", "xiao4", "在這裡的吾……掌握了全世界的金錢流動，是當之無愧的金錢女王呢。", "0", "0", "0", "0", "0", "vd_shop_sikadi_2", "0", "0"},
[9002102] = {9002102, 90021, 97, 0, "0", "xiao3", "買定離手，願賭服輸……吾只是想說這句話，吾店裡的東西可都是一分錢一分貨的哦！", "0", "0", "0", "0", "0", "vd_shop_sikadi_8", "0", "0"},
