[9002105] = {9002105, 90021, 98, 0, "0", "ganga", "在這裡的吾……掌握了全世界的金錢流動，是當之無愧的金錢女王呢。", "0", "0", "0", "0", "0", "vd_shop_sikadi_2", "0", "0"},
