[9002200] = {9002200, 90022, 97, 0, "0", "smile", "……這次是我們出場的話，難道說，我們是主人公？", "0", "0", "0", "0", "0", "0", "0", "0"},
[9002201] = {9002201, 90022, 97, 0, "0", "smile", "我們隊伍到底有幾個人？", "0", "0", "0", "0", "0", "0", "0", "0"},
[9002202] = {9002202, 90022, 97, 0, "0", "sad", "天氣好的時候就會想要躺在地上曬太陽，大家都是這樣吧？", "0", "0", "0", "0", "0", "0", "0", "0"},
[9002203] = {9002203, 90022, 97, 0, "0", "rage", "說起來，方舟附近會有原罪出現嗎？", "0", "0", "0", "0", "0", "0", "0", "0"},
[9002204] = {9002204, 90022, 97, 0, "0", "idle", "我還以為我這次不會出場了。", "0", "0", "0", "0", "0", "0", "0", "0"},
[9002205] = {9002205, 90022, 97, 0, "0", "smile", "也可能是給主人公當墊腳石的炮灰噢？", "0", "0", "0", "0", "0", "0", "0", "0"},
[9002206] = {9002206, 90022, 97, 0, "0", "smile", "說是有四個人，但搞不好只有羅莎你一個人誒。", "0", "0", "0", "0", "0", "0", "0", "0"},
[9002207] = {9002207, 90022, 97, 0, "0", "sad", "不，只有你會這麼做。", "0", "0", "0", "0", "0", "0", "0", "0"},
[9002208] = {9002208, 90022, 97, 0, "0", "rage", "如果有的話，感覺就像是被投放到敵人大本營的炮灰一樣。", "0", "0", "0", "0", "0", "0", "0", "0"},
[9002209] = {9002209, 90022, 97, 0, "0", "idle", "你是哪位……？", "0", "0", "0", "0", "0", "0", "0", "0"},
[9002300] = {9002300, 90023, 97, 0, "0", "idle", "感謝領航前來協助調查任務，請收下這邊準備的禮物吧~", "0", "0", "0", "0", "0", "0", "0", "0"},
[9002301] = {9002301, 90023, 97, 0, "0", "idle", "聖女梅莉雅也向你致以謝意~", "0", "0", "0", "0", "0", "0", "0", "0"},
[9002302] = {9002302, 90023, 97, 0, "0", "idle", "今天還有工作？我的“乖乖能量”都已經用完了。", "0", "0", "0", "0", "0", "0", "0", "0"},
[9002303] = {9002303, 90023, 97, 0, "0", "idle", "這才第二天而已，你的能量用得也太快了吧……", "0", "0", "0", "0", "0", "0", "0", "0"},
[9002304] = {9002304, 90023, 97, 0, "0", "idle", "我說，既然每天的三個禮物都剩兩個，與其浪費還不如歸我們呢。", "0", "0", "0", "0", "0", "0", "0", "0"},
[9002305] = {9002305, 90023, 97, 0, "0", "idle", "你還挺節儉的嘛，可惜，不~行~", "0", "0", "0", "0", "0", "0", "0", "0"},
[9002306] = {9002306, 90023, 97, 0, "0", "idle", "珂斯嘉德，今天沒有事要忙嗎？", "0", "0", "0", "0", "0", "0", "0", "0"},
[9002307] = {9002307, 90023, 97, 0, "0", "idle", "想著至少得抽空來一趟，總不能完全甩手不管。", "0", "0", "0", "0", "0", "0", "0", "0"},
[9002308] = {9002308, 90023, 97, 0, "0", "idle", "你還真是敬業啊，明明拿不到什麼好處。", "0", "0", "0", "0", "0", "0", "0", "0"},
[9002309] = {9002309, 90023, 97, 0, "0", "idle", "這也只是因心而異，對我來說，能會見這位領航就已經值得了。", "0", "0", "0", "0", "0", "0", "0", "0"},
[9002400] = {9002400, 90024, 97, 0, "0", "idle", "歡迎光顧梅莉雅的秘密市場，這裡的商品均無法追查來源，請放心購買~", "0", "0", "0", "0", "0", "1ST_meiliya_1", "0", "0"},
[9002401] = {9002401, 90024, 97, 0, "0", "xianqi", "即使和我套近乎，也不會給你更多福利的哦。", "0", "0", "0", "0", "0", "1ST_meiliya_2", "0", "0"},
[9002402] = {9002402, 90024, 97, 0, "0", "idle", "請務必看管好自己的財物，若有遺失，本店概不負責。", "0", "0", "0", "0", "0", "1ST_meiliya_3", "0", "0"},
[9002403] = {9002403, 90024, 97, 0, "0", "bushuang", "在我眼皮子底下還敢做這種小偷小摸的動作，真有勇氣啊。", "0", "0", "0", "0", "0", "1ST_meiliya_4", "0", "0"},
[9002404] = {9002404, 90024, 97, 0, "0", "zhuangsha", "還在猶豫嗎？立刻購買的話，本聖女就將贈送免費祈福一次~", "0", "0", "0", "0", "0", "1ST_meiliya_5", "0", "0"},
[9002405] = {9002405, 90024, 98, 0, "0", "deyi", "感謝購買~不愧是領航，眼光真不錯。", "0", "0", "0", "0", "0", "1ST_meiliya_6", "0", "0"},
[9002406] = {9002406, 90024, 98, 0, "0", "deyi", "祝你萬事順利。好了，購買商品所贈的祈福完成了。", "0", "0", "0", "0", "0", "1ST_meiliya_7", "0", "0"},
[9002407] = {9002407, 90024, 98, 0, "0", "zhenmianmu", "還有什麼想要的貨我都可以幫你弄到手哦。欸，想要我？這是非賣品！", "0", "0", "0", "0", "0", "1ST_meiliya_8", "0", "0"},
[9002500] = {9002500, 90025, 97, 0, "0", "idle", "加油吧，努力完成工作後的那頓晚飯總是會更香呢~", "0", "0", "0", "0", "0", "1ST_xhixha_1", "0", "0"},
[9002501] = {9002501, 90025, 97, 0, "0", "fuza", "沒有幹勁的時候，就想像自己不是在工作，而是在打遊戲、鍛煉，或是體驗人生如何？", "0", "0", "0", "0", "0", "1ST_xhixha_2", "0", "0"},
[9002502] = {9002502, 90025, 97, 0, "0", "renzhen", "有什麼任務細節還不清楚嗎？我會耐心跟你講的哦。", "0", "0", "0", "0", "0", "1ST_xhixha_3", "0", "0"},
[9002503] = {9002503, 90025, 97, 0, "0", "fuza", "需要我協力的話就儘管開口吧~現在的我就相當於領航的秘書呢。", "0", "0", "0", "0", "0", "1ST_xhixha_4", "0", "0"},
[9002504] = {9002504, 90025, 98, 0, "0", "xiao", "恭喜恭喜，用一頓大餐好好犒勞自己吧，不太捨得的話，這次就我請客了~", "0", "0", "0", "0", "0", "1ST_xhixha_5", "0", "0"},
[9002505] = {9002505, 90025, 98, 0, "0", "xinwei", "認真是沒錯，但也別忘記勞逸結合，待會要一起去逛街、看電影放鬆下嗎？", "0", "0", "0", "0", "0", "1ST_xhixha_6", "0", "0"},
[9002506] = {9002506, 90025, 98, 0, "0", "jingya", "辛苦了，請好好享受勞動過後的滿足感、解放感，以及豐厚的物質獎勵吧。", "0", "0", "0", "0", "0", "1ST_xhixha_7", "0", "0"},
[9002600] = {9002600, 90026, 97, 0, "0", "idle", "失敗是對勝利的預演，今日是對明日的預演，所以雖是訓練，也不可輕易懈怠。", "0", "0", "0", "0", "0", "1ST_korsgaard_1", "0", "0"},
[9002601] = {9002601, 90026, 97, 0, "0", "xiao4", "我一直提醒自己，用以守護人們的不只是盾，還有劍。", "0", "0", "0", "0", "0", "1ST_korsgaard_2", "0", "0"},
[9002602] = {9002602, 90026, 97, 0, "0", "xiao3", "迷茫之時，就用酣暢淋漓的戰鬥、用滌除雜念的意志、用心靈的劍尖去指明方向吧。", "0", "0", "0", "0", "0", "1ST_korsgaard_3", "0", "0"},
[9002603] = {9002603, 90026, 97, 0, "0", "shy2", "怎麼了？不用擔心，這種程度的訓練只是日常，不會超過負荷。", "0", "0", "0", "0", "0", "1ST_korsgaard_4", "0", "0"},
[9002604] = {9002604, 90026, 98, 0, "0", "xiao2", "那麼，戰鬥開始。", "0", "0", "0", "0", "0", "1ST_korsgaard_5", "0", "0"},
[9002605] = {9002605, 90026, 98, 0, "0", "ganga", "奔湧的泉水，由每一滴汗水積攢所成。", "0", "0", "0", "0", "0", "1ST_korsgaard_6", "0", "0"},
[9002606] = {9002606, 90026, 98, 0, "0", "ganga", "多虧了你，這次的效果遠勝往常。", "0", "0", "0", "0", "0", "1ST_korsgaard_7", "0", "0"},
[9002607] = {9002607, 90026, 98, 0, "0", "ganga", "我會將訓練中的成功轉變為現實。", "0", "0", "0", "0", "0", "1ST_korsgaard_8", "0", "0"},
[9002608] = {9002608, 90026, 98, 0, "0", "ganga", "不必氣餒，握緊武器，再來一戰。", "0", "0", "0", "0", "0", "1ST_korsgaard_9", "0", "0"},
[9002700] = {9002700, 90027, 97, 0, "0", "idle", "補充些物資吧。", "0", "0", "0", "0", "0", "shop_kalian_1", "0", "0"},
[9002701] = {9002701, 90027, 97, 0, "0", "angry", "嗯？正好我有事想要請教您，可以佔有您一些時間嗎？領航。", "0", "0", "0", "0", "0", "shop_kalian_2", "0", "0"},
[9002702] = {9002702, 90027, 97, 0, "0", "sad", "這件制服很陌生？啊，這是薩哈拉為候補生們準備的學院服。", "0", "0", "0", "0", "0", "shop_kalian_3", "0", "0"},
[9002703] = {9002703, 90027, 98, 0, "0", "happy", "雖然這麼說有些自大，不過我感覺在你的幫助下，自己已經是個合格的駕駛員了呢。", "0", "0", "0", "0", "0", "shop_kalian_4", "0", "0"},
[9002704] = {9002704, 90027, 98, 0, "0", "jingya", "除了我之外應該還有其他候補生吧，如果見到她們的話還請多多關照一下。", "0", "0", "0", "0", "0", "shop_kalian_5", "0", "0"},
[9002800] = {9002800, 90028, 97, 0, "0", "idle", "噔咚——莉莉絲，吾終於把《影之國編年史2》寫完了！", "0", "0", "0", "0", "0", "XH2_countdown_1", "0", "0"},
[9002801] = {9002801, 90028, 97, 0, "0", "angry", "這次的副標題是——女主角宇宙的海濱樂園危機！我讓莉莉絲在書裏穿上了泳裝哦！", "0", "0", "0", "0", "0", "XH2_countdown_2", "0", "0"},
[9002802] = {9002802, 90028, 97, 0, "0", "sad", "咿——我、我怎麼穿著這麼不知廉恥的泳裝！", "0", "0", "0", "0", "0", "XH2_countdown_3", "0", "0"},
[9002803] = {9002803, 90028, 97, 0, "0", "happy", "王女……你不會忘記我們來海濱樂園的任務了吧？", "0", "0", "0", "0", "0", "XH2_countdown_4", "0", "0"},
[9002804] = {9002804, 90028, 97, 0, "0", "jingya", "弗蘭卡……明明在付了來這裏的船票後我們的經費已經見底了，為什麼你還有錢買泳裝！", "0", "0", "0", "0", "0", "XH2_countdown_5", "0", "0"},
[9002900] = {9002900, 90029, 97, 0, "0", "xiao2", "哼哼，變態先生要是留在這裡陪我的話，這些東西想要多少都有。", "0", "0", "0", "0", "0", "shop_weilai_1", "0", "0"},
[9002901] = {9002901, 90029, 97, 0, "0", "xiao4", "想要在我這裡購買“未來”？笨、笨蛋，這種怎麼東西怎麼可能有啊！", "0", "0", "0", "0", "0", "shop_weilai_2", "0", "0"},
[9002902] = {9002902, 90029, 97, 0, "0", "xiao2", "如果變態先生當我的男朋友，我就能向大家炫耀你了，嘿嘿……", "0", "0", "0", "0", "0", "shop_weilai_3", "0", "0"},
[9002903] = {9002903, 90029, 97, 0, "0", "xiao4", "就連未來的未來都能掌握在你的手中，不愧是變態先生，真了不起。", "0", "0", "0", "0", "0", "shop_weilai_4", "0", "0"},
[9002904] = {9002904, 90029, 97, 0, "0", "wuyu", "我與你相熟共事就連一個月都沒有，所以沒有優惠，但是你如果願意犧牲色相的話……那也不行。", "0", "0", "0", "0", "0", "shop_weilai_5", "0", "0"},
[9002905] = {9002905, 90029, 98, 0, "0", "xiao2", "要不把我也一起買走吧~誒……你那是什麼表情，我、我當然是開玩笑的！", "0", "0", "0", "0", "0", "shop_weilai_6", "0", "0"},
[9002906] = {9002906, 90029, 98, 0, "0", "xiao4", "在真理法庭的見證下，我這裡可是合法生意。", "0", "0", "0", "0", "0", "shop_weilai_7", "0", "0"},
[9002907] = {9002907, 90029, 98, 0, "0", "wuyu", "太變態了。", "0", "0", "0", "0", "0", "shop_weilai_8", "0", "0"},
[9003000] = {9003000, 90030, 97, 0, "0", "xiao2", "啊，領航……真是好久不見了呢。我可以坐你的身邊的嗎？", "0", "0", "0", "0", "0", "XH2_mission_fulanka_1", "0", "0"},
[9003001] = {9003001, 90030, 97, 0, "0", "xiao1", "我有很多話想要和領航講，等我下班了之後約個時間吧？", "0", "0", "0", "0", "0", "XH2_mission_fulanka_2", "0", "0"},
[9003002] = {9003002, 90030, 97, 0, "0", "xiao2", "就算暴露了身份而被通緝也沒關係，躲在我這裡吧，我會照顧你直到生命盡頭的。", "0", "0", "0", "0", "0", "XH2_mission_fulanka_3", "0", "0"},
[9003003] = {9003003, 90030, 97, 0, "0", "xiao1", "……雖然你離開這裡之後還會忘掉這一切，但你想聽我的故事嗎？", "0", "0", "0", "0", "0", "XH2_mission_fulanka_4", "0", "0"},
[9003004] = {9003004, 90030, 98, 0, "0", "xiao1", "任務完成了，太棒了，不愧是領航。", "0", "0", "0", "0", "0", "XH2_mission_fulanka_5", "0", "0"},
[9003005] = {9003005, 90030, 98, 0, "0", "xiao2", "之後……要來我家裡嗎？", "0", "0", "0", "0", "0", "XH2_mission_fulanka_6", "0", "0"},
[9003100] = {9003100, 90031, 97, 0, "0", "idle", "嗯……這裡是什麼地方？", "0", "0", "0", "0", "0", "XH2_game_aofeiliya_1", "0", "0"},
[9003101] = {9003101, 90031, 97, 0, "0", "idle", "這個場景……是未來會發生的事情嗎？", "0", "0", "0", "0", "0", "XH2_game_aofeiliya_2", "0", "0"},
[9003102] = {9003102, 90031, 97, 0, "0", "idle", "啊！那個長得像小未來的一樣的，圓溜溜的腦袋是什麼啊，好可愛哦。", "0", "0", "0", "0", "0", "XH2_game_aofeiliya_3", "0", "0"},
[9003103] = {9003103, 90031, 97, 0, "0", "idle", "咦咦咦咦咦咦——要用腦袋撞上去嗎！？", "0", "0", "0", "0", "0", "XH2_game_aofeiliya_4", "0", "0"},
[9003104] = {9003104, 90031, 97, 0, "0", "idle", "開始模擬……咦，是什麼意思？", "0", "0", "0", "0", "0", "XH2_game_aofeiliya_5", "0", "0"},
[9003105] = {9003105, 90031, 97, 0, "0", "idle", "難、難不成是要我撞上去嗎！？", "0", "0", "0", "0", "0", "XH2_game_aofeiliya_6", "0", "0"},
[9003106] = {9003106, 90031, 97, 0, "0", "idle", "嗚嗚……竟然真的是要我操縱奧菲莉亞號撞上……嘔……", "0", "0", "0", "0", "0", "XH2_game_aofeiliya_7", "0", "0"},
[9003107] = {9003107, 90031, 97, 0, "0", "idle", "好、好險！差一點就來不及緊急脫出了！", "0", "0", "0", "0", "0", "XH2_game_aofeiliya_8", "0", "0"},
[9003108] = {9003108, 90031, 97, 0, "0", "idle", "死、死掉了……咿——不會還要再來一次吧？", "0", "0", "0", "0", "0", "XH2_game_aofeiliya_9", "0", "0"},
[9003200] = {9003200, 90032, 97, 0, "0", "idle", "明明是第一次開店，卻沒有首次開店的特殊禮品嗎……真小氣。", "0", "0", "0", "0", "0", "mmbz_shop_saimiu_1", "0", "0"},
[9003201] = {9003201, 90032, 97, 0, "0", "idle", "在活動裡刷貨幣，然後在商店裡兌換物品，這好像已經成為了一種約定俗成的慣例——不過，最早是誰先這麼做的？", "0", "0", "0", "0", "0", "mmbz_shop_saimiu_2", "0", "0"},
[9003202] = {9003202, 90032, 97, 0, "0", "idle", "商品太少了？就算你跟我說也……對了，我們一起去跟開發人員回饋吧！", "0", "0", "0", "0", "0", "mmbz_shop_saimiu_3", "0", "0"},
[9003203] = {9003203, 90032, 97, 0, "0", "idle", "不知道我下次出場會是什麼時候呢……等下，會出場吧？會的吧？快回答我呀！", "0", "0", "0", "0", "0", "mmbz_shop_saimiu_4", "0", "0"},
[9003204] = {9003204, 90032, 97, 0, "0", "idle", "“人生從近處看是悲劇，從遠處看是喜劇”，現在的我完全理解這句話的含義了。", "0", "0", "0", "0", "0", "mmbz_shop_saimiu_5", "0", "0"},
[9003205] = {9003205, 90032, 98, 0, "0", "idle", "謝謝光臨，下次再來啊……一定要來啊！", "0", "0", "0", "0", "0", "mmbz_shop_saimiu_6", "0", "0"},
[9003206] = {9003206, 90032, 98, 0, "0", "idle", "我和你，說不定能成為最佳搭檔呢！", "0", "0", "0", "0", "0", "mmbz_shop_saimiu_7", "0", "0"},
[9003207] = {9003207, 90032, 98, 0, "0", "idle", "真遺憾……和你共演的時間只有這麼一點——下次再出場的時候，我一定會大放異彩的！", "0", "0", "0", "0", "0", "mmbz_shop_saimiu_8", "0", "0"},
[9003300] = {9003300, 90033, 97, 0, "0", "idle", "領航，您還記得我嗎？我是之前和您並肩作戰過的……駕駛員……不記得了嗎？", "0", "0", "0", "0", "0", "mmbz_mi_feilin_1", "0", "0"},
[9003301] = {9003301, 90033, 97, 0, "0", "idle", "沒想到我們還能有機會再一次合作……這是我的榮幸，領航。", "0", "0", "0", "0", "0", "mmbz_mi_feilin_2", "0", "0"},
[9003302] = {9003302, 90033, 97, 0, "0", "idle", "時間真奇怪……以前覺得一周都很漫長，但在我離開方舟的半年裡，又感覺時間過得很快，非常不可思議。", "0", "0", "0", "0", "0", "mmbz_mi_feilin_3", "0", "0"},
[9003303] = {9003303, 90033, 97, 0, "0", "idle", "嗯……也許已經有其他人對您說過了……不過，領航認真工作時的模樣真的很迷人噢。", "0", "0", "0", "0", "0", "mmbz_mi_feilin_4", "0", "0"},
[9003304] = {9003304, 90033, 98, 0, "0", "idle", "任務完成得十分漂亮呢，不愧是傳說中的領航！", "0", "0", "0", "0", "0", "mmbz_mi_feilin_5", "0", "0"},
[9003305] = {9003305, 90033, 98, 0, "0", "idle", "任務獎勵，任務獎勵……我記得是放這裡的……稍微等等……呼，找到啦~", "0", "0", "0", "0", "0", "mmbz_mi_feilin_6", "0", "0"},
[9003400] = {9003400, 90034, 97, 0, "0", "idle", "鏘鏘鏘！今天會看到什麼樣的電影呢？會是好片嗎？還是說是爛片呢？讓我們拭目以待吧！", "0", "0", "0", "0", "0", "mmbz_mg_saimiu1", "0", "0"},
[9003401] = {9003401, 90034, 97, 0, "0", "idle", "世界上只有倆類爛片，一種是經費有限的同時，黔驢技窮製作出來的低成本電影，另一種是揮霍無度，在特技場面上投資億萬，內容卻空無一物的“大片”。", "0", "0", "0", "0", "0", "mmbz_mg_saimiu2", "0", "0"},
[9003402] = {9003402, 90034, 97, 0, "0", "idle", "雖然熱衷於挖掘冷門的好作品是一件值得褒獎的事，但追隨大眾的品味選擇當下的熱門電影我認為也沒什麼丟臉的！", "0", "0", "0", "0", "0", "mmbz_mg_saimiu3", "0", "0"},
[9003403] = {9003403, 90034, 97, 0, "0", "idle", "據說有那種專門品鑒廉價無趣的B級電影的人……說實話，我無法和那類人共情，優秀的劇情，經費充足的製作，這才是我想要的電影！", "0", "0", "0", "0", "0", "mmbz_mg_saimiu4", "0", "0"},
[9003404] = {9003404, 90034, 98, 0, "0", "idle", "抽到什麼就看什麼，不管怎樣的爛片我都會堅持下去的！", "0", "0", "0", "0", "0", "mmbz_mg_saimiu5", "0", "0"},
[9003405] = {9003405, 90034, 98, 0, "0", "idle", "人生就像是一場電影，有時候是爛片，有時候是好片，但無論是好是壞，都是人生的一部分，要認真地感受它，體驗它。", "0", "0", "0", "0", "0", "mmbz_mg_saimiu6", "0", "0"},
[9003406] = {9003406, 90034, 98, 0, "0", "idle", "他們的團隊是怎麼拍出這種電影的，能不能教我，我也想給自己拍這麼精彩的電影！", "0", "0", "0", "0", "0", "mmbz_mg_saimiu7", "0", "0"},
[9003407] = {9003407, 90034, 98, 0, "0", "idle", "感謝它，讓我又多了一次豐富有趣的冒險。", "0", "0", "0", "0", "0", "mmbz_mg_saimiu8", "0", "0"},
[9003408] = {9003408, 90034, 98, 0, "0", "idle", "……我要去匿名罵它，浪費了我人生寶貴的倆小時！", "0", "0", "0", "0", "0", "mmbz_mg_saimiu9", "0", "0"},
[9003500] = {9003500, 90035, 97, 0, "0", "idle", "伊莉雅，我們這是要去哪？", "0", "0", "0", "0", "0", "0", "0", "0"},
[9003501] = {9003501, 90035, 97, 0, "0", "idle", "你又把這套衣服拿出來了呀。", "0", "0", "0", "0", "0", "0", "0", "0"},
[9003502] = {9003502, 90035, 97, 0, "0", "idle", "怎麼又沒吃晚飯？好孩子可是不會挑食的。", "0", "0", "0", "0", "0", "0", "0", "0"},
[9003503] = {9003503, 90035, 97, 0, "0", "idle", "波琳娜相信，領航一定會把伊莉雅帶回來的。", "0", "0", "0", "0", "0", "0", "0", "0"},
[9003504] = {9003504, 90035, 97, 0, "0", "idle", "听说你和亚尔薇特在进行非常危险的实验项目。", "0", "0", "0", "0", "0", "0", "0", "0"},
[9003600] = {9003600, 90036, 97, 0, "0", "idle", "任务清单整理好了，哥哥……我忘了，在工作的时候应该叫，领航。", "0", "0", "0", "0", "0", "xma1_mission_jiya_1", "0", "0"},
[9003601] = {9003601, 90036, 97, 0, "0", "idle", "放轻松，就和平常一样，不过还是要注意安全。", "0", "0", "0", "0", "0", "xma1_mission_jiya_2", "0", "0"},
[9003602] = {9003602, 90036, 97, 0, "0", "idle", "想先完成哪个任务就领航自己安排吧。顺便问一下，晚餐想吃烤鱼排还是牛肉炖汤？", "0", "0", "0", "0", "0", "xma1_mission_jiya_3", "0", "0"},
[9003603] = {9003603, 90036, 97, 0, "0", "idle", "圣诞节还要工作是很辛苦呢，当然我也会一直陪着你。", "0", "0", "0", "0", "0", "xma1_mission_jiya_4", "0", "0"},
[9003604] = {9003604, 90036, 98, 0, "0", "idle", "不愧是哥哥！", "0", "0", "0", "0", "0", "xma1_mission_jiya_5", "0", "0"},
[9003605] = {9003605, 90036, 98, 0, "0", "idle", "任务完成，接下来的任务是……回家吃饭。", "0", "0", "0", "0", "0", "xma1_mission_jiya_6", "0", "0"},
[9003700] = {9003700, 90037, 97, 0, "0", "idle", "MERRY CHRITMAS！", "0", "0", "0", "0", "0", "xam1_shop_kelimu_1", "0", "0"},
[9003701] = {9003701, 90037, 97, 0, "0", "idle", "聖誕老人的禮物還要花錢買？這件事確實很奇怪。", "0", "0", "0", "0", "0", "xam1_shop_kelimu_2", "0", "0"},
[9003702] = {9003702, 90037, 97, 0, "0", "idle", "這些酒是非賣品，是要留給……聖誕老人的。", "0", "0", "0", "0", "0", "xam1_shop_kelimu_3", "0", "0"},
[9003703] = {9003703, 90037, 97, 0, "0", "idle", "讓我看看好孩子名單上有沒有你的名字。", "0", "0", "0", "0", "0", "xam1_shop_kelimu_4", "0", "0"},
[9003704] = {9003704, 90037, 97, 0, "0", "idle", "特惠折扣，僅在今天！……悄悄告訴你，其實明天也有。", "0", "0", "0", "0", "0", "xam1_shop_kelimu_5", "0", "0"},
[9003705] = {9003705, 90037, 98, 0, "0", "idle", "太……太有實力了，領航。", "0", "0", "0", "0", "0", "xam1_shop_kelimu_6", "0", "0"},
[9003706] = {9003706, 90037, 98, 0, "0", "idle", "這就給您包起來！那個，我的小費……", "0", "0", "0", "0", "0", "xam1_shop_kelimu_7", "0", "0"},
[9003707] = {9003707, 90037, 98, 0, "0", "idle", "您購買的商品我晚上給您送過去吧，記得煙囪不要生火。", "0", "0", "0", "0", "0", "xam1_shop_kelimu_8", "0", "0"},
[9003800] = {9003800, 90038, 97, 0, "0", "idle", "我就知道你會再來，希望今天的你能像昨天一樣滿載而歸。", "0", "0", "0", "0", "0", "xam1_shop_heluoka_1", "0", "0"},
[9003801] = {9003801, 90038, 97, 0, "0", "idle", "釣魚只是在消磨時間？我不同意這種説法，我可是每時每刻都在心裏期待著能釣上不一樣的東西。", "0", "0", "0", "0", "0", "xam1_shop_heluoka_2", "0", "0"},
[9003802] = {9003802, 90038, 97, 0, "0", "idle", "不要被水面上的波紋給欺騙了，那只是魚在試探。一定要冷靜，冷靜，直到浮漂完全沉下去。", "0", "0", "0", "0", "0", "xam1_shop_heluoka_3", "0", "0"},
[9003803] = {9003803, 90038, 97, 0, "0", "idle", "你知道這冰面之下通往哪裏嗎？你的記憶，你的那些曾經發生過又被忘卻的美好回憶。遺忘之海，還記得嗎……", "0", "0", "0", "0", "0", "xam1_shop_heluoka_4", "0", "0"},
[9003804] = {9003804, 90038, 98, 0, "0", "idle", "等待吧，接下來要做的只有等待。", "0", "0", "0", "0", "0", "xam1_shop_heluoka_5", "0", "0"},
[9003805] = {9003805, 90038, 98, 0, "0", "idle", "不知道會釣上多大的魚。", "0", "0", "0", "0", "0", "xam1_shop_heluoka_6", "0", "0"},
[9003806] = {9003806, 90038, 98, 0, "0", "idle", "破紀錄了 ！難道是傳説中的湖中之主！", "0", "0", "0", "0", "0", "xam1_shop_heluoka_7", "0", "0"},
[9003807] = {9003807, 90038, 98, 0, "0", "idle", "不錯呢，但是和我的最大釣魚紀錄相比還差得遠。", "0", "0", "0", "0", "0", "xam1_shop_heluoka_8", "0", "0"},
[9003808] = {9003808, 90038, 98, 0, "0", "idle", "……這也是難免的，習慣就好。", "0", "0", "0", "0", "0", "xam1_shop_heluoka_9", "0", "0"},
[9003900] = {9003900, 90039, 97, 0, "0", "idle", "嘿嘿……這次是商店的店員……就由我來接待變態先生吧！", "0", "0", "0", "0", "0", "vd2_shop_weilai_1", "0", "0"},
[9003901] = {9003901, 90039, 97, 0, "0", "jidong", "哈——打折？我和變態先生只不過相熟共事了一年不到而已……", "0", "0", "0", "0", "0", "vd2_shop_weilai_2", "0", "0"},
[9003902] = {9003902, 90039, 97, 0, "0", "chensi", "本店可不能賒賬……！但是我可以收受賄賂！", "0", "0", "0", "0", "0", "vd2_shop_weilai_3", "0", "0"},
[9003903] = {9003903, 90039, 97, 0, "0", "jingya", "咦……我和變態先生是用的情侶錢包……我賺到了就等於變態先生賺到了，是這个道理嗎？", "0", "0", "0", "0", "0", "vd2_shop_weilai_4", "0", "0"},
[9003904] = {9003904, 90039, 97, 0, "0", "jidong", "我差不多膩了……站在這裏等變態先生的時間只感到無聊……你能不能一直待在這裏陪我？", "0", "0", "0", "0", "0", "vd2_shop_weilai_5", "0", "0"},
[9003905] = {9003905, 90039, 98, 0, "0", "xiao2", "在我這裏買東西不用交稅哦……也就是説我是——the逃稅商店。", "0", "0", "0", "0", "0", "vd2_shop_weilai_6", "0", "0"},
[9003906] = {9003906, 90039, 98, 0, "0", "xiao1", "有沒有小費？", "0", "0", "0", "0", "0", "vd2_shop_weilai_7", "0", "0"},
[9003907] = {9003907, 90039, 98, 0, "0", "xiao3", "東西就在貨架上，你自己拏吧！", "0", "0", "0", "0", "0", "vd2_shop_weilai_8", "0", "0"},
[9004000] = {9004000, 90040, 97, 0, "0", "danxin", "領航……很抱歉這次連累了你……", "0", "0", "0", "0", "0", "vd2_mission_zhuliwusi_1", "0", "0"},
[9004001] = {9004001, 90040, 97, 0, "0", "chensi", "保密作戰會議……是叫這樣的名字嗎？呵呵……倒也挺符合我現在的處境的……", "0", "0", "0", "0", "0", "vd2_mission_zhuliwusi_2", "0", "0"},
[9004002] = {9004002, 90040, 97, 0, "0", "idle", "就現有的情報對事件作出最後的推理吧。", "0", "0", "0", "0", "0", "vd2_mission_zhuliwusi_3", "0", "0"},
[9004003] = {9004003, 90040, 97, 0, "0", "angry2", "竟然對駕駛員們的感情出手……我絶不原諒……", "0", "0", "0", "0", "0", "vd2_mission_zhuliwusi_4", "0", "0"},
[9004004] = {9004004, 90040, 98, 0, "0", "xiao1", "情報收集完了，辛苦您了。", "0", "0", "0", "0", "0", "vd2_mission_zhuliwusi_5", "0", "0"},
[9004005] = {9004005, 90040, 98, 0, "0", "xiao2", "嗯……綫索到這裏就斷了……總之先整理手上的情報吧。", "0", "0", "0", "0", "0", "vd2_mission_zhuliwusi_6", "0", "0"},
[9004100] = {9004100, 90041, 97, 0, "0", "idle", "你們那份熾熱的感情和心就由我絕對戀愛怪盜收下了！", "0", "0", "0", "0", "0", "0", "0", "0"},
[9004101] = {9004101, 90041, 97, 0, "0", "idle", "你們的情書與欲望就由我收下了！", "0", "0", "0", "0", "0", "0", "0", "0"},
[9004102] = {9004102, 90041, 97, 0, "0", "idle", "咦……這、這是我！？這究竟是……！？", "0", "0", "0", "0", "0", "0", "0", "0"},
[9004103] = {9004103, 90041, 97, 0, "0", "idle", "咦……你是誰，怎麼會在這裏！？", "0", "0", "0", "0", "0", "0", "0", "0"},
[9004104] = {9004104, 90041, 98, 0, "0", "idle", "總感覺……你有點眼熟……有讓人討厭……不對……讓人懷念的感覺……", "0", "0", "0", "0", "0", "0", "0", "0"},
[9004105] = {9004105, 90041, 98, 0, "0", "idle", "咳……我的名字是亞瑟·潘德拉貢！", "0", "0", "0", "0", "0", "0", "0", "0"},
[9004106] = {9004106, 90041, 98, 0, "0", "idle", "九十九環……接招吧！看我把你的記憶和感情全部都消除。", "0", "0", "0", "0", "0", "0", "0", "0"},
[9004107] = {9004107, 90041, 98, 0, "0", "idle", "呃啊啊啊啊——", "0", "0", "0", "0", "0", "0", "0", "0"},
[9004108] = {9004108, 90041, 98, 0, "0", "idle", "大、大事不妙了……！超級戀愛偵探和他的助手們必須立刻出擊！", "0", "0", "0", "0", "0", "0", "0", "0"},
[9004109] = {9004109, 90041, 98, 0, "0", "idle", "我會盡綿薄之力輔佐您的。", "0", "0", "0", "0", "0", "0", "0", "0"},
[9004110] = {9004110, 90041, 98, 0, "0", "idle", "我乃原罪中的原罪，被稱之為原罪之神也不為過！", "0", "0", "0", "0", "0", "0", "0", "0"},
[9004111] = {9004111, 90041, 98, 0, "0", "idle", "所以原罪中的原罪為什麼要奪走大家的情書……", "0", "0", "0", "0", "0", "0", "0", "0"},
[9004112] = {9004112, 90041, 98, 0, "0", "idle", "看來我要啟動我的秘密武器——超級機械朱利烏斯號了！", "0", "0", "0", "0", "0", "0", "0", "0"},
[9004113] = {9004113, 90041, 98, 0, "0", "idle", "超級機械朱利烏斯號！？為什麼是朱利烏斯的名字……而且聽起來一點都不像是邪惡怪盜的秘密武器！？", "0", "0", "0", "0", "0", "0", "0", "0"},
[9004200] = {9004200, 90042, 97, 0, "0", "idle", "和您一起找石頭的回憶，是我人生中寶貴的記憶。", "0", "0", "0", "0", "0", "grjq_dlls_shop_001", "0", "0"},
[9004201] = {9004201, 90042, 97, 0, "0", "idle", "領航，用石頭交換您喜歡的東西吧。", "0", "0", "0", "0", "0", "grjq_dlls_shop_002", "0", "0"},
[9004202] = {9004202, 90042, 97, 0, "0", "idle", "收集石頭是個人興趣嗎……不，只是想把希望傳遞給以後的人。", "0", "0", "0", "0", "0", "grjq_dlls_shop_003", "0", "0"},
[9004203] = {9004203, 90042, 97, 0, "0", "idle", "在領航兌換完商品之前，我會守護好這家商店的！", "0", "0", "0", "0", "0", "grjq_dlls_shop_004", "0", "0"},
[9004204] = {9004204, 90042, 97, 0, "0", "idle", "如果時間充裕的話，可以在購物之前先準備一張清單，這樣有助於您製定計劃。", "0", "0", "0", "0", "0", "grjq_dlls_shop_005", "0", "0"},
[9004205] = {9004205, 90042, 98, 0, "0", "idle", "謝謝惠顧~", "0", "0", "0", "0", "0", "grjq_dlls_shop_006", "0", "0"},
[9004206] = {9004206, 90042, 98, 0, "0", "idle", "謝謝~請再努力收集些奇怪的石頭吧！", "0", "0", "0", "0", "0", "grjq_dlls_shop_007", "0", "0"},
[9004207] = {9004207, 90042, 98, 0, "0", "idle", "好、好多石頭！都可以開石頭品鑒大會了！", "0", "0", "0", "0", "0", "grjq_dlls_shop_008", "0", "0"},
[9004300] = {9004300, 90043, 97, 0, "0", "idle", "石頭……石頭……啊，領航，您來了——那個，我正在找石頭……能幫幫我嗎？", "0", "0", "0", "0", "0", "grjq_dlls_main_001", "0", "0"},
[9004301] = {9004301, 90043, 97, 0, "0", "idle", "我在找一顆能讓人安心，讓人雀躍，讓人心懷希望的石頭……這樣說，是不是有點奇怪？", "0", "0", "0", "0", "0", "grjq_dlls_main_002", "0", "0"},
[9004302] = {9004302, 90043, 97, 0, "0", "idle", "唔……領航，您方便說一下，您喜歡什麽樣的石頭嗎……如果、如果有機會的話，我想挑一顆合適的石頭送給您。", "0", "0", "0", "0", "0", "grjq_dlls_main_003", "0", "0"},
[9004303] = {9004303, 90043, 97, 0, "0", "idle", "「好妻子」眼鏡？奇怪的名字……是什麽cosplay道具嗎？", "0", "0", "0", "0", "0", "grjq_dlls_main_004", "0", "0"},
[9004304] = {9004304, 90043, 97, 0, "0", "idle", "領航，您最近有什麽出行計劃嗎？不介意的話……可以留點時間給我嗎？", "0", "0", "0", "0", "0", "grjq_dlls_main_005", "0", "0"},
[9004305] = {9004305, 90043, 97, 0, "0", "idle", "戒指……嘿嘿……戒指……嗯？什——什麽事都沒有，我只是在自言自語，您不要在意！", "0", "0", "0", "0", "0", "grjq_dlls_main_006", "0", "0"},
[9004400] = {9004400, 90044, 97, 0, "0", "idle", "以前的芙露露原來是這樣的嗎……眞讓人懷念啊，和小動物一樣人畜無害時期的芙露露……", "0", "0", "0", "0", "0", "2nd_countdown_1", "0", "0"},
[9004401] = {9004401, 90044, 97, 0, "0", "idle", "只要睡一覺起來，昨天的不開心事就會全部忘記，這是只有“現在”的查麗莎姐姐才能做到的事情，太厲害了。", "0", "0", "0", "0", "0", "2nd_countdown_2", "0", "0"},
[9004402] = {9004402, 90044, 97, 0, "0", "idle", "說起來……這個時候的我，好像和阿萊塔幾乎沒說過話……", "0", "0", "0", "0", "0", "2nd_countdown_3", "0", "0"},
[9004403] = {9004403, 90044, 97, 0, "0", "idle", "芙露露長大以後……會變成像隊長那樣成熟的大人喵？", "0", "0", "0", "0", "0", "2nd_countdown_4", "0", "0"},
[9004404] = {9004404, 90044, 97, 0, "0", "idle", "不用想也知道，未來的我一定成為家喩戶曉的大明星了。", "0", "0", "0", "0", "0", "2nd_countdown_5", "0", "0"},
[9004405] = {9004405, 90044, 97, 0, "0", "idle", "以前的我……是這樣的笨蛋嗎？", "0", "0", "0", "0", "0", "2nd_countdown_6", "0", "0"},
[9004406] = {9004406, 90044, 97, 0, "0", "idle", "哼——像你這樣的老傢夥已經該退役了，時代該交到新生代手上了。", "0", "0", "0", "0", "0", "2nd_countdown_7", "0", "0"},
[9004500] = {9004500, 90045, 97, 0, "0", "shengqi3", "現在不是休息的時候，我們必須爭分奪秒！", "0", "0", "0", "0", "0", "2ND_mission_sps_001", "0", "0"},
[9004501] = {9004501, 90045, 97, 0, "0", "yansu2", "只要我們多做一些，世界就離被拯救近了一些，這就是我們不能懈怠的理由。", "0", "0", "0", "0", "0", "2ND_mission_sps_002", "0", "0"},
[9004502] = {9004502, 90045, 97, 0, "0", "yansu2", "如果把所有任務都完成了的話，會有人給我們建雕像嗎？", "0", "0", "0", "0", "0", "2ND_mission_sps_003", "0", "0"},
[9004503] = {9004503, 90045, 97, 0, "0", "wink2", "我所理解的世界末日，就是我們喜歡的東西被人一件不賸地丟進焚化爐。很難受吧？很不甘心吧？那還不趕快行動起來！", "0", "0", "0", "0", "0", "2ND_mission_sps_004", "0", "0"},
[9004504] = {9004504, 90045, 98, 0, "0", "wink2", "很好，憑著這份氣勢，一鼓作氣把所有任務都完成吧！", "0", "0", "0", "0", "0", "2ND_mission_sps_005", "0", "0"},
[9004505] = {9004505, 90045, 98, 0, "0", "maozui2", "你可是我親自挑選的一號同伴，這種程度的任務肯定難不倒你。", "0", "0", "0", "0", "0", "2ND_mission_sps_006", "0", "0"},
[9004600] = {9004600, 90046, 97, 0, "0", "idle", "店裡的商品，可都是我這麼多年的珍藏，絕對不會讓您失望的——大槪？", "0", "0", "0", "0", "0", "2ND_shop_alaita_001", "0", "0"},
[9004601] = {9004601, 90046, 97, 0, "0", "weixiao", "雖然能夠再見到領航是件好事，但是該收的錢還是一分也不會少的。", "0", "0", "0", "0", "0", "2ND_shop_alaita_002", "0", "0"},
[9004602] = {9004602, 90046, 97, 0, "0", "sikao", "像這樣看著領航忙碌的模樣，總感覺又回到了以前……整個人都年輕了二十歲。", "0", "0", "0", "0", "0", "2ND_shop_alaita_003", "0", "0"},
[9004603] = {9004603, 90046, 97, 0, "0", "sikao", "用貨幣去購買商品，用現在的忙碌去換取未來的美好，聽起來感覺差不多呢。", "0", "0", "0", "0", "0", "2ND_shop_alaita_004", "0", "0"},
[9004604] = {9004604, 90046, 97, 0, "0", "weixiao", "新切斯頓采購處童叟無欺，都是物美價廉的好東西~", "0", "0", "0", "0", "0", "2ND_shop_alaita_005", "0", "0"},
[9004605] = {9004605, 90046, 98, 0, "0", "weixiao", "謝謝惠顧，領航~", "0", "0", "0", "0", "0", "2ND_shop_alaita_006", "0", "0"},
[9004606] = {9004606, 90046, 98, 0, "0", "shengqi", "其他商品也很不錯，要再看看嗎？", "0", "0", "0", "0", "0", "2ND_shop_alaita_007", "0", "0"},
[9004607] = {9004607, 90046, 98, 0, "0", "weixiao", "太好了，這下新切斯頓的財報又好看一些了。", "0", "0", "0", "0", "0", "2ND_shop_alaita_008", "0", "0"},
[9004700] = {9004700, 90047, 97, 0, "0", "idle", "領航領航，大事不妙，小灰走丟啦！", "0", "0", "0", "0", "0", "2ND_game_fululu_001", "0", "0"},
[9004701] = {9004701, 90047, 97, 0, "0", "idle", "搜救貓咪行動，從現在開始！", "0", "0", "0", "0", "0", "2ND_game_fululu_002", "0", "0"},
[9004702] = {9004702, 90047, 97, 0, "0", "idle", "這是小灰，紅色的那隻是小黃，黑色的那隻是白小姐，它們在聚會喵！", "0", "0", "0", "0", "0", "2ND_game_fululu_003", "0", "0"},
