[9004802] = {9004802, 90048, 97, 0, "0", "bizui", "嗯……您需要什麼？", "0", "0", "0", "0", "0", "mtsr_shop_uzkk_03", "0", "0"},
[9004803] = {9004803, 90048, 97, 0, "0", "angry", "原來店員要記住這麼多種商品的擺放位置……好啊，我會做好的……", "0", "0", "0", "0", "0", "mtsr_shop_uzkk_04", "0", "0"},
