[9004807] = {9004807, 90048, 98, 0, "0", "angry", "謝謝惠顧……呃，慢走。", "0", "0", "0", "0", "0", "mtsr_shop_uzkk_08", "0", "0"},
[9004900] = {9004900, 90049, 97, 0, "0", "gg", "要去執行任務了？……不必緊張，按指示行事即可。若遇突發情況，優先確保自身安全。", "0", "0", "0", "0", "0", "mtsr_mission_iztk_01", "0", "0"},
[9004901] = {9004901, 90049, 97, 0, "0", "jy", "魯莽行動只會讓你成爲報告上的數字。我是想說……小心謹慎。", "0", "0", "0", "0", "0", "mtsr_mission_iztk_02", "0", "0"},
[9004902] = {9004902, 90049, 97, 0, "0", "gx", "看來這次的任務依舊難不倒你。那麼，這份委託便交給你了。", "0", "0", "0", "0", "0", "mtsr_mission_iztk_03", "0", "0"},
[9004903] = {9004903, 90049, 97, 0, "0", "hx", "雖然你並不需要我的提醒，但既然我是這次的任務官，那麼例行公事——這次的任務涉及【準罪級原罪】，請務必注意。", "0", "0", "0", "0", "0", "mtsr_mission_iztk_04", "0", "0"},
[9004904] = {9004904, 90049, 98, 0, "0", "nu", "你知道自己在做什麼就好。", "0", "0", "0", "0", "0", "mtsr_mission_iztk_05", "0", "0"},
[9004905] = {9004905, 90049, 98, 0, "0", "hx", "祝你好運。加油。", "0", "0", "0", "0", "0", "mtsr_mission_iztk_06", "0", "0"},
[9005000] = {9005000, 90050, 97, 0, "0", "haixiu", "只要把硬幣投進去……就會有獎勵掉下來……", "0", "0", "0", "0", "0", "her_fr_shop_fulanka_01", "0", "0"},
[9005001] = {9005001, 90050, 97, 0, "0", "cixiaogui", "扭蛋裏有什麼？嗯……我把婚紗的每個部件的拆了放進去了……開玩笑的嘿嘿……", "0", "0", "0", "0", "0", "her_fr_shop_fulanka_02", "0", "0"},
[9005002] = {9005002, 90050, 97, 0, "0", "haixiu", "領航可不許上癮！", "0", "0", "0", "0", "0", "her_fr_shop_fulanka_03", "0", "0"},
[9005003] = {9005003, 90050, 97, 0, "0", "idle", "嗯……感覺會讓人沉迷呢……", "0", "0", "0", "0", "0", "her_fr_shop_fulanka_04", "0", "0"},
[9005004] = {9005004, 90050, 97, 0, "0", "jingya", "你把“那個東西”帶來了吧？咳，就是硬幣啦，硬幣。", "0", "0", "0", "0", "0", "her_fr_shop_fulanka_05", "0", "0"},
[9005005] = {9005005, 90050, 98, 0, "0", "weixiao", "快出來吧~快出來吧~把硬幣全部都交出來~", "0", "0", "0", "0", "0", "her_fr_shop_fulanka_06", "0", "0"},
[9005006] = {9005006, 90050, 98, 0, "0", "xiaozhang", "扭蛋機硬幣的購買力可真是強大呢。", "0", "0", "0", "0", "0", "her_fr_shop_fulanka_07", "0", "0"},
[9005007] = {9005007, 90050, 98, 0, "0", "zaogao", "那麼……我們就一手交錢一手交貨。", "0", "0", "0", "0", "0", "her_fr_shop_fulanka_08", "0", "0"},
[9005100] = {9005100, 90051, 97, 0, "0", "idle", "明明今天是結婚的日子……竟然睡過頭了……糟糕了……", "0", "0", "0", "0", "0", "her_fr_event_fulanka_01", "0", "0"},
[9005101] = {9005101, 90051, 97, 0, "0", "idle", "哈呼呼呼……（打哈欠）昨天晚上興奮得沒有睡着……", "0", "0", "0", "0", "0", "her_fr_event_fulanka_02", "0", "0"},
[9005102] = {9005102, 90051, 97, 0, "0", "idle", "嗯……嗯……打起精神來吧，畢竟這對我們來說都是最重要的時刻！", "0", "0", "0", "0", "0", "her_fr_event_fulanka_03", "0", "0"},
[9005200] = {9005200, 90052, 97, 0, "0", "idle", "我乃終將掌控女主角宇宙的帝王。領航疼愛過的女兒。人類最後希望的背負者。", "0", "0", "0", "0", "0", "0", "0", "0"},
[9005201] = {9005201, 90052, 97, 0, "0", "idle", "閉嘴，我爸爸是領航，如果你惹怒了我，我就讓他來女主角宇宙暴打你們。", "0", "0", "0", "0", "0", "0", "0", "0"},
[9005202] = {9005202, 90052, 97, 0, "0", "idle", "我就長話短説了……我可以替代史蔕芬妮博士成為領航的媽媽。", "0", "0", "0", "0", "0", "0", "0", "0"},
[9005203] = {9005203, 90052, 97, 0, "0", "idle", "如果領航叫不知火媽媽的話……那我豈不是要稱呼不知火為嬭嬭！？", "0", "0", "0", "0", "0", "0", "0", "0"},
[9005204] = {9005204, 90052, 97, 0, "0", "idle", "爸爸也稱呼你為媽媽，我也稱呼你為媽媽！？輩分完全亂套了！？", "0", "0", "0", "0", "0", "0", "0", "0"},
[9005205] = {9005205, 90052, 97, 0, "0", "idle", "目標是整个女主角宇宙——大鬧一場吧！", "0", "0", "0", "0", "0", "0", "0", "0"},
[9005206] = {9005206, 90052, 97, 0, "0", "idle", "……？我不在的時候你們都干了什麽？", "0", "0", "0", "0", "0", "0", "0", "0"},
[9005300] = {9005300, 90053, 97, 0, "0", "chensi", "這是帝國的至高指令。", "0", "0", "0", "0", "0", "XH3_mission_RED_01", "0", "0"},
[9005301] = {9005301, 90053, 97, 0, "0", "idle", "我也想發布一个任務，任務內容就是“讓我開心”，想想都爽。", "0", "0", "0", "0", "0", "XH3_mission_RED_02", "0", "0"},
[9005302] = {9005302, 90053, 97, 0, "0", "nu", "我就派遣我的頭和你一起去吧，身體就畱在這裏。", "0", "0", "0", "0", "0", "XH3_mission_RED_03", "0", "0"},
[9005303] = {9005303, 90053, 97, 0, "0", "xiao", "好無聊啊……就沒有人忽然來襲擊這裏嗎？", "0", "0", "0", "0", "0", "XH3_mission_RED_04", "0", "0"},
[9005304] = {9005304, 90053, 98, 0, "0", "ganga", "哎，眞搞不懂為什麽要給你派這些簡單任務。", "0", "0", "0", "0", "0", "XH3_mission_RED_05", "0", "0"},
[9005305] = {9005305, 90053, 98, 0, "0", "xiao", "就把那些什麽宇宙大災通通打倒吧。", "0", "0", "0", "0", "0", "XH3_mission_RED_06", "0", "0"},
[9005400] = {9005400, 90054, 97, 0, "0", "daizhi", "爸爸又來看我了，好開心！", "0", "0", "0", "0", "0", "XH3_shop_hikari_01", "0", "0"},
[9005401] = {9005401, 90054, 97, 0, "0", "haixiu", "這些東西全都是爸爸的。", "0", "0", "0", "0", "0", "XH3_shop_hikari_02", "0", "0"},
[9005402] = {9005402, 90054, 97, 0, "0", "huangzhang", "剛剛有其他女主角來商店買東西，我把她們都赶跑了。", "0", "0", "0", "0", "0", "XH3_shop_hikari_03", "0", "0"},
[9005403] = {9005403, 90054, 97, 0, "0", "kuqi2", "商店打烊了之後我就要和爸爸分別了。", "0", "0", "0", "0", "0", "XH3_shop_hikari_04", "0", "0"},
[9005404] = {9005404, 90054, 97, 0, "0", "tushe", "開設商店的證明？我有哦，是我搶到的，厲害吧？", "0", "0", "0", "0", "0", "XH3_shop_hikari_05", "0", "0"},
[9005405] = {9005405, 90054, 98, 0, "0", "xiao1", "這些店裏的東西有爸爸需要的嗎？", "0", "0", "0", "0", "0", "XH3_shop_hikari_06", "0", "0"},
[9005406] = {9005406, 90054, 98, 0, "0", "xiao2", "我會努力去“進貨”的。", "0", "0", "0", "0", "0", "XH3_shop_hikari_07", "0", "0"},
[9005407] = {9005407, 90054, 98, 0, "0", "xiao4", "爸爸~歡迎光臨~", "0", "0", "0", "0", "0", "XH3_shop_hikari_08", "0", "0"},
[9005500] = {9005500, 90055, 97, 0, "0", "idle", "啊~旅行眞開心啊~", "0", "0", "0", "0", "0", "XH3_game_huizhang_01", "0", "0"},
[9005501] = {9005501, 90055, 97, 0, "0", "idle", "應該給她們帶什麽紀念品呢……王女的話興趣會和我一樣就帶同樣的好了。", "0", "0", "0", "0", "0", "XH3_game_huizhang_02", "0", "0"},
[9005502] = {9005502, 90055, 97, 0, "0", "idle", "不知火……和小孩子有關的紀念品都可以吧……決定了，就帶這个小孩子地縛靈雕像給她吧。", "0", "0", "0", "0", "0", "XH3_game_huizhang_03", "0", "0"},
[9005503] = {9005503, 90055, 97, 0, "0", "idle", "九十九環的話……反制不知火能力的手段多多益善，就帶這个詛咒轉移人偶吧。", "0", "0", "0", "0", "0", "XH3_game_huizhang_04", "0", "0"},
[9005504] = {9005504, 90055, 97, 0, "0", "idle", "我的大冒險，要開始了！", "0", "0", "0", "0", "0", "XH3_game_huizhang_05", "0", "0"},
[9005505] = {9005505, 90055, 97, 0, "0", "idle", "這次又會遇到什麽有趣的事情呢。", "0", "0", "0", "0", "0", "XH3_game_huizhang_06", "0", "0"},
[9005506] = {9005506, 90055, 97, 0, "0", "idle", "大寶藏……眞是豐收……藏品又增加了。", "0", "0", "0", "0", "0", "XH3_game_huizhang_07", "0", "大成功"},
[9005507] = {9005507, 90055, 97, 0, "0", "idle", "吼……只是珠寶黃金的話就有點無聊了。", "0", "0", "0", "0", "0", "XH3_game_huizhang_08", "0", "成功"},
[9005508] = {9005508, 90055, 97, 0, "0", "idle", "呵呵……是假的藏寶圖嗎……", "0", "0", "0", "0", "0", "XH3_game_huizhang_09", "0", "失敗"},
[9005600] = {9005600, 90056, 97, 0, "0", "ganga", "如果完不成也不要緊，比起完成任務，自身的生命安全更加重要。", "0", "0", "0", "0", "0", "2.5_mission_yida_01", "0", "0"},
[9005601] = {9005601, 90056, 97, 0, "0", "angry", "執行任務時的幫手幷不是越多越好，人越多，變數也越多，反而會更危險。", "0", "0", "0", "0", "0", "2.5_mission_yida_02", "0", "0"},
[9005602] = {9005602, 90056, 97, 0, "0", "idle", "休息和工作同樣重要……不，休息比工作更加重要。", "0", "0", "0", "0", "0", "2.5_mission_yida_03", "0", "0"},
[9005603] = {9005603, 90056, 97, 0, "0", "jingya", "裝備和補給檢查了嗎？可不要因為這種低級的疏忽導致無法挽回的結果。", "0", "0", "0", "0", "0", "2.5_mission_yida_04", "0", "0"},
[9005604] = {9005604, 90056, 98, 0, "0", "happy", "這个任務竟然完成了……眞厲害。", "0", "0", "0", "0", "0", "2.5_mission_yida_05", "0", "0"},
[9005605] = {9005605, 90056, 98, 0, "0", "shy", "能完成這个任務，看來我之前對您的擔心完全是多餘的。", "0", "0", "0", "0", "0", "2.5_mission_yida_06", "0", "0"},
[9005700] = {9005700, 90057, 97, 0, "0", "bzsc", "歡……歡迎光臨，有什麽需要……請隨意選購……", "0", "0", "0", "0", "0", "2.5_shop_mika_01", "0", "0"},
[9005701] = {9005701, 90057, 97, 0, "0", "gaoxing", "價格標籤貼錯了？這這這……要不這个商品我來替您支付吧……", "0", "0", "0", "0", "0", "2.5_shop_mika_02", "0", "0"},
[9005702] = {9005702, 90057, 97, 0, "0", "ganga", "這些都是今早的新上架的商品……", "0", "0", "0", "0", "0", "2.5_shop_mika_03", "0", "0"},
[9005703] = {9005703, 90057, 97, 0, "0", "ku", "因為只有我一个店員的緣故……暫不支持外送服務……", "0", "0", "0", "0", "0", "2.5_shop_mika_04", "0", "0"},
[9005704] = {9005704, 90057, 97, 0, "0", "idle", "雖然我很感激店主給我這个工作機會，但是就這樣放心把店交給我一个人眞的沒問題嗎？", "0", "0", "0", "0", "0", "2.5_shop_mika_05", "0", "0"},
[9005705] = {9005705, 90057, 98, 0, "0", "haixiu", "謝……謝謝惠顧……", "0", "0", "0", "0", "0", "2.5_shop_mika_06", "0", "0"},
[9005706] = {9005706, 90057, 98, 0, "0", "jingya", "需要幫您加熱一下嗎……", "0", "0", "0", "0", "0", "2.5_shop_mika_07", "0", "0"},
[9005707] = {9005707, 90057, 98, 0, "0", "ganga", "那个……這个……收銀機該怎麽用來著……", "0", "0", "0", "0", "0", "2.5_shop_mika_08", "0", "0"},
[9005800] = {9005800, 90058, 97, 0, "0", "idle", "抽奬和釣魚是一樣的，只管放手去做就好了。", "0", "0", "0", "0", "0", "2.5_game_heluoka_01", "0", "0"},
[9005801] = {9005801, 90058, 97, 0, "0", "idle", "領航需要我借你點好運嗎?", "0", "0", "0", "0", "0", "2.5_game_heluoka_02", "0", "0"},
[9005802] = {9005802, 90058, 97, 0, "0", "idle", "不愧是領航！", "0", "0", "0", "0", "0", "2.5_game_heluoka_03", "0", "大成功"},
[9005803] = {9005803, 90058, 97, 0, "0", "idle", "不錯的奬品呢。", "0", "0", "0", "0", "0", "2.5_game_heluoka_04", "0", "成功"},
[9005804] = {9005804, 90058, 97, 0, "0", "idle", "不要灰心，還有機會。", "0", "0", "0", "0", "0", "2.5_game_heluoka_05", "0", "失敗"},
[9005900] = {9005900, 90059, 97, 0, "0", "chensi", "這裏是章魚星球的商店，想要什麽東西就用糖果來交換吧。", "0", "0", "0", "0", "0", "her_sk_shop_sikadi_01", "0", "0"},
[9005901] = {9005901, 90059, 97, 0, "0", "ci", "幫助大家解決困擾和麻煩的話就會收到糖果作為報酬哦~", "0", "0", "0", "0", "0", "her_sk_shop_sikadi_02", "0", "0"},
[9005902] = {9005902, 90059, 97, 0, "0", "ganga", "不給糖就搗蛋！？誒！？對吾説嗎！？嗚——領航可不要想著鑽我的漏洞哦！", "0", "0", "0", "0", "0", "her_sk_shop_sikadi_03", "0", "0"},
[9005903] = {9005903, 90059, 97, 0, "0", "idle", "吾想了很久……世界上的一般等價物變成了糖果之後……那吾之前攢著的錢……豈不是變成廢紙了……", "0", "0", "0", "0", "0", "her_sk_shop_sikadi_04", "0", "0"},
[9005904] = {9005904, 90059, 97, 0, "0", "idle2", "吾想了很久……如果世界變回去之後……現在賺到的糖果不就變成眞的糖果了嗎……", "0", "0", "0", "0", "0", "her_sk_shop_sikadi_05", "0", "0"},
[9005905] = {9005905, 90059, 98, 0, "0", "jingya", "還是當个幸福的章魚好了。", "0", "0", "0", "0", "0", "her_sk_shop_sikadi_06", "0", "0"},
[9005906] = {9005906, 90059, 98, 0, "0", "xiao", "向深淵揮舞你的熱情吧。", "0", "0", "0", "0", "0", "her_sk_shop_sikadi_07", "0", "0"},
[9005907] = {9005907, 90059, 98, 0, "0", "xiao3", "暗波洶涌的萬聖節呢，希望你玩得開心。", "0", "0", "0", "0", "0", "her_sk_shop_sikadi_08", "0", "0"},
[9006000] = {9006000, 90060, 97, 0, "0", "idle", "開始今天的旅行吧領航~目標是找到惡魔！", "0", "0", "0", "0", "0", "her_sk_ev_sakadi_01", "0", "0"},
[9006001] = {9006001, 90060, 97, 0, "0", "idle", "眷屬~吾聽見了深淵的低語，吾有預感一定會有好事發生的！", "0", "0", "0", "0", "0", "her_sk_ev_sakadi_02", "0", "0"},
[9006002] = {9006002, 90060, 97, 0, "0", "idle", "哈嚕~？", "0", "0", "0", "0", "0", "her_sk_ev_sakadi_03", "0", "0"},
[9006100] = {9006100, 90061, 97, 0, "0", "biyanxiao", "奇怪，爲什麽這裏會有商店呢……", "0", "0", "0", "0", "0", "her_gr_shop_guroria_01", "0", "0"},
[9006101] = {9006101, 90061, 97, 0, "0", "biyan", "訓練了這麽久，肚子也有些餓了……嗯……原來這裏不是喫飯的地方嗎……", "0", "0", "0", "0", "0", "her_gr_shop_guroria_02", "0", "0"},
[9006102] = {9006102, 90061, 97, 0, "0", "haixiu", "店裏好像沒有其他客人……不用排隊眞是太好了，您不這麽想嗎，領航先生？", "0", "0", "0", "0", "0", "her_gr_shop_guroria_03", "0", "0"},
[9006103] = {9006103, 90061, 97, 0, "0", "haixiu2", "領航先生沒有寫購物清單的習慣嗎……是嗎……我還以爲大家都會把每周的購物清單都準備好才會去商店的……", "0", "0", "0", "0", "0", "her_gr_shop_guroria_04", "0", "0"},
[9006104] = {9006104, 90061, 97, 0, "0", "weixiao", "“想買什麽就買什麽”……感覺像是羅德尼亞會説的話，我的話，是做不到這點的吧。", "0", "0", "0", "0", "0", "her_gr_shop_guroria_05", "0", "0"},
[9006105] = {9006105, 90061, 98, 0, "0", "jingya", "要是能買到領航先生喜歡的東西就好了。", "0", "0", "0", "0", "0", "her_gr_shop_guroria_06", "0", "0"},
[9006106] = {9006106, 90061, 98, 0, "0", "haixiu", "領航先生訓練時的熱情，即使是現在……我也能感受到。", "0", "0", "0", "0", "0", "her_gr_shop_guroria_07", "0", "0"},
[9006107] = {9006107, 90061, 98, 0, "0", "jingya", "價格高昂的球拍和便宜的球拍……用起來的手感會差別很大嗎？", "0", "0", "0", "0", "0", "her_gr_shop_guroria_08", "0", "0"},
[9006200] = {9006200, 90062, 97, 0, "0", "idle", "今天也麻煩您了，領航先生。", "0", "0", "0", "0", "0", "her_gr_event_guroria_01", "0", "0"},
[9006201] = {9006201, 90062, 97, 0, "0", "idle", "爲了訓練師……我們一起努力吧。", "0", "0", "0", "0", "0", "her_gr_event_guroria_02", "0", "0"},
[9006202] = {9006202, 90062, 97, 0, "0", "idle", "領航先生，您要是……累了的話……接下來我一个人也可以的。", "0", "0", "0", "0", "0", "her_gr_event_guroria_03", "0", "0"},
[9006300] = {9006300, 90063, 97, 0, "0", "daiji", "你的待辦事項還眞是够多的啊，有考慮過去申請薪資翻倍嗎？", "0", "0", "0", "0", "0", "xmas2_mission_teberda_01", "0", "0"},
[9006301] = {9006301, 90063, 97, 0, "0", "mor", "喏，你這次任務清單，我按大致的順序整理好了，有任何問題就來問我……你那表情是什麽意思，我在休息之外也是會好好干活的好嗎？", "0", "0", "0", "0", "0", "xmas2_mission_teberda_02", "0", "0"},
[9006302] = {9006302, 90063, 97, 0, "0", "bunai", "和幫葉格沙規劃日程比起來，整理這些東西就像做十位數加減法一樣簡單。", "0", "0", "0", "0", "0", "xmas2_mission_teberda_03", "0", "0"},
[9006303] = {9006303, 90063, 97, 0, "0", "yansu", "有什麽事是需要我幫忙的嗎？我會全部按加班標準上報的，盡管開口吧。", "0", "0", "0", "0", "0", "xmas2_mission_teberda_04", "0", "0"},
[9006304] = {9006304, 90063, 98, 0, "0", "qixiao", "好，又一項工作完成了。就這麽一步步往收工大吉邁進吧。", "0", "0", "0", "0", "0", "xmas2_mission_teberda_05", "0", "0"},
[9006305] = {9006305, 90063, 98, 0, "0", "xiao", "你居然連這个都解決了啊……可惜沒有工作越麻煩假期越長的規定。", "0", "0", "0", "0", "0", "xmas2_mission_teberda_06", "0", "0"},
[9006400] = {9006400, 90064, 97, 0, "0", "daiji", "不需要把客人灌醉稍微有點不適應啊——啊，歡迎光臨。", "0", "0", "0", "0", "0", "xmas2_shop_isucara_01", "0", "0"},
[9006401] = {9006401, 90064, 97, 0, "0", "gg", "就算你把這家店翻个底朝天我也不會換上隱藏服裝的，畢竟光是同樣的酒保服我就有四套。", "0", "0", "0", "0", "0", "xmas2_shop_isucara_02", "0", "0"},
[9006402] = {9006402, 90064, 97, 0, "0", "lendan", "戈露卡那丫頭不會又跑丢了吧……算了，專心工作，專心工作。", "0", "0", "0", "0", "0", "xmas2_shop_isucara_03", "0", "0"},
[9006403] = {9006403, 90064, 97, 0, "0", "shengqi", "我是能理解看店的必要性。但説實話，這家店從店員到顧客都只出現過一个人吧？", "0", "0", "0", "0", "0", "xmas2_shop_isucara_04", "0", "0"},
[9006404] = {9006404, 90064, 97, 0, "0", "sikao", "商品擺放有些亂？這種恰到好處的雜亂正方便管理哦，領航。", "0", "0", "0", "0", "0", "xmas2_shop_isucara_05", "0", "0"},
[9006405] = {9006405, 90064, 98, 0, "0", "weixiao", "感謝惠顧——好，又能從庫存單上劃掉一條了。", "0", "0", "0", "0", "0", "xmas2_shop_isucara_06", "0", "0"},
[9006406] = {9006406, 90064, 98, 0, "0", "haixiu", "我一般是允許熟客賒賬的哦？但這次的供貨商不同意，沒辦法。", "0", "0", "0", "0", "0", "xmas2_shop_isucara_07", "0", "0"},
[9006407] = {9006407, 90064, 98, 0, "0", "jingya", "現在加購特定商品還附贈一杯特調軟飲哦。啊？當然是現調的了，有道德的調酒師才不會給顧客冰箱裏的東西。", "0", "0", "0", "0", "0", "xmas2_shop_isucara_08", "0", "0"},
[9006500] = {9006500, 90065, 97, 0, "0", "idle", "全自動調酒機啓動——具體會蹦出什麽東西本店槪不負責！", "0", "0", "0", "0", "0", "xmas2_gmae_gorca_01", "0", "0"},
[9006501] = {9006501, 90065, 97, 0, "0", "idle", "這東西運轉時的動靜眞的超不妙啊，應該不會突然爆炸吧？", "0", "0", "0", "0", "0", "xmas2_gmae_gorca_02", "0", "0"},
[9006502] = {9006502, 90065, 97, 0, "0", "idle", "噢噢，運氣超好！這杯感覺都能直接擺到吧臺上去了。", "0", "0", "0", "0", "0", "xmas2_gmae_gorca_03", "0", "大成功"},
[9006503] = {9006503, 90065, 97, 0, "0", "idle", "好標準的軟飲。領航你要喝嗎？不要的話我就不客氣咯？", "0", "0", "0", "0", "0", "xmas2_gmae_gorca_04", "0", "成功"},
[9006504] = {9006504, 90065, 97, 0, "0", "idle", "哇，出現像不明化合物一樣的東西了……員工培訓裏説化學危害是要怎麽處理來著？", "0", "0", "0", "0", "0", "xmas2_gmae_gorca_05", "0", "失敗"},
[9006600] = {9006600, 90066, 97, 0, "0", "zhuai", "陽光好的時候，人的心情也就會變好，好的天氣，好的心情，正適合我們今天約會購物，您意下如何，領航。", "0", "0", "0", "0", "0", "her_fa_game_faernaisi_01", "0", "0"},
[9006601] = {9006601, 90066, 97, 0, "0", "biyan", "即使是其貌不揚的店鋪，裏面也可能埋藏著未被世人察覺的珍寶——任何時候都保持期待與懷疑，這是蘭德家族的家訓。", "0", "0", "0", "0", "0", "her_fa_game_faernaisi_02", "0", "0"},
[9006602] = {9006602, 90066, 97, 0, "0", "deyi", "只要是鍾意的，無論是商品還是人，我都會不擇手段地得到它……不，這並非家訓，而是我的人生哲學。", "0", "0", "0", "0", "0", "her_fa_game_faernaisi_03", "0", "0"},
[9006603] = {9006603, 90066, 97, 0, "0", "shengqi", "有找到心儀的東西嗎？沒有嗎？如果沒有的話，就毁掉這家不入流的店吧，我很樂意再燒毁一个無價値的事物。", "0", "0", "0", "0", "0", "her_fa_game_faernaisi_04", "0", "0"},
[9006604] = {9006604, 90066, 97, 0, "0", "idle", "事物的價値取決於購買者的主觀看法。倘若是我喜歡的東西，即便是隨處可見的一朵花，它的價値也足以買下一棟別墅。", "0", "0", "0", "0", "0", "her_fa_game_faernaisi_05", "0", "0"},
[9006605] = {9006605, 90066, 98, 0, "0", "zhuai", "如果您喜歡的話，只要您願意委身於蘭德家族……委身於我，我很樂意將它們全部買下贈予您。", "0", "0", "0", "0", "0", "her_fa_game_faernaisi_06", "0", "0"},
[9006606] = {9006606, 90066, 98, 0, "0", "zhuai", "注重華麗外觀的商品，其內在是否具備與其外觀一致的價値，在挑選商品時，我總會顧慮這一點，最後選擇更加實用的款式——不知您是否也是如此呢？", "0", "0", "0", "0", "0", "her_fa_game_faernaisi_07", "0", "0"},
[9006607] = {9006607, 90066, 98, 0, "0", "shengqi", "對於商品來説，噱頭往往比其實用性更重要，建築也是，奇形怪狀的建築總能收獲更多的目光與評價——但我並不喜歡這點，或者説，厭惡這一客觀規律。", "0", "0", "0", "0", "0", "her_fa_game_faernaisi_08", "0", "0"},
[9006700] = {9006700, 90067, 97, 0, "0", "idle", "直到我説“結束”之前，你都要扮演我的未婚夫，這是我和您的約定，不許反悔。", "0", "0", "0", "0", "0", "her_fa_home_faernaisi_01", "0", "0"},
[9006701] = {9006701, 90067, 97, 0, "0", "idle", "有想好今天去哪兒約會嗎，親~愛~的。", "0", "0", "0", "0", "0", "her_fa_home_faernaisi_02", "0", "0"},
[9006702] = {9006702, 90067, 97, 0, "0", "idle", "呵呵~", "0", "0", "0", "0", "0", "her_fa_home_faernaisi_03", "0", "0"},
[9006800] = {9006800, 90068, 97, 0, "0", "idle", "打擾了……查麗莎，領航他現在有空嗎？", "0", "0", "0", "0", "0", "mt2_wu_01", "0", "0"},
[9006801] = {9006801, 90068, 97, 0, "0", "idle", "初次見面，異世界的小妹~還有，希望這个世界能够歡迎夜雲~", "0", "0", "0", "0", "0", "mt2_wu_02", "0", "0"},
[9006802] = {9006802, 90068, 97, 0, "0", "idle", "即使是異世界，也一樣會遇上難纏的敵人嗎……", "0", "0", "0", "0", "0", "mt2_wu_03", "0", "0"},
[9006803] = {9006803, 90068, 97, 0, "0", "idle", "不管是原罪還是醜鬼，旣然是危害市民安全的敵人，我都會負責把它們揍飛的。", "0", "0", "0", "0", "0", "mt2_wu_04", "0", "0"},
[9006804] = {9006804, 90068, 97, 0, "0", "idle", "您就是那位被人人歌頌的多洛莉絲隊長嗎？初次見面，我是星環。", "0", "0", "0", "0", "0", "mt2_wu_05", "0", "0"},
[9006805] = {9006805, 90068, 97, 0, "0", "idle", "異世界人？超能力者？未來人？好有趣！", "0", "0", "0", "0", "0", "mt2_wu_06", "0", "0"},
[9006806] = {9006806, 90068, 97, 0, "0", "idle", "你們的表現……我應該説過了，旣然是魔防隊的組長，就算對手是神，也沒理由輸吧？", "0", "0", "0", "0", "0", "mt2_wu_07", "0", "0"},
[9006900] = {9006900, 90069, 97, 0, "0", "biyanxiao", "這份委託，就拜託給你了。", "这份委托，就拜托给你了。", "0", "0", "0", "0", "mt2_mission_afbk_01", "0", "0"},
[9006901] = {9006901, 90069, 97, 0, "0", "yansu", "完成任務的同時确保自己安全，這兩件事都要做到。", "完成任务的同时确保自己安全，这两件事都要做到。", "0", "0", "0", "0", "mt2_mission_afbk_02", "0", "0"},
[9006902] = {9006902, 90069, 97, 0, "0", "biyanxiao", "只要願意去做，就一定能做到，我很确信你就是這類人。", "只要愿意去做，就一定能做到，我很确信你就是这类人。", "0", "0", "0", "0", "mt2_mission_afbk_03", "0", "0"},
[9006903] = {9006903, 90069, 97, 0, "0", "yansu", "仔細确認任務目標，制定好作戰計劃，接著是按照計劃推進任務……嗯，你是明白這些基礎流程的。", "仔细确认任务目标，制定好作战计划，接着是按照计划推进任务……嗯，你是明白这些基础流程的。", "0", "0", "0", "0", "mt2_mission_afbk_04", "0", "0"},
[9006904] = {9006904, 90069, 98, 0, "0", "weixiao2", "出色的表現，賞心悅目。", "出色的表现，赏心悦目。", "0", "0", "0", "0", "mt2_mission_afbk_05", "0", "0"},
[9006905] = {9006905, 90069, 98, 0, "0", "weixiao2", "不錯。", "不错。", "0", "0", "0", "0", "mt2_mission_afbk_06", "0", "0"},
[9007000] = {9007000, 90070, 97, 0, "0", "biyanxiao", "歡迎光臨~今天要買什麽呢？", "欢迎光临~今天要买什么呢？", "0", "0", "0", "0", "mt2_shop_eykm_01", "0", "0"},
[9007001] = {9007001, 90070, 97, 0, "0", "biyanxiao", "想買什麽就買吧，不用跟夜雲客氣，反正不是我掏錢啦。", "想买什么就买吧，不用跟夜云客气，反正不是我掏钱啦。", "0", "0", "0", "0", "mt2_shop_eykm_02", "0", "0"},
[9007002] = {9007002, 90070, 97, 0, "0", "ganxingqu", "不只是異世界人，居然連宇宙人，超能力者，未來人都有，你們艾吉斯眞有意思呢！", "不只是異世界人，居然連宇宙人，超能力者，未來人都有，你們艾吉斯真有意思呢！", "0", "0", "0", "0", "mt2_shop_eykm_03", "0", "0"},
[9007003] = {9007003, 90070, 97, 0, "0", "idle", "你們是不是有宇宙飛船呀？眞好啊，夜雲也想去太空玩！", "你们是不是有宇宙飞船呀？真好啊，夜云也想去太空玩！", "0", "0", "0", "0", "mt2_shop_eykm_04", "0", "0"},
[9007004] = {9007004, 90070, 97, 0, "0", "kaixinxiao", "偶像的周邊？要是有那種東西，夜雲也想買啊~", "偶像的周边？要是有那种东西，夜云也想买啊~", "0", "0", "0", "0", "mt2_shop_eykm_05", "0", "0"},
[9007005] = {9007005, 90070, 98, 0, "0", "shahuhu", "很好，憑著這股勢頭，將商店掃空吧！", "很好，凭着这股势头，将商店扫空吧！", "0", "0", "0", "0", "mt2_shop_eykm_06", "0", "0"},
[9007006] = {9007006, 90070, 98, 0, "0", "wink", "買一送一的優惠？夜雲可沒有準備那種東西！", "买一送一的优惠？夜云可没有准备那种东西！", "0", "0", "0", "0", "mt2_shop_eykm_07", "0", "0"},
[9007007] = {9007007, 90070, 98, 0, "0", "wink", "謝謝惠顧！", "谢谢惠顾！", "0", "0", "0", "0", "mt2_shop_eykm_08", "0", "0"},
[9007400] = {9007400, 90074, 97, 0, "0", "yansu", "貴族出身的人往往只會在比較特定的場合走上街道——這樣來看，我對多瑙的理解可能存在比想象中更多的盲區。", "0", "0", "0", "0", "0", "her_Ju_game_Julius_01", "0", "0"},
[9007401] = {9007401, 90074, 97, 0, "0", "idle", "這個觀景臺對您來說，存在什麼額外的意義嗎？沒有，只是剛剛突然覺得風景應該很好？", "0", "0", "0", "0", "0", "her_Ju_game_Julius_02", "0", "0"},
[9007402] = {9007402, 90074, 97, 0, "0", "smile", "本來想勸您節制一些……但這些東西每一個都比我預想的便宜，我就睜一隻眼閉一隻眼了。", "0", "0", "0", "0", "0", "her_Ju_game_Julius_03", "0", "0"},
[9007403] = {9007403, 90074, 97, 0, "0", "idle", "稍顯清冷的午後商街，感覺有一種奇妙的空靈感呢。", "0", "0", "0", "0", "0", "her_Ju_game_Julius_04", "0", "0"},
[9007404] = {9007404, 90074, 97, 0, "0", "smile", "您沒必要這麼在意我的意見……我明白了，爲了讓領航您能更好地享受假期，我會好好跟您一起下決斷的。", "0", "0", "0", "0", "0", "her_Ju_game_Julius_05", "0", "0"},
[9007405] = {9007405, 90074, 98, 0, "0", "idle", "會不會一下買太多了……誒？只要付這麼一點？真的假的？", "0", "0", "0", "0", "0", "her_Ju_game_Julius_06", "0", "0"},
[9007406] = {9007406, 90074, 98, 0, "0", "shy", "領航在這方面的喜好是……啊，呃——我只是在自言自語，請別放在心上！", "0", "0", "0", "0", "0", "her_Ju_game_Julius_07", "0", "0"},
[9007407] = {9007407, 90074, 98, 0, "0", "smile", "如果是您中意的東西，我當然樂意一試。", "0", "0", "0", "0", "0", "her_Ju_game_Julius_08", "0", "0"},
[9007500] = {9007500, 90075, 97, 0, "0", "idle", "那麼，接下來的行程請多關照，領航。", "0", "0", "0", "0", "0", "her_Ju_home_Julius_01", "0", "0"},
[9007501] = {9007501, 90075, 97, 0, "0", "idle", "接下來又準備去哪呢？……您說讓我決定？", "0", "0", "0", "0", "0", "her_Ju_home_Julius_02", "0", "0"},
[9007502] = {9007502, 90075, 97, 0, "0", "idle", "如果您有空安排的話，之後每週……不對，每個月，每個月就好！……再去點，類似的地方吧？", "0", "0", "0", "0", "0", "her_Ju_home_Julius_03", "0", "0"},
[9007600] = {9007600, 90076, 97, 0, "0", "idle", "果然，每一處遊樂設施都必不可缺的“景點”——商店。", "やっぱり、どんなアミューズメントにも欠かせない「名所」といえば――ショップね。", "0", "0", "0", "0", "her_li_game_lilith_01", "0", "0"},
[9007601] = {9007601, 90076, 97, 0, "0", "shy", "結婚用的“戒指”竟然也有賣……而且看上去不像是玩具？", "結婚用の「指輪」まで売ってるのね……しかも、どう見てもおもちゃには見えないわね。", "0", "0", "0", "0", "her_li_game_lilith_02", "0", "0"},
[9007602] = {9007602, 90076, 97, 0, "0", "daiji", "“樂園”的周邊商品，不過是些隨處可見的便宜貨而已。", "「パラダイス」のグッズなんて、どこにでもある安物ばかりよ。", "0", "0", "0", "0", "her_li_game_lilith_03", "0", "0"},
[9007603] = {9007603, 90076, 97, 0, "0", "sad", "除了我們之外沒有其他客人光顧……雖然我不希望“樂園”倒閉，但除了多光顧幾次之外也做不了什麼。", "私たち以外に客はいないみたいね……。別に「パラダイス」に潰れてほしいわけじゃないけど、私たちにできることなんて、せいぜい何度か通ってあげるくらいね。", "0", "0", "0", "0", "her_li_game_lilith_04", "0", "0"},
[9007604] = {9007604, 90076, 97, 0, "0", "angry", "這身婚紗的確花掉了我很多積蓄，但還不至於淪落到三餐要吃草的程度。", "このウェディングドレス、かなり貯金を使ったけど……さすがに草を食べて生きるほど困ってはいないわ。", "0", "0", "0", "0", "her_li_game_lilith_05", "0", "0"},
[9007605] = {9007605, 90076, 98, 0, "0", "angry", "喜歡？那就多買點吧。", "気に入ったなら、もっと買えばいいじゃない。", "0", "0", "0", "0", "her_li_game_lilith_06", "0", "0"},
[9007606] = {9007606, 90076, 98, 0, "0", "daiji", "像是你會選的東西，其他東西不買一點嗎？", "あなたらしい選び方ね。他は買わなくていいの？", "0", "0", "0", "0", "her_li_game_lilith_07", "0", "0"},
[9007607] = {9007607, 90076, 98, 0, "0", "idle", "眼光不錯，難得我們會喜歡同樣的東西。", "いいセンスじゃない。私と同じものを気に入るなんて、珍しいわね。", "0", "0", "0", "0", "her_li_game_lilith_08", "0", "0"},
[9007700] = {9007700, 90077, 97, 0, "0", "idle", "這裏很安全也很安靜。", "ここは安全だし、静かなの。", "0", "0", "0", "0", "her_li_home_lilith_01", "0", "0"},
[9007701] = {9007701, 90077, 97, 0, "0", "idle", "你的心臟太吵了……撲通……撲通……撲通……聽得我直犯困……", "あなたの心臓がうるさい……。ドクン……ドクン……ドクン……聞いてると、眠くなってくるの。", "0", "0", "0", "0", "her_li_home_lilith_02", "0", "0"},
[9007702] = {9007702, 90077, 97, 0, "0", "idle", "有你在我很安心，但是不允許用“通感”窺探我的夢境。", "あなたがいると安心するの。でも、「通感覚」で私の夢を覗くのは……許さないわ。", "0", "0", "0", "0", "her_li_home_lilith_03", "0", "0"},
[4000000100] = {4000000100, 10000001, 1, 1, "0", "0", "蒼霧殘響。", "0", "0", "0", "0", "0", "cv_sk_rurura_33", "0", "0"},
[4000000101] = {4000000101, 10000001, 2, 2, "0", "0", "一切都交給我吧！", "0", "0", "0", "0", "0", "cv_sk_rurura_2", "0", "0"},
[4000000102] = {4000000102, 10000001, 3, 3, "0", "0", "我是魂滅小隊隊長露露啦，只要有我在，無論是生活方面還是戰鬥方面，都不需要領航費心。", "0", "0", "0", "0", "0", "cv_sk_rurura_1", "0", "0"},
[4000000103] = {4000000103, 10000001, 4, 4, "0", "idle", "金庫啦和歐朵啦在做什麼呢……呀！我沒在發呆！對了！領航想吃什麼嗎？我可以做很多菜喔，紅燒肉、醋溜魚、辣子雞……", "0", "0", "0", "0", "0", "cv_sk_rurura_3", "0", "0"},
[4000000104] = {4000000104, 10000001, 5, 4, "0", "idle", "領航您累了嗎？把工作交給我吧！有什麼心事也可以和我說，我會一直陪在您身邊。", "0", "0", "0", "0", "0", "cv_sk_rurura_4", "0", "0"},
[4000000105] = {4000000105, 10000001, 6, 4, "0", "idle", "領航，工作結束之後，我可以和你一起玩電玩喔！我可是超厲害的，歐朵啦和金庫啦都不是我的對手！", "0", "0", "0", "0", "0", "cv_sk_rurura_30", "0", "0"},
[4000000106] = {4000000106, 10000001, 7, 5, "15_1_0_0.8", "level1", "戰爭結束之後想做什麼……？我沒有特別想做的事，不過，如果領航希望的話，我可以像現在一樣一直照顧領航喔。", "0", "0", "0", "0", "0", "cv_sk_rurura_31", "0", "0"},
[4000000107] = {4000000107, 10000001, 8, 5, "15_2_0_0.8", "level2", "嗯……我正在思考今天晚上要做的晚飯喔，還請不要打斷我的思路啦。", "0", "0", "0", "0", "0", "cv_sk_rurura_5", "0", "0"},
[4000000108] = {4000000108, 10000001, 9, 5, "15_2_0_0.8", "level2", "欸呀呀，領航是覺得寂寞了嗎？要露露啦來陪你說說話嗎？", "0", "0", "0", "0", "0", "cv_sk_rurura_6", "0", "0"},
[4000000109] = {4000000109, 10000001, 10, 5, "15_1_0_0.8", "level1", "不知不覺中已經在多瑙支部待了這麼久了……一開始的時候確實有點沒法習慣，但是好在這裡大家都非常友善，現在我已經完全適應了喔。", "0", "0", "0", "0", "0", "cv_sk_rurura_7", "0", "0"},
[4000000110] = {4000000110, 10000001, 11, 5, "15_2_0_0.8", "level3", "領航……雖然有些不好意思，但是我覺得還是有必要當面說出來。那……那個，為了感謝這段時間你對我的照顧，我想邀請你來我這邊吃頓晚飯可以嗎？", "0", "0", "0", "0", "0", "cv_sk_rurura_8", "0", "0"},
[4000000111] = {4000000111, 10000001, 12, 6, "0", "0", "謝謝！這樣一來就能幫上領航了！", "0", "0", "0", "0", "0", "cv_sk_rurura_9", "0", "0"},
[4000000112] = {4000000112, 10000001, 13, 7, "0", "0", "這裡就由我來守護吧！", "0", "0", "0", "0", "0", "cv_sk_rurura_10", "0", "0"},
[4000000113] = {4000000113, 10000001, 14, 8, "0", "0", "太好了領航！這樣一來露露啦能做到的事情又變多了呢。", "0", "0", "0", "0", "0", "cv_sk_rurura_11", "0", "0"},
[4000000114] = {4000000114, 10000001, 15, 9, "0", "0", "新功能感覺真棒啊，真想馬上就去嘗試一下呢。", "0", "0", "0", "0", "0", "cv_sk_rurura_12", "0", "0"},
[4000000115] = {4000000115, 10000001, 16, 10, "0", "0", "這點小事就交給露露啦吧。", "0", "0", "0", "0", "0", "cv_sk_rurura_13", "0", "0"},
[4000000116] = {4000000116, 10000001, 17, 11, "0", "0", "呼~終於結束了呢，領航露露啦表現如何呢？", "0", "0", "0", "0", "0", "cv_sk_rurura_14", "0", "0"},
[4000000117] = {4000000117, 10000001, 18, 12, "0", "0", "下次再繼續加油啦！", "0", "0", "0", "0", "0", "cv_sk_rurura_15", "0", "0"},
