[4000000129] = {4000000129, 10000001, 31, 23, "0", "0", "我可以相信您嗎？", "0", "0", "0", "0", "0", "cv_sk_rurura_27", "0", "0"},
[4000000130] = {4000000130, 10000001, 32, 24, "0", "0", "猜對啦！能遇到領航真是太幸運啦！", "0", "0", "0", "0", "0", "cv_sk_rurura_28", "0", "0"},
[4000000131] = {4000000131, 10000001, 33, 25, "0", "0", "沒關係，反正下次還會有機會的吧。", "0", "0", "0", "0", "0", "cv_sk_rurura_29", "0", "0"},
[4000000132] = {4000000132, 10000001, 34, 26, "0", "0", "領航，歡迎回來！是要先洗澡嗎？還是說先吃飯呢？", "0", "0", "0", "0", "0", "cv_sk_rurura_32", "0", "0"},
[4000000133] = {4000000133, 10000001, 35, 27, "0", "0", "不管什麼樣的難關都可以依靠我喔。", "0", "0", "0", "0", "0", "cv_sk_rurura_34", "0", "0"},
[4000000134] = {4000000134, 10000001, 36, 28, "0", "0", "請儘管依賴我吧！", "0", "0", "0", "0", "0", "cv_sk_rurura_35", "0", "0"},
[4000000135] = {4000000135, 10000001, 37, 29, "0", "0", "有人肚子餓了嗎？", "0", "0", "0", "0", "0", "cv_sk_rurura_36", "0", "0"},
[4000000136] = {4000000136, 10000001, 38, 30, "0", "0", "我會負責面試的。", "0", "0", "0", "0", "0", "cv_sk_rurura_37", "0", "0"},
[4000000137] = {4000000137, 10000001, 39, 31, "0", "0", "新裝備？是領航給大家準備的禮物嗎！？", "0", "0", "0", "0", "0", "cv_sk_rurura_38", "0", "0"},
[4000000138] = {4000000138, 10000001, 40, 32, "0", "0", "採購的事情也請交給我吧。", "0", "0", "0", "0", "0", "cv_sk_rurura_39", "0", "0"},
[4000000139] = {4000000139, 10000001, 41, 33, "0", "0", "資訊確認很重要呢。", "0", "0", "0", "0", "0", "cv_sk_rurura_40", "0", "0"},
[4000000140] = {4000000140, 10000001, 42, 34, "0", "0", "來設定一下吧。", "0", "0", "0", "0", "0", "cv_sk_rurura_41", "0", "0"},
[4000000141] = {4000000141, 10000001, 43, 35, "0", "0", "嗯……看起來沒有可疑的信件。", "0", "0", "0", "0", "0", "cv_sk_rurura_42", "0", "0"},
[4000000142] = {4000000142, 10000001, 44, 36, "0", "0", "領航要多和朋友聊天！", "0", "0", "0", "0", "0", "cv_sk_rurura_43", "0", "0"},
[4000000143] = {4000000143, 10000001, 45, 37, "0", "0", "您還有其他事嗎？", "0", "0", "0", "0", "0", "cv_sk_rurura_44", "0", "0"},
[4000100100] = {4000100100, 10001001, 1, 1, "0", "0", "蒼霧殘響。", "蒼霧殘響（ハツリバーブ）。", "0", "0", "蒼霧殘響。", "0", "cv_sk_Julius_33", "0", "0"},
[4000100101] = {4000100101, 10001001, 2, 2, "0", "0", "我絕對不會辜負您的期待。", "絶対にご期待を裏切りませんわ。", "0", "0", "我絕對不會辜負您的期待。", "0", "cv_sk_Julius_2", "0", "0"},
[4000100102] = {4000100102, 10001001, 3, 3, "0", "0", "朱利烏斯·馮·尼采，從現在起將作為您最出色的部下，為了我們共同的榮耀而戰鬥。", "ユリウス・フォン・ニーチェです。これからあなた様の一番の部下として、我らの栄光のため、共に戦いましょう。", "0", "0", "朱利烏斯·馮·尼采，從現在起將作為您最出色的部下，為了我們共同的榮耀而戰鬥。", "0", "cv_sk_Julius_1", "0", "0"},
[4000100103] = {4000100103, 10001001, 4, 4, "0", "idle", "耀眼眩目的燈光、過於歡快的舞曲……雖說參與者都是年輕駕駛員，沒有太多寒暄與繁文縟節，但我果然還是不適應這種場合，幸好有邀您一同前來。", "華やかな照明と楽しい音楽……若いドライバーばかりですから堅苦しい雰囲気はありませんが、こういう場は少し慣れなくて……だから、あなた様に一緒に來ていただいて良かったです。", "0", "0", "我想要做的，我能做到的，只不過是笨拙地模仿先人罷了。但是，哪怕是如此愚鈍的我還是有一點可以向您保證……賭上家族的榮耀，我一定會為您帶來光榮的勝利。", "0", "cv_sk_Julius_3", "0", "0"},
[4000100104] = {4000100104, 10001001, 5, 4, "0", "idle", "這是由我們家族舉辦的宴會，而作為長女，待會我必須為來賓們進行一番演講，宣說家族的誓言、使命與榮耀。屆時……您也會在旁聆聽的吧？", "私の家族が主催するパーティーですから、私は長女として、家族の誓いと使命、そして栄光を誓うスピーチをしなければなりません。……もしよろしければ、側にいていただけますか？", "0", "0", "在這裡停留了這麼久，難道說領航已經很累了嗎？沒關係的，您去休息好了，這裡交給我就行了。", "0", "cv_sk_Julius_4", "0", "0"},
[4000100105] = {4000100105, 10001001, 6, 4, "0", "idle", "穿著高跟鞋，還非得跳華爾滋……在舞會上我會盡力避免失態的，還希望您多多擔待，我的舞伴。", "ハイヒールを履いて、ワルツを踴らなければいけないなんて……恥ずかしいところをお見せしないように精一杯頑張りますから、パートナーとして、どうかご協力をお願いいたします。", "0", "0", "領航，你有看到查麗莎嗎？今天她又沒來訓練……每次也不請一個假，真是讓人擔心的傢伙……", "0", "cv_sk_Julius_30", "0", "0"},
[4000100106] = {4000100106, 10001001, 7, 5, "1_》_0_0.8", "level1", "都說不用這麼奢華的衣服了，可母親大人她還是……誒？領航認為很適合我嗎？那……雖然不太習慣，以後在您面前我就再嘗試一些吧。", "こんなに豪華なドレスは必要ないと申し上げたのに、母上はまた……え？似合う、ですか？でしたら……まだ慣れませんが、あなた様の前では色々試してみましょうか。", "0", "0", "成為駕駛員的理由？啊，一方面是因為我自己本身就非常憧憬這樣的生活，另一方面則是因為我的父親……", "0", "cv_sk_Julius_31", "0", "0"},
[4000100107] = {4000100107, 10001001, 8, 5, "1_》_0_0.8", "level2", "領航需要喝點什麼嗎？綠茶，還是紅酒？抱歉……家中僅備有這類略帶苦味的飲品，據長輩說，這種習慣是源於一句古老的家訓：榮耀的味道是苦的。", "ナビゲーター、お飲み物はいかがですか？緑茶か、赤ワインか……申し訳ありません。ここでは、やや苦味のある飲み物だけをご用意させていただいております。栄光の味は苦いという、先代から伝わる家訓によるものです。", "0", "0", "謝謝關心，但是還請您注意形象。", "0", "cv_sk_Julius_5", "0", "0"},
[4000100108] = {4000100108, 10001001, 9, 5, "1_》_0_0.8", "level3", "對了，母親大人一直很想親自見見您，她常被評價為手腕強勢的貴婦人，也許會說些較為尖銳的話，但那只是算種……考驗？總之，還請您放心。", "そういえば、母上がずっとあなた様にお會いしたがっていました。母上は「手ごわい貴婦人」と言われ、言葉にも遠慮のないところがあるのですが、それも一種の……テストのようなものです。あまりご心配されなくても大丈夫ですよ。", "0", "0", "怎麼了？我的裝備穿錯了嗎？抱歉，我馬上檢討。", "0", "cv_sk_Julius_6", "0", "0"},
[4000100109] = {4000100109, 10001001, 10, 5, "1_》_0_0.8", "level4", "關於我小時候？嗯……那時整天都得上各種課，尤其以馬術課最難熬，為了讓我克服，父親特意買了個大型獨角獸玩偶給我。我很喜歡它，至今還妥善保存著，待會要一起試試嗎？", "私の子供の頃ですか？そうですね……色々な習い事をしたのですが、乗馬が一番苦手でしたね。でも頑張れるように、父上が大きなユニコーンのぬいぐるみを買ってくれたんです。とても気に入って、今でも大切にしているんですよ。後で一緒に見に行きませんか？", "0", "0", "為什麼……會這麼在意我。如果我有讓您不滿意的地方還請直接指出，老用這種眼神看著我，我也會……", "0", "cv_sk_Julius_7", "0", "0"},
[4000100110] = {4000100110, 10001001, 11, 5, "1_》_0_0.8", "level5", "非常感謝您願意陪我出席宴會，改天我也去您家做做客吧？不，不是指艾吉斯宿舍，而是您的故鄉……那個隨著記憶忘卻的地方，我想陪您一起尋找。", "今晩はパーティーにお付き合いくださり、ありがとうございました。いつかあなた様のお家にもお邪魔できたら嬉しいですね。ええ、アイギス寮ではなく、あなた様の故郷……記憶から失われた場所を、一緒に探してみたいのです。", "0", "0", "原來如此，最近我已經明白您的感受了。沒錯，現在的我和您心中想的事情是一樣的……但是在沒有結束這一切之前，只是這樣看著彼此，就足夠了。", "0", "cv_sk_Julius_8", "0", "0"},
[4000100111] = {4000100111, 10001001, 12, 6, "0", "0", "謝謝關心。", "お気遣い、ありがとうございます。", "0", "0", "謝謝關心。", "0", "cv_sk_Julius_9", "0", "0"},
[4000100112] = {4000100112, 10001001, 13, 7, "0", "0", "承蒙厚愛。", "そのお気持ち、ありがたく頂戴します。", "0", "0", "承蒙厚愛。", "0", "cv_sk_Julius_10", "0", "0"},
[4000100113] = {4000100113, 10001001, 14, 8, "0", "0", "終於抵達這個高度了嗎……領航，這份榮耀與您共用！", "やっとここまで辿り著くことができました…...ナビゲーター、この栄光をあなた様と共に！", "0", "0", "終於抵達這個高度了嗎……領航，這份榮耀與您共用！", "0", "cv_sk_Julius_11", "0", "0"},
[4000100114] = {4000100114, 10001001, 15, 9, "0", "0", "到底還要再揮動多少次劍，才能抵達那個高度呢？", "あとどれほど剣を振り回せば、あそこにたどり著けるのでしょう。", "0", "0", "到底還要再揮動多少次劍，才能抵達那個高度呢？", "0", "cv_sk_Julius_12", "0", "0"},
[4000100115] = {4000100115, 10001001, 16, 10, "0", "0", "大家，向著勝利前進吧！", "皆、勝利に向かって進みましょう！", "0", "0", "大家，向著勝利前進吧！", "0", "cv_sk_Julius_13", "0", "0"},
[4000100116] = {4000100116, 10001001, 17, 11, "0", "0", "勝利……很光榮吧？", "勝利とは、輝かしいものです。", "0", "0", "勝利……很光榮吧？", "0", "cv_sk_Julius_14", "0", "0"},
[4000100117] = {4000100117, 10001001, 18, 12, "0", "0", "任務完成，一起回去吧。", "ミッション完了です。一緒に帰りましょう。", "0", "0", "任務完成，一起回去吧。", "0", "cv_sk_Julius_15", "0", "0"},
[4000100118] = {4000100118, 10001001, 19, 13, "0", "0", "雖然還有些小遺憾，但是，還是恭喜大家了。", "至らない點も少々ありましたが、おめでとうございます。", "0", "0", "雖然還有些小遺憾，但是，還是恭喜大家了。", "0", "cv_sk_Julius_16", "0", "0"},
[4000100119] = {4000100119, 10001001, 20, 14, "0", "0", "……沒能完成對您的承諾，非常抱歉。", "……あなた様との約束を果たせなくて、申し訳ありません。", "0", "0", "……沒能完成對您的承諾，非常抱歉。", "0", "cv_sk_Julius_17", "0", "0"},
[4000100120] = {4000100120, 10001001, 21, 15, "0", "0", "請離開這場宴會。", "ご退席願います。", "0", "0", "哼，解決了呢。", "0", "cv_sk_Julius_18", "0", "0"},
[4000100121] = {4000100121, 10001001, 23, 16, "0", "0", "刀與叉。", "ナイフとフォーク。", "0", "0", "喝——哈啊!", "0", "cv_sk_Julius_19", "0", "0"},
[4000100122] = {4000100122, 10001001, 26, 19, "0", "0", "實在是失態……", "なんという失態……", "0", "0", "讓您失望了……", "0", "cv_sk_Julius_20", "0", "0"},
[4000100123] = {4000100123, 10001001, 24, 17, "0", "0", "酒與燭。", "ワインとキャンドル。", "0", "0", "完全不夠！", "0", "cv_sk_Julius_21", "0", "0"},
[4000100124] = {4000100124, 10001001, 25, 18, "0", "0", "這就是賭上了朱利烏斯之名的——全力一擊！！！！！！！！！！！", "ユリウスの名をかけた――會心の一撃！！！！！！！！！！", "0", "0", "這就是賭上了朱利烏斯之名的——全力一擊！！！！！！！！！！！", "0", "cv_sk_Julius_22", "0", "0"},
[4000100125] = {4000100125, 10001001, 27, 20, "0", "0", "麻煩您了。", "お願いします。", "0", "0", "麻煩您了。", "0", "cv_sk_Julius_23", "0", "0"},
[4000100126] = {4000100126, 10001001, 28, 21, "0", "0", "怎麼了？您累了嗎？", "どうしましたか？疲れましたか？", "0", "0", "怎麼了？您累了嗎？", "0", "cv_sk_Julius_24", "0", "0"},
[4000100127] = {4000100127, 10001001, 29, 21, "0", "0", "不用太勉強自己，能享受到領航的服務，我已經很滿足了。", "あまり無理しないでください。ナビゲーターにもてなして頂いて、もう十分幸せです。", "0", "0", "不用太勉強自己，能享受到領航的服務，我已經很滿足了。", "0", "cv_sk_Julius_25", "0", "0"},
[4000100128] = {4000100128, 10001001, 30, 22, "0", "0", "還請多加小心。", "どうかお気を付けください。", "0", "0", "還請多加小心。", "0", "cv_sk_Julius_26", "0", "0"},
[4000100129] = {4000100129, 10001001, 31, 23, "0", "0", "還請放輕鬆，無論結果如何我都不會責備您的。", "リラックスしてください。どんな結果になったとしても、責めたりはしませんから。", "0", "0", "還請放輕鬆，無論結果如何我都不會責備您的。", "0", "cv_sk_Julius_27", "0", "0"},
[4000100130] = {4000100130, 10001001, 32, 24, "0", "0", "謝謝您，每次都讓您費心了。", "いつも、ありがとうございます。", "0", "0", "謝謝您，每次都讓您費心了。", "0", "cv_sk_Julius_28", "0", "0"},
[4000100131] = {4000100131, 10001001, 33, 25, "0", "0", "我……我沒有責怪您的意思。", "わ、私は……あなた様を責める気はないのですが。", "0", "0", "我……我沒有責怪您的意思。", "0", "cv_sk_Julius_29", "0", "0"},
[4000100132] = {4000100132, 10001001, 34, 26, "0", "0", "在宴會進行得正熱烈時，就這樣兩人獨處，靜靜待著也不錯呢。", "パーティーの喧騒から離れて、二人きりで靜かに過ごすのも悪くありませんね。", "0", "0", "歡迎回來，領航。今天也讓我們一起為了榮耀而戰鬥吧。", "0", "cv_sk_Julius_32", "0", "0"},
[4000100133] = {4000100133, 10001001, 35, 27, "0", "0", "在旅途結束之前，我都將成為您最牢固的盾以及最鋒利的劍。", "この旅が終わるまで、あなた様の一番丈夫な盾、そして一番鋭利な剣であり続けると誓いましょう。", "0", "0", "在旅途結束之前，我都將成為您最牢固的盾以及最鋒利的劍。", "0", "cv_sk_Julius_34", "0", "0"},
[4000100134] = {4000100134, 10001001, 36, 28, "0", "0", "向著更高點邁進吧。", "もっと高い目標に向かって進んでいきましょう。", "0", "0", "向著更高點邁進吧。", "0", "cv_sk_Julius_35", "0", "0"},
[4000100135] = {4000100135, 10001001, 37, 29, "0", "0", "大家都在等著您呢。", "皆、あなた様を待っていますよ。", "0", "0", "大家都在等著您呢。", "0", "cv_sk_Julius_36", "0", "0"},
[4000100136] = {4000100136, 10001001, 38, 30, "0", "0", "有新的夥伴加入是件令人高興的事呢。", "新しい仲間が加わるなんて、嬉しいですね。", "0", "0", "有新的夥伴加入是件令人高興的事呢。", "0", "cv_sk_Julius_37", "0", "0"},
[4000100137] = {4000100137, 10001001, 39, 31, "0", "0", "新式的裝備真是令人期待啊。", "新しい裝備、楽しみですね。", "0", "0", "新式的裝備真是令人期待啊。", "0", "cv_sk_Julius_38", "0", "0"},
[4000100138] = {4000100138, 10001001, 40, 32, "0", "0", "補充一下物資吧。", "物資を補充しましょう。", "0", "0", "補充一下物資吧。", "0", "cv_sk_Julius_39", "0", "0"},
[4000100139] = {4000100139, 10001001, 41, 33, "0", "0", "確認下自己的狀況也很重要呢。", "自分の狀況を確認するというのも大事なことです。", "0", "0", "確認下自己的狀況也很重要呢。", "0", "cv_sk_Julius_40", "0", "0"},
[4000100140] = {4000100140, 10001001, 42, 34, "0", "0", "變更設定，說不定會對戰鬥有利。", "設定を変更すると、戦いに役立つかもしれません。", "0", "0", "變更設置，說不定會對戰鬥有利。", "0", "cv_sk_Julius_41", "0", "0"},
[4000100141] = {4000100141, 10001001, 43, 35, "0", "0", "有新的來信嗎？", "新しいメールが屆いていたのでしょうか？", "0", "0", "有新的來信嗎？", "0", "cv_sk_Julius_42", "0", "0"},
[4000100142] = {4000100142, 10001001, 44, 36, "0", "0", "有必要交流下情報呢。", "情報交換は必要ですよ。", "0", "0", "有必要交流下情報呢。", "0", "cv_sk_Julius_43", "0", "0"},
[4000100143] = {4000100143, 10001001, 45, 37, "0", "0", "確認一下吧。", "確認しましょう。", "0", "0", "確認一下吧。", "0", "cv_sk_Julius_44", "0", "0"},
[4000100200] = {4000100200, 10001002, 1, 1, "0", "0", "蒼霧殘響。", "0", "0", "0", "0", "0", "cv_sk1_Julius_33", "0", "0"},
[4000100201] = {4000100201, 10001002, 2, 2, "0", "0", "我絕對不會辜負您的期待。", "0", "0", "0", "0", "0", "cv_sk1_Julius_2", "0", "0"},
[4000100202] = {4000100202, 10001002, 3, 3, "0", "0", "朱利烏斯·馮·尼采，從現在起將作為您最出色的部下，為了我們共同的榮耀而戰鬥。", "0", "0", "0", "0", "0", "cv_sk1_Julius_1", "0", "0"},
[4000100203] = {4000100203, 10001002, 4, 4, "0", "idle", "如同號角般的轟鳴聲，如同戰歌般的喝彩聲，如同劍戟相接般的急刹聲……賽場如戰場，我也按耐不住想加入這場熱血沸騰的戰鬥。", "0", "0", "0", "0", "0", "cv_sk1_Julius_3", "0", "0"},
[4000100204] = {4000100204, 10001002, 5, 4, "0", "idle", "領航，車輛的裏裏外外我都檢查妥當了，唯一沒法確認的就是身為賽車手的你了。", "0", "0", "0", "0", "0", "cv_sk1_Julius_4", "0", "0"},
[4000100205] = {4000100205, 10001002, 6, 4, "0", "idle", "你聞到了嗎？車胎與地面摩擦後殘留的焦灼氣味。這是賽車手們在賽場上激烈對抗的證明。我十分期待領航您的表現，想必會將比賽的刺激程度提升至新的臺階。", "0", "0", "0", "0", "0", "cv_sk1_Julius_30", "0", "0"},
[4000100206] = {4000100206, 10001002, 7, 5, "15_1_0_0.8", "touch1", "賽車手是與駕駛員同等榮耀的職業。相比於巨大化的身軀，由金屬和橡膠組成的賽車更加難以控制。但賽車手們卻能做到如臂使指，這正是我所追求的境界。", "0", "0", "0", "0", "0", "cv_sk1_Julius_31", "0", "0"},
[4000100207] = {4000100207, 10001002, 8, 5, "15_2_0_0.8", "touch2", "賽場上的熱浪湧起，令我一時間分不清是太陽的熱量還是賽場上燃燒的鬥志。", "0", "0", "0", "0", "0", "cv_sk1_Julius_5", "0", "0"},
[4000100208] = {4000100208, 10001002, 9, 5, "15_1_0_0.8", "touch1", "今天的烈陽似火，賽道都像要被陽光烤焦。領航您可一定要注意補水，不要影響接下來的比賽發揮。", "0", "0", "0", "0", "0", "cv_sk1_Julius_6", "0", "0"},
[4000100209] = {4000100209, 10001002, 10, 5, "15_1_0_0.8", "touch1", "賽車是一項考研精神力和反應力的運動，而這正是領航您最擅長的能力之一。雖然是第一次參加賽車比賽，但是我知道您有爭奪第一的實力。", "0", "0", "0", "0", "0", "cv_sk1_Julius_7", "0", "0"},
[4000100210] = {4000100210, 10001002, 11, 5, "15_2_0_0.8", "touch2", "賽車的訣竅不是超越所有人，而是找到屬於自己的路線，只要找到屬於自己的路線，終點線自然會出現在前方。我就在終點線那等待您的沖線。", "0", "0", "0", "0", "0", "cv_sk1_Julius_8", "0", "0"},
[4000100211] = {4000100211, 10001002, 12, 6, "0", "0", "謝謝關心。", "0", "0", "0", "0", "0", "cv_sk1_Julius_9", "0", "0"},
[4000100212] = {4000100212, 10001002, 13, 7, "0", "0", "承蒙厚愛。", "0", "0", "0", "0", "0", "cv_sk1_Julius_10", "0", "0"},
[4000100213] = {4000100213, 10001002, 14, 8, "0", "0", "終於抵達這個高度了嗎……領航，這份榮耀與您共用！", "0", "0", "0", "0", "0", "cv_sk1_Julius_11", "0", "0"},
[4000100214] = {4000100214, 10001002, 15, 9, "0", "0", "到底還要再揮動多少次劍，才能抵達那個高度呢？", "0", "0", "0", "0", "0", "cv_sk1_Julius_12", "0", "0"},
[4000100215] = {4000100215, 10001002, 16, 10, "0", "0", "大家，向著勝利前進吧！", "0", "0", "0", "0", "0", "cv_sk1_Julius_13", "0", "0"},
[4000100216] = {4000100216, 10001002, 17, 11, "0", "0", "勝利……很光榮吧？", "0", "0", "0", "0", "0", "cv_sk1_Julius_14", "0", "0"},
[4000100217] = {4000100217, 10001002, 18, 12, "0", "0", "任務完成，一起回去吧。", "0", "0", "0", "0", "0", "cv_sk1_Julius_15", "0", "0"},
[4000100218] = {4000100218, 10001002, 19, 13, "0", "0", "雖然還有些小遺憾，但是，還是恭喜大家了。", "0", "0", "0", "0", "0", "cv_sk1_Julius_16", "0", "0"},
[4000100219] = {4000100219, 10001002, 20, 14, "0", "0", "……沒能完成對您的承諾，非常抱歉。", "0", "0", "0", "0", "0", "cv_sk1_Julius_17", "0", "0"},
[4000100220] = {4000100220, 10001002, 21, 15, "0", "0", "彎道超車！", "0", "0", "0", "0", "0", "cv_sk1_Julius_18", "0", "0"},
[4000100221] = {4000100221, 10001002, 23, 16, "0", "0", "衝刺！", "0", "0", "0", "0", "0", "cv_sk1_Julius_19", "0", "0"},
[4000100222] = {4000100222, 10001002, 26, 19, "0", "0", "失敗了啊……", "0", "0", "0", "0", "0", "cv_sk1_Julius_20", "0", "0"},
[4000100223] = {4000100223, 10001002, 24, 17, "0", "0", "向著終點加速吧！", "0", "0", "0", "0", "0", "cv_sk1_Julius_21", "0", "0"},
[4000100224] = {4000100224, 10001002, 25, 18, "0", "0", "這就是賭上了朱利烏斯之名的——全力一擊！！！！！！！！！！！", "0", "0", "0", "0", "0", "cv_sk1_Julius_22", "0", "0"},
[4000100225] = {4000100225, 10001002, 27, 20, "0", "0", "麻煩您了。", "0", "0", "0", "0", "0", "cv_sk1_Julius_23", "0", "0"},
[4000100226] = {4000100226, 10001002, 28, 21, "0", "0", "怎麼了？您累了嗎？", "0", "0", "0", "0", "0", "cv_sk1_Julius_24", "0", "0"},
[4000100227] = {4000100227, 10001002, 29, 21, "0", "0", "不用太勉強自己，能享受到領航的服務，我已經很滿足了。", "0", "0", "0", "0", "0", "cv_sk1_Julius_25", "0", "0"},
[4000100228] = {4000100228, 10001002, 30, 22, "0", "0", "還請多加小心。", "0", "0", "0", "0", "0", "cv_sk1_Julius_26", "0", "0"},
