[4000100317] = {4000100317, 10001003, 18, 12, "0", "0", "任務完成，一起回去吧。", "0", "0", "0", "0", "0", "cv_sk2_Julius_15", "0", "0"},
[4000100318] = {4000100318, 10001003, 19, 13, "0", "0", "雖然還有些小遺憾，但是，還是恭喜大家了。", "0", "0", "0", "0", "0", "cv_sk2_Julius_16", "0", "0"},
[4000100319] = {4000100319, 10001003, 20, 14, "0", "0", "……沒能完成對您的承諾，非常抱歉。", "0", "0", "0", "0", "0", "cv_sk2_Julius_17", "0", "0"},
[4000100320] = {4000100320, 10001003, 21, 15, "0", "0", "破壞節日的下場。", "祝日を台無しにした者の末路です。", "0", "0", "0", "0", "cv_sk2_Julius_18", "0", "0"},
[4000100321] = {4000100321, 10001003, 23, 16, "0", "0", "給你的禮物！", "これは、あなたへのプレゼントです！", "0", "0", "0", "0", "cv_sk2_Julius_19", "0", "0"},
[4000100322] = {4000100322, 10001003, 26, 19, "0", "0", "好冷……", "すごく、寒いです……", "0", "0", "0", "0", "cv_sk2_Julius_20", "0", "0"},
[4000100323] = {4000100323, 10001003, 24, 17, "0", "0", "要上了！", "全然足りません！", "0", "0", "0", "0", "cv_sk2_Julius_21", "0", "0"},
[4000100324] = {4000100324, 10001003, 25, 18, "0", "0", "這就是賭上了朱利烏斯之名的——全力一擊！！！！！！！！！！！", "0", "0", "0", "0", "0", "cv_sk2_Julius_22", "0", "0"},
[4000100325] = {4000100325, 10001003, 27, 20, "0", "0", "麻煩您了。", "0", "0", "0", "0", "0", "cv_sk2_Julius_23", "0", "0"},
[4000100326] = {4000100326, 10001003, 28, 21, "0", "0", "怎麼了？您累了嗎？", "0", "0", "0", "0", "0", "cv_sk2_Julius_24", "0", "0"},
[4000100327] = {4000100327, 10001003, 29, 21, "0", "0", "不用太勉強自己，能享受到領航的服務，我已經很滿足了。", "0", "0", "0", "0", "0", "cv_sk2_Julius_25", "0", "0"},
[4000100328] = {4000100328, 10001003, 30, 22, "0", "0", "還請多加小心。", "0", "0", "0", "0", "0", "cv_sk2_Julius_26", "0", "0"},
[4000100329] = {4000100329, 10001003, 31, 23, "0", "0", "還請放輕鬆，無論結果如何我都不會責備您的。", "0", "0", "0", "0", "0", "cv_sk2_Julius_27", "0", "0"},
[4000100330] = {4000100330, 10001003, 32, 24, "0", "0", "謝謝您，每次都讓您費心了。", "0", "0", "0", "0", "0", "cv_sk2_Julius_28", "0", "0"},
[4000100331] = {4000100331, 10001003, 33, 25, "0", "0", "我……我沒有責怪您的意思。", "0", "0", "0", "0", "0", "cv_sk2_Julius_29", "0", "0"},
[4000100332] = {4000100332, 10001003, 34, 26, "0", "0", "Me……MerryChristmas……領航。", "め、メリークリスマス……ナビゲーター。", "0", "0", "0", "0", "cv_sk2_Julius_32", "0", "0"},
[4000100333] = {4000100333, 10001003, 35, 27, "0", "0", "在旅途結束之前，我都將成為您最牢固的盾以及最鋒利的劍。", "0", "0", "0", "0", "0", "cv_sk2_Julius_34", "0", "0"},
[4000100334] = {4000100334, 10001003, 36, 28, "0", "0", "向著更高點邁進吧。", "0", "0", "0", "0", "0", "cv_sk2_Julius_35", "0", "0"},
[4000100335] = {4000100335, 10001003, 37, 29, "0", "0", "大家都在等著您呢。", "0", "0", "0", "0", "0", "cv_sk2_Julius_36", "0", "0"},
[4000100336] = {4000100336, 10001003, 38, 30, "0", "0", "有新的夥伴加入是件令人高興的事呢。", "0", "0", "0", "0", "0", "cv_sk2_Julius_37", "0", "0"},
[4000100337] = {4000100337, 10001003, 39, 31, "0", "0", "新式的裝備真是令人期待啊。", "0", "0", "0", "0", "0", "cv_sk2_Julius_38", "0", "0"},
[4000100338] = {4000100338, 10001003, 40, 32, "0", "0", "補充一下物資吧。", "0", "0", "0", "0", "0", "cv_sk2_Julius_39", "0", "0"},
[4000100339] = {4000100339, 10001003, 41, 33, "0", "0", "確認下自己的狀況也很重要呢。", "0", "0", "0", "0", "0", "cv_sk2_Julius_40", "0", "0"},
[4000100340] = {4000100340, 10001003, 42, 34, "0", "0", "變更設定，說不定會對戰鬥有利。", "0", "0", "0", "0", "0", "cv_sk2_Julius_41", "0", "0"},
[4000100341] = {4000100341, 10001003, 43, 35, "0", "0", "有新的來信嗎？", "0", "0", "0", "0", "0", "cv_sk2_Julius_42", "0", "0"},
[4000100342] = {4000100342, 10001003, 44, 36, "0", "0", "有必要交流下情報呢。", "0", "0", "0", "0", "0", "cv_sk2_Julius_43", "0", "0"},
[4000100343] = {4000100343, 10001003, 45, 37, "0", "0", "確認一下吧。", "0", "0", "0", "0", "0", "cv_sk2_Julius_44", "0", "0"},
[4000900100] = {4000900100, 10009001, 1, 1, "0", "0", "蒼霧殘響", "0", "0", "0", "0", "0", "cv_sk_morgan_33", "0", "0"},
[4000900101] = {4000900101, 10009001, 2, 2, "0", "0", "我嗎…我明白了，我會好好協助領航您完成工作的。", "0", "0", "0", "0", "0", "cv_sk_morgan_2", "0", "0"},
[4000900102] = {4000900102, 10009001, 3, 3, "0", "0", "您好，領航。我是月冕的隊長，摩根勒菲，莉莉絲和斯卡蒂有給您添麻煩嗎？", "0", "0", "0", "0", "0", "cv_sk_morgan_1", "0", "0"},
[4000900103] = {4000900103, 10009001, 4, 4, "0", "idle", "在創作新魔術的時候出現失誤了……但，但是，這麼嚴重的失誤，還是第一次遇到……", "0", "0", "0", "0", "0", "cv_sk_morgan_3", "0", "0"},
[4000900104] = {4000900104, 10009001, 5, 4, "0", "idle", "不斷地為觀眾帶來新的魔術，讓他們臉上展露笑容，是一件很開心的事情。", "0", "0", "0", "0", "0", "cv_sk_morgan_4", "0", "0"},
[4000900105] = {4000900105, 10009001, 6, 4, "0", "idle", "領航，加油噢。", "0", "0", "0", "0", "0", "cv_sk_morgan_30", "0", "0"},
[4000900106] = {4000900106, 10009001, 7, 5, "15_1_0_0.8", "touch1", "嗯……讓您看到我這副樣子，真是不好意思，魔術師應該隨時都準備著魔術滿足觀眾才對！", "0", "0", "0", "0", "0", "cv_sk_morgan_31", "0", "0"},
[4000900107] = {4000900107, 10009001, 8, 5, "15_2_0_0.8", "touch2", "嗯……這裡的動作，稍微有點複雜，之後讓我手把手指導您的動作吧，但是首先……我得先擺脫這些道具。", "0", "0", "0", "0", "0", "cv_sk_morgan_5", "0", "0"},
[4000900108] = {4000900108, 10009001, 9, 5, "15_1_0_0.8", "touch1", "呀——啊！又搞砸了……嘿嘿，但是我能想像得到，這個魔術要是成功的話，大家一定會非常驚訝的，讓我們一起加油吧。", "0", "0", "0", "0", "0", "cv_sk_morgan_6", "0", "0"},
[4000900109] = {4000900109, 10009001, 10, 5, "15_1_0_0.8", "touch1", "……完蛋了，好像越來越亂了。那個……領，領航……如果可以的話，能不能幫幫我？", "0", "0", "0", "0", "0", "cv_sk_morgan_7", "0", "0"},
[4000900110] = {4000900110, 10009001, 11, 5, "15_2_0_0.8", "touch2", "又是在這裡出錯……嗚……不過錯誤的經歷經過積累，一定能成為我們成功的魔術。來，請搭著我的手，把我解救出來吧，讓我們再來一次。", "0", "0", "0", "0", "0", "cv_sk_morgan_8", "0", "0"},
[4000900111] = {4000900111, 10009001, 12, 6, "0", "0", "謝謝，這下變得更強了呢。", "0", "0", "0", "0", "0", "cv_sk_morgan_9", "0", "0"},
[4000900112] = {4000900112, 10009001, 13, 7, "0", "0", "謝謝…我一定不會辜負領航您的期望的。", "0", "0", "0", "0", "0", "cv_sk_morgan_10", "0", "0"},
[4000900113] = {4000900113, 10009001, 14, 8, "0", "0", "不知不覺我也成長了許多…如果沒有領航的話，我一個人是不可能做到的。謝謝您，領航，今後也和我一起守護大家吧。", "0", "0", "0", "0", "0", "cv_sk_morgan_11", "0", "0"},
[4000900114] = {4000900114, 10009001, 15, 9, "0", "0", "這份力量，我會好好使用的。", "0", "0", "0", "0", "0", "cv_sk_morgan_12", "0", "0"},
[4000900115] = {4000900115, 10009001, 16, 10, "0", "0", "傷害同伴的人…在哪？", "0", "0", "0", "0", "0", "cv_sk_morgan_13", "0", "0"},
[4000900116] = {4000900116, 10009001, 17, 11, "0", "0", "敵人全滅，我們勝利了，領航。", "0", "0", "0", "0", "0", "cv_sk_morgan_14", "0", "0"},
[4000900117] = {4000900117, 10009001, 18, 12, "0", "0", "我需要得做更好才行…不然……", "0", "0", "0", "0", "0", "cv_sk_morgan_15", "0", "0"},
[4000900118] = {4000900118, 10009001, 19, 13, "0", "0", "大家…還好嗎？", "0", "0", "0", "0", "0", "cv_sk_morgan_16", "0", "0"},
[4000900119] = {4000900119, 10009001, 20, 14, "0", "0", "…振作起來，領航，還沒有結束。", "0", "0", "0", "0", "0", "cv_sk_morgan_17", "0", "0"},
[4000900120] = {4000900120, 10009001, 21, 15, "0", "0", "不能放鬆警惕。", "0", "0", "0", "0", "0", "cv_sk_morgan_18", "0", "0"},
[4000900121] = {4000900121, 10009001, 23, 16, "0", "0", "Magic，S.T.A.R.T!!", "0", "0", "0", "0", "0", "cv_sk_morgan_19", "0", "0"},
[4000900122] = {4000900122, 10009001, 26, 19, "0", "0", "最後的大魔術……", "0", "0", "0", "0", "0", "cv_sk_morgan_20", "0", "0"},
[4000900123] = {4000900123, 10009001, 24, 17, "0", "0", "不會讓你們逃走的！", "0", "0", "0", "0", "0", "cv_sk_morgan_21", "0", "0"},
[4000900124] = {4000900124, 10009001, 25, 18, "0", "0", "請看著吧，這是我為您準備的華麗演出。", "0", "0", "0", "0", "0", "cv_sk_morgan_22", "0", "0"},
[4000900125] = {4000900125, 10009001, 27, 20, "0", "0", "領航，麻煩您了。", "0", "0", "0", "0", "0", "cv_sk_morgan_23", "0", "0"},
[4000900126] = {4000900126, 10009001, 28, 21, "0", "0", "以前，和父母流亡的時候，都沒辦法像這樣靜下心來放鬆呢……", "0", "0", "0", "0", "0", "cv_sk_morgan_24", "0", "0"},
[4000900127] = {4000900127, 10009001, 29, 21, "0", "0", "莉莉絲來過了嗎…您被她嚇到了？真是的…之後我會好好跟她溝通的，讓她不要再這麼做了。", "0", "0", "0", "0", "0", "cv_sk_morgan_25", "0", "0"},
[4000900128] = {4000900128, 10009001, 30, 22, "0", "0", "領航，請小心。", "0", "0", "0", "0", "0", "cv_sk_morgan_26", "0", "0"},
[4000900129] = {4000900129, 10009001, 31, 23, "0", "0", "猜對了的話…我給您表演一個魔術吧？", "0", "0", "0", "0", "0", "cv_sk_morgan_27", "0", "0"},
[4000900130] = {4000900130, 10009001, 32, 24, "0", "0", "——嘿！玫瑰花出現了，如何，厲害吧？", "0", "0", "0", "0", "0", "cv_sk_morgan_28", "0", "0"},
[4000900131] = {4000900131, 10009001, 33, 25, "0", "0", "沒關係，我相信領航您下次一定會成功的……", "0", "0", "0", "0", "0", "cv_sk_morgan_29", "0", "0"},
[4000900132] = {4000900132, 10009001, 34, 26, "0", "0", "哦，助手先生今天也很早就來了呢，那麼在準備過後，我們就開始吧。", "0", "0", "0", "0", "0", "cv_sk_morgan_32", "0", "0"},
[4000900133] = {4000900133, 10009001, 35, 27, "0", "0", "不戰鬥的話…就無法保護大家，不是嗎？", "0", "0", "0", "0", "0", "cv_sk_morgan_34", "0", "0"},
[4000900134] = {4000900134, 10009001, 36, 28, "0", "0", "不要太勉強哦。", "0", "0", "0", "0", "0", "cv_sk_morgan_35", "0", "0"},
[4000900135] = {4000900135, 10009001, 37, 29, "0", "0", "大家，都要乖乖的噢？", "0", "0", "0", "0", "0", "cv_sk_morgan_36", "0", "0"},
[4000900136] = {4000900136, 10009001, 38, 30, "0", "0", "要為新來的同伴準備禮物才行。", "0", "0", "0", "0", "0", "cv_sk_morgan_37", "0", "0"},
[4000900137] = {4000900137, 10009001, 39, 31, "0", "0", "要購入新裝備嗎？", "0", "0", "0", "0", "0", "cv_sk_morgan_38", "0", "0"},
[4000900138] = {4000900138, 10009001, 40, 32, "0", "0", "有好好做購物規劃嗎？", "0", "0", "0", "0", "0", "cv_sk_morgan_39", "0", "0"},
[4000900139] = {4000900139, 10009001, 41, 33, "0", "0", "請看個人信息。", "0", "0", "0", "0", "0", "cv_sk_morgan_40", "0", "0"},
[4000900140] = {4000900140, 10009001, 42, 34, "0", "0", "要看仔細哦。", "0", "0", "0", "0", "0", "cv_sk_morgan_41", "0", "0"},
[4000900141] = {4000900141, 10009001, 43, 35, "0", "0", "情書…不可能有吧？", "0", "0", "0", "0", "0", "cv_sk_morgan_42", "0", "0"},
[4000900142] = {4000900142, 10009001, 44, 36, "0", "0", "有需要幫助的人嗎？", "0", "0", "0", "0", "0", "cv_sk_morgan_43", "0", "0"},
[4000900143] = {4000900143, 10009001, 45, 37, "0", "0", "真有趣呢。", "0", "0", "0", "0", "0", "cv_sk_morgan_44", "0", "0"},
[4001000100] = {4001000100, 10010001, 1, 1, "0", "0", "蒼霧殘響。", "0", "0", "0", "0", "0", "cv_sk_alaita_32", "0", "0"},
[4001000101] = {4001000101, 10010001, 2, 2, "0", "0", "可不要看我看入迷了喔，那樣會耽誤工作的。", "0", "0", "0", "0", "0", "cv_sk_alaita_2", "0", "0"},
[4001000102] = {4001000102, 10010001, 3, 3, "0", "0", "第三研究室防衛班，阿萊塔。我家的多洛莉絲隊長受你照顧了，謝謝~", "0", "0", "0", "0", "0", "cv_sk_alaita_1", "0", "0"},
[4001000103] = {4001000103, 10010001, 4, 4, "0", "idle", "沒見過嗎？“海妖”真正的面目。這個狀態下的歌聲會更好聽噢。", "見たことがないの？セイレーンの本當の姿を。この姿の時は、本當に素晴らしい歌聲になるんだから。", "0", "0", "0", "0", "cv_sk_alaita_3", "0", "0,idle"},
[4001000104] = {4001000104, 10010001, 5, 4, "0", "idle", "希望你能永遠記住此刻，我將以最美的姿態來為你演唱。", "この瞬間のことを、永遠に忘れないで。最も美しい姿で、あなたのために歌っている私のことを。", "0", "0", "0", "0", "cv_sk_alaita_4", "0", "0,idle"},
[4001000105] = {4001000105, 10010001, 6, 4, "0", "idle", "多洛莉絲隊長還沒見過我現在的樣子。呵呵，要是被看到了不知道會不會被嚇一跳呢。", "ドロリィス隊長は、この姿をまだ見たことがないの。ふふ、見たらびっくりするかしら。", "0", "0", "0", "0", "cv_sk_alaita_29", "0", "0,idle"},
[4001000106] = {4001000106, 10010001, 7, 5, "15_1_0_0.8", "leve2", "曇花的哀傷在於綻放的刹那無人欣賞，所幸我能有你，來共度這盛放的瞬間。", "月下美人が悲しいのは、花咲く瞬間に立ち會ってくれる人がいないこと。でも私には、花咲く瞬間を共に過ごしてくれるあなたがいるの。", "0", "0", "0", "0", "cv_sk_alaita_30", "0", "0,leve2"},
[4001000107] = {4001000107, 10010001, 8, 5, "15_2_0_0.8", "leve1", "等……等一下，先別碰那裏……", "ちょっと……やめて、そこは觸らないで……", "0", "0", "0", "0", "cv_sk_alaita_5", "0", "0,leve1"},
[4001000108] = {4001000108, 10010001, 9, 5, "15_3_0_0.8", "leve3", "就算只有我們兩個人，那裏也是危險的禁區噢。", "ふたりきりだからって、そこは觸れていい場所じゃないわよ。", "0", "0", "0", "0", "cv_sk_alaita_6", "0", "0,leve3"},
[4001000109] = {4001000109, 10010001, 10, 5, "15_2_0_0.8", "leve1", "呼……呼……感覺有些困了。領航，與我一同沉入夢境的海灣，好嗎？", "（あくび）ふぁ……んん……なんだか眠いわね。ナビゲーター。このまま一緒に夢の海に沈んでいかない？", "0", "0", "0", "0", "cv_sk_alaita_7", "0", "0,leve1"},
[4001000110] = {4001000110, 10010001, 11, 5, "15_1_0_0.8", "leve2", "為了今日的幽約我已經準備許久，這件衣服只為領航你一人而穿著，也只有領航你一人能解開我衣領上的紐扣。", "今日のために、ずっと準備して來たの。この服、あなたのために著て來たのよ。この服のボタンを外していいのも、あなただけ。", "0", "0", "0", "0", "cv_sk_alaita_8", "0", "0,leve2"},
[4001000111] = {4001000111, 10010001, 12, 6, "0", "0", "不錯的感覺。", "0", "0", "0", "0", "0", "cv_sk_alaita_9", "0", "0"},
[4001000112] = {4001000112, 10010001, 13, 7, "0", "0", "想看更華麗的演出嗎？", "0", "0", "0", "0", "0", "cv_sk_alaita_10", "0", "0"},
[4001000113] = {4001000113, 10010001, 14, 8, "0", "0", "呵呵……你能感受到嗎，這把劍正在發出喜悅的鳴聲呢。不，並不是在稱讚我的美麗。它一定是因為能夠再一次保護多瑙，保護薩爾而高興吧。", "0", "0", "0", "0", "0", "cv_sk_alaita_11", "0", "0"},
[4001000114] = {4001000114, 10010001, 15, 9, "0", "0", "讓我變得更加美麗吧。", "0", "0", "0", "0", "0", "cv_sk_alaita_12", "0", "0"},
[4001000115] = {4001000115, 10010001, 16, 10, "0", "0", "我負責表演，你負責喝彩！", "0", "0", "0", "0", "0", "cv_sk_alaita_13", "0", "0"},
