[4001000119] = {4001000119, 10010001, 20, 14, "0", "0", "嗯…真是一場失敗的演出，你不這樣認為嗎？", "0", "0", "0", "0", "0", "cv_sk_alaita_17", "0", "0"},
[4001000120] = {4001000120, 10010001, 21, 15, "0", "0", "在玫瑰的荊條下消散吧。", "バラのトゲに散りなさい。", "0", "0", "0", "0", "cv_sk_alaita_18", "0", "0"},
