[4001000122] = {4001000122, 10010001, 24, 17, "0", "0", "沉迷吧。", "もう目が離せないでしょ。", "0", "0", "0", "0", "cv_sk_alaita_21", "0", "0"},
[4001000123] = {4001000123, 10010001, 26, 19, "0", "0", "華麗的謝幕。", "終幕もまた美しく……ね。", "0", "0", "0", "0", "cv_sk_alaita_20", "0", "0"},
[4001000124] = {4001000124, 10010001, 27, 20, "0", "0", "喔？你來了啊。", "0", "0", "0", "0", "0", "cv_sk_alaita_22", "0", "0"},
[4001000125] = {4001000125, 10010001, 28, 21, "0", "0", "看入迷了嗎？不用害羞，稱讚我的美麗吧。", "0", "0", "0", "0", "0", "cv_sk_alaita_23", "0", "0"},
[4001000126] = {4001000126, 10010001, 29, 21, "0", "0", "情不自禁想哼歌呢…你準備了蠟來封耳朵嗎？", "0", "0", "0", "0", "0", "cv_sk_alaita_24", "0", "0"},
[4001000127] = {4001000127, 10010001, 30, 22, "0", "0", "呵…提高警惕，對嗎？", "0", "0", "0", "0", "0", "cv_sk_alaita_25", "0", "0"},
[4001000128] = {4001000128, 10010001, 31, 23, "0", "0", "這點幕布是遮擋不了我的星光的，對吧？", "0", "0", "0", "0", "0", "cv_sk_alaita_26", "0", "0"},
[4001000129] = {4001000129, 10010001, 32, 24, "0", "0", "不愧是領航~遺憾的是，沒有獎勵喔。", "0", "0", "0", "0", "0", "cv_sk_alaita_27", "0", "0"},
[4001000130] = {4001000130, 10010001, 33, 25, "0", "0", "下次再努力吧。", "0", "0", "0", "0", "0", "cv_sk_alaita_28", "0", "0"},
[4001000131] = {4001000131, 10010001, 34, 26, "0", "0", "歡迎來到你和我兩個人的秘密舞臺。", "あなたと私の秘密の舞臺にようこそ。", "0", "0", "0", "0", "cv_sk_alaita_31", "0", "0"},
[4001000132] = {4001000132, 10010001, 35, 27, "0", "0", "要執行任務了？我明白了，出發吧。", "0", "0", "0", "0", "0", "cv_sk_alaita_33", "0", "0"},
