[4001000139] = {4001000139, 10010001, 42, 34, "0", "0", "隨便吧。", "0", "0", "0", "0", "0", "cv_sk_alaita_40", "0", "0"},
[4001000140] = {4001000140, 10010001, 43, 35, "0", "0", "有邀請函嗎？", "0", "0", "0", "0", "0", "cv_sk_alaita_41", "0", "0"},
[4001000141] = {4001000141, 10010001, 44, 36, "0", "0", "遇到喜歡的人記得要聯繫方式喔。", "0", "0", "0", "0", "0", "cv_sk_alaita_42", "0", "0"},
[4001000142] = {4001000142, 10010001, 45, 37, "0", "0", "吼~", "0", "0", "0", "0", "0", "cv_sk_alaita_43", "0", "0"},
[4001100100] = {4001100100, 10011001, 1, 1, "0", "0", "蒼霧殘響。", "0", "0", "0", "0", "0", "cv_sk_ruoshui_32", "0", "0"},
[4001100101] = {4001100101, 10011001, 2, 2, "0", "0", "是，我會一直站在這等待您下一個命令的，領航哥哥。", "0", "0", "0", "0", "0", "cv_sk_ruoshui_2", "0", "0"},
[4001100102] = {4001100102, 10011001, 3, 3, "0", "0", "我的名字是弱水…眼睛？沒關係，我能看見您的，領航哥哥。", "0", "0", "0", "0", "0", "cv_sk_ruoshui_1", "0", "0"},
[4001100103] = {4001100103, 10011001, 4, 4, "0", "idle", "看不見我看不見我看不見我看不見我看不見我……", "見つかりませんように、見つかりませんように……", "0", "0", "0", "0", "cv_sk_ruoshui_3", "0", "0"},
[4001100104] = {4001100104, 10011001, 5, 4, "0", "idle", "領航哥哥！啊不，這位病人，你這樣在醫院內隨意走動是很危險的……請回到自己的病房。", "ナビゲーターのお兄さん！あ、いえ、患者さん、勝手に病院內を歩き回るのは危険なので……自分の病室に戻ってください。", "0", "0", "0", "0", "cv_sk_ruoshui_4", "0", "0"},
[4001100105] = {4001100105, 10011001, 6, 4, "0", "idle", "冥火告訴我，領航哥哥得了重病住院，一個人很危險……所以我才潛伏進來想要保護哥哥。可是看領航哥哥的樣子好像病得並不是很重。", "冥火さんが教えてくれたんです。ナビゲーターのお兄さんが重い病気で入院していて、ひとりじゃ危険だって…。…だから、お兄さんを守るために潛入しました。でも、お兄さんの様子からすると、そんなに重い病気でもなさそうですね。", "0", "0", "0", "0", "cv_sk_ruoshui_29", "0", "0"},
[4001100106] = {4001100106, 10011001, 7, 5, "15_1_0_0.8", "level1", "我是來暗中保護哥哥的！為了找出可能存在醫院的刺客，我必須偽裝自己。請哥哥也把我當作一個普通的護士來對待，千萬不要讓別人發現我們之間的關係。", "私はお兄さんを守るためにここに來たんです！刺客を見つけ出すためには、変裝しなくてはいけません。なので、お兄さんも私に看護師さんとして接してください。他の人に、私たちの関係を知られないように。", "0", "0", "0", "0", "cv_sk_ruoshui_30", "0", "0"},
[4001100107] = {4001100107, 10011001, 8, 5, "15_2_0_0.8", "level2", "不，不要靠近……小……小心刀子……", "ち、近づかないでください……ナ、ナイフが危ないので……", "0", "0", "0", "0", "cv_sk_ruoshui_5", "0", "0"},
[4001100108] = {4001100108, 10011001, 9, 5, "15_2_0_0.8", "level2", "從更衣室隨手拿的這件衣服太小了，電視劇裡可沒有講過遇到這種情況該怎麼辦。", "更衣室から取ってきたナース服、ちょっと小さすぎたかもしれません。こういうときはどうすれば…。ドラマでもやってませんでした。", "0", "0", "0", "0", "cv_sk_ruoshui_6", "0", "0"},
[4001100109] = {4001100109, 10011001, 10, 5, "15_2_0_0.8", "level2", "哥哥放心養病，弱水會保護哥哥，絕不會讓任何可疑的人接近病房。", "お兄さんは安心して休んでください。弱水がお守りしますし、不審者は病室に近づかせません。", "0", "0", "0", "0", "cv_sk_ruoshui_7", "0", "0"},
[4001100110] = {4001100110, 10011001, 11, 5, "15_1_0_0.8", "level1", "等哥哥病好了，一切去看電影吧。算算時間，應該正好可以趕上那部電影的首映……就這樣說好了哦！", "お兄さんが快復したら、映畫に行きましょう。日程的には、ちょうどあの映畫のプレミア上映に間に合うはずなので……よし、決まりですね！", "0", "0", "0", "0", "cv_sk_ruoshui_8", "0", "0"},
[4001100111] = {4001100111, 10011001, 12, 6, "0", "0", "我升級了欸！", "0", "0", "0", "0", "0", "cv_sk_ruoshui_9", "0", "0"},
[4001100112] = {4001100112, 10011001, 13, 7, "0", "0", "武器變鋒利了！", "0", "0", "0", "0", "0", "cv_sk_ruoshui_10", "0", "0"},
[4001100113] = {4001100113, 10011001, 14, 8, "0", "0", "真是不可思議呢…力量在源源不斷地湧出。嗯，決定了，這份力量，這份強大，只為領航您而存在。今後，不管是什麼樣的敵人，“弱水”都會為了您，將他擊潰！", "0", "0", "0", "0", "0", "cv_sk_ruoshui_11", "0", "0"},
[4001100114] = {4001100114, 10011001, 15, 9, "0", "0", "速度變快了！", "0", "0", "0", "0", "0", "cv_sk_ruoshui_12", "0", "0"},
[4001100115] = {4001100115, 10011001, 16, 10, "0", "0", "瞭解，作戰開始。", "0", "0", "0", "0", "0", "cv_sk_ruoshui_13", "0", "0"},
[4001100116] = {4001100116, 10011001, 17, 11, "0", "0", "任務完成——領航，我們回去吧。", "0", "0", "0", "0", "0", "cv_sk_ruoshui_14", "0", "0"},
[4001100117] = {4001100117, 10011001, 18, 12, "0", "0", "我沒事…但是有傷員需要治療，領航。", "0", "0", "0", "0", "0", "cv_sk_ruoshui_15", "0", "0"},
[4001100118] = {4001100118, 10011001, 19, 13, "0", "0", "大家…還好嗎？", "0", "0", "0", "0", "0", "cv_sk_ruoshui_16", "0", "0"},
[4001100119] = {4001100119, 10011001, 20, 14, "0", "0", "不能就這樣放棄，領航……", "0", "0", "0", "0", "0", "cv_sk_ruoshui_17", "0", "0"},
[4001100120] = {4001100120, 10011001, 21, 15, "0", "0", "為了保護領航哥哥。", "お兄さんを守るために。", "0", "0", "0", "0", "cv_sk_ruoshui_18", "0", "0"},
[4001100121] = {4001100121, 10011001, 23, 16, "0", "0", "手術時間到了。", "手術の時間です。", "0", "0", "0", "0", "cv_sk_ruoshui_19", "0", "0"},
[4001100122] = {4001100122, 10011001, 24, 17, "0", "0", "全給我咽下去吧。", "全部飲んでください。", "0", "0", "0", "0", "cv_sk_ruoshui_21", "0", "0"},
[4001100123] = {4001100123, 10011001, 26, 19, "0", "0", "領航哥哥……你在……哪兒……", "お兄さん……どこに……いるんですか……", "0", "0", "0", "0", "cv_sk_ruoshui_20", "0", "0"},
[4001100124] = {4001100124, 10011001, 27, 20, "0", "0", "泡澡~泡澡~", "0", "0", "0", "0", "0", "cv_sk_ruoshui_22", "0", "0"},
[4001100125] = {4001100125, 10011001, 28, 21, "0", "0", "哥哥！水裡面有一條白色的大鯊魚——開玩笑的~", "0", "0", "0", "0", "0", "cv_sk_ruoshui_23", "0", "0"},
[4001100126] = {4001100126, 10011001, 29, 21, "0", "0", "哥哥，能幫我拿一聽碳酸飲料過來嗎~謝謝~", "0", "0", "0", "0", "0", "cv_sk_ruoshui_24", "0", "0"},
[4001100127] = {4001100127, 10011001, 30, 22, "0", "0", "是敵人嗎！？", "0", "0", "0", "0", "0", "cv_sk_ruoshui_25", "0", "0"},
[4001100128] = {4001100128, 10011001, 31, 23, "0", "0", "您的眼睛，能看見我嗎？", "0", "0", "0", "0", "0", "cv_sk_ruoshui_26", "0", "0"},
[4001100129] = {4001100129, 10011001, 32, 24, "0", "0", "好耶！哥哥是最棒的！", "0", "0", "0", "0", "0", "cv_sk_ruoshui_27", "0", "0"},
[4001100130] = {4001100130, 10011001, 33, 25, "0", "0", "嗚…被背叛了。", "0", "0", "0", "0", "0", "cv_sk_ruoshui_28", "0", "0"},
[4001100131] = {4001100131, 10011001, 34, 26, "0", "0", "為什麼領航哥哥會在這裡？快回去躺病床上！", "なんでナビゲーターのお兄さんがここにいるんですか？早く病室に戻ってください！", "0", "0", "0", "0", "cv_sk_ruoshui_31", "0", "0"},
[4001100132] = {4001100132, 10011001, 35, 27, "0", "0", "要開始任務了嗎——瞭解。", "0", "0", "0", "0", "0", "cv_sk_ruoshui_33", "0", "0"},
[4001100133] = {4001100133, 10011001, 36, 28, "0", "0", "弱水，準備出擊！", "0", "0", "0", "0", "0", "cv_sk_ruoshui_34", "0", "0"},
[4001100134] = {4001100134, 10011001, 37, 29, "0", "0", "大家一起去春遊嗎~", "0", "0", "0", "0", "0", "cv_sk_ruoshui_35", "0", "0"},
[4001100135] = {4001100135, 10011001, 38, 30, "0", "0", "我也要成為前輩了嗎？", "0", "0", "0", "0", "0", "cv_sk_ruoshui_36", "0", "0"},
[4001100136] = {4001100136, 10011001, 39, 31, "0", "0", "想要帥氣的武器！", "0", "0", "0", "0", "0", "cv_sk_ruoshui_37", "0", "0"},
[4001100137] = {4001100137, 10011001, 40, 32, "0", "0", "來兩張電影票~！", "0", "0", "0", "0", "0", "cv_sk_ruoshui_38", "0", "0"},
[4001100138] = {4001100138, 10011001, 41, 33, "0", "0", "領航很帥喔~", "0", "0", "0", "0", "0", "cv_sk_ruoshui_39", "0", "0"},
[4001100139] = {4001100139, 10011001, 42, 34, "0", "0", "慢慢來~", "0", "0", "0", "0", "0", "cv_sk_ruoshui_40", "0", "0"},
[4001100140] = {4001100140, 10011001, 43, 35, "0", "0", "要注意查收信件喔。", "0", "0", "0", "0", "0", "cv_sk_ruoshui_41", "0", "0"},
[4001100141] = {4001100141, 10011001, 44, 36, "0", "0", "好多人啊……", "0", "0", "0", "0", "0", "cv_sk_ruoshui_42", "0", "0"},
[4001100142] = {4001100142, 10011001, 45, 37, "0", "0", "噗噠！", "0", "0", "0", "0", "0", "cv_sk_ruoshui_43", "0", "0"},
[4001200100] = {4001200100, 10012001, 1, 1, "0", "0", "蒼霧殘響。", "0", "0", "0", "0", "0", "cv_sk_guroria_32", "0", "0"},
[4001200101] = {4001200101, 10012001, 2, 2, "0", "0", "我會站在這，注視著您工作的……無聊？不，您無須在意我的感受。", "0", "0", "0", "0", "0", "cv_sk_guroria_2", "0", "0"},
[4001200102] = {4001200102, 10012001, 3, 3, "0", "0", "您好，我是第三研究室防衛班的新成員，格洛麗亞。從今天開始，您便是我的領航了。", "0", "0", "0", "0", "0", "cv_sk_guroria_1", "0", "0"},
[4001200103] = {4001200103, 10012001, 4, 4, "0", "idle", "告訴查麗莎，喝醉的人都會臉紅的。我沒有臉紅，所以沒有喝醉，嗯，接、接著喝！", "0", "0", "0", "0", "0", "cv_sk_guroria_3", "0", "0"},
[4001200104] = {4001200104, 10012001, 5, 4, "0", "idle", "有兩個領航在飛……呀，變成三個了……", "0", "0", "0", "0", "0", "cv_sk_guroria_4", "0", "0"},
[4001200105] = {4001200105, 10012001, 6, 4, "0", "idle", "怎麼一直盯著我看？我明白了，您也想來一杯。想喝就直說嘛……來，拿著，幹、乾杯！", "0", "0", "0", "0", "0", "cv_sk_guroria_29", "0", "0"},
[4001200106] = {4001200106, 10012001, 7, 5, "15_1_0_0.8", "level1", "這種輕飄飄的感覺，好有趣呀……", "0", "0", "0", "0", "0", "cv_sk_guroria_30", "0", "0"},
[4001200107] = {4001200107, 10012001, 8, 5, "15_2_0_0.8", "level2", "您說的那個“梭哈”，好像有聽誰介紹過——啊，想起來了。我今天是荷官，負責發牌的，發牌……請等一下，我把牌放哪去了？", "0", "0", "0", "0", "0", "cv_sk_guroria_5", "0", "0"},
[4001200108] = {4001200108, 10012001, 9, 5, "15_1_0_0.8", "level1", "醒酒湯？拿、拿走。我酒量超大的。", "0", "0", "0", "0", "0", "cv_sk_guroria_6", "0", "0"},
[4001200109] = {4001200109, 10012001, 10, 5, "15_1_0_0.8", "level1", "……對哦，就像領航先生您所說的那樣，有些人是喝醉了也不上臉的。所以或許我確實是醉了？嘿嘿。", "0", "0", "0", "0", "0", "cv_sk_guroria_7", "0", "0"},
[4001200110] = {4001200110, 10012001, 11, 5, "15_1_0_0.8", "level1", "醉了以後，腦袋裡空空的，什麼都不用考慮，也不用去顧慮任何事情……我還挺喜歡這種感覺的……所以領航先生，再讓我多喝一杯吧？好不好嘛~", "0", "0", "0", "0", "0", "cv_sk_guroria_8", "0", "0"},
[4001200111] = {4001200111, 10012001, 12, 6, "0", "0", "升級？喔，謝謝。", "0", "0", "0", "0", "0", "cv_sk_guroria_9", "0", "0"},
[4001200112] = {4001200112, 10012001, 13, 7, "0", "0", "階級提升，謝謝。", "0", "0", "0", "0", "0", "cv_sk_guroria_10", "0", "0"},
[4001200113] = {4001200113, 10012001, 14, 8, "0", "0", "領航先生…一直以來，我十分感謝您對我的幫助…可，這些並不是我所希望的。領航先生…能，離我更近一些嗎？", "0", "0", "0", "0", "0", "cv_sk_guroria_11", "0", "0"},
[4001200114] = {4001200114, 10012001, 15, 9, "0", "0", "謝謝您，領航先生。", "0", "0", "0", "0", "0", "cv_sk_guroria_12", "0", "0"},
[4001200115] = {4001200115, 10012001, 16, 10, "0", "0", "到此為止吧。", "0", "0", "0", "0", "0", "cv_sk_guroria_13", "0", "0"},
[4001200116] = {4001200116, 10012001, 17, 11, "0", "0", "勝利了嗎，嗯，那就好，多虧大家了。", "0", "0", "0", "0", "0", "cv_sk_guroria_14", "0", "0"},
[4001200117] = {4001200117, 10012001, 18, 12, "0", "0", "給您添麻煩了。", "0", "0", "0", "0", "0", "cv_sk_guroria_15", "0", "0"},
[4001200118] = {4001200118, 10012001, 19, 13, "0", "0", "抱歉，我應該做得更好的。", "0", "0", "0", "0", "0", "cv_sk_guroria_16", "0", "0"},
[4001200119] = {4001200119, 10012001, 20, 14, "0", "0", "先撤退吧。", "0", "0", "0", "0", "0", "cv_sk_guroria_17", "0", "0"},
[4001200120] = {4001200120, 10012001, 21, 15, "0", "0", "輕輕鬆鬆~", "0", "0", "0", "0", "0", "cv_sk_guroria_18", "0", "0"},
[4001200121] = {4001200121, 10012001, 23, 16, "0", "0", "我要……敲開你！", "0", "0", "0", "0", "0", "cv_sk_guroria_19", "0", "0"},
[4001200122] = {4001200122, 10012001, 24, 17, "0", "0", "看瓶！", "0", "0", "0", "0", "0", "cv_sk_guroria_21", "0", "0"},
[4001200123] = {4001200123, 10012001, 26, 19, "0", "0", "咦？我怎麼在這裡……頭好痛……", "0", "0", "0", "0", "0", "cv_sk_guroria_20", "0", "0"},
[4001200124] = {4001200124, 10012001, 27, 20, "0", "0", "您也要一起過來嗎？是嗎…那按您喜歡的來吧。", "0", "0", "0", "0", "0", "cv_sk_guroria_22", "0", "0"},
[4001200125] = {4001200125, 10012001, 28, 21, "0", "0", "領航先生，您累了的話，就別勉強了。", "0", "0", "0", "0", "0", "cv_sk_guroria_23", "0", "0"},
[4001200126] = {4001200126, 10012001, 29, 21, "0", "0", "領航先生，辛苦您了。剩下的讓我自己來…不行嗎？…我明白了。", "0", "0", "0", "0", "0", "cv_sk_guroria_24", "0", "0"},
[4001200127] = {4001200127, 10012001, 30, 22, "0", "0", "喔…是事件。", "0", "0", "0", "0", "0", "cv_sk_guroria_25", "0", "0"},
[4001200128] = {4001200128, 10012001, 31, 23, "0", "0", "請您隨意。", "0", "0", "0", "0", "0", "cv_sk_guroria_26", "0", "0"},
[4001200129] = {4001200129, 10012001, 32, 24, "0", "0", "恭喜您。", "0", "0", "0", "0", "0", "cv_sk_guroria_27", "0", "0"},
[4001200130] = {4001200130, 10012001, 33, 25, "0", "0", "辛苦了。", "0", "0", "0", "0", "0", "cv_sk_guroria_28", "0", "0"},
[4001200131] = {4001200131, 10012001, 34, 26, "0", "0", "哦？領航先生今天的工作還沒有結束嗎？您可真是太辛苦了、嗝。", "0", "0", "0", "0", "0", "cv_sk_guroria_31", "0", "0"},
[4001200132] = {4001200132, 10012001, 35, 27, "0", "0", "領航先生，出發吧，我沒有需要準備的東西。", "0", "0", "0", "0", "0", "cv_sk_guroria_33", "0", "0"},
[4001200133] = {4001200133, 10012001, 36, 28, "0", "0", "我們走吧，領航先生。", "0", "0", "0", "0", "0", "cv_sk_guroria_34", "0", "0"},
[4001200134] = {4001200134, 10012001, 37, 29, "0", "0", "午安，各位。", "0", "0", "0", "0", "0", "cv_sk_guroria_35", "0", "0"},
[4001200135] = {4001200135, 10012001, 38, 30, "0", "0", "領航先生，您是要面試嗎？", "0", "0", "0", "0", "0", "cv_sk_guroria_36", "0", "0"},
[4001200136] = {4001200136, 10012001, 39, 31, "0", "0", "裝備…要換新的嗎？", "0", "0", "0", "0", "0", "cv_sk_guroria_37", "0", "0"},
[4001200137] = {4001200137, 10012001, 40, 32, "0", "0", "想買什麼？", "0", "0", "0", "0", "0", "cv_sk_guroria_38", "0", "0"},
[4001200138] = {4001200138, 10012001, 41, 33, "0", "0", "請記得洗漱。", "0", "0", "0", "0", "0", "cv_sk_guroria_39", "0", "0"},
[4001200139] = {4001200139, 10012001, 42, 34, "0", "0", "請小心設定。", "0", "0", "0", "0", "0", "cv_sk_guroria_40", "0", "0"},
[4001200140] = {4001200140, 10012001, 43, 35, "0", "0", "請仔細閱讀。", "0", "0", "0", "0", "0", "cv_sk_guroria_41", "0", "0"},
[4001200141] = {4001200141, 10012001, 44, 36, "0", "0", "很熱鬧呢。", "0", "0", "0", "0", "0", "cv_sk_guroria_42", "0", "0"},
[4001200142] = {4001200142, 10012001, 45, 37, "0", "0", "嗯？", "0", "0", "0", "0", "0", "cv_sk_guroria_43", "0", "0"},
[4001300100] = {4001300100, 10013001, 1, 1, "0", "0", "蒼霧殘響。", "0", "0", "0", "0", "0", "cv_sk_lilith_31", "0", "0"},
[4001300101] = {4001300101, 10013001, 2, 2, "0", "0", "為什麼要這麼在意我？", "0", "0", "0", "0", "0", "cv_sk_lilith_2", "0", "0"},
[4001300102] = {4001300102, 10013001, 3, 3, "0", "0", "啊，熟悉的味道啊。你就是那個真正的通感者吧。話先說在前面，我討厭所有的通感者，當然也包括我自己。", "0", "0", "0", "0", "0", "cv_sk_lilith_1", "0", "0"},
[4001300103] = {4001300103, 10013001, 4, 4, "0", "idle", "鐘聲已響，你是否能夠聽見？它正於人們苦難的天空盤旋，激蕩出情願揚棄一切的信仰。", "鳴り響く鐘の音が聞こえるかしら？苦しむ人々の頭上で、すべての信仰心を投げうつように迫っているの。", "0", "0", "0", "0", "cv_sk_lilith_3", "0", "0"},
[4001300104] = {4001300104, 10013001, 5, 4, "0", "idle", "在無意義的等待面前，燭火會漸漸燃盡，但我們的罪惡並不會隨之減輕分毫。", "無意味に待っている間にも、ロウソクは燃え続けていく。けれど、それと共に我々の罪が減っていくわけではないわ。", "0", "0", "0", "0", "cv_sk_lilith_4", "0", "0"},
[4001300105] = {4001300105, 10013001, 6, 4, "0", "idle", "摩根勒菲聖座大人所展現出的奇跡，我的眼卻無法清晰看見……這也是由於吾罪之深嗎？", "モーガンルフェイ聖座さまの起こす奇跡は、私の目には映らない……これもまた私の罪の深さゆえか……", "0", "0", "0", "0", "cv_sk_lilith_28", "0", "0"},
[4001300106] = {4001300106, 10013001, 7, 5, "1_》_0_0.8", "level1", "如果人性——人類的性質本身就飽含原罪，那麼究竟該擁抱它，還是拒絕它？", "もし人の本性が……人類の本質が原罪に塗れているのであれば、それを受け入れるべきなのか。それとも拒絶すべきなのか。", "0", "0", "0", "0", "cv_sk_lilith_29", "0", "0"},
[4001300107] = {4001300107, 10013001, 8, 5, "1_》_0_0.8", "level1", "還請不要亂碰我的身體，以免破壞了儀式。", "私の體をみだりに觸らないで。儀式が壊れてしまうわ。", "0", "0", "0", "0", "cv_sk_lilith_5", "0", "0"},
[4001300108] = {4001300108, 10013001, 9, 5, "1_》_0_0.8", "level2", "即使蒙住雙眼，在我所見的深邃黑暗中，你的存在還是如此突兀……讓人完全無法忽視啊。", "両目が塞がれようと、深い闇の中であなたの存在を感じ取ることができるわ……とても無視できないほどに。", "0", "0", "0", "0", "cv_sk_lilith_6", "0", "0"},
[4001300109] = {4001300109, 10013001, 10, 5, "1_》_0_0.8", "level3", "我能感覺到，你那熾烈陽光般的視線正直射在我身上，像是要洞穿一切。你從我這看見了什麼？還是想要看見什麼呢？", "あなたの燃え盛る太陽のような視線を感じるわ。あなたは私に何を見ているの？それとも、何を見ようとしているの？", "0", "0", "0", "0", "cv_sk_lilith_7", "0", "0"},
[4001300110] = {4001300110, 10013001, 11, 5, "1_》_0_0.8", "level4", "教堂的殘礫，融化的蠟液，凋落的鮮花，以及我這副扭曲姿態，在儀式中各有其象徵，唯獨你身處於此的含義我完全不懂。接下來……你能告訴我嗎？", "教會の殘骸。溶けたロウソク。色あせた花。そしてねじれた私の姿。儀式では全てのものが意味を持つけれど、唯一、あなたがここにいる意味が理解できないの。さぁ……私にそれを教えて？", "0", "0", "0", "0", "cv_sk_lilith_8", "0", "0"},
[4001300111] = {4001300111, 10013001, 12, 6, "0", "0", "沒錯，就這樣繼續下去吧。", "0", "0", "0", "0", "0", "cv_sk_lilith_9", "0", "0"},
[4001300112] = {4001300112, 10013001, 13, 7, "0", "0", "很好……這麼一來我的病就能痊癒了吧……", "0", "0", "0", "0", "0", "cv_sk_lilith_10", "0", "0"},
[4001300113] = {4001300113, 10013001, 14, 8, "0", "0", "果然，無論怎麼樣都無法擺脫通感者的身份嗎……只是，那些讓人討厭的聲音好像變得柔和了……我好像能聽到其他的聲音了。孩子們的祝福，感謝以及……祈禱的歌聲。", "0", "0", "0", "0", "0", "cv_sk_lilith_11", "0", "0"},
[4001300114] = {4001300114, 10013001, 15, 9, "0", "0", "電流量提升了呢。", "0", "0", "0", "0", "0", "cv_sk_lilith_12", "0", "0"},
[4001300115] = {4001300115, 10013001, 16, 10, "0", "0", "真討厭啊。", "0", "0", "0", "0", "0", "cv_sk_lilith_13", "0", "0"},
[4001300116] = {4001300116, 10013001, 17, 11, "0", "0", "不用急著感謝我。", "0", "0", "0", "0", "0", "cv_sk_lilith_14", "0", "0"},
[4001300117] = {4001300117, 10013001, 18, 12, "0", "0", "都和你說過了，沒問題的。", "0", "0", "0", "0", "0", "cv_sk_lilith_15", "0", "0"},
[4001300118] = {4001300118, 10013001, 19, 13, "0", "0", "嗯，怎麼說呢，有驚無險吧。", "0", "0", "0", "0", "0", "cv_sk_lilith_16", "0", "0"},
[4001300119] = {4001300119, 10013001, 20, 14, "0", "0", "啊……那些討厭的聲音…又出現了嗎。", "0", "0", "0", "0", "0", "cv_sk_lilith_17", "0", "0"},
[4001300120] = {4001300120, 10013001, 21, 15, "0", "0", "還會再出現嗎？", "まだ出て來るのかしら？", "0", "0", "0", "0", "cv_sk_lilith_18", "0", "0"},
[4001300121] = {4001300121, 10013001, 23, 16, "0", "0", "從我的眼前消失。", "私の前から消えなさい。", "0", "0", "0", "0", "cv_sk_lilith_19", "0", "0"},
[4001300122] = {4001300122, 10013001, 26, 19, "0", "0", "殺了我……", "私を殺して……", "0", "0", "0", "0", "cv_sk_lilith_20", "0", "0"},
[4001300123] = {4001300123, 10013001, 27, 20, "0", "0", "啊，又是那股熟悉的味道呢，是你吧。", "0", "0", "0", "0", "0", "cv_sk_lilith_21", "0", "0"},
[4001300124] = {4001300124, 10013001, 28, 21, "0", "0", "和你貼得這麼近，真討厭啊……", "0", "0", "0", "0", "0", "cv_sk_lilith_22", "0", "0"},
[4001300125] = {4001300125, 10013001, 29, 21, "0", "0", "要小心點喔，我可不想聽到你摔下去時發出的哀嚎。", "0", "0", "0", "0", "0", "cv_sk_lilith_23", "0", "0"},
[4001300126] = {4001300126, 10013001, 30, 22, "0", "0", "放心地上吧。", "0", "0", "0", "0", "0", "cv_sk_lilith_24", "0", "0"},
[4001300127] = {4001300127, 10013001, 31, 23, "0", "0", "如果敢使用通感作弊就殺了你喔。", "0", "0", "0", "0", "0", "cv_sk_lilith_25", "0", "0"},
[4001300128] = {4001300128, 10013001, 32, 24, "0", "0", "好棒，我好開心。", "0", "0", "0", "0", "0", "cv_sk_lilith_26", "0", "0"},
[4001300129] = {4001300129, 10013001, 33, 25, "0", "0", "啊，和我想得一樣，下次再努力吧。", "0", "0", "0", "0", "0", "cv_sk_lilith_27", "0", "0"},
[4001300130] = {4001300130, 10013001, 34, 26, "0", "0", "你的足音就像午夜時分的教堂鐘聲，讓人分不清自己感到的是安心還是恐懼。", "あなたの足音は、夜中に聞く教會の鐘のようなもの。自分が安心しているのか恐れているのか、分からなくなるの。", "0", "0", "0", "0", "cv_sk_lilith_30", "0", "0"},
[4001300131] = {4001300131, 10013001, 35, 27, "0", "0", "終點到底有什麼在等著我們呢？", "0", "0", "0", "0", "0", "cv_sk_lilith_32", "0", "0"},
[4001300132] = {4001300132, 10013001, 36, 28, "0", "0", "這次又要持續多久呢？", "0", "0", "0", "0", "0", "cv_sk_lilith_33", "0", "0"},
[4001300133] = {4001300133, 10013001, 37, 29, "0", "0", "這些是同伴吧。", "0", "0", "0", "0", "0", "cv_sk_lilith_34", "0", "0"},
[4001300134] = {4001300134, 10013001, 38, 30, "0", "0", "招些厲害的傢夥吧。", "0", "0", "0", "0", "0", "cv_sk_lilith_35", "0", "0"},
[4001300135] = {4001300135, 10013001, 39, 31, "0", "0", "嗯？缺裝備了嗎？", "0", "0", "0", "0", "0", "cv_sk_lilith_36", "0", "0"},
[4001300136] = {4001300136, 10013001, 40, 32, "0", "0", "去採購點東西吧。", "0", "0", "0", "0", "0", "cv_sk_lilith_37", "0", "0"},
[4001300137] = {4001300137, 10013001, 41, 33, "0", "0", "確認一下個人資訊吧。", "0", "0", "0", "0", "0", "cv_sk_lilith_38", "0", "0"},
[4001300138] = {4001300138, 10013001, 42, 34, "0", "0", "在這裡變更設定。", "0", "0", "0", "0", "0", "cv_sk_lilith_39", "0", "0"},
[4001300139] = {4001300139, 10013001, 43, 35, "0", "0", "有給你寫的情書，開玩笑的。", "0", "0", "0", "0", "0", "cv_sk_lilith_40", "0", "0"},
[4001300140] = {4001300140, 10013001, 44, 36, "0", "0", "滿是通感者的味道呢，真討厭。", "0", "0", "0", "0", "0", "cv_sk_lilith_41", "0", "0"},
[4001300141] = {4001300141, 10013001, 45, 37, "0", "0", "確認一下。", "0", "0", "0", "0", "0", "cv_sk_lilith_42", "0", "0"},
[4001600100] = {4001600100, 10016001, 1, 1, "0", "0", "蒼霧殘響。", "0", "0", "0", "0", "0", "cv_sk_anan_32", "0", "0"},
[4001600101] = {4001600101, 10016001, 2, 2, "0", "0", "站崗任務…是嗎？好，我會努力完成的。", "0", "0", "0", "0", "0", "cv_sk_anan_2", "0", "0"},
[4001600102] = {4001600102, 10016001, 3, 3, "0", "0", "雛鷹小隊安安前來報導，請領航下達命令。", "0", "0", "0", "0", "0", "cv_sk_anan_1", "0", "0"},
[4001600103] = {4001600103, 10016001, 4, 4, "0", "idle", "本店已經打烊了，現在是清潔時間。", "0", "0", "0", "0", "0", "cv_sk_anan_3", "0", "0"},
[4001600104] = {4001600104, 10016001, 5, 4, "0", "idle", "只要把這些杯子整理完，就能換回原本的衣服了。", "0", "0", "0", "0", "0", "cv_sk_anan_4", "0", "0"},
[4001600105] = {4001600105, 10016001, 6, 4, "0", "idle", "雖然不是很理解為什麼服務員要穿這麼暴露的服裝，但光顧的客人都是學院的學生倒也沒什麼好害羞的……而且這裏可是班長推薦的打工地點。", "0", "0", "0", "0", "0", "cv_sk_anan_29", "0", "0"},
[4001600106] = {4001600106, 10016001, 7, 5, "15_1_0_0.8", "level1", "這件兔子衣服穿著真不舒服，為什麼城市裏的人會喜歡扮成兔子呢？在我老家，兔子可是用來吃的東西……", "0", "0", "0", "0", "0", "cv_sk_anan_30", "0", "0"},
[4001600107] = {4001600107, 10016001, 8, 5, "15_1_0_0.8", "level1", "請問，您想要點什麼飲品嗎？", "0", "0", "0", "0", "0", "cv_sk_anan_5", "0", "0"},
[4001600108] = {4001600108, 10016001, 9, 5, "15_1_0_0.8", "level1", "要不要告訴店長，外面有奇怪的人……但仔細看的話，好像是領航？", "0", "0", "0", "0", "0", "cv_sk_anan_6", "0", "0"},
[4001600109] = {4001600109, 10016001, 10, 5, "15_2_0_0.8", "level2", "誰，誰在偷看？領航？……唔，可以不可以不要這樣盯著我……你看著我的話，我很難繼續清掃的工作……", "0", "0", "0", "0", "0", "cv_sk_anan_7", "0", "0"},
[4001600110] = {4001600110, 10016001, 11, 5, "15_2_0_0.8", "level2", "我沒想到會在這裏看到領航，真可惜現在店裏已經打烊了……領航下次早點來，安安會盡全力那個……服，服務好您！", "0", "0", "0", "0", "0", "cv_sk_anan_8", "0", "0"},
[4001600111] = {4001600111, 10016001, 12, 6, "0", "0", "能感覺到，力量的提升。", "0", "0", "0", "0", "0", "cv_sk_anan_9", "0", "0"},
[4001600112] = {4001600112, 10016001, 13, 7, "0", "0", "這個知識點，終於理解了。", "0", "0", "0", "0", "0", "cv_sk_anan_10", "0", "0"},
[4001600113] = {4001600113, 10016001, 14, 8, "0", "0", "下次測驗，我不會再考最後一名了。", "0", "0", "0", "0", "0", "cv_sk_anan_11", "0", "0"},
[4001600114] = {4001600114, 10016001, 15, 9, "0", "0", "謝謝您的輔導，領航。", "0", "0", "0", "0", "0", "cv_sk_anan_12", "0", "0"},
[4001600115] = {4001600115, 10016001, 16, 10, "0", "0", "安安，到達任務地點！", "0", "0", "0", "0", "0", "cv_sk_anan_13", "0", "0"},
[4001600116] = {4001600116, 10016001, 17, 11, "0", "0", "我會保持努力的，請相信我，領航。", "0", "0", "0", "0", "0", "cv_sk_anan_14", "0", "0"},
[4001600117] = {4001600117, 10016001, 18, 12, "0", "0", "還是不夠努力，之後再多訓練一小時吧。", "0", "0", "0", "0", "0", "cv_sk_anan_15", "0", "0"},
[4001600118] = {4001600118, 10016001, 19, 13, "0", "0", "不行，這樣下去是報答不了卡蓮班長的恩情的。", "0", "0", "0", "0", "0", "cv_sk_anan_16", "0", "0"},
[4001600119] = {4001600119, 10016001, 20, 14, "0", "0", "果然，我是個“廢材”呢。", "0", "0", "0", "0", "0", "cv_sk_anan_17", "0", "0"},
[4001600120] = {4001600120, 10016001, 21, 15, "0", "0", "歡迎下次光臨。", "0", "0", "0", "0", "0", "cv_sk_anan_18", "0", "0"},
[4001600121] = {4001600121, 10016001, 23, 16, "0", "0", "吃根胡蘿蔔吧！", "0", "0", "0", "0", "0", "cv_sk_anan_19", "0", "0"},
[4001600122] = {4001600122, 10016001, 24, 17, "0", "0", "不許逃跑……", "0", "0", "0", "0", "0", "cv_sk_anan_21", "0", "0"},
[4001600123] = {4001600123, 10016001, 26, 19, "0", "0", "對不起，安安失敗了……", "0", "0", "0", "0", "0", "cv_sk_anan_20", "0", "0"},
[4001600124] = {4001600124, 10016001, 27, 20, "0", "0", "這點小事，其實不必麻煩領航。", "0", "0", "0", "0", "0", "cv_sk_anan_22", "0", "0"},
[4001600125] = {4001600125, 10016001, 28, 21, "0", "0", "好舒服~", "0", "0", "0", "0", "0", "cv_sk_anan_23", "0", "0"},
[4001600126] = {4001600126, 10016001, 29, 21, "0", "0", "到訓練時間了，但是…不想出去…", "0", "0", "0", "0", "0", "cv_sk_anan_24", "0", "0"},
[4001600127] = {4001600127, 10016001, 30, 22, "0", "0", "領航，我會給您加油的！", "0", "0", "0", "0", "0", "cv_sk_anan_25", "0", "0"},
[4001600128] = {4001600128, 10016001, 31, 23, "0", "0", "加油！", "0", "0", "0", "0", "0", "cv_sk_anan_26", "0", "0"},
[4001600129] = {4001600129, 10016001, 32, 24, "0", "0", "嘿嘿，沒想到除了卡蓮班長還有人在乎我。", "0", "0", "0", "0", "0", "cv_sk_anan_27", "0", "0"},
[4001600130] = {4001600130, 10016001, 33, 25, "0", "0", "下次再努力吧！", "0", "0", "0", "0", "0", "cv_sk_anan_28", "0", "0"},
[4001600131] = {4001600131, 10016001, 34, 26, "0", "0", "歡迎光臨，不對已經打烊了，呃……歡迎下次光臨……", "0", "0", "0", "0", "0", "cv_sk_anan_31", "0", "0"},
[4001600132] = {4001600132, 10016001, 35, 27, "0", "0", "安安已經準備完畢。", "0", "0", "0", "0", "0", "cv_sk_anan_33", "0", "0"},
[4001600133] = {4001600133, 10016001, 36, 28, "0", "0", "就算是困難的任務，我也會盡全力完成！", "0", "0", "0", "0", "0", "cv_sk_anan_34", "0", "0"},
[4001600134] = {4001600134, 10016001, 37, 29, "0", "0", "原來有這麼多前輩在。", "0", "0", "0", "0", "0", "cv_sk_anan_35", "0", "0"},
[4001600135] = {4001600135, 10016001, 38, 30, "0", "0", "要給別人更多的機會。", "0", "0", "0", "0", "0", "cv_sk_anan_36", "0", "0"},
[4001600136] = {4001600136, 10016001, 39, 31, "0", "0", "不用給我更多的裝備了。", "0", "0", "0", "0", "0", "cv_sk_anan_37", "0", "0"},
[4001600137] = {4001600137, 10016001, 40, 32, "0", "0", "購物的話…我只買過麵包和水。", "0", "0", "0", "0", "0", "cv_sk_anan_38", "0", "0"},
[4001600138] = {4001600138, 10016001, 41, 33, "0", "0", "領航很溫柔呢。", "0", "0", "0", "0", "0", "cv_sk_anan_39", "0", "0"},
[4001600139] = {4001600139, 10016001, 42, 34, "0", "0", "又是我不瞭解的新知識。", "0", "0", "0", "0", "0", "cv_sk_anan_40", "0", "0"},
[4001600140] = {4001600140, 10016001, 43, 35, "0", "0", "我想給爸媽寄一封信。", "0", "0", "0", "0", "0", "cv_sk_anan_41", "0", "0"},
[4001600141] = {4001600141, 10016001, 44, 36, "0", "0", "好多人…", "0", "0", "0", "0", "0", "cv_sk_anan_42", "0", "0"},
[4001600142] = {4001600142, 10016001, 45, 37, "0", "0", "瞭解！", "0", "0", "0", "0", "0", "cv_sk_anan_43", "0", "0"},
[4001800100] = {4001800100, 10018001, 1, 1, "0", "0", "蒼霧殘響", "0", "0", "0", "0", "0", "cv_sk_lyfa_32", "0", "0"},
[4001800101] = {4001800101, 10018001, 2, 2, "0", "0", "交給我吧。", "0", "0", "0", "0", "0", "cv_sk_lyfa_2", "0", "0"},
[4001800102] = {4001800102, 10018001, 3, 3, "0", "0", "瓦爾基里小隊的莉法，向您報導。領航……我能稱呼您為主人嗎？", "0", "0", "0", "0", "0", "cv_sk_lyfa_1", "0", "0"},
[4001800103] = {4001800103, 10018001, 4, 4, "0", "idle", "休息一下然後繼續……今天的訓練還遠遠沒有達標。", "少し休憩したら再開しましょう。…今日の訓練目標は、まだ達成していませんので。", "0", "0", "0", "0", "cv_sk_lyfa_3", "0", "0"},
[4001800104] = {4001800104, 10018001, 5, 4, "0", "idle", "遠處的夜空在銀河間滑行，留下閃光的線痕。不知道我滑冰的舞姿能否比得上百分之一的夜空。", "遠い夜空の星は、光の跡を殘し、銀河を流れて行く。私のスケートは、あの夜空の美しさの１パーセントには及ぶでしょうか。", "0", "0", "0", "0", "cv_sk_lyfa_4", "0", "0"},
[4001800105] = {4001800105, 10018001, 6, 4, "0", "idle", "沒想到這裡的冰面能承載這麼巨大身體的重量，簡直是天然的滑冰場。我可不能辜負大自然好意，要更努力地訓練才行。", "これほど巨大な身體の重みに耐えられるなんて、本當に素晴らしい天然のスケートリンクですね。大自然のご厚意に応えるためにも、もっと頑張らなくては。", "0", "0", "0", "0", "cv_sk_lyfa_29", "0", "0"},
[4001800106] = {4001800106, 10018001, 7, 5, "1_》_0_0.8", "level1", "滑冰運動也是女僕修行的一環。這可以鍛煉身體的平衡感以及對力量的控制。當然像這樣巨大化後滑冰還是第一次。", "スケートもメイド修行の一環なんですよ。バランス感覚や筋力のコントロールを鍛えることができるんです。巨大化した姿でスケートをするのは初めてですがね……。", "0", "0", "0", "0", "cv_sk_lyfa_30", "0", "0"},
[4001800107] = {4001800107, 10018001, 8, 5, "1_》_0_0.8", "level1", "主人很在意我這件衣服嗎？這可是專門為了滑冰而設計的服裝。", "ご主人様、この服裝が気になるんですか？これはスケートのためにデザインされた専用の衣裝なんですよ。", "0", "0", "0", "0", "cv_sk_lyfa_5", "0", "0"},
[4001800108] = {4001800108, 10018001, 9, 5, "1_》_100_1.5", "level1", "很冷吧……抱歉，我現在沒法為主人準備暖身的紅茶。", "寒いのですか？……いまはご主人様に溫かい紅茶をご用意できず、申し訳ございません。", "0", "0", "0", "0", "cv_sk_lyfa_6", "0", "0"},
[4001800109] = {4001800109, 10018001, 10, 5, "1_》_500_2", "level1", "想要觀賞我滑冰時的舞姿？好的，主人。無論何時何地，只要您想，我都會為您起舞。", "私のスケートを見たいのですか？畏まりました、ご主人様。お望みでしたら、いつでもどこでも、ご主人様のために舞いましょう。", "0", "0", "0", "0", "cv_sk_lyfa_7", "0", "0"},
[4001800110] = {4001800110, 10018001, 11, 5, "1_》_1000_2.5", "level1", "我想邀請主人與我共舞，當然不是現在，除非……如果我現在解除幻化，主人能在空中接住我嗎？我相信您可以，但身為女僕我不會讓主人為我擔心。", "ご主人様と一緒に滑ってみたいですね。もちろん、今ということではなく…。…もし、いま私が幻化を解除したら、ご主人様は私を受け止めてくださいますか？もちろん、ご主人様なら受け止めてくれると信じています。ですが、メイドとしてご主人様にご迷惑をおかけわけにはいきませんよね。", "0", "0", "0", "0", "cv_sk_lyfa_8", "0", "0"},
[4001800111] = {4001800111, 10018001, 12, 6, "0", "0", "感覺到能力有提升了。", "0", "0", "0", "0", "0", "cv_sk_lyfa_9", "0", "0"},
[4001800112] = {4001800112, 10018001, 13, 7, "0", "0", "離成為專業女僕又進了一步。", "0", "0", "0", "0", "0", "cv_sk_lyfa_10", "0", "0"},
[4001800113] = {4001800113, 10018001, 14, 8, "0", "0", "主人的心意，我感受到了。從主人那得到的全部，我都會用來更好地服侍您的。", "0", "0", "0", "0", "0", "cv_sk_lyfa_11", "0", "0"},
[4001800114] = {4001800114, 10018001, 15, 9, "0", "0", "清掃技能up！", "0", "0", "0", "0", "0", "cv_sk_lyfa_12", "0", "0"},
[4001800115] = {4001800115, 10018001, 16, 10, "0", "0", "是這裏需要清掃嗎？", "0", "0", "0", "0", "0", "cv_sk_lyfa_13", "0", "0"},
[4001800116] = {4001800116, 10018001, 17, 11, "0", "0", "可不要小瞧女僕的厲害之處哦。", "0", "0", "0", "0", "0", "cv_sk_lyfa_14", "0", "0"},
[4001800117] = {4001800117, 10018001, 18, 12, "0", "0", "十分抱歉，撒掉的咖啡，馬上就幫你換一杯。", "0", "0", "0", "0", "0", "cv_sk_lyfa_15", "0", "0"},
[4001800118] = {4001800118, 10018001, 19, 13, "0", "0", "嗚——這種情況第一次遇到，該怎麼辦呢……", "0", "0", "0", "0", "0", "cv_sk_lyfa_16", "0", "0"},
[4001800119] = {4001800119, 10018001, 20, 14, "0", "0", "果然…我離專業的女僕還差得遠呢…嗚嗚……", "0", "0", "0", "0", "0", "cv_sk_lyfa_17", "0", "0"},
[4001800120] = {4001800120, 10018001, 21, 15, "0", "0", "清場時間。", "お掃除の時間です。", "0", "0", "0", "0", "cv_sk_lyfa_18", "0", "0"},
[4001800121] = {4001800121, 10018001, 23, 16, "0", "0", "跟得上我的舞步嗎？", "私の舞いについてこられますか？", "0", "0", "0", "0", "cv_sk_lyfa_19", "0", "0"},
[4001800122] = {4001800122, 10018001, 24, 17, "0", "0", "連續的跳躍。", "連続ジャンプです。", "0", "0", "0", "0", "cv_sk_lyfa_21", "0", "0"},
[4001800123] = {4001800123, 10018001, 26, 19, "0", "0", "我還不夠努力嗎……", "まだ、努力が足りないのでしょうか……", "0", "0", "0", "0", "cv_sk_lyfa_20", "0", "0"},
[4001800124] = {4001800124, 10018001, 27, 20, "0", "0", "沒想到會有讓主人服侍我的一天……", "0", "0", "0", "0", "0", "cv_sk_lyfa_22", "0", "0"},
[4001800125] = {4001800125, 10018001, 28, 21, "0", "0", "這裏的水溫好舒服…", "0", "0", "0", "0", "0", "cv_sk_lyfa_23", "0", "0"},
[4001800126] = {4001800126, 10018001, 29, 21, "0", "0", "這就是被別人服侍的感覺嗎？真舒服啊。", "0", "0", "0", "0", "0", "cv_sk_lyfa_24", "0", "0"},
[4001800127] = {4001800127, 10018001, 30, 22, "0", "0", "真是意想不到的狀況。", "0", "0", "0", "0", "0", "cv_sk_lyfa_25", "0", "0"},
[4001800128] = {4001800128, 10018001, 31, 23, "0", "0", "應該不會猜錯吧！", "0", "0", "0", "0", "0", "cv_sk_lyfa_26", "0", "0"},
[4001800129] = {4001800129, 10018001, 32, 24, "0", "0", "原來領航這麼在意我的嗎！", "0", "0", "0", "0", "0", "cv_sk_lyfa_27", "0", "0"},
[4001800130] = {4001800130, 10018001, 33, 25, "0", "0", "我知道了，主人一個人也可以的。", "0", "0", "0", "0", "0", "cv_sk_lyfa_28", "0", "0"},
[4001800131] = {4001800131, 10018001, 34, 26, "0", "0", "歡迎歸來，有主人陪在身邊，接下來我能有更好的表現。", "おかえりなさいませ。ご主人様が傍にいてくれるなら、次はもっと上手に舞える気がします。", "0", "0", "0", "0", "cv_sk_lyfa_31", "0", "0"},
[4001800132] = {4001800132, 10018001, 35, 27, "0", "0", "需要莉法去清掃嗎？", "0", "0", "0", "0", "0", "cv_sk_lyfa_33", "0", "0"},
[4001800133] = {4001800133, 10018001, 36, 28, "0", "0", "雖然很棘手但是放心交給我吧。", "0", "0", "0", "0", "0", "cv_sk_lyfa_34", "0", "0"},
[4001800134] = {4001800134, 10018001, 37, 29, "0", "0", "不知道茶點夠不夠呢？", "0", "0", "0", "0", "0", "cv_sk_lyfa_35", "0", "0"},
[4001800135] = {4001800135, 10018001, 38, 30, "0", "0", "我也是這樣招進來的嗎？", "0", "0", "0", "0", "0", "cv_sk_lyfa_36", "0", "0"},
[4001800136] = {4001800136, 10018001, 39, 31, "0", "0", "和風女僕裝也好好看……啊，沒沒什麼。", "0", "0", "0", "0", "0", "cv_sk_lyfa_37", "0", "0"},
[4001800137] = {4001800137, 10018001, 40, 32, "0", "0", "咖啡豆有點不夠用了。", "0", "0", "0", "0", "0", "cv_sk_lyfa_38", "0", "0"},
[4001800138] = {4001800138, 10018001, 41, 33, "0", "0", "這是主人的檔案，請過目。", "0", "0", "0", "0", "0", "cv_sk_lyfa_39", "0", "0"},
[4001800139] = {4001800139, 10018001, 42, 34, "0", "0", "這就要麻煩主人自行整理了。", "0", "0", "0", "0", "0", "cv_sk_lyfa_40", "0", "0"},
[4001800140] = {4001800140, 10018001, 43, 35, "0", "0", "這是今日的郵件。", "0", "0", "0", "0", "0", "cv_sk_lyfa_41", "0", "0"},
[4001800141] = {4001800141, 10018001, 44, 36, "0", "0", "請稍等，馬上就為大家泡茶。", "0", "0", "0", "0", "0", "cv_sk_lyfa_42", "0", "0"},
[4001800142] = {4001800142, 10018001, 45, 37, "0", "0", "安心使用吧。", "0", "0", "0", "0", "0", "cv_sk_lyfa_43", "0", "0"},
[4001900100] = {4001900100, 10019001, 1, 1, "0", "0", "蒼霧殘響", "蒼霧殘響（ハツリバーブ）。", "0", "0", "0", "0", "cv_sk_nozomi_sw_1", "0", "0"},
[4001900101] = {4001900101, 10019001, 2, 2, "0", "0", "你找到我啦，領航，我等你好久了。", "あたしを見つけてくれたんですね。ナビゲーターさん。", "0", "0", "0", "0", "cv_sk_nozomi_sw_2", "0", "0"},
[4001900102] = {4001900102, 10019001, 3, 3, "0", "0", "嗯？我的名字怎麼了嗎？和那位傳說中的偶像名字一模一樣？……是嘛，原來“她”已經死了啊。", "あたしの名前が何か……？え、伝説のアイドルと同じ？……そうですか。彼女はもう、いないんですね。", "0", "0", "0", "0", "cv_sk_nozomi_sw_3", "0", "0"},
[4001900103] = {4001900103, 10019001, 91, 4, "0", "idle", "即使我不在你的身邊了，但是我會通過微風、星辰與大海守望你的。……是什麼？是我以前的歌啦。", "もしあたしがあなたから離れることがあっても、風と星と海を通して、見守り続ける。……今のですか？昔つくった歌ですよ。", "0", "0", "0", "0", "cv_sk_nozomi_sw_5", "0", "0"},
[4001900104] = {4001900104, 10019001, 91, 4, "0", "idle", "我們的故事還沒翻到最後一頁呢，不要太著急結束哦。", "あたし達の物語はまだ最後のページではありません。そんなに急がなくてもいいですよ。", "0", "0", "0", "0", "cv_sk_nozomi_sw_6", "0", "0"},
[4001900105] = {4001900105, 10019001, 94, 4, "0", "idle2", "夏風聽起來、略微夾雜著為我喝彩的聲音。它們在為我加油鼓勁哦。", "夏のそよ風があたしを元気にしてくれるんです。頑張れって言われてるみたいに……", "0", "0", "0", "0", "cv_sk_nozomi_sw_7", "0", "0"},
[4001900106] = {4001900106, 10019001, 94, 5, "0", "idle2", "遮陽傘、就好像是我的舞臺一樣。我們一起躲在這裏吧，我有一段剛想到的旋律、想給領航聽。", "このビーチパラソルの下、まるであたしのステージみたいですね。ここで一緒に少し休みませんか？新しいメロディを思いついたので、ナビゲーターさんに聞いて欲しいんです。", "0", "0", "0", "0", "cv_sk_nozomi_sw_8", "0", "0"},
[4001900107] = {4001900107, 10019001, 93, 5, "14_》_0_0.8", "touch_s1", "真涼快呢……還是這樣更自在。", "涼しい……やっぱりこの方が楽ですね。", "0", "0", "0", "0", "cv_sk_nozomi_sw_9", "0", "0"},
[4001900108] = {4001900108, 10019001, 96, 5, "14_》_0_0.8", "touch_s2", "……被會長要求披上這件衣服。在她視線裏的時候還是先這樣穿著吧。", "この服を著るように、會長に言われてるんです。……少なくとも會長がいる間は、著てた方がいいですよね？", "0", "0", "0", "0", "cv_sk_nozomi_sw_10", "0", "0"},
[4001900109] = {4001900109, 10019001, 92, 5, "14_》_0_0.8", "touch1", "我能抓住幸運、改變運氣，但是這是有代價的……我在你的身上賭了一把，拜託了……一定要找到我啊。", "あたしは幸運をつかむことができます。運命を変えることができます。……でもそれには代償が必要なんです。ナビゲーターさん、お願い……絶対にあたしのことを見つけてくださいね。", "0", "0", "0", "0", "cv_sk_nozomi_sw_11", "0", "0"},
[4001900110] = {4001900110, 10019001, 92, 5, "14_》_0_0.8", "touch3", "你能猜到我現在正在想什麼嗎？……總有一天，我會登上這個世界最大的舞臺。如果我的願望實現的話，那一天你能來看我嗎？", "あたしが今何を考えているのか、分かりますか？……あたしはいつか、この世界で一番大きなステージに立ちたいと思っています。もしあたしの願いが実現したら、見に來てくれますか？", "0", "0", "0", "0", "cv_sk_nozomi_sw_12", "0", "0"},
[4001900111] = {4001900111, 10019001, 95, 5, "14_》_0_0.8", "touch2", "……我要把領航好好地記住……在我的周圍多呆一會吧。", "……ナビゲーターさんのことをちゃんと覚えていたくて……だから、もう少しあたしの側にいてくれませんか？", "0", "0", "0", "0", "cv_sk_nozomi_sw_46", "0", "0"},
[4001900112] = {4001900112, 10019001, 95, 5, "14_》_0_0.8", "touch2", "真是一場漫長而又短暫的冒險、謝謝你能回應我的聲音。", "長くて短い冒険でしたね。あたしの聲に応えてくれて、ありがとうございます。", "0", "0", "0", "0", "cv_sk_nozomi_sw_47", "0", "0"},
[4001900113] = {4001900113, 10019001, 12, 6, "0", "0", "哼♫~~", "フンフフーン♪", "0", "0", "0", "0", "cv_sk_nozomi_sw_13", "0", "0"},
[4001900114] = {4001900114, 10019001, 13, 7, "0", "0", "目標是頂點！", "トップを目指します！", "0", "0", "0", "0", "cv_sk_nozomi_sw_14", "0", "0"},
[4001900115] = {4001900115, 10019001, 14, 8, "0", "0", "嗯……嗯？剛剛好像有了一點靈感，剛剛那個是什麼？！覺醒？好厲害！可以再來一次嗎！……不可以了？遺憾……", "んん……あれ？このインスピレーション……これ、なんですか！？覚醒？すごーい！もう一回お願いできますか？……ダメ？殘念です……", "0", "0", "0", "0", "cv_sk_nozomi_sw_15", "0", "0"},
[4001900116] = {4001900116, 10019001, 15, 9, "0", "0", "找回曾經的手感了。", "昔の感覚が戻ってきました！", "0", "0", "0", "0", "cv_sk_nozomi_sw_16", "0", "0"},
[4001900117] = {4001900117, 10019001, 16, 10, "0", "0", "輪到我表演了嗎？", "私の出番ですか？", "0", "0", "0", "0", "cv_sk_nozomi_sw_17", "0", "0"},
[4001900118] = {4001900118, 10019001, 17, 11, "0", "0", "完美謝幕！", "カーテンコール！", "0", "0", "0", "0", "cv_sk_nozomi_sw_18", "0", "0"},
[4001900119] = {4001900119, 10019001, 18, 12, "0", "0", "略微的失誤，嗯……音樂有點雜音呢。", "ちょっと失敗ですね。うーん……ノイズが入っちゃいました。", "0", "0", "0", "0", "cv_sk_nozomi_sw_19", "0", "0"},
[4001900120] = {4001900120, 10019001, 19, 13, "0", "0", "還沒完全掌握這一段，再鍛煉一下自己吧。", "あのパートが上手くいきません……もっと練習しなきゃ。", "0", "0", "0", "0", "cv_sk_nozomi_sw_20", "0", "0"},
[4001900121] = {4001900121, 10019001, 20, 14, "0", "0", "大事件！演奏大失敗！要引起公憤了！", "やばい、大失敗！炎上しちゃいます！", "0", "0", "0", "0", "cv_sk_nozomi_sw_21", "0", "0"},
[4001900122] = {4001900122, 10019001, 21, 15, "0", "0", "大幕落下。", "これでラスト！", "0", "0", "0", "0", "cv_sk_nozomi_sw_23", "0", "0"},
[4001900123] = {4001900123, 10019001, 23, 16, "0", "0", "請聆聽！", "聞いてください！", "0", "0", "0", "0", "cv_sk_nozomi_sw_22", "0", "0"},
[4001900124] = {4001900124, 10019001, 26, 19, "0", "0", "噪音……", "不協和音が……", "0", "0", "0", "0", "cv_sk_nozomi_sw_24", "0", "0"},
[4001900125] = {4001900125, 10019001, 24, 17, "0", "0", "間奏律——", "インテルメッツォ！", "0", "0", "0", "0", "cv_sk_nozomi_sw_26", "0", "0"},
[4001900126] = {4001900126, 10019001, 25, 18, "0", "0", "大家久等了！結束希重回舞臺的演出，此刻，開演！", "お待たせしました！希ちゃんの復帰ライブ、開演です！", "0", "0", "0", "0", "cv_sk_nozomi_sw_25", "0", "0"},
[4001900127] = {4001900127, 10019001, 27, 20, "0", "0", "——呀！！領航？！你怎麼在這裏？！", "え、えええ！？ナビゲーターさん！？なんでここに？", "0", "0", "0", "0", "cv_sk_nozomi_sw_27", "0", "0"},
[4001900128] = {4001900128, 10019001, 28, 21, "0", "0", "…嗯嗯，原來如此，現在的樂壇真是大不一樣啊。", "……なるほど。今の音楽業界はこうなんですね。", "0", "0", "0", "0", "cv_sk_nozomi_sw_28", "0", "0"},
[4001900129] = {4001900129, 10019001, 29, 21, "0", "0", "音樂真是讓人痛苦又快樂……別人的表演會打動我的心，但卻又讓我嫉妒，不甘心。……等出去了，就繼續練習吧！", "音楽って本當に楽しいけど、辛い時もあるんですよ。他の人のパフォーマンスで感動して泣くこともあれば、嫉妬で悔しくなることも……うん！帰ったらすぐ練習します！", "0", "0", "0", "0", "cv_sk_nozomi_sw_29", "0", "0"},
[4001900130] = {4001900130, 10019001, 30, 22, "0", "0", "秘密演唱會開始了哦~", "シークレットライブ、開演です！", "0", "0", "0", "0", "cv_sk_nozomi_sw_30", "0", "0"},
[4001900131] = {4001900131, 10019001, 31, 23, "0", "0", "我的“聲音”對你而言是特殊的嗎？", "ナビゲーターさんにとって私の聲って、特別ですかねー？", "0", "0", "0", "0", "cv_sk_nozomi_sw_31", "0", "0"},
[4001900132] = {4001900132, 10019001, 32, 24, "0", "0", "你記住了呢！那我單方面宣佈你是我的死忠粉了！", "覚えててくれたんですね！あたしのファンとして合格です！", "0", "0", "0", "0", "cv_sk_nozomi_sw_32", "0", "0"},
[4001900133] = {4001900133, 10019001, 33, 25, "0", "0", "嗚……看來我還不夠成熟……", "ううう……私もまだまだですね……", "0", "0", "0", "0", "cv_sk_nozomi_sw_33", "0", "0"},
[4001900134] = {4001900134, 10019001, 34, 26, "0", "0", "歡迎回來，我正要準備練習了，領航你可以在旁邊聽哦~", "おかえりなさーい。ちょうど練習をはじめるところだったんですよ。よかったらそこで聞いててくださいね。", "0", "0", "0", "0", "cv_sk_nozomi_sw_34", "0", "0"},
[4001900135] = {4001900135, 10019001, 35, 27, "0", "0", "戰鬥的練習也沒有落下！", "戦闘訓練もちゃんとしてますよ！", "0", "0", "0", "0", "cv_sk_nozomi_sw_35", "0", "0"},
[4001900136] = {4001900136, 10019001, 36, 28, "0", "0", "駕駛員的道路也和偶像一樣殘酷呢。", "ドライバーの世界もアイドルと同じくらい過酷なんですね。", "0", "0", "0", "0", "cv_sk_nozomi_sw_36", "0", "0"},
[4001900137] = {4001900137, 10019001, 37, 29, "0", "0", "下次邀請大家一起來聽吧！", "みなさんもライブに來てくださいねー！", "0", "0", "0", "0", "cv_sk_nozomi_sw_37", "0", "0"},
[4001900138] = {4001900138, 10019001, 38, 30, "0", "0", "哦！新的成員要來了嗎。", "新しいメンバーですか？", "0", "0", "0", "0", "cv_sk_nozomi_sw_38", "0", "0"},
[4001900139] = {4001900139, 10019001, 39, 31, "0", "0", "其實鋼琴我也會彈哦。", "実はピアノも弾けちゃいますよ！", "0", "0", "0", "0", "cv_sk_nozomi_sw_39", "0", "0"},
[4001900140] = {4001900140, 10019001, 40, 32, "0", "0", "想試試新的樂器。", "新しい楽器も試してみたいです。", "0", "0", "0", "0", "cv_sk_nozomi_sw_40", "0", "0"},
[4001900141] = {4001900141, 10019001, 41, 33, "0", "0", "檔案對吧，請看。", "プロフィールですね、どうぞ。", "0", "0", "0", "0", "cv_sk_nozomi_sw_41", "0", "0"},
[4001900142] = {4001900142, 10019001, 42, 34, "0", "0", "把音量調到最大吧！", "音量を最大にしましょう！", "0", "0", "0", "0", "cv_sk_nozomi_sw_42", "0", "0"},
[4001900143] = {4001900143, 10019001, 43, 35, "0", "0", "有粉絲的感謝信嗎？", "ファンレターは…ありますか？", "0", "0", "0", "0", "cv_sk_nozomi_sw_43", "0", "0"},
[4001900144] = {4001900144, 10019001, 44, 36, "0", "0", "看看大家的想法吧。", "みんなの感想を見てみましょう。", "0", "0", "0", "0", "cv_sk_nozomi_sw_44", "0", "0"},
[4001900145] = {4001900145, 10019001, 45, 37, "0", "0", "哼~", "へえー。", "0", "0", "0", "0", "cv_sk_nozomi_sw_45", "0", "0"},
[4002000100] = {4002000100, 10020001, 1, 1, "0", "0", "蒼霧殘響", "ハツリバーブ", "0", "0", "0", "0", "cv_sk_weilai_sw_1", "0", "0"},
[4002000101] = {4002000101, 10020001, 2, 2, "0", "0", "變態先生就這麼想看到我嗎，好噁心。不過我可是成熟大方的淑女，自然是不會拒絕這種要求的。", "変態さん、そんなに私に会いたかったんですか？気持ち悪いです。だけど私も大人のレディですから、お誘いを断ったりはしませんよ。", "0", "0", "0", "0", "cv_sk_weilai_sw_2", "0", "0"},
[4002000102] = {4002000102, 10020001, 3, 3, "0", "0", "我的名字是未來，是早前預約過要來的駕駛員。咦……你說在夢裡見過我？變態先生你真的是……要是我什麼都不記得了的話，你這句話就是性騷擾哦？", "私の名前はミライです。約束通り会いに来ました。えっ？夢の中で私に会ったことがある？変態さん、あなた……それ私が何も覚えてなかったら、ただのセクハラですからね？", "0", "0", "0", "0", "cv_sk_weilai_sw_3", "0", "0"},
[4002000103] = {4002000103, 10020001, 91, 4, "0", "idle", "哈~好久沒睡得這麼舒服了~啊，難道說變態先生一直在旁邊守護著我？看不出來你這麼有紳士風度。", "はぁ～こんなにぐっすり眠れたのは久しぶりでした。あれっ、もしかして変態さん、ずっと傍で見守ってくれてたんですか？紳士的なところもあるんですね。", "0", "0", "0", "0", "cv_sk_weilai_sw_4", "0", "0"},
[4002000104] = {4002000104, 10020001, 91, 4, "0", "idle", "我睡覺的時候把自己的衣服都脫了？我是笨蛋嗎，怎麼可能做出這種事情……啊！難道這是你為自己找的藉口！", "私が寝てる間に服を脱いでるって？バカじゃないんですから、そんなわけが……あ！あなたが脱がしてるんじゃないですよね！", "0", "0", "0", "0", "cv_sk_weilai_sw_5", "0", "0"},
[4002000105] = {4002000105, 10020001, 91, 4, "0", "idle", "為我的身段著迷了嗎，畢竟我可是美少女……你那是什麼眼神，竟、竟然嫌棄本美少女引以為傲的身段！", "私の体に見惚れちゃいましたか。まぁ美少女ですからね。……なんですか？その目は。ま、まさかこの美少女ボディが気に入らないって言うんですか！", "0", "0", "0", "0", "cv_sk_weilai_sw_6", "0", "0"},
[4002000106] = {4002000106, 10020001, 94, 4, "0", "idle2", "爸爸……媽媽……姐姐……", "お父さん……お母さん……お姉ちゃん……", "0", "0", "0", "0", "cv_sk_weilai_sw_7", "0", "0"},
[4002000107] = {4002000107, 10020001, 94, 4, "0", "idle2", "對、對不起……我讓大家失望了……都是我的錯……", "ご、ごめんなさい……みんなをガッカリさせてしまって…。…私のせいです。", "0", "0", "0", "0", "cv_sk_weilai_sw_8", "0", "0"},
[4002000108] = {4002000108, 10020001, 94, 4, "0", "idle2", "一、一定是因為我的原因……要是我能堅持下去就好了……嗚……", "わ、私のせいですよね…。…私が頑張っていれば……うう……。", "0", "0", "0", "0", "cv_sk_weilai_sw_9", "0", "0"},
[4002000109] = {4002000109, 10020001, 92, 5, "14_1_0_0.8", "touch1", "誒~我睡覺的時候有說夢話！？說、說了什麼？不告訴我？大壞蛋！", "え！？私、寝てる時に寝言言ってるんですか！？な、なんて言ってるんですか？教えない？いじわる過ぎます！", "0", "0", "0", "0", "cv_sk_weilai_sw_10", "0", "0"},
[4002000110] = {4002000110, 10020001, 92, 5, "14_1_0_0.8", "touch1", "是不是被我的睡顏震撼得說不出話了？……口，口水！？哪、哪裡？", "私の寝顔に心打たれて言葉も出ませんか？……よ、ヨダレが付いてる！？ど、どこですか？", "0", "0", "0", "0", "cv_sk_weilai_sw_11", "0", "0"},
[4002000111] = {4002000111, 10020001, 93, 5, "14_2_0_0.8", "touch_s1", "哈~好困~", "はぁ～眠いです～。", "0", "0", "0", "0", "cv_sk_weilai_sw_46", "0", "0"},
[4002000112] = {4002000112, 10020001, 95, 5, "14_1_0_0.8", "touch2", "領航……救救我……嗚……", "ナビゲーターさん……助けてください…。…うう……。", "0", "0", "0", "0", "cv_sk_weilai_sw_47", "0", "0"},
[4002000113] = {4002000113, 10020001, 95, 5, "14_1_0_0.8", "touch2", "我、我下一次一定會做好的……所、所以請再相信我一次吧……", "つ、次はちゃんとやるので……も、もう一度信用して貰えませんか……。", "0", "0", "0", "0", "cv_sk_weilai_sw_48", "0", "0"},
[4002000114] = {4002000114, 10020001, 96, 5, "14_2_0_0.8", "touch_s2", "姆姆——", "むむ…。", "0", "0", "0", "0", "cv_sk_weilai_sw_49", "0", "0"},
[4002000115] = {4002000115, 10020001, 12, 6, "0", "0", "這樣就變強了……好沒有實感……等一下還要特訓？誒——", "これで強くなったんですね……実感はありませんが。後で特訓がある？え～…。", "0", "0", "0", "0", "cv_sk_weilai_sw_12", "0", "0"},
[4002000116] = {4002000116, 10020001, 13, 7, "0", "0", "呀啊啊啊啊——！有什麼東西進到我身體內的感覺！麻麻的！好噁心！變態先生就是這樣用【通感】性騷擾其他女主角的嗎！", "ぎゃああああ！何かが体の中に入って来きます！ムズムズします！気持ち悪い！変態さん、通感覚でヒロイン達にこんなセクハラじみたことしてたんですか！？", "0", "0", "0", "0", "cv_sk_weilai_sw_13", "0", "0"},
[4002000117] = {4002000117, 10020001, 14, 8, "0", "0", "好累啊——我受不了了，特訓要不還是算了吧！", "疲れました…もう限界です…！やっぱり特訓はやめておきましょう！", "0", "0", "0", "0", "cv_sk_weilai_sw_14", "0", "0"},
[4002000118] = {4002000118, 10020001, 15, 9, "0", "0", "誒……你說希望和我保護大家……真是的太狡猾了竟然說這種話……我、我儘量回應你的期待吧。", "えっ？……私と一緒にみんなを守りたいって……ほんと言い回しが卑怯ですねあなたって。……わ、私もできるだけ頑張ってみますよ。", "0", "0", "0", "0", "cv_sk_weilai_sw_15", "0", "0"},
[4002000119] = {4002000119, 10020001, 16, 10, "0", "0", "啊？我也要上戰場嗎？", "は？私も戦場に出るんですか？", "0", "0", "0", "0", "cv_sk_weilai_sw_16", "0", "0"},
[4002000120] = {4002000120, 10020001, 17, 11, "0", "0", "輕、輕鬆拿下了，呼，我已經對當駕駛員這件事沒興趣了。", "ら、楽勝でしたね。ふぅ…私、もうドライバーという仕事に飽きちゃったかもです。", "0", "0", "0", "0", "cv_sk_weilai_sw_17", "0", "0"},
[4002000121] = {4002000121, 10020001, 18, 12, "0", "0", "快點回家吧！", "早く家に帰りましょう！", "0", "0", "0", "0", "cv_sk_weilai_sw_18", "0", "0"},
[4002000122] = {4002000122, 10020001, 19, 13, "0", "0", "啊！剛剛——鐳射擦著我的額頭飛過去啦！", "わっ！いま、光線が私のおでこを掠めていきましたよ！", "0", "0", "0", "0", "cv_sk_weilai_sw_19", "0", "0"},
[4002000123] = {4002000123, 10020001, 20, 14, "0", "0", "誒……這種情況該怎麼辦……要、要不領航和我一起當逃兵吧！", "あ、ああ……この状況、一体どうすれば…。な、ナビゲーターさん、一緒に逃げましょう！", "0", "0", "0", "0", "cv_sk_weilai_sw_20", "0", "0"},
[4002000124] = {4002000124, 10020001, 21, 15, "0", "0", "好厲害！", "やった！", "0", "0", "0", "0", "cv_sk_weilai_sw_21", "0", "0"},
[4002000125] = {4002000125, 10020001, 23, 16, "0", "0", "太、太麻煩了", "め、めんどくさい…。", "0", "0", "0", "0", "cv_sk_weilai_sw_22", "0", "0"},
[4002000126] = {4002000126, 10020001, 26, 19, "0", "0", "嗚……誰來救救我……", "うぅ……誰か助けてください……", "0", "0", "0", "0", "cv_sk_weilai_sw_23", "0", "0"},
[4002000127] = {4002000127, 10020001, 24, 17, "0", "0", "消失吧！", "消えてください！", "0", "0", "0", "0", "cv_sk_weilai_sw_24", "0", "0"},
[4002000128] = {4002000128, 10020001, 25, 18, "0", "0", "海濱樂園管理員出擊！", "シーサイドパラダイス管理人、出撃です！", "0", "0", "0", "0", "cv_sk_weilai_sw_25", "0", "0"},
[4002000129] = {4002000129, 10020001, 27, 20, "0", "0", "嗯……你要和我一起洗？好、好啊，來吧。我已經做好準備了。", "へぇ……私と一緒にお風呂に入りたいんですか？い、いいでしょう。準備はできてますので。", "0", "0", "0", "0", "cv_sk_weilai_sw_27", "0", "0"},
[4002000130] = {4002000130, 10020001, 28, 21, "0", "0", "原、原來說是洗澡就真的只是洗澡嗎！？太奇怪了吧！", "お、お風呂に入るってほんとにお風呂に入るだけって意味だったんですか！？おかしくないですか！？", "0", "0", "0", "0", "cv_sk_weilai_sw_28", "0", "0"},
[4002000131] = {4002000131, 10020001, 29, 21, "0", "0", "巨大化之後和你一起洗澡！？能想到這種玩法……果然不愧是變態先生！你的性癖也太奇怪了吧……！", "巨大化した私と一緒にお風呂に入りたい！？そんなやり方が……さすがは変態さんですね！あなたの性癖には驚かされてばかりですよ……！", "0", "0", "0", "0", "cv_sk_weilai_sw_29", "0", "0"},
[4002000132] = {4002000132, 10020001, 30, 22, "0", "0", "這是……懲罰遊戲？", "これって罰ゲームですか…？", "0", "0", "0", "0", "cv_sk_weilai_sw_30", "0", "0"},
[4002000133] = {4002000133, 10020001, 31, 23, "0", "0", "我可不保證你答錯了之後會發生什麼事情……", "答えを間違えたらどうなるか分かってますよね……", "0", "0", "0", "0", "cv_sk_weilai_sw_31", "0", "0"},
[4002000134] = {4002000134, 10020001, 32, 24, "0", "0", "我就知道你能認出來，因為我可是你的女主角呀！", "間違うはずがないって思ってましたよ。だって私はあなたのヒロインですもんね！", "0", "0", "0", "0", "cv_sk_weilai_sw_32", "0", "0"},
[4002000135] = {4002000135, 10020001, 33, 25, "0", "0", "明、明明說好要把我放在心上的……", "わ、私のことを気にかけてるって言ってたくせに……", "0", "0", "0", "0", "cv_sk_weilai_sw_33", "0", "0"},
[4002000136] = {4002000136, 10020001, 34, 26, "0", "0", "啊~領航你剛剛也睡著了哦，多虧有我看著，不然你的腳就要被小螃蟹夾住了，嘿嘿。", "あ、ナビゲーターさん、今寝てましたよね？私が見てあげてなかったら、足をカニに挟まれるところでしたよ。えへへ。", "0", "0", "0", "0", "cv_sk_weilai_sw_34", "0", "0"},
[4002000137] = {4002000137, 10020001, 35, 27, "0", "0", "不要——我不想戰鬥——好危險——！", "いやです！戦いたくありませんっ！危な過ぎます！", "0", "0", "0", "0", "cv_sk_weilai_sw_35", "0", "0"},
[4002000138] = {4002000138, 10020001, 36, 28, "0", "0", "演、演習……可以試試……", "え、演習ですか？……やってみてもいいですけど……。", "0", "0", "0", "0", "cv_sk_weilai_sw_36", "0", "0"},
[4002000139] = {4002000139, 10020001, 37, 29, "0", "0", "大家好可靠……", "みんな頼もしいです……", "0", "0", "0", "0", "cv_sk_weilai_sw_37", "0", "0"},
[4002000140] = {4002000140, 10020001, 38, 30, "0", "0", "說起來……泳裝也算裝備嗎……", "そう言えば……水着も装備品なんですよね……", "0", "0", "0", "0", "cv_sk_weilai_sw_38", "0", "0"},
[4002000141] = {4002000141, 10020001, 39, 31, "0", "0", "……明明是為了保護世界而研發的裝甲竟然不是免費配給駕駛員……好奇怪啊。", "……世界を救うために開発された装甲が、ドライバーにタダで提供されないなんて……なんかおかしいですよね。", "0", "0", "0", "0", "cv_sk_weilai_sw_39", "0", "0"},
[4002000142] = {4002000142, 10020001, 40, 32, "0", "0", "變態先生……我、我還沒工作，真的能進這種店嗎……", "変態さん……わ、私、仕事もしてないのに、こんなお店入っていいんですか……？", "0", "0", "0", "0", "cv_sk_weilai_sw_40", "0", "0"},
[4002000143] = {4002000143, 10020001, 41, 33, "0", "0", "把我的照片也放在變態先生這裡吧！", "私の写真も変態さんのところに置いておいてください！", "0", "0", "0", "0", "cv_sk_weilai_sw_41", "0", "0"},
[4002000144] = {4002000144, 10020001, 42, 34, "0", "0", "把所有人都禁言看看。", "全員ミュートしてみたらどうですかね。", "0", "0", "0", "0", "cv_sk_weilai_sw_42", "0", "0"},
[4002000145] = {4002000145, 10020001, 43, 35, "0", "0", "變態先生的家門口竟然有郵箱，好復古啊~", "変態さんの家ってポストが置いてあるんですか。レトロですね。", "0", "0", "0", "0", "cv_sk_weilai_sw_43", "0", "0"},
[4002000146] = {4002000146, 10020001, 44, 36, "0", "0", "喂——變態先生有聽到回音嗎？", "ちょっと、変態さん、返信来てませんか？", "0", "0", "0", "0", "cv_sk_weilai_sw_44", "0", "0"},
[4002000147] = {4002000147, 10020001, 45, 37, "0", "0", "這是什麼？", "これなんですか？", "0", "0", "0", "0", "cv_sk_weilai_sw_45", "0", "0"},
[4002100100] = {4002100100, 10021001, 1, 1, "0", "0", "蒼霧殘響。", "蒼霧殘響（ハツリバーブ）。", "0", "0", "0", "0", "cv_sk_xinxiya_33", "0", "0"},
[4002100101] = {4002100101, 10021001, 2, 2, "0", "0", "交給我們吧。", "私たちに任せてください。", "0", "0", "0", "0", "cv_sk_xinxiya_2", "0", "0"},
[4002100102] = {4002100102, 10021001, 3, 3, "0", "0", "初次見面，多瑙的領航，我們是兩人一體的駕駛員，辛西婭，辛米亞。", "はじめまして、ダニューブのナビゲーター。私たちは二つで一つのドライバー、シンシアとシンミアです。", "0", "0", "0", "0", "cv_sk_xinxiya_1", "0", "0"},
[4002100103] = {4002100103, 10021001, 4, 4, "0", "idle", "光是站在這裏稍微有些無聊……\n不如一起出去轉轉吧，領航。", "立っているだけでは少し退屈ですから……。みんなでお散歩に行こうよ！ナビゲーター。", "0", "0", "0", "0", "cv_sk_xinxiya_3", "0", "0"},
[4002100104] = {4002100104, 10021001, 5, 4, "0", "idle", "方舟周邊沒有任何敵人，還請不用太過操心。\n即便是出現敵人了，我們也能在瞬間搞定吧。", "方舟周辺に敵影、ありません。大丈夫です。もし敵がきても、私たちなら一瞬でやっつけちゃうしね。", "0", "0", "0", "0", "cv_sk_xinxiya_4", "0", "0"},
[4002100105] = {4002100105, 10021001, 6, 4, "0", "idle", "真羡慕你可以全世界到處跑啊，我們基本上就只能在方舟上行動。", "世界中を旅できるナビゲーターが羨ましいなあ。私たちは基本方舟に乗ってるだけだからねー。", "0", "0", "0", "0", "cv_sk_xinxiya_30", "0", "0"},
[4002100106] = {4002100106, 10021001, 7, 5, "15_1_0_0.8", "level1", "機會難得，週末一起和芙羅拉到城裏逛逛吧，領航也要一起來嗎？", "せっかくの機會ですから、週末はフローラと一緒に街に行く予定です。……ナビゲーターもご一緒にいかがですか？", "0", "0", "0", "0", "cv_sk_xinxiya_31", "0", "0"},
[4002100107] = {4002100107, 10021001, 8, 5, "15_1_0_0.8", "level1", "哎？是在叫我嗎？還是說，辛米亞？", "あ……私に何か、ご用でしょうか？それとも、シンミアにですか？", "0", "0", "0", "0", "cv_sk_xinxiya_5", "0", "0"},
[4002100108] = {4002100108, 10021001, 9, 5, "15_1_0_0.8", "level1", "想要和辛西婭處好關係嗎？我能告訴你方法哦。\n辛米亞……", "シンシアと仲良くなりたいの？じゃあいい方法を教えるね。シンミア……", "0", "0", "0", "0", "cv_sk_xinxiya_6", "0", "0"},
[4002100109] = {4002100109, 10021001, 10, 5, "15_2_0_0.8", "level2", "嗯……抱歉，我對你沒有任何印象。不過話說回來我對除了辛西婭外的所有人都沒有什麼印象。但是潛意識裏，我還是覺得你是個對我還有她而言非常重要的人。", "えーっと……ごめんね。あなたのこと、覚えてないんだ。っていうより、私はシンシア以外の人のことはあんまり覚えてないの。でもなぜか、私にも、シンシアにも、あなたがとても大切な人だって気がするんだ。", "0", "0", "0", "0", "cv_sk_xinxiya_7", "0", "0"},
[4002100110] = {4002100110, 10021001, 11, 5, "15_2_0_0.8", "level2", "正如你所見，她就像是我的影子一樣。如果你不介意的話，我們三個人就像現在這樣相處就好……", "ご覧の通り、私とシンミアは表裏一體の存在。もしあなたが宜しければ、私達三人、このままで……いたいです……", "0", "0", "0", "0", "cv_sk_xinxiya_8", "0", "0"},
[4002100111] = {4002100111, 10021001, 12, 6, "0", "0", "一起變強吧，辛米亞。", "一緒に強くなろう。シンミア。", "0", "0", "0", "0", "cv_sk_xinxiya_9", "0", "0"},
[4002100112] = {4002100112, 10021001, 13, 7, "0", "0", "太好了，辛西婭，這樣一來我們就變得更強了！。", "やったね、シンシア！これで私たち、もっと強くなれたよ！", "0", "0", "0", "0", "cv_sk_xinxiya_10", "0", "0"},
[4002100113] = {4002100113, 10021001, 14, 8, "0", "0", "和你們一起抵達這裏的此刻，是我人生中最寶貴的時刻。", "あなたと一緒にここまで來ることができました。いま私は、人生で一番大切な瞬間を迎えています……", "0", "0", "0", "0", "cv_sk_xinxiya_11", "0", "0"},
[4002100114] = {4002100114, 10021001, 15, 9, "0", "0", "辛米亞，一起試試新的技能吧。", "シンミア、一緒に新しいスキルを試してみよう！", "0", "0", "0", "0", "cv_sk_xinxiya_12", "0", "0"},
[4002100115] = {4002100115, 10021001, 16, 10, "0", "0", "一起上吧，辛米亞。", "シンミア、一緒に行こう。", "0", "0", "0", "0", "cv_sk_xinxiya_13", "0", "0"},
[4002100116] = {4002100116, 10021001, 17, 11, "0", "0", "戰鬥結束，下次再一起並肩作戰吧。", "戦闘終了。次も一緒に戦いましょう。", "0", "0", "0", "0", "cv_sk_xinxiya_14", "0", "0"},
[4002100117] = {4002100117, 10021001, 18, 12, "0", "0", "哎嘿嘿，稍微有點點小失誤就別在意啦。", "えへへ。ちょっとぐらいのミスは気にしない、気にしない！", "0", "0", "0", "0", "cv_sk_xinxiya_15", "0", "0"},
[4002100118] = {4002100118, 10021001, 19, 13, "0", "0", "對不起…我明明可以做得更好的……", "すみません…もっと上手くできたはず……", "0", "0", "0", "0", "cv_sk_xinxiya_16", "0", "0"},
[4002100119] = {4002100119, 10021001, 20, 14, "0", "0", "絕對…不能讓你們傷害辛西婭……", "絶対に…シンシアを傷つけさせない…！", "0", "0", "0", "0", "cv_sk_xinxiya_17", "0", "0"},
[4002100120] = {4002100120, 10021001, 21, 15, "0", "0", "到此為止了……", "ここまでです…！", "0", "0", "0", "0", "cv_sk_xinxiya_19", "0", "0"},
[4002100121] = {4002100121, 10021001, 23, 16, "0", "0", "辛西婭，交給你了！", "シンシア、任せたよ！", "0", "0", "0", "0", "cv_sk_xinxiya_18", "0", "0"},
[4002100122] = {4002100122, 10021001, 26, 19, "0", "0", "辛西婭…", "シンシア……", "0", "0", "0", "0", "cv_sk_xinxiya_20", "0", "0"},
[4002100123] = {4002100123, 10021001, 24, 17, "0", "0", "剩下的交給我吧！", "後はお任せてください！", "0", "0", "0", "0", "cv_sk_xinxiya_21", "0", "0"},
[4002100124] = {4002100124, 10021001, 25, 18, "0", "0", "辛米亞！\n在~\n一起來完成最後一擊吧。\n收到！", "シンミア！はーい！とどめを一緒にっ！ラジャー！", "0", "0", "0", "0", "cv_sk_xinxiya_22", "0", "0"},
[4002100125] = {4002100125, 10021001, 27, 20, "0", "0", "被水沒過身體的感覺真糟糕……", "水沒したみたいで、気持ち悪いです……", "0", "0", "0", "0", "cv_sk_xinxiya_23", "0", "0"},
[4002100126] = {4002100126, 10021001, 28, 21, "0", "0", "要是能換成淋浴式的就好了。", "シャワーでもいいですか……", "0", "0", "0", "0", "cv_sk_xinxiya_24", "0", "0"},
[4002100127] = {4002100127, 10021001, 29, 21, "0", "0", "不用擔心我，過段時間我就會自己消失啦，所以不洗也無所謂。", "私のことなら気にしないで。そのうち消えるんだから、洗わなくてもいいよね。", "0", "0", "0", "0", "cv_sk_xinxiya_25", "0", "0"},
[4002100128] = {4002100128, 10021001, 30, 22, "0", "0", "小心！", "気をつけて！", "0", "0", "0", "0", "cv_sk_xinxiya_26", "0", "0"},
[4002100129] = {4002100129, 10021001, 31, 23, "0", "0", "我們應該很好就猜對了吧。", "私たちを當てるのは簡単だよね。", "0", "0", "0", "0", "cv_sk_xinxiya_27", "0", "0"},
[4002100130] = {4002100130, 10021001, 32, 24, "0", "0", "回答正確。", "正解です。", "0", "0", "0", "0", "cv_sk_xinxiya_28", "0", "0"},
[4002100131] = {4002100131, 10021001, 33, 25, "0", "0", "回答錯誤！", "はっずれー！", "0", "0", "0", "0", "cv_sk_xinxiya_29", "0", "0"},
[4002100132] = {4002100132, 10021001, 34, 26, "0", "0", "歡迎回來。", "お帰りなさい。", "0", "0", "0", "0", "cv_sk_xinxiya_32", "0", "0"},
[4002100133] = {4002100133, 10021001, 35, 27, "0", "0", "一起行動吧，辛米亞。", "シンミア、一緒に行くよ。", "0", "0", "0", "0", "cv_sk_xinxiya_34", "0", "0"},
[4002100134] = {4002100134, 10021001, 36, 28, "0", "0", "發揮出全部的實力吧，辛西婭。", "シンシア、実力を全部出そう。", "0", "0", "0", "0", "cv_sk_xinxiya_35", "0", "0"},
[4002100135] = {4002100135, 10021001, 37, 29, "0", "0", "同隊的夥伴都在這裏了。", "同じ部隊の仲間はみんなここに。", "0", "0", "0", "0", "cv_sk_xinxiya_36", "0", "0"},
[4002100136] = {4002100136, 10021001, 38, 30, "0", "0", "朋友多多益善~", "友達は多いに越したことないねー。", "0", "0", "0", "0", "cv_sk_xinxiya_37", "0", "0"},
[4002100137] = {4002100137, 10021001, 39, 31, "0", "0", "裝備多多益善。", "裝備は多いに越したことはありません。", "0", "0", "0", "0", "cv_sk_xinxiya_38", "0", "0"},
[4002100138] = {4002100138, 10021001, 40, 32, "0", "0", "一起去購物吧。", "一緒に買い物に。", "0", "0", "0", "0", "cv_sk_xinxiya_39", "0", "0"},
[4002100139] = {4002100139, 10021001, 41, 33, "0", "0", "需要更新個人資料嗎？", "個人プロフィールの更新ですか？", "0", "0", "0", "0", "cv_sk_xinxiya_40", "0", "0"},
[4002100140] = {4002100140, 10021001, 42, 34, "0", "0", "變更設置。", "設定を変更します。", "0", "0", "0", "0", "cv_sk_xinxiya_41", "0", "0"},
[4002100141] = {4002100141, 10021001, 43, 35, "0", "0", "收到的信件都在這裏了。", "メールはこちらです。", "0", "0", "0", "0", "cv_sk_xinxiya_42", "0", "0"},
[4002100142] = {4002100142, 10021001, 44, 36, "0", "0", "大家已經到齊了吧。", "全員到著したようです。", "0", "0", "0", "0", "cv_sk_xinxiya_43", "0", "0"},
[4002100143] = {4002100143, 10021001, 45, 37, "0", "0", "交給我們吧。", "私たちに任せて。", "0", "0", "0", "0", "cv_sk_xinxiya_44", "0", "0"},
[4002600100] = {4002600100, 10026001, 1, 1, "0", "0", "蒼~霧~殘~響", "は・つ・り・ば・あ・ぶ～。", "0", "0", "0", "0", "cv_sk_nasijia_1", "0", "0"},
[4002600101] = {4002600101, 10026001, 2, 2, "0", "0", "我可不保證會發生什麼事哦~", "何が起こっても知らないよ～。", "0", "0", "0", "0", "cv_sk_nasijia_2", "0", "0"},
[4002600102] = {4002600102, 10026001, 3, 3, "0", "0", "吼呀，好年輕的領航呀，還以為會是個滿身汗味的臭大叔呢。", "へぇ、ナビゲーターなのに若いのね。汗臭い中年おやじだと思ってたのに。", "0", "0", "0", "0", "cv_sk_nasijia_3", "0", "0"},
[4002600103] = {4002600103, 10026001, 91, 4, "0", "idle", "你要不也來這坐著吧，反正看你也很閑呢。", "あんたもこっちに座ったら？どうせヒマなんでしょ。", "0", "0", "0", "0", "cv_sk_nasijia_4", "0", "0"},
[4002600104] = {4002600104, 10026001, 94, 4, "0", "idle2", "突然想到件有趣的事，想知道的話就跪下來求我吧。", "面白いこと思い付いちゃった。知りたい？じゃあそこで四つん這いになって。", "0", "0", "0", "0", "cv_sk_nasijia_5", "0", "0"},
[4002600105] = {4002600105, 10026001, 94, 4, "0", "idle2", "我和隊伍的其他駕駛員當然不一樣了，只是掛名在這而已，你不會這都弄不清楚吧，笨蛋領航。", "あたしはあの娘たちとは全然違うの。ただ所屬してるだけ。その辺、勘違いしないでよね。バカナビゲーター。", "0", "0", "0", "0", "cv_sk_nasijia_6", "0", "0"},
[4002600106] = {4002600106, 10026001, 92, 5, "14_1_0_0.8", "touch1", "我可要呼叫警備了哦。", "大人のひと呼んじゃおっかな～。", "0", "0", "0", "0", "cv_sk_nasijia_7", "0", "0"},
[4002600107] = {4002600107, 10026001, 93, 5, "14_2_0_0.8", "touch_s1", "在這大庭廣眾之下，領航不會想對我做那種事情吧。", "こんな人目につくところで、まさか何もするわけないよね。", "0", "0", "0", "0", "cv_sk_nasijia_8", "0", "0"},
[4002600108] = {4002600108, 10026001, 95, 5, "14_1_0_0.8", "touch2", "誒~原來領航比我大這麼多嗎？外表上完全看不出呢。一下子變成大叔了呢，領航大叔。", "え～ナビゲーターってあたしよりそんなに年上なの？見た目じゃ分かんないもんね。もうおじさんじゃん。おじさんナビゲーター。", "0", "0", "0", "0", "cv_sk_nasijia_9", "0", "0"},
[4002600109] = {4002600109, 10026001, 96, 5, "14_2_0_0.8", "touch_s2", "聽說領航被人惡作劇了呀，嘻嘻。加了辣椒醬的果汁一飲而盡的樣子真是太好笑了……當然不是我做的啦，我可是一直在這站崗呢，笨蛋大叔。", "ナビゲーター、イタズラされたんだって？ふふ。ホットソース入りのジュースを一気飲みした時の顔ったら、ホンット最高……ん？あたしじゃないってば。ずっとここにいたじゃない。バカおじ。", "0", "0", "0", "0", "cv_sk_nasijia_10", "0", "0"},
[4002600110] = {4002600110, 10026001, 95, 5, "14_1_0_0.8", "touch2", "明天晚上有空嗎?我有些話想對領航說……或者現在……領航，我喜……喜……啊哈哈哈，上當了吧，你的心剛才跳得好快哦。不會真以為我會向你表白吧，笨蛋大叔。", "明日の夜、空いてる？ナビゲーターにちょっと話があって……い、今でもいいんだけどさ……ナビゲーター、す……す……あはは！引っかかったー！心臓ばくばくだったでしょ。あたしが告白するって本気で思ったの？チョロおじー。", "0", "0", "0", "0", "cv_sk_nasijia_11", "0", "0"},
[4002600111] = {4002600111, 10026001, 12, 6, "0", "0", "才這點就想打發我嗎？", "こんなんであたしが納得すると思ってんの？", "0", "0", "0", "0", "cv_sk_nasijia_12", "0", "0"},
[4002600112] = {4002600112, 10026001, 13, 7, "0", "0", "這還差不多。", "まあまあかな。", "0", "0", "0", "0", "cv_sk_nasijia_13", "0", "0"},
[4002600113] = {4002600113, 10026001, 14, 8, "0", "0", "怎麼樣，被我的強大給嚇到了吧。", "どう？あたしの強さに言葉も出ないでしょ。", "0", "0", "0", "0", "cv_sk_nasijia_14", "0", "0"},
[4002600114] = {4002600114, 10026001, 15, 9, "0", "0", "感覺肩膀輕鬆了不少。", "あら。肩がだいぶ軽くなったかも。", "0", "0", "0", "0", "cv_sk_nasijia_15", "0", "0"},
[4002600115] = {4002600115, 10026001, 16, 10, "0", "0", "好多敵人哦，我好害怕哦。", "敵がいっぱいでこわ～い。", "0", "0", "0", "0", "cv_sk_nasijia_16", "0", "0"},
[4002600116] = {4002600116, 10026001, 17, 11, "0", "0", "還沒怎麼用力就倒下了，真弱。", "もう終わり？まだ本気出していないのに。マジモンのザコね。", "0", "0", "0", "0", "cv_sk_nasijia_17", "0", "0"},
[4002600117] = {4002600117, 10026001, 18, 12, "0", "0", "我只是稍微放放水而已。", "ちょっと手を抜いてあげたの。", "0", "0", "0", "0", "cv_sk_nasijia_18", "0", "0"},
[4002600118] = {4002600118, 10026001, 19, 13, "0", "0", "這樣都贏不了我。", "これだけ手加減しても勝てないの？", "0", "0", "0", "0", "cv_sk_nasijia_19", "0", "0"},
[4002600119] = {4002600119, 10026001, 20, 14, "0", "0", "這可不是我的問題。", "言っとくけど、あたしのせいじゃないからね。", "0", "0", "0", "0", "cv_sk_nasijia_20", "0", "0"},
[4002600120] = {4002600120, 10026001, 21, 15, "0", "0", "果然雜魚就是雜魚。", "やっぱりザコはザコね。", "0", "0", "0", "0", "cv_sk_nasijia_21", "0", "0"},
[4002600121] = {4002600121, 10026001, 23, 16, "0", "0", "去死吧，雜魚。", "死んじゃえ。このザコ。", "0", "0", "0", "0", "cv_sk_nasijia_23", "0", "0"},
[4002600122] = {4002600122, 10026001, 26, 19, "0", "0", "哦？沒想到還挺堅強的嘛，雜魚。", "ん？思ったより頑張るじゃん。ザコのくせに。", "0", "0", "0", "0", "cv_sk_nasijia_24", "0", "0"},
[4002600123] = {4002600123, 10026001, 24, 17, "0", "0", "老實一點，雜魚就要有雜魚的覺悟。", "覚悟決めなさいよ。ザコはザコらしくさ。", "0", "0", "0", "0", "cv_sk_nasijia_25", "0", "0"},
[4002600124] = {4002600124, 10026001, 25, 18, "0", "0", "肚子有些不舒服，先撤退了。", "ちょっとお腹の調子が……先に撤退しよーっと。", "0", "0", "0", "0", "cv_sk_nasijia_26", "0", "0"},
[4002600125] = {4002600125, 10026001, 27, 20, "0", "0", "還有這種地方？", "こんな場所まであるの？", "0", "0", "0", "0", "cv_sk_nasijia_27", "0", "0"},
[4002600126] = {4002600126, 10026001, 28, 21, "0", "0", "你就只會看著嗎？", "あんた、見てることしかできないわけ？", "0", "0", "0", "0", "cv_sk_nasijia_28", "0", "0"},
[4002600127] = {4002600127, 10026001, 29, 21, "0", "0", "很想觸碰吧，我的身體。", "觸りたいんでしょ？あたしの體。", "0", "0", "0", "0", "cv_sk_nasijia_29", "0", "0"},
[4002600128] = {4002600128, 10026001, 30, 22, "0", "0", "誰允許你亂碰了。", "勝手に觸んないでよね。", "0", "0", "0", "0", "cv_sk_nasijia_30", "0", "0"},
[4002600129] = {4002600129, 10026001, 31, 23, "0", "0", "以大叔的智力來說是不是有點困難呢？", "おじさんの知能だとちょっと難しかったかなぁ？", "0", "0", "0", "0", "cv_sk_nasijia_31", "0", "0"},
[4002600130] = {4002600130, 10026001, 32, 24, "0", "0", "哈，勉強算及格吧。", "ふん。ギリ合格かな。", "0", "0", "0", "0", "cv_sk_nasijia_32", "0", "0"},
[4002600131] = {4002600131, 10026001, 33, 25, "0", "0", "笨蛋！白癡！", "バカ！間抜け！", "0", "0", "0", "0", "cv_sk_nasijia_33", "0", "0"},
[4002600132] = {4002600132, 10026001, 34, 26, "0", "0", "又孤零零一個人來向我尋求安慰了嗎？", "相手がいないからって、またあたしに慰めてもらいに來たの？", "0", "0", "0", "0", "cv_sk_nasijia_34", "0", "0"},
[4002600133] = {4002600133, 10026001, 35, 27, "0", "0", "這種雜魚還需要我出手嗎？", "この程度のザコ相手にあたしが出るわけ？", "0", "0", "0", "0", "cv_sk_nasijia_35", "0", "0"},
[4002600134] = {4002600134, 10026001, 36, 28, "0", "0", "憑什麼要跟她們打？", "なんであいつらと戦わなきゃいけないのよ？", "0", "0", "0", "0", "cv_sk_nasijia_36", "0", "0"},
[4002600135] = {4002600135, 10026001, 37, 29, "0", "0", "她們是誰！", "……誰、あいつら？", "0", "0", "0", "0", "cv_sk_nasijia_37", "0", "0"},
[4002600136] = {4002600136, 10026001, 38, 30, "0", "0", "真是精力旺盛呢。", "ほんと元気だけはあるよね。", "0", "0", "0", "0", "cv_sk_nasijia_38", "0", "0"},
[4002600137] = {4002600137, 10026001, 39, 31, "0", "0", "都是些便宜貨。", "子供だましばっかじゃん。", "0", "0", "0", "0", "cv_sk_nasijia_39", "0", "0"},
[4002600138] = {4002600138, 10026001, 40, 32, "0", "0", "給我買根棒棒糖吧。", "ロリポップ買ってよ。", "0", "0", "0", "0", "cv_sk_nasijia_40", "0", "0"},
[4002600139] = {4002600139, 10026001, 41, 33, "0", "0", "哎呀，發現有趣的東西了。", "へ～。面白いもの見付けちゃった。", "0", "0", "0", "0", "cv_sk_nasijia_41", "0", "0"},
[4002600140] = {4002600140, 10026001, 42, 34, "0", "0", "我當然知道這是什麼。", "これが何かなんて、知ってるに決まってるじゃない。", "0", "0", "0", "0", "cv_sk_nasijia_42", "0", "0"},
[4002600141] = {4002600141, 10026001, 43, 35, "0", "0", "真可憐啊，一封情書都沒有呢。", "かわいそ～。ラブレターのひとつも來ないなんて。", "0", "0", "0", "0", "cv_sk_nasijia_43", "0", "0"},
[4002600142] = {4002600142, 10026001, 44, 36, "0", "0", "有我陪你說話還不夠嗎？真實貪婪呢。", "このあたしが話し相手になってあげてるんだから充分でしょ？ほんっと欲張りね。", "0", "0", "0", "0", "cv_sk_nasijia_44", "0", "0"},
[4002600143] = {4002600143, 10026001, 45, 37, "0", "0", "這個。", "これ？", "0", "0", "0", "0", "cv_sk_nasijia_45", "0", "0"},
[4002700100] = {4002700100, 10027001, 1, 1, "0", "0", "蒼霧殘響", "0", "0", "0", "0", "0", "cv_sk_alvitr_1", "0", "0"},
[4002700101] = {4002700101, 10027001, 2, 2, "0", "0", "作為我的領航，如果盡做些無趣的事，那會是對我的侮辱。", "0", "0", "0", "0", "0", "cv_sk_alvitr_2", "0", "0"},
[4002700102] = {4002700102, 10027001, 3, 3, "0", "0", "這次與我合作的對像是你嗎？呵，多瑙的領航，竭盡全力跟上我的步伐吧。", "0", "0", "0", "0", "0", "cv_sk_alvitr_3", "0", "0"},
[4002700103] = {4002700103, 10027001, 91, 4, "0", "idle", "在開戰的時候，我就特例允許你對我使用【通感】。對於這些沒有理智，肆意侵害的害蟲，沒有手下留情的必要。", "0", "0", "0", "0", "0", "cv_sk_alvitr_4", "0", "0"},
[4002700104] = {4002700104, 10027001, 94, 4, "0", "idle2", "很好很好，全都不知所謂地沖上來吧，不用我一個一個去找，原罪也就只有這一個優點能被稱讚了。", "0", "0", "0", "0", "0", "cv_sk_alvitr_5", "0", "0"},
[4002700105] = {4002700105, 10027001, 95, 5, "14_》_0_0.8", "touch1", "原罪是有形的，只要捏碎它們的核心，它們便會死去；但是，我的合作者，你將來要面對的敵人，是絕不會如此輕易被殺死的，你能理解嗎？", "0", "0", "0", "0", "0", "cv_sk_alvitr_6", "0", "0"},
[4002700106] = {4002700106, 10027001, 95, 5, "14_》_0_0.8", "touch1", "不必擔心，我當然還能繼續戰鬥，不過你沒注意到嗎？礙眼的蟲子們早就被全部解決了。", "0", "0", "0", "0", "0", "cv_sk_alvitr_7", "0", "0"},
[4002700107] = {4002700107, 10027001, 95, 5, "14_》_0_0.8", "touch1", "看到了嗎？和原罪不同，只需一瞬，我就能讓這座城市覆滅……人類應該慶倖，慶倖這個世界上有你存在，我的合作者。", "0", "0", "0", "0", "0", "cv_sk_alvitr_8", "0", "0"},
[4002700108] = {4002700108, 10027001, 93, 5, "14_》_0_0.8", "touch_s1", "我的合作者，接下來你將看到我的全力，這是未曾有人得到過的殊榮。", "0", "0", "0", "0", "0", "cv_sk_alvitr_9", "0", "0"},
[4002700109] = {4002700109, 10027001, 92, 5, "14_》_0_0.8", "touch2", "和螻蟻的鬥爭只不過是在浪費時間，我的合作者，你應該明白，我們要粉碎的——可不是區區低等原罪吧？", "0", "0", "0", "0", "0", "cv_sk_alvitr_10", "0", "0"},
[4002700110] = {4002700110, 10027001, 92, 5, "14_》_0_0.8", "touch2", "初次合作就迎來了全數殲滅的勝利，很好，不過對我而言這是理所當然的。你想要什麼樣的獎賞？毋需多言，這是對你合格的賞賜。", "0", "0", "0", "0", "0", "cv_sk_alvitr_11", "0", "0"},
[4002700111] = {4002700111, 10027001, 92, 5, "14_》_0_0.8", "touch2", "城市不斷地在戰鬥中毀滅，又不斷地重建。如果沒有其他人站出來領導他們的話，恐怕他們一輩子都是這個局面，愚昧而又堅韌，也只有這點值得讚賞。", "0", "0", "0", "0", "0", "cv_sk_alvitr_45", "0", "0"},
[4002700112] = {4002700112, 10027001, 96, 5, "14_》_0_0.8", "touch_s2", "怎麼，是擔心破壞的範圍太大了嗎？呵，我能理解，那麼我便收斂一些吧。", "0", "0", "0", "0", "0", "cv_sk_alvitr_46", "0", "0"},
[4002700113] = {4002700113, 10027001, 12, 6, "0", "0", "很好，繼續取悅我吧。", "0", "0", "0", "0", "0", "cv_sk_alvitr_12", "0", "0"},
[4002700114] = {4002700114, 10027001, 13, 7, "0", "0", "還差得遠呢。", "0", "0", "0", "0", "0", "cv_sk_alvitr_13", "0", "0"},
[4002700115] = {4002700115, 10027001, 14, 8, "0", "0", "呵呵呵....多瑙的領航，我認可了為我做到這一步的你。放聲大笑吧，理智淹沒在狂熱中吧，這是凡人能夠得到的最大的殊榮。", "0", "0", "0", "0", "0", "cv_sk_alvitr_14", "0", "0"},
[4002700116] = {4002700116, 10027001, 15, 9, "0", "0", "繼續努力吧。", "0", "0", "0", "0", "0", "cv_sk_alvitr_15", "0", "0"},
[4002700117] = {4002700117, 10027001, 16, 10, "0", "0", "螻蟻，準備接受審判吧。", "0", "0", "0", "0", "0", "cv_sk_alvitr_16", "0", "0"},
[4002700118] = {4002700118, 10027001, 17, 11, "0", "0", "為此歡呼吧，這是你我攜手帶來的勝利。", "0", "0", "0", "0", "0", "cv_sk_alvitr_17", "0", "0"},
[4002700119] = {4002700119, 10027001, 18, 12, "0", "0", "無聊的對手。", "0", "0", "0", "0", "0", "cv_sk_alvitr_18", "0", "0"},
[4002700120] = {4002700120, 10027001, 19, 13, "0", "0", "姑且承認...這次的敵人給我帶來了點困擾。", "0", "0", "0", "0", "0", "cv_sk_alvitr_19", "0", "0"},
[4002700121] = {4002700121, 10027001, 20, 14, "0", "0", "居然被這種對手打敗了...真是丟人。", "0", "0", "0", "0", "0", "cv_sk_alvitr_20", "0", "0"},
[4002700122] = {4002700122, 10027001, 21, 15, "0", "0", "消失吧，真礙眼。", "0", "0", "0", "0", "0", "cv_sk_alvitr_22", "0", "0"},
[4002700123] = {4002700123, 10027001, 23, 16, "0", "0", "無聊。", "0", "0", "0", "0", "0", "cv_sk_alvitr_21", "0", "0"},
[4002700124] = {4002700124, 10027001, 26, 19, "0", "0", "稍微動點真格吧。", "0", "0", "0", "0", "0", "cv_sk_alvitr_24", "0", "0"},
[4002700125] = {4002700125, 10027001, 24, 17, "0", "0", "感到榮幸吧，因為我將賜予你們永恆的死亡！", "0", "0", "0", "0", "0", "cv_sk_alvitr_25", "0", "0"},
[4002700126] = {4002700126, 10027001, 25, 18, "0", "0", "呵呵，這次就到此為止吧。", "0", "0", "0", "0", "0", "cv_sk_alvitr_23", "0", "0"},
[4002700127] = {4002700127, 10027001, 27, 20, "0", "0", "想服侍我嗎？呵，我准許了。", "0", "0", "0", "0", "0", "cv_sk_alvitr_26", "0", "0"},
[4002700128] = {4002700128, 10027001, 28, 21, "0", "0", "誰允許你休息了？", "0", "0", "0", "0", "0", "cv_sk_alvitr_27", "0", "0"},
[4002700129] = {4002700129, 10027001, 29, 21, "0", "0", "允許你侍奉我，是對你一直以來辛苦工作的獎勵。", "0", "0", "0", "0", "0", "cv_sk_alvitr_28", "0", "0"},
[4002700130] = {4002700130, 10027001, 30, 22, "0", "0", "在大驚小怪什麼？", "0", "0", "0", "0", "0", "cv_sk_alvitr_29", "0", "0"},
[4002700131] = {4002700131, 10027001, 31, 23, "0", "0", "我的聲音，還有氣味，難道沒有深刻進你的靈魂嗎？", "0", "0", "0", "0", "0", "cv_sk_alvitr_30", "0", "0"},
[4002700132] = {4002700132, 10027001, 32, 24, "0", "0", "儘管是幼稚的把戲，但你表現得不錯。", "0", "0", "0", "0", "0", "cv_sk_alvitr_31", "0", "0"},
[4002700133] = {4002700133, 10027001, 33, 25, "0", "0", "連這種小事都做不好嗎？", "0", "0", "0", "0", "0", "cv_sk_alvitr_32", "0", "0"},
[4002700134] = {4002700134, 10027001, 34, 26, "0", "0", "真慢啊。既然沒出什麼事就趕緊回到自己的位置上吧，領航。", "0", "0", "0", "0", "0", "cv_sk_alvitr_33", "0", "0"},
[4002700135] = {4002700135, 10027001, 35, 27, "0", "0", "別命令我...走吧，去拯救這個殘破的世界。", "0", "0", "0", "0", "0", "cv_sk_alvitr_34", "0", "0"},
[4002700136] = {4002700136, 10027001, 36, 28, "0", "0", "我可沒有蹂躪弱者的惡趣味。", "0", "0", "0", "0", "0", "cv_sk_alvitr_35", "0", "0"},
[4002700137] = {4002700137, 10027001, 37, 29, "0", "0", "我的隊伍裡可不需要庸才。", "0", "0", "0", "0", "0", "cv_sk_alvitr_36", "0", "0"},
[4002700138] = {4002700138, 10027001, 38, 30, "0", "0", "無聊的流程。", "0", "0", "0", "0", "0", "cv_sk_alvitr_37", "0", "0"},
[4002700139] = {4002700139, 10027001, 39, 31, "0", "0", "拙劣的技術。", "0", "0", "0", "0", "0", "cv_sk_alvitr_38", "0", "0"},
[4002700140] = {4002700140, 10027001, 40, 32, "0", "0", "沒有能入眼的寶物呢。", "0", "0", "0", "0", "0", "cv_sk_alvitr_39", "0", "0"},
[4002700141] = {4002700141, 10027001, 41, 33, "0", "0", "謔，你還蠻有趣的。", "0", "0", "0", "0", "0", "cv_sk_alvitr_40", "0", "0"},
[4002700142] = {4002700142, 10027001, 42, 34, "0", "0", "真原始的方式。", "0", "0", "0", "0", "0", "cv_sk_alvitr_41", "0", "0"},
[4002700143] = {4002700143, 10027001, 43, 35, "0", "0", "盡是些無聊的內容。", "0", "0", "0", "0", "0", "cv_sk_alvitr_42", "0", "0"},
[4002700144] = {4002700144, 10027001, 44, 36, "0", "0", "盡情暢談吧。", "0", "0", "0", "0", "0", "cv_sk_alvitr_43", "0", "0"},
[4002700145] = {4002700145, 10027001, 45, 37, "0", "0", "嗯？", "0", "0", "0", "0", "0", "cv_sk_alvitr_44", "0", "0"},
[4002900100] = {4002900100, 10029001, 1, 1, "0", "0", "蒼霧殘響", "0", "0", "0", "0", "0", "cv_sk_lili_001", "0", "0"},
[4002900101] = {4002900101, 10029001, 2, 2, "0", "0", "會不會被人誤會啊……我現在的樣子看起來不是很糟糕嗎？", "0", "0", "0", "0", "0", "cv_sk_lili_002", "0", "0"},
[4002900102] = {4002900102, 10029001, 3, 3, "0", "0", "黎貝……不對，現在是莉莉，“九頭蛇”的莉莉。領航！我們又見面了！", "0", "0", "0", "0", "0", "cv_sk_lili_003", "0", "0"},
[4002900103] = {4002900103, 10029001, 4, 4, "0", "idle", "嗚嗚嗚——領航，快幫我抓住它們……它們是我“不受控制”的一部分，如果不管它們的話，搞不好會發生糟糕的事情！", "0", "0", "0", "0", "0", "cv_sk_lili_004", "0", "0"},
[4002900104] = {4002900104, 10029001, 5, 4, "0", "idle", "我們這一次相信艾吉斯，不是因為我們原諒了它……而是因為這個地方有你在，領航。我和萊薇相信的人是你。", "0", "0", "0", "0", "0", "cv_sk_lili_005", "0", "0"},
[4002900105] = {4002900105, 10029001, 6, 4, "0", "idle", "它們很可愛？……嗚，畢竟也算是我的一部分……領航，你不要被它們的模樣迷惑了，雖然可愛，但和我不一樣，它們真的是原罪噢！", "0", "0", "0", "0", "0", "cv_sk_lili_006", "0", "0"},
[4002900106] = {4002900106, 10029001, 7, 5, "15_2_0_0.8", "level2", "嗚嗚嗚……不要欺負我，明明我才是“本體”……這樣下去我就要生氣了，真的會生氣的，會發生很恐怖的事情的……大概。", "0", "0", "0", "0", "0", "cv_sk_lili_007", "0", "0"},
[4002900107] = {4002900107, 10029001, 8, 5, "15_1_0_0.8", "level1", "這個時候就不要胡鬧了啦，領航，快來幫幫我啦。", "0", "0", "0", "0", "0", "cv_sk_lili_008", "0", "0"},
[4002900108] = {4002900108, 10029001, 9, 5, "15_1_0_0.8", "level1", "我時不時還能夢到那天晚上的事情，在那個噩夢裏，我變成了怪物，向著自己保護的人揮下爪子……一次又一次地夢到它，怎麼也無法釋懷。", "0", "0", "0", "0", "0", "cv_sk_lili_009", "0", "0"},
[4002900109] = {4002900109, 10029001, 10, 5, "15_1_0_0.8", "level1", "史蒂芬妮博士每次都跟我說，我的身體正在好轉……真的是這樣嗎？我會不會已經……再也回不去了……呼，領航，你會陪著我的吧？", "0", "0", "0", "0", "0", "cv_sk_lili_010", "0", "0"},
[4002900110] = {4002900110, 10029001, 11, 5, "15_1_0_0.8", "level1", "領航，還記得我們那時候定下的約定嗎？嗯，就是你想的那件事。如果那一天真的到來了，請你不要猶豫，做你應該做的事情，這也是我所希望的——我希望能死在你的手下。", "0", "0", "0", "0", "0", "cv_sk_lili_011", "0", "0"},
[4002900111] = {4002900111, 10029001, 12, 6, "0", "0", "我變得更強了嗎？", "0", "0", "0", "0", "0", "cv_sk_lili_012", "0", "0"},
[4002900112] = {4002900112, 10029001, 13, 7, "0", "0", "好美麗的星星。", "0", "0", "0", "0", "0", "cv_sk_lili_013", "0", "0"},
[4002900113] = {4002900113, 10029001, 14, 8, "0", "0", "如果身體不能恢復的話……我也要用這份力量去保護領航和萊薇，因為你們是我僅有的“家人”了。", "0", "0", "0", "0", "0", "cv_sk_lili_014", "0", "0"},
[4002900114] = {4002900114, 10029001, 15, 9, "0", "0", "身體更敏銳了……", "0", "0", "0", "0", "0", "cv_sk_lili_015", "0", "0"},
[4002900115] = {4002900115, 10029001, 16, 10, "0", "0", "嗚喵？", "0", "0", "0", "0", "0", "cv_sk_lili_016", "0", "0"},
[4002900116] = {4002900116, 10029001, 17, 11, "0", "0", "嘿嘿嘿，我很棒吧？", "0", "0", "0", "0", "0", "cv_sk_lili_017", "0", "0"},
[4002900117] = {4002900117, 10029001, 18, 12, "0", "0", "贏了？我們贏了？", "0", "0", "0", "0", "0", "cv_sk_lili_018", "0", "0"},
[4002900118] = {4002900118, 10029001, 19, 13, "0", "0", "沒有出現意外真是太好了。", "0", "0", "0", "0", "0", "cv_sk_lili_019", "0", "0"},
[4002900119] = {4002900119, 10029001, 20, 14, "0", "0", "只要還活著，就沒問題。", "0", "0", "0", "0", "0", "cv_sk_lili_020", "0", "0"},
[4002900120] = {4002900120, 10029001, 21, 15, "0", "0", "喵！", "0", "0", "0", "0", "0", "cv_sk_lili_021", "0", "0"},
[4002900121] = {4002900121, 10029001, 23, 16, "0", "0", "喵喵喵！", "0", "0", "0", "0", "0", "cv_sk_lili_023", "0", "0"},
[4002900122] = {4002900122, 10029001, 26, 19, "0", "0", "救救我……萊薇，領航……", "0", "0", "0", "0", "0", "cv_sk_lili_026", "0", "0"},
[4002900123] = {4002900123, 10029001, 24, 17, "0", "0", "喵喵！", "0", "0", "0", "0", "0", "cv_sk_lili_024", "0", "0"},
[4002900124] = {4002900124, 10029001, 25, 18, "0", "0", "能量……快要暴走了。", "0", "0", "0", "0", "0", "cv_sk_lili_025", "0", "0"},
[4002900125] = {4002900125, 10029001, 27, 20, "0", "0", "嗚哇——是領航？嚇死我了……", "0", "0", "0", "0", "0", "cv_sk_lili_027", "0", "0"},
[4002900126] = {4002900126, 10029001, 28, 21, "0", "0", "體內的能量好像平靜下來了，原來如此，這就是領航在這裏的原因嗎？", "0", "0", "0", "0", "0", "cv_sk_lili_028", "0", "0"},
[4002900127] = {4002900127, 10029001, 29, 21, "0", "0", "領航小小的……在背上走來走去的，有點癢……", "0", "0", "0", "0", "0", "cv_sk_lili_029", "0", "0"},
[4002900128] = {4002900128, 10029001, 30, 22, "0", "0", "誒誒誒？", "0", "0", "0", "0", "0", "cv_sk_lili_030", "0", "0"},
[4002900129] = {4002900129, 10029001, 31, 23, "0", "0", "應該很好猜……吧？", "0", "0", "0", "0", "0", "cv_sk_lili_031", "0", "0"},
[4002900130] = {4002900130, 10029001, 32, 24, "0", "0", "呼……還好猜對了。", "0", "0", "0", "0", "0", "cv_sk_lili_032", "0", "0"},
[4002900131] = {4002900131, 10029001, 33, 25, "0", "0", "嗚嗚嗚，領航欺負人。", "0", "0", "0", "0", "0", "cv_sk_lili_033", "0", "0"},
[4002900132] = {4002900132, 10029001, 34, 26, "0", "0", "領航，今天的身體檢查也拜託你了！", "0", "0", "0", "0", "0", "cv_sk_lili_034", "0", "0"},
[4002900133] = {4002900133, 10029001, 35, 27, "0", "0", "為了領航，為了萊薇，我會戰鬥的！", "0", "0", "0", "0", "0", "cv_sk_lili_035", "0", "0"},
[4002900134] = {4002900134, 10029001, 36, 28, "0", "0", "會被當做原罪的吧……", "0", "0", "0", "0", "0", "cv_sk_lili_036", "0", "0"},
[4002900135] = {4002900135, 10029001, 37, 29, "0", "0", "嗚嗚嗚，大、大家好！", "0", "0", "0", "0", "0", "cv_sk_lili_037", "0", "0"},
[4002900136] = {4002900136, 10029001, 38, 30, "0", "0", "要見其他人了？", "0", "0", "0", "0", "0", "cv_sk_lili_038", "0", "0"},
[4002900137] = {4002900137, 10029001, 39, 31, "0", "0", "誒——會有我的裝備嗎？", "0", "0", "0", "0", "0", "cv_sk_lili_039", "0", "0"},
[4002900138] = {4002900138, 10029001, 40, 32, "0", "0", "要購物嗎？", "0", "0", "0", "0", "0", "cv_sk_lili_040", "0", "0"},
[4002900139] = {4002900139, 10029001, 41, 33, "0", "0", "領航變得更加帥氣了呢。", "0", "0", "0", "0", "0", "cv_sk_lili_041", "0", "0"},
[4002900140] = {4002900140, 10029001, 42, 34, "0", "0", "設置~", "0", "0", "0", "0", "0", "cv_sk_lili_042", "0", "0"},
[4002900141] = {4002900141, 10029001, 43, 35, "0", "0", "需要我幫忙打開嗎？", "0", "0", "0", "0", "0", "cv_sk_lili_043", "0", "0"},
[4002900142] = {4002900142, 10029001, 44, 36, "0", "0", "我不打擾你了~", "0", "0", "0", "0", "0", "cv_sk_lili_044", "0", "0"},
[4002900143] = {4002900143, 10029001, 45, 37, "0", "0", "誒？", "0", "0", "0", "0", "0", "cv_sk_lili_045", "0", "0"},
[4003000100] = {4003000100, 10030001, 1, 1, "0", "0", "蒼霧殘響", "0", "0", "0", "0", "0", "cv_sk_faernaisi_1", "0", "0"},
[4003000101] = {4003000101, 10030001, 2, 2, "0", "0", "父親曾計劃將我培養為參謀，您也有此打算嗎？", "0", "0", "0", "0", "0", "cv_sk_faernaisi_2", "0", "0"},
[4003000102] = {4003000102, 10030001, 3, 3, "0", "0", "我已聽聞您是位通情達理的領航，在此請允許我更多按照家族的規則，而非艾吉斯的規則行事。那麼，“歧花”隊長，法爾奈斯·蘭特向您報道。", "0", "0", "0", "0", "0", "cv_sk_faernaisi_3", "0", "0"},
[4003000103] = {4003000103, 10030001, 4, 4, "0", "idle", "玫瑰花浴之後，讓肌膚充分接觸清新的空氣，享受從天鵝絨窗簾透入的陽光……沒有比這更適合放鬆的了。", "0", "0", "0", "0", "0", "cv_sk_faernaisi_4", "0", "0"},
[4003000104] = {4003000104, 10030001, 5, 4, "0", "idle", "還在兀自沉思嗎？請您盡快翻牌吧，不論會面臨怎樣的結果，我都早已做好準備。", "0", "0", "0", "0", "0", "cv_sk_faernaisi_5", "0", "0"},
[4003000105] = {4003000105, 10030001, 6, 4, "0", "idle", "改天也把歧花的其他幾人叫來吧？人多的話，也許可以玩些更刺激的遊戲。", "0", "0", "0", "0", "0", "cv_sk_faernaisi_6", "0", "0"},
[4003000106] = {4003000106, 10030001, 7, 5, "15_2_0_0.8", "touch1", "既未勝利，也非失敗，我遇上了概率最小的可能啊……看來這場漫長的遊戲還將繼續下去，這是否正如您所願呢？", "0", "0", "0", "0", "0", "cv_sk_faernaisi_7", "0", "0"},
[4003000107] = {4003000107, 10030001, 8, 5, "15_2_0_0.8", "touch2", "對於勝利的渴望幾乎寫在了您的臉上，但可惜，這一輪是我贏了。時刻隱瞞好自己的忐忑和欲求，這才是牌桌上的製勝之道。", "0", "0", "0", "0", "0", "cv_sk_faernaisi_8", "0", "0"},
[4003000108] = {4003000108, 10030001, 9, 5, "15_2_0_0.8", "touch3", "哦？沒想到竟然是我輸了……哎呀，我甚至沒注意到籌碼已經所剩無幾，我究竟該用何物來向您償還才好呢？", "0", "0", "0", "0", "0", "cv_sk_faernaisi_9", "0", "0"},
[4003000109] = {4003000109, 10030001, 10, 5, "15_1_0_0.8", "touch4", "唔……這是在檢查我身上是否藏著牌？真過分啊，雖然我的確不介意出老千，但我這身裝扮，還能往哪裡再藏一張牌呢？", "0", "0", "0", "0", "0", "cv_sk_faernaisi_10", "0", "0"},
[4003000110] = {4003000110, 10030001, 11, 5, "15_1_0_0.8", "touch4", "對選手進行這種幹擾……是違反規則的吧？我倒是不討厭您的這份膽量，但，再這樣下去我可就得以牙還牙了。", "0", "0", "0", "0", "0", "cv_sk_faernaisi_11", "0", "0"},
[4003000111] = {4003000111, 10030001, 12, 6, "0", "0", "何處都得學習啊。", "0", "0", "0", "0", "0", "cv_sk_faernaisi_12", "0", "0"},
[4003000112] = {4003000112, 10030001, 13, 7, "0", "0", "花開之時，也即瀕臨凋謝之際。", "0", "0", "0", "0", "0", "cv_sk_faernaisi_13", "0", "0"},
[4003000113] = {4003000113, 10030001, 14, 8, "0", "0", "父親畏懼我的才能，一度放棄過對我的栽培，看來領航您不會這樣。那麼，今後就請享受我所結出的碩果吧。", "0", "0", "0", "0", "0", "cv_sk_faernaisi_14", "0", "0"},
[4003000114] = {4003000114, 10030001, 15, 9, "0", "0", "這門“手藝”可不能生疏。", "0", "0", "0", "0", "0", "cv_sk_faernaisi_15", "0", "0"},
[4003000115] = {4003000115, 10030001, 16, 10, "0", "0", "這種場地的話……", "0", "0", "0", "0", "0", "cv_sk_faernaisi_16", "0", "0"},
[4003000116] = {4003000116, 10030001, 17, 11, "0", "0", "我們所期望的結果。", "0", "0", "0", "0", "0", "cv_sk_faernaisi_17", "0", "0"},
[4003000117] = {4003000117, 10030001, 18, 12, "0", "0", "可以接受的損失。", "0", "0", "0", "0", "0", "cv_sk_faernaisi_18", "0", "0"},
[4003000118] = {4003000118, 10030001, 19, 13, "0", "0", "得好好反省了。", "0", "0", "0", "0", "0", "cv_sk_faernaisi_19", "0", "0"},
[4003000119] = {4003000119, 10030001, 20, 14, "0", "0", "這種失敗不會有下次。", "0", "0", "0", "0", "0", "cv_sk_faernaisi_20", "0", "0"},
[4003000120] = {4003000120, 10030001, 21, 15, "0", "0", "我贏了。", "0", "0", "0", "0", "0", "cv_sk_faernaisi_21", "0", "0"},
[4003000121] = {4003000121, 10030001, 23, 16, "0", "0", "這張牌如何？", "0", "0", "0", "0", "0", "cv_sk_faernaisi_22", "0", "0"},
[4003000122] = {4003000122, 10030001, 26, 19, "0", "0", "再來一張。", "0", "0", "0", "0", "0", "cv_sk_faernaisi_23", "0", "0"},
[4003000123] = {4003000123, 10030001, 24, 17, "0", "0", "你所對抗的，是整個家族。", "0", "0", "0", "0", "0", "cv_sk_faernaisi_24", "0", "0"},
[4003000124] = {4003000124, 10030001, 25, 18, "0", "0", "計算失敗了。", "0", "0", "0", "0", "0", "cv_sk_faernaisi_26", "0", "0"},
[4003000125] = {4003000125, 10030001, 27, 20, "0", "0", "您不敲門就……好吧，我忘了這種體型是很難聽見敲門聲的。", "0", "0", "0", "0", "0", "cv_sk_faernaisi_27", "0", "0"},
[4003000126] = {4003000126, 10030001, 28, 21, "0", "0", "如此坦誠相待的場合，才最適合用來放鬆，畢竟沒人能在這裡偷偷攜帶武器。", "0", "0", "0", "0", "0", "cv_sk_faernaisi_28", "0", "0"},
[4003000127] = {4003000127, 10030001, 29, 21, "0", "0", "還不快點嗎？還是說……您不願讓這種曖昧的氛圍太快結束呢？", "0", "0", "0", "0", "0", "cv_sk_faernaisi_29", "0", "0"},
[4003000128] = {4003000128, 10030001, 30, 22, "0", "0", "這個動靜……", "0", "0", "0", "0", "0", "cv_sk_faernaisi_30", "0", "0"},
[4003000129] = {4003000129, 10030001, 31, 23, "0", "0", "關於信賴的遊戲嗎。", "0", "0", "0", "0", "0", "cv_sk_faernaisi_31", "0", "0"},
[4003000130] = {4003000130, 10030001, 32, 24, "0", "0", "我也會回應您的重視。", "0", "0", "0", "0", "0", "cv_sk_faernaisi_32", "0", "0"},
[4003000131] = {4003000131, 10030001, 33, 25, "0", "0", "不得不說，我有些失望。", "0", "0", "0", "0", "0", "cv_sk_faernaisi_33", "0", "0"},
[4003000132] = {4003000132, 10030001, 34, 26, "0", "0", "這間私宅別無閒雜人等打擾，接下來我們再玩些什麼好呢？21點、德州撲克……或是陪我試一次露西亞輪盤賭？", "0", "0", "0", "0", "0", "cv_sk_faernaisi_34", "0", "0"},
[4003000133] = {4003000133, 10030001, 35, 27, "0", "0", "出發吧。", "0", "0", "0", "0", "0", "cv_sk_faernaisi_35", "0", "0"},
[4003000134] = {4003000134, 10030001, 36, 28, "0", "0", "一種遊戲。", "0", "0", "0", "0", "0", "cv_sk_faernaisi_36", "0", "0"},
[4003000135] = {4003000135, 10030001, 37, 29, "0", "0", "親信之人嗎。", "0", "0", "0", "0", "0", "cv_sk_faernaisi_37", "0", "0"},
[4003000136] = {4003000136, 10030001, 38, 30, "0", "0", "新的成員啊。", "0", "0", "0", "0", "0", "cv_sk_faernaisi_38", "0", "0"},
[4003000137] = {4003000137, 10030001, 39, 31, "0", "0", "得清點仔細。", "0", "0", "0", "0", "0", "cv_sk_faernaisi_39", "0", "0"},
[4003000138] = {4003000138, 10030001, 40, 32, "0", "0", "我喜歡消費。", "0", "0", "0", "0", "0", "cv_sk_faernaisi_40", "0", "0"},
[4003000139] = {4003000139, 10030001, 41, 33, "0", "0", "小心洩露。", "0", "0", "0", "0", "0", "cv_sk_faernaisi_41", "0", "0"},
[4003000140] = {4003000140, 10030001, 42, 34, "0", "0", "請。", "0", "0", "0", "0", "0", "cv_sk_faernaisi_42", "0", "0"},
[4003000141] = {4003000141, 10030001, 43, 35, "0", "0", "確保無人看見。", "0", "0", "0", "0", "0", "cv_sk_faernaisi_43", "0", "0"},
[4003000142] = {4003000142, 10030001, 44, 36, "0", "0", "言語的戰場。", "0", "0", "0", "0", "0", "cv_sk_faernaisi_44", "0", "0"},
[4003000143] = {4003000143, 10030001, 45, 37, "0", "0", "注意安全。", "0", "0", "0", "0", "0", "cv_sk_faernaisi_45", "0", "0"},
[4003400100] = {4003400100, 10034001, 1, 1, "0", "0", "蒼霧殘響", "0", "0", "0", "0", "0", "cv_sk_roki_1", "0", "0"},
[4003400101] = {4003400101, 10034001, 2, 2, "0", "0", "讓我待在明處……不知道該說你是膽大心細，還是初出茅廬氣焰正盛……不過，畢竟你的命令是大於守則的，我很樂意聽從。", "0", "0", "0", "0", "0", "cv_sk_roki_2", "0", "0"},
[4003400102] = {4003400102, 10034001, 3, 3, "0", "0", "“受刑人”洛基……可以的話，最好別用這個名字叫我……用“喂”或者是“那個誰”，都可以，我能明白的。", "0", "0", "0", "0", "0", "cv_sk_roki_3", "0", "0"},
[4003400103] = {4003400103, 10034001, 91, 4, "0", "idle", "你的視線可真是失禮——作為道歉，就用更加認真的態度仔細看吧。反正你的眼睛也沒其他用途了吧。", "0", "0", "0", "0", "0", "cv_sk_roki_4", "0", "idle,idle"},
[4003400104] = {4003400104, 10034001, 91, 4, "0", "idle", "你不覺得現在的氛圍很好嗎？讓我想想，對，就像是戰場上的停屍間一樣，死寂的同時又感受不到時間的流逝。", "0", "0", "0", "0", "0", "cv_sk_roki_5", "0", "idle,idle"},
[4003400105] = {4003400105, 10034001, 94, 4, "0", "idle2", "如果想不到什麼要說的話，就這樣閉著嘴巴，保持安靜，和我一直對視吧。第一個忍不住的人就切斷舌頭吧。", "0", "0", "0", "0", "0", "cv_sk_roki_6", "0", "idle2,idle2"},
[4003400106] = {4003400106, 10034001, 94, 4, "0", "idle2", "困了的話就請放心地入睡吧，我會負責在領航入睡的一分鐘後搖醒你的。今晚也好，明晚也好，你都沒機會睡著的。", "0", "0", "0", "0", "0", "cv_sk_roki_7", "0", "idle2,idle2"},
[4003400107] = {4003400107, 10034001, 92, 5, "14_》_0_0.8", "touch1", "我看起來毫無防備？因為我相當信任你——畢竟是領航的話，可沒有那個膽子做一些壞事吧？", "0", "0", "0", "0", "0", "cv_sk_roki_8", "0", "touch1,touch1"},
[4003400108] = {4003400108, 10034001, 92, 5, "14_》_0_0.8", "touch1", "虐待和招待， 聽上去差不多吧？難得領航你來一趟敝廬，你是想要好好招待呢，還是想好好被虐待呢？", "0", "0", "0", "0", "0", "cv_sk_roki_9", "0", "touch1,touch1"},
[4003400109] = {4003400109, 10034001, 93, 5, "14_》_0_0.8", "touch_s1", "發生什麼了？", "0", "0", "0", "0", "0", "cv_sk_roki_46", "0", "touch_s1,touch_s1"},
[4003400110] = {4003400110, 10034001, 95, 5, "14_》_0_0.8", "touch2", "我比你想像中還要記仇。我有多怨恨史蒂芬妮，就會在你身上尋找更多的補償。害怕了？現在想跑的話已經來不及了，你已經是跌入蛇口的倉鼠了。", "0", "0", "0", "0", "0", "cv_sk_roki_10", "0", "touch2,touch2"},
[4003400111] = {4003400111, 10034001, 95, 5, "14_》_0_0.8", "touch2", "一個罪犯，一個特工，能夠擁有的最寶貴的寶物也不過是像這種靜謐的夜晚……我把它分享給了你，那麼你呢，你能把什麼交給我呢，領航？", "0", "0", "0", "0", "0", "cv_sk_roki_11", "0", "touch2,touch2"},
[4003400112] = {4003400112, 10034001, 96, 5, "14_》_0_0.8", "touch_s2", "哎呀哎呀……", "0", "0", "0", "0", "0", "cv_sk_roki_47", "0", "touch_s2,touch_s2"},
[4003400113] = {4003400113, 10034001, 12, 6, "0", "0", "享受到了正規軍的待遇。", "0", "0", "0", "0", "0", "cv_sk_roki_12", "0", "0"},
[4003400114] = {4003400114, 10034001, 13, 7, "0", "0", "感謝提拔。", "0", "0", "0", "0", "0", "cv_sk_roki_13", "0", "0"},
[4003400115] = {4003400115, 10034001, 14, 8, "0", "0", "突然覺得……當駕駛員說不定也挺好的。", "0", "0", "0", "0", "0", "cv_sk_roki_14", "0", "0"},
[4003400116] = {4003400116, 10034001, 15, 9, "0", "0", "多學點戰鬥技能也不是壞事。", "0", "0", "0", "0", "0", "cv_sk_roki_15", "0", "0"},
[4003400117] = {4003400117, 10034001, 16, 10, "0", "0", "我也沒想過自己會出現在正面戰場。", "0", "0", "0", "0", "0", "cv_sk_roki_16", "0", "0"},
[4003400118] = {4003400118, 10034001, 17, 11, "0", "0", "完美勝利？難以置信。", "0", "0", "0", "0", "0", "cv_sk_roki_17", "0", "0"},
[4003400119] = {4003400119, 10034001, 18, 12, "0", "0", "居然贏了嗎？不可思議。", "0", "0", "0", "0", "0", "cv_sk_roki_18", "0", "0"},
[4003400120] = {4003400120, 10034001, 19, 13, "0", "0", "這也能贏？值得佩服。", "0", "0", "0", "0", "0", "cv_sk_roki_19", "0", "0"},
[4003400121] = {4003400121, 10034001, 20, 14, "0", "0", "輸了？應該不是我的責任吧。", "0", "0", "0", "0", "0", "cv_sk_roki_20", "0", "0"},
[4003400122] = {4003400122, 10034001, 21, 15, "0", "0", "手感不錯。", "0", "0", "0", "0", "0", "cv_sk_roki_21", "0", "0"},
[4003400123] = {4003400123, 10034001, 23, 16, "0", "0", "就選你了。", "0", "0", "0", "0", "0", "cv_sk_roki_23", "0", "0"},
[4003400124] = {4003400124, 10034001, 26, 19, "0", "0", "那麼，我就先撤退了。", "0", "0", "0", "0", "0", "cv_sk_roki_26", "0", "0"},
[4003400125] = {4003400125, 10034001, 24, 17, "0", "0", "快嚥氣吧。", "0", "0", "0", "0", "0", "cv_sk_roki_24", "0", "0"},
[4003400126] = {4003400126, 10034001, 25, 18, "0", "0", "我來斬去你的多餘之物吧。", "0", "0", "0", "0", "0", "cv_sk_roki_25", "0", "0"},
[4003400127] = {4003400127, 10034001, 27, 20, "0", "0", "如果你因此產生了什麼邪念，我就會殺了你，立即，立刻。", "0", "0", "0", "0", "0", "cv_sk_roki_27", "0", "0"},
[4003400128] = {4003400128, 10034001, 28, 21, "0", "0", "以前只在動畫和漫畫裡遇過這種事……怎麼，你覺得我對那種東西不感興趣？", "0", "0", "0", "0", "0", "cv_sk_roki_28", "0", "0"},
[4003400129] = {4003400129, 10034001, 29, 21, "0", "0", "看著你在旁邊晃悠，就會想到不小心踩到你的畫面……放心，只是想想而已。", "0", "0", "0", "0", "0", "cv_sk_roki_29", "0", "0"},
[4003400130] = {4003400130, 10034001, 30, 22, "0", "0", "嗯？", "0", "0", "0", "0", "0", "cv_sk_roki_30", "0", "0"},
[4003400131] = {4003400131, 10034001, 31, 23, "0", "0", "你要叫那個名字了嗎……", "0", "0", "0", "0", "0", "cv_sk_roki_31", "0", "0"},
[4003400132] = {4003400132, 10034001, 32, 24, "0", "0", "別叫我洛基——就當是我在求你吧。", "0", "0", "0", "0", "0", "cv_sk_roki_32", "0", "0"},
[4003400133] = {4003400133, 10034001, 33, 25, "0", "0", "總好過你用那個代號叫我。", "0", "0", "0", "0", "0", "cv_sk_roki_33", "0", "0"},
[4003400134] = {4003400134, 10034001, 34, 26, "0", "0", "嗯……我剛剛正在和人打賭你不會回來了。", "0", "0", "0", "0", "0", "cv_sk_roki_34", "0", "0"},
[4003400135] = {4003400135, 10034001, 35, 27, "0", "0", "我還不是很喜歡這種類型的出勤任務……算了，總會習慣的。", "0", "0", "0", "0", "0", "cv_sk_roki_35", "0", "0"},
[4003400136] = {4003400136, 10034001, 36, 28, "0", "0", "也算是我擅長的事情吧。", "0", "0", "0", "0", "0", "cv_sk_roki_36", "0", "0"},
[4003400137] = {4003400137, 10034001, 37, 29, "0", "0", "這下我們才是真正的總部了。", "0", "0", "0", "0", "0", "cv_sk_roki_37", "0", "0"},
[4003400138] = {4003400138, 10034001, 38, 30, "0", "0", "很好，召集人反攻總部吧。", "0", "0", "0", "0", "0", "cv_sk_roki_38", "0", "0"},
[4003400139] = {4003400139, 10034001, 39, 31, "0", "0", "我也挺想要那種看著很厲害的裝備。", "0", "0", "0", "0", "0", "cv_sk_roki_39", "0", "0"},
[4003400140] = {4003400140, 10034001, 40, 32, "0", "0", "一起逛逛吧。", "0", "0", "0", "0", "0", "cv_sk_roki_40", "0", "0"},
[4003400141] = {4003400141, 10034001, 41, 33, "0", "0", "看來你也沒少被使喚。", "0", "0", "0", "0", "0", "cv_sk_roki_41", "0", "0"},
[4003400142] = {4003400142, 10034001, 42, 34, "0", "0", "忘帶東西了嗎？", "0", "0", "0", "0", "0", "cv_sk_roki_42", "0", "0"},
[4003400143] = {4003400143, 10034001, 43, 35, "0", "0", "想起來了？我正打算刪了呢。", "0", "0", "0", "0", "0", "cv_sk_roki_43", "0", "0"},
[4003400144] = {4003400144, 10034001, 44, 36, "0", "0", "留下文字記錄可不是什麼好事。", "0", "0", "0", "0", "0", "cv_sk_roki_44", "0", "0"},
[4003400145] = {4003400145, 10034001, 45, 37, "0", "0", "怎麼了？", "0", "0", "0", "0", "0", "cv_sk_roki_45", "0", "0"},
[4003600100] = {4003600100, 10036001, 1, 1, "0", "0", "蒼霧殘響", "0", "0", "0", "0", "0", "cv_sk_chalisha_vd_1", "0", "0"},
[4003600101] = {4003600101, 10036001, 2, 2, "0", "0", "竟，竟然讓本小姐穿著這樣的衣服陪你……", "0", "0", "0", "0", "0", "cv_sk_chalisha_vd_2", "0", "0"},
[4003600102] = {4003600102, 10036001, 3, 3, "0", "0", "這是巧克力……我只是順手拿來的，別把它當成什麼特別的東西。", "0", "0", "0", "0", "0", "cv_sk_chalisha_vd_3", "0", "0"},
[4003600103] = {4003600103, 10036001, 91, 4, "0", "idle", "今天一整天……我都在想你會什麼過來……", "0", "0", "0", "0", "0", "cv_sk_chalisha_vd_4", "0", "0"},
[4003600104] = {4003600104, 10036001, 91, 4, "0", "idle", "這件衣服對本小姐而言是特別的，同樣，穿上這件衣服的本小姐也是特別的。", "0", "0", "0", "0", "0", "cv_sk_chalisha_vd_5", "0", "0"},
[4003600105] = {4003600105, 10036001, 94, 4, "0", "idle2", "沒……沒有贅肉的……不要再仔細地盯著看了，本小姐很努力地鍛煉過了……", "0", "0", "0", "0", "0", "cv_sk_chalisha_vd_6", "0", "0"},
[4003600106] = {4003600106, 10036001, 94, 4, "0", "idle2", "竟然會選擇白天過來……真是的……", "0", "0", "0", "0", "0", "cv_sk_chalisha_vd_7", "0", "0"},
[4003600107] = {4003600107, 10036001, 92, 5, "14_》_0_0.8", "touch1", "這是你和本小姐挑選的衣服之一，前幾件的我都穿給你看了……但是這一件……本，本小姐可是下了很大的決心哦！", "0", "0", "0", "0", "0", "cv_sk_chalisha_vd_8", "0", "0"},
[4003600108] = {4003600108, 10036001, 92, 5, "14_》_0_0.8", "touch1", "節食……鍛煉……都是為了在穿上這件衣服之後顯得好看……你就心懷感激地把本小姐的美貌一輩子記在心裡吧！", "0", "0", "0", "0", "0", "cv_sk_chalisha_vd_9", "0", "0"},
[4003600109] = {4003600109, 10036001, 93, 5, "14_》_0_0.8", "touch_s1", "本小姐終於知道這件衣服怎麼穿了，但是只要拉動後面的蝴蝶結就會一下子脫落……哇嗚嗚……你看掉下來了……", "0", "0", "0", "0", "0", "cv_sk_chalisha_vd_10", "0", "0"},
[4003600110] = {4003600110, 10036001, 95, 5, "14_》_0_0.8", "touch2", "內……內衣也是這套衣服自帶的……所，所以只有這一次給你看……！", "0", "0", "0", "0", "0", "cv_sk_chalisha_vd_11", "0", "0"},
[4003600111] = {4003600111, 10036001, 95, 5, "14_》_0_0.8", "touch2", "哇啊啊啊……領航的手好冰啊……不……是，是本小姐……稍微有點熱呢……奇怪……明明穿得那麼少……", "0", "0", "0", "0", "0", "cv_sk_chalisha_vd_46", "0", "0"},
[4003600112] = {4003600112, 10036001, 96, 5, "14_》_0_0.8", "touch_s2", "啊啊湫——啊啊啊啊啊啊湫——還是把衣服穿上吧？說，說得也是呢。", "0", "0", "0", "0", "0", "cv_sk_chalisha_vd_47", "0", "0"},
[4003600113] = {4003600113, 10036001, 12, 6, "0", "0", "就陪你再來一次吧。", "0", "0", "0", "0", "0", "cv_sk_chalisha_vd_12", "0", "0"},
[4003600114] = {4003600114, 10036001, 13, 7, "0", "0", "在這身衣服穿在身上的時候，我便知曉了我的心意。", "0", "0", "0", "0", "0", "cv_sk_chalisha_vd_13", "0", "0"},
[4003600115] = {4003600115, 10036001, 14, 8, "0", "0", "啊……啊……我明白了。", "0", "0", "0", "0", "0", "cv_sk_chalisha_vd_14", "0", "0"},
[4003600116] = {4003600116, 10036001, 15, 9, "0", "0", "多麼燦爛啊……我的感情。", "0", "0", "0", "0", "0", "cv_sk_chalisha_vd_15", "0", "0"},
[4003600117] = {4003600117, 10036001, 16, 10, "0", "0", "快點結束回去吧，我有話要對領航講呢。", "0", "0", "0", "0", "0", "cv_sk_chalisha_vd_16", "0", "0"},
[4003600118] = {4003600118, 10036001, 17, 11, "0", "0", "呼呼，還是打原罪讓人安心。", "0", "0", "0", "0", "0", "cv_sk_chalisha_vd_17", "0", "0"},
[4003600119] = {4003600119, 10036001, 18, 12, "0", "0", "……為什麼我會失誤。", "0", "0", "0", "0", "0", "cv_sk_chalisha_vd_18", "0", "0"},
[4003600120] = {4003600120, 10036001, 19, 13, "0", "0", "我我我……才沒有一邊戰鬥一邊在想領航的事情呢！", "0", "0", "0", "0", "0", "cv_sk_chalisha_vd_19", "0", "0"},
[4003600121] = {4003600121, 10036001, 20, 14, "0", "0", "搞砸了……怎麼會這樣……", "0", "0", "0", "0", "0", "cv_sk_chalisha_vd_20", "0", "0"},
[4003600122] = {4003600122, 10036001, 21, 15, "0", "0", "搞定了！", "0", "0", "0", "0", "0", "cv_sk_chalisha_vd_21", "0", "0"},
[4003600123] = {4003600123, 10036001, 23, 16, "0", "0", "別擋我！", "0", "0", "0", "0", "0", "cv_sk_chalisha_vd_23", "0", "0"},
[4003600124] = {4003600124, 10036001, 24, 17, "0", "0", "滾開！", "0", "0", "0", "0", "0", "cv_sk_chalisha_vd_24", "0", "0"},
[4003600125] = {4003600125, 10036001, 25, 18, "0", "0", "不要妨礙我！全部消失吧！", "0", "0", "0", "0", "0", "cv_sk_chalisha_vd_25", "0", "0"},
[4003600126] = {4003600126, 10036001, 26, 19, "0", "0", "還沒有傳達出的感情……", "0", "0", "0", "0", "0", "cv_sk_chalisha_vd_26", "0", "0"},
[4003600127] = {4003600127, 10036001, 27, 20, "0", "0", "怎，怎麼了，一直在那裡盯著看個不停……本小姐吸引了你的目光？哼，算你有眼光！", "0", "0", "0", "0", "0", "cv_sk_chalisha_vd_27", "0", "0"},
[4003600128] = {4003600128, 10036001, 28, 21, "0", "0", "因為你，本小姐才會變成這樣，本小姐是想說，還好能遇見你。", "0", "0", "0", "0", "0", "cv_sk_chalisha_vd_28", "0", "0"},
[4003600129] = {4003600129, 10036001, 29, 21, "0", "0", "心裡熱熱的……以前也是這個樣子嗎……", "0", "0", "0", "0", "0", "cv_sk_chalisha_vd_29", "0", "0"},
[4003600130] = {4003600130, 10036001, 30, 22, "0", "0", "本小姐就破例和你一起看看，我可沒在擔心什麼……", "0", "0", "0", "0", "0", "cv_sk_chalisha_vd_30", "0", "0"},
[4003600131] = {4003600131, 10036001, 31, 23, "0", "0", "你不會認不出本小姐吧——", "0", "0", "0", "0", "0", "cv_sk_chalisha_vd_31", "0", "0"},
[4003600132] = {4003600132, 10036001, 32, 24, "0", "0", "哼哼，不錯嘛，能感受到我的心意，算是你的福氣。", "0", "0", "0", "0", "0", "cv_sk_chalisha_vd_32", "0", "0"},
[4003600133] = {4003600133, 10036001, 33, 25, "0", "0", "假的吧——————！", "0", "0", "0", "0", "0", "cv_sk_chalisha_vd_33", "0", "0"},
[4003600134] = {4003600134, 10036001, 34, 26, "0", "0", "糟糕了！？我還沒準備好！", "0", "0", "0", "0", "0", "cv_sk_chalisha_vd_34", "0", "0"},
[4003600135] = {4003600135, 10036001, 35, 27, "0", "0", "一起走吧！", "0", "0", "0", "0", "0", "cv_sk_chalisha_vd_35", "0", "0"},
[4003600136] = {4003600136, 10036001, 36, 28, "0", "0", "這裡還是和以前一樣呢。", "0", "0", "0", "0", "0", "cv_sk_chalisha_vd_36", "0", "0"},
[4003600137] = {4003600137, 10036001, 37, 29, "0", "0", "都是珍貴的邂逅嗎……", "0", "0", "0", "0", "0", "cv_sk_chalisha_vd_37", "0", "0"},
[4003600138] = {4003600138, 10036001, 38, 30, "0", "0", "習以為常了。", "0", "0", "0", "0", "0", "cv_sk_chalisha_vd_38", "0", "0"},
[4003600139] = {4003600139, 10036001, 39, 31, "0", "0", "發著光呢，這些裝備。", "0", "0", "0", "0", "0", "cv_sk_chalisha_vd_39", "0", "0"},
[4003600140] = {4003600140, 10036001, 40, 32, "0", "0", "今天晚上想吃什麼？", "0", "0", "0", "0", "0", "cv_sk_chalisha_vd_40", "0", "0"},
[4003600141] = {4003600141, 10036001, 41, 33, "0", "0", "從今往後會有我的故事被記錄在這裡嗎？", "0", "0", "0", "0", "0", "cv_sk_chalisha_vd_41", "0", "0"},
[4003600142] = {4003600142, 10036001, 42, 34, "0", "0", "請再對我說些什麼吧。", "0", "0", "0", "0", "0", "cv_sk_chalisha_vd_42", "0", "0"},
[4003600143] = {4003600143, 10036001, 43, 35, "0", "0", "想向你傳達……", "0", "0", "0", "0", "0", "cv_sk_chalisha_vd_43", "0", "0"},
[4003600144] = {4003600144, 10036001, 44, 36, "0", "0", "不可思議的地方呢。", "0", "0", "0", "0", "0", "cv_sk_chalisha_vd_44", "0", "0"},
[4003600145] = {4003600145, 10036001, 45, 37, "0", "0", "好極了。", "0", "0", "0", "0", "0", "cv_sk_chalisha_vd_45", "0", "0"},
[4100000100] = {4100000100, 11000001, 1, 1, "0", "0", "蒼霧殘響——切，這麼做的意義到底是什麼啊？！", "蒼霧殘響（ハツリバーブ）――ふーん、これって意味あるの？", "0", "0", "蒼霧殘響——切，這麼做的意義到底是什麼啊？！", "0", "cv_sk_chilyarisa_1", "0", "0"},
[4100000101] = {4100000101, 11000001, 2, 2, "0", "0", "喔～眼光還不錯嘛～", "へぇ、見る目があるじゃん～", "0", "0", "噢～眼光還不錯嘛～", "0", "cv_sk_chilyarisa_2", "0", "0"},
[4100000102] = {4100000102, 11000001, 3, 3, "0", "0", "嘖，真是的。人家為什麼會被編進這種邊緣部隊啊。", "もうっ！何でこんなノンコア部隊に配屬されてるのよ。", "0", "0", "嘖，真是的。人家為什麼會被編進這種邊緣部隊啊。", "0", "cv_sk_chilyarisa_3", "0", "0"},
[4100000103] = {4100000103, 11000001, 4, 4, "0", "idle", "笨領航不要磨磨蹭蹭的，等你在這賞完櫻，上學都快要遲到了……聽到這樣的臺詞你就高興了嗎？", "ばかナビゲーター！ボーっとお花見なんかしてたら、學校に遅刻しちゃうわよ！……こ、こういうセリフがいいんでしょ？", "0", "0", "喂，那邊的傢伙。如果有什麼要幫忙的就隨時連絡人家吧，今天也絕對不會讓你失望的。", "0", "cv_sk_chilyarisa_4", "0", "0"},
[4100000104] = {4100000104, 11000001, 5, 4, "0", "idle", "……為什麼不說話啊？明明是你非要我穿這種衣服的，倒是給點反應啊！", "……なんで黙ってんの？あんたがこういう服著せたかったんでしょ。なんか言いなさいよ！", "0", "0", "離家出走的千金大小姐？你到底是從哪聽到的謠言啊，下次如果再敢提起這事，人家絕對不會放過你。", "0", "cv_sk_chilyarisa_5", "0", "0"},
[4100000105] = {4100000105, 11000001, 6, 4, "0", "idle", "這身打扮會不會被弗蘭卡看見呢？有些期待，但果然還是算了……唔，好糾結！", "フランカーがこの格好を見たらなんて言うかな？聞いてみたい気もするけど、やめといたほうがいいかも……うー、悩む！", "0", "0", "嗚嗚嗚，弗蘭卡真的超級可愛啊～說實話，沒人能拒絕年幼又懂事的後輩叫自己學姐吧。", "0", "cv_sk_chilyarisa_6", "0", "0"},
[4100000106] = {4100000106, 11000001, 7, 5, "1_》_0_0.8", "level1", "喂，不要亂碰我！你說什麼？是想幫我拍掉身上的櫻花？呃，那就，謝、謝謝……", "ちょっと、觸んないでよ！……え？服についた桜を払ってくれたの？そ、そうなんだ。ありがと……", "0", "0", "我就直說了吧，我想要出名，想讓全世界的目光都聚焦到我的身上。想要……證明自己才不是什麼一無是處任人擺佈的千金大小姐。", "0", "cv_sk_chilyarisa_7", "0", "0"},
[4100000107] = {4100000107, 11000001, 8, 5, "1_》_0_0.8", "level1", "玩夠了沒？玩夠了就快去做正經事啦。", "もういいでしょ？そろそろ真面目にして！", "0", "0", "滾。", "0", "cv_sk_chilyarisa_8", "0", "0"},
[4100000108] = {4100000108, 11000001, 9, 5, "1_》_0_0.8", "level2", "為什麼帶傘？哼，還不是怕突然下雨淋濕衣服的話，會被你這個煩人的領航笑話！", "なんで傘を持ってるのかって？ふん。急に雨でも降って服が濡れたら、あんたみたいにしつこいヤツに笑われちゃうからよ！", "0", "0", "哈？被人家迷住了嗎～真是單純的傢伙啊。", "0", "cv_sk_chilyarisa_9", "0", "0"},
[4100000109] = {4100000109, 11000001, 10, 5, "1_》_0_0.8", "level3", "這種白色的春夏裝是不錯，要是之後有機會，也有些想試試深色系的秋冬季校服。", "この白い夏服、悪くないわね。今度は落ち著いた色の冬服も試してみたいな！", "0", "0", "喂，都說了，不要再這麼盯著人家了……煩……煩死人了哇啊啊啊啊！！！！！", "0", "cv_sk_chilyarisa_10", "0", "0"},
[4100000110] = {4100000110, 11000001, 11, 5, "1_》_0_0.8", "level4", "現、現在沒空啦，要是有什麼事……等會去天臺、體育館二樓、校舍後花園之類沒人的地方再說吧。", "今、忙しいの！話があるんだったら……屋上とか體育館とか校舎裏とか……人のいないところで、聞いてあげてもいいわ。", "0", "0", "哼，那個什麼。就破例讓你看一會吧，聽好了就一會哦……真……真是的，沒……沒想到人家的魅力這麼大啊，哈，哈哈，哈哈哈哈。", "0", "cv_sk_chilyarisa_11", "0", "0"},
[4100000111] = {4100000111, 11000001, 12, 6, "0", "0", "吼～", "ふーん", "0", "0", "吼～", "0", "cv_sk_chilyarisa_12", "0", "0"},
[4100000112] = {4100000112, 11000001, 13, 7, "0", "0", "感覺真是不錯呢～", "いい感じ。", "0", "0", "感覺真是不錯呢～", "0", "cv_sk_chilyarisa_13", "0", "0"},
[4100000113] = {4100000113, 11000001, 14, 8, "0", "0", "怎麼說呢，那個……雖然這都是人家自己努力得到的結果，但是還是多謝你一直陪著人家了。", "なんていうか、その……あたし自身が頑張ったからね！まぁ、そばにいてくれたのは…...その、あ、ありがとう……", "0", "0", "怎麼說呢，那個……雖然這都是人家自己努力得到的結果，但是還是多謝你一直陪著人家了。", "0", "cv_sk_chilyarisa_14", "0", "0"},
[4100000114] = {4100000114, 11000001, 15, 9, "0", "0", "太棒了～人家的速度又變快了欸！", "やった、あたしのスピード、また上がったじゃん！", "0", "0", "太棒了～人家的速度又變快了哎！", "0", "cv_sk_chilyarisa_15", "0", "0"},
[4100000115] = {4100000115, 11000001, 16, 10, "0", "0", "速戰速決吧～", "さっさとやりましょ。", "0", "0", "速戰速決吧～", "0", "cv_sk_chilyarisa_16", "0", "0"},
[4100000116] = {4100000116, 11000001, 17, 11, "0", "0", "哈哈哈哈～不愧是本小姐啊～", "あははは！さすがあたしね。", "0", "0", "哈哈哈哈～不愧是本小姐啊～", "0", "cv_sk_chilyarisa_17", "0", "0"},
[4100000117] = {4100000117, 11000001, 18, 12, "0", "0", "嗯嗯，感覺還算不錯～", "うん、いい感じ。", "0", "0", "嗯嗯，感覺還算不錯～", "0", "cv_sk_chilyarisa_18", "0", "0"},
[4100000118] = {4100000118, 11000001, 19, 13, "0", "0", "哼，真……真是輕鬆啊～哈，哈哈。", "ふ、ふーん。楽勝過ぎてびっくりしちゃったわ、あはは、あははは。", "0", "0", "哼，真……真是輕鬆啊～哈，哈哈。", "0", "cv_sk_chilyarisa_19", "0", "0"},
[4100000119] = {4100000119, 11000001, 20, 14, "0", "0", "都……都是裝備的問題啦！", "そ、裝備のせいだからね！", "0", "0", "都……都是裝備的問題啦！", "0", "cv_sk_chilyarisa_20", "0", "0"},
[4100000120] = {4100000120, 11000001, 21, 15, "0", "0", "不要小看女子高中生啊！", "ＪＫを甘く見るんじゃないわよ！", "0", "0", "Parfait～", "0", "cv_sk_chilyarisa_21", "0", "0"},
[4100000121] = {4100000121, 11000001, 23, 16, "0", "0", "去死！", "くたばれ！", "0", "0", "滾開！", "0", "cv_sk_chilyarisa_22", "0", "0"},
[4100000122] = {4100000122, 11000001, 24, 17, "0", "0", "哈！", "ざっけんな！", "0", "0", "呼～輕鬆～", "0", "cv_sk_chilyarisa_23", "0", "0"},
[4100000123] = {4100000123, 11000001, 26, 19, "0", "0", "等……領結都要松掉了！", "ちょ……スカーフがとれちゃう！", "0", "0", "你竟敢……可惡！下次絕對饒不了你！！！", "0", "cv_sk_chilyarisa_24", "0", "0"},
[4100000124] = {4100000124, 11000001, 27, 20, "0", "0", "哼，讓人家高興一下吧～", "ふー、リラックスさせて。", "0", "0", "哼，讓人家高興一下吧～", "0", "cv_sk_chilyarisa_25", "0", "0"},
[4100000125] = {4100000125, 11000001, 28, 21, "0", "0", "喂，怎麼停下來了啊？", "ちょっ、なんで止まってるのよ！", "0", "0", "喂，怎麼停下來了啊？", "0", "cv_sk_chilyarisa_26", "0", "0"},
[4100000126] = {4100000126, 11000001, 29, 21, "0", "0", "哼，如果累了的話就不要勉強自己嘛……", "ふーん、疲れたら無理しなくていいんだからさ……", "0", "0", "哼，如果累了的話就不要勉強自己嘛……", "0", "cv_sk_chilyarisa_27", "0", "0"},
[4100000127] = {4100000127, 11000001, 30, 22, "0", "0", "嘔吼～要來了嗎？", "へぇ。もう來るの？", "0", "0", "嘔吼～要來了嗎？", "0", "cv_sk_chilyarisa_28", "0", "0"},
[4100000128] = {4100000128, 11000001, 31, 23, "0", "0", "來吧～來吧～你一定不會出錯的吧～", "ほら、やろうよ。外したりしないよね。", "0", "0", "來吧～來吧～你一定不會出錯的吧～", "0", "cv_sk_chilyarisa_29", "0", "0"},
[4100000129] = {4100000129, 11000001, 32, 24, "0", "0", "還，還真是被你猜中了啊……", "ほ、本當に當たったんだ……", "0", "0", "還，還真是被你猜中了啊……", "0", "cv_sk_chilyarisa_30", "0", "0"},
[4100000130] = {4100000130, 11000001, 33, 25, "0", "0", "什麼嘛，真是一個笨蛋……", "な、なによ！あんたって本當、バカよね……", "0", "0", "什麼嘛，真是一個笨蛋……", "0", "cv_sk_chilyarisa_31", "0", "0"},
[4100000131] = {4100000131, 11000001, 34, 26, "0", "0", "嘖，下次懲罰遊戲要是我贏了，我一定會要求你穿比這更羞恥的服裝！", "チッ……次の勝負であたしが勝ったら、罰ゲームでもっと恥ずかしい服を著させてやるんだからね！", "0", "0", "歡迎回來～放心好了，在你不在的這段時間裡我可沒到處惹事哦。", "0", "cv_sk_chilyarisa_32", "0", "0"},
[4100000132] = {4100000132, 11000001, 35, 27, "0", "0", "你的故事中應該也有我的戲份吧……", "あんたの物語、あたしも出てるよね……？", "0", "0", "你的故事中應該也有我的戲份吧……", "0", "cv_sk_chilyarisa_33", "0", "0"},
[4100000133] = {4100000133, 11000001, 36, 28, "0", "0", "一杯紅茶的功夫就能完成了吧～", "すぐに完了できるよね。", "0", "0", "一杯紅茶的功夫就能完成了吧～", "0", "cv_sk_chilyarisa_34", "0", "0"},
[4100000134] = {4100000134, 11000001, 37, 29, "0", "0", "管理大家的任務就交給你啦～", "みんなの管理をよろしくね。", "0", "0", "管理大家的任務就交給你啦～", "0", "cv_sk_chilyarisa_35", "0", "0"},
[4100000135] = {4100000135, 11000001, 38, 30, "0", "0", "多招點可愛又聽話的孩子吧。", "可愛くて物分かりのいいコをもっと募集して！", "0", "0", "多招點可愛又聽話的孩子吧。", "0", "cv_sk_chilyarisa_36", "0", "0"},
[4100000136] = {4100000136, 11000001, 39, 31, "0", "0", "比起實用度，我更喜歡那些好看的裝備。", "実用性より、見た目の良い裝備の方がいいもん。", "0", "0", "比起實用度，我更喜歡那些好看的裝備。", "0", "cv_sk_chilyarisa_37", "0", "0"},
[4100000137] = {4100000137, 11000001, 40, 32, "0", "0", "achats～", "アシャ！", "0", "0", "achats～", "0", "cv_sk_chilyarisa_38", "0", "0"},
[4100000138] = {4100000138, 11000001, 41, 33, "0", "0", "你還真是自戀啊～", "あんたってナルシストね。", "0", "0", "你還真是自戀啊～", "0", "cv_sk_chilyarisa_39", "0", "0"},
