[4100000140] = {4100000140, 11000001, 43, 35, "0", "0", "會有粉絲來信嗎？！", "ファンからメールが屆いたりするのかな？", "0", "0", "會有粉絲來信嗎？！", "0", "cv_sk_chilyarisa_41", "0", "0"},
[4100000141] = {4100000141, 11000001, 44, 36, "0", "0", "是類似茶話會一樣的無聊地方呢。", "お茶會みたいな、つまんないとこ。", "0", "0", "是類似茶話會一樣的無聊地方呢。", "0", "cv_sk_chilyarisa_42", "0", "0"},
[4100000142] = {4100000142, 11000001, 45, 37, "0", "0", "給本小姐好好確認一下吧～", "ちゃんと確認してよね。", "0", "0", "給本小姐好好確認一下吧～", "0", "cv_sk_chilyarisa_43", "0", "0"},
[4100000200] = {4100000200, 11000002, 1, 1, "0", "0", "蒼霧殘響——切，這麼做的意義到底是什麼啊？！", "0", "0", "0", "0", "0", "cv_sk1_chilyarisa_1", "0", "0"},
[4100000201] = {4100000201, 11000002, 2, 2, "0", "0", "喔～眼光還不錯嘛～", "0", "0", "0", "0", "0", "cv_sk1_chilyarisa_2", "0", "0"},
[4100000202] = {4100000202, 11000002, 3, 3, "0", "0", "嘖，真是的。人家為什麼會被編進這種邊緣部隊啊。", "0", "0", "0", "0", "0", "cv_sk1_chilyarisa_3", "0", "0"},
[4100000203] = {4100000203, 11000002, 4, 4, "0", "idle", "看、看什麼看？是沒見過這麼美的兔女郎嗎？", "0", "0", "0", "0", "0", "cv_sk1_chilyarisa_4", "0", "0"},
[4100000204] = {4100000204, 11000002, 5, 4, "0", "idle", "……喂。人家穿著這種衣服，站在你身旁，你卻一直盯著那破電腦看？領航，你腦袋沒問題吧？", "0", "0", "0", "0", "0", "cv_sk1_chilyarisa_5", "0", "0"},
[4100000205] = {4100000205, 11000002, 6, 4, "0", "idle", "格洛麗亞那傢夥，看上去挺能喝的，但沒想到才一口就醉了……如果你等會兒看到她了，可千萬別給她遞酒。否則你絕對會後悔的，就像我現在這樣。", "0", "0", "0", "0", "0", "cv_sk1_chilyarisa_6", "0", "0"},
[4100000206] = {4100000206, 11000002, 7, 5, "15_2_0_0.8", "touch2", "你說什麼？啤酒？我給你個重新組織語言的機會……還是要啤酒？喂，你今天該不會是來找茬的吧？我這裡只有紅酒，愛喝不喝！", "0", "0", "0", "0", "0", "cv_sk1_chilyarisa_7", "0", "0"},
[4100000207] = {4100000207, 11000002, 8, 5, "15_2_0_0.8", "touch2", "要是某人還管不住自己的手……哼，本小姐不介意幫他管管。", "0", "0", "0", "0", "0", "cv_sk1_chilyarisa_8", "0", "0"},
[4100000208] = {4100000208, 11000002, 9, 5, "15_1_0_0.8", "touch1", "哈？說什麼廢話呢。你看看這周圍，有誰比我更有魅力？所以聚光燈會一直跟著我，這不是理所當然的事情麼。", "0", "0", "0", "0", "0", "cv_sk1_chilyarisa_9", "0", "0"},
[4100000209] = {4100000209, 11000002, 10, 5, "15_1_0_0.8", "touch1", "鋼鋼鋼鋼鋼管舞？！你要不要聽聽自己在說什麼蠢話？那種東西人家怎麼可能會的啊？！", "0", "0", "0", "0", "0", "cv_sk1_chilyarisa_10", "0", "0"},
[4100000210] = {4100000210, 11000002, 11, 5, "15_1_0_0.8", "touch1", "你如果實在想看，也不是不能跳一段……怎、怎麼，人家聰慧絕倫、無師自通，有什麼問題嗎？才不是因為你之前失落的樣子太可憐了，偷偷下載視頻學的呢！", "0", "0", "0", "0", "0", "cv_sk1_chilyarisa_11", "0", "0"},
[4100000211] = {4100000211, 11000002, 12, 6, "0", "0", "吼～", "0", "0", "0", "0", "0", "cv_sk1_chilyarisa_12", "0", "0"},
