[4100100100] = {4100100100, 11001001, 1, 1, "0", "0", "蒼霧殘響。", "0", "0", "0", "0", "0", "cv_sk_alice_33", "0", "0"},
[4100100101] = {4100100101, 11001001, 2, 2, "0", "0", "非常感謝您對我的信任。", "0", "0", "0", "0", "0", "cv_sk_alice_2", "0", "0"},
[4100100102] = {4100100102, 11001001, 3, 3, "0", "0", "愛麗絲·克雷蒂亞，克雷蒂亞家的長女。", "0", "0", "0", "0", "0", "cv_sk_alice_1", "0", "0"},
[4100100103] = {4100100103, 11001001, 4, 4, "0", "idle", "即便身處異鄉，我也不會忘記自己是克雷蒂亞家的長女。", "0", "0", "0", "0", "0", "cv_sk_alice_3", "0", "0"},
[4100100104] = {4100100104, 11001001, 5, 4, "0", "idle", "準備好了的話就出擊吧，領航。讓你見識一下克雷蒂亞家正統繼承人的劍藝。", "0", "0", "0", "0", "0", "cv_sk_alice_4", "0", "0"},
[4100100105] = {4100100105, 11001001, 6, 4, "0", "idle", "靜雖然是個沒有上進心的孩子，但是不知道為什麼我很喜歡和她待在一起……總覺得，她比起貓咪更像是倉鼠呢……", "0", "0", "0", "0", "0", "cv_sk_alice_30", "0", "0"},
[4100100106] = {4100100106, 11001001, 7, 5, "1_》_0_0.8", "level1", "在回到多瑙之前，我必須要足夠強大才行啊，否則的話即便是回去了也改變不了什麼。", "0", "0", "0", "0", "0", "cv_sk_alice_31", "0", "0"},
[4100100107] = {4100100107, 11001001, 8, 5, "1_》_0_0.8", "level1", "靜，別鬧！欸……是領航啊。", "0", "0", "0", "0", "0", "cv_sk_alice_5", "0", "0"},
[4100100108] = {4100100108, 11001001, 9, 5, "1_》_0_0.8", "level2", "為了遠離家族內部的派系鬥爭，我和靜從小就被安置在了瑪雅。不知不覺中已經快忘記父母的樣貌了……", "0", "0", "0", "0", "0", "cv_sk_alice_6", "0", "0"},
[4100100109] = {4100100109, 11001001, 10, 5, "1_》_0_0.8", "level3", "這是……泡芙嗎？真是令人懷念的味道啊……以前經常和靜一起去家對面的甜品店偷偷買回來吃呢。", "0", "0", "0", "0", "0", "cv_sk_alice_7", "0", "0"},
[4100100110] = {4100100110, 11001001, 11, 5, "1_》_0_0.8", "level4", "這麼多年，我的腦海中只有一件事……那就是回家。但是無論是蒂娜老師還是父母都覺得我還不夠成熟……", "0", "0", "0", "0", "0", "cv_sk_alice_8", "0", "0"},
[4100100111] = {4100100111, 11001001, 12, 6, "0", "0", "很好，讓我變得更強吧！", "0", "0", "0", "0", "0", "cv_sk_alice_9", "0", "0"},
[4100100112] = {4100100112, 11001001, 13, 7, "0", "0", "比任何人……都要強。", "0", "0", "0", "0", "0", "cv_sk_alice_10", "0", "0"},
