[4100200103] = {4100200103, 11002001, 4, 4, "0", "idle", "神明是虛偽的嗎……哼，讓妄想變為現實，顛覆了所有常識之後，您居然還會在意這些嗎？", "0", "0", "0", "0", "0", "cv_sk_kokorokami_3", "0", "0"},
[4100200104] = {4100200104, 11002001, 5, 4, "0", "idle", "茶味花香嗎……這兩者都是老身所喜好的，沒想到出生在多瑙的您也懂得欣賞這些，真是難得。", "0", "0", "0", "0", "0", "cv_sk_kokorokami_4", "0", "0"},
[4100200105] = {4100200105, 11002001, 6, 4, "0", "idle", "瑩草姐……不對，應該是小瑩草才是……如果當著她的面說錯稱呼估計會被殺掉吧。", "0", "0", "0", "0", "0", "cv_sk_kokorokami_30", "0", "0"},
[4100200106] = {4100200106, 11002001, 7, 5, "15_2_0_0.8", "level1", "神明只有在動亂時才有存在的價值，老身只不過是被這樣的使命驅使著前行罷了。", "0", "0", "0", "0", "0", "cv_sk_kokorokami_31", "0", "0"},
[4100200107] = {4100200107, 11002001, 8, 5, "15_1_0_0.8", "level5", "可以請您私下再說嗎？現在老身並沒有空。", "0", "0", "0", "0", "0", "cv_sk_kokorokami_5", "0", "0"},
[4100200108] = {4100200108, 11002001, 9, 5, "15_2_0_0.8", "level2", "怎麼？又來找老身了嗎？很抱歉，下次有空時會提前告知您的。", "0", "0", "0", "0", "0", "cv_sk_kokorokami_6", "0", "0"},
[4100200109] = {4100200109, 11002001, 10, 5, "15_2_0_0.8", "level3", "真是個執著的男人啊，那麼您想和老身聊些什麼呢？放心好了，身為侍奉神明的巫女，我會耐心回答完您所有的疑問。", "0", "0", "0", "0", "0", "cv_sk_kokorokami_7", "0", "0"},
[4100200110] = {4100200110, 11002001, 11, 5, "15_2_0_0.8", "level4", "啊……想必已經被發現了吧，我口中的神明，愛好……甚至我的姓名都是虛假的。沒錯，這段時間與您相處的女孩只不過是虛偽的化身，信仰的人偶罷了……什麼？您說無論哪邊的我在您眼中都是……真實的嗎……", "0", "0", "0", "0", "0", "cv_sk_kokorokami_8", "0", "0"},
[4100200111] = {4100200111, 11002001, 12, 6, "0", "0", "啊……這股從心中湧現出的力量……", "0", "0", "0", "0", "0", "cv_sk_kokorokami_9", "0", "0"},
[4100200112] = {4100200112, 11002001, 13, 7, "0", "0", "信仰的純度，提高了呢。", "0", "0", "0", "0", "0", "cv_sk_kokorokami_10", "0", "0"},
[4100200113] = {4100200113, 11002001, 14, 8, "0", "0", "落櫻紛飛，刹那芳華，何為虛影，傾此半生。但您的心意，已經傳達到了。", "0", "0", "0", "0", "0", "cv_sk_kokorokami_11", "0", "0"},
[4100200114] = {4100200114, 11002001, 15, 9, "0", "0", "技藝的純度，也提升了嗎？", "0", "0", "0", "0", "0", "cv_sk_kokorokami_12", "0", "0"},
[4100200115] = {4100200115, 11002001, 16, 10, "0", "0", "下麵就交由老身吧。", "0", "0", "0", "0", "0", "cv_sk_kokorokami_13", "0", "0"},
[4100200116] = {4100200116, 11002001, 17, 11, "0", "0", "做得好啊！領航！", "0", "0", "0", "0", "0", "cv_sk_kokorokami_14", "0", "0"},
[4100200117] = {4100200117, 11002001, 18, 12, "0", "0", "還算可以吧。", "0", "0", "0", "0", "0", "cv_sk_kokorokami_15", "0", "0"},
[4100200118] = {4100200118, 11002001, 19, 13, "0", "0", "嘖，刀劍豈是如此不便之物！", "0", "0", "0", "0", "0", "cv_sk_kokorokami_16", "0", "0"},
[4100200119] = {4100200119, 11002001, 20, 14, "0", "0", "果然……有些事僅憑精神力是做不到的。", "0", "0", "0", "0", "0", "cv_sk_kokorokami_17", "0", "0"},
[4100200120] = {4100200120, 11002001, 21, 15, "0", "0", "安息吧。", "0", "0", "0", "0", "0", "cv_sk_kokorokami_18", "0", "0"},
[4100200121] = {4100200121, 11002001, 23, 16, "0", "0", "斬！", "0", "0", "0", "0", "0", "cv_sk_kokorokami_19", "0", "0"},
[4100200122] = {4100200122, 11002001, 24, 17, "0", "0", "破除！", "0", "0", "0", "0", "0", "cv_sk_kokorokami_21", "0", "0"},
[4100200123] = {4100200123, 11002001, 25, 18, "0", "0", "來吧，一同見證吧…燒盡一切汙穢之物吧！", "0", "0", "0", "0", "0", "cv_sk_kokorokami_22", "0", "0"},
[4100200124] = {4100200124, 11002001, 26, 19, "0", "0", "到此為止了啊……老身所信仰的神明也沒能……", "0", "0", "0", "0", "0", "cv_sk_kokorokami_20", "0", "0"},
[4100200125] = {4100200125, 11002001, 27, 20, "0", "0", "您是認真的嗎？", "0", "0", "0", "0", "0", "cv_sk_kokorokami_23", "0", "0"},
[4100200126] = {4100200126, 11002001, 28, 21, "0", "0", "請不要看向其他地方。", "0", "0", "0", "0", "0", "cv_sk_kokorokami_24", "0", "0"},
[4100200127] = {4100200127, 11002001, 29, 21, "0", "0", "如果已經清理完畢了，請務必通知老身一聲。", "0", "0", "0", "0", "0", "cv_sk_kokorokami_25", "0", "0"},
[4100200128] = {4100200128, 11002001, 30, 22, "0", "0", "斬!……等等，這是您的戰鬥，老身無法插手。", "0", "0", "0", "0", "0", "cv_sk_kokorokami_26", "0", "0"},
[4100200129] = {4100200129, 11002001, 31, 23, "0", "0", "那麼，您會怎麼選呢？", "0", "0", "0", "0", "0", "cv_sk_kokorokami_27", "0", "0"},
[4100200130] = {4100200130, 11002001, 32, 24, "0", "0", "看來您信仰的純度很高呢，領航。", "0", "0", "0", "0", "0", "cv_sk_kokorokami_28", "0", "0"},
[4100200131] = {4100200131, 11002001, 33, 25, "0", "0", "老身無所謂。", "0", "0", "0", "0", "0", "cv_sk_kokorokami_29", "0", "0"},
[4100200132] = {4100200132, 11002001, 34, 26, "0", "0", "歡迎回來，老身已經恭候多時了。", "0", "0", "0", "0", "0", "cv_sk_kokorokami_32", "0", "0"},
[4100200133] = {4100200133, 11002001, 35, 27, "0", "0", "故事本身就是真假參半的。", "0", "0", "0", "0", "0", "cv_sk_kokorokami_34", "0", "0"},
[4100200134] = {4100200134, 11002001, 36, 28, "0", "0", "祭典已經開始了吧。", "0", "0", "0", "0", "0", "cv_sk_kokorokami_35", "0", "0"},
[4100200135] = {4100200135, 11002001, 37, 29, "0", "0", "您所供奉的神明，究竟是哪一位呢？", "0", "0", "0", "0", "0", "cv_sk_kokorokami_36", "0", "0"},
[4100200136] = {4100200136, 11002001, 38, 30, "0", "0", "這次神明又會降臨到哪個孩子身上呢？", "0", "0", "0", "0", "0", "cv_sk_kokorokami_37", "0", "0"},
[4100200137] = {4100200137, 11002001, 39, 31, "0", "0", "新的貢物已經準備好了嗎？", "0", "0", "0", "0", "0", "cv_sk_kokorokami_38", "0", "0"},
[4100200138] = {4100200138, 11002001, 40, 32, "0", "0", "啊，是類似於奉納箱一樣的東西吧。", "0", "0", "0", "0", "0", "cv_sk_kokorokami_39", "0", "0"},
[4100200139] = {4100200139, 11002001, 41, 33, "0", "0", "名片……也就是身份的象徵吧。", "0", "0", "0", "0", "0", "cv_sk_kokorokami_40", "0", "0"},
[4100200140] = {4100200140, 11002001, 42, 34, "0", "0", "變更設定。", "0", "0", "0", "0", "0", "cv_sk_kokorokami_41", "0", "0"},
[4100200141] = {4100200141, 11002001, 43, 35, "0", "0", "是從遠方寄來的文書呢。", "0", "0", "0", "0", "0", "cv_sk_kokorokami_42", "0", "0"},
[4100200142] = {4100200142, 11002001, 44, 36, "0", "0", "來自不同世界的聲音……", "0", "0", "0", "0", "0", "cv_sk_kokorokami_43", "0", "0"},
[4100200143] = {4100200143, 11002001, 45, 37, "0", "0", "讓老身來確認一下吧。", "0", "0", "0", "0", "0", "cv_sk_kokorokami_44", "0", "0"},
[4100300100] = {4100300100, 11003001, 1, 1, "0", "0", "蒼霧殘響。", "蒼霧殘響（ハツリバーブ）。", "0", "0", "蒼霧殘響。", "0", "cv_sk_suzuki_1", "0", "0"},
[4100300101] = {4100300101, 11003001, 2, 2, "0", "0", "嗚姆，我知道了。", "ふむ、分かった。", "0", "0", "嗚姆，咱知道了。", "0", "cv_sk_suzuki_2", "0", "0"},
[4100300102] = {4100300102, 11003001, 3, 3, "0", "0", "我是風林火山的鈴木清風，順帶一提，我可是隊長喔。", "うちは風林火山の鈴木清風。ちなみに、隊長やで。", "0", "0", "咱是風林火山的鈴木清風，順帶一提，咱可是隊長哦。", "0", "cv_sk_suzuki_3", "0", "0"},
[4100300103] = {4100300103, 11003001, 4, 4, "0", "idle", "“一宵夢黃粱，鏡花難折水月蕩，徒餘淚愁腸。”然後是……啊，又忘了。話劇臺詞還真是難背呢。", "一夜の夢、鏡に映し、ただ憂い……あー、また忘れてもうた。舞臺のセリフってホンマ覚えられへんわ。", "0", "0", "對咱而言，優先保護好同伴才是最重要的。", "0", "cv_sk_suzuki_4", "0", "0"},
[4100300104] = {4100300104, 11003001, 5, 4, "0", "idle", "困了嗎？先好好休息下吧。唔……看來咱的演繹還不夠吸引人呢，必須要再加把勁了！", "眠いんか？とりあえずゆっくり休んどき。うー……、やっぱうちの演技はまだまだやな。もっと頑張らなあかんな！", "0", "0", "領航呀，咱很好奇呀，你難道不需要休息嗎？", "0", "cv_sk_suzuki_5", "0", "0"},
[4100300105] = {4100300105, 11003001, 6, 4, "0", "idle", "沒想到在話劇裡，咱也要作為“大姐”，照顧不知火、青鸞、鬼之介所扮演的，初來棲野莊的孩子們呢。", "棲野莊に新しく來た子らを不知火と青鸞と鬼之介が演じるんや。まさか舞臺でも姉さんになって世話することになるとは思わんかったわ。", "0", "0", "不知火那孩子，總是用看小孩的目光看著咱呢。呼呼呼，對於咱來說，她才是需要照顧的孩子呢。因為，咱才是這支隊伍的隊長呀。", "0", "cv_sk_suzuki_6", "0", "0"},
[4100300106] = {4100300106, 11003001, 7, 5, "1_》_0_0.8", "level1", "《棲野哀歌》講述的是關於花魁的故事，而話劇選角全都是駕駛員少女們，咱聽說，這麼做是為了致敬某個知名歌劇團哦。", "「棲野哀歌」って花魁のお話やねんけど、キャストがドライバーの女の子だけなんは、有名な歌劇団へのオマージュらしいで。", "0", "0", "咱的夢想？嗚，咱可沒有精力去想那些。光是照顧隊伍裡的同伴，就已經耗費咱不少精力了。", "0", "cv_sk_suzuki_7", "0", "0"},
[4100300107] = {4100300107, 11003001, 8, 5, "1_》_0_0.8", "level1", "對於這戲服，咱可是很用心製作的，結果整套衣物的層數太多，倒是難以只靠自己穿上了。領航能搭把手、幫咱穿上幾件嗎？", "この衣裝、ホンマに心を込めて作ったんやけど、重ね著が大変すぎて一人で著られへんねん。ナビゲーター、手伝ってくれるか？", "0", "0", "別……別老是光盯著咱啊，有話快問啦。", "0", "cv_sk_suzuki_8", "0", "0"},
[4100300108] = {4100300108, 11003001, 9, 5, "1_》_0_0.8", "level2", "服飾、妝容、舞臺道具……嗚姆，基本算是周全了。領航覺得這幅場景怎麼樣？嗯嗯，很漂亮對吧？欸？居然是在說咱嗎……！", "衣裝とかメイクとか小道具とか、まあまあ、しっかりと用意したつもりや。ナビゲーター、このシーン、どう思う？……うんうん、キレイやろ？……え？うちのこと言うてんの！？", "0", "0", "哎？想向咱請教該怎麼和隊員交流。嗯嗯……老實說，咱也不是很清楚哎……", "0", "cv_sk_suzuki_9", "0", "0"},
[4100300109] = {4100300109, 11003001, 10, 5, "1_》_0_0.8", "level3", "再飲半杯濁酒，撫一曲清詞，然後今夜……啊不對！領航，咱、咱才沒有醉呢，只是入戲有些深而已，不信的話，你揪一下咱的臉看看？", "にごり酒を一獻（いっこん）、無粋はそろそろおさらばえ。今宵は……って、あかん、あかん！ナビゲーター、う、うちは酔ってへんで。ただちょっと役に入り込み過ぎてもうただけや。信じてないなら、ほっぺたつねってみい", "0", "0", "哎？咱喜歡的東西？嗯嗯……壽喜燒吧。當然，咱指得是喜歡製作壽喜燒，而不是吃啦。", "0", "cv_sk_suzuki_10", "0", "0"},
[4100300110] = {4100300110, 11003001, 11, 5, "1_》_0_0.8", "level4", "感覺話劇的結尾有些悲涼呢，畢竟劇名就帶有“哀歌”啊。不過，故事所傳遞的並不只是悲傷，還有與命運抗爭的決心，為了咱們的未來，戲外也得更加努力呢！", "「哀歌」ってタイトルだけあって、ラストはちょっと悲しいねん。せやけど、この物語は悲しみだけやなくて、運命と戦う決意も描いてんねん。うちらの未來のために、舞臺の外でももっと頑張らなあかんな！", "0", "0", "真是的，這段時間領航你總是問東問西的，整得就像是咱那個沒換牙的弟弟一樣。不過……咱覺得這種關係也不錯呢。", "0", "cv_sk_suzuki_11", "0", "0"},
[4100300111] = {4100300111, 11003001, 12, 6, "0", "0", "不得了啊！領航，我變強了呀！", "大変、ナビゲーター！うち、強くなったんよ！", "0", "0", "不得了啊！領航，咱變強了呀！", "0", "cv_sk_suzuki_12", "0", "0"},
[4100300112] = {4100300112, 11003001, 13, 7, "0", "0", "你就……這麼在意我嗎？", "そんなに……うちのことが気になる？", "0", "0", "你就……這麼在意咱嗎？", "0", "cv_sk_suzuki_13", "0", "0"},
[4100300113] = {4100300113, 11003001, 14, 8, "0", "0", "喔喔喔喔——領航，你看到了嗎！刀的顏色…刀刃的顏色！！！欸，你說沒啥變化？！", "おおっ――ナビゲーター！今の見た？刀の色……刃の色！！！えっ？特に変わっとらんって？！", "0", "0", "噢噢噢噢——領航，你看到了嗎！刀的顏色…刀刃的顏色！！！哎，你說沒啥變化？！", "0", "cv_sk_suzuki_14", "0", "0"},
[4100300114] = {4100300114, 11003001, 15, 9, "0", "0", "穩穩滴！", "ばっちり！", "0", "0", "妥妥滴！", "0", "cv_sk_suzuki_15", "0", "0"},
[4100300115] = {4100300115, 11003001, 16, 10, "0", "0", "斬落敵人的旗幟吧！", "敵の旗を斬り落とせ！", "0", "0", "斬落敵人的旗幟吧！", "0", "cv_sk_suzuki_16", "0", "0"},
[4100300116] = {4100300116, 11003001, 17, 11, "0", "0", "嗚姆，真是一場爽快的戰鬥。", "ふぅ、爽快な戦いやったわぁ。", "0", "0", "嗚姆，真是一場爽快的戰鬥。", "0", "cv_sk_suzuki_17", "0", "0"},
[4100300117] = {4100300117, 11003001, 18, 12, "0", "0", "好了，該回去啦。", "よし、帰ろ。", "0", "0", "妥了，該回去啦。", "0", "cv_sk_suzuki_18", "0", "0"},
[4100300118] = {4100300118, 11003001, 19, 13, "0", "0", "嗚姆，大家能平安回來就好。", "ふむ、みんな無事に帰ってこれてよかったわ。", "0", "0", "嗚姆，大家能平安回來就好。", "0", "cv_sk_suzuki_19", "0", "0"},
[4100300119] = {4100300119, 11003001, 20, 14, "0", "0", "遺憾啊……", "惜しい……", "0", "0", "遺憾啊……", "0", "cv_sk_suzuki_20", "0", "0"},
[4100300120] = {4100300120, 11003001, 21, 15, "0", "0", "“凋櫻入杯……”", "散り桜、杯に落ち……", "0", "0", "你還不配做咱的對手。", "0", "cv_sk_suzuki_21", "0", "0"},
[4100300121] = {4100300121, 11003001, 23, 16, "0", "0", "起舞！", "踴るでぇ！", "0", "0", "哆呀！", "0", "cv_sk_suzuki_22", "0", "0"},
[4100300122] = {4100300122, 11003001, 24, 17, "0", "0", "“……再添一味。”", "……ひと味加える。", "0", "0", "咱就收下了！", "0", "cv_sk_suzuki_23", "0", "0"},
[4100300123] = {4100300123, 11003001, 25, 18, "0", "0", "要上了喔。忍法·多重手裡劍之術（偽）！", "行くで？忍法・多重手裏剣の術！", "0", "0", "要上了哦。忍法·多重手裡劍之術（偽）！", "0", "cv_sk_suzuki_24", "0", "0"},
[4100300124] = {4100300124, 11003001, 26, 19, "0", "0", "嗚，我的衣服……！", "う……うちの衣裝……！", "0", "0", "才沒有……才沒有痛哦，不用擔心咱……抱歉。", "0", "cv_sk_suzuki_25", "0", "0"},
[4100300125] = {4100300125, 11003001, 27, 20, "0", "0", "我只是稍微放鬆一下而已。", "ちょーっと、リラックスするだけー……", "0", "0", "咱只是稍微放鬆一下而已。", "0", "cv_sk_suzuki_26", "0", "0"},
[4100300126] = {4100300126, 11003001, 28, 21, "0", "0", "我在老家時可沒有泡澡的習慣呢。", "実家にいた時はお風呂に入る習慣なんてなかったんやけど。", "0", "0", "咱在老家時可沒有泡澡的習慣呢。", "0", "cv_sk_suzuki_27", "0", "0"},
[4100300127] = {4100300127, 11003001, 29, 21, "0", "0", "稍微……稍微有點燙啊……啊哈哈。", "ち、ちょっと熱いかも……あははは。", "0", "0", "稍微……稍微有點燙啊……啊哈哈。", "0", "cv_sk_suzuki_28", "0", "0"},
[4100300128] = {4100300128, 11003001, 30, 22, "0", "0", "是！是壽喜燒！！！", "あっ！すき焼きや！！！", "0", "0", "是！是壽喜燒！！！", "0", "cv_sk_suzuki_29", "0", "0"},
[4100300129] = {4100300129, 11003001, 31, 23, "0", "0", "那麼，來猜猜我是誰吧？", "じゃあ、うちが誰なのか當ててみーや！", "0", "0", "那麼，來猜猜咱是誰吧？", "0", "cv_sk_suzuki_30", "0", "0"},
[4100300130] = {4100300130, 11003001, 32, 24, "0", "0", "嗚姆！回答正確！", "ふむ、正解！", "0", "0", "嗚姆！回答正確！", "0", "cv_sk_suzuki_31", "0", "0"},
[4100300131] = {4100300131, 11003001, 33, 25, "0", "0", "在戰場上認錯的話就糟糕了喂。", "戦場で間違えたらごっついことになるで。", "0", "0", "在戰場上認錯的話就糟糕了喂。", "0", "cv_sk_suzuki_32", "0", "0"},
[4100300132] = {4100300132, 11003001, 34, 26, "0", "0", "嗚姆，你回來了！咱正對劇本的一處地方疑惑著呢，能幫咱排練下嗎？", "お、待っとったで！臺本のここがちょっとわからへんから、稽古につき合ってくれるか？", "0", "0", "咱在這裡恭候多時了，領航！", "0", "cv_sk_suzuki_33", "0", "0"},
[4100300133] = {4100300133, 11003001, 35, 27, "0", "0", "讓好戲上演吧！", "おもろいことが始まるらしいで。", "0", "0", "讓好戲上演吧！", "0", "cv_sk_suzuki_34", "0", "0"},
[4100300134] = {4100300134, 11003001, 36, 28, "0", "0", "請放心把任務交給我吧！", "安心してうちに任せえ！", "0", "0", "請放心把任務交給咱吧！", "0", "cv_sk_suzuki_35", "0", "0"},
[4100300135] = {4100300135, 11003001, 37, 29, "0", "0", "領航，我的同伴可是很優秀的！", "ナビゲーター、うちの仲間はめっちゃ優秀なんやで！", "0", "0", "領航，咱的同伴可是很優秀的！", "0", "cv_sk_suzuki_36", "0", "0"},
[4100300136] = {4100300136, 11003001, 38, 30, "0", "0", "我會照顧好新人的！", "うち、新人のお世話係ちゃんとやるから！", "0", "0", "咱會照顧好新人的！", "0", "cv_sk_suzuki_37", "0", "0"},
[4100300137] = {4100300137, 11003001, 39, 31, "0", "0", "喔！要有新裝備了嗎！？", "おお！新しい裝備がもらえるん？！", "0", "0", "噢！要有新裝備了嗎！？", "0", "cv_sk_suzuki_38", "0", "0"},
[4100300138] = {4100300138, 11003001, 40, 32, "0", "0", "欸欸欸，是缺少什麼東西嗎？", "えぇぇっ？何か足りんもんあった？", "0", "0", "誒誒誒，是缺少什麼東西嗎？", "0", "cv_sk_suzuki_39", "0", "0"},
[4100300139] = {4100300139, 11003001, 41, 33, "0", "0", "要好好確認自己的狀況才行喔。", "自分の狀況をちゃんと確認せんといかんなあ。", "0", "0", "要好好確認自己的狀況才行哦。", "0", "cv_sk_suzuki_40", "0", "0"},
[4100300140] = {4100300140, 11003001, 42, 34, "0", "0", "適當的變通才是優秀指揮官的體現。", "臨機応変に対応出來るっちゅーことは、優秀な指揮官に要求される才能なんやで。", "0", "0", "適當的變通才是優秀指揮官的體現。", "0", "cv_sk_suzuki_41", "0", "0"},
[4100300141] = {4100300141, 11003001, 43, 35, "0", "0", "讓我先看看是誰的信！", "誰からのメールなんか、先にうちに見せてーやー。", "0", "0", "讓咱先看看是誰的信！", "0", "cv_sk_suzuki_42", "0", "0"},
[4100300142] = {4100300142, 11003001, 44, 36, "0", "0", "真是不可思議呢，大家通過這個東西聯繫在一起！", "不思議やな！みんな、こんなんで繋がってる！", "0", "0", "真是不可思議呢，大家通過這個東西聯繫在一起！", "0", "cv_sk_suzuki_43", "0", "0"},
[4100300143] = {4100300143, 11003001, 45, 37, "0", "0", "和我一起好好確認下吧。", "うちと一緒に確認しよう。", "0", "0", "和咱一起好好確認下吧。", "0", "cv_sk_suzuki_44", "0", "0"},
[4100300200] = {4100300200, 11003002, 1, 1, "0", "0", "蒼霧殘響。", "蒼霧殘響（ハツリバーブ）。", "0", "0", "蒼霧殘響。", "0", "cv_sk1_suzuki_33", "0", "0"},
[4100300201] = {4100300201, 11003002, 2, 2, "0", "0", "嗚姆，咱知道了。", "ふむ、分かった。", "0", "0", "嗚姆，咱知道了。", "0", "cv_sk1_suzuki_2", "0", "0"},
[4100300202] = {4100300202, 11003002, 3, 3, "0", "0", "咱是風林火山的鈴木清風，順帶一提，咱可是隊長喔。", "うちは風林火山の鈴木清風。ちなみに、隊長やで。", "0", "0", "咱是風林火山的鈴木清風，順帶一提，咱可是隊長哦。", "0", "cv_sk1_suzuki_1", "0", "0"},
[4100300203] = {4100300203, 11003002, 4, 4, "0", "idle", "對咱而言，優先保護好同伴才是最重要的。", "うちにとって一番大切なことは仲間を守ることや。", "0", "0", "對咱而言，優先保護好同伴才是最重要的。", "0", "cv_sk1_suzuki_3", "0", "0"},
[4100300204] = {4100300204, 11003002, 5, 4, "0", "idle", "領航呀，咱很好奇呀，你難道不需要休息嗎？", "なあ、ナビゲーター。前から気になってたんやけど…...ナビゲーターは休憩とかせえへんの？", "0", "0", "領航呀，咱很好奇呀，你難道不需要休息嗎？", "0", "cv_sk1_suzuki_4", "0", "0"},
[4100300205] = {4100300205, 11003002, 6, 4, "0", "idle", "不知火那孩子，總是用看小孩的目光看著咱呢。呼呼呼，對於咱來說，她才是需要照顧的孩子呢。因為，咱才是這支隊伍的隊長呀。", "不知火はいつも子供を見る目でうちを見とるけど、ふふ、うちにとっては、あいつこそ世話する必要がある子供なんやで。だって、うちがこのチームの隊長やからね！", "0", "0", "不知火那孩子，總是用看小孩的目光看著咱呢。呼呼呼，對於咱來說，她才是需要照顧的孩子呢。因為，咱才是這支隊伍的隊長呀。", "0", "cv_sk1_suzuki_30", "0", "0"},
[4100300206] = {4100300206, 11003002, 7, 5, "15_1_0_0.8", "level1", "咱的夢想？嗚，咱可沒有精力去想那些。光是照顧隊伍裡的同伴，就已經耗費咱不少精力了。", "うちの夢？うーん、そんなん考える時間がないなあ。チーム內の仲間たちの世話をすることだけで手いっぱいやもん。", "0", "0", "咱的夢想？嗚，咱可沒有精力去想那些。光是照顧隊伍裡的同伴，就已經耗費咱不少精力了。", "0", "cv_sk1_suzuki_31", "0", "0"},
[4100300207] = {4100300207, 11003002, 8, 5, "15_2_0_0.8", "level2", "別……別老是光盯著咱啊，有話快問啦。", "そ、そんな目で見つめんといて。聞きたいことがあるんやったらはよ聞いてや。", "0", "0", "別……別老是光盯著咱啊，有話快問啦。", "0", "cv_sk1_suzuki_5", "0", "0"},
[4100300208] = {4100300208, 11003002, 9, 5, "15_1_0_0.8", "level1", "欸？想向咱請教該怎麼和隊員交流。嗯嗯……老實說，咱也不是很清楚欸……", "え？チームメンバーとどうやって交流すればええかって……？えっと……正直、うちもよくわからんのや……", "0", "0", "哎？想向咱請教該怎麼和隊員交流。嗯嗯……老實說，咱也不是很清楚哎……", "0", "cv_sk1_suzuki_6", "0", "0"},
[4100300209] = {4100300209, 11003002, 10, 5, "15_2_0_0.8", "level2", "欸？咱喜歡的東西？嗯嗯……壽喜燒吧。當然，咱指的是喜歡製作壽喜燒，而不是吃啦。", "え？うちの好きな物？うーん……すき焼きかな。もちろん、食べるのも好きやけど、作るのも好きやしね。", "0", "0", "哎？咱喜歡的東西？嗯嗯……壽喜燒吧。當然，咱指得是喜歡製作壽喜燒，而不是吃啦。", "0", "cv_sk1_suzuki_7", "0", "0"},
[4100300210] = {4100300210, 11003002, 11, 5, "15_1_0_0.8", "level1", "真是的，這段時間領航你總是問東問西的，整得就像是咱那個沒換牙的弟弟一樣。不過……咱覺得這種關係也不錯呢。", "まったく……最近のナビゲーターって、色々質問してくるからまるで歯の生え変わりがまだ始まっとらんうちの弟みたいなんやけど。まぁ……こんな関係でもええけどな。", "0", "0", "真是的，這段時間領航你總是問東問西的，整得就像是咱那個沒換牙的弟弟一樣。不過……咱覺得這種關係也不錯呢。", "0", "cv_sk1_suzuki_8", "0", "0"},
[4100300211] = {4100300211, 11003002, 12, 6, "0", "0", "不得了啊！領航，咱變強了呀！", "大変、ナビゲーター！うち、強くなったんよ！", "0", "0", "不得了啊！領航，咱變強了呀！", "0", "cv_sk1_suzuki_9", "0", "0"},
[4100300212] = {4100300212, 11003002, 13, 7, "0", "0", "你就……這麼在意咱嗎？", "そんなに……うちのことが気になる？", "0", "0", "你就……這麼在意咱嗎？", "0", "cv_sk1_suzuki_10", "0", "0"},
[4100300213] = {4100300213, 11003002, 14, 8, "0", "0", "喔喔喔喔——領航，你看到了嗎！刀的顏色…刀刃的顏色！！！欸，你說沒啥變化？！", "おおっ――ナビゲーター！今の見た？刀の色……刃の色！！！えっ？特に変わっとらんって？！", "0", "0", "噢噢噢噢——領航，你看到了嗎！刀的顏色…刀刃的顏色！！！哎，你說沒啥變化？！", "0", "cv_sk1_suzuki_11", "0", "0"},
[4100300214] = {4100300214, 11003002, 15, 9, "0", "0", "穩穩的！", "ばっちり！", "0", "0", "妥妥滴！", "0", "cv_sk1_suzuki_12", "0", "0"},
[4100300215] = {4100300215, 11003002, 16, 10, "0", "0", "斬落敵人的旗幟吧！", "敵の旗を斬り落とせ！", "0", "0", "斬落敵人的旗幟吧！", "0", "cv_sk1_suzuki_13", "0", "0"},
[4100300216] = {4100300216, 11003002, 17, 11, "0", "0", "嗚姆，真是一場爽快的戰鬥。", "ふぅ、爽快な戦いやったわぁ。", "0", "0", "嗚姆，真是一場爽快的戰鬥。", "0", "cv_sk1_suzuki_14", "0", "0"},
[4100300217] = {4100300217, 11003002, 18, 12, "0", "0", "好了，該回去啦。", "よし、帰ろ。", "0", "0", "妥了，該回去啦。", "0", "cv_sk1_suzuki_15", "0", "0"},
