[4100700101] = {4100700101, 11007001, 2, 2, "0", "0", "如果能幫上大家的話那就最好不過了，畢竟我是大姐姐嘛。", "0", "0", "0", "0", "0", "cv_sk_ridelia_2", "0", "0"},
[4100700102] = {4100700102, 11007001, 3, 3, "0", "0", "我是莉迪婭·李·烏斯季諾維奇。叫我莉迪婭就好了。從今天起就一起生活吧，請多多關照。", "0", "0", "0", "0", "0", "cv_sk_ridelia_1", "0", "0"},
[4100700103] = {4100700103, 11007001, 4, 4, "0", "idle", "啊——來領航，這是我們卡佳的特產糖果，不知道合不合你胃口呢？嘿嘿。", "0", "0", "0", "0", "0", "cv_sk_ridelia_3", "0", "0"},
[4100700104] = {4100700104, 11007001, 5, 4, "0", "idle", "一直盯著大姐姐看是因為遇到什麼麻煩事了嗎？要和大姐姐說說看嗎？", "0", "0", "0", "0", "0", "cv_sk_ridelia_4", "0", "0"},
[4100700105] = {4100700105, 11007001, 6, 4, "0", "idle", "真是的，瑪利亞那個傢夥又犯老毛病了？不是每個人都能接受她那種問候方式吧。", "0", "0", "0", "0", "0", "cv_sk_ridelia_29", "0", "0"},
[4100700106] = {4100700106, 11007001, 7, 5, "15_1_0_0.8", "touch1", "卡佳是個冰冷的地方，不光光是環境，還有那裡的人心……", "0", "0", "0", "0", "0", "cv_sk_ridelia_30", "0", "0"},
[4100700107] = {4100700107, 11007001, 8, 5, "15_1_0_0.8", "touch1", "無論是什麼事情，大姐姐都會幫你解決的。", "0", "0", "0", "0", "0", "cv_sk_ridelia_5", "0", "0"},
[4100700108] = {4100700108, 11007001, 9, 5, "15_1_0_0.8", "touch1", "領航，我要出門去採購些物資,要一起來嗎？今晚我打算給大家做燉牛肉喔。", "0", "0", "0", "0", "0", "cv_sk_ridelia_6", "0", "0"},
[4100700109] = {4100700109, 11007001, 10, 5, "15_2_0_0.8", "touch2", "嘿嘿嘿，總覺得在你面前我都不好意思叫自己是姐姐了呢。你是一個值得依靠和信賴的對象，領航。", "0", "0", "0", "0", "0", "cv_sk_ridelia_7", "0", "0"},
[4100700110] = {4100700110, 11007001, 11, 5, "15_2_0_0.8", "touch2", "等戰爭結束後要來姐姐的家鄉看看嗎？其實很早之前就想邀請你去玩一趟了，但是一直都沒找到合適的機會說罷了。當然，你可不能拒絕姐姐喔~為什麼？嘿嘿嘿，就當做是姐姐在撒嬌好了。", "0", "0", "0", "0", "0", "cv_sk_ridelia_8", "0", "0"},
[4100700111] = {4100700111, 11007001, 12, 6, "0", "0", "更依賴姐姐一些吧。", "0", "0", "0", "0", "0", "cv_sk_ridelia_9", "0", "0"},
[4100700112] = {4100700112, 11007001, 13, 7, "0", "0", "這份力量，一定會為你所用的。", "0", "0", "0", "0", "0", "cv_sk_ridelia_10", "0", "0"},
[4100700113] = {4100700113, 11007001, 14, 8, "0", "0", "真是……我已經不知道該如何表達自己現在的感情了。領航，可以讓姐姐抱一下你嗎？如果能聽到我的心跳聲的話，你應該就能明白了吧。", "0", "0", "0", "0", "0", "cv_sk_ridelia_11", "0", "0"},
[4100700114] = {4100700114, 11007001, 15, 9, "0", "0", "領航！姐姐已經準備好了喔！", "0", "0", "0", "0", "0", "cv_sk_ridelia_12", "0", "0"},
[4100700115] = {4100700115, 11007001, 16, 10, "0", "0", "這裡就交給姐姐吧。", "0", "0", "0", "0", "0", "cv_sk_ridelia_13", "0", "0"},
