[4103200143] = {4103200143, 11032001, 45, 37, "0", "0", "嘿咻！", "0", "0", "0", "0", "0", "cv_sk_qianqiu_45", "0", "0"},
[4103300100] = {4103300100, 11033001, 1, 1, "0", "0", "蒼霧殘響", "0", "0", "0", "0", "0", "cv_sk_starry_1", "0", "0"},
[4103300101] = {4103300101, 11033001, 2, 2, "0", "0", "讓我待在這的話，說不定會被墜落的隕石命中——哈哈，只是開個“電影玩笑”而已。", "0", "0", "0", "0", "0", "cv_sk_starry_2", "0", "0"},
[4103300102] = {4103300102, 11033001, 3, 3, "0", "0", "嗨~色狼先生，好久不見~你已經是正式的領航了？嗯，我也是正式的駕駛員，前線小隊的“星爍”咯……雖然發生了各種各樣的事，但我們總算又見面了。", "0", "0", "0", "0", "0", "cv_sk_starry_3", "0", "0"},
[4103300103] = {4103300103, 11033001, 4, 4, "0", "idle", "海風的氣味……還有你的氣味，真是讓人不想忘懷。", "0", "0", "0", "0", "0", "cv_sk_starry_4", "0", "0"},
[4103300104] = {4103300104, 11033001, 5, 4, "0", "idle", "一想到之後要做的事情，頭就會開始疼起來。算啦，不想那種不開心的事，我們還是享受當下吧！", "0", "0", "0", "0", "0", "cv_sk_starry_5", "0", "0"},
[4103300105] = {4103300105, 11033001, 6, 4, "0", "idle", "我這次算是偷偷摸摸過來的，為了你和我的安全著想，最好不要告訴給第三人，這是我和你的秘——密噢。", "0", "0", "0", "0", "0", "cv_sk_starry_6", "0", "0"},
[4103300106] = {4103300106, 11033001, 7, 5, "15_1_0_0.8", "level1", "怎麼了？對我的身體心動了嗎？", "0", "0", "0", "0", "0", "cv_sk_starry_7", "0", "0"},
[4103300107] = {4103300107, 11033001, 8, 5, "15_1_0_0.8", "level1", "和你一起享受海灘與陽光……哈哈…真是的，難道之後世界就要毀滅了嗎？", "0", "0", "0", "0", "0", "cv_sk_starry_8", "0", "0"},
[4103300108] = {4103300108, 11033001, 9, 5, "15_2_0_0.8", "level2", "想吃嗎？真遺憾，這一次我沒有抽中第二根——不過你要是不介意的話，我可以把這一根給你哦，“啊——”。", "0", "0", "0", "0", "0", "cv_sk_starry_9", "0", "0"},
[4103300109] = {4103300109, 11033001, 10, 5, "15_1_0_0.8", "level1", "光是躺著很沒意思把。喂，色狼先生，我們要不要去做更加刺激的事情？只要你想的話，什麼——都可以噢。", "0", "0", "0", "0", "0", "cv_sk_starry_10", "0", "0"},
[4103300110] = {4103300110, 11033001, 11, 5, "15_1_0_0.8", "level1", "色狼先生，我們來做個約定吧。當我遇到危險時你要來救我——當你遇到危險時，無論我在什麼地方，我都會奔赴到你的身邊，我不會食言的。", "0", "0", "0", "0", "0", "cv_sk_starry_11", "0", "0"},
[4103300111] = {4103300111, 11033001, 12, 6, "0", "0", "不錯不錯。", "0", "0", "0", "0", "0", "cv_sk_starry_12", "0", "0"},
[4103300112] = {4103300112, 11033001, 13, 7, "0", "0", "和我的代號很搭配呢。", "0", "0", "0", "0", "0", "cv_sk_starry_13", "0", "0"},
[4103300113] = {4103300113, 11033001, 14, 8, "0", "0", "我們貪婪的本性會讓我們去不斷索取更好的東西，連運氣也不會放過。色狼先生，也許以後會發生不好的事情，但這一次，我會和你共同面對的。", "0", "0", "0", "0", "0", "cv_sk_starry_14", "0", "0"},
[4103300114] = {4103300114, 11033001, 15, 9, "0", "0", "我更加幸運了？", "0", "0", "0", "0", "0", "cv_sk_starry_15", "0", "0"},
[4103300115] = {4103300115, 11033001, 16, 10, "0", "0", "接下來會發生什麼好事呢？", "0", "0", "0", "0", "0", "cv_sk_starry_16", "0", "0"},
[4103300116] = {4103300116, 11033001, 17, 11, "0", "0", "真好啊，我們又贏了。", "0", "0", "0", "0", "0", "cv_sk_starry_17", "0", "0"},
[4103300117] = {4103300117, 11033001, 18, 12, "0", "0", "確認一下傷患狀況吧。", "0", "0", "0", "0", "0", "cv_sk_starry_18", "0", "0"},
[4103300118] = {4103300118, 11033001, 19, 13, "0", "0", "這樣可算不上勝利呀。", "0", "0", "0", "0", "0", "cv_sk_starry_19", "0", "0"},
[4103300119] = {4103300119, 11033001, 20, 14, "0", "0", "吸取失敗的教訓，這也是成功的必經之路。", "0", "0", "0", "0", "0", "cv_sk_starry_20", "0", "0"},
[4103300120] = {4103300120, 11033001, 21, 15, "0", "0", "很痛吧？", "0", "0", "0", "0", "0", "cv_sk_starry_21", "0", "0"},
[4103300121] = {4103300121, 11033001, 23, 16, "0", "0", "好戲來了。", "0", "0", "0", "0", "0", "cv_sk_starry_23", "0", "0"},
[4103300122] = {4103300122, 11033001, 24, 17, "0", "0", "要賭一賭嗎？", "0", "0", "0", "0", "0", "cv_sk_starry_24", "0", "0"},
[4103300123] = {4103300123, 11033001, 26, 19, "0", "0", "唉~船到橋頭自然直。", "0", "0", "0", "0", "0", "cv_sk_starry_25", "0", "0"},
[4103300124] = {4103300124, 11033001, 27, 20, "0", "0", "噢，色狼先生，又來偷窺了嗎？", "0", "0", "0", "0", "0", "cv_sk_starry_26", "0", "0"},
[4103300125] = {4103300125, 11033001, 28, 21, "0", "0", "怎麼樣，好看嗎？那就趁還能看的時候多看一下吧。", "0", "0", "0", "0", "0", "cv_sk_starry_27", "0", "0"},
[4103300126] = {4103300126, 11033001, 29, 21, "0", "0", "色狼先生要是也巨大化的話，我就可以替你搓背了吧？", "0", "0", "0", "0", "0", "cv_sk_starry_28", "0", "0"},
[4103300127] = {4103300127, 11033001, 30, 22, "0", "0", "撿到錢了嗎？", "0", "0", "0", "0", "0", "cv_sk_starry_29", "0", "0"},
[4103300128] = {4103300128, 11033001, 31, 23, "0", "0", "猜猜我是誰？", "0", "0", "0", "0", "0", "cv_sk_starry_30", "0", "0"},
[4103300129] = {4103300129, 11033001, 32, 24, "0", "0", "恭喜，看來你這次記得我啦。", "0", "0", "0", "0", "0", "cv_sk_starry_31", "0", "0"},
[4103300130] = {4103300130, 11033001, 33, 25, "0", "0", "真遺憾，猜錯了，別在意~", "0", "0", "0", "0", "0", "cv_sk_starry_32", "0", "0"},
[4103300131] = {4103300131, 11033001, 34, 26, "0", "0", "色狼先生，又見面了，看來我還真是走運啊。", "0", "0", "0", "0", "0", "cv_sk_starry_33", "0", "0"},
[4103300132] = {4103300132, 11033001, 35, 27, "0", "0", "遇到危險我會向你求救的~", "0", "0", "0", "0", "0", "cv_sk_starry_34", "0", "0"},
[4103300133] = {4103300133, 11033001, 36, 28, "0", "0", "我不會對她們手下留情的。", "0", "0", "0", "0", "0", "cv_sk_starry_35", "0", "0"},
[4103300134] = {4103300134, 11033001, 37, 29, "0", "0", "嗨——大家好~", "0", "0", "0", "0", "0", "cv_sk_starry_36", "0", "0"},
[4103300135] = {4103300135, 11033001, 38, 30, "0", "0", "招聘新人啦！", "0", "0", "0", "0", "0", "cv_sk_starry_37", "0", "0"},
[4103300136] = {4103300136, 11033001, 39, 31, "0", "0", "抽獎嗎？那我還是離遠點比較好~", "0", "0", "0", "0", "0", "cv_sk_starry_38", "0", "0"},
[4103300137] = {4103300137, 11033001, 40, 32, "0", "0", "購物啊，我不討厭。", "0", "0", "0", "0", "0", "cv_sk_starry_39", "0", "0"},
[4103300138] = {4103300138, 11033001, 41, 33, "0", "0", "你真努力呀。", "0", "0", "0", "0", "0", "cv_sk_starry_40", "0", "0"},
[4103300139] = {4103300139, 11033001, 42, 34, "0", "0", "應付一下就行啦。", "0", "0", "0", "0", "0", "cv_sk_starry_41", "0", "0"},
[4103300140] = {4103300140, 11033001, 43, 35, "0", "0", "有寄錯的禮品就安心收下吧！", "0", "0", "0", "0", "0", "cv_sk_starry_42", "0", "0"},
[4103300141] = {4103300141, 11033001, 44, 36, "0", "0", "要和人聊聊天嗎？", "0", "0", "0", "0", "0", "cv_sk_starry_43", "0", "0"},
[4103300142] = {4103300142, 11033001, 45, 37, "0", "0", "點一下！", "0", "0", "0", "0", "0", "cv_sk_starry_44", "0", "0"},
[4103400100] = {4103400100, 11034001, 1, 1, "0", "0", "蒼霧殘響噢！", "0", "0", "0", "0", "0", "cv_sk_lodonia_34", "0", "0"},
[4103400101] = {4103400101, 11034001, 2, 2, "0", "0", "瞭解！我會把所有想傷害領航的傢夥全部打飛的！", "0", "0", "0", "0", "0", "cv_sk_lodonia_2", "0", "0"},
[4103400102] = {4103400102, 11034001, 3, 3, "0", "0", "噢噢噢！我聽說過你！你就是那位很厲害的領航吧！我是第三研究室防衛班的羅德尼亞，請多關照！", "0", "0", "0", "0", "0", "cv_sk_lodonia_1", "0", "0"},
[4103400103] = {4103400103, 11034001, 4, 4, "0", "idle", "領航，我可是被人評價為“天生的領袖”噢，超——厲害吧！誰說的？哼哼，當然是我自己說的啦。", "0", "0", "0", "0", "0", "cv_sk_lodonia_3", "0", "0"},
[4103400104] = {4103400104, 11034001, 5, 4, "0", "idle", "領航要是無聊的話，我可以為你用風笛演奏樂曲噢！……什麼，“不像是我會做的事”？真是失禮啊，我可是溫柔的女孩子噢！", "0", "0", "0", "0", "0", "cv_sk_lodonia_4", "0", "0"},
[4103400105] = {4103400105, 11034001, 6, 4, "0", "idle", "說起來……我一開始以為多洛莉絲隊長很弱呢。接觸之後才發現，她這不是超強的嗎！真不愧是“隊長”啊。", "0", "0", "0", "0", "0", "cv_sk_lodonia_31", "0", "0"},
[4103400106] = {4103400106, 11034001, 7, 5, "15_1_0_0.8", "level1", "好癢啦哈哈哈！", "0", "0", "0", "0", "0", "cv_sk_lodonia_5", "0", "0"},
[4103400107] = {4103400107, 11034001, 8, 5, "15_2_0_0.8", "level2", "我的夢想？說出來不許笑話我噢！我想成為像我的姐姐，還有多洛莉絲隊長那樣，既強大，又溫柔的人……", "0", "0", "0", "0", "0", "cv_sk_lodonia_32", "0", "0"},
[4103400108] = {4103400108, 11034001, 9, 5, "15_1_0_0.8", "level1", "領航，我基本上是從來不開玩笑的噢。有想要做的事情就現在去做！這是我的人生信條！", "0", "0", "0", "0", "0", "cv_sk_lodonia_6", "0", "0"},
[4103400109] = {4103400109, 11034001, 10, 5, "15_2_0_0.8", "level2", "領航，工作辛苦了，也要稍微注重一下身體噢——啊，不行不行，這樣說話超累啊！姐姐和多洛莉絲隊長是怎麼做到的呀？我偶爾也想試著這樣，溫柔的和領航說話啦~", "0", "0", "0", "0", "0", "cv_sk_lodonia_7", "0", "0"},
[4103400110] = {4103400110, 11034001, 11, 5, "15_1_0_0.8", "level1", "領航，你工作上如果遇到什麼不順心的事，生活上有什麼煩惱，可以跟我說噢。我超願意當你的傾聽者，聽你講述自己的煩心事的！畢竟，這也是我的目標之一啦~", "0", "0", "0", "0", "0", "cv_sk_lodonia_8", "0", "0"},
[4103400111] = {4103400111, 11034001, 12, 6, "0", "0", "前輩們的戰鬥方式超帥啊！", "0", "0", "0", "0", "0", "cv_sk_lodonia_9", "0", "0"},
[4103400112] = {4103400112, 11034001, 13, 7, "0", "0", "噢噢噢，心情高漲起來了！", "0", "0", "0", "0", "0", "cv_sk_lodonia_10", "0", "0"},
[4103400113] = {4103400113, 11034001, 14, 8, "0", "0", "哼哼，這樣一來，我就超過那些“天才”了吧！謝啦！之後就讓我為領航你獻上一曲“友誼地久天長”吧……誒？居然說不合適嗎！？", "0", "0", "0", "0", "0", "cv_sk_lodonia_11", "0", "0"},
[4103400114] = {4103400114, 11034001, 15, 9, "0", "0", "我變得更厲害了!", "0", "0", "0", "0", "0", "cv_sk_lodonia_12", "0", "0"},
[4103400115] = {4103400115, 11034001, 16, 10, "0", "0", "讓它們見識一下新第三研究室防衛班的實力！", "0", "0", "0", "0", "0", "cv_sk_lodonia_13", "0", "0"},
[4103400116] = {4103400116, 11034001, 17, 11, "0", "0", "領航，看到我們在戰場活躍的身姿了嗎？超厲害吧！", "0", "0", "0", "0", "0", "cv_sk_lodonia_14", "0", "0"},
[4103400117] = {4103400117, 11034001, 18, 12, "0", "0", "哼哼，對戰局的把握漸入佳境了呢！", "0", "0", "0", "0", "0", "cv_sk_lodonia_15", "0", "0"},
[4103400118] = {4103400118, 11034001, 19, 13, "0", "0", "我們下一次一定能做得更好的！", "0", "0", "0", "0", "0", "cv_sk_lodonia_16", "0", "0"},
[4103400119] = {4103400119, 11034001, 20, 14, "0", "0", "先暫時撤退吧，我來掩護大家！", "0", "0", "0", "0", "0", "cv_sk_lodonia_17", "0", "0"},
[4103400120] = {4103400120, 11034001, 21, 15, "0", "0", "下一個！", "0", "0", "0", "0", "0", "cv_sk_lodonia_18", "0", "0"},
[4103400121] = {4103400121, 11034001, 23, 16, "0", "0", "開火~！", "0", "0", "0", "0", "0", "cv_sk_lodonia_20", "0", "0"},
[4103400122] = {4103400122, 11034001, 24, 17, "0", "0", "我可不會手下留情噢！", "0", "0", "0", "0", "0", "cv_sk_lodonia_22", "0", "0"},
[4103400123] = {4103400123, 11034001, 25, 18, "0", "0", "接下來是我的超必殺技！接招吧，原罪！", "0", "0", "0", "0", "0", "cv_sk_lodonia_23", "0", "0"},
[4103400124] = {4103400124, 11034001, 26, 19, "0", "0", "還有好多想和領航一起做的事……真遺憾啊……", "0", "0", "0", "0", "0", "cv_sk_lodonia_21", "0", "0"},
[4103400125] = {4103400125, 11034001, 27, 20, "0", "0", "哈哈，這不是領航嗎，你也來泡澡嗎？", "0", "0", "0", "0", "0", "cv_sk_lodonia_24", "0", "0"},
[4103400126] = {4103400126, 11034001, 28, 21, "0", "0", "我也是最近才明白了泡澡的魅力。我決定了，以後要一天泡兩次澡！", "0", "0", "0", "0", "0", "cv_sk_lodonia_25", "0", "0"},
[4103400127] = {4103400127, 11034001, 29, 21, "0", "0", "像這樣慢慢地在水裏躺下，然後放鬆身體——超舒服的！領航，你要一起來試試嗎！", "0", "0", "0", "0", "0", "cv_sk_lodonia_26", "0", "0"},
[4103400128] = {4103400128, 11034001, 30, 22, "0", "0", "有趣的事件要來了嗎！", "0", "0", "0", "0", "0", "cv_sk_lodonia_27", "0", "0"},
[4103400129] = {4103400129, 11034001, 31, 23, "0", "0", "以我們的默契而看，這不是超簡單的嘛，領航！", "0", "0", "0", "0", "0", "cv_sk_lodonia_28", "0", "0"},
[4103400130] = {4103400130, 11034001, 32, 24, "0", "0", "看來領航你超懂我嘛，哈哈！", "0", "0", "0", "0", "0", "cv_sk_lodonia_29", "0", "0"},
[4103400131] = {4103400131, 11034001, 33, 25, "0", "0", "誒~超失望。", "0", "0", "0", "0", "0", "cv_sk_lodonia_30", "0", "0"},
[4103400132] = {4103400132, 11034001, 34, 26, "0", "0", "呼！嘿咻！嘿嘿，安全上壘！嗯？什麼都沒發生啦！我有老老實實地在這裏等你回來噢~", "0", "0", "0", "0", "0", "cv_sk_lodonia_33", "0", "0"},
[4103400133] = {4103400133, 11034001, 35, 27, "0", "0", "差不多該帶我去加入超大型戰役了吧~領航！", "0", "0", "0", "0", "0", "cv_sk_lodonia_35", "0", "0"},
[4103400134] = {4103400134, 11034001, 36, 28, "0", "0", "一口氣清理乾淨，然後變得超級厲害吧！", "0", "0", "0", "0", "0", "cv_sk_lodonia_36", "0", "0"},
[4103400135] = {4103400135, 11034001, 37, 29, "0", "0", "感覺大家都很厲害呢。", "0", "0", "0", "0", "0", "cv_sk_lodonia_37", "0", "0"},
[4103400136] = {4103400136, 11034001, 38, 30, "0", "0", "我超擅長選人的！讓我來吧！", "0", "0", "0", "0", "0", "cv_sk_lodonia_38", "0", "0"},
[4103400137] = {4103400137, 11034001, 39, 31, "0", "0", "讓我來抽吧，我運氣超好的！", "0", "0", "0", "0", "0", "cv_sk_lodonia_39", "0", "0"},
[4103400138] = {4103400138, 11034001, 40, 32, "0", "0", "我要買那個看著最厲害的那個！", "0", "0", "0", "0", "0", "cv_sk_lodonia_40", "0", "0"},
[4103400139] = {4103400139, 11034001, 41, 33, "0", "0", "很有精神嘛！", "0", "0", "0", "0", "0", "cv_sk_lodonia_41", "0", "0"},
[4103400140] = {4103400140, 11034001, 42, 34, "0", "0", "隨便應付一下吧！", "0", "0", "0", "0", "0", "cv_sk_lodonia_42", "0", "0"},
[4103400141] = {4103400141, 11034001, 43, 35, "0", "0", "不帶贈品的郵件沒有意義！", "0", "0", "0", "0", "0", "cv_sk_lodonia_43", "0", "0"},
[4103400142] = {4103400142, 11034001, 44, 36, "0", "0", "我來啦我來啦！", "0", "0", "0", "0", "0", "cv_sk_lodonia_44", "0", "0"},
[4103400143] = {4103400143, 11034001, 45, 37, "0", "0", "超可疑的按鈕！", "0", "0", "0", "0", "0", "cv_sk_lodonia_45", "0", "0"},
[4103500100] = {4103500100, 11035001, 1, 1, "0", "0", "蒼霧殘響。", "0", "0", "0", "0", "0", "cv_sk_zepar_32", "0", "0"},
[4103500101] = {4103500101, 11035001, 2, 2, "0", "0", "真沒想到，如今已經餘裕到可以讓駕駛員做這樣的事了~不過人家並不討厭，倒不如說很中意這份餘裕呢！", "0", "0", "0", "0", "0", "cv_sk_zepar_2", "0", "0"},
[4103500102] = {4103500102, 11035001, 3, 3, "0", "0", "你就是史蒂芬妮提過的那位領航嗎？嘻嘻，我是桀派。現在姑且是“鐵鴉”小隊的隊員。之後你可得好好照顧可愛的人家哦。", "0", "0", "0", "0", "0", "cv_sk_zepar_1", "0", "0"},
[4103500103] = {4103500103, 11035001, 4, 4, "0", "idle", "“所羅門的魔神”？討厭啦，人家這麼可愛的女孩子，怎麼會有那種奇怪的稱號呢？一定是領航你把人家和不知道的哪個誰弄混了。", "0", "0", "0", "0", "0", "cv_sk_zepar_3", "0", "0"},
[4103500104] = {4103500104, 11035001, 5, 4, "0", "idle", "艾吉斯的變化真大呢…這就是“時間”嗎？人家是不是也得努力一下，不能讓那些後生小瞧了~", "0", "0", "0", "0", "0", "cv_sk_zepar_4", "0", "0"},
[4103500105] = {4103500105, 11035001, 6, 4, "0", "idle", "“您要是害羞的話，我就用鎖鏈領走您了哦？”被萊帕尼隊長這麼說了之後，就算是人家也不好意思拒絕了。不過，像現在這樣為隊友提供支援，意外得很適合人家呢！", "0", "0", "0", "0", "0", "cv_sk_zepar_29", "0", "0"},
[4103500106] = {4103500106, 11035001, 7, 5, "15_2_0_0.8", "level2", "困的時候可以想睡多久就睡多久；喜歡的食物想吃多少就可以吃多少；如果有了想要談戀愛的對象，就大膽地去追。這就是人家現在最想做的事情。對方是誰？嘿嘿，這麼想知道麼？", "0", "0", "0", "0", "0", "cv_sk_zepar_30", "0", "0"},
[4103500107] = {4103500107, 11035001, 8, 5, "15_1_0_0.8", "level1", "呵呵~人家是不是很可愛呀？", "0", "0", "0", "0", "0", "cv_sk_zepar_5", "0", "0"},
[4103500108] = {4103500108, 11035001, 9, 5, "15_1_0_0.8", "level1", "哈啊~這種感覺，真好啊。悠悠閑閑的，更別說是和領航一起享受二人世界~", "0", "0", "0", "0", "0", "cv_sk_zepar_6", "0", "0"},
[4103500109] = {4103500109, 11035001, 10, 5, "15_2_0_0.8", "level2", "人家很關心領航你的身體健康哦~跟身體健康比起來，榮譽和金錢都不算什麼了。所以想要休息的時候要好好休息哦。", "0", "0", "0", "0", "0", "cv_sk_zepar_7", "0", "0"},
[4103500110] = {4103500110, 11035001, 11, 5, "15_1_0_0.8", "level1", "“桀派”……它是我的榮譽，也是我的桎梏。就算我躲到地獄，它也把我拉了回來，趕回戰場上。但是，我並不後悔…至少，正是因為大家需要“桀派”，人家才會和領航相遇呀。", "0", "0", "0", "0", "0", "cv_sk_zepar_8", "0", "0"},
[4103500111] = {4103500111, 11035001, 12, 6, "0", "0", "嘻嘻~謝謝~", "0", "0", "0", "0", "0", "cv_sk_zepar_9", "0", "0"},
[4103500112] = {4103500112, 11035001, 13, 7, "0", "0", "變強了嗎…接下來不會要加班吧……", "0", "0", "0", "0", "0", "cv_sk_zepar_10", "0", "0"},
[4103500113] = {4103500113, 11035001, 14, 8, "0", "0", "人家現在的心情真的有些複雜，被如此重視的話，不在戰場上好好表現是不行的吧？嗯…好！決定了，人家得拿出幹勁，讓領航你見識一下“所羅門的魔神”有多麼厲害了！……不過領航還真是喜歡人家呢，嘻嘻~♪", "0", "0", "0", "0", "0", "cv_sk_zepar_11", "0", "0"},
[4103500114] = {4103500114, 11035001, 15, 9, "0", "0", "我已經有不好的預感啦……", "0", "0", "0", "0", "0", "cv_sk_zepar_12", "0", "0"},
[4103500115] = {4103500115, 11035001, 16, 10, "0", "0", "久違的戰場呢……總之加油吧！", "0", "0", "0", "0", "0", "cv_sk_zepar_13", "0", "0"},
[4103500116] = {4103500116, 11035001, 17, 11, "0", "0", "真是漂亮的勝利！那麼可以休息了嗎？", "0", "0", "0", "0", "0", "cv_sk_zepar_14", "0", "0"},
[4103500117] = {4103500117, 11035001, 18, 12, "0", "0", "這種程度的勝利不是剛剛好嘛。", "0", "0", "0", "0", "0", "cv_sk_zepar_15", "0", "0"},
[4103500118] = {4103500118, 11035001, 19, 13, "0", "0", "唉…人家是不是該多點幹勁？", "0", "0", "0", "0", "0", "cv_sk_zepar_16", "0", "0"},
[4103500119] = {4103500119, 11035001, 20, 14, "0", "0", "別在意別在意~活著最重要。", "0", "0", "0", "0", "0", "cv_sk_zepar_17", "0", "0"},
[4103500120] = {4103500120, 11035001, 21, 15, "0", "0", "呵呵~", "0", "0", "0", "0", "0", "cv_sk_zepar_44", "0", "0"},
[4103500121] = {4103500121, 11035001, 23, 16, "0", "0", "要好好表現啊~", "0", "0", "0", "0", "0", "cv_sk_zepar_18", "0", "0"},
[4103500122] = {4103500122, 11035001, 24, 17, "0", "0", "再來一發~", "0", "0", "0", "0", "0", "cv_sk_zepar_20", "0", "0"},
[4103500123] = {4103500123, 11035001, 25, 18, "0", "0", "人家的厲害之處，好好盯著不要眨眼哦~", "0", "0", "0", "0", "0", "cv_sk_zepar_21", "0", "0"},
[4103500124] = {4103500124, 11035001, 26, 19, "0", "0", "哈哈…搞砸了啊。", "0", "0", "0", "0", "0", "cv_sk_zepar_19", "0", "0"},
[4103500125] = {4103500125, 11035001, 27, 20, "0", "0", "領航嗎？真是大膽，但人家不討厭哦。", "0", "0", "0", "0", "0", "cv_sk_zepar_22", "0", "0"},
[4103500126] = {4103500126, 11035001, 28, 21, "0", "0", "要是當時也有這個設施的話…唉……", "0", "0", "0", "0", "0", "cv_sk_zepar_23", "0", "0"},
[4103500127] = {4103500127, 11035001, 29, 21, "0", "0", "泡完澡後，人家一定會變得更可愛喲！嘻嘻~想看麼？", "0", "0", "0", "0", "0", "cv_sk_zepar_24", "0", "0"},
[4103500128] = {4103500128, 11035001, 30, 22, "0", "0", "怎麼啦？", "0", "0", "0", "0", "0", "cv_sk_zepar_25", "0", "0"},
[4103500129] = {4103500129, 11035001, 31, 23, "0", "0", "猜猜人家是誰！", "0", "0", "0", "0", "0", "cv_sk_zepar_26", "0", "0"},
[4103500130] = {4103500130, 11035001, 32, 24, "0", "0", "人家可愛的樣子，果然怎麼也忘不掉吧？嘻嘻~", "0", "0", "0", "0", "0", "cv_sk_zepar_27", "0", "0"},
[4103500131] = {4103500131, 11035001, 33, 25, "0", "0", "哈哈……也是啊…畢竟過去這麼久了嘛……", "0", "0", "0", "0", "0", "cv_sk_zepar_28", "0", "0"},
[4103500132] = {4103500132, 11035001, 34, 26, "0", "0", "領航可以晚一會再開始工作麼？人家剛打算出去玩來著……不行麼？", "0", "0", "0", "0", "0", "cv_sk_zepar_31", "0", "0"},
[4103500133] = {4103500133, 11035001, 35, 27, "0", "0", "偶爾也該上一回戰場了。", "0", "0", "0", "0", "0", "cv_sk_zepar_33", "0", "0"},
[4103500134] = {4103500134, 11035001, 36, 28, "0", "0", "人家不行不行，對手太強了~", "0", "0", "0", "0", "0", "cv_sk_zepar_34", "0", "0"},
[4103500135] = {4103500135, 11035001, 37, 29, "0", "0", "哇哦，好多人啊…", "0", "0", "0", "0", "0", "cv_sk_zepar_35", "0", "0"},
[4103500136] = {4103500136, 11035001, 38, 30, "0", "0", "要招到厲害的駕駛員噢！", "0", "0", "0", "0", "0", "cv_sk_zepar_36", "0", "0"},
[4103500137] = {4103500137, 11035001, 39, 31, "0", "0", "比起裝備更想要休假~", "0", "0", "0", "0", "0", "cv_sk_zepar_37", "0", "0"},
[4103500138] = {4103500138, 11035001, 40, 32, "0", "0", "要給人家買禮物嗎？", "0", "0", "0", "0", "0", "cv_sk_zepar_38", "0", "0"},
[4103500139] = {4103500139, 11035001, 41, 33, "0", "0", "領航的資料已經全被人家看光光啦~", "0", "0", "0", "0", "0", "cv_sk_zepar_39", "0", "0"},
[4103500140] = {4103500140, 11035001, 42, 34, "0", "0", "人家來設置！", "0", "0", "0", "0", "0", "cv_sk_zepar_40", "0", "0"},
[4103500141] = {4103500141, 11035001, 43, 35, "0", "0", "就讓身為秘書的人家來檢查吧！", "0", "0", "0", "0", "0", "cv_sk_zepar_41", "0", "0"},
[4103500142] = {4103500142, 11035001, 44, 36, "0", "0", "人家也想一起聊天~", "0", "0", "0", "0", "0", "cv_sk_zepar_42", "0", "0"},
[4103500143] = {4103500143, 11035001, 45, 37, "0", "0", "真有趣~", "0", "0", "0", "0", "0", "cv_sk_zepar_43", "0", "0"},
[4103600100] = {4103600100, 11036001, 1, 1, "0", "0", "蒼霧殘響", "0", "0", "0", "0", "0", "cv_sk_puruixiou_1", "0", "0"},
[4103600101] = {4103600101, 11036001, 2, 2, "0", "0", "真的？終於能更加近距離地觀察你了呢。", "0", "0", "0", "0", "0", "cv_sk_puruixiou_2", "0", "0"},
[4103600102] = {4103600102, 11036001, 3, 3, "0", "0", "經過計算，你和我相遇的概率是……100%！嘿嘿，開個玩笑。這裡是普瑞席歐，薩哈拉的原罪學者哦~", "0", "0", "0", "0", "0", "cv_sk_puruixiou_3", "0", "0"},
[4103600103] = {4103600103, 11036001, 91, 4, "0", "idle", "雖說能在這裡觀察你已經很不錯了，但科研的推進過程果然無比漫長，我真想快進到下一個階段，比如說……直接上手開始研究！", "0", "0", "0", "0", "0", "cv_sk_puruixiou_4", "0", "0"},
[4103600104] = {4103600104, 11036001, 94, 4, "0", "idle2", "當你凝視著我，我也正凝視著你哦。對於研究目標，不僅是接觸交流，單純地觀察也很必要。", "0", "0", "0", "0", "0", "cv_sk_puruixiou_5", "0", "0"},
[4103600105] = {4103600105, 11036001, 94, 4, "0", "idle2", "梅貝爾的席位，斯緹菈的精準，墨君的學識，都對製蜜人不可或缺。不過維繫這支小隊的，也絕不僅僅是工作上的便利呢。", "0", "0", "0", "0", "0", "cv_sk_puruixiou_6", "0", "0"},
[4103600106] = {4103600106, 11036001, 92, 5, "0", "touch1", "是否萬物皆可測量與計算，連思維也能用數理邏輯加以分析？“七賢”各有答案，而領航你又如何認為呢？對此，我相當感興趣。", "0", "0", "0", "0", "0", "cv_sk_puruixiou_7", "0", "0"},
[4103600107] = {4103600107, 11036001, 92, 5, "0", "touch1", "這些“蜂群”？請放心，它們會乖乖遵守我的指令，就像物理學家的儀器、數學家的公式，以及女王的僕從一樣聽話。", "0", "0", "0", "0", "0", "cv_sk_puruixiou_8", "0", "0"},
[4103600108] = {4103600108, 11036001, 92, 5, "0", "touch1", "要不要來我的實驗室幫忙做點研究？那些數據與儀器是很貴重沒錯，但是你的話，我可以放心。", "0", "0", "0", "0", "0", "cv_sk_puruixiou_9", "0", "0"},
[4103600109] = {4103600109, 11036001, 93, 5, "0", "touch_s1", "對哪位駕駛員的身體數據感興趣嗎？我可以將採集方法告訴你哦。欸？想知道我的？唔……那就要看你有沒有本事拿到了呢~", "0", "0", "0", "0", "0", "cv_sk_puruixiou_10", "0", "0"},
[4103600110] = {4103600110, 11036001, 96, 5, "0", "touch_s2", "最初只是對你的身體感興趣，漸漸的，你人格的構成、情感的運作、思維的奧秘，也開始讓我興致盎然了——這麼難的課題，我已久未遇見過。", "0", "0", "0", "0", "0", "cv_sk_puruixiou_11", "0", "0"},
[4103600111] = {4103600111, 11036001, 12, 6, "0", "0", "成長，就是逐漸減少可能性的過程。", "0", "0", "0", "0", "0", "cv_sk_puruixiou_12", "0", "0"},
[4103600112] = {4103600112, 11036001, 13, 7, "0", "0", "量變引起質變呢。", "0", "0", "0", "0", "0", "cv_sk_puruixiou_13", "0", "0"},
[4103600113] = {4103600113, 11036001, 14, 8, "0", "0", "我會將自己這一成果，署上你的名字，而除此以外的致謝，領航也敬請期待哦。", "0", "0", "0", "0", "0", "cv_sk_puruixiou_14", "0", "0"},
[4103600114] = {4103600114, 11036001, 15, 9, "0", "0", "“蜂群”在嗡鳴。", "0", "0", "0", "0", "0", "cv_sk_puruixiou_15", "0", "0"},
[4103600115] = {4103600115, 11036001, 16, 10, "0", "0", "數據猶如花粉，正待我們採集。", "0", "0", "0", "0", "0", "cv_sk_puruixiou_16", "0", "0"},
[4103600116] = {4103600116, 11036001, 17, 11, "0", "0", "完美結束，新一批經費又有著落了。", "0", "0", "0", "0", "0", "cv_sk_puruixiou_17", "0", "0"},
[4103600117] = {4103600117, 11036001, 18, 12, "0", "0", "不好也不壞，就像多數時候的實驗一樣。", "0", "0", "0", "0", "0", "cv_sk_puruixiou_18", "0", "0"},
[4103600118] = {4103600118, 11036001, 19, 13, "0", "0", "與其在這裡氣餒，不如趕緊回去調整一番。", "0", "0", "0", "0", "0", "cv_sk_puruixiou_19", "0", "0"},
[4103600119] = {4103600119, 11036001, 20, 14, "0", "0", "失敗的數據，與成功同樣珍貴。", "0", "0", "0", "0", "0", "cv_sk_puruixiou_20", "0", "0"},
[4103600120] = {4103600120, 11036001, 21, 15, "0", "0", "你們的貢獻，我會記得鳴謝。", "0", "0", "0", "0", "0", "cv_sk_puruixiou_21", "0", "0"},
[4103600121] = {4103600121, 11036001, 23, 16, "0", "0", "採集知識的蜜。", "0", "0", "0", "0", "0", "cv_sk_puruixiou_22", "0", "0"},
[4103600122] = {4103600122, 11036001, 24, 17, "0", "0", "還沒結束哦。", "0", "0", "0", "0", "0", "cv_sk_puruixiou_23", "0", "0"},
[4103600123] = {4103600123, 11036001, 25, 18, "0", "0", "“蜂群”集結，急襲目標！", "0", "0", "0", "0", "0", "cv_sk_puruixiou_24", "0", "0"},
[4103600124] = {4103600124, 11036001, 26, 19, "0", "0", "哎呀，這次失算了。", "0", "0", "0", "0", "0", "cv_sk_puruixiou_26", "0", "0"},
[4103600125] = {4103600125, 11036001, 27, 20, "0", "0", "我們在此相遇的概率是100%，這是根據直覺，而非計算得出的。", "0", "0", "0", "0", "0", "cv_sk_puruixiou_27", "0", "0"},
[4103600126] = {4103600126, 11036001, 28, 21, "0", "0", "你是以科研人員的冷峻目光在審視著我，還是帶著其他某種意圖呢？", "0", "0", "0", "0", "0", "cv_sk_puruixiou_28", "0", "0"},
[4103600127] = {4103600127, 11036001, 29, 21, "0", "0", "這麼毫無意義的時光，就讓它快點結束吧。", "0", "0", "0", "0", "0", "cv_sk_puruixiou_29", "0", "0"},
[4103600128] = {4103600128, 11036001, 30, 22, "0", "0", "要發生什麼了？", "0", "0", "0", "0", "0", "cv_sk_puruixiou_30", "0", "0"},
[4103600129] = {4103600129, 11036001, 31, 23, "0", "0", "有趣的環節呢。", "0", "0", "0", "0", "0", "cv_sk_puruixiou_31", "0", "0"},
[4103600130] = {4103600130, 11036001, 32, 24, "0", "0", "蜜蜂憑嗅覺辨人，領航你又是憑藉什麼呢？", "0", "0", "0", "0", "0", "cv_sk_puruixiou_32", "0", "0"},
[4103600131] = {4103600131, 11036001, 33, 25, "0", "0", "針對你的錯誤，我真想寫篇論文。", "0", "0", "0", "0", "0", "cv_sk_puruixiou_33", "0", "0"},
[4103600132] = {4103600132, 11036001, 34, 26, "0", "0", "你好呀，今天狀態如何？身體是否疲憊，注意力夠不夠集中，早上醒來時的生理反應還正常嗎？", "0", "0", "0", "0", "0", "cv_sk_puruixiou_34", "0", "0"},
[4103600133] = {4103600133, 11036001, 35, 27, "0", "0", "快快出發吧。", "0", "0", "0", "0", "0", "cv_sk_puruixiou_35", "0", "0"},
[4103600134] = {4103600134, 11036001, 36, 28, "0", "0", "這裡能更安全地採集數據。", "0", "0", "0", "0", "0", "cv_sk_puruixiou_36", "0", "0"},
[4103600135] = {4103600135, 11036001, 37, 29, "0", "0", "我能研究研究她們嗎？", "0", "0", "0", "0", "0", "cv_sk_puruixiou_37", "0", "0"},
[4103600136] = {4103600136, 11036001, 38, 30, "0", "0", "新的研究者，抑或小白鼠？", "0", "0", "0", "0", "0", "cv_sk_puruixiou_38", "0", "0"},
[4103600137] = {4103600137, 11036001, 39, 31, "0", "0", "裝備永遠不嫌多。", "0", "0", "0", "0", "0", "cv_sk_puruixiou_39", "0", "0"},
[4103600138] = {4103600138, 11036001, 40, 32, "0", "0", "採購時間到。", "0", "0", "0", "0", "0", "cv_sk_puruixiou_40", "0", "0"},
[4103600139] = {4103600139, 11036001, 41, 33, "0", "0", "都是些流於表面的資訊啊。", "0", "0", "0", "0", "0", "cv_sk_puruixiou_41", "0", "0"},
[4103600140] = {4103600140, 11036001, 42, 34, "0", "0", "設置就交給你了。", "0", "0", "0", "0", "0", "cv_sk_puruixiou_42", "0", "0"},
[4103600141] = {4103600141, 11036001, 43, 35, "0", "0", "你的郵箱裡怎麼全是女孩子寫的信？", "0", "0", "0", "0", "0", "cv_sk_puruixiou_43", "0", "0"},
[4103600142] = {4103600142, 11036001, 44, 36, "0", "0", "少說，多做。", "0", "0", "0", "0", "0", "cv_sk_puruixiou_44", "0", "0"},
[4103600143] = {4103600143, 11036001, 45, 37, "0", "0", "你去哪？", "0", "0", "0", "0", "0", "cv_sk_puruixiou_45", "0", "0"},
[4103800100] = {4103800100, 11038001, 1, 1, "0", "0", "蒼霧殘響", "0", "0", "0", "0", "0", "cv_sk_kafuka_1", "0", "0"},
[4103800101] = {4103800101, 11038001, 2, 2, "0", "0", "哈？你覺得我適合做這個？", "0", "0", "0", "0", "0", "cv_sk_kafuka_2", "0", "0"},
[4103800102] = {4103800102, 11038001, 3, 3, "0", "0", "我是“歧花”小隊的卡芙卡，如你所見是個所謂的不良，想讓我乖乖聽話可不簡單，你應該做好心理準備了吧？", "0", "0", "0", "0", "0", "cv_sk_kafuka_3", "0", "0"},
[4103800103] = {4103800103, 11038001, 4, 4, "0", "idle", "啫喱糖、棒棒糖、棉花糖……還有人類的精氣與靈魂，都是最美味的甜點哦。", "ゼリーキャンディー、ロリポップ、マシュマロ……あと人間の生気と魂、全部最高に旨いデザートだ。", "0", "0", "0", "0", "cv_sk_kafuka_4", "0", "0"},
[4103800104] = {4103800104, 11038001, 5, 4, "0", "idle", "又一個被我嚇傻了的人類啊，靈魂都肉眼可見地飛走了，簡直是字面意思的魂飛魄散。", "またひとり、アタシにビビッて腰を抜かしたやつがいたぜ。魂が目に見えて飛んでたぞ。魂飛魄散ってのは、まさにこのことだな。", "0", "0", "0", "0", "cv_sk_kafuka_5", "0", "0"},
[4103800105] = {4103800105, 11038001, 6, 4, "0", "idle", "我已經是四大惡靈中最友善的一個了，在後面那棟洋館中還沉睡著更加恐怖的存在。好奇嗎？勸你最好收起這份多餘的情感。", "アタシは四大悪霊の中でも、一番優しい方だぜ。裏の屋敷には、ヤバいヤツが眠ってるからな。…気になるのか？その餘計な好奇心、捨てたほうがいいぜ。", "0", "0", "0", "0", "cv_sk_kafuka_6", "0", "0"},
[4103800106] = {4103800106, 11038001, 7, 5, "15_1_0_0.8", "leve1", "竟敢隨便碰我，你不害怕詛咒嗎？什麼詛咒？呵，很快你就會知道了。", "アタシに觸るなんて、呪いが怖くないのか？何の呪いかって？ハッ、すぐにわかるよ。", "0", "0", "0", "0", "cv_sk_kafuka_7", "0", "0"},
[4103800107] = {4103800107, 11038001, 8, 5, "15_2_0_0.8", "leve2", "說起來，你居然能觸碰到我的身體，照理來說應該直接從中穿過才對，難道你擁有某種特殊的靈力？", "そういえば、あんたはアタシの體に觸(さわ)れるんだよな。普通なら通り抜けるはずなのに、何か特別な力とか持ってんのか？", "0", "0", "0", "0", "cv_sk_kafuka_8", "0", "0"},
[4103800108] = {4103800108, 11038001, 9, 5, "15_1_0_0.8", "leve1", "身邊這些幽靈？它們都是曾迷失於這片森林而逐漸死去的人……開個玩笑，其實只是我召喚出的使魔而已。", "アタシの周りにいる幽霊のことか？こいつらは、この森に迷い込んで死んじまった奴らだよ……ってのは冗談で、本當はアタシが召喚した使い魔だ。", "0", "0", "0", "0", "cv_sk_kafuka_9", "0", "0"},
[4103800109] = {4103800109, 11038001, 10, 5, "15_2_0_0.8", "leve2", "也把你身上帶著的外界物品給我看看吧，我已經忘了自己在這待了多久，外面的世界又發展成什麼樣了。", "あんたが持ってる外界の物を見せてくれよ。ずいぶんと長くここにいるから、外の世界がどんな感じになってるのか気になんだよ。", "0", "0", "0", "0", "cv_sk_kafuka_10", "0", "0"},
[4103800110] = {4103800110, 11038001, 11, 5, "15_1_0_0.8", "leve1", "你依然徘徊於此，是被這片森林給困住了，還是迷戀上了這份幽靜呢？無論如何，請便吧，我並不討厭你這樣的外來者。", "あんた、まだここにいたのか。この森に囚われたのか？それとも、ここの靜かさにハマっちまったのか？まあ、好きにしろよ。あんたみたいなやつは、嫌いじゃないからな。", "0", "0", "0", "0", "cv_sk_kafuka_11", "0", "0"},
[4103800111] = {4103800111, 11038001, 12, 6, "0", "0", "有勞你了。", "0", "0", "0", "0", "0", "cv_sk_kafuka_12", "0", "0"},
[4103800112] = {4103800112, 11038001, 13, 7, "0", "0", "用街機的說法，就是刷新記錄了。", "0", "0", "0", "0", "0", "cv_sk_kafuka_13", "0", "0"},
[4103800113] = {4103800113, 11038001, 14, 8, "0", "0", "畢竟我是不愛廢話的性格，除了一聲“謝謝”外，就讓我用更實在的方式回報你吧。", "0", "0", "0", "0", "0", "cv_sk_kafuka_14", "0", "0"},
[4103800114] = {4103800114, 11038001, 15, 9, "0", "0", "很好，拳頭更硬了。", "0", "0", "0", "0", "0", "cv_sk_kafuka_15", "0", "0"},
[4103800115] = {4103800115, 11038001, 16, 10, "0", "0", "就拿它們來發洩不滿吧。", "0", "0", "0", "0", "0", "cv_sk_kafuka_16", "0", "0"},
[4103800116] = {4103800116, 11038001, 17, 11, "0", "0", "哼，小菜一碟。", "0", "0", "0", "0", "0", "cv_sk_kafuka_17", "0", "0"},
[4103800117] = {4103800117, 11038001, 18, 12, "0", "0", "勉勉強強吧。", "0", "0", "0", "0", "0", "cv_sk_kafuka_18", "0", "0"},
[4103800118] = {4103800118, 11038001, 19, 13, "0", "0", "下次得以牙還牙。", "0", "0", "0", "0", "0", "cv_sk_kafuka_19", "0", "0"},
[4103800119] = {4103800119, 11038001, 20, 14, "0", "0", "可不能連怪物都踩在我頭上。", "0", "0", "0", "0", "0", "cv_sk_kafuka_20", "0", "0"},
[4103800120] = {4103800120, 11038001, 21, 15, "0", "0", "餓有餓報。", "因果応報だ！", "0", "0", "0", "0", "cv_sk_kafuka_21", "0", "0"},
[4103800121] = {4103800121, 11038001, 23, 16, "0", "0", "感受恐怖吧！", "怖がりやがれ！", "0", "0", "0", "0", "cv_sk_kafuka_23", "0", "0"},
[4103800122] = {4103800122, 11038001, 24, 17, "0", "0", "你太吵了。", "うるせーな。", "0", "0", "0", "0", "cv_sk_kafuka_24", "0", "0"},
[4103800123] = {4103800123, 11038001, 26, 19, "0", "0", "終於從詛咒中解脫了嗎……", "ようやく、呪いから解放されるのか……", "0", "0", "0", "0", "cv_sk_kafuka_25", "0", "0"},
[4103800124] = {4103800124, 11038001, 27, 20, "0", "0", "你來了？剛才本來還有個駕駛員，一看我進來就被嚇跑了。", "0", "0", "0", "0", "0", "cv_sk_kafuka_26", "0", "0"},
[4103800125] = {4103800125, 11038001, 28, 21, "0", "0", "你會在浴室裡唱歌嗎？我雖然會，但旁邊有人的話還是算了。", "0", "0", "0", "0", "0", "cv_sk_kafuka_27", "0", "0"},
[4103800126] = {4103800126, 11038001, 29, 21, "0", "0", "有次我在學校浴室裡和其他學生打架，但地太滑，誰也沒打贏誰。", "0", "0", "0", "0", "0", "cv_sk_kafuka_28", "0", "0"},
[4103800127] = {4103800127, 11038001, 30, 22, "0", "0", "這是啥。", "0", "0", "0", "0", "0", "cv_sk_kafuka_29", "0", "0"},
[4103800128] = {4103800128, 11038001, 31, 23, "0", "0", "這遊戲還真是幼稚……", "0", "0", "0", "0", "0", "cv_sk_kafuka_30", "0", "0"},
[4103800129] = {4103800129, 11038001, 32, 24, "0", "0", "好好好，給你誇誇。", "0", "0", "0", "0", "0", "cv_sk_kafuka_31", "0", "0"},
[4103800130] = {4103800130, 11038001, 33, 25, "0", "0", "你是故意猜錯想看我反應吧。", "0", "0", "0", "0", "0", "cv_sk_kafuka_32", "0", "0"},
[4103800131] = {4103800131, 11038001, 34, 26, "0", "0", "來了啊，這次打算向我獻上什麼樣的糖果？", "來たか。今度はどんなお菓子をくれるんだ？", "0", "0", "0", "0", "cv_sk_kafuka_33", "0", "0"},
[4103800132] = {4103800132, 11038001, 35, 27, "0", "0", "去找沙包們玩吧。", "0", "0", "0", "0", "0", "cv_sk_kafuka_34", "0", "0"},
[4103800133] = {4103800133, 11038001, 36, 28, "0", "0", "可別說我欺負弱小。", "0", "0", "0", "0", "0", "cv_sk_kafuka_35", "0", "0"},
[4103800134] = {4103800134, 11038001, 37, 29, "0", "0", "她們好像很開心。", "0", "0", "0", "0", "0", "cv_sk_kafuka_36", "0", "0"},
[4103800135] = {4103800135, 11038001, 38, 30, "0", "0", "又要有新人啊。", "0", "0", "0", "0", "0", "cv_sk_kafuka_37", "0", "0"},
[4103800136] = {4103800136, 11038001, 39, 31, "0", "0", "能自己改造裝備嗎？", "0", "0", "0", "0", "0", "cv_sk_kafuka_38", "0", "0"},
[4103800137] = {4103800137, 11038001, 40, 32, "0", "0", "貨差的話我不付錢哦。", "0", "0", "0", "0", "0", "cv_sk_kafuka_39", "0", "0"},
[4103800138] = {4103800138, 11038001, 41, 33, "0", "0", "普普通通嘛。", "0", "0", "0", "0", "0", "cv_sk_kafuka_40", "0", "0"},
[4103800139] = {4103800139, 11038001, 42, 34, "0", "0", "你在鼓搗什麼？", "0", "0", "0", "0", "0", "cv_sk_kafuka_41", "0", "0"},
[4103800140] = {4103800140, 11038001, 43, 35, "0", "0", "好多字，真麻煩。", "0", "0", "0", "0", "0", "cv_sk_kafuka_42", "0", "0"},
[4103800141] = {4103800141, 11038001, 44, 36, "0", "0", "我更喜歡發語音。", "0", "0", "0", "0", "0", "cv_sk_kafuka_43", "0", "0"},
[4103800142] = {4103800142, 11038001, 45, 37, "0", "0", "啊？", "0", "0", "0", "0", "0", "cv_sk_kafuka_44", "0", "0"},
[4103900100] = {4103900100, 11039001, 1, 1, "0", "0", "蒼霧殘響", "0", "0", "0", "0", "0", "cv_sk_sikadi_vd_01", "0", "0"},
[4103900101] = {4103900101, 11039001, 2, 2, "0", "0", "你選擇了吾，吾也會回應你的呼喚。", "0", "0", "0", "0", "0", "cv_sk_sikadi_vd_02", "0", "0"},
[4103900102] = {4103900102, 11039001, 3, 3, "0", "0", "吾感受到了，已經抑制不住的黑暗力量，隨著奇跡之月升起而復蘇。別擔心，吾會以全新的姿態保護你的，領航。", "0", "0", "0", "0", "0", "cv_sk_sikadi_vd_03", "0", "0"},
[4103900103] = {4103900103, 11039001, 91, 4, "0", "idle", "吾每次“通感暴走”都會和領航一起呢，嘿嘿，這一定是命中註定的紐帶。", "0", "0", "0", "0", "0", "cv_sk_sikadi_vd_04", "0", "0"},
[4103900104] = {4103900104, 11039001, 91, 4, "0", "idle", "這一次又會是怎麼樣的故事在等待著我們呢，按照我們之前經歷的那些，這一次將會是我們故事的後日談。", "0", "0", "0", "0", "0", "cv_sk_sikadi_vd_05", "0", "0"},
[4103900105] = {4103900105, 11039001, 94, 4, "0", "idle2", "只要吾與領航緊緊聯繫在一起，便一定會走到這場快樂美夢的盡頭。", "0", "0", "0", "0", "0", "cv_sk_sikadi_vd_06", "0", "0"},
[4103900106] = {4103900106, 11039001, 94, 4, "0", "idle2", "吾無法想像成為大人的吾會是怎麼樣的……但是和領航待在一起的時候，吾卻能想像出我們的未來，嘿嘿，也許在這一刻吾就是大人了。", "0", "0", "0", "0", "0", "cv_sk_sikadi_vd_07", "0", "0"},
[4103900107] = {4103900107, 11039001, 92, 5, "14_》_0_0.8", "touch1", "啊——張大嘴巴，巧克力來了。吾經過八十一次提煉得到的魔法巧克力，一定能讓你愛上我。", "0", "0", "0", "0", "0", "cv_sk_sikadi_vd_08", "0", "0"},
[4103900108] = {4103900108, 11039001, 92, 5, "14_》_0_0.8", "touch1", "如果不滿足吾的願望，“通感暴走”就不會結束……所以這一次吾的願望是什麼……？領航你想知道嗎？", "0", "0", "0", "0", "0", "cv_sk_sikadi_vd_09", "0", "0"},
[4103900109] = {4103900109, 11039001, 93, 5, "14_》_0_0.8", "touch_s1", "早上好……不要再賴床了，今天說好了要解決吾“通感暴走”的問題的吧？", "0", "0", "0", "0", "0", "cv_sk_sikadi_vd_10", "0", "0"},
[4103900110] = {4103900110, 11039001, 95, 5, "14_》_0_0.8", "touch2", "哼哼，吾的力量凝聚在腹部，這吸血鬼之印就是象徵……誒……什麼？這是魅魔的印章？……不是一樣的嗎？", "0", "0", "0", "0", "0", "cv_sk_sikadi_vd_11", "0", "0"},
[4103900111] = {4103900111, 11039001, 95, 5, "14_》_0_0.8", "touch2", "我們就像被困於籠子中的鳥兒一樣，但是還好……吾和領航關在一起……嘿嘿……", "0", "0", "0", "0", "0", "cv_sk_sikadi_vd_46", "0", "0"},
[4103900112] = {4103900112, 11039001, 96, 5, "14_》_0_0.8", "touch_s2", "領航你看，你的襯衫穿在吾的身上好大哦，都到吾膝蓋這裡了。", "0", "0", "0", "0", "0", "cv_sk_sikadi_vd_47", "0", "0"},
[4103900113] = {4103900113, 11039001, 12, 6, "0", "0", "吾不會放棄的。", "0", "0", "0", "0", "0", "cv_sk_sikadi_vd_12", "0", "0"},
[4103900114] = {4103900114, 11039001, 13, 7, "0", "0", "吾會結束這一切在這一切結束之前。", "0", "0", "0", "0", "0", "cv_sk_sikadi_vd_13", "0", "0"},
[4103900115] = {4103900115, 11039001, 14, 8, "0", "0", "永遠陪我玩鬧，一直一直這樣下去吧。", "0", "0", "0", "0", "0", "cv_sk_sikadi_vd_14", "0", "0"},
[4103900116] = {4103900116, 11039001, 15, 9, "0", "0", "讓吾與你的盛宴再延長一段時間吧。", "0", "0", "0", "0", "0", "cv_sk_sikadi_vd_15", "0", "0"},
[4103900117] = {4103900117, 11039001, 16, 10, "0", "0", "風，吹起來了。", "0", "0", "0", "0", "0", "cv_sk_sikadi_vd_16", "0", "0"},
[4103900118] = {4103900118, 11039001, 17, 11, "0", "0", "世界開始轉動。", "0", "0", "0", "0", "0", "cv_sk_sikadi_vd_17", "0", "0"},
[4103900119] = {4103900119, 11039001, 18, 12, "0", "0", "嗚哇，巧克力量不足。", "0", "0", "0", "0", "0", "cv_sk_sikadi_vd_18", "0", "0"},
[4103900120] = {4103900120, 11039001, 19, 13, "0", "0", "吾不想相信……", "0", "0", "0", "0", "0", "cv_sk_sikadi_vd_19", "0", "0"},
[4103900121] = {4103900121, 11039001, 20, 14, "0", "0", "永恆的夢境……結束了", "0", "0", "0", "0", "0", "cv_sk_sikadi_vd_20", "0", "0"},
[4103900122] = {4103900122, 11039001, 21, 15, "0", "0", "如此簡單。", "0", "0", "0", "0", "0", "cv_sk_sikadi_vd_21", "0", "0"},
[4103900123] = {4103900123, 11039001, 23, 16, "0", "0", "這就是——", "0", "0", "0", "0", "0", "cv_sk_sikadi_vd_23", "0", "0"},
