[4104000110] = {4104000110, 11040001, 92, 5, "14_》_0_0.8", "touch1", "嘿嘿，領航有聽見外面的歡呼聲嗎，馬上就輪到我上場了……我會好好努力的，所以領航也要好好地為我加油哦。", "0", "0", "0", "0", "0", "cv_sk_dororisu_haani_011", "0", "0"},
[4104000111] = {4104000111, 11040001, 92, 5, "14_》_0_0.8", "touch2", "嗚——不管是舞臺外面還是我都撲通撲通的，一直都沒辦法安靜下來——深呼吸——深呼吸——接下來我會加油的！", "0", "0", "0", "0", "0", "cv_sk_dororisu_haani_045", "0", "0"},
[4104000112] = {4104000112, 11040001, 96, 5, "14_》_0_0.8", "touch_s2", "馬上就要開始了……現在我的這份感情，真是讓人情不自禁地沉溺在其中呢。", "0", "0", "0", "0", "0", "cv_sk_dororisu_haani_046", "0", "0"},
