[4104000115] = {4104000115, 11040001, 14, 8, "0", "0", "傳遞更多希望，帶走大家的悲傷，我要做到這樣的事情。", "0", "0", "0", "0", "0", "cv_sk_dororisu_haani_014", "0", "0"},
