[4142000100] = {4142000100, 11042001, 1, 1, "0", "0", "蒼霧殘響！", "0", "0", "0", "0", "0", "cv_sk_hailuo_1", "0", "0"},
[4142000101] = {4142000101, 11042001, 2, 2, "0", "0", "我來啦！把事情都交給我吧，絕對不會出錯的，嘿嘿。", "0", "0", "0", "0", "0", "cv_sk_hailuo_2", "0", "0"},
[4142000102] = {4142000102, 11042001, 3, 3, "0", "0", "我是前線的海蘿！海蘿·特裡亞@#￥%……記不得啦，總之叫我海蘿就好！", "0", "0", "0", "0", "0", "cv_sk_hailuo_3", "0", "0"},
[4142000103] = {4142000103, 11042001, 91, 4, "0", "idle", "我很想養貓噢，不過羅莎說了，養貓就得肩負起對應的責任……光憑氣勢和心情好像是沒辦法做好這件事呢。", "0", "0", "0", "0", "0", "cv_sk_hailuo_4", "0", "0"},
[4142000104] = {4142000104, 11042001, 91, 4, "0", "idle", "遺忘是件不好的事情，但如果連不開心的事情也一起忘了的話，心情說不定就會好起來。這樣想的話，記性不好也可能是件好事！", "0", "0", "0", "0", "0", "cv_sk_hailuo_5", "0", "0"},
[4142000105] = {4142000105, 11042001, 94, 4, "0", "idle2", "我不喜歡下雨，因為下雨的時候既不能跑步，也曬不到太陽，心情也會變差，感覺我的人生失去了一半以上的意義了。", "0", "0", "0", "0", "0", "cv_sk_hailuo_6", "0", "0"},
[4142000106] = {4142000106, 11042001, 94, 4, "0", "idle2", "雨天也不全是壞事，因為當雨停下，烏雲散去，這時候的陽光，一定是最美麗最完美的陽光。這樣想的話，心情就會雀躍起來，興奮不已。", "0", "0", "0", "0", "0", "cv_sk_hailuo_7", "0", "0"},
[4142000107] = {4142000107, 11042001, 95, 5, "14_1_0_0.8", "touch1", "領航也被淋濕了……嗯，我會承擔起幫領航吹乾頭髮，擦乾身體的責任！", "0", "0", "0", "0", "0", "cv_sk_hailuo_8", "0", "0"},
[4142000108] = {4142000108, 11042001, 95, 5, "14_1_0_0.8", "touch2", "阿嚏——糟糕，好像感冒了……這下說不定沒辦法跑步了，大不妙事件呀！", "0", "0", "0", "0", "0", "cv_sk_hailuo_9", "0", "0"},
[4142000109] = {4142000109, 11042001, 93, 5, "14_2_0_0.8", "touch_s1", "誒？", "0", "0", "0", "0", "0", "cv_sk_hailuo_46", "0", "0"},
[4142000110] = {4142000110, 11042001, 92, 5, "14_1_0_0.8", "touch1", "雨……雨，最近雨總是下個不停呢，就像世界也在為什麼事哭泣……嗯，說不定領航能撫平世界的創傷，為它止住淚水哦？", "0", "0", "0", "0", "0", "cv_sk_hailuo_10", "0", "0"},
[4142000111] = {4142000111, 11042001, 92, 5, "14_1_0_0.8", "touch1", "領航，能被人喜歡是一種很棒的事情。這意味著有人把自己的一部分，還有自己的感情交給了你……嗯，我也願意把自己的一部分交給你噢。", "0", "0", "0", "0", "0", "cv_sk_hailuo_11", "0", "0"},
[4142000112] = {4142000112, 11042001, 96, 5, "14_2_0_0.8", "touch_s2", "誒嘿嘿", "0", "0", "0", "0", "0", "cv_sk_hailuo_47", "0", "0"},
[4142000113] = {4142000113, 11042001, 12, 6, "0", "0", "花了好多錢！", "0", "0", "0", "0", "0", "cv_sk_hailuo_12", "0", "0"},
[4142000114] = {4142000114, 11042001, 13, 7, "0", "0", "我會更努力的~", "0", "0", "0", "0", "0", "cv_sk_hailuo_13", "0", "0"},
[4142000115] = {4142000115, 11042001, 14, 8, "0", "0", "感覺不會再輸給任何人了。", "0", "0", "0", "0", "0", "cv_sk_hailuo_14", "0", "0"},
