[4142000121] = {4142000121, 11042001, 20, 14, "0", "0", "搞砸了……", "0", "0", "0", "0", "0", "cv_sk_hailuo_20", "0", "0"},
[4142000122] = {4142000122, 11042001, 21, 15, "0", "0", "啪嗒！", "0", "0", "0", "0", "0", "cv_sk_hailuo_21", "0", "0"},
[4142000123] = {4142000123, 11042001, 23, 16, "0", "0", "看招！", "0", "0", "0", "0", "0", "cv_sk_hailuo_23", "0", "0"},
[4142000124] = {4142000124, 11042001, 24, 17, "0", "0", "還有一招！", "0", "0", "0", "0", "0", "cv_sk_hailuo_24", "0", "0"},
[4142000125] = {4142000125, 11042001, 25, 18, "0", "0", "讓你飛起來吧！", "0", "0", "0", "0", "0", "cv_sk_hailuo_25", "0", "0"},
[4142000126] = {4142000126, 11042001, 26, 19, "0", "0", "不太妙……大家要平安呀……", "0", "0", "0", "0", "0", "cv_sk_hailuo_26", "0", "0"},
[4142000127] = {4142000127, 11042001, 27, 20, "0", "0", "領航，一起來洗澡吧！", "0", "0", "0", "0", "0", "cv_sk_hailuo_27", "0", "0"},
[4142000128] = {4142000128, 11042001, 28, 21, "0", "0", "嗯……領航？你什麼時候在的？一開始就在嗎？誒嘿，我忘記了~！", "0", "0", "0", "0", "0", "cv_sk_hailuo_28", "0", "0"},
[4142000129] = {4142000129, 11042001, 29, 21, "0", "0", "身體好暖和……就像在曬太陽一樣，真舒服，嘿嘿。", "0", "0", "0", "0", "0", "cv_sk_hailuo_29", "0", "0"},
[4142000130] = {4142000130, 11042001, 30, 22, "0", "0", "沒、沒事吧？！", "0", "0", "0", "0", "0", "cv_sk_hailuo_30", "0", "0"},
[4142000131] = {4142000131, 11042001, 31, 23, "0", "0", "我是……誰？", "0", "0", "0", "0", "0", "cv_sk_hailuo_31", "0", "0"},
[4142000132] = {4142000132, 11042001, 32, 24, "0", "0", "我都差點想不起來我是誰啦！", "0", "0", "0", "0", "0", "cv_sk_hailuo_32", "0", "0"},
[4142000133] = {4142000133, 11042001, 33, 25, "0", "0", "我也沒想起來，哈哈~", "0", "0", "0", "0", "0", "cv_sk_hailuo_33", "0", "0"},
[4142000134] = {4142000134, 11042001, 34, 26, "0", "0", "噢，領航，你來啦，要一起曬太陽嗎？今天的太陽光可是完美陽光哦。", "0", "0", "0", "0", "0", "cv_sk_hailuo_34", "0", "0"},
[4142000135] = {4142000135, 11042001, 35, 27, "0", "0", "今天要去的地方是……哪裡來著？對了，我們要做什麼？", "0", "0", "0", "0", "0", "cv_sk_hailuo_35", "0", "0"},
[4142000136] = {4142000136, 11042001, 36, 28, "0", "0", "只要不用記東西的話，我誰都不會輸的！", "0", "0", "0", "0", "0", "cv_sk_hailuo_36", "0", "0"},
[4142000137] = {4142000137, 11042001, 37, 29, "0", "0", "哇哇哇，好多人，我記不住名字的啦……", "0", "0", "0", "0", "0", "cv_sk_hailuo_37", "0", "0"},
[4142000138] = {4142000138, 11042001, 38, 30, "0", "0", "新人？我要當前輩了？", "0", "0", "0", "0", "0", "cv_sk_hailuo_38", "0", "0"},
[4142000139] = {4142000139, 11042001, 39, 31, "0", "0", "我更加信賴自己的拳頭！", "0", "0", "0", "0", "0", "cv_sk_hailuo_39", "0", "0"},
[4142000140] = {4142000140, 11042001, 40, 32, "0", "0", "眼睛看不過來了！", "0", "0", "0", "0", "0", "cv_sk_hailuo_40", "0", "0"},
[4142000141] = {4142000141, 11042001, 41, 33, "0", "0", "領航的名字是……我記住啦！", "0", "0", "0", "0", "0", "cv_sk_hailuo_41", "0", "0"},
[4142000142] = {4142000142, 11042001, 42, 34, "0", "0", "設置~", "0", "0", "0", "0", "0", "cv_sk_hailuo_42", "0", "0"},
[4142000143] = {4142000143, 11042001, 43, 35, "0", "0", "好記性不如爛筆頭~", "0", "0", "0", "0", "0", "cv_sk_hailuo_43", "0", "0"},
[4142000144] = {4142000144, 11042001, 44, 36, "0", "0", "我是來自切斯頓的海蘿！", "0", "0", "0", "0", "0", "cv_sk_hailuo_44", "0", "0"},
[4142000145] = {4142000145, 11042001, 45, 37, "0", "0", "咋啦？", "0", "0", "0", "0", "0", "cv_sk_hailuo_45", "0", "0"},
[4143000100] = {4143000100, 11043001, 1, 1, "0", "0", "蒼霧殘響", "0", "0", "0", "0", "0", "cv_sk_mila_1", "0", "0"},
[4143000101] = {4143000101, 11043001, 2, 2, "0", "0", "能有更多傳教機會了？", "0", "0", "0", "0", "0", "cv_sk_mila_2", "0", "0"},
[4143000102] = {4143000102, 11043001, 3, 3, "0", "0", "你好啊領航，我是多瑙教區的主教米菈~呵呵，感覺我的語調不太像一名神職？看來你的瞭解有些滯後了，聖濯教會可是如奔流般與時俱進的哦。", "0", "0", "0", "0", "0", "cv_sk_mila_3", "0", "0"},
[4143000103] = {4143000103, 11043001, 4, 4, "0", "idle", "古人們曾想像神的模樣，有人認為神就如同我現在這般巨大，然而矗立在此俯瞰著大地，我不由得感到人類的想像力是那麼貧弱。", "0", "0", "0", "0", "0", "cv_sk_mila_4", "0", "0"},
[4143000104] = {4143000104, 11043001, 5, 4, "0", "idle", "在這種地方以巨大化的軀體宣說教義，想必能起到非常不錯的傳教效果，領航覺得呢？唔，不允許嗎？真的不行嗎？", "0", "0", "0", "0", "0", "cv_sk_mila_5", "0", "0"},
[4143000105] = {4143000105, 11043001, 6, 4, "0", "idle", "奧菲利亞和塞蕾希婭都是相當努力又單純的孩子，領航跟她們相處時，可要記得不能欺負得太過哦。", "0", "0", "0", "0", "0", "cv_sk_mila_6", "0", "0"},
[4143000106] = {4143000106, 11043001, 7, 5, "15_1_0_0.8", "level1", "只是內斂自省、埋頭祈禱的話，奇跡可是不會自己降臨的，為了我們各自的信念，一起更加大膽地昂首向前吧。", "0", "0", "0", "0", "0", "cv_sk_mila_7", "0", "0"},
[4143000107] = {4143000107, 11043001, 8, 5, "15_1_0_0.8", "level1", "管風琴音域寬廣，規模宏大，氣流振鳴所發出的樂聲猶如信眾們的整齊合唱。領航你的通感，是不是也能和信仰一樣，讓人們發自真心地意念合一呢？", "0", "0", "0", "0", "0", "cv_sk_mila_8", "0", "0"},
[4143000108] = {4143000108, 11043001, 9, 5, "15_2_0_0.8", "level2", "聖濯教會並不是那種頑固的守舊派，我們教義的細節其實一直隨著時代演變、革新，領航若有興趣，禮拜之日不妨來教堂好好傾聽一下。", "0", "0", "0", "0", "0", "cv_sk_mila_9", "0", "0"},
[4143000109] = {4143000109, 11043001, 10, 5, "15_2_0_0.8", "level2", "如同預言往往會自我實現，信仰也擁有神奇的力量，只要你相信，它就將成真。而我的行動正是這種篤信的產物，它能讓我心無旁騖地幫助人們。", "0", "0", "0", "0", "0", "cv_sk_mila_10", "0", "0"},
[4143000110] = {4143000110, 11043001, 11, 5, "15_1_0_0.8", "level1", "哎呀，領航喜歡經由肌膚與人交流？那麼可以將腦袋再貼近些……現在，能仔細聽見嗎？脈搏是生命的激流，心跳則是為你而鳴響的戰鼓。", "0", "0", "0", "0", "0", "cv_sk_mila_11", "0", "0"},
[4143000111] = {4143000111, 11043001, 12, 6, "0", "0", "感謝恩賜。", "0", "0", "0", "0", "0", "cv_sk_mila_12", "0", "0"},
[4143000112] = {4143000112, 11043001, 13, 7, "0", "0", "宛若開啟一眼清泉。", "0", "0", "0", "0", "0", "cv_sk_mila_13", "0", "0"},
[4143000113] = {4143000113, 11043001, 14, 8, "0", "0", "細微的泉流積累匯聚，終將形成一股碎岩之勢。以我的琴聲作為伴奏，讓大家的努力一起沖洗世間的的塵霾吧。", "0", "0", "0", "0", "0", "cv_sk_mila_14", "0", "0"},
[4143000114] = {4143000114, 11043001, 15, 9, "0", "0", "音色更加明亮了。", "0", "0", "0", "0", "0", "cv_sk_mila_15", "0", "0"},
[4143000115] = {4143000115, 11043001, 16, 10, "0", "0", "我將奏響聖樂。", "0", "0", "0", "0", "0", "cv_sk_mila_16", "0", "0"},
[4143000116] = {4143000116, 11043001, 17, 11, "0", "0", "不完美的，也就無法稱之為奇跡。", "0", "0", "0", "0", "0", "cv_sk_mila_17", "0", "0"},
[4143000117] = {4143000117, 11043001, 18, 12, "0", "0", "只要人在，就還能重來。", "0", "0", "0", "0", "0", "cv_sk_mila_18", "0", "0"},
[4143000118] = {4143000118, 11043001, 19, 13, "0", "0", "這樣的結果，人們可不太能接受。", "0", "0", "0", "0", "0", "cv_sk_mila_19", "0", "0"},
[4143000119] = {4143000119, 11043001, 20, 14, "0", "0", "就連我也很難接受這種結果。", "0", "0", "0", "0", "0", "cv_sk_mila_20", "0", "0"},
[4143000120] = {4143000120, 11043001, 21, 15, "0", "0", "很好，很乖。", "0", "0", "0", "0", "0", "cv_sk_mila_21", "0", "0"},
[4143000121] = {4143000121, 11043001, 23, 16, "0", "0", "不要躲開哦。", "0", "0", "0", "0", "0", "cv_sk_mila_22", "0", "0"},
[4143000122] = {4143000122, 11043001, 24, 17, "0", "0", "請安息吧。", "0", "0", "0", "0", "0", "cv_sk_mila_23", "0", "0"},
[4143000123] = {4143000123, 11043001, 25, 18, "0", "0", "讓天空也為之共鳴的聲音，還請洗耳恭聽。", "0", "0", "0", "0", "0", "cv_sk_mila_24", "0", "0"},
[4143000124] = {4143000124, 11043001, 26, 19, "0", "0", "只好先撤退了。", "0", "0", "0", "0", "0", "cv_sk_mila_26", "0", "0"},
[4143000125] = {4143000125, 11043001, 27, 20, "0", "0", "真想和艾吉斯合作，推出教會主題的維護池啊。", "0", "0", "0", "0", "0", "cv_sk_mila_27", "0", "0"},
[4143000126] = {4143000126, 11043001, 28, 21, "0", "0", "洗禮時保持靜默，是在內心進行祈禱嗎？", "0", "0", "0", "0", "0", "cv_sk_mila_28", "0", "0"},
[4143000127] = {4143000127, 11043001, 29, 21, "0", "0", "領航累了嗎？這種程度就不行的話，可沒法跨越萬千苦難哦。", "0", "0", "0", "0", "0", "cv_sk_mila_29", "0", "0"},
[4143000128] = {4143000128, 11043001, 30, 22, "0", "0", "真期待呢。", "0", "0", "0", "0", "0", "cv_sk_mila_30", "0", "0"},
[4143000129] = {4143000129, 11043001, 31, 23, "0", "0", "需要我給出更多提示嗎？", "0", "0", "0", "0", "0", "cv_sk_mila_31", "0", "0"},
[4143000130] = {4143000130, 11043001, 32, 24, "0", "0", "我就相信你能猜中。", "0", "0", "0", "0", "0", "cv_sk_mila_32", "0", "0"},
[4143000131] = {4143000131, 11043001, 33, 25, "0", "0", "也是沒辦法的事呢。", "0", "0", "0", "0", "0", "cv_sk_mila_33", "0", "0"},
[4143000132] = {4143000132, 11043001, 34, 26, "0", "0", "“人不會兩次踏入同一條河流”，而我現在所見到的領航是否與昨天一樣？嗯……狀態似乎更好了些，看來的確不同呢。", "0", "0", "0", "0", "0", "cv_sk_mila_34", "0", "0"},
[4143000133] = {4143000133, 11043001, 35, 27, "0", "0", "一起帶去福音。", "0", "0", "0", "0", "0", "cv_sk_mila_35", "0", "0"},
[4143000134] = {4143000134, 11043001, 36, 28, "0", "0", "也是不錯的選擇。", "0", "0", "0", "0", "0", "cv_sk_mila_36", "0", "0"},
[4143000135] = {4143000135, 11043001, 37, 29, "0", "0", "還有迷茫的人。", "0", "0", "0", "0", "0", "cv_sk_mila_37", "0", "0"},
[4143000136] = {4143000136, 11043001, 38, 30, "0", "0", "做好迎接的準備吧。", "0", "0", "0", "0", "0", "cv_sk_mila_38", "0", "0"},
[4143000137] = {4143000137, 11043001, 39, 31, "0", "0", "我會為其賜予祝福。", "0", "0", "0", "0", "0", "cv_sk_mila_39", "0", "0"},
[4143000138] = {4143000138, 11043001, 40, 32, "0", "0", "大大方方地採購。", "0", "0", "0", "0", "0", "cv_sk_mila_40", "0", "0"},
[4143000139] = {4143000139, 11043001, 41, 33, "0", "0", "怎樣都好啦。", "0", "0", "0", "0", "0", "cv_sk_mila_41", "0", "0"},
[4143000140] = {4143000140, 11043001, 42, 34, "0", "0", "請慢慢來。", "0", "0", "0", "0", "0", "cv_sk_mila_42", "0", "0"},
[4143000141] = {4143000141, 11043001, 43, 35, "0", "0", "有給我的嗎？", "0", "0", "0", "0", "0", "cv_sk_mila_43", "0", "0"},
[4143000142] = {4143000142, 11043001, 44, 36, "0", "0", "能不能發送音頻？", "0", "0", "0", "0", "0", "cv_sk_mila_44", "0", "0"},
[4143000143] = {4143000143, 11043001, 45, 37, "0", "0", "請。", "0", "0", "0", "0", "0", "cv_sk_mila_45", "0", "0"},
[4145000100] = {4145000100, 11045001, 1, 1, "0", "0", "蒼霧殘響", "0", "0", "0", "0", "0", "cv_sk_feilier_33", "0", "0"},
[4145000101] = {4145000101, 11045001, 2, 2, "0", "0", "只要呆在這裡，就能和你保持通感？", "0", "0", "0", "0", "0", "cv_sk_feilier_2", "0", "0"},
[4145000102] = {4145000102, 11045001, 3, 3, "0", "0", "你就是多瑙的領航？好小一隻啊……先自我介紹一下。晨曦，吠黎爾，B17，是B組唯一倖存下來的失敗品。通感治療，就拜託你了。", "0", "0", "0", "0", "0", "cv_sk_feilier_1", "0", "0"},
[4145000103] = {4145000103, 11045001, 4, 4, "0", "idle", "每次連上通感，感覺整個人都飄飄然的，好舒服……", "0", "0", "0", "0", "0", "cv_sk_feilier_3", "0", "0"},
[4145000104] = {4145000104, 11045001, 5, 4, "0", "idle", "……糟糕，有點上癮欸。", "0", "0", "0", "0", "0", "cv_sk_feilier_4", "0", "0"},
[4145000105] = {4145000105, 11045001, 6, 4, "0", "idle", "咦？通感怎麼斷了？", "0", "0", "0", "0", "0", "cv_sk_feilier_5", "0", "0"},
[4145000106] = {4145000106, 11045001, 7, 5, "15_1_0_0.8", "level1", "等解除巨大化了，可不要再這麼觸碰我。我不確定，那時候的自己……會不會傷到你。", "0", "0", "0", "0", "0", "cv_sk_feilier_6", "0", "0"},
[4145000107] = {4145000107, 11045001, 8, 5, "15_2_0_0.8", "level2", "請放心，現在我能控制住自己的。", "0", "0", "0", "0", "0", "cv_sk_feilier_7", "0", "0"},
[4145000108] = {4145000108, 11045001, 9, 5, "15_1_0_0.8", "level1", "衣服？無所謂，就讓它破著吧。反正也不過是層布而已。", "0", "0", "0", "0", "0", "cv_sk_feilier_8", "0", "0"},
[4145000109] = {4145000109, 11045001, 10, 5, "15_2_0_0.8", "level2", "回印加？為什麼？我可是知道的，我是多瑙人，要回也是回多瑙才對。", "0", "0", "0", "0", "0", "cv_sk_feilier_9", "0", "0"},
[4145000110] = {4145000110, 11045001, 11, 5, "15_1_0_0.8", "level1", "只要一直在一起，就能一直保持通感……永遠不斷開……", "0", "0", "0", "0", "0", "cv_sk_feilier_10", "0", "0"},
[4145000111] = {4145000111, 11045001, 12, 6, "0", "0", "聽你的。", "0", "0", "0", "0", "0", "cv_sk_feilier_11", "0", "0"},
[4145000112] = {4145000112, 11045001, 13, 7, "0", "0", "都聽你的。", "0", "0", "0", "0", "0", "cv_sk_feilier_12", "0", "0"},
[4145000113] = {4145000113, 11045001, 14, 8, "0", "0", "照這個趨勢，或許不久後，即便沒有連接幻化核心，我也能保持意志，與你正常交流？真期待那一天的到來呀。", "0", "0", "0", "0", "0", "cv_sk_feilier_13", "0", "0"},
[4145000114] = {4145000114, 11045001, 15, 9, "0", "0", "小心，這爪子還挺利的。", "0", "0", "0", "0", "0", "cv_sk_feilier_14", "0", "0"},
[4145000115] = {4145000115, 11045001, 16, 10, "0", "0", "別忘了搭建通感。", "0", "0", "0", "0", "0", "cv_sk_feilier_15", "0", "0"},
[4145000116] = {4145000116, 11045001, 17, 11, "0", "0", "你很高興。我能感受到。", "0", "0", "0", "0", "0", "cv_sk_feilier_16", "0", "0"},
[4145000117] = {4145000117, 11045001, 18, 12, "0", "0", "小傷，沒事。有尼姆比斯，能修復。", "0", "0", "0", "0", "0", "cv_sk_feilier_17", "0", "0"},
[4145000118] = {4145000118, 11045001, 19, 13, "0", "0", "手上的繃帶，不髒，分你一些？", "0", "0", "0", "0", "0", "cv_sk_feilier_18", "0", "0"},
[4145000119] = {4145000119, 11045001, 20, 14, "0", "0", "不要生氣，不要沮喪……我再去和它們打一架，你會不會開心些？", "0", "0", "0", "0", "0", "cv_sk_feilier_19", "0", "0"},
[4145000120] = {4145000120, 11045001, 21, 15, "0", "0", "撕裂你！", "0", "0", "0", "0", "0", "cv_sk_feilier_20", "0", "0"},
[4145000121] = {4145000121, 11045001, 23, 16, "0", "0", "是你剛才打我的？", "0", "0", "0", "0", "0", "cv_sk_feilier_21", "0", "0"},
[4145000122] = {4145000122, 11045001, 24, 17, "0", "0", "好痛呀……", "0", "0", "0", "0", "0", "cv_sk_feilier_23", "0", "0"},
[4145000123] = {4145000123, 11045001, 25, 18, "0", "0", "現在的我可是無敵的！", "0", "0", "0", "0", "0", "cv_sk_feilier_24", "0", "0"},
[4145000124] = {4145000124, 11045001, 26, 19, "0", "0", "眼睛……不可以閉上……", "0", "0", "0", "0", "0", "cv_sk_feilier_22", "0", "0"},
[4145000125] = {4145000125, 11045001, 27, 20, "0", "0", "這也是治療的一環？", "0", "0", "0", "0", "0", "cv_sk_feilier_25", "0", "0"},
[4145000126] = {4145000126, 11045001, 28, 21, "0", "0", "我都快忘了，原來人類的肌膚是如此溫暖……", "0", "0", "0", "0", "0", "cv_sk_feilier_26", "0", "0"},
[4145000127] = {4145000127, 11045001, 29, 21, "0", "0", "……不痛，癢癢的。好奇怪呀。", "0", "0", "0", "0", "0", "cv_sk_feilier_27", "0", "0"},
[4145000128] = {4145000128, 11045001, 30, 22, "0", "0", "要結束了？", "0", "0", "0", "0", "0", "cv_sk_feilier_28", "0", "0"},
[4145000129] = {4145000129, 11045001, 31, 23, "0", "0", "不要明知故問呐。", "0", "0", "0", "0", "0", "cv_sk_feilier_29", "0", "0"},
[4145000130] = {4145000130, 11045001, 32, 24, "0", "0", "自問自答很有意思麼……那我也要來。猜猜我是誰？", "0", "0", "0", "0", "0", "cv_sk_feilier_30", "0", "0"},
[4145000131] = {4145000131, 11045001, 33, 25, "0", "0", "……那個人是誰？", "0", "0", "0", "0", "0", "cv_sk_feilier_31", "0", "0"},
[4145000132] = {4145000132, 11045001, 34, 26, "0", "0", "終於回來了……其他的不急，先重新連上通感吧。快點，我已經準備好了。", "0", "0", "0", "0", "0", "cv_sk_feilier_32", "0", "0"},
[4145000133] = {4145000133, 11045001, 35, 27, "0", "0", "好吧。治療期間，我確實得保護你的人身安全呢。", "0", "0", "0", "0", "0", "cv_sk_feilier_34", "0", "0"},
[4145000134] = {4145000134, 11045001, 36, 28, "0", "0", "這裡也是靠拳頭說話麼。", "0", "0", "0", "0", "0", "cv_sk_feilier_35", "0", "0"},
[4145000135] = {4145000135, 11045001, 37, 29, "0", "0", "好多的人……", "0", "0", "0", "0", "0", "cv_sk_feilier_36", "0", "0"},
[4145000136] = {4145000136, 11045001, 38, 30, "0", "0", "這裡有我就夠了。", "0", "0", "0", "0", "0", "cv_sk_feilier_37", "0", "0"},
[4145000137] = {4145000137, 11045001, 39, 31, "0", "0", "這些裝備……如果被它們打，一定很痛……", "0", "0", "0", "0", "0", "cv_sk_feilier_38", "0", "0"},
[4145000138] = {4145000138, 11045001, 40, 32, "0", "0", "我可以幫忙搬東西。我力氣很大的。", "0", "0", "0", "0", "0", "cv_sk_feilier_39", "0", "0"},
[4145000139] = {4145000139, 11045001, 41, 33, "0", "0", "就算療程結束，我也是可以繼續呆在這裡的吧？", "0", "0", "0", "0", "0", "cv_sk_feilier_40", "0", "0"},
[4145000140] = {4145000140, 11045001, 42, 34, "0", "0", "需要我更大聲說話？還是再小聲一點？", "0", "0", "0", "0", "0", "cv_sk_feilier_41", "0", "0"},
[4145000141] = {4145000141, 11045001, 43, 35, "0", "0", "我來幫忙整理。", "0", "0", "0", "0", "0", "cv_sk_feilier_42", "0", "0"},
[4145000142] = {4145000142, 11045001, 44, 36, "0", "0", "你在看什麼？", "0", "0", "0", "0", "0", "cv_sk_feilier_43", "0", "0"},
[4145000143] = {4145000143, 11045001, 45, 37, "0", "0", "不要不理我啊。", "0", "0", "0", "0", "0", "cv_sk_feilier_44", "0", "0"},
[4147000100] = {4147000100, 11047001, 1, 1, "0", "0", "蒼霧殘響", "0", "0", "0", "0", "0", "cv_sk_dangyangtu_1", "0", "0"},
[4147000101] = {4147000101, 11047001, 2, 2, "0", "0", "欸？真的不是什麼整人綜藝節目？", "0", "0", "0", "0", "0", "cv_sk_dangyangtu_2", "0", "0"},
[4147000102] = {4147000102, 11047001, 3, 3, "0", "0", "這裡是蕩漾兔，一名活躍在網絡世界的偶像~你就是我的製作人嗎？雖然並非初次見面，以後請多指教咯！", "0", "0", "0", "0", "0", "cv_sk_dangyangtu_3", "0", "0"},
[4147000103] = {4147000103, 11047001, 4, 4, "0", "idle", "如果將城市視為一座巨大的演唱會場館，那麼多瑙可謂是座無虛席，不放聲唱首歌真有些浪費呢。", "0", "0", "0", "0", "0", "cv_sk_dangyangtu_4", "0", "0"},
[4147000104] = {4147000104, 11047001, 5, 4, "0", "idle", "怎麼啦怎麼啦？突然間這麼死氣沉沉的，作為我的製作人兼粉絲，不時刻保持活力的話可是會讓我很傷心的！", "0", "0", "0", "0", "0", "cv_sk_dangyangtu_5", "0", "0"},
[4147000105] = {4147000105, 11047001, 6, 4, "0", "idle", "小隊裡老有人想揪出我的真實身份，實在是傷腦筋啊，戳破了真實與虛假之間的這層面紗，許多事可就會沒有意思了。", "0", "0", "0", "0", "0", "cv_sk_dangyangtu_6", "0", "0"},
[4147000106] = {4147000106, 11047001, 7, 5, "15_1_0_0.8", "level1", "用尼姆比斯能幻化出的這具身體，操控起來的確更輕鬆了，但相比投影也少了些樂趣啊，比如說，不能裝作電子幽靈嚇唬人了~", "0", "0", "0", "0", "0", "cv_sk_dangyangtu_7", "0", "0"},
[4147000107] = {4147000107, 11047001, 8, 5, "15_1_0_0.8", "level1", "喂喂現在可不是握手會的時候啊！而且作為我的製作人，你不是每天都有機會和我互動嗎？", "0", "0", "0", "0", "0", "cv_sk_dangyangtu_8", "0", "0"},
[4147000108] = {4147000108, 11047001, 9, 5, "15_1_0_0.8", "level2", "想知道我的真實身份嗎？我已經將解開秘密的鑰匙藏在網絡海洋的某一處了，請製作人自行尋找吧~當然，可別忘了有句話叫“狡兔三窟”。", "0", "0", "0", "0", "0", "cv_sk_dangyangtu_9", "0", "0"},
[4147000109] = {4147000109, 11047001, 10, 5, "15_1_0_0.8", "level2", "運營偶像身份的同時，學業也不能就這麼落下，再加上還有駕駛員的工作要做，我已經分身乏術了，看來，得更加依靠製作人才行啊~", "0", "0", "0", "0", "0", "cv_sk_dangyangtu_10", "0", "0"},
[4147000110] = {4147000110, 11047001, 11, 5, "15_1_0_0.6", "level3", "雖然起初不太滿意這種安排，但能由你成為我的製作人果然最棒了~充分給予每個人自由與尊重，我想成為的正是這樣的“偶像”。", "0", "0", "0", "0", "0", "cv_sk_dangyangtu_11", "0", "0"},
[4147000111] = {4147000111, 11047001, 12, 6, "0", "0", "感謝應援！", "0", "0", "0", "0", "0", "cv_sk_dangyangtu_12", "0", "0"},
[4147000112] = {4147000112, 11047001, 13, 7, "0", "0", "得好好回饋你的愛才行了~", "0", "0", "0", "0", "0", "cv_sk_dangyangtu_13", "0", "0"},
[4147000113] = {4147000113, 11047001, 14, 8, "0", "0", "偶像與駭客都能創造奇跡，儘管只憑歌聲或代碼無法辦到的事同樣還有許多，但……如果和你一起，我相信現在還遠遠沒到極限。", "0", "0", "0", "0", "0", "cv_sk_dangyangtu_14", "0", "0"},
[4147000114] = {4147000114, 11047001, 15, 9, "0", "0", "身為偶像可不能懈怠。", "0", "0", "0", "0", "0", "cv_sk_dangyangtu_15", "0", "0"},
[4147000115] = {4147000115, 11047001, 16, 10, "0", "0", "讓我聽聽，哪邊的粉絲呼聲最熱情~", "0", "0", "0", "0", "0", "cv_sk_dangyangtu_16", "0", "0"},
[4147000116] = {4147000116, 11047001, 17, 11, "0", "0", "我不會忘記這場演出的哦。", "0", "0", "0", "0", "0", "cv_sk_dangyangtu_17", "0", "0"},
[4147000117] = {4147000117, 11047001, 18, 12, "0", "0", "既然還不完美，未來就讓我們共同進步吧！", "0", "0", "0", "0", "0", "cv_sk_dangyangtu_18", "0", "0"},
[4147000118] = {4147000118, 11047001, 19, 13, "0", "0", "玩鬧過頭了嗎？得認真起來了啊。", "0", "0", "0", "0", "0", "cv_sk_dangyangtu_19", "0", "0"},
[4147000119] = {4147000119, 11047001, 20, 14, "0", "0", "事前准備還得更加充足。", "0", "0", "0", "0", "0", "cv_sk_dangyangtu_20", "0", "0"},
[4147000120] = {4147000120, 11047001, 21, 15, "0", "0", "請這位粉絲安靜點~", "0", "0", "0", "0", "0", "cv_sk_dangyangtu_21", "0", "0"},
[4147000121] = {4147000121, 11047001, 23, 16, "0", "0", "這次是新的曲子！", "0", "0", "0", "0", "0", "cv_sk_dangyangtu_23", "0", "0"},
[4147000122] = {4147000122, 11047001, 24, 17, "0", "0", "陶醉其中吧~", "0", "0", "0", "0", "0", "cv_sk_dangyangtu_24", "0", "0"},
[4147000123] = {4147000123, 11047001, 25, 18, "0", "0", "慾望與源碼，都將由我改寫。", "0", "0", "0", "0", "0", "cv_sk_dangyangtu_25", "0", "0"},
[4147000124] = {4147000124, 11047001, 26, 19, "0", "0", "唔……我還會再出現的！", "0", "0", "0", "0", "0", "cv_sk_dangyangtu_26", "0", "0"},
[4147000125] = {4147000125, 11047001, 27, 20, "0", "0", "咿呀！——以為我會這麼尖叫嗎？", "0", "0", "0", "0", "0", "cv_sk_dangyangtu_27", "0", "0"},
[4147000126] = {4147000126, 11047001, 28, 21, "0", "0", "喜歡這副身體？我也很喜歡~", "0", "0", "0", "0", "0", "cv_sk_dangyangtu_28", "0", "0"},
[4147000127] = {4147000127, 11047001, 29, 21, "0", "0", "我懂我懂，檢視偶像的身體健康狀況也是製作人的職責對吧？", "0", "0", "0", "0", "0", "cv_sk_dangyangtu_29", "0", "0"},
[4147000128] = {4147000128, 11047001, 30, 22, "0", "0", "請~", "0", "0", "0", "0", "0", "cv_sk_dangyangtu_30", "0", "0"},
[4147000129] = {4147000129, 11047001, 31, 23, "0", "0", "餘興節目嗎？", "0", "0", "0", "0", "0", "cv_sk_dangyangtu_31", "0", "0"},
[4147000130] = {4147000130, 11047001, 32, 24, "0", "0", "理所當然嘛。", "0", "0", "0", "0", "0", "cv_sk_dangyangtu_32", "0", "0"},
[4147000131] = {4147000131, 11047001, 33, 25, "0", "0", "製作人的失格啊！", "0", "0", "0", "0", "0", "cv_sk_dangyangtu_33", "0", "0"},
[4147000132] = {4147000132, 11047001, 34, 26, "0", "0", "製作人回來了啊，我又有了些新的靈感，要一起來商量下嗎？——關於如何在艾吉斯總部的會議室上舉辦一場演唱會~", "0", "0", "0", "0", "0", "cv_sk_dangyangtu_34", "0", "0"},
[4147000133] = {4147000133, 11047001, 35, 27, "0", "0", "快前往live現場吧。", "0", "0", "0", "0", "0", "cv_sk_dangyangtu_35", "0", "0"},
[4147000134] = {4147000134, 11047001, 36, 28, "0", "0", "排練時也得努力。", "0", "0", "0", "0", "0", "cv_sk_dangyangtu_36", "0", "0"},
[4147000135] = {4147000135, 11047001, 37, 29, "0", "0", "都是具有偶像潛質的孩子呢。", "0", "0", "0", "0", "0", "cv_sk_dangyangtu_37", "0", "0"},
[4147000136] = {4147000136, 11047001, 38, 30, "0", "0", "新的夥伴？", "0", "0", "0", "0", "0", "cv_sk_dangyangtu_38", "0", "0"},
[4147000137] = {4147000137, 11047001, 39, 31, "0", "0", "有新衣服嗎？", "0", "0", "0", "0", "0", "cv_sk_dangyangtu_39", "0", "0"},
[4147000138] = {4147000138, 11047001, 40, 32, "0", "0", "這個商場系統，好多漏洞。", "0", "0", "0", "0", "0", "cv_sk_dangyangtu_40", "0", "0"},
[4147000139] = {4147000139, 11047001, 41, 33, "0", "0", "而我的檔案全是虛假信息呢。", "0", "0", "0", "0", "0", "cv_sk_dangyangtu_41", "0", "0"},
[4147000140] = {4147000140, 11047001, 42, 34, "0", "0", "真用心啊。", "0", "0", "0", "0", "0", "cv_sk_dangyangtu_42", "0", "0"},
[4147000141] = {4147000141, 11047001, 43, 35, "0", "0", "小心釣魚郵件。", "0", "0", "0", "0", "0", "cv_sk_dangyangtu_43", "0", "0"},
[4147000142] = {4147000142, 11047001, 44, 36, "0", "0", "我聽到了粉絲們的呼聲。", "0", "0", "0", "0", "0", "cv_sk_dangyangtu_44", "0", "0"},
[4147000143] = {4147000143, 11047001, 45, 37, "0", "0", "加油~", "0", "0", "0", "0", "0", "cv_sk_dangyangtu_45", "0", "0"},
[4148000100] = {4148000100, 11048001, 1, 1, "0", "0", "蒼霧殘響", "ハツリバーブ", "0", "0", "0", "0", "cv_sk_lilith_sw_1", "0", "0"},
[4148000101] = {4148000101, 11048001, 2, 2, "0", "0", "好笑嗎？那就趁你的那張嘴被我撕爛前多笑一下吧。", "そんなにおかしい？　好きなだけ笑っていいのよ。その口を引き裂く前に、ね。", "0", "0", "0", "0", "cv_sk_lilith_sw_2", "0", "0"},
[4148000102] = {4148000102, 11048001, 3, 3, "0", "0", "你的臉上真是寫滿了意外，我換上泳裝在你看來是很不可思議的事情嗎？通感者。", "びっくりしたって顔ね。私の水著がそんなに意外だった？通感覚者さん。", "0", "0", "0", "0", "cv_sk_lilith_sw_3", "0", "0"},
[4148000103] = {4148000103, 11048001, 91, 4, "0", "idle", "在這裡的你不是通感者和領航，我也不是偽通感者和駕駛員……你還不明白我的意思嗎？", "ここでのあなたは通感覚者でもナビゲーターでもない。私も、疑似通感覚者でもドライバーでもない……私の言ってる意味がまだ分からないの？", "0", "0", "0", "0", "cv_sk_lilith_sw_4", "0", "idle,idle"},
[4148000104] = {4148000104, 11048001, 91, 4, "0", "idle", "我的表情很嫵媚？呵呵，也許吧。", "私が可愛い？　……ふふ、そうかもね。", "0", "0", "0", "0", "cv_sk_lilith_sw_5", "0", "idle,idle"},
[4148000105] = {4148000105, 11048001, 94, 4, "0", "idle2", "要是對我的病情沒有效果的話，等會我就把你的眼珠挖下來。", "これで治らなかったら、後で目玉を抉り出してあげるわ。", "0", "0", "0", "0", "cv_sk_lilith_sw_6", "0", "idle2,idle2"},
[4148000106] = {4148000106, 11048001, 94, 4, "0", "idle2", "真是的……史蒂芬妮博士究竟在想些什麼……竟然要我穿成這樣……", "まったく……ステファニー博士は何を考えているのかしら……こんな物を著せるなんて……", "0", "0", "0", "0", "cv_sk_lilith_sw_7", "0", "idle2,idle2"},
[4148000107] = {4148000107, 11048001, 95, 5, "14_1_0_0.8", "touch1", "別誤會了通感者……因為博士說可以抑制夏天的詛咒我才這樣做的。", "勘違いしないで、通感覚者さん……夏の呪いを抑え込めるって博士が言うから、こうしているの。", "0", "0", "0", "0", "cv_sk_lilith_sw_8", "0", "touch1,touch1"},
[4148000108] = {4148000108, 11048001, 95, 5, "14_1_0_0.8", "touch1", "“主人~想要你的專屬女僕莉莉絲和你一起留下難忘的夏日回憶嗎？”……惡，一定要這麼念嗎？", "ご主人様～♪　あなた専屬メイドのリリスと、忘れられない夏の思い出を作りませんか？　……うぇ、これ言わなきゃいけないの？", "0", "0", "0", "0", "cv_sk_lilith_sw_9", "0", "touch1,touch1"},
[4148000109] = {4148000109, 11048001, 95, 5, "14_1_0_0.8", "touch1", "“我是彆扭性格，口是心非的女僕莉莉絲，其實我的心裡超級喜歡你！！！”……哈？這臺詞是在說我嗎！？", "ひねくれ者でツンツンしてるメイドのリリスだけど、本當はあなたの事がだ～いすき！！！　……は？　これ私のセリフなの！？", "0", "0", "0", "0", "cv_sk_lilith_sw_10", "0", "touch1,touch1"},
[4148000110] = {4148000110, 11048001, 93, 5, "14_2_0_0.8", "touch_s1", "哈？", "はぁ？", "0", "0", "0", "0", "cv_sk_lilith_sw_11", "0", "touch_s1,touch_s1"},
[4148000111] = {4148000111, 11048001, 92, 5, "14_1_0_0.8", "touch2", "想看就看吧，畢竟要我和你搞好關係，如果只用簡單的肉體就能讓你滿足的話，那再好不過。", "見たければ、どうぞ。あなたと良好な関係を築くために、この體ひとつで満足してくれるのなら、楽でいいわ。", "0", "0", "0", "0", "cv_sk_lilith_sw_46", "0", "touch2,touch2"},
[4148000112] = {4148000112, 11048001, 92, 5, "14_1_0_0.8", "touch2", "你也有會露出這麼平和的表情……我第一次見。", "あなたもそんなに穏やかな表情をするのね……初めて見たわ。", "0", "0", "0", "0", "cv_sk_lilith_sw_47", "0", "touch2,touch2"},
[4148000113] = {4148000113, 11048001, 92, 5, "14_1_0_0.8", "touch2", "主人想要和我一起游泳嗎，來，把手遞給你的莉莉絲吧？……真是見鬼了。", "ご主人様、一緒に泳ぎましょうよ～。ほら、リリスの手を摑んで？　……なに今の。", "0", "0", "0", "0", "cv_sk_lilith_sw_48", "0", "touch2,touch2"},
[4148000114] = {4148000114, 11048001, 96, 5, "14_2_0_0.8", "touch_s2", "哈——", "……ふう。", "0", "0", "0", "0", "cv_sk_lilith_sw_49", "0", "touch_s2,touch_s2"},
[4148000115] = {4148000115, 11048001, 12, 6, "0", "0", "變強總歸是好事。", "強くなるのは良いことよ。", "0", "0", "0", "0", "cv_sk_lilith_sw_12", "0", "0"},
[4148000116] = {4148000116, 11048001, 13, 7, "0", "0", "會在你眼中變得更加耀眼嗎？", "より輝いて見えるかしら？", "0", "0", "0", "0", "cv_sk_lilith_sw_13", "0", "0"},
[4148000117] = {4148000117, 11048001, 14, 8, "0", "0", "錯覺嗎……為什麼會出現不存在的記憶？", "錯覚かしら……どうして存在しないはずの記憶が浮かんで來るの？", "0", "0", "0", "0", "cv_sk_lilith_sw_14", "0", "0"},
[4148000118] = {4148000118, 11048001, 15, 9, "0", "0", "感官更敏銳了，真是複雜的心情。", "感覚がより鋭敏になったみたい。複雑な気持ちよ。", "0", "0", "0", "0", "cv_sk_lilith_sw_15", "0", "0"},
[4148000119] = {4148000119, 11048001, 16, 10, "0", "0", "難得的夏日……", "貴重な夏が……", "0", "0", "0", "0", "cv_sk_lilith_sw_16", "0", "0"},
[4148000120] = {4148000120, 11048001, 17, 11, "0", "0", "趁夏天還沒結束，回去吧。", "夏が終わらない內に、戻りましょう。", "0", "0", "0", "0", "cv_sk_lilith_sw_17", "0", "0"},
[4148000121] = {4148000121, 11048001, 18, 12, "0", "0", "狀態還沒從假期中調整回來。", "休暇明けからまだ調子が戻ってないわ。", "0", "0", "0", "0", "cv_sk_lilith_sw_18", "0", "0"},
[4148000122] = {4148000122, 11048001, 19, 13, "0", "0", "我們應該做得更好。", "私達ならもっとうまくやれるわ。", "0", "0", "0", "0", "cv_sk_lilith_sw_19", "0", "0"},
[4148000123] = {4148000123, 11048001, 20, 14, "0", "0", "這份感情不管多少次都讓人不愉快。", "この感覚、何度経験しても慣れないわね。", "0", "0", "0", "0", "cv_sk_lilith_sw_20", "0", "0"},
[4148000124] = {4148000124, 11048001, 21, 15, "0", "0", "喪命於此！", "ここで終わりよ！", "0", "0", "0", "0", "cv_sk_lilith_sw_21", "0", "0"},
[4148000125] = {4148000125, 11048001, 23, 16, "0", "0", "沒用的。", "ムダよ。", "0", "0", "0", "0", "cv_sk_lilith_sw_23", "0", "0"},
[4148000126] = {4148000126, 11048001, 24, 17, "0", "0", "毀滅吧。", "滅びなさい。", "0", "0", "0", "0", "cv_sk_lilith_sw_24", "0", "0"},
[4148000127] = {4148000127, 11048001, 25, 18, "0", "0", "盛夏啊……真希望能一直持續下去……", "夏ね……ずっと夏ならいいのに……", "0", "0", "0", "0", "cv_sk_lilith_sw_25", "0", "0"},
[4148000128] = {4148000128, 11048001, 26, 19, "0", "0", "幻覺嗎……我好像看到了另一個自己……", "幻覚かしら……もうひとりの自分が見えるような……", "0", "0", "0", "0", "cv_sk_lilith_sw_26", "0", "0"},
[4148000129] = {4148000129, 11048001, 27, 20, "0", "0", "不知不覺就習慣了……真可怕。", "いつの間にか慣れちゃったわ……いやね。", "0", "0", "0", "0", "cv_sk_lilith_sw_27", "0", "0"},
[4148000130] = {4148000130, 11048001, 28, 21, "0", "0", "真是讓人心跳的距離啊……呵呵。", "ドキドキするでしょ、この距離……ふふ。", "0", "0", "0", "0", "cv_sk_lilith_sw_28", "0", "0"},
[4148000131] = {4148000131, 11048001, 29, 21, "0", "0", "你還真是擅長這件事呢……到底幫多少女孩子做了？", "こういうの本當に上手よね……一體どれだけの女の子にして來たの？", "0", "0", "0", "0", "cv_sk_lilith_sw_29", "0", "0"},
[4148000132] = {4148000132, 11048001, 30, 22, "0", "0", "又來了。", "また來たわね。", "0", "0", "0", "0", "cv_sk_lilith_sw_30", "0", "0"},
[4148000133] = {4148000133, 11048001, 31, 23, "0", "0", "“泳衣”，這算提示嗎？", "水著って、これヒントなの？", "0", "0", "0", "0", "cv_sk_lilith_sw_31", "0", "0"},
[4148000134] = {4148000134, 11048001, 32, 24, "0", "0", "理所當然。", "當然よね。", "0", "0", "0", "0", "cv_sk_lilith_sw_32", "0", "0"},
[4148000135] = {4148000135, 11048001, 33, 25, "0", "0", "真無趣。", "つまらないわ。", "0", "0", "0", "0", "cv_sk_lilith_sw_33", "0", "0"},
[4148000136] = {4148000136, 11048001, 34, 26, "0", "0", "你又遲到了通感者……大家等你很久了，說好今天要一起去海灘的吧。", "また遅刻したの、通感覚者さん……みんな待ってるわよ。今日は一緒にビーチに行くんでしょ。", "0", "0", "0", "0", "cv_sk_lilith_sw_34", "0", "0"},
[4148000137] = {4148000137, 11048001, 35, 27, "0", "0", "我們的假期真的很少。", "本當に休む暇もないわ。", "0", "0", "0", "0", "cv_sk_lilith_sw_35", "0", "0"},
[4148000138] = {4148000138, 11048001, 36, 28, "0", "0", "最後留在場上的人一定是我。", "最後に殘るのはきっとこの私よ。", "0", "0", "0", "0", "cv_sk_lilith_sw_36", "0", "0"},
[4148000139] = {4148000139, 11048001, 37, 29, "0", "0", "你是要和其他人打招呼嗎？", "他の人にも聲をかけるつもり？", "0", "0", "0", "0", "cv_sk_lilith_sw_37", "0", "0"},
[4148000140] = {4148000140, 11048001, 38, 30, "0", "0", "又要有新的孽緣了呀……", "また新しい子に手を出すつもり？", "0", "0", "0", "0", "cv_sk_lilith_sw_38", "0", "0"},
[4148000141] = {4148000141, 11048001, 39, 31, "0", "0", "買什麼", "なにを買うのかしら。", "0", "0", "0", "0", "cv_sk_lilith_sw_39", "0", "0"},
[4148000142] = {4148000142, 11048001, 40, 32, "0", "0", "一起去吧。", "行きましょうか。", "0", "0", "0", "0", "cv_sk_lilith_sw_40", "0", "0"},
[4148000143] = {4148000143, 11048001, 41, 33, "0", "0", "真是讓人懷念的呆臉。", "相変わらずの間抜け面ね。", "0", "0", "0", "0", "cv_sk_lilith_sw_41", "0", "0"},
[4148000144] = {4148000144, 11048001, 42, 34, "0", "0", "還要調整設定嗎？", "設定を調整するの？", "0", "0", "0", "0", "cv_sk_lilith_sw_42", "0", "0"},
[4148000145] = {4148000145, 11048001, 43, 35, "0", "0", "海灘的邀請券說不定落在裡面了。", "ビーチへの招待狀が來てるかもしれないわね。", "0", "0", "0", "0", "cv_sk_lilith_sw_43", "0", "0"},
[4148000146] = {4148000146, 11048001, 44, 36, "0", "0", "保持安靜。", "靜かに。", "0", "0", "0", "0", "cv_sk_lilith_sw_44", "0", "0"},
[4148000147] = {4148000147, 11048001, 45, 37, "0", "0", "嗯。", "あら。", "0", "0", "0", "0", "cv_sk_lilith_sw_45", "0", "0"},
[4149000100] = {4149000100, 11049001, 1, 1, "0", "0", "蒼霧殘響", "ハツリバーブ", "0", "0", "0", "0", "cv_sk_aertaiya_1", "0", "0"},
[4149000101] = {4149000101, 11049001, 2, 2, "0", "0", "真不想值班啊……好想睡覺，好想看動畫……", "当直したくない……寝たい、アニメ観たい……", "0", "0", "0", "0", "cv_sk_aertaiya_2", "0", "0"},
[4149000102] = {4149000102, 11049001, 3, 3, "0", "0", "沒想到我會出現在這裡吧，蜥蜴先生！哼哼，不是有人說過嗎，世間所有的重逢，都是蓄謀已久的相遇——我沒記錯吧？", "驚いたでしょ、トカゲさん！ふふ、誰かが言ってたよね、世の中の再会はすべて仕組まれた出会いだって——間違ってないよね？", "0", "0", "0", "0", "cv_sk_aertaiya_3", "0", "0"},
[4149000103] = {4149000103, 11049001, 4, 4, "0", "idle", "好困……現在是幾點……對了……我今天不用上學……", "ふあ、眠い……今何時だろう……あ、今日は学校行かなくていいんだっけ……", "0", "0", "0", "0", "cv_sk_aertaiya_4", "0", "0"},
[4149000104] = {4149000104, 11049001, 5, 4, "0", "idle", "糟糕……一不小心睡著了……我沒有流口水吧……嗚……先擦乾淨，這樣就不會被發現了……！", "やばい……うっかり寝ちゃった……よだれ、垂れてないよね……うぅ……きれいに拭かなきゃ、これでバレないよね……！", "0", "0", "0", "0", "cv_sk_aertaiya_5", "0", "0"},
[4149000105] = {4149000105, 11049001, 6, 4, "0", "idle", "待會他進來後……一定會嚇他一跳的……沒想到我會有這麼有女人味的一面吧，嘿嘿……嘿嘿嘿……蜥蜴先生？你什麼時候來的！？", "あとで彼が入ってきたら……きっとびっくりするだろうな……こんな女らしい一面があるなんてって…、ふふ……ふふふ……トカゲさん？いつからそこにいたの！？", "0", "0", "0", "0", "cv_sk_aertaiya_6", "0", "0"},
[4149000106] = {4149000106, 11049001, 7, 5, "15_1_0_0.8", "touch1", "嗚嗚嗚……為了買這件衣服，我好不容易存下來的錢都花完了……一定要讓蜥蜴先生對我刮目相看，我可不是小鬼了。", "うぅぅ……この服を買うために、頑張って貯めたお金全部使っちゃったんだ……絶対トカゲさんに見直してもらわなきゃ、私はもう子供じゃないんだから。", "0", "0", "0", "0", "cv_sk_aertaiya_7", "0", "0"},
[4149000107] = {4149000107, 11049001, 8, 5, "15_2_0_0.8", "touch2", "……你都聽見了嗎？我剛剛說的話，你全都聽見了嗎！？快忘掉！當做沒聽見，拜託你了！", "……全部聞いてたの？今言ったこと、全部聞こえてたの！？忘れて！聞いてなかったことにして、お願いだから！", "0", "0", "0", "0", "cv_sk_aertaiya_8", "0", "0"},
[4149000108] = {4149000108, 11049001, 9, 5, "15_1_0_0.8", "touch1", "你讓我等了好久啊——是工作到了現在嗎……啊……辛苦了，抱歉……", "ずっと待ってたんだからね——この時間まで仕事だったの？あ……お疲れ様、ごめんね……", "0", "0", "0", "0", "cv_sk_aertaiya_9", "0", "0"},
[4149000109] = {4149000109, 11049001, 10, 5, "15_2_0_0.8", "touch2", "既然你都看見了……我也不可能學遊戲裡的女主人公那樣，用電擊刺激你的海馬體讓你失憶……所以你就沒什麼想對我說的嗎？一句也沒有嗎？喂！", "見られちゃった以上……ゲームの女主人公みたいに、電撃で君の海馬体を刺激して記憶を消すことなんて造作もないから……何か言いたいことはないの？一言もないの？ねえ！", "0", "0", "0", "0", "cv_sk_aertaiya_10", "0", "0"},
[4149000110] = {4149000110, 11049001, 11, 5, "15_1_0_0.8", "touch1", "好看嗎……啊，謝謝，這樣一來我的努力也不算白費了……不過，想說的只有這點嗎，就沒有什麼……更讓人怦然心動的話嗎？就是類似於……動畫裡那種“月色真美”……之類的話。", "どう？……あ、ありがとう、これで私の努力も無駄じゃなかったってことだね……でも、言いたいのはそれだけ？もっと……胸がときめくような言葉はないの？アニメみたいに……「月が綺麗」とか……さ。", "0", "0", "0", "0", "cv_sk_aertaiya_11", "0", "0"},
[4149000111] = {4149000111, 11049001, 12, 6, "0", "0", "等級提升！", "レベルアップ！ ", "0", "0", "0", "0", "cv_sk_aertaiya_12", "0", "0"},
[4149000112] = {4149000112, 11049001, 13, 7, "0", "0", "覺醒吧，我沉睡的潛力！", "目覚めよ、私の眠れる力！", "0", "0", "0", "0", "cv_sk_aertaiya_13", "0", "0"},
[4149000113] = {4149000113, 11049001, 14, 8, "0", "0", "現在，我登上食物鏈的頂端了吧……開玩笑的，只是個“遊戲玩笑”而已。", "今、私は食物連鎖の頂点に立ったよ……冗談、ただの「ゲームジョーク」さ。", "0", "0", "0", "0", "cv_sk_aertaiya_14", "0", "0"},
[4149000114] = {4149000114, 11049001, 15, 9, "0", "0", "只要吃掉124個自己，我就會無敵了！", "124人の自分を食べれば、私は無敵になる！", "0", "0", "0", "0", "cv_sk_aertaiya_15", "0", "0"},
[4149000115] = {4149000115, 11049001, 16, 10, "0", "0", "你們的救世主來了！", "あなたたちの救世主が来た！ ", "0", "0", "0", "0", "cv_sk_aertaiya_16", "0", "0"},
[4149000116] = {4149000116, 11049001, 17, 11, "0", "0", "這就是由我喚來的奇跡！", "これが私が呼び起こした奇跡！", "0", "0", "0", "0", "cv_sk_aertaiya_17", "0", "0"},
[4149000117] = {4149000117, 11049001, 18, 12, "0", "0", "作為新手駕駛員，我已經表現得很好了！", "新米ドライバーとして、私、かなりよくやってるよね！", "0", "0", "0", "0", "cv_sk_aertaiya_18", "0", "0"},
[4149000118] = {4149000118, 11049001, 19, 13, "0", "0", "遍體鱗傷的我們看起來就像真正的英雄一樣！", "傷だらけの私たち、まるで本当の英雄みたい！", "0", "0", "0", "0", "cv_sk_aertaiya_19", "0", "0"},
[4149000119] = {4149000119, 11049001, 20, 14, "0", "0", "輸得太醜陋了，這可不像我們的作風！", "こんなみにくい負け方、私たちらしくないよ！", "0", "0", "0", "0", "cv_sk_aertaiya_20", "0", "0"},
[4149000120] = {4149000120, 11049001, 21, 15, "0", "0", "這下安靜了。", "これで静かになった。", "0", "0", "0", "0", "cv_sk_aertaiya_21", "0", "0"},
[4149000121] = {4149000121, 11049001, 23, 16, "0", "0", "別來礙事啦。", "邪魔しないでよ。", "0", "0", "0", "0", "cv_sk_aertaiya_22", "0", "0"},
[4149000122] = {4149000122, 11049001, 24, 17, "0", "0", "這件決勝衣服可不是為了戰鬥才穿的啦！", "この勝負服は戦うために着たんじゃないんだから！", "0", "0", "0", "0", "cv_sk_aertaiya_24", "0", "0"},
[4149000123] = {4149000123, 11049001, 26, 19, "0", "0", "這可是我最喜歡的衣服……", "お気に入りの服……なのに。", "0", "0", "0", "0", "cv_sk_aertaiya_25", "0", "0"},
[4149000124] = {4149000124, 11049001, 27, 20, "0", "0", "我可不會像動畫裡的女生那樣尖叫——反正你肯定有什麼理由吧……不可能真是走錯地方了吧？", "アニメの女の子みたいに叫んだりしないからね——どうせ理由があるんでしょ……まさか本当に間違って来たわけじゃないよね？", "0", "0", "0", "0", "cv_sk_aertaiya_27", "0", "0"},
[4149000125] = {4149000125, 11049001, 28, 21, "0", "0", "不該看的地方都被你看光了吧，“給我負起責任呀”……要是說這句話會不會太老土了？", "見ちゃいけないとこ全部見ちゃったでしょ、「責任取ってよ」……ちょっと古くさいかな？", "0", "0", "0", "0", "cv_sk_aertaiya_28", "0", "0"},
[4149000126] = {4149000126, 11049001, 29, 21, "0", "0", "對了，下次要不要一起去真正的溫泉？我對動畫裡的溫泉旅店一直都很感興趣！", "そうだ、今度本物の温泉に一緒に行かない？アニメの温泉旅館にずっと興味があったんだ！", "0", "0", "0", "0", "cv_sk_aertaiya_29", "0", "0"},
[4149000127] = {4149000127, 11049001, 30, 22, "0", "0", "嗯？", "え？ ", "0", "0", "0", "0", "cv_sk_aertaiya_30", "0", "0"},
[4149000128] = {4149000128, 11049001, 31, 23, "0", "0", "猜不出來的話就去查聲優名字吧！", "声優さんの名前を調べればわかるよ！", "0", "0", "0", "0", "cv_sk_aertaiya_31", "0", "0"},
[4149000129] = {4149000129, 11049001, 32, 24, "0", "0", "我的聲音難道不好記嗎？", "私の声、覚えにくい？", "0", "0", "0", "0", "cv_sk_aertaiya_32", "0", "0"},
[4149000130] = {4149000130, 11049001, 33, 25, "0", "0", "哼哼，在聽聲識人上，蜥蜴先生不如我呢。", "ふふ、声で人を見分けるのは、私のほうが上手いわね。", "0", "0", "0", "0", "cv_sk_aertaiya_33", "0", "0"},
[4149000131] = {4149000131, 11049001, 34, 26, "0", "0", "呼……再让我睡一会……一会就好啦……", "ぅ……もう少しだけ寢させて……ほんの少しだけ……", "0", "0", "0", "0", "cv_sk_aertaiya_34", "0", "0"},
[4149000132] = {4149000132, 11049001, 35, 27, "0", "0", "聽我說聽我說，我有一個計畫，一個最好的計畫！", "聞いて聞いて、作戦があるんだ、最高の作戦が！", "0", "0", "0", "0", "cv_sk_aertaiya_35", "0", "0"},
[4149000133] = {4149000133, 11049001, 36, 28, "0", "0", "屁股被踢痛了可不要告狀噢。", "お尻を蹴られて痛くても、文句言わないでね。", "0", "0", "0", "0", "cv_sk_aertaiya_36", "0", "0"},
[4149000134] = {4149000134, 11049001, 37, 29, "0", "0", "這麼多人……有社團嗎？有傳說中的動漫社嗎？", "こんなに人がいる……部活とかあるの？伝説のアニメ部とか？", "0", "0", "0", "0", "cv_sk_aertaiya_37", "0", "0"},
[4149000135] = {4149000135, 11049001, 38, 30, "0", "0", "女孩子一個接一個的靠過來，你真是搶手呀。", "女の子が次々に寄ってくるなんて、ほんとにモテるね。", "0", "0", "0", "0", "cv_sk_aertaiya_38", "0", "0"},
[4149000136] = {4149000136, 11049001, 39, 31, "0", "0", "我要最高配置的裝備！", "最高の装備が欲しい！ ", "0", "0", "0", "0", "cv_sk_aertaiya_39", "0", "0"},
[4149000137] = {4149000137, 11049001, 40, 32, "0", "0", "全部買下來吧！", "全部買っちゃおう！ ", "0", "0", "0", "0", "cv_sk_aertaiya_40", "0", "0"},
[4149000138] = {4149000138, 11049001, 41, 33, "0", "0", "我就知道你不一般！", "あなたはやっぱり特別だね！ ", "0", "0", "0", "0", "cv_sk_aertaiya_41", "0", "0"},
[4149000139] = {4149000139, 11049001, 42, 34, "0", "0", "全部拉滿！", "全部マックス！ ", "0", "0", "0", "0", "cv_sk_aertaiya_42", "0", "0"},
[4149000140] = {4149000140, 11049001, 43, 35, "0", "0", "一鍵領取！一鍵刪除！", "一括受け取り！一括削除！", "0", "0", "0", "0", "cv_sk_aertaiya_43", "0", "0"},
[4149000141] = {4149000141, 11049001, 44, 36, "0", "0", "Good Game.", "Good Game.", "0", "0", "0", "0", "cv_sk_aertaiya_44", "0", "0"},
[4149000142] = {4149000142, 11049001, 45, 37, "0", "0", "嘿咻！", "えいしょ！", "0", "0", "0", "0", "cv_sk_aertaiya_45", "0", "0"},
[4200100100] = {4200100100, 12001001, 1, 1, "0", "0", "蒼霧殘響～", "0", "0", "0", "0", "0", "cv_sk_jing_33", "0", "0"},
[4200100101] = {4200100101, 12001001, 2, 2, "0", "0", "領航～麻煩再給我來張床～～", "0", "0", "0", "0", "0", "cv_sk_jing_2", "0", "0"},
[4200100102] = {4200100102, 12001001, 3, 3, "0", "0", "hello～在下正是萬年吊車尾——靜·克雷蒂亞是也！", "0", "0", "0", "0", "0", "cv_sk_jing_1", "0", "0"},
[4200100103] = {4200100103, 12001001, 4, 4, "0", "idle", "唔，好睏……濫用星空魔法的副作用也太明顯了。", "うぅ、眠い……明らかに星空魔法を使い過ぎた副作用だねー、これは。", "0", "0", "0", "0", "cv_sk_jing_3", "0", "0"},
[4200100104] = {4200100104, 12001001, 5, 4, "0", "idle", "如果你也很睏，在這裡躺下就睡也可以。放心，那些魔物不敢接近我的。", "眠かったら、ここで橫になってもいいよー。大丈夫。あの魔物たちは私に近づこうとしないから。", "0", "0", "0", "0", "cv_sk_jing_4", "0", "0"},
[4200100105] = {4200100105, 12001001, 6, 5, "15_1_0_0.8", "level1", "讓我看看姐姐在幹什麼……呃，居然還沒放棄找我嗎？復興星空魔法的事交給她一個人就好了，為什麼非要找我一起。", "（魔法で遠くを見て）姉ちゃんは何してるのかなーっと……あれ、まだ私を探してんの？星空魔法の復興なんて姉ちゃんひとりでいいじゃん。どうして私まで一緒にやんなきゃいけないのー。", "0", "0", "0", "0", "cv_sk_jing_30", "0", "0"},
[4200100106] = {4200100106, 12001001, 7, 5, "15_2_0_0.8", "level2", "沒有事的話，就不要打擾我休息了。如果有事的話，那就先把委託定金獻上吧~", "用事がないなら休憩は邪魔しないでー。用事があるなら前金払いねー。", "0", "0", "0", "0", "cv_sk_jing_5", "0", "0"},
[4200100107] = {4200100107, 12001001, 8, 5, "15_1_0_0.8", "level3", "你是在小瞧我嗎？我可是掌握著星空魔法的大魔法師，人稱“靜謐的喚星者”，無詠唱就能使用高階魔法哦。", "私のこと舐めてない？これでも星空魔法をマスターした大魔法使い……人呼んで「靜謐なる星呼び」だよー？詠唱なしで高等魔法が使えるんだから。", "0", "0", "0", "0", "cv_sk_jing_31", "0", "0"},
[4200100108] = {4200100108, 12001001, 9, 5, "15_2_0_0.8", "level4", "你問我為什麼會在這種地方？別想多了，只是凡間太吵鬧了而已，要是世上只有你一個人的聲音，就像現在這樣倒還算好。", "どうしてこんな場所にいるのかって？別にいーじゃん。世の中が騒がしすぎるんだよー。今みたいに、世界であんたの聲しかしないといいんだけどなー。", "0", "0", "0", "0", "cv_sk_jing_6", "0", "0"},
[4200100109] = {4200100109, 12001001, 10, 5, "15_1_0_0.8", "level5", "看你總是為我帶來那麼多財寶，今天就免費贈送一次服務好了。說吧，想要我解決什麼魔物？還是想讓我作為護衛陪你一天？", "いつもお寶を沢山持って來てくれるから、今日は１回だけタダで動いてあげよー。何がいい？やっつけたい魔物がいる？それとも、１日護衛に著いて欲しい？", "0", "0", "0", "0", "cv_sk_jing_7", "0", "0"},
[4200100110] = {4200100110, 12001001, 11, 5, "15_2_0_0.8", "level6", "我們只是單純的合作關係……這點你沒忘吧？不過，雖說我最初是那麼說的，但現在我改變想法了。你乾脆就這樣和我住在永恆的星空中，如何？", "私達の関係はただのビジネス……だったはずだけど、考えが変わっちゃった。いっそのことこのまま私と一緒に、永遠の星空の中で暮らしてみない？", "0", "0", "0", "0", "cv_sk_jing_8", "0", "0"},
[4200100111] = {4200100111, 12001001, 12, 6, "0", "0", "leveup！哎？不是電子遊戲嗎？", "0", "0", "0", "0", "0", "cv_sk_jing_9", "0", "0"},
[4200100112] = {4200100112, 12001001, 13, 7, "0", "0", "這就是所謂喝水也能長胖嗎？", "0", "0", "0", "0", "0", "cv_sk_jing_10", "0", "0"},
[4200100113] = {4200100113, 12001001, 14, 8, "0", "0", "只有這個還請饒了我吧……比起戰鬥我更加喜歡待在家裏……但是也不能白吃你這麼久，還是稍微運動下吧～", "0", "0", "0", "0", "0", "cv_sk_jing_11", "0", "0"},
[4200100114] = {4200100114, 12001001, 15, 9, "0", "0", "噢——！體重增加了！", "0", "0", "0", "0", "0", "cv_sk_jing_12", "0", "0"},
[4200100115] = {4200100115, 12001001, 16, 10, "0", "0", "真麻煩啊……", "0", "0", "0", "0", "0", "cv_sk_jing_13", "0", "0"},
[4200100116] = {4200100116, 12001001, 17, 11, "0", "0", "除了我之外的大家辛苦啦～", "0", "0", "0", "0", "0", "cv_sk_jing_14", "0", "0"},
[4200100117] = {4200100117, 12001001, 18, 12, "0", "0", "好累——要死了——", "0", "0", "0", "0", "0", "cv_sk_jing_15", "0", "0"},
[4200100118] = {4200100118, 12001001, 19, 13, "0", "0", "床……快給我來張床……", "0", "0", "0", "0", "0", "cv_sk_jing_16", "0", "0"},
[4200100119] = {4200100119, 12001001, 20, 14, "0", "0", "這也是必然的吧，畢竟有我在呢……", "0", "0", "0", "0", "0", "cv_sk_jing_17", "0", "0"},
[4200100120] = {4200100120, 12001001, 21, 15, "0", "0", "委託完成~", "任務完了ー。", "0", "0", "0", "0", "cv_sk_jing_18", "0", "0"},
[4200100121] = {4200100121, 12001001, 23, 16, "0", "0", "看，星星掉下來了。", "見て、星が降って來るよ。", "0", "0", "0", "0", "cv_sk_jing_19", "0", "0"},
[4200100122] = {4200100122, 12001001, 22, 38, "0", "0", "不要著急。", "焦っちゃダメダメ。", "0", "0", "0", "0", "cv_sk_jing_20", "0", "0"},
[4200100123] = {4200100123, 12001001, 26, 19, "0", "0", "那我就先撤咯。", "お先に失禮しまぁす。", "0", "0", "0", "0", "cv_sk_jing_21", "0", "0"},
[4200100124] = {4200100124, 12001001, 27, 20, "0", "0", "啊——好可惜，變成這個大小之後就沒法邊吃邊洗了啊。", "0", "0", "0", "0", "0", "cv_sk_jing_23", "0", "0"},
[4200100125] = {4200100125, 12001001, 28, 21, "0", "0", "呼呼呼——要睡著了哦。", "0", "0", "0", "0", "0", "cv_sk_jing_24", "0", "0"},
[4200100126] = {4200100126, 12001001, 29, 21, "0", "0", "咕咕咕——肚子餓了哦。", "0", "0", "0", "0", "0", "cv_sk_jing_25", "0", "0"},
[4200100127] = {4200100127, 12001001, 30, 22, "0", "0", "哦～是外賣嗎？！", "0", "0", "0", "0", "0", "cv_sk_jing_26", "0", "0"},
[4200100128] = {4200100128, 12001001, 31, 23, "0", "0", "不要憑藉腰圍來判斷人品啊！", "0", "0", "0", "0", "0", "cv_sk_jing_27", "0", "0"},
[4200100129] = {4200100129, 12001001, 32, 24, "0", "0", "恭喜！遊戲通關！", "0", "0", "0", "0", "0", "cv_sk_jing_28", "0", "0"},
[4200100130] = {4200100130, 12001001, 33, 25, "0", "0", "哎呀呀，看來你猜錯了呢，作為懲罰就把你吃掉吧～", "0", "0", "0", "0", "0", "cv_sk_jing_29", "0", "0"},
[4200100131] = {4200100131, 12001001, 34, 26, "0", "0", "又來見我了嗎？這次所為何事，準備了多少報酬~？", "また私に會いに來たの？それで、どんな仕事？いくらぐらい用意して來たのかな～？", "0", "0", "0", "0", "cv_sk_jing_32", "0", "0"},
[4200100132] = {4200100132, 12001001, 35, 27, "0", "0", "幹勁十足，一口氣通關吧！", "0", "0", "0", "0", "0", "cv_sk_jing_34", "0", "0"},
[4200100133] = {4200100133, 12001001, 36, 28, "0", "0", "要來試試挑戰模式嗎？", "0", "0", "0", "0", "0", "cv_sk_jing_35", "0", "0"},
[4200100134] = {4200100134, 12001001, 37, 29, "0", "0", "戰鬥的話果然還是交給其他人好了～", "0", "0", "0", "0", "0", "cv_sk_jing_36", "0", "0"},
[4200100135] = {4200100135, 12001001, 38, 30, "0", "0", "抽卡嗎？", "0", "0", "0", "0", "0", "cv_sk_jing_37", "0", "0"},
[4200100136] = {4200100136, 12001001, 39, 31, "0", "0", "這就是所謂的裝備池吧。", "0", "0", "0", "0", "0", "cv_sk_jing_38", "0", "0"},
[4200100137] = {4200100137, 12001001, 40, 32, "0", "0", "不用出門就能買到東西呢～", "0", "0", "0", "0", "0", "cv_sk_jing_39", "0", "0"},
