[4200100139] = {4200100139, 12001001, 42, 34, "0", "0", "遊戲設置？", "0", "0", "0", "0", "0", "cv_sk_jing_41", "0", "0"},
[4200100140] = {4200100140, 12001001, 43, 35, "0", "0", "一鍵領取就行了吧。", "0", "0", "0", "0", "0", "cv_sk_jing_42", "0", "0"},
[4200100141] = {4200100141, 12001001, 44, 36, "0", "0", "不要在公屏曬卡哦。", "0", "0", "0", "0", "0", "cv_sk_jing_43", "0", "0"},
[4200100142] = {4200100142, 12001001, 45, 37, "0", "0", "我按喵～", "0", "0", "0", "0", "0", "cv_sk_jing_44", "0", "0"},
[4200200100] = {4200200100, 12002001, 1, 1, "0", "0", "蒼霧殘響！", "0", "0", "0", "0", "0", "cv_sk_shiranui_33", "0", "0"},
[4200200101] = {4200200101, 12002001, 2, 2, "0", "0", "我可不是什麼好榜樣喔～", "0", "0", "0", "0", "0", "cv_sk_shiranui_2", "0", "0"},
[4200200102] = {4200200102, 12002001, 3, 3, "0", "0", "你好，我是風林火山的不知火，聽說這裡有很多可愛的女孩子，就讓我來確認下吧。", "0", "0", "0", "0", "0", "cv_sk_shiranui_1", "0", "0"},
[4200200103] = {4200200103, 12002001, 4, 4, "0", "idle", "越是強者，就越會忌憚比自己更強的存在，而弱者往往不會那樣大驚小怪，這真是個有趣的現象。", "0", "0", "0", "0", "0", "cv_sk_shiranui_3", "0", "0"},
[4200200104] = {4200200104, 12002001, 5, 4, "0", "idle", "在我這副百尺有餘的身軀面前……領航感到的更多是害怕，還是激動呢？", "0", "0", "0", "0", "0", "cv_sk_shiranui_4", "0", "0"},
[4200200105] = {4200200105, 12002001, 6, 4, "0", "idle", "心經屋的巫女小姐總是試圖以驅邪退魔之名將我從你身邊趕走，但在我看來，那孩子分明只是想獨佔你呢。", "0", "0", "0", "0", "0", "cv_sk_shiranui_30", "0", "0"},
[4200200106] = {4200200106, 12002001, 7, 5, "15_2_0_0.8", "level2", "呼呼，終於來到了四下無人的僻靜之處，在這裡領航可不要想著向誰呼救哦，乖乖束手就擒，讓我充分吸收你的陽氣吧~", "0", "0", "0", "0", "0", "cv_sk_shiranui_31", "0", "0"},
[4200200107] = {4200200107, 12002001, 8, 5, "15_1_0_0.8", "level1", "所謂都市傳說，很多時候只是人類自己嚇自己，你看這些單純的小動物不就絲毫不懼怕我嗎？", "0", "0", "0", "0", "0", "cv_sk_shiranui_5", "0", "0"},
[4200200108] = {4200200108, 12002001, 9, 5, "15_1_0_0.8", "level1", "姐姐我啊，心臟正狂蹦亂跳著，將每一刻悸動傳向肌膚，這身薄薄的衣物都要承受不住了。可愛的領航不來感受下嗎？", "0", "0", "0", "0", "0", "cv_sk_shiranui_6", "0", "0"},
[4200200109] = {4200200109, 12002001, 10, 5, "15_1_0_0.8", "level1", "如果感到有些累了，可以坐在我的身上休息一會兒。至於是坐在手心裡、帽子上、腰間，還是更加柔軟舒適的地方，就由你來決定吧~", "0", "0", "0", "0", "0", "cv_sk_shiranui_7", "0", "0"},
[4200200110] = {4200200110, 12002001, 11, 5, "15_1_0_0.8", "level1", "漫步在一望無際的田野間，我們二人的道路好似走不到盡頭。如果能夠就這麼成為悠遠雋永的傳說，是不是也不錯呢？", "0", "0", "0", "0", "0", "cv_sk_shiranui_8", "0", "0"},
[4200200111] = {4200200111, 12002001, 12, 6, "0", "0", "變強的感覺……真不錯啊。", "0", "0", "0", "0", "0", "cv_sk_shiranui_9", "0", "0"},
[4200200112] = {4200200112, 12002001, 13, 7, "0", "0", "這樣一來就更加容易吸引到可愛的孩子了吧？", "0", "0", "0", "0", "0", "cv_sk_shiranui_10", "0", "0"},
[4200200113] = {4200200113, 12002001, 14, 8, "0", "0", "呵呵呵，沒想到你這麼在意姐姐啊。那麼接下來該如何疼愛你呢？", "0", "0", "0", "0", "0", "cv_sk_shiranui_11", "0", "0"},
[4200200114] = {4200200114, 12002001, 15, 9, "0", "0", "喝啊！哼，真是一把好弓啊。", "0", "0", "0", "0", "0", "cv_sk_shiranui_12", "0", "0"},
[4200200115] = {4200200115, 12002001, 16, 10, "0", "0", "燒盡他們吧。", "0", "0", "0", "0", "0", "cv_sk_shiranui_13", "0", "0"},
[4200200116] = {4200200116, 12002001, 17, 11, "0", "0", "怎麼樣，我很強吧？", "0", "0", "0", "0", "0", "cv_sk_shiranui_14", "0", "0"},
[4200200117] = {4200200117, 12002001, 18, 12, "0", "0", "稍微掙紮了一下嗎？不過也就這樣了。", "0", "0", "0", "0", "0", "cv_sk_shiranui_15", "0", "0"},
[4200200118] = {4200200118, 12002001, 19, 13, "0", "0", "呵呵呵，敵人也不弱啊。", "0", "0", "0", "0", "0", "cv_sk_shiranui_16", "0", "0"},
[4200200119] = {4200200119, 12002001, 20, 14, "0", "0", "無論是我還是你，都還需要再努力一些啊。", "0", "0", "0", "0", "0", "cv_sk_shiranui_17", "0", "0"},
[4200200120] = {4200200120, 12002001, 21, 15, "0", "0", "要安靜。", "0", "0", "0", "0", "0", "cv_sk_shiranui_18", "0", "0"},
[4200200121] = {4200200121, 12002001, 23, 16, "0", "0", "乖乖不要動。", "0", "0", "0", "0", "0", "cv_sk_shiranui_20", "0", "0"},
[4200200122] = {4200200122, 12002001, 24, 17, "0", "0", "別想擺脫我哦。", "0", "0", "0", "0", "0", "cv_sk_shiranui_22", "0", "0"},
[4200200123] = {4200200123, 12002001, 22, 38, "0", "0", "po~po~po~", "0", "0", "0", "0", "0", "cv_sk_shiranui_19", "0", "0"},
[4200200124] = {4200200124, 12002001, 26, 19, "0", "0", "我還會回來的~", "0", "0", "0", "0", "0", "cv_sk_shiranui_21", "0", "0"},
[4200200125] = {4200200125, 12002001, 27, 20, "0", "0", "小小的，還真是可愛呢。", "0", "0", "0", "0", "0", "cv_sk_shiranui_23", "0", "0"},
