[4200300100] = {4200300100, 12003001, 1, 1, "0", "0", "蒼霧殘響！", "0", "0", "0", "0", "0", "cv_sk_efugenia_34", "0", "0"},
[4200300101] = {4200300101, 12003001, 2, 2, "0", "0", "哈哈，你的眼光不錯！", "0", "0", "0", "0", "0", "cv_sk_efugenia_2", "0", "0"},
[4200300102] = {4200300102, 12003001, 3, 3, "0", "0", "你這個傢夥就是領航？看起來有些弱不禁風啊。哈哈，沒事，你的敵人就交給我葉芙根尼婭解決吧！", "0", "0", "0", "0", "0", "cv_sk_efugenia_1", "0", "0"},
[4200300103] = {4200300103, 12003001, 4, 4, "0", "idle", "再泡一會兒就進行接下來的鍛煉吧。今天的晨跑目標還剩十公里。", "0", "0", "0", "0", "0", "cv_sk_efugenia_3", "0", "0"},
[4200300104] = {4200300104, 12003001, 5, 4, "0", "idle", "嗯~~~~好舒服~~~冰涼的泉水刺激著緊繃的肌肉，感覺剛才運動的疲憊都煙消雲散了。", "0", "0", "0", "0", "0", "cv_sk_efugenia_4", "0", "0"},
[4200300105] = {4200300105, 12003001, 6, 4, "0", "idle", "晨練是必須的，作為駕駛員，作為隊長，我必須保證自己的身體永遠處在最佳的狀態。肌肉可是很容易就會被懶惰嚇跑的。", "0", "0", "0", "0", "0", "cv_sk_efugenia_31", "0", "0"},
[4200300106] = {4200300106, 12003001, 7, 5, "15_2_0_0.8", "level1", "每天四點起床，四點十五從基地出發開始長跑十公里，接著是二十組力量訓練然後再慢跑回基地用早餐。早餐之後？當然是繼續日常訓練啦。", "0", "0", "0", "0", "0", "cv_sk_efugenia_32", "0", "0"},
[4200300107] = {4200300107, 12003001, 8, 5, "15_1_0_0.8", "level2", "別碰我……不，不是……我的腿……抽筋了。", "0", "0", "0", "0", "0", "cv_sk_efugenia_5", "0", "0"},
[4200300108] = {4200300108, 12003001, 9, 5, "15_1_0_0.8", "level3", "這是什麼按摩的手法嗎？肌肉麻酥酥的確實很有效呢，不過力道可以再大一些。", "0", "0", "0", "0", "0", "cv_sk_efugenia_6", "0", "0"},
[4200300109] = {4200300109, 12003001, 10, 5, "15_1_0_0.8", "level4", "這裏可真是個好地方，以後訓練結束就來這裏放鬆身體吧。領航也會晨練嗎？那我們約好每天都在這裏見面吧。我們互相監督對方的鍛煉成果。", "0", "0", "0", "0", "0", "cv_sk_efugenia_7", "0", "0"},
[4200300110] = {4200300110, 12003001, 11, 5, "15_1_0_0.8", "level5", "果然，領航也有在好好鍛煉呢。以你現在的身體，已經可以承受我最初級的訓練了。來，與我一起燃燒身體吧。", "0", "0", "0", "0", "0", "cv_sk_efugenia_8", "0", "0"},
