[4201100124] = {4201100124, 12011001, 26, 19, "0", "0", "沒關係…沒關係…嗚……", "0", "0", "0", "0", "0", "cv_sk_garannken_21", "0", "0"},
[4201100125] = {4201100125, 12011001, 27, 20, "0", "0", "澡堂…讓我想起了以前的事…不，沒什麼。", "0", "0", "0", "0", "0", "cv_sk_garannken_24", "0", "0"},
[4201100126] = {4201100126, 12011001, 28, 21, "0", "0", "這時候有一本書的話就好了…嗯，推理小說之類的……", "0", "0", "0", "0", "0", "cv_sk_garannken_25", "0", "0"},
[4201100127] = {4201100127, 12011001, 29, 21, "0", "0", "還要多久？我快睡著了……不行，會感冒的。", "0", "0", "0", "0", "0", "cv_sk_garannken_26", "0", "0"},
