[4201100129] = {4201100129, 12011001, 31, 23, "0", "0", "提示是…書。", "0", "0", "0", "0", "0", "cv_sk_garannken_28", "0", "0"},
[4201100130] = {4201100130, 12011001, 32, 24, "0", "0", "…領航，這是我喜歡的書，借給你。", "0", "0", "0", "0", "0", "cv_sk_garannken_29", "0", "0"},
[4201100131] = {4201100131, 12011001, 33, 25, "0", "0", "哦…猜錯了啊。不，我沒有不高興。", "0", "0", "0", "0", "0", "cv_sk_garannken_30", "0", "0"},
[4201100132] = {4201100132, 12011001, 34, 26, "0", "0", "領航，歡迎回來…我手上的書？噢，這是《飛鳥集》，我的寶物。", "0", "0", "0", "0", "0", "cv_sk_garannken_33", "0", "0"},
[4201100133] = {4201100133, 12011001, 35, 27, "0", "0", "我能帶上喜歡的書出去嗎？", "0", "0", "0", "0", "0", "cv_sk_garannken_35", "0", "0"},
[4201100134] = {4201100134, 12011001, 36, 28, "0", "0", "“生於憂患，死於安樂”……", "0", "0", "0", "0", "0", "cv_sk_garannken_36", "0", "0"},
[4201100135] = {4201100135, 12011001, 37, 29, "0", "0", "真熱鬧……", "0", "0", "0", "0", "0", "cv_sk_garannken_37", "0", "0"},
[4201100136] = {4201100136, 12011001, 38, 30, "0", "0", "遵從我的召喚…開玩笑的。", "0", "0", "0", "0", "0", "cv_sk_garannken_38", "0", "0"},
[4201100137] = {4201100137, 12011001, 39, 31, "0", "0", "我有小白就足夠了。", "0", "0", "0", "0", "0", "cv_sk_garannken_39", "0", "0"},
[4201100138] = {4201100138, 12011001, 40, 32, "0", "0", "…書，有嗎？", "0", "0", "0", "0", "0", "cv_sk_garannken_40", "0", "0"},
[4201100139] = {4201100139, 12011001, 41, 33, "0", "0", "要好好打理自己。", "0", "0", "0", "0", "0", "cv_sk_garannken_41", "0", "0"},
[4201100140] = {4201100140, 12011001, 42, 34, "0", "0", "按喜歡的來吧。", "0", "0", "0", "0", "0", "cv_sk_garannken_42", "0", "0"},
[4201100141] = {4201100141, 12011001, 43, 35, "0", "0", "有新的郵件嗎？", "0", "0", "0", "0", "0", "cv_sk_garannken_43", "0", "0"},
[4201100142] = {4201100142, 12011001, 44, 36, "0", "0", "……好吵。", "0", "0", "0", "0", "0", "cv_sk_garannken_44", "0", "0"},
[4201100143] = {4201100143, 12011001, 45, 37, "0", "0", "嗯。", "0", "0", "0", "0", "0", "cv_sk_garannken_45", "0", "0"},
[4201300100] = {4201300100, 12013001, 1, 1, "0", "0", "蒼霧殘響。", "蒼霧殘響（ハツリバーブ）。", "0", "0", "0", "0", "cv_sk_kalian_33", "0", "0"},
[4201300101] = {4201300101, 12013001, 2, 2, "0", "0", "交給我這種候補生真的好嗎？", "候補生の私が擔當しても宜しいのですか？", "0", "0", "0", "0", "cv_sk_kalian_2", "0", "0"},
[4201300102] = {4201300102, 12013001, 3, 3, "0", "0", "終於見面了，領航。我是薩哈拉支部的候補生，卡蓮。如果不介意的話，可以讓我與您一同前往戰場嗎？", "ナビゲーター、やっとお會いできました。サハラ支部の候補生、カレンと申します。ご迷惑でなければ、戦場に同行させていただいても宜しいでしょうか？", "0", "0", "0", "0", "cv_sk_kalian_1", "0", "0"},
[4201300103] = {4201300103, 12013001, 4, 4, "0", "idle", "這就是駕駛員們平時的工作嗎……好的，我會努力的。", "ドライバーの通常業務ですか……わかりました。頑張ります。", "0", "0", "0", "0", "cv_sk_kalian_3", "0", "0"},
[4201300104] = {4201300104, 12013001, 5, 4, "0", "idle", "怎麼說呢？將幻化出的裝備穿在身上的感覺真是太奇妙了……欸？還可以去戰場測試一下嗎？！", "なんと言うか、幻化した裝備を身に付けるのは本當に不思議な感覚ですね。", "0", "0", "0", "0", "cv_sk_kalian_4", "0", "0"},
[4201300105] = {4201300105, 12013001, 6, 4, "0", "idle", "除了我之外應該還有其他候補生吧，如果見到她們的話還請多多關照一下。", "私の他にも候補生がいるのですよね。彼女たちの事も、どうぞよろしくお願いします。", "0", "0", "0", "0", "cv_sk_kalian_30", "0", "0"},
[4201300106] = {4201300106, 12013001, 7, 5, "15_1_0_0.8", "level1", "這件制服很陌生？啊，這是薩哈拉為候補生們準備的學院服。", "見たことないユニフォーム、ですか？ああ、これはサハラが候補生に用意した制服ですよ。", "0", "0", "0", "0", "cv_sk_kalian_31", "0", "0"},
[4201300107] = {4201300107, 12013001, 8, 5, "15_2_0_0.8", "level2", "嗯？正好我有事想要請教您，可以佔有您一些時間嗎？領航。", "あ、ちょうどナビゲーターにお聞きしたい事があったのです。少しお時間を頂いても宜しいですか？", "0", "0", "0", "0", "cv_sk_kalian_5", "0", "0"},
[4201300108] = {4201300108, 12013001, 9, 5, "15_2_0_0.8", "level2", "領航，我回去思考了一段時間，但還是有很多事情都弄不明白……非常抱歉，可能今後也還要拜託你了，老師。嗯，還請允許我像這樣稱呼您吧。", "ナビゲーター。しばらく考えたのですが、私には、まだまだ分からないことが沢山あるようです。お手數をおかけいたしますが、今後とも宜しくお願いします、先生。……ええ、先生とお呼びすることをお許しください。", "0", "0", "0", "0", "cv_sk_kalian_6", "0", "0"},
[4201300109] = {4201300109, 12013001, 10, 5, "15_1_0_0.8", "level1", "老師，您今天有空嗎？我整理出了一些自己這段時間收集到的記錄，想讓您幫忙看一下可以嗎？當然，如果您正在忙的話，我們改天也可以。", "先生、今日、少しお時間宜しいでしょうか？今までの記録を整理したのですが、ご覧いただけますか？もちろんお忙しいようでしたら、後日でも結構ですので。", "0", "0", "0", "0", "cv_sk_kalian_7", "0", "0"},
[4201300110] = {4201300110, 12013001, 11, 5, "15_2_0_0.8", "level2", "不知不覺已經和你相處了這麼久了啊，老師。在當駕駛員的時間裏，多虧了你的照顧我才沒有受傷。真希望分別的日子可以再晚些……我還有很多想向老師請教的東西……", "先生とはじめてお會いしてから、もうこんなに経ったんですね。先生のおかげで、私は生き延びることができたんですよ。……私、先生とお別れしたくありません。まだまだ教えていただきたいことが、沢山あるんです。", "0", "0", "0", "0", "cv_sk_kalian_8", "0", "0"},
[4201300111] = {4201300111, 12013001, 12, 6, "0", "0", "這真是……非常感謝！", "これは……本當にありがとうございます！", "0", "0", "0", "0", "cv_sk_kalian_9", "0", "0"},
[4201300112] = {4201300112, 12013001, 13, 7, "0", "0", "馳騁在戰場的感覺……真好。", "戦場を駆け抜ける感じ……素晴らしいです。", "0", "0", "0", "0", "cv_sk_kalian_10", "0", "0"},
[4201300113] = {4201300113, 12013001, 14, 8, "0", "0", "雖然這麼說有些自大，不過我感覺在你的幫助下，自己已經是個合格的駕駛員了呢。", "自惚れに聞こえるかもしれませんが、私が一人前のドライバーになれたのは、先生のお陰です。", "0", "0", "0", "0", "cv_sk_kalian_11", "0", "0"},
[4201300114] = {4201300114, 12013001, 15, 9, "0", "0", "果然，實戰中獲取的經驗才是最寶貴的。", "やはり、実戦での経験ほど貴重なものはありません。", "0", "0", "0", "0", "cv_sk_kalian_12", "0", "0"},
[4201300115] = {4201300115, 12013001, 16, 10, "0", "0", "調試完畢，準備戰鬥。", "デバッグ完了。戦闘態勢に入ります。", "0", "0", "0", "0", "cv_sk_kalian_13", "0", "0"},
[4201300116] = {4201300116, 12013001, 17, 11, "0", "0", "完勝，沒有人受傷就是最好的結果。", "完勝です！誰も怪我をせずに勝利できたことは、最高の戦果です。", "0", "0", "0", "0", "cv_sk_kalian_14", "0", "0"},
[4201300117] = {4201300117, 12013001, 18, 12, "0", "0", "任務完成，現在就返回吧，領航。", "任務完了。直ちに帰還しましょう、ナビゲーター。", "0", "0", "0", "0", "cv_sk_kalian_15", "0", "0"},
[4201300118] = {4201300118, 12013001, 19, 13, "0", "0", "略微有些遺憾嗎？不過算了，這也是寶貴的經驗。", "少し殘念、ですか？でも、これも貴重な経験ですから。", "0", "0", "0", "0", "cv_sk_kalian_16", "0", "0"},
[4201300119] = {4201300119, 12013001, 20, 14, "0", "0", "撤退…至少要活下來……", "撤退…せめて生き延びてください……", "0", "0", "0", "0", "cv_sk_kalian_17", "0", "0"},
[4201300120] = {4201300120, 12013001, 21, 15, "0", "0", "我做到了……", "やりました…！", "0", "0", "0", "0", "cv_sk_kalian_18", "0", "0"},
[4201300121] = {4201300121, 12013001, 23, 16, "0", "0", "逃不了的！", "逃がさない！", "0", "0", "0", "0", "cv_sk_kalian_20", "0", "0"},
[4201300122] = {4201300122, 12013001, 24, 17, "0", "0", "齊射！", "斉射ッ！", "0", "0", "0", "0", "cv_sk_kalian_22", "0", "0"},
[4201300123] = {4201300123, 12013001, 22, 38, "0", "0", "下一個！", "次っ！", "0", "0", "0", "0", "cv_sk_kalian_19", "0", "0"},
[4201300124] = {4201300124, 12013001, 26, 19, "0", "0", "撤退…已經來不及了嗎？", "撤退は…もう間に合わないのか……", "0", "0", "0", "0", "cv_sk_kalian_21", "0", "0"},
[4201300125] = {4201300125, 12013001, 27, 20, "0", "0", "呼~水溫正好呢，老師。", "ふぅ。いい湯加減ですよ、先生。", "0", "0", "0", "0", "cv_sk_kalian_23", "0", "0"},
[4201300126] = {4201300126, 12013001, 28, 21, "0", "0", "多瑙的浴場和薩哈拉的浴場還蠻像的嘛，讓我有種還在學校裏的感覺。", "ダニューブの浴場は、サハラのと隨分似ています。なんだか未だに學校にいるような感じですね。", "0", "0", "0", "0", "cv_sk_kalian_24", "0", "0"},
[4201300127] = {4201300127, 12013001, 29, 21, "0", "0", "好像小時候和姐姐一起洗澡時的感覺一樣呢。", "子供の頃、お姉ちゃんと一緒にお風呂に入ったのを思い出します……", "0", "0", "0", "0", "cv_sk_kalian_25", "0", "0"},
[4201300128] = {4201300128, 12013001, 30, 22, "0", "0", "老師，還請小心一些。", "先生、どうかお気をつけて。", "0", "0", "0", "0", "cv_sk_kalian_26", "0", "0"},
[4201300129] = {4201300129, 12013001, 31, 23, "0", "0", "稍微玩個小遊戲吧。", "ちょっとしたゲームですね。", "0", "0", "0", "0", "cv_sk_kalian_27", "0", "0"},
[4201300130] = {4201300130, 12013001, 32, 24, "0", "0", "果然，不愧是我的老師。", "さすが、私の先生です。", "0", "0", "0", "0", "cv_sk_kalian_28", "0", "0"},
[4201300131] = {4201300131, 12013001, 33, 25, "0", "0", "原來老師也會有出錯的時候啊。", "先生もミスをする時があるのですね。", "0", "0", "0", "0", "cv_sk_kalian_29", "0", "0"},
[4201300132] = {4201300132, 12013001, 34, 26, "0", "0", "終於等到您了，今天也有一大堆問題想要請教您呢。", "やっとお會いできました。今日も教えて頂きたいことが沢山あるのです。", "0", "0", "0", "0", "cv_sk_kalian_32", "0", "0"},
[4201300133] = {4201300133, 12013001, 35, 27, "0", "0", "戰場才是最好的教室。", "戦場こそ最高の教室です。", "0", "0", "0", "0", "cv_sk_kalian_34", "0", "0"},
[4201300134] = {4201300134, 12013001, 36, 28, "0", "0", "沒有什麼可以難倒我。", "私にとって難しいことではありません。", "0", "0", "0", "0", "cv_sk_kalian_35", "0", "0"},
[4201300135] = {4201300135, 12013001, 37, 29, "0", "0", "要確認一下點名簿嗎？", "名簿を確認しますか？", "0", "0", "0", "0", "cv_sk_kalian_36", "0", "0"},
[4201300136] = {4201300136, 12013001, 38, 30, "0", "0", "要招募新的駕駛員嗎？", "新しいドライバーを募集しますか？", "0", "0", "0", "0", "cv_sk_kalian_37", "0", "0"},
[4201300137] = {4201300137, 12013001, 39, 31, "0", "0", "要採購新的裝備嗎？", "新しい裝備を整えますか？", "0", "0", "0", "0", "cv_sk_kalian_38", "0", "0"},
[4201300138] = {4201300138, 12013001, 40, 32, "0", "0", "補充些物資吧。", "物資を補充しましょう。", "0", "0", "0", "0", "cv_sk_kalian_39", "0", "0"},
[4201300139] = {4201300139, 12013001, 41, 33, "0", "0", "確認名片。", "名刺を確認しますね。", "0", "0", "0", "0", "cv_sk_kalian_40", "0", "0"},
[4201300140] = {4201300140, 12013001, 42, 34, "0", "0", "需要變更設定嗎？", "設定を変更するのですか？", "0", "0", "0", "0", "cv_sk_kalian_41", "0", "0"},
[4201300141] = {4201300141, 12013001, 43, 35, "0", "0", "有新信件嗎？老師。", "新しいメールが來ているかもしれませんね。", "0", "0", "0", "0", "cv_sk_kalian_42", "0", "0"},
[4201300142] = {4201300142, 12013001, 44, 36, "0", "0", "其他領航都在這裡吧。", "他のナビゲーターたちはここにいると思います。", "0", "0", "0", "0", "cv_sk_kalian_43", "0", "0"},
[4201300143] = {4201300143, 12013001, 45, 37, "0", "0", "好的，老師。", "はい、先生。", "0", "0", "0", "0", "cv_sk_kalian_44", "0", "0"},
[4201600100] = {4201600100, 12016001, 1, 1, "0", "0", "蒼霧殘響。", "0", "0", "0", "0", "0", "cv_sk_saraid_33", "0", "0"},
[4201600101] = {4201600101, 12016001, 2, 2, "0", "0", "哈！這個地方真不錯，很適合開演唱會！", "0", "0", "0", "0", "0", "cv_sk_saraid_2", "0", "0"},
[4201600102] = {4201600102, 12016001, 3, 3, "0", "0", "唷吼，薩拉蒂·索尼參上！不知道領航喜歡哪種風格的音樂呢？", "0", "0", "0", "0", "0", "cv_sk_saraid_1", "0", "0"},
[4201600103] = {4201600103, 12016001, 4, 4, "0", "idle", "終於結束了，剛才的比賽驚險萬分，還好有領航你在一旁指導。", "0", "0", "0", "0", "0", "cv_sk_saraid_3", "0", "0"},
[4201600104] = {4201600104, 12016001, 5, 4, "0", "idle", "沖過終點的那一刻，我的精神保持著興奮，但身體卻感到疲憊，就像剛結束一場盛大的演唱會。", "0", "0", "0", "0", "0", "cv_sk_saraid_4", "0", "0"},
[4201600105] = {4201600105, 12016001, 6, 4, "0", "idle", "本來是艾希麗卡來做我的領航員，可是她的嗓子在演唱上用力過猛變得沙啞。但多虧了領航你在，或許你就是我命中註定是的領航員。", "0", "0", "0", "0", "0", "cv_sk_saraid_30", "0", "0"},
[4201600106] = {4201600106, 12016001, 7, 5, "15_1_0_0.8", "touch1", "賽車引擎的轟鳴就像是緊密的音符節拍，我緊踩油門，演奏出一曲名為【速度】的樂譜。從此之後，賽車將是我生命中第三重要的東西。", "0", "0", "0", "0", "0", "cv_sk_saraid_31", "0", "0"},
[4201600107] = {4201600107, 12016001, 8, 5, "15_2_0_0.8", "touch2", "想要獲得一張冠軍的簽名照嗎？", "0", "0", "0", "0", "0", "cv_sk_saraid_5", "0", "0"},
[4201600108] = {4201600108, 12016001, 9, 5, "15_1_0_0.8", "touch1", "本來參加賽車比賽就已經是我的極限了，但因為領航你在，所以今天的我沒有極限！", "0", "0", "0", "0", "0", "cv_sk_saraid_6", "0", "0"},
[4201600109] = {4201600109, 12016001, 10, 5, "15_1_0_0.8", "touch1", "雖然比賽已經結束了，但我還想再去開車兜兜風。領航你願意陪我嗎？", "0", "0", "0", "0", "0", "cv_sk_saraid_7", "0", "0"},
[4201600110] = {4201600110, 12016001, 11, 5, "15_2_0_0.8", "touch2", "今天的冠軍是一場奇跡，一場你與我共創的奇跡。在比賽之前，我從沒有想過會不會贏，我想的只是和你一起沖過終點。", "0", "0", "0", "0", "0", "cv_sk_saraid_8", "0", "0"},
[4201600111] = {4201600111, 12016001, 12, 6, "0", "0", "我將獻上更動聽的旋律。", "0", "0", "0", "0", "0", "cv_sk_saraid_9", "0", "0"},
[4201600112] = {4201600112, 12016001, 13, 7, "0", "0", "我想要給大家帶來希望，而舞臺一直會承載著我的願望！", "0", "0", "0", "0", "0", "cv_sk_saraid_10", "0", "0"},
[4201600113] = {4201600113, 12016001, 14, 8, "0", "0", "音樂裏飽含著無限的可能性。我感覺到現在我可以真正地抓住這可能性了。謝謝你，領航。你給我和我的音樂能夠飛向更遠處。", "0", "0", "0", "0", "0", "cv_sk_saraid_11", "0", "0"},
[4201600114] = {4201600114, 12016001, 15, 9, "0", "0", "掌握了新的編曲法，這就加入新的單曲裏試試吧！", "0", "0", "0", "0", "0", "cv_sk_saraid_12", "0", "0"},
[4201600115] = {4201600115, 12016001, 16, 10, "0", "0", "music！開始！", "0", "0", "0", "0", "0", "cv_sk_saraid_13", "0", "0"},
[4201600116] = {4201600116, 12016001, 17, 11, "0", "0", "感謝大家！多虧了你們今天的公演才能如此成功!", "0", "0", "0", "0", "0", "cv_sk_saraid_14", "0", "0"},
[4201600117] = {4201600117, 12016001, 18, 12, "0", "0", "就算並不是完美的演出，但也珍惜這次舞臺吧！", "0", "0", "0", "0", "0", "cv_sk_saraid_15", "0", "0"},
