[4201600126] = {4201600126, 12016001, 28, 21, "0", "0", "朦朧的蒸汽，溫暖的漣漪…仿佛在演奏和我截然不同風格的音樂。", "0", "0", "0", "0", "0", "cv_sk_saraid_24", "0", "0"},
