[4201600130] = {4201600130, 12016001, 32, 24, "0", "0", "領航不愧是我的頭號粉絲，好開心~", "0", "0", "0", "0", "0", "cv_sk_saraid_28", "0", "0"},
[4201600131] = {4201600131, 12016001, 33, 25, "0", "0", "一定會讓你記住我的！這份心情，融入音樂中。", "0", "0", "0", "0", "0", "cv_sk_saraid_29", "0", "0"},
