[4201600143] = {4201600143, 12016001, 45, 37, "0", "0", "哇喔！", "0", "0", "0", "0", "0", "cv_sk_saraid_44", "0", "0"},
[4201700100] = {4201700100, 12017001, 1, 1, "0", "0", "蒼霧殘響~", "蒼霧殘響（ハツリバーブ）！", "0", "0", "0", "0", "cv_sk_lin_sw_33", "0", "0"},
[4201700101] = {4201700101, 12017001, 2, 2, "0", "0", "久等了！——鈴的超天才模式已經準備就緒了！實驗開始……誒？你問平時是什麼狀態？——那當然是天才模式啦？！", "お待たせー！鈴、超天才モードの準備オッケー！実験を開始するよー！……え、普段はどんなモード？當然、天才モードだけど？", "0", "0", "0", "0", "cv_sk_lin_sw_1", "0", "0"},
[4201700102] = {4201700102, 12017001, 3, 3, "0", "0", "哇，我把太陽傘一起帶到這裏可以嗎？水之狐丸也過來這邊吧~", "うわぁ！ここにパラソル差しちゃっていい？きつね丸たちもこっちにおいでー！", "0", "0", "0", "0", "cv_sk_lin_sw_2", "0", "0"},
[4201700103] = {4201700103, 12017001, 91, 4, "0", "idle", "沒想到我們真的到達了這裏呢，領航。對我來說這真是最好的結局了……", "あたしたち、本當にここに來れたんだね、ナビゲーター。あたしにとって、本當に最高の結末だよ……", "0", "0", "0", "0", "cv_sk_lin_sw_3", "0", "0"},
[4201700104] = {4201700104, 12017001, 91, 4, "0", "idle", "陽光稍微有點晃眼呢……暈乎乎的、我現在就好像在做夢一樣……中暑？……也許是吧。", "日差しがちょっと眩しいな～。クラクラして、まるで夢を見てるみたい……熱中症？……かもね。", "0", "0", "0", "0", "cv_sk_lin_sw_4", "0", "0"},
[4201700105] = {4201700105, 12017001, 94, 4, "0", "idle2", "呼啊，陽光真舒服，好想在沙灘上好好睡一覺——防曬霜？嗯、嗯？塗上就好了吧！", "ふわー、日差しが気持ちいい～。砂浜でゆっくり寢たいなぁーー。日焼け止め？えーと、うん？塗ればいいの？", "0", "0", "0", "0", "cv_sk_lin_sw_30", "0", "0"},
[4201700106] = {4201700106, 12017001, 94, 5, "0", "idle2", "明年還要來這裏！", "來年もここに來ようね！", "0", "0", "0", "0", "cv_sk_lin_sw_31", "0", "0"},
[4201700107] = {4201700107, 12017001, 93, 5, "14_》_0_0.8", "touch_s1", "下水咯！領航衣服給你給你，幫我拿一下！", "海だよ！ナビゲーター、あたしの服持っててぇ！", "0", "0", "0", "0", "cv_sk_lin_sw_5", "0", "0"},
[4201700108] = {4201700108, 12017001, 96, 5, "14_》_0_0.8", "touch_s2", "擔心我著涼？嗯……那就先穿上衣服吧。不過哦，我是不會感冒的……從來沒有過哦。", "體が冷えるのが心配？うーん……じゃあとりあえず服著よっかな。でもね、あたしは風邪ひかないんだ！今まで一度もひいたことないんだよ！", "0", "0", "0", "0", "cv_sk_lin_sw_6", "0", "0"},
[4201700109] = {4201700109, 12017001, 92, 5, "14_》_0_0.8", "touch1", "做個約定吧，下次也要帶我來這裏、和我一起……", "約束、またここに、あたしをつれてきてね……", "0", "0", "0", "0", "cv_sk_lin_sw_7", "0", "0"},
[4201700110] = {4201700110, 12017001, 92, 5, "14_》_0_0.8", "touch1", "怎麼了？一直盯著我看？哼哼……你不會在等我邀請你吧？那就、一起來吧？", "どうしたの？あたしのことじっと見て？えへへ…もしかしてあたしから誘われるのを待ってたの？じゃあ、一緒にいこー！", "0", "0", "0", "0", "cv_sk_lin_sw_8", "0", "0"},
[4201700111] = {4201700111, 12017001, 95, 5, "14_》_0_0.8", "touch2", "領航聽我說，鈴為這個夏天準備了兩套泳裝哦……已經猜到了？誒？為什麼、為什麼？領航好厲害！", "ナビゲーター、聞いて聞いて、あたしこの夏のために、水著を二著も用意したんだー！……予想通りだって？え？どうしてどうして？ナビゲーターすっごーい！", "0", "0", "0", "0", "cv_sk_lin_sw_46", "0", "0"},
[4201700112] = {4201700112, 12017001, 95, 5, "14_》_0_0.8", "touch2", "領航~~不要在這裏一個人看著了，一起來吧？難道說！領航不會游泳嗎？鈴可以教你哦！", "ナビゲーター！そんなところで見てないで、一緒に行こうよ！あ、もしかしてナビゲーター泳げないの？それならあたしが教えてあげるよ！", "0", "0", "0", "0", "cv_sk_lin_sw_47", "0", "0"},
[4201700113] = {4201700113, 12017001, 12, 6, "0", "0", "夏日力提升了。", "サマーパワーレベルアァァップッ！", "0", "0", "0", "0", "cv_sk_lin_sw_9", "0", "0"},
[4201700114] = {4201700114, 12017001, 13, 7, "0", "0", "哦！鼓動的泳裝力量充斥著我的全身。", "おおぉ！水著パワーがみなぎってきたぁ！", "0", "0", "0", "0", "cv_sk_lin_sw_10", "0", "0"},
[4201700115] = {4201700115, 12017001, 14, 8, "0", "0", "這就是我的極限了？哼哼，天才是不會停下自己的腳步的，極限就是用來超越的！", "これがあたしの限界？……ふふん、天才に不可能はないんだよ。限界は超えるものだもんね！", "0", "0", "0", "0", "cv_sk_lin_sw_11", "0", "0"},
[4201700116] = {4201700116, 12017001, 15, 9, "0", "0", "知識的積累也很重要呢……但是呢，我討厭看書！！！", "勉強しなくちゃいけないことはいっぱいあるけど……本は嫌いなの！", "0", "0", "0", "0", "cv_sk_lin_sw_12", "0", "0"},
[4201700117] = {4201700117, 12017001, 16, 10, "0", "0", "天才登場，大家就退到我身後吧，我會保護你們的！", "天才様のお出ましだよー！あたしが守るから、みんな後ろに下がって！", "0", "0", "0", "0", "cv_sk_lin_sw_13", "0", "0"},
[4201700118] = {4201700118, 12017001, 17, 11, "0", "0", "實驗成功。作戰完美執行。不愧是超天才的我！", "実験成功！完璧な作戦だったね。さすがあたし、超天才！", "0", "0", "0", "0", "cv_sk_lin_sw_14", "0", "0"},
[4201700119] = {4201700119, 12017001, 18, 12, "0", "0", "預料之中的損失，我已經幫你把下一次的行動路線規劃好了，重整旗鼓吧！", "これくらい想定內だよ。次の作戦も準備できてるから、切り替えていこー！", "0", "0", "0", "0", "cv_sk_lin_sw_15", "0", "0"},
[4201700120] = {4201700120, 12017001, 19, 13, "0", "0", "呃嗯嗯……事態還沒脫離我們的掌控，領航不要放棄啊！", "ぐぬぬ……もっとうまくできるはずだよ。ナビゲーター、がんばろー！", "0", "0", "0", "0", "cv_sk_lin_sw_16", "0", "0"},
[4201700121] = {4201700121, 12017001, 20, 14, "0", "0", "嗚……看來我所預設的未來還不夠充分。", "うぅ……あたしの読みが甘かったかぁ……", "0", "0", "0", "0", "cv_sk_lin_sw_17", "0", "0"},
[4201700122] = {4201700122, 12017001, 21, 15, "0", "0", "哎嘿，一擊必殺！", "えっへん、一撃必殺！", "0", "0", "0", "0", "cv_sk_lin_sw_18", "0", "0"},
[4201700123] = {4201700123, 12017001, 23, 16, "0", "0", "嘿！", "ほいっ！", "0", "0", "0", "0", "cv_sk_lin_sw_19", "0", "0"},
[4201700124] = {4201700124, 12017001, 24, 17, "0", "0", "這就是展現天才實力的最佳時機！", "天才の実力をみせる時だぁー！", "0", "0", "0", "0", "cv_sk_lin_sw_21", "0", "0"},
[4201700125] = {4201700125, 12017001, 25, 18, "0", "0", "夏日！泳裝！超天才的概念能量在此時溢滿而出。盛夏的實驗場沒有退路，這是只有親身體驗才能明白的水之研究派對！", "夏！そして水著！超天才のエネルギーが溢れ出ているっ！真夏の実験場に出口なし！これは體験してみないとわからない水の実験パーティーだー！", "0", "0", "0", "0", "cv_sk_lin_sw_22", "0", "0"},
[4201700126] = {4201700126, 12017001, 22, 38, "0", "0", "找到了！", "発見っ！", "0", "0", "0", "0", "cv_sk_lin_sw_45", "0", "0"},
[4201700127] = {4201700127, 12017001, 26, 19, "0", "0", "狐丸，啟動緊急撤退裝置……", "きつね丸、緊急脫出裝置を……", "0", "0", "0", "0", "cv_sk_lin_sw_20", "0", "0"},
[4201700128] = {4201700128, 12017001, 27, 20, "0", "0", "為什麼游泳之後還要洗澡？？", "泳いだあとにお風呂入るのおかしくなーい？", "0", "0", "0", "0", "cv_sk_lin_sw_23", "0", "0"},
[4201700129] = {4201700129, 12017001, 28, 21, "0", "0", "誒？澡堂裏竟然有橡膠鴨子！", "あ、お風呂にアヒルさんがいるー！", "0", "0", "0", "0", "cv_sk_lin_sw_24", "0", "0"},
[4201700130] = {4201700130, 12017001, 29, 21, "0", "0", "呼~哦——我打算開發一個能一直冒泡的裝置！", "ふぅうぅ……ジャグジーもほしいなぁ……", "0", "0", "0", "0", "cv_sk_lin_sw_25", "0", "0"},
[4201700131] = {4201700131, 12017001, 30, 22, "0", "0", "領航？！你、你也一起來嗎。", "ナビゲーター！い、一緒に行くか？", "0", "0", "0", "0", "cv_sk_lin_sw_26", "0", "0"},
[4201700132] = {4201700132, 12017001, 31, 23, "0", "0", "哇嗚嗚，被太陽曬的地方有點痛，應該抹防曬霜的……", "あああ……日焼けしすぎてちょっと痛いぃー。オイル塗るの忘れてたぁ……", "0", "0", "0", "0", "cv_sk_lin_sw_27", "0", "0"},
[4201700133] = {4201700133, 12017001, 32, 24, "0", "0", "聽到聲音就知道了吧？就是本天才哦！", "天才の聲を間違えるはずないよねー！", "0", "0", "0", "0", "cv_sk_lin_sw_28", "0", "0"},
[4201700134] = {4201700134, 12017001, 33, 25, "0", "0", "欸……？你把我弄疼啦！領航是笨蛋！", "ちょ、ちょっと、痛いんだけどー！ナビゲーターのバカッ！", "0", "0", "0", "0", "cv_sk_lin_sw_29", "0", "0"},
[4201700135] = {4201700135, 12017001, 34, 26, "0", "0", "歡迎回來，我們馬上就要開party了！燒烤party！", "おかえりー！もうすぐパーティーがはじまるよー！焼肉パーティー！", "0", "0", "0", "0", "cv_sk_lin_sw_32", "0", "0"},
[4201700136] = {4201700136, 12017001, 35, 27, "0", "0", "趕緊解決戰鬥之後來游泳吧！", "さっさと片付けて泳ぎにいこ！", "0", "0", "0", "0", "cv_sk_lin_sw_34", "0", "0"},
[4201700137] = {4201700137, 12017001, 36, 28, "0", "0", "比游泳的話我可不會輸哦！", "泳ぎなら負けないもんね！", "0", "0", "0", "0", "cv_sk_lin_sw_35", "0", "0"},
[4201700138] = {4201700138, 12017001, 37, 29, "0", "0", "我給你們帶了伴手禮哦~", "お土産持ってきたよー！", "0", "0", "0", "0", "cv_sk_lin_sw_36", "0", "0"},
[4201700139] = {4201700139, 12017001, 38, 30, "0", "0", "大家為什麼都不出來玩？", "みんな遊ばないの？", "0", "0", "0", "0", "cv_sk_lin_sw_37", "0", "0"},
[4201700140] = {4201700140, 12017001, 39, 31, "0", "0", "給狐丸也配個救生圈……啊，好像能飛欸？", "きつね丸にも浮き輪を……あ、飛べるからいらないか。", "0", "0", "0", "0", "cv_sk_lin_sw_38", "0", "0"},
[4201700141] = {4201700141, 12017001, 40, 32, "0", "0", "我要防曬霜！領航幫我抹背上！", "日焼け止め買ったんだー！ナビゲーター、背中に塗って塗ってー！", "0", "0", "0", "0", "cv_sk_lin_sw_39", "0", "0"},
[4201700142] = {4201700142, 12017001, 41, 33, "0", "0", "領航你看，我發現你的照片了！", "ナビゲーターの寫真、発見！", "0", "0", "0", "0", "cv_sk_lin_sw_40", "0", "0"},
[4201700143] = {4201700143, 12017001, 42, 34, "0", "0", "需要本天才幫你嗎？", "天才が助けてあげよっか？", "0", "0", "0", "0", "cv_sk_lin_sw_41", "0", "0"},
[4201700144] = {4201700144, 12017001, 43, 35, "0", "0", "有信件了嗎？", "メールが來たのー？", "0", "0", "0", "0", "cv_sk_lin_sw_42", "0", "0"},
[4201700145] = {4201700145, 12017001, 44, 36, "0", "0", "喂~有人線上嗎？", "もしもーし、誰かいるー？", "0", "0", "0", "0", "cv_sk_lin_sw_43", "0", "0"},
[4201700146] = {4201700146, 12017001, 45, 37, "0", "0", "這是什麼？", "なにこれ？", "0", "0", "0", "0", "cv_sk_lin_sw_44", "0", "0"},
[4201800100] = {4201800100, 12018001, 1, 1, "0", "0", "蒼霧殘響", "0", "0", "0", "0", "0", "cv_sk_xhixha_1", "0", "0"},
[4201800101] = {4201800101, 12018001, 2, 2, "0", "0", "全部交給我就好~", "0", "0", "0", "0", "0", "cv_sk_xhixha_2", "0", "0"},
[4201800102] = {4201800102, 12018001, 3, 3, "0", "0", "珀因雷德首席橋梁設計師——希夏報道！不介意的話，就讓我用這副巨大身軀承載你的意志，成為架向未來之橋吧~", "0", "0", "0", "0", "0", "cv_sk_xhixha_3", "0", "0"},
[4201800103] = {4201800103, 12018001, 91, 4, "0", "idle", "……所以，我的AVG外觀是以太空棧橋為靈感原型設計的，仔細看就能發現，這種造型正適合於無重力環境對吧？", "0", "0", "0", "0", "0", "cv_sk_xhixha_4", "0", "0"},
[4201800104] = {4201800104, 12018001, 91, 4, "0", "idle", "喂喂領航你有在聽嗎……我的講解就這麼無趣？那要不，我們來聊些你更感興趣的事好了，比如……我的三圍數據？嘿嘿開個玩笑~", "0", "0", "0", "0", "0", "cv_sk_xhixha_5", "0", "0"},
[4201800105] = {4201800105, 12018001, 94, 4, "0", "idle2", "怎麼又沉默不語了……有什麼想說的就說出來嘛，在我故鄉，人們就是因缺乏交流而導致了些問題，只要能把話好好說出來，我相信一切都會變好。", "0", "0", "0", "0", "0", "cv_sk_xhixha_6", "0", "0"},
[4201800106] = {4201800106, 12018001, 94, 4, "0", "idle2", "領航……是不是對我著迷了？不用解釋哦，看你這副眼神就能明白了。真是沒辦法啊，都怪我太具有誘惑力了，就讓我好好負起責任滿足你的期待吧~", "0", "0", "0", "0", "0", "cv_sk_xhixha_7", "0", "0"},
[4201800107] = {4201800107, 12018001, 93, 5, "14_》_0_0.8", "touch_s1", "嗯哼？", "0", "0", "0", "0", "0", "cv_sk_xhixha_46", "0", "0"},
[4201800108] = {4201800108, 12018001, 96, 5, "14_》_0_0.8", "touch_s2", "嗯？", "0", "0", "0", "0", "0", "cv_sk_xhixha_47", "0", "0"},
[4201800109] = {4201800109, 12018001, 92, 5, "14_》_0_0.8", "touch1", "不行不行！不要那麼急啦。人與人之間的相處和建築工程是一樣的，都需要耐心！等到夜再深點，我們再進一步做該做的事吧？", "0", "0", "0", "0", "0", "cv_sk_xhixha_8", "0", "0"},
[4201800110] = {4201800110, 12018001, 92, 5, "14_》_0_0.8", "touch1", "沒錯，多多鍛煉就是我的秘訣，這樣才能充分吸收營養。海因要是能夠聽進勸，說不定現在也擁有迷人的好身材了呢~", "0", "0", "0", "0", "0", "cv_sk_xhixha_9", "0", "0"},
[4201800111] = {4201800111, 12018001, 92, 5, "14_》_0_0.8", "touch1", "怎麼啦？", "0", "0", "0", "0", "0", "cv_sk_xhixha_48", "0", "0"},
[4201800112] = {4201800112, 12018001, 95, 5, "14_》_0_0.8", "touch2", "雖然明白你的心情，但也要注意留些精力哦，明天我們還得早起迎接新一天的工作呢。既然每天都能在一起，我們還是把快樂均等地分到每個夜晚吧~", "0", "0", "0", "0", "0", "cv_sk_xhixha_10", "0", "0"},
[4201800113] = {4201800113, 12018001, 95, 5, "14_》_0_0.8", "touch2", "通感會讓彼此的情感飛向對方，所以如果在不安時進行通感，就會造成雙倍的不安。但現在完全沒關係呢，現在我們只會收穫雙倍的快樂~", "0", "0", "0", "0", "0", "cv_sk_xhixha_11", "0", "0"},
[4201800114] = {4201800114, 12018001, 95, 5, "14_》_0_0.8", "touch2", "嗚哇哇哇好癢！", "0", "0", "0", "0", "0", "cv_sk_xhixha_49", "0", "0"},
