[4202000101] = {4202000101, 12020001, 2, 2, "0", "0", "嘿咻！…誒？只是待在這裏嗎…我明白了……", "0", "0", "0", "0", "0", "cv_sk_flovilla_2", "0", "0"},
[4202000102] = {4202000102, 12020001, 3, 3, "0", "0", "嗚哇哇，你原來是領航嗎？我是弗洛維拉，之後就麻煩你帶路咯~", "0", "0", "0", "0", "0", "cv_sk_flovilla_1", "0", "0"},
[4202000103] = {4202000103, 12020001, 4, 4, "0", "idle", "這裏…還有這裏…嗯，決定好了！領航，我已經規劃好節假日要去的地方了，你要來嗎？", "0", "0", "0", "0", "0", "cv_sk_flovilla_3", "0", "0"},
[4202000104] = {4202000104, 12020001, 5, 4, "0", "idle", "宇宙航行時總會遇到各種難題,燃料不足、導航系統失靈之類的；不過我總會有辦法解決它們，我很了不起吧！", "0", "0", "0", "0", "0", "cv_sk_flovilla_4", "0", "0"},
[4202000105] = {4202000105, 12020001, 6, 4, "0", "idle", "唉…現在想起來還是很可怕啊，密托希瓦她們一瞬間就被拍飛了。那個大家夥，真是個不折不扣的怪物呀。", "0", "0", "0", "0", "0", "cv_sk_flovilla_31", "0", "0"},
[4202000106] = {4202000106, 12020001, 7, 5, "15_1_0_0.8", "level1", "為什麼要旅行？因為宇宙就在那裏！咳咳，當然是因為我喜歡旅行啦，想要一直旅行，死在旅行的路上；死了以後也要繼續我的旅行，我的這份心情，你能明白嗎？", "0", "0", "0", "0", "0", "cv_sk_flovilla_32", "0", "0"},
[4202000107] = {4202000107, 12020001, 8, 5, "15_2_0_0.8", "level2", "領航，就算你不停地摸我，我也不會給你零食的。", "0", "0", "0", "0", "0", "cv_sk_flovilla_5", "0", "0"},
[4202000108] = {4202000108, 12020001, 9, 5, "15_1_0_0.8", "level1", "宇宙裏存在著各種各樣的外星人呢，真的很有趣。誒，我也是外星人？這個…的確呢……", "0", "0", "0", "0", "0", "cv_sk_flovilla_6", "0", "0"},
[4202000109] = {4202000109, 12020001, 10, 5, "15_1_0_0.8", "level1", "領航，我們去旅行吧！丟下所有煩心的、讓人不快樂的事情，來一場只有你和我的旅行，怎麼樣？", "0", "0", "0", "0", "0", "cv_sk_flovilla_7", "0", "0"},
[4202000110] = {4202000110, 12020001, 11, 5, "15_2_0_0.8", "level2", "如你所瞭解的那樣…真正的我已經死了；現在的我，說不定只是一道思念的幻影。即便如此，你也願意與我踏上旅途嗎？這樣的話…或許你就是我的“終點”呢。", "0", "0", "0", "0", "0", "cv_sk_flovilla_8", "0", "0"},
[4202000111] = {4202000111, 12020001, 12, 6, "0", "0", "變強後肚子餓了呢~", "0", "0", "0", "0", "0", "cv_sk_flovilla_9", "0", "0"},
[4202000112] = {4202000112, 12020001, 13, 7, "0", "0", "設備升級！這下就無敵了吧？", "0", "0", "0", "0", "0", "cv_sk_flovilla_10", "0", "0"},
[4202000113] = {4202000113, 12020001, 14, 8, "0", "0", "地球上的力量，真是不可思議啊。嗯，這樣一來，大概連黑洞的視界也抓不住我了吧！下次…遇到那個大家夥的時候，不會再輸了！", "0", "0", "0", "0", "0", "cv_sk_flovilla_11", "0", "0"},
