[4202000133] = {4202000133, 12020001, 34, 26, "0", "0", "領航！？你怎麼來了？…我絕對沒有偷偷溜出去的打算哦！", "0", "0", "0", "0", "0", "cv_sk_flovilla_33", "0", "0"},
[4202000134] = {4202000134, 12020001, 35, 27, "0", "0", "整頓出發，開始我們的征程吧！", "0", "0", "0", "0", "0", "cv_sk_flovilla_35", "0", "0"},
[4202000135] = {4202000135, 12020001, 36, 28, "0", "0", "“精益求精”，對吧？", "0", "0", "0", "0", "0", "cv_sk_flovilla_36", "0", "0"},
[4202000136] = {4202000136, 12020001, 37, 29, "0", "0", "嗨，我是，宇宙人！", "0", "0", "0", "0", "0", "cv_sk_flovilla_37", "0", "0"},
[4202000137] = {4202000137, 12020001, 38, 30, "0", "0", "夥伴可是很重要的！", "0", "0", "0", "0", "0", "cv_sk_flovilla_38", "0", "0"},
[4202000138] = {4202000138, 12020001, 39, 31, "0", "0", "實力不足，用裝備來彌補！", "0", "0", "0", "0", "0", "cv_sk_flovilla_39", "0", "0"},
[4202000139] = {4202000139, 12020001, 40, 32, "0", "0", "買些飯後甜點吧？", "0", "0", "0", "0", "0", "cv_sk_flovilla_40", "0", "0"},
[4202000140] = {4202000140, 12020001, 41, 33, "0", "0", "和本人不太一樣！", "0", "0", "0", "0", "0", "cv_sk_flovilla_41", "0", "0"},
[4202000141] = {4202000141, 12020001, 42, 34, "0", "0", "一鍵設置在哪？", "0", "0", "0", "0", "0", "cv_sk_flovilla_42", "0", "0"},
[4202000142] = {4202000142, 12020001, 43, 35, "0", "0", "不要的郵票請給我~", "0", "0", "0", "0", "0", "cv_sk_flovilla_43", "0", "0"},
[4202000143] = {4202000143, 12020001, 44, 36, "0", "0", "一起分享見聞吧~", "0", "0", "0", "0", "0", "cv_sk_flovilla_44", "0", "0"},
[4202000144] = {4202000144, 12020001, 45, 37, "0", "0", "不要亂碰哦", "0", "0", "0", "0", "0", "cv_sk_flovilla_45", "0", "0"},
[4202100100] = {4202100100, 12021001, 1, 1, "0", "0", "蒼霧殘響", "0", "0", "0", "0", "0", "cv_sk_shaoyin_1", "0", "0"},
[4202100101] = {4202100101, 12021001, 2, 2, "0", "0", "承蒙抬愛。", "0", "0", "0", "0", "0", "cv_sk_shaoyin_2", "0", "0"},
[4202100102] = {4202100102, 12021001, 3, 3, "0", "0", "小女子名為韶音，可輔以排兵佈陣，出謀劃策。願共事愉悅。", "0", "0", "0", "0", "0", "cv_sk_shaoyin_3", "0", "0"},
[4202100103] = {4202100103, 12021001, 4, 4, "0", "idle", "年年歲歲，歲歲年年，又到了舊去新來的時候，今年可是小女子的本命年呢。", "年年歳歳花相似たり、歳歳年年人同じからず。また、古きものが去り、新しきものが來る時期になりましたね。…今年は、私めの「本命年」なんです。", "0", "0", "0", "0", "cv_sk_shaoyin_4", "0", "0"},
[4202100104] = {4202100104, 12021001, 5, 4, "0", "idle", "不知何時開始，這辭舊迎新的日子愈發冷清，領航可有何頭緒？", "いつからでしょうか…この時期になると、なぜか寂しく感じるのです。……ナビゲーター様は、何か心當たりはありませんか？", "0", "0", "0", "0", "cv_sk_shaoyin_5", "0", "0"},
[4202100105] = {4202100105, 12021001, 6, 4, "0", "idle", "梅花、落雪還有領航，今年過得倒還算是熱鬧。", "梅の花と雪、そしてナビゲーター様がそばに……今年は、賑やかな一年を過ごせた気がします。", "0", "0", "0", "0", "cv_sk_shaoyin_6", "0", "0"},
[4202100106] = {4202100106, 12021001, 7, 5, "15_1_0_0.8", "touch1", "學宮的大部分人，此刻都回到家中與各自的親人相聚。我也想回去見一見父母，但綜合考量了行程，花費以及“煩心事”之後，今年還是就暫留這裏吧。", "學宮の生徒たちは、ほとんどが家族に會うため帰省していますね。私めも両親に會いたいですが、日程や費用…あと「悩み事」を考慮して、今年はここに殘ることにしました。", "0", "0", "0", "0", "cv_sk_shaoyin_7", "0", "0"},
[4202100107] = {4202100107, 12021001, 8, 5, "15_2_0_0.8", "touch2", "坦誠相待既是信任，領航可不能肆意輕薄……等天色暗下後再說。", "互いに正直であることは一種の信頼ですが、くれぐれも軽薄な行動はしないように…。…日が暮れたら、また話しましょう。", "0", "0", "0", "0", "cv_sk_shaoyin_8", "0", "0"},
[4202100108] = {4202100108, 12021001, 9, 5, "15_2_0_0.8", "touch2", "我這身上的佩飾靈感可是取自【八門金鎖陣法】。不知道領航能否參得透其中的奧妙，找到生門破陣。", "この身に著けているアクセサリーは「八門金鎖の陣」をイメージしたものです。ナビゲーター様は、これに秘められた極意を理解し、陣を破る「生門」を見つけ出せるでしょうか。", "0", "0", "0", "0", "cv_sk_shaoyin_9", "0", "0"},
[4202100109] = {4202100109, 12021001, 10, 5, "15_3_0_0.8", "touch3", "領航竟也懂書法？我都忘了，你也是九州出身。那我來考考你，你看我這寫的是什麼字？", "ナビゲーター様も、書道を嗜むのですか？そういえば、ナビゲーター様も九州の出身でしたよね。では、問題です。私めが書いたこの字は、何の字でしょうか？", "0", "0", "0", "0", "cv_sk_shaoyin_10", "0", "0"},
[4202100110] = {4202100110, 12021001, 11, 5, "15_3_0_0.8", "touch3", "啊~不要，那裏……不行~……領航你，真是的毛筆可不是……玩具。……剛才的感覺，我會記住一輩子。", "きゃっ、いや……そこは、ダメです……ナビゲーター様……筆はおもちゃではありません。……さっきのこと、一生忘れませんから。", "0", "0", "0", "0", "cv_sk_shaoyin_11", "0", "0"},
[4202100111] = {4202100111, 12021001, 12, 6, "0", "0", "善矣。", "0", "0", "0", "0", "0", "cv_sk_shaoyin_12", "0", "0"},
[4202100112] = {4202100112, 12021001, 13, 7, "0", "0", "此般垂青，定不辜負。", "0", "0", "0", "0", "0", "cv_sk_shaoyin_13", "0", "0"},
[4202100113] = {4202100113, 12021001, 14, 8, "0", "0", "……領航，誇誇我好嗎？", "0", "0", "0", "0", "0", "cv_sk_shaoyin_14", "0", "0"},
[4202100114] = {4202100114, 12021001, 15, 9, "0", "0", "利器，然工事。", "0", "0", "0", "0", "0", "cv_sk_shaoyin_15", "0", "0"},
[4202100115] = {4202100115, 12021001, 16, 10, "0", "0", "明瞭。", "0", "0", "0", "0", "0", "cv_sk_shaoyin_16", "0", "0"},
[4202100116] = {4202100116, 12021001, 17, 11, "0", "0", "敬賀領航大獲全勝。", "0", "0", "0", "0", "0", "cv_sk_shaoyin_17", "0", "0"},
[4202100117] = {4202100117, 12021001, 18, 12, "0", "0", "無需失落，略有瑕疵而已。", "0", "0", "0", "0", "0", "cv_sk_shaoyin_18", "0", "0"},
[4202100118] = {4202100118, 12021001, 19, 13, "0", "0", "……是以領航更勝一籌，應當高興。", "0", "0", "0", "0", "0", "cv_sk_shaoyin_19", "0", "0"},
[4202100119] = {4202100119, 12021001, 20, 14, "0", "0", "怎麼會這樣？等等，先讓我複盤一下，看問題究竟出在那裡……", "0", "0", "0", "0", "0", "cv_sk_shaoyin_20", "0", "0"},
[4202100120] = {4202100120, 12021001, 21, 15, "0", "0", "除舊迎新。", "古きを捨て、新しきを得る。", "0", "0", "0", "0", "cv_sk_shaoyin_21", "0", "0"},
[4202100121] = {4202100121, 12021001, 23, 16, "0", "0", "落筆無悔。", "下す筆に、後悔なし。", "0", "0", "0", "0", "cv_sk_shaoyin_23", "0", "0"},
[4202100122] = {4202100122, 12021001, 24, 17, "0", "0", "一字千鈞。", "一字は千鈞(せんきん)の如く。", "0", "0", "0", "0", "cv_sk_shaoyin_24", "0", "0"},
[4202100123] = {4202100123, 12021001, 25, 18, "0", "0", "遊雲驚龍。", "流れゆく雲…天を駆ける龍のように。", "0", "0", "0", "0", "cv_sk_shaoyin_25", "0", "0"},
[4202100124] = {4202100124, 12021001, 22, 38, "0", "0", "起筆。", "筆を起こします。", "0", "0", "0", "0", "cv_sk_shaoyin_22", "0", "0"},
[4202100125] = {4202100125, 12021001, 26, 19, "0", "0", "失策。", "失策でした。", "0", "0", "0", "0", "cv_sk_shaoyin_26", "0", "0"},
[4202100126] = {4202100126, 12021001, 27, 20, "0", "0", "連這裡也有您相伴呀。", "0", "0", "0", "0", "0", "cv_sk_shaoyin_27", "0", "0"},
[4202100127] = {4202100127, 12021001, 28, 21, "0", "0", "欲速則不達。", "0", "0", "0", "0", "0", "cv_sk_shaoyin_28", "0", "0"},
[4202100128] = {4202100128, 12021001, 29, 21, "0", "0", "……所以說慢慢來嘛。和我在這裡多呆一會兒不好嗎？", "0", "0", "0", "0", "0", "cv_sk_shaoyin_29", "0", "0"},
[4202100129] = {4202100129, 12021001, 30, 22, "0", "0", "原來這裡還設有小遊戲呀。", "0", "0", "0", "0", "0", "cv_sk_shaoyin_30", "0", "0"},
[4202100130] = {4202100130, 12021001, 31, 23, "0", "0", "是小女子哦。可千萬要猜對哦。", "0", "0", "0", "0", "0", "cv_sk_shaoyin_31", "0", "0"},
[4202100131] = {4202100131, 12021001, 32, 24, "0", "0", "太好啦！", "0", "0", "0", "0", "0", "cv_sk_shaoyin_32", "0", "0"},
[4202100132] = {4202100132, 12021001, 33, 25, "0", "0", "……我沒有生氣。", "0", "0", "0", "0", "0", "cv_sk_shaoyin_33", "0", "0"},
[4202100133] = {4202100133, 12021001, 34, 26, "0", "0", "領航今日到訪，是要來精進書法嗎？", "今日、ナビゲーター様がいらしたのは、書道を上達させるためでしょうか？", "0", "0", "0", "0", "cv_sk_shaoyin_34", "0", "0"},
[4202100134] = {4202100134, 12021001, 35, 27, "0", "0", "望諸事順遂。", "0", "0", "0", "0", "0", "cv_sk_shaoyin_35", "0", "0"},
[4202100135] = {4202100135, 12021001, 36, 28, "0", "0", "願旗開得勝。", "0", "0", "0", "0", "0", "cv_sk_shaoyin_36", "0", "0"},
[4202100136] = {4202100136, 12021001, 37, 29, "0", "0", "領航認識的駕駛員可真多啊……", "0", "0", "0", "0", "0", "cv_sk_shaoyin_37", "0", "0"},
[4202100137] = {4202100137, 12021001, 38, 30, "0", "0", "此般仁人志士……等等，該不會是準備把我換掉了吧？", "0", "0", "0", "0", "0", "cv_sk_shaoyin_38", "0", "0"},
[4202100138] = {4202100138, 12021001, 39, 31, "0", "0", "人形錦鯉的傳言，您已知曉了呀……", "0", "0", "0", "0", "0", "cv_sk_shaoyin_39", "0", "0"},
[4202100139] = {4202100139, 12021001, 40, 32, "0", "0", "欲易何物？", "0", "0", "0", "0", "0", "cv_sk_shaoyin_40", "0", "0"},
[4202100140] = {4202100140, 12021001, 41, 33, "0", "0", "哼哼，領航的助理是我呢~", "0", "0", "0", "0", "0", "cv_sk_shaoyin_41", "0", "0"},
[4202100141] = {4202100141, 12021001, 42, 34, "0", "0", "難道是我話太多了，領航決定要靜我的音？", "0", "0", "0", "0", "0", "cv_sk_shaoyin_42", "0", "0"},
[4202100142] = {4202100142, 12021001, 43, 35, "0", "0", "要不然我也寫封信寄給領航吧？", "0", "0", "0", "0", "0", "cv_sk_shaoyin_43", "0", "0"},
[4202100143] = {4202100143, 12021001, 44, 36, "0", "0", "……不要總是和別人聊啦。", "0", "0", "0", "0", "0", "cv_sk_shaoyin_44", "0", "0"},
[4202100144] = {4202100144, 12021001, 45, 37, "0", "0", "凡事皆應謹言慎——您已經按下去了？！", "0", "0", "0", "0", "0", "cv_sk_shaoyin_45", "0", "0"},
[4202200100] = {4202200100, 12022001, 1, 1, "0", "0", "蒼霧殘響~", "0", "0", "0", "0", "0", "cv_sk_laipani_34", "0", "0"},
[4202200101] = {4202200101, 12022001, 2, 2, "0", "0", "領航，現在可是工作的時間，就在這哪裡都不要去哦。", "0", "0", "0", "0", "0", "cv_sk_laipani_2", "0", "0"},
[4202200102] = {4202200102, 12022001, 3, 3, "0", "0", "初次見面，我是萊帕尼，偵查小隊“鐵鴉”的隊長。之後很長一段時間都要請您指教了，領航。", "0", "0", "0", "0", "0", "cv_sk_laipani_1", "0", "0"},
[4202200103] = {4202200103, 12022001, 4, 4, "0", "idle", "領航，您看上去睡眠不足的樣子，要休息一下嗎？曠工的懲罰可以先記在本子上。", "0", "0", "0", "0", "0", "cv_sk_laipani_3", "0", "0"},
[4202200104] = {4202200104, 12022001, 5, 4, "0", "idle", "“鐵鴉”是一隻讓我引以為豪的隊伍。所以，我也希望領航您能夠信任我們，把重要的任務託付給我們。", "0", "0", "0", "0", "0", "cv_sk_laipani_4", "0", "0"},
[4202200105] = {4202200105, 12022001, 6, 4, "0", "idle", "執行任務的時候，如果洛洛不在身邊的話，我可能哪裡都去不了。真的多虧有她在了。", "0", "0", "0", "0", "0", "cv_sk_laipani_31", "0", "0"},
[4202200106] = {4202200106, 12022001, 7, 5, "1_》_0_0.8", "level1", "戰爭中，一定有很多像我一樣和父母走散了的孩子……那樣的事實在是太不合理了……您不這麼認為嗎？", "0", "0", "0", "0", "0", "cv_sk_laipani_32", "0", "0"},
[4202200107] = {4202200107, 12022001, 8, 5, "1_》_0_0.8", "level1", "領航，您是想讓我握住您的手嗎？嗯……是不是太小了點？", "0", "0", "0", "0", "0", "cv_sk_laipani_5", "0", "0"},
[4202200108] = {4202200108, 12022001, 9, 5, "1_》_100_1.5", "level2", "領航，您最近如果失眠的話，我可以幫你噢。我這邊有許多類型的安眠藥，一定能讓您睡個好覺的。", "0", "0", "0", "0", "0", "cv_sk_laipani_6", "0", "0"},
[4202200109] = {4202200109, 12022001, 10, 5, "1_》_500_2", "level3", "領航，雖然我是路癡，但我可是“鐵鴉”的隊長噢！不管您身處何地，只要您呼喚了我，我一定能找到您的！", "0", "0", "0", "0", "0", "cv_sk_laipani_7", "0", "0"},
[4202200110] = {4202200110, 12022001, 11, 5, "1_》_1000_2.5", "level4", "領航，能請您帶上這根鏈子嗎……“捆綁”？啊，不是的。我只是希望我們從此之後都不會分開，不會走散而已……不行……嗎？", "0", "0", "0", "0", "0", "cv_sk_laipani_8", "0", "0"},
[4202200111] = {4202200111, 12022001, 12, 6, "0", "0", "謝謝。", "0", "0", "0", "0", "0", "cv_sk_laipani_9", "0", "0"},
[4202200112] = {4202200112, 12022001, 13, 7, "0", "0", "要想想該怎麼回報您才行~", "0", "0", "0", "0", "0", "cv_sk_laipani_10", "0", "0"},
[4202200113] = {4202200113, 12022001, 14, 8, "0", "0", "能被您如此重視，我真的感到很幸福，領航。在這之後，我們也要一直在一起，不要，也不能分開噢。", "0", "0", "0", "0", "0", "cv_sk_laipani_11", "0", "0"},
[4202200114] = {4202200114, 12022001, 15, 9, "0", "0", "更想要識路的技能呀……", "0", "0", "0", "0", "0", "cv_sk_laipani_12", "0", "0"},
[4202200115] = {4202200115, 12022001, 16, 10, "0", "0", "討人厭的原罪在哪呢？", "0", "0", "0", "0", "0", "cv_sk_laipani_13", "0", "0"},
[4202200116] = {4202200116, 12022001, 17, 11, "0", "0", "這都是大家的功勞。", "0", "0", "0", "0", "0", "cv_sk_laipani_14", "0", "0"},
[4202200117] = {4202200117, 12022001, 18, 12, "0", "0", "我們一起反省吧，領航。", "0", "0", "0", "0", "0", "cv_sk_laipani_15", "0", "0"},
[4202200118] = {4202200118, 12022001, 19, 13, "0", "0", "千鈞一髮，真危險啊……", "0", "0", "0", "0", "0", "cv_sk_laipani_16", "0", "0"},
[4202200119] = {4202200119, 12022001, 20, 14, "0", "0", "撤退……大家，別走散了！", "0", "0", "0", "0", "0", "cv_sk_laipani_17", "0", "0"},
[4202200120] = {4202200120, 12022001, 21, 15, "0", "0", "下一位是誰呢？", "0", "0", "0", "0", "0", "cv_sk_laipani_18", "0", "0"},
[4202200121] = {4202200121, 12022001, 23, 16, "0", "0", "發射！", "0", "0", "0", "0", "0", "cv_sk_laipani_20", "0", "0"},
[4202200122] = {4202200122, 12022001, 24, 17, "0", "0", "永不復還！", "0", "0", "0", "0", "0", "cv_sk_laipani_22", "0", "0"},
[4202200123] = {4202200123, 12022001, 25, 18, "0", "0", "我宣佈，捉迷藏遊戲結束了。", "0", "0", "0", "0", "0", "cv_sk_laipani_23", "0", "0"},
[4202200124] = {4202200124, 12022001, 22, 38, "0", "0", "要來了噢。", "0", "0", "0", "0", "0", "cv_sk_laipani_19", "0", "0"},
[4202200125] = {4202200125, 12022001, 26, 19, "0", "0", "要找到我噢，領航……", "0", "0", "0", "0", "0", "cv_sk_laipani_21", "0", "0"},
[4202200126] = {4202200126, 12022001, 27, 20, "0", "0", "領航，果然是您來了。您的腳步聲，我已經完全記住了呢。", "0", "0", "0", "0", "0", "cv_sk_laipani_24", "0", "0"},
[4202200127] = {4202200127, 12022001, 28, 21, "0", "0", "呼……好危險。剛剛差點把領航當做蚊子拍下去了~", "0", "0", "0", "0", "0", "cv_sk_laipani_25", "0", "0"},
[4202200128] = {4202200128, 12022001, 29, 21, "0", "0", "領航的視線……感覺癢癢的。", "0", "0", "0", "0", "0", "cv_sk_laipani_26", "0", "0"},
[4202200129] = {4202200129, 12022001, 30, 22, "0", "0", "嗯？", "0", "0", "0", "0", "0", "cv_sk_laipani_27", "0", "0"},
[4202200130] = {4202200130, 12022001, 31, 23, "0", "0", "請放心，即使錯了也沒有關係的。", "0", "0", "0", "0", "0", "cv_sk_laipani_28", "0", "0"},
[4202200131] = {4202200131, 12022001, 32, 24, "0", "0", "謝謝您找到了我，領航。", "0", "0", "0", "0", "0", "cv_sk_laipani_29", "0", "0"},
[4202200132] = {4202200132, 12022001, 33, 25, "0", "0", "為了不重蹈覆轍，請您聽我的錄音一萬遍，好嗎？", "0", "0", "0", "0", "0", "cv_sk_laipani_30", "0", "0"},
[4202200133] = {4202200133, 12022001, 34, 26, "0", "0", "領航，歡迎回來，您安排好今天的行程了嗎？", "0", "0", "0", "0", "0", "cv_sk_laipani_33", "0", "0"},
[4202200134] = {4202200134, 12022001, 35, 27, "0", "0", "放著我不管的話，我會迷路的。", "0", "0", "0", "0", "0", "cv_sk_laipani_35", "0", "0"},
[4202200135] = {4202200135, 12022001, 36, 28, "0", "0", "我們攜手前進吧，領航。", "0", "0", "0", "0", "0", "cv_sk_laipani_36", "0", "0"},
[4202200136] = {4202200136, 12022001, 37, 29, "0", "0", "大家看起來都很健康呢。", "0", "0", "0", "0", "0", "cv_sk_laipani_37", "0", "0"},
[4202200137] = {4202200137, 12022001, 38, 30, "0", "0", "我來為新人引路吧。", "0", "0", "0", "0", "0", "cv_sk_laipani_38", "0", "0"},
[4202200138] = {4202200138, 12022001, 39, 31, "0", "0", "不能太沉迷噢。", "0", "0", "0", "0", "0", "cv_sk_laipani_39", "0", "0"},
[4202200139] = {4202200139, 12022001, 40, 32, "0", "0", "嗯……全買了吧？", "0", "0", "0", "0", "0", "cv_sk_laipani_40", "0", "0"},
[4202200140] = {4202200140, 12022001, 41, 33, "0", "0", "要記得管理好自己的檔案噢。", "0", "0", "0", "0", "0", "cv_sk_laipani_41", "0", "0"},
[4202200141] = {4202200141, 12022001, 42, 34, "0", "0", "要細心設置呢。", "0", "0", "0", "0", "0", "cv_sk_laipani_42", "0", "0"},
[4202200142] = {4202200142, 12022001, 43, 35, "0", "0", "不許和可疑的人來往。", "0", "0", "0", "0", "0", "cv_sk_laipani_43", "0", "0"},
[4202200143] = {4202200143, 12022001, 44, 36, "0", "0", "有可疑的人要告訴我~", "0", "0", "0", "0", "0", "cv_sk_laipani_44", "0", "0"},
[4202200144] = {4202200144, 12022001, 45, 37, "0", "0", "小心觸電。", "0", "0", "0", "0", "0", "cv_sk_laipani_45", "0", "0"},
[4202600100] = {4202600100, 12026001, 1, 1, "0", "0", "蒼霧殘響", "ハツリバーブ", "0", "0", "0", "0", "cv_sk_lyfa2_1", "0", "0"},
[4202600101] = {4202600101, 12026001, 2, 2, "0", "0", "請放心交給我吧，保護老大的安全是身為手下的我該盡的義務！", "安心して私にお任せください、親分の身の安全を確保することこそ、私の義務ですから。", "0", "0", "0", "0", "cv_sk_lyfa2_2", "0", "0"},
[4202600102] = {4202600102, 12026001, 3, 3, "0", "0", "瓦爾基裡的莉法小姐——也就是我——又來打擾您啦！這次的目標是打倒艾吉斯嗎？", "ワルキューレのリーファさん――つまり私――この度もお邪魔することになりました！今回の目標は打倒アイギスでしょうか？", "0", "0", "0", "0", "cv_sk_lyfa2_3", "0", "0"},
[4202600103] = {4202600103, 12026001, 91, 4, "0", "touch1", "奇怪……問題出在哪了呢？難道是上次開得太過火了嗎？", "おかしいなあ……どこが問題だったんでしょう？もしかして、前回飛ばしすぎたせいかな？", "0", "0", "0", "0", "cv_sk_lyfa2_7", "0", "0,touch1"},
[4202600104] = {4202600104, 12026001, 91, 4, "0", "touch1", "把車修好之後就一起去兜風吧，那種將風甩在身後，大腦一片放空的感覺會讓人上癮的，我跟您保證！", "バイクが直ったら、一緒にドライブに行きましょう！風を追い越して、頭を空っぽにする感覚、病みつきになりますよ、私が保証します！", "0", "0", "0", "0", "cv_sk_lyfa2_8", "0", "0,touch1"},
[4202600105] = {4202600105, 12026001, 91, 4, "0", "idle", "我經常在實驗室裡幫忙……不過機械維修的確不是我擅長的領域，是不是拜託隊長比較好？", "私はよく研究室で手伝っていますけど、機械の修理はあまり得意じゃないんです。隊長にお願いするのがいいかもしれませんね。", "0", "0", "0", "0", "cv_sk_lyfa2_9", "0", "0,idle"},
[4202600106] = {4202600106, 12026001, 94, 4, "0", "touch2", "哇哇哇，涼颼颼的，奇怪的感覺……", "あわわ、ひんやりして、変な感じです……", "0", "0", "0", "0", "cv_sk_lyfa2_13", "0", "0,touch2"},
[4202600107] = {4202600107, 12026001, 94, 4, "0", "touch2", "咦，領航什麼都不打算做嗎……不，也不是希望領航您要做什麼，但是……氣氛不是都到這了嗎……", "え、ナビゲーターさん、何もするつもりないんですか……いや、別に何かしてほしいわけじゃないんですけど……この雰囲気なら何かが起こるかと思ったのに……", "0", "0", "0", "0", "cv_sk_lyfa2_14", "0", "0,touch2"},
[4202600108] = {4202600108, 12026001, 94, 4, "0", "idle2", "捉弄人之後又把人放置不管，這是某種惡趣味的做法吧，我明白的。", "人をからかった後に放置するのは、ちょっと悪趣味なやり方ですね。わかってます。", "0", "0", "0", "0", "cv_sk_lyfa2_15", "0", "0,idle2"},
[4202600109] = {4202600109, 12026001, 94, 5, "0", "touch3", "只要騎上摩托，就可以前往任何地方，就算是領航的心裡，也一定能抵達的。", "バイクに乗れば、例えナビゲーターさんの心の奥底でもひとっ走りで着きますね。", "0", "0", "0", "0", "cv_sk_lyfa2_5", "0", "0,touch3"},
[4202600110] = {4202600110, 12026001, 94, 5, "0", "idle3", "肌膚之間的親密接觸能夠讓人更加深入地瞭解對方的想法，這點用在摩托上行不行得通呢？對了，領航要來試試嗎？不，不是摩托，我是說和我~", "スキンシップによってお互いの考えをもっと深く理解できるんです。これバイクにも通用するでしょうか？そうだ、ナビゲーターさんも試してみますか？む～、バイクじゃなくて、私とですけど～", "0", "0", "0", "0", "cv_sk_lyfa2_6", "0", "0,idle3"},
[4202600111] = {4202600111, 12026001, 94, 5, "0", "touch3", "嗚——到不是討厭，只是有點癢……非要說的話，還有點舒服？就是時機不太對啦……", "ううん、嫌じゃないんですけど、ちょっとくすぐったいです……どちらかというと、少し気持ちいいかも？でも何事にも節度というものが……", "0", "0", "0", "0", "cv_sk_lyfa2_12", "0", "0,touch3"},
[4202600112] = {4202600112, 12026001, 93, 5, "0", "level1", "呜……", "……", "0", "0", "0", "0", "cv_sk_lyfa2_50", "0", "0,level1"},
[4202600113] = {4202600113, 12026001, 93, 5, "0", "level2", "唔……！", "……", "0", "0", "0", "0", "cv_sk_lyfa2_51", "0", "0,level2"},
[4202600114] = {4202600114, 12026001, 93, 5, "0", "level3", "诶嘿——", "てへ……", "0", "0", "0", "0", "cv_sk_lyfa2_52", "0", "0,level3"},
[4202600115] = {4202600115, 12026001, 12, 6, "0", "0", "謝謝~", "ありがとうございます～", "0", "0", "0", "0", "cv_sk_lyfa2_16", "0", "0"},
[4202600116] = {4202600116, 12026001, 13, 7, "0", "0", "聽到引擎的嗡嗡聲了！", "エンジン音が聞こえる！", "0", "0", "0", "0", "cv_sk_lyfa2_17", "0", "0"},
[4202600117] = {4202600117, 12026001, 14, 8, "0", "0", "能聽到咆哮聲嗎？嗯，那正是我與摩托的默契達到極致時發出的共鳴！", "この轟音こそが、私とバイクの共鳴です！", "0", "0", "0", "0", "cv_sk_lyfa2_18", "0", "0"},
[4202600118] = {4202600118, 12026001, 15, 9, "0", "0", "車技變得更嫺熟了。", "運転技術がさらに上達しました。", "0", "0", "0", "0", "cv_sk_lyfa2_19", "0", "0"},
[4202600119] = {4202600119, 12026001, 16, 10, "0", "0", "讓我們在戰場上刮起龍捲風吧！", "戦場に竜巻を巻き起こしましょう！", "0", "0", "0", "0", "cv_sk_lyfa2_20", "0", "0"},
[4202600120] = {4202600120, 12026001, 17, 11, "0", "0", "這是一次完美的表演。", "完璧なパフォーマンスですね。", "0", "0", "0", "0", "cv_sk_lyfa2_21", "0", "0"},
[4202600121] = {4202600121, 12026001, 18, 12, "0", "0", "是不是違章了？", "もしかして、交通違反しちゃった？", "0", "0", "0", "0", "cv_sk_lyfa2_22", "0", "0"},
[4202600122] = {4202600122, 12026001, 19, 13, "0", "0", "嗚哇，摩托車出現裂痕了……", "ああ、バイクに傷が……", "0", "0", "0", "0", "cv_sk_lyfa2_23", "0", "0"},
[4202600123] = {4202600123, 12026001, 20, 14, "0", "0", "擰滿油門，撤退！", "アクセル全開、撤退します！", "0", "0", "0", "0", "cv_sk_lyfa2_24", "0", "0"},
[4202600124] = {4202600124, 12026001, 21, 15, "0", "0", "嗯？撞到什麼了？", "ん？何かにぶつかりました？", "0", "0", "0", "0", "cv_sk_lyfa2_25", "0", "0"},
[4202600125] = {4202600125, 12026001, 22, 38, "0", "0", "點火、準備啟動~", "エンジン点火、準備完了～", "0", "0", "0", "0", "cv_sk_lyfa2_29", "0", "0"},
[4202600126] = {4202600126, 12026001, 23, 16, "0", "0", "哇呼~~", "わあぁ！", "0", "0", "0", "0", "cv_sk_lyfa2_26", "0", "0"},
[4202600127] = {4202600127, 12026001, 24, 17, "0", "0", "速度max！", "スピードMAX！", "0", "0", "0", "0", "cv_sk_lyfa2_27", "0", "0"},
[4202600128] = {4202600128, 12026001, 25, 18, "0", "0", "做好心理準備吧，我是沖下懸崖的那類！", "覚悟してくださいね、私は崖から飛び降りるタイプですから！", "0", "0", "0", "0", "cv_sk_lyfa2_28", "0", "0"},
[4202600129] = {4202600129, 12026001, 26, 19, "0", "0", "我會好好反省的……", "ちゃんと反省します……", "0", "0", "0", "0", "cv_sk_lyfa2_30", "0", "0"},
[4202600130] = {4202600130, 12026001, 27, 20, "0", "0", "居然又麻煩領航來招待我了……之後只好下跪謝罪了！", "またナビゲーターさんに迷惑をかけちゃって……これはもう土下座してお詫びするしか！", "0", "0", "0", "0", "cv_sk_lyfa2_31", "0", "0"},
[4202600131] = {4202600131, 12026001, 28, 21, "0", "0", "我會懷著感恩的心情享受領航的服務，謝謝！", "ナビゲーターさんのサービスに感謝しながら、楽しませていただきますね、ありがとうございます！", "0", "0", "0", "0", "cv_sk_lyfa2_32", "0", "0"},
[4202600132] = {4202600132, 12026001, 29, 21, "0", "0", "下次換我來給領航搓背吧~", "次は私がナビゲーターさんの背中を洗いますね～", "0", "0", "0", "0", "cv_sk_lyfa2_33", "0", "0"},
[4202600133] = {4202600133, 12026001, 30, 22, "0", "0", "發生什麼了？", "何があったんですか？", "0", "0", "0", "0", "cv_sk_lyfa2_34", "0", "0"},
[4202600134] = {4202600134, 12026001, 31, 23, "0", "0", "鏘鏘鏘！老大，猜猜我是誰！", "じゃじゃーん！親分、私が誰だか分かりますか？", "0", "0", "0", "0", "cv_sk_lyfa2_35", "0", "0"},
[4202600135] = {4202600135, 12026001, 32, 24, "0", "0", "答對啦，我們之間的默契無懈可擊。", "大正解、私たちの相性はバッチリですね！", "0", "0", "0", "0", "cv_sk_lyfa2_36", "0", "0"},
[4202600136] = {4202600136, 12026001, 33, 25, "0", "0", "奇怪，到底是哪裡搞錯了呢……", "あれ、どこで間違えたんだろう……", "0", "0", "0", "0", "cv_sk_lyfa2_37", "0", "0"},
[4202600137] = {4202600137, 12026001, 34, 26, "0", "0", "嗯？是老大啊，我正在檢查摩托，稍微等等啊~", "あれ、親分？今バイクの点検中なんです。ちょっと待っていってくださいね～", "0", "0", "0", "0", "cv_sk_lyfa2_38", "0", "0"},
[4202600138] = {4202600138, 12026001, 35, 27, "0", "0", "把攔在路上的敵人全部撞飛吧。", "道を阻む敵は全部ぶっ飛ばしましょう！", "0", "0", "0", "0", "cv_sk_lyfa2_39", "0", "0"},
[4202600139] = {4202600139, 12026001, 36, 28, "0", "0", "點到即止噢。", "加減はちゃんとしますよ。", "0", "0", "0", "0", "cv_sk_lyfa2_40", "0", "0"},
[4202600140] = {4202600140, 12026001, 37, 29, "0", "0", "大家既是夥伴……也是競爭者。", "みんな仲間でもあり……競争相手でもあります。", "0", "0", "0", "0", "cv_sk_lyfa2_41", "0", "0"},
[4202600141] = {4202600141, 12026001, 38, 30, "0", "0", "不知道這次來的會是怎樣有趣的人。", "今回はどんな面白い人が来るかな。", "0", "0", "0", "0", "cv_sk_lyfa2_42", "0", "0"},
[4202600142] = {4202600142, 12026001, 39, 31, "0", "0", "我也想換上更高檔的車。", "私ももっと高級なバイクに乗りたいな。", "0", "0", "0", "0", "cv_sk_lyfa2_43", "0", "0"},
[4202600143] = {4202600143, 12026001, 40, 32, "0", "0", "我來負責搬東西~", "荷物運びは私に任せてください～", "0", "0", "0", "0", "cv_sk_lyfa2_44", "0", "0"},
[4202600144] = {4202600144, 12026001, 41, 33, "0", "0", "領航變得更成熟了~", "ナビゲーターさん、また一段と立派になりましたね。", "0", "0", "0", "0", "cv_sk_lyfa2_45", "0", "0"},
[4202600145] = {4202600145, 12026001, 42, 34, "0", "0", "修改後記得確認哦。", "修正したら確認してくださいね。", "0", "0", "0", "0", "cv_sk_lyfa2_46", "0", "0"},
[4202600146] = {4202600146, 12026001, 43, 35, "0", "0", "沒有定時炸彈，沒有刀片，安全。", "爆弾も刃物もありません、安全です。", "0", "0", "0", "0", "cv_sk_lyfa2_47", "0", "0"},
[4202600147] = {4202600147, 12026001, 44, 36, "0", "0", "不可以說髒話。", "汚い言葉はダメですよ。", "0", "0", "0", "0", "cv_sk_lyfa2_48", "0", "0"},
[4202600148] = {4202600148, 12026001, 45, 37, "0", "0", "呼呼~", "ふふ～", "0", "0", "0", "0", "cv_sk_lyfa2_49", "0", "0"},
[4300100100] = {4300100100, 13001001, 1, 1, "0", "0", "蒼霧殘響。", "0", "0", "0", "0", "0", "cv_sk_furanka_30", "0", "0"},
[4300100101] = {4300100101, 13001001, 2, 2, "0", "0", "這樣真的好嗎？不……我並不是在質疑您的判斷，非常抱歉！", "0", "0", "0", "0", "0", "cv_sk_furanka_2", "0", "0"},
[4300100102] = {4300100102, 13001001, 3, 3, "0", "0", "您好，我的名字是弗蘭卡·芬奇，是今年新上任的駕駛員，很高興能夠見到您。", "0", "0", "0", "0", "0", "cv_sk_furanka_1", "0", "0"},
[4300100103] = {4300100103, 13001001, 91, 4, "0", "idle", "到底是哪裡出了問題呢？", "0", "0", "0", "0", "0", "cv_sk_furanka_3", "0", "0"},
[4300100104] = {4300100104, 13001001, 94, 4, "0", "idle2", "剛洗了澡麼，頭髮蓬蓬的，應該是用吹風機——不對，不是啦！醒醒弗蘭卡，現在可沒有多餘的時間來分神偷看領航，要趕緊把問題找出來才行。", "0", "0", "0", "0", "0", "cv_sk_furanka_4", "0", "0"},
[4300100105] = {4300100105, 13001001, 94, 4, "0", "idle2", "如果是朱利烏斯學姐，或者是查麗莎學姐在這裏，一定不會犯這種低級錯誤吧……", "0", "0", "0", "0", "0", "cv_sk_furanka_27", "0", "0"},
[4300100106] = {4300100106, 13001001, 93, 5, "14_》_0_0.8", "touch_s1", "一定要脫掉嗎？好吧……領航會這麼做，一定有領航的道理。嗯。", "0", "0", "0", "0", "0", "cv_sk_furanka_28", "0", "0"},
[4300100107] = {4300100107, 13001001, 96, 5, "14_》_0_0.8", "touch_s2", "衣服怎麼——啊，謝謝領航。我正覺得自己這個樣子有點不好意思，您就幫我圍上了……嘿嘿，真是太感謝您啦。", "0", "0", "0", "0", "0", "cv_sk_furanka_5", "0", "0"},
[4300100108] = {4300100108, 13001001, 92, 5, "14_》_0_0.8", "touch1", "對、對不起呐！我一定儘快會把問題解決掉的，領航您再給我點時間，好嗎？", "0", "0", "0", "0", "0", "cv_sk_furanka_6", "0", "0"},
[4300100109] = {4300100109, 13001001, 95, 5, "14_》_0_0.8", "touch2", "不要再催了啦……我已經很仔細地在排查了，但就是找不到出錯的地方……我、我也很急的啦！", "0", "0", "0", "0", "0", "cv_sk_furanka_7", "0", "0"},
[4300100110] = {4300100110, 13001001, 95, 5, "14_》_0_0.8", "touch3", "嗚！糟糕，太糟糕了，還是一點頭緒都沒有……領航，您也來幫忙啦！時間已經快來不及了！", "0", "0", "0", "0", "0", "cv_sk_furanka_8", "0", "0"},
[4300100111] = {4300100111, 13001001, 95, 5, "14_》_0_0.8", "touch4", "嗚！糟糕，太糟糕了，還是一點頭緒都沒有……領航，您也來幫忙啦！時間已經快來不及了！", "0", "0", "0", "0", "0", "cv_sk_furanka_8", "0", "0"},
