[4300100200] = {4300100200, 13001002, 1, 1, "0", "0", "蒼霧殘響。", "0", "0", "0", "0", "0", "cv_sk1_furanka_30", "0", "0"},
[4300100201] = {4300100201, 13001002, 2, 2, "0", "0", "這樣真的好嗎？不……我並不是在質疑您的判斷，非常抱歉！", "0", "0", "0", "0", "0", "cv_sk1_furanka_2", "0", "0"},
[4300100202] = {4300100202, 13001002, 3, 3, "0", "0", "您好，我的名字是弗蘭卡·芬奇，是今年新上任的駕駛員，很高興能夠見到您。", "0", "0", "0", "0", "0", "cv_sk1_furanka_1", "0", "0"},
[4300100203] = {4300100203, 13001002, 4, 4, "0", "idle", "像這樣子躺著吹吹風，不一會兒就會有很多小動物聚過來呢，小松鼠、小蝸牛，還有漂亮的小蝴蝶~", "0", "0", "0", "0", "0", "cv_sk1_furanka_3", "0", "0"},
[4300100204] = {4300100204, 13001002, 5, 4, "0", "idle", "上次出門採集，爪子不小心太用力，把漿果汁液弄得灑滿了一地，草叢都被染紅了，被外婆看見罵了一頓……", "0", "0", "0", "0", "0", "cv_sk1_furanka_4", "0", "0"},
[4300100205] = {4300100205, 13001002, 6, 4, "0", "idle", "等我長大，我是不是也要像姐姐們那樣離開這片森林，去其他地方尋找果實呢？但……我想一直留在這裡。", "0", "0", "0", "0", "0", "cv_sk1_furanka_27", "0", "0"},
[4300100206] = {4300100206, 13001002, 7, 5, "1_》_0_0.8", "touch1", "嗷嗚~嗷嗚~！看起來你們人類一聽到這樣的聲音就會害怕呢，但其實我只是在唱歌而已哦，呵呵~", "0", "0", "0", "0", "0", "cv_sk1_furanka_28", "0", "0"},
[4300100207] = {4300100207, 13001002, 8, 5, "1_》_0_0.8", "touch2", "哈嗚……不准亂摸我的小樹莓！這可是我剛採摘下來，打算帶回去給外婆吃的新鮮樹莓！", "0", "0", "0", "0", "0", "cv_sk1_furanka_5", "0", "0"},
[4300100208] = {4300100208, 13001002, 9, 5, "1_》_0_0.8", "touch1", "這件紅頭巾是外婆給我做的，很漂亮對吧？每次外出採集，我都會特別注意不把它弄髒，因為那些漿果的汁液實在太多了嘛。", "0", "0", "0", "0", "0", "cv_sk1_furanka_6", "0", "0"},
[4300100209] = {4300100209, 13001002, 10, 5, "1_》_0_0.8", "touch2", "雖然顏色都很鮮艷，但其實有的蘑菇可以吃，而有的不可以，會肚子痛。唔……你說你身上也帶著蘑菇？嗅嗅……氣味不錯呢，讓我咬一口嘗嘗。", "0", "0", "0", "0", "0", "cv_sk1_furanka_7", "0", "0"},
[4300100210] = {4300100210, 13001002, 11, 5, "1_》_0_0.8", "touch1", "你、你突然間怎麼了？明明還沒到月圓之夜，怎麼就突然獸性大發了……竟然還學我嚎叫，看我把你踹開！嗷嗚！嗷嗚！", "0", "0", "0", "0", "0", "cv_sk1_furanka_8", "0", "0"},
