[4300200100] = {4300200100, 13002001, 1, 1, "0", "0", "蒼霧殘響。", "0", "0", "0", "0", "0", "cv_sk_tina_29", "0", "0"},
[4300200101] = {4300200101, 13002001, 2, 2, "0", "0", "身為女僕長確實應該起到表率作用。", "0", "0", "0", "0", "0", "cv_sk_tina_2", "0", "0"},
[4300200102] = {4300200102, 13002001, 3, 3, "0", "0", "蒂娜·愛森，克雷蒂亞家族最忠誠的僕從。領航，你有看到我家小姐嗎？", "0", "0", "0", "0", "0", "cv_sk_tina_1", "0", "0"},
[4300200103] = {4300200103, 13002001, 4, 4, "0", "idle", "車隊比賽和戰鬥是一樣的，如果心中只有自己，就無法取得勝利。", "レースは戦闘と同じです。自分のことだけを考えていては、勝つことはできません。", "0", "0", "0", "0", "cv_sk_tina_3", "0", "0"},
[4300200104] = {4300200104, 13002001, 5, 4, "0", "idle", "除了駕駛技術，比賽時的心態也非常重要。我對你的高要求也是在訓練你的抗壓能力。", "運転のテクニック以外に、メンタルも非常に重要です。私があなたに厳しくしているのも、ストレス耐性を鍛えるためですよ。", "0", "0", "0", "0", "cv_sk_tina_4", "0", "0"},
[4300200105] = {4300200105, 13002001, 6, 4, "0", "idle", "下次的比賽選擇硬胎轉軟胎的戰術……我已經說過很多遍了？看來我也有些緊張了，我會儘量保持克制的。", "次のレースでは、タイヤをハードからソフトに交換するように……既に言っていましたか？どうやら、私も少し緊張しているようですね。メンタルを整えます。", "0", "0", "0", "0", "cv_sk_tina_41", "0", "0"},
[4300200106] = {4300200106, 13002001, 7, 5, "15_1_0_0.8", "level1", "雖然現在是休賽期，但也不能鬆懈，今天照常訓練。", "オフシーズンに入りましたが、怠けてはいけませんよ。今日もいつも通りに訓練を行いますわ。", "0", "0", "0", "0", "cv_sk_tina_27", "0", "0"},
[4300200107] = {4300200107, 13002001, 8, 5, "15_2_0_0.8", "level2", "請專心訓練。", "訓練に集中してください。", "0", "0", "0", "0", "cv_sk_tina_5", "0", "0"},
[4300200108] = {4300200108, 13002001, 9, 5, "15_1_0_0.8", "level1", "記住，第一圈的首要任務永遠是“活下來”，一定要穩住心態，保持自己的節奏。", "ちゃんと覚えてくださいね。１周目の目標は、生き殘ることです。メンタルを安定させて、自分のリズムを保つようにしましょう。", "0", "0", "0", "0", "cv_sk_tina_6", "0", "0"},
[4300200109] = {4300200109, 13002001, 10, 5, "15_1_0_0.8", "level1", "比賽中你不需要一直都保持緊張，如果你領先得足夠多，你可以試著放慢節奏去節省輪胎。什麼？只要想起我就會緊張？我是那麼可怕的教練麼……", "レース中、常に気を張る必要はありません。十分にリードしている場合は、タイヤの節約のために速度を落としてもいいでしょう。え、私のことを考えるだけで緊張してしまうですって？私って、そんなに怖いコーチなのででしょうか……", "0", "0", "0", "0", "cv_sk_tina_7", "0", "0"},
[4300200110] = {4300200110, 13002001, 11, 5, "15_2_0_0.8", "level2", "誒？我在這裡就無法認真訓練？你……你在看什麼地方啊！我是來監督訓練的，不要老是看著我啊！不專心訓練我可是會懲罰你的！", "え、私がここにいたら、訓練に集中できないと？あなた、どこを見ているのですか！私は訓練を監督するために來ているのです。私のことばかり見つめるのはおやめください！訓練に集中しないと、後でお仕置きですからね！", "0", "0", "0", "0", "cv_sk_tina_8", "0", "0"},
[4300200111] = {4300200111, 13002001, 12, 6, "0", "0", "欸呀，看來你對我心懷期待呢。", "0", "0", "0", "0", "0", "cv_sk_tina_9", "0", "0"},
[4300200112] = {4300200112, 13002001, 13, 7, "0", "0", "喔～這就是你教育人的方式嗎？", "0", "0", "0", "0", "0", "cv_sk_tina_10", "0", "0"},
[4300200113] = {4300200113, 13002001, 14, 8, "0", "0", "承蒙厚愛，從今往後我絕不辜負你的期待，努力探求出屬於自己的道路。", "0", "0", "0", "0", "0", "cv_sk_tina_11", "0", "0"},
[4300200114] = {4300200114, 13002001, 15, 9, "0", "0", "這是……新的教鞭？", "0", "0", "0", "0", "0", "cv_sk_tina_12", "0", "0"},
[4300200115] = {4300200115, 13002001, 16, 10, "0", "0", "這群野獸，已經完全沒有接受教育的必要了！", "0", "0", "0", "0", "0", "cv_sk_tina_13", "0", "0"},
[4300200116] = {4300200116, 13002001, 17, 11, "0", "0", "哼，果然獎勵要比責罰更加重要啊。", "0", "0", "0", "0", "0", "cv_sk_tina_14", "0", "0"},
[4300200117] = {4300200117, 13002001, 18, 12, "0", "0", "稍微有些疏漏呢，應該還有提升的空間。", "0", "0", "0", "0", "0", "cv_sk_tina_15", "0", "0"},
[4300200118] = {4300200118, 13002001, 19, 13, "0", "0", "該好好自我反省一下了啊。", "0", "0", "0", "0", "0", "cv_sk_tina_16", "0", "0"},
[4300200119] = {4300200119, 13002001, 20, 14, "0", "0", "是因為平時還不夠嚴苛嗎……還是說我的方法本身就是錯誤的……", "0", "0", "0", "0", "0", "cv_sk_tina_17", "0", "0"},
[4300200120] = {4300200120, 13002001, 23, 16, "0", "0", "Box！", "ボックス！", "0", "0", "0", "0", "cv_sk_tina_18", "0", "0"},
[4300200121] = {4300200121, 13002001, 26, 19, "0", "0", "比賽……結束了麼……", "レース……終了ですか……", "0", "0", "0", "0", "cv_sk_tina_19", "0", "0"},
[4300200122] = {4300200122, 13002001, 27, 20, "0", "0", "保持清潔，也是禮儀的一環。", "0", "0", "0", "0", "0", "cv_sk_tina_20", "0", "0"},
[4300200123] = {4300200123, 13002001, 28, 21, "0", "0", "不要懈怠！", "0", "0", "0", "0", "0", "cv_sk_tina_21", "0", "0"},
[4300200124] = {4300200124, 13002001, 29, 21, "0", "0", "目前為止，你都做得不錯呢。", "0", "0", "0", "0", "0", "cv_sk_tina_22", "0", "0"},
[4300200125] = {4300200125, 13002001, 30, 22, "0", "0", "要來了，打起精神！", "0", "0", "0", "0", "0", "cv_sk_tina_23", "0", "0"},
[4300200126] = {4300200126, 13002001, 31, 23, "0", "0", "這裡是單選題，千萬不要選錯了。", "0", "0", "0", "0", "0", "cv_sk_tina_24", "0", "0"},
[4300200127] = {4300200127, 13002001, 32, 24, "0", "0", "不錯，這都是你自己努力的結果，值得表揚！", "0", "0", "0", "0", "0", "cv_sk_tina_25", "0", "0"},
[4300200128] = {4300200128, 13002001, 33, 25, "0", "0", "看來……是教育方式出了問題！", "0", "0", "0", "0", "0", "cv_sk_tina_26", "0", "0"},
[4300200129] = {4300200129, 13002001, 34, 26, "0", "0", "嗯，沒有遲到，今天的訓練項目是頸部力量訓練、三角肌訓練、坐姿……醒醒，醒醒。", "はい、遅刻はしませんでしたね。今日の訓練メニューは、首周りの筋力、三角筋の強化、座りの姿勢……って、もしもし、起きてください！", "0", "0", "0", "0", "cv_sk_tina_28", "0", "0"},
[4300200130] = {4300200130, 13002001, 35, 27, "0", "0", "來吧，書寫屬於你的故事吧。", "0", "0", "0", "0", "0", "cv_sk_tina_30", "0", "0"},
[4300200131] = {4300200131, 13002001, 36, 28, "0", "0", "每天都得適當活動一下呢。", "0", "0", "0", "0", "0", "cv_sk_tina_31", "0", "0"},
[4300200132] = {4300200132, 13002001, 37, 29, "0", "0", "很好，人都到齊了呢。", "0", "0", "0", "0", "0", "cv_sk_tina_32", "0", "0"},
[4300200133] = {4300200133, 13002001, 38, 30, "0", "0", "看來要培養的孩子又變多了呢。", "0", "0", "0", "0", "0", "cv_sk_tina_33", "0", "0"},
[4300200134] = {4300200134, 13002001, 39, 31, "0", "0", "裝備對戰鬥力的提升是不可忽視的。", "0", "0", "0", "0", "0", "cv_sk_tina_34", "0", "0"},
[4300200135] = {4300200135, 13002001, 40, 32, "0", "0", "採購的話，就交給我吧。", "0", "0", "0", "0", "0", "cv_sk_tina_35", "0", "0"},
[4300200136] = {4300200136, 13002001, 41, 33, "0", "0", "要記得整理好妝容。", "0", "0", "0", "0", "0", "cv_sk_tina_36", "0", "0"},
[4300200137] = {4300200137, 13002001, 42, 34, "0", "0", "確認下設定有沒有問題吧。", "0", "0", "0", "0", "0", "cv_sk_tina_37", "0", "0"},
[4300200138] = {4300200138, 13002001, 43, 35, "0", "0", "請定期檢查信箱。", "0", "0", "0", "0", "0", "cv_sk_tina_38", "0", "0"},
[4300200139] = {4300200139, 13002001, 44, 36, "0", "0", "不要一直賴在聊天室裏。", "0", "0", "0", "0", "0", "cv_sk_tina_39", "0", "0"},
[4300200140] = {4300200140, 13002001, 45, 37, "0", "0", "得留心一下。", "0", "0", "0", "0", "0", "cv_sk_tina_40", "0", "0"},
[4300300100] = {4300300100, 13003001, 1, 1, "0", "0", "抗霧才想——", "0", "0", "0", "0", "0", "cv_sk_kurimu_30", "0", "0"},
[4300300101] = {4300300101, 13003001, 2, 2, "0", "0", "喔！這就是所謂的上得廳堂下得廚房吧。", "0", "0", "0", "0", "0", "cv_sk_kurimu_2", "0", "0"},
[4300300102] = {4300300102, 13003001, 3, 3, "0", "0", "欸嘿嘿~李猴牙~我名字是克裏姆木木木木點科點塔諾夫~", "0", "0", "0", "0", "0", "cv_sk_kurimu_1", "0", "0"},
[4300300103] = {4300300103, 13003001, 4, 4, "0", "idle", "翅膀？尾巴？領航你是喝醉了嗎？不過不要緊，我們繼續喝。", "羽根？尻尾？ナビゲーター、酔ってるんじゃない？ま、気にしないでじゃんじゃん飲もー！", "0", "0", "0", "0", "cv_sk_kurimu_3", "0", "0"},
[4300300104] = {4300300104, 13003001, 5, 4, "0", "idle", "唔？熏肉腸吃完了嗎？沒有下酒菜的話這酒喝著沒滋味了……領航你那兒還藏著熏肉腸是不是？", "あれ、ソーセージ、もうないの？つまみがないと寂しいなー……ナビゲーター、どっかにまだソーセージ隠してなーい？", "0", "0", "0", "0", "cv_sk_kurimu_4", "0", "0"},
[4300300105] = {4300300105, 13003001, 6, 4, "0", "idle", "伊莉雅姐姐在這裏的話，領航今天可就別想走著回去咯。她的酒量就連我都有點扛不住。不過放心，真到了那時候的話，我會幫你喝的。", "イリア姉さんがここにいたら、ナビゲーターは帰れなかったよ。姉さんの飲む量はハンパないからね。でも大丈夫！そうなったらあたしが代わりに飲んであげる！", "0", "0", "0", "0", "cv_sk_kurimu_27", "0", "0"},
[4300300106] = {4300300106, 13003001, 7, 5, "1_》_0_0.8", "level1", "人們都說酒會勾出人的欲望，那是因為欲望本來就存在於人的心中。", "酒は人を狂わせるって言うけど、その人の本質が元々そうってことだよ。", "0", "0", "0", "0", "cv_sk_kurimu_28", "0", "0"},
[4300300107] = {4300300107, 13003001, 8, 5, "1_》_0_0.8", "level1", "你摸哪裡呢？這可不是酒瓶。", "どこ觸ってんの？それは酒瓶じゃないよ。", "0", "0", "0", "0", "cv_sk_kurimu_5", "0", "0"},
[4300300108] = {4300300108, 13003001, 9, 5, "1_》_0_0.8", "level2", "乾杯！喜歡我的新口味“伏特加”嗎？", "かんぱーい！ウォッカを使った新しいドリンク、気に入った？", "0", "0", "0", "0", "cv_sk_kurimu_6", "0", "0"},
[4300300109] = {4300300109, 13003001, 10, 5, "1_》_0_0.8", "level3", "我突然想起件重要的事，一件必須和領航一起才能做的事，不過這件事還是等喝完了酒再說吧。", "そうだ。大事な話があるんだった。ナビゲーターと一緒じゃないとできないこと。でもまぁ、お酒を飲み終わってからでいいよね。", "0", "0", "0", "0", "cv_sk_kurimu_7", "0", "0"},
[4300300110] = {4300300110, 13003001, 11, 5, "1_》_0_0.8", "level4", "現在的我在你眼中一定很奇怪吧。不用否認，領航的眼睛已經告訴我了。但這只是幻覺，是喝醉之後的正常現象。請放心，正常的我一直都陪在領航身邊。", "今のあたし、すごく変に見えてるんじゃない？へへ。否定しないくていいよ。ナビゲーターの目を見れば分かるから。でも、これは幻覚。酔ってるんだもん、當たり前だよね。安心していいよ。いつものあたしは、ずっとナビゲーターの傍にいるから。", "0", "0", "0", "0", "cv_sk_kurimu_8", "0", "0"},
[4300300111] = {4300300111, 13003001, 12, 6, "0", "0", "Колбаса！", "0", "0", "0", "0", "0", "cv_sk_kurimu_9", "0", "0"},
[4300300112] = {4300300112, 13003001, 13, 7, "0", "0", "ура乾杯！", "0", "0", "0", "0", "0", "cv_sk_kurimu_10", "0", "0"},
[4300300113] = {4300300113, 13003001, 14, 8, "0", "0", "終於到了最後的階段了啊，ура萬歲！真是件值得慶祝的事情，不如今晚我們一起去喝一杯吧？", "0", "0", "0", "0", "0", "cv_sk_kurimu_11", "0", "0"},
[4300300114] = {4300300114, 13003001, 15, 9, "0", "0", "Борщ甜菜湯！", "0", "0", "0", "0", "0", "cv_sk_kurimu_12", "0", "0"},
[4300300115] = {4300300115, 13003001, 16, 10, "0", "0", "品嘗一下我的精釀吧。", "あたしの特製ドリンク、どう？", "0", "0", "0", "0", "cv_sk_kurimu_13", "0", "0"},
[4300300116] = {4300300116, 13003001, 17, 11, "0", "0", "怎麼樣？我的後勤工作做得不錯吧。", "0", "0", "0", "0", "0", "cv_sk_kurimu_14", "0", "0"},
[4300300117] = {4300300117, 13003001, 18, 12, "0", "0", "任務完成！該回去吃飯啦~", "0", "0", "0", "0", "0", "cv_sk_kurimu_15", "0", "0"},
[4300300118] = {4300300118, 13003001, 19, 13, "0", "0", "下次再努力吧，只是一次小失誤而已啦，來吃點東西打起精神吧！", "0", "0", "0", "0", "0", "cv_sk_kurimu_16", "0", "0"},
[4300300119] = {4300300119, 13003001, 20, 14, "0", "0", "唔啊啊，感覺頭暈暈的呢。", "0", "0", "0", "0", "0", "cv_sk_kurimu_17", "0", "0"},
[4300300120] = {4300300120, 13003001, 23, 16, "0", "0", "嘗嘗這個吧。", "0", "0", "0", "0", "0", "cv_sk_kurimu_18", "0", "0"},
[4300300121] = {4300300121, 13003001, 26, 19, "0", "0", "筋疲……力盡了。", "疲れた……もうクタクタだよ。", "0", "0", "0", "0", "cv_sk_kurimu_19", "0", "0"},
[4300300122] = {4300300122, 13003001, 27, 20, "0", "0", "欸嘿嘿~要被你看光啦~", "0", "0", "0", "0", "0", "cv_sk_kurimu_20", "0", "0"},
[4300300123] = {4300300123, 13003001, 28, 21, "0", "0", "欸？原來艾吉斯的澡堂裡不能邊吃邊洗嗎？", "0", "0", "0", "0", "0", "cv_sk_kurimu_21", "0", "0"},
[4300300124] = {4300300124, 13003001, 29, 21, "0", "0", "下次要不要往水箱裏參點威士卡呢？", "0", "0", "0", "0", "0", "cv_sk_kurimu_22", "0", "0"},
