[4300300126] = {4300300126, 13003001, 31, 23, "0", "0", "來吧，來吧~身為我的摯友你應該不會認錯人吧。", "0", "0", "0", "0", "0", "cv_sk_kurimu_24", "0", "0"},
[4300300127] = {4300300127, 13003001, 32, 24, "0", "0", "ура萬歲！", "0", "0", "0", "0", "0", "cv_sk_kurimu_25", "0", "0"},
[4300300128] = {4300300128, 13003001, 33, 25, "0", "0", "果然，喝酒誤事啊。", "0", "0", "0", "0", "0", "cv_sk_kurimu_26", "0", "0"},
[4300300129] = {4300300129, 13003001, 34, 26, "0", "0", "我就知道領航肯定忍不了這股酒香。", "ナビゲーターはこのお酒の香り、ガマンできないはずだよね。", "0", "0", "0", "0", "cv_sk_kurimu_29", "0", "0"},
[4300300130] = {4300300130, 13003001, 35, 27, "0", "0", "真好啊，我也想成為故事的主角呢。", "0", "0", "0", "0", "0", "cv_sk_kurimu_31", "0", "0"},
[4300300131] = {4300300131, 13003001, 36, 28, "0", "0", "ура！向著高處邁步吧！", "0", "0", "0", "0", "0", "cv_sk_kurimu_32", "0", "0"},
