[4301400108] = {4301400108, 13014001, 9, 5, "15_1_0_0.8", "level1", "感覺被曬暈了……領航，你剛才摸我了嗎？", "0", "0", "0", "0", "0", "cv_sk_momoca_6", "0", "0"},
[4301400109] = {4301400109, 13014001, 10, 5, "15_2_0_0.8", "level2", "海水冰涼涼的，好想跳進海裏給身體降降溫，就像這些魚兒一樣。可是我並不游泳……領航你能教教我游泳的技巧嗎？", "0", "0", "0", "0", "0", "cv_sk_momoca_7", "0", "0"},
[4301400110] = {4301400110, 13014001, 11, 5, "15_1_0_0.8", "level1", "領航你也感覺炎熱難耐嗎？可以坐到我邊上像我一樣將腳泡在海水裏降溫。順便也可以教我怎麼塗防曬霜。", "0", "0", "0", "0", "0", "cv_sk_momoca_8", "0", "0"},
[4301400111] = {4301400111, 13014001, 12, 6, "0", "0", "領航不會感到冷麼？", "0", "0", "0", "0", "0", "cv_sk_momoca_9", "0", "0"},
