[4301400141] = {4301400141, 13014001, 45, 37, "0", "0", "這是？", "0", "0", "0", "0", "0", "cv_sk_momoca_42", "0", "0"},
[4301900100] = {4301900100, 13019001, 1, 1, "0", "0", "蒼霧殘響", "ハツリバーブ。", "0", "0", "0", "0", "cv_sk_zhaowu_1", "0", "0"},
[4301900101] = {4301900101, 13019001, 2, 2, "0", "0", "這樣真的好嗎……讓我這樣的罪人站在這裏……", "本當に良いのでしょうか……わたくしのような罪深い者がここにいて……", "0", "0", "0", "0", "cv_sk_zhaowu_2", "0", "0"},
[4301900102] = {4301900102, 13019001, 3, 3, "0", "0", "初次見面，我是來自“學宮”的……啊，不，現在應該叫平心社了……我是平心社的朝霧，小……小女子不才，我……我會全心全意支援領航的。", "初めてお目にかかります。學宮（がっきゅう）……あ、いえ。今は平心社（へいしんしゃ）の朝霧（ちょうむ）と申します。ふ、不束者ですが、全身全霊でナビゲーターをお支えします。", "0", "0", "0", "0", "cv_sk_zhaowu_3", "0", "0"},
[4301900103] = {4301900103, 13019001, 4, 4, "0", "idle", "“學宮”……是我出身、長大的地方，一個能讓人能靜下心來讀書的地方……但是我現在已經不用回去了。沒事的……是我自己決定出來的，我是為了領航，也是為了我自己而來的。", "學宮……わたくしが生まれ育ち、心靜かに學ぶことができた場所。……でももう帰ることはありません。……わたくし自身のために、そしてナビゲーターのために……自分で決斷したのです。", "0", "0", "0", "0", "cv_sk_zhaowu_4", "0", "0"},
[4301900104] = {4301900104, 13019001, 5, 4, "0", "idle", "我覺得……領航就是我們一直在等待的人。我們“平心社”的責任，我的目標在遇見領航的時候就已經完成了，接下來只需要陪伴著您就好了。", "わたくし達が待ち望んでいたのはきっと……ナビゲーターです。平心社の目的と使命は、あなたと出會った瞬間に達成されました。これからは、あなたの傍にいるだけで良いのです。", "0", "0", "0", "0", "cv_sk_zhaowu_5", "0", "0"},
[4301900105] = {4301900105, 13019001, 6, 4, "0", "idle", "我認為領航的存在比任何人都重要——所以在危險的時候，請毫不留情地使用我吧，能和您經歷過這麼多事情，我已經很滿足了。", "ナビゲーターは誰よりも重要な存在です。危険な時は迷わずわたくしを盾にしてください。あなたと多くの時間を共有することができて、わたくしはもう十分満足です。", "0", "0", "0", "0", "cv_sk_zhaowu_6", "0", "0"},
[4301900106] = {4301900106, 13019001, 7, 5, "15_1_0_0.8", "level1", "領航，請不要……碰觸我這個戴罪之人。", "ナビゲーター……どうかこの咎人に觸れないでください。", "0", "0", "0", "0", "cv_sk_zhaowu_7", "0", "0"},
[4301900107] = {4301900107, 13019001, 8, 5, "15_2_0_0.8", "level2", "有更值得您去陪伴的駕駛員，領航，為什麼要呆在我身邊呢。", "わたくしよりも、傍にいるべきドライバーがいるはずです。なのにどうして……？", "0", "0", "0", "0", "cv_sk_zhaowu_8", "0", "0"},
[4301900108] = {4301900108, 13019001, 9, 5, "15_1_0_0.8", "level1", "我是作為罪人降生在這個世界上的，但是謝謝您能相信我。您允許我站在您的身邊，不知道為什麼……讓我感到放鬆。", "咎人としてこの世に生を受けたわたくしを信じてくださって、ありがとうございます。あなたの隣はなぜか……心が安らぐのです。", "0", "0", "0", "0", "cv_sk_zhaowu_9", "0", "0"},
[4301900109] = {4301900109, 13019001, 10, 5, "15_2_0_0.8", "level2", "我犯下了什麼過錯……您無需擔心，相伴在您身邊的每一天，便是在贖罪的每一天，但是——我希望您知道，我並不是為了贖罪待在您身邊的，而是我希望，我想要……我憧憬著您。", "わたくしが犯した罪、ですか……どうか、お気になさらないでください。あなたのそばにいる毎日が償いの日々ですが……罪滅ぼしのためにあなたの傍にいるのではありません。わたくしが……わたくしがあなたに憧れているからです。", "0", "0", "0", "0", "cv_sk_zhaowu_10", "0", "0"},
[4301900110] = {4301900110, 13019001, 11, 5, "15_1_0_0.8", "level1", "領航……領航……", "ナビゲーター……ナビゲーター……", "0", "0", "0", "0", "cv_sk_zhaowu_11", "0", "0"},
[4301900111] = {4301900111, 13019001, 12, 6, "0", "0", "呼，這……這是給我的嗎？", "こ…これをわたくしに……？", "0", "0", "0", "0", "cv_sk_zhaowu_12", "0", "0"},
[4301900112] = {4301900112, 13019001, 13, 7, "0", "0", "就算您習以為常，我依然能感受到其中真實的心意。", "あなたにとっては當たり前のことかもしれませんが、わたくしは真心を感じています。", "0", "0", "0", "0", "cv_sk_zhaowu_13", "0", "0"},
[4301900113] = {4301900113, 13019001, 14, 8, "0", "0", "呼……呼……呼……我做到了，我……現在感覺很好，很安心。", "はぁ、はぁ……成し遂げました。いま……とっても、ホッとしています。", "0", "0", "0", "0", "cv_sk_zhaowu_14", "0", "0"},
[4301900114] = {4301900114, 13019001, 15, 9, "0", "0", "我的力量，全部都……為您所用。", "わたくしの力すべてを……あなたに捧げます。", "0", "0", "0", "0", "cv_sk_zhaowu_15", "0", "0"},
[4301900115] = {4301900115, 13019001, 16, 10, "0", "0", "平心社，“天醫”朝霧，抵達戰場。", "平心社の天醫（てんい）、朝霧。ここにあり。", "0", "0", "0", "0", "cv_sk_zhaowu_16", "0", "0"},
[4301900116] = {4301900116, 13019001, 17, 11, "0", "0", "成功了……你看到了嗎，領航！", "やりました……見ていただけましたか、ナビゲーター！", "0", "0", "0", "0", "cv_sk_zhaowu_17", "0", "0"},
[4301900117] = {4301900117, 13019001, 18, 12, "0", "0", "如果有受傷一定要馬上和我講哦。", "もし怪我をしたらすぐわたくしにおっしゃってください。", "0", "0", "0", "0", "cv_sk_zhaowu_18", "0", "0"},
[4301900118] = {4301900118, 13019001, 19, 13, "0", "0", "如果沒有我參戰……領航一定會獲得更完美的勝利吧。", "わたくしさえいなければ……きっとナビゲーターは完璧な勝利を手にされていたはず……", "0", "0", "0", "0", "cv_sk_zhaowu_19", "0", "0"},
[4301900119] = {4301900119, 13019001, 20, 14, "0", "0", "嗚……領航……您先走，我……隨後就到。", "うぅ……ナビゲーター、早くお逃げください……わたくしが背中をお守りします。", "0", "0", "0", "0", "cv_sk_zhaowu_20", "0", "0"},
[4301900120] = {4301900120, 13019001, 23, 16, "0", "0", "哪裡受傷了嗎？", "どこを怪我されたんですか？", "0", "0", "0", "0", "cv_sk_zhaowu_21", "0", "0"},
[4301900121] = {4301900121, 13019001, 26, 19, "0", "0", "讓我……看看傷口。", "傷口をお見せください。", "0", "0", "0", "0", "cv_sk_zhaowu_22", "0", "0"},
[4301900122] = {4301900122, 13019001, 25, 18, "0", "0", "我要在這裏償還我身為“天醫”的人之罪，我不會再讓你們傷害到大家的。", "「天醫」即ち「人の罪」。これがその償い。二度と仲間を傷つけさせません。", "0", "0", "0", "0", "cv_sk_zhaowu_23", "0", "0"},
[4301900123] = {4301900123, 13019001, 24, 17, "0", "0", "這份罪責，我還清了嗎……？", "罪を償えたでしょうか……", "0", "0", "0", "0", "cv_sk_zhaowu_24", "0", "0"},
[4301900124] = {4301900124, 13019001, 27, 20, "0", "0", "啊……如果您不嫌棄的話……", "あ……もし……あなたさえ良ければ……", "0", "0", "0", "0", "cv_sk_zhaowu_25", "0", "0"},
[4301900125] = {4301900125, 13019001, 28, 21, "0", "0", "在開始之前，請戴好護具，保護好自己……", "最初に防具を著用し、ご自分の體をお守りください……", "0", "0", "0", "0", "cv_sk_zhaowu_26", "0", "0"},
[4301900126] = {4301900126, 13019001, 29, 21, "0", "0", "還沒有開始嗎……沒關係，在您做好準備之前，我會一直忍耐的。", "まだ始まらないんですね……大丈夫です。準備が整うまでお待ちします。", "0", "0", "0", "0", "cv_sk_zhaowu_27", "0", "0"},
[4301900127] = {4301900127, 13019001, 30, 22, "0", "0", "需要我來幫您一起嗎……雖然我可能……起不到什麼作用。", "お手伝いいたしましょうか……何の役にも立たないかもしれませんが……", "0", "0", "0", "0", "cv_sk_zhaowu_28", "0", "0"},
[4301900128] = {4301900128, 13019001, 31, 23, "0", "0", "領航……您……還記得我？", "ナビゲーター……わたくしのこと、覚えていらっしゃいますよね？", "0", "0", "0", "0", "cv_sk_zhaowu_29", "0", "0"},
[4301900129] = {4301900129, 13019001, 32, 24, "0", "0", "呼……謝謝您。", "ふぅ……ありがとうございます。", "0", "0", "0", "0", "cv_sk_zhaowu_30", "0", "0"},
[4301900130] = {4301900130, 13019001, 33, 25, "0", "0", "這也是沒辦法的事情……畢竟是我啊……", "當然でしょうね……わたくしですから……", "0", "0", "0", "0", "cv_sk_zhaowu_31", "0", "0"},
[4301900131] = {4301900131, 13019001, 34, 26, "0", "0", "安心……像是回到了學宮一樣。", "なんだか安心します……まるで學宮に帰ったみたいに……", "0", "0", "0", "0", "cv_sk_zhaowu_32", "0", "0"},
[4301900132] = {4301900132, 13019001, 35, 27, "0", "0", "要上戰場了……", "戦場ですね……お任せください。", "0", "0", "0", "0", "cv_sk_zhaowu_33", "0", "0"},
[4301900133] = {4301900133, 13019001, 36, 28, "0", "0", "演習也會出現傷患……", "演習でも負傷者が出るかもしれませんね……", "0", "0", "0", "0", "cv_sk_zhaowu_34", "0", "0"},
[4301900134] = {4301900134, 13019001, 37, 29, "0", "0", "大家都好好的，真好呀。", "皆さんお元気で、何よりです。", "0", "0", "0", "0", "cv_sk_zhaowu_35", "0", "0"},
[4301900135] = {4301900135, 13019001, 38, 30, "0", "0", "您要去找新的陪伴者了嗎……", "新しいパートナーを探しに行くんですか？", "0", "0", "0", "0", "cv_sk_zhaowu_36", "0", "0"},
[4301900136] = {4301900136, 13019001, 39, 31, "0", "0", "出門要穿戴整齊哦。", "外出する際は、身なりを整えないと。", "0", "0", "0", "0", "cv_sk_zhaowu_37", "0", "0"},
[4301900137] = {4301900137, 13019001, 40, 32, "0", "0", "……我……我想要買本書可以嗎？", "本を……本を買いたいです……", "0", "0", "0", "0", "cv_sk_zhaowu_38", "0", "0"},
[4301900138] = {4301900138, 13019001, 41, 33, "0", "0", "檔案上有您的照片。", "あなたの寫真がありますね。", "0", "0", "0", "0", "cv_sk_zhaowu_39", "0", "0"},
[4301900139] = {4301900139, 13019001, 42, 34, "0", "0", "這裏是調整設置的地方。", "セッティングを調整できます。", "0", "0", "0", "0", "cv_sk_zhaowu_40", "0", "0"},
[4301900140] = {4301900140, 13019001, 43, 35, "0", "0", "會有新的來信嗎？", "新しいメールは來ているでしょうか？", "0", "0", "0", "0", "cv_sk_zhaowu_41", "0", "0"},
[4301900141] = {4301900141, 13019001, 44, 36, "0", "0", "領航的聊天……我……我也被允許一起看嗎？", "ナビゲーターのチャット……わ、わたくしも拝見していいでしょうか？", "0", "0", "0", "0", "cv_sk_zhaowu_42", "0", "0"},
[4301900142] = {4301900142, 13019001, 45, 37, "0", "0", "呼——", "ふぅ……", "0", "0", "0", "0", "cv_sk_zhaowu_43", "0", "0"},
[4302000100] = {4302000100, 13020001, 1, 1, "0", "0", "蒼霧殘響", "0", "0", "0", "0", "0", "cv_sk_mayball_1", "0", "0"},
[4302000101] = {4302000101, 13020001, 2, 2, "0", "0", "確定交由我嗎？事先說好，不保證能勝任哦。", "0", "0", "0", "0", "0", "cv_sk_mayball_2", "0", "0"},
[4302000102] = {4302000102, 13020001, 3, 3, "0", "0", "這裏是梅貝爾·伊司，薩哈拉蒼穹學院的一名哲學教師，隸屬於制蜜人小隊。唔，介紹應該就這些了……", "0", "0", "0", "0", "0", "cv_sk_mayball_3", "0", "0"},
[4302000103] = {4302000103, 13020001, 4, 4, "0", "idle", "這裏微風習習，碧浪疊沙，是個適合哲思的好歸宿。", "青い海に白い砂浜、そしてそよ風。哲學に耽るには最適な場所だね。", "0", "0", "0", "0", "cv_sk_mayball_4", "0", "0"},
[4302000104] = {4302000104, 13020001, 5, 4, "0", "idle", "來時忘記向學院遞交請假申請，我負責的課程恐怕都要停擺了。不過平時我也不怎麼去上課，我存在或者不存在，對於學生們來說大概也沒有區別。", "學院に休暇屆け出すのを忘れちゃったから、私の授業は全部休講になっちゃうのかな。でも、普段からあまり授業に出ていないし、生徒たちからしたら、私がいてもいなくても変わらないかもしれないね。", "0", "0", "0", "0", "cv_sk_mayball_5", "0", "0"},
[4302000105] = {4302000105, 13020001, 6, 4, "0", "idle", "只有親身浮於海上，我才能感覺到真正的自由。而與自由的我相比，普瑞席歐她們還被牢牢地拴在生活的牢籠之中。", "海の上に浮かんでるときは、本當の自由を感じることができるね。こんな自由な私とは対照的に、プレシオたちはまだ命の檻に囚われてる。", "0", "0", "0", "0", "cv_sk_mayball_6", "0", "0"},
[4302000106] = {4302000106, 13020001, 7, 5, "15_1_0_0.8", "level2", "我經常思考，巨大化後的我和本來的我有何不同。因為無論身體如何改變，我的思維意志並不會隨之改變。那巨大後的我是否真的超越了原本的我呢？", "巨大化した私と元の私はどう違うのか、よく考えるの。體がどんなに変わっても、思考や意志は変わらない。なら、巨大化した私は元の私を超えていると言えるのかな？", "0", "0", "0", "0", "cv_sk_mayball_7", "0", "0"},
[4302000107] = {4302000107, 13020001, 8, 5, "15_2_0_0.8", "level1", "在這舒適的環境中，反而變得愈加精神，我能清晰地感覺到思緒在大海上漂散……哈嗚~", "こんなに快適な環境の中だと、なんだかテンションが上がるね。思考が海のように広がっていくのを感じる…。…ふぅ～", "0", "0", "0", "0", "cv_sk_mayball_8", "0", "0"},
[4302000108] = {4302000108, 13020001, 9, 5, "15_1_0_0.8", "level2", "這裏的生物比我預想的更加活潑，可是對它們來說，是否會意識到自己的存在？又是否會因此感到困惑呢？領航同學覺得呢。", "ここの生物たちが思っていた以上に活発だけど、私たちの存在を認識しているのかな？そのせいで困惑しているのかも。ナビゲーターくんはどう思う？", "0", "0", "0", "0", "cv_sk_mayball_9", "0", "0"},
[4302000109] = {4302000109, 13020001, 10, 5, "15_2_0_0.8", "level1", "哈嗚~倦意又湧上來了，領航同學，接下來就只能依靠你了。在我睡著的時候，一定不要讓我被海浪卷走……", "ふぅ～疲れてきちゃった。ナビゲーターくん、あとは頼むね。私が寢てる間、波に流されないようにしてね……", "0", "0", "0", "0", "cv_sk_mayball_10", "0", "0"},
[4302000110] = {4302000110, 13020001, 11, 5, "15_1_0_0.8", "level2", "領航同學開始對哲學感興趣了嗎？那就請躺在我的胸口上與我一同閱讀這本書籍。難得單獨輔導的機會，有不解的觀點請直接問我吧。", "ナビゲーターくん、哲學に興味がわいてきたの？なら、私の胸の上に橫になって、この本を一緒に読もう。個別指導の機會なんてなかなか無いから、分からないことがあれば聞いてね。", "0", "0", "0", "0", "cv_sk_mayball_11", "0", "0"},
[4302000111] = {4302000111, 13020001, 12, 6, "0", "0", "哈嗚~謝謝。", "0", "0", "0", "0", "0", "cv_sk_mayball_12", "0", "0"},
[4302000112] = {4302000112, 13020001, 13, 7, "0", "0", "思維更清晰了，像在品一杯冰咖啡。", "0", "0", "0", "0", "0", "cv_sk_mayball_13", "0", "0"},
[4302000113] = {4302000113, 13020001, 14, 8, "0", "0", "“覺醒”嗎？這詞真不適合我呢，說不定我下一秒就會睡著。但領航同學一直對我有所期待，果然我還是拿出十足的幹勁吧~", "0", "0", "0", "0", "0", "cv_sk_mayball_14", "0", "0"},
[4302000114] = {4302000114, 13020001, 15, 9, "0", "0", "用思想武裝自己呢。", "0", "0", "0", "0", "0", "cv_sk_mayball_15", "0", "0"},
[4302000115] = {4302000115, 13020001, 16, 10, "0", "0", "闊別已久的戰場啊。", "0", "0", "0", "0", "0", "cv_sk_mayball_16", "0", "0"},
[4302000116] = {4302000116, 13020001, 17, 11, "0", "0", "哎呀，不小心發揮超常了。", "0", "0", "0", "0", "0", "cv_sk_mayball_17", "0", "0"},
[4302000117] = {4302000117, 13020001, 18, 12, "0", "0", "不完美才是人生的常態，不用在意哦。", "0", "0", "0", "0", "0", "cv_sk_mayball_18", "0", "0"},
[4302000118] = {4302000118, 13020001, 19, 13, "0", "0", "這樣下去沒法給學生們當榜樣了呢。", "0", "0", "0", "0", "0", "cv_sk_mayball_19", "0", "0"},
[4302000119] = {4302000119, 13020001, 20, 14, "0", "0", "果然下次作戰把我換掉更好吧~？", "0", "0", "0", "0", "0", "cv_sk_mayball_20", "0", "0"},
[4302000120] = {4302000120, 13020001, 23, 16, "0", "0", "同學們，加油。", "みんな、頑張って。", "0", "0", "0", "0", "cv_sk_mayball_21", "0", "0"},
[4302000121] = {4302000121, 13020001, 26, 19, "0", "0", "已經很厲害了。", "もう十分強いよね。", "0", "0", "0", "0", "cv_sk_mayball_22", "0", "0"},
[4302000122] = {4302000122, 13020001, 24, 17, "0", "0", "讓我再……睡一會兒……", "もうちょっと、寢かせて……", "0", "0", "0", "0", "cv_sk_mayball_23", "0", "0"},
[4302000123] = {4302000123, 13020001, 27, 20, "0", "0", "為了更好地思考，讓我們洗卻身體的疲憊吧~", "0", "0", "0", "0", "0", "cv_sk_mayball_24", "0", "0"},
[4302000124] = {4302000124, 13020001, 28, 21, "0", "0", "哈嗚~這裏比外面更容易讓人發困，領航同學可不能比我先睡著哦。", "0", "0", "0", "0", "0", "cv_sk_mayball_25", "0", "0"},
[4302000125] = {4302000125, 13020001, 29, 21, "0", "0", "古時起，薩哈拉的哲學家們就喜歡在浴場討論問題，領航同學此刻也有想要知曉的問題嗎？", "0", "0", "0", "0", "0", "cv_sk_mayball_26", "0", "0"},
[4302000126] = {4302000126, 13020001, 30, 22, "0", "0", "遊戲時間開始~", "0", "0", "0", "0", "0", "cv_sk_mayball_27", "0", "0"},
[4302000127] = {4302000127, 13020001, 31, 23, "0", "0", "那麼答案是什麼呢？", "0", "0", "0", "0", "0", "cv_sk_mayball_28", "0", "0"},
[4302000128] = {4302000128, 13020001, 32, 24, "0", "0", "答對了，一百分！", "0", "0", "0", "0", "0", "cv_sk_mayball_29", "0", "0"},
[4302000129] = {4302000129, 13020001, 33, 25, "0", "0", "很遺憾，不及格呢~", "0", "0", "0", "0", "0", "cv_sk_mayball_30", "0", "0"},
[4302000130] = {4302000130, 13020001, 34, 26, "0", "0", "你剛才去哪了？來我這邊躺下繼續閱讀書籍吧。", "どこにいってたの？こっちで橫になって、一緒に本を読もうよ。", "0", "0", "0", "0", "cv_sk_mayball_31", "0", "0"},
[4302000131] = {4302000131, 13020001, 35, 27, "0", "0", "該認真起來了嗎？", "0", "0", "0", "0", "0", "cv_sk_mayball_32", "0", "0"},
[4302000132] = {4302000132, 13020001, 36, 28, "0", "0", "模擬戰就隨意點吧。", "0", "0", "0", "0", "0", "cv_sk_mayball_33", "0", "0"},
[4302000133] = {4302000133, 13020001, 37, 29, "0", "0", "突擊檢查~有開小差的同學嗎？", "0", "0", "0", "0", "0", "cv_sk_mayball_34", "0", "0"},
[4302000134] = {4302000134, 13020001, 38, 30, "0", "0", "謔~要出現神秘轉校生了。", "0", "0", "0", "0", "0", "cv_sk_mayball_35", "0", "0"},
[4302000135] = {4302000135, 13020001, 39, 31, "0", "0", "會得到什麼呢？稍微期待下吧。", "0", "0", "0", "0", "0", "cv_sk_mayball_36", "0", "0"},
[4302000136] = {4302000136, 13020001, 40, 32, "0", "0", "幫忙留意下新款睡衣哦。", "0", "0", "0", "0", "0", "cv_sk_mayball_37", "0", "0"},
[4302000137] = {4302000137, 13020001, 41, 33, "0", "0", "看看領航同學的志向填了什麼。", "0", "0", "0", "0", "0", "cv_sk_mayball_38", "0", "0"},
[4302000138] = {4302000138, 13020001, 42, 34, "0", "0", "領航同學真講究呢~", "0", "0", "0", "0", "0", "cv_sk_mayball_39", "0", "0"},
[4302000139] = {4302000139, 13020001, 43, 35, "0", "0", "比起口頭交流，果然文字更方便呢。", "0", "0", "0", "0", "0", "cv_sk_mayball_40", "0", "0"},
[4302000140] = {4302000140, 13020001, 44, 36, "0", "0", "有什麼想對大家說的呢？", "0", "0", "0", "0", "0", "cv_sk_mayball_41", "0", "0"},
[4302000141] = {4302000141, 13020001, 45, 37, "0", "0", "好、好。", "0", "0", "0", "0", "0", "cv_sk_mayball_42", "0", "0"},
[4302100100] = {4302100100, 13021001, 1, 1, "0", "0", "蒼~霧~殘~響~", "0", "0", "0", "0", "0", "cv_sk_hoshii_1", "0", "0"},
[4302100101] = {4302100101, 13021001, 2, 2, "0", "0", "用九州的神秘學理論來說就是——這裏的風水不錯。", "0", "0", "0", "0", "0", "cv_sk_hoshii_2", "0", "0"},
[4302100102] = {4302100102, 13021001, 3, 3, "0", "0", "我是星井伯納蒂，您的人生指引者。我可以稱呼你為“領航哥哥”嗎？", "0", "0", "0", "0", "0", "cv_sk_hoshii_3", "0", "0"},
[4302100103] = {4302100103, 13021001, 4, 4, "0", "idle", "來自無邊思緒之上的無上之光，請照亮迷惑靈魂飄蕩的方向。", "0", "0", "0", "0", "0", "cv_sk_hoshii_4", "0", "0"},
[4302100104] = {4302100104, 13021001, 5, 4, "0", "idle", "占卜的結果是……晚飯吃拉麵。", "0", "0", "0", "0", "0", "cv_sk_hoshii_5", "0", "0"},
[4302100105] = {4302100105, 13021001, 6, 4, "0", "idle", "我呀，昨天偷偷給其他人占卜了一下未來。小螢草和花語的命運清晰而寧靜，但心紙姐姐她……嗯……領航哥哥還是不要知道比較好。", "0", "0", "0", "0", "0", "cv_sk_hoshii_6", "0", "0"},
[4302100106] = {4302100106, 13021001, 7, 5, "15_1_0_0.8", "touch1", "巫女和占卜師的在我看來並沒有區別，都是幫助迷茫的人尋找人生的希望。不過巫女可以穿可愛的巫女服。", "0", "0", "0", "0", "0", "cv_sk_hoshii_7", "0", "0"},
[4302100107] = {4302100107, 13021001, 8, 5, "15_2_0_0.8", "touch1", "別……別打擾我的冥想……我正在……接受……思維世界先賢的……智慧……呼——（呼嚕聲）", "0", "0", "0", "0", "0", "cv_sk_hoshii_8", "0", "0"},
[4302100108] = {4302100108, 13021001, 9, 5, "15_1_0_0.8", "touch2", "誒？領航哥哥還要再占卜一次嗎？可以是可以啦，不過就算再占卜一千次，結果也不會變的——黑色的光自月亮開始吞沒了太陽與大地……", "0", "0", "0", "0", "0", "cv_sk_hoshii_9", "0", "0"},
[4302100109] = {4302100109, 13021001, 10, 5, "15_2_0_0.8", "touch1", "不必過於擔心“黑光”，占卜的結果僅僅是未來的推演而已，真正的未來並不一定會發生那樣的事。更何況，還有我在領航哥哥身邊。", "0", "0", "0", "0", "0", "cv_sk_hoshii_10", "0", "0"},
[4302100110] = {4302100110, 13021001, 11, 5, "15_1_0_0.8", "touch2", "母親的占卜結果說，我將會與一位千轉輪回之人產生超越群體潛意識控制的深度交融。現在我越來越確定，那個千轉輪回之人就是你——領航哥哥。", "0", "0", "0", "0", "0", "cv_sk_hoshii_11", "0", "0"},
[4302100111] = {4302100111, 13021001, 12, 6, "0", "0", "靈感提升。", "0", "0", "0", "0", "0", "cv_sk_hoshii_12", "0", "0"},
[4302100112] = {4302100112, 13021001, 13, 7, "0", "0", "與思維世界的感應更緊密了。", "0", "0", "0", "0", "0", "cv_sk_hoshii_13", "0", "0"},
[4302100113] = {4302100113, 13021001, 14, 8, "0", "0", "世界的枝條在我眼前舒展，未來的定格照正在一張一張覆蓋。唯一的光將消融黑色，那便是領航哥哥你。", "0", "0", "0", "0", "0", "cv_sk_hoshii_14", "0", "0"},
[4302100114] = {4302100114, 13021001, 15, 9, "0", "0", "要保持水晶球的清潔。", "0", "0", "0", "0", "0", "cv_sk_hoshii_15", "0", "0"},
[4302100115] = {4302100115, 13021001, 16, 10, "0", "0", "我來占卜一下戰鬥的結果。", "0", "0", "0", "0", "0", "cv_sk_hoshii_16", "0", "0"},
[4302100116] = {4302100116, 13021001, 17, 11, "0", "0", "占卜的結果是——完全勝利！", "0", "0", "0", "0", "0", "cv_sk_hoshii_17", "0", "0"},
[4302100117] = {4302100117, 13021001, 18, 12, "0", "0", "和占卜結果基本符合。", "0", "0", "0", "0", "0", "cv_sk_hoshii_18", "0", "0"},
[4302100118] = {4302100118, 13021001, 19, 13, "0", "0", "勉強成功——改寫必輸的命運。", "0", "0", "0", "0", "0", "cv_sk_hoshii_19", "0", "0"},
[4302100119] = {4302100119, 13021001, 20, 14, "0", "0", "未來無法改變嗎？", "0", "0", "0", "0", "0", "cv_sk_hoshii_20", "0", "0"},
[4302100120] = {4302100120, 13021001, 23, 16, "0", "0", "機會只有一次。", "0", "0", "0", "0", "0", "cv_sk_hoshii_21", "0", "0"},
[4302100121] = {4302100121, 13021001, 26, 19, "0", "0", "水晶球碎了……", "0", "0", "0", "0", "0", "cv_sk_hoshii_23", "0", "0"},
[4302100122] = {4302100122, 13021001, 24, 17, "0", "0", "你的生命之河不會在此斷流。", "0", "0", "0", "0", "0", "cv_sk_hoshii_22", "0", "0"},
[4302100123] = {4302100123, 13021001, 27, 20, "0", "0", "哇哦！好大的澡堂。", "0", "0", "0", "0", "0", "cv_sk_hoshii_24", "0", "0"},
[4302100124] = {4302100124, 13021001, 28, 21, "0", "0", "領航哥哥能幫我搓下背嗎？", "0", "0", "0", "0", "0", "cv_sk_hoshii_25", "0", "0"},
[4302100125] = {4302100125, 13021001, 29, 21, "0", "0", "在這裏冥想效率會變高吧。", "0", "0", "0", "0", "0", "cv_sk_hoshii_26", "0", "0"},
[4302100126] = {4302100126, 13021001, 30, 22, "0", "0", "需要占卜的幫助嗎？", "0", "0", "0", "0", "0", "cv_sk_hoshii_27", "0", "0"},
[4302100127] = {4302100127, 13021001, 31, 23, "0", "0", "應該不需要我的引導吧。", "0", "0", "0", "0", "0", "cv_sk_hoshii_28", "0", "0"},
[4302100128] = {4302100128, 13021001, 32, 24, "0", "0", "果然領航哥哥的命運與我是相連的。", "0", "0", "0", "0", "0", "cv_sk_hoshii_29", "0", "0"},
[4302100129] = {4302100129, 13021001, 33, 25, "0", "0", "難道我又占卜錯了？", "0", "0", "0", "0", "0", "cv_sk_hoshii_30", "0", "0"},
[4302100130] = {4302100130, 13021001, 34, 26, "0", "0", "三，二，一，嘻嘻，我早就通過占卜算到領航哥哥回來的時間了。", "0", "0", "0", "0", "0", "cv_sk_hoshii_31", "0", "0"},
[4302100131] = {4302100131, 13021001, 35, 27, "0", "0", "戰前的占卜儀式很重要。", "0", "0", "0", "0", "0", "cv_sk_hoshii_32", "0", "0"},
[4302100132] = {4302100132, 13021001, 36, 28, "0", "0", "如果提前知道結果就不好玩了哦。", "0", "0", "0", "0", "0", "cv_sk_hoshii_33", "0", "0"},
[4302100133] = {4302100133, 13021001, 37, 29, "0", "0", "哥哥的桃花運真旺啊。", "0", "0", "0", "0", "0", "cv_sk_hoshii_34", "0", "0"},
[4302100134] = {4302100134, 13021001, 38, 30, "0", "0", "想知道下一個出現的是誰嗎？領航哥哥。", "0", "0", "0", "0", "0", "cv_sk_hoshii_35", "0", "0"},
[4302100135] = {4302100135, 13021001, 39, 31, "0", "0", "水晶球顯現出金色的光芒。", "0", "0", "0", "0", "0", "cv_sk_hoshii_36", "0", "0"},
[4302100136] = {4302100136, 13021001, 40, 32, "0", "0", "那件道具……充滿了能量。", "0", "0", "0", "0", "0", "cv_sk_hoshii_37", "0", "0"},
[4302100137] = {4302100137, 13021001, 41, 33, "0", "0", "領航哥哥的名字擁有強大的能量。", "0", "0", "0", "0", "0", "cv_sk_hoshii_38", "0", "0"},
[4302100138] = {4302100138, 13021001, 42, 34, "0", "0", "能改變什麼呢？", "0", "0", "0", "0", "0", "cv_sk_hoshii_39", "0", "0"},
[4302100139] = {4302100139, 13021001, 43, 35, "0", "0", "我有一封來自未來的信。", "0", "0", "0", "0", "0", "cv_sk_hoshii_40", "0", "0"},
[4302100140] = {4302100140, 13021001, 44, 36, "0", "0", "這麼多人我可占卜不過來。", "0", "0", "0", "0", "0", "cv_sk_hoshii_41", "0", "0"},
[4302100141] = {4302100141, 13021001, 45, 37, "0", "0", "哦吼？", "0", "0", "0", "0", "0", "cv_sk_hoshii_42", "0", "0"},
[4400000100] = {4400000100, 14000001, 1, 1, "0", "0", "蒼霧殘響", "0", "0", "0", "0", "0", "cv_sk_starry2_1", "0", "0"},
[4400000101] = {4400000101, 14000001, 2, 2, "0", "0", "有沒有想我？我到是每天都在想你，色狼先生。", "0", "0", "0", "0", "0", "cv_sk_starry2_2", "0", "0"},
[4400000102] = {4400000102, 14000001, 3, 3, "0", "0", "色狼先生，這段時間有好好吃飯，好好休息嗎，感覺你消瘦了不少——我？沒事的，只是點小事故，跟喝水被嗆到沒區別。", "0", "0", "0", "0", "0", "cv_sk_starry2_3", "0", "0"},
[4400000103] = {4400000103, 14000001, 91, 4, "0", "idle", "將心沉寂在無邊的黑暗中，閉上雙眼感受到的是近乎海洋般浩瀚的力量。憑借著它，我大概能夠戰勝命運吧。", "0", "0", "0", "0", "0", "cv_sk_starry2_4", "0", "0"},
[4400000104] = {4400000104, 14000001, 91, 4, "0", "idle", "我漸漸明白了……幸運和不幸是一體兩面的，我既是幸運的，也是不幸的。我無法逃離自己的不幸，就像我離不開我的幸運一樣。", "0", "0", "0", "0", "0", "cv_sk_starry2_5", "0", "0"},
[4400000105] = {4400000105, 14000001, 94, 4, "0", "idle2", "我現在的狀況……該怎麼說呢，“我很好”……這樣也不會有人相信吧，但是沒關係，船到橋頭自然直，總會有辦法的。", "0", "0", "0", "0", "0", "cv_sk_starry2_6", "0", "0"},
[4400000106] = {4400000106, 14000001, 94, 4, "0", "idle2", "變成這副模樣之後，情緒會不受控制地高漲起來。真是不可思議，好像自己什麼都可以做到一樣。", "0", "0", "0", "0", "0", "cv_sk_starry2_46", "0", "0"},
[4400000107] = {4400000107, 14000001, 92, 5, "14_1_0_0.8", "touch1", "那種努力想要去抓住某種東西，卻只能眼睜睜地看著它從指縫間流失的感覺……真的是最糟了，光是我體驗就已經足夠了……我不會讓你感同身受的，領航。", "0", "0", "0", "0", "0", "cv_sk_starry2_9", "0", "0"},
[4400000108] = {4400000108, 14000001, 92, 5, "14_1_0_0.8", "touch2", "感覺……說不定我會下地獄啊，要是真有那天的話，我要是大聲呼救的話……你會來救我嗎，我的領航。", "0", "0", "0", "0", "0", "cv_sk_starry2_10", "0", "0"},
[4400000109] = {4400000109, 14000001, 92, 5, "14_1_0_0.8", "touch3", "它在侵蝕，在奪走我的意識，在把我一點點拽向噩夢……但只要有你在，我的心就不會迷失，這點我可以向你保證。", "0", "0", "0", "0", "0", "cv_sk_starry2_11", "0", "0"},
[4400000110] = {4400000110, 14000001, 93, 5, "14_2_0_0.8", "touch_s1", "……怎麼了，不行了嗎？", "0", "0", "0", "0", "0", "cv_sk_starry2_49", "0", "0"},
[4400000111] = {4400000111, 14000001, 95, 5, "14_1_0_0.8", "touch4", "嗯……突然想嘗嘗人類的味道了，就先從色狼先生開始吧——哈哈，開玩笑的，只是想說說這樣的臺詞而已，畢竟原罪也不會吃人類吧？……應該不會吧？", "0", "0", "0", "0", "0", "cv_sk_starry2_47", "0", "0"},
[4400000112] = {4400000112, 14000001, 95, 5, "14_1_0_0.8", "touch5", "如果是你的話，我覺得能做到吧，把你身上的，以及我身上的，所有人身上的“不幸”，全部反轉。", "0", "0", "0", "0", "0", "cv_sk_starry2_7", "0", "0"},
[4400000113] = {4400000113, 14000001, 95, 5, "14_1_0_0.8", "touch6", "如果犧牲自己的全部，卻連喜歡的人都幫不了的話，那也太可悲了。我這麼幸運，絕對不會淪落到那種結局的。", "0", "0", "0", "0", "0", "cv_sk_starry2_8", "0", "0"},
[4400000114] = {4400000114, 14000001, 96, 5, "14_2_0_0.8", "touch_s2", "逃跑是禁止事項。", "0", "0", "0", "0", "0", "cv_sk_starry2_48", "0", "0"},
[4400000115] = {4400000115, 14000001, 12, 6, "0", "0", "哈哈……手有點疼……", "0", "0", "0", "0", "0", "cv_sk_starry2_12", "0", "0"},
[4400000116] = {4400000116, 14000001, 13, 7, "0", "0", "還算在控制範圍吧。", "0", "0", "0", "0", "0", "cv_sk_starry2_13", "0", "0"},
[4400000117] = {4400000117, 14000001, 14, 8, "0", "0", "在燃盡之前綻放出最耀眼的光，這就是我要做的事。", "0", "0", "0", "0", "0", "cv_sk_starry2_14", "0", "0"},
[4400000118] = {4400000118, 14000001, 15, 9, "0", "0", "偶爾也想變得更耀眼一點。", "0", "0", "0", "0", "0", "cv_sk_starry2_15", "0", "0"},
[4400000119] = {4400000119, 14000001, 16, 10, "0", "0", "又能並肩作戰了呢。", "0", "0", "0", "0", "0", "cv_sk_starry2_16", "0", "0"},
[4400000120] = {4400000120, 14000001, 17, 11, "0", "0", "這次做到了，誰都沒有受傷。", "0", "0", "0", "0", "0", "cv_sk_starry2_17", "0", "0"},
[4400000121] = {4400000121, 14000001, 18, 12, "0", "0", "果然還是不夠走運啊。", "0", "0", "0", "0", "0", "cv_sk_starry2_18", "0", "0"},
[4400000122] = {4400000122, 14000001, 19, 13, "0", "0", "還要繼續嗎……", "0", "0", "0", "0", "0", "cv_sk_starry2_19", "0", "0"},
[4400000123] = {4400000123, 14000001, 20, 14, "0", "0", "我們……走吧。", "0", "0", "0", "0", "0", "cv_sk_starry2_20", "0", "0"},
[4400000124] = {4400000124, 14000001, 21, 15, "0", "0", "真不幸呢。", "0", "0", "0", "0", "0", "cv_sk_starry2_21", "0", "0"},
[4400000125] = {4400000125, 14000001, 23, 16, "0", "0", "死吧。", "0", "0", "0", "0", "0", "cv_sk_starry2_23", "0", "0"},
[4400000126] = {4400000126, 14000001, 24, 17, "0", "0", "你不走運呢。", "0", "0", "0", "0", "0", "cv_sk_starry2_24", "0", "0"},
[4400000127] = {4400000127, 14000001, 25, 18, "0", "0", "不會有事的，我保證。", "0", "0", "0", "0", "0", "cv_sk_starry2_25", "0", "0"},
[4400000128] = {4400000128, 14000001, 26, 19, "0", "0", "好痛……", "0", "0", "0", "0", "0", "cv_sk_starry2_26", "0", "0"},
[4400000129] = {4400000129, 14000001, 27, 20, "0", "0", "哈哈哈——讓我想起我們第一次見面的時候……“第一次”……", "0", "0", "0", "0", "0", "cv_sk_starry2_27", "0", "0"},
[4400000130] = {4400000130, 14000001, 28, 21, "0", "0", "那些東西……果然還是有點嚇人吧？不知道除黑頭的面膜能不能除去它們呢？", "0", "0", "0", "0", "0", "cv_sk_starry2_28", "0", "0"},
[4400000131] = {4400000131, 14000001, 29, 21, "0", "0", "疼疼疼……不知道那些有腎結石的人是不是也是這種感覺？", "0", "0", "0", "0", "0", "cv_sk_starry2_29", "0", "0"},
[4400000132] = {4400000132, 14000001, 30, 22, "0", "0", "發生好事了嗎？", "0", "0", "0", "0", "0", "cv_sk_starry2_30", "0", "0"},
[4400000133] = {4400000133, 14000001, 31, 23, "0", "0", "又要來嗎？", "0", "0", "0", "0", "0", "cv_sk_starry2_31", "0", "0"},
[4400000134] = {4400000134, 14000001, 32, 24, "0", "0", "這次我想直率的表達——我很高興，色狼先生。", "0", "0", "0", "0", "0", "cv_sk_starry2_32", "0", "0"},
[4400000135] = {4400000135, 14000001, 33, 25, "0", "0", "別在意~總會有錯的時候。", "0", "0", "0", "0", "0", "cv_sk_starry2_33", "0", "0"},
[4400000136] = {4400000136, 14000001, 34, 26, "0", "0", "……你回來啦，嗯，歡迎回來。", "0", "0", "0", "0", "0", "cv_sk_starry2_34", "0", "0"},
[4400000137] = {4400000137, 14000001, 35, 27, "0", "0", "好啦，戰場還在等著我們呢，出發吧。", "0", "0", "0", "0", "0", "cv_sk_starry2_35", "0", "0"},
[4400000138] = {4400000138, 14000001, 36, 28, "0", "0", "我不會讓給別人的。", "0", "0", "0", "0", "0", "cv_sk_starry2_36", "0", "0"},
[4400000139] = {4400000139, 14000001, 37, 29, "0", "0", "又多了些不認識的人呢。", "0", "0", "0", "0", "0", "cv_sk_starry2_37", "0", "0"},
[4400000140] = {4400000140, 14000001, 38, 30, "0", "0", "你還真是永不滿足呢。", "0", "0", "0", "0", "0", "cv_sk_starry2_38", "0", "0"},
[4400000141] = {4400000141, 14000001, 39, 31, "0", "0", "全力武裝自己，盡可能變強吧。", "0", "0", "0", "0", "0", "cv_sk_starry2_39", "0", "0"},
[4400000142] = {4400000142, 14000001, 40, 32, "0", "0", "有什麼想買的嗎？", "0", "0", "0", "0", "0", "cv_sk_starry2_40", "0", "0"},
[4400000143] = {4400000143, 14000001, 41, 33, "0", "0", "士別三日，刮目相看~", "0", "0", "0", "0", "0", "cv_sk_starry2_41", "0", "0"},
[4400000144] = {4400000144, 14000001, 42, 34, "0", "0", "怎麼了？", "0", "0", "0", "0", "0", "cv_sk_starry2_42", "0", "0"},
[4400000145] = {4400000145, 14000001, 43, 35, "0", "0", "又是女孩子的信嗎？", "0", "0", "0", "0", "0", "cv_sk_starry2_43", "0", "0"},
[4400000146] = {4400000146, 14000001, 44, 36, "0", "0", "真有精神啊。", "0", "0", "0", "0", "0", "cv_sk_starry2_44", "0", "0"},
[4400000147] = {4400000147, 14000001, 45, 37, "0", "0", "哈啊……", "0", "0", "0", "0", "0", "cv_sk_starry2_45", "0", "0"},
[4400100100] = {4400100100, 14001001, 1, 1, "0", "0", "蒼霧殘響", "0", "0", "0", "0", "0", "cv_sk_korsgaard_1", "0", "0"},
[4400100101] = {4400100101, 14001001, 2, 2, "0", "0", "雖然不擅長，但我相信你的選擇。", "0", "0", "0", "0", "0", "cv_sk_korsgaard_2", "0", "0"},
[4400100102] = {4400100102, 14001001, 3, 3, "0", "0", "沒想到重逢來得這麼快，領航。多餘的寒暄就留在日後吧，我——珀因雷德教會騎士團長珂斯嘉德，期待與你的再次合作。", "0", "0", "0", "0", "0", "cv_sk_korsgaard_3", "0", "0"},
[4400100103] = {4400100103, 14001001, 91, 4, "0", "idle", "居然選擇置之不理……的確，這也是一種懲罰啊。", "0", "0", "0", "0", "0", "cv_sk_korsgaard_4", "0", "0"},
[4400100104] = {4400100104, 14001001, 91, 4, "0", "idle", "不要這麼沉默不語，有什麼話就請直說，寧願你痛罵我一頓也好，否則實在太難為情了。", "0", "0", "0", "0", "0", "cv_sk_korsgaard_5", "0", "0"},
[4400100105] = {4400100105, 14001001, 94, 4, "0", "idle2", "由我獨自一人承擔責罰的話，按照約定，你會放過我的同伴對吧？", "0", "0", "0", "0", "0", "cv_sk_korsgaard_6", "0", "0"},
[4400100106] = {4400100106, 14001001, 94, 4, "0", "idle2", "我明白，你認為我是個罪無可赦之人，只能用這種方式進行改造，但我有些害怕，我究竟會變成什麼樣？", "0", "0", "0", "0", "0", "cv_sk_korsgaard_7", "0", "0"},
[4400100107] = {4400100107, 14001001, 92, 5, "14_2_0_0.8", "touch1", "如果痛苦就能洗清罪孽，那麼就讓更為深重的痛苦向我襲來吧。儘管……我也知道贖罪當然不是如此簡單的事。", "0", "0", "0", "0", "0", "cv_sk_korsgaard_8", "0", "0"},
[4400100108] = {4400100108, 14001001, 92, 5, "14_2_0_0.8", "touch1", "你說……能夠看出我本性的正直嗎？不，都說論跡不論心，不管我的初衷如何，我終究走上了一條歧路，因此，還是請你賜下應有的懲罰吧。", "0", "0", "0", "0", "0", "cv_sk_korsgaard_9", "0", "0"},
[4400100109] = {4400100109, 14001001, 93, 5, "14_1_0_0.8", "touch_s1", "呼……", "0", "0", "0", "0", "0", "cv_sk_korsgaard_45", "0", "0"},
[4400100110] = {4400100110, 14001001, 95, 5, "14_2_0_0.8", "touch2", "嘖……雖說我敗得心服口服，可是這種懲罰再怎麼說也……", "0", "0", "0", "0", "0", "cv_sk_korsgaard_10", "0", "0"},
[4400100111] = {4400100111, 14001001, 95, 5, "14_2_0_0.8", "touch2", "就連我也一直堅守底線從不逾矩，可為什麼，我感覺你最近越來越對懲罰樂在其中了……？", "0", "0", "0", "0", "0", "cv_sk_korsgaard_11", "0", "0"},
[4400100112] = {4400100112, 14001001, 96, 5, "14_1_0_0.8", "touch_s2", "嗯？", "0", "0", "0", "0", "0", "cv_sk_korsgaard_46", "0", "0"},
[4400100113] = {4400100113, 14001001, 12, 6, "0", "0", "有勞你了。", "0", "0", "0", "0", "0", "cv_sk_korsgaard_12", "0", "0"},
[4400100114] = {4400100114, 14001001, 13, 7, "0", "0", "強大的力量，需要更強的心靈來控制。", "0", "0", "0", "0", "0", "cv_sk_korsgaard_13", "0", "0"},
[4400100115] = {4400100115, 14001001, 14, 8, "0", "0", "那次事件之後，我原以為我會不再堅持玻璃製品般易碎的“純粹”，但與你相處的這段時間，讓我重新開始思考何為純粹，何為永恆。", "0", "0", "0", "0", "0", "cv_sk_korsgaard_14", "0", "0"},
[4400100116] = {4400100116, 14001001, 15, 9, "0", "0", "不斷磨礪劍藝。", "0", "0", "0", "0", "0", "cv_sk_korsgaard_15", "0", "0"},
[4400100117] = {4400100117, 14001001, 16, 10, "0", "0", "我即是防線。", "0", "0", "0", "0", "0", "cv_sk_korsgaard_16", "0", "0"},
[4400100118] = {4400100118, 14001001, 17, 11, "0", "0", "勝利的滋味，和大家一起分享吧。", "0", "0", "0", "0", "0", "cv_sk_korsgaard_17", "0", "0"},
[4400100119] = {4400100119, 14001001, 18, 12, "0", "0", "還有提升空間呢。", "0", "0", "0", "0", "0", "cv_sk_korsgaard_18", "0", "0"},
[4400100120] = {4400100120, 14001001, 19, 13, "0", "0", "真危險啊……應當吸取教訓。", "0", "0", "0", "0", "0", "cv_sk_korsgaard_19", "0", "0"},
[4400100121] = {4400100121, 14001001, 20, 14, "0", "0", "我會反省，領航也請不用吝惜懲罰。", "0", "0", "0", "0", "0", "cv_sk_korsgaard_20", "0", "0"},
[4400100122] = {4400100122, 14001001, 21, 15, "0", "0", "請安息。", "0", "0", "0", "0", "0", "cv_sk_korsgaard_21", "0", "0"},
[4400100123] = {4400100123, 14001001, 23, 16, "0", "0", "速戰速決吧。", "0", "0", "0", "0", "0", "cv_sk_korsgaard_22", "0", "0"},
[4400100124] = {4400100124, 14001001, 24, 17, "0", "0", "還沒結束！", "0", "0", "0", "0", "0", "cv_sk_korsgaard_23", "0", "0"},
[4400100125] = {4400100125, 14001001, 25, 18, "0", "0", "神聖之劍啊，請用這份光芒指引我吧。", "0", "0", "0", "0", "0", "cv_sk_korsgaard_24", "0", "0"},
[4400100126] = {4400100126, 14001001, 26, 19, "0", "0", "這就是我的宿命嗎……", "0", "0", "0", "0", "0", "cv_sk_korsgaard_25", "0", "0"},
[4400100127] = {4400100127, 14001001, 27, 20, "0", "0", "來了啊，今天就拜託你了。", "0", "0", "0", "0", "0", "cv_sk_korsgaard_26", "0", "0"},
[4400100128] = {4400100128, 14001001, 28, 21, "0", "0", "可能因為我自己就是個直率的人，像這樣坦誠相待的感覺很不錯。", "0", "0", "0", "0", "0", "cv_sk_korsgaard_27", "0", "0"},
[4400100129] = {4400100129, 14001001, 29, 21, "0", "0", "領航？注意力請稍微集中些，畢竟我也不是一點都不害羞的。", "0", "0", "0", "0", "0", "cv_sk_korsgaard_28", "0", "0"},
[4400100130] = {4400100130, 14001001, 30, 22, "0", "0", "加油。", "0", "0", "0", "0", "0", "cv_sk_korsgaard_29", "0", "0"},
[4400100131] = {4400100131, 14001001, 31, 23, "0", "0", "這個遊戲是……？", "0", "0", "0", "0", "0", "cv_sk_korsgaard_30", "0", "0"},
[4400100132] = {4400100132, 14001001, 32, 24, "0", "0", "看來是個會增加信賴感的遊戲呢。", "0", "0", "0", "0", "0", "cv_sk_korsgaard_31", "0", "0"},
[4400100133] = {4400100133, 14001001, 33, 25, "0", "0", "好吧，我們還需更加熟悉彼此才行。", "0", "0", "0", "0", "0", "cv_sk_korsgaard_32", "0", "0"},
[4400100134] = {4400100134, 14001001, 34, 26, "0", "0", "又、又來了嗎？雖然想請求你讓我多休息會兒……但，果然，我必須承擔自己做出的所有選擇。", "0", "0", "0", "0", "0", "cv_sk_korsgaard_33", "0", "0"},
[4400100135] = {4400100135, 14001001, 35, 27, "0", "0", "該出擊了嗎。", "0", "0", "0", "0", "0", "cv_sk_korsgaard_34", "0", "0"},
[4400100136] = {4400100136, 14001001, 36, 28, "0", "0", "以劍會友吧。", "0", "0", "0", "0", "0", "cv_sk_korsgaard_35", "0", "0"},
[4400100137] = {4400100137, 14001001, 37, 29, "0", "0", "大家都有各自的目標啊。", "0", "0", "0", "0", "0", "cv_sk_korsgaard_36", "0", "0"},
[4400100138] = {4400100138, 14001001, 38, 30, "0", "0", "領航所賞識的新人嗎？", "0", "0", "0", "0", "0", "cv_sk_korsgaard_37", "0", "0"},
[4400100139] = {4400100139, 14001001, 39, 31, "0", "0", "不要過於依賴裝備就好。", "0", "0", "0", "0", "0", "cv_sk_korsgaard_38", "0", "0"},
[4400100140] = {4400100140, 14001001, 40, 32, "0", "0", "請注意開銷。", "0", "0", "0", "0", "0", "cv_sk_korsgaard_39", "0", "0"},
[4400100141] = {4400100141, 14001001, 41, 33, "0", "0", "非常漂亮的履歷。", "0", "0", "0", "0", "0", "cv_sk_korsgaard_40", "0", "0"},
[4400100142] = {4400100142, 14001001, 42, 34, "0", "0", "仔細檢查下吧。", "0", "0", "0", "0", "0", "cv_sk_korsgaard_41", "0", "0"},
[4400100143] = {4400100143, 14001001, 43, 35, "0", "0", "有信到了嗎？", "0", "0", "0", "0", "0", "cv_sk_korsgaard_42", "0", "0"},
[4400100144] = {4400100144, 14001001, 44, 36, "0", "0", "以言語交戰的地方呢。", "0", "0", "0", "0", "0", "cv_sk_korsgaard_43", "0", "0"},
[4400100145] = {4400100145, 14001001, 45, 37, "0", "0", "請。", "0", "0", "0", "0", "0", "cv_sk_korsgaard_44", "0", "0"},
[4400200100] = {4400200100, 14002001, 1, 1, "0", "0", "蒼霧殘響", "0", "0", "0", "0", "0", "cv_sk_aofeiliya2_1", "0", "0"},
[4400200101] = {4400200101, 14002001, 2, 2, "0", "0", "就、就交給我吧！", "0", "0", "0", "0", "0", "cv_sk_aofeiliya2_2", "0", "0"},
[4400200102] = {4400200102, 14002001, 3, 3, "0", "0", "遵，遵從古老的誓約而來，我、我是您的騎士奧菲莉亞，因為深知自己的不足正在【星之騎士】修行中……再一次，請多多指教！", "0", "0", "0", "0", "0", "cv_sk_aofeiliya2_3", "0", "0"},
[4400200103] = {4400200103, 14002001, 91, 4, "0", "idle", "衣服被勾住了……起、起不來了！", "服が引っかかって……た、立てません！", "0", "0", "0", "0", "cv_sk_aofeiliya2_4", "0", "0,idle"},
[4400200104] = {4400200104, 14002001, 94, 4, "0", "idle12", "怎、怎麼又是這樣……我竟然在同一個地方失敗了兩次……", "な、なんでまたこんな事に……同じ失敗を繰り返すなんて……", "0", "0", "0", "0", "cv_sk_aofeiliya2_5", "0", "0,idle12"},
[4400200105] = {4400200105, 14002001, 98, 4, "0", "idle21", "我也想以正常的方式給領航看啊！嗚嗚……怎麼每次都是這樣！", "うちだってちゃんとした恰好を見て貰いたいんです！うう……なんで毎回こうなるんですか！", "0", "0", "0", "0", "cv_sk_aofeiliya2_6", "0", "0,idle21"},
[4400200106] = {4400200106, 14002001, 99, 4, "0", "idle22", "咦……唔……我？為什麼會三次都這樣……我明明有注意腳下……", "え……う……あれ？どうして三回もこんな事に……足元には注意してたはずなのに……", "0", "0", "0", "0", "cv_sk_aofeiliya2_7", "0", "0,idle22"},
[4400200107] = {4400200107, 14002001, 100, 4, "0", "idle31", "請、請把我不檢點的樣子忘掉！", "う、うちの恥ずかしい姿は忘れてください！", "0", "0", "0", "0", "cv_sk_aofeiliya2_8", "0", "0,idle31"},
[4400200108] = {4400200108, 14002001, 101, 4, "0", "idle32", "領領領領領領航！？請閉上眼睛——", "ななななな、なびげーたーさん！？見ないでくださーい！", "0", "0", "0", "0", "cv_sk_aofeiliya2_9", "0", "0,idle32"},
[4400200109] = {4400200109, 14002001, 961, 5, "0", "touch_s1", "啊！？", "うあっ！？", "0", "0", "0", "0", "cv_sk_aofeiliya2_10", "0", "0,touch_s1"},
[4400200110] = {4400200110, 14002001, 931, 5, "0", "touch_s2", "咿呀——！", "イヤーッ！", "0", "0", "0", "0", "cv_sk_aofeiliya2_11", "0", "0,touch_s2"},
[4400200111] = {4400200111, 14002001, 102, 5, "0", "touch_s3", "嗚……", "う……", "0", "0", "0", "0", "cv_sk_aofeiliya2_46", "0", "0,touch_s3"},
[4400200112] = {4400200112, 14002001, 103, 5, "0", "touch_s01", "呀——", "きゃっ", "0", "0", "0", "0", "cv_sk_aofeiliya2_47", "0", "0,touch_s01"},
[4400200113] = {4400200113, 14002001, 104, 5, "0", "touch_s02", "盯……", "ジー……", "0", "0", "0", "0", "cv_sk_aofeiliya2_48", "0", "0,touch_s02"},
[4400200114] = {4400200114, 14002001, 105, 5, "0", "touch_s03", "咿——", "ぇ？", "0", "0", "0", "0", "cv_sk_aofeiliya2_49", "0", "0,touch_s03"},
[4400200115] = {4400200115, 14002001, 92, 5, "0", "touch_s101", "我、我平時穿的內衣可不是這種款式，不是這、這種色、色情的衣服，平、平時都是白色的！", "ふ、普段はこんな下著じゃないんです。こ、こんな、えっちなのじゃなくて、もっと……白とかですから！", "0", "0", "0", "0", "cv_sk_aofeiliya2_50", "0", "0,touch_s101"},
[4400200116] = {4400200116, 14002001, 92, 5, "0", "touch_s102", "我、我只是想試試看穿上去會是什麼樣的，因、因為之前和領航逛街的時候看到了這種衣服，很、很好奇……", "う、うちは著てみたらどうなるか気になっただけで……だ、だってなびげーたーさんが街で、きょ、興味深そうにこの服を見てたから……", "0", "0", "0", "0", "cv_sk_aofeiliya2_51", "0", "0,touch_s102"},
[4400200117] = {4400200117, 14002001, 95, 5, "0", "touch1", "嗚——", "うぇっ──", "0", "0", "0", "0", "cv_sk_aofeiliya2_52", "0", "0,touch1"},
[4400200118] = {4400200118, 14002001, 95, 5, "0", "touch2", "嗚……嗚……嗚……", "あ……あ……あ……", "0", "0", "0", "0", "cv_sk_aofeiliya2_53", "0", "0,touch2"},
[4400200119] = {4400200119, 14002001, 95, 5, "0", "touch_s10", "嗚哇——！哇啊啊啊啊——！不要看過來啊——！", "うわぁ！あわわわわ！見ないでくださーい！", "0", "0", "0", "0", "cv_sk_aofeiliya2_54", "0", "0,touch_s10"},
[4400200120] = {4400200120, 14002001, 106, 5, "0", "touch_s201", "領、領航……你會負起責任把我娶回家的……對吧！對吧！", "な、なびげーたーさん……責任もってうちをお嫁さんにしてくれるんですよね……そうですよね！ね！", "0", "0", "0", "0", "cv_sk_aofeiliya2_55", "0", "0,touch_s201"},
[4400200121] = {4400200121, 14002001, 106, 5, "0", "touch_s202", "這、這就是奶牛服！您一定在心裡覺得我就是這樣的女人吧！事到如今我也沒有什麼可以狡辯的了！", "こ、これ……ホルスタインじゃないですか！うちのことそういう目で見てたんですね！　……そりゃ反論はできませんけど！", "0", "0", "0", "0", "cv_sk_aofeiliya2_56", "0", "0,touch_s202"},
[4400200122] = {4400200122, 14002001, 107, 5, "0", "touch3", "領航……領航……嘿嘿……", "ナビゲーターさん……ナビゲーターさん……えへへ……", "0", "0", "0", "0", "cv_sk_aofeiliya2_57", "0", "0,touch3"},
[4400200123] = {4400200123, 14002001, 107, 5, "0", "touch4", "……", "……", "0", "0", "0", "0", "cv_sk_aofeiliya2_58", "0", "0,touch4"},
[4400200124] = {4400200124, 14002001, 107, 5, "0", "touch_s20", "……算、算了！領航要看的話，就看吧！", "……わ、分かりましたよ！　もうなびげーたーさんの好きにしてください！", "0", "0", "0", "0", "cv_sk_aofeiliya2_59", "0", "0,touch_s20"},
[4400200125] = {4400200125, 14002001, 108, 5, "0", "touch_s301", "為什麼會穿著其他款式的泳裝……這、這是因為，米菈隊長說這樣穿領、領航會開心……", "どうしていつもと違う水着なのか、ですか？　……そ、それは、こっちの方がなびげーたーさんが喜ぶって、ミーラ隊長が……", "0", "0", "0", "0", "cv_sk_aofeiliya2_60", "0", "0,touch_s301"},
[4400200126] = {4400200126, 14002001, 108, 5, "0", "touch_s302", "好、好痛……", "い、いたた……", "0", "0", "0", "0", "cv_sk_aofeiliya2_61", "0", "0,touch_s302"},
[4400200127] = {4400200127, 14002001, 109, 5, "0", "touch5", "嘿嘿……哈……", "へへ……ふふ……", "0", "0", "0", "0", "cv_sk_aofeiliya2_62", "0", "0,touch5"},
[4400200128] = {4400200128, 14002001, 109, 5, "0", "touch6", "嗚……", "うぅ……", "0", "0", "0", "0", "cv_sk_aofeiliya2_63", "0", "0,touch6"},
[4400200129] = {4400200129, 14002001, 109, 5, "0", "touch_s30", "沒、沒想到我身為騎士，竟然在這種地方犯下這種錯誤……", "う、うちは騎士なのに、こんなミスをしちゃうなんて……", "0", "0", "0", "0", "cv_sk_aofeiliya2_64", "0", "0,touch_s30"},
[4400200130] = {4400200130, 14002001, 12, 6, "0", "0", "能、能感受到宇宙的力量，已、已經開始傳遞了。", "う、宇宙の力が伝わって來るのを、か、感じます。", "0", "0", "0", "0", "cv_sk_aofeiliya2_12", "0", "0"},
[4400200131] = {4400200131, 14002001, 13, 7, "0", "0", "這還不是我的極限……請繼續吧，我、我會忍耐的！", "うちはまだ限界じゃありません……続けましょう、う、うち頑張ります！", "0", "0", "0", "0", "cv_sk_aofeiliya2_13", "0", "0"},
[4400200132] = {4400200132, 14002001, 14, 8, "0", "0", "啊……就在剛剛的一瞬間，我好像能感受到命運的水車開始轉動了……奇怪……", "あ……いま、運命の水車が回り始めたのを感じました……なんか不思議ですね……", "0", "0", "0", "0", "cv_sk_aofeiliya2_14", "0", "0"},
[4400200133] = {4400200133, 14002001, 15, 9, "0", "0", "啊——嚇、嚇死我了，我、我還沒做好心理準備呢。", "うわ…！　び、びっくりしました。まだ心の準備ができてなくて……", "0", "0", "0", "0", "cv_sk_aofeiliya2_15", "0", "0"},
[4400200134] = {4400200134, 14002001, 16, 10, "0", "0", "【星之騎士】，准、準備開始前進了。", "【星の騎士】い、いつでも行けます。", "0", "0", "0", "0", "cv_sk_aofeiliya2_16", "0", "0"},
[4400200135] = {4400200135, 14002001, 17, 11, "0", "0", "呼……戰、戰鬥總算結束了，趕緊回去洗澡吧。", "ふぅ……や、やっと終わりましたぁ……早く戻ってお風呂にしましょう……", "0", "0", "0", "0", "cv_sk_aofeiliya2_17", "0", "0"},
[4400200136] = {4400200136, 14002001, 18, 12, "0", "0", "距、距離成為真正的騎士還有一點距離。", "ほ、本當の騎士になるまでには、もう少しかかりそうです。", "0", "0", "0", "0", "cv_sk_aofeiliya2_18", "0", "0"},
[4400200137] = {4400200137, 14002001, 19, 13, "0", "0", "請領航不要遠離我，接下來要小心了。", "なびげーたーさん、気をつけて……うちから離れないでくださいね。", "0", "0", "0", "0", "cv_sk_aofeiliya2_19", "0", "0"},
[4400200138] = {4400200138, 14002001, 20, 14, "0", "0", "沒有時間再猶豫了，請您下達撤退的指令吧。", "これ以上迷っていては……撤退命令をお願いします！", "0", "0", "0", "0", "cv_sk_aofeiliya2_20", "0", "0"},
[4400200139] = {4400200139, 14002001, 21, 15, "0", "0", "哼。", "ふん。", "0", "0", "0", "0", "cv_sk_aofeiliya2_21", "0", "0"},
[4400200140] = {4400200140, 14002001, 23, 16, "0", "0", "嘿！", "えい！", "0", "0", "0", "0", "cv_sk_aofeiliya2_22", "0", "0"},
[4400200141] = {4400200141, 14002001, 24, 17, "0", "0", "哈！", "ハッ！", "0", "0", "0", "0", "cv_sk_aofeiliya2_23", "0", "0"},
[4400200142] = {4400200142, 14002001, 25, 18, "0", "0", "我乃女主角，【星之騎士】奧菲莉亞！", "うちこそがひろいん、【星の騎士】オフィーリアです！", "0", "0", "0", "0", "cv_sk_aofeiliya2_24", "0", "0"},
[4400200143] = {4400200143, 14002001, 26, 19, "0", "0", "我一定還會回來的，在那之前堅持住。", "すぐに戻って來るので、それまで持ち堪えてください。", "0", "0", "0", "0", "cv_sk_aofeiliya2_25", "0", "0"},
[4400200144] = {4400200144, 14002001, 27, 20, "0", "0", "不管是戰鬥後還是游泳之後都要好好地清洗自己的身體。", "戦闘の後も水泳の後も、しっかり體を洗わなきゃですね。", "0", "0", "0", "0", "cv_sk_aofeiliya2_27", "0", "0"},
[4400200145] = {4400200145, 14002001, 28, 21, "0", "0", "領、領航更喜歡那種肌膚呢？是、是稍微被曬黑一點的健康膚色……還、還是現在這樣就好……我、我可以做好準備……", "な、なびげーたーさんって、ああいう感じの子がお好きなんですか？ちょっと日に焼けた、健康的な感じの……やっぱり今はこういうのが……わ、分かりました……", "0", "0", "0", "0", "cv_sk_aofeiliya2_28", "0", "0"},
[4400200146] = {4400200146, 14002001, 29, 21, "0", "0", "肩、肩膀好僵硬……是因為一直在戰鬥的原因吧……不過還好有領航幫我調理。", "か、肩がガチガチですね……ずっと戦っていたからでしょうか……でも、なびげーたーさんがほぐしてくれるので助かります。", "0", "0", "0", "0", "cv_sk_aofeiliya2_29", "0", "0"},
[4400200147] = {4400200147, 14002001, 30, 22, "0", "0", "又、又開始了嗎！", "ま、また始まったんですね！", "0", "0", "0", "0", "cv_sk_aofeiliya2_30", "0", "0"},
[4400200148] = {4400200148, 14002001, 31, 23, "0", "0", "領、領航可千萬不要猜錯啊，加油！", "な、なびげーたーさん、間違えちゃダメですよ。がんばって！", "0", "0", "0", "0", "cv_sk_aofeiliya2_31", "0", "0"},
[4400200149] = {4400200149, 14002001, 32, 24, "0", "0", "嘿嘿嘿，不愧是我的主君。", "えへへ、さすがはうちの主さまです。", "0", "0", "0", "0", "cv_sk_aofeiliya2_32", "0", "0"},
[4400200150] = {4400200150, 14002001, 33, 25, "0", "0", "我、我還是希望領航能認出我的！", "な、なびげーたーさんなら當ててくれると思ってたのに……", "0", "0", "0", "0", "cv_sk_aofeiliya2_33", "0", "0"},
[4400200151] = {4400200151, 14002001, 34, 26, "0", "0", "救……救命啊……我動不了了……", "た……たすけて……動けません……", "0", "0", "0", "0", "cv_sk_aofeiliya2_34", "0", "0"},
[4400200152] = {4400200152, 14002001, 35, 27, "0", "0", "我會盡到騎士的職責的，請待在我身後吧。", "うちが騎士としての務めを果たします。うちの後ろに下がっていてください。", "0", "0", "0", "0", "cv_sk_aofeiliya2_35", "0", "0"},
[4400200153] = {4400200153, 14002001, 36, 28, "0", "0", "我會跟上大家的行動的。", "みんなに著いて行きます。", "0", "0", "0", "0", "cv_sk_aofeiliya2_36", "0", "0"},
[4400200154] = {4400200154, 14002001, 37, 29, "0", "0", "大家……", "みんな……", "0", "0", "0", "0", "cv_sk_aofeiliya2_37", "0", "0"},
[4400200155] = {4400200155, 14002001, 38, 30, "0", "0", "想好要遇見哪位駕駛員了嗎？", "どのドライバーさんに會うか決まりましたか？", "0", "0", "0", "0", "cv_sk_aofeiliya2_38", "0", "0"},
[4400200156] = {4400200156, 14002001, 39, 31, "0", "0", "找一些正常的衣服換掉泳裝吧……沒、沒有？也是呢……", "み、水著に著替えるんですか？　……ち、違う？　そうですか……", "0", "0", "0", "0", "cv_sk_aofeiliya2_39", "0", "0"},
[4400200157] = {4400200157, 14002001, 40, 32, "0", "0", "好貴……", "高いですね……", "0", "0", "0", "0", "cv_sk_aofeiliya2_40", "0", "0"},
[4400200158] = {4400200158, 14002001, 41, 33, "0", "0", "領航的照片……要裝裱起來……", "なびげーたーさんの寫真……ちゃんと額に入れなきゃ……", "0", "0", "0", "0", "cv_sk_aofeiliya2_41", "0", "0"},
[4400200159] = {4400200159, 14002001, 42, 34, "0", "0", "嗯……", "えーっと……", "0", "0", "0", "0", "cv_sk_aofeiliya2_42", "0", "0"},
[4400200160] = {4400200160, 14002001, 43, 35, "0", "0", "我會記得給您寫信的。", "ちゃんと手紙を出しますね。", "0", "0", "0", "0", "cv_sk_aofeiliya2_43", "0", "0"},
[4400200161] = {4400200161, 14002001, 44, 36, "0", "0", "好、好吵……", "に、賑やかですね……", "0", "0", "0", "0", "cv_sk_aofeiliya2_44", "0", "0"},
[4400200162] = {4400200162, 14002001, 45, 37, "0", "0", "哇哦。", "わわっ。", "0", "0", "0", "0", "cv_sk_aofeiliya2_45", "0", "0"},
[4001700100] = {4001700100, 10017001, 1, 1, "0", "0", "蒼霧殘響。", "0", "0", "0", "蒼霧殘響。", "0", "cv_sk_rosalind_32", "0", "0"},
[4001700101] = {4001700101, 10017001, 2, 2, "0", "0", "明智之選，本小姐不會讓你失望的！", "0", "0", "0", "明智之選，本小姐不會讓你失望的！", "0", "cv_sk_rosalind_2", "0", "0"},
[4001700102] = {4001700102, 10017001, 3, 3, "0", "0", "“羅斯柴德”家族長女——羅莎琳德覲見。您就是這次行動的領航嗎？", "0", "0", "0", "“羅斯柴德”家族長女——羅莎琳德覲見。您就是這次行動的領航嗎？", "0", "cv_sk_rosalind_1", "0", "0"},
[4001700103] = {4001700103, 10017001, 91, 4, "0", "idle", "本小姐竟然輸了……！", "0", "0", "0", "這裡的裝潢雖然不及家族內的裝飾，但是也算是別有風格。", "0", "cv_sk_rosalind_n01", "0", "0,idle"},
[4001700104] = {4001700104, 10017001, 94, 4, "0", "idle2", "領航你、你應該不會對破破爛爛的衣服感興趣吧！？", "0", "0", "0", "不要因為本小姐是貴族就小瞧我的實力，下次任務本小姐來擔任前鋒。", "0", "cv_sk_rosalind_n02", "0", "0,idle2"},
[4001700105] = {4001700105, 10017001, 98, 4, "0", "idle3", "不、已經不能再脫了！結束了！我要收手了！金盆洗手！", "0", "0", "0", "與原罪戰鬥當然會害怕啦，但是本小姐的貴族血統可不允許害怕。作為前線小隊的成員每一次任務都是在用生命進行戰鬥，這點本小姐早就已經有覺悟了。", "0", "cv_sk_rosalind_n03", "0", "0,idle3"},
[4001700106] = {4001700106, 10017001, 92, 5, "14_1_0_0.8", "level1", "咕——！還、還是殺了我！", "0", "0", "0", "參加前線小隊完全是本小姐自己的意願，當然我家族那塊是必須瞞著的，要是被爸媽知道我在做這麼危險的事……所以，一定要保護好本小姐哦，領航！", "0", "cv_sk_rosalind_n04", "0", "0,level1"},
[4001700107] = {4001700107, 10017001, 95, 5, "14_1_0_0.8", "level2", "願、願賭服輸……", "0", "0", "0", "本小姐可是貴族，就算是領航也不可肆意輕薄。", "0", "cv_sk_rosalind_n05", "0", "0,level2"},
[4001700108] = {4001700108, 10017001, 99, 5, "14_1_0_0.8", "level3", "給、給本小姐記好了……！玷污貴族的尊嚴！我、我一定會復仇的！", "0", "0", "0", "本小姐的家族有著千年的歷史，是瑪雅地區老牌的貴族之一……嗯？網路上搜索不到？這…這是因為家族內有規矩，不會隨便出現在世人面前。", "0", "cv_sk_rosalind_n06", "0", "0,level3"},
[4001700109] = {4001700109, 10017001, 93, 5, "14_2_0_0.8", "livel1-2", "咕……繼續……！本小姐就不信了！", "0", "0", "0", "話說駕駛員巨大化後穿著的裝甲值不少錢吧，如果拿去賣了——呃啊啊，領航你怎麼在這？本小姐剛才什麼都沒說！你也什麼都沒聽到！", "0", "cv_sk_rosalind_n07", "0", "0,livel1-2"},
[4001700110] = {4001700110, 10017001, 96, 5, "14_2_0_0.8", "livel2-3", "又輸了！？……還要繼續脫嗎……！", "0", "0", "0", "領航，雖然你與本小姐之間身份懸殊，但是…也並非沒有機會。如果說你願意的話，我回去請示一下父母……誒？領航……怎麼偏偏這時候睡著了啊。", "0", "cv_sk_rosalind_n08", "0", "0,livel2-3"},
[4001700111] = {4001700111, 10017001, 100, 5, "14_2_0_0.8", "livel3-1", "呃啊……", "0", "0", "0", "感覺到實力的增強了。", "0", "cv_sk_rosalind_n09", "0", "0,livel3-1"},
[4001700112] = {4001700112, 10017001, 12, 6, "0", "0", "感覺到實力的增強了。", "0", "0", "0", "剛閃過的星星，好像很值錢的樣子。", "0", "cv_sk_rosalind_9", "0", "0"},
[4001700113] = {4001700113, 10017001, 13, 7, "0", "0", "剛閃過的星星，好像很值錢的樣子。", "0", "0", "0", "擁有這樣的力量，我就可以重振家族的榮耀了。", "0", "cv_sk_rosalind_10", "0", "0"},
[4001700114] = {4001700114, 10017001, 14, 8, "0", "0", "擁有這樣的力量，我就可以重振家族的榮耀了。", "0", "0", "0", "這就是貴族的待遇麼……咳，謝謝。", "0", "cv_sk_rosalind_11", "0", "0"},
[4001700115] = {4001700115, 10017001, 15, 9, "0", "0", "這就是貴族的待遇麼……咳，謝謝。", "0", "0", "0", "儘管交給本小姐吧，本小姐絕對不會讓期待落空。", "0", "cv_sk_rosalind_12", "0", "0"},
[4001700116] = {4001700116, 10017001, 16, 10, "0", "0", "儘管交給本小姐吧，本小姐絕對不會讓期待落空。", "0", "0", "0", "有本小姐在，這都是理所應當的結果。", "0", "cv_sk_rosalind_13", "0", "0"},
[4001700117] = {4001700117, 10017001, 17, 11, "0", "0", "有本小姐在，這都是理所應當的結果。", "0", "0", "0", "本小姐不過是分心了而已。", "0", "cv_sk_rosalind_14", "0", "0"},
[4001700118] = {4001700118, 10017001, 18, 12, "0", "0", "本小姐不過是分心了而已。", "0", "0", "0", "本小姐下次肯定會做得更好！", "0", "cv_sk_rosalind_15", "0", "0"},
[4001700119] = {4001700119, 10017001, 19, 13, "0", "0", "本小姐下次肯定會做得更好！", "0", "0", "0", "如果死了就什麼都沒了，快撤吧。", "0", "cv_sk_rosalind_16", "0", "0"},
[4001700120] = {4001700120, 10017001, 20, 14, "0", "0", "如果死了就什麼都沒了，快撤吧。", "0", "0", "0", "想作為本小姐的對手還不夠格呢！", "0", "cv_sk_rosalind_17", "0", "0"},
[4001700121] = {4001700121, 10017001, 21, 15, "0", "0", "變成我的籌碼吧！", "0", "0", "0", "看本小姐的厲害！", "0", "cv_sk_rosalind_n10", "0", "0"},
[4001700122] = {4001700122, 10017001, 23, 16, "0", "0", "加注！", "0", "0", "0", "本小姐的全力一擊，接得住嗎。", "0", "cv_sk_rosalind_n11", "0", "0"},
[4001700123] = {4001700123, 10017001, 24, 17, "0", "0", "梭哈！", "0", "0", "0", "真不甘心啊…", "0", "cv_sk_rosalind_n12", "0", "0"},
[4001700124] = {4001700124, 10017001, 26, 19, "0", "0", "真不甘心啊…", "0", "0", "0", "哇啊啊，這…這這，這就是貴族的奢靡生活嗎！……啊，就和我家一樣！", "0", "cv_sk_rosalind_20", "0", "0"},
[4001700125] = {4001700125, 10017001, 27, 20, "0", "0", "哇啊啊，這…這這，這就是貴族的奢靡生活嗎！……啊，就和我家一樣！", "0", "0", "0", "這樣盯著一位女士可不是紳士所為。", "0", "cv_sk_rosalind_22", "0", "0"},
[4001700126] = {4001700126, 10017001, 28, 21, "0", "0", "這樣盯著一位女士可不是紳士所為。", "0", "0", "0", "就一次哦，本小姐允許你為我搓背。", "0", "cv_sk_rosalind_23", "0", "0"},
[4001700127] = {4001700127, 10017001, 29, 21, "0", "0", "就一次喔，本小姐允許你為我搓背。", "0", "0", "0", "抓住這次機會，領航。", "0", "cv_sk_rosalind_24", "0", "0"},
[4001700128] = {4001700128, 10017001, 30, 22, "0", "0", "抓住這次機會，領航。", "0", "0", "0", "相信你不會認錯本小姐的。", "0", "cv_sk_rosalind_25", "0", "0"},
[4001700129] = {4001700129, 10017001, 31, 23, "0", "0", "相信你不會認錯本小姐的。", "0", "0", "0", "本小姐才沒有因為這點事高興呢！", "0", "cv_sk_rosalind_26", "0", "0"},
[4001700130] = {4001700130, 10017001, 32, 24, "0", "0", "本小姐才沒有因為這點事高興呢！", "0", "0", "0", "你是誰，我也不認識你。", "0", "cv_sk_rosalind_27", "0", "0"},
[4001700131] = {4001700131, 10017001, 33, 25, "0", "0", "你是誰，我也不認識你。", "0", "0", "0", "啊，你好啊，領航……", "0", "cv_sk_rosalind_28", "0", "0"},
[4001700132] = {4001700132, 10017001, 34, 26, "0", "0", "如、如你所願，按照賭約本小姐在這裡迎接你了！", "0", "0", "0", "輪到本小姐上場了嗎？", "0", "cv_sk_rosalind_n13", "0", "0"},
[4001700133] = {4001700133, 10017001, 35, 27, "0", "0", "輪到本小姐上場了嗎？", "0", "0", "0", "該讓你們看一下本小姐的實力了。", "0", "cv_sk_rosalind_33", "0", "0"},
[4001700134] = {4001700134, 10017001, 36, 28, "0", "0", "該讓你們看一下本小姐的實力了。", "0", "0", "0", "原來你有這麼多朋友呢。", "0", "cv_sk_rosalind_34", "0", "0"},
[4001700135] = {4001700135, 10017001, 37, 29, "0", "0", "原來你有這麼多朋友呢。", "0", "0", "0", "花錢就能買到朋友？！這個得記下來。", "0", "cv_sk_rosalind_35", "0", "0"},
[4001700136] = {4001700136, 10017001, 38, 30, "0", "0", "花錢就能買到朋友？！這個得記下來。", "0", "0", "0", "不錯的裝備，不過比起本小姐的還差遠了。", "0", "cv_sk_rosalind_36", "0", "0"},
[4001700137] = {4001700137, 10017001, 39, 31, "0", "0", "不錯的裝備，不過比起本小姐的還差遠了。", "0", "0", "0", "今天的特惠是……咳，隨便挑吧。", "0", "cv_sk_rosalind_37", "0", "0"},
[4001700138] = {4001700138, 10017001, 40, 32, "0", "0", "今天的特惠是……咳，隨便挑吧。", "0", "0", "0", "領航來自多瑙……啊！你不會是真正的貴族吧？", "0", "cv_sk_rosalind_38", "0", "0"},
[4001700139] = {4001700139, 10017001, 41, 33, "0", "0", "領航來自多瑙……啊！你不會是真正的貴族吧？", "0", "0", "0", "真複雜啊……", "0", "cv_sk_rosalind_39", "0", "0"},
[4001700140] = {4001700140, 10017001, 42, 34, "0", "0", "真複雜啊……", "0", "0", "0", "本小姐還是習慣用家族裡飼養的信鴿。", "0", "cv_sk_rosalind_40", "0", "0"},
[4001700141] = {4001700141, 10017001, 43, 35, "0", "0", "本小姐還是習慣用家族裡飼養的信鴿。", "0", "0", "0", "名流聚會？不行，還沒做好心理準備……", "0", "cv_sk_rosalind_41", "0", "0"},
[4001700142] = {4001700142, 10017001, 44, 36, "0", "0", "名流聚會？不行，還沒做好心理準備……", "0", "0", "0", "還行吧。", "0", "cv_sk_rosalind_42", "0", "0"},
[4001700143] = {4001700143, 10017001, 45, 37, "0", "0", "還行吧。", "0", "0", "0", "0", "0", "cv_sk_rosalind_43", "0", "0"},
[4149000200] = {4149000200, 11049002, 1, 1, "0", "0", "蒼霧殘響", "ハツリバーブ", "0", "0", "0", "0", "cv_sk2_aertaiya_1", "0", "0"},
[4149000201] = {4149000201, 11049002, 2, 2, "0", "0", "真不想值班啊……好想睡覺，好想看動畫……", "当直したくない……寝たい、アニメ観たい……", "0", "0", "0", "0", "cv_sk2_aertaiya_2", "0", "0"},
[4149000202] = {4149000202, 11049002, 3, 3, "0", "0", "沒想到我會出現在這裡吧，蜥蜴先生！哼哼，不是有人說過嗎，世間所有的重逢，都是蓄謀已久的相遇——我沒記錯吧？", "驚いたでしょ、トカゲさん！ふふ、誰かが言ってたよね、世の中の再会はすべて仕組まれた出会いだって——間違ってないよね？", "0", "0", "0", "0", "cv_sk2_aertaiya_3", "0", "0"},
[4149000203] = {4149000203, 11049002, 4, 4, "0", "idle", "這身打扮……就當是我心血來潮吧。雖然這麼說不好，穿著它的時候，感覺自己是在服喪，真奇怪啊……", "この服装は……気まぐれだと思ってね。こんなこと言うのも変だけど、これを着てるとまるで喪服を着てるみたいで、なんだか変な感じがするの……", "0", "0", "0", "0", "cv_sk2_aertaiya_4", "0", "0"},
[4149000204] = {4149000204, 11049002, 5, 4, "0", "idle", "“阿爾泰婭”是我，“塞繆”也是我，認真與戲謔，這就是我的兩面性。", "「アルテア」は私で、「セミュー」も私。真面目と戯れ、これが私の二面性だよ。", "0", "0", "0", "0", "cv_sk2_aertaiya_5", "0", "0"},
[4149000205] = {4149000205, 11049002, 6, 4, "0", "idle", "過去，“阿爾泰婭”所做的每一件事，都是我做的——我就像某部動畫裏的吸血鬼一樣，寄宿在“阿爾泰婭”影子裏……或者說，像寄生蟲一樣。", "過去に「アルテア」がしたすべてのこと、それは私がしたこと——私はまるであるアニメの吸血鬼のように、「アルテア」の影に潜んでる……もしくは寄生している。", "0", "0", "0", "0", "cv_sk2_aertaiya_6", "0", "0"},
[4149000206] = {4149000206, 11049002, 7, 5, "15_1_0_0.8", "level1", "比起“塞繆”，是不是“阿爾泰婭”會更受歡迎一點呢？遺憾的是，無論是“阿爾泰婭”還是“塞繆”，都是假的，我才是真的。", "「セミュー」より「アルテア」の方が人気があるのかな？残念ながら、「アルテア」も「セミュー」も偽物で、私が本物なの。", "0", "0", "0", "0", "cv_sk2_aertaiya_7", "0", "0"},
[4149000207] = {4149000207, 11049002, 8, 5, "15_1_0_0.8", "level1", "你也差不多該發現了吧？哼哼，我和她長得基本上一模一樣，畢竟是以我本來的模樣創造出來的分身呢！", "気づいてきたんじゃない？ふふ、私と彼女はほとんど同じ顔してるでしょ、だって私の姿を元に作られた分身なんだから！", "0", "0", "0", "0", "cv_sk2_aertaiya_8", "0", "0"},
[4149000208] = {4149000208, 11049002, 9, 5, "15_1_0_0.8", "level1", "現在這樣更好看……喂！我生氣了！難道長頭髮的女生更討人喜歡嗎？這不公平，短頭髮的女生也一樣很可愛的！", "今のほうが素敵……ねえ！怒るよ！髪の長い女の子の方が人気あるってこと？そんなの不公平だよ、髪の短い女の子も同じくらい可愛いのに！", "0", "0", "0", "0", "cv_sk2_aertaiya_9", "0", "0"},
[4149000209] = {4149000209, 11049002, 10, 5, "15_2_0_0.8", "level2", "“阿爾泰婭”也許再也不會出現了，因為她從來沒真正存在過——不過，你要是喜歡那麼彆扭的傢伙，我也不介意扮成她，畢竟都是我嘛，演起來肯定很輕鬆的！", "「アルテア」はもう二度と現れないかもしれない、だって彼女は本当に存在したことがないから——でも、もし君があの気難しい彼女が好きなら、私が演じてあげてもいいよ、結局は私なんだから、演じるのも簡単だしね！", "0", "0", "0", "0", "cv_sk2_aertaiya_10", "0", "0"},
[4149000210] = {4149000210, 11049002, 11, 5, "15_2_0_0.8", "level2", "沒有人能夠認識到真正的自己……真正的“我”到底是個怎樣的人？你要是見到了我的真面目，會不會變得討厭我呢？還是說會喜歡我呢……我的話，就算你是很糟糕的人，我都會——努力喜歡上的！", "誰も本当の自分を知ることができない……本当の「私」ってどんな人？もし君が私の本当の姿を見たら、嫌いになるかな？それとも好きになってくれるかな……私なら、君がどんなにひどい人でも——頑張って好きになってみせるよ！", "0", "0", "0", "0", "cv_sk2_aertaiya_11", "0", "0"},
[4149000211] = {4149000211, 11049002, 12, 6, "0", "0", "等級提升！", "レベルアップ！ ", "0", "0", "0", "0", "cv_sk2_aertaiya_12", "0", "0"},
[4149000212] = {4149000212, 11049002, 13, 7, "0", "0", "覺醒吧，我沉睡的潛力！", "目覚めよ、私の眠れる力！", "0", "0", "0", "0", "cv_sk2_aertaiya_13", "0", "0"},
[4149000213] = {4149000213, 11049002, 14, 8, "0", "0", "現在，我登上食物鏈的頂端了吧……開玩笑的，只是個“遊戲玩笑”而已。", "今、私は食物連鎖の頂点に立ったよ……冗談、ただの「ゲームジョーク」さ。", "0", "0", "0", "0", "cv_sk2_aertaiya_14", "0", "0"},
[4149000214] = {4149000214, 11049002, 15, 9, "0", "0", "只要吃掉124個自己，我就會無敵了！", "124人の自分を食べれば、私は無敵になる！", "0", "0", "0", "0", "cv_sk2_aertaiya_15", "0", "0"},
[4149000215] = {4149000215, 11049002, 16, 10, "0", "0", "你們的救世主來了！", "あなたたちの救世主が来た！ ", "0", "0", "0", "0", "cv_sk2_aertaiya_16", "0", "0"},
[4149000216] = {4149000216, 11049002, 17, 11, "0", "0", "這就是由我喚來的奇跡！", "これが私が呼び起こした奇跡！", "0", "0", "0", "0", "cv_sk2_aertaiya_17", "0", "0"},
[4149000217] = {4149000217, 11049002, 18, 12, "0", "0", "作為新手駕駛員，我已經表現得很好了！", "新米ドライバーとして、私、かなりよくやってるよね！", "0", "0", "0", "0", "cv_sk2_aertaiya_18", "0", "0"},
[4149000218] = {4149000218, 11049002, 19, 13, "0", "0", "遍體鱗傷的我們看起來就像真正的英雄一樣！", "傷だらけの私たち、まるで本当の英雄みたい！", "0", "0", "0", "0", "cv_sk2_aertaiya_19", "0", "0"},
[4149000219] = {4149000219, 11049002, 20, 14, "0", "0", "輸得太醜陋了，這可不像我們的作風！", "こんなみにくい負け方、私たちらしくないよ！", "0", "0", "0", "0", "cv_sk2_aertaiya_20", "0", "0"},
[4149000220] = {4149000220, 11049002, 21, 15, "0", "0", "化為亡靈吧。", "亡霊になれ。", "0", "0", "0", "0", "cv_sk2_aertaiya_21", "0", "0"},
[4149000221] = {4149000221, 11049002, 23, 16, "0", "0", "看招！", "くらえ！", "0", "0", "0", "0", "cv_sk2_aertaiya_22", "0", "0"},
[4149000222] = {4149000222, 11049002, 24, 17, "0", "0", "嘿呀！", "やあ！", "0", "0", "0", "0", "cv_sk2_aertaiya_23", "0", "0"},
[4149000223] = {4149000223, 11049002, 26, 19, "0", "0", "不甘心……", "悔しい……", "0", "0", "0", "0", "cv_sk2_aertaiya_26", "0", "0"},
[4149000224] = {4149000224, 11049002, 27, 20, "0", "0", "我可不會像動畫裡的女生那樣尖叫——反正你肯定有什麼理由吧……不可能真是走錯地方了吧？", "アニメの女の子みたいに叫んだりしないからね——どうせ理由があるんでしょ……まさか本当に間違って来たわけじゃないよね？", "0", "0", "0", "0", "cv_sk2_aertaiya_27", "0", "0"},
[4149000225] = {4149000225, 11049002, 28, 21, "0", "0", "不該看的地方都被你看光了吧，“給我負起責任呀”……要是說這句話會不會太老土了？", "見ちゃいけないとこ全部見ちゃったでしょ、「責任取ってよ」……ちょっと古くさいかな？", "0", "0", "0", "0", "cv_sk2_aertaiya_28", "0", "0"},
[4149000226] = {4149000226, 11049002, 29, 21, "0", "0", "對了，下次要不要一起去真正的溫泉？我對動畫裡的溫泉旅店一直都很感興趣！", "そうだ、今度本物の温泉に一緒に行かない？アニメの温泉旅館にずっと興味があったんだ！", "0", "0", "0", "0", "cv_sk2_aertaiya_29", "0", "0"},
[4149000227] = {4149000227, 11049002, 30, 22, "0", "0", "嗯？", "え？ ", "0", "0", "0", "0", "cv_sk2_aertaiya_30", "0", "0"},
[4149000228] = {4149000228, 11049002, 31, 23, "0", "0", "猜不出來的話就去查聲優名字吧！", "声優さんの名前を調べればわかるよ！", "0", "0", "0", "0", "cv_sk2_aertaiya_31", "0", "0"},
[4149000229] = {4149000229, 11049002, 32, 24, "0", "0", "我的聲音難道不好記嗎？", "私の声、覚えにくい？", "0", "0", "0", "0", "cv_sk2_aertaiya_32", "0", "0"},
[4149000230] = {4149000230, 11049002, 33, 25, "0", "0", "哼哼，在聽聲識人上，蜥蜴先生不如我呢。", "ふふ、声で人を見分けるのは、私のほうが上手いわね。", "0", "0", "0", "0", "cv_sk2_aertaiya_33", "0", "0"},
[4149000231] = {4149000231, 11049002, 34, 26, "0", "0", "噢？你來了……有被嚇到嗎？", "あら？来たの……びっくりした？", "0", "0", "0", "0", "cv_sk2_aertaiya_34", "0", "0"},
[4149000232] = {4149000232, 11049002, 35, 27, "0", "0", "聽我說聽我說，我有一個計畫，一個最好的計畫！", "聞いて聞いて、作戦があるんだ、最高の作戦が！", "0", "0", "0", "0", "cv_sk2_aertaiya_35", "0", "0"},
[4149000233] = {4149000233, 11049002, 36, 28, "0", "0", "屁股被踢痛了可不要告狀噢。", "お尻を蹴られて痛くても、文句言わないでね。", "0", "0", "0", "0", "cv_sk2_aertaiya_36", "0", "0"},
[4149000234] = {4149000234, 11049002, 37, 29, "0", "0", "這麼多人……有社團嗎？有傳說中的動漫社嗎？", "こんなに人がいる……部活とかあるの？伝説のアニメ部とか？", "0", "0", "0", "0", "cv_sk2_aertaiya_37", "0", "0"},
[4149000235] = {4149000235, 11049002, 38, 30, "0", "0", "女孩子一個接一個的靠過來，你真是搶手呀。", "女の子が次々に寄ってくるなんて、ほんとにモテるね。", "0", "0", "0", "0", "cv_sk2_aertaiya_38", "0", "0"},
[4149000236] = {4149000236, 11049002, 39, 31, "0", "0", "我要最高配置的裝備！", "最高の装備が欲しい！ ", "0", "0", "0", "0", "cv_sk2_aertaiya_39", "0", "0"},
[4149000237] = {4149000237, 11049002, 40, 32, "0", "0", "全部買下來吧！", "全部買っちゃおう！ ", "0", "0", "0", "0", "cv_sk2_aertaiya_40", "0", "0"},
[4149000238] = {4149000238, 11049002, 41, 33, "0", "0", "我就知道你不一般！", "あなたはやっぱり特別だね！ ", "0", "0", "0", "0", "cv_sk2_aertaiya_41", "0", "0"},
[4149000239] = {4149000239, 11049002, 42, 34, "0", "0", "全部拉滿！", "全部マックス！ ", "0", "0", "0", "0", "cv_sk2_aertaiya_42", "0", "0"},
[4149000240] = {4149000240, 11049002, 43, 35, "0", "0", "一鍵領取！一鍵刪除！", "一括受け取り！一括削除！", "0", "0", "0", "0", "cv_sk2_aertaiya_43", "0", "0"},
[4149000241] = {4149000241, 11049002, 44, 36, "0", "0", "Good Game.", "Good Game.", "0", "0", "0", "0", "cv_sk2_aertaiya_44", "0", "0"},
[4149000242] = {4149000242, 11049002, 45, 37, "0", "0", "嘿咻！", "えいしょ！", "0", "0", "0", "0", "cv_sk2_aertaiya_45", "0", "0"},
[4000700100] = {4000700100, 10007001, 1, 1, "0", "0", "蒼霧殘響。", "蒼霧殘響（ハツリバーブ）。", "0", "0", "蒼霧殘響。", "0", "cv_sk_uki_31", "0", "0"},
[4000700101] = {4000700101, 10007001, 2, 2, "0", "0", "請放心，我會一直待在這，照顧好您的。", "ご安心ください。私はずっとあなたの傍でお世話をしますから。", "0", "0", "請放心，我會一直待在這，照顧好您的。", "0", "cv_sk_uki_2", "0", "0"},
[4000700102] = {4000700102, 10007001, 3, 3, "0", "0", "初次見面，我的名字叫做海姬，是海神的新娘……開玩笑的，您的表情真是可愛啊。", "初めまして。私の名は海姫。海神の花嫁です――冗談ですわ。その表情、可愛かったですよ。", "0", "0", "初次見面，我的名字叫做海姬，是海神的新娘……開玩笑的，您的表情真是可愛啊。", "0", "cv_sk_uki_1", "0", "0"},
[4000700103] = {4000700103, 10007001, 4, 4, "0", "idle", "領航，把衣服脫下來吧……為什麼？欸呀，因為脫下來才能縫好它呀。", "服を脫いでくださいね、ナビゲーター……どうしたのですか？脫がないと繕えないですよ？", "0", "0", "領航，把衣服脫下來吧……為什麼？誒呀，因為脫下來才能縫好它呀。", "0", "cv_sk_uki_3", "0", "0"},
[4000700104] = {4000700104, 10007001, 5, 4, "0", "idle", "差不多該到休息的時間了……領航，午飯想吃什麼？", "そろそろ休憩時間ですね……ナビゲーター、お晝は何がいいですか？", "0", "0", "差不多該到休息的時間了……領航，午飯想吃什麼？", "0", "cv_sk_uki_4", "0", "0"},
[4000700105] = {4000700105, 10007001, 6, 4, "0", "idle", "默默……總是讓人不明白她在想什麼。但是那孩子似乎總是表現出一副很孤單的樣子，領航要多關心下她喔。", "モモ……あのコが何を考えているのか全然分かりません。でも、何だか寂しそうに見えます……優しくしてあげてくださいね、ナビゲーター。", "0", "0", "默默……總是讓人不明白她在想什麼。但是那孩子似乎總是表現出一副很孤單的樣子，領航要多關心下她噢。", "0", "cv_sk_uki_28", "0", "0"},
[4000700106] = {4000700106, 10007001, 7, 5, "15_1_0_0.8", "level1", "戰爭結束之後，海姬想回到故鄉，開一間旅館。每天看著來來往往的旅人，傾聽旅人的故事，治癒旅人的疲憊。", "戦爭が終わったら、私は故郷に帰って旅館をやりたいと思っています。毎日行き來する旅人たちを眺めて、彼らの物語を聞いたりして、疲れを癒してあげたいのです。", "0", "0", "戰爭結束之後，海姬想回到故鄉，開一間旅館。每天看著來來往往的旅人，傾聽旅人的故事，治癒旅人的疲憊。", "0", "cv_sk_uki_29", "0", "0"},
[4000700107] = {4000700107, 10007001, 8, 5, "15_1_0_0.8", "level1", "嗯？領航，我的臉上有什麼嗎？", "え？私の顔に何かついていますか？ナビゲーター。", "0", "0", "嗯？領航，我的臉上有什麼嗎？", "0", "cv_sk_uki_5", "0", "0"},
[4000700108] = {4000700108, 10007001, 9, 5, "15_1_0_0.8", "level1", "領航，總是吃一些不健康的食品對身體不好，讓我給您做些料理吧。", "ナビゲーター、不健康な食品ばかり食べていると、體に悪いですよ？私の自慢の手料理を作ってあげましょう。", "0", "0", "領航，總是吃一些不健康的食品對身體不好，讓我給您做些料理吧。", "0", "cv_sk_uki_6", "0", "0"},
[4000700109] = {4000700109, 10007001, 10, 5, "15_2_0_0.8", "level2", "領航，等閒暇的時候，我們一起去旅行吧，只有你和我喔~", "ナビゲーター、いつか一緒に旅行に行きましょう！私とあなた、二人きりで。", "0", "0", "領航，等閒暇的時候，我們一起去旅行吧，只有你和我噢~", "0", "cv_sk_uki_7", "0", "0"},
[4000700110] = {4000700110, 10007001, 11, 5, "15_2_0_0.8", "level2", "真希望這樣的時光能一直持續下去啊……領航，您以後想和什麼樣的人結婚呢？", "こんな日が続くといいのにって思います……ナビゲーターは將來、どんな方と結婚したいのですか？", "0", "0", "真希望這樣的時光能一直持續下去啊……領航，您以後想和什麼樣的人結婚呢？", "0", "cv_sk_uki_8", "0", "0"},
[4000700111] = {4000700111, 10007001, 12, 6, "0", "0", "料理的水準也提高了呢。", "料理の腕が上がったみたいですね。", "0", "0", "料理的水準也提高了呢。", "0", "cv_sk_uki_9", "0", "0"},
[4000700112] = {4000700112, 10007001, 13, 7, "0", "0", "果然，我對領航來說是特別的嗎……", "やはり、ナビゲーターにとって、私は特別な存在なのですね……", "0", "0", "果然，我對領航來說是特別的嗎……", "0", "cv_sk_uki_10", "0", "0"},
[4000700113] = {4000700113, 10007001, 14, 8, "0", "0", "我感受到了，領航您那顆炙熱的心。為了回應那份熱情，海姬會傾盡所有的。", "感じていますよ、ナビゲーターのその熱い心。私は全てをかけてその情熱に応えます。", "0", "0", "我感受到了，領航您那顆炙熱的心。為了回應那份熱情，海姬會傾盡所有的。", "0", "cv_sk_uki_11", "0", "0"},
[4000700114] = {4000700114, 10007001, 15, 9, "0", "0", "連戰鬥技能也上升了喔~", "戦闘スキルが上達しました。", "0", "0", "連戰鬥技能也上升了噢~", "0", "cv_sk_uki_12", "0", "0"},
[4000700115] = {4000700115, 10007001, 16, 10, "0", "0", "戰場……可不能掉以輕心呢。", "戦場……絶対に気を緩めてはいけません。", "0", "0", "戰場……可不能掉以輕心呢。", "0", "cv_sk_uki_13", "0", "0"},
[4000700116] = {4000700116, 10007001, 17, 11, "0", "0", "戰鬥勝利，太好了~領航，一起回家吧。", "戦闘勝利！よかったですね！一緒に帰りましょう、ナビゲーター。", "0", "0", "戰鬥勝利，太好了~領航，一起回家吧。", "0", "cv_sk_uki_14", "0", "0"},
[4000700117] = {4000700117, 10007001, 18, 12, "0", "0", "有一些遺憾，下次一起努力吧，領航。", "惜しかったですね。また今度一緒に頑張りましょう、ナビゲーター。", "0", "0", "有一些遺憾，下次一起努力吧，領航。", "0", "cv_sk_uki_15", "0", "0"},
[4000700118] = {4000700118, 10007001, 19, 13, "0", "0", "真危險，領航，您沒事吧？", "危ないところでした！ナビゲーター、大丈夫ですか？", "0", "0", "真危險，領航，您沒事吧？", "0", "cv_sk_uki_16", "0", "0"},
[4000700119] = {4000700119, 10007001, 20, 14, "0", "0", "領航，請跟緊我，要撤退了。", "ナビゲーター、撤退しますから、私について來てください。", "0", "0", "領航，請跟緊我，要撤退了。", "0", "cv_sk_uki_17", "0", "0"},
[4000700120] = {4000700120, 10007001, 21, 15, "0", "0", "嘿咻！消滅一隻了！", "やっ！一體、片付けましたね！", "0", "0", "嘿咻！幹掉一隻了！", "0", "cv_sk_uki_18", "0", "0"},
[4000700121] = {4000700121, 10007001, 23, 16, "0", "0", "這是……大海的力量。", "これが……海の力です。", "0", "0", "這是……大海的力量。", "0", "cv_sk_uki_19", "0", "0"},
[4000700122] = {4000700122, 10007001, 26, 19, "0", "0", "抱歉，領航……給您添麻煩了……", "申し訳ありません、ナビゲーター……ご迷惑をお掛けしてしまって……", "0", "0", "抱歉，領航……給您添麻煩了……", "0", "cv_sk_uki_20", "0", "0"},
[4000700123] = {4000700123, 10007001, 27, 20, "0", "0", "領航，您不進來嗎？", "ナビゲーター、入らないのですか？", "0", "0", "領航，您不進來嗎？", "0", "cv_sk_uki_21", "0", "0"},
[4000700124] = {4000700124, 10007001, 28, 21, "0", "0", "海姬從小時候開始，就很喜歡泡在水裡的感覺，您呢？", "私は小さい頃から水の中が好きなんです。あなたは？", "0", "0", "海姬從小時候開始，就很喜歡泡在水裡的感覺，您呢？", "0", "cv_sk_uki_22", "0", "0"},
[4000700125] = {4000700125, 10007001, 29, 21, "0", "0", "一起洗吧，領航您也累了一天了，不是嗎？", "一緒に入りましょう。今日も一日頑張っていましたから、ナビゲーターもお疲れでしょう。", "0", "0", "一起洗吧，領航您也累了一天了，不是嗎？", "0", "cv_sk_uki_23", "0", "0"},
[4000700126] = {4000700126, 10007001, 30, 22, "0", "0", "您要當心腳下的路面呀。", "足元に、お気をつけて。", "0", "0", "您要當心腳下的路面呀。", "0", "cv_sk_uki_24", "0", "0"},
[4000700127] = {4000700127, 10007001, 31, 23, "0", "0", "如果領航能猜中是我的話，我會很高興的。", "當たったら嬉しいです。", "0", "0", "如果領航能猜中是我的話，我會很高興的。", "0", "cv_sk_uki_25", "0", "0"},
[4000700128] = {4000700128, 10007001, 32, 24, "0", "0", "我從一開始，就相信您一定能答對的。", "正解すると信じていましたよ、最初から。", "0", "0", "我從一開始，就相信您一定能答對的。", "0", "cv_sk_uki_26", "0", "0"},
[4000700129] = {4000700129, 10007001, 33, 25, "0", "0", "嗯……沒關係，領航已經盡力了，對吧？", "うーん……大丈夫です。ナビゲーターは全力を盡くしましたから、ね？", "0", "0", "嗯……沒關係，領航已經盡力了，對吧？", "0", "cv_sk_uki_27", "0", "0"},
[4000700130] = {4000700130, 10007001, 34, 26, "0", "0", "領航，今天您也要工作嗎？那麼，我也會一直在這陪您的。", "今日もお仕事ですか、ナビゲーター？では、ここから、ずっとご一緒しますよ。", "0", "0", "領航，今天您也要工作嗎？那麼，我也會一直在這陪您的。", "0", "cv_sk_uki_30", "0", "0"},
[4000700131] = {4000700131, 10007001, 35, 27, "0", "0", "領航，請您帶領著我們前進吧。", "ナビゲーター、私たちを率いて前に進んでください。", "0", "0", "領航，請您帶領著我們前進吧。", "0", "cv_sk_uki_32", "0", "0"},
[4000700132] = {4000700132, 10007001, 36, 28, "0", "0", "您要多注意身體喔。", "お體に気をつけてくださいね。", "0", "0", "您要多注意身體哦。", "0", "cv_sk_uki_33", "0", "0"},
