[4000700134] = {4000700134, 10007001, 38, 30, "0", "0", "要給新的同伴做豐盛的宴席才行。", "新しい仲間のために豪華な宴を用意してあげないと。", "0", "0", "要給新的同伴做豐盛的宴席才行。", "0", "cv_sk_uki_35", "0", "0"},
[4000700135] = {4000700135, 10007001, 39, 31, "0", "0", "舊的東西要記得回收利用喔。", "古いものは回収して再利用するようにしましょう。", "0", "0", "舊的東西要記得回收利用噢。", "0", "cv_sk_uki_36", "0", "0"},
