[4000700138] = {4000700138, 10007001, 42, 34, "0", "0", "變更設定，您在這方面上很認真呢。", "設定の変更、真面目にやっていますね。", "0", "0", "變更設置，您在這方面上很認真呢。", "0", "cv_sk_uki_39", "0", "0"},
