[4001400102] = {4001400102, 10014001, 3, 3, "0", "0", "科羅溫·卡·薇拉，向領航報導，請問這裡附近有買零食的地方嗎？", "0", "0", "0", "柯洛溫·卡·薇拉，向領航報導，請問這裡附近有買零食的地方嗎？", "0", "cv_sk_korovin_1", "0", "0"},
[4001400103] = {4001400103, 10014001, 4, 4, "0", "idle", "零食要吃完了，得想辦法去買一些…領航，能借我一萬盾幣嗎？", "0", "0", "0", "零食要吃完了，得想辦法去買一些…領航，能借我一萬盾幣嗎？", "0", "cv_sk_korovin_3", "0", "0"},
[4001400104] = {4001400104, 10014001, 5, 4, "0", "idle", "不知道小伊莉雅跑哪去了，領航，你知道嗎？", "0", "0", "0", "不知道小伊莉雅跑哪去了，領航，你知道嗎？", "0", "cv_sk_korovin_4", "0", "0"},
[4001400105] = {4001400105, 10014001, 6, 4, "0", "idle", "雖然大家都覺得我們灰燼小隊的人都是怪胎，但是在我眼裏伊莉雅她們都是善良的孩子，只是對別人缺乏信任。不過據我所知，她們對於領航你可是非常信任的。", "0", "0", "0", "雖然大家都覺得我們灰燼小隊的人都是怪胎，但是在我眼裡伊莉雅她們都是善良的孩子，只是對別人缺乏信任。不過據我所知，她們對於領航你可是非常信任的。", "0", "cv_sk_korovin_29", "0", "0"},
[4001400106] = {4001400106, 10014001, 7, 5, "15_1_0_0.8", "level1", "和灰燼的大家在一起的日子，我感到非常開心，真希望這樣的生活能一直持續下去。", "0", "0", "0", "和灰燼的大家在一起的日子，我感到非常開心，真希望這樣的生活能一直持續下去。", "0", "cv_sk_korovin_30", "0", "0"},
[4001400107] = {4001400107, 10014001, 8, 5, "15_1_0_0.8", "level1", "這樣子對待一位女士可是很不禮貌的行為喔。", "0", "0", "0", "這樣子對待一位女士可是很不禮貌的行為哦。", "0", "cv_sk_korovin_5", "0", "0"},
[4001400108] = {4001400108, 10014001, 9, 5, "15_1_0_0.8", "level1", "聽說領航是來自多瑙的，不知道是哪家貴族的公子呢？", "0", "0", "0", "聽說領航是來自多瑙的，不知道是哪家貴族的公子呢？", "0", "cv_sk_korovin_6", "0", "0"},
[4001400109] = {4001400109, 10014001, 10, 5, "15_2_0_0.8", "level2", "雖說在家族的莊園內不愁吃穿，但是還是外面的世界更有意思。", "0", "0", "0", "雖說在家族的莊園內不愁吃穿，但是還是外面的世界更有意思。", "0", "cv_sk_korovin_7", "0", "0"},
[4001400110] = {4001400110, 10014001, 11, 5, "15_2_0_0.8", "level2", "領航，你有喜歡吃的東西嗎？蛋糕怎麼樣？如果你喜歡吃蛋糕的話，哼哼，下次我帶你一起去吃我最喜歡的蛋糕吧！", "0", "0", "0", "領航，你有喜歡吃的東西嗎？蛋糕怎麼樣？如果你喜歡吃蛋糕的話，哼哼，下次我帶你一起去吃我最喜歡的蛋糕吧！", "0", "cv_sk_korovin_8", "0", "0"},
