[4400300104] = {4400300104, 14003001, 91, 4, "0", "idle", "到晚飯時間了嗎？請等等我，馬上就好……", "0", "0", "0", "0", "0", "cv_sk_iria2_47", "0", "0,idle"},
[4400300105] = {4400300105, 14003001, 92, 5, "14_1_0_0.8", "touch1", "沒有防備？因為現在只有我們兩個人。難道說領航想要趁人之危……", "0", "0", "0", "0", "0", "cv_sk_iria2_48", "0", "0,touch1"},
[4400300106] = {4400300106, 14003001, 92, 5, "14_1_0_0.8", "touch1", "我感覺到心跳加速……很美妙的感覺。", "0", "0", "0", "0", "0", "cv_sk_iria2_49", "0", "0,touch1"},
