[4400300110] = {4400300110, 14003001, 92, 5, "14_1_0_0.8", "touch2", "那裏並不是……不過我並不討厭……被領航撫摸的感覺。", "0", "0", "0", "0", "0", "cv_sk_iria2_53", "0", "0,touch2"},
