[4400300112] = {4400300112, 14003001, 91, 4, "0", "idle3", "明明穿的更少了，感覺卻更熱了。", "0", "0", "0", "0", "0", "cv_sk_iria2_55", "0", "0,idle3"},
[4400300113] = {4400300113, 14003001, 92, 5, "14_1_0_0.8", "touch3", "唔……領航手掌的溫度，感受更明顯了……是比複仇還要燙的火焰。", "0", "0", "0", "0", "0", "cv_sk_iria2_56", "0", "0,touch3"},
[4400300114] = {4400300114, 14003001, 92, 5, "14_1_0_0.8", "touch3", "如今我也有自信以如此坦誠的樣貌出現在您的面前，今後我想要永遠陪伴在您左右。", "0", "0", "0", "0", "0", "cv_sk_iria2_57", "0", "0,touch3"},
[4400300115] = {4400300115, 14003001, 12, 6, "0", "0", "力量從身體裏湧現。", "0", "0", "0", "0", "0", "cv_sk_iria2_12", "0", "0"},
