[4101600102] = {4101600102, 11016001, 3, 3, "0", "0", "忍心社，黑羽，從今天開始擔任您的護衛，我會寸步不離地守候在您周圍的。", "忍心社、黒羽。今日からナビゲーター殿の護衛として、一歩も離れません。", "0", "0", "忍心社，黑羽，從今天開始擔任您的護衛，我會寸步不離地守候在您周圍的。", "0", "cv_sk_heiyu_1", "0", "0"},
[4101600103] = {4101600103, 11016001, 4, 4, "0", "idle", "領航，我的職責並不是監視您，而是保護您。只有這點，請不要弄錯。", "ナビゲーター殿。私の役目は監視ではなく、護衛です。これだけは、誤解しないでいただきたい。", "0", "0", "領航，我的職責並不是監視您，而是保護您。只有這點，請不要弄錯。", "0", "cv_sk_heiyu_3", "0", "0"},
[4101600104] = {4101600104, 11016001, 5, 4, "0", "idle", "我不會那些光怪陸離的忍術，至於刺殺的技藝，也只是一知半解。不過，我向您保證，在我的視野範圍內，您不會有任何危險。", "奇妙な忍術はできませんし、暗殺の技も未熟ですが、私の目が黒いうちは、ナビゲーター殿を危険を曬すようなことはないと、保証します。", "0", "0", "我不會那些光怪陸離的忍術，至於刺殺的技藝，也只是一知半解。不過，我向您保證，在我的視野範圍內，您不會有任何危險。", "0", "cv_sk_heiyu_4", "0", "0"},
[4101600105] = {4101600105, 11016001, 6, 4, "0", "idle", "轟雷隊長是去外出執行任務了嗎？真遺憾，我本來想向她學習一些戰鬥的技巧呢。", "轟雷隊長は、任務でご不在なのですか？戦闘のコツを教えて頂きたかったのですが、殘念です。", "0", "0", "轟雷隊長是去外出執行任務了嗎？真遺憾，我本來想向她學習一些戰鬥的技巧呢。", "0", "cv_sk_heiyu_29", "0", "0"},
[4101600106] = {4101600106, 11016001, 7, 5, "15_1_0_0.8", "level1", "我並不是效忠於艾吉斯…只是平等交易罷了。他們為“黑羽”提供了庇佑的住所，而我為他們服務。", "私はアイギスに忠誠を誓った訳ではなく、取引をしただけです。彼らは黒羽に住処を提供し、その対価として、私は任務を果たすのです。", "0", "0", "我並不是效忠于艾吉斯…只是平等交易罷了。他們為“黑羽”提供了庇佑的住所，而我為他們服務。", "0", "cv_sk_heiyu_30", "0", "0"},
[4101600107] = {4101600107, 11016001, 8, 5, "15_1_0_0.8", "level1", "您這樣做，有什麼特別的含義嗎？", "これは、何か特別な意味があるのですか？", "0", "0", "您這樣做，有什麼特別的含義嗎？", "0", "cv_sk_heiyu_5", "0", "0"},
[4101600108] = {4101600108, 11016001, 9, 5, "15_1_0_0.8", "level1", "我不能理解您的行為…“想和我更加親近一些”？…呵呵，真是奇怪啊。", "主殿の行動が理解できないのですが……私ともっと親しくなりたい？……フフ。変なことをおっしゃいますね。", "0", "0", "我不能理解您的行為…“想和我更加親近一些”？…呵呵，真是奇怪啊。", "0", "cv_sk_heiyu_6", "0", "0"},
[4101600109] = {4101600109, 11016001, 10, 5, "15_2_0_0.8", "level2", "領航，您對我的過去感興趣嗎？雖然按照規定應該是要對您保密的…不過，如果您想知道的話……我會把您想知道的，都告訴您的。", "私の過去に興味があるのですか？掟は秘密にしなければならないのですが……もし主殿が知りたいのであれば……全てお話しします。", "0", "0", "領航，您對我的過去感興趣嗎？雖然按照規定應該是要對您保密的…不過，如果您想知道的話……我會把您想知道的，都告訴您的。", "0", "cv_sk_heiyu_7", "0", "0"},
[4101600110] = {4101600110, 11016001, 11, 5, "15_2_0_0.8", "level2", "…是該承認這一點了。領…領航，您的確和其他人不一樣。從您身上，我感受不到其他人的偏見……您並沒有把我視為達成目的的道具，而是當做同您一樣的“人”對待。", "……認めざるを得ないようですね。主殿は、確かに他の人とは違って、私を偏見の目で見ることがありませんでした。目的達成のための道具ではなく、自分と同じ「人間」として見てくださったのですね。", "0", "0", "…是該承認這一點了。領…領航，您的確和其他人不一樣。從您身上，我感受不到其他人的偏見……您並沒有把我視為達成目的的道具，而是當做同您一樣的“人”對待。", "0", "cv_sk_heiyu_8", "0", "0"},
[4101600111] = {4101600111, 11016001, 12, 6, "0", "0", "感謝。", "感謝します。", "0", "0", "感謝。", "0", "cv_sk_heiyu_9", "0", "0"},
[4101600112] = {4101600112, 11016001, 13, 7, "0", "0", "箭矢，將貫穿您的敵人。", "主殿の敵を貫く矢となります。", "0", "0", "箭矢，將貫穿您的敵人。", "0", "cv_sk_heiyu_10", "0", "0"},
[4101600113] = {4101600113, 11016001, 14, 8, "0", "0", "您…給予了我愛。無論這份愛是友情、是親情、是愛情，哪怕是同情…我都會用忠誠回報您。這就是“黑羽”的信條。", "主殿は、私に愛をくださいました。たとえその愛が友情であろうと、愛情であろうと……同情であっても……私は忠誠をもってお応えします。これが黒羽のやり方です。", "0", "0", "您…給予了我愛。無論這份愛是友情、是親情、是愛情，哪怕是同情…我都會用忠誠回報您。這就是“黑羽”的信條。", "0", "cv_sk_heiyu_11", "0", "0"},
[4101600114] = {4101600114, 11016001, 15, 9, "0", "0", "讓您的敵人，更加痛苦吧。", "我らが敵に、もっと苦痛を與えましょう。", "0", "0", "讓您的敵人，更加痛苦吧。", "0", "cv_sk_heiyu_12", "0", "0"},
[4101600115] = {4101600115, 11016001, 16, 10, "0", "0", "抵達目的地。", "目的地到著。", "0", "0", "抵達目的地。", "0", "cv_sk_heiyu_13", "0", "0"},
[4101600116] = {4101600116, 11016001, 17, 11, "0", "0", "為了領航，我會掃清所有的阻礙。", "主殿の前に立ちはだかる全てを排除します。", "0", "0", "為了領航，我會掃清所有的阻礙。", "0", "cv_sk_heiyu_14", "0", "0"},
[4101600117] = {4101600117, 11016001, 18, 12, "0", "0", "嘁…真是難纏的敵人。", "ふう……しつこい敵でした。", "0", "0", "嘁…真是難纏的敵人。", "0", "cv_sk_heiyu_15", "0", "0"},
[4101600118] = {4101600118, 11016001, 19, 13, "0", "0", "只要您平安無事就好。", "主殿が無事で何よりです。", "0", "0", "只要您平安無事就好。", "0", "cv_sk_heiyu_16", "0", "0"},
[4101600119] = {4101600119, 11016001, 20, 14, "0", "0", "我會讓您安全離開戰場的。", "主殿を安全な場所までお連れします……！", "0", "0", "我會讓您安全離開戰場的。", "0", "cv_sk_heiyu_17", "0", "0"},
[4101600120] = {4101600120, 11016001, 21, 15, "0", "0", "消失在黑夜中吧。", "闇夜に散れ。", "0", "0", "消失在黑夜中吧。", "0", "cv_sk_heiyu_18", "0", "0"},
[4101600121] = {4101600121, 11016001, 23, 16, "0", "0", "一擊。", "一撃。", "0", "0", "一擊。", "0", "cv_sk_heiyu_19", "0", "0"},
[4101600122] = {4101600122, 11016001, 24, 17, "0", "0", "在你的身後！", "隙あり！", "0", "0", "在你的身後！", "0", "cv_sk_heiyu_21", "0", "0"},
[4101600123] = {4101600123, 11016001, 26, 19, "0", "0", "很抱歉…沒法再保護您了……", "すみません…もう守れない……", "0", "0", "很抱歉…沒法再保護您了……", "0", "cv_sk_heiyu_20", "0", "0"},
[4101600124] = {4101600124, 11016001, 27, 20, "0", "0", "清洗？我明白了。", "禊ですか？承知しました。", "0", "0", "清洗？我明白了。", "0", "cv_sk_heiyu_22", "0", "0"},
[4101600125] = {4101600125, 11016001, 28, 21, "0", "0", "這種感覺，真不習慣啊。", "こういうのは、あまり慣れていなくて……", "0", "0", "這種感覺，真不習慣啊。", "0", "cv_sk_heiyu_23", "0", "0"},
[4101600126] = {4101600126, 11016001, 29, 21, "0", "0", "領航為下屬服務…這種事真的能被允許嗎？", "主殿が部下に奉仕するなど……こんなことが本當に許されるのですか？", "0", "0", "領航為下屬服務…這種事真的能被允許嗎？", "0", "cv_sk_heiyu_24", "0", "0"},
[4101600127] = {4101600127, 11016001, 30, 22, "0", "0", "請退後。", "お下がりください。", "0", "0", "請退後。", "0", "cv_sk_heiyu_25", "0", "0"},
[4101600128] = {4101600128, 11016001, 31, 23, "0", "0", "…領航，這樣做的意義是什麼？", "……主殿。これは、どういう意味があるのでしょうか？", "0", "0", "…領航，這樣做的意義是什麼？", "0", "cv_sk_heiyu_26", "0", "0"},
[4101600129] = {4101600129, 11016001, 32, 24, "0", "0", "您…是怎麼認出我的？", "なぜお分かりになったのですか？", "0", "0", "您…是怎麼認出我的？", "0", "cv_sk_heiyu_27", "0", "0"},
[4101600130] = {4101600130, 11016001, 33, 25, "0", "0", "嗯…沒猜對…嗎……", "……ハズレ…ですか……", "0", "0", "嗯…沒猜對…嗎……", "0", "cv_sk_heiyu_28", "0", "0"},
[4101600131] = {4101600131, 11016001, 34, 26, "0", "0", "領航，您外出的這段時間，有遇到可疑的事嗎？", "主殿。外出先で何か変わったことはなかったですか？", "0", "0", "領航，您外出的這段時間，有遇到可疑的事嗎？", "0", "cv_sk_heiyu_31", "0", "0"},
[4101600132] = {4101600132, 11016001, 35, 27, "0", "0", "領航，出發吧。不過，請不要離開我的身邊。", "主殿、參りましょう。くれぐれも私のそばから離れぬように。", "0", "0", "領航，出發吧。不過，請不要離開我的身邊。", "0", "cv_sk_heiyu_33", "0", "0"},
[4101600133] = {4101600133, 11016001, 36, 28, "0", "0", "磨煉技藝，才能更好的保護您。", "主殿を守るため、さらに腕前を磨かねば。", "0", "0", "磨煉技藝，才能更好的保護您。", "0", "cv_sk_heiyu_34", "0", "0"},
[4101600134] = {4101600134, 11016001, 37, 29, "0", "0", "刺客…沒有呢。", "刺客は……いないようですね。", "0", "0", "刺客…沒有呢。", "0", "cv_sk_heiyu_35", "0", "0"},
[4101600135] = {4101600135, 11016001, 38, 30, "0", "0", "要招募新人嗎？", "新人を募集するのですか？", "0", "0", "要招募新人嗎？", "0", "cv_sk_heiyu_36", "0", "0"},
[4101600136] = {4101600136, 11016001, 39, 31, "0", "0", "您會給我…準備新武器嗎？", "s", "0", "0", "您會給我…準備新武器嗎？", "0", "cv_sk_heiyu_37", "0", "0"},
[4101600137] = {4101600137, 11016001, 40, 32, "0", "0", "請您隨意。", "どうぞご自由に。", "0", "0", "請您隨意。", "0", "cv_sk_heiyu_38", "0", "0"},
[4101600138] = {4101600138, 11016001, 41, 33, "0", "0", "嗯，就是您。", "ええ。間違いなく主殿です。", "0", "0", "嗯，就是您。", "0", "cv_sk_heiyu_39", "0", "0"},
[4101600139] = {4101600139, 11016001, 42, 34, "0", "0", "麻煩……", "む…面倒な……", "0", "0", "麻煩……", "0", "cv_sk_heiyu_40", "0", "0"},
[4101600140] = {4101600140, 11016001, 43, 35, "0", "0", "我能先檢查麼？", "危険がないか、確認します。", "0", "0", "我能先檢查麼？", "0", "cv_sk_heiyu_41", "0", "0"},
[4101600141] = {4101600141, 11016001, 44, 36, "0", "0", "請牢記保護隱私。", "どうかプライバシーにはご注意を。", "0", "0", "請牢記保護隱私。", "0", "cv_sk_heiyu_42", "0", "0"},
[4101600142] = {4101600142, 11016001, 45, 37, "0", "0", "慎重行事。", "お気をつけて。", "0", "0", "慎重行事。", "0", "cv_sk_heiyu_43", "0", "0"},
[4201900100] = {4201900100, 12019001, 1, 1, "0", "0", "蒼霧殘響。", "0", "0", "0", "0", "0", "cv_sk_kaitelin_1", "0", "0"},
[4201900101] = {4201900101, 12019001, 2, 2, "0", "0", "接下來的任務是駐守這裡？", "0", "0", "0", "0", "0", "cv_sk_kaitelin_2", "0", "0"},
[4201900102] = {4201900102, 12019001, 3, 3, "0", "0", "黑荊棘編號ODY763001，你也可以叫我的名字——凱特琳。", "0", "0", "0", "0", "0", "cv_sk_kaitelin_3", "0", "0"},
[4201900103] = {4201900103, 12019001, 4, 4, "0", "idle", "恕我直言，這裡的安防措施在我看來漏洞百出。", "0", "0", "0", "0", "0", "cv_sk_kaitelin_4", "0", "0"},
[4201900104] = {4201900104, 12019001, 5, 4, "0", "idle", "我不太理解領航你的想法，佔用我一個駕駛員的戰鬥力僅僅是在這裡站崗？", "0", "0", "0", "0", "0", "cv_sk_kaitelin_5", "0", "0"},
[4201900105] = {4201900105, 12019001, 6, 4, "0", "idle", "管理一個小隊並不輕鬆，特別是當你的隊員都是擁有強烈個人色彩的傢夥的時候。不過所幸我在當員警時管理過不少這樣的人。", "0", "0", "0", "0", "0", "cv_sk_kaitelin_6", "0", "0"},
[4201900106] = {4201900106, 12019001, 7, 5, "1_》_0_0.8", "leve", "我只是想守護我想守護的東西，作為特警的我失敗了，但是作為駕駛員的我一定會成功。你會幫我？那一言為定……怎麼，你以為我是那種自負的笨蛋嗎？", "0", "0", "0", "0", "0", "cv_sk_kaitelin_7", "0", "0"},
[4201900107] = {4201900107, 12019001, 8, 5, "1_》_0_0.8", "leve", "哼，這次只是警告。", "0", "0", "0", "0", "0", "cv_sk_kaitelin_8", "0", "0"},
[4201900108] = {4201900108, 12019001, 9, 5, "1_》_100_1.5", "leve", "碰我可以但不能碰我的槍。", "0", "0", "0", "0", "0", "cv_sk_kaitelin_9", "0", "0"},
[4201900109] = {4201900109, 12019001, 10, 5, "1_》_500_2", "leve", "聽說領航你也懂一點射擊？只用過手槍嗎……那你想要試試狙擊槍嗎？我們可以先從後坐力最小的練起。", "0", "0", "0", "0", "0", "cv_sk_kaitelin_10", "0", "0"},
[4201900110] = {4201900110, 12019001, 11, 5, "1_》_1000_2.5", "leve", "領航上次戰鬥你使用的那套戰術效果非凡，我有幾個戰鬥上的想法想與你探討探討。要不我們去你的住處吧，免得閒人打擾，或者到我的住處也行。", "0", "0", "0", "0", "0", "cv_sk_kaitelin_11", "0", "0"},
[4201900111] = {4201900111, 12019001, 12, 6, "0", "0", "很特殊的練習方法。", "0", "0", "0", "0", "0", "cv_sk_kaitelin_12", "0", "0"},
[4201900112] = {4201900112, 12019001, 13, 7, "0", "0", "軍銜提升了嗎？", "0", "0", "0", "0", "0", "cv_sk_kaitelin_13", "0", "0"},
[4201900113] = {4201900113, 12019001, 14, 8, "0", "0", "奇怪的感覺，好像槍更趁手了。", "0", "0", "0", "0", "0", "cv_sk_kaitelin_14", "0", "0"},
[4201900114] = {4201900114, 12019001, 15, 9, "0", "0", "不練習就會生疏。", "0", "0", "0", "0", "0", "cv_sk_kaitelin_15", "0", "0"},
[4201900115] = {4201900115, 12019001, 16, 10, "0", "0", "黑荊棘小隊，到達目標地點。", "0", "0", "0", "0", "0", "cv_sk_kaitelin_16", "0", "0"},
[4201900116] = {4201900116, 12019001, 17, 11, "0", "0", "任務完成，等待進一步指示——", "0", "0", "0", "0", "0", "cv_sk_kaitelin_17", "0", "0"},
