[4300000102] = {4300000102, 13000001, 3, 3, "0", "0", "哇呼——你是誰？原來是領航，你好，我是歐朵啦。呼——", "ふぁ――あなた、誰？ナビゲーターだったのね。初めまして。あたしはオードラ。ふぁ――", "0", "0", "哇呼——你是誰？原來是領航，你好，我是歐朵啦。呼——", "0", "cv_sk_odora_1", "0", "0"},
[4300000103] = {4300000103, 13000001, 4, 4, "0", "idle", "明明睡眠很充足，為什麼長不高呢……領航有什麼長高的秘訣嗎？牛奶……露露啦也是這麼說的……好吧，相信你們……", "たっぷり寢てるのに、背が伸びないんだよね。何でだろう……ナビゲーターって、背を伸ばす秘訣とか何か知らない？ミルクか……ルルラもそう言ってたなあ……よし、あなたたちの言うことを信じようっと……", "0", "0", "明明睡眠很充足，為什麼長不高呢……領航有什麼長高的秘訣嗎？牛奶……露露啦也是這麼說的……好吧，相信你們……", "0", "cv_sk_odora_3", "0", "0,idle"},
[4300000104] = {4300000104, 13000001, 5, 4, "0", "idle", "哼哼——哼哼——太陽出來啦～領航和我出去玩吧～露露啦說多曬太陽才能長高哇～", "ふふふん～ふんふん～♪お日様が出てきたよ、あたしと出かけて遊ぼ、ね、ナビゲーター。背を伸ばすにはひなたぼっこを沢山しないといけないってルルラも言ってたの。", "0", "0", "哼哼——哼哼——太陽出來啦～領航和我出去玩吧～露露啦說多曬太陽才能長高哇～", "0", "cv_sk_odora_4", "0", "0,idle"},
[4300000105] = {4300000105, 13000001, 6, 4, "0", "idle", "肚子餓了……露露啦，你在哪~我肚子餓了~~~", "お腹空いた……ルルラ！どこにいるの、お腹空いたよ～……", "0", "0", "肚子餓了……露露啦，你在哪~我肚子餓了~~~", "0", "cv_sk_odora_27", "0", "0,idle"},
