[4300000129] = {4300000129, 13000001, 34, 26, "0", "0", "領航回來了啊……呼……呼……好困……", "ナビゲーター、帰ってきたんだ……ふぁ……ふぁ……眠い……", "0", "0", "領航回來了啊……呼……呼……好困……", "0", "cv_sk_odora_29", "0", "0"},
[4300000130] = {4300000130, 13000001, 35, 27, "0", "0", "要出去玩了嗎？欸？不是嗎……嗚，想去睡覺了……", "外に出かけて遊ぶの？え？違うの？……うっ、寢てたい……", "0", "0", "要出去玩了嗎？誒？不是嗎……嗚，想去睡覺了……", "0", "cv_sk_odora_31", "0", "0"},
[4300000131] = {4300000131, 13000001, 36, 28, "0", "0", "想睡覺了啦……", "眠りたいよ……", "0", "0", "想睡覺了啦……", "0", "cv_sk_odora_32", "0", "0"},
[4300000132] = {4300000132, 13000001, 37, 29, "0", "0", "露露啦在哪？", "ルルラはどこ？", "0", "0", "露露啦在哪？", "0", "cv_sk_odora_33", "0", "0"},
[4300000133] = {4300000133, 13000001, 38, 30, "0", "0", "這裡是招人的地方~", "ここは人材を募集する場所だよ～", "0", "0", "這裡是招人的地方~", "0", "cv_sk_odora_34", "0", "0"},
[4300000134] = {4300000134, 13000001, 39, 31, "0", "0", "補給裝備的地方~", "裝備補給の場所だよ～", "0", "0", "補給裝備的地方~", "0", "cv_sk_odora_35", "0", "0"},
[4300000135] = {4300000135, 13000001, 40, 32, "0", "0", "這裡是買東西的地方~", "ここは買い物をする場所だよ～", "0", "0", "這裡是買東西的地方~", "0", "cv_sk_odora_36", "0", "0"},
[4300000136] = {4300000136, 13000001, 41, 33, "0", "0", "這裡是領航……", "ここはナビゲーター……", "0", "0", "這裡是領航……", "0", "cv_sk_odora_37", "0", "0"},
[4300000137] = {4300000137, 13000001, 42, 34, "0", "0", "變更設定的地方~", "設定を変更する場所だよ～", "0", "0", "變更設置的地方~", "0", "cv_sk_odora_38", "0", "0"},
