[4300000139] = {4300000139, 13000001, 44, 36, "0", "0", "好多人說話的地方……", "沢山の人がおしゃべりする場所……", "0", "0", "好多人說話的地方……", "0", "cv_sk_odora_40", "0", "0"},
[4300000140] = {4300000140, 13000001, 45, 37, "0", "0", "我能去睡覺了嗎？", "もう寢ていい？", "0", "0", "我能去睡覺了嗎？", "0", "cv_sk_odora_41", "0", "0"},
[4102300200] = {4102300200, 11023002, 1, 1, "0", "0", "蒼霧殘響", "ハツリバーブ。", "0", "0", "0", "0", "cv_sk2_xiaomeng_1", "0", "0"},
[4102300201] = {4102300201, 11023002, 2, 2, "0", "0", "這就是閣下經常呆的地方嗎。嗯……嗯！那現在這裏就是曉夢要守護的地方了。", "ここが殿がよくいる場所か……うん……うん！では、今からここが暁夢（ぎょうむ）の守備範囲だな！", "0", "0", "0", "0", "cv_sk2_xiaomeng_2", "0", "0"},
[4102300202] = {4102300202, 11023002, 3, 3, "0", "0", "閣下，聽到你的呼喚，曉夢馬上就來幫忙了。這次又要給予曉夢什麼樣的試煉呢？", "殿の呼びかけに応じ、暁夢、ここに參上！さあ、今回はどのような試練が待っているんだ？", "0", "0", "0", "0", "cv_sk2_xiaomeng_3", "0", "0"},
[4102300203] = {4102300203, 11023002, 4, 4, "0", "idle", "诶……！穿着一身就不要练拳了？为什么？……呜，虽然有一点点难受……不过晓梦会遵守命令的……", "この拳の意味？分からん、考えたこともない。師匠が拳法を教え、暁夢はそれを修める。それだけのことだ。暁夢が何のためにどうやって拳を出すのか。それは殿に任せる。殿が思うところに我が拳あり！それが暁夢の生き様だ！", "0", "0", "0", "0", "cv_sk2_xiaomeng_46", "0", "0"},
[4102300204] = {4102300204, 11023002, 5, 4, "0", "idle", "挠痒痒……？晓梦可不会怕这个哦！尽管来吧！", "殿が修行をつけてくれると澄練（ちょうれん）から聞いたんだ。今からどんな命令にも従うぞ！", "0", "0", "0", "0", "cv_sk2_xiaomeng_55", "0", "0"},
[4102300205] = {4102300205, 11023002, 6, 4, "0", "idle", "阁下不试试吗，我送的情人节礼物？", "その拳に乗せるものを探しなさい……母上はそう言って、暁夢を追い出したんだ。殿。この意味が分かるか？", "0", "0", "0", "0", "cv_sk2_xiaomeng_56", "0", "0"},
[4102300206] = {4102300206, 11023002, 7, 5, "1_》_0_0.8", "level", "我今天只要跟着阁下行动就好了吧？嘿嘿……太好了！", "と、殿？何をしているんだ？", "0", "0", "0", "0", "cv_sk2_xiaomeng_49", "0", "0"},
[4102300207] = {4102300207, 11023002, 8, 5, "1_》_0_0.8", "level", "哇哦，我们今天这样打扮是要当“便衣警察”对吧，所以要揍谁？尽管吩咐好了！", "拳法を始めた時は痛かった拳が、今はもう痛むことはない。暁夢の手を見てみるか？", "0", "0", "0", "0", "cv_sk2_xiaomeng_50", "0", "0"},
[4102300208] = {4102300208, 11023002, 9, 5, "1_》_100_1.5", "level", "哇~晓梦自己会穿衣服的~不用领航帮忙~", "殿。暁夢に命令をくれ。暁夢は殿の言うことを聞きたい。暁夢は……殿の傍にいたい……", "0", "0", "0", "0", "cv_sk2_xiaomeng_52", "0", "0"},
[4102300209] = {4102300209, 11023002, 10, 5, "1_》_500_2", "level", "呜……有种燃烧起来的感觉……", "殿。暁夢は少し分かってきた気がする……でも、もっと落ち著いて考えてから、話そうと思う。だから今はここまでだ。", "0", "0", "0", "0", "cv_sk2_xiaomeng_53", "0", "0"},
[4102300210] = {4102300210, 11023002, 11, 5, "1_》_1000_2.5", "level", "我的脸很红？是的！晓梦的心现在正“咚咚咚”地狂跳……啊！难道说阁下希望我冷静下来吗！？", "考えることは大切だけど……決めることも大切だな！で、暁夢は平心社のみんなが大切で……でも！殿も大切な存在で……うーん……申し訳ない。いまの暁夢は、これぐらいしか分からない。……だからこれから一緒に考えてくれ！", "0", "0", "0", "0", "cv_sk2_xiaomeng_54", "0", "0"},
[4102300211] = {4102300211, 11023002, 12, 6, "0", "0", "原來如此，還有這種練習方式。", "このような修行があるとは！", "0", "0", "0", "0", "cv_sk2_xiaomeng_12", "0", "0"},
[4102300212] = {4102300212, 11023002, 13, 7, "0", "0", "這樣做的目的是什麼。", "もっと體を鍛えるぞ！", "0", "0", "0", "0", "cv_sk2_xiaomeng_13", "0", "0"},
[4102300213] = {4102300213, 11023002, 14, 8, "0", "0", "該練練脊骨了……", "うおぉー！こんなにスッキリしたのは久しぶりだ！どうだ！暁夢は殿の望む姿になれたか？", "0", "0", "0", "0", "cv_sk2_xiaomeng_14", "0", "0"},
[4102300214] = {4102300214, 11023002, 15, 9, "0", "0", "無過不及，隨曲就伸！", "過ぎること及ばざることなく、曲に隨（したが）い伸（しん）に就（つ）く！", "0", "0", "0", "0", "cv_sk2_xiaomeng_15", "0", "0"},
[4102300215] = {4102300215, 11023002, 16, 10, "0", "0", "九州平心社，“武夫”曉夢，請指教。", "九州平心社（きゅうしゅうへいしんしゃ）の武者、暁夢。參る！", "0", "0", "0", "0", "cv_sk2_xiaomeng_16", "0", "0"},
[4102300216] = {4102300216, 11023002, 17, 11, "0", "0", "簡單，順利完成了！", "押忍、一件落著！", "0", "0", "0", "0", "cv_sk2_xiaomeng_17", "0", "0"},
[4102300217] = {4102300217, 11023002, 18, 12, "0", "0", "積累了經驗，再來一次吧！", "経験は積んだ、もう一度！", "0", "0", "0", "0", "cv_sk2_xiaomeng_18", "0", "0"},
[4102300218] = {4102300218, 11023002, 19, 13, "0", "0", "棋差半步啊。", "一手足りないか……！", "0", "0", "0", "0", "cv_sk2_xiaomeng_19", "0", "0"},
[4102300219] = {4102300219, 11023002, 20, 14, "0", "0", "勝敗乃常事，曉夢陪閣下重新來過吧。", "勝敗は兵家の常だ。殿が命じてくれるのなら暁夢が再び挑んでやる！", "0", "0", "0", "0", "cv_sk2_xiaomeng_20", "0", "0"},
[4102300220] = {4102300220, 11023002, 21, 15, "0", "0", "好烦啊——————！！！", "倒す。それだけだ。", "0", "0", "0", "0", "cv_sk2_xiaomeng_57", "0", "0"},
[4102300221] = {4102300221, 11023002, 23, 16, "0", "0", "都说了不能战斗了！", "いちっ！", "0", "0", "0", "0", "cv_sk2_xiaomeng_58", "0", "0"},
[4102300222] = {4102300222, 11023002, 24, 17, "0", "0", "啊？", "にっ！", "0", "0", "0", "0", "cv_sk2_xiaomeng_59", "0", "0"},
[4102300223] = {4102300223, 11023002, 25, 18, "0", "0", "烟消云散吧！", "虛領頂勁。はぁーー！", "0", "0", "0", "0", "cv_sk2_xiaomeng_60", "0", "0"},
[4102300224] = {4102300224, 11023002, 26, 19, "0", "0", "晚饭我就不回去吃了！", "暁夢は……錆びてしまったのか……", "0", "0", "0", "0", "cv_sk2_xiaomeng_62", "0", "0"},
[4102300225] = {4102300225, 11023002, 27, 20, "0", "0", "久候多時了，今天是要……那個吧……以前媽媽經常做的……藥浴……", "待っていたぞ。今日は…あの…昔、母上がよくやっていた薬湯をするんだな？", "0", "0", "0", "0", "cv_sk2_xiaomeng_26", "0", "0"},
[4102300226] = {4102300226, 11023002, 28, 21, "0", "0", "閣下……不向曉夢下要求嗎……曉夢會聽閣下的話哦。", "殿……暁夢に命令はないか？……ちゃんと従うぞ。", "0", "0", "0", "0", "cv_sk2_xiaomeng_27", "0", "0"},
[4102300227] = {4102300227, 11023002, 29, 21, "0", "0", "乖乖這樣就可以了嗎，只是一個姿勢的話，有些地方會洗不乾淨哦……", "これでいいのか？同じ體勢だけだと、すみずみまできれいに洗えないだろ……？", "0", "0", "0", "0", "cv_sk2_xiaomeng_28", "0", "0"},
[4102300228] = {4102300228, 11023002, 30, 22, "0", "0", "要開始了嗎……", "やってみるか？", "0", "0", "0", "0", "cv_sk2_xiaomeng_29", "0", "0"},
[4102300229] = {4102300229, 11023002, 31, 23, "0", "0", "曉夢相信閣下。", "暁夢は殿を信じるぞ。", "0", "0", "0", "0", "cv_sk2_xiaomeng_30", "0", "0"},
[4102300230] = {4102300230, 11023002, 32, 24, "0", "0", "分清楚是和非、正確和錯誤。閣下就是教會曉夢這個道理的人。", "善と悪、正解と不正解を見極める。殿がこの道理を教えてくれたんだ！", "0", "0", "0", "0", "cv_sk2_xiaomeng_31", "0", "0"},
[4102300231] = {4102300231, 11023002, 33, 25, "0", "0", "閣下！", "殿！", "0", "0", "0", "0", "cv_sk2_xiaomeng_32", "0", "0"},
[4102300232] = {4102300232, 11023002, 34, 26, "0", "0", "天气真好~今天又有什么新命令？", "おかえり、殿！暁夢はちゃんと言いつけ通り留守番をしてたぞ！", "0", "0", "0", "0", "cv_sk2_xiaomeng_63", "0", "0"},
[4102300233] = {4102300233, 11023002, 35, 27, "0", "0", "下達命令吧，閣下。", "命令をくれ！殿！", "0", "0", "0", "0", "cv_sk2_xiaomeng_34", "0", "0"},
[4102300234] = {4102300234, 11023002, 36, 28, "0", "0", "準備踏青了嗎。", "ピクニックにでも行くのか？", "0", "0", "0", "0", "cv_sk2_xiaomeng_35", "0", "0"},
[4102300235] = {4102300235, 11023002, 37, 29, "0", "0", "好強的氣息……", "強者の気配がするぞ……", "0", "0", "0", "0", "cv_sk2_xiaomeng_36", "0", "0"},
[4102300236] = {4102300236, 11023002, 38, 30, "0", "0", "……", "……色々な気配があるな。", "0", "0", "0", "0", "cv_sk2_xiaomeng_37", "0", "0"},
[4102300237] = {4102300237, 11023002, 39, 31, "0", "0", "身外之物罷了。", "大事なのは己の肉體だ！", "0", "0", "0", "0", "cv_sk2_xiaomeng_38", "0", "0"},
[4102300238] = {4102300238, 11023002, 40, 32, "0", "0", "銀貨兩訖。", "貸し借りなし。だろ？", "0", "0", "0", "0", "cv_sk2_xiaomeng_39", "0", "0"},
[4102300239] = {4102300239, 11023002, 41, 33, "0", "0", "哦哦，曉夢也有類似的檔案！", "おぉ。暁夢にもこんなプロフィールがあるぞ。", "0", "0", "0", "0", "cv_sk2_xiaomeng_40", "0", "0"},
[4102300240] = {4102300240, 11023002, 42, 34, "0", "0", "設定好了嗎。", "設定できたか？", "0", "0", "0", "0", "cv_sk2_xiaomeng_41", "0", "0"},
[4102300241] = {4102300241, 11023002, 43, 35, "0", "0", "書信來去。", "手紙は行ったり來たりするものだよな。", "0", "0", "0", "0", "cv_sk2_xiaomeng_42", "0", "0"},
[4102300242] = {4102300242, 11023002, 44, 36, "0", "0", "聒噪，曉夢只想聽閣下的聲音。", "うるさいな。暁夢は殿の聲だけが聞きたいのだ。", "0", "0", "0", "0", "cv_sk2_xiaomeng_43", "0", "0"},
[4102300243] = {4102300243, 11023002, 45, 37, "0", "0", "哦哦！", "おおぉ！", "0", "0", "0", "0", "cv_sk2_xiaomeng_44", "0", "0"},
[4300600200] = {4300600200, 13006002, 1, 1, "0", "0", "蒼霧殘響。", "0", "0", "0", "蒼霧殘響。", "0", "cv_sk1_yincao_31", "0", "0"},
[4300600201] = {4300600201, 13006002, 2, 2, "0", "0", "是！那麼，時薪是…什麼，沒有嗎？嘁——", "0", "0", "0", "是！那麼，時薪是…什麼，沒有嗎？嘁——", "0", "cv_sk1_yincao_2", "0", "0"},
[4300600202] = {4300600202, 13006002, 3, 3, "0", "0", "我來了喔~心經屋的經紀人…不，心經屋的巫女，小瑩草，向你報導，領航。", "0", "0", "0", "我來了噢~心經屋的經紀人…不，心經屋的巫女，小瑩草，向你報導，領航。", "0", "cv_sk1_yincao_1", "0", "0"},
[4300600203] = {4300600203, 13006002, 91, 4, "0", "idle", "嘿嘿……就让小莹草为领航举行迎接新年的仪式好了~由你扮演蛇神，我来扮演侍奉蛇神的妻子。", "0", "0", "0", "瑩草姐？討厭啦，是小瑩草才對。下次再叫錯的話…你會死噢？", "0", "cv_sk1_yincao_n01", "0", "idle,idle"},
[4300600204] = {4300600204, 13006002, 91, 4, "0", "idle", "我可是抛下了工作悄悄跑出来和你约会的……所以我今天的薪水什么的……有吗？", "0", "0", "0", "在現代社會，只要經受過培訓，任何人都能成為巫女——領航想試試看嗎，我給你備好巫女服了。", "0", "cv_sk1_yincao_n02", "0", "idle,idle"},
[4300600205] = {4300600205, 13006002, 91, 4, "0", "idle", "蛇是贪婪的象征呢……也就是说……领航要是今天和其他驾驶员说话我就会很生气！", "0", "0", "0", "領航，你的臉色很難看噢——花語剛剛看到我們了？唔嗯…被她看見了的話，就麻煩了，是不是先預定一下床位比較好？", "0", "cv_sk1_yincao_n03", "0", "idle,idle"},
[4300600206] = {4300600206, 13006002, 93, 5, "14_2_0_0.8", "switch12", "啊呀~", "0", "0", "0", "溫柔地引領迷茫之人，點亮前進道路的燈……大概，我沒辦法成為這樣的巫女。不過，我所守護那名少女一定…領航，你能幫我嗎？", "0", "cv_sk1_yincao_n04", "0", "switch12,switch12"},
[4300600207] = {4300600207, 13006002, 92, 5, "14_1_0_0.8", "touch1", "不要着急嘛~反正今天我们有的是时间~", "0", "0", "0", "嗯？噢，我正在算這個月的收支。", "0", "cv_sk1_yincao_n05", "0", "touch1,touch1"},
[4300600208] = {4300600208, 13006002, 92, 5, "14_1_0_0.8", "touch1", "嘶呀~~怎样？是不是很吓人呀~", "0", "0", "0", "居然有人說巫女只要微笑迎客就行了…別小看巫女這個職業啊！打掃衛生、朝拜神社、主持典禮，還要練習舞蹈…可沒想像中那麼輕鬆。", "0", "cv_sk1_yincao_n06", "0", "touch1,touch1"},
[4300600209] = {4300600209, 13006002, 94, 4, "0", "idle2", "我听见了神明的声音——也就是你的声音，你想让我做你永生永世的妻子对吗？", "0", "0", "0", "我和想像中的巫女不一樣？領航，平安年代之後，巫女被賦予沉重意義的時代也就結束了…“可靠”，呵呵，我就當做誇獎收下了。", "0", "cv_sk1_yincao_n07", "0", "idle2,idle2"},
[4300600210] = {4300600210, 13006002, 94, 4, "0", "idle2", "我可不是普通的巫女，呵呵，我可是正正经经的纳税人，是艾吉斯认证了我捞钱本领的巫女。", "0", "0", "0", "“夢想”、“理想”、“願望”之類的，我已經很久沒有說過這種話了。不過…心紙，還有領航，你們卻應該去追逐它們。請放心地翱翔吧，其他的交給我來處理吧。", "0", "cv_sk1_yincao_n08", "0", "idle2,idle2"},
[4300600211] = {4300600211, 13006002, 94, 4, "0", "idle2", "什么人都能成为，什么事都能做到，希望领航能成为这样的人，在新的一年试着努力吧？", "0", "0", "0", "0", "0", "cv_sk1_yincao_n09", "0", "idle2,idle2"},
