[4105100100] = {4105100100, 11051001, 1, 1, "0", "0", "蒼霧殘響", "0", "0", "0", "0", "0", "cv_sk_Julius_vd_1", "0", "0"},
[4105100101] = {4105100101, 11051001, 2, 2, "0", "0", "讓我以現、現在這個狀態待在、在這麼顯眼的地方真的好嗎……", "0", "0", "0", "0", "0", "cv_sk_Julius_vd_2", "0", "0"},
[4105100102] = {4105100102, 11051001, 3, 3, "0", "0", "我的名字是朱……咳咳，阿瑟·潘德拉貢，初次見面，請多指教。……非得再說一遍嗎？", "0", "0", "0", "0", "0", "cv_sk_Julius_vd_3", "0", "0"},
[4105100103] = {4105100103, 11051001, 91, 4, "0", "idle", "雖然變年輕了，但是總感覺身體的疲勞並沒有被消除……是為什麼呢……", "0", "0", "0", "0", "0", "cv_sk_Julius_vd_n1", "0", "idle,idle"},
[4105100104] = {4105100104, 11051001, 91, 4, "0", "idle", "既要對戰友們隱瞞身份，對家裏報信的時候也要假裝一切順利……真是糟糕透了……還好有您在我身邊……", "0", "0", "0", "0", "0", "cv_sk_Julius_vd_n2", "0", "idle,idle"},
[4105100105] = {4105100105, 11051001, 91, 4, "0", "idle", "懂得變通的騎士……？領、領航……！這、這種時候就不要取笑我了！", "0", "0", "0", "0", "0", "cv_sk_Julius_vd_n3", "0", "idle,idle"},
[4105100106] = {4105100106, 11051001, 92, 5, "14_1_0_0.8", "touch1", "哇啊哇……抱抱歉、我還沒習慣您的觸摸！", "0", "0", "0", "0", "0", "cv_sk_Julius_vd_n4", "0", "touch1,touch1"},
[4105100107] = {4105100107, 11051001, 92, 5, "14_1_0_0.8", "touch1", "嗚……", "0", "0", "0", "0", "0", "cv_sk_Julius_vd_n5", "0", "touch1,touch1"},
[4105100108] = {4105100108, 11051001, 93, 5, "14_2_0_0.8", "switch1", "啊，這、這都是為了治療……！", "0", "0", "0", "0", "0", "cv_sk_Julius_vd_n6", "0", "switch1,switch1"},
[4105100109] = {4105100109, 11051001, 94, 4, "0", "idle2", "孤獨感……嗯……我還是第一次有這種感受……我的內心還是能被這種感情撼動……看來我還有待精進啊……", "0", "0", "0", "0", "0", "cv_sk_Julius_vd_n7", "0", "idle2,idle2"},
[4105100110] = {4105100110, 11051001, 94, 4, "0", "idle2", "我知道您可能會抵觸這些，但我沒有時間再在這裏消磨時間了……您得配合我快點把我變成“大人”才行。", "0", "0", "0", "0", "0", "cv_sk_Julius_vd_n8", "0", "idle2,idle2"},
[4105100111] = {4105100111, 11051001, 94, 4, "0", "idle2", "我、我會全力配合的……所以請您放開手腳按照指示書上的那樣實踐……我會忍耐的……", "0", "0", "0", "0", "0", "cv_sk_Julius_vd_n9", "0", "idle2,idle2"},
