[4105100135] = {4105100135, 11051001, 33, 25, "0", "0", "也……也是沒辦法的事情呢，呵呵，只能從新的我開始認識了。", "0", "0", "0", "0", "0", "cv_sk_Julius_vd_33", "0", "0"},
