[4101700100] = {4101700100, 11017001, 1, 1, "0", "0", "蒼霧殘響。", "蒼霧殘響（ハツリバーブ）。", "0", "0", "蒼霧殘響。", "0", "cv_sk_fuluola_32", "0", "0"},
[4101700101] = {4101700101, 11017001, 2, 2, "0", "0", "收到，芙蘿拉保證不會讓您失望的。", "承知いたしました。あなた様のご期待に応えてみせます。", "0", "0", "收到，芙蘿拉保證不會讓您失望的。", "0", "cv_sk_fuluola_2", "0", "0"},
[4101700102] = {4101700102, 11017001, 3, 3, "0", "0", "多瑙第一親衛班隊長，芙蘿拉。欸？您問為什麼親衛隊要穿女僕裝？", "ダニューブ第一親衛班班長、フローラと申します。え？どうして親衛班がメイド服なのか、ですか？", "0", "0", "多瑙第一親衛班隊長，芙蘿拉。哎？您問為什麼親衛隊要穿女僕裝？", "0", "cv_sk_fuluola_1", "0", "0"},
[4101700103] = {4101700103, 11017001, 4, 4, "0", "idle", "领航，一直以来辛苦您了。至少在今天，我希望您能好好放松一下。", "方舟の運航は順調です。暫くゆっくりなさってください。そうだ、お茶を淹れましょうか？", "0", "0", "方舟正在平穩地行駛，看來暫時沒有什麼要忙的，要為您泡杯茶嗎？", "0", "cv_sk_fuluola_n1", "0", "0"},
[4101700104] = {4101700104, 11017001, 5, 4, "0", "idle", "工作与任务固然重要，但也不能忘记享受生活，珍惜闲暇的时间。", "わたくしの武器で驚かせてしまったでしょうか？申し訳ありません。今すぐ収めます。", "0", "0", "我的武器嚇到您了嗎？很抱歉，現在就收起來。", "0", "cv_sk_fuluola_n2", "0", "0"},
[4101700105] = {4101700105, 11017001, 6, 4, "0", "idle", "这是我为了这一天特意准备的衣服，我认为它有着绝对不输给其他人的可爱，您觉得如何呢？", "わたくしは親衛班の班長として、常に模範とならなければいけません。今度、ユリウスさんにご指導いただこうと思います。", "0", "0", "身為親衛班的隊長，我更應該要起到表率作用。有機會的話，我想要向朱利烏斯小姐請教一下。", "0", "cv_sk_fuluola_n3", "0", "0"},
[4101700106] = {4101700106, 11017001, 7, 5, "15_1_0_0.8", "level1", "情人节是向爱人献上自己纯洁之爱，并且战胜其他竞争者的日子。身为第一亲卫班的队长，我必须要成为最后的胜利者。", "第一親衛班の最も重要な任務はダニューブの象徴、方舟を守ることです。また、わたくしたちはダニューブのドライバーの代表として見られることが多いですから、自身のイメージを維持することも非常に重要です。", "0", "0", "第一親衛班的首要任務是確保多瑙的象徵——方舟能夠安全地行駛。當然，我們本身也常常被當做是多瑙駕駛員的代表，所以維持自身形象是非常有必要的。", "0", "cv_sk_fuluola_n4", "0", "0"},
[4101700107] = {4101700107, 11017001, 8, 5, "15_2_0_0.8", "level2", "不只是制作巧克力，我还为了这一天准备了很多……比如，烛光晚餐……领航能接受我的邀请吗？", "はい。本日の巡迴は終了しました。何なりとお申しつけください。", "0", "0", "嗯，今天的巡視任務已經結束了，隨時聽從您的調遣。", "0", "cv_sk_fuluola_n5", "0", "0"},
[4101700108] = {4101700108, 11017001, 9, 5, "15_1_0_0.8", "level3", "多瑙最上乘的可可豆，内馅选用了季节限定的新鲜覆盆子与黑松露，最终由我亲手制成的巧克力——我相信，它一定能攻陷您的味蕾，您的心。", "わたくしの両親ですか？はい。わたくしを育ててくれただけでなく、わたくしの目標でもあります。親衛班の家系で生まれたわたくしは、他の隊員以上に責務を全うしなければなりません。でなければ、皆様の期待を裏切ることになってしまいます。", "0", "0", "我的父母？嗯，她們不光光是養育我的人，同時還是我努力想要成為的人。作為親衛的後代，我必須要做得比其他隊員更好。只有這樣，才不會辜負大家的期待。", "0", "cv_sk_fuluola_n6", "0", "0"},
[4101700109] = {4101700109, 11017001, 10, 5, "15_1_0_0.8", "level4", "希望您能仔细品味我的巧克力，以及我们相处的这段时光。", "ユリウスさんとチャリサーさんが羨ましいです。もしわたくしも親衛隊でなければ、彼女たちのようにあなた様と共に戦いたい……。ですがわたくしには為すべきことが、ダニューブの方舟を守るという使命があるのです。", "0", "0", "真是羡慕朱利烏斯和查麗莎小姐啊……如果我不是親衛的話，也想像她們一樣和您並肩作戰。但是，我現在有更重要的東西要去做，守住多瑙的方舟是我的使命……", "0", "cv_sk_fuluola_n7", "0", "0"},
[4101700110] = {4101700110, 11017001, 11, 5, "15_1_0_0.8", "level5", "只有今天，我想暂时忘记自己第一亲卫班队长的身份，享受这特殊的日子。", "あなたと共に遠征はできませんが、親衛班であるわたくしだからこそ、できることがあります。ご安心ください。あなた様と仲間の皆様の帰る場所は、わたくしが必ずお守りします。もし疲れたら、いつでも帰ってきてください。いつでもここでお待ちしております。", "0", "0", "雖然無法和您一同遠征，但也有身為親衛的我能做的事。無論您身處何方都還請放心，我一定會守住您和您同伴們的歸所。如果有一天您感到疲憊了也隨時都能回來休息一段時間，我會在這裡等著您的。", "0", "cv_sk_fuluola_n8", "0", "0"},
[4101700111] = {4101700111, 11017001, 11, 5, "15_1_0_0.8", "level6", "只有今天，我想暂时忘记自己第一亲卫班队长的身份，享受这特殊的日子。", "あなたと共に遠征はできませんが、親衛班であるわたくしだからこそ、できることがあります。ご安心ください。あなた様と仲間の皆様の帰る場所は、わたくしが必ずお守りします。もし疲れたら、いつでも帰ってきてください。いつでもここでお待ちしております。", "0", "0", "雖然無法和您一同遠征，但也有身為親衛的我能做的事。無論您身處何方都還請放心，我一定會守住您和您同伴們的歸所。如果有一天您感到疲憊了也隨時都能回來休息一段時間，我會在這裡等著您的。", "0", "cv_sk_fuluola_n8", "0", "0"},
[4101700112] = {4101700112, 11017001, 12, 6, "0", "0", "呼~力氣變大了呢。", "ふぅ……力が増したようです。", "0", "0", "呼~力氣變大了呢。", "0", "cv_sk_fuluola_9", "0", "0"},
[4101700113] = {4101700113, 11017001, 13, 7, "0", "0", "一切都是為了多瑙。", "すべてはダニューブのために。", "0", "0", "一切都是為了多瑙。", "0", "cv_sk_fuluola_10", "0", "0"},
[4101700114] = {4101700114, 11017001, 14, 8, "0", "0", "呼啊~神清氣爽……簡直就像是漫步在春天的花園中一樣。", "ああ、なんと清らかな……春の庭園にいるかのようです。", "0", "0", "呼啊~神清氣爽……簡直就像是漫步在春天的花園中一樣。", "0", "cv_sk_fuluola_11", "0", "0"},
[4101700115] = {4101700115, 11017001, 15, 9, "0", "0", "很好，就這樣繼續下去吧。", "いいですね。このまま続けましょう。", "0", "0", "很好，就這樣繼續下去吧。", "0", "cv_sk_fuluola_12", "0", "0"},
[4101700116] = {4101700116, 11017001, 16, 10, "0", "0", "嗯，一口氣解決它們吧。", "はい。一気に倒しましょう。", "0", "0", "嗯，一口氣解決它們吧。", "0", "cv_sk_fuluola_13", "0", "0"},
[4101700117] = {4101700117, 11017001, 17, 11, "0", "0", "多虧大家的協助，此次任務圓滿完成了呢。", "素晴らしい結果です。皆様のお陰ですね。", "0", "0", "多虧大家的協助，此次任務圓滿完成了呢。", "0", "cv_sk_fuluola_14", "0", "0"},
[4101700118] = {4101700118, 11017001, 18, 12, "0", "0", "任務完成，領航，您沒有受傷吧？", "任務完了です。ナビゲーター様、お怪我はありませんか？", "0", "0", "任務完成，領航，您沒有受傷吧？", "0", "cv_sk_fuluola_15", "0", "0"},
[4101700119] = {4101700119, 11017001, 19, 13, "0", "0", "放棄追擊吧，比起殲滅敵人，保全戰力才是重要的。", "追撃はやめましょう、敵の殲滅より、戦力の溫存が大事です。", "0", "0", "放棄追擊吧，比起殲滅敵人，保全戰力才是重要的。", "0", "cv_sk_fuluola_16", "0", "0"},
[4101700120] = {4101700120, 11017001, 20, 14, "0", "0", "失敗了嗎？…方舟絕對不能交給它們……", "失敗、ですか……。方舟は絶対に守ってみせます。", "0", "0", "失敗了嗎？…方舟絕對不能交給它們……", "0", "cv_sk_fuluola_17", "0", "0"},
[4101700121] = {4101700121, 11017001, 21, 15, "0", "0", "罪有应得。", "ふぅ……", "0", "0", "呼……", "0", "cv_sk_fuluola_n9", "0", "0"},
[4101700122] = {4101700122, 11017001, 23, 16, "0", "0", "神圣的一天不容玷污。", "一歩たりとも近づけさせません！", "0", "0", "一步，也不會讓你們接近！", "0", "cv_sk_fuluola_n10", "0", "0"},
[4101700123] = {4101700123, 11017001, 24, 17, "0", "0", "不可饶恕。", "ダニューブのために！", "0", "0", "為了多瑙……！", "0", "cv_sk_fuluola_n11", "0", "0"},
[4101700124] = {4101700124, 11017001, 26, 19, "0", "0", "我失败了吗……", "春の……終わりが……", "0", "0", "春天…已經結束了……", "0", "cv_sk_fuluola_n12", "0", "0"},
[4101700125] = {4101700125, 11017001, 27, 20, "0", "0", "雖然已經不是第一次來這裡了，不過還是不得不令人讚歎啊。方舟上的熱能供給系統，真是先進。", "何度も來ていますが、やはり感心せざるを得ません。方舟の熱エネルギー供給システムは実に先進的ですね。", "0", "0", "雖然已經不是第一次來這裡了，不過還是不得不令人讚歎啊。方舟上的熱能供給系統，真是先進。", "0", "cv_sk_fuluola_22", "0", "0"},
[4101700126] = {4101700126, 11017001, 28, 21, "0", "0", "欸？您聞到了花香？是…是在開玩笑的吧。", "え？花のような香りがする、って……ご、ご冗談を。", "0", "0", "哎？您聞到了花香？是…是在開玩笑的吧。", "0", "cv_sk_fuluola_23", "0", "0"},
[4101700127] = {4101700127, 11017001, 29, 21, "0", "0", "每次完成了巡視工作後，總會忍不住來這裡放鬆一下啊。", "巡迴が終わると、いつもここで疲れをとっているのです。", "0", "0", "每次完成了巡視工作後，總會忍不住來這裡放鬆一下啊。", "0", "cv_sk_fuluola_24", "0", "0"},
[4101700128] = {4101700128, 11017001, 30, 22, "0", "0", "欸？究竟是從哪裡冒出來的呢？", "あれは……一體どこから現れたのでしょうか？", "0", "0", "哎？究竟是從哪裡冒出來的呢？", "0", "cv_sk_fuluola_25", "0", "0"},
[4101700129] = {4101700129, 11017001, 31, 23, "0", "0", "需要我給您點提示嗎？", "ヒントはいかがでしょうか？", "0", "0", "需要我給您點提示嗎？", "0", "cv_sk_fuluola_26", "0", "0"},
[4101700130] = {4101700130, 11017001, 32, 24, "0", "0", "果然，您是懂我的。", "あなた様なら分かってくださると、信じていました。", "0", "0", "果然，您是懂我的。", "0", "cv_sk_fuluola_27", "0", "0"},
[4101700131] = {4101700131, 11017001, 33, 25, "0", "0", "下次再努力吧，領航。", "ナビゲーター様、次は頑張りましょう。", "0", "0", "下次再努力吧，領航。", "0", "cv_sk_fuluola_28", "0", "0"},
[4101700132] = {4101700132, 11017001, 34, 26, "0", "0", "情人节快乐！愿您度过满是爱与幸福的一天。", "報告します。周辺に敵影はありません。本日の巡迴は、わたくしが擔當いたします。", "0", "0", "報告，周邊暫無敵情，今天由我來負責巡視工作。", "0", "cv_sk_fuluola_n13", "0", "0"},
[4101700133] = {4101700133, 11017001, 35, 27, "0", "0", "現在要出擊嗎？", "今から出発なさいますか？", "0", "0", "現在要出擊嗎？", "0", "cv_sk_fuluola_33", "0", "0"},
[4101700134] = {4101700134, 11017001, 36, 28, "0", "0", "向著更高處邁進吧。", "さらなる高みを目指しましょう。", "0", "0", "向著更高處邁進吧。", "0", "cv_sk_fuluola_34", "0", "0"},
[4101700135] = {4101700135, 11017001, 37, 29, "0", "0", "真是一群優秀的駕駛員呢。", "皆様、本當に優秀なドライバーです。", "0", "0", "真是一群優秀的駕駛員呢。", "0", "cv_sk_fuluola_35", "0", "0"},
[4101700136] = {4101700136, 11017001, 38, 30, "0", "0", "試著招募新人吧。", "新人を募集してはいかがでしょうか？", "0", "0", "試著招募新人吧。", "0", "cv_sk_fuluola_36", "0", "0"},
[4101700137] = {4101700137, 11017001, 39, 31, "0", "0", "試著生產新裝備吧。", "新しい裝備を生産してはいかがでしょうか？", "0", "0", "試著生產新裝備吧。", "0", "cv_sk_fuluola_37", "0", "0"},
[4101700138] = {4101700138, 11017001, 40, 32, "0", "0", "要我去買什麼？", "何をご所望でしょうか？", "0", "0", "要我去買什麼？", "0", "cv_sk_fuluola_38", "0", "0"},
[4101700139] = {4101700139, 11017001, 41, 33, "0", "0", "讓我幫您檢查下吧。", "わたくしが検査いたしましょうか？", "0", "0", "讓我幫您檢查下吧。", "0", "cv_sk_fuluola_39", "0", "0"},
[4101700140] = {4101700140, 11017001, 42, 34, "0", "0", "要變更哪些設定呢？", "どの設定を変更されますか？", "0", "0", "要變更哪些設置呢？", "0", "cv_sk_fuluola_40", "0", "0"},
[4101700141] = {4101700141, 11017001, 43, 35, "0", "0", "這就去檢查信箱。", "直ちにメールをチェックします。", "0", "0", "這就去檢查郵箱。", "0", "cv_sk_fuluola_41", "0", "0"},
[4101700142] = {4101700142, 11017001, 44, 36, "0", "0", "要去參加茶話會嗎？", "お茶會に參加されますか？", "0", "0", "要去參加茶話會嗎？", "0", "cv_sk_fuluola_42", "0", "0"},
[4101700143] = {4101700143, 11017001, 45, 37, "0", "0", "如您所願。", "お望みのままに。", "0", "0", "如您所願。", "0", "cv_sk_fuluola_43", "0", "0"},
[4301700100] = {4301700100, 13017001, 1, 1, "0", "0", "蒼霧殘響", "0", "0", "0", "0", "0", "cv_jiushijiuhuan_1", "0", "0"},
[4301700101] = {4301700101, 13017001, 2, 2, "0", "0", "領航真的是……兩個人待在一起的話，直接叫我小環好不好？", "0", "0", "0", "0", "0", "cv_jiushijiuhuan_2", "0", "0"},
[4301700102] = {4301700102, 13017001, 3, 3, "0", "0", "數字的九十九，九十九環的環，從今天開始我們就是新婚夫妻了……現在還不行嗎？", "0", "0", "0", "0", "0", "cv_jiushijiuhuan_3", "0", "0"},
[4301700103] = {4301700103, 13017001, 4, 4, "0", "idle", "哈哈，很少看到親愛的會發呆呢，真的忍不住想要捉弄一下，不過嘛我還是忍住了，怎麼樣，很了不起吧？", "0", "0", "0", "0", "0", "cv_jiushijiuhuan_4", "0", "0"},
[4301700104] = {4301700104, 13017001, 5, 4, "0", "idle", "會很細心地，很積極地面對每一個駕駛員，親愛的是個很願意誇獎別人的人……嗯？我是不會嫉妒這樣的正常交流的啦。", "0", "0", "0", "0", "0", "cv_jiushijiuhuan_5", "0", "0"},
[4301700105] = {4301700105, 13017001, 6, 4, "0", "idle", "親愛的在想什麼事情呢？我還蠻擅長傾聽的，不介意的話和我說說吧，我也正因為親愛的好久沒有陪我說話感到有一點一點一點寂寞。", "0", "0", "0", "0", "0", "cv_jiushijiuhuan_6", "0", "0"},
[4301700106] = {4301700106, 13017001, 7, 5, "1_》_0_0.8", "level", "我在想該怎麼稱呼領航比較好，先生？當家的？親愛的？Honey？……你覺得哪個好？", "0", "0", "0", "0", "0", "cv_jiushijiuhuan_7", "0", "0"},
[4301700107] = {4301700107, 13017001, 8, 5, "1_》_0_0.8", "level", "忙這麼久真是辛苦了，要不要和我一起去吃點甜品，我知道有一家店最近在開著活動呢，會幫到店的情侶拍攝有魔法的照片哦。", "0", "0", "0", "0", "0", "cv_jiushijiuhuan_8", "0", "0"},
[4301700108] = {4301700108, 13017001, 9, 5, "1_》_0_0.8", "level", "那……那個，聽我說啊，今天啊我的父母都不在家，晚上只有一個人感覺很孤單……要一起出來玩，就我們兩個，一起去熱鬧一點的地方逛逛。", "0", "0", "0", "0", "0", "cv_jiushijiuhuan_9", "0", "0"},
[4301700109] = {4301700109, 13017001, 10, 5, "1_》_0_0.8", "level", "我們都已經是這樣的關係了，親愛的有沒有什麼事情想要我做的，可以提一些大膽點的要求，真的不行的話我會說出來的……今天去參加99場模擬戰？不行不行不行！", "0", "0", "0", "0", "0", "cv_jiushijiuhuan_10", "0", "0"},
[4301700110] = {4301700110, 13017001, 11, 5, "1_》_0_0.8", "level", "給你帶了桃子，真的好甜，回家的時候記得嘗嘗看，如果今天沒有其他事情的話，晚上我想陪吉雅妹妹玩……接下來我的人生規劃就是——要一直待在親愛的身邊！", "0", "0", "0", "0", "0", "cv_jiushijiuhuan_11", "0", "0"},
[4301700111] = {4301700111, 13017001, 12, 6, "0", "0", "嗯嗯……收穫了很多的領航能量。", "0", "0", "0", "0", "0", "cv_jiushijiuhuan_12", "0", "0"},
[4301700112] = {4301700112, 13017001, 13, 7, "0", "0", "哇啊啊！親愛的能量多到溢出了！", "0", "0", "0", "0", "0", "cv_jiushijiuhuan_13", "0", "0"},
[4301700113] = {4301700113, 13017001, 14, 8, "0", "0", "哦——這像是要靈魂出竅般的誇張感覺！不愧是親愛的！", "0", "0", "0", "0", "0", "cv_jiushijiuhuan_14", "0", "0"},
[4301700114] = {4301700114, 13017001, 15, 9, "0", "0", "心在噗通噗通地跳。", "0", "0", "0", "0", "0", "cv_jiushijiuhuan_15", "0", "0"},
