[4301700122] = {4301700122, 13017001, 24, 17, "0", "0", "這樣的未來……我根本就沒有看到……", "0", "0", "0", "0", "0", "cv_jiushijiuhuan_23", "0", "0"},
[4301700123] = {4301700123, 13017001, 27, 20, "0", "0", "洗澡洗澡~戰鬥過後就要痛痛快快地洗澡洗澡~", "0", "0", "0", "0", "0", "cv_jiushijiuhuan_24", "0", "0"},
[4301700124] = {4301700124, 13017001, 28, 21, "0", "0", "我等你很久了哦，怎麼了剛剛在忙嗎，那就等會讓我來幫你也做個按摩舒服舒服吧。", "0", "0", "0", "0", "0", "cv_jiushijiuhuan_25", "0", "0"},
[4301700125] = {4301700125, 13017001, 29, 21, "0", "0", "還不快點開始嗎？今天的女主角可是已經做好準備等你了哦！", "0", "0", "0", "0", "0", "cv_jiushijiuhuan_26", "0", "0"},
[4301700126] = {4301700126, 13017001, 30, 22, "0", "0", "我的危機意識雷達在響動……好像有什麼事情要發生了！", "0", "0", "0", "0", "0", "cv_jiushijiuhuan_27", "0", "0"},
[4301700127] = {4301700127, 13017001, 31, 23, "0", "0", "竟然是“猜猜我是誰”……對我來說是種殘酷的考驗呢……", "0", "0", "0", "0", "0", "cv_jiushijiuhuan_28", "0", "0"},
