[4002500100] = {4002500100, 10025001, 1, 1, "0", "0", "蒼霧殘響！", "0", "0", "0", "0", "0", "cv_melu_32", "0", "0"},
[4002500101] = {4002500101, 10025001, 2, 2, "0", "0", "我還是想要更自由一點啊......", "0", "0", "0", "0", "0", "cv_melu_2", "0", "0"},
[4002500102] = {4002500102, 10025001, 3, 3, "0", "0", "我是梅爾。你就是那個多瑙特別聯合部隊的領航？比我想像中的要瘦弱一點啊。", "0", "0", "0", "0", "0", "cv_melu_1", "0", "0"},
[4002500103] = {4002500103, 10025001, 91, 4, "0", "idle", "喂，我們什麼時候才能出擊啊，稍微有些無聊了。", "0", "0", "0", "0", "0", "cv_melu_3", "0", "idle,idle"},
[4002500104] = {4002500104, 10025001, 91, 4, "0", "idle", "哎？我的聲音太大了？沒辦法，身體變得這麼大之後我也沒辦法啊。", "0", "0", "0", "0", "0", "cv_melu_4", "0", "idle,idle"},
[4002500105] = {4002500105, 10025001, 91, 4, "0", "idle", "喂，可以聽我稍微抱怨下嗎？雖說我並沒有指望能和大家相處得多好，但是法芙娜那個傢夥也太過分了吧。戰鬥的時候完全沒法和她好好配合......", "0", "0", "0", "0", "0", "cv_melu_29", "0", "idle,idle"},
[4002500106] = {4002500106, 10025001, 92, 5, "14_1_0_0.8", "level1", "如果有可能的話，我希望能夠回到過去...哪怕只是再見他們一面也好......", "0", "0", "0", "0", "0", "cv_melu_30", "0", "level1,level1"},
[4002500108] = {4002500108, 10025001, 93, 5, "14_2_0_0.8", "switch1", "哈？找我有什麼事嗎？如果要出擊的話我隨時都能奉陪。", "0", "0", "0", "0", "0", "cv_melu_5", "0", "switch1,switch1"},
[4002500109] = {4002500109, 10025001, 94, 4, "0", "idle2", "喂，我們什麼時候才能出擊啊，稍微有些無聊了。", "0", "0", "0", "0", "0", "cv_melu_3", "0", "idle2,idle2"},
[4002500110] = {4002500110, 10025001, 94, 4, "0", "idle2", "哎？我的聲音太大了？沒辦法，身體變得這麼大之後我也沒辦法啊。", "0", "0", "0", "0", "0", "cv_melu_4", "0", "idle2,idle2"},
[4002500111] = {4002500111, 10025001, 94, 4, "0", "idle2", "喂，可以聽我稍微抱怨下嗎？雖說我並沒有指望能和大家相處得多好，但是法芙娜那個傢夥也太過分了吧。戰鬥的時候完全沒法和她好好配合......", "0", "0", "0", "0", "0", "cv_melu_29", "0", "idle2,idle2"},
[4002500112] = {4002500112, 10025001, 95, 5, "14_1_0_0.8", "level2", "哎...你已經知道那些事了吧。不過不用同情我，在這個時代像我一樣的人還有很多很多，這並不是什麼大不了的事...並不是...", "0", "0", "0", "0", "0", "cv_melu_6", "0", "level2,level2"},
[4002500113] = {4002500113, 10025001, 95, 5, "14_1_0_0.8", "level3", "我很後悔，如果當年沒有離開家的話，說不定就能多陪家人一段時間了。但即便當時的我在現場，應該也改變不了什麼......這一切都因為我非常弱小吧，哪怕是現在的我，也非常的弱小......", "0", "0", "0", "0", "0", "cv_melu_7", "0", "level3,level3"},
[4002500114] = {4002500114, 10025001, 102, 5, "14_2_0_0.8", "switch2", "所謂的自由也許只是一個偽命題，哪怕是解決了所有的原罪我們依舊也無法擺脫死亡的詛咒。但如果真的有永遠不會消逝的生命，那大概也非常痛苦吧。......請不要在意，還請繼續前進吧，我會一直陪在你身邊的。", "0", "0", "0", "0", "0", "cv_melu_8", "0", "switch2,switch2"},
