[4400400203] = {4400400203, 14004002, 4, 4, "0", "idle", "這身衣服……不太適合我，對嗎？我也這麼想的……果然，坐在辦公室裡工作一點也不像我。", "0", "0", "0", "0", "0", "cv_sk2_chilyarisa_sp_n01", "0", "0"},
[4400400204] = {4400400204, 14004002, 5, 4, "0", "idle", "要是跟過去的我說，我會當上新切斯頓的管理員，她一定會覺得我是在騙她吧……要真是謊言的話，就好了。", "0", "0", "0", "0", "0", "cv_sk2_chilyarisa_sp_n02", "0", "0"},
[4400400205] = {4400400205, 14004002, 6, 4, "0", "idle", "芙露露和阿萊塔說我是這個城市的支柱……可如果沒有她們的話，我一定沒辦法堅持到現在的，也不可能和領航你重逢。", "0", "0", "0", "0", "0", "cv_sk2_chilyarisa_sp_n03", "0", "0"},
[4400400206] = {4400400206, 14004002, 7, 5, "1_》_0_0.8", "level1", "當好一個管理員，真是一門複雜的學問……但是只能去做了吧，畢竟辜負大家的信任，對我來說比死還要可怕。", "0", "0", "0", "0", "0", "cv_sk2_chilyarisa_sp_n04", "0", "0"},
[4400400207] = {4400400207, 14004002, 8, 5, "1_》_0_0.8", "level2", "好啦，別鬧了，我可是管理員，要尊重下我！", "0", "0", "0", "0", "0", "cv_sk2_chilyarisa_sp_n05", "0", "0"},
[4400400208] = {4400400208, 14004002, 9, 5, "1_》_100_1.5", "level3", "以前，我以為責任是枷鎖，是限制我自由的囚牢……現在我才明白，責任是繩索，是確保我的人性不會墮入地獄的救命繩索。", "0", "0", "0", "0", "0", "cv_sk2_chilyarisa_sp_n06", "0", "0"},
[4400400209] = {4400400209, 14004002, 10, 5, "1_》_500_2", "level4", "對了，領航，我還沒有問過，你喜歡年輕點的女孩，還是成熟的……我是說，過去的我，現在的我，你更加鐘意哪一個？", "0", "0", "0", "0", "0", "cv_sk2_chilyarisa_sp_n07", "0", "0"},
[4400400210] = {4400400210, 14004002, 11, 5, "1_》_1000_2.5", "level5", "新切斯頓的管理員、現存最強的駕駛員、“火炬”的隊長……領航，你說，現在的我，有沒有成為“英雄”呢？成為“英雄”的代價，原來這麼大嗎？", "0", "0", "0", "0", "0", "cv_sk2_chilyarisa_sp_n08", "0", "0"},
[4400400211] = {4400400211, 14004002, 12, 6, "0", "0", "謝謝。", "0", "0", "0", "0", "0", "cv_sk2_chilyarisa_sp_12", "0", "0"},
[4400400212] = {4400400212, 14004002, 13, 7, "0", "0", "我會一直閃耀下去的。", "0", "0", "0", "0", "0", "cv_sk2_chilyarisa_sp_13", "0", "0"},
[4400400213] = {4400400213, 14004002, 14, 8, "0", "0", "我要做出能與這份榮耀匹配的實績。", "0", "0", "0", "0", "0", "cv_sk2_chilyarisa_sp_14", "0", "0"},
[4400400214] = {4400400214, 14004002, 15, 9, "0", "0", "這種感覺真不錯。", "0", "0", "0", "0", "0", "cv_sk2_chilyarisa_sp_15", "0", "0"},
[4400400215] = {4400400215, 14004002, 16, 10, "0", "0", "接下來，由我接管這個戰場。", "0", "0", "0", "0", "0", "cv_sk2_chilyarisa_sp_16", "0", "0"},
[4400400216] = {4400400216, 14004002, 17, 11, "0", "0", "我會一直贏，一直贏，贏到最後。", "0", "0", "0", "0", "0", "cv_sk2_chilyarisa_sp_17", "0", "0"},
[4400400217] = {4400400217, 14004002, 18, 12, "0", "0", "贏了就好。", "0", "0", "0", "0", "0", "cv_sk2_chilyarisa_sp_18", "0", "0"},
[4400400218] = {4400400218, 14004002, 19, 13, "0", "0", "還不能鬆懈。", "0", "0", "0", "0", "0", "cv_sk2_chilyarisa_sp_19", "0", "0"},
[4400400219] = {4400400219, 14004002, 20, 14, "0", "0", "不要慌亂，有序撤退。", "0", "0", "0", "0", "0", "cv_sk2_chilyarisa_sp_20", "0", "0"},
[4400400220] = {4400400220, 14004002, 21, 15, "0", "0", "別妨礙我的工作。", "0", "0", "0", "0", "0", "cv_sk2_chilyarisa_sp_n09", "0", "0"},
[4400400221] = {4400400221, 14004002, 23, 16, "0", "0", "真是煩人！", "0", "0", "0", "0", "0", "cv_sk2_chilyarisa_sp_n10", "0", "0"},
[4400400222] = {4400400222, 14004002, 24, 17, "0", "0", "還沒結束嗎？", "0", "0", "0", "0", "0", "cv_sk2_chilyarisa_sp_n11", "0", "0"},
[4400400223] = {4400400223, 14004002, 25, 18, "0", "0", "/", "0", "0", "0", "0", "0", "cv_sk2_chilyarisa_sp_25", "0", "0"},
[4400400224] = {4400400224, 14004002, 26, 19, "0", "0", "可惡……", "0", "0", "0", "0", "0", "cv_sk2_chilyarisa_sp_n13", "0", "0"},
[4400400225] = {4400400225, 14004002, 27, 20, "0", "0", "是呢，該放鬆的時候就得好好放鬆。", "0", "0", "0", "0", "0", "cv_sk2_chilyarisa_sp_27", "0", "0"},
[4400400226] = {4400400226, 14004002, 28, 21, "0", "0", "在想些什麼呢，領航？", "0", "0", "0", "0", "0", "cv_sk2_chilyarisa_sp_28", "0", "0"},
[4400400227] = {4400400227, 14004002, 29, 21, "0", "0", "你應該沒有在幻想一些很糟糕的事情吧？", "0", "0", "0", "0", "0", "cv_sk2_chilyarisa_sp_29", "0", "0"},
[4400400228] = {4400400228, 14004002, 30, 22, "0", "0", "怎麼了？", "0", "0", "0", "0", "0", "cv_sk2_chilyarisa_sp_30", "0", "0"},
[4400400229] = {4400400229, 14004002, 31, 23, "0", "0", "又來這套……千萬別猜錯了啊。", "0", "0", "0", "0", "0", "cv_sk2_chilyarisa_sp_31", "0", "0"},
[4400400230] = {4400400230, 14004002, 32, 24, "0", "0", "我就知道——領航是不會忘記我的。", "0", "0", "0", "0", "0", "cv_sk2_chilyarisa_sp_32", "0", "0"},
[4400400231] = {4400400231, 14004002, 33, 25, "0", "0", "笨蛋……", "0", "0", "0", "0", "0", "cv_sk2_chilyarisa_sp_33", "0", "0"},
[4400400232] = {4400400232, 14004002, 34, 26, "0", "0", "在工作中……嗯，是領航啊？沒事，什麼事都沒有，歡迎回來。", "0", "0", "0", "0", "0", "cv_sk2_chilyarisa_sp_n14", "0", "0"},
[4400400233] = {4400400233, 14004002, 35, 27, "0", "0", "讓我們將故事書寫到尾聲吧。", "0", "0", "0", "0", "0", "cv_sk2_chilyarisa_sp_35", "0", "0"},
[4400400234] = {4400400234, 14004002, 36, 28, "0", "0", "陪練嗎？我會手下留情的。", "0", "0", "0", "0", "0", "cv_sk2_chilyarisa_sp_36", "0", "0"},
[4400400235] = {4400400235, 14004002, 37, 29, "0", "0", "每一位駕駛員，都是希望的火種。", "0", "0", "0", "0", "0", "cv_sk2_chilyarisa_sp_37", "0", "0"},
[4400400236] = {4400400236, 14004002, 38, 30, "0", "0", "是要補充作戰人員嗎？", "0", "0", "0", "0", "0", "cv_sk2_chilyarisa_sp_38", "0", "0"},
[4400400237] = {4400400237, 14004002, 39, 31, "0", "0", "從實戰角度挑選裝備吧。", "0", "0", "0", "0", "0", "cv_sk2_chilyarisa_sp_39", "0", "0"},
[4400400238] = {4400400238, 14004002, 40, 32, "0", "0", "有什麼需要的嗎？", "0", "0", "0", "0", "0", "cv_sk2_chilyarisa_sp_40", "0", "0"},
[4400400239] = {4400400239, 14004002, 41, 33, "0", "0", "你真是一點也沒變啊。", "0", "0", "0", "0", "0", "cv_sk2_chilyarisa_sp_41", "0", "0"},
[4400400240] = {4400400240, 14004002, 42, 34, "0", "0", "要變更設置嗎？", "0", "0", "0", "0", "0", "cv_sk2_chilyarisa_sp_42", "0", "0"},
[4400400241] = {4400400241, 14004002, 43, 35, "0", "0", "多留意重要信息。", "0", "0", "0", "0", "0", "cv_sk2_chilyarisa_sp_43", "0", "0"},
[4400400242] = {4400400242, 14004002, 44, 36, "0", "0", "要珍惜與人交流的機會啊。", "0", "0", "0", "0", "0", "cv_sk2_chilyarisa_sp_44", "0", "0"},
[4400400243] = {4400400243, 14004002, 45, 37, "0", "0", "嗯？", "0", "0", "0", "0", "0", "cv_sk2_chilyarisa_sp_45", "0", "0"},
[4105200100] = {4105200100, 11052001, 1, 1, "0", "0", "蒼霧殘響", "0", "0", "0", "0", "0", "cv_sk_sps_001", "0", "0"},
[4105200101] = {4105200101, 11052001, 2, 2, "0", "0", "畢竟我是勇者，被人依靠是當然的，護衛工作就交給我吧。", "0", "0", "0", "0", "0", "cv_sk_sps_002", "0", "0"},
[4105200102] = {4105200102, 11052001, 3, 3, "0", "0", "我是斯珀絲，未來的救世主，人類最後的希望，註定要拯救世界的勇者，記清楚了嗎？", "0", "0", "0", "0", "0", "cv_sk_sps_003", "0", "0"},
[4105200103] = {4105200103, 11052001, 93, 5, "14_2_0_0.8", "sw12", "幹嘛？好冷啊……", "0", "0", "0", "0", "0", "cv_sk_sps_change_001", "0", "0"},
[4105200104] = {4105200104, 11052001, 92, 5, "14_1_0_0.8", "touch1", "怎麼了？有什麼想說的話就說吧，我會認真聽的，媽媽說過，這是聊天的基本禮儀。", "0", "0", "0", "0", "0", "cv_sk_sps_change_002", "0", "0"},
[4105200105] = {4105200105, 11052001, 92, 5, "14_1_0_0.8", "touch1", "旅行要是累了的話，我們就在這裡多休息一會，吃的東西雖然只有這些壓縮食品，但總好過什麼都不吃……等事情結束後，我會請你吃好吃的，我可不是不懂關心同伴的勇者！", "0", "0", "0", "0", "0", "cv_sk_sps_change_003", "0", "0"},
[4105200106] = {4105200106, 11052001, 91, 4, "0", "idle", "說起來……你能說說你那個時代的事情嗎？讓你記憶深刻的人啊……或者無法釋懷的往事啊之類的，有嗎，我很感興趣！", "0", "0", "0", "0", "0", "cv_sk_sps_change_004", "0", "0"},
[4105200107] = {4105200107, 11052001, 91, 4, "0", "idle", "我有很多問題想要弄清楚，但光在一個地方待著，問題也不會消失，為了找到這些問題的答案，我才會開始旅行的。", "0", "0", "0", "0", "0", "cv_sk_sps_change_005", "0", "0"},
[4105200108] = {4105200108, 11052001, 91, 4, "0", "idle", "散落在書店裡的漫畫書很有趣，已經過期的垃圾食品出乎意料的好吃，碳酸飲料喝上一口就會讓人幸福，旅途中遇上的這些事，讓我覺得這個世界還有被拯救的價值。", "0", "0", "0", "0", "0", "cv_sk_sps_change_006", "0", "0"},
[4105200109] = {4105200109, 11052001, 93, 5, "14_2_0_0.8", "sw21", "呼……暖和了。", "0", "0", "0", "0", "0", "cv_sk_sps_change_007", "0", "0"},
[4105200110] = {4105200110, 11052001, 92, 5, "14_1_0_0.8", "touch2", "嗯……媽媽說過，這時候的應對方式是……“變態！”", "0", "0", "0", "0", "0", "cv_sk_sps_change_008", "0", "0"},
[4105200111] = {4105200111, 11052001, 92, 5, "14_1_0_0.8", "touch2", "不要把我當小孩子捉弄，我是勇者，是要拯救世界的勇者。", "0", "0", "0", "0", "0", "cv_sk_sps_change_009", "0", "0"},
[4105200112] = {4105200112, 11052001, 91, 4, "0", "idle2", "勇者的身體是完美無缺的，就算被你看到了也沒什麼好害羞的——不過只能給你看，這是一號同伴的特殊待遇。", "0", "0", "0", "0", "0", "cv_sk_sps_change_010", "0", "0"},
[4105200113] = {4105200113, 11052001, 91, 4, "0", "idle2", "我不太清楚舊時代的人對異性身體有什麼特別的執著，不過再這樣盯下去，偉大的勇者，未來的救世主，也就是我——要感冒了。", "0", "0", "0", "0", "0", "cv_sk_sps_change_011", "0", "0"},
[4105200114] = {4105200114, 11052001, 91, 4, "0", "idle2", "嗯……嗯……把衣服還我，太冷了，我的耐寒屬性是零！", "0", "0", "0", "0", "0", "cv_sk_sps_change_012", "0", "0"},
[4105200115] = {4105200115, 11052001, 12, 6, "0", "0", "要是能用指令升級就好了。", "0", "0", "0", "0", "0", "cv_sk_sps_012", "0", "0"},
[4105200116] = {4105200116, 11052001, 13, 7, "0", "0", "已經到上限了嗎？", "0", "0", "0", "0", "0", "cv_sk_sps_013", "0", "0"},
[4105200117] = {4105200117, 11052001, 14, 8, "0", "0", "成長係的勇者是沒有極限的。", "0", "0", "0", "0", "0", "cv_sk_sps_014", "0", "0"},
[4105200118] = {4105200118, 11052001, 15, 9, "0", "0", "升到滿級吧。", "0", "0", "0", "0", "0", "cv_sk_sps_015", "0", "0"},
[4105200119] = {4105200119, 11052001, 16, 10, "0", "0", "別擔心，有我在呢。", "0", "0", "0", "0", "0", "cv_sk_sps_016", "0", "0"},
[4105200120] = {4105200120, 11052001, 17, 11, "0", "0", "不做到這種程度，怎麼拯救世界？", "0", "0", "0", "0", "0", "cv_sk_sps_017", "0", "0"},
[4105200121] = {4105200121, 11052001, 18, 12, "0", "0", "我只是沒有拿出全部實力。", "0", "0", "0", "0", "0", "cv_sk_sps_018", "0", "0"},
[4105200122] = {4105200122, 11052001, 19, 13, "0", "0", "只是在熱身。", "0", "0", "0", "0", "0", "cv_sk_sps_019", "0", "0"},
[4105200123] = {4105200123, 11052001, 20, 14, "0", "0", "太丟人了，好想去死。", "0", "0", "0", "0", "0", "cv_sk_sps_020", "0", "0"},
[4105200124] = {4105200124, 11052001, 21, 15, "0", "0", "成為經驗值吧。", "0", "0", "0", "0", "0", "cv_sk_sps_021", "0", "0"},
[4105200125] = {4105200125, 11052001, 23, 16, "0", "0", "一刀兩斷，勇者劍！", "0", "0", "0", "0", "0", "cv_sk_sps_022", "0", "0"},
[4105200126] = {4105200126, 11052001, 24, 17, "0", "0", "還沒有死嗎？", "0", "0", "0", "0", "0", "cv_sk_sps_023", "0", "0"},
[4105200127] = {4105200127, 11052001, 25, 18, "0", "0", "就讓你們見識一下，全盛期的勇者有多強吧。", "0", "0", "0", "0", "0", "cv_sk_sps_025", "0", "0"},
[4105200128] = {4105200128, 11052001, 26, 19, "0", "0", "我……是不會死的。", "0", "0", "0", "0", "0", "cv_sk_sps_026", "0", "0"},
[4105200129] = {4105200129, 11052001, 27, 20, "0", "0", "你也要一起來嗎？", "0", "0", "0", "0", "0", "cv_sk_sps_027", "0", "0"},
[4105200130] = {4105200130, 11052001, 28, 21, "0", "0", "小的時候，媽媽還會幫我洗澡……後來她嫌麻煩，就再也沒幫過了。", "0", "0", "0", "0", "0", "cv_sk_sps_028", "0", "0"},
[4105200131] = {4105200131, 11052001, 29, 21, "0", "0", "不能再這麼放鬆了……懈怠是勇者的頭號大敵。", "0", "0", "0", "0", "0", "cv_sk_sps_029", "0", "0"},
[4105200132] = {4105200132, 11052001, 30, 22, "0", "0", "觸發特殊事件了？", "0", "0", "0", "0", "0", "cv_sk_sps_030", "0", "0"},
[4105200133] = {4105200133, 11052001, 31, 23, "0", "0", "這件事有什麼難度嗎？", "0", "0", "0", "0", "0", "cv_sk_sps_031", "0", "0"},
[4105200134] = {4105200134, 11052001, 32, 24, "0", "0", "身為我唯一的同伴，這是理所當然該做到的事。", "0", "0", "0", "0", "0", "cv_sk_sps_032", "0", "0"},
[4105200135] = {4105200135, 11052001, 33, 25, "0", "0", "這次就算了，之後你要把我的聲音記在靈魂深處，明白嗎？", "0", "0", "0", "0", "0", "cv_sk_sps_033", "0", "0"},
[4105200136] = {4105200136, 11052001, 34, 26, "0", "0", "醒了？那就跟我一起去拯救這個一塌糊塗的世界吧。", "0", "0", "0", "0", "0", "cv_sk_sps_034", "0", "0"},
[4105200137] = {4105200137, 11052001, 35, 27, "0", "0", "準備好繼續我們的旅行了嗎？", "0", "0", "0", "0", "0", "cv_sk_sps_035", "0", "0"},
[4105200138] = {4105200138, 11052001, 36, 28, "0", "0", "被打哭了別找媽媽告狀啊。", "0", "0", "0", "0", "0", "cv_sk_sps_036", "0", "0"},
[4105200139] = {4105200139, 11052001, 37, 29, "0", "0", "舊時代的駕駛員也沒什麼特別之處。", "0", "0", "0", "0", "0", "cv_sk_sps_037", "0", "0"},
[4105200140] = {4105200140, 11052001, 38, 30, "0", "0", "事先說好，我不會付僱傭費的。", "0", "0", "0", "0", "0", "cv_sk_sps_038", "0", "0"},
[4105200141] = {4105200141, 11052001, 39, 31, "0", "0", "每個人的專屬套裝都要集齊啊。", "0", "0", "0", "0", "0", "cv_sk_sps_039", "0", "0"},
[4105200142] = {4105200142, 11052001, 40, 32, "0", "0", "可以賒賬嗎，我以後再還。", "0", "0", "0", "0", "0", "cv_sk_sps_040", "0", "0"},
[4105200143] = {4105200143, 11052001, 41, 33, "0", "0", "還不錯，和我比起來就一般了。", "0", "0", "0", "0", "0", "cv_sk_sps_041", "0", "0"},
[4105200144] = {4105200144, 11052001, 42, 34, "0", "0", "用默認就行了。", "0", "0", "0", "0", "0", "cv_sk_sps_042", "0", "0"},
[4105200145] = {4105200145, 11052001, 43, 35, "0", "0", "會有新郵件嗎？", "0", "0", "0", "0", "0", "cv_sk_sps_043", "0", "0"},
[4105200146] = {4105200146, 11052001, 44, 36, "0", "0", "別太鬧騰了。", "0", "0", "0", "0", "0", "cv_sk_sps_044", "0", "0"},
[4105200147] = {4105200147, 11052001, 45, 37, "0", "0", "嗯？", "0", "0", "0", "0", "0", "cv_sk_sps_045", "0", "0"},
[4004100100] = {4004100100, 10041001, 1, 1, "0", "0", "蒼霧殘響", "0", "0", "0", "0", "0", "cv_alaita2nd_001", "0", "0"},
[4004100101] = {4004100101, 10041001, 2, 2, "0", "0", "我知道了，就像從前那樣，對嗎？", "0", "0", "0", "0", "0", "cv_alaita2nd_002", "0", "0"},
[4004100102] = {4004100102, 10041001, 3, 3, "0", "0", "讓我們為您的眼眸乾杯，領航。", "0", "0", "0", "0", "0", "cv_alaita2nd_003", "0", "0"},
[4004100103] = {4004100103, 10041001, 91, 4, "0", "idie", "現在，我還不清楚，您的回來，是希望來臨時的第一絲曙光，還是將我們引入瘋狂的誘惑……無論如何，我們都將追隨您，領航。", "0", "0", "0", "0", "0", "cv_alaita2nd_004", "0", "idie,idie"},
[4004100104] = {4004100104, 10041001, 91, 4, "0", "idle", "您在身邊的時候，就像一切都回到了從前一樣，令人陶醉。", "0", "0", "0", "0", "0", "cv_alaita2nd_005", "0", "idle,idle"},
[4004100105] = {4004100105, 10041001, 91, 4, "0", "idle2", "領航……您之後能不能和查麗莎說一下，讓她把上次收繳的酒還給我？那可是我僅有的人生樂趣了。", "0", "0", "0", "0", "0", "cv_alaita2nd_006", "0", "idle2,idle2"},
[4004100106] = {4004100106, 10041001, 93, 5, "14_2_0_0.8", "switch12", "行蹤不明的王子在公主遇上危機時出現，將世界重新引向和平，這就是我想要的童話故事。", "0", "0", "0", "0", "0", "cv_alaita2nd_007", "0", "switch12,switch12"},
[4004100107] = {4004100107, 10041001, 92, 5, "14_1_0_0.8", "touch1", "我們都知道……領航您一定是會回去的。您要回去的地方，沒有路，也不需要路。", "0", "0", "0", "0", "0", "cv_alaita2nd_008", "0", "touch1,touch1"},
[4004100108] = {4004100108, 10041001, 93, 5, "14_2_0_0.8", "switch21", "過去的悲劇已經發生，未來的道路撲朔迷離。領航，唯有您，能把握現在，讓悲劇不復存在，讓未來迎來光明。", "0", "0", "0", "0", "0", "cv_alaita2nd_009", "0", "switch21,switch21"},
[4004100109] = {4004100109, 10041001, 92, 5, "14_1_0_0.8", "touch2", "從時間的角度來看，未來無垠沒有盡頭，您可以出現在未來的每一個節點，可以與每個節點的人相遇，但這一刻，您偏偏與我們重逢了，我認為，這就是命運。", "0", "0", "0", "0", "0", "cv_alaita2nd_010", "0", "touch2,touch2"},
[4004100110] = {4004100110, 10041001, 92, 5, "14_1_0_0.8", "touchs", "我會將自己的餘生，自己的未來，自己的一切交給您，只要您想要——這是我最後的瘋狂，最後的賭博，領航，您會贏的，對嗎？", "0", "0", "0", "0", "0", "cv_alaita2nd_011", "0", "touchs,touchs"},
[4004100111] = {4004100111, 10041001, 12, 6, "0", "0", "謝謝。", "0", "0", "0", "0", "0", "cv_alaita2nd_012", "0", "0"},
[4004100112] = {4004100112, 10041001, 13, 7, "0", "0", "能得到您的信任，是我的榮幸。", "0", "0", "0", "0", "0", "cv_alaita2nd_013", "0", "0"},
[4004100113] = {4004100113, 10041001, 14, 8, "0", "0", "時間無法讓我的利刃生鏽，只會讓我更加清楚，自己為何而戰。", "0", "0", "0", "0", "0", "cv_alaita2nd_014", "0", "0"},
[4004100114] = {4004100114, 10041001, 15, 9, "0", "0", "真是美妙。", "0", "0", "0", "0", "0", "cv_alaita2nd_015", "0", "0"},
[4004100115] = {4004100115, 10041001, 16, 10, "0", "0", "歡呼吧，這是名作的重映。", "0", "0", "0", "0", "0", "cv_alaita2nd_016", "0", "0"},
[4004100116] = {4004100116, 10041001, 17, 11, "0", "0", "時光荏苒，但依然無法遮掩我的無瑕光輝。", "0", "0", "0", "0", "0", "cv_alaita2nd_017", "0", "0"},
[4004100117] = {4004100117, 10041001, 18, 12, "0", "0", "時間只會讓我更有魅力。", "0", "0", "0", "0", "0", "cv_alaita2nd_018", "0", "0"},
[4004100118] = {4004100118, 10041001, 19, 13, "0", "0", "不完美也是一種美。", "0", "0", "0", "0", "0", "cv_alaita2nd_019", "0", "0"},
[4004100119] = {4004100119, 10041001, 20, 14, "0", "0", "還是生疏了嗎……", "0", "0", "0", "0", "0", "cv_alaita2nd_020", "0", "0"},
[4004100120] = {4004100120, 10041001, 21, 15, "0", "0", "這就結束了嗎？", "0", "0", "0", "0", "0", "cv_alaita2nd_021", "0", "0"},
[4004100121] = {4004100121, 10041001, 23, 16, "0", "0", "死吧。", "0", "0", "0", "0", "0", "cv_alaita2nd_022", "0", "0"},
[4004100122] = {4004100122, 10041001, 24, 17, "0", "0", "染上血色吧。", "0", "0", "0", "0", "0", "cv_alaita2nd_023", "0", "0"},
[4004100123] = {4004100123, 10041001, 26, 19, "0", "0", "遲來的謝幕……", "0", "0", "0", "0", "0", "cv_alaita2nd_026", "0", "0"},
[4004100124] = {4004100124, 10041001, 27, 20, "0", "0", "嗯？是領航啊……也就只有您會在這種場合出現了。", "0", "0", "0", "0", "0", "cv_alaita2nd_027", "0", "0"},
[4004100125] = {4004100125, 10041001, 28, 21, "0", "0", "能吸引您的視線，說明我的魅力依然不減當年。", "0", "0", "0", "0", "0", "cv_alaita2nd_028", "0", "0"},
[4004100126] = {4004100126, 10041001, 29, 21, "0", "0", "能聽見這具巨大軀體下的心跳嗎？它讓我知道這一刻的我身處現實，而非妄想的幻覺。", "0", "0", "0", "0", "0", "cv_alaita2nd_029", "0", "0"},
[4004100127] = {4004100127, 10041001, 30, 22, "0", "0", "令人懷念……", "0", "0", "0", "0", "0", "cv_alaita2nd_030", "0", "0"},
[4004100128] = {4004100128, 10041001, 31, 23, "0", "0", "那麼，請說出我的名字吧，領航。", "0", "0", "0", "0", "0", "cv_alaita2nd_031", "0", "0"},
[4004100129] = {4004100129, 10041001, 32, 24, "0", "0", "您想要什麼獎勵呢，領航？", "0", "0", "0", "0", "0", "cv_alaita2nd_032", "0", "0"},
[4004100130] = {4004100130, 10041001, 33, 25, "0", "0", "您真喜歡讓人空歡喜，領航。", "0", "0", "0", "0", "0", "cv_alaita2nd_033", "0", "0"},
[4004100131] = {4004100131, 10041001, 34, 26, "0", "0", "領航，我為您準備了提神的咖啡，您有空和我討論一下之後的戰術佈置嗎？", "0", "0", "0", "0", "0", "cv_alaita2nd_034", "0", "0"},
[4004100132] = {4004100132, 10041001, 35, 27, "0", "0", "準備和海妖最後瘋狂一次嗎？", "0", "0", "0", "0", "0", "cv_alaita2nd_035", "0", "0"},
[4004100133] = {4004100133, 10041001, 36, 28, "0", "0", "就當遠征前的熱身吧。", "0", "0", "0", "0", "0", "cv_alaita2nd_036", "0", "0"},
[4004100134] = {4004100134, 10041001, 37, 29, "0", "0", "大家還真是有精神呢。", "0", "0", "0", "0", "0", "cv_alaita2nd_037", "0", "0"},
[4004100135] = {4004100135, 10041001, 38, 30, "0", "0", "希望能來位能幹的新人。", "0", "0", "0", "0", "0", "cv_alaita2nd_038", "0", "0"},
[4004100136] = {4004100136, 10041001, 40, 31, "0", "0", "得定期研發裝備呢。", "0", "0", "0", "0", "0", "cv_alaita2nd_039", "0", "0"},
[4004100137] = {4004100137, 10041001, 40, 32, "0", "0", "要購物了嗎？", "0", "0", "0", "0", "0", "cv_alaita2nd_040", "0", "0"},
[4004100138] = {4004100138, 10041001, 41, 33, "0", "0", "讓人懷念的名字。", "0", "0", "0", "0", "0", "cv_alaita2nd_041", "0", "0"},
[4004100139] = {4004100139, 10041001, 42, 34, "0", "0", "耐心設置吧。", "0", "0", "0", "0", "0", "cv_alaita2nd_042", "0", "0"},
[4004100140] = {4004100140, 10041001, 43, 35, "0", "0", "別誤刪郵件噢。", "0", "0", "0", "0", "0", "cv_alaita2nd_043", "0", "0"},
[4004100141] = {4004100141, 10041001, 44, 36, "0", "0", "喧鬧也是一種幸福。", "0", "0", "0", "0", "0", "cv_alaita2nd_044", "0", "0"},
[4004100142] = {4004100142, 10041001, 45, 37, "0", "0", "呵呵~", "0", "0", "0", "0", "0", "cv_alaita2nd_045", "0", "0"},
[4202900100] = {4202900100, 12029001, 1, 1, "0", "0", "蒼霧殘響", "0", "0", "0", "0", "0", "cv_sk_fululu_2nd_01", "0", "0"},
[4202900101] = {4202900101, 12029001, 2, 2, "0", "0", "領航請安心地依賴我吧。", "0", "0", "0", "0", "0", "cv_sk_fululu_2nd_02", "0", "0"},
[4202900102] = {4202900102, 12029001, 3, 3, "0", "0", "領航，好久不見，芙露露已經是大人了喵。", "0", "0", "0", "0", "0", "cv_sk_fululu_2nd_03", "0", "0"},
[4202900103] = {4202900103, 12029001, 91, 4, "0", "idle", "正因為相處的時間註定短暫，所以才要好好珍惜~我會珍惜與領航玩耍的每一秒的~", "0", "0", "0", "0", "0", "cv_sk_fululu_2nd_n01", "0", "idle,idle"},
[4202900104] = {4202900104, 12029001, 91, 4, "0", "idle", "對我來說，和領航的再一次相遇，再一次玩耍，就是神明大人給芙露露最好的成年禮——雖然已經成年很久了啦。", "0", "0", "0", "0", "0", "cv_sk_fululu_2nd_n02", "0", "idle,idle"},
[4202900105] = {4202900105, 12029001, 91, 4, "0", "idle", "不管領航想要做什麼奇怪的事情，現在的芙露露都能全盤接受，這就是成長帶來的餘裕！", "0", "0", "0", "0", "0", "cv_sk_fululu_2nd_n03", "0", "idle,idle"},
[4202900106] = {4202900106, 12029001, 92, 5, "14_1_0_0.8", "level1", "要和芙露露玩遊戲嗎~喵~", "0", "0", "0", "0", "0", "cv_sk_fululu_2nd_n04", "0", "level1,level1"},
[4202900107] = {4202900107, 12029001, 92, 5, "14_1_0_0.8", "level1", "喵哈哈——好癢啦。", "0", "0", "0", "0", "0", "cv_sk_fululu_2nd_n05", "0", "level1,level1"},
[4202900108] = {4202900108, 12029001, 93, 5, "14_2_0_0.8", "switch1", "嗚喵？", "0", "0", "0", "0", "0", "cv_sk_fululu_2nd_n06", "0", "switch1,switch1"},
[4202900109] = {4202900109, 12029001, 94, 4, "0", "idle2", "嗚喵——要是現在把領航吃掉了，查麗莎姐姐她們一定會很慌亂吧？", "0", "0", "0", "0", "0", "cv_sk_fululu_2nd_n07", "0", "idle2,idle2"},
[4202900110] = {4202900110, 12029001, 94, 4, "0", "idle2", "對了對了，我還得向其他的貓咪介紹領航呢，領航也很想認識它們吧，它們都是些可愛的孩子。", "0", "0", "0", "0", "0", "cv_sk_fululu_2nd_n08", "0", "idle2,idle2"},
[4202900111] = {4202900111, 12029001, 94, 4, "0", "idle2", "喵——芙露露現在要進入狩獵模式了，領航你逃不掉了~", "0", "0", "0", "0", "0", "cv_sk_fululu_2nd_n09", "0", "idle2,idle2"},
[4202900112] = {4202900112, 12029001, 95, 5, "14_1_0_0.8", "level2", "領航，笑一笑吧，只要笑起來，就會讓人覺得未來還有希望。", "0", "0", "0", "0", "0", "cv_sk_fululu_2nd_n10", "0", "level2,level2"},
[4202900113] = {4202900113, 12029001, 95, 5, "14_1_0_0.8", "level3", "領航的手，就和過去一樣溫暖，我很喜歡，非常非常的喜歡~", "0", "0", "0", "0", "0", "cv_sk_fululu_2nd_n11", "0", "level3,level3"},
[4202900114] = {4202900114, 12029001, 102, 5, "14_2_0_0.8", "switch2", "喵~", "0", "0", "0", "0", "0", "cv_sk_fululu_2nd_n12", "0", "switch2,switch2"},
[4202900115] = {4202900115, 12029001, 12, 6, "0", "0", "等級提高了~", "0", "0", "0", "0", "0", "cv_sk_fululu_2nd_12", "0", "0"},
