[4202900117] = {4202900117, 12029001, 14, 8, "0", "0", "現在的我成長到了什麼程度，領航來親自感受吧。", "0", "0", "0", "0", "0", "cv_sk_fululu_2nd_14", "0", "0"},
[4202900118] = {4202900118, 12029001, 15, 9, "0", "0", "想要一擊必殺的技能~", "0", "0", "0", "0", "0", "cv_sk_fululu_2nd_15", "0", "0"},
