[4400500101] = {4400500101, 14005001, 2, 2, "0", "0", "把來犯的原罪都斬掉就好了吧？", "0", "0", "0", "0", "0", "cv_sk_uzkk_2", "0", "0"},
[4400500102] = {4400500102, 14005001, 3, 3, "0", "0", "我是魔防隊第七組組長·羽前京香。放心吧，我來救你了。", "0", "0", "0", "0", "0", "cv_sk_uzkk_3", "0", "0"},
[4400500103] = {4400500103, 14005001, 93, 5, "14_2_0_0.8", "switch1", "嗚——！？", "0", "0", "0", "0", "0", "cv_sk_uzkk_n1", "0", "switch1,switch1"},
[4400500104] = {4400500104, 14005001, 91, 4, "0", "idle", "話劇？為了緩解駕駛員的精神壓力，所以會定期舉辦類似的活動啊……你們還有這種活動……誒……我也要參加嗎？", "0", "0", "0", "0", "0", "cv_sk_uzkk_n2", "0", "idle,idle"},
[4400500105] = {4400500105, 14005001, 91, 4, "0", "idle", "我也是第一次做這樣的事情……我該怎麼做？", "0", "0", "0", "0", "0", "cv_sk_uzkk_n3", "0", "idle,idle"},
[4400500106] = {4400500106, 14005001, 91, 4, "0", "idle", "你們竟然會熱衷於這樣的事情，但是大家似乎都很熱情……盛情難卻。", "0", "0", "0", "0", "0", "cv_sk_uzkk_n4", "0", "idle,idle"},
[4400500107] = {4400500107, 14005001, 92, 5, "14_1_0_0.8", "level1", "我只瞭解在魔都的戰鬥，以及與之相關的事情……讓我有些緊張啊。", "0", "0", "0", "0", "0", "cv_sk_uzkk_n5", "0", "level1,level1"},
[4400500108] = {4400500108, 14005001, 92, 5, "14_1_0_0.8", "level1", "……雖說是異世界，但能有一個遠離戰鬥、能夠休息的地方，確實是件好事。", "0", "0", "0", "0", "0", "cv_sk_uzkk_n6", "0", "level1,level1"},
[4400500109] = {4400500109, 14005001, 102, 5, "14_2_0_0.8", "switch2", "怎麼回事——！？", "0", "0", "0", "0", "0", "cv_sk_uzkk_n7", "0", "switch2,switch2"},
[4400500110] = {4400500110, 14005001, 94, 4, "0", "idle2", "練習中的肢體接觸也是可能發生的，但要是太過分了，我可是會讓你屈服的哦？", "0", "0", "0", "0", "0", "cv_sk_uzkk_n8", "0", "idle2,idle2"},
[4400500111] = {4400500111, 14005001, 94, 4, "0", "idle2", "嗚……！哼……這種事也是可能會發生的！真是個沒辦法的傢伙啊。", "0", "0", "0", "0", "0", "cv_sk_uzkk_n9", "0", "idle2,idle2"},
[4400500112] = {4400500112, 14005001, 94, 4, "0", "idle2", "真是的，拿你沒辦法呢……", "0", "0", "0", "0", "0", "cv_sk_uzkk_n10", "0", "idle2,idle2"},
[4400500113] = {4400500113, 14005001, 95, 5, "14_1_0_0.8", "level2", "練、練習就先這樣子吧。", "0", "0", "0", "0", "0", "cv_sk_uzkk_n11", "0", "level2,level2"},
