[415400] = {415400, 11054, 1, 1, "0", "0", "蒼霧殘響", "0", "0", "0", "0", "0", "cv_iztk_1", "0", "0"},
[415401] = {415401, 11054, 2, 2, "0", "0", "請放心去作戰，後方的安危就交給我負責吧。", "0", "0", "0", "0", "0", "cv_iztk_2", "0", "0"},
[415402] = {415402, 11054, 3, 3, "0", "0", "魔防隊第六組組長·出雲天花。有需要的地方請儘管開口。", "0", "0", "0", "0", "0", "cv_iztk_3", "0", "0"},
[415403] = {415403, 11054, 4, 4, "0", "idle", "我的能力無法在兩個世界之間傳送，真是遺憾。", "0", "0", "0", "0", "0", "cv_iztk_4", "0", "0"},
[415404] = {415404, 11054, 5, 4, "0", "idle2", "這個世界，同樣也深陷痛苦和折磨之中呢……", "0", "0", "0", "0", "0", "cv_iztk_5", "0", "0"},
[415405] = {415405, 11054, 6, 4, "0", "idle3", "希望我們消失的期間，我們的世界不要發生【魔都災害】。不過我相信即使我不在，我的組員們也能夠發揮她們的能力，及時並且完美地解決【災害】問題。", "0", "0", "0", "0", "0", "cv_iztk_6", "0", "0"},
[415406] = {415406, 11054, 7, 5, "1_》_0_0.8", "level", "我可以連續使用能力的次數上限是666次，應付一般的戰鬥已經足夠了。但如果真的遇到需要超過這個限制的情況……我會將最後的傳送，留給你們。", "0", "0", "0", "0", "0", "cv_iztk_7", "0", "0"},
[415407] = {415407, 11054, 8, 5, "1_》_0_0.8", "level2", "【原罪】、【醜鬼】，無論哪個世界的人們都得不到平靜的生活。", "0", "0", "0", "0", "0", "cv_iztk_8", "0", "0"},
[415408] = {415408, 11054, 9, 5, "1_》_100_1.5", "level3", "我身為組長只需要管理兩名組員，而你手下的駕駛員是“2”的幾十倍。真的很了不起呢。", "0", "0", "0", "0", "0", "cv_iztk_9", "0", "0"},
[415409] = {415409, 11054, 10, 5, "1_》_500_2", "level4", "沒有【桃之恩惠】的你們，很強大。", "0", "0", "0", "0", "0", "cv_iztk_10", "0", "0"},
[415410] = {415410, 11054, 11, 5, "1_》_1000_2.5", "level5", "能夠見識到不同世界的美好真的很開心，如果有機會也希望可以請你們去我們的世界做客。", "0", "0", "0", "0", "0", "cv_iztk_11", "0", "0"},
[415411] = {415411, 11054, 12, 6, "0", "0", "輕輕鬆松就變強了。", "0", "0", "0", "0", "0", "cv_iztk_12", "0", "0"},
[415412] = {415412, 11054, 13, 7, "0", "0", "很特殊的感覺。", "0", "0", "0", "0", "0", "cv_iztk_13", "0", "0"},
[415413] = {415413, 11054, 14, 8, "0", "0", "感謝你的禮物，期待我在戰鬥中的表現吧。", "0", "0", "0", "0", "0", "cv_iztk_14", "0", "0"},
[415414] = {415414, 11054, 15, 9, "0", "0", "667，能做到嗎？", "0", "0", "0", "0", "0", "cv_iztk_15", "0", "0"},
[415415] = {415415, 11054, 16, 10, "0", "0", "只有這些敵人的話，全部交給我也沒有問題的。", "0", "0", "0", "0", "0", "cv_iztk_16", "0", "0"},
[415416] = {415416, 11054, 17, 11, "0", "0", "用傳送門回去吧，大家的精力可要好好用在慶祝上。", "0", "0", "0", "0", "0", "cv_iztk_17", "0", "0"},
[415417] = {415417, 11054, 18, 12, "0", "0", "我來把傷患傳送回去。", "0", "0", "0", "0", "0", "cv_iztk_18", "0", "0"},
[415418] = {415418, 11054, 19, 13, "0", "0", "大家都受傷了，不過只要贏了就好。", "0", "0", "0", "0", "0", "cv_iztk_19", "0", "0"},
[415419] = {415419, 11054, 20, 14, "0", "0", "不要逞強，你們先走。", "0", "0", "0", "0", "0", "cv_iztk_20", "0", "0"},
[415420] = {415420, 11054, 21, 15, "0", "0", "放棄吧。", "0", "0", "0", "0", "0", "cv_iztk_21", "0", "0"},
[415421] = {415421, 11054, 23, 16, "0", "0", "安息吧。", "0", "0", "0", "0", "0", "cv_iztk_22", "0", "0"},
[415422] = {415422, 11054, 24, 17, "0", "0", "逃不掉的。", "0", "0", "0", "0", "0", "cv_iztk_23", "0", "0"},
[415423] = {415423, 0, 22, 38, "0", "0", "天·禦·鳥·命", "0", "0", "0", "0", "0", "cv_iztk_24", "0", "0"},
[415424] = {415424, 11054, 25, 18, "0", "0", "你想逃到哪裡？", "0", "0", "0", "0", "0", "cv_iztk_25", "0", "0"},
[415425] = {415425, 11054, 26, 19, "0", "0", "抱歉，接下來就交給你們了。", "0", "0", "0", "0", "0", "cv_iztk_26", "0", "0"},
