[423000] = {423000, 12030, 1, 1, "0", "0", "蒼霧殘響", "0", "0", "0", "0", "0", "cv_azhm_1", "0", "0"},
[423001] = {423001, 12030, 2, 2, "0", "0", "輪到我駐守了嗎？請您放心，我會用生命保護這裡。", "0", "0", "0", "0", "0", "cv_azhm_2", "0", "0"},
[423002] = {423002, 12030, 3, 3, "0", "0", "魔防隊第七組副組長·東日萬凜參上。按照隊長的命令，現在開始聽從您的指揮，領航。", "0", "0", "0", "0", "0", "cv_azhm_3", "0", "0"},
[423003] = {423003, 12030, 4, 4, "0", "idle", "如果沒有戰鬥任務的話，請允許我先行離隊，今天的日常訓練還沒有完成。", "0", "0", "0", "0", "0", "cv_azhm_4", "0", "0"},
[423004] = {423004, 12030, 5, 4, "0", "idle", "巨大化後身體靈活性降低了很多，但是看那些駕駛員們好像沒受太大影響。為了掌控巨大化的力量，看來必須加強相關的訓練……或許應該去請教一下朱朱。", "0", "0", "0", "0", "0", "cv_azhm_5", "0", "0"},
[423005] = {423005, 12030, 6, 4, "0", "idle", "這次的危機也是一次機會，我一定要在對抗【原罪】的戰鬥裡取得令人稱讚的戰績。", "0", "0", "0", "0", "0", "cv_azhm_6", "0", "0"},
[423006] = {423006, 12030, 7, 5, "1_》_0_0.8", "level", "第七組幾乎全員都來到了這個世界，要是在這期間發生【魔都災害】的話，後果不堪設想。京香隊長一定也在苦惱這件事吧。", "0", "0", "0", "0", "0", "cv_azhm_7", "0", "0"},
[423007] = {423007, 12030, 8, 5, "1_》_0_0.8", "level2", "身為駕駛員的大家，都很努力呢。", "0", "0", "0", "0", "0", "cv_azhm_8", "0", "0"},
[423008] = {423008, 12030, 9, 5, "1_》_100_1.5", "level3", "這個世界也有“拉麵”！太好了。", "0", "0", "0", "0", "0", "cv_azhm_9", "0", "0"},
[423009] = {423009, 12030, 10, 5, "1_》_500_2", "level4", "請領航將駕駛員的訓練方法傳授於我，無論多麼辛苦我都能夠接受。我不想再在面對原罪時束手無策。", "0", "0", "0", "0", "0", "cv_azhm_10", "0", "0"},
[423010] = {423010, 12030, 11, 5, "1_》_1000_2.5", "level5", "我覺得領航和京香隊長很像，都是那麼強大並擁有領袖魅力的人。我相信領航一定能帶領人類消滅所有【原罪】，正如我相信京香隊長一樣。", "0", "0", "0", "0", "0", "cv_azhm_11", "0", "0"},
[423011] = {423011, 12030, 12, 6, "0", "0", "領航的訓練方法，效果真的很不錯。", "0", "0", "0", "0", "0", "cv_azhm_12", "0", "0"},
[423012] = {423012, 12030, 13, 7, "0", "0", "能明顯感覺到實力的提升。", "0", "0", "0", "0", "0", "cv_azhm_13", "0", "0"},
[423013] = {423013, 12030, 14, 8, "0", "0", "我已經和之前不同了，有了這股力量，我一定能向所有人證明自己。", "0", "0", "0", "0", "0", "cv_azhm_14", "0", "0"},
[423014] = {423014, 12030, 15, 9, "0", "0", "要保持這股勢頭。", "0", "0", "0", "0", "0", "cv_azhm_15", "0", "0"},
[423015] = {423015, 12030, 16, 10, "0", "0", "魔防隊第七組東日萬凜到達戰場。", "0", "0", "0", "0", "0", "cv_azhm_16", "0", "0"},
[423016] = {423016, 12030, 17, 11, "0", "0", "終於，我做到了。", "0", "0", "0", "0", "0", "cv_azhm_17", "0", "0"},
[423017] = {423017, 12030, 18, 12, "0", "0", "還不夠完美，不能就此自滿。", "0", "0", "0", "0", "0", "cv_azhm_18", "0", "0"},
