[4203000102] = {4203000102, 12030001, 3, 3, "0", "0", "魔防隊第七組副組長·東日萬凜參上。按照隊長的命令，現在開始聽從您的指揮，領航。", "0", "0", "0", "0", "0", "cv_sk_azhm_3", "0", "0"},
[4203000103] = {4203000103, 12030001, 93, 5, "14_2_0_0.8", "switch1", "哇啊——！", "0", "0", "0", "0", "0", "cv_sk_azhm_n1", "0", "switch1,switch1"},
[4203000104] = {4203000104, 12030001, 91, 4, "0", "idle", "雖然是借用你們的地方，但現在這裡是我的私人房間，請尊重我的個人隱私。", "0", "0", "0", "0", "0", "cv_sk_azhm_n2", "0", "idle,idle"},
[4203000105] = {4203000105, 12030001, 91, 4, "0", "idle", "您平時也是這樣冒冒失失地闖入別的女孩子房間的嗎？看來我今天有必要為她們伸張正義。", "0", "0", "0", "0", "0", "cv_sk_azhm_n3", "0", "idle,idle"},
[4203000106] = {4203000106, 12030001, 91, 4, "0", "idle", "因為連續通宵工作幾天頭昏腦漲，沒注意所以走錯了房間？是在忙著處理我們的事嗎……即便如此，我也不能原諒。", "0", "0", "0", "0", "0", "cv_sk_azhm_n4", "0", "idle,idle"},
[4203000107] = {4203000107, 12030001, 92, 5, "14_1_0_0.8", "level1", "我對這裡的印象？這裡的拉麵不錯，僅此而已。", "0", "0", "0", "0", "0", "cv_sk_azhm_n5", "0", "level1,level1"},
[4203000108] = {4203000108, 12030001, 92, 5, "14_1_0_0.8", "level1", "如果沒有重要的事情，那我就先睡覺了。您最好也回去好好休息……謝謝你這幾天的付出。", "0", "0", "0", "0", "0", "cv_sk_azhm_n6", "0", "level1,level1"},
