[415301] = {415301, 11053, 2, 2, "0", "0", "誒~就安排我待這裡？我說你小子，是不是在小瞧我？", "0", "0", "0", "0", "0", "cv_aoba_2", "0", "0"},
[415302] = {415302, 11053, 3, 3, "0", "0", "你就是領航？醜話說在前頭，我只會按照自己的方式戰鬥，你就在一旁看我給你奪取勝利吧。", "0", "0", "0", "0", "0", "cv_aoba_3", "0", "0"},
[415303] = {415303, 11053, 4, 4, "0", "idle", "無聊，無聊……無聊，無聊，無聊，無聊，這裡太沒勁了！", "0", "0", "0", "0", "0", "cv_aoba_4", "0", "0"},
[415304] = {415304, 11053, 5, 4, "0", "idle2", "那邊的人就像是搬家的螞蟻一樣，我來幫幫他們吧。", "0", "0", "0", "0", "0", "cv_aoba_5", "0", "0"},
[415305] = {415305, 11053, 6, 4, "0", "idle3", "好久沒有享受這麼悠閒的時光了，最近一直在為覆滅陰陽寮的事忙這忙那的……就當是一次難得的修學旅行吧，好好放鬆一下，然後回去把討厭的傢伙們打爆。", "0", "0", "0", "0", "0", "cv_aoba_6", "0", "0"},
[415306] = {415306, 11053, 7, 5, "1_》_0_0.8", "level", "身上帶的“桃子”不多了……唉，沒想到我有一天會過上連“桃子”都要省著吃的日子。啊嗚——唔姆唔姆~", "0", "0", "0", "0", "0", "cv_aoba_7", "0", "0"},
[415307] = {415307, 11053, 8, 5, "1_》_0_0.8", "level2", "我的頭髮可沒看上去那麼溫柔。", "0", "0", "0", "0", "0", "cv_aoba_8", "0", "0"},
[415308] = {415308, 11053, 9, 5, "1_》_100_1.5", "level3", "這裡的人們看到我好像沒有一點驚訝，他們到底見識過多少怪人？", "0", "0", "0", "0", "0", "cv_aoba_9", "0", "0"},
[415309] = {415309, 11053, 10, 5, "1_》_500_2", "level4", "【原罪】可真是巨大啊，要是能帶幾隻回去，說不定就統治魔都了。可惜它們不像【醜鬼】一樣會聽我的話。", "0", "0", "0", "0", "0", "cv_aoba_10", "0", "0"},
[415310] = {415310, 11053, 11, 5, "1_》_1000_2.5", "level5", "聽說領航你有個妹妹，而且還是你的情報官？不錯，有著如此出色的兄長，你的妹妹一定會為你自豪的。", "0", "0", "0", "0", "0", "cv_aoba_11", "0", "0"},
[415311] = {415311, 11053, 12, 6, "0", "0", "哦~變強了，變強了。", "0", "0", "0", "0", "0", "cv_aoba_12", "0", "0"},
