[4105300107] = {4105300107, 11053001, 92, 5, "14_1_0_0.8", "level1", "身體沒有發抖，看來你很習慣這樣的戰場嘛。我的身體已經興奮得止不住發抖了啊。", "0", "0", "0", "0", "0", "cv_sk_aoba_n5", "0", "0,0"},
