[432408] = {432408, 13024, 9, 5, "1_》_100_1.5", "touch", "在甯的爸爸媽媽消失之後，寧吃下【桃】，獲得了千里眼的【桃之能力】，我想那一定是因為寧想要找到他們的心情而變化而來的吧？", "0", "0", "0", "0", "0", "cv_okni_9", "0", "0"},
[432409] = {432409, 13024, 10, 5, "1_》_500_2", "touch", "對於寧來說……魔防隊的工作很重要！因為說不定有一天，寧就能在魔都找到失蹤的爸爸媽媽了！", "0", "0", "0", "0", "0", "cv_okni_10", "0", "0"},
