[404202] = {404202, 10042, 3, 3, "0", "0", "駿河朱朱，將在異世界開始新的冒險~！", "0", "0", "0", "0", "0", "cv_srss_3", "0", "0"},
[404203] = {404203, 10042, 4, 4, "0", "idle", "我的特殊之處現在就只有能變小了……不對，只要我想的話我也可以變得更大，比一般駕駛員都大！", "0", "0", "0", "0", "0", "cv_srss_4", "0", "0"},
[404204] = {404204, 10042, 5, 4, "0", "idle", "沒想到真遇到了漫畫裡面會發生的事情~我還以為會有更有奇幻冒險風格的那種世界呢……", "0", "0", "0", "0", "0", "cv_srss_5", "0", "0"},
[404205] = {404205, 10042, 6, 4, "0", "idle", "不過不管怎麼說，這個世界和我們世界還是有著微妙的不同呢，好想去這個方舟的裡面看看，要不等一下領航和我一起去探險怎麼樣？", "0", "0", "0", "0", "0", "cv_srss_6", "0", "0"},
[404206] = {404206, 10042, 7, 5, "1_》_0_0.8", "level1", "嗯……不知道媽媽和姐姐們怎麼樣了，對了……這是異世界轉生漫畫都從不會過度提及的內容呢……轉生者的家人們在失去了親人之後還要堅強地活在世界上之類的事情。", "0", "0", "0", "0", "0", "cv_srss_7", "0", "0"},
[404207] = {404207, 10042, 8, 5, "1_》_0_0.8", "level2", "“好無聊啊……”我就這樣想著成為了魔防隊的一員！", "0", "0", "0", "0", "0", "cv_srss_8", "0", "0"},
[404208] = {404208, 10042, 9, 5, "1_》_100_1.5", "level3", "我可以去其他地方看看嗎？隨便逛逛沒事的吧？嗯~如果遇到原罪打飛它們就好了。", "0", "0", "0", "0", "0", "cv_srss_9", "0", "0"},
[404209] = {404209, 10042, 10, 5, "1_》_500_2", "level4", "沒想到這個異世界竟然和我們的世界沒什麼太大區別……就連語言之間都沒有溝通障礙……為什麼？", "0", "0", "0", "0", "0", "cv_srss_10", "0", "0"},
[404210] = {404210, 10042, 11, 5, "1_》_1000_2.5", "level5", "《駿河朱朱的異世界冒險體驗報告》，如果回去之後寫這麼一本書的話會不會爆火呢……嘿，為了寫出這本書——今天我們去什麼地方？", "0", "0", "0", "0", "0", "cv_srss_11", "0", "0"},
[404211] = {404211, 10042, 12, 6, "0", "0", "哦，我知道這個，加點就能升級對吧。", "0", "0", "0", "0", "0", "cv_srss_12", "0", "0"},
[404212] = {404212, 10042, 13, 7, "0", "0", "果然異世界就是不一樣~", "0", "0", "0", "0", "0", "cv_srss_13", "0", "0"},
[404213] = {404213, 10042, 14, 8, "0", "0", "覺醒……嗯……微妙……我還以會像【桃之果實】一樣會給予我新的能力。可惜了，要是我也能有更主人公一樣的能力就好了。", "0", "0", "0", "0", "0", "cv_srss_14", "0", "0"},
