[4004200108] = {4004200108, 10042001, 92, 5, "14_1_0_0.8", "level3", "要試試站在我的手上嗎，我可以和你玩舉高高的遊戲哦……飛咯飛咯……這樣把你拋起來接住……", "0", "0", "0", "0", "0", "cv_sk_srss_n6", "0", "0,0"},
