[4004200110] = {4004200110, 10042001, 94, 4, "0", "idle2", "戰鬥過後稍微有點熱呢……幻化裝置竟然這麼方便嗎……有藍圖的話不是什麼樣的衣服我都能換？", "0", "0", "0", "0", "0", "cv_sk_srss_n8", "0", "0,0"},
[4004200111] = {4004200111, 10042001, 94, 4, "0", "idle2", "嗯~流了汗之後被風拂過~真暢快~啊……！不會有很重的汗味吧！嗅嗅……嗅嗅……", "0", "0", "0", "0", "0", "cv_sk_srss_n9", "0", "0,0"},
[4004200112] = {4004200112, 10042001, 94, 4, "0", "idle2", "等會打算去吃點什麼嗎？", "0", "0", "0", "0", "0", "cv_sk_srss_n10", "0", "0,0"},
[4004200113] = {4004200113, 10042001, 95, 5, "14_1_0_0.8", "level2", "這樣的天氣真適合野餐……嗯……說到野餐口有點渴了……嗯？你帶了牛奶……？哈哈，那等我變小了之後再給我吧。", "0", "0", "0", "0", "0", "cv_sk_srss_n11", "0", "0,0"},
[4004200114] = {4004200114, 10042001, 95, 5, "14_1_0_0.8", "level4", "把你推舉到對面那棟大樓的樓頂上哦。", "0", "0", "0", "0", "0", "cv_sk_srss_n12", "0", "0,0"},
[4004200115] = {4004200115, 10042001, 12, 6, "0", "0", "哦，我知道這個，加點就能升級對吧。", "0", "0", "0", "0", "0", "cv_sk_srss_12", "0", "0"},
[4004200116] = {4004200116, 10042001, 13, 7, "0", "0", "果然異世界就是不一樣~", "0", "0", "0", "0", "0", "cv_sk_srss_13", "0", "0"},
[4004200117] = {4004200117, 10042001, 14, 8, "0", "0", "覺醒……嗯……微妙……我還以會像【桃之果實】一樣會給予我新的能力。可惜了，要是我也能有更主人公一樣的能力就好了。", "0", "0", "0", "0", "0", "cv_sk_srss_14", "0", "0"},
[4004200118] = {4004200118, 10042001, 15, 9, "0", "0", "更有力氣了！", "0", "0", "0", "0", "0", "cv_sk_srss_15", "0", "0"},
