[4400000200] = {4400000200, 14000002, 1, 1, "0", "0", "蒼霧殘響", "0", "0", "0", "0", "0", "cv_starry2_1", "0", "0"},
[4400000201] = {4400000201, 14000002, 2, 2, "0", "0", "有沒有想我？我倒是每天都在想你，色狼先生。", "0", "0", "0", "0", "0", "cv_starry2_2", "0", "0"},
[4400000202] = {4400000202, 14000002, 3, 3, "0", "0", "色狼先生，這段時間有好好吃飯，好好休息嗎，感覺你消瘦了不少——我？沒事的，只是點小事故，跟喝水被嗆到沒區別。", "0", "0", "0", "0", "0", "cv_starry2_3", "0", "0"},
[4400000203] = {4400000203, 14000002, 4, 4, "0", "idle", "色狼先生，掌握主權的“鎖鏈”就在你的手中，想做什麼，怎麼做，取決於你內心的真實想法——要去直面它們嗎？", "0", "0", "0", "0", "0", "cv_starry2_4", "0", "0"},
[4400000204] = {4400000204, 14000002, 5, 4, "0", "idle", "最近，駕駛員之間似乎都在議論色狼先生呢——說你實際上是一個有著施虐癖好的怪人呢。要是被她們看到這一幕，你一輩子也洗不清罪名了吧？", "0", "0", "0", "0", "0", "cv_starry2_5", "0", "0"},
[4400000205] = {4400000205, 14000002, 6, 4, "0", "idle", "色狼先生打算做什麼呢？還是什麼都不做呢？不管你打算怎麼做，我都很期待呢。", "0", "0", "0", "0", "0", "cv_starry2_6", "0", "0"},
[4400000206] = {4400000206, 14000002, 7, 5, "14_1_0_0.8", "level1", "咳咳——突然扯繩子的話，比想像中要痛呢。", "0", "0", "0", "0", "0", "cv_starry2_7", "0", "0"},
[4400000207] = {4400000207, 14000002, 8, 5, "14_1_0_0.8", "level2", "雖然是我自己同意的，但我可沒有想到色狼先生你也會接受這種懲罰提議呢——真是壞心眼啊。", "0", "0", "0", "0", "0", "cv_starry2_8", "0", "0"},
[4400000208] = {4400000208, 14000002, 9, 5, "14_1_0_0.8", "level3", "讓我們盡情享受現在的時光吧。", "0", "0", "0", "0", "0", "cv_starry2_9", "0", "0"},
[4400000209] = {4400000209, 14000002, 9, 5, "14_1_0_0.8", "level4", "你還真是一點都不留情……那個叫做弗蘭卡的孩子，也被你這麼做過吧？你還真是殘忍呢，色狼先生。", "0", "0", "0", "0", "0", "cv_starry2_9", "0", "0"},
[4400000210] = {4400000210, 14000002, 9, 5, "14_1_0_0.8", "level4", "唉——我已經有點後悔了噢，感覺像是上了史蒂芬妮和你的當了。", "0", "0", "0", "0", "0", "cv_starry2_9", "0", "0"},
[4400000211] = {4400000211, 14000002, 10, 5, "14_2_0_0.8", "switch1", "要開始了嗎？", "0", "0", "0", "0", "0", "cv_starry2_10", "0", "0"},
[4400000212] = {4400000212, 14000002, 11, 5, "14_2_0_0.8", "switch2", "呵呵。", "0", "0", "0", "0", "0", "cv_starry2_11", "0", "0"},
[4400000213] = {4400000213, 14000002, 12, 6, "0", "0", "哈哈……手有點疼……", "0", "0", "0", "0", "0", "cv_starry2_12", "0", "0"},
[4400000214] = {4400000214, 14000002, 13, 7, "0", "0", "還算在控制範圍吧。", "0", "0", "0", "0", "0", "cv_starry2_13", "0", "0"},
[4400000215] = {4400000215, 14000002, 14, 8, "0", "0", "在燃盡之前綻放出最耀眼的光，這就是我要做的事。", "0", "0", "0", "0", "0", "cv_starry2_14", "0", "0"},
[4400000216] = {4400000216, 14000002, 15, 9, "0", "0", "偶爾也想變得更耀眼一點。", "0", "0", "0", "0", "0", "cv_starry2_15", "0", "0"},
[4400000217] = {4400000217, 14000002, 16, 10, "0", "0", "又能並肩作戰了呢。", "0", "0", "0", "0", "0", "cv_starry2_16", "0", "0"},
[4400000218] = {4400000218, 14000002, 17, 11, "0", "0", "真無聊。", "0", "0", "0", "0", "0", "cv_starry2_17", "0", "0"},
