[4400000226] = {4400000226, 14000002, 26, 19, "0", "0", "丟人現眼了啊……", "0", "0", "0", "0", "0", "cv_starry2_26", "0", "0"},
[4400000227] = {4400000227, 14000002, 27, 20, "0", "0", "哈哈哈——讓我想起我們第一次見面的時候……“第一次”……", "0", "0", "0", "0", "0", "cv_starry2_27", "0", "0"},
[4400000228] = {4400000228, 14000002, 28, 21, "0", "0", "那些東西……果然還是有點嚇人吧？不知道除黑頭的面膜能不能除去它們呢？", "0", "0", "0", "0", "0", "cv_starry2_28", "0", "0"},
