[4400000230] = {4400000230, 14000002, 30, 22, "0", "0", "發生好事了嗎？", "0", "0", "0", "0", "0", "cv_starry2_30", "0", "0"},
[4400000231] = {4400000231, 14000002, 31, 23, "0", "0", "又要來嗎？", "0", "0", "0", "0", "0", "cv_starry2_31", "0", "0"},
[4400000232] = {4400000232, 14000002, 32, 24, "0", "0", "這次我想直率的表達——我很高興，色狼先生。", "0", "0", "0", "0", "0", "cv_starry2_32", "0", "0"},
[4400000233] = {4400000233, 14000002, 33, 25, "0", "0", "別在意~總會有錯的時候。", "0", "0", "0", "0", "0", "cv_starry2_33", "0", "0"},
[4400000234] = {4400000234, 14000002, 34, 26, "0", "0", "噢，是壞心眼的色狼先生——想得怎麼樣了？是打算懲罰我，還是獎勵我呢？", "0", "0", "0", "0", "0", "cv_starry2_34", "0", "0"},
[4400000235] = {4400000235, 14000002, 35, 27, "0", "0", "好啦，戰場還在等著我們呢，出發吧。", "0", "0", "0", "0", "0", "cv_starry2_35", "0", "0"},
[4400000236] = {4400000236, 14000002, 36, 28, "0", "0", "我不會讓給別人的。", "0", "0", "0", "0", "0", "cv_starry2_36", "0", "0"},
[4400000237] = {4400000237, 14000002, 37, 29, "0", "0", "又多了些不認識的人呢。", "0", "0", "0", "0", "0", "cv_starry2_37", "0", "0"},
[4400000238] = {4400000238, 14000002, 38, 30, "0", "0", "你還真是永不滿足呢。", "0", "0", "0", "0", "0", "cv_starry2_38", "0", "0"},
[4400000239] = {4400000239, 14000002, 39, 31, "0", "0", "全力武裝自己，盡可能變強吧。", "0", "0", "0", "0", "0", "cv_starry2_39", "0", "0"},
