[4400000243] = {4400000243, 14000002, 43, 35, "0", "0", "又是女孩子的信嗎？", "0", "0", "0", "0", "0", "cv_starry2_43", "0", "0"},
[4400000244] = {4400000244, 14000002, 44, 36, "0", "0", "真有精神啊。", "0", "0", "0", "0", "0", "cv_starry2_44", "0", "0"},
[4400000245] = {4400000245, 14000002, 45, 37, "0", "0", "哈啊……", "0", "0", "0", "0", "0", "cv_starry2_45", "0", "0"},
[4200000100] = {4200000100, 12000001, 1, 1, "0", "0", "蒼霧殘響！", "苍雾残响（ハツリバーブ）！", "0", "0", "苍雾残响！", "0", "cv_kinkura_32", "0", "0"},
[4200000101] = {4200000101, 12000001, 2, 2, "0", "0", "喔吼~還真是有眼光啊~", "おほほ、见る目があるのね。", "0", "0", "哦吼~还真是有眼光啊~", "0", "cv_kinkura_2", "0", "0"},
[4200000102] = {4200000102, 12000001, 3, 3, "0", "0", "喔吼吼~你就是那個多瑙的領航嗎？聽好了，本小姐的名字是金庫啦，好好記住吧。", "おーっほっほ、あんたがあのダニューブのナビゲーター？よく闻いて！あたしはキンクラ。ちゃんと覚えなさい？", "0", "0", "哦吼吼~你就是那个多瑙的领航吗？听好了，本小姐的名字是金库啦，好好记住吧。", "0", "cv_kinkura_1", "0", "0"},
[4200000103] = {4200000103, 12000001, 4, 4, "0", "idle", "富有的人貢獻金錢，強壯的人貢獻力量。當然~對於我來說，金錢就是力量！", "お金持ちがお金を出す。体の强い人が力を出す。まぁ、あたしにとっては、お金イコール力だからね！", "0", "0", "富有的人贡献金钱，强壮的人贡献力量。当然~对于我来说，金钱就是力量！", "0", "cv_kinkura_3", "0", "0"},
[4200000104] = {4200000104, 12000001, 5, 4, "0", "idle", "真是可惜啊，像你這樣的人才如果能來九州的話，一定會為我們帶來新的變革吧。", "残念ね。あんたみたいな人が九州岛に来たら、きっと新しい変化をもたらしてくれるのに。", "0", "0", "真是可惜啊，像你这样的人才如果能来九州岛的话，一定会为我们带来新的变革吧。", "0", "cv_kinkura_4", "0", "0"},
[4200000105] = {4200000105, 12000001, 6, 4, "0", "idle", "多瑙的領航，你不覺得露露啦太天真了嗎？她那種溫柔的性格，太容易被人利用了。嗯？你也這麼覺得……喂，她可是本小姐先看上的！", "ルルラってホント単纯すぎる。そう思わない？あんな优しい性格じゃ利用されちゃうよね。そっか、あんたもそう思って……？待って、彼女はあたしが先に目を付けたんだからね！", "0", "0", "多瑙的领航，你不觉得露露啦太天真了吗？她那种温柔的性格，太容易被人利用了。嗯？你也这么觉得……喂，她可是本小姐先看上的！", "0", "cv_kinkura_29", "0", "0"},
[4200000106] = {4200000106, 12000001, 7, 5, "15_1_0_0.8", "touch1", "加入這場戰爭，不過是本小姐計畫的第一步。與異獸的戰爭結束後，本小姐的商業帝國也就成型了，哼哼哼！", "この戦争に参加するのはあたしの计划の第一歩に过ぎない。原罪との戦争が终わったら、あたしの商业帝国も形になってるはず。ふっふっふー", "0", "0", "加入这场战争，不过是本小姐计划的第一步。与原罪的战争结束后，本小姐的商业帝国也就成型了，哼哼哼！", "0", "cv_kinkura_30", "0", "0"},
[4200000107] = {4200000107, 12000001, 8, 5, "15_1_0_0.8", "touch1", "喔吼~難道說你終於打算轉部了嗎？放心好了，只要有本小姐的指示，你的待遇一切從優。", "おほほほ、ようやく転部を决心したの？安心して。あたしからの指示さえあれば、あんたの待遇は保证されるよ。", "0", "0", "哦吼~难道说你终于打算转部了吗？放心好了，只要有本小姐的指示，你的待遇一切从优。", "0", "cv_kinkura_5", "0", "0"},
[4200000108] = {4200000108, 12000001, 9, 5, "15_1_0_0.8", "touch1", "沒錯，沒錯。本小姐確實是結果主義者，只要能夠幫助到那些有困難的人。我既可以是商人，也可以是戰士。", "そう、そうなのよ。困ってる人を助けられるかどうか、あたしは成果主义者なの。あたしは商人でもあり、戦士でもあるのよ。", "0", "0", "没错，没错。本小姐确实是结果主义者，只要能够帮助到那些有困难的人。我既可以是商人，也可以是战士。", "0", "cv_kinkura_6", "0", "0"},
[4200000109] = {4200000109, 12000001, 10, 5, "15_2_0_0.8", "touch2", "雖然家裡的長輩曾經教導過我們，不要妄圖使用金錢解決一切問題。但是，我明白，有些事情必須要用金錢來解決……比如說，想要為那些流離失所的孩子們建起一座大廈，光靠力氣是絕對辦不到的。", "全てのことをお金で解决しようとしてはいけないって、家族に教わってるけど。でも、时にはそうしなければならないこともあると、あたしは思ってる……たとえば、居场所を失ってしまった子供たちのためにビルを建てることは、力だけじゃできないでしょ。", "0", "0", "虽然家里的长辈曾经教导过我们，不要妄图使用金钱解决一切问题。但是，我明白，有些事情必须要用金钱来解决……比如说，想要为那些流离失所的孩子们建起一座大厦，光靠力气是绝对办不到的。", "0", "cv_kinkura_7", "0", "0"},
[4200000110] = {4200000110, 12000001, 11, 5, "15_2_0_0.8", "touch2", "無價之寶嗎……確實啊，我承認，這個世界上確實存在著無法用金錢衡量的事物。比如爺爺曾經說過的，人和人之間的聯繫，信任，與愛意……究竟從何時起，我好像也能漸漸體會到這其中的含義了。", "価値なき宝か……确かに、この世にはお金で価値を判断できないものはある。たとえば、人と人の间にある繋がり、信頼、爱がそうだって……おじいちゃんが言ってた。いつの间にかあたしもその意味が分かるようになった気がする。", "0", "0", "无价之宝吗……确实啊，我承认，这个世界上确实存在着无法用金钱衡量的事物。比如爷爷曾经说过的，人和人之间的联系，信任，与爱意……究竟从何时起，我好像也能渐渐体会到这其中的含义了。", "0", "cv_kinkura_8", "0", "0"},
[4200000111] = {4200000111, 12000001, 12, 6, "0", "0", "看來我的股勢要大漲啦。", "どうやらあたしの株が大きく上がったみたいね。", "0", "0", "看来我的股势要大涨啦。", "0", "cv_kinkura_9", "0", "0"},
[4200000112] = {4200000112, 12000001, 13, 7, "0", "0", "喔吼吼~沒錯，就是這樣，你投入得越多我的力量也會變得越大。這便是，等價交換！", "おーっほっほ、そうなの。あんたからの投资が多いほど、あたしの力は大きくなるの。これはいわば等価交换ってやつなのよ！", "0", "0", "哦吼吼~没错，就是这样，你投入得越多我的力量也会变得越大。这便是，等价交换！", "0", "cv_kinkura_10", "0", "0"},
[4200000113] = {4200000113, 12000001, 14, 8, "0", "0", "將攢到現在的積蓄全部都投在我身上了嗎？這樣真的好嗎？事到如今本小姐可不允許你反悔喔~", "今まで贮めてきたものを全部あたしに？本当にいいの？后悔しても遅いわよっ。", "0", "0", "将攒到现在的积蓄全部都投在我身上了吗？这样真的好吗？事到如今本小姐可不允许你反悔哦~", "0", "cv_kinkura_11", "0", "0"},
[4200000114] = {4200000114, 12000001, 15, 9, "0", "0", "看來新訂的貨到了啊，正好想去活動一下呢。", "新しく発注したものが届いたみたいね。ちょうど、体を动かそうと思ってたところなの。", "0", "0", "看来新订的货到了啊，正好想去活动一下呢。", "0", "cv_kinkura_12", "0", "0"},
[4200000115] = {4200000115, 12000001, 16, 10, "0", "0", "來試試新買的玩具吧。", "新しく买ったおもちゃを试してみようっと。", "0", "0", "来试试新买的玩具吧。", "0", "cv_kinkura_13", "0", "0"},
[4200000116] = {4200000116, 12000001, 17, 11, "0", "0", "金錢就是力量！", "お金こそ力よ！", "0", "0", "金钱就是力量！", "0", "cv_kinkura_14", "0", "0"},
[4200000117] = {4200000117, 12000001, 18, 12, "0", "0", "喔吼~看來你們這邊給的獎金也不算少嘛。", "おほほほ、どうやらあんたたちからの报酬も少なくないみたいね。", "0", "0", "哦吼~看来你们这边给的奖金也不算少嘛。", "0", "cv_kinkura_15", "0", "0"},
[4200000118] = {4200000118, 12000001, 19, 13, "0", "0", "哼，本小姐只不過是稍微有些累了而已。", "ふん。ちょっと疲れただけよ。", "0", "0", "哼，本小姐只不过是稍微有些累了而已。", "0", "cv_kinkura_16", "0", "0"},
[4200000119] = {4200000119, 12000001, 20, 14, "0", "0", "果然……除了金錢外還需要投入更多的精力啊。", "やっぱり……お金以外にももっと力を入れるべきだったわ。", "0", "0", "果然……除了金钱外还需要投入更多的精力啊。", "0", "cv_kinkura_17", "0", "0"},
[4200000120] = {4200000120, 12000001, 21, 15, "0", "0", "你的賞金本小姐可不稀罕喔。", "あんたからの赏金、别に要らないわ。", "0", "0", "你的赏金本小姐可不稀罕哦。", "0", "cv_kinkura_18", "0", "0"},
[4200000121] = {4200000121, 12000001, 23, 16, "0", "0", "你們的好日子要到頭了喔~", "どうやらここまでのようね。", "0", "0", "你们的好日子要到头了哦~", "0", "cv_kinkura_20", "0", "0"},
[4200000122] = {4200000122, 12000001, 22, 38, "0", "0", "喂~", "ちょっと待って。", "0", "0", "喂~", "0", "cv_kinkura_19", "0", "0"},
[4200000123] = {4200000123, 12000001, 26, 19, "0", "0", "怎麼會……歐朵啦……領航……救救我……", "そんな……オードラ……ナビゲーター……助けて……", "0", "0", "怎么会……欧朵啦……领航……救救我……", "0", "cv_kinkura_21", "0", "0"},
[4200000124] = {4200000124, 12000001, 27, 20, "0", "0", "你來了啊，多瑙的領航，要和本小姐一起泡澡嗎？", "来たんだ？ナビゲーター。あたしと一绪にお风吕に入る？", "0", "0", "你来了啊，多瑙的领航，要和本小姐一起泡澡吗？", "0", "cv_kinkura_22", "0", "0"},
[4200000125] = {4200000125, 12000001, 28, 21, "0", "0", "喔吼吼~沒想到你們多瑙也有泡澡的習慣啊。", "おほほ、あんたたちダニューブにもお风吕に入る习惯があったのね。", "0", "0", "哦吼吼~没想到你们多瑙也有泡澡的习惯啊。", "0", "cv_kinkura_23", "0", "0"},
[4200000126] = {4200000126, 12000001, 29, 21, "0", "0", "說起來，領航下次要不要來體驗下九州那邊的澡堂文化呢？放心好了，我請客就是了。", "そういえば、今度は九州岛のお风吕文化を体験してみない？安心して、あたしのおごりだから。", "0", "0", "说起来，领航下次要不要来体验下九州岛那边的澡堂文化呢？放心好了，我请客就是了。", "0", "cv_kinkura_24", "0", "0"},
[4200000127] = {4200000127, 12000001, 30, 22, "0", "0", "看來這裡也有窺探著我的財寶的小偷呢。", "どうやらここにもあたしの财宝を狙ってる泥棒がいるみたい。", "0", "0", "看来这里也有窥探着我的财宝的小偷呢。", "0", "cv_kinkura_25", "0", "0"},
[4200000128] = {4200000128, 12000001, 31, 23, "0", "0", "不要有壓力，放鬆挑戰吧。", "自分にプレッシャーをかけないで。リラックスして挑戦しなさい。", "0", "0", "不要有压力，放松挑战吧。", "0", "cv_kinkura_26", "0", "0"},
[4200000129] = {4200000129, 12000001, 32, 24, "0", "0", "喔吼吼~看來你和本小姐還真是有緣啊。", "おほほ、どうやらあたしとは随分縁があるようね。", "0", "0", "哦吼吼~看来你和本小姐还真是有缘啊。", "0", "cv_kinkura_27", "0", "0"},
[4200000130] = {4200000130, 12000001, 33, 25, "0", "0", "你總會做出讓本小姐出乎意料的事呢~當然，這次可不算驚喜~", "あんたっていつも予想のつかないことをやってくれるのね。もちろん、今回のはサプライズでも何でもないけど。", "0", "0", "你总会做出让本小姐出乎意料的事呢~当然，这次可不算惊喜~", "0", "cv_kinkura_28", "0", "0"},
[4200000131] = {4200000131, 12000001, 34, 26, "0", "0", "太慢了，你以為本小姐等你多久了啊？", "遅すぎ。あたしがどれだけ待ってたと思うの？", "0", "0", "太慢了，你以为本小姐等你多久了啊？", "0", "cv_kinkura_31", "0", "0"},
[4200000132] = {4200000132, 12000001, 35, 27, "0", "0", "危機四伏之地，處處都是商機。我們出發吧，多瑙的領航！", "危険が多い场所には商机も沢山あるからね。出発しよう。", "0", "0", "危机四伏之地，处处都是商机。我们出发吧，多瑙的领航！", "0", "cv_kinkura_33", "0", "0"},
[4200000133] = {4200000133, 12000001, 36, 28, "0", "0", "優秀的商人能從日常中發現寶藏。", "优秀な商人は日常生活の中でも宝を见つけられるの。", "0", "0", "优秀的商人能从日常中发现宝藏。", "0", "cv_kinkura_34", "0", "0"},
[4200000134] = {4200000134, 12000001, 37, 29, "0", "0", "雇傭這麼多人要花多少錢啊？", "これくらい人を雇うのって、どのくらいお金がかかるの？", "0", "0", "雇佣这么多人要花多少钱啊？", "0", "cv_kinkura_35", "0", "0"},
[4200000135] = {4200000135, 12000001, 38, 30, "0", "0", "又要招新人了嗎？", "また新人を募集するの？", "0", "0", "又要招新人了吗？", "0", "cv_kinkura_36", "0", "0"},
[4200000136] = {4200000136, 12000001, 39, 31, "0", "0", "要精打細算喔！", "细かく计算しないとね！", "0", "0", "要精打细算噢！", "0", "cv_kinkura_37", "0", "0"},
[4200000137] = {4200000137, 12000001, 40, 32, "0", "0", "把需要的東西列在清單上吧。", "必要な物をリストアップして。", "0", "0", "把需要的东西列在清单上吧。", "0", "cv_kinkura_38", "0", "0"},
[4200000138] = {4200000138, 12000001, 41, 33, "0", "0", "多瑙的領航，身體是你的本錢，不可忽視呀。", "身体が一番大事よ。気を付けてね。", "0", "0", "多瑙的领航，身体是你的本钱，不可忽视呀。", "0", "cv_kinkura_39", "0", "0"},
[4200000139] = {4200000139, 12000001, 42, 34, "0", "0", "將環境調整成最舒適的狀況吧。", "一番心地いい环境に整えて。", "0", "0", "将环境调整成最舒适的状况吧。", "0", "cv_kinkura_40", "0", "0"},
[4200000140] = {4200000140, 12000001, 43, 35, "0", "0", "先確認有沒有商業合作吧！", "先に商业关系のものが入ってるか确认して！", "0", "0", "先确认有没有商业合作吧！", "0", "cv_kinkura_41", "0", "0"},
[4200000141] = {4200000141, 12000001, 44, 36, "0", "0", "說不定你能成為優秀的情報商。", "あんた、もしかしたら优秀な情报商人になれるかもしれないわね。", "0", "0", "说不定你能成为优秀的情报商。", "0", "cv_kinkura_42", "0", "0"},
[4200000142] = {4200000142, 12000001, 45, 37, "0", "0", "確認完可要記得行動喔。", "确认し终わったら、ちゃんと行动に移してね。", "0", "0", "确认完可要记得行动哦。", "0", "cv_kinkura_43", "0", "0"},
[4201900200] = {4201900200, 12019002, 1, 1, "0", "0", "蒼霧殘響。", "0", "0", "0", "0", "0", "cv_kaitelin_1", "0", "0"},
[4201900201] = {4201900201, 12019002, 2, 2, "0", "0", "接下來的任務是駐守這裡？", "0", "0", "0", "0", "0", "cv_kaitelin_2", "0", "0"},
[4201900202] = {4201900202, 12019002, 3, 3, "0", "0", "黑荊棘編號ODY763001，你也可以叫我的名字——凱特琳。", "0", "0", "0", "0", "0", "cv_kaitelin_3", "0", "0"},
[4201900203] = {4201900203, 12019002, 91, 4, "0", "idle", "恕我直言，這裡的安防措施在我看來漏洞百出。", "0", "0", "0", "0", "0", "cv_kaitelin_4", "0", "idle,idle"},
[4201900204] = {4201900204, 12019002, 94, 4, "0", "idle2", "我不太理解領航你的想法，佔用我一個駕駛員的戰鬥力僅僅是在這裡站崗？", "0", "0", "0", "0", "0", "cv_kaitelin_5", "0", "idle2,idle2"},
[4201900205] = {4201900205, 12019002, 98, 4, "0", "idle3", "管理一個小隊並不輕鬆，特別是當你的隊員都是擁有強烈個人色彩的傢伙的時候。不過所幸我在當員警時看守過不少這樣的人。", "0", "0", "0", "0", "0", "cv_kaitelin_6", "0", "idle3,idle3"},
[4201900206] = {4201900206, 12019002, 92, 5, "15_1_0_0.8", "touch1", "我只是想守護我想守護的東西，作為特警的我失敗了，但是作為駕駛員的我一定會成功。你會幫我？那一言為定……怎麼，你以為我是那種自負的笨蛋嗎？", "0", "0", "0", "0", "0", "cv_kaitelin_7", "0", "touch1,touch1"},
[4201900207] = {4201900207, 12019002, 95, 5, "15_1_0_0.8", "touch2", "哼，這次只是警告。", "0", "0", "0", "0", "0", "cv_kaitelin_8", "0", "touch2,touch2"},
[4201900208] = {4201900208, 12019002, 106, 5, "15_1_0_0.8", "touch3", "碰我可以但不能碰我的槍。", "0", "0", "0", "0", "0", "cv_kaitelin_9", "0", "touch3,touch3"},
[4201900209] = {4201900209, 12019002, 96, 5, "15_2_0_0.8", "switch_1", "聽說領航你也懂一點射擊？只用過手槍嗎……那你想要試試狙擊槍嗎？我們可以先從後坐力最小的練起。", "0", "0", "0", "0", "0", "cv_kaitelin_10", "0", "switch_1,switch_1"},
[4201900210] = {4201900210, 12019002, 93, 5, "15_2_0_0.8", "switch_2", "領航上次戰鬥你使用的那套戰術效果非凡，我有幾個戰鬥上的想法想與你探討探討。要不我們去你的住處吧，免得閒人打擾，或者到我的住處也行。", "0", "0", "0", "0", "0", "cv_kaitelin_11", "0", "switch_2,switch_2"},
[4201900211] = {4201900211, 12019002, 102, 5, "15_2_0_0.8", "switch_3", "領航上次戰鬥你使用的那套戰術效果非凡，我有幾個戰鬥上的想法想與你探討探討。要不我們去你的住處吧，免得閒人打擾，或者到我的住處也行。", "0", "0", "0", "0", "0", "cv_kaitelin_11", "0", "switch_3,switch_3"},
