[4201500102] = {4201500102, 12015001, 3, 3, "0", "0", "原來如此，您就是父親說的那位傳奇領航嗎？我的名字是薇絲帕爾，很高興能夠見到您。", "0", "0", "0", "原來如此，您就是父親說的那位傳奇領航嗎？我的名字是薇絲帕爾，很高興能夠見到您。", "0", "cv_vicepearl_1", "0", "0"},
[4201500103] = {4201500103, 12015001, 4, 4, "0", "idle", "父親雖然貴為支部長，但其實方舟才是多瑙地區的象徵，我們家族能有今天的地位還是拜艾吉斯所賜。", "0", "0", "0", "父親雖然貴為支部長，但其實方舟才是多瑙地區的象徵，我們家族能有今天的地位還是拜艾吉斯所賜。", "0", "cv_vicepearl_3", "0", "0"},
[4201500104] = {4201500104, 12015001, 5, 4, "0", "idle", "還請不要把我當做是多瑙的公主什麼的，如您所見，我現在只是一名親衛隊隊員。", "0", "0", "0", "還請不要把我當做是多瑙的公主什麼的，如您所見，我現在只是一名親衛隊隊員。", "0", "cv_vicepearl_4", "0", "0"},
