[4201100203] = {4201100203, 12011002, 4, 4, "0", "idle", "“巴厘斯先生在死前十五分鐘還活著。”呵，真有意思。", "0", "0", "0", "0", "0", "cv_garannken_3", "0", "0"},
[4201100204] = {4201100204, 12011002, 5, 4, "0", "idle", "呼…已經這個時間了嗎？差不多該休息了呢…不行嗎？", "0", "0", "0", "0", "0", "cv_garannken_4", "0", "0"},
[4201100205] = {4201100205, 12011002, 6, 4, "0", "idle", "我並不討厭海姬她們…我從她們身上，感受到一種從未有過的親切感。", "0", "0", "0", "0", "0", "cv_garannken_31", "0", "0"},
[4201100206] = {4201100206, 12011002, 7, 5, "1_》_0_0.8", "touch1", "曾經，有一位鋼琴師與這個世界擦肩而過…我不想，所以我才下了船。", "0", "0", "0", "0", "0", "cv_garannken_32", "0", "0"},
[4201100207] = {4201100207, 12011002, 8, 5, "1_》_0_0.8", "touch1", "嗯？", "0", "0", "0", "0", "0", "cv_garannken_5", "0", "0"},
[4201100208] = {4201100208, 12011002, 9, 5, "1_》_0_0.8", "touch2", "請不要打擾我…是領航啊，有什麼事嗎？", "0", "0", "0", "0", "0", "cv_garannken_6", "0", "0"},
[4201100209] = {4201100209, 12011002, 10, 5, "1_》_0_0.8", "touch2", "早安，領航…現在已經不算是早上了嗎……沒關係，那只不過是問候的形式而已，對你我而言，能明白對方的心意就已經足夠了。", "0", "0", "0", "0", "0", "cv_garannken_7", "0", "0"},
[4201100210] = {4201100210, 12011002, 11, 5, "1_》_0_0.8", "touch2", "我們行走在行徑分叉的花園裏，偶然的機會使我們於此相遇。領航，我能與您像現在這樣對話，已經足夠幸福了。", "0", "0", "0", "0", "0", "cv_garannken_8", "0", "0"},
[4201100211] = {4201100211, 12011002, 12, 6, "0", "0", "啊…謝謝。", "0", "0", "0", "0", "0", "cv_garannken_9", "0", "0"},
[4201100212] = {4201100212, 12011002, 13, 7, "0", "0", "嗯…和之前比起來，稍微有些改變了吧。", "0", "0", "0", "0", "0", "cv_garannken_10", "0", "0"},
[4201100213] = {4201100213, 12011002, 14, 8, "0", "0", "這就是…“覺醒”…和我在資料庫裏看到的一樣。嗯，這樣一來，我就多多少少接近領航您了吧。成為一個像您一樣，能幫助別人，引領大家前進的人。", "0", "0", "0", "0", "0", "cv_garannken_11", "0", "0"},
[4201100214] = {4201100214, 12011002, 15, 9, "0", "0", "小白，我們變強了呢。", "0", "0", "0", "0", "0", "cv_garannken_12", "0", "0"},
