[4104600101] = {4104600101, 11046001, 2, 2, "0", "0", "能待在老師身邊就好~", "0", "0", "0", "0", "0", "cv_peipeita_2", "0", "0"},
[4104600102] = {4104600102, 11046001, 3, 3, "0", "0", "歧花小隊所屬，佩佩塔前來報到！終於又見到老師您了，雖然是以問題學生的身份……但我會加倍努力的！", "0", "0", "0", "0", "0", "cv_peipeita_3", "0", "0"},
[4104600103] = {4104600103, 11046001, 91, 4, "0", "idle", "這就是正式駕駛員每天都會看見的風景啊，比學校裏見到的更加廣闊，也更讓人期待不已。", "0", "0", "0", "0", "0", "cv_peipeita_4", "0", "idle,idle"},
[4104600104] = {4104600104, 11046001, 94, 4, "0", "idle2", "老師？工作辛苦所以困了的話，可以在我身上休息哦，躺在胸口上會更柔軟、暖和，就是……如果心跳聲太吵的話，還請包涵。", "0", "0", "0", "0", "0", "cv_peipeita_5", "0", "idle2,idle2"},
[4104600105] = {4104600105, 11046001, 98, 4, "0", "idle3", "明明想作為優等生來見老師，卻事與願違加入了問題學生小隊呢。而且，這支隊伍中對老師虎視眈眈的人也不少，請當心點哦。", "0", "0", "0", "0", "0", "cv_peipeita_6", "0", "idle3,idle3"},
[4104600106] = {4104600106, 11046001, 92, 5, "1_》_0_0.8", "level1", "用、用摸頭來鼓勵學生嗎？那我就把腦袋再低一點好了，這樣老師摸起來也會更方便~", "0", "0", "0", "0", "0", "cv_peipeita_7", "0", "level1,level1"},
[4104600107] = {4104600107, 11046001, 95, 5, "1_》_0_0.8", "level2", "因為很在意，就收集了不少關於老師的資料，那個……老師真的和很多駕駛員都有超常的關係嗎？還是說只是謠言呢？", "0", "0", "0", "0", "0", "cv_peipeita_8", "0", "level2,level2"},
[4104600108] = {4104600108, 11046001, 106, 5, "1_》_0_0.8", "level3", "這個武器因為很重所以用起來很吃力，不過我是特意選擇它的，因為如果連這點困難都克服不了，怎麼能成為老師的駕駛員呢~", "0", "0", "0", "0", "0", "cv_peipeita_9", "0", "level3,level3"},
[4104600109] = {4104600109, 11046001, 106, 5, "1_》_0_0.8", "level4", "已經和老師相處一段時間了，我想聽聽您對我的評價……在您看來，我是一名好學生嗎？沒有輸給雛鷹小隊那些傢伙嗎？嗯……嗯……感謝老師！", "0", "0", "0", "0", "0", "cv_peipeita_10", "0", "level4,level4"},
[4104600110] = {4104600110, 11046001, 93, 5, "1_》_0_0.8", "switch1", "我曾被批評，身為學生不要老想著大人世界的感情……但現在我已經是名出色的駕駛員了吧？如果得到您的認可，我對您的憧憬更激進大膽些也可以了吧？", "0", "0", "0", "0", "0", "cv_peipeita_11", "0", "switch1,switch1"},
[4104600111] = {4104600111, 11046001, 102, 5, "1_》_0_0.8", "switch2", "什麼？", "0", "0", "0", "0", "0", "cv_peipeita_30", "0", "switch2,switch2"},
[4104600112] = {4104600112, 11046001, 96, 5, "1_》_0_0.8", "switch3", "雖然還是學生，但我的身體已經很成熟了對吧~", "0", "0", "0", "0", "0", "cv_peipeita_28", "0", "switch3,switch3"},
