[4003900100] = {4003900100, 10039001, 1, 1, "0", "0", "蒼霧殘響！", "0", "0", "0", "0", "0", "cv_harriet_1", "0", "0"},
[4003900101] = {4003900101, 10039001, 2, 2, "0", "0", "對手在哪里？……什麼！你說這裏不是擂臺？", "0", "0", "0", "0", "0", "cv_harriet_2", "0", "0"},
