[4003900104] = {4003900104, 10039001, 94, 4, "0", "idle2", "異獸！……原來只是個飛艇啊，唉……", "0", "0", "0", "0", "0", "cv_harriet_5", "0", "idle2,idle2"},
[4003900105] = {4003900105, 10039001, 98, 4, "0", "idle3", "這裏的駕駛員不是玩槍就是玩鞭子的，想找個懂拳的對手真難啊。", "0", "0", "0", "0", "0", "cv_harriet_6", "0", "idle3,idle3"},
[4003900106] = {4003900106, 10039001, 93, 5, "1_》_0_0.8", "switch1", "衝動是拳擊手唯一的敵人，越是頭腦發昏的時候就越是要讓自己冷靜下來。冷靜、觀察、計算，最後打出制勝的那一拳。不過對於領航來說應該不用再強調這些了。", "0", "0", "0", "0", "0", "cv_harriet_7", "0", "switch1,switch1"},
[4003900107] = {4003900107, 10039001, 102, 5, "1_》_0_0.8", "switch2", "給你一拳。", "0", "0", "0", "0", "0", "cv_harriet_8", "0", "switch2,switch2"},
[4003900108] = {4003900108, 10039001, 96, 5, "1_》_0_0.8", "switch3", "別光癡迷別人的身體，領航你自己也要勤加鍛煉。", "0", "0", "0", "0", "0", "cv_harriet_9", "0", "switch3,switch3"},
[4003900109] = {4003900109, 10039001, 92, 5, "1_》_0_0.8", "touch1", "肩膀有些酸痛，難道是胸前的兩團又重了嗎……看來下次練拳的時候得要請領航幫忙托著了。", "0", "0", "0", "0", "0", "cv_harriet_10", "0", "touch1,touch1"},
[4003900110] = {4003900110, 10039001, 95, 5, "1_》_0_0.8", "touch2", "以前練拳的時候腦子裏想的都是些拳賽的對手做假想敵。然而最近我滿腦子出現的都是領航，這還讓我怎麼練習……我，沒法對領航出拳啊！——", "0", "0", "0", "0", "0", "cv_harriet_11", "0", "touch2,touch2"},
[4003900111] = {4003900111, 10039001, 106, 5, "1_》_0_0.8", "touch3", "這裏就是我想要的訓練場。", "0", "0", "0", "0", "0", "cv_harriet_36", "0", "touch3,touch3"},
