[4103600200] = {4103600200, 11036002, 1, 1, "0", "0", "蒼霧殘響", "0", "0", "0", "0", "0", "cv_puruixiou_1", "0", "0"},
[4103600201] = {4103600201, 11036002, 2, 2, "0", "0", "真的？終於能更加近距離地觀察你了呢。", "0", "0", "0", "0", "0", "cv_puruixiou_2", "0", "0"},
[4103600202] = {4103600202, 11036002, 3, 3, "0", "0", "經過計算，你和我相遇的概率是……100%！嘿嘿，開個玩笑。這裡是普瑞席歐，薩哈拉的異獸學者哦~", "0", "0", "0", "0", "0", "cv_puruixiou_3", "0", "0"},
[4103600203] = {4103600203, 11036002, 91, 4, "1_》_0_0.8", "idle", "雖說能在這裡觀察你已經很不錯了，但科研的推進過程果然無比漫長，我真想快進到下一個階段，比如說……直接上手開始研究！", "0", "0", "0", "0", "0", "cv_puruixiou_4", "0", "idle,idle"},
[4103600204] = {4103600204, 11036002, 94, 5, "1_》_0_0.8", "idle2", "當你凝視著我，我也正凝視著你哦。對於研究目標，不僅是接觸交流，單純地觀察也很必要。", "0", "0", "0", "0", "0", "cv_puruixiou_5", "0", "idle2,idle2"},
[4103600205] = {4103600205, 11036002, 98, 5, "1_》_0_0.8", "idle3", "梅貝爾的席位，斯緹菈的精准，墨君的學識，都對制蜜人不可或缺。不過維繫這支小隊的，也絕不僅僅是工作上的便利呢。", "0", "0", "0", "0", "0", "cv_puruixiou_6", "0", "idle3,idle3"},
[4103600206] = {4103600206, 11036002, 92, 5, "1_》_0_0.8", "level1", "是否萬物皆可測量與計算，連思維也能用數理邏輯加以分析？“七賢”各有答案，而領航你又如何認為呢？對此，我相當感興趣。", "0", "0", "0", "0", "0", "cv_puruixiou_7", "0", "level1,level1"},
[4103600207] = {4103600207, 11036002, 95, 5, "1_》_0_0.8", "level2", "這些“蜂群”？請放心，它們會乖乖遵守我的指令，就像物理學家的儀器、數學家的公式，以及女王的僕從一樣聽話。", "0", "0", "0", "0", "0", "cv_puruixiou_8", "0", "level2,level2"},
[4103600208] = {4103600208, 11036002, 106, 5, "1_》_0_0.8", "level3", "要不要來我的實驗室幫忙做點研究？那些資料與儀器是很貴重沒錯，但是你的話，我可以放心。", "0", "0", "0", "0", "0", "cv_puruixiou_9", "0", "level3,level3"},
[4103600209] = {4103600209, 11036002, 106, 5, "1_》_0_0.8", "level4", "對哪位元駕駛員的身體資料感興趣嗎？我可以將採集方法告訴你哦。欸？想知道我的？唔……那就要看你有沒有本事拿到了呢~", "0", "0", "0", "0", "0", "cv_puruixiou_10", "0", "level4,level4"},
[4103600210] = {4103600210, 11036002, 93, 5, "1_》_0_0.8", "switch1", "最初只是對你的身體感興趣，漸漸的，你人格的構成、情感的運作、思維的奧秘，也開始讓我興致盎然了——這麼難的課題，我已久未遇見過。", "0", "0", "0", "0", "0", "cv_puruixiou_11", "0", "switch1,switch1"},
[4103600211] = {4103600211, 11036002, 96, 5, "1_》_0_0.8", "switch2", "最初只是對你的身體感興趣，漸漸的，你人格的構成、情感的運作、思維的奧秘，也開始讓我興致盎然了——這麼難的課題，我已久未遇見過。", "0", "0", "0", "0", "0", "cv_puruixiou_11", "0", "switch2,switch2"},
[4103600212] = {4103600212, 11036002, 102, 5, "1_》_0_0.8", "switch3", "最初只是對你的身體感興趣，漸漸的，你人格的構成、情感的運作、思維的奧秘，也開始讓我興致盎然了——這麼難的課題，我已久未遇見過。", "0", "0", "0", "0", "0", "cv_puruixiou_11", "0", "switch3,switch3"},
[4103600213] = {4103600213, 11036002, 96, 5, "1_》_0_0.8", "switch4", "最初只是對你的身體感興趣，漸漸的，你人格的構成、情感的運作、思維的奧秘，也開始讓我興致盎然了——這麼難的課題，我已久未遇見過。", "0", "0", "0", "0", "0", "cv_puruixiou_11", "0", "switch4,switch4"},
[4103600214] = {4103600214, 11036002, 12, 6, "0", "0", "成長，就是逐漸減少可能性的過程。", "0", "0", "0", "0", "0", "cv_puruixiou_12", "0", "0"},
[4103600215] = {4103600215, 11036002, 13, 7, "0", "0", "量變引起質變呢。", "0", "0", "0", "0", "0", "cv_puruixiou_13", "0", "0"},
[4103600216] = {4103600216, 11036002, 14, 8, "0", "0", "我會將自己這一成果，署上你的名字，而除此以外的致謝，領航也敬請期待哦。", "0", "0", "0", "0", "0", "cv_puruixiou_14", "0", "0"},
[4103600217] = {4103600217, 11036002, 15, 9, "0", "0", "“蜂群”在嗡鳴。", "0", "0", "0", "0", "0", "cv_puruixiou_15", "0", "0"},
[4103600218] = {4103600218, 11036002, 16, 10, "0", "0", "資料猶如花粉，正待我們採集。", "0", "0", "0", "0", "0", "cv_puruixiou_16", "0", "0"},
