[4103600220] = {4103600220, 11036002, 18, 12, "0", "0", "不好也不壞，就像多數時候的實驗一樣。", "0", "0", "0", "0", "0", "cv_puruixiou_18", "0", "0"},
[4103600221] = {4103600221, 11036002, 19, 13, "0", "0", "與其在這裡氣餒，不如趕緊回去調整一番。", "0", "0", "0", "0", "0", "cv_puruixiou_19", "0", "0"},
[4103600222] = {4103600222, 11036002, 20, 14, "0", "0", "失敗的資料，與成功同樣珍貴。", "0", "0", "0", "0", "0", "cv_puruixiou_20", "0", "0"},
