[4103600226] = {4103600226, 11036002, 25, 18, "0", "0", "“蜂群”集結，急襲目標！", "0", "0", "0", "0", "0", "cv_puruixiou_24", "0", "0"},
[4103600227] = {4103600227, 11036002, 26, 19, "0", "0", "哎呀，這次失算了。", "0", "0", "0", "0", "0", "cv_puruixiou_26", "0", "0"},
[4103600228] = {4103600228, 11036002, 27, 20, "0", "0", "我們在此相遇的概率是100%，這是根據直覺，而非計算得出的。", "0", "0", "0", "0", "0", "cv_puruixiou_27", "0", "0"},
[4103600229] = {4103600229, 11036002, 28, 21, "0", "0", "你是以科研人員的冷峻目光在審視著我，還是帶著其他某種意圖呢？", "0", "0", "0", "0", "0", "cv_puruixiou_28", "0", "0"},
[4103600230] = {4103600230, 11036002, 29, 21, "0", "0", "這麼毫無意義的時光，就讓它快點結束吧。", "0", "0", "0", "0", "0", "cv_puruixiou_29", "0", "0"},
[4103600231] = {4103600231, 11036002, 30, 22, "0", "0", "要發生什麼了？", "0", "0", "0", "0", "0", "cv_puruixiou_30", "0", "0"},
[4103600232] = {4103600232, 11036002, 31, 23, "0", "0", "有趣的環節呢。", "0", "0", "0", "0", "0", "cv_puruixiou_31", "0", "0"},
[4103600233] = {4103600233, 11036002, 32, 24, "0", "0", "蜜蜂憑嗅覺辨人，領航你又是憑藉什麼呢？", "0", "0", "0", "0", "0", "cv_puruixiou_32", "0", "0"},
[4103600234] = {4103600234, 11036002, 33, 25, "0", "0", "針對你的錯誤，我真想寫篇論文。", "0", "0", "0", "0", "0", "cv_puruixiou_33", "0", "0"},
[4103600235] = {4103600235, 11036002, 34, 26, "0", "0", "你好呀，今天狀態如何？身體是否疲憊，注意力夠不夠集中，早上醒來時的生理反應還正常嗎？", "0", "0", "0", "0", "0", "cv_puruixiou_34", "0", "0"},
[4103600236] = {4103600236, 11036002, 35, 27, "0", "0", "快快出發吧。", "0", "0", "0", "0", "0", "cv_puruixiou_35", "0", "0"},
[4103600237] = {4103600237, 11036002, 36, 28, "0", "0", "這裡能更安全地採集資料。", "0", "0", "0", "0", "0", "cv_puruixiou_36", "0", "0"},
[4103600238] = {4103600238, 11036002, 37, 29, "0", "0", "我能研究研究她們嗎？", "0", "0", "0", "0", "0", "cv_puruixiou_37", "0", "0"},
[4103600239] = {4103600239, 11036002, 38, 30, "0", "0", "新的研究者，抑或小白鼠？", "0", "0", "0", "0", "0", "cv_puruixiou_38", "0", "0"},
[4103600240] = {4103600240, 11036002, 39, 31, "0", "0", "裝備永遠不嫌多。", "0", "0", "0", "0", "0", "cv_puruixiou_39", "0", "0"},
[4103600241] = {4103600241, 11036002, 40, 32, "0", "0", "採購時間到。", "0", "0", "0", "0", "0", "cv_puruixiou_40", "0", "0"},
[4103600242] = {4103600242, 11036002, 41, 33, "0", "0", "都是些流於表面的資訊啊。", "0", "0", "0", "0", "0", "cv_puruixiou_41", "0", "0"},
[4103600243] = {4103600243, 11036002, 42, 34, "0", "0", "設置就交給你了。", "0", "0", "0", "0", "0", "cv_puruixiou_42", "0", "0"},
[4103600244] = {4103600244, 11036002, 43, 35, "0", "0", "你的郵箱裡怎麼全是女孩子寫的信？", "0", "0", "0", "0", "0", "cv_puruixiou_43", "0", "0"},
[4103600245] = {4103600245, 11036002, 44, 36, "0", "0", "少說，多做。", "0", "0", "0", "0", "0", "cv_puruixiou_44", "0", "0"},
[4103600246] = {4103600246, 11036002, 45, 37, "0", "0", "你去哪？", "0", "0", "0", "0", "0", "cv_puruixiou_45", "0", "0"},
[415500] = {415500, 11055, 1, 1, "0", "0", "蒼霧殘響。", "0", "0", "0", "0", "0", "cv_red_01", "0", "0"},
[415501] = {415501, 11055, 2, 2, "0", "0", "我站在這裏不會引起大家恐慌吧？如果會，那我只能深表遺憾，那些人根本就沒有欣賞我的美的眼睛。", "0", "0", "0", "0", "0", "cv_red_02", "0", "0"},
[415502] = {415502, 11055, 3, 3, "0", "0", "鏘鏘——史上最偉大的人造原罪登場。", "0", "0", "0", "0", "0", "cv_red_03", "0", "0"},
[415503] = {415503, 11055, 4, 4, "0", "idle", "我一直是忠於艾吉斯、忠於人類的好原罪啊，出生只能決定我的種族，但是否定不了我熠熠生輝的心，如果原罪有心的話。", "0", "0", "0", "0", "0", "cv_red_04", "0", "0"},
[415504] = {415504, 11055, 5, 4, "0", "idle2", "如果人類被原罪擊敗了怎麼辦？還能怎麼辦，我從出生開始就是原罪了。我一直都是原罪的夥伴啊。", "0", "0", "0", "0", "0", "cv_red_05", "0", "0"},
[415505] = {415505, 11055, 6, 4, "0", "idle3", "沒事的領航，在人類這裏你罩著我，在原罪那邊我罩著你，我用紅博士的生命做保障。", "0", "0", "0", "0", "0", "cv_red_06", "0", "0"},
[415506] = {415506, 11055, 7, 5, "1_》_0_0.8", "touch", "憂傷在我的內心蔓延。", "0", "0", "0", "0", "0", "cv_red_07", "0", "0"},
[415507] = {415507, 11055, 8, 5, "1_》_0_0.8", "touch2", "感覺像是心被掏空了一樣，哦，我沒有心。", "0", "0", "0", "0", "0", "cv_red_08", "0", "0"},
[415508] = {415508, 11055, 9, 5, "1_》_100_1.5", "touch3", "希望你能滿足我。", "0", "0", "0", "0", "0", "cv_red_09", "0", "0"},
[415509] = {415509, 11055, 10, 5, "1_》_500_2", "touch4", "我需不需要充電？不用哦，我是高性能的。順便說一下，在我看來這是性騷擾話題。", "0", "0", "0", "0", "0", "cv_red_10", "0", "0"},
[415510] = {415510, 11055, 11, 5, "1_》_1000_2.5", "touch5", "你介意增加一點額外的玩法嗎？我可以加裝很多你沒體驗過的設備……對，沒錯，我就是在性騷擾你。怎麼？有本事把我辦了。", "0", "0", "0", "0", "0", "cv_red_11", "0", "0"},
[415511] = {415511, 11055, 12, 6, "0", "0", "不錯的改造，但希望能把我改裝得性感一點。", "0", "0", "0", "0", "0", "cv_red_12", "0", "0"},
[415512] = {415512, 11055, 13, 7, "0", "0", "品味很好，但希望下一次選擇改造方向的時候和我一起商量。", "0", "0", "0", "0", "0", "cv_red_13", "0", "0"},
[415513] = {415513, 11055, 14, 8, "0", "0", "駕駛員員們對你的喜歡還殘留在我的記憶裏，現在恢復理智的我認為這是垃圾檔，但是人類就是帶著這堆垃圾檔前進的，很奇怪。", "0", "0", "0", "0", "0", "cv_red_14", "0", "0"},
[415514] = {415514, 11055, 15, 9, "0", "0", "蕪——", "0", "0", "0", "0", "0", "cv_red_15", "0", "0"},
[415515] = {415515, 11055, 16, 10, "0", "0", "自己人不打自己人。", "0", "0", "0", "0", "0", "cv_red_16", "0", "0"},
[415516] = {415516, 11055, 17, 11, "0", "0", "red醬的MVP精彩回放呢？", "0", "0", "0", "0", "0", "cv_red_17", "0", "0"},
[415517] = {415517, 11055, 18, 12, "0", "0", "一般。", "0", "0", "0", "0", "0", "cv_red_18", "0", "0"},
[415518] = {415518, 11055, 19, 13, "0", "0", "慘勝也是勝，贏了一次就是贏了一輩子。", "0", "0", "0", "0", "0", "cv_red_19", "0", "0"},
[415519] = {415519, 11055, 20, 14, "0", "0", "敢得罪我，你完蛋了。", "0", "0", "0", "0", "0", "cv_red_20", "0", "0"},
[415520] = {415520, 11055, 21, 15, "0", "0", "誰跟你自己人。", "0", "0", "0", "0", "0", "cv_red_21", "0", "0"},
[415521] = {415521, 11055, 23, 16, "0", "0", "打的就是原罪，不是也沒關係。", "0", "0", "0", "0", "0", "cv_red_22", "0", "0"},
[415522] = {415522, 11055, 24, 17, "0", "0", "打了。", "0", "0", "0", "0", "0", "cv_red_23", "0", "0"},
[415523] = {415523, 11055, 25, 18, "0", "0", "數值（能量）給到位，一切都好說。", "0", "0", "0", "0", "0", "cv_red_24", "0", "0"},
[415524] = {415524, 11055, 26, 19, "0", "0", "？", "0", "0", "0", "0", "0", "cv_red_26", "0", "0"},
[415525] = {415525, 11055, 27, 20, "0", "0", "搞不懂，我這種完美生命體為什麼要洗澡。", "0", "0", "0", "0", "0", "cv_red_27", "0", "0"},
[415526] = {415526, 11055, 28, 21, "0", "0", "我懂了，我是完美的，但是環境是不完美的，所以會污染我。", "0", "0", "0", "0", "0", "cv_red_28", "0", "0"},
[415527] = {415527, 11055, 29, 21, "0", "0", "你對紅博士小時候的樣子起興致了嗎？", "0", "0", "0", "0", "0", "cv_red_29", "0", "0"},
[415528] = {415528, 11055, 30, 22, "0", "0", "您進入了隱藏區域，能借此一睹完美生物的身軀。", "0", "0", "0", "0", "0", "cv_red_30", "0", "0"},
[415529] = {415529, 11055, 31, 23, "0", "0", "……所以說紅博士把我的外貌定成她小時候的樣子就是純粹的自戀。", "0", "0", "0", "0", "0", "cv_red_31", "0", "0"},
[415530] = {415530, 11055, 32, 24, "0", "0", "我的設定裏本來就對你好感度是爆滿，好感度還能升高？", "0", "0", "0", "0", "0", "cv_red_32", "0", "0"},
[415531] = {415531, 11055, 33, 25, "0", "0", "這都記不住，我要給你換個機械腦子。", "0", "0", "0", "0", "0", "cv_red_33", "0", "0"},
[415532] = {415532, 11055, 34, 26, "0", "0", "前來覲見我了嗎，凡人。", "0", "0", "0", "0", "0", "cv_red_34", "0", "0"},
[415533] = {415533, 11055, 35, 27, "0", "0", "戰鬥吧，red。", "0", "0", "0", "0", "0", "cv_red_35", "0", "0"},
[415534] = {415534, 11055, 36, 28, "0", "0", "要戰鬥的地方未免也太多了。", "0", "0", "0", "0", "0", "cv_red_36", "0", "0"},
[415535] = {415535, 11055, 37, 29, "0", "0", "工口奴隸們。", "0", "0", "0", "0", "0", "cv_red_37", "0", "0"},
[415536] = {415536, 11055, 38, 30, "0", "0", "我們需要更多人口。", "0", "0", "0", "0", "0", "cv_red_38", "0", "0"},
[415537] = {415537, 11055, 39, 31, "0", "0", "我不是很需要。", "0", "0", "0", "0", "0", "cv_red_39", "0", "0"},
[415538] = {415538, 11055, 40, 32, "0", "0", "買點電腦配件。", "0", "0", "0", "0", "0", "cv_red_40", "0", "0"},
[415539] = {415539, 11055, 41, 33, "0", "0", "不如放我的頭像。", "0", "0", "0", "0", "0", "cv_red_41", "0", "0"},
[415540] = {415540, 11055, 42, 34, "0", "0", "設置就是為了用來突破的。", "0", "0", "0", "0", "0", "cv_red_42", "0", "0"},
[415541] = {415541, 11055, 43, 35, "0", "0", "幫你掃描轉到你的手機裏了。", "0", "0", "0", "0", "0", "cv_red_43", "0", "0"},
[415542] = {415542, 11055, 44, 36, "0", "0", "你的朋友好多，我投降了。", "0", "0", "0", "0", "0", "cv_red_44", "0", "0"},
[415543] = {415543, 11055, 45, 37, "0", "0", "我點。", "0", "0", "0", "0", "0", "cv_red_45", "0", "0"},
[415600] = {415600, 11056, 1, 1, "0", "0", "蒼霧殘響", "0", "0", "0", "0", "0", "cv_huizhang_01", "0", "0"},
[415601] = {415601, 11056, 2, 2, "0", "0", "看護的任務是吧，沒問題就交給我吧，就當支付房子的租金了。", "0", "0", "0", "0", "0", "cv_huizhang_02", "0", "0"},
[415602] = {415602, 11056, 3, 3, "0", "0", "啊……沒想到會發生這種事情，我們竟然來到了你的世界，那在我們解決問題之前，就拜託你收留我們一段時間吧。姑且再通報一下姓名，我是斯卡蒂的未來之一，叫我會長就好。", "0", "0", "0", "0", "0", "cv_huizhang_03", "0", "0"},
[415603] = {415603, 11056, 4, 4, "0", "idle", "文檔要我幫你一起處理嗎？沒關係的，我在學生會長時期要處理的文檔量大概是你這的十倍左右吧，我會很效率地看完和你溝通的。", "0", "0", "0", "0", "0", "cv_huizhang_04", "0", "0"},
[415604] = {415604, 11056, 5, 4, "0", "idle", "斯卡蒂……啊……哦，原來是在說影之國女王的事情……有那麼一瞬間我還以為是在叫我，真是的，在我面前還是不要提這個名字比較好。", "0", "0", "0", "0", "0", "cv_huizhang_05", "0", "0"},
[415605] = {415605, 11056, 6, 4, "0", "idle", "沒想到我最終還是來到了你的世界，所以你有什麼打算嗎……對我們。", "0", "0", "0", "0", "0", "cv_huizhang_06", "0", "0"},
[415606] = {415606, 11056, 7, 5, "1_》_0_0.8", "touch1", "既然來到了這裏……那總要留下我曾經來過的痕跡才對，短期的目標就定在征服世界吧。", "0", "0", "0", "0", "0", "cv_huizhang_07", "0", "0"},
[415607] = {415607, 11056, 8, 5, "1_》_0_0.8", "touch2", "果然，在與原罪廝殺過後我現在很確信，這裏就是我所期望的世界。", "0", "0", "0", "0", "0", "cv_huizhang_08", "0", "0"},
[415608] = {415608, 11056, 9, 5, "1_》_100_1.5", "touch3", "斯卡蒂？又要說影之國女王的事情嗎？這次是在叫我的名字？嗯，領航請你注意——我已經過了被人叫對名字就會很開心的年紀了。", "0", "0", "0", "0", "0", "cv_huizhang_09", "0", "0"},
[415609] = {415609, 11056, 10, 5, "1_》_500_2", "touch4", "捉弄我很有意思嗎？為什麼在每次獨處的時候都用“斯卡蒂”來稱呼我？因為覺得應該這麼稱呼？真是的，笨蛋一樣。", "0", "0", "0", "0", "0", "cv_huizhang_10", "0", "0"},
[415610] = {415610, 11056, 11, 5, "1_》_1000_2.5", "touch5", "唉，隨便你了，我就是斯卡蒂怎麼了？", "0", "0", "0", "0", "0", "cv_huizhang_11", "0", "0"},
[415611] = {415611, 11056, 12, 6, "0", "0", "這、這是像game一樣地得到了強化？", "0", "0", "0", "0", "0", "cv_huizhang_12", "0", "0"},
[415612] = {415612, 11056, 13, 7, "0", "0", "能感受到你的意志在左右著我的成長。", "0", "0", "0", "0", "0", "cv_huizhang_13", "0", "0"},
[415613] = {415613, 11056, 14, 8, "0", "0", "原來如此，我明白了你存在的意義了，怪不得被大家稱之為唯一的主人公。那麼，接下來的時間裏可別讓我失望啊，主人公。", "0", "0", "0", "0", "0", "cv_huizhang_14", "0", "0"},
[415614] = {415614, 11056, 15, 9, "0", "0", "規劃已完成，按照計畫進行吧。", "0", "0", "0", "0", "0", "cv_huizhang_15", "0", "0"},
[415615] = {415615, 11056, 16, 10, "0", "0", "由我來吧。", "0", "0", "0", "0", "0", "cv_huizhang_16", "0", "0"},
[415616] = {415616, 11056, 17, 11, "0", "0", "與我一同享受勝利吧，領航。", "0", "0", "0", "0", "0", "cv_huizhang_17", "0", "0"},
[415617] = {415617, 11056, 18, 12, "0", "0", "還挺有趣的嘛。", "0", "0", "0", "0", "0", "cv_huizhang_18", "0", "0"},
[415618] = {415618, 11056, 19, 13, "0", "0", "險勝呢，有趣。", "0", "0", "0", "0", "0", "cv_huizhang_19", "0", "0"},
[415619] = {415619, 11056, 20, 14, "0", "0", "哼，了不起，但是下一次就未必了。", "0", "0", "0", "0", "0", "cv_huizhang_20", "0", "0"},
[415620] = {415620, 11056, 21, 15, "0", "0", "得勝！", "0", "0", "0", "0", "0", "cv_huizhang_21", "0", "0"},
[415621] = {415621, 11056, 23, 16, "0", "0", "一！", "0", "0", "0", "0", "0", "cv_huizhang_23", "0", "0"},
[415622] = {415622, 11056, 24, 17, "0", "0", "二！", "0", "0", "0", "0", "0", "cv_huizhang_24", "0", "0"},
[415623] = {415623, 11056, 25, 18, "0", "0", "我乃躊躇不前者的未來一角。", "0", "0", "0", "0", "0", "cv_huizhang_25", "0", "0"},
[415624] = {415624, 11056, 26, 19, "0", "0", "重來一次，你死定了。", "0", "0", "0", "0", "0", "cv_huizhang_26", "0", "0"},
[415625] = {415625, 11056, 27, 20, "0", "0", "洗洗洗洗洗洗洗洗洗澡！？", "0", "0", "0", "0", "0", "cv_huizhang_27", "0", "0"},
[415626] = {415626, 11056, 28, 21, "0", "0", "太離譜了！我不能接受！有違禮儀！不檢點！太下流了！", "0", "0", "0", "0", "0", "cv_huizhang_28", "0", "0"},
[415627] = {415627, 11056, 29, 21, "0", "0", "死刑了啊死刑了，你這傢伙。", "0", "0", "0", "0", "0", "cv_huizhang_29", "0", "0"},
[415628] = {415628, 11056, 30, 22, "0", "0", "……難道斯卡蒂她也會和你做這種事情？", "0", "0", "0", "0", "0", "cv_huizhang_30", "0", "0"},
[415629] = {415629, 11056, 31, 23, "0", "0", "……給你個提示吧，我是斯卡蒂。", "0", "0", "0", "0", "0", "cv_huizhang_31", "0", "0"},
[415630] = {415630, 11056, 32, 24, "0", "0", "簡簡單單對吧……我在笑？笨、笨蛋，怎麼可能！", "0", "0", "0", "0", "0", "cv_huizhang_32", "0", "0"},
[415631] = {415631, 11056, 33, 25, "0", "0", "……看來接下來要讓你對我熟悉起來才行", "0", "0", "0", "0", "0", "cv_huizhang_33", "0", "0"},
[415632] = {415632, 11056, 34, 26, "0", "0", "來吧，和我一起尋找自由的方向吧。", "0", "0", "0", "0", "0", "cv_huizhang_34", "0", "0"},
[415633] = {415633, 11056, 35, 27, "0", "0", "好主意呢。", "0", "0", "0", "0", "0", "cv_huizhang_35", "0", "0"},
[415634] = {415634, 11056, 36, 28, "0", "0", "讓我稍微活動一下吧。", "0", "0", "0", "0", "0", "cv_huizhang_36", "0", "0"},
[415635] = {415635, 11056, 37, 29, "0", "0", "未成熟的女主角們。", "0", "0", "0", "0", "0", "cv_huizhang_37", "0", "0"},
[415636] = {415636, 11056, 38, 30, "0", "0", "願好運與您同行。", "0", "0", "0", "0", "0", "cv_huizhang_38", "0", "0"},
[415637] = {415637, 11056, 39, 31, "0", "0", "好酷……咳，我是說還不錯。", "0", "0", "0", "0", "0", "cv_huizhang_39", "0", "0"},
[415638] = {415638, 11056, 40, 32, "0", "0", "我有攢下來的私房錢，想要什麼？", "0", "0", "0", "0", "0", "cv_huizhang_40", "0", "0"},
[415639] = {415639, 11056, 41, 33, "0", "0", "主人公啊……我也是主人公。", "0", "0", "0", "0", "0", "cv_huizhang_41", "0", "0"},
[415640] = {415640, 11056, 42, 34, "0", "0", "改變世界的機關就在這裏。", "0", "0", "0", "0", "0", "cv_huizhang_42", "0", "0"},
[415641] = {415641, 11056, 43, 35, "0", "0", "星光彙聚於此。", "0", "0", "0", "0", "0", "cv_huizhang_43", "0", "0"},
[415642] = {415642, 11056, 44, 36, "0", "0", "你能聽見世界的聲音嗎？", "0", "0", "0", "0", "0", "cv_huizhang_44", "0", "0"},
[415643] = {415643, 11056, 45, 37, "0", "0", "yes——", "0", "0", "0", "0", "0", "cv_huizhang_45", "0", "0"},
[432600] = {432600, 13026, 1, 1, "0", "0", "蒼霧殘響", "0", "0", "0", "0", "0", "cv_buzhihuo_sw_01", "0", "0"},
[432601] = {432601, 13026, 2, 2, "0", "0", "哎呀……領航……一個人寂寞了嗎~沒關係，我來陪你了哦~", "0", "0", "0", "0", "0", "cv_buzhihuo_sw_02", "0", "0"},
[432602] = {432602, 13026, 3, 3, "0", "0", "不知火……特長是擅長照顧小孩子~呵呵我們又見面了，領航。", "0", "0", "0", "0", "0", "cv_buzhihuo_sw_03", "0", "0"},
[432603] = {432603, 13026, 4, 4, "0", "idle", "我一直在想……史蒂芬妮博士雖說會自稱為你的母親……但是……她真的配被稱作“媽媽”嗎~", "0", "0", "0", "0", "0", "cv_buzhihuo_sw_04", "0", "0"},
[432604] = {432604, 13026, 5, 4, "0", "idle2", "啊，夏天好熱啊~（偷瞄）陽光好刺眼~（偷瞄）要是有人能幫我撐傘就好了~（偷瞄） 咦？你幫我撐傘嗎？真是可靠呢，謝謝你啦~", "0", "0", "0", "0", "0", "cv_buzhihuo_sw_05", "0", "0"},
[432605] = {432605, 13026, 6, 4, "0", "idle3", "偶爾也想撒撒嬌呢……（偷瞄）", "0", "0", "0", "0", "0", "cv_buzhihuo_sw_06", "0", "0"},
[432606] = {432606, 13026, 6, 4, "0", "idle4", "偶爾也想撒撒嬌呢……（偷瞄）", "0", "0", "0", "0", "0", "cv_buzhihuo_sw_06", "0", "0"},
[432607] = {432607, 13026, 7, 5, "1_》_0_0.8", "level", "為什麼不自稱“姐姐”了？呵呵~秘密~如果你不介意，現在可以稱呼我為“媽媽”……對我來說領航就像小孩子一樣……需要引導。", "0", "0", "0", "0", "0", "cv_buzhihuo_sw_07", "0", "0"},
[432608] = {432608, 13026, 8, 5, "1_》_0_0.8", "level2", "我以為我們不會這麼快見面的……在我的預想中，我還要把整個女主角宇宙的女主角都變成小baby，在那之後掌握了宇宙才能見到你……", "0", "0", "0", "0", "0", "cv_buzhihuo_sw_08", "0", "0"},
[432609] = {432609, 13026, 9, 5, "1_》_100_1.5", "level3", "平時的時候會幹什麼？照顧小孩子吧，也就是那些女主角……我不放心她們，雖然大家都經歷了很多……但是……我毫不誇張地說，她們還沒長大……", "0", "0", "0", "0", "0", "cv_buzhihuo_sw_09", "0", "0"},
[432610] = {432610, 13026, 10, 5, "1_》_500_2", "level4", "媽媽會好好地負起責任來把領航變成廢人的。", "0", "0", "0", "0", "0", "cv_buzhihuo_sw_10", "0", "0"},
[432611] = {432611, 13026, 11, 5, "1_》_1000_2.5", "level5", "……“我一定會抵達完美的結局。”？啊……我是被你安慰了？感覺心裏暖暖的呢~謝謝你，領航就像太陽一樣呢……不過說實話，我一直，一直，直到現在都相信領航會做到的。", "0", "0", "0", "0", "0", "cv_buzhihuo_sw_11", "0", "0"},
[432612] = {432612, 13026, 11, 5, "1_》_1000_2.5", "level6", "……“我一定會抵達完美的結局。”？啊……我是被你安慰了？感覺心裏暖暖的呢~謝謝你，領航就像太陽一樣呢……不過說實話，我一直，一直，直到現在都相信領航會做到的。", "0", "0", "0", "0", "0", "cv_buzhihuo_sw_11", "0", "0"},
[432613] = {432613, 13026, 12, 6, "0", "0", "可不要勉強自己訓練哦~要張弛有度。", "0", "0", "0", "0", "0", "cv_buzhihuo_sw_12", "0", "0"},
[432614] = {432614, 13026, 13, 7, "0", "0", "真的做到了呢！媽媽為你感到驕傲！", "0", "0", "0", "0", "0", "cv_buzhihuo_sw_13", "0", "0"},
[432615] = {432615, 13026, 14, 8, "0", "0", "原來是這樣用的呀……沒有你教媽媽還真搞不懂呢，你已經很努力了，接下來就交給媽媽吧。", "0", "0", "0", "0", "0", "cv_buzhihuo_sw_14", "0", "0"},
[432616] = {432616, 13026, 15, 9, "0", "0", "比起上次進步了好多~", "0", "0", "0", "0", "0", "cv_buzhihuo_sw_15", "0", "0"},
[432617] = {432617, 13026, 16, 10, "0", "0", "戰鬥結束之後要注意休息哦~", "0", "0", "0", "0", "0", "cv_buzhihuo_sw_16", "0", "0"},
[432618] = {432618, 13026, 17, 11, "0", "0", "好啦，危險解除！我們回家吧？", "0", "0", "0", "0", "0", "cv_buzhihuo_sw_17", "0", "0"},
[432619] = {432619, 13026, 18, 12, "0", "0", "閉上眼睛，捂住耳朵……戰鬥很快就要結束了。", "0", "0", "0", "0", "0", "cv_buzhihuo_sw_18", "0", "0"},
[432620] = {432620, 13026, 19, 13, "0", "0", "我要……撕碎你們！", "0", "0", "0", "0", "0", "cv_buzhihuo_sw_19", "0", "0"},
[432621] = {432621, 13026, 20, 14, "0", "0", "看來不聽話的孩子有好多……我可以把它們變成嬰兒嗎？", "0", "0", "0", "0", "0", "cv_buzhihuo_sw_20", "0", "0"},
[432622] = {432622, 13026, 21, 15, "0", "0", "膽敢將惡意指向我的家人！", "0", "0", "0", "0", "0", "cv_buzhihuo_sw_21", "0", "0"},
[432623] = {432623, 13026, 23, 16, "0", "0", "退後！", "0", "0", "0", "0", "0", "cv_buzhihuo_sw_23", "0", "0"},
[432624] = {432624, 13026, 24, 17, "0", "0", "別想傷害領航！", "0", "0", "0", "0", "0", "cv_buzhihuo_sw_24", "0", "0"},
[432625] = {432625, 13026, 25, 18, "0", "0", "能和領航在一起，就是我最大的幸福了！", "0", "0", "0", "0", "0", "cv_buzhihuo_sw_25", "0", "0"},
[432626] = {432626, 13026, 26, 19, "0", "0", "不可原諒！！！", "0", "0", "0", "0", "0", "cv_buzhihuo_sw_26", "0", "0"},
[432627] = {432627, 13026, 27, 20, "0", "0", "呼——終於能泡個澡了……辛苦了一天，熱水最治癒了，領航要和媽媽一起洗嗎？", "0", "0", "0", "0", "0", "cv_buzhihuo_sw_27", "0", "0"},
[432628] = {432628, 13026, 28, 21, "0", "0", "啊……泡得有點暈乎乎的了……再泡一會兒就出去吧……", "0", "0", "0", "0", "0", "cv_buzhihuo_sw_28", "0", "0"},
[432629] = {432629, 13026, 29, 21, "0", "0", "能這樣安安穩穩地泡個澡……和領航一起……就是我嚮往的幸福呢。", "0", "0", "0", "0", "0", "cv_buzhihuo_sw_29", "0", "0"},
[432630] = {432630, 13026, 30, 22, "0", "0", "啊……有人來了。", "0", "0", "0", "0", "0", "cv_buzhihuo_sw_30", "0", "0"},
[432631] = {432631, 13026, 31, 23, "0", "0", "無論你做什麼，只要是你努力去做的，媽媽都為你驕傲！", "0", "0", "0", "0", "0", "cv_buzhihuo_sw_31", "0", "0"},
[432632] = {432632, 13026, 32, 24, "0", "0", "謝謝你來到我身邊，我愛你~", "0", "0", "0", "0", "0", "cv_buzhihuo_sw_32", "0", "0"},
[432633] = {432633, 13026, 33, 25, "0", "0", "…………………………", "0", "0", "0", "0", "0", "cv_buzhihuo_sw_33", "0", "0"},
[432634] = {432634, 13026, 34, 26, "0", "0", "今天也要和媽媽一起度過充實的一天哦~", "0", "0", "0", "0", "0", "cv_buzhihuo_sw_34", "0", "0"},
[432635] = {432635, 13026, 35, 27, "0", "0", "你們……吵到領航休息了。", "0", "0", "0", "0", "0", "cv_buzhihuo_sw_35", "0", "0"},
[432636] = {432636, 13026, 36, 28, "0", "0", "戰鬥開始前提前預習一遍吧。", "0", "0", "0", "0", "0", "cv_buzhihuo_sw_36", "0", "0"},
[432637] = {432637, 13026, 37, 29, "0", "0", "有不少問題兒童呢……讓我來照顧她們吧？", "0", "0", "0", "0", "0", "cv_buzhihuo_sw_37", "0", "0"},
[432638] = {432638, 13026, 38, 30, "0", "0", "我不介意家裏再多一點人哦？", "0", "0", "0", "0", "0", "cv_buzhihuo_sw_38", "0", "0"},
[432639] = {432639, 13026, 39, 31, "0", "0", "要做好保護措施。", "0", "0", "0", "0", "0", "cv_buzhihuo_sw_39", "0", "0"},
[432640] = {432640, 13026, 40, 32, "0", "0", "晚上準備吃什麼？", "0", "0", "0", "0", "0", "cv_buzhihuo_sw_40", "0", "0"},
[432641] = {432641, 13026, 41, 33, "0", "0", "雖然戰績累累……但總有點不放心呢。", "0", "0", "0", "0", "0", "cv_buzhihuo_sw_41", "0", "0"},
[432642] = {432642, 13026, 42, 34, "0", "0", "要打理好自己再出門。", "0", "0", "0", "0", "0", "cv_buzhihuo_sw_42", "0", "0"},
[432643] = {432643, 13026, 43, 35, "0", "0", "不要已讀不回哦。", "0", "0", "0", "0", "0", "cv_buzhihuo_sw_43", "0", "0"},
[432644] = {432644, 13026, 44, 36, "0", "0", "吃飯的時候不要看手機~", "0", "0", "0", "0", "0", "cv_buzhihuo_sw_44", "0", "0"},
[432645] = {432645, 13026, 45, 37, "0", "0", "嘿——!", "0", "0", "0", "0", "0", "cv_buzhihuo_sw_45", "0", "0"},
[440600] = {440600, 14006, 1, 1, "0", "0", "蒼霧殘響", "0", "0", "0", "0", "0", "cv_RED_SP_01", "0", "0"},
[440601] = {440601, 14006, 2, 2, "0", "0", "叫我這個完美人類兼勇者來擔任看護你的人嗎？也行吧，畢竟守護的是一位“神明”。不算浪費我的時間。", "0", "0", "0", "0", "0", "cv_RED_SP_02", "0", "0"},
[440602] = {440602, 14006, 3, 3, "0", "0", "你把我召喚出來了……是不是應該實現我的願望了？為什麼不是反過來？廢話……召喚了我之後我還要實現你的願望，什麼好事情都給你占了。", "0", "0", "0", "0", "0", "cv_RED_SP_03", "0", "0"},
[440603] = {440603, 14006, 4, 4, "0", "idle", "我是這個世界上最完美的人類，我的造物主給予了我世間的美好……你不這麼覺得嗎？紅博士只是把自戀遺傳給了我？有嗎？", "0", "0", "0", "0", "0", "cv_RED_SP_04", "0", "0"},
[440604] = {440604, 14006, 5, 4, "0", "idle1", "簡直該被供奉在神殿裏……我當然是在說我自己啊……不然呢？", "0", "0", "0", "0", "0", "cv_RED_SP_05", "0", "0"},
[440605] = {440605, 14006, 6, 4, "0", "idle2", "沒、沒看出來有什麼完美的地方！？不可能……尖酸刻薄，自私自利……這些不都是優點嗎？", "0", "0", "0", "0", "0", "cv_RED_SP_06", "0", "0"},
[440606] = {440606, 14006, 6, 4, "0", "idle3", "沒、沒看出來有什麼完美的地方！？不可能……尖酸刻薄，自私自利……這些不都是優點嗎？", "0", "0", "0", "0", "0", "cv_RED_SP_06", "0", "0"},
[440607] = {440607, 14006, 7, 5, "1_》_0_0.8", "level1", "為什麼我要穿成這樣……？因為我現在是想要征服世界的勇者。", "0", "0", "0", "0", "0", "cv_RED_SP_07", "0", "0"},
[440608] = {440608, 14006, 8, 5, "1_》_0_0.8", "level2", "鏡子鏡子告訴我，誰是這個世界上最強最美最可怕的女人？哈哈，要說最可怕的話當然是那位博士啦，這還用問。是邪惡的史蒂芬妮博士。", "0", "0", "0", "0", "0", "cv_RED_SP_08", "0", "0"},
[440609] = {440609, 14006, 9, 5, "1_》_100_1.5", "level3", "我的身體是為了帶領人類勝利而鑄就的，每一寸都寫滿著勝利。你想要看看嗎，那我準備開始脫衣服了。", "0", "0", "0", "0", "0", "cv_RED_SP_09", "0", "0"},
[440610] = {440610, 14006, 10, 5, "1_》_500_2", "level4", "有的人出生就是為了當這個世界的主人的，所以到時候誰勝利了我們就投靠誰，可千萬不能讓我吃苦。", "0", "0", "0", "0", "0", "cv_RED_SP_10", "0", "0"},
[440611] = {440611, 14006, 11, 5, "1_》_1000_2.5", "level5", "除了領航之外，我才不需要什麼同伴……", "0", "0", "0", "0", "0", "cv_RED_SP_11", "0", "0"},
[440612] = {440612, 14006, 12, 6, "0", "0", "因為我是高性能的人類，這種小事自然能辦到！", "0", "0", "0", "0", "0", "cv_RED_SP_12", "0", "0"},
[440613] = {440613, 14006, 13, 7, "0", "0", "呼～看這皮膚，優質，要摸摸嗎？放心，就是為了給你摸才準備的。", "0", "0", "0", "0", "0", "cv_RED_SP_13", "0", "0"},
[440614] = {440614, 14006, 14, 8, "0", "0", "哼，跟著身為勇者的我，你們就等著走向勝利吧！如果沒有勝利也沒關係，我可以帶著你們投降。", "0", "0", "0", "0", "0", "cv_RED_SP_14", "0", "0"},
[440615] = {440615, 14006, 15, 9, "0", "0", "一直升級胸部的話，能用胸部發射鐳射嗎？就像漫畫裏一樣。", "0", "0", "0", "0", "0", "cv_RED_SP_15", "0", "0"},
[440616] = {440616, 14006, 16, 10, "0", "0", "區區原罪也敢在完美人類面前倡狂？", "0", "0", "0", "0", "0", "cv_RED_SP_16", "0", "0"},
[440617] = {440617, 14006, 17, 11, "0", "0", "贏得太輕鬆了", "0", "0", "0", "0", "0", "cv_RED_SP_17", "0", "0"},
[440618] = {440618, 14006, 18, 12, "0", "0", "輕鬆拿下。", "0", "0", "0", "0", "0", "cv_RED_SP_18", "0", "0"},
[440619] = {440619, 14006, 19, 13, "0", "0", "今天狀態一般。", "0", "0", "0", "0", "0", "cv_RED_SP_19", "0", "0"},
[440620] = {440620, 14006, 20, 14, "0", "0", "有點無聊了，不玩了。", "0", "0", "0", "0", "0", "cv_RED_SP_20", "0", "0"},
[440621] = {440621, 14006, 21, 15, "0", "0", "死亡對你們來說算是一種解脫呢，NPC。", "0", "0", "0", "0", "0", "cv_RED_SP_21", "0", "0"},
[440622] = {440622, 14006, 23, 16, "0", "0", "擋路了。", "0", "0", "0", "0", "0", "cv_RED_SP_23", "0", "0"},
[440623] = {440623, 14006, 24, 17, "0", "0", "還敢對我動手？", "0", "0", "0", "0", "0", "cv_RED_SP_24", "0", "0"},
[440624] = {440624, 14006, 25, 18, "0", "0", "死在我的手裏……也算是一種榮幸了吧？", "0", "0", "0", "0", "0", "cv_RED_SP_25", "0", "0"},
[440625] = {440625, 14006, 26, 19, "0", "0", "你可不准死。不然我真的會……很生氣的。", "0", "0", "0", "0", "0", "cv_RED_SP_26", "0", "0"},
[440626] = {440626, 14006, 27, 20, "0", "0", "那些原罪能成為我討好史蒂芬妮和你的禮物，還算是有點價值嘛。", "0", "0", "0", "0", "0", "cv_RED_SP_27", "0", "0"},
[440627] = {440627, 14006, 28, 21, "0", "0", "說起來我想到了……殺那些原罪不就是在殺和我一樣構造的生物嗎……", "0", "0", "0", "0", "0", "cv_RED_SP_28", "0", "0"},
[440628] = {440628, 14006, 29, 21, "0", "0", "泡得我都快生銹了……", "0", "0", "0", "0", "0", "cv_RED_SP_29", "0", "0"},
[440629] = {440629, 14006, 30, 22, "0", "0", "要是你現在進來……我大概不會趕你出去。不過我想領航也不敢，哈哈畢竟是正人君子嘛……這也挺好。沒有在說你不好的意思哦？哈哈。", "0", "0", "0", "0", "0", "cv_RED_SP_30", "0", "0"},
[440630] = {440630, 14006, 31, 23, "0", "0", "由人所鑄就的人，完美的人類，機械人也是人。", "0", "0", "0", "0", "0", "cv_RED_SP_31", "0", "0"},
[440631] = {440631, 14006, 32, 24, "0", "0", "不出我所料了。", "0", "0", "0", "0", "0", "cv_RED_SP_32", "0", "0"},
[440632] = {440632, 14006, 33, 25, "0", "0", "哎呀，身上又濺到血了……是敵人的吧？反正不是我的。", "0", "0", "0", "0", "0", "cv_RED_SP_33", "0", "0"},
[440633] = {440633, 14006, 34, 26, "0", "0", "我的人生沒有道德，只有方向。", "0", "0", "0", "0", "0", "cv_RED_SP_34", "0", "0"},
[440634] = {440634, 14006, 35, 27, "0", "0", "我打賭原罪會被我的完美嚇得不敢動彈。", "0", "0", "0", "0", "0", "cv_RED_SP_35", "0", "0"},
[440635] = {440635, 14006, 36, 28, "0", "0", "沒電了，我先走了。", "0", "0", "0", "0", "0", "cv_RED_SP_36", "0", "0"},
[440636] = {440636, 14006, 37, 29, "0", "0", "哎，這種菜雞也能算是‘同伴’？", "0", "0", "0", "0", "0", "cv_RED_SP_37", "0", "0"},
[440637] = {440637, 14006, 38, 30, "0", "0", "只有我還不夠嗎？只是從勝率來說沒有任何變化。", "0", "0", "0", "0", "0", "cv_RED_SP_38", "0", "0"},
[440638] = {440638, 14006, 39, 31, "0", "0", "升級……胸部！", "0", "0", "0", "0", "0", "cv_RED_SP_39", "0", "0"},
[440639] = {440639, 14006, 40, 32, "0", "0", "升級……超級胸部！", "0", "0", "0", "0", "0", "cv_RED_SP_40", "0", "0"},
[440640] = {440640, 14006, 41, 33, "0", "0", "你穿得像個NPC……", "0", "0", "0", "0", "0", "cv_RED_SP_41", "0", "0"},
[440641] = {440641, 14006, 42, 34, "0", "0", "能調整的參數也太少了", "0", "0", "0", "0", "0", "cv_RED_SP_42", "0", "0"},
[440642] = {440642, 14006, 43, 35, "0", "0", "這麼多紙質信件？原始人打過來了？", "0", "0", "0", "0", "0", "cv_RED_SP_43", "0", "0"},
[440643] = {440643, 14006, 44, 36, "0", "0", "我可以順著網路刪掉你的遊戲存檔。", "0", "0", "0", "0", "0", "cv_RED_SP_44", "0", "0"},
[440644] = {440644, 14006, 45, 37, "0", "0", "嗯……", "0", "0", "0", "0", "0", "cv_RED_SP_45", "0", "0"},
[4101100100] = {4101100100, 11011001, 1, 1, "0", "0", "蒼霧殘響。", "苍雾残响（ハツリバーブ）。", "0", "0", "苍雾残响。", "0", "cv_honglei_32", "0", "0"},
[4101100101] = {4101100101, 11011001, 2, 2, "0", "0", "這是您下達的任務嗎？瞭解，我會一直站在這裡的。", "これは贵殿の命令か？承知した。ここから离れぬ。", "0", "0", "这是您下达的任务吗？了解，我会一直站在这里的。", "0", "cv_honglei_2", "0", "0"},
[4101100102] = {4101100102, 11011001, 3, 3, "0", "0", "忍心社，轟雷。您就是這支隊伍的領航嗎？我明白了，我會聽從您的所有命令。", "忍心社、轰雷。贵殿がこの队のナビゲーターか？分かった。命令に従う。", "0", "0", "忍心社，轰雷。您就是这支队伍的领航吗？我明白了，我会听从您的所有命令。", "0", "cv_honglei_1", "0", "0"},
[4101100103] = {4101100103, 11011001, 91, 4, "0", "idle", "鈴木清風…她不在這裡吧？那就好……領航，給您一個提議，最好不要把她和我安排在一起。", "铃木清风は……ここにはおらぬようだな。よかった。……贵殿に一つ忠告しておく。彼女と我を同じ所に配置せぬことだ。", "0", "0", "铃木清风…她不在这里吧？那就好……领航，给您一个提议，最好不要把她和我安排在一起。", "0", "cv_honglei_3", "0", "idle,idle"},
[4101100104] = {4101100104, 11011001, 94, 4, "0", "idle2", "打起精神，領航，您也有自己的任務吧？", "ナビゲーター、しっかりしろ。贵殿にも己の任务があるはずだ。", "0", "0", "打起精神，领航，您也有自己的任务吧？", "0", "cv_honglei_4", "0", "idle2,idle2"},
[4101100105] = {4101100105, 11011001, 98, 4, "0", "idle3", "儘管艾吉斯並不是一個表面上那樣完美的的組織…但它救了我，讓我重獲新生也是不爭的事實。所以，我決定將作為“轟雷”的人生…全部奉獻給艾吉斯。", "アイギスは……特に素晴らしい组织とも言えぬ。だが我を救い、新たな人生を与えてくれたことも纷れのない事実だ。だから我は轰雷としての人生を、全てアイギスに捧げると决意したのだ。", "0", "0", "尽管艾吉斯并不是一个表面上那样完美的的组织…但它救了我，让我重获新生也是不争的事实。所以，我决定将作为“轰雷”的人生…全部奉献给艾吉斯。", "0", "cv_honglei_29", "0", "idle3,idle3"},
[4101100106] = {4101100106, 11011001, 93, 5, "1_》_0_0.8", "switch1", "忍心社的成員，平常會偽裝成不起眼的人，來隱藏自己的身份。我們作為艾吉斯的無形之刃，在黑暗中為它服務，直到死亡才會停下，這就是我們的宿命。", "忍心社の者たちは、目立たぬ一般人として生活することで、己の正体を隠している。アイギスの刃として闇の中で己を研ぎすまし、人知れず锖びていく。これが我らの宿命だ。", "0", "0", "忍心社的成员，平常会伪装成不起眼的人，来隐藏自己的身份。我们作为艾吉斯的无形之刃，在黑暗中为它服务，直到死亡才会停下，这就是我们的宿命。", "0", "cv_honglei_30", "0", "switch1,switch1"},
[4101100107] = {4101100107, 11011001, 102, 5, "1_》_0_0.8", "switch2", "有任務嗎？", "任务か？", "0", "0", "有任务吗？", "0", "cv_honglei_5", "0", "switch2,switch2"},
[4101100108] = {4101100108, 11011001, 96, 5, "1_》_0_0.8", "switch3", "怎麼了？", "どうした？", "0", "0", "怎么了？", "0", "cv_honglei_43", "0", "switch3,switch3"},
[4101100109] = {4101100109, 11011001, 92, 5, "1_》_0_0.8", "level1", "忍心社的成員，平常會偽裝成不起眼的人，來隱藏自己的身份。我們作為艾吉斯的無形之刃，在黑暗中為它服務，直到死亡才會停下，這就是我們的宿命。", "忍心社の者たちは、目立たぬ一般人として生活することで、己の正体を隠している。アイギスの刃として闇の中で己を研ぎすまし、人知れず锖びていく。これが我らの宿命だ。", "0", "0", "忍心社的成员，平常会伪装成不起眼的人，来隐藏自己的身份。我们作为艾吉斯的无形之刃，在黑暗中为它服务，直到死亡才会停下，这就是我们的宿命。", "0", "cv_honglei_30", "0", "level1,level1"},
[4101100110] = {4101100110, 11011001, 95, 5, "1_》_0_0.8", "level2", "領航，無論多麼骯髒的任務我都會完成的，這就是我的使命。", "どんな污い任务でも成し遂げてみせる。これが我が使命だ。", "0", "0", "领航，无论多么肮脏的任务我都会完成的，这就是我的使命。", "0", "cv_honglei_6", "0", "level2,level2"},
[4101100111] = {4101100111, 11011001, 106, 5, "1_》_0_0.8", "level3", "成立“忍心社”的目的，是為了防止像“她”那樣的悲劇再次出現。領航，我不會讓任何人傷害您的…您理應有一個美滿的人生。", "忍心社を创设した目的は……彼女のような悲剧を二度と生じさせぬこと。……ナビゲーター、谁にも贵殿を伤付けさせぬ。贵殿には幸せな人生を送って欲しいのだ。", "0", "0", "成立“忍心社”的目的，是为了防止像“她”那样的悲剧再次出现。领航，我不会让任何人伤害您的…您理应有一个美满的人生。", "0", "cv_honglei_7", "0", "level3,level3"},
[4101100112] = {4101100112, 11011001, 106, 5, "1_》_0_0.8", "level4", "…領航，我一直認為，只要能夠完成任務，無論是別人的性命，抑或是自己的生命，都不過是消耗品。但，唯有您…只有您，是不同的。", "……ナビゲーター。我は任务が达成できるのであれば、人の命や自分の命など、ただの消耗品に过ぎないと思っていた。しかしナビゲーター。贵殿だけは……特别なのだ。", "0", "0", "…领航，我一直认为，只要能够完成任务，无论是别人的性命，亦或是自己的生命，都不过是消耗品。但，唯有您…只有您，是不同的。", "0", "cv_honglei_8", "0", "level4,level4"},
[4101100113] = {4101100113, 11011001, 12, 6, "0", "0", "嗯，我變得更強了。", "うむ。强くなった。", "0", "0", "嗯，我变得更强了。", "0", "cv_honglei_9", "0", "0"},
[4101100114] = {4101100114, 11011001, 13, 7, "0", "0", "您相信我嗎？", "贵殿は……我を信じるか？", "0", "0", "您…相信我吗？", "0", "cv_honglei_10", "0", "0"},
[4101100115] = {4101100115, 11011001, 14, 8, "0", "0", "您的這份信任，我會用實績來回報的。請原諒我現在只能用一句簡單的“謝謝”來回應您……", "贵殿の信頼に、必ずや実绩を持って応えよう。今は、感谢の言叶しかない。许してくれ……", "0", "0", "您的这份信任，我会用实绩来回报的。请原谅我现在只能用一句简单的“谢谢”来回应您……", "0", "cv_honglei_11", "0", "0"},
[4101100116] = {4101100116, 11011001, 15, 9, "0", "0", "謝謝。", "感谢する。", "0", "0", "谢谢。", "0", "cv_honglei_12", "0", "0"},
[4101100117] = {4101100117, 11011001, 16, 10, "0", "0", "作戰開始。", "作戦开始。", "0", "0", "作战开始。", "0", "cv_honglei_13", "0", "0"},
[4101100118] = {4101100118, 11011001, 17, 11, "0", "0", "這是當然的結果，忍心社從未失敗過。", "当然の结果だ。忍心社に失败はない。", "0", "0", "这是当然的结果，忍心社从未失败过。", "0", "cv_honglei_14", "0", "0"},
[4101100119] = {4101100119, 11011001, 18, 12, "0", "0", "下一次，我們一定會做得更好的。", "次は必ず、もっと上手くやる。", "0", "0", "下一次，我们一定会做得更好的。", "0", "cv_honglei_15", "0", "0"},
[4101100120] = {4101100120, 11011001, 19, 13, "0", "0", "這樣的勝利…我不能接受。", "このような胜利……腑に落ちぬ。", "0", "0", "这样的胜利…我不能接受。", "0", "cv_honglei_16", "0", "0"},
[4101100121] = {4101100121, 11011001, 20, 14, "0", "0", "…這是我會銘記一生的恥辱……", "一生の耻として刻んでおこう……", "0", "0", "…这是我会铭记一生的耻辱……", "0", "cv_honglei_17", "0", "0"},
[4101100122] = {4101100122, 11011001, 21, 15, "0", "0", "這是我的功勞。", "讨ち取った！", "0", "0", "这是我的功劳。", "0", "cv_honglei_18", "0", "0"},
[4101100123] = {4101100123, 11011001, 23, 16, "0", "0", "化為兩半吧。", "真っ二つになるがいい。", "0", "0", "化为两半吧。", "0", "cv_honglei_19", "0", "0"},
[4101100124] = {4101100124, 11011001, 24, 17, "0", "0", "不會讓你喘息的。", "息つく暇はないぞ。", "0", "0", "不会让你喘息的。", "0", "cv_honglei_21", "0", "0"},
[4101100125] = {4101100125, 11011001, 26, 19, "0", "0", "不甘心……", "悔しい…な……", "0", "0", "不甘心……", "0", "cv_honglei_20", "0", "0"},
[4101100126] = {4101100126, 11011001, 27, 20, "0", "0", "任務之外的放鬆嗎…我明白了。", "任务外の休息か……承知した。", "0", "0", "任务之外的放松吗…我明白了。", "0", "cv_honglei_22", "0", "0"},
[4101100127] = {4101100127, 11011001, 28, 21, "0", "0", "…這樣實在是太耽誤時間了。", "うむ……これはあまりにも时间の无駄では……", "0", "0", "…这样实在是太耽误时间了。", "0", "cv_honglei_23", "0", "0"},
[4101100128] = {4101100128, 11011001, 29, 21, "0", "0", "我果然…不太適應這種感覺。", "やはり…こういうのは惯れぬな。", "0", "0", "我果然…不太适应这种感觉。", "0", "cv_honglei_24", "0", "0"},
[4101100129] = {4101100129, 11011001, 30, 22, "0", "0", "請後退，領航。", "ナビゲーター、我が背后に。", "0", "0", "请后退，领航。", "0", "cv_honglei_25", "0", "0"},
[4101100130] = {4101100130, 11011001, 31, 23, "0", "0", "這也屬於任務的一種形式嗎？", "これも一种の任务か？", "0", "0", "这也属于任务的一种形式吗？", "0", "cv_honglei_26", "0", "0"},
[4101100131] = {4101100131, 11011001, 32, 24, "0", "0", "您已經能夠認出我了…這樣一來，就不太妙了啊。", "我が気配を见抜かれてしまうとは……修行不足か。", "0", "0", "您已经能够认出我了…这样一来，就不太妙了啊。", "0", "cv_honglei_27", "0", "0"},
[4101100132] = {4101100132, 11011001, 33, 25, "0", "0", "偽裝是我們擅長的事，您認不出來，很正常……", "隠れ身は我の得意とするところ。贵殿が分からぬのも当然だ。", "0", "0", "伪装是我们擅长的事，您认不出来，很正常……", "0", "cv_honglei_28", "0", "0"},
[4101100133] = {4101100133, 11011001, 34, 26, "0", "0", "領航，開始工作吧，我正看著你。", "ナビゲーター。勤めを果たそう。我もついていく。", "0", "0", "领航，开始工作吧，我正看着你。", "0", "cv_honglei_31", "0", "0"},
[4101100134] = {4101100134, 11011001, 35, 27, "0", "0", "您下達的任務，我一定會完成的。", "贵殿に与えられた任务、必ずや成し遂げてみせる。", "0", "0", "您下达的任务，我一定会完成的。", "0", "cv_honglei_33", "0", "0"},
[4101100135] = {4101100135, 11011001, 36, 28, "0", "0", "只要完成它就可以了吧。", "この任务を果たせばよいのだな？", "0", "0", "只要完成它就可以了吧。", "0", "cv_honglei_34", "0", "0"},
[4101100136] = {4101100136, 11011001, 37, 29, "0", "0", "目標…有嗎？", "目当ての者はいるのか？", "0", "0", "目标…有吗？", "0", "cv_honglei_35", "0", "0"},
[4101100137] = {4101100137, 11011001, 38, 30, "0", "0", "招人嗎…那麼我先告退了。", "招集か。……では一旦失礼する。", "0", "0", "招人吗…那么我先告退了。", "0", "cv_honglei_36", "0", "0"},
[4101100138] = {4101100138, 11011001, 39, 31, "0", "0", "為“劍”而準備劍嗎……", "刃の振るう剣、か……", "0", "0", "为“剑”而准备剑吗……", "0", "cv_honglei_37", "0", "0"},
[4101100139] = {4101100139, 11011001, 40, 32, "0", "0", "您打算買什麼呢？", "何か买うのか？", "0", "0", "您打算买什么呢？", "0", "cv_honglei_38", "0", "0"},
[4101100140] = {4101100140, 11011001, 41, 33, "0", "0", "真是漂亮的眼睛呢。", "绮丽な目だ。", "0", "0", "真是漂亮的眼睛呢。", "0", "cv_honglei_39", "0", "0"},
[4101100141] = {4101100141, 11011001, 42, 34, "0", "0", "需要我幫忙嗎？", "手が必要なら贷すぞ。", "0", "0", "需要我帮忙吗？", "0", "cv_honglei_40", "0", "0"},
[4101100142] = {4101100142, 11011001, 43, 35, "0", "0", "有總部的命令嗎？", "本部からの指令はあるか？", "0", "0", "有总部的命令吗？", "0", "cv_honglei_41", "0", "0"},
[4101100143] = {4101100143, 11011001, 44, 36, "0", "0", "請去和其他人交流吧，不必在意我。", "我のことは気にするな。気配を消しておく。", "0", "0", "请去和其他人交流吧，不必在意我。", "0", "cv_honglei_42", "0", "0"},
[4101100144] = {4101100144, 11011001, 45, 37, "0", "0", "怎麼了？", "どうした？", "0", "0", "怎么了？", "0", "cv_honglei_43", "0", "0"},
[4105600100] = {4105600100, 11056001, 1, 1, "0", "0", "蒼霧殘響", "0", "0", "0", "0", "0", "cv_sk_huizhang_01", "0", "0"},
[4105600101] = {4105600101, 11056001, 2, 2, "0", "0", "看護的任務是吧，沒問題就交給我吧，就當支付房子的租金了。", "0", "0", "0", "0", "0", "cv_sk_huizhang_02", "0", "0"},
[4105600102] = {4105600102, 11056001, 3, 3, "0", "0", "啊……沒想到會發生這種事情，我們竟然來到了你的世界，那在我們解決問題之前，就拜託你收留我們一段時間吧。姑且再通報一下姓名，我是斯卡蒂的未來之一，叫我會長就好。", "0", "0", "0", "0", "0", "cv_sk_huizhang_03", "0", "0"},
[4105600103] = {4105600103, 11056001, 4, 4, "0", "idle", "說到夏天的海邊，除了沙灘排球外，就是這個了吧——不錯，打西瓜可是海灘活動絕不缺少的一環。", "0", "0", "0", "0", "0", "cv_sk_huizhang_n01", "0", "idle,idle"},
[4105600104] = {4105600104, 11056001, 5, 4, "0", "idle", "當雙眼被蒙蔽時，想要看清前方的道路，所需要的就是掙開心中的眼睛——這就是打西瓜的奧秘。", "0", "0", "0", "0", "0", "cv_sk_huizhang_n02", "0", "idle,idle"},
[4105600105] = {4105600105, 11056001, 6, 4, "0", "idle", "我呢……在原本的世界裡，幾乎沒有真正意義上的“朋友”，響子算一個……但她也不會像這樣陪我胡鬧，所以我很高興，能夠來到你們的世界。", "0", "0", "0", "0", "0", "cv_sk_huizhang_n03", "0", "idle,idle"},
[4105600106] = {4105600106, 11056001, 7, 5, "15_1_0_0.8", "touch1", "西瓜——在這邊嗎？斬！", "0", "0", "0", "0", "0", "cv_sk_huizhang_n04", "0", "touch1,touch1"},
[4105600107] = {4105600107, 11056001, 8, 5, "15_1_0_0.8", "touch1", "打西瓜比賽嗎……有趣，雖然是第一次，但我自信不會輸給任何人。", "0", "0", "0", "0", "0", "cv_sk_huizhang_n05", "0", "touch1,touch1"},
[4105600108] = {4105600108, 11056001, 9, 5, "15_2_0_0.8", "touch2", "領航，不要試圖用錯誤的指令來迷惑我，即便肉眼看不見，我也能感受到真實的世界是怎樣一副光景。", "0", "0", "0", "0", "0", "cv_sk_huizhang_n06", "0", "touch2,touch2"},
[4105600109] = {4105600109, 11056001, 10, 5, "15_2_0_0.8", "touch2", "嗯？這個觸感……噢，是領航啊。我還在想這個圓圓的東西如果是西瓜的話未免有些小了，原來是領航你的頭。真危險，我差點就砍下去了。", "0", "0", "0", "0", "0", "cv_sk_huizhang_n07", "0", "touch2,touch2"},
[4105600110] = {4105600110, 11056001, 11, 5, "15_2_0_0.8", "touch2", "夏日的回憶，和領航度過的時光……這或許才是夏天真正的寶物吧，是足以和影之國匹敵的，無法被任何事物取代的寶物。", "0", "0", "0", "0", "0", "cv_sk_huizhang_n08", "0", "touch2,touch2"},
[4105600111] = {4105600111, 11056001, 12, 6, "0", "0", "這、這是像game一樣地得到了強化？", "0", "0", "0", "0", "0", "cv_sk_huizhang_12", "0", "0"},
[4105600112] = {4105600112, 11056001, 13, 7, "0", "0", "能感受到你的意志在左右著我的成長。", "0", "0", "0", "0", "0", "cv_sk_huizhang_13", "0", "0"},
[4105600113] = {4105600113, 11056001, 14, 8, "0", "0", "原來如此，我明白了你存在的意義了，怪不得被大家稱之為唯一的主人公。那麼，接下來的時間裡可別讓我失望啊，主人公。", "0", "0", "0", "0", "0", "cv_sk_huizhang_14", "0", "0"},
[4105600114] = {4105600114, 11056001, 15, 9, "0", "0", "規劃已完成，按照計畫進行吧。", "0", "0", "0", "0", "0", "cv_sk_huizhang_15", "0", "0"},
[4105600115] = {4105600115, 11056001, 16, 10, "0", "0", "由我來吧。", "0", "0", "0", "0", "0", "cv_sk_huizhang_16", "0", "0"},
[4105600116] = {4105600116, 11056001, 17, 11, "0", "0", "與我一同享受勝利吧，領航。", "0", "0", "0", "0", "0", "cv_sk_huizhang_17", "0", "0"},
[4105600117] = {4105600117, 11056001, 18, 12, "0", "0", "還挺有趣的嘛。", "0", "0", "0", "0", "0", "cv_sk_huizhang_18", "0", "0"},
[4105600118] = {4105600118, 11056001, 19, 13, "0", "0", "險勝呢，有趣。", "0", "0", "0", "0", "0", "cv_sk_huizhang_19", "0", "0"},
[4105600119] = {4105600119, 11056001, 20, 14, "0", "0", "哼，了不起，但是下一次就未必了。", "0", "0", "0", "0", "0", "cv_sk_huizhang_20", "0", "0"},
[4105600120] = {4105600120, 11056001, 21, 15, "0", "0", "真難看。", "0", "0", "0", "0", "0", "cv_sk_huizhang_n09", "0", "0"},
[4105600121] = {4105600121, 11056001, 23, 16, "0", "0", "是這邊！", "0", "0", "0", "0", "0", "cv_sk_huizhang_n11", "0", "0"},
[4105600122] = {4105600122, 11056001, 24, 17, "0", "0", "不對嗎？那這邊呢！", "0", "0", "0", "0", "0", "cv_sk_huizhang_n12", "0", "0"},
[4105600123] = {4105600123, 0, 25, 18, "0", "0", "我乃躊躇不前者的未來一角。", "0", "0", "0", "0", "0", "cv_sk_huizhang_25", "0", "0"},
[4105600124] = {4105600124, 11056001, 26, 19, "0", "0", "好難吃的西瓜……", "0", "0", "0", "0", "0", "cv_sk_huizhang_n13", "0", "0"},
[4105600125] = {4105600125, 11056001, 27, 20, "0", "0", "洗洗洗洗洗洗洗洗洗澡！？", "0", "0", "0", "0", "0", "cv_sk_huizhang_27", "0", "0"},
[4105600126] = {4105600126, 11056001, 28, 21, "0", "0", "太離譜了！我不能接受！有違禮儀！不檢點！太下流了！", "0", "0", "0", "0", "0", "cv_sk_huizhang_28", "0", "0"},
[4105600127] = {4105600127, 11056001, 29, 21, "0", "0", "死刑了啊死刑了，你這傢伙。", "0", "0", "0", "0", "0", "cv_sk_huizhang_29", "0", "0"},
[4105600128] = {4105600128, 11056001, 30, 22, "0", "0", "……難道斯卡蒂她也會和你做這種事情？", "0", "0", "0", "0", "0", "cv_sk_huizhang_30", "0", "0"},
[4105600129] = {4105600129, 11056001, 31, 23, "0", "0", "……給你個提示吧，我是斯卡蒂。", "0", "0", "0", "0", "0", "cv_sk_huizhang_31", "0", "0"},
[4105600130] = {4105600130, 11056001, 32, 24, "0", "0", "簡簡單單對吧……我在笑？笨、笨蛋，怎麼可能！", "0", "0", "0", "0", "0", "cv_sk_huizhang_32", "0", "0"},
[4105600131] = {4105600131, 11056001, 33, 25, "0", "0", "……看來接下來要讓你對我熟悉起來才行", "0", "0", "0", "0", "0", "cv_sk_huizhang_33", "0", "0"},
[4105600132] = {4105600132, 11056001, 34, 26, "0", "0", "一起來玩吧——玩什麼？當然是打西瓜。", "0", "0", "0", "0", "0", "cv_sk_huizhang_n14", "0", "0"},
[4105600133] = {4105600133, 11056001, 35, 27, "0", "0", "好主意呢。", "0", "0", "0", "0", "0", "cv_sk_huizhang_35", "0", "0"},
[4105600134] = {4105600134, 11056001, 36, 28, "0", "0", "讓我稍微活動一下吧。", "0", "0", "0", "0", "0", "cv_sk_huizhang_36", "0", "0"},
[4105600135] = {4105600135, 11056001, 37, 29, "0", "0", "未成熟的女主角們。", "0", "0", "0", "0", "0", "cv_sk_huizhang_37", "0", "0"},
[4105600136] = {4105600136, 11056001, 38, 30, "0", "0", "願好運與您同行。", "0", "0", "0", "0", "0", "cv_sk_huizhang_38", "0", "0"},
[4105600137] = {4105600137, 11056001, 39, 31, "0", "0", "好酷……咳，我是說還不錯。", "0", "0", "0", "0", "0", "cv_sk_huizhang_39", "0", "0"},
[4105600138] = {4105600138, 11056001, 40, 32, "0", "0", "我有攢下來的私房錢，想要什麼？", "0", "0", "0", "0", "0", "cv_sk_huizhang_40", "0", "0"},
[4105600139] = {4105600139, 11056001, 41, 33, "0", "0", "主人公啊……我也是主人公。", "0", "0", "0", "0", "0", "cv_sk_huizhang_41", "0", "0"},
[4105600140] = {4105600140, 11056001, 42, 34, "0", "0", "改變世界的機關就在這裡。", "0", "0", "0", "0", "0", "cv_sk_huizhang_42", "0", "0"},
[4105600141] = {4105600141, 11056001, 43, 35, "0", "0", "星光彙聚於此。", "0", "0", "0", "0", "0", "cv_sk_huizhang_43", "0", "0"},
[4105600142] = {4105600142, 11056001, 44, 36, "0", "0", "你能聽見世界的聲音嗎？", "0", "0", "0", "0", "0", "cv_sk_huizhang_44", "0", "0"},
[4105600143] = {4105600143, 11056001, 45, 37, "0", "0", "yes——", "0", "0", "0", "0", "0", "cv_sk_huizhang_45", "0", "0"},
[4301700200] = {4301700200, 13017002, 1, 1, "0", "0", "蒼霧殘響", "0", "0", "0", "0", "0", "cv_sk_jiushijiuhuan_1", "0", "0"},
[4301700201] = {4301700201, 13017002, 2, 2, "0", "0", "親愛的真的是……兩個人待在一起的話，直接叫我小環好不好？", "0", "0", "0", "0", "0", "cv_sk_jiushijiuhuan_2", "0", "0"},
[4301700202] = {4301700202, 13017002, 3, 3, "0", "0", "數字的九十九，九十九環的環，從今天開始我們就是新婚夫妻了……現在還不行嗎？", "0", "0", "0", "0", "0", "cv_sk_jiushijiuhuan_3", "0", "0"},
[4301700203] = {4301700203, 13017002, 91, 4, "0", "idle", "真沒想到我預見的未來竟然在這裡實現了，我還是要等到遙遠的未來呢，lucky~", "0", "0", "0", "0", "0", "cv_sk_jiushijiuhuan_n02", "0", "idle,idle"},
[4301700204] = {4301700204, 13017002, 91, 4, "0", "idle", "好啦，既然都在女主角宇宙了，那就露出開心的笑吧，不要擔心現實世界的事情了……不然我要生氣了哦？", "0", "0", "0", "0", "0", "cv_sk_jiushijiuhuan_n03", "0", "idle,idle"},
[4301700205] = {4301700205, 13017002, 94, 4, "0", "idle2", "我……開始變得不像是我了，都是因為親愛的……只要在親愛的身邊就會這樣……感覺身體都輕鬆了不少……", "0", "0", "0", "0", "0", "cv_sk_jiushijiuhuan_n08", "0", "idle2,idle2"},
[4301700206] = {4301700206, 13017002, 94, 4, "0", "idle2", "親愛的……我也想一直留在你身邊……變得獨一無二……", "0", "0", "0", "0", "0", "cv_sk_jiushijiuhuan_n09", "0", "idle2,idle2"},
[4301700207] = {4301700207, 13017002, 98, 4, "0", "idle3", "即使這是轉瞬即逝的夢也好……只需要享受這一刻的溫暖就好了……至少……我明白了這樣的道理。", "0", "0", "0", "0", "0", "cv_sk_jiushijiuhuan_n14", "0", "idle3,idle3"},
[4301700208] = {4301700208, 13017002, 98, 4, "0", "idle3", "我和你擁有著相同的感情……對嗎？", "0", "0", "0", "0", "0", "cv_sk_jiushijiuhuan_n15", "0", "idle3,idle3"},
[4301700209] = {4301700209, 13017002, 93, 5, "1_》_0_0.8", "switch1", "哎……", "0", "0", "0", "0", "0", "cv_sk_jiushijiuhuan_n01", "0", "switch1,switch1"},
[4301700210] = {4301700210, 13017002, 102, 5, "1_》_0_0.8", "switch2", "呀……", "0", "0", "0", "0", "0", "cv_sk_jiushijiuhuan_n07", "0", "switch2,switch2"},
[4301700211] = {4301700211, 13017002, 96, 5, "1_》_0_0.8", "switch3", "嗯……", "0", "0", "0", "0", "0", "cv_sk_jiushijiuhuan_n13", "0", "switch3,switch3"},
[4301700212] = {4301700212, 13017002, 92, 5, "1_》_0_0.8", "level1", "我還以為我會抱著這份感情一直這樣下去呢……謝謝你……親愛的……", "0", "0", "0", "0", "0", "cv_sk_jiushijiuhuan_n04", "0", "level1,level1"},
[4301700213] = {4301700213, 13017002, 92, 5, "1_》_0_0.8", "level1", "夢醒來的時候……我也一定會和你重逢的……總會有那麼一天的……", "0", "0", "0", "0", "0", "cv_sk_jiushijiuhuan_n05", "0", "level1,level1"},
[4301700214] = {4301700214, 13017002, 92, 5, "1_》_0_0.8", "level1", "現在就請閉上眼睛吧……安心地睡吧……還、還是說你想要做、做一些……一些……其他的事情……", "0", "0", "0", "0", "0", "cv_sk_jiushijiuhuan_n06", "0", "level1,level1"},
[4301700215] = {4301700215, 13017002, 95, 5, "1_》_0_0.8", "level2", "無論是歡笑還是悲傷，在這個夏天都請把它們忘記了吧。為什麼要說這種話？唔——！我的意思是……只、只要記住我就好了！", "0", "0", "0", "0", "0", "cv_sk_jiushijiuhuan_n10", "0", "level2,level2"},
[4301700216] = {4301700216, 13017002, 95, 5, "1_》_0_0.8", "level2", "想要見面……但是沒辦法見面……想要見面……但是沒辦法見面……想要見面……但是沒辦法見面。我的每一天都是這麼度過的……親愛的……", "0", "0", "0", "0", "0", "cv_sk_jiushijiuhuan_n11", "0", "level2,level2"},
[4301700217] = {4301700217, 13017002, 95, 5, "1_》_0_0.8", "level2", "正是有了這一刻……這漫長的等待才沒有到令人厭棄的程度。抱歉……說了奇怪的話，但是我現在真的很開心……", "0", "0", "0", "0", "0", "cv_sk_jiushijiuhuan_n12", "0", "level2,level2"},
[4301700218] = {4301700218, 13017002, 106, 5, "1_》_0_0.8", "level3", "等、等下……", "0", "0", "0", "0", "0", "cv_sk_jiushijiuhuan_n16", "0", "level3,level3"},
[4301700219] = {4301700219, 13017002, 106, 5, "1_》_0_0.8", "level4", "我們的孩子將在9個月之後出生……這可不是預知未來。只、只是我的期望而已……嚇到你了？", "0", "0", "0", "0", "0", "cv_sk_jiushijiuhuan_n17", "0", "level4,level4"},
[4301700220] = {4301700220, 13017002, 106, 5, "1_》_0_0.8", "level4", "我想將我的一切都獻給你。", "0", "0", "0", "0", "0", "cv_sk_jiushijiuhuan_n18", "0", "level4,level4"},
[4301700221] = {4301700221, 13017002, 12, 6, "0", "0", "嗯嗯……收穫了很多的領航能量。", "0", "0", "0", "0", "0", "cv_sk_jiushijiuhuan_12", "0", "0"},
[4301700222] = {4301700222, 13017002, 13, 7, "0", "0", "哇啊啊！親愛的能量多到溢出了！", "0", "0", "0", "0", "0", "cv_sk_jiushijiuhuan_13", "0", "0"},
[4301700223] = {4301700223, 13017002, 14, 8, "0", "0", "哦——這像是要靈魂出竅般的誇張感覺！不愧是親愛的！", "0", "0", "0", "0", "0", "cv_sk_jiushijiuhuan_14", "0", "0"},
[4301700224] = {4301700224, 13017002, 15, 9, "0", "0", "心在噗通噗通地跳。", "0", "0", "0", "0", "0", "cv_sk_jiushijiuhuan_15", "0", "0"},
[4301700225] = {4301700225, 13017002, 16, 10, "0", "0", "九十九環，作為駕駛員開始戰鬥。", "0", "0", "0", "0", "0", "cv_sk_jiushijiuhuan_16", "0", "0"},
[4301700226] = {4301700226, 13017002, 17, 11, "0", "0", "不能妥協的完美勝利！", "0", "0", "0", "0", "0", "cv_sk_jiushijiuhuan_17", "0", "0"},
[4301700227] = {4301700227, 13017002, 18, 12, "0", "0", "下次一定會做個了斷。", "0", "0", "0", "0", "0", "cv_sk_jiushijiuhuan_18", "0", "0"},
[4301700228] = {4301700228, 13017002, 19, 13, "0", "0", "出了紕漏……弱點都暴露出來了。", "0", "0", "0", "0", "0", "cv_sk_jiushijiuhuan_19", "0", "0"},
