[4301700231] = {4301700231, 13017002, 26, 19, "0", "0", "這樣的未來……我根本就沒有看到……", "0", "0", "0", "0", "0", "cv_sk_jiushijiuhuan_23", "0", "0"},
[4301700232] = {4301700232, 13017002, 24, 17, "0", "0", "弱點在那裡！", "0", "0", "0", "0", "0", "cv_sk_jiushijiuhuan_n22", "0", "0"},
[4301700233] = {4301700233, 13017002, 27, 20, "0", "0", "洗澡洗澡~戰鬥過後就要痛痛快快地洗澡洗澡~", "0", "0", "0", "0", "0", "cv_sk_jiushijiuhuan_24", "0", "0"},
[4301700234] = {4301700234, 13017002, 28, 21, "0", "0", "我等你很久了哦，怎麼了剛剛在忙嗎，那就等會讓我來幫你也做個按摩舒服舒服吧。", "0", "0", "0", "0", "0", "cv_sk_jiushijiuhuan_25", "0", "0"},
[4301700235] = {4301700235, 13017002, 29, 21, "0", "0", "還不快點開始嗎？今天的女主角可是已經做好準備等你了哦！", "0", "0", "0", "0", "0", "cv_sk_jiushijiuhuan_26", "0", "0"},
