[4302600129] = {4302600129, 13026001, 27, 20, "0", "0", "呼——終於能泡個澡了……辛苦了一天，熱水最治癒了，領航要和媽媽一起洗嗎？", "0", "0", "0", "0", "0", "cv_sk_buzhihuo_sw_27", "0", "0"},
[4302600130] = {4302600130, 13026001, 28, 21, "0", "0", "啊……泡得有點暈乎乎的了……再泡一會兒就出去吧……", "0", "0", "0", "0", "0", "cv_sk_buzhihuo_sw_28", "0", "0"},
