[4302600136] = {4302600136, 13026001, 34, 26, "0", "0", "無論游出去多遠，媽媽這裡永遠是你的港灣哦。", "0", "0", "0", "0", "0", "cv_sk_buzhihuo_sw_n19", "0", "0"},
