[4400600100] = {4400600100, 14006001, 1, 1, "0", "0", "蒼霧殘響", "0", "0", "0", "0", "0", "cv_sk_RED_SP_01", "0", "0"},
[4400600101] = {4400600101, 14006001, 2, 2, "0", "0", "叫我這個完美人類兼勇者來擔任看護你的人嗎？也行吧，畢竟守護的是一位“神明”。不算浪費我的時間。", "0", "0", "0", "0", "0", "cv_sk_RED_SP_02", "0", "0"},
[4400600102] = {4400600102, 14006001, 3, 3, "0", "0", "你把我召喚出來了……是不是應該實現我的願望了？為什麼不是反過來？廢話……召喚了我之後我還要實現你的願望，什麼好事情都給你占了。", "0", "0", "0", "0", "0", "cv_sk_RED_SP_03", "0", "0"},
[4400600103] = {4400600103, 14006001, 91, 4, "0", "idle", "誒嘿，是不是在偷看我浴衣裡面？想看嗎？自己來脫吧？", "0", "0", "0", "0", "0", "cv_sk_RED_SP_n02", "0", "idle,idle"},
[4400600104] = {4400600104, 14006001, 91, 4, "0", "idle", "這樣是不是很有夏天的感覺？我不知道所以才問你的，畢竟領航是經驗豐富者。", "0", "0", "0", "0", "0", "cv_sk_RED_SP_n03", "0", "idle,idle"},
[4400600105] = {4400600105, 14006001, 94, 4, "0", "idle2", "好、好熱的天氣啊……系統溫度已經警告三次了……雖然我沒有這種系統就是了。", "0", "0", "0", "0", "0", "cv_sk_RED_SP_n08", "0", "idle2,idle2"},
[4400600106] = {4400600106, 14006001, 94, 4, "0", "idle2", "你是不是在想不純潔的事情？我可是機器人哦，會記錄證據的……把你的犯罪行為播放到全宇宙。", "0", "0", "0", "0", "0", "cv_sk_RED_SP_n09", "0", "idle2,idle2"},
[4400600107] = {4400600107, 14006001, 98, 4, "0", "idle3", "領航是個喜新厭舊的壞蛋，而我是隨時能改變性格和身體構造的機器人，你不覺得我們是絕配嗎？又污蔑你？哪有的事。", "0", "0", "0", "0", "0", "cv_sk_RED_SP_n14", "0", "idle3,idle3"},
[4400600108] = {4400600108, 14006001, 98, 4, "0", "idle3", "你真的不打算在夏天和我留下點什麼色情的記憶嗎，啊……我可不是打算拍了視頻之後去炫耀哦……我真的不是這麼想的哦？", "0", "0", "0", "0", "0", "cv_sk_RED_SP_n15", "0", "idle3,idle3"},
[4400600109] = {4400600109, 14006001, 93, 5, "1_》_0_0.8", "switch1", "啊~終於輪到我了？", "0", "0", "0", "0", "0", "cv_sk_RED_SP_n01", "0", "switch1,switch1"},
[4400600110] = {4400600110, 14006001, 102, 5, "1_》_0_0.8", "switch2", "摸摸我的頭吧。", "0", "0", "0", "0", "0", "cv_sk_RED_SP_n07", "0", "switch2,switch2"},
[4400600111] = {4400600111, 14006001, 96, 5, "1_》_0_0.8", "switch3", "嘿……", "0", "0", "0", "0", "0", "cv_sk_RED_SP_n13", "0", "switch3,switch3"},
[4400600112] = {4400600112, 14006001, 92, 5, "1_》_0_0.8", "level1", "我只是來陪你看煙火的，不是來勾引你的，證據就是——我在浴衣下還穿著衣服，當然你要是著急現在就要做些什麼……那我也奉陪。", "0", "0", "0", "0", "0", "cv_sk_RED_SP_n04", "0", "level1,level1"},
[4400600113] = {4400600113, 14006001, 92, 5, "1_》_0_0.8", "level1", "你想不想……在煙火的下面看看星星？我是說真的。沒在開玩笑。", "0", "0", "0", "0", "0", "cv_sk_RED_SP_n05", "0", "level1,level1"},
[4400600114] = {4400600114, 14006001, 92, 5, "1_》_0_0.8", "level1", "你靠太近了。", "0", "0", "0", "0", "0", "cv_sk_RED_SP_n06", "0", "level1,level1"},
[4400600115] = {4400600115, 14006001, 95, 5, "1_》_0_0.8", "level2", "我可以模仿其他女主角……你想要哪一位陪伴你？查麗莎？多洛莉絲？斯卡蒂？還是星爍？", "0", "0", "0", "0", "0", "cv_sk_RED_SP_n10", "0", "level2,level2"},
[4400600116] = {4400600116, 14006001, 95, 5, "1_》_0_0.8", "level2", "我肚子上的鎖孔？你想摸？不過你竟然是想要摸鎖孔而不是我的胸部嗎？遺憾。", "0", "0", "0", "0", "0", "cv_sk_RED_SP_n11", "0", "level2,level2"},
[4400600117] = {4400600117, 14006001, 95, 5, "1_》_0_0.8", "level2", "風好大……你是不是在等我的泳衣被吹跑的那一瞬間？", "0", "0", "0", "0", "0", "cv_sk_RED_SP_n12", "0", "level2,level2"},
[4400600118] = {4400600118, 14006001, 106, 5, "1_》_0_0.8", "level3", "不做點什麼的話我就走了。", "0", "0", "0", "0", "0", "cv_sk_RED_SP_n16", "0", "level3,level3"},
[4400600119] = {4400600119, 14006001, 107, 5, "1_》_0_0.8", "level4", "等一會煙花升空的時候我們悄悄接吻吧？電影裡都是這麼演的……接完吻你會愛上我。", "0", "0", "0", "0", "0", "cv_sk_RED_SP_n17", "0", "level4,level4"},
[4400600120] = {4400600120, 14006001, 107, 5, "1_》_0_0.8", "level4", "怎麼樣？我和你的想像中一樣嗎？這是由愛而生的”表現“嗎？還是說這只是模仿愛的“行為“？告訴我吧？", "0", "0", "0", "0", "0", "cv_sk_RED_SP_n18", "0", "level4,level4"},
[4400600121] = {4400600121, 14006001, 12, 6, "0", "0", "因為我是高性能的人類，這種小事自然能辦到！", "0", "0", "0", "0", "0", "cv_sk_RED_SP_12", "0", "0"},
[4400600122] = {4400600122, 14006001, 13, 7, "0", "0", "呼～看這皮膚，優質，要摸摸嗎？放心，就是為了給你摸才準備的。", "0", "0", "0", "0", "0", "cv_sk_RED_SP_13", "0", "0"},
[4400600123] = {4400600123, 14006001, 14, 8, "0", "0", "哼，跟著身為勇者的我，你們就等著走向勝利吧！如果沒有勝利也沒關係，我可以帶著你們投降。", "0", "0", "0", "0", "0", "cv_sk_RED_SP_14", "0", "0"},
[4400600124] = {4400600124, 14006001, 15, 9, "0", "0", "一直升級胸部的話，能用胸部發射鐳射嗎？就像漫畫裡一樣。", "0", "0", "0", "0", "0", "cv_sk_RED_SP_15", "0", "0"},
[4400600125] = {4400600125, 14006001, 16, 10, "0", "0", "區區原罪也敢在完美人類面前倡狂？", "0", "0", "0", "0", "0", "cv_sk_RED_SP_16", "0", "0"},
[4400600126] = {4400600126, 14006001, 17, 11, "0", "0", "永久清除！", "0", "0", "0", "0", "0", "cv_sk_RED_SP_n19", "0", "0"},
