[4400600129] = {4400600129, 14006001, 20, 14, "0", "0", "啊……不好意思……剛剛宕機了……", "0", "0", "0", "0", "0", "cv_sk_RED_SP_n24", "0", "0"},
[4400600130] = {4400600130, 14006001, 21, 15, "0", "0", "死亡對你們來說算是一種解脫呢，NPC。", "0", "0", "0", "0", "0", "cv_sk_RED_SP_21", "0", "0"},
[4400600131] = {4400600131, 14006001, 23, 16, "0", "0", "我趕時間。", "0", "0", "0", "0", "0", "cv_sk_RED_SP_n20", "0", "0"},
[4400600132] = {4400600132, 14006001, 24, 17, "0", "0", "速度。", "0", "0", "0", "0", "0", "cv_sk_RED_SP_n21", "0", "0"},
[4400600133] = {4400600133, 14006001, 25, 18, "0", "0", "把我變成人類……你可要對我負責啊……！", "0", "0", "0", "0", "0", "cv_sk_RED_SP_n22", "0", "0"},
[4400600134] = {4400600134, 14006001, 26, 19, "0", "0", "你可不准死。不然我真的會……很生氣的。", "0", "0", "0", "0", "0", "cv_sk_RED_SP_26", "0", "0"},
[4400600135] = {4400600135, 14006001, 27, 20, "0", "0", "那些原罪能成為我討好史蒂芬妮和你的禮物，還算是有點價值嘛。", "0", "0", "0", "0", "0", "cv_sk_RED_SP_27", "0", "0"},
[4400600136] = {4400600136, 14006001, 28, 21, "0", "0", "說起來我想到了……殺那些原罪不就是在殺和我一樣構造的生物嗎……", "0", "0", "0", "0", "0", "cv_sk_RED_SP_28", "0", "0"},
[4400600137] = {4400600137, 14006001, 29, 21, "0", "0", "泡得我都快生銹了……", "0", "0", "0", "0", "0", "cv_sk_RED_SP_29", "0", "0"},
[4400600138] = {4400600138, 14006001, 30, 22, "0", "0", "要是你現在進來……我大概不會趕你出去。不過我想領航也不敢，哈哈畢竟是正人君子嘛……這也挺好。沒有在說你不好的意思哦？哈哈。", "0", "0", "0", "0", "0", "cv_sk_RED_SP_30", "0", "0"},
[4400600139] = {4400600139, 14006001, 31, 23, "0", "0", "由人所鑄就的人，完美的人類，機械人也是人。", "0", "0", "0", "0", "0", "cv_sk_RED_SP_31", "0", "0"},
[4400600140] = {4400600140, 14006001, 32, 24, "0", "0", "不出我所料了。", "0", "0", "0", "0", "0", "cv_sk_RED_SP_32", "0", "0"},
[4400600141] = {4400600141, 14006001, 33, 25, "0", "0", "哎呀，身上又濺到血了……是敵人的吧？反正不是我的。", "0", "0", "0", "0", "0", "cv_sk_RED_SP_33", "0", "0"},
[4400600142] = {4400600142, 14006001, 34, 26, "0", "0", "錯過今晚要等明年啦，及時享樂，boy。", "0", "0", "0", "0", "0", "cv_sk_RED_SP_n25", "0", "0"},
[4400600143] = {4400600143, 14006001, 35, 27, "0", "0", "我打賭原罪會被我的完美嚇得不敢動彈。", "0", "0", "0", "0", "0", "cv_sk_RED_SP_35", "0", "0"},
[4400600144] = {4400600144, 14006001, 36, 28, "0", "0", "沒電了，我先走了。", "0", "0", "0", "0", "0", "cv_sk_RED_SP_36", "0", "0"},
[4400600145] = {4400600145, 14006001, 37, 29, "0", "0", "哎，這種菜雞也能算是‘同伴’？", "0", "0", "0", "0", "0", "cv_sk_RED_SP_37", "0", "0"},
[4400600146] = {4400600146, 14006001, 38, 30, "0", "0", "只有我還不夠嗎？只是從勝率來說沒有任何變化。", "0", "0", "0", "0", "0", "cv_sk_RED_SP_38", "0", "0"},
[4400600147] = {4400600147, 14006001, 39, 31, "0", "0", "升級……胸部！", "0", "0", "0", "0", "0", "cv_sk_RED_SP_39", "0", "0"},
[4400600148] = {4400600148, 14006001, 40, 32, "0", "0", "升級……超級胸部！", "0", "0", "0", "0", "0", "cv_sk_RED_SP_40", "0", "0"},
[4400600149] = {4400600149, 14006001, 41, 33, "0", "0", "你穿得像個NPC……", "0", "0", "0", "0", "0", "cv_sk_RED_SP_41", "0", "0"},
[4400600150] = {4400600150, 14006001, 42, 34, "0", "0", "能調整的參數也太少了", "0", "0", "0", "0", "0", "cv_sk_RED_SP_42", "0", "0"},
[4400600151] = {4400600151, 14006001, 43, 35, "0", "0", "這麼多紙質信件？原始人打過來了？", "0", "0", "0", "0", "0", "cv_sk_RED_SP_43", "0", "0"},
[4400600152] = {4400600152, 14006001, 44, 36, "0", "0", "我可以順著網路刪掉你的遊戲存檔。", "0", "0", "0", "0", "0", "cv_sk_RED_SP_44", "0", "0"},
[4400600153] = {4400600153, 14006001, 45, 37, "0", "0", "嗯……", "0", "0", "0", "0", "0", "cv_sk_RED_SP_45", "0", "0"},
[404300] = {404300, 10043, 1, 1, "0", "0", "蒼霧殘響", "0", "0", "0", "0", "0", "cv_hikari_01", "0", "0"},
[404301] = {404301, 10043, 2, 2, "0", "0", "待在爸爸身邊？好呀~", "0", "0", "0", "0", "0", "cv_hikari_02", "0", "0"},
[404302] = {404302, 10043, 3, 3, "0", "0", "爸爸——！我通過自己的努力終於又誕生了！我好想你！", "0", "0", "0", "0", "0", "cv_hikari_03", "0", "0"},
[404303] = {404303, 10043, 4, 4, "0", "idle", "我來到這個世界這麼久了都沒有見到過媽媽……嗯……說實話前世也沒有見過媽媽……", "0", "0", "0", "0", "0", "cv_hikari_04", "0", "0"},
[404304] = {404304, 10043, 5, 4, "0", "idle2", "要帶我去見一見媽媽？嗯……希望她是個和爸爸一樣好相處的人，不要佔用我和爸爸的時間……如果我不喜歡的話就算是媽媽我也不會給她好臉色看的。", "0", "0", "0", "0", "0", "cv_hikari_05", "0", "0"},
[404305] = {404305, 10043, 6, 4, "0", "idle3", "爸爸是只屬於我一個人的爸爸。我是不會把爸爸拱手讓給別人的。絕對不會。", "0", "0", "0", "0", "0", "cv_hikari_06", "0", "0"},
[404306] = {404306, 10043, 6, 4, "0", "idle4", "哈？爸爸又去找其他人聊天了對吧？很開心吧？開心嗎？怎麼不笑了？聊天記錄給我看一下？為什麼我不是爸爸的特別關注？這個女的是誰？為什麼你們沒有聊天記錄，全清除了？", "0", "0", "0", "0", "0", "cv_hikari_44", "0", "0"},
[404307] = {404307, 10043, 7, 5, "1_》_0_0.8", "level1", "爸爸……你說了還有很多要告訴我的事情吧？請再多教教我吧……各種各樣的事情……我不想再離開爸爸了……", "0", "0", "0", "0", "0", "cv_hikari_07", "0", "0"},
[404308] = {404308, 10043, 8, 5, "1_》_0_0.8", "level2", "影、影之國的女王嗎……真沒想到媽媽竟然是這種人。", "0", "0", "0", "0", "0", "cv_hikari_08", "0", "0"},
[404309] = {404309, 10043, 9, 5, "1_》_100_1.5", "level3", "爸爸——媽媽又和一群小孩子玩在一起了。還在自顧自地說著“影之國的女王”什麼的話……她也……她也太幼稚了……我不喜歡。", "0", "0", "0", "0", "0", "cv_hikari_09", "0", "0"},
[404310] = {404310, 10043, 10, 5, "1_》_500_2", "level4", "爸爸——媽媽又把我放在冰箱裡的甜點偷吃了。“吾、吾才沒有偷吃！還有都說了不要叫吾媽媽了，吾才十八歲怎麼會有你這麼大的女兒！”", "0", "0", "0", "0", "0", "cv_hikari_10", "0", "0"},
[404311] = {404311, 10043, 11, 5, "1_》_1000_2.5", "level5", "爸爸，我愛你……當然也喜歡媽媽。", "0", "0", "0", "0", "0", "cv_hikari_11", "0", "0"},
[404312] = {404312, 10043, 12, 6, "0", "0", "謝謝爸爸！", "0", "0", "0", "0", "0", "cv_hikari_12", "0", "0"},
[404313] = {404313, 10043, 13, 7, "0", "0", "太棒了，好開心！", "0", "0", "0", "0", "0", "cv_hikari_13", "0", "0"},
[404314] = {404314, 10043, 14, 8, "0", "0", "爸爸……請不要離開我的視線……請看著我，把我的身姿刻進每一滴血液中……", "0", "0", "0", "0", "0", "cv_hikari_14", "0", "0"},
[404315] = {404315, 10043, 15, 9, "0", "0", "無法呼吸了，我現在……好幸福。", "0", "0", "0", "0", "0", "cv_hikari_15", "0", "0"},
[404316] = {404316, 10043, 16, 10, "0", "0", "好溫順的敵人？真可愛!全都可以殺了吧？", "0", "0", "0", "0", "0", "cv_hikari_16", "0", "0"},
[404317] = {404317, 10043, 17, 11, "0", "0", "爸爸……你看啊~全都殺掉了~", "0", "0", "0", "0", "0", "cv_hikari_17", "0", "0"},
[404318] = {404318, 10043, 18, 12, "0", "0", "我可是人類的希望……怎麼會出紕漏！？", "0", "0", "0", "0", "0", "cv_hikari_18", "0", "0"},
