[4004300102] = {4004300102, 10043001, 3, 3, "0", "0", "爸爸——！我通過自己的努力終於又誕生了！我好想你！", "0", "0", "0", "0", "0", "cv_sk_hikari_03", "0", "0"},
[4004300103] = {4004300103, 10043001, 91, 4, "0", "idle", "爸爸……你要是離我太遠，我可要生氣了哦？我不保證會發生什麼哦？", "0", "0", "0", "0", "0", "cv_sk_hikari_n02", "0", "idle,idle"},
