[4000500100] = {4000500100, 10005001, 1, 1, "0", "0", "蒼霧殘響！", "苍雾残响（ハツリバーブ）！", "0", "0", "苍雾残响！", "0", "cv_karenn_33", "0", "0"},
[4000500101] = {4000500101, 10005001, 2, 2, "0", "0", "這麼在意小生，難道說……", "ボクのことがそんなに気になるの？もしかして……", "0", "0", "这么在意小生，难道说……", "0", "cv_karenn_2", "0", "0"},
[4000500102] = {4000500102, 10005001, 3, 3, "0", "0", "小生名為華戀，如果能接下小生這一腳的話小生就跟定你了喔。", "ボクの名は华恋。もしボクの蹴りを受け流すことができたなら、结婚してあげるよ！", "0", "0", "小生名为华恋，如果能接下小生这一脚的话小生就跟定你了哦。", "0", "cv_karenn_1", "0", "0"},
[4000500103] = {4000500103, 10005001, 91, 4, "0", "idle", "我說……你是不是已經有點累了啊？如果累了的話就趕快去休息吧，這裡有小生在就好。", "あのね……もしかして、疲れてきた？だったら早く休んで！ここはボクに任せて。", "0", "0", "我说……你是不是已经有点累了啊？如果累了的话就赶快去休息吧，这里有小生在就好。", "0", "cv_karenn_3", "0", "idle,idle"},
[4000500104] = {4000500104, 10005001, 94, 4, "0", "idle2", "輸贏並不是關鍵，重要的是在交手時的心理交流。正所謂不打不相識，只有好好打上一架才能真正瞭解一個人啊。", "手合わせする时は、胜败なんかより、心の交流の方が大事だよ。「けんかをしなければ友达になれない」って言うでしょ？人を理解するにはちゃんとした手合わせが必要だってこと。", "0", "0", "输赢并不是关键，重要的是在交手时的心理交流。正所谓不打不相识，只有好好打上一架才能真正了解一个人啊。", "0", "cv_karenn_4", "0", "idle2,idle2"},
[4000500105] = {4000500105, 10005001, 98, 4, "0", "idle3", "華夢？啊，她是小生的姐姐，也是小生的對手。從很小的時候我們就在一起修行了。", "华梦？ああ、あれはボクの姉で、好敌手だよ。小さい顷からずっと一绪に修行してるし。", "0", "0", "华梦？啊，她是小生的姐姐，也是小生的对手。从很小的时候我们就在一起修行了。", "0", "cv_karenn_30", "0", "idle3,idle3"},
[4000500106] = {4000500106, 10005001, 93, 5, "1_》_0_0.8", "switch1", "小生自己倒是沒什麼志向，加入艾吉斯也只是單純覺得這裡一定會有小生中意的強者罷了。", "ボクには个人的な志なんかない。アイギスに入ったのも、ボクの気に入る强者がいそうだと思ったから。ただそれだけ。", "0", "0", "小生自己倒是没什么志向，加入艾吉斯也只是单纯觉得这里一定会有小生中意的强者罢了。", "0", "cv_karenn_31", "0", "switch1,switch1"},
[4000500107] = {4000500107, 10005001, 102, 5, "1_》_0_0.8", "switch2", "要來打上一架嗎？小生已經準備好了喔。", "手合わせをやる？ボクはもう、准备出来てるよ。", "0", "0", "要来打上一架吗？小生已经准备好了哦。", "0", "cv_karenn_5", "0", "switch2,switch2"},
[4000500108] = {4000500108, 10005001, 96, 5, "1_》_0_0.8", "switch3", "小生自己倒是沒什麼志向，加入艾吉斯也只是單純覺得這裡一定會有小生中意的強者罷了。", "ボクには个人的な志なんかない。アイギスに入ったのも、ボクの気に入る强者がいそうだと思ったから。ただそれだけ。", "0", "0", "小生自己倒是没什么志向，加入艾吉斯也只是单纯觉得这里一定会有小生中意的强者罢了。", "0", "cv_karenn_31", "0", "switch3,switch3"},
[4000500109] = {4000500109, 10005001, 92, 5, "1_》_0_0.8", "touch1", "喔喔，不錯的一擊嘛，看來你的體內也流淌著多瑙的血啊。", "おお、なかなか良い攻撃だったね。あんたの体にも九州岛の血が流れてるようだ。", "0", "0", "噢噢，不错的一击嘛，看来你的体内也流淌着九州岛的血啊。", "0", "cv_karenn_6", "0", "touch1,touch1"},
[4000500110] = {4000500110, 10005001, 95, 5, "1_》_0_0.8", "touch2", "不是這樣的啦，像你這樣的踢腿是沒法將情感傳遞給小生的啦。看好了喔，小生再給你演示一遍。", "そうじゃなくて……！そんな足蹴りじゃ気持ちをボクに伝えることはできないよ。いい？ボクがもう一回手本をやって见せてあげる。", "0", "0", "不是这样的啦，像你这样的踢腿是没法将情感传递给小生的啦。看好了哦，小生再给你演示一遍。", "0", "cv_karenn_7", "0", "touch2,touch2"},
[4000500111] = {4000500111, 10005001, 106, 5, "1_》_0_0.8", "touch3", "為什麼……為什麼無法使出全力呢？只要與你對視的話，小生全身的力氣都會溜走……這樣的話可沒法將現在的心情好好傳遞給你啊。", "なんで……なんで全力を出せないんだろ？あんたと目が合うと、全身の力が抜けちゃうっていうか……こんなんじゃ今の気持ちをちゃんとあんたに伝えられないじゃないか！", "0", "0", "为什么……为什么无法使出全力呢？只要与你对视的话，小生全身的力气都会溜走……这样的话可没法将现在的心情好好传递给你啊。", "0", "cv_karenn_8", "0", "touch3,touch3"},
[4000500112] = {4000500112, 10005001, 12, 6, "0", "0", "呼呼呼，小腿上的肌肉增加了喔~", "ふふ、ふくらはぎの筋肉が増えた！", "0", "0", "呼呼呼，小腿上的肌肉增加了哦~", "0", "cv_karenn_9", "0", "0"},
[4000500113] = {4000500113, 10005001, 13, 7, "0", "0", "喔，小生在收下你的禮物後好像又變強了欸！", "おっ！あんたからのプレゼントをもらったお阴でまた强くなったみたい！", "0", "0", "哦，小生在收下你的礼物后好像又变强了哎！", "0", "cv_karenn_10", "0", "0"},
[4000500114] = {4000500114, 10005001, 14, 8, "0", "0", "完全形態！領航，還請務必要收下這注入了小生所有情感的一擊！", "完全形态！ナビゲーター、このボクの気持ちが込められた一撃を是非受け取めて！", "0", "0", "完全形态！领航，还请务必要收下这注入了小生所有情感的一击！", "0", "cv_karenn_11", "0", "0"},
[4000500115] = {4000500115, 10005001, 15, 9, "0", "0", "戰鬥變得得心應手了！", "戦闘が上达したね！", "0", "0", "战斗变得得心应手了！", "0", "cv_karenn_12", "0", "0"},
[4000500116] = {4000500116, 10005001, 16, 10, "0", "0", "我可沒打算和異獸交朋友啊。", "原罪なんかと友达になるつもりはないから。", "0", "0", "我可没打算和原罪交朋友啊。", "0", "cv_karenn_13", "0", "0"},
[4000500117] = {4000500117, 10005001, 17, 11, "0", "0", "這個世界上沒有什麼傢伙是用武術打不倒的！", "武术で倒せない奴なんてこの世界には存在しない！", "0", "0", "这个世界上没有什么家伙是用武术打不倒的！", "0", "cv_karenn_14", "0", "0"},
[4000500118] = {4000500118, 10005001, 18, 12, "0", "0", "稍微有點吃力啊，回去之後再鍛煉下好了。", "ギリだったね。帰ってもっと锻錬した方がいい。", "0", "0", "稍微有点吃力啊，回去之后再锻炼下好了。", "0", "cv_karenn_15", "0", "0"},
[4000500119] = {4000500119, 10005001, 19, 13, "0", "0", "果然……它們只是沒有心的怪物。", "やっぱり……あいつらは心のないモンスターに过ぎない。", "0", "0", "果然……他们只是没有心的怪物。", "0", "cv_karenn_16", "0", "0"},
[4000500120] = {4000500120, 10005001, 20, 14, "0", "0", "原來還有武術達不到的境界……", "武术で到达できない领域もあったんだ……", "0", "0", "原来还有武术达不到的境界……", "0", "cv_karenn_17", "0", "0"},
[4000500121] = {4000500121, 10005001, 21, 15, "0", "0", "還差點意思啊。", "ちょっと足りないかも。", "0", "0", "还差点意思啊。", "0", "cv_karenn_18", "0", "0"},
[4000500122] = {4000500122, 10005001, 23, 16, "0", "0", "小生來了喔！", "华恋、参る！", "0", "0", "小生来了哦！", "0", "cv_karenn_19", "0", "0"},
[4000500123] = {4000500123, 10005001, 24, 17, "0", "0", "來吧，朝小生攻擊吧。", "さぁ、かかってこい！", "0", "0", "来吧，朝小生攻击吧。", "0", "cv_karenn_21", "0", "0"},
[4000500124] = {4000500124, 10005001, 26, 19, "0", "0", "小生的定力……還遠遠不夠……", "ボクの定力……まだまだだったね……", "0", "0", "小生的定力……还远远不够……", "0", "cv_karenn_20", "0", "0"},
[4000500125] = {4000500125, 10005001, 27, 20, "0", "0", "洗澡，也就是與水的戰鬥嗎？小生瞭解了。", "お风吕？つまり水との戦い？分かった。", "0", "0", "洗澡，也就是与水的战斗吗？小生清楚了。", "0", "cv_karenn_23", "0", "0"},
[4000500126] = {4000500126, 10005001, 28, 21, "0", "0", "如果是水的話應該能接住小生的一腳吧。", "水ならボクの足蹴りを受け流せるよね？", "0", "0", "如果是水的话应该能接住小生的一脚吧。", "0", "cv_karenn_24", "0", "0"},
[4000500127] = {4000500127, 10005001, 29, 21, "0", "0", "聽說過嗎？在小生的故鄉，有人會使用瀑布進行修行呢。", "ボクの故郷には滝を使って锻錬する人がいるんだ。こんな话、闻いたことある？", "0", "0", "听说过吗？在小生的故乡，有人会使用瀑布进行修行呢。", "0", "cv_karenn_25", "0", "0"},
[4000500128] = {4000500128, 10005001, 30, 22, "0", "0", "像小生一樣使出全心全意的一擊吧！", "ボクのみたいに、会心の一撃を出そう！", "0", "0", "像小生一样使出全心全意的一击吧！", "0", "cv_karenn_26", "0", "0"},
[4000500129] = {4000500129, 10005001, 31, 23, "0", "0", "猜錯了的話就準備接下小生這腳吧。", "外れたらボクの足蹴りを食らうことになるからね。", "0", "0", "猜错了的话就准备接下小生这脚吧。", "0", "cv_karenn_27", "0", "0"},
[4000500130] = {4000500130, 10005001, 32, 24, "0", "0", "看來我們之間的默契已經足夠了呢。", "ボクたちはもう、心が通じ合ってるみたいだね。", "0", "0", "看来我们之间的默契已经足够了呢。", "0", "cv_karenn_28", "0", "0"},
[4000500131] = {4000500131, 10005001, 33, 25, "0", "0", "嘿呀！我踹！", "はっ！足蹴りを食らえ！", "0", "0", "嘿呀！我踹！", "0", "cv_karenn_29", "0", "0"},
[4000500132] = {4000500132, 10005001, 34, 26, "0", "0", "歡迎回來，多瑙的領航，小生正愁沒有對手呢。", "お帰り、ダニューブのナビゲーター。ボクはちょうど、手合わせの相手がいなくて悩んでたところだ。", "0", "0", "欢迎回来，多瑙的领航，小生正愁没有对手呢。", "0", "cv_karenn_32", "0", "0"},
[4000500133] = {4000500133, 10005001, 35, 27, "0", "0", "就讓小生用拳腳為你開路吧。", "ボクが武术で道を切り开いてやる！", "0", "0", "就让小生用拳脚为你开路吧。", "0", "cv_karenn_34", "0", "0"},
[4000500134] = {4000500134, 10005001, 36, 28, "0", "0", "修行又要開始了啊。", "修行がまた始まるってことだね。", "0", "0", "修行又要开始了啊。", "0", "cv_karenn_35", "0", "0"},
[4000500135] = {4000500135, 10005001, 37, 29, "0", "0", "部隊已經集合完畢了喔。", "部队はもう、集合済みだ。", "0", "0", "部队已经集合完毕了哦。", "0", "cv_karenn_36", "0", "0"},
[4000500136] = {4000500136, 10005001, 38, 30, "0", "0", "希望能招到個好對手啊。", "好敌手が来ると良いな。", "0", "0", "希望能招到个好对手啊。", "0", "cv_karenn_37", "0", "0"},
[4000500137] = {4000500137, 10005001, 39, 31, "0", "0", "我還是更習慣九州的裝備啊。", "个人的には九州岛の装备の方がいい。", "0", "0", "我还是更习惯九州岛的装备啊。", "0", "cv_karenn_38", "0", "0"},
[4000500138] = {4000500138, 10005001, 40, 32, "0", "0", "採購的事情就交給小生吧！", "买いものならボクに任せて！", "0", "0", "采购的事情就交给小生吧！", "0", "cv_karenn_39", "0", "0"},
[4000500139] = {4000500139, 10005001, 41, 33, "0", "0", "身份確認。", "身分确认だ。", "0", "0", "身份确认。", "0", "cv_karenn_40", "0", "0"},
[4000500140] = {4000500140, 10005001, 42, 34, "0", "0", "按照自己的喜好來變更設定吧。", "自分の好みに合わせて设定を変更しよう。", "0", "0", "按照自己的喜好来变更设置吧。", "0", "cv_karenn_41", "0", "0"},
[4000500141] = {4000500141, 10005001, 43, 35, "0", "0", "檢查一下有沒有新的來信吧。", "新しいメールが来てるかチェックしよう。", "0", "0", "检查一下有没有新的来信吧。", "0", "cv_karenn_42", "0", "0"},
[4000500142] = {4000500142, 10005001, 44, 36, "0", "0", "這是領航專用的聊天室吧。", "これはナビゲーター専用のチャットルームかな？", "0", "0", "这是领航专用的聊天室吧。", "0", "cv_karenn_43", "0", "0"},
[4000500143] = {4000500143, 10005001, 45, 37, "0", "0", "由小生來確認一下吧。", "ボクが确认してあげる。", "0", "0", "由小生来确认一下吧。", "0", "cv_karenn_44", "0", "0"},
[4302000200] = {4302000200, 13020002, 1, 1, "0", "0", "蒼霧殘響", "ハツ…ふぁ～（あくび）…リバーブ", "0", "0", "0", "0", "cv_mayball_1", "0", "0"},
[4302000201] = {4302000201, 13020002, 2, 2, "0", "0", "確定交由我嗎？事先說好，不保證能勝任哦。", "私に任せるの？あんまり、期待しないでね。", "0", "0", "0", "0", "cv_mayball_2", "0", "0"},
[4302000202] = {4302000202, 13020002, 3, 3, "0", "0", "這裡是梅貝爾·伊司，薩哈拉蒼穹學院的一名哲學教師，隸屬于制蜜人小隊。唔，介紹應該就這些了……", "私はメイベル・イース。サハラの「ファーマメントアカデミー」で哲学の授业担当。ハニーメイカーに所属。これぐらいかな……。", "0", "0", "0", "0", "cv_mayball_3", "0", "0"},
[4302000203] = {4302000203, 13020002, 91, 4, "0", "idle", "等工作完就放鬆下吧，去咖啡館會會朋友，享受靜謐、芬芳，以及……哈嗚~思想的碰撞。", "仕事が终わったら、友达とカフェで会って、リラックスして、静かな时间と良い香り、そして…ふぁ～、思想のぶつかり合いを楽しむの。", "0", "0", "0", "0", "cv_mayball_4", "0", "0,idle"},
[4302000204] = {4302000204, 13020002, 94, 4, "0", "idle2", "我這悠閒散漫的樣子不太受一些學生歡迎，雖說作為教師有些失敗，但反面教材也算教嘛~", "のんびりしてる私は、一部の生徒からあまり良く思われてないみたい。でも教师としては成功かな…反面教师としてだけど。", "0", "0", "0", "0", "cv_mayball_5", "0", "0,idle2"},
[4302000205] = {4302000205, 13020002, 98, 4, "0", "idle3", "普瑞席歐和墨君都是工作狂，小隊有她們真讓人輕鬆不少。至於斯緹菈，軟乎乎的非常治癒呢，領航同學也要試試嗎？", "プレシオと墨君（ぼくくん）は仕事狂いだから、彼女たちがいるとチームはかなり楽になる。ステラは……柔らかくて愈されるの、ナビゲーターくんも试してみない？", "0", "0", "0", "0", "cv_mayball_6", "0", "0,idle3"},
[4302000206] = {4302000206, 13020002, 93, 5, "1_》_0_0.8", "switch1", "存在即虛無，因此，存在才會不斷探尋意義……但虛無真的能被填滿嗎？", "存在は虚无であるが故に、意味を探し続ける。虚无を埋めることは出来るのかな？", "0", "0", "0", "0", "cv_mayball_7", "0", "0,switch1"},
[4302000207] = {4302000207, 13020002, 102, 5, "1_》_0_0.8", "switch2", "我看起來有些困？請不用擔心，就算不小心睡著，手上的書正好能作為一個小枕頭。", "少し疲れているように见える？心配しないで。うっかり寝てしまっても、この本がちょうど枕代わりになるから。", "0", "0", "0", "0", "cv_mayball_8", "0", "0,switch2"},
[4302000208] = {4302000208, 13020002, 96, 5, "1_》_0_0.8", "switch3", "存在即虛無，因此，存在才會不斷探尋意義……但虛無真的能被填滿嗎？", "存在は虚无であるが故に、意味を探し続ける。虚无を埋めることは出来るのかな？", "0", "0", "0", "0", "cv_mayball_7", "0", "0,switch3"},
[4302000209] = {4302000209, 13020002, 92, 5, "1_》_0_0.8", "level1", "哲學書艱深晦澀，有些能打消困倦，有些能使人安眠。領航同學喜歡哪種呢？", "哲学の本は难解で深远。眠気が飞ぶものもあれば、眠りへ诱うものもある。ナビゲーターくんはどちらがお好み？", "0", "0", "0", "0", "cv_mayball_9", "0", "0,level1"},
[4302000210] = {4302000210, 13020002, 95, 5, "1_》_0_0.8", "level2", "偶爾會感到迷茫嗎？沒關係，能夠迷茫正是“存在先於本質”的證明，這不是壞事。", "たまに迷いを感じることはある？心配しないで。迷いを感じることこそ「実存は本质に先立つ」ということの证明。悪いことではないよ。", "0", "0", "0", "0", "cv_mayball_10", "0", "0,level2"},
[4302000211] = {4302000211, 13020002, 106, 5, "1_》_0_0.8", "level3", "領航同學，我可以更加依靠你一些嗎？比如……要是嗜睡症不小心發作，希望正好有你在我身邊……這種感覺？", "ナビゲーターくん、もっと君に頼ってもいいかな？…もし过眠症の発作が起きたとき、君が侧にいてくれたらいいなって思って。", "0", "0", "0", "0", "cv_mayball_11", "0", "0,level3"},
[4302000212] = {4302000212, 13020002, 106, 5, "1_》_0_0.8", "level4", "領航同學，我可以更加依靠你一些嗎？比如……要是嗜睡症不小心發作，希望正好有你在我身邊……這種感覺？", "ナビゲーターくん、もっと君に頼ってもいいかな？…もし过眠症の発作が起きたとき、君が侧にいてくれたらいいなって思って。", "0", "0", "0", "0", "cv_mayball_11", "0", "0,level4"},
[4302000213] = {4302000213, 13020002, 12, 6, "0", "0", "哈嗚~謝謝。", "ふぅ～、ありがとう。", "0", "0", "0", "0", "cv_mayball_12", "0", "0"},
[4302000214] = {4302000214, 13020002, 13, 7, "0", "0", "思維更清晰了，像在品一杯冰咖啡。", "头の中がすっきりしてる。まるでアイスコーヒーを饮んだ后みたい。", "0", "0", "0", "0", "cv_mayball_13", "0", "0"},
[4302000215] = {4302000215, 13020002, 14, 8, "0", "0", "“覺醒”嗎？這詞真不適合我呢，說不定我下一秒就會睡著。但領航同學一直對我有所期待，果然我還是拿出十足的幹勁吧~", "「覚醒」？私にはあまり似合わないね。もしかしたら、次の瞬间には寝てしまうかもしれないのに。でも、ナビゲーターくんが期待してくれてるなら、顽张ってみようかな。", "0", "0", "0", "0", "cv_mayball_14", "0", "0"},
[4302000216] = {4302000216, 13020002, 15, 9, "0", "0", "用思想武裝自己呢。", "思考で武装するよ。", "0", "0", "0", "0", "cv_mayball_15", "0", "0"},
[4302000217] = {4302000217, 13020002, 16, 10, "0", "0", "闊別已久的戰場啊。", "久しぶりの戦场だ。", "0", "0", "0", "0", "cv_mayball_16", "0", "0"},
[4302000218] = {4302000218, 13020002, 17, 11, "0", "0", "哎呀，不小心發揮超常了。", "おっと、やりすぎちゃったかな。", "0", "0", "0", "0", "cv_mayball_17", "0", "0"},
[4302000219] = {4302000219, 13020002, 18, 12, "0", "0", "不完美才是人生的常態，不用在意哦。", "不完全こそ人らしさだよ。心配しないで。", "0", "0", "0", "0", "cv_mayball_18", "0", "0"},
[4302000220] = {4302000220, 13020002, 19, 13, "0", "0", "這樣下去沒法給學生們當榜樣了呢。", "これじゃあお手本を见せられないね。", "0", "0", "0", "0", "cv_mayball_19", "0", "0"},
[4302000221] = {4302000221, 13020002, 20, 14, "0", "0", "果然下次作戰把我換掉更好吧~？", "やっぱり、次の作戦では私を交代させた方が良さそうだね～。", "0", "0", "0", "0", "cv_mayball_20", "0", "0"},
[4302000222] = {4302000222, 13020002, 23, 16, "0", "0", "加油吧。", "顽张って。", "0", "0", "0", "0", "cv_mayball_21", "0", "0"},
[4302000223] = {4302000223, 13020002, 26, 19, "0", "0", "我還沒睡著呢。", "まだ寝てないよ。", "0", "0", "0", "0", "cv_mayball_22", "0", "0"},
[4302000224] = {4302000224, 13020002, 24, 17, "0", "0", "希望醒來後還能再見到大家。", "起きたらまた会えますように……", "0", "0", "0", "0", "cv_mayball_23", "0", "0"},
[4302000225] = {4302000225, 13020002, 27, 20, "0", "0", "為了更好地思考，讓我們洗卻身體的疲憊吧~", "体の疲れを愈して、思考をスムーズにしよ～。", "0", "0", "0", "0", "cv_mayball_24", "0", "0"},
[4302000226] = {4302000226, 13020002, 28, 21, "0", "0", "哈嗚~這裡比外面更容易讓人發困，領航同學可不能比我先睡著哦。", "ふぁ～、ここは外よりも寝やすいね。ナビゲーターくんは先に寝ちゃだめだよ。", "0", "0", "0", "0", "cv_mayball_25", "0", "0"},
[4302000227] = {4302000227, 13020002, 29, 21, "0", "0", "古時起，薩哈拉的哲學家們就喜歡在浴場討論問題，領航同學此刻也有想要知曉的問題嗎？", "昔からサハラの哲学者たちはお风吕で议论するのが大好きだったの。ナビゲーターくんは何か话したいことはある？", "0", "0", "0", "0", "cv_mayball_26", "0", "0"},
[4302000228] = {4302000228, 13020002, 30, 22, "0", "0", "遊戲時間開始~", "游びの时间だ～。", "0", "0", "0", "0", "cv_mayball_27", "0", "0"},
[4302000229] = {4302000229, 13020002, 31, 23, "0", "0", "那麼答案是什麼呢？", "それでは答えは？", "0", "0", "0", "0", "cv_mayball_28", "0", "0"},
[4302000230] = {4302000230, 13020002, 32, 24, "0", "0", "答對了，一百分！", "正解、ひゃくてん！", "0", "0", "0", "0", "cv_mayball_29", "0", "0"},
[4302000231] = {4302000231, 13020002, 33, 25, "0", "0", "很遺憾，不及格呢~", "残念ながら、不正解～。", "0", "0", "0", "0", "cv_mayball_30", "0", "0"},
[4302000232] = {4302000232, 13020002, 34, 26, "0", "0", "時間過得真快，又要開始工作了。", "时间が経つのは速いね。もう仕事の时だ。", "0", "0", "0", "0", "cv_mayball_31", "0", "0"},
[4302000233] = {4302000233, 13020002, 35, 27, "0", "0", "該認真起來了嗎？", "本気を出しちゃう？", "0", "0", "0", "0", "cv_mayball_32", "0", "0"},
[4302000234] = {4302000234, 13020002, 36, 28, "0", "0", "模擬戰就隨意點吧。", "模拟戦はほどほどにね。", "0", "0", "0", "0", "cv_mayball_33", "0", "0"},
[4302000235] = {4302000235, 13020002, 37, 29, "0", "0", "突擊檢查~有開小差的同學嗎？", "抜き打ち検査～。サボってる人いない？", "0", "0", "0", "0", "cv_mayball_34", "0", "0"},
[4302000236] = {4302000236, 13020002, 38, 30, "0", "0", "謔~要出現神秘轉校生了。", "へぇ～、転校生が来るみたいだよ。", "0", "0", "0", "0", "cv_mayball_35", "0", "0"},
[4302000237] = {4302000237, 13020002, 39, 31, "0", "0", "會得到什麼呢？稍微期待下吧。", "何が出るのか、期待してね。", "0", "0", "0", "0", "cv_mayball_36", "0", "0"},
[4302000238] = {4302000238, 13020002, 40, 32, "0", "0", "幫忙留意下新款睡衣哦。", "新デザインのパジャマ探し、手伝って？", "0", "0", "0", "0", "cv_mayball_37", "0", "0"},
[4302000239] = {4302000239, 13020002, 41, 33, "0", "0", "看看領航同學的志向填了什麼。", "どれどれ、ナビゲーターくんの进路希望は……", "0", "0", "0", "0", "cv_mayball_38", "0", "0"},
[4302000240] = {4302000240, 13020002, 42, 34, "0", "0", "領航同學真講究呢~", "ナビゲーターくん、こだわってるね。", "0", "0", "0", "0", "cv_mayball_39", "0", "0"},
[4302000241] = {4302000241, 13020002, 43, 35, "0", "0", "比起口頭交流，果然文字更方便呢。", "会话より、文字のほうが便利かも。", "0", "0", "0", "0", "cv_mayball_40", "0", "0"},
[4302000242] = {4302000242, 13020002, 44, 36, "0", "0", "有什麼想對大家說的呢？", "みんなに何か言いたいの？", "0", "0", "0", "0", "cv_mayball_41", "0", "0"},
[4302000243] = {4302000243, 13020002, 45, 37, "0", "0", "好、好。", "はい、はい。", "0", "0", "0", "0", "cv_mayball_42", "0", "0"},
[4000200100] = {4000200100, 10002001, 1, 1, "0", "0", "蒼霧殘響！", "苍雾残响（ハツリバーブ）！", "0", "0", "苍雾残响！", "0", "cv_hank_31", "0", "0"},
[4000200101] = {4000200101, 10002001, 2, 2, "0", "0", "欸？這樣真的好嗎，我這種人完全不知道該怎麽處理這種情況欸。", "え？本当にいいのか？こういうとき、どうすればいいのか全然わからないんだが。", "0", "0", "哎？这样真的好吗，我这种人完全不知道该怎么处理这种情况哎。", "0", "cv_hank_2", "0", "0"},
[4000200102] = {4000200102, 10002001, 3, 3, "0", "0", "唷，你就是領航嗎？話先說好，我只是個傭兵喔。", "よぉ！あんたがナビゲーターか？言っておくが、私はただの佣兵だ。", "0", "0", "哟，你就是领航吗？话先说好，我只是个佣兵哦。", "0", "cv_hank_1", "0", "0"},
[4000200103] = {4000200103, 10002001, 91, 4, "0", "idle", "給多少錢辦多少事，不光光是為了我好也是為了雇主好喔。", "私は报酬に応じた仕事をする。自分にとっても雇用主にとっても良いことだと思うんだがな。", "0", "0", "给多少钱办多少事，不光光是为了我好也是为了雇主好哦。", "0", "cv_hank_3", "0", "0,idle"},
[4000200104] = {4000200104, 10002001, 91, 4, "0", "idle", "殺戮，殺戮，殺戮，殺戮……這就是我一直以來在做的工作……早在成為駕駛員之前，我就在幹類似的事情了。", "杀戮、杀戮、杀戮、杀戮……これが私の仕事だ……ドライバーになる前もずっと似たような事をやっていた。", "0", "0", "杀戮，杀戮，杀戮，杀戮……这就是我一直以来在做的工作……早在成为驾驶员之前，我就在干类似的事情了。", "0", "cv_hank_4", "0", "0,idle"},
[4000200105] = {4000200105, 10002001, 91, 4, "0", "idle", "雖然蒂娜是個蠻難相處的家夥，不過說實話，比起刀子嘴豆腐心的人，我更喜歡像她一樣言行一致的家夥。", "确かにティナは扱いにくいやつだけど、でも正直なところ、口が悪いけど心根が优しいっていう女の子より、彼女みたいな言行一致のやつの方がいい。", "0", "0", "虽然蒂娜是个蛮难相处的家伙，不过说实话，比起刀子嘴豆腐心的人，我更喜欢像她一样言行一致的家伙。", "0", "cv_hank_28", "0", "0,idle"},
[4000200106] = {4000200106, 10002001, 92, 5, "15_1_0_0.8", "level1", "加入艾吉斯的理由…嗯……當然是因為雇主給的錢足夠多啊。還有部分原因是因為我很在意那兩個女孩，在過去，我和姐姐的關系也不太好呢。", "アイギスに入った理由……うーん……それはもちろん、报酬がいいからに决まってるだろ。まぁ、あの二人の女の子のことが気になるからっていうのもなくはないが……昔、私も姉さんとは仲が悪かったからな。", "0", "0", "加入艾吉斯的理由…嗯……当然是因为雇主给的钱足够多啊。还有部分原因是因为我很在意那两个女孩，在过去，我和姐姐的关系也不太好呢。", "0", "cv_hank_29", "0", "0,level1"},
[4000200107] = {4000200107, 10002001, 92, 5, "15_1_0_0.8", "level1", "欸？這是什麽情況啊？", "ん？どういうことだ？", "0", "0", "哎？这是什么情况啊？", "0", "cv_hank_5", "0", "0,level1"},
[4000200108] = {4000200108, 10002001, 92, 5, "15_2_0_0.8", "level2", "嗯……雖然還有些奇怪，但是你應該是沒有惡意的吧。", "うーん……なんかよくわからないけど、悪意はないってことだろ？", "0", "0", "嗯……虽然还有些奇怪，但是你应该是没有恶意的吧。", "0", "cv_hank_6", "0", "0,level2"},
[4000200109] = {4000200109, 10002001, 92, 5, "15_2_0_0.8", "level2", "還真是少見，除了敵人外，居然還會有主動靠近我的家夥啊。難道說，你並沒有討厭我嗎？", "珍しい。敌以外に自分から私に近づいてくるやつがいただなんて。ひょっとして、私のこと、嫌じゃないのか？", "0", "0", "还真是少见，除了敌人外，居然还会有主动靠近我的家伙啊。难道说，你并没有讨厌我吗？", "0", "cv_hank_7", "0", "0,level2"},
[4000200110] = {4000200110, 10002001, 92, 5, "15_2_0_0.8", "level2", "雖然我只是一個拿錢辦事的傭兵，也不是很懂該怎麽表達自己的想法。但是，該怎麽說呢……哈！就是那個啊——能和你一起工作，真的非常開心！如果有機會的話想要一直和你一起工作！", "私は报酬に応じた仕事をするだけの佣兵、だから、自分の考えをどうやって伝えればいいのかもよくわからない。でも、なんというか……だから、あれだ――あんたと一绪に仕事をすることができて、本当に嬉しいんだ！出来るなら、あんたとはずっと一绪に仕事をしたい！", "0", "0", "虽然我只是一个拿钱办事的佣兵，也不是很懂该怎么表达自己的想法。但是，该怎么说呢……哈！就是那个啊——能和你一起工作，真的非常开心！如果有机会的话想要一直和你一起工作！", "0", "cv_hank_8", "0", "0,level2"},
[4000200111] = {4000200111, 10002001, 12, 6, "0", "0", "就只有這點嗎？哈，開玩笑的。", "これしかないのか？あはは、冗谈だ。", "0", "0", "就只有这点吗？哈，开玩笑的。", "0", "cv_hank_9", "0", "0"},
[4000200112] = {4000200112, 10002001, 13, 7, "0", "0", "拿錢辦事～拿錢辦事～今天要去砍誰呢？", "报酬に応じた仕事をするんだ、さて、今日は谁を斩ろうか？", "0", "0", "拿钱办事～拿钱办事～今天要去砍谁呢？", "0", "cv_hank_10", "0", "0"},
[4000200113] = {4000200113, 10002001, 14, 8, "0", "0", "呼啊——真是一筆好買賣呢～你就好好看著吧，我絕對不會讓雇主失望的！", "へぇー、これはうまい话だ。任せとけ！雇用主をがっかりさせるようなことは絶対しない。", "0", "0", "呼啊——真是一笔好买卖呢～你就好好看着吧，我绝对不会让雇主失望的！", "0", "cv_hank_11", "0", "0"},
[4000200114] = {4000200114, 10002001, 15, 9, "0", "0", "喔喔喔喔——揮刀的時候感覺更加有幹勁了啊！", "おおお――刀捌きが上手くなった気がするぞ！", "0", "0", "噢噢噢噢——挥刀的时候感觉更加有干劲了啊！", "0", "cv_hank_12", "0", "0"},
[4000200115] = {4000200115, 10002001, 16, 10, "0", "0", "好！工作開始～", "オッケー！仕事を始めようか。", "0", "0", "OK！工作开始～", "0", "cv_hank_13", "0", "0"},
[4000200116] = {4000200116, 10002001, 17, 11, "0", "0", "完美！", "パーフェクト！", "0", "0", "perfect！", "0", "cv_hank_14", "0", "0"},
[4000200117] = {4000200117, 10002001, 18, 12, "0", "0", "怎麽樣我很厲害吧？報酬可不要給少了喔。", "どうだ？私、凄いだろ？报酬の方はケチるなよ。", "0", "0", "怎么样我很厉害吧？报酬可不要给少了哦。", "0", "cv_hank_15", "0", "0"},
[4000200118] = {4000200118, 10002001, 19, 13, "0", "0", "嗯……我懂我懂，你看著扣點錢吧。", "うーん…...ああ、はいはい。报酬の方、适当に减らしておいて良いぞ。", "0", "0", "嗯……我懂我懂，你看着扣点钱吧。", "0", "cv_hank_16", "0", "0"},
[4000200119] = {4000200119, 10002001, 20, 14, "0", "0", "糟糕！", "ホーリーシット！", "0", "0", "holyshit！", "0", "cv_hank_17", "0", "0"},
[4000200120] = {4000200120, 10002001, 21, 15, "0", "0", "不堪一擊！", "一溜まりもないな！", "0", "0", "不堪一击！", "0", "cv_hank_18", "0", "0"},
[4000200121] = {4000200121, 10002001, 23, 16, "0", "0", "跑不了了喔～", "逃がさないぞ！", "0", "0", "跑不了了哦～", "0", "cv_hank_19", "0", "0"},
[4000200122] = {4000200122, 10002001, 26, 19, "0", "0", "可惡！", "シット！", "0", "0", "shit！", "0", "cv_hank_20", "0", "0"},
[4000200123] = {4000200123, 10002001, 27, 20, "0", "0", "喔～這可不是雇主該幹的活喔。", "へぇー、それは雇用主がやることじゃないと思うが。", "0", "0", "哦～这可不是雇主该干的活哦。", "0", "cv_hank_21", "0", "0"},
[4000200124] = {4000200124, 10002001, 28, 21, "0", "0", "要是不行了你就回去吧～", "疲れてるなら帰っていいぞ。", "0", "0", "要是不行了你就回去吧～", "0", "cv_hank_22", "0", "0"},
[4000200125] = {4000200125, 10002001, 29, 21, "0", "0", "啊——洗澡還真是個麻煩事啊～", "ああ――风吕って面倒くさい……", "0", "0", "啊——洗澡还真是个麻烦事啊～", "0", "cv_hank_23", "0", "0"},
[4000200126] = {4000200126, 10002001, 30, 22, "0", "0", "欸呀，這裏居然還會出現這種東西嗎？", "おっと、ここにはこんなもんも出てくるのか？", "0", "0", "哎呀，这里居然还会出现这种东西吗？", "0", "cv_hank_24", "0", "0"},
[4000200127] = {4000200127, 10002001, 31, 23, "0", "0", "搞快點啦，這裏實在是太熱了餵。", "早くしろ。ここ、めちゃくちゃ暑いんだ。", "0", "0", "搞快点啦，这里实在是太热了喂。", "0", "cv_hank_25", "0", "0"},
[4000200128] = {4000200128, 10002001, 32, 24, "0", "0", "不錯不錯，我們去喝一杯慶祝一下吧～", "いいね。お祝いに饮みにいこう。", "0", "0", "不错不错，我们去喝一杯庆祝一下吧～", "0", "cv_hank_26", "0", "0"},
[4000200129] = {4000200129, 10002001, 33, 25, "0", "0", "還行吧，我要回去睡覺了喔。", "まぁ、あれだ。帰って寝る。", "0", "0", "还行吧，我要回去睡觉了哦。", "0", "cv_hank_27", "0", "0"},
[4000200130] = {4000200130, 10002001, 34, 26, "0", "0", "唷，你回來啦，正好正好，我這邊正愁沒人陪我喝上一杯呢～", "よぉ！お帰り。ちょうどいい！谁か饮みに付き合ってくれないかなって思ってたところなんだ。", "0", "0", "呦，你回来啦，正好正好，我这边正愁没人陪我喝上一杯呢～", "0", "cv_hank_30", "0", "0"},
[4000200131] = {4000200131, 10002001, 35, 27, "0", "0", "來吧，讓我聽聽你的故事吧。", "さぁ、あんたの物语を闻かせろ。", "0", "0", "来吧，让我听听你的故事吧。", "0", "cv_hank_32", "0", "0"},
[4000200132] = {4000200132, 10002001, 36, 28, "0", "0", "無論是什麽樣的敵人，最後都會變成酬金。", "どんな敌であっても、最终的には报酬になるからな。", "0", "0", "无论是什么样的敌人，最后都会变成酬金。", "0", "cv_hank_33", "0", "0"},
[4000200133] = {4000200133, 10002001, 37, 29, "0", "0", "管理很多人一定很累吧。", "沢山の人を管理するのって、大変だろ。", "0", "0", "管理很多人一定很累吧。", "0", "cv_hank_34", "0", "0"},
[4000200134] = {4000200134, 10002001, 38, 30, "0", "0", "不錯，不錯，我是個喜歡熱鬧的人～", "いいね。赈やかなのは好きだ。", "0", "0", "不错，不错，我是个喜欢热闹的人～", "0", "cv_hank_35", "0", "0"},
[4000200135] = {4000200135, 10002001, 39, 31, "0", "0", "真想趕快用上新裝備啊。", "早く新しい装备に替えたいな。", "0", "0", "真想赶快用上新装备啊。", "0", "cv_hank_36", "0", "0"},
[4000200136] = {4000200136, 10002001, 40, 32, "0", "0", "來采購些啤酒吧～", "ビールの买い付けをしようぜ。", "0", "0", "来采购些啤酒吧～", "0", "cv_hank_37", "0", "0"},
[4000200137] = {4000200137, 10002001, 41, 33, "0", "0", "嘖！這就是官老爺們生活的地方嗎？", "ふーん。これがお役人さまが暮らしてるとこか。", "0", "0", "啧！这就是官老爷们生活的地方吗？", "0", "cv_hank_38", "0", "0"},
[4000200138] = {4000200138, 10002001, 42, 34, "0", "0", "變更設定？還蠻方便的嘛～", "设定の変更？めっちゃ便利だな。", "0", "0", "变更设置？还蛮方便的嘛～", "0", "cv_hank_39", "0", "0"},
[4000200139] = {4000200139, 10002001, 43, 35, "0", "0", "欸？有新信件送過來嗎？", "え？新しいメールが来るのか？", "0", "0", "哎？有新邮件送过来吗？", "0", "cv_hank_40", "0", "0"},
[4000200140] = {4000200140, 10002001, 44, 36, "0", "0", "交換情報～交換情報～", "情报交换、情报交换。", "0", "0", "交换情报～交换情报～", "0", "cv_hank_41", "0", "0"},
[4000200141] = {4000200141, 10002001, 45, 37, "0", "0", "確認一下吧～", "确认したら？", "0", "0", "确认一下吧～", "0", "cv_hank_42", "0", "0"},
[423100] = {423100, 12031, 1, 1, "0", "0", "蒼霧殘響", "0", "0", "0", "0", "0", "cv_qianqiu_se_01", "0", "0"},
[423101] = {423101, 12031, 2, 2, "0", "0", "不要！我討厭這種浪費時間的工作！你太“史蔕芬妮”了！", "0", "0", "0", "0", "0", "cv_qianqiu_se_02", "0", "0"},
[423102] = {423102, 12031, 3, 3, "0", "0", "久等了吧！你尊敬的千秋大人來救你了，感恩戴德，痛哭流涕，五體投地吧！", "0", "0", "0", "0", "0", "cv_qianqiu_se_03", "0", "0"},
[423103] = {423103, 12031, 4, 4, "0", "idle", "果然，比起這把弩，還是翦刀更適合我……下次找史蔕芬妮把武器改一改吧，就這樣決定了，你也要和我一起去，她只聽得進你的話！", "0", "0", "0", "0", "0", "cv_qianqiu_se_04", "0", "0"},
[423104] = {423104, 12031, 5, 4, "0", "idle", "雖然本來就覺得你這家夥很容易惹很多麻煩……沒少喫苦頭吧？有時間的話，和我説下你這段時間經歷了什麽吧，我挺感興趣的。", "0", "0", "0", "0", "0", "cv_qianqiu_se_05", "0", "0"},
[423105] = {423105, 12031, 6, 4, "0", "idle", "不知道為什麽，最近經常聽到什麽“受刑人好酷”，“比起駕駛員，還是更想加入受刑人啊”之類的話……現在的小鬼都瘋了嗎？那些蒼穹學院的學生難不成以為受刑人都是反英雄？腦子壞掉了吧？需要我把她們腦袋切開硏究下嗎？", "0", "0", "0", "0", "0", "cv_qianqiu_se_06", "0", "0"},
[423106] = {423106, 12031, 7, 5, "1_》_0_0.8", "level", "你平常有寫“最討厭的人排行榜”嗎？有的話就把它交出來吧，剛好可以給我凑工作業績……史蔕芬妮最近都不給我發任務了，眞是磨蹭。", "0", "0", "0", "0", "0", "cv_qianqiu_se_07", "0", "0"},
[423107] = {423107, 12031, 8, 5, "1_》_0_0.8", "level2", "人類一定要巨大化才能打敗原罪嗎？就沒有其他選項了嗎？太怪了，站在這麽高的地方，怎麽可能發揮得出全部實力啊！", "0", "0", "0", "0", "0", "cv_qianqiu_se_08", "0", "0"},
[423108] = {423108, 12031, 9, 5, "1_》_100_1.5", "level3", "對了！切斯頓的事情，你還沒有好好感謝我呢！我可要好好想想該讓你如何報答我……嗯，總之先承包我一年的拉麵吧！我受够艾吉斯的夥食了！", "0", "0", "0", "0", "0", "cv_qianqiu_se_09", "0", "0"},
[423109] = {423109, 12031, 10, 5, "1_》_500_2", "level4", "對了——是不是只要待在你身邊，就不用回到那个睡覺都嫌窄的監獄了？好，在史蔕芬妮找上門之前，我就待在你這裏不走了！不許拒絶，我可是你的救命恩人。", "0", "0", "0", "0", "0", "cv_qianqiu_se_10", "0", "0"},
[423110] = {423110, 12031, 11, 5, "1_》_1000_2.5", "level5", "話説，你也不小了吧，史蔕芬妮沒有跟你商量過“結婚”之類的事嗎？沒什麽……只是在想，要是和你成為家人的話，好像也挺好的——“夫婦”，應該算家人吧？", "0", "0", "0", "0", "0", "cv_qianqiu_se_11", "0", "0"},
[423111] = {423111, 12031, 12, 6, "0", "0", "還是不適應這个高度啊……", "0", "0", "0", "0", "0", "cv_qianqiu_se_12", "0", "0"},
[423112] = {423112, 12031, 13, 7, "0", "0", "其實，我討厭形式主義。", "0", "0", "0", "0", "0", "cv_qianqiu_se_13", "0", "0"},
[423113] = {423113, 12031, 14, 8, "0", "0", "我們去把礙事的家夥都大卸八塊吧。", "0", "0", "0", "0", "0", "cv_qianqiu_se_14", "0", "0"},
[423114] = {423114, 12031, 15, 9, "0", "0", "礙眼的人全都殺了！", "0", "0", "0", "0", "0", "cv_qianqiu_se_15", "0", "0"},
[423115] = {423115, 12031, 16, 10, "0", "0", "不長眼的家夥在哪呢？", "0", "0", "0", "0", "0", "cv_qianqiu_se_16", "0", "0"},
[423116] = {423116, 12031, 17, 11, "0", "0", "我的詞典裏沒有“遺憾”和“瑕疵”！", "0", "0", "0", "0", "0", "cv_qianqiu_se_17", "0", "0"},
[423117] = {423117, 12031, 18, 12, "0", "0", "我的詞典裏沒有“失敗”和“做不到”！", "0", "0", "0", "0", "0", "cv_qianqiu_se_18", "0", "0"},
[423118] = {423118, 12031, 19, 13, "0", "0", "我的詞典裏沒有“失敗”！", "0", "0", "0", "0", "0", "cv_qianqiu_se_19", "0", "0"},
[423119] = {423119, 12031, 20, 14, "0", "0", "我沒有詞典。", "0", "0", "0", "0", "0", "cv_qianqiu_se_20", "0", "0"},
[423120] = {423120, 12031, 21, 15, "0", "0", "四分五裂！", "0", "0", "0", "0", "0", "cv_qianqiu_se_21", "0", "0"},
[423121] = {423121, 12031, 23, 16, "0", "0", "呵呵呵——", "0", "0", "0", "0", "0", "cv_qianqiu_se_22", "0", "0"},
[423122] = {423122, 12031, 24, 17, "0", "0", "你逃不掉的！", "0", "0", "0", "0", "0", "cv_qianqiu_se_23", "0", "0"},
[423123] = {423123, 12031, 22, 38, "0", "0", "享受殺人鬼的盛宴吧！", "0", "0", "0", "0", "0", "cv_qianqiu_se_24", "0", "0"},
[423124] = {423124, 12031, 25, 18, "0", "0", "眞不方便！", "0", "0", "0", "0", "0", "cv_qianqiu_se_25", "0", "0"},
[423125] = {423125, 12031, 26, 19, "0", "0", "太高了！！！", "0", "0", "0", "0", "0", "cv_qianqiu_se_26", "0", "0"},
[423126] = {423126, 12031, 27, 20, "0", "0", "果然工作結束之後就要好好放松一下呀。", "0", "0", "0", "0", "0", "cv_qianqiu_se_27", "0", "0"},
[423127] = {423127, 12031, 28, 21, "0", "0", "説起來，我還沒有去泡過温泉呢……要一起去嗎？", "0", "0", "0", "0", "0", "cv_qianqiu_se_28", "0", "0"},
[423128] = {423128, 12031, 29, 21, "0", "0", "這時候要是冷飲就好了。", "0", "0", "0", "0", "0", "cv_qianqiu_se_29", "0", "0"},
[423129] = {423129, 12031, 30, 22, "0", "0", "同樣是浪費時間，至少這个很舒服，工作就不行。", "0", "0", "0", "0", "0", "cv_qianqiu_se_30", "0", "0"},
[423130] = {423130, 12031, 31, 23, "0", "0", "猜錯了的話我就把你大卸八塊。", "0", "0", "0", "0", "0", "cv_qianqiu_se_31", "0", "0"},
[423131] = {423131, 12031, 32, 24, "0", "0", "很好，輪到我了。", "0", "0", "0", "0", "0", "cv_qianqiu_se_32", "0", "0"},
[423132] = {423132, 12031, 33, 25, "0", "0", "你有什麽遺言想對我説嗎？", "0", "0", "0", "0", "0", "cv_qianqiu_se_33", "0", "0"},
[423133] = {423133, 12031, 34, 26, "0", "0", "你啊，整天都到處亂跑，要是被人殺了可別怪我不在你身邊。", "0", "0", "0", "0", "0", "cv_qianqiu_se_34", "0", "0"},
[423134] = {423134, 12031, 35, 27, "0", "0", "記得找史蔕芬妮報備一下，這也算任務。", "0", "0", "0", "0", "0", "cv_qianqiu_se_35", "0", "0"},
[423135] = {423135, 12031, 36, 28, "0", "0", "她們做好被殺的覺悟了嗎？", "0", "0", "0", "0", "0", "cv_qianqiu_se_36", "0", "0"},
[423136] = {423136, 12031, 37, 29, "0", "0", "你的桃花運遲早會讓你倒霉的。", "0", "0", "0", "0", "0", "cv_qianqiu_se_37", "0", "0"},
[423137] = {423137, 12031, 38, 30, "0", "0", "眞是貪得無厭的男人。", "0", "0", "0", "0", "0", "cv_qianqiu_se_38", "0", "0"},
[423138] = {423138, 12031, 39, 31, "0", "0", "艾吉斯的裝備眞的可信嗎？", "0", "0", "0", "0", "0", "cv_qianqiu_se_39", "0", "0"},
[423139] = {423139, 12031, 40, 32, "0", "0", "再來一次——拉麵！冰淇淋漢堡！", "0", "0", "0", "0", "0", "cv_qianqiu_se_40", "0", "0"},
