[423143] = {423143, 12031, 44, 36, "0", "0", "別閑聊了。", "0", "0", "0", "0", "0", "cv_qianqiu_se_44", "0", "0"},
[423144] = {423144, 12031, 45, 37, "0", "0", "呵——", "0", "0", "0", "0", "0", "cv_qianqiu_se_45", "0", "0"},
[4203100100] = {4203100100, 12031001, 1, 1, "0", "0", "蒼霧殘響", "0", "0", "0", "0", "0", "cv_sk_qianqiu_se_01", "0", "0"},
[4203100101] = {4203100101, 12031001, 2, 2, "0", "0", "不要！我討厭這種浪費時間的工作！你太“史蔕芬妮”了！", "0", "0", "0", "0", "0", "cv_sk_qianqiu_se_02", "0", "0"},
[4203100102] = {4203100102, 12031001, 3, 3, "0", "0", "久等了吧！你尊敬的千秋大人來救你了，感恩戴德，痛哭流涕，五體投地吧！", "0", "0", "0", "0", "0", "cv_sk_qianqiu_se_03", "0", "0"},
[4203100103] = {4203100103, 12031001, 91, 4, "0", "idle", "這就是你的房間嗎？嚯——有藏著什麽不可告人的秘密嗎？説出來吧，我不會告訴別人的。", "0", "0", "0", "0", "0", "cv_sk_qianqiu_se_n06", "0", "idle,idle"},
[4203100104] = {4203100104, 12031001, 94, 4, "0", "idle2", "奇怪……這个房間的温度怎麽在不斷昇高，難道你平常還有蒸桑拏的愛好？", "0", "0", "0", "0", "0", "cv_sk_qianqiu_se_n10", "0", "idle2,idle2"},
[4203100105] = {4203100105, 12031001, 98, 4, "0", "idle3", "史蔕芬妮那傢夥，雖然臉上一副沒表情的模樣，實際上是一肚子壞水，總會想一些故意惡心人的壞點子，難怪大家都不喜歡她。", "0", "0", "0", "0", "0", "cv_sk_qianqiu_se_n14", "0", "idle3,idle3"},
[4203100106] = {4203100106, 12031001, 92, 5, "1_》_0_0.8", "level1", "來決一勝負吧，輸掉遊戲的人要請對方喫飯！", "0", "0", "0", "0", "0", "cv_sk_qianqiu_se_n07", "0", "level1,level1"},
[4203100107] = {4203100107, 12031001, 92, 5, "1_》_0_0.8", "level1", "像這樣玩電子遊戲，感覺是上輩子的事情了——不過仔細數的話，可能也沒有過去幾年。", "0", "0", "0", "0", "0", "cv_sk_qianqiu_se_n08", "0", "level1,level1"},
[4203100108] = {4203100108, 12031001, 92, 5, "1_》_0_0.8", "level1", "我的遊戲技術説不定是可以制霸職業聯賽的水平，你肯定不是我對手的。", "0", "0", "0", "0", "0", "cv_sk_qianqiu_se_n09", "0", "level1,level1"},
[4203100109] = {4203100109, 12031001, 95, 5, "1_》_0_0.8", "level2", "我跟你説啊——史蔕芬妮那个傢夥，最近越來越過分了，都開始讓我給小鬼頭當保姆了。那傢夥把我當什麽了，新手導師嗎？", "0", "0", "0", "0", "0", "cv_sk_qianqiu_se_n11", "0", "level2,level2"},
[4203100110] = {4203100110, 12031001, 106, 5, "1_》_0_0.8", "level3", "剛剛那个在房間門口晃來晃去偷偷摸摸的就是你的妹妹吉雅吧？安心，我不會對她動手的，我只是想……她會不會想要一个姐姐？", "0", "0", "0", "0", "0", "cv_sk_qianqiu_se_n15", "0", "level3,level3"},
[4203100111] = {4203100111, 12031001, 95, 5, "1_》_0_0.8", "level4", "對了，上次的事情我還沒跟你計較呢。聽好了，以後要是遇到什麽麻煩的事情，記得跟我説一聲。我不一定有空幫你，但你什麽都不跟我説，那就是你的問題！", "0", "0", "0", "0", "0", "cv_sk_qianqiu_se_n12", "0", "level4,level4"},
[4203100112] = {4203100112, 12031001, 95, 5, "1_》_0_0.8", "level4", "還有，我不是跟你説過嗎，不要總是沒事給自己找事做。就是因為你太容易被女人騙了，所以才那麽容易被捲入到無妄之災裏，你應該吸取教訓！", "0", "0", "0", "0", "0", "cv_sk_qianqiu_se_n13", "0", "level4,level4"},
[4203100113] = {4203100113, 12031001, 106, 5, "1_》_0_0.8", "level5", "如果不是這个世界過於離譜，恐怕像我這樣的殺人鬼根本沒有容身之處吧，能像現在這樣待在你身邊，用那傢夥的話來説就是——“我眞是相當走運啊。”", "0", "0", "0", "0", "0", "cv_sk_qianqiu_se_n16", "0", "level5,level5"},
[4203100114] = {4203100114, 12031001, 106, 5, "1_》_0_0.8", "level5", "我是沒有家人的殺人鬼，是已經和塵世斬斷聯繫的異類，我比誰都要清楚這件事，但是，如果有機會的話，我也想再一次擁有自己的家人……沒什麽，你就當我在癡人説夢吧。", "0", "0", "0", "0", "0", "cv_sk_qianqiu_se_n17", "0", "level5,level5"},
[4203100115] = {4203100115, 12031001, 93, 5, "1_》_0_0.8", "switch1", "咦……房間的温度是不是突然昇高了？", "0", "0", "0", "0", "0", "cv_sk_qianqiu_se_n01", "0", "switch1,switch1"},
[4203100116] = {4203100116, 12031001, 96, 5, "1_》_0_0.8", "switch2", "突然好冷——！", "0", "0", "0", "0", "0", "cv_sk_qianqiu_se_n02", "0", "switch2,switch2"},
[4203100117] = {4203100117, 12031001, 102, 5, "1_》_0_0.8", "switch3", "還有這種功能啊……", "0", "0", "0", "0", "0", "cv_sk_qianqiu_se_n03", "0", "switch3,switch3"},
[4203100118] = {4203100118, 12031001, 96, 5, "1_》_0_0.8", "switch4", "突然好冷——！", "0", "0", "0", "0", "0", "cv_sk_qianqiu_se_n02", "0", "switch4,switch4"},
