[4203100135] = {4203100135, 12031001, 27, 20, "0", "0", "果然工作結束之後就要好好放松一下呀。", "0", "0", "0", "0", "0", "cv_sk_qianqiu_se_27", "0", "0"},
[4203100136] = {4203100136, 12031001, 28, 21, "0", "0", "説起來，我還沒有去泡過温泉呢……要一起去嗎？", "0", "0", "0", "0", "0", "cv_sk_qianqiu_se_28", "0", "0"},
[4203100137] = {4203100137, 12031001, 29, 21, "0", "0", "這時候要是冷飲就好了。", "0", "0", "0", "0", "0", "cv_sk_qianqiu_se_29", "0", "0"},
[4203100138] = {4203100138, 12031001, 30, 22, "0", "0", "同樣是浪費時間，至少這个很舒服，工作就不行。", "0", "0", "0", "0", "0", "cv_sk_qianqiu_se_30", "0", "0"},
[4203100139] = {4203100139, 12031001, 31, 23, "0", "0", "猜錯了的話我就把你大卸八塊。", "0", "0", "0", "0", "0", "cv_sk_qianqiu_se_31", "0", "0"},
[4203100140] = {4203100140, 12031001, 32, 24, "0", "0", "很好，輪到我了。", "0", "0", "0", "0", "0", "cv_sk_qianqiu_se_32", "0", "0"},
[4203100141] = {4203100141, 12031001, 33, 25, "0", "0", "你有什麽遺言想對我説嗎？", "0", "0", "0", "0", "0", "cv_sk_qianqiu_se_33", "0", "0"},
[4203100142] = {4203100142, 12031001, 34, 26, "0", "0", "快點坐過來，遊戲要開始了，我可不會手下畱情，做好被我打得落花流水的心理準備吧。", "0", "0", "0", "0", "0", "cv_sk_qianqiu_se_n24", "0", "0"},
[4203100143] = {4203100143, 12031001, 35, 27, "0", "0", "記得找史蔕芬妮報備一下，這也算任務。", "0", "0", "0", "0", "0", "cv_sk_qianqiu_se_35", "0", "0"},
[4203100144] = {4203100144, 12031001, 36, 28, "0", "0", "她們做好被殺的覺悟了嗎？", "0", "0", "0", "0", "0", "cv_sk_qianqiu_se_36", "0", "0"},
[4203100145] = {4203100145, 12031001, 37, 29, "0", "0", "你的桃花運遲早會讓你倒霉的。", "0", "0", "0", "0", "0", "cv_sk_qianqiu_se_37", "0", "0"},
