[4203100153] = {4203100153, 12031001, 45, 37, "0", "0", "呵——", "0", "0", "0", "0", "0", "cv_sk_qianqiu_se_45", "0", "0"},
[4102700200] = {4102700200, 11027002, 1, 1, "0", "0", "蒼霧殘響", "ハツリバーブ", "0", "0", "0", "0", "cv_qishi_1", "0", "0"},
[4102700201] = {4102700201, 11027002, 2, 2, "0", "0", "旣然是你選的，那可不要嫌棄我的話太多了。", "あなたが选んだのだから、私がおしゃべりだとは思わないでね。", "0", "0", "0", "0", "cv_qishi_2", "0", "0"},
[4102700202] = {4102700202, 11027002, 3, 3, "0", "0", "我還以為你不想再見到我了，果然是我的魅力太大了嗎？也好，我會在接下來的相處中，讓你充分感受到我那致命的誘惑力的，領航小弟。", "もう会いたくないのかと思ったわ。やっぱり私の魅力が强すぎるのかしら？まあいいわ、これからの付き合いで、私の魅力的な诱惑を存分に味わせてあげるわね、ナビゲーターくん。", "0", "0", "0", "0", "cv_qishi_3", "0", "0"},
[4102700203] = {4102700203, 11027002, 91, 4, "0", "idle", "喜歡甜食的人和喜歡咸食的人在本質上沒有區別。這句話放在我身上也是一樣的，崇尙希望與美好的人，跟我這類拏別人的不幸當下酒菜的人是同類。", "甘いものが好きな人と塩辛いものが好きな人は本质的に変わらないわ。それは私にも言えることよ。希望や美しさを尊ぶ人も、他人の不幸を酒の肴にする私みたいな人も、结局同じなの。", "0", "0", "0", "0", "cv_qishi_4", "0", "0,idle"},
[4102700204] = {4102700204, 11027002, 94, 4, "0", "idle2", "不要對自己的能力有不切實際的期待，不要擅自幻想自己的人生會有夢幻般的展開，凡事往最糟糕的情況去設想，這就是我們這種人唯一能抓住幸福人生的方法。", "自分の能力に过度な期待をしないで。人生が梦のように展开するなんて幻想を抱かないで。全てを最悪の状况で考えること、それが私たちのような人间が幸せをつかむ唯一の方法よ。", "0", "0", "0", "0", "cv_qishi_5", "0", "0,idle2"},
[4102700205] = {4102700205, 11027002, 98, 4, "0", "idle3", "言語的力量是有限的，就算我再怎麽花言巧語，也不可能敵得過極致的暴力。那个凡事只想著用翦刀來解決問題的暴力小鬼，可謂是我的“天敵”啊。", "言叶の力は限られているの。どんなに私が巧みに话しても、极度の暴力には胜てないわ。何でもハサミで解决しようとするあの暴力おちびちゃん、彼女はまさに私の「天敌」ね。", "0", "0", "0", "0", "cv_qishi_6", "0", "0,idle3"},
[4102700206] = {4102700206, 11027002, 92, 5, "1_》_0_0.8", "level1", "我從來不會害人，我的所作所為只不過是推動人做出選擇而已——即便選擇了錯誤的那一邊，也是他們憑著自己的意志做出的選擇。", "私は决して人を害することはないわ。私のすることはただ、人を选択へと促すだけ——たとえそれが间违った选択であっても、それは彼らが自分の意志で决めたことよ。", "0", "0", "0", "0", "cv_qishi_8", "0", "0,level1"},
[4102700207] = {4102700207, 11027002, 95, 5, "1_》_0_0.8", "level2", "當人站在迷茫的十字路口時，即使是細如微風一般的言語，也會讓他停滯的身體向某處傾斜。領航小弟，你可要提防那些教導你什麽是“正确”的人呀。", "人が迷いの十字路に立たされるとき、そよ风のような言叶でもその体をどこかに倾かせる力になるの。ナビゲーターくん、「正しい」ことを教えようとする人には注意しなさいね。", "0", "0", "0", "0", "cv_qishi_9", "0", "0,level2"},
[4102700208] = {4102700208, 11027002, 106, 5, "1_》_0_0.8", "level3", "領航小弟，我是教唆犯，不是詐騙師，謊言是我瞧不上的卑劣手段，我的言語都是眞心實意，比方説這一句——領航小弟，你的氣味在教唆我對你犯罪哦~", "ナビゲーターくん、私は教唆犯であって、诈欺师ではないわ。嘘なんて卑劣な手段は使わない。私の言叶はすべて本心よ。例えば——あなたの香りが私を犯罪に駆り立てるのよ、ナビゲーターくん。", "0", "0", "0", "0", "cv_qishi_10", "0", "0,level3"},
[4102700209] = {4102700209, 11027002, 106, 5, "1_》_0_0.8", "level4", "我不會，也不値得被救贖，我的一生都是在犯罪，也是在贖罪，不管過去多久，我都不會改變。現在，領航小弟已經了解我是个怎樣的人了……你願意當我一輩子的共犯嗎？", "私は救われることも、救われる価値もないわ。私の一生は犯罪と赎罪の连続よ。どんなに时间が経っても、私は変わらない。さあ、ナビゲーターくんは私がどんな人间か分かったでしょう……あなた、一生私の共犯者になってくれる？", "0", "0", "0", "0", "cv_qishi_11", "0", "0,level4"},
[4102700210] = {4102700210, 11027002, 93, 5, "1_》_0_0.8", "switch1", "就當做是我的詭辯吧——領航小弟，這世界上有助人為樂的人，那理所當然也該有我這種盼著別人墜下深淵的人，人們應該尊重我這一惡劣的興趣。", "これを私の诡弁だと思ってもいいわ——ナビゲーターくん。この世には助けを求める人がいる一方で、当然のことながら、他人が奈落の底に落ちるのを楽しみにしている私のような人间もいるの。私の悪趣味は尊重されるべきよ。", "0", "0", "0", "0", "cv_qishi_7", "0", "0,switch1"},
[4102700211] = {4102700211, 11027002, 102, 23, "1_》_0_0.8", "switch2", "檢驗一下我是不是个令你印象深刻的女人吧。", "私が印象に残る女かどうか、确かめてみて。", "0", "0", "0", "0", "cv_qishi_31", "0", "0,switch2"},
[4102700212] = {4102700212, 11027002, 96, 24, "1_》_0_0.8", "switch3", "原來如此，領航小弟已經迷上我了吧？", "なるほど、ナビゲーターくんはもう私に梦中なのね？", "0", "0", "0", "0", "cv_qishi_32", "0", "0,switch3"},
[4102700213] = {4102700213, 11027002, 12, 6, "0", "0", "即使投資我，也未必能得到什麽好處呀。", "私に投资しても、何の利益も得られないかもしれないわよ。", "0", "0", "0", "0", "cv_qishi_12", "0", "0"},
[4102700214] = {4102700214, 11027002, 13, 7, "0", "0", "這算是獲得褒奬了嗎？", "これが褒められたってことかしら？", "0", "0", "0", "0", "cv_qishi_13", "0", "0"},
[4102700215] = {4102700215, 11027002, 14, 8, "0", "0", "要是能像領航小弟一樣知道別人腦子裏在想些什麽就好了~", "ナビゲーターくんのように他人の考えが分かるようになれたらいいのにね。", "0", "0", "0", "0", "cv_qishi_14", "0", "0"},
[4102700216] = {4102700216, 11027002, 15, 9, "0", "0", "感覺沒什麽提昇呢。", "特に进歩は感じられないわ。", "0", "0", "0", "0", "cv_qishi_15", "0", "0"},
[4102700217] = {4102700217, 11027002, 16, 10, "0", "0", "人家比較想待在領航小弟身邊呀~", "私はナビゲーターくんのそばにいたいだけよ。", "0", "0", "0", "0", "cv_qishi_16", "0", "0"},
[4102700218] = {4102700218, 11027002, 17, 11, "0", "0", "我是在該認眞的時候會認眞的人~", "私も真剣になる时は真剣になるの。", "0", "0", "0", "0", "cv_qishi_17", "0", "0"},
[4102700219] = {4102700219, 11027002, 18, 12, "0", "0", "能做到這份上已經値得領航小弟夸奬了。", "ここまでやれたんだから、ナビゲーターくんに褒めてもらってもいいわよね。", "0", "0", "0", "0", "cv_qishi_18", "0", "0"},
[4102700220] = {4102700220, 11027002, 19, 13, "0", "0", "再慘烈的勝利也強過一無所獲的失敗。", "どんなに惨めな胜利でも、何も得られない败北よりはましよ。", "0", "0", "0", "0", "cv_qishi_19", "0", "0"},
[4102700221] = {4102700221, 11027002, 20, 14, "0", "0", "人家盡力了啦。", "私は全力を尽くしたわ。", "0", "0", "0", "0", "cv_qishi_20", "0", "0"},
[4102700222] = {4102700222, 11027002, 21, 15, "0", "0", "漂亮的全壘打。", "素晴らしいホームランね。", "0", "0", "0", "0", "cv_qishi_21", "0", "0"},
[4102700223] = {4102700223, 11027002, 23, 16, "0", "0", "咔嚓！", "カチン！", "0", "0", "0", "0", "cv_qishi_22", "0", "0"},
[4102700224] = {4102700224, 11027002, 24, 17, "0", "0", "會很痛噢？", "痛いかもよ？", "0", "0", "0", "0", "cv_qishi_23", "0", "0"},
[4102700225] = {4102700225, 11027002, 25, 18, "0", "0", "快點放棄吧，快點絶望吧，讓我好好欣賞你們破滅時的表情吧。", "早く谛めて、絶望して、あなたたちの破灭する表情をじっくり楽しませてね。", "0", "0", "0", "0", "cv_qishi_25", "0", "0"},
[4102700226] = {4102700226, 11027002, 26, 19, "0", "0", "遭報應了啊……", "报いが来たわね……", "0", "0", "0", "0", "cv_qishi_26", "0", "0"},
[4102700227] = {4102700227, 11027002, 27, 20, "0", "0", "嗯哼？原來領航小弟也是有自己欲望的人啊，我説的對嗎？", "んふ？ナビゲーターくんにも欲望があるのね、私の言った通りでしょう？", "0", "0", "0", "0", "cv_qishi_27", "0", "0"},
[4102700228] = {4102700228, 11027002, 28, 21, "0", "0", "旣然都做到這一步了，就不要移開視綫，欺騙自己的內心了，領航小弟。", "ここまで来たのだから、视线をそらさないで、自分の心に嘘つかないでね、ナビゲーターくん。", "0", "0", "0", "0", "cv_qishi_28", "0", "0"},
[4102700229] = {4102700229, 11027002, 29, 21, "0", "0", "就當是被我欺騙慫恿吧，做你想做的事情吧，領航小弟。", "私に骗されて、そそのかされたと思って、やりたいことをやりなさい、ナビゲーターくん。", "0", "0", "0", "0", "cv_qishi_29", "0", "0"},
[4102700230] = {4102700230, 11027002, 30, 22, "0", "0", "有什麽好事嗎？", "何かいいことでもあった？", "0", "0", "0", "0", "cv_qishi_30", "0", "0"},
[4102700231] = {4102700231, 11027002, 31, 23, "0", "0", "檢驗一下我是不是个令你印象深刻的女人吧。", "私が印象に残る女かどうか、确かめてみて。", "0", "0", "0", "0", "cv_qishi_31", "0", "0"},
[4102700232] = {4102700232, 11027002, 32, 24, "0", "0", "原來如此，領航小弟已經迷上我了吧？", "なるほど、ナビゲーターくんはもう私に梦中なのね？", "0", "0", "0", "0", "cv_qishi_32", "0", "0"},
[4102700233] = {4102700233, 11027002, 33, 25, "0", "0", "看來我對領航小弟只是个“不過如此”的女人呀。", "どうやら私はナビゲーターくんにとって「それほどでもない」女みたいね。", "0", "0", "0", "0", "cv_qishi_33", "0", "0"},
[4102700234] = {4102700234, 11027002, 34, 26, "0", "0", "讓我們找找今天的受害者吧~", "さあ、今日の犠牲者を见つけましょうか～", "0", "0", "0", "0", "cv_qishi_34", "0", "0"},
[4102700235] = {4102700235, 11027002, 35, 27, "0", "0", "讓我去做這種事……你和我是同類啊。", "こんなことを私にやらせるなんて……あなたも私と同类ね。", "0", "0", "0", "0", "cv_qishi_35", "0", "0"},
[4102700236] = {4102700236, 11027002, 36, 28, "0", "0", "大家一起愉快地自相殘殺吧~", "みんなで楽しく杀し合いましょう～", "0", "0", "0", "0", "cv_qishi_36", "0", "0"},
[4102700237] = {4102700237, 11027002, 37, 29, "0", "0", "一盤散沙和精兵強將，你們是哪類呢？", "结束するか、それともしないかしら？", "0", "0", "0", "0", "cv_qishi_37", "0", "0"},
[4102700238] = {4102700238, 11027002, 38, 30, "0", "0", "祈禱不要再遇上我這樣的人吧。", "私のような人间に二度と会わないように祈りなさい。", "0", "0", "0", "0", "cv_qishi_38", "0", "0"},
[4102700239] = {4102700239, 11027002, 39, 31, "0", "0", "凡事都有要支付代價，連拯救世界的裝備也不例外。", "すべてには代偿が必要よ、世界を救う装备だって例外じゃないわ。", "0", "0", "0", "0", "cv_qishi_39", "0", "0"},
[4102700240] = {4102700240, 11027002, 40, 32, "0", "0", "有錢的話，什麽都可以買到嗎？", "お金さえあれば、何でも买えると思うの？", "0", "0", "0", "0", "cv_qishi_40", "0", "0"},
[4102700241] = {4102700241, 11027002, 41, 33, "0", "0", "看起來是很好騙的那類人呢。", "骗しやすそうな人に见えるわね。", "0", "0", "0", "0", "cv_qishi_41", "0", "0"},
[4102700242] = {4102700242, 11027002, 42, 34, "0", "0", "記得開聲音~", "音をオンにするのを忘れないでね。", "0", "0", "0", "0", "cv_qishi_42", "0", "0"},
[4102700243] = {4102700243, 11027002, 43, 35, "0", "0", "會不會有詐騙郵件呢？", "诈欺メールが届いてないかしら？", "0", "0", "0", "0", "cv_qishi_43", "0", "0"},
[4102700244] = {4102700244, 11027002, 44, 36, "0", "0", "別被花言巧語騙了。", "甘い言叶に骗されないでね。", "0", "0", "0", "0", "cv_qishi_44", "0", "0"},
[4102700245] = {4102700245, 11027002, 45, 37, "0", "0", "嗯哼？", "んふ？", "0", "0", "0", "0", "cv_qishi_45", "0", "0"},
[4003500100] = {4003500100, 10035001, 1, 1, "0", "0", "蒼霧殘響", "0", "0", "0", "0", "0", "cv_heli_1", "0", "0"},
[4003500101] = {4003500101, 10035001, 2, 2, "0", "0", "OK，這種事我還是挺擅長的，畢竟當了六年打雜的……呵呵……", "0", "0", "0", "0", "0", "cv_heli_2", "0", "0"},
[4003500102] = {4003500102, 10035001, 3, 3, "0", "0", "你是領航……是吧？那我就是駕駛員了？對吧？沒錯吧？咳咳，我是赫莉·加西亞，是一名正式駕駛員！", "0", "0", "0", "0", "0", "cv_heli_3", "0", "0"},
[4003500103] = {4003500103, 10035001, 91, 4, "0", "idle", "我以前對艾吉斯還挺憧憬的，結果來了之後才發現到處都是些怪人，這就是適者生存吧，普通人早就待不下去了，切斯頓也是這樣，可能哪裏都一樣吧。", "0", "0", "0", "0", "0", "cv_heli_4", "0", "idle,idle"},
[4003500104] = {4003500104, 10035001, 91, 4, "0", "idle", "駕駛員的假期比想象中要多不少，這樣一來我就可以經常回去嘲笑以前的店老闆了，讓她瞧不起我。", "0", "0", "0", "0", "0", "cv_heli_5", "0", "idle,idle"},
[4003500105] = {4003500105, 10035001, 91, 4, "0", "idle", "……説起來，因為各種各樣的原因，我幾乎沒有和其他隊友好好聊過，她們的臉和名字我都不一定對得上，眞是一點也不成熟啊。", "0", "0", "0", "0", "0", "cv_heli_6", "0", "idle,idle"},
[4003500106] = {4003500106, 10035001, 92, 5, "15_1_0_0.8", "touch1", "不同人追求的幸福是有不同重量的。有的人想要的是“10”，有的人則是“100”。我的話……總之，先以變成正數為目標吧。", "0", "0", "0", "0", "0", "cv_heli_7", "0", "touch1,touch1"},
[4003500107] = {4003500107, 10035001, 92, 5, "15_1_0_0.8", "touch1", "只要不戰斗的話，駕駛員的工作還蠻輕松的。", "0", "0", "0", "0", "0", "cv_heli_8", "0", "touch1,touch1"},
[4003500108] = {4003500108, 10035001, 92, 5, "15_1_0_0.8", "touch1", "想喫牛肋骨……想喫牛排……廣告上把它們拍得太美味了啦……你能請我喫嗎？", "0", "0", "0", "0", "0", "cv_heli_9", "0", "touch1,touch1"},
[4003500109] = {4003500109, 10035001, 92, 5, "15_2_0_0.8", "touch2", "你的時間眞的是被工作擠得滿滿……餧，找个時間，我們偷偷溜出去玩吧？我知道一个很適合發泄壓力，凈化心靈的地方。", "0", "0", "0", "0", "0", "cv_heli_10", "0", "touch2,touch2"},
[4003500110] = {4003500110, 10035001, 92, 5, "15_2_0_0.8", "touch2", "嗚啊啊……眞是心煩，這種心情還是第一次，太奇怪了，我居然也會有這種不切實際的想法嗎？餧，領航，答應我，絶對不要騙我，也絶對不要突然消失，可以吧？沒問題的吧？", "0", "0", "0", "0", "0", "cv_heli_11", "0", "touch2,touch2"},
[4003500111] = {4003500111, 10035001, 12, 6, "0", "0", "該怎麽説……感謝培養？", "0", "0", "0", "0", "0", "cv_heli_12", "0", "0"},
[4003500112] = {4003500112, 10035001, 13, 7, "0", "0", "怪怪的感覺……", "0", "0", "0", "0", "0", "cv_heli_13", "0", "0"},
[4003500113] = {4003500113, 10035001, 14, 8, "0", "0", "我不太習慣你這類好人……一開始還以為會被冷落呢……謝謝啦。", "0", "0", "0", "0", "0", "cv_heli_14", "0", "0"},
[4003500114] = {4003500114, 10035001, 15, 9, "0", "0", "謝、謝謝。", "0", "0", "0", "0", "0", "cv_heli_15", "0", "0"},
[4003500115] = {4003500115, 10035001, 16, 10, "0", "0", "早點結束，早點回家！", "0", "0", "0", "0", "0", "cv_heli_16", "0", "0"},
[4003500116] = {4003500116, 10035001, 17, 11, "0", "0", "嚇了我一跳，我原來這麽厲害嗎？", "0", "0", "0", "0", "0", "cv_heli_17", "0", "0"},
[4003500117] = {4003500117, 10035001, 18, 12, "0", "0", "要知足，做到這个程度已經可以了啦。", "0", "0", "0", "0", "0", "cv_heli_18", "0", "0"},
[4003500118] = {4003500118, 10035001, 19, 13, "0", "0", "總比輸掉要好吧？", "0", "0", "0", "0", "0", "cv_heli_19", "0", "0"},
[4003500119] = {4003500119, 10035001, 20, 14, "0", "0", "我還眞沒想過會輸……", "0", "0", "0", "0", "0", "cv_heli_20", "0", "0"},
[4003500120] = {4003500120, 10035001, 21, 15, "0", "0", "下一个。", "0", "0", "0", "0", "0", "cv_heli_21", "0", "0"},
[4003500121] = {4003500121, 10035001, 23, 16, "0", "0", "要上了。", "0", "0", "0", "0", "0", "cv_heli_23", "0", "0"},
[4003500122] = {4003500122, 10035001, 24, 17, "0", "0", "切。", "0", "0", "0", "0", "0", "cv_heli_24", "0", "0"},
[4003500123] = {4003500123, 10035001, 26, 19, "0", "0", "不是吧……", "0", "0", "0", "0", "0", "cv_heli_25", "0", "0"},
[4003500124] = {4003500124, 10035001, 27, 20, "0", "0", "我的常識正在告訴我這不合理。", "0", "0", "0", "0", "0", "cv_heli_26", "0", "0"},
[4003500125] = {4003500125, 10035001, 28, 21, "0", "0", "我正試著通過無視你來保證我的神經不崩壞。", "0", "0", "0", "0", "0", "cv_heli_27", "0", "0"},
[4003500126] = {4003500126, 10035001, 29, 21, "0", "0", "要是你想看到我害羞丢臉的樣子，那就死心吧，我是絶對不會出醜的！", "0", "0", "0", "0", "0", "cv_heli_28", "0", "0"},
[4003500127] = {4003500127, 10035001, 30, 22, "0", "0", "怎、怎麽了？！", "0", "0", "0", "0", "0", "cv_heli_29", "0", "0"},
[4003500128] = {4003500128, 10035001, 31, 23, "0", "0", "有點意思……猜猜我是誰？", "0", "0", "0", "0", "0", "cv_heli_30", "0", "0"},
[4003500129] = {4003500129, 10035001, 32, 24, "0", "0", "答對啦！姑且是件好事吧？", "0", "0", "0", "0", "0", "cv_heli_31", "0", "0"},
[4003500130] = {4003500130, 10035001, 33, 25, "0", "0", "答錯了，看來你眞的和我不熟呢。", "0", "0", "0", "0", "0", "cv_heli_32", "0", "0"},
[4003500131] = {4003500131, 10035001, 34, 26, "0", "0", "歡迎回來……對了，有女孩子找你……你還眞是有够受歡迎的。", "0", "0", "0", "0", "0", "cv_heli_33", "0", "0"},
[4003500132] = {4003500132, 10035001, 35, 27, "0", "0", "那麽，今天又要去哪裏鬧騰呢？", "0", "0", "0", "0", "0", "cv_heli_34", "0", "0"},
[4003500133] = {4003500133, 10035001, 36, 28, "0", "0", "不想進行無意義的戰斗呀。", "0", "0", "0", "0", "0", "cv_heli_35", "0", "0"},
[4003500134] = {4003500134, 10035001, 37, 29, "0", "0", "要是當時大家都在，可能結果就不一樣了吧。", "0", "0", "0", "0", "0", "cv_heli_36", "0", "0"},
[4003500135] = {4003500135, 10035001, 38, 30, "0", "0", "又要有人被騙來當炰灰咯。", "0", "0", "0", "0", "0", "cv_heli_37", "0", "0"},
[4003500136] = {4003500136, 10035001, 39, 31, "0", "0", "眞希望你能把這些錢交給我。", "0", "0", "0", "0", "0", "cv_heli_38", "0", "0"},
