[415701] = {415701, 11057, 2, 2, "0", "0", "吾把萬聖節的服裝制作成了AVG藍圖~怎麽樣不錯吧，想必原罪也會被吾的深邃黑暗而震懾吧！", "0", "0", "0", "0", "0", "cv_sikadi_ha_02", "0", "0"},
[415702] = {415702, 11057, 3, 3, "0", "0", "眷屬~~！咳咳咳……【八足】的魔女斯卡蔕，謹聽召喚而來，説出你的願望吧——吾之眷屬。", "0", "0", "0", "0", "0", "cv_sikadi_ha_03", "0", "0"},
[415703] = {415703, 11057, 4, 4, "0", "idle", "領航~這是吾的新作——《萬聖節的滅世預言~兩个人的世界末日》，快來看看~吾想要讀後感~！", "0", "0", "0", "0", "0", "cv_sikadi_ha_04", "0", "0"},
[415704] = {415704, 11057, 5, 4, "0", "idle2", "唔……果然不愧是更接近黑暗的形態……吾的內心正不斷地被漆黑的衝動蠶食……這就是為了獲得強大力量的代價嗎……", "0", "0", "0", "0", "0", "cv_sikadi_ha_05", "0", "0"},
[415705] = {415705, 11057, 6, 4, "0", "idle3", "吾又做了一个夢，夢到了和領航一起在章魚星球冒險……等吾寫出來領航就知道了？", "0", "0", "0", "0", "0", "cv_sikadi_ha_06", "0", "0"},
[415706] = {415706, 11057, 7, 5, "1_》_0_0.8", "level1", "想要喫章魚燒嗎？從吾的身上現切的新鮮地獄食材，制作流程全透明絶對沒有以次充好的劣質貨！", "0", "0", "0", "0", "0", "cv_sikadi_ha_07", "0", "0"},
[415707] = {415707, 11057, 8, 5, "1_》_0_0.8", "level2", "不給糖就毁滅世界！哈嚕——！", "0", "0", "0", "0", "0", "cv_sikadi_ha_08", "0", "0"},
[415708] = {415708, 11057, 9, 5, "1_》_100_1.5", "level3", "為什麽吾的觸手纏著你的手不放……？啊……啊……這是那个，觸手會根據我的想法下意識地動起來……吾是説……領航，現、現在該牽吾的手了。", "0", "0", "0", "0", "0", "cv_sikadi_ha_09", "0", "0"},
[415709] = {415709, 11057, 10, 5, "1_》_500_2", "level4", "大家都會變成章魚？哈哈，領航你累了吧，要和吾睡一會午覺嗎，吾的觸手裏塡充了很多松松軟軟的尾巴哦。", "0", "0", "0", "0", "0", "cv_sikadi_ha_10", "0", "0"},
[415710] = {415710, 11057, 11, 5, "1_》_1000_2.5", "level5", "與吾一同瘋狂吧、染上吾的漆黑顔色吧、墜入吾無限的夢中吧！", "0", "0", "0", "0", "0", "cv_sikadi_ha_11", "0", "0"},
