[4104700200] = {4104700200, 11047002, 1, 1, "0", "0", "蒼霧殘響", "0", "0", "0", "0", "0", "cv_dangyangtu_1", "0", "0"},
[4104700201] = {4104700201, 11047002, 2, 2, "0", "0", "欸？真的不是什麼整人綜藝節目？", "0", "0", "0", "0", "0", "cv_dangyangtu_2", "0", "0"},
[4104700202] = {4104700202, 11047002, 3, 3, "0", "0", "這裡是蕩漾兔，一名活躍在網路世界的偶像~你就是我的製作人嗎？雖然並非初次見面，以後請多指教咯！", "0", "0", "0", "0", "0", "cv_dangyangtu_3", "0", "0"},
[4104700203] = {4104700203, 11047002, 91, 4, "0", "idle", "如果將城市視為一座巨大的演唱會場館，那麼多瑙可謂是座無虛席，不放聲唱首歌真有些浪費呢。", "0", "0", "0", "0", "0", "cv_dangyangtu_4", "0", "idle,idle"},
[4104700204] = {4104700204, 11047002, 94, 4, "0", "idle2", "怎麼啦怎麼啦？突然間這麼死氣沉沉的，作為我的製作人兼粉絲，不時刻保持活力的話可是會讓我很傷心的！", "0", "0", "0", "0", "0", "cv_dangyangtu_5", "0", "idle2,idle2"},
[4104700205] = {4104700205, 11047002, 98, 4, "0", "idle3", "小隊裡老有人想揪出我的真實身份，實在是傷腦筋啊，戳破了真實與虛假之間的這層面紗，許多事可就會沒有意思了。", "0", "0", "0", "0", "0", "cv_dangyangtu_6", "0", "idle3,idle3"},
[4104700206] = {4104700206, 11047002, 92, 5, "1_》_0_0.8", "touch1", "用尼姆比斯能幻化出的這具身體，操控起來的確更輕鬆了，但相比投影也少了些樂趣啊，比如說，不能裝作電子幽靈嚇唬人了~", "0", "0", "0", "0", "0", "cv_dangyangtu_7", "0", "touch1,touch1"},
[4104700207] = {4104700207, 11047002, 95, 5, "1_》_0_0.8", "touch2", "喂喂現在可不是握手會的時候啊！而且作為我的製作人，你不是每天都有機會和我互動嗎？", "0", "0", "0", "0", "0", "cv_dangyangtu_8", "0", "touch2,touch2"},
[4104700208] = {4104700208, 11047002, 106, 5, "1_》_0_0.8", "touch3", "想知道我的真實身份嗎？我已經將解開秘密的鑰匙藏在網路海洋的某一處了，請製作人自行尋找吧~當然，可別忘了有句話叫“狡兔三窟”。", "0", "0", "0", "0", "0", "cv_dangyangtu_9", "0", "touch3,touch3"},
[4104700209] = {4104700209, 11047002, 106, 5, "1_》_0_0.8", "touch4", "運營偶像身份的同時，學業也不能就這麼落下，再加上還有駕駛員的工作要做，我已經分身乏術了，看來，得更加依靠製作人才行啊~", "0", "0", "0", "0", "0", "cv_dangyangtu_10", "0", "touch4,touch4"},
[4104700210] = {4104700210, 11047002, 93, 5, "1_》_0_0.8", "switch1", "請~", "0", "0", "0", "0", "0", "cv_dangyangtu_30", "0", "switch1,switch1"},
[4104700211] = {4104700211, 11047002, 102, 5, "1_》_0_0.8", "switch2", "有新衣服嗎？", "0", "0", "0", "0", "0", "cv_dangyangtu_39", "0", "switch2,switch2"},
[4104700212] = {4104700212, 11047002, 96, 5, "1_》_0_0.8", "switch3", "雖然起初不太滿意這種安排，但能由你成為我的製作人果然最棒了~充分給予每個人自由與尊重，我想成為的正是這樣的“偶像”。", "0", "0", "0", "0", "0", "cv_dangyangtu_11", "0", "switch3,switch3"},
[4104700213] = {4104700213, 11047002, 12, 6, "0", "0", "感謝應援！", "0", "0", "0", "0", "0", "cv_dangyangtu_12", "0", "0"},
[4104700214] = {4104700214, 11047002, 13, 7, "0", "0", "得好好回饋你的愛才行了~", "0", "0", "0", "0", "0", "cv_dangyangtu_13", "0", "0"},
[4104700215] = {4104700215, 11047002, 14, 8, "0", "0", "偶像與駭客都能創造奇跡，儘管只憑歌聲或代碼無法辦到的事同樣還有許多，但……如果和你一起，我相信現在還遠遠沒到極限。", "0", "0", "0", "0", "0", "cv_dangyangtu_14", "0", "0"},
[4104700216] = {4104700216, 11047002, 15, 9, "0", "0", "身為偶像可不能懈怠。", "0", "0", "0", "0", "0", "cv_dangyangtu_15", "0", "0"},
[4104700217] = {4104700217, 11047002, 16, 10, "0", "0", "讓我聽聽，哪邊的粉絲呼聲最熱情~", "0", "0", "0", "0", "0", "cv_dangyangtu_16", "0", "0"},
[4104700218] = {4104700218, 11047002, 17, 11, "0", "0", "我不會忘記這場演出的哦。", "0", "0", "0", "0", "0", "cv_dangyangtu_17", "0", "0"},
[4104700219] = {4104700219, 11047002, 18, 12, "0", "0", "既然還不完美，未來就讓我們共同進步吧！", "0", "0", "0", "0", "0", "cv_dangyangtu_18", "0", "0"},
[4104700220] = {4104700220, 11047002, 19, 13, "0", "0", "玩鬧過頭了嗎？得認真起來了啊。", "0", "0", "0", "0", "0", "cv_dangyangtu_19", "0", "0"},
[4104700221] = {4104700221, 11047002, 20, 14, "0", "0", "事前準備還得更加充足。", "0", "0", "0", "0", "0", "cv_dangyangtu_20", "0", "0"},
[4104700222] = {4104700222, 11047002, 21, 15, "0", "0", "請這位粉絲安靜點~", "0", "0", "0", "0", "0", "cv_dangyangtu_21", "0", "0"},
[4104700223] = {4104700223, 11047002, 23, 16, "0", "0", "這次是新的曲子！", "0", "0", "0", "0", "0", "cv_dangyangtu_23", "0", "0"},
[4104700224] = {4104700224, 11047002, 24, 17, "0", "0", "陶醉其中吧~", "0", "0", "0", "0", "0", "cv_dangyangtu_24", "0", "0"},
