[423200] = {423200, 12032, 1, 1, "0", "0", "蒼霧殘響", "0", "0", "0", "0", "0", "cv_yida_01", "0", "0"},
[423201] = {423201, 12032, 2, 2, "0", "0", "這裏……存在很多安全隱患。", "0", "0", "0", "0", "0", "cv_yida_02", "0", "0"},
[423202] = {423202, 12032, 3, 3, "0", "0", "竟然是安排到領航的手下，這樣也好。", "0", "0", "0", "0", "0", "cv_yida_03", "0", "0"},
[423203] = {423203, 12032, 4, 4, "0", "idle", "我會緊盯著要道和關鍵出入口，不讓任何危險有可乘之機。", "0", "0", "0", "0", "0", "cv_yida_04", "0", "0"},
[423204] = {423204, 12032, 5, 4, "0", "idle2", "有情況……呃，是只貓啊……差點就開槍了。", "0", "0", "0", "0", "0", "cv_yida_05", "0", "0"},
[423205] = {423205, 12032, 6, 4, "0", "idle3", "聽赫洛卡說，似乎還有其他的“守夜人”。她們都藏在哪里呢？又都在守著什麼呢？真的很令人在意。", "0", "0", "0", "0", "0", "cv_yida_06", "0", "0"},
[423206] = {423206, 12032, 7, 5, "1_》_0_0.8", "level1", "我知道想要避開生活中所有的危險是不可能做到的。我只是希望自己的死因不是“樓上掉落的花盆”或者“浴缸裏通電的吹風機”這種可笑的意外。", "0", "0", "0", "0", "0", "cv_yida_07", "0", "0"},
[423207] = {423207, 12032, 8, 5, "1_》_0_0.8", "level2", "領航似乎養成了很多危險的壞習慣，需要我幫您糾正嗎？", "0", "0", "0", "0", "0", "cv_yida_08", "0", "0"},
[423208] = {423208, 12032, 9, 5, "1_》_100_1.5", "level3", "幻化的身體擁有和原本同樣的敏感度，您應該是知道的吧。", "0", "0", "0", "0", "0", "cv_yida_09", "0", "0"},
[423209] = {423209, 12032, 10, 5, "1_》_500_2", "level4", "常用的裝備要按時進行保養，這樣才能在危險來臨時發揮出它應有的作用。如果領航因為工作繁忙沒時間養護的話，我願意代勞。", "0", "0", "0", "0", "0", "cv_yida_10", "0", "0"},
[423210] = {423210, 12032, 11, 5, "1_》_1000_2.5", "level5", "有一種說法是“生命的價值在死亡的那一刻才得以體現”，而我認可的是“活著才能創造更多價值”。\n所以我們一起要好好活下去，直到老去。", "0", "0", "0", "0", "0", "cv_yida_11", "0", "0"},
[423211] = {423211, 12032, 12, 6, "0", "0", "變強了……沒有副作用吧？", "0", "0", "0", "0", "0", "cv_yida_12", "0", "0"},
[423212] = {423212, 12032, 13, 7, "0", "0", "這是一次突破，但還不夠。", "0", "0", "0", "0", "0", "cv_yida_13", "0", "0"},
[423213] = {423213, 12032, 14, 8, "0", "0", "身體的強大倒是其次，思維的敏銳才是關鍵。", "0", "0", "0", "0", "0", "cv_yida_14", "0", "0"},
[423214] = {423214, 12032, 15, 9, "0", "0", "即使如此，每日的訓練還是不能懈怠，生死的區別就在日常的細節之中。", "0", "0", "0", "0", "0", "cv_yida_15", "0", "0"},
[423215] = {423215, 12032, 16, 10, "0", "0", "先做好偵察工作，等待出手的時機吧。", "0", "0", "0", "0", "0", "cv_yida_16", "0", "0"},
[423216] = {423216, 12032, 17, 11, "0", "0", "很好，沒有人受傷，沒有人死。", "0", "0", "0", "0", "0", "cv_yida_17", "0", "0"},
[423217] = {423217, 12032, 18, 12, "0", "0", "還好，有驚無險。", "0", "0", "0", "0", "0", "cv_yida_18", "0", "0"},
[423218] = {423218, 12032, 19, 13, "0", "0", "活下來了……", "0", "0", "0", "0", "0", "cv_yida_19", "0", "0"},
