[4105800103] = {4105800103, 11058001, 91, 4, "0", "idle", "緊張的時候，只要鑽到黑暗狹窄的地方就能靜下心來……從基因層面我大概要被歸屬於夜行生物吧……", "0", "0", "0", "0", "0", "cv_sk_mika_n04", "0", "idle,idle"},
[4105800104] = {4105800104, 11058001, 91, 4, "0", "idle", "領航您也想進來嗎？", "0", "0", "0", "0", "0", "cv_sk_mika_n05", "0", "idle,idle"},
[4105800105] = {4105800105, 11058001, 91, 4, "0", "idle", "我……其實是來找領航報導的，但是等了很久您都沒有來，不知道怎麼的就鑽到您的衣櫃裏了。", "0", "0", "0", "0", "0", "cv_sk_mika_n06", "0", "idle,idle"},
[4105800106] = {4105800106, 11058001, 94, 4, "0", "idle2", "要是現在有別人進來的話……會不會產生不必要的誤會……", "0", "0", "0", "0", "0", "cv_sk_mika_n10", "0", "idle2,idle2"},
[4105800107] = {4105800107, 11058001, 94, 4, "0", "idle2", "領航的衣櫃裏有著一股特別的味道……很好聞……", "0", "0", "0", "0", "0", "cv_sk_mika_n11", "0", "idle2,idle2"},
[4105800108] = {4105800108, 11058001, 94, 4, "0", "idle2", "如果能提供食物和電腦，我大概可以在這裏生活一輩子。", "0", "0", "0", "0", "0", "cv_sk_mika_n12", "0", "idle2,idle2"},
[4105800109] = {4105800109, 11058001, 92, 5, "1_》_0_0.8", "level1", "這身衣服……是因為赫洛卡小姐說平時多穿著和AVG裝備相同款式的服裝可以增加幻化時和裝備的親和度。", "0", "0", "0", "0", "0", "cv_sk_mika_n02", "0", "level1,level1"},
[4105800110] = {4105800110, 11058001, 92, 5, "1_》_0_0.8", "level1", "我能……繼續待著這裏嗎？這裏讓我感覺很安心。", "0", "0", "0", "0", "0", "cv_sk_mika_n03", "0", "level1,level1"},
[4105800111] = {4105800111, 11058001, 95, 5, "1_》_0_0.8", "level2", "雖……雖然說這裏是衣櫃，但是在這裏……脫衣服不太好吧……", "0", "0", "0", "0", "0", "cv_sk_mika_n08", "0", "level2,level2"},
