[4300200222] = {4300200222, 13002002, 27, 20, "0", "0", "保持清潔，也是禮儀的一環。", "绮丽な状态を维持することも、礼仪作法において大事なことの一つです。", "0", "0", "保持清洁，也是礼仪的一环。", "0", "cv_tina_20", "0", "0"},
[4300200223] = {4300200223, 13002002, 28, 21, "0", "0", "不要懈怠！", "気を缓めてはいけません！", "0", "0", "不要懈怠！", "0", "cv_tina_21", "0", "0"},
