[4300200227] = {4300200227, 13002002, 32, 24, "0", "0", "不錯，這都是你自己努力的結果，值得表揚！", "素晴らしいです。これはあなたの努力の赐物でしょう。", "0", "0", "不错，这都是你自己努力的结果，值得表扬！", "0", "cv_tina_25", "0", "0"},
[4300200228] = {4300200228, 13002002, 33, 25, "0", "0", "看來……是教育方式出了問題！", "どうやら……教育方法に问题があったようですね！", "0", "0", "看来……是教育方式出了问题！", "0", "cv_tina_26", "0", "0"},
[4300200229] = {4300200229, 13002002, 34, 26, "0", "0", "准點到達，那麼就來開始今天的工作吧。", "定刻通りに到着しましたね。では、今日の仕事を始めましょう。", "0", "0", "准点到达，那么就来开始今天的工作吧。", "0", "cv_tina_28", "0", "0"},
[4300200230] = {4300200230, 13002002, 35, 27, "0", "0", "來吧，書寫屬於你的故事吧。", "さて、あなたの物语を创りましょう。", "0", "0", "来吧，书写属于你的故事吧。", "0", "cv_tina_30", "0", "0"},
[4300200231] = {4300200231, 13002002, 36, 28, "0", "0", "每天都得適當活動一下呢。", "适度なアクティビティは毎日不可欠です。", "0", "0", "每天都得适当活动一下呢。", "0", "cv_tina_31", "0", "0"},
[4300200232] = {4300200232, 13002002, 37, 29, "0", "0", "很好，人都到齊了呢。", "いいですね、皆揃っています。", "0", "0", "很好，人都到齐了呢。", "0", "cv_tina_32", "0", "0"},
[4300200233] = {4300200233, 13002002, 38, 30, "0", "0", "看來要培養的孩子又變多了呢。", "育て甲斐のあるコが、また増えそうですね。", "0", "0", "看来要培养的孩子又变多了呢。", "0", "cv_tina_33", "0", "0"},
[4300200234] = {4300200234, 13002002, 39, 31, "0", "0", "裝備對戰鬥力的提升是不可忽視的。", "装备は戦闘力を上げるのに必要なものですわ。", "0", "0", "装备对战斗力的提升是不可忽视的。", "0", "cv_tina_34", "0", "0"},
[4300200235] = {4300200235, 13002002, 40, 32, "0", "0", "採購的話，就交給我吧。", "买い付けなら、私にお任せください。", "0", "0", "采购的话，就交给我吧。", "0", "cv_tina_35", "0", "0"},
