[4300200237] = {4300200237, 13002002, 42, 34, "0", "0", "確認下設定有沒有問題吧。", "设定に问题があるかどうか、今一度ご确认ください。", "0", "0", "确认下设置有没有问题吧。", "0", "cv_tina_37", "0", "0"},
