[423300] = {423300, 12033, 1, 1, "0", "0", "蒼霧殘響", "0", "0", "0", "0", "0", "cv_guroria_her_01", "0", "0"},
[423301] = {423301, 12033, 2, 2, "0", "0", "這是一種新的訓練方式嗎？", "0", "0", "0", "0", "0", "cv_guroria_her_02", "0", "0"},
[423302] = {423302, 12033, 3, 3, "0", "0", "如您所見，領航先生，我已經做好準備接受您的專業指導了。", "0", "0", "0", "0", "0", "cv_guroria_her_03", "0", "0"},
[423303] = {423303, 12033, 4, 4, "0", "idle", "“業餘網球手”——雖然這樣説有虛張聲勢的嫌疑，但我以前在同齡人裏眞的很厲害的，領航先生。", "0", "0", "0", "0", "0", "cv_guroria_her_04", "0", "0"},
[423304] = {423304, 12033, 5, 4, "0", "idle2", "身體已經習慣了戰場，站在網球場上，即使是類似的動作，自己的感受也是截然不同的……這種恍惚的心情，有些讓人沉醉。", "0", "0", "0", "0", "0", "cv_guroria_her_05", "0", "0"},
[423305] = {423305, 12033, 6, 4, "0", "idle3", "“要是能讓多洛莉絲隊長她們大喫一驚就好了”——我是帶著這份私心在努力復健的……領航先生不會責怪我吧？", "0", "0", "0", "0", "0", "cv_guroria_her_06", "0", "0"},
[423306] = {423306, 12033, 7, 5, "1_》_0_0.8", "level1", "“以打進全國大賽爲目標努力吧”……開玩笑的，以前偷偷看漫畫的時候，就想這麽説了……", "0", "0", "0", "0", "0", "cv_guroria_her_07", "0", "0"},
[423307] = {423307, 12033, 8, 5, "1_》_0_0.8", "level2", "領航先生，有人説過你“壞心眼”嗎？故意隱藏自己實力欺負人……這種行爲會教壞小孩子的。", "0", "0", "0", "0", "0", "cv_guroria_her_08", "0", "0"},
[423308] = {423308, 12033, 9, 5, "1_》_100_1.5", "level3", "明明只是指尖的觸碰，卻會讓人心跳加速……領航先生，你能理解這種情感嗎？", "0", "0", "0", "0", "0", "cv_guroria_her_09", "0", "0"},
[423309] = {423309, 12033, 10, 5, "1_》_500_2", "level4", "比賽結束之後，我和領航先生又會回到之前的關繫了嗎……光是想象這樣的一天遲早會到來，心就好痛……不希望理應結束的事情結束，是這麽痛苦的事嗎？", "0", "0", "0", "0", "0", "cv_guroria_her_10", "0", "0"},
[423310] = {423310, 12033, 11, 5, "1_》_1000_2.5", "level5", "領航先生，“理解者”的身份，我只爲您虛席以待……只有您能走進我的心裏，明白我的渴望……任何人都無法代替您的位置……所以，我也希望，我能成爲你內心那个——不會被任何人取代的人。", "0", "0", "0", "0", "0", "cv_guroria_her_11", "0", "0"},
[423311] = {423311, 12033, 12, 6, "0", "0", "比賽的感覺回來了。", "0", "0", "0", "0", "0", "cv_guroria_her_12", "0", "0"},
[423312] = {423312, 12033, 13, 7, "0", "0", "也許眞能打進全國大賽也説不定呢？", "0", "0", "0", "0", "0", "cv_guroria_her_13", "0", "0"},
