[4104200202] = {4104200202, 11042002, 3, 3, "0", "0", "我是前線的海蘿！海蘿·特裡亞@#￥%……記不得啦，總之叫我海蘿就好！", "0", "0", "0", "0", "0", "cv_hailuo_3", "0", "0"},
[4104200203] = {4104200203, 11042002, 91, 4, "0", "idle", "不開心的時候只要去跑步就好了！陽光照在身上，風打在臉上，什麼煩惱都會忘了！", "0", "0", "0", "0", "0", "cv_hailuo_4", "0", "idle,idle"},
[4104200204] = {4104200204, 11042002, 94, 4, "0", "idle2", "這是今天要做的事情……這是明天要做的事情……OK，已經全部記下來了……嗯，話說今天是幾號……啊！這不是全部錯過了嗎！", "0", "0", "0", "0", "0", "cv_hailuo_5", "0", "idle2,idle2"},
[4104200205] = {4104200205, 11042002, 98, 4, "0", "idle3", "星爍……她那樣子真讓人擔心……啊，我不是說她的外表，是說她的精神狀態，總感覺她好像隨時都會爆炸一樣……彭！啪嗒！我很擔心她。", "0", "0", "0", "0", "0", "cv_hailuo_6", "0", "idle3,idle3"},
[4104200206] = {4104200206, 11042002, 92, 5, "1_》_0_0.8", "level1", "我沒有想要實現的事情，就算有也肯定很快就忘記吧，但是我會努力幫其他人實現夢想的，為此就算一直戰鬥下去也沒關係！", "0", "0", "0", "0", "0", "cv_hailuo_7", "0", "level1,level1"},
[4104200207] = {4104200207, 11042002, 95, 5, "1_》_0_0.8", "level2", "領航，重要的約定一定要寫在紙上，因為人的記憶是不可靠的！", "0", "0", "0", "0", "0", "cv_hailuo_8", "0", "level2,level2"},
[4104200208] = {4104200208, 11042002, 106, 5, "1_》_0_0.8", "level3", "即使記不住重要的人的名字也沒關係，因為那份感情和回憶一直會存在我和領航的心裡的！", "0", "0", "0", "0", "0", "cv_hailuo_9", "0", "level3,level3"},
[4104200209] = {4104200209, 11042002, 93, 5, "1_》_0_0.8", "switch1", "領航也失憶過嗎？我懂的我懂的，那種想不起來重要事情的感覺特別難受吧。不過只要我們還活著，還能向著未來前進，我們總能找回當初忘掉的事情的！", "0", "0", "0", "0", "0", "cv_hailuo_10", "0", "switch1,switch1"},
[4104200210] = {4104200210, 11042002, 102, 5, "1_》_0_0.8", "switch2", "領航也失憶過嗎？我懂的我懂的，那種想不起來重要事情的感覺特別難受吧。不過只要我們還活著，還能向著未來前進，我們總能找回當初忘掉的事情的！", "0", "0", "0", "0", "0", "cv_hailuo_10", "0", "switch2,switch2"},
[4104200211] = {4104200211, 11042002, 96, 5, "1_》_0_0.8", "switch3", "哼哼，作為記性不好的病友，領航要是遇到了什麼困擾就儘管和我傾訴吧，我不管什麼時候都會陪伴你在身邊的，就算是睡覺時候也會的！洗澡的時候……我不介意！", "0", "0", "0", "0", "0", "cv_hailuo_11", "0", "switch3,switch3"},
