[4101900134] = {4101900134, 11019001, 38, 30, "0", "0", "嘿嘿，我也能當別人的前輩了嗎？", "0", "0", "0", "嘿嘿，我也能当别人的前辈了吗？", "0", "cv_tenten_35", "0", "0"},
[4101900135] = {4101900135, 11019001, 39, 31, "0", "0", "打蛋器，油漏勺，油鍋……", "0", "0", "0", "打蛋器，油漏勺，油锅……", "0", "cv_tenten_36", "0", "0"},
[4101900136] = {4101900136, 11019001, 40, 32, "0", "0", "感覺能買到高端的食材。", "0", "0", "0", "感觉能买到高端的食材。", "0", "cv_tenten_37", "0", "0"},
[4101900137] = {4101900137, 11019001, 41, 33, "0", "0", "領航的名片，我會好好保存的。", "0", "0", "0", "领航的名片，我会好好保存的。", "0", "cv_tenten_38", "0", "0"},
[4101900138] = {4101900138, 11019001, 42, 34, "0", "0", "這也在考試範圍內嗎……", "0", "0", "0", "这也在考试范围内吗……", "0", "cv_tenten_39", "0", "0"},
[4101900139] = {4101900139, 11019001, 43, 35, "0", "0", "能幫我寄一封信嗎，我想寄給我的父母。", "0", "0", "0", "能帮我寄一封信吗，我想寄给我的父母。", "0", "cv_tenten_40", "0", "0"},
[4101900140] = {4101900140, 11019001, 44, 36, "0", "0", "可以交更多新的朋友！", "0", "0", "0", "可以交更多新的朋友！", "0", "cv_tenten_41", "0", "0"},
[4101900141] = {4101900141, 11019001, 45, 37, "0", "0", "開飯啦！", "0", "0", "0", "开饭啦！", "0", "cv_tenten_42", "0", "0"},
[415900] = {415900, 11059, 1, 1, "0", "0", "蒼霧！殘響！", "0", "0", "0", "0", "0", "cv_mihaier_01", "0", "0"},
[415901] = {415901, 11059, 2, 2, "0", "0", "不錯，這裏能更好地彰顯勝者的英姿。", "0", "0", "0", "0", "0", "cv_mihaier_02", "0", "0"},
[415902] = {415902, 11059, 3, 3, "0", "0", "我是米海爾，勝利的化身。我在此宣誓，之後的戰鬥您將戰無不勝。", "0", "0", "0", "0", "0", "cv_mihaier_03", "0", "0"},
[415903] = {415903, 11059, 4, 4, "0", "idle", "我將在此豎立起一座雕像，然後用無盡的勝利來證明它值得被豎立。", "0", "0", "0", "0", "0", "cv_mihaier_04", "0", "0"},
[415904] = {415904, 11059, 5, 4, "0", "idle1", "也有別的駕駛員在這裏堅守過？……她們中堅持最久的是誰？", "0", "0", "0", "0", "0", "cv_mihaier_05", "0", "0"},
[415905] = {415905, 11059, 6, 4, "0", "idle2", "法芙娜的強大配得上“惡龍”的名號。認輸？哈哈哈~被騎槍貫穿頭顱就是惡龍唯一的生存意義。", "0", "0", "0", "0", "0", "cv_mihaier_06", "0", "0"},
[415906] = {415906, 11059, 7, 5, "1_》_0_0.8", "level1", "“無法失敗，無法後退。”“追求勝利？其實是害怕承擔失敗的後果。”我不認同這樣的評價，但也無話可說。", "0", "0", "0", "0", "0", "cv_mihaier_07", "0", "0"},
[415907] = {415907, 11059, 8, 5, "1_》_0_0.8", "level2", "戰勝我，然後隨你處置。", "0", "0", "0", "0", "0", "cv_mihaier_08", "0", "0"},
[415908] = {415908, 11059, 9, 5, "1_》_100_1.5", "level3", "這個世界只有兩種人——強者和弱者。如果你認為自己是一只老鼠，那麼結果就只有成為貓的食物。", "0", "0", "0", "0", "0", "cv_mihaier_09", "0", "0"},
[415909] = {415909, 11059, 10, 5, "1_》_500_2", "level4", "我承認你是個天生的勝利者，你所指揮的每一場戰鬥都能以勝利畫上圓滿的句號。只有你這樣的勝利者有資格指揮我戰鬥。", "0", "0", "0", "0", "0", "cv_mihaier_10", "0", "0"},
[415910] = {415910, 11059, 11, 5, "1_》_1000_2.5", "level5", "聽說領航你擁有一種叫做通感的能力，可以加強駕駛員的戰鬥能力。從今以後，只需與我通感就好了，因為只有我才能幫你奪得勝利。", "0", "0", "0", "0", "0", "cv_mihaier_11", "0", "0"},
[415911] = {415911, 11059, 12, 6, "0", "0", "離下一次的勝利更進了一步。", "0", "0", "0", "0", "0", "cv_mihaier_12", "0", "0"},
[415912] = {415912, 11059, 13, 7, "0", "0", "這是勝利者的榮耀。", "0", "0", "0", "0", "0", "cv_mihaier_13", "0", "0"},
[415913] = {415913, 11059, 14, 8, "0", "0", "從現在開始我將一場不輸並為人類奪得最終的勝利。", "0", "0", "0", "0", "0", "cv_mihaier_14", "0", "0"},
[415914] = {415914, 11059, 15, 9, "0", "0", "去獲取勝利吧。", "0", "0", "0", "0", "0", "cv_mihaier_15", "0", "0"},
[415915] = {415915, 11059, 16, 10, "0", "0", "這場戰鬥的勝利就交給我吧。", "0", "0", "0", "0", "0", "cv_mihaier_16", "0", "0"},
[415916] = {415916, 11059, 17, 11, "0", "0", "我就是唯一的勝者。", "0", "0", "0", "0", "0", "cv_mihaier_17", "0", "0"},
[415917] = {415917, 11059, 18, 12, "0", "0", "無所謂，只要勝利了就行。", "0", "0", "0", "0", "0", "cv_mihaier_18", "0", "0"},
[415918] = {415918, 11059, 19, 13, "0", "0", "呵，勝利……還是屬於我。", "0", "0", "0", "0", "0", "cv_mihaier_19", "0", "0"},
[415919] = {415919, 11059, 20, 14, "0", "0", "失敗……我是失敗者？", "0", "0", "0", "0", "0", "cv_mihaier_20", "0", "0"},
[415920] = {415920, 11059, 21, 15, "0", "0", "哼，失敗者的醜態。", "0", "0", "0", "0", "0", "cv_mihaier_21", "0", "0"},
[415921] = {415921, 11059, 23, 16, "0", "0", "致勝一擊。", "0", "0", "0", "0", "0", "cv_mihaier_22", "0", "0"},
[415922] = {415922, 11059, 24, 17, "0", "0", "掙扎不過是徒勞。", "0", "0", "0", "0", "0", "cv_mihaier_23", "0", "0"},
[415923] = {415923, 11059, 25, 18, "0", "0", "你的屍體將幫我建成勝利的階梯。", "0", "0", "0", "0", "0", "cv_mihaier_24", "0", "0"},
[415924] = {415924, 11059, 26, 19, "0", "0", "不，還沒有結束，我一定……一定會贏！", "0", "0", "0", "0", "0", "cv_mihaier_26", "0", "0"},
[415925] = {415925, 11059, 27, 20, "0", "0", "這是給勝利者提供的服務嗎。", "0", "0", "0", "0", "0", "cv_mihaier_27", "0", "0"},
[415926] = {415926, 11059, 28, 21, "0", "0", "為勝利者搓背是值得驕傲的事。", "0", "0", "0", "0", "0", "cv_mihaier_28", "0", "0"},
[415927] = {415927, 11059, 29, 21, "0", "0", "緊繃的肌肉放鬆下來了。", "0", "0", "0", "0", "0", "cv_mihaier_29", "0", "0"},
[415928] = {415928, 11059, 30, 22, "0", "0", "這，這是什麼？", "0", "0", "0", "0", "0", "cv_mihaier_30", "0", "0"},
[415929] = {415929, 11059, 31, 23, "0", "0", "一定要贏啊，領航。", "0", "0", "0", "0", "0", "cv_mihaier_31", "0", "0"},
[415930] = {415930, 11059, 32, 24, "0", "0", "不愧是天生的勝利者。", "0", "0", "0", "0", "0", "cv_mihaier_32", "0", "0"},
[415931] = {415931, 11059, 33, 25, "0", "0", "切，失敗者。", "0", "0", "0", "0", "0", "cv_mihaier_33", "0", "0"},
[415932] = {415932, 11059, 34, 26, "0", "0", "我不會說什麼“歡迎回來”，我只會問“你今天贏了幾場？”", "0", "0", "0", "0", "0", "cv_mihaier_34", "0", "0"},
[415933] = {415933, 11059, 35, 27, "0", "0", "又到了收割勝利的時候了嗎？", "0", "0", "0", "0", "0", "cv_mihaier_35", "0", "0"},
[415934] = {415934, 11059, 36, 28, "0", "0", "就算是駕駛員，我也一定會贏。", "0", "0", "0", "0", "0", "cv_mihaier_36", "0", "0"},
[415935] = {415935, 11059, 37, 29, "0", "0", "還……還有這麼多人要戰勝。", "0", "0", "0", "0", "0", "cv_mihaier_37", "0", "0"},
[415936] = {415936, 11059, 38, 30, "0", "0", "都是未來的手下敗將。", "0", "0", "0", "0", "0", "cv_mihaier_38", "0", "0"},
[415937] = {415937, 11059, 39, 31, "0", "0", "新的裝備，新的勝利。", "0", "0", "0", "0", "0", "cv_mihaier_39", "0", "0"},
[415938] = {415938, 11059, 40, 32, "0", "0", "這就是市場的勝者？", "0", "0", "0", "0", "0", "cv_mihaier_40", "0", "0"},
[415939] = {415939, 11059, 41, 33, "0", "0", "有沒有考慮過換張照片？", "0", "0", "0", "0", "0", "cv_mihaier_41", "0", "0"},
[415940] = {415940, 11059, 42, 34, "0", "0", "變更設置。", "0", "0", "0", "0", "0", "cv_mihaier_42", "0", "0"},
[415941] = {415941, 11059, 43, 35, "0", "0", "有我的郵件嗎？", "0", "0", "0", "0", "0", "cv_mihaier_43", "0", "0"},
[415942] = {415942, 11059, 44, 36, "0", "0", "發表勝利宣言。", "0", "0", "0", "0", "0", "cv_mihaier_44", "0", "0"},
[415943] = {415943, 11059, 45, 37, "0", "0", "這裏？", "0", "0", "0", "0", "0", "cv_mihaier_45", "0", "0"},
[440700] = {440700, 14007, 1, 1, "0", "0", "蒼霧殘響", "0", "0", "0", "0", "0", "cv_isucara_01", "0", "0"},
[440701] = {440701, 14007, 2, 2, "0", "0", "文書工作的我倒是還算擅長。但這些重要的文件，你還是親自确認一遍比較好。説起來，你工作時想喝點什麽嗎？", "0", "0", "0", "0", "0", "cv_isucara_02", "0", "0"},
[440702] = {440702, 14007, 3, 3, "0", "0", "“中庭”所屬的駕駛員，伊斯卡拉·彼得洛夫娜·伊萬諾娃，很榮幸爲您效命……是不是太嚴肅了？咳咳，那麽，博洛特內以來好久不見，領航。", "0", "0", "0", "0", "0", "cv_isucara_03", "0", "0"},
[440703] = {440703, 14007, 4, 4, "0", "idle", "有什麽需要我處理的事情嗎？我雖然挺習慣一直站著了，但還是手頭有點事的感覺比較好。", "0", "0", "0", "0", "0", "cv_isucara_04", "0", "0"},
[440704] = {440704, 14007, 5, 4, "0", "idle2", "你的門口好像有經常被闖入的痕迹啊……需要我幫忙設置點陷阱嗎？不用？你習慣了？", "0", "0", "0", "0", "0", "cv_isucara_05", "0", "0"},
[440705] = {440705, 14007, 6, 4, "0", "idle3", "有點想起以前在吧臺後面看店的日子了……", "0", "0", "0", "0", "0", "cv_isucara_06", "0", "0"},
[440706] = {440706, 14007, 7, 5, "1_》_0_0.8", "touch1", "我的表情比以前柔和了不少？我是沒怎麽注意，不過，這應該算好事吧。", "0", "0", "0", "0", "0", "cv_isucara_07", "0", "0"},
[440707] = {440707, 14007, 8, 5, "1_》_0_0.8", "touch2", "我一開始還擔心第一硏究室會是什麽超大型秘密硏究所一樣的地方，但那裏的生活設施居然意外地全。比如，領航，你知道那地方還開了好幾家酒吧嗎?", "0", "0", "0", "0", "0", "cv_isucara_08", "0", "0"},
[440708] = {440708, 14007, 9, 5, "1_》_100_1.5", "touch3", "有人説我很多時候都表現得像有疑心病一樣。但如果能幫助更多人活下來的話，我不介意當个“病患”。", "0", "0", "0", "0", "0", "cv_isucara_09", "0", "0"},
[440709] = {440709, 14007, 10, 5, "1_》_500_2", "touch4", "戈露卡在第一硏究室的生活比我想象中正常很多，她經常能有空思考未來到底要做什麽——説實話，我完全給不出什麽好的建議，你能支支招嗎，領航？", "0", "0", "0", "0", "0", "cv_isucara_10", "0", "0"},
[440710] = {440710, 14007, 11, 5, "1_》_1000_2.5", "touch5", "我知道，自己是受了很多照顧才能站在如今這个地方的。所以，當未來的苦難來臨時，我希望我——不，我希望，你能見證我，成爲那个够格直面它的人。", "0", "0", "0", "0", "0", "cv_isucara_11", "0", "0"},
[440711] = {440711, 14007, 12, 6, "0", "0", "參數好像又出現了微妙的變化。", "0", "0", "0", "0", "0", "cv_isucara_12", "0", "0"},
[440712] = {440712, 14007, 13, 7, "0", "0", "説不定，這个箱子能變成的東西也會越來越多呢。", "0", "0", "0", "0", "0", "cv_isucara_13", "0", "0"},
[440713] = {440713, 14007, 14, 8, "0", "0", "爲了我自己，爲了所有人……我會變強的，這場戰爭不會停下來等待我們。", "0", "0", "0", "0", "0", "cv_isucara_14", "0", "0"},
[440714] = {440714, 14007, 15, 9, "0", "0", "就算看上去是相同的形態，具體的威力也還有上昇的空間。", "0", "0", "0", "0", "0", "cv_isucara_15", "0", "0"},
[440715] = {440715, 14007, 16, 10, "0", "0", "已到達指定地點，請指示，長官。", "0", "0", "0", "0", "0", "cv_isucara_16", "0", "0"},
[440716] = {440716, 14007, 17, 11, "0", "0", "被清掃一空的戰場，硝烟味似乎也沒那麽刺鼻了。", "0", "0", "0", "0", "0", "cv_isucara_17", "0", "0"},
[440717] = {440717, 14007, 18, 12, "0", "0", "保持陣型，警惕任何可能的反撲。", "0", "0", "0", "0", "0", "cv_isucara_18", "0", "0"},
[440718] = {440718, 14007, 19, 13, "0", "0", "我得去推翻很多過時的預案了。", "0", "0", "0", "0", "0", "cv_isucara_19", "0", "0"},
[440719] = {440719, 14007, 20, 14, "0", "0", "趁它們還沒從火力網裏脫身，所有人開始後撤！", "0", "0", "0", "0", "0", "cv_isucara_20", "0", "0"},
[440720] = {440720, 14007, 21, 15, "0", "0", "首要目標已清除。", "0", "0", "0", "0", "0", "cv_isucara_21", "0", "0"},
[440721] = {440721, 14007, 23, 16, "0", "0", "這下會很重的！", "0", "0", "0", "0", "0", "cv_isucara_22", "0", "0"},
[440722] = {440722, 14007, 24, 17, "0", "0", "目標進入射界——開火。", "0", "0", "0", "0", "0", "cv_isucara_23", "0", "0"},
[440723] = {440723, 14007, 25, 18, "0", "0", "安全限制解除——全員，避開火力區！", "0", "0", "0", "0", "0", "cv_isucara_24", "0", "0"},
[440724] = {440724, 14007, 26, 19, "0", "0", "抱歉，我會……盡快返回。", "0", "0", "0", "0", "0", "cv_isucara_26", "0", "0"},
[440725] = {440725, 14007, 27, 20, "0", "0", "要不還是讓我自己來吧……就算是我這種大齡單身女，也還是會害羞的，明白嗎？", "0", "0", "0", "0", "0", "cv_isucara_27", "0", "0"},
[440726] = {440726, 14007, 28, 21, "0", "0", "呼……嗚哇，居然眞的差點睡著了。", "0", "0", "0", "0", "0", "cv_isucara_28", "0", "0"},
[440727] = {440727, 14007, 29, 21, "0", "0", "以前有一次我和隊長比蒸桑拏，最後好像……一起昏死在裏面了。", "0", "0", "0", "0", "0", "cv_isucara_29", "0", "0"},
[440728] = {440728, 14007, 30, 22, "0", "0", "有什麽意外的情況嗎？", "0", "0", "0", "0", "0", "cv_isucara_30", "0", "0"},
[440729] = {440729, 14007, 31, 23, "0", "0", "我的背上畱過好幾道疤來著……不對，巨大化的時候好像全都去掉了。", "0", "0", "0", "0", "0", "cv_isucara_31", "0", "0"},
[440730] = {440730, 14007, 32, 24, "0", "0", "我相信你的眼光哦，小哥。", "0", "0", "0", "0", "0", "cv_isucara_32", "0", "0"},
[440731] = {440731, 14007, 33, 25, "0", "0", "啊——沒辦法嘛，總有狀態不好的日子。", "0", "0", "0", "0", "0", "cv_isucara_33", "0", "0"},
[440732] = {440732, 14007, 34, 26, "0", "0", "啊，你回來了。我調了些提神的東西，要嘗嘗看嗎？", "0", "0", "0", "0", "0", "cv_isucara_34", "0", "0"},
[440733] = {440733, 14007, 35, 27, "0", "0", "我們永遠面對的，這場戰爭……", "0", "0", "0", "0", "0", "cv_isucara_35", "0", "0"},
[440734] = {440734, 14007, 36, 28, "0", "0", "遇上隊長的話，這應該也會被她算進計數里吧。", "0", "0", "0", "0", "0", "cv_isucara_36", "0", "0"},
[440735] = {440735, 14007, 37, 29, "0", "0", "以前的部隊名册裏可沒有這麽多女孩子啊。", "0", "0", "0", "0", "0", "cv_isucara_37", "0", "0"},
[440736] = {440736, 14007, 38, 30, "0", "0", "畢竟戰爭中的人手總是不嫌多嘛。", "0", "0", "0", "0", "0", "cv_isucara_38", "0", "0"},
