[4003800213] = {4003800213, 10038002, 12, 6, "0", "0", "平平無奇。", "0", "0", "0", "0", "0", "cv_heluoka_12", "0", "0"},
[4003800214] = {4003800214, 10038002, 13, 7, "0", "0", "有趣的提升方式。", "0", "0", "0", "0", "0", "cv_heluoka_13", "0", "0"},
[4003800215] = {4003800215, 10038002, 14, 8, "0", "0", "這倒是出乎我的意料了。", "0", "0", "0", "0", "0", "cv_heluoka_14", "0", "0"},
[4003800216] = {4003800216, 10038002, 15, 9, "0", "0", "我覺得也不是很有必要。", "0", "0", "0", "0", "0", "cv_heluoka_15", "0", "0"},
[4003800217] = {4003800217, 10038002, 16, 10, "0", "0", "吸引了很多“魚”嘛。", "0", "0", "0", "0", "0", "cv_heluoka_16", "0", "0"},
[4003800218] = {4003800218, 10038002, 17, 11, "0", "0", "你怎麼知道我釣上了大魚？", "0", "0", "0", "0", "0", "cv_heluoka_17", "0", "0"},
[4003800219] = {4003800219, 10038002, 18, 12, "0", "0", "正常情況，下次早點拉杆。", "0", "0", "0", "0", "0", "cv_heluoka_18", "0", "0"},
[4003800220] = {4003800220, 10038002, 19, 13, "0", "0", "至少不是一無所獲。", "0", "0", "0", "0", "0", "cv_heluoka_19", "0", "0"},
[4003800221] = {4003800221, 10038002, 20, 14, "0", "0", "空軍了……", "0", "0", "0", "0", "0", "cv_heluoka_20", "0", "0"},
[4003800222] = {4003800222, 10038002, 21, 15, "0", "0", "上鉤。", "0", "0", "0", "0", "0", "cv_heluoka_21", "0", "0"},
[4003800223] = {4003800223, 10038002, 23, 16, "0", "0", "被魚竿砸到可是很痛的。", "0", "0", "0", "0", "0", "cv_heluoka_22", "0", "0"},
[4003800224] = {4003800224, 10038002, 24, 17, "0", "0", "可別期待我先松手。", "0", "0", "0", "0", "0", "cv_heluoka_23", "0", "0"},
[4003800225] = {4003800225, 10038002, 25, 18, "0", "0", "拿你作為今天的收杆魚。", "0", "0", "0", "0", "0", "cv_heluoka_25", "0", "0"},
[4003800226] = {4003800226, 10038002, 26, 19, "0", "0", "我回去拿備用竿。", "0", "0", "0", "0", "0", "cv_heluoka_26", "0", "0"},
[4003800227] = {4003800227, 10038002, 27, 20, "0", "0", "有水的地方就有魚。", "0", "0", "0", "0", "0", "cv_heluoka_27", "0", "0"},
[4003800228] = {4003800228, 10038002, 28, 21, "0", "0", "身上有汗味？是穿的裝甲太厚的緣故吧，巨大化後的身體也還是會流汗的。", "0", "0", "0", "0", "0", "cv_heluoka_28", "0", "0"},
[4003800229] = {4003800229, 10038002, 29, 21, "0", "0", "溝溝縫縫裏都要清洗幹淨哦，拜托了。", "0", "0", "0", "0", "0", "cv_heluoka_29", "0", "0"},
[4003800230] = {4003800230, 10038002, 30, 22, "0", "0", "到底會發生什麼呢？", "0", "0", "0", "0", "0", "cv_heluoka_30", "0", "0"},
[4003800231] = {4003800231, 10038002, 31, 23, "0", "0", "我期待領航的答案。", "0", "0", "0", "0", "0", "cv_heluoka_31", "0", "0"},
[4003800232] = {4003800232, 10038002, 32, 24, "0", "0", "領航記得還真清楚……", "0", "0", "0", "0", "0", "cv_heluoka_32", "0", "0"},
[4003800233] = {4003800233, 10038002, 33, 25, "0", "0", "果然我這種人不值得被領航記住。", "0", "0", "0", "0", "0", "cv_heluoka_33", "0", "0"},
[4003800234] = {4003800234, 10038002, 34, 26, "0", "0", "歡迎回來，猜猜看在你離開的這段時間裏，我釣上了幾條大魚。", "0", "0", "0", "0", "0", "cv_heluoka_34", "0", "0"},
[4003800235] = {4003800235, 10038002, 35, 27, "0", "0", "來點出人意料的展開。", "0", "0", "0", "0", "0", "cv_heluoka_35", "0", "0"},
[4003800236] = {4003800236, 10038002, 36, 28, "0", "0", "戰前就確定的結局，無聊。", "0", "0", "0", "0", "0", "cv_heluoka_36", "0", "0"},
[4003800237] = {4003800237, 10038002, 37, 29, "0", "0", "你們之間一定發生過很多有趣的事。", "0", "0", "0", "0", "0", "cv_heluoka_37", "0", "0"},
[4003800238] = {4003800238, 10038002, 38, 30, "0", "0", "下一個上鉤的會是哪位？", "0", "0", "0", "0", "0", "cv_heluoka_38", "0", "0"},
[4003800239] = {4003800239, 10038002, 39, 31, "0", "0", "給我換一身清涼些的裝甲。", "0", "0", "0", "0", "0", "cv_heluoka_39", "0", "0"},
[4003800240] = {4003800240, 10038002, 40, 32, "0", "0", "不需要新魚竿了。", "0", "0", "0", "0", "0", "cv_heluoka_40", "0", "0"},
[4003800241] = {4003800241, 10038002, 41, 33, "0", "0", "告訴我一些檔案上沒有的事吧。", "0", "0", "0", "0", "0", "cv_heluoka_41", "0", "0"},
[4003800242] = {4003800242, 10038002, 42, 34, "0", "0", "這個按鈕按下去會發什麼？我按。", "0", "0", "0", "0", "0", "cv_heluoka_42", "0", "0"},
[4003800243] = {4003800243, 10038002, 43, 35, "0", "0", "釣魚郵件？", "0", "0", "0", "0", "0", "cv_heluoka_43", "0", "0"},
[4003800244] = {4003800244, 10038002, 44, 36, "0", "0", "驚喜往往就藏在其中。", "0", "0", "0", "0", "0", "cv_heluoka_44", "0", "0"},
[4003800245] = {4003800245, 10038002, 45, 37, "0", "0", "嗯。", "0", "0", "0", "0", "0", "cv_heluoka_45", "0", "0"},
[423400] = {423400, 12034, 1, 1, "0", "0", "蒼霧殘響", "0", "0", "0", "0", "0", "cv_efugeniaD_01", "0", "0"},
[423401] = {423401, 12034, 2, 2, "0", "0", "你的房間還是老樣子啊。要我幫你加幾個室內健身設施嗎？我有很推薦的牌子哦。", "0", "0", "0", "0", "0", "cv_efugeniaD_02", "0", "0"},
[423402] = {423402, 12034, 3, 3, "0", "0", "又見面啦，領航！這身裝備是艾吉斯工程部做給我的，怎麼樣，合適嗎？", "0", "0", "0", "0", "0", "cv_efugeniaD_03", "0", "0"},
[423403] = {423403, 12034, 4, 4, "0", "idle", "還好我的義肢是可以調節力量輔助等級的款式呢，要是調不了這個，我應該早就被空虛感淹死了。", "0", "0", "0", "0", "0", "cv_efugeniaD_04", "0", "0"},
[423404] = {423404, 12034, 5, 4, "0", "idle2", "疼——嗚啊，撞到桌角了……這個模擬痛覺真夠還原的。但就是這樣才好，會感到痛，人才能有活著的感覺。", "0", "0", "0", "0", "0", "cv_efugeniaD_05", "0", "0"},
[423405] = {423405, 12034, 6, 4, "0", "idle3", "領航，你角落裏這疊書是特維莎留下來的嗎？那我還是別亂動了，回頭惹她生氣就糟了。", "0", "0", "0", "0", "0", "cv_efugeniaD_06", "0", "0"},
[423406] = {423406, 12034, 7, 5, "1_》_0_0.8", "touch", "你還有在堅持我之前教你的那幾種鍛煉方法嗎，領航？怎麼樣，有效果嗎——沒感覺有？怎麼可能！？", "0", "0", "0", "0", "0", "cv_efugeniaD_07", "0", "0"},
[423407] = {423407, 12034, 8, 5, "1_》_0_0.8", "touch2", "雖然揍扁原罪還是最關鍵的。但說真的，工程部給我研發的這身裝備超——好用的！我回頭帶你去天上兜兜風怎麼樣，領航？", "0", "0", "0", "0", "0", "cv_efugeniaD_08", "0", "0"},
[423408] = {423408, 12034, 9, 5, "1_》_100_1.5", "touch3", "上次那件事之後，總感覺塞倫對我的態度變得有些微妙了呢，如果只是我的錯覺就好了，啊哈哈……領航，你們多瑙特別聯合部隊還有位置嗎？", "0", "0", "0", "0", "0", "cv_efugeniaD_09", "0", "0"},
[423409] = {423409, 12034, 10, 5, "1_》_500_2", "touch4", "說來挺奇妙的。對我來說，巨大化時受傷帶來的痛感，其實比平時義肢模擬給我的那些都更接近真實。不過嘛，我就是我，所以沒什麼大不了的。", "0", "0", "0", "0", "0", "cv_efugeniaD_10", "0", "0"},
[423410] = {423410, 12034, 11, 5, "1_》_1000_2.5", "touch5", "我早就習慣用這副面貌示人了。所以，哪怕在根底上是裝的，在處理細膩感情這方面的經驗也確實是一點沒有。所以，在你希望我能細膩一點時，一定要提醒我哦，領航。", "0", "0", "0", "0", "0", "cv_efugeniaD_11", "0", "0"},
[423411] = {423411, 12034, 12, 6, "0", "0", "成長的感覺，真懷念啊。", "0", "0", "0", "0", "0", "cv_efugeniaD_12", "0", "0"},
[423412] = {423412, 12034, 13, 7, "0", "0", "哦哦，感覺自己又能飛得更快點了！", "0", "0", "0", "0", "0", "cv_efugeniaD_13", "0", "0"},
[423413] = {423413, 12034, 14, 8, "0", "0", "適應新裝備的過程真是出乎意料地有趣！如果早些發現這點就好了。", "0", "0", "0", "0", "0", "cv_efugeniaD_14", "0", "0"},
[423414] = {423414, 12034, 15, 9, "0", "0", "出力提升！", "0", "0", "0", "0", "0", "cv_efugeniaD_15", "0", "0"},
[423415] = {423415, 12034, 16, 10, "0", "0", "自晴空之上，颯爽登場！", "0", "0", "0", "0", "0", "cv_efugeniaD_16", "0", "0"},
[423416] = {423416, 12034, 17, 11, "0", "0", "好，處理得就像卡佳的大晴天一樣乾淨！", "0", "0", "0", "0", "0", "cv_efugeniaD_17", "0", "0"},
[423417] = {423417, 12034, 18, 12, "0", "0", "沒有做到最好呢，要我再去試試嗎？", "0", "0", "0", "0", "0", "cv_efugeniaD_18", "0", "0"},
[423418] = {423418, 12034, 19, 13, "0", "0", "贏得好慘啊……有需要我救援的人嗎？", "0", "0", "0", "0", "0", "cv_efugeniaD_19", "0", "0"},
[423419] = {423419, 12034, 20, 14, "0", "0", "帶著其他人先跑吧。我會用速度拖住它們的，不用擔心我。", "0", "0", "0", "0", "0", "cv_efugeniaD_20", "0", "0"},
[423420] = {423420, 12034, 21, 15, "0", "0", "OK，一分！", "0", "0", "0", "0", "0", "cv_efugeniaD_21", "0", "0"},
[423421] = {423421, 12034, 23, 16, "0", "0", "吃我一拳！", "0", "0", "0", "0", "0", "cv_efugeniaD_22", "0", "0"},
[423422] = {423422, 12034, 24, 17, "0", "0", "被刺穿吧！", "0", "0", "0", "0", "0", "cv_efugeniaD_23", "0", "0"},
[423423] = {423423, 12034, 22, 38, "0", "0", "積蓄力量，然後再一口氣——", "0", "0", "0", "0", "0", "cv_efugeniaD_25", "0", "0"},
[423424] = {423424, 12034, 25, 18, "0", "0", "眼睛跟不上的話，可別怪我哦！", "0", "0", "0", "0", "0", "cv_efugeniaD_24", "0", "0"},
[423425] = {423425, 12034, 26, 19, "0", "0", "啊呀，終究還是有不習慣的地方嗎……", "0", "0", "0", "0", "0", "cv_efugeniaD_26", "0", "0"},
[423426] = {423426, 12034, 27, 20, "0", "0", "都是老熟人啦，我就不客氣咯。", "0", "0", "0", "0", "0", "cv_efugeniaD_27", "0", "0"},
[423427] = {423427, 12034, 28, 21, "0", "0", "啊……畢竟是這種場合，偷懶一下應該也行吧。", "0", "0", "0", "0", "0", "cv_efugeniaD_28", "0", "0"},
[423428] = {423428, 12034, 29, 21, "0", "0", "以前也有和伊斯卡在類似的地方較過勁呢，雖然結果怎樣我忘了。", "0", "0", "0", "0", "0", "cv_efugeniaD_29", "0", "0"},
[423429] = {423429, 12034, 30, 22, "0", "0", "嗯~發生什麼了？", "0", "0", "0", "0", "0", "cv_efugeniaD_30", "0", "0"},
[423430] = {423430, 12034, 31, 23, "0", "0", "怎麼樣，雖然裝備換了，但身體還是一樣的吧？", "0", "0", "0", "0", "0", "cv_efugeniaD_31", "0", "0"},
[423431] = {423431, 12034, 32, 24, "0", "0", "你成全了我的好心情哦，雖然本來就很好~", "0", "0", "0", "0", "0", "cv_efugeniaD_32", "0", "0"},
[423432] = {423432, 12034, 33, 25, "0", "0", "我傷心了，我要把自己關在訓練房裏了。", "0", "0", "0", "0", "0", "cv_efugeniaD_33", "0", "0"},
[423433] = {423433, 12034, 34, 26, "0", "0", "歡迎回來，領航。說吧說吧，接下來的計畫是什麼？", "0", "0", "0", "0", "0", "cv_efugeniaD_34", "0", "0"},
[423434] = {423434, 12034, 35, 27, "0", "0", "要出戰了是吧？一定要帶上我哦！", "0", "0", "0", "0", "0", "cv_efugeniaD_35", "0", "0"},
[423435] = {423435, 12034, 36, 28, "0", "0", "演習啊，用這套裝備區嚇嚇那些老對手也不錯呢。", "0", "0", "0", "0", "0", "cv_efugeniaD_36", "0", "0"},
[423436] = {423436, 12034, 37, 29, "0", "0", "大家都還是老樣子啊。", "0", "0", "0", "0", "0", "cv_efugeniaD_37", "0", "0"},
[423437] = {423437, 12034, 38, 30, "0", "0", "最近有什麼有趣的新面孔嗎，其中有誰想和我過過招嗎？", "0", "0", "0", "0", "0", "cv_efugeniaD_38", "0", "0"},
[423438] = {423438, 12034, 39, 31, "0", "0", "新裝備？可以再往我背後加兩個噴口嗎？", "0", "0", "0", "0", "0", "cv_efugeniaD_39", "0", "0"},
[423439] = {423439, 12034, 40, 32, "0", "0", "欸，我來負責資金管理嗎？你的心真大。", "0", "0", "0", "0", "0", "cv_efugeniaD_40", "0", "0"},
[423440] = {423440, 12034, 41, 33, "0", "0", "你在檔案裏的戰績又增加了呢，了不起。", "0", "0", "0", "0", "0", "cv_efugeniaD_41", "0", "0"},
[423441] = {423441, 12034, 42, 34, "0", "0", "嗯？現在的設置有什麼問題嗎？", "0", "0", "0", "0", "0", "cv_efugeniaD_42", "0", "0"},
[423442] = {423442, 12034, 43, 35, "0", "0", "不知道之前戰報裏的那幾個地方，後來怎麼樣了。", "0", "0", "0", "0", "0", "cv_efugeniaD_43", "0", "0"},
[423443] = {423443, 12034, 44, 36, "0", "0", "這裏的人一如既往地很多呢。", "0", "0", "0", "0", "0", "cv_efugeniaD_44", "0", "0"},
[423444] = {423444, 12034, 45, 37, "0", "0", "好，我點。", "0", "0", "0", "0", "0", "cv_efugeniaD_45", "0", "0"},
[4203400100] = {4203400100, 12034001, 1, 1, "0", "0", "蒼霧殘響", "0", "0", "0", "0", "0", "cv_sk_efugeniaD_01", "0", "0"},
[4203400101] = {4203400101, 12034001, 2, 2, "0", "0", "你的房間還是老樣子啊。要我幫你加幾個室內健身設施嗎？我有很推薦的牌子哦。", "0", "0", "0", "0", "0", "cv_sk_efugeniaD_02", "0", "0"},
[4203400102] = {4203400102, 12034001, 3, 3, "0", "0", "又見面啦，領航！這身裝備是艾吉斯工程部做給我的，怎麼樣，合適嗎？", "0", "0", "0", "0", "0", "cv_sk_efugeniaD_03", "0", "0"},
[4203400103] = {4203400103, 12034001, 91, 4, "0", "idle", "呀——冬天果然就是要配上伏特加啊。而且卡佳一年到頭都跟冬天一樣，世上怎麽會有這麽巧的事啊，對不對~", "0", "0", "0", "0", "0", "cv_sk_efugeniaD_n04", "0", "idle,idle"},
[4203400104] = {4203400104, 12034001, 91, 4, "0", "idle", "領航，你要不要來試試看，我毛衣上這兩根細綫到底連著什麽東西？", "0", "0", "0", "0", "0", "cv_sk_efugeniaD_n05", "0", "idle,idle"},
[4203400105] = {4203400105, 12034001, 91, 4, "0", "idle", "我這輩子還沒見過幾个能喝得過我的人呢。怎麽樣，要不要來挑戰一下？", "0", "0", "0", "0", "0", "cv_sk_efugeniaD_n06", "0", "idle,idle"},
[4203400106] = {4203400106, 12034001, 94, 4, "0", "idle2", "特維莎她最近都不願意陪我喝酒了呢，這也算是小孩子叛逆期的其中一環吧……", "0", "0", "0", "0", "0", "cv_sk_efugeniaD_n10", "0", "idle2,idle2"},
[4203400107] = {4203400107, 12034001, 94, 4, "0", "idle2", "我去倒杯水好了。嗯，水杯放在哪來著……喔哇啊！……扶，扶我一把，領航。感覺，不該連會腿軟這種部分都還原的……", "0", "0", "0", "0", "0", "cv_sk_efugeniaD_n11", "0", "idle2,idle2"},
[4203400108] = {4203400108, 12034001, 94, 4, "0", "idle2", "我喝醉了？哪有~我清醒得要命，不信你可以來考我……呼……呼……", "0", "0", "0", "0", "0", "cv_sk_efugeniaD_n12", "0", "idle2,idle2"},
[4203400109] = {4203400109, 12034001, 92, 5, "1_》_0_0.8", "touch1", "你也來一口不，領航？", "0", "0", "0", "0", "0", "cv_sk_efugeniaD_n02", "0", "touch1,touch1"},
[4203400110] = {4203400110, 12034001, 92, 5, "1_》_0_0.8", "touch1", "有人跟我推薦過那種讓人完全不會喝醉的改造手術呢。但那種東西完——全沒意思啊，我壓根沒考慮過。", "0", "0", "0", "0", "0", "cv_sk_efugeniaD_n03", "0", "touch1,touch1"},
[4203400111] = {4203400111, 12034001, 95, 5, "1_》_0_0.8", "touch2", "總感覺還是有點熱啊。要不，再脫一件好了？", "0", "0", "0", "0", "0", "cv_sk_efugeniaD_n08", "0", "touch2,touch2"},
[4203400112] = {4203400112, 12034001, 95, 5, "1_》_0_0.8", "touch2", "喝得這麽開心的時候，一般不會突然有出勤電話打過來吧——啊，還是別説這種話了。", "0", "0", "0", "0", "0", "cv_sk_efugeniaD_n09", "0", "touch2,touch2"},
[4203400113] = {4203400113, 12034001, 93, 5, "1_》_0_0.8", "switch1", "好——熱——", "0", "0", "0", "0", "0", "cv_sk_efugeniaD_n01", "0", "switch1,switch1"},
[4203400114] = {4203400114, 12034001, 96, 5, "1_》_0_0.8", "switch2", "你要幫我穿嗎？謝謝~", "0", "0", "0", "0", "0", "cv_sk_efugeniaD_n07", "0", "switch2,switch2"},
[4203400115] = {4203400115, 12034001, 12, 6, "0", "0", "成長的感覺，真懷念啊。", "0", "0", "0", "0", "0", "cv_sk_efugeniaD_12", "0", "0"},
[4203400116] = {4203400116, 12034001, 13, 7, "0", "0", "哦哦，感覺自己又能飛得更快點了！", "0", "0", "0", "0", "0", "cv_sk_efugeniaD_13", "0", "0"},
[4203400117] = {4203400117, 12034001, 14, 8, "0", "0", "適應新裝備的過程真是出乎意料地有趣！如果早些發現這點就好了。", "0", "0", "0", "0", "0", "cv_sk_efugeniaD_14", "0", "0"},
[4203400118] = {4203400118, 12034001, 15, 9, "0", "0", "出力提升！", "0", "0", "0", "0", "0", "cv_sk_efugeniaD_15", "0", "0"},
[4203400119] = {4203400119, 12034001, 16, 10, "0", "0", "自晴空之上，颯爽登場！", "0", "0", "0", "0", "0", "cv_sk_efugeniaD_16", "0", "0"},
[4203400120] = {4203400120, 12034001, 17, 11, "0", "0", "好，處理得就像卡佳的大晴天一樣乾淨！", "0", "0", "0", "0", "0", "cv_sk_efugeniaD_17", "0", "0"},
[4203400121] = {4203400121, 12034001, 18, 12, "0", "0", "沒有做到最好呢，要我再去試試嗎？", "0", "0", "0", "0", "0", "cv_sk_efugeniaD_18", "0", "0"},
[4203400122] = {4203400122, 12034001, 19, 13, "0", "0", "贏得好慘啊……有需要我救援的人嗎？", "0", "0", "0", "0", "0", "cv_sk_efugeniaD_19", "0", "0"},
[4203400123] = {4203400123, 12034001, 20, 14, "0", "0", "帶著其他人先跑吧。我會用速度拖住它們的，不用擔心我。", "0", "0", "0", "0", "0", "cv_sk_efugeniaD_20", "0", "0"},
[4203400124] = {4203400124, 12034001, 21, 15, "0", "0", "下輩子見咯。", "0", "0", "0", "0", "0", "cv_sk_efugeniaD_n13", "0", "0"},
[4203400125] = {4203400125, 12034001, 23, 16, "0", "0", "用這一下把你送上天！", "0", "0", "0", "0", "0", "cv_sk_efugeniaD_n14", "0", "0"},
[4203400126] = {4203400126, 12034001, 24, 17, "0", "0", "打！樁！拳！", "0", "0", "0", "0", "0", "cv_sk_efugeniaD_n15", "0", "0"},
[4203400127] = {4203400127, 12034001, 22, 38, "0", "0", "我要全力以赴咯！", "0", "0", "0", "0", "0", "cv_sk_efugeniaD_n17", "0", "0"},
[4203400128] = {4203400128, 12034001, 25, 18, "0", "0", "眼睛跟不上的話，可別怪我哦！", "0", "0", "0", "0", "0", "cv_sk_efugeniaD_n16", "0", "0"},
[4203400129] = {4203400129, 12034001, 26, 19, "0", "0", "哪裏出了問題呢……", "0", "0", "0", "0", "0", "cv_sk_efugeniaD_n18", "0", "0"},
[4203400130] = {4203400130, 12034001, 27, 20, "0", "0", "都是老熟人啦，我就不客氣咯。", "0", "0", "0", "0", "0", "cv_sk_efugeniaD_27", "0", "0"},
[4203400131] = {4203400131, 12034001, 28, 21, "0", "0", "啊……畢竟是這種場合，偷懶一下應該也行吧。", "0", "0", "0", "0", "0", "cv_sk_efugeniaD_28", "0", "0"},
[4203400132] = {4203400132, 12034001, 29, 21, "0", "0", "以前也有和伊斯卡在類似的地方較過勁呢，雖然結果怎樣我忘了。", "0", "0", "0", "0", "0", "cv_sk_efugeniaD_29", "0", "0"},
[4203400133] = {4203400133, 12034001, 30, 22, "0", "0", "嗯~發生什麼了？", "0", "0", "0", "0", "0", "cv_sk_efugeniaD_30", "0", "0"},
[4203400134] = {4203400134, 12034001, 31, 23, "0", "0", "怎麼樣，雖然裝備換了，但身體還是一樣的吧？", "0", "0", "0", "0", "0", "cv_sk_efugeniaD_31", "0", "0"},
[4203400135] = {4203400135, 12034001, 32, 24, "0", "0", "你成全了我的好心情哦，雖然本來就很好~", "0", "0", "0", "0", "0", "cv_sk_efugeniaD_32", "0", "0"},
[4203400136] = {4203400136, 12034001, 33, 25, "0", "0", "我傷心了，我要把自己關在訓練房裏了。", "0", "0", "0", "0", "0", "cv_sk_efugeniaD_33", "0", "0"},
[4203400137] = {4203400137, 12034001, 34, 26, "0", "0", "啊，你可算來啦，領航！一个人喝酒好無聊的！", "0", "0", "0", "0", "0", "cv_sk_efugeniaD_n19", "0", "0"},
[4203400138] = {4203400138, 12034001, 35, 27, "0", "0", "要出戰了是吧？一定要帶上我哦！", "0", "0", "0", "0", "0", "cv_sk_efugeniaD_35", "0", "0"},
[4203400139] = {4203400139, 12034001, 36, 28, "0", "0", "演習啊，用這套裝備去嚇嚇那些老對手也不錯呢。", "0", "0", "0", "0", "0", "cv_sk_efugeniaD_36", "0", "0"},
[4203400140] = {4203400140, 12034001, 37, 29, "0", "0", "大家都還是老樣子啊。", "0", "0", "0", "0", "0", "cv_sk_efugeniaD_37", "0", "0"},
[4203400141] = {4203400141, 12034001, 38, 30, "0", "0", "最近有什麼有趣的新面孔嗎，其中有誰想和我過過招嗎？", "0", "0", "0", "0", "0", "cv_sk_efugeniaD_38", "0", "0"},
[4203400142] = {4203400142, 12034001, 39, 31, "0", "0", "新裝備？可以再往我背後加兩個噴口嗎？", "0", "0", "0", "0", "0", "cv_sk_efugeniaD_39", "0", "0"},
[4203400143] = {4203400143, 12034001, 40, 32, "0", "0", "欸，我來負責資金管理嗎？你的心真大。", "0", "0", "0", "0", "0", "cv_sk_efugeniaD_40", "0", "0"},
[4203400144] = {4203400144, 12034001, 41, 33, "0", "0", "你在檔案裏的戰績又增加了呢，了不起。", "0", "0", "0", "0", "0", "cv_sk_efugeniaD_41", "0", "0"},
[4203400145] = {4203400145, 12034001, 42, 34, "0", "0", "嗯？現在的設置有什麼問題嗎？", "0", "0", "0", "0", "0", "cv_sk_efugeniaD_42", "0", "0"},
[4203400146] = {4203400146, 12034001, 43, 35, "0", "0", "不知道之前戰報裏的那幾個地方，後來怎麼樣了。", "0", "0", "0", "0", "0", "cv_sk_efugeniaD_43", "0", "0"},
[4203400147] = {4203400147, 12034001, 44, 36, "0", "0", "這裏的人一如既往地很多呢。", "0", "0", "0", "0", "0", "cv_sk_efugeniaD_44", "0", "0"},
[4203400148] = {4203400148, 12034001, 45, 37, "0", "0", "好，我點。", "0", "0", "0", "0", "0", "cv_sk_efugeniaD_45", "0", "0"},
[404500] = {404500, 10045, 1, 1, "0", "0", "蒼霧殘響", "0", "0", "0", "0", "0", "cv_teberda_01", "0", "0"},
[404501] = {404501, 10045, 2, 2, "0", "0", "好，那我就先去那邊的沙發上躺著了，有什麼事就叫我。風衣我能掛在這嗎？", "0", "0", "0", "0", "0", "cv_teberda_02", "0", "0"},
[404502] = {404502, 10045, 3, 3, "0", "0", "初次見面，我是“鋼輪戈爾”的駕駛員特薇爾達，很高興能認識——等等，原來是你啊。早說嘛，用剛剛那種方式說話很費力的。", "0", "0", "0", "0", "0", "cv_teberda_03", "0", "0"},
[404503] = {404503, 10045, 4, 4, "0", "idle", "這裏能抽煙嗎？嗯，理所當然地不能，方舟上就不能多設幾個吸煙區嗎？", "0", "0", "0", "0", "0", "cv_teberda_04", "0", "0"},
[404504] = {404504, 10045, 5, 4, "0", "idle2", "我嘴裏這個東西？棍狀薄荷糖。我習慣在嘴裏隨便叼點什麼東西了，能幫我保持精神安定。", "0", "0", "0", "0", "0", "cv_teberda_05", "0", "0"},
[404505] = {404505, 10045, 6, 4, "0", "idle3", "好無聊啊……我想小睡一會兒可以嗎？站著睡就行，我很擅長這個，不會被人看出來的。", "0", "0", "0", "0", "0", "cv_teberda_06", "0", "0"},
[404506] = {404506, 10045, 7, 5, "1_》_0_0.8", "level1", "你角落裏那幾個快報廢的機器能給我看看嗎？我想用來打發下時間，說不定順手就給你修好了呢。", "0", "0", "0", "0", "0", "cv_teberda_07", "0", "0"},
[404507] = {404507, 10045, 8, 5, "1_》_0_0.8", "level2", "我可以在能力範圍裏幫您處理一些事情，比如傳遞文書，當保鏢，成為您進行公益捐款的對象，或者省下你專門去工程部找個技工的麻煩。", "0", "0", "0", "0", "0", "cv_teberda_08", "0", "0"},
[404508] = {404508, 10045, 9, 5, "1_》_100_1.5", "level3", "第一次見面時沒想到我是這樣的人？可惜了，世上沒有後悔藥。作為替代，我倒是可以換葉格沙過來吵死你。", "0", "0", "0", "0", "0", "cv_teberda_09", "0", "0"},
[404509] = {404509, 10045, 10, 5, "1_》_500_2", "level4", "我現在這種樣子……大概算是過去的反噬吧。經歷過那種日子後，我已經對保持嚴肅產生生理厭惡了。", "0", "0", "0", "0", "0", "cv_teberda_10", "0", "0"},
[404510] = {404510, 10045, 11, 5, "1_》_1000_2.5", "level5", "我確實很討厭偽裝自己。但與此同時，能讓我毫不在意地暴露本性的人也是少數。你在這點上和葉格沙是同類，要銘記於心，領航。", "0", "0", "0", "0", "0", "cv_teberda_11", "0", "0"},
[404511] = {404511, 10045, 12, 6, "0", "0", "就算變強了也不用擔心長出太多肌肉呢，不錯。", "0", "0", "0", "0", "0", "cv_teberda_12", "0", "0"},
[404512] = {404512, 10045, 13, 7, "0", "0", "我的假期能隨這個變多些嗎？", "0", "0", "0", "0", "0", "cv_teberda_13", "0", "0"},
[404513] = {404513, 10045, 14, 8, "0", "0", "沒事的，這點程度還不至於讓那股衝動追上我……我會控制好的。", "0", "0", "0", "0", "0", "cv_teberda_14", "0", "0"},
[404514] = {404514, 10045, 15, 9, "0", "0", "我很清楚怎麼使用自己的身體。", "0", "0", "0", "0", "0", "cv_teberda_15", "0", "0"},
[404515] = {404515, 10045, 16, 10, "0", "0", "我想早點解決然後回去，所以，麻煩你們去死了。", "0", "0", "0", "0", "0", "cv_teberda_16", "0", "0"},
[404516] = {404516, 10045, 17, 11, "0", "0", "呼……又是沒有後患的一天。", "0", "0", "0", "0", "0", "cv_teberda_17", "0", "0"},
[404517] = {404517, 10045, 18, 12, "0", "0", "沒想到對面居然還有能動的傢伙，要我去補一錘子嗎？", "0", "0", "0", "0", "0", "cv_teberda_18", "0", "0"},
[404518] = {404518, 10045, 19, 13, "0", "0", "嘖……算了，工作完成了就好。", "0", "0", "0", "0", "0", "cv_teberda_19", "0", "0"},
[404519] = {404519, 10045, 20, 14, "0", "0", "撤退吧，繼續留在這，場面會變得很難看的。", "0", "0", "0", "0", "0", "cv_teberda_20", "0", "0"},
[404520] = {404520, 10045, 21, 15, "0", "0", "像垃圾一樣去死吧。", "0", "0", "0", "0", "0", "cv_teberda_21", "0", "0"},
[404521] = {404521, 10045, 23, 16, "0", "0", "破顱——", "0", "0", "0", "0", "0", "cv_teberda_22", "0", "0"},
[404522] = {404522, 10045, 24, 17, "0", "0", "都給我滾開！", "0", "0", "0", "0", "0", "cv_teberda_23", "0", "0"},
[404523] = {404523, 10045, 25, 18, "0", "0", "可惜了，你本來可以死得完整點。", "0", "0", "0", "0", "0", "cv_teberda_24", "0", "0"},
[404524] = {404524, 10045, 26, 19, "0", "0", "呸……得走了，我要花點時間冷靜下來。", "0", "0", "0", "0", "0", "cv_teberda_26", "0", "0"},
[404525] = {404525, 10045, 27, 20, "0", "0", "只要趴著不動就行了？還有這種好事啊，不錯嘛。", "0", "0", "0", "0", "0", "cv_teberda_27", "0", "0"},
[404526] = {404526, 10045, 28, 21, "0", "0", "在這裏發呆，好像比別的地方舒服一些。", "0", "0", "0", "0", "0", "cv_teberda_28", "0", "0"},
[404527] = {404527, 10045, 29, 21, "0", "0", "雖然以前我因為嫌麻煩都是沖澡的，但偶爾這樣，好像也挺不錯。", "0", "0", "0", "0", "0", "cv_teberda_29", "0", "0"},
[404528] = {404528, 10045, 30, 22, "0", "0", "啊，你好。", "0", "0", "0", "0", "0", "cv_teberda_30", "0", "0"},
[404529] = {404529, 10045, 31, 23, "0", "0", "你應該不至於認不出來吧？", "0", "0", "0", "0", "0", "cv_teberda_31", "0", "0"},
[404530] = {404530, 10045, 32, 24, "0", "0", "嗯，我不介意生活中多發生點好事。", "0", "0", "0", "0", "0", "cv_teberda_32", "0", "0"},
[404531] = {404531, 10045, 33, 25, "0", "0", "好，我久違地有點生氣了。", "0", "0", "0", "0", "0", "cv_teberda_33", "0", "0"},
[404532] = {404532, 10045, 34, 26, "0", "0", "喲，你終於回來了。葉格沙已經快把我煩死了，麻煩你幫忙分擔一下。", "0", "0", "0", "0", "0", "cv_teberda_34", "0", "0"},
[404533] = {404533, 10045, 35, 27, "0", "0", "好吧，工作工作……", "0", "0", "0", "0", "0", "cv_teberda_35", "0", "0"},
[404534] = {404534, 10045, 36, 28, "0", "0", "演習？先給我點時間，我回憶下怎麼調整力道。", "0", "0", "0", "0", "0", "cv_teberda_36", "0", "0"},
[404535] = {404535, 10045, 37, 29, "0", "0", "好多人啊，雖然我沒幾個認識的。", "0", "0", "0", "0", "0", "cv_teberda_37", "0", "0"},
[404536] = {404536, 10045, 38, 30, "0", "0", "又有新人要來了？我對她們沒興趣，交流的部分麻煩你自己負責吧。", "0", "0", "0", "0", "0", "cv_teberda_38", "0", "0"},
[404537] = {404537, 10045, 39, 31, "0", "0", "有什麼有趣的新裝備嗎？我能拆了看看嗎？", "0", "0", "0", "0", "0", "cv_teberda_39", "0", "0"},
[404538] = {404538, 10045, 40, 32, "0", "0", "你的資金沒出過問題嗎？真羡慕啊。", "0", "0", "0", "0", "0", "cv_teberda_40", "0", "0"},
[404539] = {404539, 10045, 41, 33, "0", "0", "噗……你看看你在這張照片上的臉。", "0", "0", "0", "0", "0", "cv_teberda_41", "0", "0"},
[404540] = {404540, 10045, 42, 34, "0", "0", "用得順手就行吧。", "0", "0", "0", "0", "0", "cv_teberda_42", "0", "0"},
[404541] = {404541, 10045, 43, 35, "0", "0", "啊，我討厭這東西，裏面會塞滿工作通知和帳單。", "0", "0", "0", "0", "0", "cv_teberda_43", "0", "0"},
[404542] = {404542, 10045, 44, 36, "0", "0", "好吵啊，能加點遮罩條件嗎？", "0", "0", "0", "0", "0", "cv_teberda_44", "0", "0"},
[404543] = {404543, 10045, 45, 37, "0", "0", "這個是？", "0", "0", "0", "0", "0", "cv_teberda_45", "0", "0"},
[416000] = {416000, 11060, 1, 1, "0", "0", "蒼霧殘響", "0", "0", "0", "0", "0", "cv_gorca_01", "0", "0"},
[416001] = {416001, 11060, 2, 2, "0", "0", "讓我來負責這個沒問題嗎？畢竟我連陪人聊天都說不上擅長……要不讓店長遠程支援我吧？", "0", "0", "0", "0", "0", "cv_gorca_02", "0", "0"},
[416002] = {416002, 11060, 3, 3, "0", "0", "啊，終於放心不下來看我了嗎，領航？開玩笑啦。作為受訓中的預備駕駛員，我現在有一大堆問題要找你請教，做好覺悟吧~", "0", "0", "0", "0", "0", "cv_gorca_03", "0", "0"},
[416003] = {416003, 11060, 4, 4, "0", "idle", "我說，別什麼事都不讓我做啊，會有負罪感的。", "0", "0", "0", "0", "0", "cv_gorca_04", "0", "0"},
[416004] = {416004, 11060, 5, 4, "0", "idle2", "有什麼需要我幫忙跑腿的嗎？畢竟我腳程很快的，而且最近也學會控制好不撞傷人了。", "0", "0", "0", "0", "0", "cv_gorca_05", "0", "0"},
[416005] = {416005, 11060, 6, 4, "0", "idle3", "嗯……左邊這排書的標題是用什麼文寫的？", "0", "0", "0", "0", "0", "cv_gorca_06", "0", "0"},
[416006] = {416006, 11060, 7, 5, "1_》_0_0.8", "level1", "第一研究室的生活？整體都還好吧，畢竟店長一直在陪著我。不過，那個地方為什麼會有女僕啊，領航？", "0", "0", "0", "0", "0", "cv_gorca_07", "0", "0"},
[416007] = {416007, 11060, 8, 5, "1_》_0_0.8", "level2", "最大的煩惱……大概是不被允許外出吧。這樣就算有休息日也沒機會去那個有超大棕熊的商店了，感覺好可惜。", "0", "0", "0", "0", "0", "cv_gorca_08", "0", "0"},
[416008] = {416008, 11060, 9, 5, "1_》_100_1.5", "level3", "那些人說，我的身體就像是專門為了成為駕駛員而被調整過似的……感覺就像以前那些人還在影響著我現在的生活一樣，我挺討厭的。", "0", "0", "0", "0", "0", "cv_gorca_09", "0", "0"},
[416009] = {416009, 11060, 10, 5, "1_》_500_2", "level4", "我跟很多人確認過，我名字的含義是“小小的鴿子”。我當時第一眼就喜歡上了這個名字。可能是因為……以前的我，就是為了自由的生活，而開啟了我至今為止的人生吧。", "0", "0", "0", "0", "0", "cv_gorca_10", "0", "0"},
[416010] = {416010, 11060, 11, 5, "1_》_1000_2.5", "level5", "……所以，你也是失去過過去的人嗎，領航大哥？你是怎麼為自己找到生活方向的，可以拜託你教教我嗎？", "0", "0", "0", "0", "0", "cv_gorca_11", "0", "0"},
[416011] = {416011, 11060, 12, 6, "0", "0", "這副身體居然還能變強啊。", "0", "0", "0", "0", "0", "cv_gorca_12", "0", "0"},
[416012] = {416012, 11060, 13, 7, "0", "0", "這樣下去我到底還有多少算人類啊……算了，別想這個。", "0", "0", "0", "0", "0", "cv_gorca_13", "0", "0"},
[416013] = {416013, 11060, 14, 8, "0", "0", "在某種意義上，我甚至希望自己能變得更弱。但，既然當上了駕駛員，就不能像這樣任性，對吧？", "0", "0", "0", "0", "0", "cv_gorca_14", "0", "0"},
[416014] = {416014, 11060, 15, 9, "0", "0", "想看看這只手還能變成什麼別的樣子嗎，領航？", "0", "0", "0", "0", "0", "cv_gorca_15", "0", "0"},
[416015] = {416015, 11060, 16, 10, "0", "0", "調整好呼吸，控制好情緒……嗯，我能行！", "0", "0", "0", "0", "0", "cv_gorca_16", "0", "0"},
[416016] = {416016, 11060, 17, 11, "0", "0", "嗯？已經都結束了嗎？呼啊……差點忘記要喘氣了。", "0", "0", "0", "0", "0", "cv_gorca_17", "0", "0"},
[416017] = {416017, 11060, 18, 12, "0", "0", "……這些失誤裏有我造成的嗎？", "0", "0", "0", "0", "0", "cv_gorca_18", "0", "0"},
[416018] = {416018, 11060, 19, 13, "0", "0", "嗚哇，好險好險。不過都這樣了，我們就別追了吧？", "0", "0", "0", "0", "0", "cv_gorca_19", "0", "0"},
[416019] = {416019, 11060, 20, 14, "0", "0", "這下可糟糕了……有什麼人需要我捎上跑嗎？", "0", "0", "0", "0", "0", "cv_gorca_20", "0", "0"},
[416020] = {416020, 11060, 21, 15, "0", "0", "抱歉哦。", "0", "0", "0", "0", "0", "cv_gorca_21", "0", "0"},
[416021] = {416021, 11060, 23, 16, "0", "0", "控制好身體。", "0", "0", "0", "0", "0", "cv_gorca_22", "0", "0"},
[416022] = {416022, 11060, 24, 17, "0", "0", "調整好步伐。", "0", "0", "0", "0", "0", "cv_gorca_23", "0", "0"},
[416023] = {416023, 11060, 26, 19, "0", "0", "……對不起。", "0", "0", "0", "0", "0", "cv_gorca_26", "0", "0"},
[416024] = {416024, 11060, 27, 20, "0", "0", "提醒一下，我的身體比看上去硬很多哦，雖然我也不想這樣。", "0", "0", "0", "0", "0", "cv_gorca_27", "0", "0"},
[416025] = {416025, 11060, 28, 21, "0", "0", "呼……呼……呃……我是不是睡著了？", "0", "0", "0", "0", "0", "cv_gorca_28", "0", "0"},
[416026] = {416026, 11060, 29, 21, "0", "0", "洗澡應該不會讓我身體的什麼地方生銹吧……", "0", "0", "0", "0", "0", "cv_gorca_29", "0", "0"},
[416027] = {416027, 11060, 30, 22, "0", "0", "嗚啊，嚇我一跳。", "0", "0", "0", "0", "0", "cv_gorca_30", "0", "0"},
[416028] = {416028, 11060, 31, 23, "0", "0", "怎麼樣，要我稍微變形幫你作弊一下嗎？", "0", "0", "0", "0", "0", "cv_gorca_31", "0", "0"},
[416029] = {416029, 11060, 32, 24, "0", "0", "我就知道你能猜到的！", "0", "0", "0", "0", "0", "cv_gorca_32", "0", "0"},
[416030] = {416030, 11060, 33, 25, "0", "0", "啊——我可沒失望哦，絕對沒有。", "0", "0", "0", "0", "0", "cv_gorca_33", "0", "0"},
[416031] = {416031, 11060, 34, 26, "0", "0", "歡迎回來——呃，桌上東西的順序是不是變了？你的錯覺啦，錯覺。", "0", "0", "0", "0", "0", "cv_gorca_34", "0", "0"},
[416032] = {416032, 11060, 35, 27, "0", "0", "果然，當上駕駛員就要去戰鬥啊。", "0", "0", "0", "0", "0", "cv_gorca_35", "0", "0"},
[416033] = {416033, 11060, 36, 28, "0", "0", "和其他的駕駛員對戰？這也算一種練習嗎？", "0", "0", "0", "0", "0", "cv_gorca_36", "0", "0"},
[416034] = {416034, 11060, 37, 29, "0", "0", "嗚哇，好多人。這些人都來自什麼地方啊……", "0", "0", "0", "0", "0", "cv_gorca_37", "0", "0"},
[416035] = {416035, 11060, 38, 30, "0", "0", "你要去見新的駕駛員？我可以去旁邊看著嗎？", "0", "0", "0", "0", "0", "cv_gorca_38", "0", "0"},
[416036] = {416036, 11060, 39, 31, "0", "0", "有什麼我也能用上的裝備嗎？", "0", "0", "0", "0", "0", "cv_gorca_39", "0", "0"},
[416037] = {416037, 11060, 40, 32, "0", "0", "這就是，文明社會的消費旋渦……", "0", "0", "0", "0", "0", "cv_gorca_40", "0", "0"},
[416038] = {416038, 11060, 41, 33, "0", "0", "你檔案裏的這一條是什麼意思？欸？真的假的？", "0", "0", "0", "0", "0", "cv_gorca_41", "0", "0"},
[416039] = {416039, 11060, 42, 34, "0", "0", "這些按鈕是什麼？", "0", "0", "0", "0", "0", "cv_gorca_42", "0", "0"},
[416040] = {416040, 11060, 43, 35, "0", "0", "好多郵件啊，都是你的熟人寄來的？", "0", "0", "0", "0", "0", "cv_gorca_43", "0", "0"},
[416041] = {416041, 11060, 44, 36, "0", "0", "我能通過看這些學習怎麼和人交流嗎……", "0", "0", "0", "0", "0", "cv_gorca_44", "0", "0"},
[416042] = {416042, 11060, 45, 37, "0", "0", "這裏？", "0", "0", "0", "0", "0", "cv_gorca_45", "0", "0"},
[4004500100] = {4004500100, 10045001, 1, 1, "0", "0", "蒼霧殘響", "0", "0", "0", "0", "0", "cv_sk_teberda_01", "0", "0"},
[4004500101] = {4004500101, 10045001, 2, 2, "0", "0", "好，那我就先去那邊的沙發上躺著了，有什麼事就叫我。風衣我能掛在這嗎？", "0", "0", "0", "0", "0", "cv_sk_teberda_02", "0", "0"},
[4004500102] = {4004500102, 10045001, 3, 3, "0", "0", "初次見面，我是“鋼輪戈爾”的駕駛員特薇爾達，很高興能認識——等等，原來是你啊。早說嘛，用剛剛那種方式說話很費力的。", "0", "0", "0", "0", "0", "cv_sk_teberda_03", "0", "0"},
[4004500103] = {4004500103, 10045001, 91, 4, "0", "idle", "卡佳的天氣，怎麼都比那些一天到頭都熱得要死的地方好吧……不過暖氣還是再開大點好了。", "0", "0", "0", "0", "0", "cv_sk_teberda_n04", "0", "idle,idle"},
[4004500104] = {4004500104, 10045001, 91, 4, "0", "idle", "我才不收腿。保護人類的駕駛員起碼得有霸占整個沙發的自由。", "0", "0", "0", "0", "0", "cv_sk_teberda_n05", "0", "idle,idle"},
[4004500105] = {4004500105, 10045001, 91, 4, "0", "idle", "我想趁葉格沙沒回來好好享受下獨處的時間。畢竟……她那個尺寸，一旦湊過來，幹什麼都會變得很擠，你能理解吧？", "0", "0", "0", "0", "0", "cv_sk_teberda_n06", "0", "idle,idle"},
[4004500106] = {4004500106, 10045001, 94, 4, "0", "idle2", "呼啊……我現在這樣，大概隨時都有可能睡過去，到時候別叫醒我。", "0", "0", "0", "0", "0", "cv_sk_teberda_n10", "0", "idle2,idle2"},
[4004500107] = {4004500107, 10045001, 94, 4, "0", "idle2", "葉格沙老是嫌我休息時穿成這樣容易生病。說真的，你覺得她的打扮有任何說這種話的資格嗎，領航？", "0", "0", "0", "0", "0", "cv_sk_teberda_n11", "0", "idle2,idle2"},
[4004500108] = {4004500108, 10045001, 94, 4, "0", "idle2", "話說，你來找我是有什麼事來著？忘了？挺好嘛，沒有工作時的生活就是要漫無目的一些。既然這樣，有什麼想看的電影不？", "0", "0", "0", "0", "0", "cv_sk_teberda_n12", "0", "idle2,idle2"},
[4004500109] = {4004500109, 10045001, 92, 5, "1_》_0_0.8", "touch1", "我為什麼在家也穿這一身？哎呀，休息這種事最重要的是心態到位。", "0", "0", "0", "0", "0", "cv_sk_teberda_n02", "0", "touch1,touch1"},
[4004500110] = {4004500110, 10045001, 92, 5, "1_》_0_0.8", "touch1", "嗯……有點不想動了。能去冰箱裏隨便拿杯什麼給我嗎？剩下的就當送你了。", "0", "0", "0", "0", "0", "cv_sk_teberda_n03", "0", "touch1,touch1"},
[4004500111] = {4004500111, 10045001, 95, 5, "1_》_0_0.8", "touch2", "不是嫌我剛剛那打扮太常見嗎，現在不知道看哪了？", "0", "0", "0", "0", "0", "cv_sk_teberda_n08", "0", "touch2,touch2"},
[4004500112] = {4004500112, 10045001, 95, 5, "1_》_0_0.8", "touch3", "就用風衣來當被子好了……算了，還是不想動。", "0", "0", "0", "0", "0", "cv_sk_teberda_n09", "0", "touch3,touch3"},
[4004500113] = {4004500113, 10045001, 93, 5, "1_》_0_0.8", "switch1", "嚯噢……", "0", "0", "0", "0", "0", "cv_sk_teberda_n01", "0", "switch1,switch1"},
[4004500114] = {4004500114, 10045001, 96, 5, "1_》_0_0.8", "switch2", "有點冷……", "0", "0", "0", "0", "0", "cv_sk_teberda_n07", "0", "switch2,switch2"},
[4004500115] = {4004500115, 10045001, 12, 6, "0", "0", "就算變強了也不用擔心長出太多肌肉呢，不錯。", "0", "0", "0", "0", "0", "cv_sk_teberda_12", "0", "0"},
[4004500116] = {4004500116, 10045001, 13, 7, "0", "0", "我的假期能隨這個變多些嗎？", "0", "0", "0", "0", "0", "cv_sk_teberda_13", "0", "0"},
[4004500117] = {4004500117, 10045001, 14, 8, "0", "0", "沒事的，這點程度還不至於讓那股衝動追上我……我會控制好的。", "0", "0", "0", "0", "0", "cv_sk_teberda_14", "0", "0"},
[4004500118] = {4004500118, 10045001, 15, 9, "0", "0", "我很清楚怎麼使用自己的身體。", "0", "0", "0", "0", "0", "cv_sk_teberda_15", "0", "0"},
[4004500119] = {4004500119, 10045001, 16, 10, "0", "0", "我想早點解決然後回去，所以，麻煩你們去死了。", "0", "0", "0", "0", "0", "cv_sk_teberda_16", "0", "0"},
[4004500120] = {4004500120, 10045001, 17, 11, "0", "0", "呼……又是沒有後患的一天。", "0", "0", "0", "0", "0", "cv_sk_teberda_17", "0", "0"},
[4004500121] = {4004500121, 10045001, 18, 12, "0", "0", "沒想到對面居然還有能動的傢伙，要我去補一錘子嗎？", "0", "0", "0", "0", "0", "cv_sk_teberda_18", "0", "0"},
[4004500122] = {4004500122, 10045001, 19, 13, "0", "0", "嘖……算了，工作完成了就好。", "0", "0", "0", "0", "0", "cv_sk_teberda_19", "0", "0"},
[4004500123] = {4004500123, 10045001, 20, 14, "0", "0", "撤退吧，繼續留在這，場面會變得很難看的。", "0", "0", "0", "0", "0", "cv_sk_teberda_20", "0", "0"},
[4004500124] = {4004500124, 10045001, 21, 15, "0", "0", "好，工作進度加一。", "0", "0", "0", "0", "0", "cv_sk_teberda_n13", "0", "0"},
[4004500125] = {4004500125, 10045001, 23, 16, "0", "0", "滾。", "0", "0", "0", "0", "0", "cv_sk_teberda_n14", "0", "0"},
[4004500126] = {4004500126, 10045001, 24, 17, "0", "0", "正面接一下試試？", "0", "0", "0", "0", "0", "cv_sk_teberda_n15", "0", "0"},
[4004500127] = {4004500127, 10045001, 25, 18, "0", "0", "可惜了，你本來可以死得完整點。", "0", "0", "0", "0", "0", "cv_sk_teberda_24", "0", "0"},
[4004500128] = {4004500128, 10045001, 26, 19, "0", "0", "唉……他媽的……", "0", "0", "0", "0", "0", "cv_sk_teberda_n18", "0", "0"},
[4004500129] = {4004500129, 10045001, 27, 20, "0", "0", "只要趴著不動就行了？還有這種好事啊，不錯嘛。", "0", "0", "0", "0", "0", "cv_sk_teberda_27", "0", "0"},
[4004500130] = {4004500130, 10045001, 28, 21, "0", "0", "在這裏發呆，好像比別的地方舒服一些。", "0", "0", "0", "0", "0", "cv_sk_teberda_28", "0", "0"},
[4004500131] = {4004500131, 10045001, 29, 21, "0", "0", "雖然以前我因為嫌麻煩都是沖澡的，但偶爾這樣，好像也挺不錯。", "0", "0", "0", "0", "0", "cv_sk_teberda_29", "0", "0"},
[4004500132] = {4004500132, 10045001, 30, 22, "0", "0", "啊，你好。", "0", "0", "0", "0", "0", "cv_sk_teberda_30", "0", "0"},
[4004500133] = {4004500133, 10045001, 31, 23, "0", "0", "你應該不至於認不出來吧？", "0", "0", "0", "0", "0", "cv_sk_teberda_31", "0", "0"},
[4004500134] = {4004500134, 10045001, 32, 24, "0", "0", "嗯，我不介意生活中多發生點好事。", "0", "0", "0", "0", "0", "cv_sk_teberda_32", "0", "0"},
[4004500135] = {4004500135, 10045001, 33, 25, "0", "0", "好，我久違地有點生氣了。", "0", "0", "0", "0", "0", "cv_sk_teberda_33", "0", "0"},
[4004500136] = {4004500136, 10045001, 34, 26, "0", "0", "歡迎光臨——啊，如果你是來通知我下一份工作的話，麻煩立刻從那扇門出去。", "0", "0", "0", "0", "0", "cv_sk_teberda_n19", "0", "0"},
[4004500137] = {4004500137, 10045001, 35, 27, "0", "0", "好吧，工作工作……", "0", "0", "0", "0", "0", "cv_sk_teberda_35", "0", "0"},
[4004500138] = {4004500138, 10045001, 36, 28, "0", "0", "演習？先給我點時間，我回憶下怎麼調整力道。", "0", "0", "0", "0", "0", "cv_sk_teberda_36", "0", "0"},
[4004500139] = {4004500139, 10045001, 37, 29, "0", "0", "好多人啊，雖然我沒幾個認識的。", "0", "0", "0", "0", "0", "cv_sk_teberda_37", "0", "0"},
[4004500140] = {4004500140, 10045001, 38, 30, "0", "0", "又有新人要來了？我對她們沒興趣，交流的部分麻煩你自己負責吧。", "0", "0", "0", "0", "0", "cv_sk_teberda_38", "0", "0"},
[4004500141] = {4004500141, 10045001, 39, 31, "0", "0", "有什麼有趣的新裝備嗎？我能拆了看看嗎？", "0", "0", "0", "0", "0", "cv_sk_teberda_39", "0", "0"},
[4004500142] = {4004500142, 10045001, 40, 32, "0", "0", "你的資金沒出過問題嗎？真羡慕啊。", "0", "0", "0", "0", "0", "cv_sk_teberda_40", "0", "0"},
[4004500143] = {4004500143, 10045001, 41, 33, "0", "0", "噗……你看看你在這張照片上的臉。", "0", "0", "0", "0", "0", "cv_sk_teberda_41", "0", "0"},
[4004500144] = {4004500144, 10045001, 42, 34, "0", "0", "用得順手就行吧。", "0", "0", "0", "0", "0", "cv_sk_teberda_42", "0", "0"},
[4004500145] = {4004500145, 10045001, 43, 35, "0", "0", "啊，我討厭這東西，裏面會塞滿工作通知和帳單。", "0", "0", "0", "0", "0", "cv_sk_teberda_43", "0", "0"},
[4004500146] = {4004500146, 10045001, 44, 36, "0", "0", "好吵啊，能加點遮罩條件嗎？", "0", "0", "0", "0", "0", "cv_sk_teberda_44", "0", "0"},
[4004500147] = {4004500147, 10045001, 45, 37, "0", "0", "這個是？", "0", "0", "0", "0", "0", "cv_sk_teberda_45", "0", "0"},
[4200700100] = {4200700100, 12007001, 1, 1, "0", "0", "蒼霧殘響！", "苍雾残响（ハツリバーブ）！", "0", "0", "苍雾残响！", "0", "cv_kamu_32", "0", "0"},
[4200700101] = {4200700101, 12007001, 2, 2, "0", "0", "放心好了，我會替你守住大門的！", "安心しろ、この入り口は、オレが守ってやるから！", "0", "0", "放心好了，我会替你守住大门的！", "0", "cv_kamu_2", "0", "0"},
[4200700102] = {4200700102, 12007001, 3, 3, "0", "0", "呀吼~終於見面了呢，多瑙的領航。小生的名字是華夢，可千萬不要忘記啊。", "ヤッホー。やっと会えたな、ダニューブのナビゲーター。オレの名は华梦。忘れるなよ。", "0", "0", "呀吼~终于见面了呢，多瑙的领航。小生的名字是华梦，可千万不要忘记啊。", "0", "cv_kamu_1", "0", "0"},
[4200700103] = {4200700103, 12007001, 91, 4, "0", "idle", "喝——啊——！太小了！這裡實在是太過於狹小了！完全施展不開拳腳！", "はっ――やっ――！狭すぎ！ここ、本当に狭すぎる！体、动かせないじゃん！", "0", "0", "喝——啊——！太小了！这里实在是太过于狭小了！完全施展不开拳脚！", "0", "cv_kamu_3", "0", "0,idle"},
[4200700104] = {4200700104, 12007001, 91, 4, "0", "idle", "今天是個適合踏青的好日子呢，如果可以的話真想和你一起出去走走啊。正所謂勞逸結合，偶爾也去做點其他事情放鬆下吧。", "今日は远足日和だ。できればお前と一绪に出挂けたいな。まぁ、仕事と休みはバランスよく取るべきだし。たまには他のことをやってみて、リラックスしたらどうだ？", "0", "0", "今天是个适合踏青的好日子呢，如果可以的话真想和你一起出去走走啊。正所谓劳逸结合，偶尔也去做点其他事情放松下吧。", "0", "cv_kamu_4", "0", "0,idle"},
[4200700105] = {4200700105, 12007001, 91, 4, "0", "idle", "無論是彩華還是華戀，她們都不是可以輕視的對手啊。不過小生還是更加害怕和彩華交手，那個傢夥總是會使用非常危險的武器呢。", "彩华も华恋も、见くびっちゃいけない相手だ。まぁ、オレは彩华の方が苦手だな。あいつ、いつも危ない武器を使ってるからさ。", "0", "0", "无论是彩华还是华恋，她们都不是可以轻视的对手啊。不过小生还是更加害怕和彩华交手，那个家伙总是会使用非常危险的武器呢。", "0", "cv_kamu_29", "0", "0,idle"},
[4200700106] = {4200700106, 12007001, 92, 5, "15_1_0_0.8", "touch1", "小生對於修行之外的事情沒有興趣。", "修行以外のことには兴味ないな。", "0", "0", "小生对于修行之外的事情没有兴趣。", "0", "cv_kamu_30", "0", "0,touch1"},
[4200700107] = {4200700107, 12007001, 92, 5, "15_1_0_0.8", "touch1", "天華閣…與其說是作戰部隊不如說是修行部隊呢，像這樣習武是我們的日常。", "天华阁……作戦部队っていうより、修行部队って言うべきか。こうして武芸の练习をするのはオレたちの日常だし。", "0", "0", "天华阁…与其说是作战部队不如说是修行部队呢，像这样习武是我们的日常。", "0", "cv_kamu_5", "0", "0,touch1"},
[4200700108] = {4200700108, 12007001, 92, 5, "15_2_0_0.8", "touch2", "將身體與技巧都鍛煉到極致確實是我們的追求。但是，就我個人來說的話，還有需要鍛煉的事物。沒錯，那便是氣。", "体とスキルを限界まで锻える事は确かにオレたちが求めてることだ。でも、个人的にはもう一つ锻えなきゃならないものがある。そう、気のことだ。", "0", "0", "将身体与技巧都锻炼到极致确实是我们的追求。但是，就我个人来说的话，还有需要锻炼的事物。没错，那便是气。", "0", "cv_kamu_6", "0", "0,touch2"},
[4200700109] = {4200700109, 12007001, 92, 5, "15_2_0_0.8", "touch2", "癡迷修行的代價嘛……估計就是回過神來才發現自己已經到這個歲數了吧。說起來，在我的記憶中似乎並沒有所謂的童年呢。稍微……有點遺憾啊。", "修行に梦中になることの代偿と言えば……まぁ、気付いたらもうこんな年になっちゃった、ぐらいか。そういえばオレ、いわゆる子供时代ってものの记忆がないんだ。ちょっと……残念だな。", "0", "0", "痴迷修行的代价嘛……估计就是回过神来才发现自己已经到这个岁数了吧。说起来，在我的记忆中似乎并没有所谓的童年呢。稍微……有点遗憾啊。", "0", "cv_kamu_7", "0", "0,touch2"},
[4200700110] = {4200700110, 12007001, 92, 5, "15_2_0_0.8", "touch2", "修行確實讓我失去了很多東西，但是一想到今天的自己，那麼這一切便都有了意義。更加重要的是，正是因為修行，我才認識了你。", "确かにオレは修行のせいで沢山のものを失った。でも、今の自分を见たら、全ては意味があることだったと确信できる。修行のお阴でお前に出会えたんだ。", "0", "0", "修行确实让我失去了很多东西，但是一想到今天的自己，那么这一切便都有了意义。更加重要的是，正是因为修行，我才认识了你。", "0", "cv_kamu_8", "0", "0,touch2"},
[4200700111] = {4200700111, 12007001, 12, 6, "0", "0", "有了這些的幫助修行也會輕鬆不少吧？多謝了！", "助力があれば、修行も多少楽になるよな？ありがとう！", "0", "0", "有了这些的帮助修行也会轻松不少吧？多谢了！", "0", "cv_kamu_9", "0", "0"},
[4200700112] = {4200700112, 12007001, 13, 7, "0", "0", "肉體，技巧……都得到提升了呢！", "肉体、スキル……全部精进したんだ！", "0", "0", "肉体，技巧……都得到提升了呢！", "0", "cv_kamu_10", "0", "0"},
[4200700113] = {4200700113, 12007001, 14, 8, "0", "0", "這就是武學的真髓嗎？非常感謝！謝謝你將我帶到了新的領域！", "これが武道の真髄なのか？ありがとう！オレを新しい领域へと导いてくれて！", "0", "0", "这就是武学的真髓吗？非常感谢！谢谢你将我带到了新的领域！", "0", "cv_kamu_11", "0", "0"},
[4200700114] = {4200700114, 12007001, 15, 9, "0", "0", "氣的純度提升了！", "気の纯度が上がったな！", "0", "0", "气的纯度提升了！", "0", "cv_kamu_12", "0", "0"},
[4200700115] = {4200700115, 12007001, 16, 10, "0", "0", "可悲的生物啊，接下來就由我來打倒你們。", "悲しい生き物だ。さぁ、オレが倒してやる！", "0", "0", "可悲的生物啊，接下来就由我来打倒你们。", "0", "cv_kamu_13", "0", "0"},
[4200700116] = {4200700116, 12007001, 17, 11, "0", "0", "全部都解決乾淨了呢，果然，武術是最強的！", "全部片付けられたな。やっぱり、武术は最强だ！", "0", "0", "全部都解决干净了呢，果然，武术是最强的！", "0", "cv_kamu_14", "0", "0"},
[4200700117] = {4200700117, 12007001, 18, 12, "0", "0", "早知道如此就將全部的氣都給釋放出來了……", "こうなると知ってたなら、全ての気を出しとけばよかった……", "0", "0", "早知道如此就将全部的气都给释放出来了……", "0", "cv_kamu_15", "0", "0"},
[4200700118] = {4200700118, 12007001, 19, 13, "0", "0", "看來我還需要進行修行啊。", "まだまだ修行が必要みたいだな", "0", "0", "看来我还需要进行修行啊。", "0", "cv_kamu_16", "0", "0"},
[4200700119] = {4200700119, 12007001, 20, 14, "0", "0", "可以的話……能讓我進行苦修嗎？", "よかったら……苦行、してもいいか？", "0", "0", "可以的话……能让我进行苦修吗？", "0", "cv_kamu_17", "0", "0"},
[4200700120] = {4200700120, 12007001, 21, 15, "0", "0", "無法修行的生物，真是可悲啊。", "修行できない生き物だなんて、哀れなヤツだな。", "0", "0", "无法修行的生物，真是可悲啊。", "0", "cv_kamu_18", "0", "0"},
[4200700121] = {4200700121, 12007001, 23, 16, "0", "0", "哈！", "はっ！", "0", "0", "哈！", "0", "cv_kamu_20", "0", "0"},
[4200700122] = {4200700122, 12007001, 22, 38, "0", "0", "嘿咻。", "ふう", "0", "0", "嘿咻。", "0", "cv_kamu_19", "0", "0"},
[4200700123] = {4200700123, 12007001, 26, 19, "0", "0", "看來我的修行，也到此為止了。", "どうやらオレの修行はここまでのようだ。", "0", "0", "看来我的修行，也到此为止了。", "0", "cv_kamu_21", "0", "0"},
[4200700124] = {4200700124, 12007001, 27, 20, "0", "0", "水下可是非常適合修行的場所呢。", "水の中っていうのは修行に最适だ。", "0", "0", "水下可是非常适合修行的场所呢。", "0", "cv_kamu_22", "0", "0"},
[4200700125] = {4200700125, 12007001, 28, 21, "0", "0", "這是定力的修行喔。", "これは定力の修行だぞ。", "0", "0", "这是定力的修行哦。", "0", "cv_kamu_23", "0", "0"},
[4200700126] = {4200700126, 12007001, 29, 21, "0", "0", "洗澡的時候總會忍不住放鬆下來啊~", "お风吕に入ると何だかんだ気が缓むな。", "0", "0", "洗澡的时候总会忍不住放松下来啊~", "0", "cv_kamu_24", "0", "0"},
[4200700127] = {4200700127, 12007001, 30, 22, "0", "0", "將氣注入武器吧！", "気を武器に注ぎ込め！", "0", "0", "将气注入武器吧！", "0", "cv_kamu_25", "0", "0"},
[4200700128] = {4200700128, 12007001, 31, 23, "0", "0", "來展示下修行過後的結果吧！", "修行の成果を见せてくれ！", "0", "0", "来展示下修行过后的结果吧！", "0", "cv_kamu_26", "0", "0"},
[4200700129] = {4200700129, 12007001, 32, 24, "0", "0", "是通過氣來分辨出來的嗎？還是說……", "気で分かったのか？それとも……", "0", "0", "是通过气来分辨出来的吗？还是说……", "0", "cv_kamu_27", "0", "0"},
[4200700130] = {4200700130, 12007001, 33, 25, "0", "0", "無論是你我，修行還都不夠啊。", "お前もオレも、まだまだ修行が足りないな。", "0", "0", "无论是你我，修行还都不够啊。", "0", "cv_kamu_28", "0", "0"},
[4200700131] = {4200700131, 12007001, 34, 26, "0", "0", "啊，領航你回來了嗎？小生這就中斷修行。", "ああ、お帰り、ナビゲーター！待ってくれ、すぐに修行を终えるから。", "0", "0", "啊，领航你回来了吗？小生这就中断修行。", "0", "cv_kamu_31", "0", "0"},
[4200700132] = {4200700132, 12007001, 35, 27, "0", "0", "前往新的戰場吧。", "新しい戦场に向かおう。", "0", "0", "前往新的战场吧。", "0", "cv_kamu_33", "0", "0"},
[4200700133] = {4200700133, 12007001, 36, 28, "0", "0", "人只有在苦修中才能磨練自己。", "人は苦行の中でのみ、自分を磨けるからな。", "0", "0", "人只有在苦修中才能磨练自己。", "0", "cv_kamu_34", "0", "0"},
[4200700134] = {4200700134, 12007001, 37, 29, "0", "0", "各位，在苦修中磨練自己吧！", "皆、苦行で自分を磨こう！", "0", "0", "各位，在苦修中磨练自己吧！", "0", "cv_kamu_35", "0", "0"},
[4200700135] = {4200700135, 12007001, 38, 30, "0", "0", "要增加夥伴了嗎？", "仲间が増えるのか？", "0", "0", "要增加伙伴了吗？", "0", "cv_kamu_36", "0", "0"},
[4200700136] = {4200700136, 12007001, 39, 31, "0", "0", "多瑙的裝備還真是有趣啊。", "ダニューブの装备って面白いな。", "0", "0", "多瑙的装备还真是有趣啊。", "0", "cv_kamu_37", "0", "0"},
[4200700137] = {4200700137, 12007001, 40, 32, "0", "0", "採購一些修行用的東西吧。", "修行用のアイテムを买い付けよう。", "0", "0", "采购一些修行用的东西吧。", "0", "cv_kamu_38", "0", "0"},
[4200700138] = {4200700138, 12007001, 41, 33, "0", "0", "要更新個人資訊嗎？", "个人情报を更新するのか？", "0", "0", "要更新个人信息吗？", "0", "cv_kamu_39", "0", "0"},
[4200700139] = {4200700139, 12007001, 42, 34, "0", "0", "根據自己的需要來變更設定吧。", "自分の需要に合わせて设定を変更しよう。", "0", "0", "根据自己的需要来变更设置吧。", "0", "cv_kamu_40", "0", "0"},
[4200700140] = {4200700140, 12007001, 43, 35, "0", "0", "領航，來清理一下信箱吧。", "受信箱を整理しよう、ナビゲーター。", "0", "0", "领航，来清理一下邮箱吧。", "0", "cv_kamu_41", "0", "0"},
[4200700141] = {4200700141, 12007001, 44, 36, "0", "0", "小生的話，還是更加喜歡一個人苦修啊。", "オレは、一人の苦行の方がいいけどな。", "0", "0", "小生的话，还是更加喜欢一个人苦修啊。", "0", "cv_kamu_42", "0", "0"},
[4200700142] = {4200700142, 12007001, 45, 37, "0", "0", "就由小生來代你確認一下吧。", "オレが代わりに确认してやるよ。", "0", "0", "就由小生来代你确认一下吧。", "0", "cv_kamu_43", "0", "0"},
[432700] = {432700, 13027, 1, 1, "0", "0", "蒼霧殘響", "0", "0", "0", "0", "0", "cv_faernaisi_her_01", "0", "0"},
[432701] = {432701, 13027, 2, 2, "0", "0", "這也是約會的一環嗎？您的想法總是那麼讓人捉摸不透呢。", "0", "0", "0", "0", "0", "cv_faernaisi_her_02", "0", "0"},
[432702] = {432702, 13027, 3, 3, "0", "0", "明明已經是熟到不能再熟的關系，卻還要自我介紹嗎？那就如您所願，“歧花”隊長，法爾奈斯·蘭特再次向您報道。", "0", "0", "0", "0", "0", "cv_faernaisi_her_03", "0", "0"},
[432703] = {432703, 13027, 4, 4, "0", "idle", "您和我的距離可以更近一些——您現在是我的未婚夫，要是離得遠了，反而會奇怪……還是說，您擔心被其他女孩子看見，花心的領航？", "0", "0", "0", "0", "0", "cv_faernaisi_her_04", "0", "0"},
[432704] = {432704, 13027, 5, 4, "0", "idle2", "請牽著我的手，領航。既然是未婚夫，又是熱戀中的情侶，我們的手如果沒有二十四小時粘在一起，那會讓人起疑心的。", "0", "0", "0", "0", "0", "cv_faernaisi_her_05", "0", "0"},
[432705] = {432705, 13027, 6, 4, "0", "idle3", "“要是這副打扮被熟人看到了怎麼辦”……真是奇怪的問題，我並不認為我的品味有失大體，如果被卡芙卡她們看到了，她們也只會因為我的美麗端莊而目瞪口呆。", "0", "0", "0", "0", "0", "cv_faernaisi_her_06", "0", "0"},
[432706] = {432706, 13027, 7, 5, "1_》_0_0.8", "level1", "請您遵從自己內心的欲求，盡情觸摸我吧，這樣才能讓別人相信您是我貨真價實的“未婚夫”。", "0", "0", "0", "0", "0", "cv_faernaisi_her_07", "0", "0"},
[432707] = {432707, 13027, 8, 5, "1_》_0_0.8", "level2", "像這樣，掌心相抵，感受彼此的體溫……感受彼此的真實存在，是件幸福的事，對吧？", "0", "0", "0", "0", "0", "cv_faernaisi_her_08", "0", "0"},
[432708] = {432708, 13027, 9, 5, "1_》_100_1.5", "level3", "我們的約會，和真正的約會相差多少呢？或者說，那些真正的情侶，是不是也像我們一樣相處呢……我多多少少有些在意這件事。", "0", "0", "0", "0", "0", "cv_faernaisi_her_09", "0", "0"},
[432709] = {432709, 13027, 10, 5, "1_》_500_2", "level4", "一日為師終身為父……那麼即使是一天的情侶，是否也存在著將這份關系永遠延續下去的可能呢……我這不是在試探，而是在詢問您的想法，領航。", "0", "0", "0", "0", "0", "cv_faernaisi_her_10", "0", "0"},
[432710] = {432710, 13027, 11, 5, "1_》_1000_2.5", "level5", "虛假的身份不會長久地維持下去，當戲劇落幕的時候，離開舞臺的演員便會回到原本的生活……不過，若是您的話，只要您願意開口，這份虛假就會在頃刻間逆轉為真實。", "0", "0", "0", "0", "0", "cv_faernaisi_her_11", "0", "0"},
[432711] = {432711, 13027, 12, 6, "0", "0", "即使是約會的時候，也不能忘記學習嗎？", "0", "0", "0", "0", "0", "cv_faernaisi_her_12", "0", "0"},
[432712] = {432712, 13027, 13, 7, "0", "0", "即使終將凋謝，此刻也要將生命怒放。", "0", "0", "0", "0", "0", "cv_faernaisi_her_13", "0", "0"},
[432713] = {432713, 13027, 14, 8, "0", "0", "我想在自己的“未婚夫”面前，展現出最好的自己，這種心情，您能理解嗎？", "0", "0", "0", "0", "0", "cv_faernaisi_her_14", "0", "0"},
[432714] = {432714, 13027, 15, 9, "0", "0", "要是有約會的心得就更好了。", "0", "0", "0", "0", "0", "cv_faernaisi_her_15", "0", "0"},
[432715] = {432715, 13027, 16, 10, "0", "0", "不要打擾別人的約會。", "0", "0", "0", "0", "0", "cv_faernaisi_her_16", "0", "0"},
