[432717] = {432717, 13027, 18, 12, "0", "0", "又得重新化妝了……", "0", "0", "0", "0", "0", "cv_faernaisi_her_18", "0", "0"},
[432718] = {432718, 13027, 19, 13, "0", "0", "嘖。", "0", "0", "0", "0", "0", "cv_faernaisi_her_19", "0", "0"},
[432719] = {432719, 13027, 20, 14, "0", "0", "令人作嘔的失敗……", "0", "0", "0", "0", "0", "cv_faernaisi_her_20", "0", "0"},
