[432723] = {432723, 13027, 25, 18, "0", "0", "化為花草的養分吧。", "0", "0", "0", "0", "0", "cv_faernaisi_her_25", "0", "0"},
[432724] = {432724, 13027, 26, 19, "0", "0", "約會……不想結束。", "0", "0", "0", "0", "0", "cv_faernaisi_her_26", "0", "0"},
[432725] = {432725, 13027, 27, 20, "0", "0", "既然是未婚夫，那麼坦誠相待也是理所當然的。", "0", "0", "0", "0", "0", "cv_faernaisi_her_27", "0", "0"},
[432726] = {432726, 13027, 28, 21, "0", "0", "身體上的坦誠，心靈上的坦誠，只有做到這倆點，我們才能真正的互相理解，領航。", "0", "0", "0", "0", "0", "cv_faernaisi_her_28", "0", "0"},
[432727] = {432727, 13027, 29, 21, "0", "0", "真不想結束呢……無論是現在，還是我們的關系，我都不願意讓它們結束。", "0", "0", "0", "0", "0", "cv_faernaisi_her_29", "0", "0"},
[432728] = {432728, 13027, 30, 22, "0", "0", "怎麼了？", "0", "0", "0", "0", "0", "cv_faernaisi_her_30", "0", "0"},
[432729] = {432729, 13027, 31, 23, "0", "0", "是您的話，一定能認出我的。", "0", "0", "0", "0", "0", "cv_faernaisi_her_31", "0", "0"},
[432730] = {432730, 13027, 32, 24, "0", "0", "您真懂得哄女孩子高興。", "0", "0", "0", "0", "0", "cv_faernaisi_her_32", "0", "0"},
[432731] = {432731, 13027, 33, 25, "0", "0", "欲擒故縱嗎？真狡猾。", "0", "0", "0", "0", "0", "cv_faernaisi_her_33", "0", "0"},
[432732] = {432732, 13027, 34, 26, "0", "0", "接下來要去哪裏約會，您有做好計劃嗎？是僅有你我二人的電影院，還是可以俯瞰城市的摩天輪，我都會奉陪到底的。", "0", "0", "0", "0", "0", "cv_faernaisi_her_34", "0", "0"},
[432733] = {432733, 13027, 35, 27, "0", "0", "即使是作戰中，您也要記得我和您的關系。", "0", "0", "0", "0", "0", "cv_faernaisi_her_35", "0", "0"},
[432734] = {432734, 13027, 36, 28, "0", "0", "我是永遠的勝者。", "0", "0", "0", "0", "0", "cv_faernaisi_her_36", "0", "0"},
[432735] = {432735, 13027, 37, 29, "0", "0", "該去向失敗者炫耀了。", "0", "0", "0", "0", "0", "cv_faernaisi_her_37", "0", "0"},
[432736] = {432736, 13027, 38, 30, "0", "0", "一個倆個都喜歡往您這邊湊過來呢。", "0", "0", "0", "0", "0", "cv_faernaisi_her_38", "0", "0"},
[432737] = {432737, 13027, 39, 31, "0", "0", "清點裝備。", "0", "0", "0", "0", "0", "cv_faernaisi_her_39", "0", "0"},
[432738] = {432738, 13027, 40, 32, "0", "0", "購物總是讓人心情愉快。", "0", "0", "0", "0", "0", "cv_faernaisi_her_40", "0", "0"},
