[432740] = {432740, 13027, 42, 34, "0", "0", "請設置。", "0", "0", "0", "0", "0", "cv_faernaisi_her_42", "0", "0"},
[432741] = {432741, 13027, 43, 35, "0", "0", "請逐字閱讀。", "0", "0", "0", "0", "0", "cv_faernaisi_her_43", "0", "0"},
