[4302700100] = {4302700100, 13027001, 1, 1, "0", "0", "蒼霧殘響", "0", "0", "0", "0", "0", "cv_sk_faernaisi_her_01", "0", "0"},
[4302700101] = {4302700101, 13027001, 2, 2, "0", "0", "這也是約會的一環嗎？您的想法總是那麼讓人捉摸不透呢。", "0", "0", "0", "0", "0", "cv_sk_faernaisi_her_02", "0", "0"},
[4302700102] = {4302700102, 13027001, 3, 3, "0", "0", "明明已經是熟到不能再熟的關系，卻還要自我介紹嗎？那就如您所願，“歧花”隊長，法爾奈斯·蘭特再次向您報道。", "0", "0", "0", "0", "0", "cv_sk_faernaisi_her_03", "0", "0"},
[4302700103] = {4302700103, 13027001, 91, 4, "0", "idle", "從您坐上這輛車開始，您就已經步入法爾奈斯·蘭德為您精心准備的甜蜜陷阱了。", "0", "0", "0", "0", "0", "cv_sk_faernaisi_her_n05", "0", "idle,idle"},
[4302700104] = {4302700104, 13027001, 94, 4, "0", "idle2", "好熱……但這份炎熱的源頭，是車內的溫度呢，還是說，是我內心那無法遏制的情感呢……", "0", "0", "0", "0", "0", "cv_sk_faernaisi_her_n08", "0", "idle2,idle2"},
[4302700105] = {4302700105, 13027001, 98, 4, "0", "idle3", "您如果不舍得閉上眼睛的話，是不能入睡的噢。", "0", "0", "0", "0", "0", "cv_sk_faernaisi_her_n11", "0", "idle3,idle3"},
[4302700106] = {4302700106, 13027001, 99, 4, "0", "idle4", "領航的表情真有趣……真美味。", "0", "0", "0", "0", "0", "cv_sk_faernaisi_her_n14", "0", "idle4,idle4"},
[4302700107] = {4302700107, 13027001, 92, 5, "1_》_0_0.8", "level1", "您在觸摸我的時候，也意味著我在觸摸您，這是對等的交換，領航。", "0", "0", "0", "0", "0", "cv_sk_faernaisi_her_n06", "0", "level1,level1"},
[4302700108] = {4302700108, 13027001, 92, 5, "1_》_0_0.8", "level1", "您現在的樣子，就像一個任人宰割的小動物，讓人心動。", "0", "0", "0", "0", "0", "cv_sk_faernaisi_her_n07", "0", "level1,level1"},
[4302700109] = {4302700109, 13027001, 95, 5, "1_》_0_0.8", "level2", "不知道在艾吉斯裏又有幾個人，能像我這樣幸運，盡情享用您呢？", "0", "0", "0", "0", "0", "cv_sk_faernaisi_her_n09", "0", "level2,level2"},
[4302700110] = {4302700110, 13027001, 95, 5, "1_》_0_0.8", "level2", "您的雙手不方便的話，就讓我來褪去您的衣服吧——呵，害羞了嗎？", "0", "0", "0", "0", "0", "cv_sk_faernaisi_her_n10", "0", "level2,level2"},
[4302700111] = {4302700111, 13027001, 106, 5, "1_》_0_0.8", "level3", "光是看著是不夠的的，您肯定也是這麼想的吧。", "0", "0", "0", "0", "0", "cv_sk_faernaisi_her_n12", "0", "level3,level3"},
[4302700112] = {4302700112, 13027001, 106, 5, "1_》_0_0.8", "level3", "能玩弄那個總是高高在上的領航，真是有趣的體驗。", "0", "0", "0", "0", "0", "cv_sk_faernaisi_her_n13", "0", "level3,level3"},
[4302700113] = {4302700113, 13027001, 107, 5, "1_》_0_0.8", "level4", "看來今晚，您是不能好好休息了。", "0", "0", "0", "0", "0", "cv_sk_faernaisi_her_n15", "0", "level4,level4"},
[4302700114] = {4302700114, 13027001, 107, 5, "1_》_0_0.8", "level4", "乖孩子，乖孩子，好好休息吧。", "0", "0", "0", "0", "0", "cv_sk_faernaisi_her_n16", "0", "level4,level4"},
[4302700115] = {4302700115, 13027001, 93, 5, "1_》_0_0.8", "switch1", "車上有些熱呢。", "0", "0", "0", "0", "0", "cv_sk_faernaisi_her_n01", "0", "switch1,switch1"},
