[4103700100] = {4103700100, 11037001, 1, 1, "0", "0", "蒼霧殘響", "0", "0", "0", "0", "0", "cv_saileixiya_1", "0", "0"},
[4103700101] = {4103700101, 11037001, 2, 2, "0", "0", "如果您需要的話。", "0", "0", "0", "0", "0", "cv_saileixiya_2", "0", "0"},
[4103700102] = {4103700102, 11037001, 3, 3, "0", "0", "我的名字是塞蕾希婭，聖濯教會的神職，就任於鐵鴉小隊。願源遠流長之水洗去彼此的不潔。", "0", "0", "0", "0", "0", "cv_saileixiya_3", "0", "0"},
[4103700103] = {4103700103, 11037001, 91, 4, "0", "idle", "多瑙的天空依然這麼渾濁，霧霾中的每一口呼吸，都像是在浮藻滿佈的湖中溺了水。", "0", "0", "0", "0", "0", "cv_saileixiya_4", "0", "0,idle"},
[4103700104] = {4103700104, 11037001, 94, 4, "0", "idle2", "體型變得巨大，就更容易忽視細微而又無孔不入的汙物，仿佛它們從不存在一樣……", "0", "0", "0", "0", "0", "cv_saileixiya_5", "0", "0,idle2"},
[4103700105] = {4103700105, 11037001, 98, 4, "0", "idle3", "萊帕尼隊長染上了迷茫的毒，而我則罹患了偏執的病，偶爾，我們各自的問題在對方身上或許卻成了一種良方。", "0", "0", "0", "0", "0", "cv_saileixiya_6", "0", "0,idle3"},
[4103700106] = {4103700106, 11037001, 92, 5, "1_》_0_0.8", "level1", "領航，您的嘴角有一粒飯，衣服上刮了層灰，還有……褲子拉鏈居然忘了拉上？嘖，實在是有失檢點，我真想親手為您進行一場洗禮。", "0", "0", "0", "0", "0", "cv_saileixiya_7", "0", "0,level1"},
[4103700107] = {4103700107, 11037001, 95, 5, "1_》_0_0.8", "level2", "在觸碰我之前，您是否好好進行過清潔？啊，我指的不僅是身體上的，也包括心靈。", "0", "0", "0", "0", "0", "cv_saileixiya_8", "0", "0,level2"},
[4103700108] = {4103700108, 11037001, 106, 5, "1_》_0_0.8", "level3", "我喜歡的事物？纖塵不染的羽毛、鹽晶般澄澈透明的水流、無暇的天空……然而我不確定，這份“喜歡”的情感本身，會不會成為玷污它們的泥。", "0", "0", "0", "0", "0", "cv_saileixiya_9", "0", "0,level3"},
[4103700109] = {4103700109, 11037001, 106, 5, "1_》_0_0.8", "level4", "我喜歡的事物？纖塵不染的羽毛、鹽晶般澄澈透明的水流、無暇的天空……然而我不確定，這份“喜歡”的情感本身，會不會成為玷污它們的泥。", "0", "0", "0", "0", "0", "cv_saileixiya_9", "0", "0,level4"},
[4103700110] = {4103700110, 11037001, 93, 5, "1_》_0_0.8", "switch1", "您是說，汙穢也是人類必須背負的罪罰，與其逃避，不如直面並接受？在教會中，我曾聽過類似的教誨，那麼您想讓我承受的汙穢，究竟是什麼呢？", "0", "0", "0", "0", "0", "cv_saileixiya_10", "0", "0,switch1"},
[4103700111] = {4103700111, 11037001, 102, 5, "1_》_0_0.8", "switch2", "最近我愈發感到，自己已無法處理內心氾濫成災的那份骯髒汙濁的思緒……領航，您能夠以您的力量、您的方式，為我淨化深植於心的不潔嗎？", "0", "0", "0", "0", "0", "cv_saileixiya_11", "0", "0,switch2"},
[4103700112] = {4103700112, 11037001, 96, 5, "1_》_0_0.8", "switch3", "最近我愈發感到，自己已無法處理內心氾濫成災的那份骯髒汙濁的思緒……領航，您能夠以您的力量、您的方式，為我淨化深植於心的不潔嗎？", "0", "0", "0", "0", "0", "cv_saileixiya_11", "0", "0,switch3"},
[4103700113] = {4103700113, 11037001, 12, 6, "0", "0", "不錯的感覺。", "0", "0", "0", "0", "0", "cv_saileixiya_12", "0", "0"},
[4103700114] = {4103700114, 11037001, 13, 7, "0", "0", "我不討厭這種事。", "0", "0", "0", "0", "0", "cv_saileixiya_13", "0", "0"},
[4103700115] = {4103700115, 11037001, 14, 8, "0", "0", "我希望自己不僅是力量變得強大，心靈也依舊堅如鑽石，不被外物侵蝕，依舊保持自身的光輝。", "0", "0", "0", "0", "0", "cv_saileixiya_14", "0", "0"},
[4103700116] = {4103700116, 11037001, 15, 9, "0", "0", "更加運用自如。", "0", "0", "0", "0", "0", "cv_saileixiya_15", "0", "0"},
[4103700117] = {4103700117, 11037001, 16, 10, "0", "0", "消殺這些毒物。", "0", "0", "0", "0", "0", "cv_saileixiya_16", "0", "0"},
[4103700118] = {4103700118, 11037001, 17, 11, "0", "0", "每次戰鬥都該像這樣結束。", "0", "0", "0", "0", "0", "cv_saileixiya_17", "0", "0"},
[4103700119] = {4103700119, 11037001, 18, 12, "0", "0", "還差一點，再接再厲。", "0", "0", "0", "0", "0", "cv_saileixiya_18", "0", "0"},
[4103700120] = {4103700120, 11037001, 19, 13, "0", "0", "也許完全潰敗都比這樣要好。", "0", "0", "0", "0", "0", "cv_saileixiya_19", "0", "0"},
[4103700121] = {4103700121, 11037001, 20, 14, "0", "0", "我無法忍受這種結果……", "0", "0", "0", "0", "0", "cv_saileixiya_20", "0", "0"},
[4103700122] = {4103700122, 11037001, 21, 15, "0", "0", "枯涸。", "0", "0", "0", "0", "0", "cv_saileixiya_21", "0", "0"},
[4103700123] = {4103700123, 11037001, 23, 16, "0", "0", "滌除。", "0", "0", "0", "0", "0", "cv_saileixiya_22", "0", "0"},
[4103700124] = {4103700124, 11037001, 24, 17, "0", "0", "洞見。", "0", "0", "0", "0", "0", "cv_saileixiya_23", "0", "0"},
[4103700125] = {4103700125, 11037001, 26, 19, "0", "0", "不甘心……", "0", "0", "0", "0", "0", "cv_saileixiya_25", "0", "0"},
[4103700126] = {4103700126, 11037001, 27, 20, "0", "0", "終於到了最讓人安心的地方。", "0", "0", "0", "0", "0", "cv_saileixiya_26", "0", "0"},
[4103700127] = {4103700127, 11037001, 28, 21, "0", "0", "怎麼了？沒事的話，還請不要停下動作，許多地方都還沒被您顧及。", "0", "0", "0", "0", "0", "cv_saileixiya_27", "0", "0"},
[4103700128] = {4103700128, 11037001, 29, 21, "0", "0", "在這洗滌身心的場合……領航您不會在思考某些不潔之事吧？", "0", "0", "0", "0", "0", "cv_saileixiya_28", "0", "0"},
[4103700129] = {4103700129, 11037001, 30, 22, "0", "0", "還待更多。", "0", "0", "0", "0", "0", "cv_saileixiya_29", "0", "0"},
[4103700130] = {4103700130, 11037001, 31, 23, "0", "0", "這種遊戲……有什麼意義嗎？", "0", "0", "0", "0", "0", "cv_saileixiya_30", "0", "0"},
[4103700131] = {4103700131, 11037001, 32, 24, "0", "0", "您真的想要的話，我就誇獎你一句吧。", "0", "0", "0", "0", "0", "cv_saileixiya_31", "0", "0"},
[4103700132] = {4103700132, 11037001, 33, 25, "0", "0", "看來您的判斷被某些汙物幹擾了。", "0", "0", "0", "0", "0", "cv_saileixiya_32", "0", "0"},
[4103700133] = {4103700133, 11037001, 34, 26, "0", "0", "您回來了，在不潔的此世牢籠中，讓我們今天也保持身心的純粹吧。", "0", "0", "0", "0", "0", "cv_saileixiya_33", "0", "0"},
[4103700134] = {4103700134, 11037001, 35, 27, "0", "0", "淨化必不可懈怠。", "0", "0", "0", "0", "0", "cv_saileixiya_34", "0", "0"},
[4103700135] = {4103700135, 11037001, 36, 28, "0", "0", "不會沾血的活動。", "0", "0", "0", "0", "0", "cv_saileixiya_35", "0", "0"},
[4103700136] = {4103700136, 11037001, 37, 29, "0", "0", "有不愛乾淨的人呢……", "0", "0", "0", "0", "0", "cv_saileixiya_36", "0", "0"},
[4103700137] = {4103700137, 11037001, 38, 30, "0", "0", "我會隨您一同迎接。", "0", "0", "0", "0", "0", "cv_saileixiya_37", "0", "0"},
[4103700138] = {4103700138, 11037001, 39, 31, "0", "0", "不腐之物。", "0", "0", "0", "0", "0", "cv_saileixiya_38", "0", "0"},
[4103700139] = {4103700139, 11037001, 40, 32, "0", "0", "貪慾也是種毒素。", "0", "0", "0", "0", "0", "cv_saileixiya_39", "0", "0"},
[4103700140] = {4103700140, 11037001, 41, 33, "0", "0", "還算整潔。", "0", "0", "0", "0", "0", "cv_saileixiya_40", "0", "0"},
[4103700141] = {4103700141, 11037001, 42, 34, "0", "0", "請您慢慢調整。", "0", "0", "0", "0", "0", "cv_saileixiya_41", "0", "0"},
[4103700142] = {4103700142, 11037001, 43, 35, "0", "0", "我會閉上眼。", "0", "0", "0", "0", "0", "cv_saileixiya_42", "0", "0"},
[4103700143] = {4103700143, 11037001, 44, 36, "0", "0", "言語也有乾淨汙俗之分。", "0", "0", "0", "0", "0", "cv_saileixiya_43", "0", "0"},
[4103700144] = {4103700144, 11037001, 45, 37, "0", "0", "最好不要亂碰。", "0", "0", "0", "0", "0", "cv_saileixiya_44", "0", "0"},
[4001300200] = {4001300200, 10013002, 1, 1, "0", "0", "蒼霧殘響。", "苍雾残响（ハツリバーブ）。", "0", "0", "苍雾残响。", "0", "cv_lilith_31", "0", "0"},
[4001300201] = {4001300201, 10013002, 2, 2, "0", "0", "為什麼要這麼在意我？", "何故そんなに私のことが気になるの？", "0", "0", "为什么要这么在意我？", "0", "cv_lilith_2", "0", "0"},
[4001300202] = {4001300202, 10013002, 3, 3, "0", "0", "啊，熟悉的味道啊。你就是那個真正的通感者吧。話先說在前面，我討厭所有的通感者，當然也包括我自己。", "ああ、懐かしい匂い…...あなたが真の通感覚者なのね。先に言っておくけど、私、通感覚者のことが嫌いなの。もちろん、私自身も含めて。", "0", "0", "啊，熟悉的味道啊。你就是那个真正的通感者吧。话先说在前面，我讨厌所有的通感者，当然也包括我自己。", "0", "cv_lilith_1", "0", "0"},
[4001300203] = {4001300203, 10013002, 91, 4, "0", "idle", "身為真正的通感者，你應該也能聽得到吧？大家的恐懼，憎恨以及……絕望。", "真の通感覚者のあなたなら、闻こえるんじゃない？みんなの恐怖、憎悪、そして……絶望。", "0", "0", "身为真正的通感者，你应该也能听得到吧？大家的恐惧，憎恨以及……绝望。", "0", "cv_lilith_3", "0", "0,idle"},
[4001300204] = {4001300204, 10013002, 94, 4, "0", "idle2", "在這裡浪費時間毫無意義，既然我是你的屬下，就趕快給我佈置任務吧。", "ここで时间を费やしても意味がない。ここでは私はあなたの部下なのだから、早く指示を出してちょうだい。", "0", "0", "在这里浪费时间毫无意义，既然我是你的属下，就赶快给我布置任务吧。", "0", "cv_lilith_4", "0", "0,idle2"},
[4001300205] = {4001300205, 10013002, 98, 4, "0", "idle3", "藍莓蛋糕……斯卡蒂，你又偷偷吃了我的藍莓蛋糕了吧？不要再裝了，你心裡想的我全都知道了。", "スカディ、また私のブルーベリーケーキをこっそりつまみ食いしたでしょ？知らないふりをしたって无駄よ。何を考えてるのか、私には分かる。", "0", "0", "蓝莓蛋糕……斯卡蒂，你又偷偷吃了我的蓝莓蛋糕了吧？不要再装了，你心里想的我全都知道了。", "0", "cv_lilith_28", "0", "0,idle3"},
[4001300206] = {4001300206, 10013002, 92, 5, "1_》_0_0.8", "level1", "怎麼了？我喜歡吃甜食很奇怪嗎？", "どうしたの？私がスイーツ好きなのが、そんなに惊くこと？", "0", "0", "怎么了？我喜欢吃甜食很奇怪吗？", "0", "cv_lilith_29", "0", "0,level1"},
[4001300207] = {4001300207, 10013002, 95, 5, "1_》_0_0.8", "level2", "如果可以的話，將我當作是工具就好了。", "私を道具として使っていいよ。", "0", "0", "如果可以的话，将我当作是工具就好了。", "0", "cv_lilith_5", "0", "0,level2"},
[4001300208] = {4001300208, 10013002, 106, 5, "1_》_0_0.8", "level3", "既然你也能接受到他人的負面情感的話，那麼我們姑且也能算作是通感者中的同類了吧。", "もし、あなたも他人の负の感情を感じられると言うのなら、私たちは、通感覚者の中でも同类であると言えるね。", "0", "0", "既然你也能接受到他人的负面情感的话，那么我们姑且也能算作是通感者中的同类了吧。", "0", "cv_lilith_6", "0", "0,level3"},
[4001300209] = {4001300209, 10013002, 106, 5, "1_》_0_0.8", "level4", "既然你也能接受到他人的負面情感的話，那麼我們姑且也能算作是通感者中的同類了吧。", "もし、あなたも他人の负の感情を感じられると言うのなら、私たちは、通感覚者の中でも同类であると言えるね。", "0", "0", "既然你也能接受到他人的负面情感的话，那么我们姑且也能算作是通感者中的同类了吧。", "0", "cv_lilith_6", "0", "0,level4"},
[4001300210] = {4001300210, 10013002, 93, 5, "1_》_0_0.8", "switch1", "一直以來都很辛苦吧，雖然不清楚為什麼你對此還是一副無所謂的態度。但是我很清楚，你的痛楚，你的自責……", "辛いでしょ？あなたが何故そのようにどうでもいいみたいな态度をとってるのかは知らないけど。でも、私は知ってる。あなたの苦しみと自责の念……", "0", "0", "一直以来都很辛苦吧，虽然不清楚为什么你对此还是一副无所谓的态度。但是我很清楚，你的痛楚，你的自责……", "0", "cv_lilith_7", "0", "0,switch1"},
[4001300211] = {4001300211, 10013002, 102, 5, "1_》_0_0.8", "switch2", "是同伴而不是同類嗎……隨便你怎麼說吧，我只是你的工具而已。不過在戰鬥的時候還請不要再對我使用通感了，我可不希望你的痛苦翻倍。", "同类じゃなくて仲间、か……胜手にすれば。私はただの道具だわ。あなたの道具。でも、戦ってる时は私に対して通感覚をしないで。あなたの苦しみを増やしたくないから。", "0", "0", "是同伴而不是同类吗……随便你怎么说吧，我只是你的工具而已。不过在战斗的时候还请不要再对我使用通感了，我可不希望你的痛苦翻倍。", "0", "cv_lilith_8", "0", "0,switch2"},
[4001300212] = {4001300212, 10013002, 96, 5, "1_》_0_0.8", "switch3", "是同伴而不是同類嗎……隨便你怎麼說吧，我只是你的工具而已。不過在戰鬥的時候還請不要再對我使用通感了，我可不希望你的痛苦翻倍。", "同类じゃなくて仲间、か……胜手にすれば。私はただの道具だわ。あなたの道具。でも、戦ってる时は私に対して通感覚をしないで。あなたの苦しみを増やしたくないから。", "0", "0", "是同伴而不是同类吗……随便你怎么说吧，我只是你的工具而已。不过在战斗的时候还请不要再对我使用通感了，我可不希望你的痛苦翻倍。", "0", "cv_lilith_8", "0", "0,switch3"},
[4001300213] = {4001300213, 10013002, 12, 6, "0", "0", "沒錯，就這樣繼續下去吧。", "そう、こうやって続けて。", "0", "0", "没错，就这样继续下去吧。", "0", "cv_lilith_9", "0", "0"},
[4001300214] = {4001300214, 10013002, 13, 7, "0", "0", "很好……這麼一來我的病就能痊癒了吧……", "良いわね…...これなら私の病もきっと治るわ……", "0", "0", "很好……这么一来我的病就能痊愈了吧……", "0", "cv_lilith_10", "0", "0"},
[4001300215] = {4001300215, 10013002, 14, 8, "0", "0", "果然，無論怎麼樣都無法擺脫通感者的身份嗎……只是，那些讓人討厭的聲音好像變得柔和了……我好像能聽到其他的聲音了。孩子們的祝福，感謝以及……祈禱的歌聲。", "やっぱり、何をやっても通感覚者という身分から逃れられないのね……でも、最近あの嫌な声が柔らかくなった気がする……私、他の声が闻こえるようになったみたいだわ。子供たちの祝福、感谢、そして……祈りの歌声。", "0", "0", "果然，无论怎么样都无法摆脱通感者的身份吗……只是，那些让人讨厌的声音好像变得柔和了……我好像能听到其他的声音了。孩子们的祝福，感谢以及……祈祷的歌声。", "0", "cv_lilith_11", "0", "0"},
[4001300216] = {4001300216, 10013002, 15, 9, "0", "0", "電流量提升了呢。", "电流の量が上がったわ。", "0", "0", "电流量提升了呢。", "0", "cv_lilith_12", "0", "0"},
[4001300217] = {4001300217, 10013002, 16, 10, "0", "0", "真討厭啊。", "嫌だわ。", "0", "0", "真讨厌啊。", "0", "cv_lilith_13", "0", "0"},
[4001300218] = {4001300218, 10013002, 17, 11, "0", "0", "不用急著感謝我。", "感谢など、要らないわ。", "0", "0", "不用急着感谢我。", "0", "cv_lilith_14", "0", "0"},
[4001300219] = {4001300219, 10013002, 18, 12, "0", "0", "都和你說過了，沒問題的。", "だから言ったでしょ？大丈夫だって。", "0", "0", "都和你说过了，没问题的。", "0", "cv_lilith_15", "0", "0"},
[4001300220] = {4001300220, 10013002, 19, 13, "0", "0", "嗯，怎麼說呢，有驚無險吧。", "…うん、なんていうか、ギリギリだったのね。", "0", "0", "嗯，怎么说呢，有惊无险吧。", "0", "cv_lilith_16", "0", "0"},
[4001300221] = {4001300221, 10013002, 20, 14, "0", "0", "啊……那些討厭的聲音…又出現了嗎。", "ああ……例の嫌な声がまた……", "0", "0", "啊……那些讨厌的声音…又出现了吗。", "0", "cv_lilith_17", "0", "0"},
[4001300222] = {4001300222, 10013002, 21, 15, "0", "0", "怨恨我吧。", "私を恨みなさい。", "0", "0", "怨恨我吧。", "0", "cv_lilith_18", "0", "0"},
[4001300223] = {4001300223, 10013002, 23, 16, "0", "0", "殺了你。", "あなたを、杀す。", "0", "0", "杀了你。", "0", "cv_lilith_19", "0", "0"},
[4001300224] = {4001300224, 10013002, 26, 19, "0", "0", "能量儲備即將歸零……終於可以結束了嗎……誰來救救我……你在哪裡啊……", "エネルギーがもうすぐ切れてしまう……やっと终わるのね……谁か、私を助けて……あなたはどこ……", "0", "0", "能量储备即将归零……终于可以结束了吗……谁来救救我……你在哪里啊……", "0", "cv_lilith_20", "0", "0"},
[4001300225] = {4001300225, 10013002, 27, 20, "0", "0", "啊，又是那股熟悉的味道呢，是你吧。", "あっ、またあの懐かしい匂いが……あなたよね？", "0", "0", "啊，又是那股熟悉的味道呢，是你吧。", "0", "cv_lilith_21", "0", "0"},
[4001300226] = {4001300226, 10013002, 28, 21, "0", "0", "和你貼得這麼近，真討厭啊……", "あなたがこんな近い所にいるなんて、嫌だわ……", "0", "0", "和你贴得这么近，真讨厌啊……", "0", "cv_lilith_22", "0", "0"},
[4001300227] = {4001300227, 10013002, 29, 21, "0", "0", "要小心點喔，我可不想聽到你摔下去時發出的哀嚎。", "あなた、気を付けてね。落ちる时の叫び声は闻きたくないわ。", "0", "0", "要小心点哦，我可不想听到你摔下去时发出的哀嚎。", "0", "cv_lilith_23", "0", "0"},
[4001300228] = {4001300228, 10013002, 30, 22, "0", "0", "放心地上吧。", "安心して行きなさい。", "0", "0", "放心地上吧。", "0", "cv_lilith_24", "0", "0"},
[4001300229] = {4001300229, 10013002, 31, 23, "0", "0", "如果敢使用通感作弊就殺了你喔。", "通感覚でカンニングしたら杀すわよ。", "0", "0", "如果敢使用通感作弊就杀了你哦。", "0", "cv_lilith_25", "0", "0"},
[4001300230] = {4001300230, 10013002, 32, 24, "0", "0", "好棒，我好開心。", "やった！…...嬉しいわ。", "0", "0", "好棒，我好开心。", "0", "cv_lilith_26", "0", "0"},
[4001300231] = {4001300231, 10013002, 33, 25, "0", "0", "啊，和我想得一樣，下次再努力吧。", "ああ、こうなると思ったわ。また次の机会に顽张って。", "0", "0", "啊，和我想得一样，下次再努力吧。", "0", "cv_lilith_27", "0", "0"},
[4001300232] = {4001300232, 10013002, 34, 26, "0", "0", "老遠就聞到你的味道了呢。當然，我指的不是體味。", "远くからあなたの匂いがしたわ。もちろん、体臭の话じゃないわよ。", "0", "0", "老远就闻到你的味道了呢。当然，我指的不是体味。", "0", "cv_lilith_30", "0", "0"},
[4001300233] = {4001300233, 10013002, 35, 27, "0", "0", "終點到底有什麼在等著我們呢？", "终点で私たちを待っているものは何だろう。", "0", "0", "终点到底有什么在等着我们呢？", "0", "cv_lilith_32", "0", "0"},
[4001300234] = {4001300234, 10013002, 36, 28, "0", "0", "這次又要持續多久呢？", "今回はどのくらい続くの？", "0", "0", "这次又要持续多久呢？", "0", "cv_lilith_33", "0", "0"},
[4001300235] = {4001300235, 10013002, 37, 29, "0", "0", "這些是同伴吧。", "この者たちは仲间よね。", "0", "0", "这些是同伴吧。", "0", "cv_lilith_34", "0", "0"},
[4001300236] = {4001300236, 10013002, 38, 30, "0", "0", "招些厲害的傢夥吧。", "优秀な人材を集めて", "0", "0", "招些厉害的家伙吧。", "0", "cv_lilith_35", "0", "0"},
[4001300237] = {4001300237, 10013002, 39, 31, "0", "0", "嗯？缺裝備了嗎？", "ん？装备が足りないの？", "0", "0", "嗯？缺装备了吗？", "0", "cv_lilith_36", "0", "0"},
[4001300238] = {4001300238, 10013002, 40, 32, "0", "0", "去採購點東西吧。", "买い物をすれば？", "0", "0", "去采购点东西吧。", "0", "cv_lilith_37", "0", "0"},
[4001300239] = {4001300239, 10013002, 41, 33, "0", "0", "確認一下個人資訊吧。", "个人情报を确认しよう。", "0", "0", "确认一下个人信息吧。", "0", "cv_lilith_38", "0", "0"},
[4001300240] = {4001300240, 10013002, 42, 34, "0", "0", "在這裡變更設定。", "ここでは设定を変更できるわ。", "0", "0", "在这里变更设置。", "0", "cv_lilith_39", "0", "0"},
[4001300241] = {4001300241, 10013002, 43, 35, "0", "0", "有給你寫的情書，開玩笑的。", "あなた宛のラブレターがあるわよ。…...冗谈よ。", "0", "0", "有给你写的情书，开玩笑的。", "0", "cv_lilith_40", "0", "0"},
[4001300242] = {4001300242, 10013002, 44, 36, "0", "0", "滿是通感者的味道呢，真討厭。", "通感覚者の匂いがする。本当に嫌だわ。", "0", "0", "满是通感者的味道呢，真讨厌。", "0", "cv_lilith_41", "0", "0"},
[4001300243] = {4001300243, 10013002, 45, 37, "0", "0", "確認一下。", "确认して。", "0", "0", "确认一下。", "0", "cv_lilith_42", "0", "0"},
[4001100200] = {4001100200, 10011002, 1, 1, "0", "0", "蒼霧殘響。", "苍雾残响（ハツリバーブ）。", "0", "0", "苍雾残响。", "0", "cv_ruoshui_32", "0", "0"},
[4001100201] = {4001100201, 10011002, 2, 2, "0", "0", "是，我會一直站在這等待您下一個命令的，領航哥哥。", "はい、次の命令までここで待ってますね。ナビゲーターのお兄さん。", "0", "0", "是，我会一直站在这等待您下一个命令的，领航哥哥。", "0", "cv_ruoshui_2", "0", "0"},
[4001100202] = {4001100202, 10011002, 3, 3, "0", "0", "我的名字是弱水…眼睛？沒關係，我能看見您的，領航哥哥。", "私の名前は弱水です。……私の目ですか？大丈夫です。ちゃんと见えてますよ、ナビゲーターのお兄さん。", "0", "0", "我的名字是弱水…眼睛？没关系，我能看见您的，领航哥哥。", "0", "cv_ruoshui_1", "0", "0"},
[4001100203] = {4001100203, 10011002, 91, 4, "0", "idle", "我的眼睛…雖然看得見，但是好像和大家看到的“世界”不一樣…不過這也是沒辦法的事吧？", "见えてはいるのですが、皆さんが见ている世界とは违うのだそうです。……まあ、それも仕方ないですね。", "0", "0", "我的眼睛…虽然看得见，但是好像和大家看到的“世界”不一样…不过这也是没办法的事吧？", "0", "cv_ruoshui_3", "0", "idle,idle"},
[4001100204] = {4001100204, 10011002, 94, 4, "0", "idle2", "領航哥哥，昨天的電視劇你看了嗎？那部電視劇雖然各種地方都很爛，但他們想要拍好一部作品的決心卻讓我超感動的！欸？沒看嗎？", "ナビゲーターのお兄さん、昨日のテレビドラマは见ましたか？色々な意味で最悪なドラマでしたが、良い作品を作ろうという姿势にすごく感动したんです！えぇ？见てないんですか！？", "0", "0", "领航哥哥，昨天的电视剧你看了吗？那部电视剧虽然各种地方都很烂，但他们想要拍好一部作品的决心却让我超感动的！诶？没看吗？", "0", "cv_ruoshui_4", "0", "idle2,idle2"},
[4001100205] = {4001100205, 10011002, 94, 4, "0", "idle2", "冥火！冥火！嗯？她不在這裡嗎…欸，她只要沒有任務的時候，感覺就跟消失了一樣，真神秘呢…我還想找她玩呢！", "冥火ー？冥火ー？あれ？いない……任务がないとすぐいなくなっちゃうんだから。……一绪に游ぼうって思ってたのに！", "0", "0", "冥火！冥火！嗯？她不在这里吗…诶，她只要没有任务的时候，感觉就跟消失了一样，真神秘呢…我还想找她玩呢！", "0", "cv_ruoshui_29", "0", "idle2,idle2"},
[4001100206] = {4001100206, 10011002, 92, 5, "1_》_0_0.8", "touch1", "以前…因為一些原因，我失去了視力，也因此失去了自己的朋友和家人…不過，一切都過去了，現在的我，只想盡自己所能地幫助大家！", "ここに来る前に……视力も、友达も、家族も失いました。……でも、それはもう过ぎたことです。今はただ、出来る限りみんなの助けになりたいんです！", "0", "0", "以前…因为一些原因，我失去了视力，也因此失去了自己的朋友和家人…不过，一切都过去了，现在的我，只想尽自己所能地帮助大家！", "0", "cv_ruoshui_30", "0", "touch1,touch1"},
[4001100207] = {4001100207, 10011002, 92, 5, "1_》_0_0.8", "touch2", "領航哥哥，眼罩…您別亂碰它呀！", "ちょっと、眼帯に…胜手に触らないでください！", "0", "0", "领航哥哥，眼罩…您别乱碰它呀！", "0", "cv_ruoshui_5", "0", "touch2,touch2"},
[4001100208] = {4001100208, 10011002, 95, 5, "1_》_0_0.8", "touch3", "哥哥，哥哥，我們一起出去玩吧，我想去遊樂場玩！", "お兄さんお兄さん、一绪に出かけましょう。游园地がいいです！", "0", "0", "哥哥，哥哥，我们一起出去玩吧，我想去游乐场玩！", "0", "cv_ruoshui_6", "0", "touch3,touch3"},
[4001100209] = {4001100209, 10011002, 95, 5, "1_》_0_0.8", "touch4", "哥哥，我們一起去看電影吧，首先要做的是去買飲料、爆米花…欸，像約會一樣？……約、約會的話，也不是不行啦。", "お兄さん、一绪に映画を见に行きましょう。まず饮み物とポップコーンを买って……え、デートみたい？……デ、デートはダメ……じゃないですけど……", "0", "0", "哥哥，我们一起去看电影吧，首先要做的是去买饮料、爆米花…诶，像约会一样？……约、约会的话，也不是不行啦。", "0", "cv_ruoshui_7", "0", "touch4,touch4"},
[4001100210] = {4001100210, 10011002, 93, 5, "1_》_0_0.8", "switch1", "是領航您的話，我不用擔心被背叛，也不用擔心你會突然消失吧…這樣就足夠了。領航，之後也請您一直陪著我吧，我…不想和您分開。", "お兄さんがナビゲーターなら、私を里切ったり、ある日突然消えちゃうこともないですよね。……それで十分です。これからもずっと私のそばに居てください。私……お兄さんと离れるのは嫌なんです。", "0", "0", "是领航您的话，我不用担心被背叛，也不用担心你会突然消失吧…这样就足够了。领航，之后也请您一直陪着我吧，我…不想和您分开。", "0", "cv_ruoshui_8", "0", "switch1,switch1"},
[4001100211] = {4001100211, 10011002, 96, 5, "1_》_0_0.8", "switch2", "是領航您的話，我不用擔心被背叛，也不用擔心你會突然消失吧…這樣就足夠了。領航，之後也請您一直陪著我吧，我…不想和您分開。", "お兄さんがナビゲーターなら、私を里切ったり、ある日突然消えちゃうこともないですよね。……それで十分です。これからもずっと私のそばに居てください。私……お兄さんと离れるのは嫌なんです。", "0", "0", "是领航您的话，我不用担心被背叛，也不用担心你会突然消失吧…这样就足够了。领航，之后也请您一直陪着我吧，我…不想和您分开。", "0", "cv_ruoshui_8", "0", "switch2,switch2"},
[4001100212] = {4001100212, 10011002, 12, 6, "0", "0", "我升級了欸！", "レベルアップしましたよ！", "0", "0", "我升级了诶！", "0", "cv_ruoshui_9", "0", "0"},
[4001100213] = {4001100213, 10011002, 13, 7, "0", "0", "武器變鋒利了！", "武器が鋭くなりました！", "0", "0", "武器变锋利了！", "0", "cv_ruoshui_10", "0", "0"},
[4001100214] = {4001100214, 10011002, 14, 8, "0", "0", "真是不可思議呢…力量在源源不斷地湧出。嗯，決定了，這份力量，這份強大，只為領航您而存在。今後，不管是什麼樣的敵人，“弱水”都會為了您，將他擊潰！", "不思议……力がどんどん涌いてきます。うん、决めました。この力、この强さはお兄さんだけのものです。これからどんな敌が现れようとも、お兄さんのために弱水が倒して见せます！", "0", "0", "真是不可思议呢…力量在源源不断地涌出。嗯，决定了，这份力量，这份强大，只为领航您而存在。今后，不管是什么样的敌人，“弱水”都会为了您，将他击溃！", "0", "cv_ruoshui_11", "0", "0"},
[4001100215] = {4001100215, 10011002, 15, 9, "0", "0", "速度變快了！", "もっと速くなりました！", "0", "0", "速度变快了！", "0", "cv_ruoshui_12", "0", "0"},
[4001100216] = {4001100216, 10011002, 16, 10, "0", "0", "瞭解，作戰開始。", "了解、作戦开始。", "0", "0", "了解，作战开始。", "0", "cv_ruoshui_13", "0", "0"},
[4001100217] = {4001100217, 10011002, 17, 11, "0", "0", "任務完成——領航，我們回去吧。", "任务完了。……帰りましょう、お兄さん。", "0", "0", "任务完成——领航，我们回去吧。", "0", "cv_ruoshui_14", "0", "0"},
[4001100218] = {4001100218, 10011002, 18, 12, "0", "0", "我沒事…但是有傷員需要治療，領航。", "大丈夫です……私より、负伤者の方を……お兄さん……", "0", "0", "我没事…但是有伤员需要治疗，领航。", "0", "cv_ruoshui_15", "0", "0"},
[4001100219] = {4001100219, 10011002, 19, 13, "0", "0", "大家…還好嗎？", "みなさん…无事ですか？", "0", "0", "大家…还好吗？", "0", "cv_ruoshui_16", "0", "0"},
[4001100220] = {4001100220, 10011002, 20, 14, "0", "0", "不能就這樣放棄，領航……", "お兄さん、谛めてはいけません……", "0", "0", "不能就这样放弃，领航……", "0", "cv_ruoshui_17", "0", "0"},
[4001100221] = {4001100221, 10011002, 21, 15, "0", "0", "已擊殺。", "撃破。", "0", "0", "已击杀。", "0", "cv_ruoshui_18", "0", "0"},
[4001100222] = {4001100222, 10011002, 23, 16, "0", "0", "敵人…要殺死才行。", "敌は…始末する。", "0", "0", "敌人…要杀死才行。", "0", "cv_ruoshui_19", "0", "0"},
[4001100223] = {4001100223, 10011002, 24, 17, "0", "0", "解決你。", "仕留める！", "0", "0", "解决你。", "0", "cv_ruoshui_21", "0", "0"},
[4001100224] = {4001100224, 10011002, 26, 19, "0", "0", "不要啊…什麼都…看不見了。", "いや…何も…见えない……", "0", "0", "不要啊…什么都…看不见了。", "0", "cv_ruoshui_20", "0", "0"},
[4001100225] = {4001100225, 10011002, 27, 20, "0", "0", "泡澡~泡澡~", "おふろ、おふろ～。", "0", "0", "泡澡~泡澡~", "0", "cv_ruoshui_22", "0", "0"},
[4001100226] = {4001100226, 10011002, 28, 21, "0", "0", "哥哥！水裡面有一條白色的大鯊魚——開玩笑的~", "お兄さん、お风吕の中に人食いザメが！……冗谈ですよー。", "0", "0", "哥哥！水里面有一条白色的大鲨鱼——开玩笑的~", "0", "cv_ruoshui_23", "0", "0"},
[4001100227] = {4001100227, 10011002, 29, 21, "0", "0", "哥哥，能幫我拿一聽碳酸飲料過來嗎~謝謝~", "お兄さん、サイダーを取ってきてくれませんか？……ありがとうございます！", "0", "0", "哥哥，能帮我拿一听碳酸饮料过来吗~谢谢~", "0", "cv_ruoshui_24", "0", "0"},
[4001100228] = {4001100228, 10011002, 30, 22, "0", "0", "是敵人嗎！？", "敌ですか！？", "0", "0", "是敌人吗！？", "0", "cv_ruoshui_25", "0", "0"},
[4001100229] = {4001100229, 10011002, 31, 23, "0", "0", "您的眼睛，能看見我嗎？", "お兄さん、ちゃんと见えてます？", "0", "0", "您的眼睛，能看见我吗？", "0", "cv_ruoshui_26", "0", "0"},
[4001100230] = {4001100230, 10011002, 32, 24, "0", "0", "好耶！哥哥是最棒的！", "やったあ！お兄さん最高です！", "0", "0", "好耶！哥哥是最棒的！", "0", "cv_ruoshui_27", "0", "0"},
[4001100231] = {4001100231, 10011002, 33, 25, "0", "0", "嗚…被背叛了。", "うぅ…里切られました。", "0", "0", "呜…被背叛了。", "0", "cv_ruoshui_28", "0", "0"},
[4001100232] = {4001100232, 10011002, 34, 26, "0", "0", "領航，歡迎回來，在你不在的時候，我也有好好努力喔！", "ナビゲーターのお兄さん、おかえりなさい。お兄さんがいない间もちゃんと顽张りましたよ！", "0", "0", "领航，欢迎回来，在你不在的时候，我也有好好努力哦！", "0", "cv_ruoshui_31", "0", "0"},
[4001100233] = {4001100233, 10011002, 35, 27, "0", "0", "要開始任務了嗎——瞭解。", "任务ですか？……了解。", "0", "0", "要开始任务了吗——了解。", "0", "cv_ruoshui_33", "0", "0"},
[4001100234] = {4001100234, 10011002, 36, 28, "0", "0", "弱水，準備出擊！", "弱水、出撃准备。", "0", "0", "弱水，准备出击！", "0", "cv_ruoshui_34", "0", "0"},
