[4105200200] = {4105200200, 11052002, 1, 1, "0", "0", "蒼霧殘響", "0", "0", "0", "0", "0", "cv_sk2_sps_001", "0", "0"},
[4105200201] = {4105200201, 11052002, 2, 2, "0", "0", "畢竟我是勇者，被人依靠是當然的，護衛工作就交給我吧。", "0", "0", "0", "0", "0", "cv_sk2_sps_002", "0", "0"},
[4105200202] = {4105200202, 11052002, 3, 3, "0", "0", "我是斯珀絲，未來的救世主，人類最後的希望，註定要拯救世界的勇者，記清楚了嗎？", "0", "0", "0", "0", "0", "cv_sk2_sps_003", "0", "0"},
[4105200203] = {4105200203, 11052002, 91, 4, "0", "idle", "旣然是勇者， 自然是什麽職業都能勝任，兔女郎當然也不在話下！", "0", "0", "0", "0", "0", "cv_sk2_sps_n02", "0", "idle,idle"},
[4105200204] = {4105200204, 11052002, 91, 4, "0", "idle", "……什麽都能做到才是勇者……不過，“兔女郎”是什麽啊？從來沒在遊戲裏聽説過誒。", "0", "0", "0", "0", "0", "cv_sk2_sps_n03", "0", "idle,idle"},
[4105200205] = {4105200205, 11052002, 94, 4, "0", "idle2", "我只是穿上了這件衣服，不代表我眞的變成了兔子，明白嗎？", "0", "0", "0", "0", "0", "cv_sk2_sps_n14", "0", "idle2,idle2"},
[4105200206] = {4105200206, 11052002, 94, 4, "0", "idle2", "不要用那種讓人不舒服的視綫盯著看啊……眞是，不要以爲自己是一號同伴就可以對我爲所欲爲啊！", "0", "0", "0", "0", "0", "cv_sk2_sps_n15", "0", "idle2,idle2"},
[4105200207] = {4105200207, 11052002, 92, 5, "1_》_0_0.8", "level1", "怎麽了？一臉壞笑……你打什麽壞主意呢？", "0", "0", "0", "0", "0", "cv_sk2_sps_n04", "0", "level1,level1"},
[4105200208] = {4105200208, 11052002, 92, 5, "1_》_0_0.8", "level2", "如果提昇等級的話，這件衣服會變得更華麗嗎？不會嗎？眞掃興……", "0", "0", "0", "0", "0", "cv_sk2_sps_n05", "0", "level2,level2"},
[4105200209] = {4105200209, 11052002, 92, 5, "1_》_0_0.8", "level2", "我説你也差不多該膩了吧，這眞的很好玩嗎？", "0", "0", "0", "0", "0", "cv_sk2_sps_n06", "0", "level2,level2"},
[4105200210] = {4105200210, 11052002, 95, 5, "1_》_0_0.8", "level3", "笨蛋同伴！白癡同伴！變態同伴！", "0", "0", "0", "0", "0", "cv_sk2_sps_n16", "0", "level3,level3"},
[4105200211] = {4105200211, 11052002, 95, 5, "1_》_0_0.8", "level4", "果然……差不多該喊出那句話了……媽媽教我的，應付這種場合時該説的話——“變態！！！！！！！”", "0", "0", "0", "0", "0", "cv_sk2_sps_n17", "0", "level4,level4"},
[4105200212] = {4105200212, 11052002, 95, 5, "1_》_0_0.8", "level4", "聽好了，今天的事情絶對不能讓第三个人知道，有損勇者的威嚴！", "0", "0", "0", "0", "0", "cv_sk2_sps_n18", "0", "level4,level4"},
[4105200213] = {4105200213, 11052002, 93, 5, "1_》_0_0.8", "switch1", "白癡！", "0", "0", "0", "0", "0", "cv_sk2_sps_n07", "0", "switch1,switch1"},
[4105200214] = {4105200214, 11052002, 96, 5, "1_》_0_0.8", "switch2", "眞是的……", "0", "0", "0", "0", "0", "cv_sk2_sps_n13", "0", "switch2,switch2"},
[4105200215] = {4105200215, 11052002, 12, 6, "0", "0", "要是能用指令升級就好了。", "0", "0", "0", "0", "0", "cv_sk2_sps_012", "0", "0"},
