[4104000201] = {4104000201, 11040002, 2, 2, "0", "0", "我會在這裡和領航一起加油的。", "0", "0", "0", "0", "0", "cv_sk2_dororisu_haani_002", "0", "0"},
[4104000202] = {4104000202, 11040002, 3, 3, "0", "0", "……不管多少次，穿上這套AVG還是會有點難為情呢……走吧領航，不過現在是不是稱呼您為製作人先生比較好？", "0", "0", "0", "0", "0", "cv_sk2_dororisu_haani_003", "0", "0"},
[4104000203] = {4104000203, 11040002, 91, 4, "0", "idle", "先是偶像……然後是兔女郎……好像越來越奇怪了……不過爲了領航，我會努力的！", "0", "0", "0", "0", "0", "cv_sk2_dororisu_haani_n02", "0", "0,idle"},
[4104000204] = {4104000204, 11040002, 91, 4, "0", "idle", "不管是作爲偶像，還是作爲兔女郎，我都會努力爲領航帶來笑容的……至少，我希望領航在疲憊的時候能提供依靠……", "0", "0", "0", "0", "0", "cv_sk2_dororisu_haani_n03", "0", "0,idle"},
[4104000205] = {4104000205, 11040002, 91, 4, "0", "idle", "要是領航累了的話，就睡在我旁邊吧……沒關繫的，我不介意的！", "0", "0", "0", "0", "0", "cv_sk2_dororisu_haani_n04", "0", "0,idle"},
[4104000206] = {4104000206, 11040002, 94, 4, "0", "idle2", "那个……領航，差不多該……放下來了吧？", "0", "0", "0", "0", "0", "cv_sk2_dororisu_haani_n10", "0", "0,idle2"},
[4104000207] = {4104000207, 11040002, 94, 4, "0", "idle2", "雖然有些奇怪，但旣然是領航要做的事情，那一定有你的理由！", "0", "0", "0", "0", "0", "cv_sk2_dororisu_haani_n11", "0", "0,idle2"},
[4104000208] = {4104000208, 11040002, 94, 4, "0", "idle2", "這樣擡著腿，感覺腦袋也變得奇怪了……還是説，是空調太熱了……？", "0", "0", "0", "0", "0", "cv_sk2_dororisu_haani_n12", "0", "0,idle2"},
[4104000209] = {4104000209, 11040002, 92, 5, "1_》_0_0.8", "touch1", "我的衣服有哪裏不對嗎？", "0", "0", "0", "0", "0", "cv_sk2_dororisu_haani_n05", "0", "0,touch1"},
[4104000210] = {4104000210, 11040002, 92, 5, "1_》_0_0.8", "touch1", "領航、領航，你的視綫……太、太明顯了……", "0", "0", "0", "0", "0", "cv_sk2_dororisu_haani_n06", "0", "0,touch1"},
[4104000211] = {4104000211, 11040002, 92, 5, "1_》_0_0.8", "touch2", "領航想要做什麽，都是可以的噢，因爲多洛莉絲現在是領航的小兔子~", "0", "0", "0", "0", "0", "cv_sk2_dororisu_haani_n07", "0", "0,touch2"},
[4104000212] = {4104000212, 11040002, 92, 5, "1_》_0_0.8", "touch2", "不要比兔子還急躁噢，領航~", "0", "0", "0", "0", "0", "cv_sk2_dororisu_haani_n08", "0", "0,touch2"},
[4104000213] = {4104000213, 11040002, 95, 5, "1_》_0_0.8", "touch3", "什麽時候都要保持微笑……嗯，微笑！", "0", "0", "0", "0", "0", "cv_sk2_dororisu_haani_n13", "0", "0,touch3"},
[4104000214] = {4104000214, 11040002, 95, 5, "1_》_0_0.8", "touch3", "咿——別，別突然嚇人啊，領航……", "0", "0", "0", "0", "0", "cv_sk2_dororisu_haani_n14", "0", "0,touch3"},
[4104000215] = {4104000215, 11040002, 95, 5, "1_》_0_0.8", "touch4", "嗚……領航總是這樣，喜歡捉弄人……惡趣味……", "0", "0", "0", "0", "0", "cv_sk2_dororisu_haani_n15", "0", "0,touch4"},
[4104000216] = {4104000216, 11040002, 95, 5, "1_》_0_0.8", "touch4", "領航欺負人……", "0", "0", "0", "0", "0", "cv_sk2_dororisu_haani_n16", "0", "0,touch4"},
[4104000217] = {4104000217, 11040002, 93, 5, "1_》_0_0.8", "switch1", "咿？！腿、腿怎麽了嗎？", "0", "0", "0", "0", "0", "cv_sk2_dororisu_haani_n01", "0", "0,switch1"},
[4104000218] = {4104000218, 11040002, 96, 5, "1_》_0_0.8", "switch2", "放下來了……", "0", "0", "0", "0", "0", "cv_sk2_dororisu_haani_n09", "0", "0,switch2"},
[4104000219] = {4104000219, 11040002, 12, 6, "0", "0", "我會繼續努力的！我要成為大家戰鬥的理由。", "0", "0", "0", "0", "0", "cv_sk2_dororisu_haani_012", "0", "0"},
[4104000220] = {4104000220, 11040002, 13, 7, "0", "0", "感覺現在的我可以做得更多。", "0", "0", "0", "0", "0", "cv_sk2_dororisu_haani_013", "0", "0"},
[4104000221] = {4104000221, 11040002, 14, 8, "0", "0", "傳遞更多希望，帶走大家的悲傷，我要做到這樣的事情。", "0", "0", "0", "0", "0", "cv_sk2_dororisu_haani_014", "0", "0"},
[4104000222] = {4104000222, 11040002, 15, 9, "0", "0", "這身裝甲，裝載了很多新功能，我還在慢慢熟悉。", "0", "0", "0", "0", "0", "cv_sk2_dororisu_haani_015", "0", "0"},
