[4106100100] = {4106100100, 11061001, 1, 1, "0", "0", "蒼霧殘響", "0", "0", "0", "0", "0", "cv_sk_kmra_01", "0", "0"},
[4106100101] = {4106100101, 11061001, 2, 2, "0", "0", "這个工作有更合適的人吧？我知道了我知道了，我會好好做的……眞無聊。", "0", "0", "0", "0", "0", "cv_sk_kmra_02", "0", "0"},
[4106100102] = {4106100102, 11061001, 3, 3, "0", "0", "魔防隊二番組組長，上運天美羅！要是有棘手的敵人就交給我吧！", "0", "0", "0", "0", "0", "cv_sk_kmra_03", "0", "0"},
[4106100103] = {4106100103, 11061001, 91, 4, "0", "idle", "這種時候要是能用分身就好了……讓分身來替我穿這身羞恥的衣服……啊？你説分身穿了等於我穿了……嘁！", "0", "0", "0", "0", "0", "cv_sk_kmra_n08", "0", "0,idle"},
[4106100104] = {4106100104, 11061001, 91, 4, "0", "idle", "這身衣服很適合我？你……是不是腦子壞掉了？這種下、下流的衣服哪裏好看了！", "0", "0", "0", "0", "0", "cv_sk_kmra_n09", "0", "0,idle"},
[4106100105] = {4106100105, 11061001, 94, 4, "0", "idle2", "什、什麽啊……臉這麽紅……我這身打扮，就那麽讓你興奮嗎……變態", "0", "0", "0", "0", "0", "cv_sk_kmra_n14", "0", "0,idle2"},
[4106100106] = {4106100106, 11061001, 94, 4, "0", "idle2", "好別扭的衣服……下次絶對不穿這種東西喝酒了。", "0", "0", "0", "0", "0", "cv_sk_kmra_n15", "0", "0,idle2"},
[4106100107] = {4106100107, 11061001, 92, 5, "1_》_0_0.8", "touch1", "今天的事，是一生的恥辱！", "0", "0", "0", "0", "0", "cv_sk_kmra_n10", "0", "0,touch1"},
[4106100108] = {4106100108, 11061001, 92, 5, "1_》_0_0.8", "touch2", "別一直盯著看呀……", "0", "0", "0", "0", "0", "cv_sk_kmra_n11", "0", "0,touch2"},
[4106100109] = {4106100109, 11061001, 92, 5, "1_》_0_0.8", "touch2", "要、要干嘛啊？！", "0", "0", "0", "0", "0", "cv_sk_kmra_n12", "0", "0,touch2"},
[4106100110] = {4106100110, 11061001, 95, 5, "1_》_0_0.8", "touch3", "這个尾巴眞礙事……餧，幫我弄一下……笨蛋！不是讓你摸屁股！", "0", "0", "0", "0", "0", "cv_sk_kmra_n16", "0", "0,touch3"},
