[4203500100] = {4203500100, 12035001, 1, 1, "0", "0", "蒼霧殘響", "0", "0", "0", "0", "0", "cv_sk_eykm_01", "0", "0"},
[4203500101] = {4203500101, 12035001, 2, 2, "0", "0", "夜雲很厲害的噢？可以做很多事情的噢？只是站在這裏也太大材小用了啦。", "0", "0", "0", "0", "0", "cv_sk_eykm_02", "0", "0"},
[4203500102] = {4203500102, 12035001, 3, 3, "0", "0", "打擾了！夜雲來找你玩啦！工作？唉？夜雲到這裏也需要工作嗎？認眞的嗎？誒——眞掃興~", "0", "0", "0", "0", "0", "cv_sk_eykm_03", "0", "0"},
[4203500103] = {4203500103, 12035001, 91, 4, "0", "idle", "這件衣服可是夜雲爲自己量身定做的——夜雲最有魅力的地方可是都展現出來了！", "0", "0", "0", "0", "0", "cv_sk_eykm_n08", "0", "idle,idle"},
[4203500104] = {4203500104, 12035001, 91, 4, "0", "idle", "女子高中生可是這世界上最美妙的存在，可惜夜雲已經不是了，眞是遺憾。", "0", "0", "0", "0", "0", "cv_sk_eykm_n09", "0", "idle,idle"},
[4203500105] = {4203500105, 12035001, 94, 4, "0", "idle2", "怎麽在發獃？是被夜雲的魅力給迷住了嗎？眞沒辦法，畢竟夜雲是如風般的偶像嘛~", "0", "0", "0", "0", "0", "cv_sk_eykm_n14", "0", "idle2,idle2"},
[4203500106] = {4203500106, 12035001, 94, 4, "0", "idle2", "把無敵美麗的偶像夜雲小姐的身姿深深映入靈魂吧，這可是僅有一次的福利大派送~", "0", "0", "0", "0", "0", "cv_sk_eykm_n15", "0", "idle2,idle2"},
[4203500107] = {4203500107, 12035001, 92, 5, "1_》_0_0.8", "touch1", "別對著這種地方吹氣……很痒的啦！你是哪裏來的醉鬼大叔嗎？！", "0", "0", "0", "0", "0", "cv_sk_eykm_n10", "0", "touch1,touch1"},
[4203500108] = {4203500108, 12035001, 92, 5, "1_》_0_0.8", "touch2", "現在就是把工作的事情拋到腦後，盡可能嗨起來的時候！", "0", "0", "0", "0", "0", "cv_sk_eykm_n11", "0", "touch2,touch2"},
[4203500109] = {4203500109, 12035001, 92, 5, "1_》_0_0.8", "touch2", "臉這麽紅啊？是因爲酒嗎？還是説……是夜雲的腿太迷人了？", "0", "0", "0", "0", "0", "cv_sk_eykm_n12", "0", "touch2,touch2"},
