[4400800100] = {4400800100, 14008001, 1, 1, "0", "0", "蒼霧殘響", "0", "0", "0", "0", "0", "cv_sk_yren_01", "0", "0"},
[4400800101] = {4400800101, 14008001, 2, 2, "0", "0", "正好，我也對艾吉斯的工作流程有些興趣。", "0", "0", "0", "0", "0", "cv_sk_yren_02", "0", "0"},
[4400800102] = {4400800102, 14008001, 3, 3, "0", "0", "全宇宙、全時空、萬事萬物皆在我的掌控之中。這份力量的盡頭，用雙眼好好見證吧。", "0", "0", "0", "0", "0", "cv_sk_yren_03", "0", "0"},
[4400800103] = {4400800103, 14008001, 91, 4, "0", "idle", "目光一直盯著哪裏呢？……想摸嗎？沒有我的許可可是不允許的哦。", "0", "0", "0", "0", "0", "cv_sk_yren_n08", "0", "idle,idle"},
[4400800104] = {4400800104, 14008001, 91, 4, "0", "idle", "無論什麽樣的衣服都能駕馭，這就是山城戀呢。呵…。", "0", "0", "0", "0", "0", "cv_sk_yren_n09", "0", "idle,idle"},
[4400800105] = {4400800105, 14008001, 94, 4, "0", "idle2", "你的表情眞有意思……與其保持理智的克制，不如沉溺在欲望中，那樣對你更好。", "0", "0", "0", "0", "0", "cv_sk_yren_n14", "0", "idle2,idle2"},
[4400800106] = {4400800106, 14008001, 94, 4, "0", "idle2", "偶爾嘗試下不同的風格也不錯呢。這才像我。", "0", "0", "0", "0", "0", "cv_sk_yren_n15", "0", "idle2,idle2"},
[4400800107] = {4400800107, 14008001, 92, 5, "1_》_0_0.8", "touch1", "再靠近一點，還是説，你希望我親自走過去嗎？", "0", "0", "0", "0", "0", "cv_sk_yren_n10", "0", "touch1,touch1"},
[4400800108] = {4400800108, 14008001, 92, 5, "1_》_0_0.8", "touch2", "臉都紅透了……眞是可愛。就這樣保持著那副癡迷的表情，把我的身姿刻印在腦海裏吧。", "0", "0", "0", "0", "0", "cv_sk_yren_n11", "0", "touch2,touch2"},
