[416100] = {416100, 11061, 1, 1, "0", "0", "蒼霧殘響", "0", "0", "0", "0", "0", "cv_kmra_01", "0", "0"},
[416101] = {416101, 11061, 2, 2, "0", "0", "這个工作有更合適的人吧？我知道了我知道了，我會好好做的……眞無聊。", "0", "0", "0", "0", "0", "cv_kmra_02", "0", "0"},
[416102] = {416102, 11061, 3, 3, "0", "0", "魔防隊二番組組長，上運天美羅！要是有棘手的敵人就交給我吧！", "0", "0", "0", "0", "0", "cv_kmra_03", "0", "0"},
[416103] = {416103, 11061, 4, 4, "0", "idle", "雖然我不想勸你擅離職守之類的……不過你一天的工作就是坐在這裏嗎？不會無聊嗎？要不請假和我出去逛逛——這个世界也有很多有趣的地方吧？", "0", "0", "0", "0", "0", "cv_kmra_04", "0", "0"},
[416104] = {416104, 11061, 5, 4, "0", "idle", "你們世界的那个“原罪”的東西，看起來挺經打的嘛。下次再遇到了記得叫我，讓我熱熱手！", "0", "0", "0", "0", "0", "cv_kmra_05", "0", "0"},
[416105] = {416105, 11061, 6, 4, "0", "idle3", "下任總組長一定是我！現在的總組長聊興趣倒是挺合得來，不過啊，果然還是想親自照顧大家啊。", "0", "0", "0", "0", "0", "cv_kmra_06", "0", "0"},
[416106] = {416106, 11061, 7, 5, "1_》_0_0.8", "level1", "在這个世界上，有著比“強大”更爲重要的事情——那就是靈魂的價値。缺少了這个，再強大的人也只不過是个沒有內容物的外殻。", "0", "0", "0", "0", "0", "cv_kmra_07", "0", "0"},
[416107] = {416107, 11061, 8, 5, "1_》_0_0.8", "level2", "嘖……別亂碰，很痒啊！", "0", "0", "0", "0", "0", "cv_kmra_08", "0", "0"},
[416108] = {416108, 11061, 9, 5, "1_》_100_1.5", "level3", "總覺得那个……叫做“駕駛員”來著？其他駕駛員好像對你的觸摸不抵觸……爲什麽？這是你們這的習俗嗎？", "0", "0", "0", "0", "0", "cv_kmra_09", "0", "0"},
[416109] = {416109, 11061, 10, 5, "1_》_500_2", "level4", "如果是想幫我按摩的話，以你的力氣還是太弱了一點，再使點勁吧。", "0", "0", "0", "0", "0", "cv_kmra_10", "0", "0"},
[416110] = {416110, 11061, 11, 5, "1_》_1000_2.5", "level5", "什、什麽啊……氣氛突然變得這麽奇怪……！不、不準看我的臉！如果你敢説出去，我就……我就……揍你！", "0", "0", "0", "0", "0", "cv_kmra_11", "0", "0"},
[416111] = {416111, 11061, 12, 6, "0", "0", "謝啦！", "0", "0", "0", "0", "0", "cv_kmra_12", "0", "0"},
[416112] = {416112, 11061, 13, 7, "0", "0", "感覺不錯！", "0", "0", "0", "0", "0", "cv_kmra_13", "0", "0"},
[416113] = {416113, 11061, 14, 8, "0", "0", "總組長，我當定了！", "0", "0", "0", "0", "0", "cv_kmra_14", "0", "0"},
[416114] = {416114, 11061, 15, 9, "0", "0", "“緋色連隊”變得更強了嗎？", "0", "0", "0", "0", "0", "cv_kmra_15", "0", "0"},
[416115] = {416115, 11061, 16, 10, "0", "0", "我單獨一人，就足以擊潰敵人！", "0", "0", "0", "0", "0", "cv_kmra_16", "0", "0"},
