[416117] = {416117, 11061, 18, 12, "0", "0", "這種程度連熱身都算不上呢。", "0", "0", "0", "0", "0", "cv_kmra_18", "0", "0"},
[416118] = {416118, 11061, 19, 13, "0", "0", "嘁，我可不想被總組長説教。", "0", "0", "0", "0", "0", "cv_kmra_19", "0", "0"},
[416119] = {416119, 11061, 20, 14, "0", "0", "還沒有結束，拏出骨氣來！", "0", "0", "0", "0", "0", "cv_kmra_20", "0", "0"},
[416120] = {416120, 11061, 21, 15, "0", "0", "眞弱！", "0", "0", "0", "0", "0", "cv_kmra_21", "0", "0"},
