[416124] = {416124, 11061, 25, 18, "0", "0", "誰都不會死的——要上了，“緋色連隊”！", "0", "0", "0", "0", "0", "cv_kmra_24", "0", "0"},
[416125] = {416125, 11061, 26, 19, "0", "0", "可惡……", "0", "0", "0", "0", "0", "cv_kmra_26", "0", "0"},
