[4001000241] = {4001000241, 10010002, 44, 36, "0", "0", "遇到喜歡的人記得要聯繫方式喔。", "気に入った人とは连络先の交换を忘れずにね。", "0", "0", "遇到喜欢的人记得要联系方式哦。", "0", "cv_alaita_42", "0", "0"},
