[4202100200] = {4202100200, 12021002, 1, 1, "0", "0", "蒼霧殘響。", "0", "0", "0", "0", "0", "cv_shaoyin_1", "0", "0"},
[4202100201] = {4202100201, 12021002, 2, 2, "0", "0", "承蒙抬愛。", "0", "0", "0", "0", "0", "cv_shaoyin_2", "0", "0"},
[4202100202] = {4202100202, 12021002, 3, 3, "0", "0", "小女子名為韶音，可輔以排兵佈陣，出謀劃策。願共事愉悅。", "0", "0", "0", "0", "0", "cv_shaoyin_3", "0", "0"},
[4202100203] = {4202100203, 12021002, 91, 4, "0", "idle", "只要我保持安靜、不說話，是不是領航就會再多陪我一會兒呢？", "0", "0", "0", "0", "0", "cv_shaoyin_4", "0", "idle,idle"},
[4202100204] = {4202100204, 12021002, 94, 4, "0", "idle2", "……嘿嘿，即便什麼話都不說，但領航只是陪在身邊，我就好開心啊。", "0", "0", "0", "0", "0", "cv_shaoyin_5", "0", "idle2,idle2"},
[4202100205] = {4202100205, 12021002, 92, 5, "1_》_0_0.8", "touch1", "真希望時間能永遠停留在當下……", "0", "0", "0", "0", "0", "cv_shaoyin_6", "0", "touch1,touch1"},
[4202100206] = {4202100206, 12021002, 92, 5, "1_》_0_0.8", "touch2", "此番造訪，是為何事？", "0", "0", "0", "0", "0", "cv_shaoyin_7", "0", "touch2,touch2"},
[4202100207] = {4202100207, 12021002, 95, 5, "1_》_0_0.8", "touch3", "既得領航委命，小女子自會事無巨細，事必躬親。", "0", "0", "0", "0", "0", "cv_shaoyin_8", "0", "touch3,touch3"},
[4202100208] = {4202100208, 12021002, 95, 5, "1_》_0_0.8", "touch4", "無需拘謹。既然好奇，多摸一會兒又何妨？小女子——不，是我。我很開心哦。倒不如說，僅靠一對鹿角就能與領航這般親昵，未免也太走運了吧我？！", "0", "0", "0", "0", "0", "cv_shaoyin_9", "0", "touch4,touch4"},
[4202100209] = {4202100209, 12021002, 93, 5, "1_》_0_0.8", "switch1", "要來聊天嗎？好呀。我等這一刻已經很久了，有很多很多話想跟領航您說呢。", "0", "0", "0", "0", "0", "cv_shaoyin_10", "0", "switch1,switch1"},
[4202100210] = {4202100210, 12021002, 96, 5, "1_》_0_0.8", "switch2", "所以說，再多陪陪我有什麼不好的？最近領航您不是和其他駕駛員去出任務，就是在指揮室裡待著，一天下來都見不了幾面……我、我也是會寂寞的，不要留我一個人在這裡呐……", "0", "0", "0", "0", "0", "cv_shaoyin_11", "0", "switch2,switch2"},
[4202100211] = {4202100211, 12021002, 12, 6, "0", "0", "善矣。", "0", "0", "0", "0", "0", "cv_shaoyin_12", "0", "0"},
[4202100212] = {4202100212, 12021002, 13, 7, "0", "0", "此般垂青，定不辜負。", "0", "0", "0", "0", "0", "cv_shaoyin_13", "0", "0"},
[4202100213] = {4202100213, 12021002, 14, 8, "0", "0", "……領航，誇誇我好嗎？", "0", "0", "0", "0", "0", "cv_shaoyin_14", "0", "0"},
[4202100214] = {4202100214, 12021002, 15, 9, "0", "0", "利器，然工事。", "0", "0", "0", "0", "0", "cv_shaoyin_15", "0", "0"},
[4202100215] = {4202100215, 12021002, 16, 10, "0", "0", "明瞭。", "0", "0", "0", "0", "0", "cv_shaoyin_16", "0", "0"},
[4202100216] = {4202100216, 12021002, 17, 11, "0", "0", "敬賀領航大獲全勝。", "0", "0", "0", "0", "0", "cv_shaoyin_17", "0", "0"},
[4202100217] = {4202100217, 12021002, 18, 12, "0", "0", "無需失落，略有瑕疵而已。", "0", "0", "0", "0", "0", "cv_shaoyin_18", "0", "0"},
[4202100218] = {4202100218, 12021002, 19, 13, "0", "0", "……是以領航更勝一籌，應當高興。", "0", "0", "0", "0", "0", "cv_shaoyin_19", "0", "0"},
[4202100219] = {4202100219, 12021002, 20, 14, "0", "0", "怎麼會這樣？等等，先讓我複盤一下，看問題究竟出在那裡……", "0", "0", "0", "0", "0", "cv_shaoyin_20", "0", "0"},
[4202100220] = {4202100220, 12021002, 21, 15, "0", "0", "後會無期。", "0", "0", "0", "0", "0", "cv_shaoyin_21", "0", "0"},
[4202100221] = {4202100221, 12021002, 23, 16, "0", "0", "落。", "0", "0", "0", "0", "0", "cv_shaoyin_23", "0", "0"},
[4202100222] = {4202100222, 12021002, 24, 17, "0", "0", "斬草需除根。", "0", "0", "0", "0", "0", "cv_shaoyin_24", "0", "0"},
[4202100223] = {4202100223, 12021002, 25, 18, "0", "0", "謀事在人，成事在天。", "0", "0", "0", "0", "0", "cv_shaoyin_25", "0", "0"},
[4202100224] = {4202100224, 12021002, 22, 38, "0", "0", "正如小女子所料。", "0", "0", "0", "0", "0", "cv_shaoyin_22", "0", "0"},
[4202100225] = {4202100225, 12021002, 26, 19, "0", "0", "失罪于此，乞蒙見恕。", "0", "0", "0", "0", "0", "cv_shaoyin_26", "0", "0"},
[4202100226] = {4202100226, 12021002, 27, 20, "0", "0", "連這裡也有您相伴呀。", "0", "0", "0", "0", "0", "cv_shaoyin_27", "0", "0"},
[4202100227] = {4202100227, 12021002, 28, 21, "0", "0", "欲速則不達。", "0", "0", "0", "0", "0", "cv_shaoyin_28", "0", "0"},
[4202100228] = {4202100228, 12021002, 29, 21, "0", "0", "……所以說慢慢來嘛。和我在這裡多呆一會兒不好嗎？", "0", "0", "0", "0", "0", "cv_shaoyin_29", "0", "0"},
[4202100229] = {4202100229, 12021002, 30, 22, "0", "0", "原來這裡還設有小遊戲呀。", "0", "0", "0", "0", "0", "cv_shaoyin_30", "0", "0"},
[4202100230] = {4202100230, 12021002, 31, 23, "0", "0", "是小女子哦。可千萬要猜對哦。", "0", "0", "0", "0", "0", "cv_shaoyin_31", "0", "0"},
[4202100231] = {4202100231, 12021002, 32, 24, "0", "0", "太好啦！", "0", "0", "0", "0", "0", "cv_shaoyin_32", "0", "0"},
[4202100232] = {4202100232, 12021002, 33, 25, "0", "0", "……我沒有生氣。", "0", "0", "0", "0", "0", "cv_shaoyin_33", "0", "0"},
[4202100233] = {4202100233, 12021002, 34, 26, "0", "0", "什麼嘛，又只剩我一個人——咿呀？！領、領航，您回來呐……咳，小女子方才什麼都沒說，您也什麼都沒聽見。", "0", "0", "0", "0", "0", "cv_shaoyin_34", "0", "0"},
