[4202100236] = {4202100236, 12021002, 37, 29, "0", "0", "領航認識的駕駛員可真多啊……", "0", "0", "0", "0", "0", "cv_shaoyin_37", "0", "0"},
[4202100237] = {4202100237, 12021002, 38, 30, "0", "0", "此般仁人志士……等等，該不會是準備把我換掉了吧？", "0", "0", "0", "0", "0", "cv_shaoyin_38", "0", "0"},
