[4202100239] = {4202100239, 12021002, 40, 32, "0", "0", "欲易何物？", "0", "0", "0", "0", "0", "cv_shaoyin_40", "0", "0"},
[4202100240] = {4202100240, 12021002, 41, 33, "0", "0", "哼哼，領航的助理是我呢~", "0", "0", "0", "0", "0", "cv_shaoyin_41", "0", "0"},
[4202100241] = {4202100241, 12021002, 42, 34, "0", "0", "難道是我話太多了，領航決定要靜我的音？", "0", "0", "0", "0", "0", "cv_shaoyin_42", "0", "0"},
[4202100242] = {4202100242, 12021002, 43, 35, "0", "0", "要不然我也寫封信寄給領航吧？", "0", "0", "0", "0", "0", "cv_shaoyin_43", "0", "0"},
[4202100243] = {4202100243, 12021002, 44, 36, "0", "0", "……不要總是和別人聊啦。", "0", "0", "0", "0", "0", "cv_shaoyin_44", "0", "0"},
[4202100244] = {4202100244, 12021002, 45, 37, "0", "0", "凡事皆應謹言慎——您已經按下去了？！", "0", "0", "0", "0", "0", "cv_shaoyin_45", "0", "0"},
[4302200200] = {4302200200, 13022002, 1, 1, "0", "0", "蒼霧殘響！", "0", "0", "0", "0", "0", "cv_monika_1", "0", "0"},
[4302200201] = {4302200201, 13022002, 2, 2, "0", "0", "很好，終於遇到個有眼光的上司了。", "0", "0", "0", "0", "0", "cv_monika_2", "0", "0"},
[4302200202] = {4302200202, 13022002, 3, 3, "0", "0", "自我介紹？檔案上不都寫著了嗎……“莫妮卡”，給我記住了。", "0", "0", "0", "0", "0", "cv_monika_3", "0", "0"},
[4302200203] = {4302200203, 13022002, 91, 4, "0", "idle", "無聊，什麼時候能來新的任務？", "0", "0", "0", "0", "0", "cv_monika_4", "0", "0"},
[4302200204] = {4302200204, 13022002, 94, 4, "0", "idle2", "死死盯著對方的眼睛來施加壓力，這是審訊時才會用到的技巧。", "0", "0", "0", "0", "0", "cv_monika_5", "0", "0"},
[4302200205] = {4302200205, 13022002, 98, 4, "0", "idle3", "凱特琳的槍法很准但是不擅長近身格鬥，哈莉特的近身格鬥很強可面對遠程敵人束手無策。而我可以從容面對這兩種情況，所以為什麼不讓我來當黑荊棘的隊長？", "0", "0", "0", "0", "0", "cv_monika_6", "0", "0"},
[4302200206] = {4302200206, 13022002, 92, 5, "1_》_0_0.8", "touch1", "“對壞人的仁慈就是對好人的殘忍。”這就是我信奉的正義。可是其他人只會說什麼“人道主義”……狗屁！", "0", "0", "0", "0", "0", "cv_monika_7", "0", "0"},
[4302200207] = {4302200207, 13022002, 95, 5, "1_》_0_0.8", "touch2", "討厭，你是對金髮有什麼特殊癖好嗎？", "0", "0", "0", "0", "0", "cv_monika_8", "0", "0"},
[4302200208] = {4302200208, 13022002, 95, 5, "1_》_0_0.8", "touch3", "成為駕駛員的好處之一是不會有人對異獸產生同情……應該不會有吧。", "0", "0", "0", "0", "0", "cv_monika_9", "0", "0"},
[4302200209] = {4302200209, 13022002, 106, 5, "1_》_0_0.8", "touch4", "有的審訊官會用言語威脅犯人，突破他們的心理防線來讓他們說出隱藏的情報。而我更喜歡用鞭子，快捷，高效。我和那些危險分子可沒什麼好說的。", "0", "0", "0", "0", "0", "cv_monika_10", "0", "0"},
[4302200210] = {4302200210, 13022002, 93, 5, "1_》_0_0.8", "switch1", "我最近經常做相同的夢，我夢見我成了犯人，而負責審訊的人是領航你。夢裡的你溫柔而耐心，只是不停地用耳語勸導我主動坦白自己。於是我決定在今天向你說出我心裡的秘密——我喜歡……", "0", "0", "0", "0", "0", "cv_monika_11", "0", "0"},
[4302200211] = {4302200211, 13022002, 102, 5, "1_》_0_0.8", "switch2", "我最近經常做相同的夢，我夢見我成了犯人，而負責審訊的人是領航你。夢裡的你溫柔而耐心，只是不停地用耳語勸導我主動坦白自己。於是我決定在今天向你說出我心裡的秘密——我喜歡……", "0", "0", "0", "0", "0", "cv_monika_11", "0", "0"},
[4302200212] = {4302200212, 13022002, 96, 5, "1_》_0_0.8", "switch3", "我最近經常做相同的夢，我夢見我成了犯人，而負責審訊的人是領航你。夢裡的你溫柔而耐心，只是不停地用耳語勸導我主動坦白自己。於是我決定在今天向你說出我心裡的秘密——我喜歡……", "0", "0", "0", "0", "0", "cv_monika_11", "0", "0"},
[4302200213] = {4302200213, 13022002, 12, 6, "0", "0", "變強了嗎？沒什麼感覺。", "0", "0", "0", "0", "0", "cv_monika_12", "0", "0"},
[4302200214] = {4302200214, 13022002, 13, 7, "0", "0", "也算是有了些長進。", "0", "0", "0", "0", "0", "cv_monika_13", "0", "0"},
[4302200215] = {4302200215, 13022002, 14, 8, "0", "0", "這下該讓我做隊長了。", "0", "0", "0", "0", "0", "cv_monika_14", "0", "0"},
[4302200216] = {4302200216, 13022002, 15, 9, "0", "0", "新的技巧，在實戰中熟悉吧。", "0", "0", "0", "0", "0", "cv_monika_15", "0", "0"},
[4302200217] = {4302200217, 13022002, 16, 10, "0", "0", "審訊開始。", "0", "0", "0", "0", "0", "cv_monika_16", "0", "0"},
[4302200218] = {4302200218, 13022002, 17, 11, "0", "0", "就這樣結束了嗎？", "0", "0", "0", "0", "0", "cv_monika_17", "0", "0"},
[4302200219] = {4302200219, 13022002, 18, 12, "0", "0", "早知道就使出全力了。", "0", "0", "0", "0", "0", "cv_monika_18", "0", "0"},
[4302200220] = {4302200220, 13022002, 19, 13, "0", "0", "真是難纏的敵人。", "0", "0", "0", "0", "0", "cv_monika_19", "0", "0"},
[4302200221] = {4302200221, 13022002, 20, 14, "0", "0", "我還不夠資格……", "0", "0", "0", "0", "0", "cv_monika_20", "0", "0"},
[4302200222] = {4302200222, 13022002, 23, 16, "0", "0", "給我清醒一下！", "0", "0", "0", "0", "0", "cv_monika_23", "0", "0"},
[4302200223] = {4302200223, 13022002, 24, 17, "0", "0", "還沒到結束的時候。", "0", "0", "0", "0", "0", "cv_monika_24", "0", "0"},
[4302200224] = {4302200224, 13022002, 26, 19, "0", "0", "中斷審訊。", "0", "0", "0", "0", "0", "cv_monika_26", "0", "0"},
[4302200225] = {4302200225, 13022002, 27, 20, "0", "0", "這是什麼特別的審訊方式嗎？", "0", "0", "0", "0", "0", "cv_monika_27", "0", "0"},
[4302200226] = {4302200226, 13022002, 28, 21, "0", "0", "手裡沒有鞭子，心裡就沒有安全感。", "0", "0", "0", "0", "0", "cv_monika_28", "0", "0"},
[4302200227] = {4302200227, 13022002, 29, 21, "0", "0", "趁著我無法反抗的時候，將我每一部分都牢記在心吧。", "0", "0", "0", "0", "0", "cv_monika_29", "0", "0"},
[4302200228] = {4302200228, 13022002, 30, 22, "0", "0", "果然，這是一場特殊的審訊。", "0", "0", "0", "0", "0", "cv_monika_30", "0", "0"},
[4302200229] = {4302200229, 13022002, 31, 23, "0", "0", "這還需要提示？答錯的話我就用鞭子抽你。", "0", "0", "0", "0", "0", "cv_monika_31", "0", "0"},
[4302200230] = {4302200230, 13022002, 32, 24, "0", "0", "完美通過了審訊。", "0", "0", "0", "0", "0", "cv_monika_32", "0", "0"},
[4302200231] = {4302200231, 13022002, 33, 25, "0", "0", "準備好接受我的鞭撻吧。", "0", "0", "0", "0", "0", "cv_monika_33", "0", "0"},
[4302200232] = {4302200232, 13022002, 34, 26, "0", "0", "把我晾在這這麼久，是想讓我更在意你嗎？", "0", "0", "0", "0", "0", "cv_monika_34", "0", "0"},
[4302200233] = {4302200233, 13022002, 35, 27, "0", "0", "這才是我該做的事。", "0", "0", "0", "0", "0", "cv_monika_35", "0", "0"},
[4302200234] = {4302200234, 13022002, 36, 28, "0", "0", "話說前頭，我可不會點到為止。", "0", "0", "0", "0", "0", "cv_monika_36", "0", "0"},
[4302200235] = {4302200235, 13022002, 37, 29, "0", "0", "真是什麼人都能成為駕駛員。", "0", "0", "0", "0", "0", "cv_monika_37", "0", "0"},
[4302200236] = {4302200236, 13022002, 38, 30, "0", "0", "需要我來審訊她們嗎？", "0", "0", "0", "0", "0", "cv_monika_38", "0", "0"},
[4302200237] = {4302200237, 13022002, 39, 31, "0", "0", "我要多備幾根鞭子，壞得太快了。", "0", "0", "0", "0", "0", "cv_monika_39", "0", "0"},
[4302200238] = {4302200238, 13022002, 40, 32, "0", "0", "這裡充滿了陷阱。", "0", "0", "0", "0", "0", "cv_monika_40", "0", "0"},
[4302200239] = {4302200239, 13022002, 41, 33, "0", "0", "不用審訊就能知道的秘密。", "0", "0", "0", "0", "0", "cv_monika_41", "0", "0"},
[4302200240] = {4302200240, 13022002, 42, 34, "0", "0", "更改設置嗎？", "0", "0", "0", "0", "0", "cv_monika_42", "0", "0"},
[4302200241] = {4302200241, 13022002, 43, 35, "0", "0", "垃圾郵件。", "0", "0", "0", "0", "0", "cv_monika_43", "0", "0"},
[4302200242] = {4302200242, 13022002, 44, 36, "0", "0", "禍從口出。", "0", "0", "0", "0", "0", "cv_monika_44", "0", "0"},
[4302200243] = {4302200243, 13022002, 45, 37, "0", "0", "哼。", "0", "0", "0", "0", "0", "cv_monika_45", "0", "0"},
[4106200100] = {4106200100, 11062001, 1, 1, "0", "0", "蒼霧殘響", "0", "0", "0", "0", "0", "cv_sk_Julius_her_01", "0", "0"},
[4106200101] = {4106200101, 11062001, 2, 2, "0", "0", "我從哪學到的這種穿衣風格……？請容我暫時保密。", "0", "0", "0", "0", "0", "cv_sk_Julius_her_02", "0", "0"},
[4106200102] = {4106200102, 11062001, 3, 3, "0", "0", "會不會跟平時的形象差太大了，肚子露出來的部分也……啊，咳咳，貴，貴安，領航。", "0", "0", "0", "0", "0", "cv_sk_Julius_her_03", "0", "0"},
[4106200103] = {4106200103, 11062001, 91, 4, "0", "idle", "這个……請當做不可抗力。", "0", "0", "0", "0", "0", "cv_sk_Julius_her_n05", "0", "idle,idle"},
[4106200104] = {4106200104, 11062001, 94, 4, "0", "idle2", "好像……有什麽要滑下去了。", "0", "0", "0", "0", "0", "cv_sk_Julius_her_n08", "0", "idle2,idle2"},
[4106200105] = {4106200105, 11062001, 98, 4, "0", "idle3", "早知道，就穿那件更寛松的衣服了……", "0", "0", "0", "0", "0", "cv_sk_Julius_her_n11", "0", "idle3,idle3"},
[4106200106] = {4106200106, 11062001, 99, 4, "0", "idle4", "忘掉……拜託您了，一定要忘掉。", "0", "0", "0", "0", "0", "cv_sk_Julius_her_n14", "0", "idle4,idle4"},
[4106200107] = {4106200107, 11062001, 92, 5, "1_》_0_0.8", "touch1", "就這樣保持一會兒……", "0", "0", "0", "0", "0", "cv_sk_Julius_her_n06", "0", "touch1,touch1"},
[4106200108] = {4106200108, 11062001, 92, 5, "1_》_0_0.8", "touch1", "這只是一時失態……", "0", "0", "0", "0", "0", "cv_sk_Julius_her_n07", "0", "touch1,touch1"},
[4106200109] = {4106200109, 11062001, 95, 5, "1_》_0_0.8", "touch2", "啊哇哇哇……", "0", "0", "0", "0", "0", "cv_sk_Julius_her_n09", "0", "touch2,touch2"},
[4106200110] = {4106200110, 11062001, 95, 5, "1_》_0_0.8", "touch2", "請先別動……", "0", "0", "0", "0", "0", "cv_sk_Julius_her_n10", "0", "touch2,touch2"},
[4106200111] = {4106200111, 11062001, 106, 5, "1_》_0_0.8", "touch3", "這副樣子……還請您保密。", "0", "0", "0", "0", "0", "cv_sk_Julius_her_n12", "0", "touch3,touch3"},
[4106200112] = {4106200112, 11062001, 106, 5, "1_》_0_0.8", "touch3", "噓——", "0", "0", "0", "0", "0", "cv_sk_Julius_her_n13", "0", "touch3,touch3"},
[4106200113] = {4106200113, 11062001, 107, 5, "1_》_0_0.8", "touch4", "您凑得這麽近的話……", "0", "0", "0", "0", "0", "cv_sk_Julius_her_n15", "0", "touch4,touch4"},
[4106200114] = {4106200114, 11062001, 107, 5, "1_》_0_0.8", "touch4", "如、如果您堅持的話。", "0", "0", "0", "0", "0", "cv_sk_Julius_her_n16", "0", "touch4,touch4"},
[4106200115] = {4106200115, 11062001, 93, 5, "1_》_0_0.8", "switch1", "哇啊！您、您沒事吧？", "0", "0", "0", "0", "0", "cv_sk_Julius_her_n01", "0", "switch1,switch1"},
[4106200116] = {4106200116, 11062001, 102, 5, "1_》_0_0.8", "switch2", "咕……", "0", "0", "0", "0", "0", "cv_sk_Julius_her_n04", "0", "switch2,switch2"},
[4106200117] = {4106200117, 11062001, 103, 5, "1_》_0_0.8", "switch3", "那个……請不要看！", "0", "0", "0", "0", "0", "cv_sk_Julius_her_n03", "0", "switch3,switch3"},
[4106200118] = {4106200118, 11062001, 96, 5, "1_》_0_0.8", "switch4", "呼……", "0", "0", "0", "0", "0", "cv_sk_Julius_her_n02", "0", "switch4,switch4"},
[4106200119] = {4106200119, 11062001, 12, 6, "0", "0", "承蒙您的關心。", "0", "0", "0", "0", "0", "cv_sk_Julius_her_12", "0", "0"},
[4106200120] = {4106200120, 11062001, 13, 7, "0", "0", "我好像，逐漸找到發力的竅門了。", "0", "0", "0", "0", "0", "cv_sk_Julius_her_13", "0", "0"},
[4106200121] = {4106200121, 11062001, 14, 8, "0", "0", "領航！你看到我剛剛的那一球了嗎！我有自信一定是很棒的動作——啊……抱歉，我有點太激動了。", "0", "0", "0", "0", "0", "cv_sk_Julius_her_14", "0", "0"},
[4106200122] = {4106200122, 11062001, 15, 9, "0", "0", "在所有力所能及的方面毫不倦怠地提昇，這也是貴族的素養。", "0", "0", "0", "0", "0", "cv_sk_Julius_her_15", "0", "0"},
[4106200123] = {4106200123, 11062001, 16, 10, "0", "0", "結果，還是穿著這身跑上戰場了啊……", "0", "0", "0", "0", "0", "cv_sk_Julius_her_16", "0", "0"},
[4106200124] = {4106200124, 11062001, 17, 11, "0", "0", "在此，不負尼采家之名！", "0", "0", "0", "0", "0", "cv_sk_Julius_her_17", "0", "0"},
[4106200125] = {4106200125, 11062001, 18, 12, "0", "0", "又是頗有收獲的一天呢。", "0", "0", "0", "0", "0", "cv_sk_Julius_her_18", "0", "0"},
[4106200126] = {4106200126, 11062001, 19, 13, "0", "0", "我會學習在適當的場合放松，但戰場不在此列。", "0", "0", "0", "0", "0", "cv_sk_Julius_her_19", "0", "0"},
[4106200127] = {4106200127, 11062001, 20, 14, "0", "0", "過程中的失誤動作太多了……我需要進行總結，您有空協助我嗎？", "0", "0", "0", "0", "0", "cv_sk_Julius_her_20", "0", "0"},
[4106200128] = {4106200128, 11062001, 21, 15, "0", "0", "本壘打！", "0", "0", "0", "0", "0", "cv_sk_Julius_her_21", "0", "0"},
[4106200129] = {4106200129, 11062001, 23, 16, "0", "0", "只要看準時機！", "0", "0", "0", "0", "0", "cv_sk_Julius_her_22", "0", "0"},
[4106200130] = {4106200130, 11062001, 24, 17, "0", "0", "喝啊！", "0", "0", "0", "0", "0", "cv_sk_Julius_her_23", "0", "0"},
[4106200132] = {4106200132, 11062001, 25, 18, "0", "0", "這次，我絶不會失手！", "0", "0", "0", "0", "0", "cv_sk_Julius_her_24", "0", "0"},
[4106200133] = {4106200133, 11062001, 26, 19, "0", "0", "終究是，到極限了……", "0", "0", "0", "0", "0", "cv_sk_Julius_her_26", "0", "0"},
[4106200134] = {4106200134, 11062001, 27, 20, "0", "0", "我似乎動得有些太過頭了……總之，麻煩您了。", "0", "0", "0", "0", "0", "cv_sk_Julius_her_27", "0", "0"},
[4106200135] = {4106200135, 11062001, 28, 21, "0", "0", "您是説，我的耳根有些發紅……？是您的錯覺吧，錯覺！", "0", "0", "0", "0", "0", "cv_sk_Julius_her_28", "0", "0"},
[4106200136] = {4106200136, 11062001, 29, 21, "0", "0", "等一下，那一塊肌肉因爲剛剛的原因還有些敏感嘶——我、我沒事，您繼續就好。", "0", "0", "0", "0", "0", "cv_sk_Julius_her_29", "0", "0"},
[4106200137] = {4106200137, 11062001, 30, 22, "0", "0", "啊啊，貴安。", "0", "0", "0", "0", "0", "cv_sk_Julius_her_30", "0", "0"},
[4106200138] = {4106200138, 11062001, 31, 23, "0", "0", "事到如今，我相信這種事應該難不住您。", "0", "0", "0", "0", "0", "cv_sk_Julius_her_31", "0", "0"},
[4106200139] = {4106200139, 11062001, 32, 24, "0", "0", "呵呵，不愧是您。", "0", "0", "0", "0", "0", "cv_sk_Julius_her_32", "0", "0"},
[4106200140] = {4106200140, 11062001, 33, 25, "0", "0", "難道説……我的形象轉換作戰太成功了？", "0", "0", "0", "0", "0", "cv_sk_Julius_her_33", "0", "0"},
[4106200141] = {4106200141, 11062001, 34, 26, "0", "0", "等今天的工作結束後，要稍微再去什麽地方逛逛嗎？", "0", "0", "0", "0", "0", "cv_sk_Julius_her_34", "0", "0"},
[4106200142] = {4106200142, 11062001, 35, 27, "0", "0", "其他不論，唯有這件事不能放松。", "0", "0", "0", "0", "0", "cv_sk_Julius_her_35", "0", "0"},
[4106200143] = {4106200143, 11062001, 36, 28, "0", "0", "我在這方面已經做了很多功課——誒，不是在説棒球賽實戰的事嗎？", "0", "0", "0", "0", "0", "cv_sk_Julius_her_36", "0", "0"},
[4106200144] = {4106200144, 11062001, 37, 29, "0", "0", "大家，應該不至於被我的打扮嚇到吧？", "0", "0", "0", "0", "0", "cv_sk_Julius_her_37", "0", "0"},
[4106200145] = {4106200145, 11062001, 38, 30, "0", "0", "可以的話……我還是希望這个場合可以私密一些。", "0", "0", "0", "0", "0", "cv_sk_Julius_her_38", "0", "0"},
[4106200146] = {4106200146, 11062001, 39, 31, "0", "0", "適時體驗新的東西吧。", "0", "0", "0", "0", "0", "cv_sk_Julius_her_39", "0", "0"},
[4106200147] = {4106200147, 11062001, 40, 32, "0", "0", "在必要的節制以外，請自便。", "0", "0", "0", "0", "0", "cv_sk_Julius_her_40", "0", "0"},
[4106200148] = {4106200148, 11062001, 41, 33, "0", "0", "我沒想到……您眞的會把那顆棒球畱下來。", "0", "0", "0", "0", "0", "cv_sk_Julius_her_41", "0", "0"},
[4106200149] = {4106200149, 11062001, 42, 34, "0", "0", "適當地做出變化。", "0", "0", "0", "0", "0", "cv_sk_Julius_her_42", "0", "0"},
[4106200150] = {4106200150, 11062001, 43, 35, "0", "0", "仔細确認一下，沒有漏掉信息吧？", "0", "0", "0", "0", "0", "cv_sk_Julius_her_43", "0", "0"},
[4106200151] = {4106200151, 11062001, 44, 36, "0", "0", "我最近深刻地體會到了，所謂交流的必要性。", "0", "0", "0", "0", "0", "cv_sk_Julius_her_44", "0", "0"},
[4106200152] = {4106200152, 11062001, 45, 37, "0", "0", "嗯。", "0", "0", "0", "0", "0", "cv_sk_Julius_her_45", "0", "0"},
[4104100100] = {4104100100, 11041001, 1, 1, "0", "0", "蒼霧殘響。", "0", "0", "0", "0", "0", "cv_zhinvxing_1", "0", "0"},
[4104100101] = {4104100101, 11041001, 2, 2, "0", "0", "正好我現在等調查結果，也沒什麼事可做，就應你邀請，來體驗一下多瑙駕駛員的日常工作吧。", "0", "0", "0", "0", "0", "cv_zhinvxing_2", "0", "0"},
[4104100102] = {4104100102, 11041001, 3, 3, "0", "0", "哦？你就是柯朗吹捧的那位領航？那麼重新自我介紹一下。代號織女星，隸屬於伊斯坎瓦亞，來自印加地區。", "0", "0", "0", "0", "0", "cv_zhinvxing_3", "0", "0"},
[4104100103] = {4104100103, 11041001, 91, 4, "0", "idle", "多瑙真是個好地方啊。最難能可貴的是，這裏非常有人情味。", "0", "0", "0", "0", "0", "cv_zhinvxing_4", "0", "idle,idle"},
[4104100104] = {4104100104, 11041001, 94, 4, "0", "idle2", "休息也是備戰的一環。你很懂嘛。", "0", "0", "0", "0", "0", "cv_zhinvxing_5", "0", "idle2,idle2"},
[4104100105] = {4104100105, 11041001, 98, 4, "0", "idle3", "嘿。如果覺得困了，就回房間睡覺，別在這裏硬撐。", "0", "0", "0", "0", "0", "cv_zhinvxing_6", "0", "idle3,idle3"},
[4104100106] = {4104100106, 11041001, 92, 5, "1_》_0_0.8", "touch1", "答應我，如果看到了可疑的、能裝下一個人的貨物箱，一定要在第一時間聯繫我。為了你的人身安全，絕對不要擅自打開。", "0", "0", "0", "0", "0", "cv_zhinvxing_7", "0", "touch1,touch1"},
[4104100107] = {4104100107, 11041001, 95, 5, "1_》_0_0.8", "touch2", "蘇亞娜？你想叫我本名是無妨，但不要在戰場上這樣稱呼。畢竟我們在這方面是有規章制度需要遵守的。", "0", "0", "0", "0", "0", "cv_zhinvxing_8", "0", "touch2,touch2"},
[4104100108] = {4104100108, 11041001, 106, 5, "1_》_0_0.8", "touch3", "當初會起“織女星”這個代號，只是為了借此警示自己，不要再輕信他人。至於現在嘛……如果可以，我想要將它還回去。可惜代號一經確定，就不允許修改了。", "0", "0", "0", "0", "0", "cv_zhinvxing_9", "0", "touch3,touch3"},
[4104100109] = {4104100109, 11041001, 107, 5, "1_》_0_0.8", "touch4", "我聽說你的那位情報官，其實是你妹妹。能得到家人的支持……真令人羡慕啊。", "0", "0", "0", "0", "0", "cv_zhinvxing_10", "0", "touch4,touch4"},
[4104100110] = {4104100110, 11041001, 93, 5, "1_》_0_0.8", "switch1", "現如今想想，如果那對夫婦能有你的一半好，我也不至於……欸，突然想到了個好主意。反正你與你的家人們都沒有血緣關係，那麼再加我一個也沒問題？別急著拒絕，你再考慮考慮？", "0", "0", "0", "0", "0", "cv_zhinvxing_11", "0", "switch1,switch1"},
[4104100111] = {4104100111, 11041001, 102, 5, "1_》_0_0.8", "switch2", "我這邊也會奉上誠意回報的。", "0", "0", "0", "0", "0", "cv_zhinvxing_12", "0", "switch2,switch2"},
[4104100112] = {4104100112, 11041001, 96, 5, "1_》_0_0.8", "switch3", "嘿。如果覺得困了，就回房間睡覺，別在這裏硬撐。", "0", "0", "0", "0", "0", "cv_zhinvxing_6", "0", "switch3,switch3"},
[4104100113] = {4104100113, 11041001, 12, 6, "0", "0", "我這邊也會奉上誠意回報的。", "0", "0", "0", "0", "0", "cv_zhinvxing_12", "0", "0"},
[4104100114] = {4104100114, 11041001, 13, 7, "0", "0", "居然會把難得的資源用在非嫡系的駕駛員身上……你還真是個怪人。", "0", "0", "0", "0", "0", "cv_zhinvxing_13", "0", "0"},
[4104100115] = {4104100115, 11041001, 14, 8, "0", "0", "到這份上，如果再不意思一下，就顯得我這人有些小氣了。所以來約定吧。等以後你來印加了，雖然沒法保證讓你橫著走，但只要是能幫上忙的，我都不會拒絕。", "0", "0", "0", "0", "0", "cv_zhinvxing_14", "0", "0"},
[4104100116] = {4104100116, 11041001, 15, 9, "0", "0", "設備升級？費用還是你來出？多瑙這邊的駕駛員待遇也太好了吧？！", "0", "0", "0", "0", "0", "cv_zhinvxing_15", "0", "0"},
[4104100117] = {4104100117, 11041001, 16, 10, "0", "0", "說吧，需要我幫忙爭取多少撤退時間？", "0", "0", "0", "0", "0", "cv_zhinvxing_16", "0", "0"},
[4104100118] = {4104100118, 11041001, 17, 11, "0", "0", "喲吼，大獲全勝？你這傢夥很行嘛。", "0", "0", "0", "0", "0", "cv_zhinvxing_17", "0", "0"},
[4104100119] = {4104100119, 11041001, 18, 12, "0", "0", "這點小傷不礙事。下一個戰場在哪裡？", "0", "0", "0", "0", "0", "cv_zhinvxing_18", "0", "0"},
[4104100120] = {4104100120, 11041001, 19, 13, "0", "0", "幸好你有先見之明，在開戰之前先通知其他隊伍疏散了群眾。", "0", "0", "0", "0", "0", "cv_zhinvxing_19", "0", "0"},
[4104100121] = {4104100121, 11041001, 20, 14, "0", "0", "你難道是想安慰我？哈哈，不需要，這種失敗我早就習慣了。", "0", "0", "0", "0", "0", "cv_zhinvxing_20", "0", "0"},
[4104100122] = {4104100122, 11041001, 21, 15, "0", "0", "呵，連我都打不過。", "0", "0", "0", "0", "0", "cv_zhinvxing_21", "0", "0"},
[4104100123] = {4104100123, 11041001, 23, 16, "0", "0", "由我來牽制他們。", "0", "0", "0", "0", "0", "cv_zhinvxing_23", "0", "0"},
[4104100124] = {4104100124, 11041001, 24, 17, "0", "0", "這就是你的決斷嗎？", "0", "0", "0", "0", "0", "cv_zhinvxing_24", "0", "0"},
[4104100125] = {4104100125, 11041001, 26, 19, "0", "0", "應該爭取到足夠的時間了……", "0", "0", "0", "0", "0", "cv_zhinvxing_26", "0", "0"},
[4104100126] = {4104100126, 11041001, 27, 20, "0", "0", "不管第幾次來，都接受不了啊……為什麼“維修池”會就在你的辦公室下麵？", "0", "0", "0", "0", "0", "cv_zhinvxing_27", "0", "0"},
[4104100127] = {4104100127, 11041001, 28, 21, "0", "0", "沒想到……巨大化之後還能像這樣躺在池子裡泡澡，真不可思議。", "0", "0", "0", "0", "0", "cv_zhinvxing_28", "0", "0"},
[4104100128] = {4104100128, 11041001, 29, 21, "0", "0", "……任何駕駛員都可以在這裡使用你的維修池嗎？為什麼說是你的維修池？因為這裡除了你和我外沒有別人了呀。", "0", "0", "0", "0", "0", "cv_zhinvxing_29", "0", "0"},
[4104100129] = {4104100129, 11041001, 30, 22, "0", "0", "動手吧。我已經準備好了。", "0", "0", "0", "0", "0", "cv_zhinvxing_30", "0", "0"},
[4104100130] = {4104100130, 11041001, 31, 23, "0", "0", "我聽說過這個環節。", "0", "0", "0", "0", "0", "cv_zhinvxing_31", "0", "0"},
[4104100131] = {4104100131, 11041001, 32, 24, "0", "0", "果然難不倒你。", "0", "0", "0", "0", "0", "cv_zhinvxing_32", "0", "0"},
[4104100132] = {4104100132, 11041001, 33, 25, "0", "0", "別介意，猜不出來也正常。誰讓我是外地人呢。", "0", "0", "0", "0", "0", "cv_zhinvxing_33", "0", "0"},
[4104100133] = {4104100133, 11041001, 34, 26, "0", "0", "喲，又見面了。今天你的眼神也很不錯，能看到一名戰士該有的堅韌。", "0", "0", "0", "0", "0", "cv_zhinvxing_34", "0", "0"},
[4104100134] = {4104100134, 11041001, 35, 27, "0", "0", "終於有機會見識一下你的特殊能力了。", "0", "0", "0", "0", "0", "cv_zhinvxing_35", "0", "0"},
[4104100135] = {4104100135, 11041001, 36, 28, "0", "0", "演習？也就是自己人跟自己人打？有點意思。", "0", "0", "0", "0", "0", "cv_zhinvxing_36", "0", "0"},
[4104100136] = {4104100136, 11041001, 37, 29, "0", "0", "能看出來，那些駕駛員都很仰慕你。", "0", "0", "0", "0", "0", "cv_zhinvxing_37", "0", "0"},
[4104100137] = {4104100137, 11041001, 38, 30, "0", "0", "在你眼中，駕駛員究竟是什麼？", "0", "0", "0", "0", "0", "cv_zhinvxing_38", "0", "0"},
[4104100138] = {4104100138, 11041001, 39, 31, "0", "0", "這些裝備都可以試用？", "0", "0", "0", "0", "0", "cv_zhinvxing_39", "0", "0"},
[4104100139] = {4104100139, 11041001, 40, 32, "0", "0", "不愧是艾吉斯，員工價的折扣就是大。", "0", "0", "0", "0", "0", "cv_zhinvxing_40", "0", "0"},
[4104100140] = {4104100140, 11041001, 41, 33, "0", "0", "獎章不少嘛你。", "0", "0", "0", "0", "0", "cv_zhinvxing_41", "0", "0"},
[4104100141] = {4104100141, 11041001, 42, 34, "0", "0", "這外掛程式的靜音效果不錯啊。", "0", "0", "0", "0", "0", "cv_zhinvxing_42", "0", "0"},
[4104100142] = {4104100142, 11041001, 43, 35, "0", "0", "又是公事？你可真是有夠忙的。", "0", "0", "0", "0", "0", "cv_zhinvxing_43", "0", "0"},
[4104100143] = {4104100143, 11041001, 44, 36, "0", "0", "匿名聊天啊……你最好小心一點，別透露自己的個人隱私。", "0", "0", "0", "0", "0", "cv_zhinvxing_44", "0", "0"},
[4104100144] = {4104100144, 11041001, 45, 37, "0", "0", "這是什麼高科技？", "0", "0", "0", "0", "0", "cv_zhinvxing_45", "0", "0"},
[4200800100] = {4200800100, 12008001, 1, 1, "0", "0", "蒼霧殘響。", "蒼霧殘響（ハツリバーブ）。", "0", "0", "蒼霧殘響。", "0", "cv_momo_33", "0", "0"},
[4200800101] = {4200800101, 12008001, 2, 2, "0", "0", "雖然我不是很喜歡站在這麼顯眼的位置……不過貌似茜茜她很喜歡，總之還是謝謝你了！", "こういう目立つ場所に立つのはあまり好きじゃないけど……まぁ、シシが好きそうだし。とにかくありがとう！", "0", "0", "雖然我不是很喜歡站在這麼顯眼的位置……不過貌似茜茜她很喜歡，總之還是謝謝你了！", "0", "cv_momo_2", "0", "0"},
[4200800102] = {4200800102, 12008001, 3, 3, "0", "0", "早上好！下午好！晚上好！我的名字是百里默默，百里茜茜，百里苑苑……總之叫我默默就好了！", "おはよう！こんにちは！こんばんは！私はバイリモモ、バイリシシ、バイリヨヨ……とにかく、モモって呼んでいい！", "0", "0", "早上好！下午好！晚上好！我的名字是百里默默，百里茜茜，百里苑苑……總之叫我默默就好了！", "0", "cv_momo_1", "0", "0"},
[4200800103] = {4200800103, 12008001, 91, 4, "0", "idle", "只要站在這裡就行了嗎？欸……好無聊，幸好有姐姐們陪我聊天。", "ここに立てばいいの？え……つまらないなぁ。お姉ちゃんたちがおしゃべりに付き合ってくれるからまだいいけど。", "0", "0", "只要站在這裡就行了嗎？誒……好無聊，幸好有姐姐們陪我聊天。", "0", "cv_momo_3", "0", "idle,idle"},
[4200800104] = {4200800104, 12008001, 91, 4, "0", "idle", "苑苑姐說，這樣待著就像是在罰站一樣。說起來，領航以前有被罰站的經驗嗎？", "ここにいるのって罰として立たされてるみたいだってヨヨお姉ちゃんが言ってたの。そういえば、ナビゲーターは立たされたことがある？", "0", "0", "苑苑姐說，這樣待著就像是在罰站一樣。說起來，領航以前有被罰站的經驗嗎？", "0", "cv_momo_4", "0", "idle,idle"},
[4200800105] = {4200800105, 12008001, 91, 4, "0", "idle", "從海姬身上，默默感受到了與自己相同的氣息……為什麼會這樣呢……", "海姫から感じる気配はモモのと同じなの……なんでだろう……", "0", "0", "從海姬身上，默默感受到了與自己相同的氣息……為什麼會這樣呢……", "0", "cv_momo_30", "0", "idle,idle"},
[4200800106] = {4200800106, 12008001, 92, 5, "15_1_0_0.8", "touch1", "默默是大海的孩子，所以，戰爭結束之後，默默會回到海裏和姐姐們在一起喔。不過，那樣的話媽媽會很傷心的，所以默默也在困擾該怎麼辦……嗚。", "モモは海の子なの。だから、戦爭が終わったら、モモは海の中に戻るの。お姉ちゃんたちと一緒に。でも、そうするとお母さんが悲しんじゃう……だから、モモもどうすればいいか分からなくて困ってるの……う……", "0", "0", "默默是大海的孩子，所以，戰爭結束之後，默默會回到海裡和姐姐們在一起哦。不過，那樣的話媽媽會很傷心的，所以默默也在困擾該怎麼辦……嗚。", "0", "cv_momo_31", "0", "touch1,touch1"},
[4200800107] = {4200800107, 12008001, 92, 5, "15_1_0_0.8", "touch1", "默默的姐姐在哪裡？默默的姐姐們就是默默喔！嗯？不明白嗎？", "モモのお姉ちゃんはどこかって？モモのお姉ちゃんたちはモモだよ！ん？分からないの？", "0", "0", "默默的姐姐在哪裡？默默的姐姐們就是默默噢！嗯？不明白嗎？", "0", "cv_momo_5", "0", "touch1,touch1"},
[4200800108] = {4200800108, 12008001, 92, 5, "15_2_0_0.8", "touch2", "事先說好，千萬不要摸我的腦袋，這麼做會讓默默聽不見姐姐們的聲音的！", "言っとくけど、私の頭を觸らないでよ。觸られたらお姉ちゃんの聲が聞こえなくなっちゃうから！", "0", "0", "事先說好，千萬不要摸我的腦袋，這麼做會讓默默聽不見姐姐們的聲音的！", "0", "cv_momo_6", "0", "touch2,touch2"},
[4200800109] = {4200800109, 12008001, 92, 5, "15_2_0_0.8", "touch2", "啊……只是摸一下的話，就隨便你了。我們也都快習慣了。", "あっ…...ちょっとだけ觸るって言うのなら別に止めないけど。私たちももう慣れっこだし。", "0", "0", "啊……只是摸一下的話，就隨便你了。我們也都快習慣了。", "0", "cv_momo_7", "0", "touch2,touch2"},
[4200800110] = {4200800110, 12008001, 92, 5, "15_2_0_0.8", "touch2", "姐姐們說……領航你是可以信任的人。雖然不想承認，但默默從領航身上，感覺到了和姐姐們不同的情感……什麼情感？領航你是不可能明白的。", "ナビゲーターは信頼できる人だってお姉ちゃんたちが言ってたの。認めたくないけど…...モモ、ナビゲーターには、お姉ちゃんたちと違う気持ちを感じるの……何の気持ちかって？ナビゲーターに分かるはずないの。", "0", "0", "姐姐們說……領航你是可以信任的人。雖然不想承認，但默默從領航身上，感覺到了和姐姐們不同的情感……什麼情感？領航你是不可能明白的。", "0", "cv_momo_8", "0", "touch2,touch2"},
[4200800111] = {4200800111, 12008001, 12, 6, "0", "0", "好！默默變強了！", "よし！モモ、強くなったの！", "0", "0", "好！默默變強了！", "0", "cv_momo_9", "0", "0"},
[4200800112] = {4200800112, 12008001, 13, 7, "0", "0", "默默能感受到與姐姐的聯繫更深了。", "モモ、お姉ちゃんたちと絆が深まった気がする。", "0", "0", "默默能感受到與姐姐的聯繫更深了。", "0", "cv_momo_10", "0", "0"},
[4200800113] = {4200800113, 12008001, 14, 8, "0", "0", "果然，就像姐姐們說的一樣，默默可以變得很厲害。接下來，默默會擁有更強的力量，拭目以待吧！", "やっぱり、お姉ちゃんたちの言う通りだ。モモ、強くなれる。これからももっと強くなるから、楽しみにしてて！", "0", "0", "果然，就像姐姐們說的一樣，默默可以變得很厲害。接下來，默默會擁有更強的力量，拭目以待吧！", "0", "cv_momo_11", "0", "0"},
[4200800114] = {4200800114, 12008001, 15, 9, "0", "0", "與姐姐靈魂的共鳴，讓默默變得更加強大！", "お姉ちゃんの魂と共鳴して、モモはもっと強くなる！", "0", "0", "與姐姐靈魂的共鳴，讓默默變得更加強大！", "0", "cv_momo_12", "0", "0"},
[4200800115] = {4200800115, 12008001, 16, 10, "0", "0", "默默，登場！", "モモ、參上！", "0", "0", "默默，登場！", "0", "cv_momo_13", "0", "0"},
[4200800116] = {4200800116, 12008001, 17, 11, "0", "0", "只要按照默默和姐姐想的那樣發展，勝利是必然的。", "モモとお姉ちゃんの予想通りに進めば、勝利は確実なの！", "0", "0", "只要按照默默和姐姐想的那樣發展，勝利是必然的。", "0", "cv_momo_14", "0", "0"},
[4200800117] = {4200800117, 12008001, 18, 12, "0", "0", "嗯嗯，雖然不完美，但只要結果好就行了！", "ふむふむ、完璧じゃないけど、結果がよければそれでいい！", "0", "0", "嗯嗯，雖然不完美，但只要結果好就行了！", "0", "cv_momo_15", "0", "0"},
[4200800118] = {4200800118, 12008001, 19, 13, "0", "0", "嗚，默默被姐姐罵了，才不是默默的錯呢！", "う……！モモ、お姉ちゃんに怒られちゃった。モモのせいじゃないのに！", "0", "0", "嗚，默默被姐姐罵了，才不是默默的錯呢！", "0", "cv_momo_16", "0", "0"},
[4200800119] = {4200800119, 12008001, 20, 14, "0", "0", "就像默默預計的那樣——快撤離啦！", "モモの予想通りだね――早く撤退しよう！", "0", "0", "就像默默預計的那樣——快撤離啦！", "0", "cv_momo_17", "0", "0"},
[4200800120] = {4200800120, 12008001, 21, 15, "0", "0", "看到了嗎，這就是默默的力量！", "今の見た？これがモモの力なの！", "0", "0", "看到了嗎，這就是默默的力量！", "0", "cv_momo_18", "0", "0"},
[4200800121] = {4200800121, 12008001, 23, 16, "0", "0", "嗯，像大海一樣發起攻擊！", "うん、海のように攻撃をしかける！", "0", "0", "嗯，像大海一樣發起攻擊！", "0", "cv_momo_20", "0", "0"},
[4200800122] = {4200800122, 12008001, 24, 17, "0", "0", "大海……", "海……", "0", "0", "大海……", "0", "cv_momo_22", "0", "0"},
[4200800123] = {4200800123, 12008001, 22, 38, "0", "0", "默默，正在蓄力中！", "モモ、力を溜めてるよ！", "0", "0", "默默，正在蓄力中！", "0", "cv_momo_19", "0", "0"},
[4200800124] = {4200800124, 12008001, 26, 19, "0", "0", "默默才不會這樣認輸呢！", "モモ、絶対に負けない！", "0", "0", "默默才不會這樣認輸呢！", "0", "cv_momo_21", "0", "0"},
[4200800125] = {4200800125, 12008001, 27, 20, "0", "0", "準備好水下作戰！欸？不是？只是洗澡而已嗎？", "水中作戦の準備！え？違うの？ただのお風呂？", "0", "0", "準備好水下作戰！誒？不是？只是洗澡而已嗎？", "0", "cv_momo_23", "0", "0"},
[4200800126] = {4200800126, 12008001, 28, 21, "0", "0", "姐姐很喜歡泡澡喔……我？我也很喜歡！", "お姉ちゃんはお風呂が大好きなの……私？私も大好きだよ！", "0", "0", "姐姐很喜歡泡澡哦……我？我也很喜歡！", "0", "cv_momo_24", "0", "0"},
[4200800127] = {4200800127, 12008001, 29, 21, "0", "0", "要泡到什麼時候呀……我都快睡著了。", "このお風呂はいつまで入れば良いの……？もう眠くなってきちゃった。", "0", "0", "要泡到什麼時候呀……我都快睡著了。", "0", "cv_momo_25", "0", "0"},
[4200800128] = {4200800128, 12008001, 30, 22, "0", "0", "欸！難道中獎了嗎！？", "え？當たったの！？", "0", "0", "誒！難道中獎了嗎！？", "0", "cv_momo_26", "0", "0"},
[4200800129] = {4200800129, 12008001, 31, 23, "0", "0", "猜錯的話就要吞一千根針！", "外れたら針千本飲んでもらうからね！", "0", "0", "猜錯的話就要吞一千根針！", "0", "cv_momo_27", "0", "0"},
[4200800130] = {4200800130, 12008001, 32, 24, "0", "0", "原來如此……領航和默默的聯繫也在變深嗎？", "なるほど……ナビゲーターとモモの間にある絆も深まってるの？", "0", "0", "原來如此……領航和默默的聯繫也在變深嗎？", "0", "cv_momo_28", "0", "0"},
[4200800131] = {4200800131, 12008001, 33, 25, "0", "0", "領航果然還是不能像默默的姐姐一樣啊……張嘴！", "やっぱり、ナビゲーターはモモのお姉ちゃんみたいになってくれないんだ……わーん！", "0", "0", "領航果然還是不能像默默的姐姐一樣啊……張嘴！", "0", "cv_momo_29", "0", "0"},
[4200800132] = {4200800132, 12008001, 34, 26, "0", "0", "領航，請小聲點，默默正在和姐姐們聊天呢。", "ナビゲーター、もう少し靜かにしてくれる？モモ、お姉ちゃんたちとおしゃべりしてるの。", "0", "0", "領航，請小聲點，默默正在和姐姐們聊天呢。", "0", "cv_momo_32", "0", "0"},
[4200800133] = {4200800133, 12008001, 35, 27, "0", "0", "海洋與蒼霧都是默默的戰場。", "海もハツも、モモの戦場なの。", "0", "0", "海洋與蒼霧都是默默的戰場。", "0", "cv_momo_34", "0", "0"},
[4200800134] = {4200800134, 12008001, 36, 28, "0", "0", "通過挑戰來變強吧。", "挑戦で強くなろう。", "0", "0", "通過挑戰來變強吧。", "0", "cv_momo_35", "0", "0"},
[4200800135] = {4200800135, 12008001, 37, 29, "0", "0", "默默想換一個大點的宿舍！", "モモ、もう少し大きな宿舎がいい！", "0", "0", "默默想換一個大點的宿舍！", "0", "cv_momo_36", "0", "0"},
[4200800136] = {4200800136, 12008001, 38, 30, "0", "0", "默默有預感會遇到厲害的人！", "モモ、淒い人に出會えそうな予感がするの！", "0", "0", "默默有預感會遇到厲害的人！", "0", "cv_momo_37", "0", "0"},
[4200800137] = {4200800137, 12008001, 39, 31, "0", "0", "默默想要可愛一點的武器！", "モモ、可愛い武器が欲しいの！", "0", "0", "默默想要可愛一點的武器！", "0", "cv_momo_38", "0", "0"},
[4200800138] = {4200800138, 12008001, 40, 32, "0", "0", "請買五份，默默不是一個人！", "五人分で！モモ、一人じゃないんだから！", "0", "0", "請買五份，默默不是一個人！", "0", "cv_momo_39", "0", "0"},
[4200800139] = {4200800139, 12008001, 41, 33, "0", "0", "領航好臭美~", "ナビゲーターのナルシストー！", "0", "0", "領航好臭美~", "0", "cv_momo_40", "0", "0"},
[4200800140] = {4200800140, 12008001, 42, 34, "0", "0", "姐姐說過，細節決定勝負~", "細部が勝敗を決めるってお姉ちゃんが言ってたの。", "0", "0", "姐姐說過，細節決定勝負~", "0", "cv_momo_41", "0", "0"},
[4200800141] = {4200800141, 12008001, 43, 35, "0", "0", "不看信箱的話，寄信人會難過的！", "受信箱を見ないと、出した人が悲しんじゃうよ！", "0", "0", "不看郵箱的話，寄信人會難過的！", "0", "cv_momo_42", "0", "0"},
[4200800142] = {4200800142, 12008001, 44, 36, "0", "0", "難道說，領航也和默默一樣嗎！？", "ひょっとして、ナビゲーターもモモと一緒なの？！", "0", "0", "難道說，領航也和默默一樣嗎！？", "0", "cv_momo_43", "0", "0"},
[4200800143] = {4200800143, 12008001, 45, 37, "0", "0", "原來這裡還有按鈕啊！", "ここにもボタンがあったんだ！", "0", "0", "原來這裡還有按鈕啊！", "0", "cv_momo_44", "0", "0"},
[432800] = {432800, 13028, 1, 1, "0", "0", "蒼霧殘響", "0", "0", "0", "0", "0", "cv_choco_01", "0", "0"},
[432801] = {432801, 13028, 2, 2, "0", "0", "甜心巧可屋，巧可为您服务~", "0", "0", "0", "0", "0", "cv_choco_02", "0", "0"},
[432802] = {432802, 13028, 3, 3, "0", "0", "啊~是提拉米蘇先生~要不要到我的店裏坐一坐？", "0", "0", "0", "0", "0", "cv_choco_03", "0", "0"},
[432803] = {432803, 13028, 4, 4, "0", "idle", "這個世界上有沒有吃了之後不會蛀牙……甚至對牙齒有益的糖果呢……", "0", "0", "0", "0", "0", "cv_choco_04", "0", "0"},
[432804] = {432804, 13028, 5, 4, "0", "idle2", "鏘鏘~這是能緩解肩部僵硬的糖果，提拉米蘇先生吃下之後乖乖坐好，我要開始給你捶背了。", "0", "0", "0", "0", "0", "cv_choco_05", "0", "0"},
[432805] = {432805, 13028, 6, 4, "0", "idle3", "其實我還有緩解腰部僵硬的餅乾，不過在變得這麼大的情況下我要是踩到提拉米蘇先生背上……提拉米蘇先生就要變成提拉米蘇餅乾了……", "0", "0", "0", "0", "0", "cv_choco_06", "0", "0"},
[432806] = {432806, 13028, 7, 5, "1_》_0_0.8", "level1", "販賣甜蜜，收藏快樂~甜心巧克屋，任何時候都能得到甜頭！這可是我想了很久的廣告詞~以後一定要拍成廣告視頻放到電視上去~", "0", "0", "0", "0", "0", "cv_choco_07", "0", "0"},
[432807] = {432807, 13028, 8, 5, "1_》_0_0.8", "level2", "爺爺說過，只有不斷地一直吃、吃、吃、吃下去才能不斷地找到好零食呢。", "0", "0", "0", "0", "0", "cv_choco_08", "0", "0"},
[432808] = {432808, 13028, 9, 5, "1_》_100_1.5", "level3", "如果能把零食當飯吃就好了……兩年的聖誕節我向聖誕老爺爺許下了這個願望，不知道爲什麼從那以後聖誕老爺爺就沒來過了。", "0", "0", "0", "0", "0", "cv_choco_09", "0", "0"},
[432809] = {432809, 13028, 10, 5, "1_》_500_2", "level4", "得在零食過期之前把大家賣出去才行，讓人們臉上誕生笑容的零食就這樣被遺棄了多可憐啊……啊，免費送給大家吃不就好了……！", "0", "0", "0", "0", "0", "cv_choco_10", "0", "0"},
[432810] = {432810, 13028, 11, 5, "1_》_1000_2.5", "level5", "我打算在領到第一筆薪水的時候給店裏加上能存放冰淇淋的櫃子，提拉米蘇先生覺得這個主意怎麼樣？天才的想法？嘿嘿，提拉米蘇先生果然也很懂。", "0", "0", "0", "0", "0", "cv_choco_11", "0", "0"},
[432811] = {432811, 13028, 12, 6, "0", "0", "作爲駕駛員我還什麼都不知道，所以教教我吧提拉米蘇先生。", "0", "0", "0", "0", "0", "cv_choco_12", "0", "0"},
[432812] = {432812, 13028, 13, 7, "0", "0", "多吃一點才能快快長大。", "0", "0", "0", "0", "0", "cv_choco_13", "0", "0"},
[432813] = {432813, 13028, 14, 8, "0", "0", "聽我說聽我說~提拉米蘇先生~我吃到了好~甜~的糖果，怎麼會有這麼甜的糖果，我的牙齒都要“叭噶”一聲掉到地上了，要融化了，大事不妙了。", "0", "0", "0", "0", "0", "cv_choco_14", "0", "0"},
[432814] = {432814, 13028, 15, 9, "0", "0", "謝謝提拉米蘇先生！", "0", "0", "0", "0", "0", "cv_choco_15", "0", "0"},
[432815] = {432815, 13028, 16, 10, "0", "0", "要做什麼？", "0", "0", "0", "0", "0", "cv_choco_16", "0", "0"},
[432816] = {432816, 13028, 17, 11, "0", "0", "yes！成功打烊了~", "0", "0", "0", "0", "0", "cv_choco_17", "0", "0"},
[432817] = {432817, 13028, 18, 12, "0", "0", "嗯……進貨單……放在哪裏了……", "0", "0", "0", "0", "0", "cv_choco_18", "0", "0"},
[432818] = {432818, 13028, 19, 13, "0", "0", "爲什麼黑巧克力這麼受歡迎！？", "0", "0", "0", "0", "0", "cv_choco_19", "0", "0"},
[432819] = {432819, 13028, 20, 14, "0", "0", "糟、糟糕……忘記收錢了……", "0", "0", "0", "0", "0", "cv_choco_20", "0", "0"},
[432820] = {432820, 13028, 21, 15, "0", "0", "我絕不承認100%黑巧克力是零食！", "0", "0", "0", "0", "0", "cv_choco_21", "0", "0"},
[432821] = {432821, 13028, 23, 16, "0", "0", "大壞蛋，打你。", "0", "0", "0", "0", "0", "cv_choco_23", "0", "0"},
