[4302800101] = {4302800101, 13028001, 2, 2, "0", "0", "甜心巧可屋，巧可爲您服務~", "0", "0", "0", "0", "0", "cv_sk_choco_02", "0", "0"},
[4302800102] = {4302800102, 13028001, 3, 3, "0", "0", "啊~是提拉米蘇先生~要不要到我的店裏坐一坐？", "0", "0", "0", "0", "0", "cv_sk_choco_03", "0", "0"},
[4302800103] = {4302800103, 13028001, 91, 4, "0", "idle", "這就是當新娘子的感覺啊……謝謝你帶我來這裏，提拉米蘇先生。", "0", "0", "0", "0", "0", "cv_sk_choco_n02", "0", "idle,idle"},
[4302800104] = {4302800104, 13028001, 91, 4, "0", "idle", "以前和爺爺一起出去的時候，有在街上看到過穿着白白婚紗的大姐姐，圍繞在大姐姐身邊的人都笑得很開心，真好啊，嘿嘿。", "0", "0", "0", "0", "0", "cv_sk_choco_n03", "0", "idle,idle"},
[4302800105] = {4302800105, 13028001, 94, 4, "0", "idle2", "頭髮被太陽公公曬了之後，香香的味道就飄出來了……嗅嗅……好像能聞到陽光的味道。", "0", "0", "0", "0", "0", "cv_sk_choco_n08", "0", "idle2,idle2"},
[4302800106] = {4302800106, 13028001, 94, 4, "0", "idle2", "提拉米蘇先生，下次巧可再給你當看板娘吧~我從小就在當看板娘了。", "0", "0", "0", "0", "0", "cv_sk_choco_n09", "0", "idle2,idle2"},
[4302800107] = {4302800107, 13028001, 98, 4, "0", "idle3", "被淋溼了啊……我還是第一次見到自動降雨的裝置……好神奇……", "0", "0", "0", "0", "0", "cv_sk_choco_n14", "0", "idle3,idle3"},
[4302800108] = {4302800108, 13028001, 98, 4, "0", "idle3", "曬乾了再回去吧，今天就不洗澡了可以嗎？", "0", "0", "0", "0", "0", "cv_sk_choco_n15", "0", "idle3,idle3"},
[4302800109] = {4302800109, 13028001, 92, 5, "1_》_0_0.8", "tocuh1", "嗷嗚~我是楓糖漿熱鬆餅老虎，要來吃掉提拉米蘇先生了。", "0", "0", "0", "0", "0", "cv_sk_choco_n04", "0", "tocuh1,touch1"},
[4302800110] = {4302800110, 13028001, 92, 5, "1_》_0_0.8", "tocuh1", "……就我們兩個跑出來玩了……這是可以的嗎？畢竟不勞者不獲麼……\n大人的世界是可以偷懶的？真是深奧呢……", "0", "0", "0", "0", "0", "cv_sk_choco_n05", "0", "tocuh1,touch1"},
[4302800111] = {4302800111, 13028001, 95, 5, "1_》_0_0.8", "tocuh2", "提拉米蘇先生真是好人呢……讓我穿漂漂亮亮的衣服還會讓我開心……以後能成爲提拉米蘇先生新娘子的女孩子，一定會像吃了超級~甜的糖果一樣幸福吧。", "0", "0", "0", "0", "0", "cv_sk_choco_n06", "0", "tocuh2,touch2"},
[4302800112] = {4302800112, 13028001, 95, 5, "1_》_0_0.8", "tocuh2", "提拉米蘇先生還準備了戒指呀，爲了這次的練習準備得這麼充分是準備以後要向哪位大姐姐求婚嗎？", "0", "0", "0", "0", "0", "cv_sk_choco_n10", "0", "tocuh2,touch2"},
[4302800113] = {4302800113, 13028001, 106, 5, "1_》_0_0.8", "tocuh3", "要給我戴上戒指？嗯……還是不要了吧，提拉米蘇先生不是要給自己最喜歡的人戴上戒指嗎？雖然是練習結婚，不過戴戒指這種事還是留給新娘子吧。", "0", "0", "0", "0", "0", "cv_sk_choco_n11", "0", "tocuh3,touch3"},
[4302800114] = {4302800114, 13028001, 106, 5, "1_》_0_0.8", "tocuh3", "好開心啊~不過也不能天天都這樣跑出來哦~還有很多人很多人在等着零食屋的開張呢~", "0", "0", "0", "0", "0", "cv_sk_choco_n12", "0", "tocuh3,touch3"},
[4302800115] = {4302800115, 13028001, 107, 5, "1_》_0_0.8", "tocuh4", "回、回去以後要洗澡了？不、不要……", "0", "0", "0", "0", "0", "cv_sk_choco_n16", "0", "tocuh4,touch4"},
[4302800116] = {4302800116, 13028001, 107, 5, "1_》_0_0.8", "tocuh4", "我想要睡一會，提拉米蘇先生要不要一起，我們去找個好一點的地方吧，能讓我們兩個都躺下來的地方……", "0", "0", "0", "0", "0", "cv_sk_choco_n17", "0", "tocuh4,touch4"},
[4302800117] = {4302800117, 13028001, 107, 5, "1_》_0_0.8", "tocuh4", "戒指上的寶石閃閃發光呢……誒？這是糖果做的……？哈哈這麼好看的戒指我可捨不得吃掉，我喜歡這個戒指。", "0", "0", "0", "0", "0", "cv_sk_choco_n18", "0", "tocuh4,touch4"},
[4302800118] = {4302800118, 13028001, 93, 5, "1_》_0_0.8", "switch1", "提拉米蘇先生，花花送給你。", "0", "0", "0", "0", "0", "cv_sk_choco_n01", "0", "switch1,switch1"},
