[4302800121] = {4302800121, 13028001, 12, 6, "0", "0", "作爲駕駛員我還什麼都不知道，所以教教我吧提拉米蘇先生。", "0", "0", "0", "0", "0", "cv_sk_choco_12", "0", "0"},
