[4300500200] = {4300500200, 13005002, 1, 1, "0", "0", "蒼霧殘響", "0", "0", "0", "0", "0", "cv_sk_genia_32", "0", "0"},
[4300500201] = {4300500201, 13005002, 2, 2, "0", "0", "明白了，我會站在這裏監督您的工作的。", "0", "0", "0", "0", "0", "cv_sk_genia_2", "0", "0"},
[4300500202] = {4300500202, 13005002, 3, 3, "0", "0", "熱尼亞·李·扎伊採夫，擔任的職位是醫療官，治療的工作就交給我吧。", "0", "0", "0", "0", "0", "cv_sk_genia_1", "0", "0"},
[4300500203] = {4300500203, 13005002, 91, 4, "0", "idle", "莉迪亞…是的，我的確救過她的性命，但那次“奇蹟”並不是因爲我一個人而發生的。她那強烈到令人目眩，感到不可思議的求生意志纔是關鍵。", "0", "0", "0", "0", "0", "cv_sk_genia_29", "0", "idle,idle"},
[4300500204] = {4300500204, 13005002, 94, 4, "0", "idle2", "您問我累不累…和以前的工作比起來，站在這裏已經是一種休息了。", "0", "0", "0", "0", "0", "cv_sk_genia_3", "0", "idle2,idle2"},
[4300500205] = {4300500205, 13005002, 98, 4, "0", "idle3", "呼…呼…啊，抱歉，因爲太放鬆了，不小心睡著了，失禮了。", "0", "0", "0", "0", "0", "cv_sk_genia_4", "0", "idle3,idle3"},
[4300500206] = {4300500206, 13005002, 92, 5, "1_》_0_0.8", "touch1", "如果不是奶奶的事…我大概不會想要去成爲一名醫生吧。而之所以能夠一直堅持下來，大概是因爲我不希望有人在自己眼前死去吧……", "0", "0", "0", "0", "0", "cv_sk_genia_30", "0", "touch1,touch1"},
[4300500207] = {4300500207, 13005002, 95, 5, "1_》_0_0.8", "touch2", "怎麼了？需要我給您的腕管做切開手術嗎？", "0", "0", "0", "0", "0", "cv_sk_genia_5", "0", "touch2,touch2"},
[4300500208] = {4300500208, 13005002, 106, 5, "1_》_0_0.8", "touch3", "不僅是確保您的生命安全，任何人的生命，我都有責任去守護。這就是醫生的職責。", "0", "0", "0", "0", "0", "cv_sk_genia_6", "0", "touch3,touch3"},
[4300500209] = {4300500209, 13005002, 107, 5, "1_》_0_0.8", "touch4", "沒有人能逃過死亡的命運。但——我希望，像您這樣的人，能迎來安詳的，幸福的死。", "0", "0", "0", "0", "0", "cv_sk_genia_7", "0", "touch4,touch4"},
[4300500210] = {4300500210, 13005002, 93, 5, "1_》_0_0.8", "switch1", "生命的奇蹟與凋零，我見證得足夠多了。今後，我也會一直以醫生的身份去戰鬥。領航，能與我同行嗎？", "0", "0", "0", "0", "0", "cv_sk_genia_8", "0", "switch1,switch1"},
[4300500211] = {4300500211, 13005002, 102, 5, "1_》_0_0.8", "switch2", "嗯，治療的效率提高了。", "0", "0", "0", "0", "0", "cv_sk_genia_9", "0", "switch2,switch2"},
[4300500212] = {4300500212, 13005002, 96, 5, "1_》_0_0.8", "switch3", "嗯？還有這種提升手段嗎？", "0", "0", "0", "0", "0", "cv_sk_genia_10", "0", "switch3,switch3"},
[4300500213] = {4300500213, 13005002, 14, 6, "0", "0", "嗯，治療的效率提高了。", "0", "0", "0", "0", "0", "cv_sk_genia_9", "0", "0"},
[4300500214] = {4300500214, 13005002, 15, 7, "0", "0", "嗯？還有這種提升手段嗎？", "0", "0", "0", "0", "0", "cv_sk_genia_10", "0", "0"},
[4300500215] = {4300500215, 13005002, 16, 8, "0", "0", "那些爲了結束戰爭而在拼命的戰士，需要人去保護他們。謝謝您，領航，給了我這份力量，我會把它用在正確的地方的。", "0", "0", "0", "0", "0", "cv_sk_genia_11", "0", "0"},
[4300500216] = {4300500216, 13005002, 17, 9, "0", "0", "醫療技術還在進步啊。", "0", "0", "0", "0", "0", "cv_sk_genia_12", "0", "0"},
[4300500217] = {4300500217, 13005002, 18, 10, "0", "0", "我來了，請各位放心戰鬥吧。", "0", "0", "0", "0", "0", "cv_sk_genia_13", "0", "0"},
[4300500218] = {4300500218, 13005002, 19, 11, "0", "0", "完美勝利？這不意味著沒有傷患，讓傷患過來接受治療。", "0", "0", "0", "0", "0", "cv_sk_genia_14", "0", "0"},
[4300500219] = {4300500219, 13005002, 20, 12, "0", "0", "負傷者，過來。", "0", "0", "0", "0", "0", "cv_sk_genia_15", "0", "0"},
[4300500220] = {4300500220, 13005002, 21, 13, "0", "0", "別沮喪了，先轉移傷患。", "0", "0", "0", "0", "0", "cv_sk_genia_16", "0", "0"},
[4300500221] = {4300500221, 13005002, 22, 14, "0", "0", "撤退！不要落下任何一個傷患！", "0", "0", "0", "0", "0", "cv_sk_genia_17", "0", "0"},
[4300500222] = {4300500222, 13005002, 23, 15, "0", "0", "可能會有點痛。", "0", "0", "0", "0", "0", "cv_sk_genia_18", "0", "0"},
