[4201000101] = {4201000101, 12010001, 1, 1, "0", "0", "蒼霧殘響！", "蒼霧殘響（ハツリバーブ）!", "0", "0", "蒼霧殘響！", "0", "cv_meika_32", "0", "0"},
[4201000102] = {4201000102, 12010001, 2, 2, "0", "0", "我知道啦，站在這裏就行了吧，你這人真的很麻煩啊。", "わぁったよ。ここに立ってりゃいいんだろう。しつけぇ奴だな。", "0", "0", "我知道啦，站在這裡就行了吧，你這人真的很麻煩啊。", "0", "cv_meika_2", "0", "0"},
[4201000103] = {4201000103, 12010001, 3, 3, "0", "0", "你就是領航啊——老孃的名字是冥火，不要把我和“另一個我”弄混了，我纔是冥火！", "てめーがナビゲーターか。俺は冥火。もうひとりのあたしと間違えんなよ。俺こそが冥火だ！", "0", "0", "你就是領航啊——老娘的名字是冥火，不要把我和“另一個我”弄混了，我才是冥火！", "0", "cv_meika_1", "0", "0"},
[4201000104] = {4201000104, 12010001, 91, 4, "0", "idle", "鮮血、毀滅，這纔是我想追求的！喂，領航，快點給我下達作戰任務！", "俺が欲しいのは血と破滅だ！おいナビゲーター、さっさと任務をよこせ！", "0", "0", "鮮血、毀滅，這才是我想追求的！喂，領航，快點給我下達作戰任務！", "0", "cv_meika_3", "0", "idle,idle"},
[4201000105] = {4201000105, 12010001, 94, 4, "0", "idle2", "真無聊，你打算一直待在辦公室裏嗎？我們出去大幹一場吧！", "つまんねえなぁ。ずっとここにいるつもりか？外で暴れさせてくれよ！", "0", "0", "真無聊，你打算一直待在辦公室裡嗎？我們出去大幹一場吧！", "0", "cv_meika_4", "0", "idle2,idle2"},
[4201000106] = {4201000106, 12010001, 98, 4, "0", "idle3", "我討厭“她”，因爲她總是忍讓。她明明可以不被人欺負，明明可以讓我消失……但她沒這麼做……我，“冥火”也是因爲她的忍耐…善良才“誕生”的。", "俺は、我慢ばかりしてやがる「あたし」が嫌いだ。俺を消せるのに、もういじめられないで済むのに……そうしなかった。俺は……冥火は、「あたし」の我慢と、優しさから生まれたんだ。", "0", "0", "我討厭“她”，因為她總是忍讓。她明明可以不被人欺負，明明可以讓我消失……但她沒這麼做……我，“冥火”也是因為她的忍耐…善良才“誕生”的。", "0", "cv_meika_29", "0", "idle3,idle3"},
[4201000107] = {4201000107, 12010001, 92, 5, "1_》_0_0.8", "touch1", "爸爸和媽媽…他們希望“我”恢復正常，想要讓我…“冥火”消失。所以才把我送到了艾吉斯。如果這就是他們希望的事，那也…纔怪咧，老孃纔不想消失！", "オヤジとオフクロは、正気の「あたし」に戻って欲しいのさ。俺に……冥火に消えてほしくて、アイギスに送ったんだ。もし、オヤジたちがそう望むなら、それでいい……わけねぇだろう！俺は消えたくねぇんだよ！", "0", "0", "爸爸和媽媽…他們希望“我”恢復正常，想要讓我…“冥火”消失。所以才把我送到了艾吉斯。如果這就是他們希望的事，那也…才怪咧，老娘才不想消失！", "0", "cv_meika_30", "0", "touch1,touch1"},
[4201000108] = {4201000108, 12010001, 95, 5, "1_》_0_0.8", "touch2", "…喂，不要隨便碰我，咬斷你手指喔！", "……おい、勝手に觸んじゃねぇ。てめーの指噛み切るぞ！", "0", "0", "…喂，不要隨便碰我，咬斷你手指噢！", "0", "cv_meika_5", "0", "touch2,touch2"},
[4201000109] = {4201000109, 12010001, 106, 5, "1_》_0_0.8", "touch3", "爲什麼不遮住自己的臉？哼哼，根本沒有那個必要。反正，那個“我”不是“現在的我”，就算見面了你們應該也認不出來吧。", "なんで顔を隠さないのかって？フン、その必要なんざねぇよ。どうせあの「あたし」は俺じゃねえし。てめーが會っても分かんねぇだろ。", "0", "0", "為什麼不遮住自己的臉？哼哼，根本沒有那個必要。反正，那個“我”不是“現在的我”，就算見面了你們應該也認不出來吧。", "0", "cv_meika_6", "0", "touch3,touch3"},
[4201000110] = {4201000110, 12010001, 107, 5, "1_》_0_0.8", "touch4", "…啊…領航，您好。這段時間，真的十分感謝您的關照。有您在的話，“冥火”就不會胡鬧過頭了，那我就能安心了。您…知道我是誰吧？", "……あっ……こんにちは、ナビゲーターさん。この間は本當にお世話になりました。あなたがいれば、冥火は羽目を外し過ぎることがないから、安心です。あの……あたしのこと……ご存知ですか？", "0", "0", "…啊…領航，您好。這段時間，真的十分感謝您的關照。有您在的話，“冥火”就不會胡鬧過頭了，那我就能安心了。您…知道我是誰吧？", "0", "cv_meika_7", "0", "touch4,touch4"},
[4201000111] = {4201000111, 12010001, 93, 5, "1_》_0_0.8", "switch1", "我大概，遲早有一天會消失吧。他們都說我是異常的存在，爸爸、媽媽也是這麼認爲的……說“另一個我”纔是真正的我。所以，在我消失之前，領航，和我一起大鬧特鬧吧，好嗎！", "俺はいつか消えちまう。他のヤツから見たら、俺の方がおかしく見えるんだろうよ。「もうひとりのあたし」こそが本物だってな。オヤジやオフクロもそう思ってる……。だから、俺が消えちまう前に一緒に大暴れしようぜ！ナビゲーター！", "0", "0", "我大概，遲早有一天會消失吧。他們都說我是異常的存在，爸爸、媽媽也是這麼認為的……說“另一個我”才是真正的我。所以，在我消失之前，領航，和我一起大鬧特鬧吧，好嗎！", "0", "cv_meika_8", "0", "switch1,switch1"},
[4201000112] = {4201000112, 12010001, 102, 5, "1_》_0_0.8", "switch2", "謝啦！", "あんがとな！", "0", "0", "謝啦！", "0", "cv_meika_9", "0", "switch2,switch2"},
[4201000113] = {4201000113, 12010001, 96, 5, "1_》_0_0.8", "switch3", "很好，我很中意！", "よし、気に入った！", "0", "0", "很好，我很中意！", "0", "cv_meika_10", "0", "switch3,switch3"},
[4201000114] = {4201000114, 12010001, 14, 6, "0", "0", "謝啦！", "あんがとな！", "0", "0", "謝啦！", "0", "cv_meika_9", "0", "0"},
[4201000115] = {4201000115, 12010001, 15, 7, "0", "0", "很好，我很中意！", "よし、気に入った！", "0", "0", "很好，我很中意！", "0", "cv_meika_10", "0", "0"},
[4201000116] = {4201000116, 12010001, 16, 8, "0", "0", "雖然不太明白，但我似乎變得很強了，這都是多虧了你啊，THANK YOU，領航！這份心意，這份熱情，我會用不滅的火焰來回應的！", "よく分かんねぇけどなんだか強くなったぜ！あんたのお陰だ。サンキューな、ナビゲーター！その熱い気持に、俺の不滅の炎で応えてやるぜ！", "0", "0", "雖然不太明白，但我似乎變得很強了，這都是多虧了你啊，THANK YOU，領航！這份心意，這份熱情，我會用不滅的火焰來回應的！", "0", "cv_meika_11", "0", "0"},
[4201000117] = {4201000117, 12010001, 17, 9, "0", "0", "不錯的感覺！", "いい感じだぁ！", "0", "0", "不錯的感覺！", "0", "cv_meika_12", "0", "0"},
[4201000118] = {4201000118, 12010001, 18, 10, "0", "0", "哈哈，來一場狂歡吧！", "ははっ、カーニバルだ！", "0", "0", "哈哈，來一場狂歡吧！", "0", "cv_meika_13", "0", "0"},
[4201000119] = {4201000119, 12010001, 19, 11, "0", "0", "領航、轟雷姐，看到了嗎，老孃果然是最強的！", "見たか、ナビゲーター、轟雷の姉貴！やっぱりこの俺が最強だぜ！", "0", "0", "領航、轟雷姐，看到了嗎，老娘果然是最強的！", "0", "cv_meika_14", "0", "0"},
[4201000120] = {4201000120, 12010001, 20, 12, "0", "0", "這個結果…勉強能接受吧。", "こんなもんか。……ま、いいだろ。", "0", "0", "這個結果…勉強能接受吧。", "0", "cv_meika_15", "0", "0"},
[4201000121] = {4201000121, 12010001, 21, 13, "0", "0", "喂！這樣也算勝利嗎！？", "おい！こんなんで勝ったって言えんのかよ！", "0", "0", "喂！這樣也算勝利嗎！？", "0", "cv_meika_16", "0", "0"},
[4201000122] = {4201000122, 12010001, 22, 14, "0", "0", "領航，請指揮撤離…別擔心，一定會沒事的……", "ナビゲーターさん、どうか撤退を……心配しないでください。きっと大丈夫です……", "0", "0", "領航，請指揮撤離…別擔心，一定會沒事的……", "0", "cv_meika_17", "0", "0"},
