[4201000128] = {4201000128, 12010001, 28, 20, "0", "0", "喂，就沒有準備些什麼泡澡時的零食嗎？", "おい、なんか風呂で食うもんはねぇのかよ？", "0", "0", "喂，就沒有準備些什麼泡澡時的零食嗎？", "0", "cv_meika_23", "0", "0"},
[4201000129] = {4201000129, 12010001, 29, 21, "0", "0", "差不多該起來了，牛奶給我準備好了嗎？咖啡牛奶！", "そろそろ出るか。牛乳は用意してんだろうな？コーヒー牛乳だぞ！", "0", "0", "差不多該起來了，牛奶給我準備好了嗎？咖啡牛奶！", "0", "cv_meika_24", "0", "0"},
[4201000130] = {4201000130, 12010001, 30, 22, "0", "0", "事件！要來了要來了！", "事件か？キタキター！", "0", "0", "事件！要來了要來了！", "0", "cv_meika_25", "0", "0"},
[4201000131] = {4201000131, 12010001, 31, 23, "0", "0", "你眼中的我…是哪一個呢？", "あなたの目に映るのは、どちらのあたしなのでしょうか……？", "0", "0", "你眼中的我…是哪一個呢？", "0", "cv_meika_26", "0", "0"},
[4201000132] = {4201000132, 12010001, 32, 24, "0", "0", "果然，我和你很合得來嘛！", "やっぱりてめーとは気が合うな！", "0", "0", "果然，我和你很合得來嘛！", "0", "cv_meika_27", "0", "0"},
