[4201000134] = {4201000134, 12010001, 34, 26, "0", "0", "喔，領航，今天我們要轟誰？", "おう、ナビゲーター。今日は誰をぶっとばす？", "0", "0", "噢，領航，今天我們要轟誰？", "0", "cv_meika_31", "0", "0"},
