[4201000140] = {4201000140, 12010001, 40, 32, "0", "0", "我全都想要！", "全部欲しいぜ！", "0", "0", "我全都想要！", "0", "cv_meika_38", "0", "0"},
[4201000141] = {4201000141, 12010001, 41, 33, "0", "0", "浪費時間！", "時間のムダだ！", "0", "0", "浪費時間！", "0", "cv_meika_39", "0", "0"},
[4201000142] = {4201000142, 12010001, 42, 34, "0", "0", "婆婆媽媽的！", "ごちゃごちゃうるせー！", "0", "0", "婆婆媽媽的！", "0", "cv_meika_40", "0", "0"},
[4201000143] = {4201000143, 12010001, 43, 35, "0", "0", "一把火燒了吧！", "燃やしちまおうぜ！", "0", "0", "一把火燒了吧！", "0", "cv_meika_41", "0", "0"},
[4201000144] = {4201000144, 12010001, 44, 36, "0", "0", "他們聽得見我的聲音嗎？", "あいつら、俺の聲が聞こえてんのか？", "0", "0", "他們聽得見我的聲音嗎？", "0", "cv_meika_42", "0", "0"},
[4201000145] = {4201000145, 12010001, 45, 37, "0", "0", "我點！", "ポチッとな！", "0", "0", "我點！", "0", "cv_meika_43", "0", "0"},
[4102200200] = {4102200200, 11022002, 1, 1, "0", "0", "誒？蒼霧……殘響？", "え？　はつ……りばーぶ？", "0", "0", "0", "0", "cv_wangnv_1", "0", "0"},
[4102200201] = {4102200201, 11022002, 2, 2, "0", "0", "好好笑哦，這個角度的領航像小蟲子一樣，真可愛。", "おっかし～。こっから見るとナビくん、蟲みたいで可愛いじゃん。", "0", "0", "0", "0", "cv_wangnv_2", "0", "0"},
[4102200202] = {4102200202, 11022002, 3, 3, "0", "0", "哦，好久不見打擾了，我是王女。嗯……？你問我為什麼能出現在這裡？不要在意這種小事嘛！", "おっひさー、王女だよー。え……？　なんでここにいるのかって？　細かいことはどうでもいいじゃん！", "0", "0", "0", "0", "cv_wangnv_3", "0", "0"},
[4102200203] = {4102200203, 11022002, 91, 4, "0", "idle", "嗯……我就像一個趕不走的租客一樣寄宿在領航的身邊，這話聽起來是不是有點色情？", "ふむふむ……追い出せない同居人みたいにナビくんから離れない……って聞くとちょっとエッチじゃない？", "0", "0", "0", "0", "cv_wangnv_4", "0", "idle,idle"},
[4102200204] = {4102200204, 11022002, 91, 4, "0", "idle", "可以看到很多熟悉的面孔呢……欸……剛剛走過來的那個人是不是小斯卡蒂！好可惜！我好想過去和她打招呼哦！", "ちらほらと見覚えのある顔が……あっ今通り過ぎたのってすかきちじゃん！　やばー！　挨拶しとけば良かったぁ！", "0", "0", "0", "0", "cv_wangnv_5", "0", "idle,idle"},
[4102200205] = {4102200205, 11022002, 91, 4, "0", "idle", "誒……你平時有這麼多文件要處理啊，好麻煩哦，真是難為你了。我看到這麼多檔就會犯困，因為一點都沒有意思嘛——！", "えぇ……普段からこんなに書類仕事があるのー？　大変だねー。同情しちゃうよ。あーしなら白目剝いちゃうね。だってマジ面白くなさそうだしー！", "0", "0", "0", "0", "cv_wangnv_6", "0", "idle,idle"},
[4102200206] = {4102200206, 11022002, 92, 5, "15_1_0_0.8", "touch1", "這裡就是艾吉斯啊……好！決定了！我的下一個目標就是成為艾吉斯的TOP1。", "ここがアイギスかぁ……よし決めた！　あーしの次の目標はアイギスのトップになること！", "0", "0", "0", "0", "cv_wangnv_7", "0", "touch1,touch1"},
[4102200207] = {4102200207, 11022002, 92, 5, "15_1_0_0.8", "touch1", "差不多也該帶我去和巨大怪獸一起作戰了吧……我已經按耐不住自己心中這股想保護大家的心情了……你說我只是想玩鬧？結果沒差別就好啦~", "そろそろあーしも巨大怪獣と戦うのに連れてってよー。みんなを守りたいっていう気持ちが抑えられなくてさぁ……暴れたいだけだろって？結果オーライならいいっしょ～", "0", "0", "0", "0", "cv_wangnv_8", "0", "touch1,touch1"},
[4102200208] = {4102200208, 11022002, 92, 5, "15_2_0_0.8", "touch2", "……在沒有人的地方，你可以偷偷叫我斯卡蒂哦？是不是有種背德的感覺……嘿嘿，感覺會上癮呢。", "……誰もいないとこでなら、あーしのことこっそりスカディって呼んでいいよ？　へへ……なんかイケないことしてるみたいでクセになるかもね。", "0", "0", "0", "0", "cv_wangnv_9", "0", "touch2,touch2"},
[4102200209] = {4102200209, 11022002, 92, 5, "15_2_0_0.8", "touch2", "領航……你更喜歡哪個斯卡蒂呢？是還在成長的她，還是充滿威嚴的她，還是我？", "ナビくんは……どのスカディの方が好き？　成長途中のか、威厳に満ちてるのか、それとも……あーしが好き？", "0", "0", "0", "0", "cv_wangnv_10", "0", "touch2,touch2"},
[4102200210] = {4102200210, 11022002, 92, 5, "15_2_0_0.8", "touch2", "我說……我覺得你還是喜歡我比較好。", "知ってるよ……ナビくんはあーしのことが好きなんだってこと！", "0", "0", "0", "0", "cv_wangnv_11", "0", "touch2,touch2"},
[4102200211] = {4102200211, 11022002, 12, 6, "0", "0", "這就是LVEVL—UP的感覺嗎。", "レベルアーップ、って感じだね。", "0", "0", "0", "0", "cv_wangnv_12", "0", "0"},
[4102200212] = {4102200212, 11022002, 13, 7, "0", "0", "感覺還不賴嘛。", "まあイケてんじゃない？", "0", "0", "0", "0", "cv_wangnv_13", "0", "0"},
[4102200213] = {4102200213, 11022002, 14, 8, "0", "0", "我懂了……因為有了你的幫助所以才能提升力量，從而讓我對你產生依賴和好感——所謂的特訓就是這樣的一種東西對吧？", "なるほど……ナビくんのおかげでレベルアップできる代わりに、あーしはナビくんのことが好きになっちゃう……特訓ってそういうアレなんだね？", "0", "0", "0", "0", "cv_wangnv_14", "0", "0"},
[4102200214] = {4102200214, 11022002, 15, 9, "0", "0", "這就是慢慢變強的踏實感覺呢。", "コツコツ強くなってるって感じだね！", "0", "0", "0", "0", "cv_wangnv_15", "0", "0"},
[4102200215] = {4102200215, 11022002, 16, 10, "0", "0", "心之鼓動，開始了。", "心臓ドキドキ、やばー♪", "0", "0", "0", "0", "cv_wangnv_16", "0", "0"},
[4102200216] = {4102200216, 11022002, 17, 11, "0", "0", "小意思！就這點水準嗎！", "楽勝楽勝！　こんなん餘裕っしょ！", "0", "0", "0", "0", "cv_wangnv_17", "0", "0"},
[4102200217] = {4102200217, 11022002, 18, 12, "0", "0", "哼，戰鬥的勝負就在一瞬間呢。", "ふっふーん。勝負が決まるのは一瞬なんだよ。", "0", "0", "0", "0", "cv_wangnv_18", "0", "0"},
[4102200218] = {4102200218, 11022002, 19, 13, "0", "0", "我還活著啊！好危險！好危險！", "死ぬかと思った！あっぶな！マジ危なかった！", "0", "0", "0", "0", "cv_wangnv_19", "0", "0"},
[4102200219] = {4102200219, 11022002, 20, 14, "0", "0", "快——跑——啊，敵人要追上來了，好可怕！", "にーげーろー！　追いかけて來てるよ、ヤバいヤバい！", "0", "0", "0", "0", "cv_wangnv_20", "0", "0"},
[4102200220] = {4102200220, 11022002, 21, 15, "0", "0", "啊哈~", "へっへーん！", "0", "0", "0", "0", "cv_wangnv_21", "0", "0"},
[4102200221] = {4102200221, 11022002, 23, 16, "0", "0", "必殺！", "必殺！", "0", "0", "0", "0", "cv_wangnv_23", "0", "0"},
[4102200222] = {4102200222, 11022002, 24, 17, "0", "0", "超必殺！", "超必殺！", "0", "0", "0", "0", "cv_wangnv_24", "0", "0"},
[4102200223] = {4102200223, 11022002, 26, 19, "0", "0", "我可還沒結束！", "あーしはまだ終わってないよ！", "0", "0", "0", "0", "cv_wangnv_26", "0", "0"},
[4102200224] = {4102200224, 11022002, 27, 20, "0", "0", "這……這是……！澡堂！", "こ……これは……！お風呂！", "0", "0", "0", "0", "cv_wangnv_27", "0", "0"},
[4102200225] = {4102200225, 11022002, 28, 21, "0", "0", "沒想到我的預感成為了現實，你真的跟進來要和我一起洗澡啊……", "まさかあーしの予感が的中するなんて。ほんとにあーしと一緒にお風呂入るんだ……", "0", "0", "0", "0", "cv_wangnv_28", "0", "0"},
[4102200226] = {4102200226, 11022002, 29, 21, "0", "0", "你這傢伙……算了，就當是給你的福利環節了……畢竟一直借住在你的身邊。", "ナビくんってば……ま、お禮だと思えばいっか……いつもお世話になってるしねー。", "0", "0", "0", "0", "cv_wangnv_29", "0", "0"},
[4102200227] = {4102200227, 11022002, 30, 22, "0", "0", "然後呢？", "それから？", "0", "0", "0", "0", "cv_wangnv_30", "0", "0"},
[4102200228] = {4102200228, 11022002, 31, 23, "0", "0", "猜猜我是誰~猜錯了可是有懲罰的哦！", "あーしは誰かな～？　間違ったら罰ゲームだからね！", "0", "0", "0", "0", "cv_wangnv_31", "0", "0"},
[4102200229] = {4102200229, 11022002, 32, 24, "0", "0", "好！答對了，獎勵你和我的二人世界時間，陪我再一次前往戰場吧！", "はい、良くできましたー！　ご褒美に二人きりの時間をあげるね……さ、二人で戦場に行くよー！", "0", "0", "0", "0", "cv_wangnv_32", "0", "0"},
[4102200230] = {4102200230, 11022002, 33, 25, "0", "0", "好！懲罰就是等一下陪我一起再一次上戰場，接下來我和領航的二人世界時間。", "オッケー、罰としてもう一回戦場に付き合って貰うよー。ここからはあーしとナビくん、二人の時間だからね。", "0", "0", "0", "0", "cv_wangnv_33", "0", "0"},
[4102200231] = {4102200231, 11022002, 34, 26, "0", "0", "你終於來了，我等得好無聊啊~等會一起去找點樂子吧？", "やっと來たー。退屈だったんだよー？　んじゃ早速、どっか遊びに行かない？", "0", "0", "0", "0", "cv_wangnv_34", "0", "0"},
[4102200232] = {4102200232, 11022002, 35, 27, "0", "0", "我們兩個人偷偷加班吧？", "あーし達ふたりでこっそり殘業しない？", "0", "0", "0", "0", "cv_wangnv_35", "0", "0"},
[4102200233] = {4102200233, 11022002, 36, 28, "0", "0", "不錯不錯！", "いいねいいねぇ！", "0", "0", "0", "0", "cv_wangnv_36", "0", "0"},
[4102200234] = {4102200234, 11022002, 37, 29, "0", "0", "打算帶我去見見其他人？好啊，現在就走嗎？", "あーしを連れて他の人に會いに行くの？いいよ、今から行く？", "0", "0", "0", "0", "cv_wangnv_37", "0", "0"},
[4102200235] = {4102200235, 11022002, 38, 30, "0", "0", "原來你的權力這麼大，竟然能隨便調度其他駕駛員過來耶。", "ナビくんって結構偉いんだねー。他のドライバーを自由に募集できるなんて。", "0", "0", "0", "0", "cv_wangnv_38", "0", "0"},
[4102200236] = {4102200236, 11022002, 39, 31, "0", "0", "噗，好奇怪的裝備。", "ぷっ、変な裝備。", "0", "0", "0", "0", "cv_wangnv_39", "0", "0"},
[4102200237] = {4102200237, 11022002, 40, 32, "0", "0", "我請客好了。", "あーしが奢ったげるよ。", "0", "0", "0", "0", "cv_wangnv_40", "0", "0"},
[4102200238] = {4102200238, 11022002, 41, 33, "0", "0", "這我認得，這照片是你對吧？", "あ、見覚えあるー。この寫真ってナビくんでしょ？", "0", "0", "0", "0", "cv_wangnv_41", "0", "0"},
[4102200239] = {4102200239, 11022002, 42, 34, "0", "0", "改變世界的機關就在這裡。", "世界を変える仕組みはここにあるよ。", "0", "0", "0", "0", "cv_wangnv_42", "0", "0"},
[4102200240] = {4102200240, 11022002, 43, 35, "0", "0", "我知道！這個是領獎勵的地方對吧？誒……錯了嗎？", "分かった！ここってボーナスが入ってる場所でしょ？え……違った？", "0", "0", "0", "0", "cv_wangnv_43", "0", "0"},
[4102200241] = {4102200241, 11022002, 44, 36, "0", "0", "聊天欄啊……可要小心那些居心不軌的人哦。", "チャットかぁ……荒らしには気を付けてよね。", "0", "0", "0", "0", "cv_wangnv_44", "0", "0"},
[4102200242] = {4102200242, 11022002, 45, 37, "0", "0", "盯——", "じぃ～", "0", "0", "0", "0", "cv_wangnv_45", "0", "0"},
[423600] = {423600, 12036, 1, 1, "0", "0", "蒼霧殘響。", "ハツリバーブ", "0", "0", "0", "0", "cv_lilith_her_01", "0", "0"},
[423601] = {423601, 12036, 2, 2, "0", "0", "就舉辦婚禮的場所來說……這裏太爛了。", "結婚式の会場としては……ここ、あまりにもお粗末ね。", "0", "0", "0", "0", "cv_lilith_her_02", "0", "0"},
[423602] = {423602, 12036, 3, 3, "0", "0", "愣着幹什麼……又不是沒有看過我穿婚紗的樣子。", "何ぼーっとしてるの。私のウェディングドレス姿、もう見たことあるでしょう？", "0", "0", "0", "0", "cv_lilith_her_03", "0", "0"},
[423603] = {423603, 12036, 4, 4, "0", "idle", "能在我耳邊說一句“我願意”嗎？……沒聽到就算了。", "私の耳元で「誓います」って言ってくれる？……聞こえなかったらもういいわ。", "0", "0", "0", "0", "cv_lilith_her_04", "0", "idle,idle"},
[423604] = {423604, 12036, 5, 4, "0", "idle2", "在真的婚禮上，新娘也需要站這麼久嗎？", "本物の結婚式でも、新婦ってこんなに長く立ってるものなの？", "0", "0", "0", "0", "cv_lilith_her_05", "0", "idle2,idle2"},
[423605] = {423605, 12036, 6, 4, "0", "idle3", "我至今想不通，你是怎麼找到那家照相館的？我也不是沒有去找過，可只得到了倒閉的消息……不得不說，有些事的確只有你才能做到。", "今でも不思議だわ。あなた、どうやってあの写真館を見つけたの？私も探したことはあるけど……「もう潰れた」って話しかなくて…… やっぱりそういうことは、あなたにしかできないのかもしれないわね。", "0", "0", "0", "0", "cv_lilith_her_06", "0", "idle3,idle3"},
[423606] = {423606, 12036, 7, 5, "1_》_0_0.8", "level1", "很少有人可以做到真正的心意相通，但這對我們來說並不是難事。", "本当に心が通じ合える人なんて、そう多くない。でも……私たちにとっては、そんなに難しいことじゃないでしょう？", "0", "0", "0", "0", "cv_lilith_her_07", "0", "level1,level1"},
[423607] = {423607, 12036, 8, 5, "1_》_0_0.8", "level2", "你還有更要緊的事情要做吧？比起陪我站在這裏無所事事，先去處理那些事比較好……算了，按照你自己的節奏來吧。", "他にやるべきことがあるんじゃない？ここで時間を無駄にするくらいなら、先にそっちを片付けてきたら。……まあいい。あなたに任せるわ。", "0", "0", "0", "0", "cv_lilith_her_08", "0", "level2,level2"},
[423608] = {423608, 12036, 9, 5, "1_》_100_1.5", "level3", "對我來說，這件婚紗只不是一件過分華麗的衣服而已……想要天天看我穿？呵呵，你當我不敢嗎？", "私にとって、このドレスは少し派手な服ってだけよ。……毎日でも着てほしいって？ふふ。私にできないと思ったの？", "0", "0", "0", "0", "cv_lilith_her_09", "0", "level3,level3"},
[423609] = {423609, 12036, 10, 5, "1_》_500_2", "level4", "雖然我們都是“通感者”，但是我怎麼感覺總是在單方面被你窺視我的心靈。那個夢，別以爲我什麼都不知道。現在，我也要看看你心裏藏着什麼祕密。", "私たちはどちらも「通感覚者」。でも、なぜか……いつもあなたのほうが、私の心を覗いている気がするの。あの夢のことも。知らないと思ってる？今度は私が、あなたの心の中を覗いてみようか。", "0", "0", "0", "0", "cv_lilith_her_10", "0", "level4,level4"},
[423610] = {423610, 12036, 11, 5, "1_》_1000_2.5", "level5", "在看過照片後，我對於父母的記憶也逐漸清晰起來了。我想起了小時候經常被父母帶去的餐廳，那似乎是他們第一次相識的地方。領航，有時間的話能陪我也去一趟嗎？", "あの写真を見てから……両親のこと、少しずつ思い出せるようになったわ。小さい頃、よく連れていってもらったレストランも。そこが、2人が初めて出会った場所みたい。ナビゲーター。時間があるなら……私と一緒に行ってくれる？", "0", "0", "0", "0", "cv_lilith_her_11", "0", "level5,level5"},
[423611] = {423611, 12036, 12, 6, "0", "0", "無論何時都要提升自己。", "いつでも、自分を高めていかないと。", "0", "0", "0", "0", "cv_lilith_her_12", "0", "0"},
[423612] = {423612, 12036, 13, 7, "0", "0", "你一直在注視着我，我也一直在注視着你……", "あなたが私を見ているように……私も、ずっとあなたを見ているの。", "0", "0", "0", "0", "cv_lilith_her_13", "0", "0"},
[423613] = {423613, 12036, 14, 8, "0", "0", "你我之間，早已不需要“戒指”的契約。", "私たちの間に、もう「指輪」の契約なんていらない。", "0", "0", "0", "0", "cv_lilith_her_14", "0", "0"},
[423614] = {423614, 12036, 15, 9, "0", "0", "似曾相識的感受。", "どこか懐かしい感じね。", "0", "0", "0", "0", "cv_lilith_her_15", "0", "0"},
[423615] = {423615, 12036, 16, 10, "0", "0", "遊戲開場了。", "ゲーム開始よ。", "0", "0", "0", "0", "cv_lilith_her_16", "0", "0"},
[423616] = {423616, 12036, 17, 11, "0", "0", "結束了？就這樣？", "終わり？これだけ？", "0", "0", "0", "0", "cv_lilith_her_17", "0", "0"},
[423617] = {423617, 12036, 18, 12, "0", "0", "裙襬被撕開了……", "ドレスの裾が……", "0", "0", "0", "0", "cv_lilith_her_18", "0", "0"},
